INSERT INTO public.questions VALUES (1, 1, 'g9-num-real-q1-01', 1, 1, 'hard', 'single', 'a = 6√2, b = 3√7, c = 5√3. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < c < a", "B": "b < a < c", "C": "c < b < a", "D": "a < b < c", "E": "c < a < b"}'::jsonb, 'B', NULL, 'Kvadratlarını müqayisə edin: a² = 36·2 = 72, b² = 9·7 = 63, c² = 25·3 = 75. Ardıcıllıq: b < a < c.');
INSERT INTO public.questions VALUES (2, 1, 'g9-num-real-q1-02', 1, 2, 'hard', 'single', 'Sadələşdirin: (√19 + √3) / (√19 − √3)', NULL, NULL, '{"A": "11/8 − √57/8", "B": "1 + √57/8", "C": "11/8 + √57/8", "D": "8/11 + √57/11", "E": "11/8 + √57/16"}'::jsonb, 'C', NULL, 'Surəti və məxrəci (√19 + √3)-yə vurun: (19 + 3 + 2√57) / (19 − 3) = 11/8 + √57/8.');
INSERT INTO public.questions VALUES (3, 1, 'g9-num-real-q1-03', 1, 3, 'hard', 'single', 'Cəmi adi kəsr şəklində yazın: 0,(19) + 0,1(48)', NULL, NULL, '{"A": "178/495", "B": "138/407", "C": "337/990", "D": "169/495", "E": "101/297"}'::jsonb, 'C', NULL, '0,(19) = 19/99; 0,1(48) = (148 − 1)/990 = 49/330. Cəm: 337/990.');
INSERT INTO public.questions VALUES (4, 1, 'g9-num-real-q1-04', 1, 4, 'hard', 'single', '−√152 ≤ x < ∛568 bərabərsizliyini ödəyən neçə tam x ədədi var?', NULL, NULL, '{"A": "23", "B": "22", "C": "19", "D": "20", "E": "21"}'::jsonb, 'E', NULL, '√152 ≈ 12,33, deməli x ≥ −12. 8³ = 512 < 568, 9³ = 729 ≥ 568, deməli x ≤ 8. Tam ədədlər: −12, …, 8 — cəmi 21.');
INSERT INTO public.questions VALUES (5, 1, 'g9-num-real-q1-05', 1, 5, 'hard', 'single', 'Hesablayın: √(9 + 2√18) − √(9 − 2√18)', NULL, NULL, '{"A": "2√3", "B": "2√6", "C": "6", "D": "√6", "E": "√6 − √3"}'::jsonb, 'A', NULL, '9 ± 2√18 = (√6 ± √3)², çünki 6 + 3 = 9 və 6·3 = 18. Fərq: (√6 + √3) − (√6 − √3) = 2√3.');
INSERT INTO public.questions VALUES (6, 1, 'g9-num-real-q1-06', 1, 6, 'hard', 'single', '−√112 ≤ x < ∛226 bərabərsizliyini ödəyən neçə tam x ədədi var?', NULL, NULL, '{"A": "18", "B": "17", "C": "16", "D": "19", "E": "15"}'::jsonb, 'B', NULL, '√112 ≈ 10,58, deməli x ≥ −10. 6³ = 216 < 226, 7³ = 343 ≥ 226, deməli x ≤ 6. Tam ədədlər: −10, …, 6 — cəmi 17.');
INSERT INTO public.questions VALUES (7, 1, 'g9-num-real-q1-07', 1, 7, 'hard', 'single', 'Sadələşdirin: (√17 + √6) / (√17 − √6)', NULL, NULL, '{"A": "23/11 + √102/11", "B": "1 + 2√102/11", "C": "23/11 − 2√102/11", "D": "23/11 + 2√102/11", "E": "11/23 + 2√102/23"}'::jsonb, 'D', NULL, 'Surəti və məxrəci (√17 + √6)-yə vurun: (17 + 6 + 2√102) / (17 − 6) = 23/11 + 2√102/11.');
INSERT INTO public.questions VALUES (8, 1, 'g9-num-real-q1-08', 1, 8, 'hard', 'single', 'Hesablayın: √(10 + 2√21) − √(10 − 2√21)', NULL, NULL, '{"A": "2√7", "B": "√6", "C": "√7 − √3", "D": "2√3", "E": "2√10"}'::jsonb, 'D', NULL, '10 ± 2√21 = (√7 ± √3)², çünki 7 + 3 = 10 və 7·3 = 21. Fərq: (√7 + √3) − (√7 − √3) = 2√3.');
INSERT INTO public.questions VALUES (9, 1, 'g9-num-real-q1-09', 1, 9, 'hard', 'single', 'Hesablayın: √(26 + 2√165) − √(26 − 2√165)', NULL, NULL, '{"A": "2√11", "B": "√15 − √11", "C": "2√15", "D": "√22", "E": "2√26"}'::jsonb, 'A', NULL, '26 ± 2√165 = (√15 ± √11)², çünki 15 + 11 = 26 və 15·11 = 165. Fərq: (√15 + √11) − (√15 − √11) = 2√11.');
INSERT INTO public.questions VALUES (10, 1, 'g9-num-real-q1-10', 1, 10, 'hard', 'single', '−√131 ≤ x < ∛569 bərabərsizliyini ödəyən neçə tam x ədədi var?', NULL, NULL, '{"A": "21", "B": "18", "C": "22", "D": "20", "E": "19"}'::jsonb, 'D', NULL, '√131 ≈ 11,45, deməli x ≥ −11. 8³ = 512 < 569, 9³ = 729 ≥ 569, deməli x ≤ 8. Tam ədədlər: −11, …, 8 — cəmi 20.');
INSERT INTO public.questions VALUES (11, 1, 'g9-num-real-q1-11', 1, 11, 'hard', 'single', 'Sadələşdirin: (√26 + √23) / (√26 − √23)', NULL, NULL, '{"A": "49/3 + 2√598/3", "B": "1 + 2√598/3", "C": "3/49 + 2√598/49", "D": "49/3 + √598/3", "E": "49/3 − 2√598/3"}'::jsonb, 'A', NULL, 'Surəti və məxrəci (√26 + √23)-yə vurun: (26 + 23 + 2√598) / (26 − 23) = 49/3 + 2√598/3.');
INSERT INTO public.questions VALUES (12, 1, 'g9-num-real-q1-12', 1, 12, 'hard', 'single', 'Cəmi adi kəsr şəklində yazın: 0,(46) + 0,4(89)', NULL, NULL, '{"A": "10441/10989", "B": "991/990", "C": "1165/1221", "D": "949/990", "E": "21/22"}'::jsonb, 'E', NULL, '0,(46) = 46/99; 0,4(89) = (489 − 4)/990 = 97/198. Cəm: 21/22.');
INSERT INTO public.questions VALUES (13, 1, 'g9-num-real-q1-13', 1, 13, 'hard', 'single', 'a = 7√5, b = 4√2, c = 2√7. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < c < a", "B": "b < a < c", "C": "c < b < a", "D": "a < b < c", "E": "a < c < b"}'::jsonb, 'C', NULL, 'Kvadratlarını müqayisə edin: a² = 49·5 = 245, b² = 16·2 = 32, c² = 4·7 = 28. Ardıcıllıq: c < b < a.');
INSERT INTO public.questions VALUES (14, 1, 'g9-num-real-q1-14', 1, 14, 'hard', 'open', 'Cəmi adi kəsr şəklində yazın: 0,(58) + 0,4(25)', NULL, NULL, NULL, NULL, '91/90', '0,(58) = 58/99; 0,4(25) = (425 − 4)/990 = 421/990. Cəm: 91/90.');
INSERT INTO public.questions VALUES (15, 1, 'g9-num-real-q1-15', 1, 15, 'hard', 'single', 'a = 4√3, b = 3√6, c = 5√5. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < a < b", "B": "a < c < b", "C": "b < c < a", "D": "a < b < c", "E": "b < a < c"}'::jsonb, 'D', NULL, 'Kvadratlarını müqayisə edin: a² = 16·3 = 48, b² = 9·6 = 54, c² = 25·5 = 125. Ardıcıllıq: a < b < c.');
INSERT INTO public.questions VALUES (16, 1, 'g9-num-real-q1-16', 1, 16, 'hard', 'single', 'Cəmi adi kəsr şəklində yazın: 0,(14) + 0,3(75)', NULL, NULL, '{"A": "103/198", "B": "1882/3663", "C": "631/1221", "D": "256/495", "E": "263/495"}'::jsonb, 'D', NULL, '0,(14) = 14/99; 0,3(75) = (375 − 3)/990 = 62/165. Cəm: 256/495.');
