INSERT INTO public.questions VALUES (184, 4, 'g9-num-abs-q1-04', 1, 4, 'hard', 'single', 'Hesablayın: √((5 − √60)²) + √((1 − √60)²)', NULL, NULL, '{"A": "4√15", "B": "−6 + 4√15", "C": "6 − 4√15", "D": "6", "E": "4"}'::jsonb, 'B', NULL, '√(t²) = |t|. √60 ≈ 7,75. 5 < √60 və 1 < √60: (√60 − 5) + (√60 − 1) = −6 + 4√15.');
