INSERT INTO public.questions VALUES (298, 5, 'g9-num-pct-q3-18', 3, 18, 'hard', 'single', '9 kq 20%-li və 2 kq 35%-li duz məhlulu qarışdırıldı, sonra qarışığa 5 kq su əlavə edildi. Alınan məhlulda duzun faizi nə qədərdir?', NULL, NULL, '{"A": "15,625%", "B": "27,5%", "C": "16,625%", "D": "22,7%", "E": "14,7%"}'::jsonb, 'A', NULL, 'Duz: 9·0,2 + 2·0,35 = 2,5 kq. Kütlə: 9 + 2 + 5 = 16 kq. Faiz: 15,625%.');
INSERT INTO public.questions VALUES (299, 5, 'g9-num-pct-q3-19', 3, 19, 'hard', 'single', '7 kq 25%-li və 8 kq 35%-li duz məhlulu qarışdırıldı, sonra qarışığa 5 kq su əlavə edildi. Alınan məhlulda duzun faizi nə qədərdir?', NULL, NULL, '{"A": "22,75%", "B": "30,3%", "C": "21,7%", "D": "23,75%", "E": "30%"}'::jsonb, 'A', NULL, 'Duz: 7·0,25 + 8·0,35 = 4,55 kq. Kütlə: 7 + 8 + 5 = 20 kq. Faiz: 22,75%.');
INSERT INTO public.questions VALUES (300, 5, 'g9-num-pct-q3-20', 3, 20, 'hard', 'single', '8 kq 15%-li və 10 kq 60%-li duz məhlulu qarışdırıldı, sonra qarışığa 7 kq su əlavə edildi. Alınan məhlulda duzun faizi nə qədərdir?', NULL, NULL, '{"A": "37,5%", "B": "27,7%", "C": "29,8%", "D": "28,8%", "E": "40%"}'::jsonb, 'D', NULL, 'Duz: 8·0,15 + 10·0,6 = 7,2 kq. Kütlə: 8 + 10 + 7 = 25 kq. Faiz: 28,8%.');
INSERT INTO public.questions VALUES (301, 6, 'g9-alg-eq-q1-01', 1, 1, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x + 6)/(x − 3) − 5/(x + 3) = 54/(x² − 9)', NULL, NULL, '{"A": "−4", "B": "−7", "C": "3", "D": "−6", "E": "7"}'::jsonb, 'B', NULL, 'Ortaq məxrəc x² − 9: (x + 6)(x + 3) − 5(x − 3) = 54 ⇒ x² + 4x − 21 = 0, köklər 3 və −7. x = 3 məxrəci sıfra çevirir (yad kök). Cavab: −7.');
INSERT INTO public.questions VALUES (302, 6, 'g9-alg-eq-q1-02', 1, 2, 'hard', 'single', 'İki usta birlikdə işi 35/6 saata bitirir. Birinci usta təklikdə ikincidən 4 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "35/3", "B": "14", "C": "10", "D": "18", "E": "15"}'::jsonb, 'B', NULL, 'Birinci x saat, ikinci x + 4 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 4) = 6/35 ⇒ x = 10. İkinci usta: 14 saat.');
INSERT INTO public.questions VALUES (303, 6, 'g9-alg-eq-q1-03', 1, 3, 'hard', 'single', 'İki usta birlikdə işi 63/4 saata bitirir. Birinci usta təklikdə ikincidən 8 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "44", "B": "36", "C": "28", "D": "37", "E": "63/2"}'::jsonb, 'B', NULL, 'Birinci x saat, ikinci x + 8 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 8) = 4/63 ⇒ x = 28. İkinci usta: 36 saat.');
INSERT INTO public.questions VALUES (304, 6, 'g9-alg-eq-q1-04', 1, 4, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 7)/(x − 3) − 5/(x + 3) = −24/(x² − 9)', NULL, NULL, '{"A": "6", "B": "3", "C": "−6", "D": "9", "E": "7"}'::jsonb, 'A', NULL, 'Ortaq məxrəc x² − 9: (x − 7)(x + 3) − 5(x − 3) = −24 ⇒ x² − 9x + 18 = 0, köklər 3 və 6. x = 3 məxrəci sıfra çevirir (yad kök). Cavab: 6.');
INSERT INTO public.questions VALUES (305, 6, 'g9-alg-eq-q1-05', 1, 5, 'hard', 'single', 'x⁴ − 2x² − 35 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "7", "B": "8", "C": "35", "D": "−35", "E": "−7"}'::jsonb, 'E', NULL, 't = x² ≥ 0: t² − 2t − 35 = 0, t = 7 və t = −5. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: −7.');
INSERT INTO public.questions VALUES (306, 6, 'g9-alg-eq-q1-06', 1, 6, 'hard', 'single', '√(x − 5) = x − 7 tənliyinin kökünü tapın.', NULL, NULL, '{"A": "8", "B": "6", "C": "15", "D": "9", "E": "10"}'::jsonb, 'D', NULL, 'Kvadrata yüksəldin: x − 5 = (x − 7)² ⇒ x² − 15x + 54 = 0, x = 9 və x = 6. Sağ tərəf mənfi olmamalıdır: x ≥ 7. x = 6 yad kökdür. Cavab: 9.');
INSERT INTO public.questions VALUES (307, 6, 'g9-alg-eq-q1-07', 1, 7, 'hard', 'open', '√(x + 3) = x + 1 tənliyinin kökünü tapın.', NULL, NULL, NULL, NULL, '1', 'Kvadrata yüksəldin: x + 3 = (x + 1)² ⇒ x² + x − 2 = 0, x = 1 və x = −2. Sağ tərəf mənfi olmamalıdır: x ≥ −1. x = −2 yad kökdür. Cavab: 1.');
INSERT INTO public.questions VALUES (308, 6, 'g9-alg-eq-q1-08', 1, 8, 'hard', 'single', 'İki usta birlikdə işi 12 saata bitirir. Birinci usta təklikdə ikincidən 10 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "31", "B": "20", "C": "30", "D": "40", "E": "24"}'::jsonb, 'C', NULL, 'Birinci x saat, ikinci x + 10 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 10) = 1/12 ⇒ x = 20. İkinci usta: 30 saat.');
INSERT INTO public.questions VALUES (309, 6, 'g9-alg-eq-q1-09', 1, 9, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x + 1)/(x − 2) − 1/(x + 2) = 12/(x² − 4)', NULL, NULL, '{"A": "2", "B": "−4", "C": "−3", "D": "4", "E": "−2"}'::jsonb, 'B', NULL, 'Ortaq məxrəc x² − 4: (x + 1)(x + 2) − 1(x − 2) = 12 ⇒ x² + 2x − 8 = 0, köklər 2 və −4. x = 2 məxrəci sıfra çevirir (yad kök). Cavab: −4.');
INSERT INTO public.questions VALUES (310, 6, 'g9-alg-eq-q1-10', 1, 10, 'hard', 'single', 'x⁴ − 7x² − 30 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "0", "B": "3", "C": "2", "D": "4", "E": "1"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 7t − 30 = 0, t = −3 və t = 10. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (311, 6, 'g9-alg-eq-q1-11', 1, 11, 'hard', 'single', 'x⁴ − 27x² + 180 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "181", "B": "−180", "C": "27", "D": "179", "E": "180"}'::jsonb, 'E', NULL, 't = x² ≥ 0: t² − 27t + 180 = 0, t = 15 və t = 12. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 180.');
INSERT INTO public.questions VALUES (312, 6, 'g9-alg-eq-q1-12', 1, 12, 'hard', 'single', 'İki usta birlikdə işi 28/3 saata bitirir. Birinci usta təklikdə ikincidən 14 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "56/3", "B": "28", "C": "14", "D": "29", "E": "42"}'::jsonb, 'B', NULL, 'Birinci x saat, ikinci x + 14 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 14) = 3/28 ⇒ x = 14. İkinci usta: 28 saat.');
INSERT INTO public.questions VALUES (313, 6, 'g9-alg-eq-q1-13', 1, 13, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 8)/(x − 4) − 1/(x + 4) = −32/(x² − 16)', NULL, NULL, '{"A": "−1", "B": "2", "C": "5", "D": "4", "E": "1"}'::jsonb, 'E', NULL, 'Ortaq məxrəc x² − 16: (x − 8)(x + 4) − 1(x − 4) = −32 ⇒ x² − 5x + 4 = 0, köklər 4 və 1. x = 4 məxrəci sıfra çevirir (yad kök). Cavab: 1.');
INSERT INTO public.questions VALUES (314, 6, 'g9-alg-eq-q1-14', 1, 14, 'hard', 'open', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 8)/(x − 5) − 1/(x + 5) = −30/(x² − 25)', NULL, NULL, NULL, NULL, '−1', 'Ortaq məxrəc x² − 25: (x − 8)(x + 5) − 1(x − 5) = −30 ⇒ x² − 4x − 5 = 0, köklər 5 və −1. x = 5 məxrəci sıfra çevirir (yad kök). Cavab: −1.');
INSERT INTO public.questions VALUES (315, 6, 'g9-alg-eq-q1-15', 1, 15, 'hard', 'single', 'x⁴ − 8x² + 12 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "−12", "B": "8", "C": "12", "D": "11", "E": "13"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 8t + 12 = 0, t = 2 və t = 6. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 12.');
INSERT INTO public.questions VALUES (316, 6, 'g9-alg-eq-q1-16', 1, 16, 'hard', 'single', '√(x + 29) = x − 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "6", "B": "7", "C": "3", "D": "−4", "E": "8"}'::jsonb, 'B', NULL, 'Kvadrata yüksəldin: x + 29 = (x − 1)² ⇒ x² − 3x − 28 = 0, x = 7 və x = −4. Sağ tərəf mənfi olmamalıdır: x ≥ 1. x = −4 yad kökdür. Cavab: 7.');
INSERT INTO public.questions VALUES (317, 6, 'g9-alg-eq-q1-17', 1, 17, 'hard', 'single', '√(x + 46) = x + 4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−7", "B": "2", "C": "−10", "D": "4", "E": "3"}'::jsonb, 'E', NULL, 'Kvadrata yüksəldin: x + 46 = (x + 4)² ⇒ x² + 7x − 30 = 0, x = 3 və x = −10. Sağ tərəf mənfi olmamalıdır: x ≥ −4. x = −10 yad kökdür. Cavab: 3.');
INSERT INTO public.questions VALUES (318, 6, 'g9-alg-eq-q1-18', 1, 18, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 9)/(x − 7) − 4/(x + 7) = −28/(x² − 49)', NULL, NULL, '{"A": "7", "B": "0", "C": "1", "D": "6", "E": "−1"}'::jsonb, 'E', NULL, 'Ortaq məxrəc x² − 49: (x − 9)(x + 7) − 4(x − 7) = −28 ⇒ x² − 6x − 7 = 0, köklər 7 və −1. x = 7 məxrəci sıfra çevirir (yad kök). Cavab: −1.');
INSERT INTO public.questions VALUES (319, 6, 'g9-alg-eq-q1-19', 1, 19, 'hard', 'single', 'x⁴ − 5x² − 14 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "3", "B": "4", "C": "0", "D": "2", "E": "1"}'::jsonb, 'D', NULL, 't = x² ≥ 0: t² − 5t − 14 = 0, t = −2 və t = 7. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (320, 6, 'g9-alg-eq-q1-20', 1, 20, 'hard', 'single', 'İki usta birlikdə işi 15/4 saata bitirir. Birinci usta təklikdə ikincidən 10 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "16", "B": "25", "C": "5", "D": "15/2", "E": "15"}'::jsonb, 'E', NULL, 'Birinci x saat, ikinci x + 10 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 10) = 4/15 ⇒ x = 5. İkinci usta: 15 saat.');
INSERT INTO public.questions VALUES (321, 6, 'g9-alg-eq-q2-01', 2, 1, 'hard', 'single', '√(x + 76) = x + 4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−12", "B": "−7", "C": "5", "D": "6", "E": "4"}'::jsonb, 'C', NULL, 'Kvadrata yüksəldin: x + 76 = (x + 4)² ⇒ x² + 7x − 60 = 0, x = 5 və x = −12. Sağ tərəf mənfi olmamalıdır: x ≥ −4. x = −12 yad kökdür. Cavab: 5.');
