INSERT INTO public.questions VALUES (353, 6, 'g9-alg-eq-q3-13', 3, 13, 'hard', 'single', '√(x + 10) = x + 4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−6", "B": "0", "C": "−2", "D": "−1", "E": "−7"}'::jsonb, 'D', NULL, 'Kvadrata yüksəldin: x + 10 = (x + 4)² ⇒ x² + 7x + 6 = 0, x = -1 və x = −6. Sağ tərəf mənfi olmamalıdır: x ≥ −4. x = −6 yad kökdür. Cavab: -1.');
INSERT INTO public.questions VALUES (354, 6, 'g9-alg-eq-q3-14', 3, 14, 'hard', 'open', 'İki usta birlikdə işi 21/4 saata bitirir. Birinci usta təklikdə ikincidən 14 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, NULL, NULL, '21', 'Birinci x saat, ikinci x + 14 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 14) = 4/21 ⇒ x = 7. İkinci usta: 21 saat.');
INSERT INTO public.questions VALUES (355, 6, 'g9-alg-eq-q3-15', 3, 15, 'hard', 'single', 'İki usta birlikdə işi 45/4 saata bitirir. Birinci usta təklikdə ikincidən 12 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "30", "B": "45/2", "C": "42", "D": "31", "E": "18"}'::jsonb, 'A', NULL, 'Birinci x saat, ikinci x + 12 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 12) = 4/45 ⇒ x = 18. İkinci usta: 30 saat.');
INSERT INTO public.questions VALUES (356, 6, 'g9-alg-eq-q3-16', 3, 16, 'hard', 'single', '√(x + 24) = x − 6 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "11", "B": "12", "C": "1", "D": "13", "E": "−12"}'::jsonb, 'B', NULL, 'Kvadrata yüksəldin: x + 24 = (x − 6)² ⇒ x² − 13x + 12 = 0, x = 12 və x = 1. Sağ tərəf mənfi olmamalıdır: x ≥ 6. x = 1 yad kökdür. Cavab: 12.');
INSERT INTO public.questions VALUES (357, 6, 'g9-alg-eq-q3-17', 3, 17, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x + 2)/(x − 4) − 5/(x + 4) = 48/(x² − 16)', NULL, NULL, '{"A": "−1", "B": "−5", "C": "5", "D": "−4", "E": "4"}'::jsonb, 'B', NULL, 'Ortaq məxrəc x² − 16: (x + 2)(x + 4) − 5(x − 4) = 48 ⇒ x² + x − 20 = 0, köklər 4 və −5. x = 4 məxrəci sıfra çevirir (yad kök). Cavab: −5.');
INSERT INTO public.questions VALUES (358, 6, 'g9-alg-eq-q3-18', 3, 18, 'hard', 'single', 'İki usta birlikdə işi 66/5 saata bitirir. Birinci usta təklikdə ikincidən 11 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "44", "B": "132/5", "C": "22", "D": "34", "E": "33"}'::jsonb, 'E', NULL, 'Birinci x saat, ikinci x + 11 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 11) = 5/66 ⇒ x = 22. İkinci usta: 33 saat.');
INSERT INTO public.questions VALUES (359, 6, 'g9-alg-eq-q3-19', 3, 19, 'hard', 'single', 'İki usta birlikdə işi 54/5 saata bitirir. Birinci usta təklikdə ikincidən 9 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "27", "B": "18", "C": "28", "D": "36", "E": "108/5"}'::jsonb, 'A', NULL, 'Birinci x saat, ikinci x + 9 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 9) = 5/54 ⇒ x = 18. İkinci usta: 27 saat.');
INSERT INTO public.questions VALUES (360, 6, 'g9-alg-eq-q3-20', 3, 20, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 9)/(x − 6) − 4/(x + 6) = −36/(x² − 36)', NULL, NULL, '{"A": "−1", "B": "6", "C": "1", "D": "7", "E": "2"}'::jsonb, 'C', NULL, 'Ortaq məxrəc x² − 36: (x − 9)(x + 6) − 4(x − 6) = −36 ⇒ x² − 7x + 6 = 0, köklər 6 və 1. x = 6 məxrəci sıfra çevirir (yad kök). Cavab: 1.');
INSERT INTO public.questions VALUES (361, 7, 'g9-alg-sys-q1-01', 1, 1, 'hard', 'single', 'Teatrda böyük bileti 4 manat, uşaq bileti 2 manatdır. Cəmi 59 bilet satıldı və 204 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "45", "B": "44", "C": "16", "D": "41", "E": "43"}'::jsonb, 'E', NULL, 'x + y = 59, 4x + 2y = 204 ⇒ x = 43, y = 16.');
INSERT INTO public.questions VALUES (362, 7, 'g9-alg-sys-q1-02', 1, 2, 'hard', 'single', 'Teatrda böyük bileti 5 manat, uşaq bileti 2 manatdır. Cəmi 85 bilet satıldı və 353 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "39", "B": "35", "C": "38", "D": "−37", "E": "37"}'::jsonb, 'E', NULL, 'x + y = 85, 5x + 2y = 353 ⇒ x = 61, y = 24.');
INSERT INTO public.questions VALUES (363, 7, 'g9-alg-sys-q1-03', 1, 3, 'hard', 'single', 'x + y = 4 və xy = 2 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "41", "B": "40", "C": "88", "D": "64", "E": "56"}'::jsonb, 'B', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 64 − 24 = 40.');
INSERT INTO public.questions VALUES (364, 7, 'g9-alg-sys-q1-04', 1, 4, 'hard', 'single', 'x² − y² = −91 və x + y = 7 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "30", "B": "109", "C": "−23", "D": "−30", "E": "−31"}'::jsonb, 'D', NULL, 'x − y = −91 : 7 = −13. x = −3, y = 10. Cavab: −30.');
INSERT INTO public.questions VALUES (365, 7, 'g9-alg-sys-q1-05', 1, 5, 'hard', 'single', 'Teatrda böyük bileti 14 manat, uşaq bileti 2 manatdır. Cəmi 37 bilet satıldı və 386 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "13", "B": "15", "C": "−15", "D": "17", "E": "16"}'::jsonb, 'B', NULL, 'x + y = 37, 14x + 2y = 386 ⇒ x = 26, y = 11.');
