INSERT INTO public.questions VALUES (368, 7, 'g9-alg-sys-q1-08', 1, 8, 'hard', 'single', 'x + y = 8 və xy = −11 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "248", "B": "512", "C": "600", "D": "776", "E": "777"}'::jsonb, 'D', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 512 − (−264) = 776.');
