INSERT INTO public.questions VALUES (400, 7, 'g9-alg-sys-q2-20', 2, 20, 'hard', 'single', 'x + y = 4 və xy = −9 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "172", "B": "173", "C": "64", "D": "−44", "E": "100"}'::jsonb, 'A', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 64 − (−108) = 172.');
INSERT INTO public.questions VALUES (401, 7, 'g9-alg-sys-q3-01', 3, 1, 'hard', 'single', 'x + y = 9 və xy = −13 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1080", "B": "378", "C": "846", "D": "729", "E": "1081"}'::jsonb, 'A', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 729 − (−351) = 1080.');
INSERT INTO public.questions VALUES (402, 7, 'g9-alg-sys-q3-02', 3, 2, 'hard', 'single', 'Teatrda böyük bileti 12 manat, uşaq bileti 5 manatdır. Cəmi 105 bilet satıldı və 1057 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "74", "B": "29", "C": "78", "D": "77", "E": "76"}'::jsonb, 'E', NULL, 'x + y = 105, 12x + 5y = 1057 ⇒ x = 76, y = 29.');
INSERT INTO public.questions VALUES (403, 7, 'g9-alg-sys-q3-03', 3, 3, 'hard', 'single', '{−3x + 7y = −68; 3x − 2y = 28} sistemi üçün x − y ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−12", "B": "−4", "C": "13", "D": "11", "E": "12"}'::jsonb, 'E', NULL, 'Toplama və ya əvəzləmə üsulu: x = 4, y = −8. x − y = 12.');
INSERT INTO public.questions VALUES (404, 7, 'g9-alg-sys-q3-04', 3, 4, 'hard', 'single', 'x + y = 12 və xy = 5 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1668", "B": "1548", "C": "1549", "D": "1728", "E": "1908"}'::jsonb, 'B', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 1728 − 180 = 1548.');
INSERT INTO public.questions VALUES (405, 7, 'g9-alg-sys-q3-05', 3, 5, 'hard', 'single', 'Teatrda böyük bileti 9 manat, uşaq bileti 8 manatdır. Cəmi 55 bilet satıldı və 469 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "5", "B": "4", "C": "1", "D": "3", "E": "−3"}'::jsonb, 'D', NULL, 'x + y = 55, 9x + 8y = 469 ⇒ x = 29, y = 26.');
INSERT INTO public.questions VALUES (406, 7, 'g9-alg-sys-q3-06', 3, 6, 'hard', 'single', 'Teatrda böyük bileti 6 manat, uşaq bileti 2 manatdır. Cəmi 28 bilet satıldı və 80 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "−15", "B": "−16", "C": "−18", "D": "16", "E": "−14"}'::jsonb, 'B', NULL, 'x + y = 28, 6x + 2y = 80 ⇒ x = 6, y = 22.');
INSERT INTO public.questions VALUES (407, 7, 'g9-alg-sys-q3-07', 3, 7, 'hard', 'open', 'x² − y² = −85 və x + y = 5 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '157', 'x − y = −85 : 5 = −17. x = −6, y = 11. Cavab: 157.');
INSERT INTO public.questions VALUES (408, 7, 'g9-alg-sys-q3-08', 3, 8, 'hard', 'single', 'x² − y² = −128 və x + y = 16 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "176", "B": "159", "C": "−160", "D": "160", "E": "48"}'::jsonb, 'D', NULL, 'x − y = −128 : 16 = −8. x = 4, y = 12. Cavab: 160.');
INSERT INTO public.questions VALUES (409, 7, 'g9-alg-sys-q3-09', 3, 9, 'hard', 'single', 'x² − y² = −224 və x + y = 16 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "15", "B": "14", "C": "31", "D": "226", "E": "−15"}'::jsonb, 'A', NULL, 'x − y = −224 : 16 = −14. x = 1, y = 15. Cavab: 15.');
INSERT INTO public.questions VALUES (410, 7, 'g9-alg-sys-q3-10', 3, 10, 'hard', 'single', 'x² − y² = −24 və x + y = −6 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "4", "B": "26", "C": "5", "D": "−5", "E": "−1"}'::jsonb, 'C', NULL, 'x − y = −24 : (−6) = 4. x = −1, y = −5. Cavab: 5.');
INSERT INTO public.questions VALUES (411, 7, 'g9-alg-sys-q3-11', 3, 11, 'hard', 'single', 'x² − y² = 13 və x + y = 13 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "55", "B": "42", "C": "41", "D": "85", "E": "−42"}'::jsonb, 'B', NULL, 'x − y = 13 : 13 = 1. x = 7, y = 6. Cavab: 42.');
INSERT INTO public.questions VALUES (412, 7, 'g9-alg-sys-q3-12', 3, 12, 'hard', 'single', '{7x + 7y = 21; −2x − 6y = −14} sistemi üçün xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−2", "B": "2", "C": "3", "D": "1", "E": "4"}'::jsonb, 'B', NULL, 'Toplama və ya əvəzləmə üsulu: x = 1, y = 2. xy = 2.');
INSERT INTO public.questions VALUES (413, 7, 'g9-alg-sys-q3-13', 3, 13, 'hard', 'single', 'x + y = 8 və xy = −3 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "67", "B": "64", "C": "70", "D": "58", "E": "71"}'::jsonb, 'C', NULL, 'x² + y² = (x + y)² − 2xy = 64 − (−6) = 70.');
INSERT INTO public.questions VALUES (414, 7, 'g9-alg-sys-q3-14', 3, 14, 'hard', 'open', '{−x − 5y = −47; 9x + 8y = 53} sistemi üçün xy ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '−30', 'Toplama və ya əvəzləmə üsulu: x = −3, y = 10. xy = −30.');
INSERT INTO public.questions VALUES (415, 7, 'g9-alg-sys-q3-15', 3, 15, 'hard', 'single', 'Teatrda böyük bileti 10 manat, uşaq bileti 3 manatdır. Cəmi 59 bilet satıldı və 527 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "43", "B": "−41", "C": "42", "D": "39", "E": "41"}'::jsonb, 'E', NULL, 'x + y = 59, 10x + 3y = 527 ⇒ x = 50, y = 9.');
INSERT INTO public.questions VALUES (416, 7, 'g9-alg-sys-q3-16', 3, 16, 'hard', 'single', '{3x + y = 33; 7x + 5y = 93} sistemi üçün x − y ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "15", "B": "3", "C": "2", "D": "4", "E": "−3"}'::jsonb, 'B', NULL, 'Toplama və ya əvəzləmə üsulu: x = 9, y = 6. x − y = 3.');
INSERT INTO public.questions VALUES (417, 7, 'g9-alg-sys-q3-17', 3, 17, 'hard', 'single', '{−7x + 9y = 59; −6x + 3y = −6} sistemi üçün xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "83", "B": "84", "C": "−84", "D": "85", "E": "19"}'::jsonb, 'B', NULL, 'Toplama və ya əvəzləmə üsulu: x = 7, y = 12. xy = 84.');
INSERT INTO public.questions VALUES (418, 7, 'g9-alg-sys-q3-18', 3, 18, 'hard', 'single', 'x + y = −6 və xy = −3 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "30", "B": "39", "C": "36", "D": "42", "E": "43"}'::jsonb, 'D', NULL, 'x² + y² = (x + y)² − 2xy = 36 − (−6) = 42.');
INSERT INTO public.questions VALUES (419, 7, 'g9-alg-sys-q3-19', 3, 19, 'hard', 'single', 'Teatrda böyük bileti 6 manat, uşaq bileti 2 manatdır. Cəmi 84 bilet satıldı və 376 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "22", "B": "21", "C": "20", "D": "−20", "E": "18"}'::jsonb, 'C', NULL, 'x + y = 84, 6x + 2y = 376 ⇒ x = 52, y = 32.');
INSERT INTO public.questions VALUES (420, 7, 'g9-alg-sys-q3-20', 3, 20, 'hard', 'single', 'x + y = 8 və xy = 4 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "64", "B": "72", "C": "56", "D": "60", "E": "57"}'::jsonb, 'C', NULL, 'x² + y² = (x + y)² − 2xy = 64 − 8 = 56.');
INSERT INTO public.questions VALUES (421, 8, 'g9-alg-quad-q1-01', 1, 1, 'hard', 'single', 'x² + 9x − 13 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 3 və x₂ + 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−4", "B": "−40", "C": "−31", "D": "−30", "E": "23"}'::jsonb, 'C', NULL, 'q = (x₁ + 3)(x₂ + 3) = x₁x₂ + 3(x₁ + x₂) + 9 = −13 − 27 + 9 = −31.');
INSERT INTO public.questions VALUES (422, 8, 'g9-alg-quad-q1-02', 1, 2, 'hard', 'single', 'x₁ və x₂ ədədləri x² + x − 13 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "27", "B": "−51", "C": "53/4", "D": "1", "E": "53"}'::jsonb, 'E', NULL, 'Viyet teoremi: x₁ + x₂ = −1, x₁x₂ = −13. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 1 − (−52) = 53.');
INSERT INTO public.questions VALUES (423, 8, 'g9-alg-quad-q1-03', 1, 3, 'hard', 'single', 'x² − mx + 144 = 0 tənliyinin köklərindən biri digərindən 4 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "−30", "B": "29", "C": "31", "D": "30", "E": "144"}'::jsonb, 'D', NULL, 'x₁ = 4x₂, x₁x₂ = 4x₂² = 144 ⇒ x₂² = 36, x₂ = 6, x₁ = 24. m = x₁ + x₂ = 30.');
INSERT INTO public.questions VALUES (424, 8, 'g9-alg-quad-q1-04', 1, 4, 'hard', 'single', 'x₁ və x₂ ədədləri x² − 12x + 1 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "140", "B": "35", "C": "148", "D": "144", "E": "142"}'::jsonb, 'A', NULL, 'Viyet teoremi: x₁ + x₂ = 12, x₁x₂ = 1. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 144 − 4 = 140.');
INSERT INTO public.questions VALUES (425, 8, 'g9-alg-quad-q1-05', 1, 5, 'hard', 'single', 'x² − x − 110 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "19", "B": "22", "C": "20", "D": "21", "E": "18"}'::jsonb, 'C', NULL, 'Köklər −10 və 11; a > 0, həllər köklər arasındadır. Tam həllər: 20.');
INSERT INTO public.questions VALUES (426, 8, 'g9-alg-quad-q1-06', 1, 6, 'hard', 'single', 'x² − mx + 2 = 0 tənliyinin köklərindən biri digərindən 2 dəfə böyükdür. m-in mənfi qiymətini tapın.', NULL, NULL, '{"A": "−4", "B": "2", "C": "3", "D": "−3", "E": "−2"}'::jsonb, 'D', NULL, 'x₁ = 2x₂, x₁x₂ = 2x₂² = 2 ⇒ x₂² = 1, x₂ = −1, x₁ = −2. m = x₁ + x₂ = −3.');
INSERT INTO public.questions VALUES (427, 8, 'g9-alg-quad-q1-07', 1, 7, 'hard', 'open', 'x² − mx + 180 = 0 tənliyinin köklərindən biri digərindən 5 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, NULL, NULL, '36', 'x₁ = 5x₂, x₁x₂ = 5x₂² = 180 ⇒ x₂² = 36, x₂ = 6, x₁ = 30. m = x₁ + x₂ = 36.');
INSERT INTO public.questions VALUES (428, 8, 'g9-alg-quad-q1-08', 1, 8, 'hard', 'single', 'x₁ və x₂ ədədləri −x² + 8x − 3 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "58", "B": "76", "C": "52", "D": "13", "E": "64"}'::jsonb, 'C', NULL, 'Viyet teoremi: x₁ + x₂ = 8, x₁x₂ = 3. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 64 − 12 = 52.');
INSERT INTO public.questions VALUES (429, 8, 'g9-alg-quad-q1-09', 1, 9, 'hard', 'single', 'x² − 28x + 132 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "15", "B": "14", "C": "16", "D": "13", "E": "17"}'::jsonb, 'A', NULL, 'Köklər 6 və 22; a > 0, həllər köklər arasındadır. Tam həllər: 15.');
INSERT INTO public.questions VALUES (430, 8, 'g9-alg-quad-q1-10', 1, 10, 'hard', 'single', 'x² + 3x − 4 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 4 və x₂ + 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "1", "B": "24", "C": "12", "D": "−16", "E": "0"}'::jsonb, 'E', NULL, 'q = (x₁ + 4)(x₂ + 4) = x₁x₂ + 4(x₁ + x₂) + 16 = −4 − 12 + 16 = 0.');
INSERT INTO public.questions VALUES (431, 8, 'g9-alg-quad-q1-11', 1, 11, 'hard', 'single', '3x² − 69x + 126 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "19", "B": "21", "C": "22", "D": "18", "E": "20"}'::jsonb, 'E', NULL, 'Köklər 2 və 21; a > 0, həllər köklər arasındadır. Tam həllər: 20.');
INSERT INTO public.questions VALUES (432, 8, 'g9-alg-quad-q1-12', 1, 12, 'hard', 'single', '2x² + 44x + 240 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "1", "B": "3", "C": "5", "D": "4", "E": "2"}'::jsonb, 'B', NULL, 'Köklər −12 və −10; a > 0, həllər köklər arasındadır. Tam həllər: 3.');
INSERT INTO public.questions VALUES (433, 8, 'g9-alg-quad-q1-13', 1, 13, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² − 10x + 6 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "25", "B": "19", "C": "37", "D": "13", "E": "13/4"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = 5, x₁x₂ = 3. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 25 − 12 = 13.');
INSERT INTO public.questions VALUES (434, 8, 'g9-alg-quad-q1-14', 1, 14, 'hard', 'open', 'x² + 9x + 2 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 1 və x₂ − 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, NULL, NULL, '12', 'q = (x₁ − 1)(x₂ − 1) = x₁x₂ − 1(x₁ + x₂) + 1 = 2 + 9 + 1 = 12.');
INSERT INTO public.questions VALUES (435, 8, 'g9-alg-quad-q1-15', 1, 15, 'hard', 'single', 'x² − 11x − 1 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 1 və x₂ + 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "11", "B": "12", "C": "−11", "D": "10", "E": "0"}'::jsonb, 'A', NULL, 'q = (x₁ + 1)(x₂ + 1) = x₁x₂ + 1(x₁ + x₂) + 1 = −1 + 11 + 1 = 11.');
INSERT INTO public.questions VALUES (436, 8, 'g9-alg-quad-q1-16', 1, 16, 'hard', 'single', 'x₁ və x₂ ədədləri 3x² + 7x − 15 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "229/9", "B": "−131/9", "C": "229/36", "D": "139/9", "E": "49/9"}'::jsonb, 'A', NULL, 'Viyet teoremi: x₁ + x₂ = −7/3, x₁x₂ = −5. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 49/9 − (−20) = 229/9.');
INSERT INTO public.questions VALUES (437, 8, 'g9-alg-quad-q1-17', 1, 17, 'hard', 'single', 'x² − 7x + 12 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 3 və x₂ + 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "21", "B": "43", "C": "0", "D": "33", "E": "42"}'::jsonb, 'E', NULL, 'q = (x₁ + 3)(x₂ + 3) = x₁x₂ + 3(x₁ + x₂) + 9 = 12 + 21 + 9 = 42.');
INSERT INTO public.questions VALUES (438, 8, 'g9-alg-quad-q1-18', 1, 18, 'hard', 'single', 'x² − mx + 6 = 0 tənliyinin köklərindən biri digərindən 3/2 dəfə böyükdür. m-in mənfi qiymətini tapın.', NULL, NULL, '{"A": "−4", "B": "−5", "C": "6", "D": "5", "E": "−6"}'::jsonb, 'B', NULL, 'x₁ = (3/2)·x₂, x₁x₂ = (3/2)·x₂² = 6 ⇒ x₂² = 4, x₂ = −2, x₁ = −3. m = x₁ + x₂ = −5.');
INSERT INTO public.questions VALUES (439, 8, 'g9-alg-quad-q1-19', 1, 19, 'hard', 'single', 'x² − mx + 64 = 0 tənliyinin köklərindən biri digərindən 4 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "64", "B": "20", "C": "−20", "D": "21", "E": "19"}'::jsonb, 'B', NULL, 'x₁ = 4x₂, x₁x₂ = 4x₂² = 64 ⇒ x₂² = 16, x₂ = 4, x₁ = 16. m = x₁ + x₂ = 20.');
INSERT INTO public.questions VALUES (440, 8, 'g9-alg-quad-q1-20', 1, 20, 'hard', 'single', '3x² − 14x − 40 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "6", "B": "10", "C": "7", "D": "8", "E": "9"}'::jsonb, 'D', NULL, 'Köklər −2 və 20/3; a > 0, həllər köklər arasındadır. Tam həllər: 8.');
INSERT INTO public.questions VALUES (441, 8, 'g9-alg-quad-q2-01', 2, 1, 'hard', 'single', 'x² − mx + 4 = 0 tənliyinin köklərindən biri digərindən 4 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "6", "B": "5", "C": "−5", "D": "4", "E": "10"}'::jsonb, 'B', NULL, 'x₁ = 4x₂, x₁x₂ = 4x₂² = 4 ⇒ x₂² = 1, x₂ = 1, x₁ = 4. m = x₁ + x₂ = 5.');
INSERT INTO public.questions VALUES (442, 8, 'g9-alg-quad-q2-02', 2, 2, 'hard', 'single', 'x² − 5x − 12 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 4 və x₂ + 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "25", "B": "−16", "C": "8", "D": "4", "E": "24"}'::jsonb, 'E', NULL, 'q = (x₁ + 4)(x₂ + 4) = x₁x₂ + 4(x₁ + x₂) + 16 = −12 + 20 + 16 = 24.');
INSERT INTO public.questions VALUES (443, 8, 'g9-alg-quad-q2-03', 2, 3, 'hard', 'single', '3x² + 25x + 48 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "2", "B": "4", "C": "1", "D": "0", "E": "3"}'::jsonb, 'A', NULL, 'Köklər −16/3 və −3; a > 0, həllər köklər arasındadır. Tam həllər: 2.');
INSERT INTO public.questions VALUES (444, 8, 'g9-alg-quad-q2-04', 2, 4, 'hard', 'single', 'x² + 5x − 10 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 2 və x₂ − 2 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "0", "B": "5", "C": "−6", "D": "−16", "E": "4"}'::jsonb, 'E', NULL, 'q = (x₁ − 2)(x₂ − 2) = x₁x₂ − 2(x₁ + x₂) + 4 = −10 + 10 + 4 = 4.');
INSERT INTO public.questions VALUES (445, 8, 'g9-alg-quad-q2-05', 2, 5, 'hard', 'single', 'x² + 14x + 48 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "1", "B": "3", "C": "−1", "D": "0", "E": "2"}'::jsonb, 'A', NULL, 'Köklər −8 və −6; a > 0, həllər köklər arasındadır. Tam həllər: 1.');
INSERT INTO public.questions VALUES (446, 8, 'g9-alg-quad-q2-06', 2, 6, 'hard', 'single', '3x² − 19x − 72 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "11", "B": "12", "C": "10", "D": "13", "E": "9"}'::jsonb, 'A', NULL, 'Köklər −8/3 və 9; a > 0, həllər köklər arasındadır. Tam həllər: 11.');
INSERT INTO public.questions VALUES (447, 8, 'g9-alg-quad-q2-07', 2, 7, 'hard', 'open', 'x² − mx + 80 = 0 tənliyinin köklərindən biri digərindən 5 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, NULL, NULL, '24', 'x₁ = 5x₂, x₁x₂ = 5x₂² = 80 ⇒ x₂² = 16, x₂ = 4, x₁ = 20. m = x₁ + x₂ = 24.');
INSERT INTO public.questions VALUES (448, 8, 'g9-alg-quad-q2-08', 2, 8, 'hard', 'single', 'x² − 8x + 10 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 4 və x₂ − 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "26", "B": "−6", "C": "−22", "D": "−5", "E": "58"}'::jsonb, 'B', NULL, 'q = (x₁ − 4)(x₂ − 4) = x₁x₂ − 4(x₁ + x₂) + 16 = 10 − 32 + 16 = −6.');
INSERT INTO public.questions VALUES (449, 8, 'g9-alg-quad-q2-09', 2, 9, 'hard', 'single', 'x₁ və x₂ ədədləri x² − 5x + 2 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "25", "B": "−21", "C": "23", "D": "21", "E": "29"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = 5, x₁x₂ = 2. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 25 − 4 = 21.');
INSERT INTO public.questions VALUES (450, 8, 'g9-alg-quad-q2-10', 2, 10, 'hard', 'single', 'x² − mx + 5 = 0 tənliyinin köklərindən biri digərindən 5 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "12", "B": "6", "C": "5", "D": "−6", "E": "7"}'::jsonb, 'B', NULL, 'x₁ = 5x₂, x₁x₂ = 5x₂² = 5 ⇒ x₂² = 1, x₂ = 1, x₁ = 5. m = x₁ + x₂ = 6.');
INSERT INTO public.questions VALUES (451, 8, 'g9-alg-quad-q2-11', 2, 11, 'hard', 'single', 'x² + x − 30 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "12", "B": "10", "C": "11", "D": "9", "E": "8"}'::jsonb, 'B', NULL, 'Köklər −6 və 5; a > 0, həllər köklər arasındadır. Tam həllər: 10.');
INSERT INTO public.questions VALUES (452, 8, 'g9-alg-quad-q2-12', 2, 12, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² − 4x − 13 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−17", "B": "4", "C": "21/2", "D": "−9", "E": "17"}'::jsonb, 'E', NULL, 'Viyet teoremi: x₁ + x₂ = 2, x₁x₂ = −13/2. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 4 − (−13) = 17.');
INSERT INTO public.questions VALUES (453, 8, 'g9-alg-quad-q2-13', 2, 13, 'hard', 'single', 'x² + x − 6 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 1 və x₂ + 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−7", "B": "−6", "C": "6", "D": "−4", "E": "−5"}'::jsonb, 'B', NULL, 'q = (x₁ + 1)(x₂ + 1) = x₁x₂ + 1(x₁ + x₂) + 1 = −6 − 1 + 1 = −6.');
INSERT INTO public.questions VALUES (454, 8, 'g9-alg-quad-q2-14', 2, 14, 'hard', 'open', 'x₁ və x₂ ədədləri −x² + 7x − 9 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '31', 'Viyet teoremi: x₁ + x₂ = 7, x₁x₂ = 9. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 49 − 18 = 31.');
INSERT INTO public.questions VALUES (455, 8, 'g9-alg-quad-q2-15', 2, 15, 'hard', 'single', 'x² − mx + 8 = 0 tənliyinin köklərindən biri digərindən 2 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "7", "B": "6", "C": "8", "D": "−6", "E": "5"}'::jsonb, 'B', NULL, 'x₁ = 2x₂, x₁x₂ = 2x₂² = 8 ⇒ x₂² = 4, x₂ = 2, x₁ = 4. m = x₁ + x₂ = 6.');
INSERT INTO public.questions VALUES (456, 8, 'g9-alg-quad-q2-16', 2, 16, 'hard', 'single', 'x² − 7x − 5 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 4 və x₂ − 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−16", "B": "−17", "C": "39", "D": "−33", "E": "11"}'::jsonb, 'B', NULL, 'q = (x₁ − 4)(x₂ − 4) = x₁x₂ − 4(x₁ + x₂) + 16 = −5 − 28 + 16 = −17.');
INSERT INTO public.questions VALUES (457, 8, 'g9-alg-quad-q2-17', 2, 17, 'hard', 'single', 'x² − mx + 12 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in mənfi qiymətini tapın.', NULL, NULL, '{"A": "−9", "B": "−8", "C": "−7", "D": "12", "E": "8"}'::jsonb, 'B', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 12 ⇒ x₂² = 4, x₂ = −2, x₁ = −6. m = x₁ + x₂ = −8.');
INSERT INTO public.questions VALUES (458, 8, 'g9-alg-quad-q2-18', 2, 18, 'hard', 'single', '3x² + 36x − 84 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "14", "B": "13", "C": "17", "D": "15", "E": "16"}'::jsonb, 'D', NULL, 'Köklər −14 və 2; a > 0, həllər köklər arasındadır. Tam həllər: 15.');
INSERT INTO public.questions VALUES (459, 8, 'g9-alg-quad-q2-19', 2, 19, 'hard', 'single', 'x₁ və x₂ ədədləri −x² + 8x − 14 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "36", "B": "50", "C": "64", "D": "92", "E": "−36"}'::jsonb, 'A', NULL, 'Viyet teoremi: x₁ + x₂ = 8, x₁x₂ = 14. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 64 − 28 = 36.');
INSERT INTO public.questions VALUES (460, 8, 'g9-alg-quad-q2-20', 2, 20, 'hard', 'single', 'x₁ və x₂ ədədləri −x² − 11x − 1 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "123", "B": "120", "C": "121", "D": "119", "E": "−119"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = −11, x₁x₂ = 1. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 121 − 2 = 119.');
INSERT INTO public.questions VALUES (461, 8, 'g9-alg-quad-q3-01', 3, 1, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² − 4x − 7 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "4", "B": "−3", "C": "−11", "D": "15/2", "E": "11"}'::jsonb, 'E', NULL, 'Viyet teoremi: x₁ + x₂ = 2, x₁x₂ = −7/2. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 4 − (−7) = 11.');
INSERT INTO public.questions VALUES (462, 8, 'g9-alg-quad-q3-02', 3, 2, 'hard', 'single', '2x² − 76x + 690 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "9", "B": "11", "C": "8", "D": "10", "E": "7"}'::jsonb, 'A', NULL, 'Köklər 15 və 23; a > 0, həllər köklər arasındadır. Tam həllər: 9.');
INSERT INTO public.questions VALUES (463, 8, 'g9-alg-quad-q3-03', 3, 3, 'hard', 'single', 'x² − 8x − 2 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 3 və x₂ + 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "7", "B": "31", "C": "−17", "D": "32", "E": "22"}'::jsonb, 'B', NULL, 'q = (x₁ + 3)(x₂ + 3) = x₁x₂ + 3(x₁ + x₂) + 9 = −2 + 24 + 9 = 31.');
INSERT INTO public.questions VALUES (464, 8, 'g9-alg-quad-q3-04', 3, 4, 'hard', 'single', '3x² + 35x − 342 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "25", "B": "24", "C": "23", "D": "27", "E": "26"}'::jsonb, 'A', NULL, 'Köklər −18 və 19/3; a > 0, həllər köklər arasındadır. Tam həllər: 25.');
INSERT INTO public.questions VALUES (465, 8, 'g9-alg-quad-q3-05', 3, 5, 'hard', 'single', '2x² − 15x − 8 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "9", "B": "7", "C": "8", "D": "10", "E": "11"}'::jsonb, 'A', NULL, 'Köklər −1/2 və 8; a > 0, həllər köklər arasındadır. Tam həllər: 9.');
INSERT INTO public.questions VALUES (466, 8, 'g9-alg-quad-q3-06', 3, 6, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² + 9x − 6 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "129/4", "B": "33/4", "C": "129/16", "D": "105/4", "E": "81/4"}'::jsonb, 'A', NULL, 'Viyet teoremi: x₁ + x₂ = −9/2, x₁x₂ = −3. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 81/4 − (−12) = 129/4.');
INSERT INTO public.questions VALUES (467, 8, 'g9-alg-quad-q3-07', 3, 7, 'hard', 'open', 'x² − mx + 45 = 0 tənliyinin köklərindən biri digərindən 5 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, NULL, NULL, '18', 'x₁ = 5x₂, x₁x₂ = 5x₂² = 45 ⇒ x₂² = 9, x₂ = 3, x₁ = 15. m = x₁ + x₂ = 18.');
INSERT INTO public.questions VALUES (468, 8, 'g9-alg-quad-q3-08', 3, 8, 'hard', 'single', 'x² + 8x − 9 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 3 və x₂ + 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "0", "B": "24", "C": "−24", "D": "−23", "E": "−33"}'::jsonb, 'C', NULL, 'q = (x₁ + 3)(x₂ + 3) = x₁x₂ + 3(x₁ + x₂) + 9 = −9 − 24 + 9 = −24.');
INSERT INTO public.questions VALUES (469, 8, 'g9-alg-quad-q3-09', 3, 9, 'hard', 'single', 'x² − mx + 3 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in mənfi qiymətini tapın.', NULL, NULL, '{"A": "3", "B": "4", "C": "−4", "D": "−3", "E": "−5"}'::jsonb, 'C', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 3 ⇒ x₂² = 1, x₂ = −1, x₁ = −3. m = x₁ + x₂ = −4.');
INSERT INTO public.questions VALUES (470, 8, 'g9-alg-quad-q3-10', 3, 10, 'hard', 'single', 'x² − 3x − 1 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 1 və x₂ + 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "4", "B": "3", "C": "0", "D": "−3", "E": "2"}'::jsonb, 'B', NULL, 'q = (x₁ + 1)(x₂ + 1) = x₁x₂ + 1(x₁ + x₂) + 1 = −1 + 3 + 1 = 3.');
INSERT INTO public.questions VALUES (471, 8, 'g9-alg-quad-q3-11', 3, 11, 'hard', 'single', 'x₁ və x₂ ədədləri x² − 7x + 8 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "33", "B": "49", "C": "17/4", "D": "17", "E": "81"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = 7, x₁x₂ = 8. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 49 − 32 = 17.');
INSERT INTO public.questions VALUES (472, 8, 'g9-alg-quad-q3-12', 3, 12, 'hard', 'single', 'x² + 8x − 4 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 4 və x₂ + 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "12", "B": "−19", "C": "44", "D": "−20", "E": "−36"}'::jsonb, 'D', NULL, 'q = (x₁ + 4)(x₂ + 4) = x₁x₂ + 4(x₁ + x₂) + 16 = −4 − 32 + 16 = −20.');
INSERT INTO public.questions VALUES (473, 8, 'g9-alg-quad-q3-13', 3, 13, 'hard', 'single', 'x² − mx + 3 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "−4", "B": "4", "C": "3", "D": "8", "E": "5"}'::jsonb, 'B', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 3 ⇒ x₂² = 1, x₂ = 1, x₁ = 3. m = x₁ + x₂ = 4.');
INSERT INTO public.questions VALUES (474, 8, 'g9-alg-quad-q3-14', 3, 14, 'hard', 'open', 'x₁ və x₂ ədədləri x² − 7x − 7 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '77', 'Viyet teoremi: x₁ + x₂ = 7, x₁x₂ = −7. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 49 − (−28) = 77.');
INSERT INTO public.questions VALUES (475, 8, 'g9-alg-quad-q3-15', 3, 15, 'hard', 'single', 'x² − 12x − 4 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 3 və x₂ + 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "5", "B": "−31", "C": "41", "D": "42", "E": "32"}'::jsonb, 'C', NULL, 'q = (x₁ + 3)(x₂ + 3) = x₁x₂ + 3(x₁ + x₂) + 9 = −4 + 36 + 9 = 41.');
INSERT INTO public.questions VALUES (476, 8, 'g9-alg-quad-q3-16', 3, 16, 'hard', 'single', 'x² − mx + 108 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "25", "B": "−24", "C": "24", "D": "23", "E": "108"}'::jsonb, 'C', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 108 ⇒ x₂² = 36, x₂ = 6, x₁ = 18. m = x₁ + x₂ = 24.');
INSERT INTO public.questions VALUES (477, 8, 'g9-alg-quad-q3-17', 3, 17, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² − 8x + 7 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "16", "B": "1/2", "C": "2", "D": "30", "E": "9"}'::jsonb, 'C', NULL, 'Viyet teoremi: x₁ + x₂ = 4, x₁x₂ = 7/2. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 16 − 14 = 2.');
INSERT INTO public.questions VALUES (478, 8, 'g9-alg-quad-q3-18', 3, 18, 'hard', 'single', 'x₁ və x₂ ədədləri 3x² + 11x + 7 = 0 tənliyinin kökləridir. (x₁ − x₂)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "37/36", "B": "121/9", "C": "37/9", "D": "205/9", "E": "79/9"}'::jsonb, 'C', NULL, 'Viyet teoremi: x₁ + x₂ = −11/3, x₁x₂ = 7/3. (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 121/9 − 28/3 = 37/9.');
INSERT INTO public.questions VALUES (479, 8, 'g9-alg-quad-q3-19', 3, 19, 'hard', 'single', '2x² − 30x − 152 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "20", "B": "21", "C": "23", "D": "22", "E": "24"}'::jsonb, 'D', NULL, 'Köklər −4 və 19; a > 0, həllər köklər arasındadır. Tam həllər: 22.');
INSERT INTO public.questions VALUES (480, 8, 'g9-alg-quad-q3-20', 3, 20, 'hard', 'single', '2x² + 14x − 36 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "12", "B": "8", "C": "11", "D": "9", "E": "10"}'::jsonb, 'E', NULL, 'Köklər −9 və 2; a > 0, həllər köklər arasındadır. Tam həllər: 10.');
INSERT INTO public.questions VALUES (481, 9, 'g9-alg-prog-q1-01', 1, 1, 'hard', 'single', '107-dən 427-yə qədər (hər ikisi daxil) 7-yə bölünən, lakin 4-ə bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, '{"A": "9233", "B": "9177", "C": "9205", "D": "12397", "E": "−8883"}'::jsonb, 'C', NULL, '7-yə bölünənlərin cəmi (ədədi silsilə): 12397. Onlardan 28-ə bölünənlər (həm 7-yə, həm 4-ə): 3192. Fərq: 9205.');
INSERT INTO public.questions VALUES (482, 9, 'g9-alg-prog-q1-02', 1, 2, 'hard', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 2 və a₉ = −16 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "−4", "B": "−1", "C": "−2", "D": "−3", "E": "0"}'::jsonb, 'C', NULL, 'a₂ = x olsun: a₃ = 2 + x, a₄ = 2 + 2x, … a₉ = 13·2 + 21x = −16 ⇒ x = −2.');
INSERT INTO public.questions VALUES (483, 9, 'g9-alg-prog-q1-03', 1, 3, 'hard', 'single', 'Ədədi silsilədə a₇ + a₆ = 27 və a₁₆ = 61 olarsa, ilk 25 həddin cəmini tapın.', NULL, NULL, '{"A": "1256", "B": "1155", "C": "1275", "D": "1025", "E": "1150"}'::jsonb, 'E', NULL, '2a₁ + 11d = 27, a₁ + 15d = 61 ⇒ a₁ = −14, d = 5. S₂₅ = (2a₁ + 24d)·25/2 = 1150.');
INSERT INTO public.questions VALUES (484, 9, 'g9-alg-prog-q1-04', 1, 4, 'hard', 'single', '55-dən 844-ə qədər (hər ikisi daxil) 11-ə bölünən, lakin 5-ə bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, '{"A": "32076", "B": "25531", "C": "−38629", "D": "25476", "E": "25421"}'::jsonb, 'D', NULL, '11-ə bölünənlərin cəmi (ədədi silsilə): 32076. Onlardan 55-ə bölünənlər (həm 11-ə, həm 5-ə): 6600. Fərq: 25476.');
INSERT INTO public.questions VALUES (485, 9, 'g9-alg-prog-q1-05', 1, 5, 'hard', 'single', '172-dən 661-ə qədər (hər ikisi daxil) 6-ya bölünən, lakin 10-a bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, '{"A": "27024", "B": "34194", "C": "13614", "D": "27054", "E": "27084"}'::jsonb, 'D', NULL, '6-ya bölünənlərin cəmi (ədədi silsilə): 34194. Onlardan 30-a bölünənlər (həm 6-ya, həm 10-a): 7140. Fərq: 27054.');
