INSERT INTO public.questions VALUES (526, 9, 'g9-alg-prog-q3-06', 3, 6, 'hard', 'single', 'Ədədi silsilədə a₆ + a₁₄ = 150 və a₁₂ = 89 olarsa, ilk 26 həddin cəmini tapın.', NULL, NULL, '{"A": "2496", "B": "2405", "C": "2769", "D": "2587", "E": "2774"}'::jsonb, 'D', NULL, '2a₁ + 18d = 150, a₁ + 11d = 89 ⇒ a₁ = 12, d = 7. S₂₆ = (2a₁ + 25d)·26/2 = 2587.');
INSERT INTO public.questions VALUES (527, 9, 'g9-alg-prog-q3-07', 3, 7, 'hard', 'open', 'Ədədi silsilədə a₉ + a₅ = −64 və a₁₉ = −116 olarsa, ilk 11 həddin cəmini tapın.', NULL, NULL, NULL, NULL, '−275', '2a₁ + 12d = −64, a₁ + 18d = −116 ⇒ a₁ = 10, d = −7. S₁₁ = (2a₁ + 10d)·11/2 = −275.');
INSERT INTO public.questions VALUES (528, 9, 'g9-alg-prog-q3-08', 3, 8, 'hard', 'single', 'Həndəsi silsilədə b₄ = 3/4 və b₅ = 3/8. İlk 5 həddin cəmini tapın.', NULL, NULL, '{"A": "45/4", "B": "−93/8", "C": "141/8", "D": "183/16", "E": "93/8"}'::jsonb, 'E', NULL, 'q = b₅/b₄ = 1/2, b₁ = 6. S₅ = b₁(qⁿ − 1)/(q − 1) = 93/8.');
INSERT INTO public.questions VALUES (529, 9, 'g9-alg-prog-q3-09', 3, 9, 'hard', 'single', '18-dən 433-ə qədər (hər ikisi daxil) 11-ə bölünən, lakin 10-a bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, '{"A": "8019", "B": "7799", "C": "8569", "D": "7909", "E": "−881"}'::jsonb, 'D', NULL, '11-ə bölünənlərin cəmi (ədədi silsilə): 8569. Onlardan 110-a bölünənlər (həm 11-ə, həm 10-a): 660. Fərq: 7909.');
INSERT INTO public.questions VALUES (530, 9, 'g9-alg-prog-q3-10', 3, 10, 'hard', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = −2 və a₇ = −42 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "−2", "B": "−6", "C": "−3", "D": "−4", "E": "−5"}'::jsonb, 'D', NULL, 'a₂ = x olsun: a₃ = −2 + x, a₄ = −2 + 2x, … a₇ = 5·(−2) + 8x = −42 ⇒ x = −4.');
INSERT INTO public.questions VALUES (531, 9, 'g9-alg-prog-q3-11', 3, 11, 'hard', 'single', 'Ədədi silsilədə a₁₃ + a₁₀ = 154 və a₇ = 41 olarsa, ilk 15 həddin cəmini tapın.', NULL, NULL, '{"A": "840", "B": "615", "C": "855", "D": "675", "E": "735"}'::jsonb, 'E', NULL, '2a₁ + 21d = 154, a₁ + 6d = 41 ⇒ a₁ = −7, d = 8. S₁₅ = (2a₁ + 14d)·15/2 = 735.');
INSERT INTO public.questions VALUES (532, 9, 'g9-alg-prog-q3-12', 3, 12, 'hard', 'single', 'Ədədi silsilədə a₃ + a₉ = 32 və a₁₄ = 56 olarsa, ilk 23 həddin cəmini tapın.', NULL, NULL, '{"A": "1058", "B": "1159", "C": "1173", "D": "1063", "E": "943"}'::jsonb, 'A', NULL, '2a₁ + 10d = 32, a₁ + 13d = 56 ⇒ a₁ = −9, d = 5. S₂₃ = (2a₁ + 22d)·23/2 = 1058.');
INSERT INTO public.questions VALUES (533, 9, 'g9-alg-prog-q3-13', 3, 13, 'hard', 'single', 'Ədədi silsilədə a₁₀ + a₆ = −2 və a₉ = −2 olarsa, ilk 18 həddin cəmini tapın.', NULL, NULL, '{"A": "−27", "B": "−45", "C": "−56", "D": "−63", "E": "−36"}'::jsonb, 'B', NULL, '2a₁ + 14d = −2, a₁ + 8d = −2 ⇒ a₁ = 6, d = −1. S₁₈ = (2a₁ + 17d)·18/2 = −45.');
INSERT INTO public.questions VALUES (534, 9, 'g9-alg-prog-q3-14', 3, 14, 'hard', 'open', '64-dən 958-ə qədər (hər ikisi daxil) 3-ə bölünən, lakin 10-a bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, NULL, NULL, '137637', '3-ə bölünənlərin cəmi (ədədi silsilə): 152427. Onlardan 30-a bölünənlər (həm 3-ə, həm 10-a): 14790. Fərq: 137637.');
INSERT INTO public.questions VALUES (535, 9, 'g9-alg-prog-q3-15', 3, 15, 'hard', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 9 və a₆ = 2 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "−5", "B": "−4", "C": "−6", "D": "−7", "E": "−3"}'::jsonb, 'A', NULL, 'a₂ = x olsun: a₃ = 9 + x, a₄ = 9 + 2x, … a₆ = 3·9 + 5x = 2 ⇒ x = −5.');
INSERT INTO public.questions VALUES (536, 9, 'g9-alg-prog-q3-16', 3, 16, 'hard', 'single', 'Həndəsi silsilədə b₂ = −3/2 və b₅ = −3/16. İlk 8 həddin cəmini tapın.', NULL, NULL, '{"A": "−1527/256", "B": "−1149/128", "C": "765/128", "D": "−765/128", "E": "−381/64"}'::jsonb, 'D', NULL, 'q^3 = b₅/b₂ = 1/8 ⇒ q = 1/2, b₁ = −3. S₈ = b₁(qⁿ − 1)/(q − 1) = −765/128.');
INSERT INTO public.questions VALUES (537, 9, 'g9-alg-prog-q3-17', 3, 17, 'hard', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 7 və a₇ = 51 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "2", "B": "3", "C": "4", "D": "1", "E": "0"}'::jsonb, 'A', NULL, 'a₂ = x olsun: a₃ = 7 + x, a₄ = 7 + 2x, … a₇ = 5·7 + 8x = 51 ⇒ x = 2.');
INSERT INTO public.questions VALUES (538, 9, 'g9-alg-prog-q3-18', 3, 18, 'hard', 'single', '88-dən 532-yə qədər (hər ikisi daxil) 11-ə bölünən, lakin 2-yə bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, '{"A": "6182", "B": "−56502", "C": "12628", "D": "6138", "E": "6160"}'::jsonb, 'E', NULL, '11-ə bölünənlərin cəmi (ədədi silsilə): 12628. Onlardan 22-yə bölünənlər (həm 11-ə, həm 2-yə): 6468. Fərq: 6160.');
INSERT INTO public.questions VALUES (539, 9, 'g9-alg-prog-q3-19', 3, 19, 'hard', 'single', '68-dən 609-a qədər (hər ikisi daxil) 7-yə bölünən, lakin 10-a bölünməyən natural ədədlərin cəmini tapın.', NULL, NULL, '{"A": "26481", "B": "8391", "C": "23961", "D": "24031", "E": "23891"}'::jsonb, 'C', NULL, '7-yə bölünənlərin cəmi (ədədi silsilə): 26481. Onlardan 70-ə bölünənlər (həm 7-yə, həm 10-a): 2520. Fərq: 23961.');
INSERT INTO public.questions VALUES (540, 9, 'g9-alg-prog-q3-20', 3, 20, 'hard', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 4 və a₈ = 97 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "5", "B": "3", "C": "6", "D": "7", "E": "4"}'::jsonb, 'A', NULL, 'a₂ = x olsun: a₃ = 4 + x, a₄ = 4 + 2x, … a₈ = 8·4 + 13x = 97 ⇒ x = 5.');
INSERT INTO public.questions VALUES (541, 10, 'g9-alg-func-q1-01', 1, 1, 'hard', 'single', 'y = √(5 − |x − 5|) / (x² − 1) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "12", "B": "10", "C": "9", "D": "11", "E": "8"}'::jsonb, 'B', NULL, '|x − 5| ≤ 5 ⇒ 0 ≤ x ≤ 10: 11 tam ədəd. x² ≠ 1 şərti çıxarır: 1. Cavab: 10.');
INSERT INTO public.questions VALUES (542, 10, 'g9-alg-func-q1-02', 1, 2, 'hard', 'single', 'y = x² − 4 parabolası ilə y = −6x + 3 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−7", "B": "−13", "C": "−6", "D": "−8", "E": "7"}'::jsonb, 'A', NULL, 'x² + 6x − 7 = 0 ⇒ x₁ = −7, x₂ = 1; y = −6x + 3: y₁ = 45, y₂ = −3. Cavab: −7.');
INSERT INTO public.questions VALUES (543, 10, 'g9-alg-func-q1-03', 1, 3, 'hard', 'single', 'f(x) = −x + 2, g(x) = x² − 4x + 4. f(g(x)) = −4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "5", "B": "8", "C": "−4", "D": "4", "E": "6"}'::jsonb, 'D', NULL, 'f(g(x)) = −g(x) + 2 = −4 ⇒ g(x) = 6 ⇒ x² − 4x − 2 = 0 (D > 0). Köklərin cəmi 4.');
INSERT INTO public.questions VALUES (544, 10, 'g9-alg-func-q1-04', 1, 4, 'hard', 'single', 'y = √(10 − |x|) / (x² − 2) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "21", "B": "23", "C": "20", "D": "19", "E": "22"}'::jsonb, 'A', NULL, '|x| ≤ 10 ⇒ −10 ≤ x ≤ 10: 21 tam ədəd. x² ≠ 2 şərti bu aralıqda heç nə çıxarmır. Cavab: 21.');
INSERT INTO public.questions VALUES (545, 10, 'g9-alg-func-q1-05', 1, 5, 'hard', 'single', 'y = x² − 5x − 4 parabolası ilə y = −4x + 8 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−12", "B": "−13", "C": "12", "D": "−16", "E": "1"}'::jsonb, 'A', NULL, 'x² − x − 12 = 0 ⇒ x₁ = −3, x₂ = 4; y = −4x + 8: y₁ = 20, y₂ = −8. Cavab: −12.');
INSERT INTO public.questions VALUES (546, 10, 'g9-alg-func-q1-06', 1, 6, 'hard', 'single', 'y = x² − 6x − 3 parabolası ilə y = −4x düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "−48", "B": "2", "C": "−8", "D": "−12", "E": "−9"}'::jsonb, 'C', NULL, 'x² − 2x − 3 = 0 ⇒ x₁ = −1, x₂ = 3; y = −4x: y₁ = 4, y₂ = −12. Cavab: −8.');
INSERT INTO public.questions VALUES (547, 10, 'g9-alg-func-q1-07', 1, 7, 'hard', 'open', 'f(4x + 4) = x² + 3x − 5 olarsa, f(−7) qiymətini tapın.', NULL, NULL, NULL, NULL, '−91/16', '4x + 4 = −7 ⇒ x = −11/4. f(−7) = (−11/4)² + 3·(−11/4) − 5 = −91/16.');
INSERT INTO public.questions VALUES (548, 10, 'g9-alg-func-q1-08', 1, 8, 'hard', 'single', 'y = x² + 8x + 9 parabolası ilə y = −4x − 2 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "11", "B": "−12", "C": "−11", "D": "7", "E": "10"}'::jsonb, 'A', NULL, 'x² + 12x + 11 = 0 ⇒ x₁ = −11, x₂ = −1; y = −4x − 2: y₁ = 42, y₂ = 2. Cavab: 11.');
INSERT INTO public.questions VALUES (549, 10, 'g9-alg-func-q1-09', 1, 9, 'hard', 'single', 'y = x² − 3x parabolası ilə y = 4 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−4", "B": "−3", "C": "−5", "D": "3", "E": "4"}'::jsonb, 'A', NULL, 'x² − 3x − 4 = 0 ⇒ x₁ = −1, x₂ = 4; y = 4: y₁ = 4, y₂ = 4. Cavab: −4.');
INSERT INTO public.questions VALUES (550, 10, 'g9-alg-func-q1-10', 1, 10, 'hard', 'single', 'f(x) = x − 4, g(x) = x² + 4x − 7. f(g(x)) = 11 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "4", "B": "−8", "C": "−4", "D": "15", "E": "−3"}'::jsonb, 'C', NULL, 'f(g(x)) = g(x) − 4 = 11 ⇒ g(x) = 15 ⇒ x² + 4x − 22 = 0 (D > 0). Köklərin cəmi −4.');
INSERT INTO public.questions VALUES (551, 10, 'g9-alg-func-q1-11', 1, 11, 'hard', 'single', 'y = √(6 − |x + 3|) / (x² − 2) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "15", "B": "12", "C": "11", "D": "13", "E": "14"}'::jsonb, 'D', NULL, '|x + 3| ≤ 6 ⇒ −9 ≤ x ≤ 3: 13 tam ədəd. x² ≠ 2 şərti bu aralıqda heç nə çıxarmır. Cavab: 13.');
INSERT INTO public.questions VALUES (552, 10, 'g9-alg-func-q1-12', 1, 12, 'hard', 'single', 'f(x) = 3x + 3, g(x) = x² + 5x − 8. f(g(x)) = −7 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−10", "B": "5", "C": "−5", "D": "−10/3", "E": "−4"}'::jsonb, 'C', NULL, 'f(g(x)) = 3g(x) + 3 = −7 ⇒ g(x) = −10/3 ⇒ x² + 5x − 14/3 = 0 (D > 0). Köklərin cəmi −5.');
INSERT INTO public.questions VALUES (553, 10, 'g9-alg-func-q1-13', 1, 13, 'hard', 'single', 'f(2x − 1) = x² − 4x + 4 olarsa, f(−4) qiymətini tapın.', NULL, NULL, '{"A": "53/4", "B": "36", "C": "121", "D": "81/4", "E": "49/4"}'::jsonb, 'E', NULL, '2x − 1 = −4 ⇒ x = −3/2. f(−4) = (−3/2)² − 4·(−3/2) + 4 = 49/4.');
INSERT INTO public.questions VALUES (554, 10, 'g9-alg-func-q1-14', 1, 14, 'hard', 'open', 'f(x) = 2x + 2, g(x) = x² − 3x + 2. f(g(x)) = 12 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '3', 'f(g(x)) = 2g(x) + 2 = 12 ⇒ g(x) = 5 ⇒ x² − 3x − 3 = 0 (D > 0). Köklərin cəmi 3.');
INSERT INTO public.questions VALUES (555, 10, 'g9-alg-func-q1-15', 1, 15, 'hard', 'single', 'f(x) = 3x + 1, g(x) = x² + 6x − 4. f(g(x)) = −3 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−6", "B": "−12", "C": "−5", "D": "−4/3", "E": "6"}'::jsonb, 'A', NULL, 'f(g(x)) = 3g(x) + 1 = −3 ⇒ g(x) = −4/3 ⇒ x² + 6x − 8/3 = 0 (D > 0). Köklərin cəmi −6.');
INSERT INTO public.questions VALUES (556, 10, 'g9-alg-func-q1-16', 1, 16, 'hard', 'single', 'y = √(8 − |x − 2|) / (x² − 9) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "17", "B": "16", "C": "13", "D": "14", "E": "15"}'::jsonb, 'E', NULL, '|x − 2| ≤ 8 ⇒ −6 ≤ x ≤ 10: 17 tam ədəd. x² ≠ 9 şərti çıxarır: −3, 3. Cavab: 15.');
INSERT INTO public.questions VALUES (557, 10, 'g9-alg-func-q1-17', 1, 17, 'hard', 'single', 'f(2x − 3) = x² − 3x − 3 olarsa, f(10) qiymətini tapın.', NULL, NULL, '{"A": "235", "B": "83/4", "C": "79/4", "D": "−5/4", "E": "67"}'::jsonb, 'C', NULL, '2x − 3 = 10 ⇒ x = 13/2. f(10) = 13/2² − 3·13/2 − 3 = 79/4.');
INSERT INTO public.questions VALUES (558, 10, 'g9-alg-func-q1-18', 1, 18, 'hard', 'single', 'f(4x − 4) = x² + 3x + 2 olarsa, f(3) qiymətini tapın.', NULL, NULL, '{"A": "90", "B": "20", "C": "21/16", "D": "181/16", "E": "165/16"}'::jsonb, 'E', NULL, '4x − 4 = 3 ⇒ x = 7/4. f(3) = 7/4² + 3·7/4 + 2 = 165/16.');
INSERT INTO public.questions VALUES (559, 10, 'g9-alg-func-q1-19', 1, 19, 'hard', 'single', 'f(x) = 2x + 5, g(x) = x² − 2x − 5. f(g(x)) = 6 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "3", "B": "−2", "C": "4", "D": "2", "E": "1/2"}'::jsonb, 'D', NULL, 'f(g(x)) = 2g(x) + 5 = 6 ⇒ g(x) = 1/2 ⇒ x² − 2x − 11/2 = 0 (D > 0). Köklərin cəmi 2.');
INSERT INTO public.questions VALUES (560, 10, 'g9-alg-func-q1-20', 1, 20, 'hard', 'single', 'f(4x − 1) = x² + 3x + 2 olarsa, f(−4) qiymətini tapın.', NULL, NULL, '{"A": "−3/16", "B": "5/16", "C": "240", "D": "21/16", "E": "6"}'::jsonb, 'B', NULL, '4x − 1 = −4 ⇒ x = −3/4. f(−4) = (−3/4)² + 3·(−3/4) + 2 = 5/16.');
INSERT INTO public.questions VALUES (561, 10, 'g9-alg-func-q2-01', 2, 1, 'hard', 'single', 'f(x) = x, g(x) = x² − 6x + 2. f(g(x)) = −5 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−6", "B": "6", "C": "12", "D": "7", "E": "−5"}'::jsonb, 'B', NULL, 'f(g(x)) = g(x) = −5 ⇒ g(x) = −5 ⇒ x² − 6x + 7 = 0 (D > 0). Köklərin cəmi 6.');
INSERT INTO public.questions VALUES (562, 10, 'g9-alg-func-q2-02', 2, 2, 'hard', 'single', 'y = √(10 − |x − 4|) / (x² − 4) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "21", "B": "19", "C": "20", "D": "17", "E": "18"}'::jsonb, 'B', NULL, '|x − 4| ≤ 10 ⇒ −6 ≤ x ≤ 14: 21 tam ədəd. x² ≠ 4 şərti çıxarır: −2, 2. Cavab: 19.');
INSERT INTO public.questions VALUES (563, 10, 'g9-alg-func-q2-03', 2, 3, 'hard', 'single', 'f(−2x − 3) = x² + x + 4 olarsa, f(9) qiymətini tapın.', NULL, NULL, '{"A": "424", "B": "94", "C": "35", "D": "10", "E": "34"}'::jsonb, 'E', NULL, '−2x − 3 = 9 ⇒ x = −6. f(9) = (−6)² + 1·(−6) + 4 = 34.');
INSERT INTO public.questions VALUES (564, 10, 'g9-alg-func-q2-04', 2, 4, 'hard', 'single', 'f(x) = 3x + 5, g(x) = x² − 4x + 5. f(g(x)) = 19 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−4", "B": "8", "C": "5", "D": "4", "E": "14/3"}'::jsonb, 'D', NULL, 'f(g(x)) = 3g(x) + 5 = 19 ⇒ g(x) = 14/3 ⇒ x² − 4x + 1/3 = 0 (D > 0). Köklərin cəmi 4.');
INSERT INTO public.questions VALUES (565, 10, 'g9-alg-func-q2-05', 2, 5, 'hard', 'single', 'y = x² − 8x − 4 parabolası ilə y = 5 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "10", "B": "9", "C": "8", "D": "11", "E": "25"}'::jsonb, 'A', NULL, 'x² − 8x − 9 = 0 ⇒ x₁ = −1, x₂ = 9; y = 5: y₁ = 5, y₂ = 5. Cavab: 10.');
INSERT INTO public.questions VALUES (566, 10, 'g9-alg-func-q2-06', 2, 6, 'hard', 'single', 'f(4x) = x² − 2x − 3 olarsa, f(1) qiymətini tapın.', NULL, NULL, '{"A": "−39/16", "B": "−55/16", "C": "−71/16", "D": "−4", "E": "5"}'::jsonb, 'B', NULL, '4x = 1 ⇒ x = 1/4. f(1) = 1/4² − 2·1/4 − 3 = −55/16.');
INSERT INTO public.questions VALUES (567, 10, 'g9-alg-func-q2-07', 2, 7, 'hard', 'open', 'y = x² + 8x − 8 parabolası ilə y = 4x + 4 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, NULL, NULL, '−8', 'x² + 4x − 12 = 0 ⇒ x₁ = −6, x₂ = 2; y = 4x + 4: y₁ = −20, y₂ = 12. Cavab: −8.');
INSERT INTO public.questions VALUES (568, 10, 'g9-alg-func-q2-08', 2, 8, 'hard', 'single', 'y = x² − 2x − 4 parabolası ilə y = 4x − 4 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "−80", "B": "20", "C": "15", "D": "16", "E": "6"}'::jsonb, 'D', NULL, 'x² − 6x = 0 ⇒ x₁ = 0, x₂ = 6; y = 4x − 4: y₁ = −4, y₂ = 20. Cavab: 16.');
INSERT INTO public.questions VALUES (569, 10, 'g9-alg-func-q2-09', 2, 9, 'hard', 'single', 'y = √(10 − |x + 1|) / (x² − 1) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "21", "B": "20", "C": "17", "D": "19", "E": "18"}'::jsonb, 'D', NULL, '|x + 1| ≤ 10 ⇒ −11 ≤ x ≤ 9: 21 tam ədəd. x² ≠ 1 şərti çıxarır: −1, 1. Cavab: 19.');
INSERT INTO public.questions VALUES (570, 10, 'g9-alg-func-q2-10', 2, 10, 'hard', 'single', 'f(−2x − 3) = x² − x olarsa, f(3) qiymətini tapın.', NULL, NULL, '{"A": "6", "B": "0", "C": "12", "D": "13", "E": "90"}'::jsonb, 'C', NULL, '−2x − 3 = 3 ⇒ x = −3. f(3) = (−3)² − 1·(−3) = 12.');
INSERT INTO public.questions VALUES (571, 10, 'g9-alg-func-q2-11', 2, 11, 'hard', 'single', 'f(x) = 2x − 4, g(x) = x² + x + 6. f(g(x)) = 18 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "11", "B": "0", "C": "−1", "D": "−2", "E": "1"}'::jsonb, 'C', NULL, 'f(g(x)) = 2g(x) − 4 = 18 ⇒ g(x) = 11 ⇒ x² + x − 5 = 0 (D > 0). Köklərin cəmi −1.');
INSERT INTO public.questions VALUES (572, 10, 'g9-alg-func-q2-12', 2, 12, 'hard', 'single', 'y = √(9 − |x + 3|) / (x² − 16) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "15", "B": "16", "C": "18", "D": "19", "E": "17"}'::jsonb, 'E', NULL, '|x + 3| ≤ 9 ⇒ −12 ≤ x ≤ 6: 19 tam ədəd. x² ≠ 16 şərti çıxarır: −4, 4. Cavab: 17.');
INSERT INTO public.questions VALUES (573, 10, 'g9-alg-func-q2-13', 2, 13, 'hard', 'single', 'f(x) = −x + 6, g(x) = x² − 3x − 3. f(g(x)) = 0 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−3", "B": "3", "C": "4", "D": "2", "E": "6"}'::jsonb, 'B', NULL, 'f(g(x)) = −g(x) + 6 = 0 ⇒ g(x) = 6 ⇒ x² − 3x − 9 = 0 (D > 0). Köklərin cəmi 3.');
INSERT INTO public.questions VALUES (574, 10, 'g9-alg-func-q2-14', 2, 14, 'hard', 'open', 'f(4x − 2) = x² − 4x − 4 olarsa, f(−5) qiymətini tapın.', NULL, NULL, NULL, NULL, '−7/16', '4x − 2 = −5 ⇒ x = −3/4. f(−5) = (−3/4)² − 4·(−3/4) − 4 = −7/16.');
INSERT INTO public.questions VALUES (575, 10, 'g9-alg-func-q2-15', 2, 15, 'hard', 'single', 'y = √(9 − |x + 1|) / (x² − 9) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "18", "B": "15", "C": "16", "D": "19", "E": "17"}'::jsonb, 'E', NULL, '|x + 1| ≤ 9 ⇒ −10 ≤ x ≤ 8: 19 tam ədəd. x² ≠ 9 şərti çıxarır: −3, 3. Cavab: 17.');
INSERT INTO public.questions VALUES (576, 10, 'g9-alg-func-q2-16', 2, 16, 'hard', 'single', 'y = x² + 8x + 5 parabolası ilə y = 2x düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−6", "B": "5", "C": "4", "D": "7", "E": "−5"}'::jsonb, 'B', NULL, 'x² + 6x + 5 = 0 ⇒ x₁ = −5, x₂ = −1; y = 2x: y₁ = −10, y₂ = −2. Cavab: 5.');
INSERT INTO public.questions VALUES (577, 10, 'g9-alg-func-q2-17', 2, 17, 'hard', 'single', 'f(2x + 2) = x² + 2x + 4 olarsa, f(−6) qiymətini tapın.', NULL, NULL, '{"A": "13", "B": "84", "C": "28", "D": "4", "E": "12"}'::jsonb, 'E', NULL, '2x + 2 = −6 ⇒ x = −4. f(−6) = (−4)² + 2·(−4) + 4 = 12.');
INSERT INTO public.questions VALUES (578, 10, 'g9-alg-func-q2-18', 2, 18, 'hard', 'single', 'y = √(4 − |x − 5|) / (x² − 1) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "10", "B": "6", "C": "8", "D": "9", "E": "7"}'::jsonb, 'C', NULL, '|x − 5| ≤ 4 ⇒ 1 ≤ x ≤ 9: 9 tam ədəd. x² ≠ 1 şərti çıxarır: 1. Cavab: 8.');
INSERT INTO public.questions VALUES (579, 10, 'g9-alg-func-q2-19', 2, 19, 'hard', 'single', 'y = x² + 5x − 7 parabolası ilə y = −5x − 7 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "31", "B": "36", "C": "−10", "D": "−301", "E": "35"}'::jsonb, 'B', NULL, 'x² + 10x = 0 ⇒ x₁ = −10, x₂ = 0; y = −5x − 7: y₁ = 43, y₂ = −7. Cavab: 36.');
INSERT INTO public.questions VALUES (580, 10, 'g9-alg-func-q2-20', 2, 20, 'hard', 'single', 'f(x) = −x + 3, g(x) = x² + x − 7. f(g(x)) = 8 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "1", "B": "−5", "C": "−2", "D": "0", "E": "−1"}'::jsonb, 'E', NULL, 'f(g(x)) = −g(x) + 3 = 8 ⇒ g(x) = −5 ⇒ x² + x − 2 = 0 (D > 0). Köklərin cəmi −1.');
INSERT INTO public.questions VALUES (581, 10, 'g9-alg-func-q3-01', 3, 1, 'hard', 'single', 'f(−2x − 1) = x² + 3x − 5 olarsa, f(0) qiymətini tapın.', NULL, NULL, '{"A": "−7", "B": "−5", "C": "−21/4", "D": "−13/4", "E": "−25/4"}'::jsonb, 'E', NULL, '−2x − 1 = 0 ⇒ x = −1/2. f(0) = (−1/2)² + 3·(−1/2) − 5 = −25/4.');
INSERT INTO public.questions VALUES (582, 10, 'g9-alg-func-q3-02', 3, 2, 'hard', 'single', 'f(x) = 3x + 6, g(x) = x² − 5x − 6. f(g(x)) = 17 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "10", "B": "−5", "C": "5", "D": "11/3", "E": "6"}'::jsonb, 'C', NULL, 'f(g(x)) = 3g(x) + 6 = 17 ⇒ g(x) = 11/3 ⇒ x² − 5x − 29/3 = 0 (D > 0). Köklərin cəmi 5.');
INSERT INTO public.questions VALUES (583, 10, 'g9-alg-func-q3-03', 3, 3, 'hard', 'single', 'y = √(9 − |x + 4|) / (x² − 2) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "20", "B": "19", "C": "17", "D": "18", "E": "21"}'::jsonb, 'B', NULL, '|x + 4| ≤ 9 ⇒ −13 ≤ x ≤ 5: 19 tam ədəd. x² ≠ 2 şərti bu aralıqda heç nə çıxarmır. Cavab: 19.');
INSERT INTO public.questions VALUES (584, 10, 'g9-alg-func-q3-04', 3, 4, 'hard', 'single', 'y = x² − 4x − 9 parabolası ilə y = −4 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "−7", "B": "16", "C": "4", "D": "−8", "E": "−9"}'::jsonb, 'D', NULL, 'x² − 4x − 5 = 0 ⇒ x₁ = −1, x₂ = 5; y = −4: y₁ = −4, y₂ = −4. Cavab: −8.');
INSERT INTO public.questions VALUES (585, 10, 'g9-alg-func-q3-05', 3, 5, 'hard', 'single', 'f(2x + 4) = x² + 4x − 1 olarsa, f(6) qiymətini tapın.', NULL, NULL, '{"A": "319", "B": "44", "C": "59", "D": "4", "E": "5"}'::jsonb, 'D', NULL, '2x + 4 = 6 ⇒ x = 1. f(6) = 1² + 4·1 − 1 = 4.');
INSERT INTO public.questions VALUES (586, 10, 'g9-alg-func-q3-06', 3, 6, 'hard', 'single', 'y = √(4 − |x − 2|) / (x² − 3) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "10", "B": "7", "C": "9", "D": "11", "E": "8"}'::jsonb, 'C', NULL, '|x − 2| ≤ 4 ⇒ −2 ≤ x ≤ 6: 9 tam ədəd. x² ≠ 3 şərti bu aralıqda heç nə çıxarmır. Cavab: 9.');
INSERT INTO public.questions VALUES (587, 10, 'g9-alg-func-q3-07', 3, 7, 'hard', 'open', 'f(x) = 2x − 5, g(x) = x² − 5x − 4. f(g(x)) = 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '5', 'f(g(x)) = 2g(x) − 5 = 1 ⇒ g(x) = 3 ⇒ x² − 5x − 7 = 0 (D > 0). Köklərin cəmi 5.');
INSERT INTO public.questions VALUES (588, 10, 'g9-alg-func-q3-08', 3, 8, 'hard', 'single', 'y = x² − 3x + 1 parabolası ilə y = 4x − 5 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "10", "B": "−6", "C": "7", "D": "6", "E": "5"}'::jsonb, 'D', NULL, 'x² − 7x + 6 = 0 ⇒ x₁ = 1, x₂ = 6; y = 4x − 5: y₁ = −1, y₂ = 19. Cavab: 6.');
INSERT INTO public.questions VALUES (589, 10, 'g9-alg-func-q3-09', 3, 9, 'hard', 'single', 'f(x) = 3x − 5, g(x) = x² − x − 7. f(g(x)) = −1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "4/3", "B": "−1", "C": "2", "D": "1", "E": "0"}'::jsonb, 'D', NULL, 'f(g(x)) = 3g(x) − 5 = −1 ⇒ g(x) = 4/3 ⇒ x² − x − 25/3 = 0 (D > 0). Köklərin cəmi 1.');
INSERT INTO public.questions VALUES (590, 10, 'g9-alg-func-q3-10', 3, 10, 'hard', 'single', 'y = x² + 4x + 8 parabolası ilə y = −3x + 2 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "25", "B": "−7", "C": "24", "D": "100", "E": "22"}'::jsonb, 'A', NULL, 'x² + 7x + 6 = 0 ⇒ x₁ = −6, x₂ = −1; y = −3x + 2: y₁ = 20, y₂ = 5. Cavab: 25.');
INSERT INTO public.questions VALUES (591, 10, 'g9-alg-func-q3-11', 3, 11, 'hard', 'single', 'f(4x + 5) = x² + 4x + 1 olarsa, f(−8) qiymətini tapın.', NULL, NULL, '{"A": "−39/16", "B": "33", "C": "−23/16", "D": "−7/16", "E": "622"}'::jsonb, 'C', NULL, '4x + 5 = −8 ⇒ x = −13/4. f(−8) = (−13/4)² + 4·(−13/4) + 1 = −23/16.');
INSERT INTO public.questions VALUES (592, 10, 'g9-alg-func-q3-12', 3, 12, 'hard', 'single', 'y = √(4 − |x − 2|) / (x² − 2) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "7", "B": "11", "C": "9", "D": "10", "E": "8"}'::jsonb, 'C', NULL, '|x − 2| ≤ 4 ⇒ −2 ≤ x ≤ 6: 9 tam ədəd. x² ≠ 2 şərti bu aralıqda heç nə çıxarmır. Cavab: 9.');
INSERT INTO public.questions VALUES (593, 10, 'g9-alg-func-q3-13', 3, 13, 'hard', 'single', 'f(x) = 2x + 2, g(x) = x² + 3x − 6. f(g(x)) = 2 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−6", "B": "−3", "C": "−2", "D": "0", "E": "3"}'::jsonb, 'B', NULL, 'f(g(x)) = 2g(x) + 2 = 2 ⇒ g(x) = 0 ⇒ x² + 3x − 6 = 0 (D > 0). Köklərin cəmi −3.');
INSERT INTO public.questions VALUES (594, 10, 'g9-alg-func-q3-14', 3, 14, 'hard', 'open', 'f(x) = −x + 3, g(x) = x² − 6x − 9. f(g(x)) = 5 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '6', 'f(g(x)) = −g(x) + 3 = 5 ⇒ g(x) = −2 ⇒ x² − 6x − 7 = 0 (D > 0). Köklərin cəmi 6.');
INSERT INTO public.questions VALUES (595, 10, 'g9-alg-func-q3-15', 3, 15, 'hard', 'single', 'y = √(8 − |x + 5|) / (x² − 4) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "14", "B": "15", "C": "16", "D": "17", "E": "13"}'::jsonb, 'B', NULL, '|x + 5| ≤ 8 ⇒ −13 ≤ x ≤ 3: 17 tam ədəd. x² ≠ 4 şərti çıxarır: −2, 2. Cavab: 15.');
INSERT INTO public.questions VALUES (596, 10, 'g9-alg-func-q3-16', 3, 16, 'hard', 'single', 'f(2x − 2) = x² + 4x − 2 olarsa, f(−7) qiymətini tapın.', NULL, NULL, '{"A": "190", "B": "19", "C": "1/4", "D": "−23/4", "E": "−19/4"}'::jsonb, 'D', NULL, '2x − 2 = −7 ⇒ x = −5/2. f(−7) = (−5/2)² + 4·(−5/2) − 2 = −23/4.');
INSERT INTO public.questions VALUES (597, 10, 'g9-alg-func-q3-17', 3, 17, 'hard', 'single', 'y = x² + 4x parabolası ilə y = 2x + 8 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "14", "B": "12", "C": "0", "D": "11", "E": "−2"}'::jsonb, 'B', NULL, 'x² + 2x − 8 = 0 ⇒ x₁ = −4, x₂ = 2; y = 2x + 8: y₁ = 0, y₂ = 12. Cavab: 12.');
INSERT INTO public.questions VALUES (598, 10, 'g9-alg-func-q3-18', 3, 18, 'hard', 'single', 'y = x² − 8x parabolası ilə y = −5x düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, '{"A": "−15", "B": "−20", "C": "−16", "D": "3", "E": "0"}'::jsonb, 'A', NULL, 'x² − 3x = 0 ⇒ x₁ = 0, x₂ = 3; y = −5x: y₁ = 0, y₂ = −15. Cavab: −15.');
INSERT INTO public.questions VALUES (599, 10, 'g9-alg-func-q3-19', 3, 19, 'hard', 'single', 'f(3x − 3) = x² − 3x + 5 olarsa, f(−8) qiymətini tapın.', NULL, NULL, '{"A": "93", "B": "124/9", "C": "265/9", "D": "815", "E": "115/9"}'::jsonb, 'E', NULL, '3x − 3 = −8 ⇒ x = −5/3. f(−8) = (−5/3)² − 3·(−5/3) + 5 = 115/9.');
INSERT INTO public.questions VALUES (600, 10, 'g9-alg-func-q3-20', 3, 20, 'hard', 'single', 'y = √(5 − |x − 3|) / (x² − 1) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "7", "B": "10", "C": "9", "D": "8", "E": "11"}'::jsonb, 'C', NULL, '|x − 3| ≤ 5 ⇒ −2 ≤ x ≤ 8: 11 tam ədəd. x² ≠ 1 şərti çıxarır: −1, 1. Cavab: 9.');
INSERT INTO public.questions VALUES (601, 11, 'g9-geo-basic-q1-01', 1, 1, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 38°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 107.7,186.0 212.3,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="98.3" y="200.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="221.7" y="200.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="107.7" y1="186.0" x2="190.1" y2="121.6" stroke-dasharray="5 4"/><text x="200.4" y="118.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "39°", "B": "33°", "C": "71°", "D": "38°", "E": "52°"}'::jsonb, 'B', NULL, '∠B = ∠C = (180° − 38°)/2 = 71°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·71° = 38°. ∠ABD = 71° − 38° = 33°.');
INSERT INTO public.questions VALUES (602, 11, 'g9-geo-basic-q1-02', 1, 2, 'hard', 'single', 'ABC üçbucağında AB = 11, AC = 14, BC = 6. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,166.5 251.0,166.5 286.0,53.5"/><text x="21.4" y="174.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="262.1" y="178.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.2" y="50.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="133.1" y="179.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="149.8" y="108.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="280.2" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="166.5" x2="266.4" y2="116.8" stroke-dasharray="5 4"/><text x="279.1" y="119.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "33/7", "B": "3", "C": "84/25", "D": "121/25", "E": "66/25"}'::jsonb, 'E', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 11 : 14. BD = 6·11/(11 + 14) = 66/25.');
INSERT INTO public.questions VALUES (603, 11, 'g9-geo-basic-q1-03', 1, 3, 'hard', 'single', 'ABC üçbucağında ∠A = 34°, ∠B = 52°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,165.7 286.0,165.7 199.0,54.3"/><text x="21.4" y="174.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="174.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="203.3" y="47.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="199.0" y1="54.3" x2="199.0" y2="165.7" stroke-dasharray="5 4"/><line x1="199.0" y1="54.3" x2="181.4" y2="165.7" stroke-dasharray="5 4"/><polyline points="209.0,165.7 209.0,155.7 199.0,155.7" stroke-width="1.2"/><text x="199.0" y="183.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="179.4" y="183.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "14°", "B": "47°", "C": "18°", "D": "43/2°", "E": "9°"}'::jsonb, 'E', NULL, '∠C = 94°, ∠ACL = 47°. ∠ACH = 90° − ∠A = 56°. Aradakı bucaq |47° − (56°)| = |∠A − ∠B|/2 = 9°.');
INSERT INTO public.questions VALUES (604, 11, 'g9-geo-basic-q1-04', 1, 4, 'hard', 'single', 'ABC üçbucağında AB = 30, AC = 5, BC = 29. Ən böyük tərəfə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,130.2 286.0,130.2 45.8,89.8"/><text x="21.1" y="137.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="299.0" y="136.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="33.5" y="90.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="171.3" y="139.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="27.9" y="114.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="177.7" y="113.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">29</text><line x1="45.8" y1="89.8" x2="45.8" y2="130.2" stroke-dasharray="5 4"/></svg>', '{"A": "144/5", "B": "12/5", "C": "144/29", "D": "24/5", "E": "29/5"}'::jsonb, 'D', NULL, 'p = 32, S = √(p(p − a)(p − b)(p − c)) = 72. h = 2S/30 = 24/5.');
INSERT INTO public.questions VALUES (605, 11, 'g9-geo-basic-q1-05', 1, 5, 'hard', 'single', 'ABC üçbucağında ∠A = 36°, ∠B = 96°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="55.4,186.0 248.6,186.0 264.6,34.0"/><text x="43.2" y="195.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="258.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="272.3" y="28.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="55.4" y1="186.0" x2="204.9" y2="137.4" stroke-dasharray="5 4"/><line x1="248.6" y1="186.0" x2="204.9" y2="137.4" stroke-dasharray="5 4"/><circle cx="204.9" cy="137.4" r="2.6" fill="currentColor"/><text x="198.4" y="153.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "156°", "B": "108°", "C": "132°", "D": "66°", "E": "114°"}'::jsonb, 'E', NULL, '∠C = 180° − 36° − 96° = 48°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 114°.');
INSERT INTO public.questions VALUES (606, 11, 'g9-geo-basic-q1-06', 1, 6, 'hard', 'single', 'ABC üçbucağında AB = 19, AC = 14, BC = 12. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,168.5 286.0,168.5 178.1,51.5"/><text x="21.5" y="177.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="177.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="180.1" y="43.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.2" y="185.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><text x="94.7" y="111.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="243.6" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="34.0" y1="168.5" x2="223.9" y2="101.1" stroke-dasharray="5 4"/><text x="236.2" y="101.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "56/11", "B": "76/11", "C": "114/7", "D": "6", "E": "361/33"}'::jsonb, 'B', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 19 : 14. BD = 12·19/(19 + 14) = 76/11.');
INSERT INTO public.questions VALUES (607, 11, 'g9-geo-basic-q1-07', 1, 7, 'hard', 'open', 'ABC üçbucağında AB = 9, AC = 12, BC = 6. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,179.7 250.0,179.7 286.0,40.3"/><text x="21.5" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="260.3" y="192.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="295.3" y="36.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="133.4" y="193.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="150.5" y="107.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="279.5" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="179.7" x2="265.4" y2="120.0" stroke-dasharray="5 4"/><text x="278.0" y="121.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', NULL, NULL, '18/7', 'Tənbölən xassəsi: BD : DC = AB : AC = 9 : 12. BD = 6·9/(9 + 12) = 18/7.');
INSERT INTO public.questions VALUES (608, 11, 'g9-geo-basic-q1-08', 1, 8, 'hard', 'single', 'ABC üçbucağında AB = 25, AC = 7, BC = 24. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,143.9 286.0,143.9 53.8,76.1"/><text x="21.4" y="152.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="150.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="42.8" y="74.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="170.1" y="155.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="32.0" y="113.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="181.5" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><circle cx="74.3" cy="113.6" r="30.2"/></svg>', '{"A": "3/2", "B": "4", "C": "25/2", "D": "3", "E": "6"}'::jsonb, 'D', NULL, 'p = 28, S = √(p(p − a)(p − b)(p − c)) = 84. r = S/p = 84/28 = 3.');
INSERT INTO public.questions VALUES (609, 11, 'g9-geo-basic-q1-09', 1, 9, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 7 və HB = 13 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,170.1 286.0,170.1 122.2,49.9"/><line x1="122.2" y1="49.9" x2="122.2" y2="170.1" stroke-dasharray="5 4"/><polyline points="132.2,170.1 132.2,160.1 122.2,160.1" stroke-width="1.2"/><polyline points="116.3,58.0 124.3,63.9 130.3,55.8" stroke-width="1.2"/><text x="21.7" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="178.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="118.3" y="42.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.2" y="188.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="74.0" y="186.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="210.9" y="185.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text></svg>', '{"A": "3√39", "B": "2√35", "C": "√91", "D": "2√65", "E": "√218"}'::jsonb, 'B', NULL, 'AC² = AH·AB = 7·20 = 140 ⇒ AC = 2√35.');
INSERT INTO public.questions VALUES (610, 11, 'g9-geo-basic-q1-10', 1, 10, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 8°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 149.4,186.0 170.6,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="146.7" y="203.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="173.3" y="203.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="149.4" y1="186.0" x2="170.4" y2="183.0" stroke-dasharray="5 4"/><text x="183.3" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "82°", "B": "84°", "C": "78°", "D": "8°", "E": "86°"}'::jsonb, 'C', NULL, '∠B = ∠C = (180° − 8°)/2 = 86°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·86° = 8°. ∠ABD = 86° − 8° = 78°.');
INSERT INTO public.questions VALUES (611, 11, 'g9-geo-basic-q1-11', 1, 11, 'hard', 'single', 'ABC üçbucağında AB = 6, AC = 8, BC = 10. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="103.0,186.0 217.0,186.0 103.0,34.0"/><text x="95.2" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="227.8" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="98.4" y="26.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="164.2" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="93.0" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="167.2" y="105.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><circle cx="141.0" cy="148.0" r="38.0"/></svg>', '{"A": "5", "B": "2", "C": "1", "D": "4", "E": "3"}'::jsonb, 'B', NULL, 'p = 12, S = √(p(p − a)(p − b)(p − c)) = 24. r = S/p = 24/12 = 2.');
INSERT INTO public.questions VALUES (612, 11, 'g9-geo-basic-q1-12', 1, 12, 'hard', 'single', 'ABC üçbucağında AB = 14, AC = 15, BC = 13. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="71.3,186.0 248.7,186.0 185.3,34.0"/><text x="59.8" y="197.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="259.7" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.5" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.0" y="202.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="118.2" y="108.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="227.6" y="109.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><circle cx="172.7" cy="135.3" r="50.7"/></svg>', '{"A": "65/8", "B": "2", "C": "4", "D": "5", "E": "8"}'::jsonb, 'C', NULL, 'p = 21, S = √(p(p − a)(p − b)(p − c)) = 84. r = S/p = 84/21 = 4.');
INSERT INTO public.questions VALUES (613, 11, 'g9-geo-basic-q1-13', 1, 13, 'hard', 'single', 'ABC üçbucağında AB = 18, AC = 7, BC = 17. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,156.2 286.0,156.2 66.7,63.8"/><text x="21.6" y="165.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="163.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="57.4" y="59.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.5" y="169.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="38.6" y="112.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="187.7" y="111.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="34.0" y1="156.2" x2="128.1" y2="89.7" stroke-dasharray="5 4"/><text x="138.7" y="87.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "324/25", "B": "306/25", "C": "306/7", "D": "119/25", "E": "17/2"}'::jsonb, 'B', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 18 : 7. BD = 17·18/(18 + 7) = 306/25.');
INSERT INTO public.questions VALUES (614, 11, 'g9-geo-basic-q1-14', 1, 14, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 3 və HB = 13 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,159.2 286.0,159.2 81.2,60.8"/><line x1="81.2" y1="60.8" x2="81.2" y2="159.2" stroke-dasharray="5 4"/><polyline points="91.2,159.2 91.2,149.2 81.2,149.2" stroke-width="1.2"/><polyline points="76.9,69.8 85.9,74.2 90.3,65.2" stroke-width="1.2"/><text x="21.6" y="168.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="166.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="73.1" y="55.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="81.2" y="177.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="54.8" y="175.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="192.3" y="172.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text></svg>', '{"A": "8√39", "B": "3√39/2", "C": "32√3", "D": "16√39", "E": "4√39"}'::jsonb, 'A', NULL, 'CH = √(AH·HB) = √39. S = AB·CH/2 = 16·√39/2 = 8√39.');
INSERT INTO public.questions VALUES (615, 11, 'g9-geo-basic-q1-15', 1, 15, 'hard', 'single', 'ABC üçbucağında ∠A = 90°, ∠B = 38°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="62.7,186.0 257.3,186.0 62.7,34.0"/><text x="52.5" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="269.4" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="55.7" y="28.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="62.7" y1="34.0" x2="62.7" y2="186.0" stroke-dasharray="5 4"/><line x1="62.7" y1="34.0" x2="136.9" y2="186.0" stroke-dasharray="5 4"/><polyline points="72.7,186.0 72.7,176.0 62.7,176.0" stroke-width="1.2"/><text x="62.7" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="142.6" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "32°", "B": "21°", "C": "26°", "D": "52°", "E": "31°"}'::jsonb, 'C', NULL, '∠C = 52°, ∠ACL = 26°. ∠ACH = 90° − ∠A = 0°. Aradakı bucaq |26° − (0°)| = |∠A − ∠B|/2 = 26°.');
INSERT INTO public.questions VALUES (616, 11, 'g9-geo-basic-q1-16', 1, 16, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 9 və HB = 5 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,170.4 286.0,170.4 196.0,49.6"/><line x1="196.0" y1="49.6" x2="196.0" y2="170.4" stroke-dasharray="5 4"/><polyline points="206.0,170.4 206.0,160.4 196.0,160.4" stroke-width="1.2"/><polyline points="188.0,55.6 194.0,63.6 202.0,57.6" stroke-width="1.2"/><text x="21.5" y="179.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="179.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="199.7" y="42.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="196.0" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="108.3" y="185.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="245.2" y="186.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text></svg>', '{"A": "27√5/2", "B": "42√5", "C": "21√5", "D": "21√14", "E": "21√5/2"}'::jsonb, 'C', NULL, 'CH = √(AH·HB) = 3√5. S = AB·CH/2 = 14·3√5/2 = 21√5.');
INSERT INTO public.questions VALUES (617, 11, 'g9-geo-basic-q1-17', 1, 17, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 15 və HB = 16 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 155.9,47.0"/><line x1="155.9" y1="47.0" x2="155.9" y2="173.0" stroke-dasharray="5 4"/><polyline points="165.9,173.0 165.9,163.0 155.9,163.0" stroke-width="1.2"/><polyline points="149.0,54.2 156.2,61.2 163.1,54.0" stroke-width="1.2"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="155.5" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="155.9" y="191.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="89.7" y="188.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="226.5" y="188.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text></svg>', '{"A": "√481", "B": "4√31", "C": "4√46", "D": "√465", "E": "4√15"}'::jsonb, 'D', NULL, 'AC² = AH·AB = 15·31 = 465 ⇒ AC = √465.');
INSERT INTO public.questions VALUES (618, 11, 'g9-geo-basic-q1-18', 1, 18, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 10°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 146.7,186.0 173.3,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="143.4" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="176.6" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="146.7" y1="186.0" x2="172.9" y2="181.4" stroke-dasharray="5 4"/><text x="185.7" y="184.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "10°", "B": "85°", "C": "80°", "D": "81°", "E": "75°"}'::jsonb, 'E', NULL, '∠B = ∠C = (180° − 10°)/2 = 85°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·85° = 10°. ∠ABD = 85° − 10° = 75°.');
INSERT INTO public.questions VALUES (619, 11, 'g9-geo-basic-q1-19', 1, 19, 'hard', 'single', 'ABC üçbucağında ∠A = 98°, ∠B = 42°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="97.0,186.0 244.4,186.0 75.6,34.0"/><text x="88.7" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="256.1" y="196.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="68.7" y="28.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="75.6" y1="34.0" x2="75.6" y2="186.0" stroke-dasharray="5 4"/><line x1="75.6" y1="34.0" x2="156.4" y2="186.0" stroke-dasharray="5 4"/><polyline points="85.6,186.0 85.6,176.0 75.6,176.0" stroke-width="1.2"/><text x="75.6" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="162.5" y="202.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "56°", "B": "33°", "C": "35°", "D": "20°", "E": "28°"}'::jsonb, 'E', NULL, '∠C = 40°, ∠ACL = 20°. ∠ACH = 90° − ∠A = -8°. Aradakı bucaq |20° − (-8°)| = |∠A − ∠B|/2 = 28°.');
INSERT INTO public.questions VALUES (620, 11, 'g9-geo-basic-q1-20', 1, 20, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 15 və HB = 13 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.8 286.0,172.8 169.0,47.2"/><line x1="169.0" y1="47.2" x2="169.0" y2="172.8" stroke-dasharray="5 4"/><polyline points="179.0,172.8 179.0,162.8 169.0,162.8" stroke-width="1.2"/><polyline points="161.7,54.0 168.5,61.3 175.8,54.5" stroke-width="1.2"/><text x="21.6" y="181.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="169.9" y="39.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="169.0" y="190.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="95.8" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="232.6" y="188.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text></svg>', '{"A": "14", "B": "2√91", "C": "2√105", "D": "√394", "E": "√195"}'::jsonb, 'E', NULL, 'CH² = AH·HB = 15·13 = 195 ⇒ CH = √195.');
INSERT INTO public.questions VALUES (621, 11, 'g9-geo-basic-q2-01', 2, 1, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 20, BC = 17. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="101.4,186.0 218.6,186.0 198.5,34.0"/><text x="90.8" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="227.3" y="200.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="201.7" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="157.1" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="141.9" y="106.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="218.4" y="108.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="101.4" y1="186.0" x2="210.7" y2="126.1" stroke-dasharray="5 4"/><text x="222.1" y="124.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "17/2", "B": "340/33", "C": "221/33", "D": "169/33", "E": "221/20"}'::jsonb, 'C', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 13 : 20. BD = 17·13/(13 + 20) = 221/33.');
INSERT INTO public.questions VALUES (622, 11, 'g9-geo-basic-q2-02', 2, 2, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 9, BC = 19. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,163.5 286.0,163.5 71.8,56.5"/><text x="21.8" y="173.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="171.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="63.5" y="51.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="167.6" y="177.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="41.2" y="112.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="190.2" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><line x1="34.0" y1="163.5" x2="138.3" y2="89.7" stroke-dasharray="5 4"/><text x="148.9" y="87.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "171/29", "B": "400/29", "C": "380/9", "D": "380/29", "E": "19/2"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 20 : 9. BD = 19·20/(20 + 9) = 380/29.');
INSERT INTO public.questions VALUES (623, 11, 'g9-geo-basic-q2-03', 2, 3, 'hard', 'single', 'ABC üçbucağında ∠A = 46°, ∠B = 50°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,179.8 286.0,179.8 168.8,40.2"/><text x="21.8" y="189.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.2" y="189.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="169.7" y="32.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="168.8" y1="40.2" x2="168.8" y2="179.8" stroke-dasharray="5 4"/><line x1="168.8" y1="40.2" x2="164.0" y2="179.8" stroke-dasharray="5 4"/><polyline points="178.8,179.8 178.8,169.8 168.8,169.8" stroke-width="1.2"/><text x="168.8" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="163.5" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "2°", "B": "24°", "C": "4°", "D": "42°", "E": "7°"}'::jsonb, 'A', NULL, '∠C = 84°, ∠ACL = 42°. ∠ACH = 90° − ∠A = 44°. Aradakı bucaq |42° − (44°)| = |∠A − ∠B|/2 = 2°.');
INSERT INTO public.questions VALUES (624, 11, 'g9-geo-basic-q2-04', 2, 4, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 8 və HB = 7 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.9 286.0,172.9 168.4,47.1"/><line x1="168.4" y1="47.1" x2="168.4" y2="172.9" stroke-dasharray="5 4"/><polyline points="178.4,172.9 178.4,162.9 168.4,162.9" stroke-width="1.2"/><polyline points="161.1,54.0 167.9,61.3 175.2,54.4" stroke-width="1.2"/><text x="21.6" y="181.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="169.3" y="39.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.4" y="190.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="95.5" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="232.3" y="188.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "√113", "B": "15/2", "C": "2√30", "D": "√105", "E": "2√14"}'::jsonb, 'E', NULL, 'CH² = AH·HB = 8·7 = 56 ⇒ CH = 2√14.');
INSERT INTO public.questions VALUES (625, 11, 'g9-geo-basic-q2-05', 2, 5, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 14 və HB = 8 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,170.6 286.0,170.6 194.4,49.4"/><line x1="194.4" y1="49.4" x2="194.4" y2="170.6" stroke-dasharray="5 4"/><polyline points="204.4,170.6 204.4,160.6 194.4,160.6" stroke-width="1.2"/><polyline points="186.4,55.4 192.4,63.4 200.4,57.4" stroke-width="1.2"/><text x="21.5" y="179.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="179.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.9" y="41.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="194.4" y="188.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="107.6" y="185.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="244.4" y="186.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "11", "B": "4√7", "C": "2√77", "D": "4√11", "E": "2√65"}'::jsonb, 'B', NULL, 'CH² = AH·HB = 14·8 = 112 ⇒ CH = 4√7.');
INSERT INTO public.questions VALUES (626, 11, 'g9-geo-basic-q2-06', 2, 6, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 16, BC = 10. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="58.7,186.0 217.0,186.0 261.3,34.0"/><text x="46.7" y="196.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="224.8" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="269.5" y="28.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="130.3" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="152.8" y="105.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="250.2" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><circle cx="185.3" cy="143.8" r="42.2"/></svg>', '{"A": "4/3", "B": "11/3", "C": "25/3", "D": "16/3", "E": "8/3"}'::jsonb, 'E', NULL, 'p = 18, S = √(p(p − a)(p − b)(p − c)) = 48. r = S/p = 48/18 = 8/3.');
INSERT INTO public.questions VALUES (627, 11, 'g9-geo-basic-q2-07', 2, 7, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 4 və HB = 7 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,170.6 286.0,170.6 125.6,49.4"/><line x1="125.6" y1="49.4" x2="125.6" y2="170.6" stroke-dasharray="5 4"/><polyline points="135.6,170.6 135.6,160.6 125.6,160.6" stroke-width="1.2"/><polyline points="119.6,57.4 127.6,63.4 133.6,55.4" stroke-width="1.2"/><text x="21.7" y="179.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="179.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="122.1" y="41.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="125.6" y="188.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="75.6" y="186.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="212.4" y="185.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "2√7", "B": "√105", "C": "2√11", "D": "√77", "E": "√65"}'::jsonb, 'C', NULL, 'AC² = AH·AB = 4·11 = 44 ⇒ AC = 2√11.');
INSERT INTO public.questions VALUES (628, 11, 'g9-geo-basic-q2-08', 2, 8, 'hard', 'single', 'ABC üçbucağında AB = 26, AC = 20, BC = 26. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="53.0,186.0 267.0,186.0 116.3,34.0"/><text x="41.6" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="279.0" y="196.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="112.7" y="26.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="163.3" y="202.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">26</text><text x="73.6" y="110.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="202.2" y="109.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">26</text><circle cx="135.3" cy="131.1" r="54.9"/></svg>', '{"A": "23/3", "B": "20/3", "C": "10/3", "D": "40/3", "E": "169/12"}'::jsonb, 'B', NULL, 'p = 36, S = √(p(p − a)(p − b)(p − c)) = 240. r = S/p = 240/36 = 20/3.');
INSERT INTO public.questions VALUES (629, 11, 'g9-geo-basic-q2-09', 2, 9, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 11, BC = 4. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,140.6 286.0,140.6 238.3,79.4"/><text x="21.1" y="147.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="148.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="248.5" y="76.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="150.5" y="152.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="124.4" y="112.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="274.0" y="113.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><line x1="34.0" y1="140.6" x2="260.2" y2="107.5" stroke-dasharray="5 4"/><text x="273.0" y="110.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "169/24", "B": "52/11", "C": "13/6", "D": "11/6", "E": "2"}'::jsonb, 'C', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 13 : 11. BD = 4·13/(13 + 11) = 13/6.');
INSERT INTO public.questions VALUES (630, 11, 'g9-geo-basic-q2-10', 2, 10, 'hard', 'single', 'ABC üçbucağında ∠A = 92°, ∠B = 64°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="128.2,186.0 197.1,186.0 122.9,34.0"/><text x="123.2" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="206.0" y="200.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="119.6" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="122.9" y1="34.0" x2="122.9" y2="186.0" stroke-dasharray="5 4"/><line x1="122.9" y1="34.0" x2="160.8" y2="186.0" stroke-dasharray="5 4"/><polyline points="132.9,186.0 132.9,176.0 122.9,176.0" stroke-width="1.2"/><text x="122.9" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="164.0" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "39°", "B": "12°", "C": "14°", "D": "19°", "E": "28°"}'::jsonb, 'C', NULL, '∠C = 24°, ∠ACL = 12°. ∠ACH = 90° − ∠A = -2°. Aradakı bucaq |12° − (-2°)| = |∠A − ∠B|/2 = 14°.');
INSERT INTO public.questions VALUES (631, 11, 'g9-geo-basic-q2-11', 2, 11, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 20°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 133.2,186.0 186.8,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="127.1" y="202.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="192.9" y="202.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="133.2" y1="186.0" x2="183.6" y2="167.7" stroke-dasharray="5 4"/><text x="195.8" y="168.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "66°", "B": "60°", "C": "80°", "D": "20°", "E": "70°"}'::jsonb, 'B', NULL, '∠B = ∠C = (180° − 20°)/2 = 80°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·80° = 20°. ∠ABD = 80° − 20° = 60°.');
INSERT INTO public.questions VALUES (632, 11, 'g9-geo-basic-q2-12', 2, 12, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 4 və HB = 12 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 97.0,55.4"/><line x1="97.0" y1="55.4" x2="97.0" y2="164.6" stroke-dasharray="5 4"/><polyline points="107.0,164.6 107.0,154.6 97.0,154.6" stroke-width="1.2"/><polyline points="92.0,64.1 100.7,69.1 105.7,60.4" stroke-width="1.2"/><text x="21.7" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="90.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="97.0" y="182.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="62.2" y="181.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="199.4" y="178.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "64√3", "B": "16√3", "C": "32√3", "D": "8√3", "E": "64"}'::jsonb, 'C', NULL, 'CH = √(AH·HB) = 4√3. S = AB·CH/2 = 16·4√3/2 = 32√3.');
INSERT INTO public.questions VALUES (633, 11, 'g9-geo-basic-q2-13', 2, 13, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 52°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 85.9,186.0 234.1,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="75.1" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="244.9" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="85.9" y1="186.0" x2="177.1" y2="69.2" stroke-dasharray="5 4"/><text x="185.2" y="63.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "64°", "B": "38°", "C": "52°", "D": "18°", "E": "12°"}'::jsonb, 'E', NULL, '∠B = ∠C = (180° − 52°)/2 = 64°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·64° = 52°. ∠ABD = 64° − 52° = 12°.');
INSERT INTO public.questions VALUES (634, 11, 'g9-geo-basic-q2-14', 2, 14, 'hard', 'single', 'ABC üçbucağında ∠A = 80°, ∠B = 28°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.3 286.0,171.3 55.6,48.7"/><text x="22.1" y="181.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="179.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="47.2" y="43.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="171.3" x2="91.7" y2="122.8" stroke-dasharray="5 4"/><line x1="286.0" y1="171.3" x2="91.7" y2="122.8" stroke-dasharray="5 4"/><circle cx="91.7" cy="122.8" r="2.6" fill="currentColor"/><text x="97.4" y="139.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "108°", "B": "54°", "C": "126°", "D": "130°", "E": "144°"}'::jsonb, 'C', NULL, '∠C = 180° − 80° − 28° = 72°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 126°.');
INSERT INTO public.questions VALUES (635, 11, 'g9-geo-basic-q2-15', 2, 15, 'hard', 'single', 'ABC üçbucağında ∠A = 98°, ∠B = 58°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="133.9,186.0 207.5,186.0 112.5,34.0"/><text x="129.6" y="203.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="217.1" y="199.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="107.9" y="26.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="133.9" y1="186.0" x2="157.8" y2="158.5" stroke-dasharray="5 4"/><line x1="207.5" y1="186.0" x2="157.8" y2="158.5" stroke-dasharray="5 4"/><circle cx="157.8" cy="158.5" r="2.6" fill="currentColor"/><text x="162.3" y="175.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "139°", "B": "168°", "C": "102°", "D": "156°", "E": "78°"}'::jsonb, 'C', NULL, '∠C = 180° − 98° − 58° = 24°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 102°.');
INSERT INTO public.questions VALUES (636, 11, 'g9-geo-basic-q2-16', 2, 16, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 24, BC = 15. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="58.7,186.0 217.0,186.0 261.3,34.0"/><text x="46.7" y="196.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="224.8" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="269.5" y="28.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="130.3" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="152.8" y="105.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="250.2" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><circle cx="185.3" cy="143.8" r="42.2"/></svg>', '{"A": "8", "B": "2", "C": "25/2", "D": "5", "E": "4"}'::jsonb, 'E', NULL, 'p = 27, S = √(p(p − a)(p − b)(p − c)) = 108. r = S/p = 108/27 = 4.');
INSERT INTO public.questions VALUES (637, 11, 'g9-geo-basic-q2-17', 2, 17, 'hard', 'single', 'ABC üçbucağında ∠A = 26°, ∠B = 96°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.5 273.1,171.5 286.0,48.5"/><text x="21.4" y="179.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="284.5" y="182.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="295.5" y="44.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="286.0" y1="48.5" x2="286.0" y2="171.5" stroke-dasharray="5 4"/><line x1="286.0" y1="48.5" x2="199.9" y2="171.5" stroke-dasharray="5 4"/><polyline points="276.0,171.5 276.0,161.5 286.0,161.5" stroke-width="1.2"/><text x="286.0" y="189.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="192.5" y="187.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "61/2°", "B": "70°", "C": "29°", "D": "40°", "E": "35°"}'::jsonb, 'E', NULL, '∠C = 58°, ∠ACL = 29°. ∠ACH = 90° − ∠A = 64°. Aradakı bucaq |29° − (64°)| = |∠A − ∠B|/2 = 35°.');
INSERT INTO public.questions VALUES (638, 11, 'g9-geo-basic-q2-18', 2, 18, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 26, BC = 24. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="128.3,186.0 191.7,186.0 191.7,34.0"/><text x="120.0" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="196.7" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="194.3" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="157.6" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="155.4" y="103.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">26</text><text x="199.3" y="105.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><circle cx="166.3" cy="160.7" r="25.3"/></svg>', '{"A": "8", "B": "13", "C": "4", "D": "2", "E": "5"}'::jsonb, 'C', NULL, 'p = 30, S = √(p(p − a)(p − b)(p − c)) = 120. r = S/p = 120/30 = 4.');
INSERT INTO public.questions VALUES (639, 11, 'g9-geo-basic-q2-19', 2, 19, 'hard', 'single', 'ABC üçbucağında AB = 9, AC = 17, BC = 18. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="119.3,186.0 200.7,186.0 142.4,34.0"/><text x="111.9" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="209.5" y="200.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="140.9" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="161.4" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="122.7" y="106.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="178.4" y="105.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><line x1="119.3" y1="186.0" x2="180.5" y2="133.4" stroke-dasharray="5 4"/><text x="190.4" y="129.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "153/13", "B": "9", "C": "162/17", "D": "81/13", "E": "81/26"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 9 : 17. BD = 18·9/(9 + 17) = 81/13.');
INSERT INTO public.questions VALUES (640, 11, 'g9-geo-basic-q2-20', 2, 20, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 26°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 124.9,186.0 195.1,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="117.5" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="202.5" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="124.9" y1="186.0" x2="188.0" y2="155.2" stroke-dasharray="5 4"/><text x="199.7" y="154.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "51°", "B": "26°", "C": "77°", "D": "57°", "E": "64°"}'::jsonb, 'A', NULL, '∠B = ∠C = (180° − 26°)/2 = 77°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·77° = 26°. ∠ABD = 77° − 26° = 51°.');
INSERT INTO public.questions VALUES (641, 11, 'g9-geo-basic-q3-01', 3, 1, 'hard', 'single', 'ABC üçbucağında AB = 18, AC = 6, BC = 15. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,142.8 286.0,142.8 86.5,77.2"/><text x="21.3" y="150.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="149.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="76.8" y="73.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="169.0" y="155.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="48.4" y="113.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="198.0" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><line x1="34.0" y1="142.8" x2="136.4" y2="93.6" stroke-dasharray="5 4"/><text x="148.1" y="93.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "45", "B": "27/2", "C": "15/2", "D": "45/4", "E": "15/4"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 18 : 6. BD = 15·18/(18 + 6) = 45/4.');
INSERT INTO public.questions VALUES (642, 11, 'g9-geo-basic-q3-02', 3, 2, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 2 və HB = 4 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,169.4 286.0,169.4 118.0,50.6"/><line x1="118.0" y1="50.6" x2="118.0" y2="169.4" stroke-dasharray="5 4"/><polyline points="128.0,169.4 128.0,159.4 118.0,159.4" stroke-width="1.2"/><polyline points="112.2,58.8 120.4,64.5 126.2,56.4" stroke-width="1.2"/><text x="21.7" y="178.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="177.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="113.7" y="43.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="118.0" y="187.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="72.0" y="185.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="208.9" y="184.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text></svg>', '{"A": "2√5", "B": "3", "C": "2√6", "D": "2√2", "E": "2√3"}'::jsonb, 'D', NULL, 'CH² = AH·HB = 2·4 = 8 ⇒ CH = 2√2.');
INSERT INTO public.questions VALUES (643, 11, 'g9-geo-basic-q3-03', 3, 3, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 5, BC = 16. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="73.1,146.0 286.0,146.0 34.0,74.0"/><text x="61.0" y="156.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="153.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="22.3" y="73.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="190.3" y="156.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="41.7" y="113.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="171.1" y="110.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><line x1="73.1" y1="146.0" x2="104.0" y2="94.0" stroke-dasharray="5 4"/><text x="110.6" y="87.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "208/5", "B": "104/9", "C": "169/18", "D": "40/9", "E": "8"}'::jsonb, 'B', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 13 : 5. BD = 16·13/(13 + 5) = 104/9.');
INSERT INTO public.questions VALUES (644, 11, 'g9-geo-basic-q3-04', 3, 4, 'hard', 'single', 'ABC üçbucağında ∠A = 102°, ∠B = 56°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="141.0,186.0 211.3,186.0 108.7,34.0"/><text x="137.9" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="221.0" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="103.5" y="27.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="141.0" y1="186.0" x2="162.2" y2="159.9" stroke-dasharray="5 4"/><line x1="211.3" y1="186.0" x2="162.2" y2="159.9" stroke-dasharray="5 4"/><circle cx="162.2" cy="159.9" r="2.6" fill="currentColor"/><text x="167.3" y="176.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "169°", "B": "79°", "C": "141°", "D": "158°", "E": "101°"}'::jsonb, 'E', NULL, '∠C = 180° − 102° − 56° = 22°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 101°.');
INSERT INTO public.questions VALUES (645, 11, 'g9-geo-basic-q3-05', 3, 5, 'hard', 'single', 'ABC üçbucağında ∠A = 20°, ∠B = 32°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,139.0 286.0,139.0 193.2,81.0"/><text x="21.1" y="145.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="146.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="199.7" y="74.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="139.0" x2="190.0" y2="111.5" stroke-dasharray="5 4"/><line x1="286.0" y1="139.0" x2="190.0" y2="111.5" stroke-dasharray="5 4"/><circle cx="190.0" cy="111.5" r="2.6" fill="currentColor"/><text x="188.7" y="129.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "52°", "B": "26°", "C": "100°", "D": "116°", "E": "154°"}'::jsonb, 'E', NULL, '∠C = 180° − 20° − 32° = 128°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 154°.');
INSERT INTO public.questions VALUES (646, 11, 'g9-geo-basic-q3-06', 3, 6, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 46°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 95.5,186.0 224.5,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="85.3" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="234.7" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="95.5" y1="186.0" x2="185.1" y2="93.2" stroke-dasharray="5 4"/><text x="194.1" y="88.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "46°", "B": "27°", "C": "21°", "D": "44°", "E": "67°"}'::jsonb, 'C', NULL, '∠B = ∠C = (180° − 46°)/2 = 67°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·67° = 46°. ∠ABD = 67° − 46° = 21°.');
INSERT INTO public.questions VALUES (647, 11, 'g9-geo-basic-q3-07', 3, 7, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 16 və HB = 11 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.9 286.0,171.9 183.3,48.1"/><line x1="183.3" y1="48.1" x2="183.3" y2="171.9" stroke-dasharray="5 4"/><polyline points="193.3,171.9 193.3,161.9 183.3,161.9" stroke-width="1.2"/><polyline points="175.6,54.5 182.0,62.2 189.7,55.8" stroke-width="1.2"/><text x="21.6" y="180.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="181.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="185.7" y="40.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="183.3" y="189.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="102.5" y="187.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="239.3" y="188.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text></svg>', '{"A": "12√3", "B": "4√11", "C": "27/2", "D": "√377", "E": "3√33"}'::jsonb, 'B', NULL, 'CH² = AH·HB = 16·11 = 176 ⇒ CH = 4√11.');
INSERT INTO public.questions VALUES (648, 11, 'g9-geo-basic-q3-08', 3, 8, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 24, BC = 13. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,162.5 181.9,162.5 286.0,57.5"/><text x="21.4" y="170.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="186.9" y="179.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.2" y="55.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="97.6" y="173.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="155.4" y="103.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="245.5" y="112.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><circle cx="170.5" cy="135.2" r="27.3"/></svg>', '{"A": "169/10", "B": "24/5", "C": "17/5", "D": "6/5", "E": "12/5"}'::jsonb, 'E', NULL, 'p = 25, S = √(p(p − a)(p − b)(p − c)) = 60. r = S/p = 60/25 = 12/5.');
INSERT INTO public.questions VALUES (649, 11, 'g9-geo-basic-q3-09', 3, 9, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 16, BC = 17. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="82.3,186.0 237.7,186.0 148.6,34.0"/><text x="71.5" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.8" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="147.6" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.9" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="105.2" y="108.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="203.1" y="108.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="82.3" y1="186.0" x2="194.6" y2="112.5" stroke-dasharray="5 4"/><text x="205.5" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "255/31", "B": "272/31", "C": "255/16", "D": "17/2", "E": "225/31"}'::jsonb, 'A', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 15 : 16. BD = 17·15/(15 + 16) = 255/31.');
INSERT INTO public.questions VALUES (650, 11, 'g9-geo-basic-q3-10', 3, 10, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 16 və HB = 10 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.3 286.0,171.3 189.1,48.7"/><line x1="189.1" y1="48.7" x2="189.1" y2="171.3" stroke-dasharray="5 4"/><polyline points="199.1,171.3 199.1,161.3 189.1,161.3" stroke-width="1.2"/><polyline points="181.2,54.9 187.4,62.7 195.3,56.5" stroke-width="1.2"/><text x="21.6" y="180.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="180.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="192.1" y="41.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="189.1" y="189.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="105.1" y="186.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="241.9" y="187.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "4√10", "B": "2√65", "C": "2√105", "D": "2√89", "E": "4√26"}'::jsonb, 'E', NULL, 'AC² = AH·AB = 16·26 = 416 ⇒ AC = 4√26.');
INSERT INTO public.questions VALUES (651, 11, 'g9-geo-basic-q3-11', 3, 11, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 56°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 79.2,186.0 240.8,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="68.2" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="251.8" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="79.2" y1="186.0" x2="169.6" y2="52.0" stroke-dasharray="5 4"/><text x="176.8" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "6°", "B": "62°", "C": "34°", "D": "12°", "E": "56°"}'::jsonb, 'A', NULL, '∠B = ∠C = (180° − 56°)/2 = 62°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·62° = 56°. ∠ABD = 62° − 56° = 6°.');
INSERT INTO public.questions VALUES (652, 11, 'g9-geo-basic-q3-12', 3, 12, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 24, BC = 20. Ən böyük tərəfə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="80.8,186.0 239.2,186.0 194.8,34.0"/><text x="69.5" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="249.6" y="198.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.7" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="157.3" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="128.2" y="107.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="227.5" y="109.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><line x1="239.2" y1="186.0" x2="137.8" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "8", "B": "32", "C": "16", "D": "17", "E": "96/5"}'::jsonb, 'C', NULL, 'p = 32, S = √(p(p − a)(p − b)(p − c)) = 192. h = 2S/24 = 16.');
INSERT INTO public.questions VALUES (653, 11, 'g9-geo-basic-q3-13', 3, 13, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 18, BC = 19. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="87.0,186.0 233.0,186.0 149.4,34.0"/><text x="76.5" y="198.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="243.9" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="148.5" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.8" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="108.2" y="108.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="200.9" y="107.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><line x1="87.0" y1="186.0" x2="193.7" y2="114.5" stroke-dasharray="5 4"/><text x="204.5" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "152/17", "B": "171/17", "C": "152/9", "D": "19/2", "E": "128/17"}'::jsonb, 'A', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 16 : 18. BD = 19·16/(16 + 18) = 152/17.');
INSERT INTO public.questions VALUES (654, 11, 'g9-geo-basic-q3-14', 3, 14, 'hard', 'single', 'ABC üçbucağında ∠A = 20°, ∠B = 68°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,150.0 286.0,150.0 253.7,70.0"/><text x="21.2" y="157.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="158.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="263.6" y="66.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="150.0" x2="233.8" y2="114.8" stroke-dasharray="5 4"/><line x1="286.0" y1="150.0" x2="233.8" y2="114.8" stroke-dasharray="5 4"/><circle cx="233.8" cy="114.8" r="2.6" fill="currentColor"/><text x="228.5" y="131.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "44°", "B": "136°", "C": "134°", "D": "100°", "E": "88°"}'::jsonb, 'B', NULL, '∠C = 180° − 20° − 68° = 92°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 136°.');
INSERT INTO public.questions VALUES (655, 11, 'g9-geo-basic-q3-15', 3, 15, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 30°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 119.3,186.0 200.7,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="111.1" y="201.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="208.9" y="201.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="119.3" y1="186.0" x2="189.8" y2="145.3" stroke-dasharray="5 4"/><text x="201.1" y="143.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "30°", "B": "45°", "C": "60°", "D": "75°", "E": "51°"}'::jsonb, 'B', NULL, '∠B = ∠C = (180° − 30°)/2 = 75°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·75° = 30°. ∠ABD = 75° − 30° = 45°.');
INSERT INTO public.questions VALUES (656, 11, 'g9-geo-basic-q3-16', 3, 16, 'hard', 'single', 'ABC üçbucağında AB = 30, AC = 24, BC = 18. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,170.5 286.0,170.5 195.3,49.5"/><text x="21.5" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="179.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="198.9" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="156.6" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="103.3" y="111.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="252.2" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><circle cx="185.2" cy="120.1" r="50.4"/></svg>', '{"A": "3", "B": "15", "C": "6", "D": "12", "E": "7"}'::jsonb, 'C', NULL, 'p = 36, S = √(p(p − a)(p − b)(p − c)) = 216. r = S/p = 216/36 = 6.');
INSERT INTO public.questions VALUES (657, 11, 'g9-geo-basic-q3-17', 3, 17, 'hard', 'single', 'ABC üçbucağında AB = 25, AC = 29, BC = 6. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,131.1 254.3,131.1 286.0,88.9"/><text x="21.1" y="137.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="267.0" y="139.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.5" y="90.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="132.6" y="139.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="148.3" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">29</text><text x="282.1" y="113.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><circle cx="245.5" cy="113.5" r="17.6"/></svg>', '{"A": "2", "B": "3", "C": "1", "D": "145/8", "E": "4"}'::jsonb, 'A', NULL, 'p = 30, S = √(p(p − a)(p − b)(p − c)) = 60. r = S/p = 60/30 = 2.');
INSERT INTO public.questions VALUES (658, 11, 'g9-geo-basic-q3-18', 3, 18, 'hard', 'single', 'ABC üçbucağında ∠A = 30°, ∠B = 76°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.6 286.0,173.6 254.3,46.4"/><text x="21.4" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.9" y="183.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="262.0" y="41.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="254.3" y1="46.4" x2="254.3" y2="173.6" stroke-dasharray="5 4"/><line x1="254.3" y1="46.4" x2="200.3" y2="173.6" stroke-dasharray="5 4"/><polyline points="264.3,173.6 264.3,163.6 254.3,163.6" stroke-width="1.2"/><text x="254.3" y="191.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="195.2" y="190.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "28°", "B": "37°", "C": "46°", "D": "53/2°", "E": "23°"}'::jsonb, 'E', NULL, '∠C = 74°, ∠ACL = 37°. ∠ACH = 90° − ∠A = 60°. Aradakı bucaq |37° − (60°)| = |∠A − ∠B|/2 = 23°.');
INSERT INTO public.questions VALUES (659, 11, 'g9-geo-basic-q3-19', 3, 19, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 7 və HB = 14 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,169.4 286.0,169.4 118.0,50.6"/><line x1="118.0" y1="50.6" x2="118.0" y2="169.4" stroke-dasharray="5 4"/><polyline points="128.0,169.4 128.0,159.4 118.0,159.4" stroke-width="1.2"/><polyline points="112.2,58.8 120.4,64.5 126.2,56.4" stroke-width="1.2"/><text x="21.7" y="178.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="177.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="113.7" y="43.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="118.0" y="187.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="72.0" y="185.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="208.9" y="184.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "7√5", "B": "21/2", "C": "7√3", "D": "7√6", "E": "7√2"}'::jsonb, 'E', NULL, 'CH² = AH·HB = 7·14 = 98 ⇒ CH = 7√2.');
INSERT INTO public.questions VALUES (660, 11, 'g9-geo-basic-q3-20', 3, 20, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 13, BC = 10. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,145.4 286.0,145.4 181.7,74.6"/><text x="21.2" y="152.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="152.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="185.6" y="67.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="156.5" y="161.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="96.1" y="112.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="245.7" y="112.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="34.0" y1="145.4" x2="222.8" y2="102.5" stroke-dasharray="5 4"/><text x="235.5" y="104.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "5", "B": "400/33", "C": "130/33", "D": "200/33", "E": "200/13"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 20 : 13. BD = 10·20/(20 + 13) = 200/33.');
INSERT INTO public.questions VALUES (661, 12, 'g9-geo-poly-q1-01', 1, 1, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 5, KC = 5 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 34.0,47.0 286.0,47.0 286.0,173.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.4" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.6" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="173.0" x2="160.0" y2="47.0" stroke-dasharray="5 4"/><text x="169.2" y="42.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "31", "B": "20", "C": "40", "D": "25", "E": "30"}'::jsonb, 'E', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 5. BC = 10. P = 2(5 + 10) = 30.');
INSERT INTO public.questions VALUES (662, 12, 'g9-geo-poly-q1-02', 1, 2, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 15 və 9, yan tərəfi 15 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="82.4,186.0 237.6,186.0 206.5,34.0 113.5,34.0"/><text x="73.1" y="200.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="246.9" y="200.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="213.3" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="106.7" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="234.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="85.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "12√217", "B": "72√6", "C": "180", "D": "144√6", "E": "36√6"}'::jsonb, 'B', NULL, 'h = √(15² − 3²) = 6√6. S = (15 + 9)/2 · h = 72√6.');
INSERT INTO public.questions VALUES (663, 12, 'g9-geo-poly-q1-03', 1, 3, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 10, KC = 25 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,146.0 34.0,74.0 286.0,74.0 286.0,146.0"/><text x="21.5" y="154.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="21.5" y="75.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.5" y="75.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="298.5" y="154.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="146.0" x2="106.0" y2="74.0" stroke-dasharray="5 4"/><text x="115.2" y="69.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "40", "B": "70", "C": "90", "D": "120", "E": "110"}'::jsonb, 'C', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 10. BC = 35. P = 2(10 + 35) = 90.');
INSERT INTO public.questions VALUES (664, 12, 'g9-geo-poly-q1-04', 1, 4, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 168° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "27", "B": "810", "C": "434", "D": "420", "E": "405"}'::jsonb, 'E', NULL, 'Xarici bucaq 180° − 168° = 12°, n = 360 : 12 = 30. Diaqonallar: n(n − 3)/2 = 405.');
INSERT INTO public.questions VALUES (665, 12, 'g9-geo-poly-q1-05', 1, 5, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 120° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "14", "B": "18", "C": "12", "D": "9", "E": "3"}'::jsonb, 'D', NULL, 'Xarici bucaq 180° − 120° = 60°, n = 360 : 60 = 6. Diaqonallar: n(n − 3)/2 = 9.');
INSERT INTO public.questions VALUES (666, 12, 'g9-geo-poly-q1-06', 1, 6, 'hard', 'single', 'Rombun diaqonalları 20 və 48 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 191.7,110.0 160.0,186.0 128.3,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="204.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="115.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="191.7" y1="110.0" x2="128.3" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="29.2"/></svg>', '{"A": "133/13", "B": "60/13", "C": "120/13", "D": "240/13", "E": "13"}'::jsonb, 'C', NULL, 'Tərəf 26. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 480/52 = 120/13.');
INSERT INTO public.questions VALUES (667, 12, 'g9-geo-poly-q1-07', 1, 7, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 24 və 12, yan tərəfi 20 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="64.4,186.0 255.6,186.0 207.8,34.0 112.2,34.0"/><text x="54.2" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="265.8" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="214.7" y="28.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="105.3" y="28.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="243.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="76.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><line x1="64.4" y1="186.0" x2="207.8" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "2√235", "B": "4√43", "C": "20", "D": "4√34", "E": "√689"}'::jsonb, 'B', NULL, 'Hündürlük: h² = 20² − ((24 − 12)/2)² = 364. Diaqonalın proyeksiyası (24 + 12)/2 = 18. d = √(364 + 324) = 4√43.');
INSERT INTO public.questions VALUES (668, 12, 'g9-geo-poly-q1-08', 1, 8, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 6 : 1 nisbətində bölür. Düzbucaqlının perimetri 130 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="71.3,186.0 71.3,34.0 248.7,34.0 248.7,186.0"/><text x="61.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="61.5" y="30.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="258.5" y="30.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="258.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="71.3" y1="186.0" x2="223.3" y2="34.0" stroke-dasharray="5 4"/><text x="232.5" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "1050", "B": "900", "C": "1225", "D": "1080", "E": "1020"}'::jsonb, 'A', NULL, '∠BAK = 45° ⇒ AB = BK = 6t, BC = 7t. Perimetr 2(13t) = 130 ⇒ t = 5. S = 30·35 = 1050.');
INSERT INTO public.questions VALUES (669, 12, 'g9-geo-poly-q1-09', 1, 9, 'hard', 'single', 'Paraleloqramın tərəfləri 9 və 3, aralarındakı bucaq 60° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,141.2 250.0,141.2 286.0,78.8 70.0,78.8"/><text x="21.4" y="149.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="262.3" y="150.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.6" y="80.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="57.7" y="79.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="136.0" y="156.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="40.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><path d="M52.0,141.2 A18,18 0 0 0 43.0,125.6" stroke-width="1.2"/><text x="60.8" y="130.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="141.2" x2="286.0" y2="78.8" stroke-dasharray="5 4"/><line x1="250.0" y1="141.2" x2="70.0" y2="78.8" stroke-dasharray="5 4"/></svg>', '{"A": "12", "B": "3√7", "C": "3√10", "D": "3√13", "E": "6√5"}'::jsonb, 'D', NULL, 'Kosinuslar teoremi: d² = 9² + 3² ∓ 2·9·3·cos 60°. Böyük diaqonal √117, kiçik diaqonal √63. Cavab: 3√13.');
INSERT INTO public.questions VALUES (670, 12, 'g9-geo-poly-q1-10', 1, 10, 'hard', 'single', 'Rombun diaqonalları 14 və 48 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 182.2,110.0 160.0,186.0 137.8,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="195.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="124.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="182.2" y1="110.0" x2="137.8" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "336/25", "B": "672/25", "C": "361/25", "D": "31", "E": "168/25"}'::jsonb, 'A', NULL, 'Tərəf: √(7² + 24²) = 25. S = d₁d₂/2 = 336. h = S/a = 336/25 = 336/25.');
INSERT INTO public.questions VALUES (671, 12, 'g9-geo-poly-q1-11', 1, 11, 'hard', 'single', 'Paraleloqramın tərəfləri 14 və 11, aralarındakı bucaq 60° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.6 214.9,171.6 286.0,48.4 105.1,48.4"/><text x="22.3" y="182.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="223.6" y="186.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.7" y="47.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="96.4" y="43.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="118.5" y="186.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="57.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><path d="M52.0,171.6 A18,18 0 0 0 43.0,156.0" stroke-width="1.2"/><text x="60.8" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="171.6" x2="286.0" y2="48.4" stroke-dasharray="5 4"/><line x1="214.9" y1="171.6" x2="105.1" y2="48.4" stroke-dasharray="5 4"/></svg>', '{"A": "√317", "B": "√634", "C": "√163", "D": "25", "E": "√471"}'::jsonb, 'E', NULL, 'Kosinuslar teoremi: d² = 14² + 11² ∓ 2·14·11·cos 60°. Böyük diaqonal √471, kiçik diaqonal √163. Cavab: √471.');
INSERT INTO public.questions VALUES (672, 12, 'g9-geo-poly-q1-12', 1, 12, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 18 və 14, yan tərəfi 17 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="79.0,186.0 241.0,186.0 223.0,34.0 97.0,34.0"/><text x="69.5" y="199.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="250.5" y="199.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="231.3" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="88.7" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="244.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="76.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="79.0" y1="186.0" x2="223.0" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√609", "B": "√485", "C": "17", "D": "√541", "E": "√542"}'::jsonb, 'D', NULL, 'Hündürlük: h² = 17² − ((18 − 14)/2)² = 285. Diaqonalın proyeksiyası (18 + 14)/2 = 16. d = √(285 + 256) = √541.');
INSERT INTO public.questions VALUES (673, 12, 'g9-geo-poly-q1-13', 1, 13, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 162° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "170", "B": "340", "C": "17", "D": "180", "E": "189"}'::jsonb, 'A', NULL, 'Xarici bucaq 180° − 162° = 18°, n = 360 : 18 = 20. Diaqonallar: n(n − 3)/2 = 170.');
INSERT INTO public.questions VALUES (674, 12, 'g9-geo-poly-q1-14', 1, 14, 'hard', 'open', 'Rombun diaqonalları 18 və 24 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/></svg>', NULL, NULL, '72/5', 'Tərəf: √(9² + 12²) = 15. S = d₁d₂/2 = 216. h = S/a = 216/15 = 72/5.');
INSERT INTO public.questions VALUES (675, 12, 'g9-geo-poly-q1-15', 1, 15, 'hard', 'single', 'Rombun diaqonalları 10 və 24 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 191.7,110.0 160.0,186.0 128.3,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="204.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="115.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="191.7" y1="110.0" x2="128.3" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="29.2"/></svg>', '{"A": "120/13", "B": "73/13", "C": "30/13", "D": "60/13", "E": "13/2"}'::jsonb, 'D', NULL, 'Tərəf 13. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 120/26 = 60/13.');
INSERT INTO public.questions VALUES (676, 12, 'g9-geo-poly-q1-16', 1, 16, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 170° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "594", "B": "1188", "C": "33", "D": "612", "E": "629"}'::jsonb, 'A', NULL, 'Xarici bucaq 180° − 170° = 10°, n = 360 : 10 = 36. Diaqonallar: n(n − 3)/2 = 594.');
INSERT INTO public.questions VALUES (677, 12, 'g9-geo-poly-q1-17', 1, 17, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 20, KC = 16 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,180.0 34.0,40.0 286.0,40.0 286.0,180.0"/><text x="22.6" y="191.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.6" y="38.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.4" y="38.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.4" y="191.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="180.0" x2="174.0" y2="40.0" stroke-dasharray="5 4"/><text x="183.2" y="35.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "104", "B": "72", "C": "112", "D": "80", "E": "152"}'::jsonb, 'C', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 20. BC = 36. P = 2(20 + 36) = 112.');
INSERT INTO public.questions VALUES (678, 12, 'g9-geo-poly-q1-18', 1, 18, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 14 və 12, yan tərəfi 20 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="106.7,186.0 213.3,186.0 205.7,34.0 114.3,34.0"/><text x="99.3" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="220.7" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="212.4" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="107.6" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="221.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="98.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><line x1="106.7" y1="186.0" x2="205.7" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√595", "B": "20", "C": "√569", "D": "2√142", "E": "4√34"}'::jsonb, 'D', NULL, 'Hündürlük: h² = 20² − ((14 − 12)/2)² = 399. Diaqonalın proyeksiyası (14 + 12)/2 = 13. d = √(399 + 169) = 2√142.');
INSERT INTO public.questions VALUES (679, 12, 'g9-geo-poly-q1-19', 1, 19, 'hard', 'single', 'Paraleloqramın tərəfləri 12 və 3, aralarındakı bucaq 120° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="62.0,134.2 286.0,134.2 258.0,85.8 34.0,85.8"/><text x="49.4" y="142.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="141.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="270.6" y="87.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.2" y="88.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="180.0" y="149.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="36.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><path d="M80.0,134.2 A18,18 0 0 0 53.0,118.7" stroke-width="1.2"/><text x="77.5" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="62.0" y1="134.2" x2="258.0" y2="85.8" stroke-dasharray="5 4"/><line x1="286.0" y1="134.2" x2="34.0" y2="85.8" stroke-dasharray="5 4"/></svg>', '{"A": "3√21", "B": "3√13", "C": "3√34", "D": "15", "E": "3√17"}'::jsonb, 'A', NULL, 'Kosinuslar teoremi: d² = 12² + 3² ∓ 2·12·3·cos 60°. Böyük diaqonal √189, kiçik diaqonal √117. Cavab: 3√21.');
INSERT INTO public.questions VALUES (680, 12, 'g9-geo-poly-q1-20', 1, 20, 'hard', 'single', 'Paraleloqramın tərəfləri 13 və 6, aralarındakı bucaq 60° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,150.9 238.8,150.9 286.0,69.1 81.3,69.1"/><text x="21.6" y="159.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="250.3" y="161.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.4" y="70.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="69.7" y="68.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="130.4" y="166.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="45.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M52.0,150.9 A18,18 0 0 0 43.0,135.3" stroke-width="1.2"/><text x="60.8" y="140.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="150.9" x2="286.0" y2="69.1" stroke-dasharray="5 4"/><line x1="238.8" y1="150.9" x2="81.3" y2="69.1" stroke-dasharray="5 4"/></svg>', '{"A": "√283", "B": "√205", "C": "19", "D": "√410", "E": "√127"}'::jsonb, 'E', NULL, 'Kosinuslar teoremi: d² = 13² + 6² ∓ 2·13·6·cos 60°. Böyük diaqonal √283, kiçik diaqonal √127. Cavab: √127.');
INSERT INTO public.questions VALUES (681, 12, 'g9-geo-poly-q2-01', 2, 1, 'hard', 'single', 'Paraleloqramın tərəfləri 14 və 10, aralarındakı bucaq 60° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,167.4 219.7,167.4 286.0,52.6 100.3,52.6"/><text x="22.2" y="177.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="229.1" y="181.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.8" y="52.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.9" y="48.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="120.8" y="182.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="55.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><path d="M52.0,167.4 A18,18 0 0 0 43.0,151.8" stroke-width="1.2"/><text x="60.8" y="156.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="167.4" x2="286.0" y2="52.6" stroke-dasharray="5 4"/><line x1="219.7" y1="167.4" x2="100.3" y2="52.6" stroke-dasharray="5 4"/></svg>', '{"A": "24", "B": "2√109", "C": "2√74", "D": "2√39", "E": "4√37"}'::jsonb, 'D', NULL, 'Kosinuslar teoremi: d² = 14² + 10² ∓ 2·14·10·cos 60°. Böyük diaqonal √436, kiçik diaqonal √156. Cavab: 2√39.');
INSERT INTO public.questions VALUES (682, 12, 'g9-geo-poly-q2-02', 2, 2, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 9 və 3, yan tərəfi 20 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="125.4,186.0 194.6,186.0 171.5,34.0 148.5,34.0"/><text x="120.0" y="202.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="200.0" y="202.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="173.5" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="146.5" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="195.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="124.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text></svg>', '{"A": "12√391", "B": "3√391", "C": "120", "D": "84√2", "E": "6√391"}'::jsonb, 'E', NULL, 'h = √(20² − 3²) = √391. S = (9 + 3)/2 · h = 6√391.');
INSERT INTO public.questions VALUES (683, 12, 'g9-geo-poly-q2-03', 2, 3, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 22 və 8, yan tərəfi 18 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="59.2,186.0 260.8,186.0 196.7,34.0 123.3,34.0"/><text x="48.8" y="198.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="271.2" y="198.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="202.3" y="27.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="117.7" y="27.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">22</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="240.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="79.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><line x1="59.2" y1="186.0" x2="196.7" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√759", "B": "10√5", "C": "√501", "D": "2√97", "E": "18"}'::jsonb, 'B', NULL, 'Hündürlük: h² = 18² − ((22 − 8)/2)² = 275. Diaqonalın proyeksiyası (22 + 8)/2 = 15. d = √(275 + 225) = 10√5.');
INSERT INTO public.questions VALUES (684, 12, 'g9-geo-poly-q2-04', 2, 4, 'hard', 'single', 'Rombun diaqonalları 80 və 84 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 232.4,110.0 160.0,186.0 87.6,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="74.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="232.4" y1="110.0" x2="87.6" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="52.4"/></svg>', '{"A": "840/29", "B": "420/29", "C": "29", "D": "869/29", "E": "1680/29"}'::jsonb, 'A', NULL, 'Tərəf 58. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 3360/116 = 840/29.');
INSERT INTO public.questions VALUES (685, 12, 'g9-geo-poly-q2-05', 2, 5, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 23 və 11, yan tərəfi 7 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,129.8 286.0,129.8 220.3,90.2 99.7,90.2"/><text x="21.2" y="136.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="136.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="232.6" y="91.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="87.4" y="91.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="146.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">23</text><text x="160.0" y="83.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="265.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="54.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><line x1="34.0" y1="129.8" x2="220.3" y2="90.2" stroke-dasharray="5 4"/></svg>', '{"A": "√170", "B": "√303", "C": "7", "D": "√542", "E": "√302"}'::jsonb, 'E', NULL, 'Hündürlük: h² = 7² − ((23 − 11)/2)² = 13. Diaqonalın proyeksiyası (23 + 11)/2 = 17. d = √(13 + 289) = √302.');
INSERT INTO public.questions VALUES (686, 12, 'g9-geo-poly-q2-06', 2, 6, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 1 : 1 nisbətində bölür. Düzbucaqlının perimetri 12 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 34.0,47.0 286.0,47.0 286.0,173.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.4" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.6" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="173.0" x2="160.0" y2="47.0" stroke-dasharray="5 4"/><text x="169.2" y="42.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "10", "B": "8", "C": "6", "D": "4", "E": "16"}'::jsonb, 'B', NULL, '∠BAK = 45° ⇒ AB = BK = 1t, BC = 2t. Perimetr 2(3t) = 12 ⇒ t = 2. S = 2·4 = 8.');
INSERT INTO public.questions VALUES (687, 12, 'g9-geo-poly-q2-07', 2, 7, 'hard', 'single', 'Paraleloqramın tərəfləri 7 və 14, aralarındakı bucaq 120° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,186.0 247.8,186.0 160.0,34.0 72.2,34.0"/><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="257.6" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="62.4" y="30.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="209.9" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="104.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><path d="M178.0,186.0 A18,18 0 0 0 151.0,170.4" stroke-width="1.2"/><text x="175.5" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="160.0" y1="186.0" x2="160.0" y2="34.0" stroke-dasharray="5 4"/><line x1="247.8" y1="186.0" x2="72.2" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "21", "B": "7√3", "C": "7√10", "D": "7√5", "E": "7√7"}'::jsonb, 'B', NULL, 'Kosinuslar teoremi: d² = 7² + 14² ∓ 2·7·14·cos 60°. Böyük diaqonal √343, kiçik diaqonal √147. Cavab: 7√3.');
INSERT INTO public.questions VALUES (688, 12, 'g9-geo-poly-q2-08', 2, 8, 'hard', 'single', 'Rombun diaqonalları 20 və 48 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 191.7,110.0 160.0,186.0 128.3,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="204.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="115.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="191.7" y1="110.0" x2="128.3" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "480/13", "B": "34", "C": "240/13", "D": "253/13", "E": "120/13"}'::jsonb, 'C', NULL, 'Tərəf: √(10² + 24²) = 26. S = d₁d₂/2 = 480. h = S/a = 480/26 = 240/13.');
INSERT INTO public.questions VALUES (689, 12, 'g9-geo-poly-q2-09', 2, 9, 'hard', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 720° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "3", "B": "14", "C": "9", "D": "18", "E": "12"}'::jsonb, 'C', NULL, '180°(n − 2) = 720° ⇒ n = 6. Diaqonallar: n(n − 3)/2 = 9.');
INSERT INTO public.questions VALUES (690, 12, 'g9-geo-poly-q2-10', 2, 10, 'hard', 'single', 'Paraleloqramın tərəfləri 9 və 5, aralarındakı bucaq 120° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="88.8,157.4 286.0,157.4 231.2,62.6 34.0,62.6"/><text x="78.0" y="169.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.2" y="167.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="242.0" y="60.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.8" y="63.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="193.4" y="172.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="49.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M106.8,157.4 A18,18 0 0 0 79.8,141.9" stroke-width="1.2"/><text x="104.3" y="135.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="88.8" y1="157.4" x2="231.2" y2="62.6" stroke-dasharray="5 4"/><line x1="286.0" y1="157.4" x2="34.0" y2="62.6" stroke-dasharray="5 4"/></svg>', '{"A": "14", "B": "√151", "C": "2√53", "D": "√61", "E": "√106"}'::jsonb, 'B', NULL, 'Kosinuslar teoremi: d² = 9² + 5² ∓ 2·9·5·cos 60°. Böyük diaqonal √151, kiçik diaqonal √61. Cavab: √151.');
INSERT INTO public.questions VALUES (691, 12, 'g9-geo-poly-q2-11', 2, 11, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 8, KC = 4 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 46.0,34.0 274.0,34.0 274.0,186.0"/><text x="35.2" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="35.2" y="31.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="284.8" y="31.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="284.8" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="46.0" y1="186.0" x2="198.0" y2="34.0" stroke-dasharray="5 4"/><text x="207.2" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "41", "B": "32", "C": "56", "D": "24", "E": "40"}'::jsonb, 'E', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 8. BC = 12. P = 2(8 + 12) = 40.');
INSERT INTO public.questions VALUES (692, 12, 'g9-geo-poly-q2-12', 2, 12, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 2 : 1 nisbətində bölür. Düzbucaqlının perimetri 20 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 46.0,34.0 274.0,34.0 274.0,186.0"/><text x="35.2" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="35.2" y="31.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="284.8" y="31.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="284.8" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="46.0" y1="186.0" x2="198.0" y2="34.0" stroke-dasharray="5 4"/><text x="207.2" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "16", "B": "24", "C": "28", "D": "36", "E": "20"}'::jsonb, 'B', NULL, '∠BAK = 45° ⇒ AB = BK = 2t, BC = 3t. Perimetr 2(5t) = 20 ⇒ t = 2. S = 4·6 = 24.');
INSERT INTO public.questions VALUES (693, 12, 'g9-geo-poly-q2-13', 2, 13, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 18 və 12, yan tərəfi 9 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,169.4 286.0,169.4 244.0,50.6 76.0,50.6"/><text x="22.2" y="179.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.8" y="179.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="254.6" y="48.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="65.4" y="48.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="186.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="43.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="277.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="43.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text></svg>', '{"A": "15√73", "B": "90√2", "C": "180√2", "D": "135", "E": "45√2"}'::jsonb, 'B', NULL, 'h = √(9² − 3²) = 6√2. S = (18 + 12)/2 · h = 90√2.');
INSERT INTO public.questions VALUES (694, 12, 'g9-geo-poly-q2-14', 2, 14, 'hard', 'open', 'Rombun diaqonalları 12 və 16 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/></svg>', NULL, NULL, '48/5', 'Tərəf: √(6² + 8²) = 10. S = d₁d₂/2 = 96. h = S/a = 96/10 = 48/5.');
INSERT INTO public.questions VALUES (695, 12, 'g9-geo-poly-q2-15', 2, 15, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 10, KC = 6 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="38.4,186.0 38.4,34.0 281.6,34.0 281.6,186.0"/><text x="27.4" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="27.4" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="292.6" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="292.6" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="38.4" y1="186.0" x2="190.4" y2="34.0" stroke-dasharray="5 4"/><text x="199.6" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "32", "B": "72", "C": "44", "D": "52", "E": "40"}'::jsonb, 'D', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 10. BC = 16. P = 2(10 + 16) = 52.');
INSERT INTO public.questions VALUES (696, 12, 'g9-geo-poly-q2-16', 2, 16, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 108° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "7", "B": "2", "C": "10", "D": "5", "E": "9"}'::jsonb, 'D', NULL, 'Xarici bucaq 180° − 108° = 72°, n = 360 : 72 = 5. Diaqonallar: n(n − 3)/2 = 5.');
INSERT INTO public.questions VALUES (697, 12, 'g9-geo-poly-q2-17', 2, 17, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 4 : 4 nisbətində bölür. Düzbucaqlının perimetri 72 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 34.0,47.0 286.0,47.0 286.0,173.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.4" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.6" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="173.0" x2="160.0" y2="47.0" stroke-dasharray="5 4"/><text x="169.2" y="42.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "300", "B": "276", "C": "576", "D": "144", "E": "288"}'::jsonb, 'E', NULL, '∠BAK = 45° ⇒ AB = BK = 4t, BC = 8t. Perimetr 2(12t) = 72 ⇒ t = 3. S = 12·24 = 288.');
INSERT INTO public.questions VALUES (698, 12, 'g9-geo-poly-q2-18', 2, 18, 'hard', 'single', 'Paraleloqramın tərəfləri 2 və 13, aralarındakı bucaq 60° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="102.6,186.0 129.6,186.0 217.4,34.0 190.4,34.0"/><text x="94.8" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="124.8" y="203.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="225.2" y="28.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="195.2" y="26.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="110.1" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="134.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><path d="M120.6,186.0 A18,18 0 0 0 111.6,170.4" stroke-width="1.2"/><text x="129.5" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="102.6" y1="186.0" x2="217.4" y2="34.0" stroke-dasharray="5 4"/><line x1="129.6" y1="186.0" x2="190.4" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√346", "B": "√199", "C": "15", "D": "√173", "E": "7√3"}'::jsonb, 'B', NULL, 'Kosinuslar teoremi: d² = 2² + 13² ∓ 2·2·13·cos 60°. Böyük diaqonal √199, kiçik diaqonal √147. Cavab: √199.');
INSERT INTO public.questions VALUES (699, 12, 'g9-geo-poly-q2-19', 2, 19, 'hard', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 1440° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "40", "B": "70", "C": "7", "D": "35", "E": "44"}'::jsonb, 'D', NULL, '180°(n − 2) = 1440° ⇒ n = 10. Diaqonallar: n(n − 3)/2 = 35.');
INSERT INTO public.questions VALUES (700, 12, 'g9-geo-poly-q2-20', 2, 20, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 28 və 14, yan tərəfi 14 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 223.0,55.4 97.0,55.4"/><text x="22.1" y="174.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.9" y="174.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="232.8" y="51.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="87.2" y="51.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="181.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">28</text><text x="160.0" y="48.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="266.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="53.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="34.0" y1="164.6" x2="223.0" y2="55.4" stroke-dasharray="5 4"/></svg>', '{"A": "7√19", "B": "14√3", "C": "14√2", "D": "14", "E": "√589"}'::jsonb, 'B', NULL, 'Hündürlük: h² = 14² − ((28 − 14)/2)² = 147. Diaqonalın proyeksiyası (28 + 14)/2 = 21. d = √(147 + 441) = 14√3.');
INSERT INTO public.questions VALUES (701, 12, 'g9-geo-poly-q3-01', 3, 1, 'hard', 'single', 'Rombun diaqonalları 6 və 8 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "48/5", "B": "24/5", "C": "29/5", "D": "7", "E": "12/5"}'::jsonb, 'B', NULL, 'Tərəf: √(3² + 4²) = 5. S = d₁d₂/2 = 24. h = S/a = 24/5 = 24/5.');
INSERT INTO public.questions VALUES (702, 12, 'g9-geo-poly-q3-02', 3, 2, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 135° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "24", "B": "27", "C": "40", "D": "5", "E": "20"}'::jsonb, 'E', NULL, 'Xarici bucaq 180° − 135° = 45°, n = 360 : 45 = 8. Diaqonallar: n(n − 3)/2 = 20.');
INSERT INTO public.questions VALUES (703, 12, 'g9-geo-poly-q3-03', 3, 3, 'hard', 'single', 'Paraleloqramın tərəfləri 7 və 5, aralarındakı bucaq 120° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="100.3,167.4 286.0,167.4 219.7,52.6 34.0,52.6"/><text x="90.9" y="181.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.8" y="177.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.1" y="48.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="22.2" y="52.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="199.2" y="182.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="55.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M118.3,167.4 A18,18 0 0 0 91.3,151.8" stroke-width="1.2"/><text x="115.8" y="145.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="100.3" y1="167.4" x2="219.7" y2="52.6" stroke-dasharray="5 4"/><line x1="286.0" y1="167.4" x2="34.0" y2="52.6" stroke-dasharray="5 4"/></svg>', '{"A": "√109", "B": "√74", "C": "√39", "D": "12", "E": "2√37"}'::jsonb, 'A', NULL, 'Kosinuslar teoremi: d² = 7² + 5² ∓ 2·7·5·cos 60°. Böyük diaqonal √109, kiçik diaqonal √39. Cavab: √109.');
INSERT INTO public.questions VALUES (704, 12, 'g9-geo-poly-q3-04', 3, 4, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 3 : 5 nisbətində bölür. Düzbucaqlının perimetri 22 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,157.2 34.0,62.8 286.0,62.8 286.0,157.2"/><text x="21.8" y="166.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="21.8" y="63.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.2" y="63.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="298.2" y="166.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="157.2" x2="128.5" y2="62.8" stroke-dasharray="5 4"/><text x="137.7" y="58.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "27", "B": "9", "C": "21", "D": "24", "E": "64"}'::jsonb, 'D', NULL, '∠BAK = 45° ⇒ AB = BK = 3t, BC = 8t. Perimetr 2(11t) = 22 ⇒ t = 1. S = 3·8 = 24.');
INSERT INTO public.questions VALUES (705, 12, 'g9-geo-poly-q3-05', 3, 5, 'hard', 'single', 'Paraleloqramın tərəfləri 13 və 2, aralarındakı bucaq 120° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="52.0,125.6 286.0,125.6 268.0,94.4 34.0,94.4"/><text x="39.1" y="132.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="132.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="280.9" y="97.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.1" y="97.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="175.0" y="141.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="31.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><path d="M70.0,125.6 A18,18 0 0 0 43.0,110.0" stroke-width="1.2"/><text x="67.5" y="103.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="52.0" y1="125.6" x2="268.0" y2="94.4" stroke-dasharray="5 4"/><line x1="286.0" y1="125.6" x2="34.0" y2="94.4" stroke-dasharray="5 4"/></svg>', '{"A": "7√3", "B": "√173", "C": "15", "D": "√199", "E": "√346"}'::jsonb, 'D', NULL, 'Kosinuslar teoremi: d² = 13² + 2² ∓ 2·13·2·cos 60°. Böyük diaqonal √199, kiçik diaqonal √147. Cavab: √199.');
INSERT INTO public.questions VALUES (706, 12, 'g9-geo-poly-q3-06', 3, 6, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 12 və 10, yan tərəfi 11 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="76.7,186.0 243.3,186.0 229.4,34.0 90.6,34.0"/><text x="67.1" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="252.9" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="238.1" y="29.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="81.9" y="29.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="248.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="71.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text></svg>', '{"A": "23√30", "B": "11√30", "C": "22√30", "D": "44√30", "E": "121"}'::jsonb, 'C', NULL, 'h = √(11² − 1²) = 2√30. S = (12 + 10)/2 · h = 22√30.');
INSERT INTO public.questions VALUES (707, 12, 'g9-geo-poly-q3-07', 3, 7, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 30 və 14, yan tərəfi 13 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,153.0 286.0,153.0 218.8,67.0 101.2,67.0"/><text x="21.7" y="162.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="162.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.3" y="64.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.7" y="64.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="170.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="160.0" y="60.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="264.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="55.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="34.0" y1="153.0" x2="218.8" y2="67.0" stroke-dasharray="5 4"/></svg>', '{"A": "√589", "B": "√365", "C": "√1005", "D": "13", "E": "√590"}'::jsonb, 'A', NULL, 'Hündürlük: h² = 13² − ((30 − 14)/2)² = 105. Diaqonalın proyeksiyası (30 + 14)/2 = 22. d = √(105 + 484) = √589.');
INSERT INTO public.questions VALUES (708, 12, 'g9-geo-poly-q3-08', 3, 8, 'hard', 'single', 'Paraleloqramın tərəfləri 2 və 7, aralarındakı bucaq 120° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="178.8,186.0 229.0,186.0 141.2,34.0 91.0,34.0"/><text x="181.9" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="237.7" y="200.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="138.1" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="82.3" y="29.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="209.9" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="122.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><path d="M196.8,186.0 A18,18 0 0 0 169.8,170.4" stroke-width="1.2"/><text x="194.3" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="178.8" y1="186.0" x2="141.2" y2="34.0" stroke-dasharray="5 4"/><line x1="229.0" y1="186.0" x2="91.0" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√39", "B": "√53", "C": "√67", "D": "√106", "E": "9"}'::jsonb, 'A', NULL, 'Kosinuslar teoremi: d² = 2² + 7² ∓ 2·2·7·cos 60°. Böyük diaqonal √67, kiçik diaqonal √39. Cavab: √39.');
INSERT INTO public.questions VALUES (709, 12, 'g9-geo-poly-q3-09', 3, 9, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 22 və 10, yan tərəfi 7 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,130.6 286.0,130.6 217.3,89.4 102.7,89.4"/><text x="21.2" y="137.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="137.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.5" y="89.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.5" y="89.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="147.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">22</text><text x="160.0" y="82.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="263.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="56.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><line x1="34.0" y1="130.6" x2="217.3" y2="89.4" stroke-dasharray="5 4"/></svg>', '{"A": "√149", "B": "√497", "C": "√269", "D": "7", "E": "3√30"}'::jsonb, 'C', NULL, 'Hündürlük: h² = 7² − ((22 − 10)/2)² = 13. Diaqonalın proyeksiyası (22 + 10)/2 = 16. d = √(13 + 256) = √269.');
INSERT INTO public.questions VALUES (710, 12, 'g9-geo-poly-q3-10', 3, 10, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 5 : 4 nisbətində bölür. Düzbucaqlının perimetri 56 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,180.0 34.0,40.0 286.0,40.0 286.0,180.0"/><text x="22.6" y="191.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.6" y="38.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.4" y="38.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.4" y="191.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="180.0" x2="174.0" y2="40.0" stroke-dasharray="5 4"/><text x="183.2" y="35.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "180", "B": "324", "C": "190", "D": "170", "E": "100"}'::jsonb, 'A', NULL, '∠BAK = 45° ⇒ AB = BK = 5t, BC = 9t. Perimetr 2(14t) = 56 ⇒ t = 2. S = 10·18 = 180.');
INSERT INTO public.questions VALUES (711, 12, 'g9-geo-poly-q3-11', 3, 11, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 13 və 3, yan tərəfi 14 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="84.4,186.0 235.6,186.0 177.4,34.0 142.6,34.0"/><text x="75.3" y="200.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="244.7" y="200.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="180.3" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="139.7" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="218.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="101.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "112", "B": "48√19", "C": "24√19", "D": "16√43", "E": "12√19"}'::jsonb, 'C', NULL, 'h = √(14² − 5²) = 3√19. S = (13 + 3)/2 · h = 24√19.');
INSERT INTO public.questions VALUES (712, 12, 'g9-geo-poly-q3-12', 3, 12, 'hard', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 6, KC = 10 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,157.2 34.0,62.8 286.0,62.8 286.0,157.2"/><text x="21.8" y="166.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="21.8" y="63.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.2" y="63.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="298.2" y="166.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="157.2" x2="128.5" y2="62.8" stroke-dasharray="5 4"/><text x="137.7" y="58.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "56", "B": "24", "C": "44", "D": "32", "E": "52"}'::jsonb, 'C', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 6. BC = 16. P = 2(6 + 16) = 44.');
INSERT INTO public.questions VALUES (713, 12, 'g9-geo-poly-q3-13', 3, 13, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 20 və 8, yan tərəfi 15 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="49.4,186.0 270.6,186.0 204.2,34.0 115.8,34.0"/><text x="38.7" y="198.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="281.3" y="198.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="210.8" y="27.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="109.2" y="27.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="249.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="70.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><line x1="49.4" y1="186.0" x2="204.2" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√589", "B": "√385", "C": "√386", "D": "17", "E": "15"}'::jsonb, 'B', NULL, 'Hündürlük: h² = 15² − ((20 − 8)/2)² = 189. Diaqonalın proyeksiyası (20 + 8)/2 = 14. d = √(189 + 196) = √385.');
INSERT INTO public.questions VALUES (714, 12, 'g9-geo-poly-q3-14', 3, 14, 'hard', 'open', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 4, KC = 4 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 34.0,47.0 286.0,47.0 286.0,173.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.4" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.6" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="173.0" x2="160.0" y2="47.0" stroke-dasharray="5 4"/><text x="169.2" y="42.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', NULL, NULL, '24', '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 4. BC = 8. P = 2(4 + 8) = 24.');
INSERT INTO public.questions VALUES (715, 12, 'g9-geo-poly-q3-15', 3, 15, 'hard', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 5040° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "810", "B": "434", "C": "27", "D": "405", "E": "420"}'::jsonb, 'D', NULL, '180°(n − 2) = 5040° ⇒ n = 30. Diaqonallar: n(n − 3)/2 = 405.');
INSERT INTO public.questions VALUES (716, 12, 'g9-geo-poly-q3-16', 3, 16, 'hard', 'single', 'Paraleloqramın tərəfləri 5 və 13, aralarındakı bucaq 60° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="82.4,186.0 149.9,186.0 237.6,34.0 170.1,34.0"/><text x="73.1" y="200.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="148.2" y="203.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="246.9" y="29.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="171.8" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="110.1" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="114.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><path d="M100.4,186.0 A18,18 0 0 0 91.4,170.4" stroke-width="1.2"/><text x="109.2" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="82.4" y1="186.0" x2="237.6" y2="34.0" stroke-dasharray="5 4"/><line x1="149.9" y1="186.0" x2="170.1" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√194", "B": "2√97", "C": "√259", "D": "√129", "E": "18"}'::jsonb, 'D', NULL, 'Kosinuslar teoremi: d² = 5² + 13² ∓ 2·5·13·cos 60°. Böyük diaqonal √259, kiçik diaqonal √129. Cavab: √129.');
INSERT INTO public.questions VALUES (717, 12, 'g9-geo-poly-q3-17', 3, 17, 'hard', 'single', 'Rombun diaqonalları 12 və 16 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="45.6"/></svg>', '{"A": "5", "B": "29/5", "C": "24/5", "D": "48/5", "E": "12/5"}'::jsonb, 'C', NULL, 'Tərəf 10. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 96/20 = 24/5.');
INSERT INTO public.questions VALUES (718, 12, 'g9-geo-poly-q3-18', 3, 18, 'hard', 'single', 'Rombun diaqonalları 6 və 8 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="45.6"/></svg>', '{"A": "12/5", "B": "6/5", "C": "24/5", "D": "5/2", "E": "17/5"}'::jsonb, 'A', NULL, 'Tərəf 5. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 24/10 = 12/5.');
INSERT INTO public.questions VALUES (719, 12, 'g9-geo-poly-q3-19', 3, 19, 'hard', 'single', 'Rombun diaqonalları 28 və 96 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 182.2,110.0 160.0,186.0 137.8,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="195.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="124.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="182.2" y1="110.0" x2="137.8" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="21.3"/></svg>', '{"A": "25", "B": "672/25", "C": "336/25", "D": "168/25", "E": "361/25"}'::jsonb, 'C', NULL, 'Tərəf 50. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 1344/100 = 336/25.');
INSERT INTO public.questions VALUES (720, 12, 'g9-geo-poly-q3-20', 3, 20, 'hard', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 150° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "60", "B": "9", "C": "65", "D": "54", "E": "108"}'::jsonb, 'D', NULL, 'Xarici bucaq 180° − 150° = 30°, n = 360 : 30 = 12. Diaqonallar: n(n − 3)/2 = 54.');
INSERT INTO public.questions VALUES (721, 13, 'g9-geo-circle-q1-01', 1, 1, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 7, EB = 5, CE = 10 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="94.7" y1="148.8" x2="225.3" y2="148.8"/><line x1="195.4" y1="42.7" x2="162.3" y2="186.0"/><circle cx="170.9" cy="148.8" r="2.6" fill="currentColor"/><text x="83.5" y="160.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="236.5" y="160.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="201.4" y="36.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="162.7" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="170.9" y="140.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "12", "B": "24", "C": "29/2", "D": "27/2", "E": "7/2"}'::jsonb, 'D', NULL, 'AE·EB = CE·ED ⇒ ED = 7/2. CD = 10 + 7/2 = 27/2.');
INSERT INTO public.questions VALUES (722, 13, 'g9-geo-circle-q1-02', 1, 2, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 7, EB = 6, CE = 2 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="123.3" y1="43.4" x2="196.7" y2="43.4"/><line x1="156.5" y1="34.1" x2="229.1" y2="141.7"/><circle cx="162.8" cy="43.4" r="2.6" fill="currentColor"/><text x="117.0" y="37.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="203.0" y="37.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="155.9" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="240.9" y="152.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="162.8" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "21", "B": "22", "C": "7/3", "D": "11", "E": "12/7"}'::jsonb, 'A', NULL, 'AE·EB = CE·ED ⇒ ED = 7·6/2 = 21.');
INSERT INTO public.questions VALUES (723, 13, 'g9-geo-circle-q1-03', 1, 3, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√7 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "28π", "B": "8π", "C": "14π", "D": "7π/2", "E": "7π"}'::jsonb, 'E', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 7. Halqanın sahəsi π(R² − r²) = 7π.');
INSERT INTO public.questions VALUES (724, 13, 'g9-geo-circle-q1-04', 1, 4, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 4, PB = 16 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="181.3" cy="110.0" r="76.0"/><line x1="62.7" y1="136.6" x2="252.5" y2="136.6"/><line x1="62.7" y1="136.6" x2="122.0" y2="62.5"/><circle cx="62.7" cy="136.6" r="2.6" fill="currentColor"/><text x="49.7" y="141.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="98.0" y="146.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="264.7" y="146.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="111.9" y="59.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "8", "B": "10", "C": "4√15", "D": "4√3", "E": "√65"}'::jsonb, 'A', NULL, 'PT² = PA·PB = 4·16 = 64 ⇒ PT = 8.');
INSERT INTO public.questions VALUES (725, 13, 'g9-geo-circle-q1-05', 1, 5, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 2 : 6 : 1 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 173.2,35.2 218.2,158.9"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="175.5" y="27.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="228.2" y="172.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "120°", "B": "240°", "C": "20°", "D": "130°", "E": "40°"}'::jsonb, 'A', NULL, 'Qövslər: 80°, 240°, 40°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 240°/2 = 120°.');
INSERT INTO public.questions VALUES (726, 13, 'g9-geo-circle-q1-06', 1, 6, 'hard', 'single', 'Radiusu 5 olan çevrədə uzunluğu 6 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="160.0" y1="110.0" x2="160.0" y2="49.2" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="205.6" y2="49.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "8", "B": "1", "C": "4", "D": "2", "E": "5"}'::jsonb, 'C', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(5² − 3²) = 4.');
INSERT INTO public.questions VALUES (727, 13, 'g9-geo-circle-q1-07', 1, 7, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 6 : 7 : 2 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 98.5,65.3 210.9,166.5"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="88.0" y="62.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="219.6" y="181.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "84°", "B": "24°", "C": "72°", "D": "168°", "E": "94°"}'::jsonb, 'A', NULL, 'Qövslər: 144°, 168°, 48°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 168°/2 = 84°.');
INSERT INTO public.questions VALUES (728, 13, 'g9-geo-circle-q1-08', 1, 8, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 7 : 2 : 9 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 101.8,61.1 84.0,110.0"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="91.8" y="57.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="71.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "70°", "B": "180°", "C": "100°", "D": "20°", "E": "90°"}'::jsonb, 'E', NULL, 'Qövslər: 140°, 40°, 180°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 180°/2 = 90°.');
INSERT INTO public.questions VALUES (729, 13, 'g9-geo-circle-q1-09', 1, 9, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 1, PB = 25 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="162.1" cy="110.0" r="76.0"/><line x1="81.9" y1="127.3" x2="236.1" y2="127.3"/><line x1="81.9" y1="127.3" x2="87.2" y2="97.0"/><circle cx="81.9" cy="127.3" r="2.6" fill="currentColor"/><text x="68.9" y="132.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="75.4" y="135.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.7" y="135.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="74.4" y="99.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "5", "B": "4√39", "C": "2√6", "D": "√26", "E": "13"}'::jsonb, 'A', NULL, 'PT² = PA·PB = 1·25 = 25 ⇒ PT = 5.');
INSERT INTO public.questions VALUES (730, 13, 'g9-geo-circle-q1-10', 1, 10, 'hard', 'single', 'Radiusu 10 olan çevrədə uzunluğu 16 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><line x1="160.0" y1="110.0" x2="160.0" y2="64.4" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="220.8" y2="64.4"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "2", "B": "5", "C": "18", "D": "6", "E": "7"}'::jsonb, 'D', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(10² − 8²) = 6.');
INSERT INTO public.questions VALUES (731, 13, 'g9-geo-circle-q1-11', 1, 11, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 21 və 72 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="138.7,183.0 181.3,183.0 138.7,37.0"/><text x="135.1" y="200.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="187.8" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="136.8" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="148.7,183.0 148.7,173.0 138.7,173.0" stroke-width="1.2"/><circle cx="157.0" cy="164.7" r="18.2"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.7" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text><text x="132.7" y="104.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">72</text></svg>', '{"A": "25/6", "B": "25/3", "C": "31/6", "D": "25/31", "E": "6/25"}'::jsonb, 'A', NULL, 'c = 75, R = 75/2, r = (a + b − c)/2 = 9. R : r = 25/6.');
INSERT INTO public.questions VALUES (732, 13, 'g9-geo-circle-q1-12', 1, 12, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 14 və 48 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="138.7,183.0 181.3,183.0 138.7,37.0"/><text x="135.1" y="200.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="187.8" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="136.8" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="148.7,183.0 148.7,173.0 138.7,173.0" stroke-width="1.2"/><circle cx="157.0" cy="164.7" r="18.2"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.7" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="132.7" y="104.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">48</text></svg>', '{"A": "6/25", "B": "31/6", "C": "25/31", "D": "25/3", "E": "25/6"}'::jsonb, 'E', NULL, 'c = 50, R = 25, r = (a + b − c)/2 = 6. R : r = 25/6.');
INSERT INTO public.questions VALUES (733, 13, 'g9-geo-circle-q1-13', 1, 13, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 8 : 3 : 9 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 98.5,65.3 87.7,133.5"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="88.0" y="62.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="75.4" y="142.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "81°", "B": "72°", "C": "162°", "D": "91°", "E": "27°"}'::jsonb, 'A', NULL, 'Qövslər: 144°, 54°, 162°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 162°/2 = 81°.');
INSERT INTO public.questions VALUES (734, 13, 'g9-geo-circle-q1-14', 1, 14, 'hard', 'open', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 4, EB = 8, CE = 6 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="84.9" y1="121.5" x2="235.1" y2="121.5"/><line x1="114.3" y1="49.3" x2="153.4" y2="185.7"/><circle cx="135.0" cy="121.5" r="2.6" fill="currentColor"/><text x="72.0" y="128.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.0" y="128.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="106.4" y="43.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="152.2" y="203.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="135.0" y="113.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', NULL, NULL, '34/3', 'AE·EB = CE·ED ⇒ ED = 16/3. CD = 6 + 16/3 = 34/3.');
INSERT INTO public.questions VALUES (735, 13, 'g9-geo-circle-q1-15', 1, 15, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 8√13 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "209π", "B": "832π", "C": "416π", "D": "104π", "E": "208π"}'::jsonb, 'E', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 208. Halqanın sahəsi π(R² − r²) = 208π.');
INSERT INTO public.questions VALUES (736, 13, 'g9-geo-circle-q1-16', 1, 16, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 9 və 12 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.4,170.8 205.6,170.8 114.4,49.2"/><text x="106.6" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="216.4" y="183.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="109.8" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="124.4,170.8 124.4,160.8 114.4,160.8" stroke-width="1.2"/><circle cx="144.8" cy="140.4" r="30.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="164.2" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="104.4" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "2/5", "B": "5", "C": "7/2", "D": "5/7", "E": "5/2"}'::jsonb, 'E', NULL, 'c = 15, R = 15/2, r = (a + b − c)/2 = 3. R : r = 5/2.');
INSERT INTO public.questions VALUES (737, 13, 'g9-geo-circle-q1-17', 1, 17, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 6, PB = 24 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="184.9" cy="110.0" r="76.0"/><line x1="59.1" y1="118.5" x2="260.4" y2="118.5"/><line x1="59.1" y1="118.5" x2="135.1" y2="52.6"/><circle cx="59.1" cy="118.5" r="2.6" fill="currentColor"/><text x="46.1" y="123.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="96.5" y="125.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="273.4" y="125.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="126.6" y="47.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "12", "B": "6√3", "C": "15", "D": "√145", "E": "6√15"}'::jsonb, 'A', NULL, 'PT² = PA·PB = 6·24 = 144 ⇒ PT = 12.');
INSERT INTO public.questions VALUES (738, 13, 'g9-geo-circle-q1-18', 1, 18, 'hard', 'single', 'Radiusu 26 olan çevrədə uzunluğu 20 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="130.8" y1="39.8" x2="189.2" y2="39.8"/><line x1="160.0" y1="110.0" x2="160.0" y2="39.8" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="189.2" y2="39.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "24", "B": "36", "C": "23", "D": "25", "E": "16"}'::jsonb, 'A', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(26² − 10²) = 24.');
INSERT INTO public.questions VALUES (739, 13, 'g9-geo-circle-q1-19', 1, 19, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 12√5 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "181π", "B": "180π", "C": "360π", "D": "720π", "E": "90π"}'::jsonb, 'B', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 180. Halqanın sahəsi π(R² − r²) = 180π.');
INSERT INTO public.questions VALUES (740, 13, 'g9-geo-circle-q1-20', 1, 20, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 13, EB = 7, CE = 3 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="176.5" y1="35.8" x2="144.9" y2="184.5"/><circle cx="173.7" cy="49.2" r="2.6" fill="currentColor"/><text x="106.6" y="43.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.4" y="43.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="179.3" y="28.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="142.3" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="173.7" y="41.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "91/3", "B": "21/13", "C": "94/3", "D": "39/7", "E": "17"}'::jsonb, 'A', NULL, 'AE·EB = CE·ED ⇒ ED = 13·7/3 = 91/3.');
INSERT INTO public.questions VALUES (741, 13, 'g9-geo-circle-q2-01', 2, 1, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 8, EB = 13, CE = 2 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="138.0" y1="37.3" x2="182.0" y2="37.3"/><line x1="157.5" y1="34.0" x2="84.8" y2="120.7"/><circle cx="154.8" cy="37.3" r="2.6" fill="currentColor"/><text x="134.2" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="185.8" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="157.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="71.9" y="127.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="154.8" y="29.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "42/13", "B": "52", "C": "54", "D": "21", "E": "55"}'::jsonb, 'C', NULL, 'AE·EB = CE·ED ⇒ ED = 52. CD = 2 + 52 = 54.');
INSERT INTO public.questions VALUES (742, 13, 'g9-geo-circle-q2-02', 2, 2, 'hard', 'single', 'Radiusu 25 olan çevrədə uzunluğu 30 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="160.0" y1="110.0" x2="160.0" y2="49.2" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="205.6" y2="49.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "20", "B": "10", "C": "5", "D": "40", "E": "21"}'::jsonb, 'A', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(25² − 15²) = 20.');
INSERT INTO public.questions VALUES (743, 13, 'g9-geo-circle-q2-03', 2, 3, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 5 və 12 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="130.8,180.2 189.2,180.2 130.8,39.8"/><text x="125.8" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="197.6" y="195.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="128.1" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="140.8,180.2 140.8,170.2 130.8,170.2" stroke-width="1.2"/><circle cx="154.2" cy="156.8" r="23.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="162.4" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="123.1" y="105.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "4/13", "B": "13/17", "C": "13/4", "D": "13/2", "E": "17/4"}'::jsonb, 'C', NULL, 'c = 13, R = 13/2, r = (a + b − c)/2 = 2. R : r = 13/4.');
INSERT INTO public.questions VALUES (744, 13, 'g9-geo-circle-q2-04', 2, 4, 'hard', 'single', 'Dairəvi sektorun qövsünün uzunluğu 35π/3, radiusu 14 olarsa, sektorun sahəsini tapın.', NULL, NULL, '{"A": "490π/3", "B": "245π/3", "C": "35π/6", "D": "248π/3", "E": "245π/6"}'::jsonb, 'B', NULL, 'Qövs: πRα/180 = 35π/3 ⇒ α = 150°. S = πR²α/360 = 245π/3. (və ya S = L·R/2)');
INSERT INTO public.questions VALUES (745, 13, 'g9-geo-circle-q2-05', 2, 5, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 21 və 72 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="138.7,183.0 181.3,183.0 138.7,37.0"/><text x="135.1" y="200.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="187.8" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="136.8" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="148.7,183.0 148.7,173.0 138.7,173.0" stroke-width="1.2"/><circle cx="157.0" cy="164.7" r="18.2"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.7" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text><text x="132.7" y="104.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">72</text></svg>', '{"A": "93", "B": "84", "C": "47", "D": "93/2", "E": "95/2"}'::jsonb, 'D', NULL, 'Hipotenuz 75. r = (a + b − c)/2 = 9, R = c/2 = 75/2. Cəm: 93/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (746, 13, 'g9-geo-circle-q2-06', 2, 6, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 5 : 6 : 9 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 160.0,34.0 87.7,133.5"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="75.4" y="142.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "81°", "B": "162°", "C": "91°", "D": "45°", "E": "54°"}'::jsonb, 'A', NULL, 'Qövslər: 90°, 108°, 162°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 162°/2 = 81°.');
INSERT INTO public.questions VALUES (747, 13, 'g9-geo-circle-q2-07', 2, 7, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√87 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "174π", "B": "88π", "C": "348π", "D": "87π", "E": "87π/2"}'::jsonb, 'D', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 87. Halqanın sahəsi π(R² − r²) = 87π.');
INSERT INTO public.questions VALUES (748, 13, 'g9-geo-circle-q2-08', 2, 8, 'hard', 'single', 'Radiusu 20 olan çevrədə uzunluğu 24 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="160.0" y1="110.0" x2="160.0" y2="49.2" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="205.6" y2="49.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "16", "B": "17", "C": "8", "D": "4", "E": "32"}'::jsonb, 'A', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(20² − 12²) = 16.');
INSERT INTO public.questions VALUES (749, 13, 'g9-geo-circle-q2-09', 2, 9, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 3 : 8 : 1 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 160.0,34.0 225.8,148.0"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.1" y="159.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "120°", "B": "240°", "C": "45°", "D": "15°", "E": "130°"}'::jsonb, 'A', NULL, 'Qövslər: 90°, 240°, 30°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 240°/2 = 120°.');
INSERT INTO public.questions VALUES (750, 13, 'g9-geo-circle-q2-10', 2, 10, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 7 : 8 : 5 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 115.3,48.5 160.0,186.0"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="107.7" y="43.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "144°", "B": "63°", "C": "82°", "D": "45°", "E": "72°"}'::jsonb, 'E', NULL, 'Qövslər: 126°, 144°, 90°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 144°/2 = 72°.');
INSERT INTO public.questions VALUES (751, 13, 'g9-geo-circle-q2-11', 2, 11, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 8, PB = 32 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="185.2" cy="110.0" r="76.0"/><line x1="58.8" y1="115.5" x2="261.0" y2="115.5"/><line x1="58.8" y1="115.5" x2="136.9" y2="51.3"/><circle cx="58.8" cy="115.5" r="2.6" fill="currentColor"/><text x="45.8" y="120.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="96.4" y="121.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="273.9" y="121.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="128.6" y="46.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√257", "B": "20", "C": "8√3", "D": "8√15", "E": "16"}'::jsonb, 'E', NULL, 'PT² = PA·PB = 8·32 = 256 ⇒ PT = 16.');
INSERT INTO public.questions VALUES (752, 13, 'g9-geo-circle-q2-12', 2, 12, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 2, PB = 18 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="168.2" cy="110.0" r="76.0"/><line x1="75.8" y1="127.6" x2="242.2" y2="127.6"/><line x1="75.8" y1="127.6" x2="99.5" y2="77.4"/><circle cx="75.8" cy="127.6" r="2.6" fill="currentColor"/><text x="62.8" y="132.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="81.6" y="135.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="254.8" y="135.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="87.8" y="76.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√37", "B": "6", "C": "8√5", "D": "10", "E": "4√2"}'::jsonb, 'B', NULL, 'PT² = PA·PB = 2·18 = 36 ⇒ PT = 6.');
INSERT INTO public.questions VALUES (753, 13, 'g9-geo-circle-q2-13', 2, 13, 'hard', 'single', 'Dairəvi sektorun qövsünün uzunluğu 9π/2, radiusu 3 olarsa, sektorun sahəsini tapın.', NULL, NULL, '{"A": "27π/8", "B": "9π/4", "C": "27π/2", "D": "31π/4", "E": "27π/4"}'::jsonb, 'E', NULL, 'Qövs: πRα/180 = 9π/2 ⇒ α = 270°. S = πR²α/360 = 27π/4. (və ya S = L·R/2)');
INSERT INTO public.questions VALUES (754, 13, 'g9-geo-circle-q2-14', 2, 14, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 6 : 4 : 8 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 122.0,44.2 88.6,136.0"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="115.5" y="37.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="76.4" y="145.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "80°", "B": "40°", "C": "90°", "D": "160°", "E": "60°"}'::jsonb, 'A', NULL, 'Qövslər: 120°, 80°, 160°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 160°/2 = 80°.');
INSERT INTO public.questions VALUES (755, 13, 'g9-geo-circle-q2-15', 2, 15, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 4, EB = 5, CE = 6 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="87.3" y1="132.0" x2="232.7" y2="132.0"/><line x1="146.8" y1="35.1" x2="154.7" y2="185.8"/><circle cx="151.9" cy="132.0" r="2.6" fill="currentColor"/><text x="74.8" y="140.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.2" y="140.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="144.6" y="27.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="153.8" y="203.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="151.9" y="124.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "54/5", "B": "9", "C": "10/3", "D": "31/3", "E": "28/3"}'::jsonb, 'E', NULL, 'AE·EB = CE·ED ⇒ ED = 10/3. CD = 6 + 10/3 = 28/3.');
INSERT INTO public.questions VALUES (756, 13, 'g9-geo-circle-q2-16', 2, 16, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 10, EB = 14, CE = 2 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="135.1" y1="38.2" x2="184.9" y2="38.2"/><line x1="156.4" y1="34.1" x2="135.6" y2="182.0"/><circle cx="155.9" cy="38.2" r="2.6" fill="currentColor"/><text x="130.8" y="30.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="189.2" y="30.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="155.8" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="131.5" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="155.9" y="30.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "73", "B": "70", "C": "72", "D": "24", "E": "24/7"}'::jsonb, 'C', NULL, 'AE·EB = CE·ED ⇒ ED = 70. CD = 2 + 70 = 72.');
INSERT INTO public.questions VALUES (757, 13, 'g9-geo-circle-q2-17', 2, 17, 'hard', 'single', 'Radiusu 13 olan çevrədə uzunluğu 24 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="89.8" y1="80.8" x2="230.2" y2="80.8"/><line x1="160.0" y1="110.0" x2="160.0" y2="80.8" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="230.2" y2="80.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "6", "B": "11", "C": "25", "D": "5", "E": "1"}'::jsonb, 'D', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(13² − 12²) = 5.');
INSERT INTO public.questions VALUES (758, 13, 'g9-geo-circle-q2-18', 2, 18, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 18 və 80 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="143.3,184.1 176.7,184.1 143.3,35.9"/><text x="140.5" y="201.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="182.0" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="141.9" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="153.3,184.1 153.3,174.1 143.3,174.1" stroke-width="1.2"/><circle cx="158.1" cy="169.3" r="14.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.3" y="201.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="138.4" y="104.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">80</text></svg>', '{"A": "8/41", "B": "41/4", "C": "41/49", "D": "41/8", "E": "49/8"}'::jsonb, 'D', NULL, 'c = 82, R = 41, r = (a + b − c)/2 = 8. R : r = 41/8.');
INSERT INTO public.questions VALUES (759, 13, 'g9-geo-circle-q2-19', 2, 19, 'hard', 'single', 'Dairəvi sektorun qövsünün uzunluğu 28π/9, radiusu 14 olarsa, sektorun sahəsini tapın.', NULL, NULL, '{"A": "14π/9", "B": "205π/9", "C": "196π/9", "D": "98π/9", "E": "392π/9"}'::jsonb, 'C', NULL, 'Qövs: πRα/180 = 28π/9 ⇒ α = 40°. S = πR²α/360 = 196π/9. (və ya S = L·R/2)');
INSERT INTO public.questions VALUES (760, 13, 'g9-geo-circle-q2-20', 2, 20, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 4, PB = 25 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="170.4" cy="110.0" r="76.0"/><line x1="73.6" y1="139.3" x2="240.6" y2="139.3"/><line x1="73.6" y1="139.3" x2="101.3" y2="78.5"/><circle cx="73.6" cy="139.3" r="2.6" fill="currentColor"/><text x="60.6" y="144.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="88.3" y="149.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="252.6" y="149.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="89.4" y="78.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "10", "B": "2√21", "C": "√101", "D": "√609", "E": "29/2"}'::jsonb, 'A', NULL, 'PT² = PA·PB = 4·25 = 100 ⇒ PT = 10.');
INSERT INTO public.questions VALUES (761, 13, 'g9-geo-circle-q3-01', 3, 1, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√17 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "18π", "B": "17π/2", "C": "17π", "D": "34π", "E": "68π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 17. Halqanın sahəsi π(R² − r²) = 17π.');
INSERT INTO public.questions VALUES (762, 13, 'g9-geo-circle-q3-02', 3, 2, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 14, EB = 11, CE = 4 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="129.0" y1="40.6" x2="191.0" y2="40.6"/><line x1="156.2" y1="34.1" x2="235.7" y2="103.2"/><circle cx="163.7" cy="40.6" r="2.6" fill="currentColor"/><text x="123.7" y="33.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="196.3" y="33.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="155.6" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="248.6" y="107.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="163.7" y="32.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "87/2", "B": "85/2", "C": "25", "D": "77/2", "E": "100/11"}'::jsonb, 'B', NULL, 'AE·EB = CE·ED ⇒ ED = 77/2. CD = 4 + 77/2 = 85/2.');
INSERT INTO public.questions VALUES (763, 13, 'g9-geo-circle-q3-03', 3, 3, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 1, PB = 4 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="162.6" cy="110.0" r="76.0"/><line x1="81.4" y1="168.3" x2="211.4" y2="168.3"/><line x1="81.4" y1="168.3" x2="86.9" y2="103.5"/><circle cx="81.4" cy="168.3" r="2.6" fill="currentColor"/><text x="68.4" y="173.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="105.5" y="183.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="219.8" y="183.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="74.0" y="107.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√15", "B": "√3", "C": "2", "D": "5/2", "E": "√5"}'::jsonb, 'C', NULL, 'PT² = PA·PB = 1·4 = 4 ⇒ PT = 2.');
INSERT INTO public.questions VALUES (764, 13, 'g9-geo-circle-q3-04', 3, 4, 'hard', 'single', 'Radiusu 15 olan çevrədə uzunluğu 24 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><line x1="160.0" y1="110.0" x2="160.0" y2="64.4" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="220.8" y2="64.4"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "10", "B": "27", "C": "3", "D": "9", "E": "8"}'::jsonb, 'D', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(15² − 12²) = 9.');
INSERT INTO public.questions VALUES (765, 13, 'g9-geo-circle-q3-05', 3, 5, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 7 : 5 : 8 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 115.3,48.5 98.5,154.7"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="107.7" y="43.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="88.0" y="167.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "144°", "B": "45°", "C": "72°", "D": "63°", "E": "82°"}'::jsonb, 'C', NULL, 'Qövslər: 126°, 90°, 144°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 144°/2 = 72°.');
INSERT INTO public.questions VALUES (766, 13, 'g9-geo-circle-q3-06', 3, 6, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 8 və 15 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="124.2,177.1 195.8,177.1 124.2,42.9"/><text x="118.1" y="193.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="205.2" y="191.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="120.9" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="134.2,177.1 134.2,167.1 124.2,167.1" stroke-width="1.2"/><circle cx="151.1" cy="150.2" r="26.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="163.1" y="193.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="115.5" y="106.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "17/6", "B": "23/6", "C": "17/23", "D": "17/3", "E": "6/17"}'::jsonb, 'A', NULL, 'c = 17, R = 17/2, r = (a + b − c)/2 = 3. R : r = 17/6.');
INSERT INTO public.questions VALUES (767, 13, 'g9-geo-circle-q3-07', 3, 7, 'hard', 'open', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 1, PB = 9 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="164.5" cy="110.0" r="76.0"/><line x1="79.5" y1="143.8" x2="232.6" y2="143.8"/><line x1="79.5" y1="143.8" x2="90.3" y2="93.9"/><circle cx="79.5" cy="143.8" r="2.6" fill="currentColor"/><text x="66.5" y="148.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="84.8" y="154.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="244.3" y="154.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="77.6" y="96.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', NULL, NULL, '3', 'PT² = PA·PB = 1·9 = 9 ⇒ PT = 3.');
INSERT INTO public.questions VALUES (768, 13, 'g9-geo-circle-q3-08', 3, 8, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 15, EB = 6, CE = 3 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.6" y1="49.0" x2="205.4" y2="49.0"/><line x1="188.1" y1="39.4" x2="92.7" y2="145.3"/><circle cx="179.4" cy="49.0" r="2.6" fill="currentColor"/><text x="106.9" y="43.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.1" y="43.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="192.9" y="32.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="81.2" y="156.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="179.4" y="41.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "6/5", "B": "15/2", "C": "31", "D": "30", "E": "18"}'::jsonb, 'D', NULL, 'AE·EB = CE·ED ⇒ ED = 15·6/3 = 30.');
INSERT INTO public.questions VALUES (769, 13, 'g9-geo-circle-q3-09', 3, 9, 'hard', 'single', 'Dairəvi sektorun qövsünün uzunluğu 8π/3, radiusu 12 olarsa, sektorun sahəsini tapın.', NULL, NULL, '{"A": "16π", "B": "32π", "C": "8π", "D": "17π", "E": "4π/3"}'::jsonb, 'A', NULL, 'Qövs: πRα/180 = 8π/3 ⇒ α = 40°. S = πR²α/360 = 16π. (və ya S = L·R/2)');
INSERT INTO public.questions VALUES (770, 13, 'g9-geo-circle-q3-10', 3, 10, 'hard', 'single', 'Dairəvi sektorun qövsünün uzunluğu 24π/5, radiusu 12 olarsa, sektorun sahəsini tapın.', NULL, NULL, '{"A": "72π/5", "B": "12π/5", "C": "149π/5", "D": "144π/5", "E": "288π/5"}'::jsonb, 'D', NULL, 'Qövs: πRα/180 = 24π/5 ⇒ α = 72°. S = πR²α/360 = 144π/5. (və ya S = L·R/2)');
INSERT INTO public.questions VALUES (771, 13, 'g9-geo-circle-q3-11', 3, 11, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 10 və 24 olarsa, xarici çəkilmiş çevrənin radiusunun daxili çəkilmiş çevrənin radiusuna nisbətini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="130.8,180.2 189.2,180.2 130.8,39.8"/><text x="125.8" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="197.6" y="195.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="128.1" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="140.8,180.2 140.8,170.2 130.8,170.2" stroke-width="1.2"/><circle cx="154.2" cy="156.8" r="23.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="162.4" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="123.1" y="105.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text></svg>', '{"A": "13/17", "B": "17/4", "C": "4/13", "D": "13/2", "E": "13/4"}'::jsonb, 'E', NULL, 'c = 26, R = 13, r = (a + b − c)/2 = 4. R : r = 13/4.');
INSERT INTO public.questions VALUES (772, 13, 'g9-geo-circle-q3-12', 3, 12, 'hard', 'single', 'Radiusu 15 olan çevrədə uzunluğu 18 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="160.0" y1="110.0" x2="160.0" y2="49.2" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="205.6" y2="49.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "24", "B": "3", "C": "12", "D": "13", "E": "6"}'::jsonb, 'C', NULL, 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(15² − 9²) = 12.');
INSERT INTO public.questions VALUES (773, 13, 'g9-geo-circle-q3-13', 3, 13, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 5, EB = 3, CE = 9 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="109.6" y1="166.9" x2="210.4" y2="166.9"/><line x1="85.7" y1="94.0" x2="188.7" y2="180.4"/><circle cx="172.6" cy="166.9" r="2.6" fill="currentColor"/><text x="101.0" y="181.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="219.0" y="181.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="73.0" y="96.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="193.6" y="197.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="172.6" y="158.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "8", "B": "35/3", "C": "5/3", "D": "32/3", "E": "24"}'::jsonb, 'D', NULL, 'AE·EB = CE·ED ⇒ ED = 5/3. CD = 9 + 5/3 = 32/3.');
INSERT INTO public.questions VALUES (774, 13, 'g9-geo-circle-q3-14', 3, 14, 'hard', 'open', 'Radiusu 10 olan çevrədə uzunluğu 12 olan vətər çəkilib. Çevrənin mərkəzindən vətərə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="160.0" y1="110.0" x2="160.0" y2="49.2" stroke-dasharray="5 4"/><line x1="160.0" y1="110.0" x2="205.6" y2="49.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="160.0" y="128.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', NULL, NULL, '8', 'Mərkəzdən vətərə perpendikulyar vətəri yarıya bölür: d = √(10² − 6²) = 8.');
INSERT INTO public.questions VALUES (775, 13, 'g9-geo-circle-q3-15', 3, 15, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 9, PB = 16 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="223.2" cy="110.0" r="62.8"/><line x1="34.0" y1="143.8" x2="276.1" y2="143.8"/><line x1="34.0" y1="143.8" x2="192.5" y2="55.2"/><circle cx="34.0" cy="143.8" r="2.6" fill="currentColor"/><text x="21.0" y="148.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="159.2" y="155.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="287.1" y="155.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="186.1" y="48.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "25/2", "B": "√145", "C": "12", "D": "3√7", "E": "5√7"}'::jsonb, 'C', NULL, 'PT² = PA·PB = 9·16 = 144 ⇒ PT = 12.');
INSERT INTO public.questions VALUES (776, 13, 'g9-geo-circle-q3-16', 3, 16, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 8 və 15 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="124.2,177.1 195.8,177.1 124.2,42.9"/><text x="118.1" y="193.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="205.2" y="191.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="120.9" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="134.2,177.1 134.2,167.1 124.2,167.1" stroke-width="1.2"/><circle cx="151.1" cy="150.2" r="26.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="163.1" y="193.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="115.5" y="106.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "23/2", "B": "23", "C": "12", "D": "25/2", "E": "20"}'::jsonb, 'A', NULL, 'Hipotenuz 17. r = (a + b − c)/2 = 3, R = c/2 = 17/2. Cəm: 23/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (777, 13, 'g9-geo-circle-q3-17', 3, 17, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 1 : 6 : 3 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 221.5,65.3 136.5,182.3"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="232.0" y="62.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="132.5" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "216°", "B": "108°", "C": "54°", "D": "18°", "E": "118°"}'::jsonb, 'B', NULL, 'Qövslər: 36°, 216°, 108°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 216°/2 = 108°.');
INSERT INTO public.questions VALUES (778, 13, 'g9-geo-circle-q3-18', 3, 18, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 3, PB = 12 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="181.0" cy="110.0" r="76.0"/><line x1="63.0" y1="137.7" x2="251.8" y2="137.7"/><line x1="63.0" y1="137.7" x2="121.1" y2="63.3"/><circle cx="63.0" cy="137.7" r="2.6" fill="currentColor"/><text x="50.0" y="142.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="98.1" y="147.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="263.9" y="147.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="110.8" y="60.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "6", "B": "3√15", "C": "√37", "D": "3√3", "E": "15/2"}'::jsonb, 'A', NULL, 'PT² = PA·PB = 3·12 = 36 ⇒ PT = 6.');
INSERT INTO public.questions VALUES (779, 13, 'g9-geo-circle-q3-19', 3, 19, 'hard', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 9 : 5 : 1 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 98.5,154.7 229.4,140.9"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="88.0" y="167.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="241.3" y="151.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "216°", "B": "12°", "C": "118°", "D": "60°", "E": "108°"}'::jsonb, 'E', NULL, 'Qövslər: 216°, 120°, 24°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 216°/2 = 108°.');
INSERT INTO public.questions VALUES (780, 13, 'g9-geo-circle-q3-20', 3, 20, 'hard', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 5, EB = 7, CE = 7 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="84.4" y1="117.7" x2="235.6" y2="117.7"/><line x1="187.4" y1="39.1" x2="118.8" y2="173.9"/><circle cx="147.4" cy="117.7" r="2.6" fill="currentColor"/><text x="71.5" y="124.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.5" y="124.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="192.1" y="32.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="111.7" y="189.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="147.4" y="109.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "6", "B": "4", "C": "49/5", "D": "35/8", "E": "5"}'::jsonb, 'E', NULL, 'AE·EB = CE·ED ⇒ ED = 5·7/7 = 5.');
INSERT INTO public.questions VALUES (781, 14, 'g9-geo-trig-q1-01', 1, 1, 'hard', 'single', 'tg α = 5 olarsa, (4sin α + 2cos α) / (4sin α + 2cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9/11", "B": "11/9", "C": "−1", "D": "2", "E": "1"}'::jsonb, 'E', NULL, 'Surəti və məxrəci cos α-ya bölün: (4·tg α + 2)/(4·tg α − (−2)) = (20 + 2)/(20 − (−2)) = 1.');
INSERT INTO public.questions VALUES (782, 14, 'g9-geo-trig-q1-02', 1, 2, 'hard', 'single', 'sin α = 5/13 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−109/60", "B": "−169/60", "C": "119/60", "D": "169/60", "E": "−119/60"}'::jsonb, 'B', NULL, 'cos α = −√(1 − 25/169) = −12/13 (rüb işarəsinə görə). tg α + ctg α = −169/60.');
INSERT INTO public.questions VALUES (783, 14, 'g9-geo-trig-q1-03', 1, 3, 'hard', 'single', 'tg α = −3 olarsa, (3sin α − 5cos α) / (sin α + 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−18/11", "B": "2", "C": "14", "D": "−4", "E": "−14"}'::jsonb, 'E', NULL, 'Surəti və məxrəci cos α-ya bölün: (3·tg α + (−5))/(1·tg α − (−4)) = (−9 + (−5))/(−3 − (−4)) = −14.');
INSERT INTO public.questions VALUES (784, 14, 'g9-geo-trig-q1-04', 1, 4, 'hard', 'single', 'ABC üçbucağında BC = 6, ∠A = 30°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 223.0,55.4"/><text x="21.4" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,164.6 A18,18 0 0 0 49.6,155.6" stroke-width="1.2"/><text x="63.9" y="161.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M277.0,149.0 A18,18 0 0 0 268.0,164.6" stroke-width="1.2"/><text x="259.2" y="154.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="266.1" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text></svg>', '{"A": "6√3", "B": "6", "C": "2√3", "D": "3√3", "E": "7√3"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 6·sin 60°/sin 30° = 6√3.');
INSERT INTO public.questions VALUES (785, 14, 'g9-geo-trig-q1-05', 1, 5, 'hard', 'single', 'tg α = 5/4 olarsa, (sin α − 5cos α) / (4sin α + 5cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−21/41", "B": "13/8", "C": "3/8", "D": "−3/8", "E": "5/8"}'::jsonb, 'D', NULL, 'Surəti və məxrəci cos α-ya bölün: (1·tg α + (−5))/(4·tg α − (−5)) = (5/4 + (−5))/(5 − (−5)) = −3/8.');
INSERT INTO public.questions VALUES (786, 14, 'g9-geo-trig-q1-06', 1, 6, 'hard', 'single', 'sin α = 20/29 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "41/420", "B": "−421/420", "C": "841/420", "D": "−41/420", "E": "−841/420"}'::jsonb, 'E', NULL, 'cos α = −√(1 − 400/841) = −21/29 (rüb işarəsinə görə). tg α + ctg α = −841/420.');
INSERT INTO public.questions VALUES (787, 14, 'g9-geo-trig-q1-07', 1, 7, 'hard', 'open', 'tg α = 5/4 olarsa, (sin α + 5cos α) / (sin α + 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '25/21', 'Surəti və məxrəci cos α-ya bölün: (1·tg α + 5)/(1·tg α − (−4)) = (5/4 + 5)/(5/4 − (−4)) = 25/21.');
INSERT INTO public.questions VALUES (788, 14, 'g9-geo-trig-q1-08', 1, 8, 'hard', 'single', 'sin α = 3/5 və π/2 < α < π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1/2", "B": "4/3", "C": "−4/3", "D": "3/4", "E": "−3/4"}'::jsonb, 'E', NULL, 'cos α = −√(1 − 9/25) = −4/5 (rüb işarəsinə görə). tg α = −3/4.');
INSERT INTO public.questions VALUES (789, 14, 'g9-geo-trig-q1-09', 1, 9, 'hard', 'single', 'ABC üçbucağında BC = 8, ∠A = 45°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 160.0,47.0"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,173.0 A18,18 0 0 0 46.7,160.3" stroke-width="1.2"/><text x="62.6" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M273.3,160.3 A18,18 0 0 0 268.0,173.0" stroke-width="1.2"/><text x="257.4" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="234.4" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "16", "B": "9", "C": "8√2", "D": "8", "E": "7"}'::jsonb, 'D', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 8·sin 45°/sin 45° = 8.');
INSERT INTO public.questions VALUES (790, 14, 'g9-geo-trig-q1-10', 1, 10, 'hard', 'single', 'ABC üçbucağında AB = 8, AC = 11, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="140.1,186.0 267.7,186.0 52.3,34.0"/><text x="136.8" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="279.6" y="196.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="43.1" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="212.4" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="85.2" y="110.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><path d="M158.1,186.0 A18,18 0 0 0 131.1,170.4" stroke-width="1.2"/><text x="155.6" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "4", "B": "√97", "C": "19", "D": "√273", "E": "√185"}'::jsonb, 'D', NULL, 'BC² = 11² + 8² − 2·11·8·cos 120° = 273 ⇒ BC = √273.');
INSERT INTO public.questions VALUES (791, 14, 'g9-geo-trig-q1-11', 1, 11, 'hard', 'single', 'ABC üçbucağında AB = 3, AC = 5, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="151.2,186.0 256.5,186.0 63.5,34.0"/><text x="149.7" y="203.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="268.1" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="54.6" y="29.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="212.0" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="96.7" y="109.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M169.2,186.0 A18,18 0 0 0 142.2,170.4" stroke-width="1.2"/><text x="166.7" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "7", "B": "√19", "C": "8", "D": "√34", "E": "3"}'::jsonb, 'A', NULL, 'BC² = 5² + 3² − 2·5·3·cos 120° = 49 ⇒ BC = 7.');
INSERT INTO public.questions VALUES (792, 14, 'g9-geo-trig-q1-12', 1, 12, 'hard', 'single', 'ABC üçbucağında AB = 3, AC = 12, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="116.1,186.0 160.0,186.0 203.9,34.0"/><text x="107.6" y="200.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="209.0" y="27.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="133.3" y="202.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="160.0" y="103.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><path d="M134.1,186.0 A18,18 0 0 0 125.1,170.4" stroke-width="1.2"/><text x="143.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "2√29", "B": "3√17", "C": "3√13", "D": "3√21", "E": "10"}'::jsonb, 'C', NULL, 'BC² = 12² + 3² − 2·12·3·cos 60° = 117 ⇒ BC = 3√13.');
INSERT INTO public.questions VALUES (793, 14, 'g9-geo-trig-q1-13', 1, 13, 'hard', 'single', 'ABC üçbucağında BC = 10, ∠A = 45°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 160.0,47.0"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,173.0 A18,18 0 0 0 46.7,160.3" stroke-width="1.2"/><text x="62.6" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M273.3,160.3 A18,18 0 0 0 268.0,173.0" stroke-width="1.2"/><text x="257.4" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="234.4" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "20", "B": "10", "C": "11", "D": "10√2", "E": "9"}'::jsonb, 'B', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 10·sin 45°/sin 45° = 10.');
INSERT INTO public.questions VALUES (794, 14, 'g9-geo-trig-q1-14', 1, 14, 'hard', 'open', 'ABC üçbucağında BC = 13, ∠A = 45°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 160.0,47.0"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,173.0 A18,18 0 0 0 46.7,160.3" stroke-width="1.2"/><text x="62.6" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M273.3,160.3 A18,18 0 0 0 268.0,173.0" stroke-width="1.2"/><text x="257.4" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="234.4" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text></svg>', NULL, NULL, '13', 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 13·sin 45°/sin 45° = 13.');
INSERT INTO public.questions VALUES (795, 14, 'g9-geo-trig-q1-15', 1, 15, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 3, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="60.1,132.6 286.0,132.6 34.0,87.4"/><text x="47.4" y="140.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="138.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="21.6" y="88.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="184.4" y="141.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="35.1" y="113.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><path d="M78.1,132.6 A18,18 0 0 0 51.1,117.0" stroke-width="1.2"/><text x="75.6" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "√217", "B": "√139", "C": "16", "D": "11", "E": "√178"}'::jsonb, 'A', NULL, 'BC² = 3² + 13² − 2·3·13·cos 120° = 217 ⇒ BC = √217.');
INSERT INTO public.questions VALUES (796, 14, 'g9-geo-trig-q1-16', 1, 16, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 4, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="106.0,172.4 286.0,172.4 34.0,47.6"/><text x="97.5" y="187.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="181.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.7" y="44.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="205.5" y="184.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="58.5" y="111.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><path d="M124.0,172.4 A18,18 0 0 0 97.0,156.8" stroke-width="1.2"/><text x="121.5" y="150.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "√41", "B": "9", "C": "√61", "D": "2", "E": "√21"}'::jsonb, 'C', NULL, 'BC² = 4² + 5² − 2·4·5·cos 120° = 61 ⇒ BC = √61.');
INSERT INTO public.questions VALUES (797, 14, 'g9-geo-trig-q1-17', 1, 17, 'hard', 'single', 'ABC üçbucağında AB = 14, AC = 10, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="37.1,186.0 282.9,186.0 124.9,34.0"/><text x="25.3" y="196.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="295.0" y="195.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="122.0" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="162.7" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="69.8" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><path d="M55.1,186.0 A18,18 0 0 0 46.1,170.4" stroke-width="1.2"/><text x="64.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "2√39", "B": "2√74", "C": "√155", "D": "2√109", "E": "5"}'::jsonb, 'A', NULL, 'BC² = 10² + 14² − 2·10·14·cos 60° = 156 ⇒ BC = 2√39.');
INSERT INTO public.questions VALUES (798, 14, 'g9-geo-trig-q1-18', 1, 18, 'hard', 'single', 'tg α = 2 olarsa, (5sin α + 5cos α) / (sin α − 3cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−3", "B": "15", "C": "−5", "D": "−15", "E": "3"}'::jsonb, 'D', NULL, 'Surəti və məxrəci cos α-ya bölün: (5·tg α + 5)/(1·tg α − 3) = (10 + 5)/(2 − 3) = −15.');
INSERT INTO public.questions VALUES (799, 14, 'g9-geo-trig-q1-19', 1, 19, 'hard', 'single', 'ABC üçbucağında BC = 12, ∠A = 30°, ∠B = 120°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,182.7 202.0,182.7 286.0,37.3"/><text x="21.7" y="192.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="208.5" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="295.8" y="33.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,182.7 A18,18 0 0 0 49.6,173.7" stroke-width="1.2"/><text x="63.9" y="179.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M211.0,167.2 A18,18 0 0 0 184.0,182.7" stroke-width="1.2"/><text x="186.5" y="160.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><text x="255.3" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "4√3", "B": "12√3", "C": "12", "D": "6√3", "E": "13√3"}'::jsonb, 'B', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 12·sin 120°/sin 30° = 12√3.');
INSERT INTO public.questions VALUES (800, 14, 'g9-geo-trig-q1-20', 1, 20, 'hard', 'single', 'sin α = 8/17 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−169/120", "B": "289/120", "C": "161/120", "D": "−161/120", "E": "−289/120"}'::jsonb, 'E', NULL, 'cos α = −√(1 − 64/289) = −15/17 (rüb işarəsinə görə). tg α + ctg α = −289/120.');
INSERT INTO public.questions VALUES (801, 14, 'g9-geo-trig-q2-01', 2, 1, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 8, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="93.3,161.4 286.0,161.4 34.0,58.6"/><text x="83.0" y="174.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="169.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.1" y="56.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="199.7" y="173.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="52.0" y="112.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><path d="M111.3,161.4 A18,18 0 0 0 84.3,145.8" stroke-width="1.2"/><text x="108.8" y="139.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "6", "B": "21", "C": "√337", "D": "√233", "E": "√129"}'::jsonb, 'C', NULL, 'BC² = 8² + 13² − 2·8·13·cos 120° = 337 ⇒ BC = √337.');
INSERT INTO public.questions VALUES (802, 14, 'g9-geo-trig-q2-02', 2, 2, 'hard', 'single', 'ABC üçbucağında BC = 8, ∠A = 30°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 223.0,55.4"/><text x="21.4" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,164.6 A18,18 0 0 0 49.6,155.6" stroke-width="1.2"/><text x="63.9" y="161.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M277.0,149.0 A18,18 0 0 0 268.0,164.6" stroke-width="1.2"/><text x="259.2" y="154.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="266.1" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "8√3", "B": "4√3", "C": "8√3/3", "D": "9√3", "E": "8"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 8·sin 60°/sin 30° = 8√3.');
INSERT INTO public.questions VALUES (803, 14, 'g9-geo-trig-q2-03', 2, 3, 'hard', 'single', 'ABC üçbucağında BC = 7, ∠A = 30°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,156.1 286.0,156.1 193.8,63.9"/><text x="21.3" y="164.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="164.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="198.2" y="56.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,156.1 A18,18 0 0 0 49.6,147.1" stroke-width="1.2"/><text x="63.9" y="153.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M273.3,143.4 A18,18 0 0 0 268.0,156.1" stroke-width="1.2"/><text x="257.4" y="149.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="251.6" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "7", "B": "6√2", "C": "8√2", "D": "7√2/2", "E": "7√2"}'::jsonb, 'E', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 7·sin 45°/sin 30° = 7√2.');
INSERT INTO public.questions VALUES (804, 14, 'g9-geo-trig-q2-04', 2, 4, 'hard', 'single', 'tg α = 5/4 olarsa, (2sin α + 4cos α) / (sin α − 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "6/11", "B": "−26/11", "C": "26/11", "D": "26/21", "E": "−7/4"}'::jsonb, 'B', NULL, 'Surəti və məxrəci cos α-ya bölün: (2·tg α + 4)/(1·tg α − 4) = (5/2 + 4)/(5/4 − 4) = −26/11.');
INSERT INTO public.questions VALUES (805, 14, 'g9-geo-trig-q2-05', 2, 5, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 2, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,128.2 286.0,128.2 55.0,91.8"/><text x="21.1" y="134.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="299.0" y="134.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="42.7" y="92.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="171.3" y="137.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="32.5" y="114.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><path d="M52.0,128.2 A18,18 0 0 0 43.0,112.6" stroke-width="1.2"/><text x="60.8" y="117.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "2√37", "B": "√123", "C": "2√43", "D": "2√31", "E": "11"}'::jsonb, 'D', NULL, 'BC² = 2² + 12² − 2·2·12·cos 60° = 124 ⇒ BC = 2√31.');
INSERT INTO public.questions VALUES (806, 14, 'g9-geo-trig-q2-06', 2, 6, 'hard', 'single', 'ABC üçbucağında BC = 7, ∠A = 45°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 160.0,47.0"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,173.0 A18,18 0 0 0 46.7,160.3" stroke-width="1.2"/><text x="62.6" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M273.3,160.3 A18,18 0 0 0 268.0,173.0" stroke-width="1.2"/><text x="257.4" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="234.4" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "8", "B": "14", "C": "7√2", "D": "7", "E": "6"}'::jsonb, 'D', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 7·sin 45°/sin 45° = 7.');
INSERT INTO public.questions VALUES (807, 14, 'g9-geo-trig-q2-07', 2, 7, 'hard', 'open', 'tg α = −3 olarsa, (2sin α + 4cos α) / (2sin α + 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '1', 'Surəti və məxrəci cos α-ya bölün: (2·tg α + 4)/(2·tg α − (−4)) = (−6 + 4)/(−6 − (−4)) = 1.');
INSERT INTO public.questions VALUES (808, 14, 'g9-geo-trig-q2-08', 2, 8, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 3, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="62.0,134.2 286.0,134.2 34.0,85.8"/><text x="49.4" y="142.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="140.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="21.7" y="86.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="185.3" y="143.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="36.1" y="113.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><path d="M80.0,134.2 A18,18 0 0 0 53.0,118.7" stroke-width="1.2"/><text x="77.5" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "3√21", "B": "3√17", "C": "10", "D": "15", "E": "3√13"}'::jsonb, 'A', NULL, 'BC² = 3² + 12² − 2·3·12·cos 120° = 189 ⇒ BC = 3√21.');
INSERT INTO public.questions VALUES (809, 14, 'g9-geo-trig-q2-09', 2, 9, 'hard', 'single', 'cos α = −7/25 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "527/168", "B": "−527/168", "C": "−625/168", "D": "625/168", "E": "−457/168"}'::jsonb, 'C', NULL, 'sin α = √(1 − 49/625) = 24/25 (rüb işarəsinə görə). tg α + ctg α = −625/168.');
INSERT INTO public.questions VALUES (810, 14, 'g9-geo-trig-q2-10', 2, 10, 'hard', 'single', 'cos α = −9/41 və π/2 < α < π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−13/3", "B": "−40/9", "C": "40/9", "D": "9/40", "E": "−9/40"}'::jsonb, 'B', NULL, 'sin α = √(1 − 81/1681) = 40/41 (rüb işarəsinə görə). tg α = −40/9.');
INSERT INTO public.questions VALUES (811, 14, 'g9-geo-trig-q2-11', 2, 11, 'hard', 'single', 'tg α = 5/3 olarsa, (2sin α − cos α) / (4sin α + cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−7/23", "B": "7/23", "C": "13/23", "D": "1/17", "E": "7/17"}'::jsonb, 'B', NULL, 'Surəti və məxrəci cos α-ya bölün: (2·tg α + (−1))/(4·tg α − (−1)) = (10/3 + (−1))/(20/3 − (−1)) = 7/23.');
INSERT INTO public.questions VALUES (812, 14, 'g9-geo-trig-q2-12', 2, 12, 'hard', 'single', 'ABC üçbucağında BC = 2, ∠A = 45°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 192.1,34.0"/><text x="28.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="291.7" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="194.8" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 52.8,173.3" stroke-width="1.2"/><text x="68.8" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M270.9,170.4 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="253.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="247.2" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text></svg>', '{"A": "√6", "B": "2√6/3", "C": "2", "D": "2√6", "E": "2√3"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 2·sin 60°/sin 45° = √6.');
INSERT INTO public.questions VALUES (813, 14, 'g9-geo-trig-q2-13', 2, 13, 'hard', 'single', 'cos α = −3/5 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−7/12", "B": "−13/12", "C": "−25/12", "D": "25/12", "E": "7/12"}'::jsonb, 'C', NULL, 'sin α = √(1 − 9/25) = 4/5 (rüb işarəsinə görə). tg α + ctg α = −25/12.');
INSERT INTO public.questions VALUES (814, 14, 'g9-geo-trig-q2-14', 2, 14, 'hard', 'open', 'tg α = 3/4 olarsa, (sin α + cos α) / (4sin α + 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '1/4', 'Surəti və məxrəci cos α-ya bölün: (1·tg α + 1)/(4·tg α − (−4)) = (3/4 + 1)/(3 − (−4)) = 1/4.');
INSERT INTO public.questions VALUES (815, 14, 'g9-geo-trig-q2-15', 2, 15, 'hard', 'single', 'cos α = −20/29 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−41/420", "B": "841/420", "C": "−421/420", "D": "41/420", "E": "−841/420"}'::jsonb, 'E', NULL, 'sin α = √(1 − 400/841) = 21/29 (rüb işarəsinə görə). tg α + ctg α = −841/420.');
INSERT INTO public.questions VALUES (816, 14, 'g9-geo-trig-q2-16', 2, 16, 'hard', 'single', 'sin α = 8/17 və π/2 < α < π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "8/15", "B": "−15/8", "C": "15/8", "D": "−8/15", "E": "−7/15"}'::jsonb, 'D', NULL, 'cos α = −√(1 − 64/289) = −15/17 (rüb işarəsinə görə). tg α = −8/15.');
INSERT INTO public.questions VALUES (817, 14, 'g9-geo-trig-q2-17', 2, 17, 'hard', 'single', 'ABC üçbucağında AB = 7, AC = 4, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="90.0,158.5 286.0,158.5 34.0,61.5"/><text x="79.3" y="170.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="166.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.0" y="59.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="198.2" y="169.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="50.3" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><path d="M108.0,158.5 A18,18 0 0 0 81.0,142.9" stroke-width="1.2"/><text x="105.5" y="136.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "√65", "B": "√93", "C": "11", "D": "√37", "E": "4"}'::jsonb, 'B', NULL, 'BC² = 4² + 7² − 2·4·7·cos 120° = 93 ⇒ BC = √93.');
INSERT INTO public.questions VALUES (818, 14, 'g9-geo-trig-q2-18', 2, 18, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 2, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="52.0,125.6 286.0,125.6 34.0,94.4"/><text x="39.1" y="132.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="299.0" y="131.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="21.3" y="96.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="180.7" y="133.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="31.0" y="114.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><path d="M70.0,125.6 A18,18 0 0 0 43.0,110.0" stroke-width="1.2"/><text x="67.5" y="103.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "7√3", "B": "15", "C": "√199", "D": "√173", "E": "12"}'::jsonb, 'C', NULL, 'BC² = 2² + 13² − 2·2·13·cos 120° = 199 ⇒ BC = √199.');
INSERT INTO public.questions VALUES (819, 14, 'g9-geo-trig-q2-19', 2, 19, 'hard', 'single', 'tg α = −3/2 olarsa, (sin α + 2cos α) / (sin α + cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "4", "B": "7", "C": "1", "D": "−1", "E": "−1/5"}'::jsonb, 'D', NULL, 'Surəti və məxrəci cos α-ya bölün: (1·tg α + 2)/(1·tg α − (−1)) = (−3/2 + 2)/(−3/2 − (−1)) = −1.');
INSERT INTO public.questions VALUES (820, 14, 'g9-geo-trig-q2-20', 2, 20, 'hard', 'single', 'ABC üçbucağında BC = 11, ∠A = 60°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 127.9,34.0"/><text x="28.3" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="125.2" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 49.1,170.4" stroke-width="1.2"/><text x="67.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M267.2,173.3 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="251.2" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="214.8" y="109.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text></svg>', '{"A": "11√6/3", "B": "11", "C": "11√6/2", "D": "11√6", "E": "11√2"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 11·sin 45°/sin 60° = 11√6/3.');
INSERT INTO public.questions VALUES (821, 14, 'g9-geo-trig-q3-01', 3, 1, 'hard', 'single', 'sin α = 12/37 və π/2 < α < π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−35/12", "B": "−12/35", "C": "12/35", "D": "−11/35", "E": "35/12"}'::jsonb, 'B', NULL, 'cos α = −√(1 − 144/1369) = −35/37 (rüb işarəsinə görə). tg α = −12/35.');
INSERT INTO public.questions VALUES (822, 14, 'g9-geo-trig-q3-02', 3, 2, 'hard', 'single', 'tg α = 4/3 olarsa, (3sin α − 3cos α) / (2sin α − 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−21/4", "B": "3/10", "C": "3/4", "D": "−3/4", "E": "3/20"}'::jsonb, 'D', NULL, 'Surəti və məxrəci cos α-ya bölün: (3·tg α + (−3))/(2·tg α − 4) = (4 + (−3))/(8/3 − 4) = −3/4.');
INSERT INTO public.questions VALUES (823, 14, 'g9-geo-trig-q3-03', 3, 3, 'hard', 'single', 'ABC üçbucağında BC = 10, ∠A = 45°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 192.1,34.0"/><text x="28.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="291.7" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="194.8" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 52.8,173.3" stroke-width="1.2"/><text x="68.8" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M270.9,170.4 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="253.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="247.2" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "10√6", "B": "10√6/3", "C": "10√3", "D": "5√6", "E": "10"}'::jsonb, 'D', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 10·sin 60°/sin 45° = 5√6.');
INSERT INTO public.questions VALUES (824, 14, 'g9-geo-trig-q3-04', 3, 4, 'hard', 'single', 'tg α = −1 olarsa, (2sin α − 3cos α) / (3sin α + 2cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1", "B": "5", "C": "−5", "D": "1", "E": "1/5"}'::jsonb, 'B', NULL, 'Surəti və məxrəci cos α-ya bölün: (2·tg α + (−3))/(3·tg α − (−2)) = (−2 + (−3))/(−3 − (−2)) = 5.');
INSERT INTO public.questions VALUES (825, 14, 'g9-geo-trig-q3-05', 3, 5, 'hard', 'single', 'sin α = 20/29 və π/2 < α < π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "21/20", "B": "−20/21", "C": "−21/20", "D": "−19/21", "E": "20/21"}'::jsonb, 'B', NULL, 'cos α = −√(1 − 400/841) = −21/29 (rüb işarəsinə görə). tg α = −20/21.');
INSERT INTO public.questions VALUES (826, 14, 'g9-geo-trig-q3-06', 3, 6, 'hard', 'single', 'tg α = −1 olarsa, (4sin α + 2cos α) / (5sin α − 5cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "5", "B": "1/5", "C": "−1/5", "D": "11/5", "E": "3/5"}'::jsonb, 'B', NULL, 'Surəti və məxrəci cos α-ya bölün: (4·tg α + 2)/(5·tg α − 5) = (−4 + 2)/(−5 − 5) = 1/5.');
INSERT INTO public.questions VALUES (827, 14, 'g9-geo-trig-q3-07', 3, 7, 'hard', 'single', 'ABC üçbucağında BC = 6, ∠A = 60°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 127.9,34.0"/><text x="28.3" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="125.2" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 49.1,170.4" stroke-width="1.2"/><text x="67.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M267.2,173.3 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="251.2" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="214.8" y="109.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text></svg>', '{"A": "6√2", "B": "6√6", "C": "3√6", "D": "2√6", "E": "6"}'::jsonb, 'D', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 6·sin 45°/sin 60° = 2√6.');
INSERT INTO public.questions VALUES (828, 14, 'g9-geo-trig-q3-08', 3, 8, 'hard', 'single', 'ABC üçbucağında BC = 9, ∠A = 30°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,156.1 286.0,156.1 193.8,63.9"/><text x="21.3" y="164.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="164.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="198.2" y="56.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,156.1 A18,18 0 0 0 49.6,147.1" stroke-width="1.2"/><text x="63.9" y="153.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M273.3,143.4 A18,18 0 0 0 268.0,156.1" stroke-width="1.2"/><text x="257.4" y="149.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="251.6" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text></svg>', '{"A": "9√2", "B": "9", "C": "8√2", "D": "10√2", "E": "9√2/2"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 9·sin 45°/sin 30° = 9√2.');
INSERT INTO public.questions VALUES (829, 14, 'g9-geo-trig-q3-09', 3, 9, 'hard', 'single', 'tg α = −4 olarsa, (3sin α − 5cos α) / (2sin α − cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "7/9", "B": "−17/9", "C": "17/7", "D": "17/9", "E": "23/6"}'::jsonb, 'D', NULL, 'Surəti və məxrəci cos α-ya bölün: (3·tg α + (−5))/(2·tg α − 1) = (−12 + (−5))/(−8 − 1) = 17/9.');
INSERT INTO public.questions VALUES (830, 14, 'g9-geo-trig-q3-10', 3, 10, 'hard', 'single', 'tg α = −5/4 olarsa, (5sin α − 5cos α) / (5sin α − 3cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9/7", "B": "5/37", "C": "45/13", "D": "−45/37", "E": "45/37"}'::jsonb, 'E', NULL, 'Surəti və məxrəci cos α-ya bölün: (5·tg α + (−5))/(5·tg α − 3) = (−25/4 + (−5))/(−25/4 − 3) = 45/37.');
INSERT INTO public.questions VALUES (831, 14, 'g9-geo-trig-q3-11', 3, 11, 'hard', 'single', 'tg α = −7/2 olarsa, (sin α − 3cos α) / (2sin α − 2cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "13/10", "B": "13/18", "C": "−13/18", "D": "1/18", "E": "23/18"}'::jsonb, 'B', NULL, 'Surəti və məxrəci cos α-ya bölün: (1·tg α + (−3))/(2·tg α − 2) = (−7/2 + (−3))/(−7 − 2) = 13/18.');
INSERT INTO public.questions VALUES (832, 14, 'g9-geo-trig-q3-12', 3, 12, 'hard', 'single', 'ABC üçbucağında BC = 6, ∠A = 60°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="72.2,186.0 247.8,186.0 160.0,34.0"/><text x="61.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="259.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M90.2,186.0 A18,18 0 0 0 81.2,170.4" stroke-width="1.2"/><text x="99.1" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M238.8,170.4 A18,18 0 0 0 229.8,186.0" stroke-width="1.2"/><text x="220.9" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="214.3" y="109.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text></svg>', '{"A": "12", "B": "6", "C": "6√3", "D": "7", "E": "9"}'::jsonb, 'B', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 6·sin 60°/sin 60° = 6.');
INSERT INTO public.questions VALUES (833, 14, 'g9-geo-trig-q3-13', 3, 13, 'hard', 'single', 'ABC üçbucağında BC = 14, ∠A = 30°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 223.0,55.4"/><text x="21.4" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,164.6 A18,18 0 0 0 49.6,155.6" stroke-width="1.2"/><text x="63.9" y="161.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M277.0,149.0 A18,18 0 0 0 268.0,164.6" stroke-width="1.2"/><text x="259.2" y="154.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="266.1" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "7√3", "B": "15√3", "C": "14", "D": "14√3/3", "E": "14√3"}'::jsonb, 'E', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 14·sin 60°/sin 30° = 14√3.');
INSERT INTO public.questions VALUES (834, 14, 'g9-geo-trig-q3-14', 3, 14, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 5, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,155.5 286.0,155.5 86.5,64.5"/><text x="21.5" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="163.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="78.3" y="59.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="167.5" y="169.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="48.5" y="112.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M52.0,155.5 A18,18 0 0 0 43.0,139.9" stroke-width="1.2"/><text x="60.8" y="145.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "6√3", "B": "8", "C": "13", "D": "√109", "E": "√229"}'::jsonb, 'D', NULL, 'BC² = 5² + 12² − 2·5·12·cos 60° = 109 ⇒ BC = √109.');
INSERT INTO public.questions VALUES (835, 14, 'g9-geo-trig-q3-15', 3, 15, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 7, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="97.3,186.0 222.7,186.0 185.1,34.0"/><text x="86.7" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="232.2" y="199.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.2" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.0" y="202.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="132.4" y="106.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><path d="M115.3,186.0 A18,18 0 0 0 106.3,170.4" stroke-width="1.2"/><text x="124.2" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "√39", "B": "√38", "C": "3", "D": "√109", "E": "√74"}'::jsonb, 'A', NULL, 'BC² = 7² + 5² − 2·7·5·cos 60° = 39 ⇒ BC = √39.');
INSERT INTO public.questions VALUES (836, 14, 'g9-geo-trig-q3-16', 3, 16, 'hard', 'single', 'cos α = −9/41 və π/2 < α < π olarsa, tg α + ctg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1321/360", "B": "−1681/360", "C": "1681/360", "D": "−1519/360", "E": "1519/360"}'::jsonb, 'B', NULL, 'sin α = √(1 − 81/1681) = 40/41 (rüb işarəsinə görə). tg α + ctg α = −1681/360.');
INSERT INTO public.questions VALUES (837, 14, 'g9-geo-trig-q3-17', 3, 17, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 9, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="112.2,177.7 286.0,177.7 34.0,42.3"/><text x="104.7" y="193.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="186.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.9" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="208.4" y="190.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="61.7" y="111.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><path d="M130.2,177.7 A18,18 0 0 0 103.2,162.1" stroke-width="1.2"/><text x="127.7" y="155.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "19", "B": "√181", "C": "√91", "D": "√271", "E": "2"}'::jsonb, 'D', NULL, 'BC² = 9² + 10² − 2·9·10·cos 120° = 271 ⇒ BC = √271.');
INSERT INTO public.questions VALUES (838, 14, 'g9-geo-trig-q3-18', 3, 18, 'hard', 'single', 'sin α = 9/41 və π/2 < α < π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9/40", "B": "−40/9", "C": "40/9", "D": "−1/5", "E": "−9/40"}'::jsonb, 'E', NULL, 'cos α = −√(1 − 81/1681) = −40/41 (rüb işarəsinə görə). tg α = −9/40.');
INSERT INTO public.questions VALUES (839, 14, 'g9-geo-trig-q3-19', 3, 19, 'hard', 'single', 'ABC üçbucağında AB = 11, AC = 6, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,169.5 286.0,169.5 102.7,50.5"/><text x="21.8" y="179.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="177.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="97.1" y="43.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.2" y="185.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="56.8" y="111.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M52.0,169.5 A18,18 0 0 0 43.0,153.9" stroke-width="1.2"/><text x="60.8" y="159.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "√223", "B": "3√10", "C": "√157", "D": "√91", "E": "6"}'::jsonb, 'D', NULL, 'BC² = 6² + 11² − 2·6·11·cos 60° = 91 ⇒ BC = √91.');
INSERT INTO public.questions VALUES (840, 14, 'g9-geo-trig-q3-20', 3, 20, 'hard', 'single', 'ABC üçbucağında AB = 8, AC = 2, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,137.3 286.0,137.3 65.5,82.7"/><text x="21.2" y="144.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="143.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="54.2" y="81.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="170.4" y="148.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="37.8" y="113.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><path d="M52.0,137.3 A18,18 0 0 0 43.0,121.7" stroke-width="1.2"/><text x="60.8" y="126.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "2√13", "B": "2√21", "C": "2√17", "D": "√51", "E": "7"}'::jsonb, 'A', NULL, 'BC² = 2² + 8² − 2·2·8·cos 60° = 52 ⇒ BC = 2√13.');
INSERT INTO public.questions VALUES (841, 15, 'g9-stat-avg-q1-01', 1, 1, 'hard', 'single', 'Sinifdəki 16 şagirdin orta balı 32,5 idi. Sinfə yeni şagird gəldikdən sonra orta bal 34 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "51/2", "B": "74", "C": "58", "D": "71/2", "E": "42"}'::jsonb, 'C', NULL, 'Əvvəlki cəm 16·32,5 = 520, yeni cəm 17·34 = 578. Fərq: 58.');
INSERT INTO public.questions VALUES (842, 15, 'g9-stat-avg-q1-02', 1, 2, 'hard', 'single', 'Sinifdəki 27 şagirdin orta balı 38 idi. Sinfə yeni şagird gəldikdən sonra orta bal 38,5 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "79", "B": "14", "C": "25", "D": "52", "E": "39"}'::jsonb, 'D', NULL, 'Əvvəlki cəm 27·38 = 1026, yeni cəm 28·38,5 = 1078. Fərq: 52.');
INSERT INTO public.questions VALUES (843, 15, 'g9-stat-avg-q1-03', 1, 3, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 2 — 5 dəfə; 3 — 7 dəfə; 4 — 9 dəfə; 6 — 8 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, '{"A": "10", "B": "9", "C": "7", "D": "231/29", "E": "8"}'::jsonb, 'E', NULL, 'n = 29, median = 4, moda = 4. Cəm: 8.');
INSERT INTO public.questions VALUES (844, 15, 'g9-stat-avg-q1-04', 1, 4, 'hard', 'single', 'Birinci qrupdakı 21 şagirdin orta balı 82, ikinci qrupdakı 6 şagirdin orta balı 67-dir. Bütün şagirdlərin orta balını tapın.', NULL, NULL, '{"A": "211/3", "B": "239/3", "C": "236/3", "D": "149/2", "E": "233/3"}'::jsonb, 'C', NULL, 'Ümumi cəm 21·82 + 6·67 = 2124, şagird sayı 27. Orta: 236/3.');
INSERT INTO public.questions VALUES (845, 15, 'g9-stat-avg-q1-05', 1, 5, 'hard', 'single', 'a və b ədədlərinin ədədi ortası 26,5, b və c-nin 36,5, a və c-nin isə 11. a, b, c ədədlərinin ədədi ortasını tapın.', NULL, NULL, '{"A": "77/3", "B": "74/3", "C": "71/3", "D": "37", "E": "74"}'::jsonb, 'B', NULL, 'a + b = 53, b + c = 73, a + c = 22. Toplasaq: 2(a + b + c) = 148, a + b + c = 74. Orta: 74/3.');
INSERT INTO public.questions VALUES (846, 15, 'g9-stat-avg-q1-06', 1, 6, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 2 — 1 dəfə; 5 — 3 dəfə; 7 — 4 dəfə; 10 — 8 dəfə. Balların ədədi ortası ilə medianının fərqini tapın.', NULL, NULL, '{"A": "5/16", "B": "−35/16", "C": "11/16", "D": "−11/16", "E": "−5/2"}'::jsonb, 'D', NULL, 'n = 16, orta = 125/16, median = 17/2. Fərq: −11/16.');
INSERT INTO public.questions VALUES (847, 15, 'g9-stat-avg-q1-07', 1, 7, 'hard', 'open', 'Testdə şagirdlərin balları belə paylanıb: 2 — 5 dəfə; 4 — 3 dəfə; 9 — 9 dəfə; 10 — 8 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, NULL, NULL, '18', 'n = 25, median = 9, moda = 9. Cəm: 18.');
