INSERT INTO public.questions VALUES (875, 15, 'g9-stat-avg-q2-15', 2, 15, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 5 — 4 dəfə; 7 — 4 dəfə; 9 — 3 dəfə; 10 — 9 dəfə. Balların ədədi ortası ilə medianının fərqini tapın.', NULL, NULL, '{"A": "−7/4", "B": "−3/4", "C": "−5/4", "D": "3/4", "E": "1/4"}'::jsonb, 'B', NULL, 'n = 20, orta = 33/4, median = 9. Fərq: −3/4.');
INSERT INTO public.questions VALUES (876, 15, 'g9-stat-avg-q2-16', 2, 16, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 6 — 6 dəfə; 7 — 8 dəfə; 8 — 9 dəfə; 9 — 8 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, '{"A": "15", "B": "31/2", "C": "16", "D": "484/31", "E": "17"}'::jsonb, 'C', NULL, 'n = 31, median = 8, moda = 8. Cəm: 16.');
INSERT INTO public.questions VALUES (877, 15, 'g9-stat-avg-q2-17', 2, 17, 'hard', 'single', 'a və b ədədlərinin ədədi ortası 40, b və c-nin 28, a və c-nin isə 32. a, b, c ədədlərinin ədədi ortasını tapın.', NULL, NULL, '{"A": "97/3", "B": "50", "C": "100", "D": "100/3", "E": "103/3"}'::jsonb, 'D', NULL, 'a + b = 80, b + c = 56, a + c = 64. Toplasaq: 2(a + b + c) = 200, a + b + c = 100. Orta: 100/3.');
INSERT INTO public.questions VALUES (878, 15, 'g9-stat-avg-q2-18', 2, 18, 'hard', 'single', 'Sinifdəki 8 şagirdin orta balı 37 idi. Sinfə yeni şagird gəldikdən sonra orta bal 42 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "74", "B": "82", "C": "47", "D": "45", "E": "90"}'::jsonb, 'B', NULL, 'Əvvəlki cəm 8·37 = 296, yeni cəm 9·42 = 378. Fərq: 82.');
INSERT INTO public.questions VALUES (879, 15, 'g9-stat-avg-q2-19', 2, 19, 'hard', 'single', 'Sinifdəki 30 şagirdin orta balı 56,5 idi. Sinfə yeni şagird gəldikdən sonra orta bal 57 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "72", "B": "102", "C": "115/2", "D": "42", "E": "31/2"}'::jsonb, 'A', NULL, 'Əvvəlki cəm 30·56,5 = 1695, yeni cəm 31·57 = 1767. Fərq: 72.');
INSERT INTO public.questions VALUES (880, 15, 'g9-stat-avg-q2-20', 2, 20, 'hard', 'single', 'Birinci qrupdakı 13 şagirdin orta balı 94, ikinci qrupdakı 26 şagirdin orta balı 65-dir. Bütün şagirdlərin orta balını tapın.', NULL, NULL, '{"A": "221/3", "B": "224/3", "C": "227/3", "D": "253/3", "E": "159/2"}'::jsonb, 'B', NULL, 'Ümumi cəm 13·94 + 26·65 = 2912, şagird sayı 39. Orta: 224/3.');
INSERT INTO public.questions VALUES (881, 15, 'g9-stat-avg-q3-01', 3, 1, 'hard', 'single', 'a və b ədədlərinin ədədi ortası 40,5, b və c-nin 14,5, a və c-nin isə 28. a, b, c ədədlərinin ədədi ortasını tapın.', NULL, NULL, '{"A": "83/3", "B": "86/3", "C": "83/2", "D": "80/3", "E": "83"}'::jsonb, 'A', NULL, 'a + b = 81, b + c = 29, a + c = 56. Toplasaq: 2(a + b + c) = 166, a + b + c = 83. Orta: 83/3.');
INSERT INTO public.questions VALUES (882, 15, 'g9-stat-avg-q3-02', 3, 2, 'hard', 'single', 'Sinifdəki 16 şagirdin orta balı 73 idi. Sinfə yeni şagird gəldikdən sonra orta bal 71 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "−34", "B": "55", "C": "69", "D": "23", "E": "39"}'::jsonb, 'E', NULL, 'Əvvəlki cəm 16·73 = 1168, yeni cəm 17·71 = 1207. Fərq: 39.');
INSERT INTO public.questions VALUES (883, 15, 'g9-stat-avg-q3-03', 3, 3, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 2 — 7 dəfə; 5 — 1 dəfə; 7 — 6 dəfə; 9 — 3 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, '{"A": "8", "B": "16", "C": "10", "D": "9", "E": "122/17"}'::jsonb, 'D', NULL, 'n = 17, median = 7, moda = 2. Cəm: 9.');
INSERT INTO public.questions VALUES (884, 15, 'g9-stat-avg-q3-04', 3, 4, 'hard', 'single', 'a və b ədədlərinin ədədi ortası 28, b və c-nin 28, a və c-nin isə 52. Bu üç ədəddən ən böyüyünü tapın.', NULL, NULL, '{"A": "108", "B": "52", "C": "53", "D": "51", "E": "54"}'::jsonb, 'B', NULL, 'a + b = 56, b + c = 56, a + c = 104. Toplasaq: 2(a + b + c) = 216, a + b + c = 108. a = 52, b = 4, c = 52. Ən böyüyü 52.');
INSERT INTO public.questions VALUES (885, 15, 'g9-stat-avg-q3-05', 3, 5, 'hard', 'single', 'Birinci qrupdakı 11 şagirdin orta balı 56, ikinci qrupdakı 9 şagirdin orta balı 91-dir. Bütün şagirdlərin orta balını tapın.', NULL, NULL, '{"A": "301/4", "B": "147/2", "C": "283/4", "D": "291/4", "E": "287/4"}'::jsonb, 'E', NULL, 'Ümumi cəm 11·56 + 9·91 = 1435, şagird sayı 20. Orta: 287/4.');
INSERT INTO public.questions VALUES (886, 15, 'g9-stat-avg-q3-06', 3, 6, 'hard', 'single', '38, 6, 34, 39, x ədədlərinin ədədi ortası medianına bərabərdir. x > 39 olarsa, x-i tapın.', NULL, NULL, '{"A": "72", "B": "78", "C": "74", "D": "38", "E": "73"}'::jsonb, 'E', NULL, 'x ən böyük ədəddirsə, median 38. (Cəm + x)/5 = 38 ⇒ x = 5·38 − 117 = 73.');
INSERT INTO public.questions VALUES (887, 15, 'g9-stat-avg-q3-07', 3, 7, 'hard', 'open', 'Testdə şagirdlərin balları belə paylanıb: 2 — 5 dəfə; 4 — 7 dəfə; 6 — 9 dəfə; 9 — 8 dəfə. Balların ədədi ortası ilə medianının fərqini tapın.', NULL, NULL, NULL, NULL, '−10/29', 'n = 29, orta = 164/29, median = 6. Fərq: −10/29.');
INSERT INTO public.questions VALUES (888, 15, 'g9-stat-avg-q3-08', 3, 8, 'hard', 'single', 'Birinci qrupdakı 26 şagirdin orta balı 60, ikinci qrupdakı 20 şagirdin orta balı 83-dür. Bütün şagirdlərin orta balını tapın.', NULL, NULL, '{"A": "73", "B": "143/2", "C": "69", "D": "70", "E": "71"}'::jsonb, 'D', NULL, 'Ümumi cəm 26·60 + 20·83 = 3220, şagird sayı 46. Orta: 70.');
INSERT INTO public.questions VALUES (889, 15, 'g9-stat-avg-q3-09', 3, 9, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 3 — 3 dəfə; 4 — 3 dəfə; 5 — 3 dəfə; 7 — 8 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, '{"A": "211/17", "B": "11", "C": "13", "D": "23/2", "E": "12"}'::jsonb, 'E', NULL, 'n = 17, median = 5, moda = 7. Cəm: 12.');
INSERT INTO public.questions VALUES (890, 15, 'g9-stat-avg-q3-10', 3, 10, 'hard', 'single', 'Sinifdəki 11 şagirdin orta balı 82 idi. Sinfə yeni şagird gəldikdən sonra orta bal 82,5 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "83", "B": "88", "C": "77", "D": "99", "E": "6"}'::jsonb, 'B', NULL, 'Əvvəlki cəm 11·82 = 902, yeni cəm 12·82,5 = 990. Fərq: 88.');
INSERT INTO public.questions VALUES (891, 15, 'g9-stat-avg-q3-11', 3, 11, 'hard', 'single', '18, 17, 19, 7, x ədədlərinin ədədi ortası medianına bərabərdir. x > 19 olarsa, x-i tapın.', NULL, NULL, '{"A": "30", "B": "29", "C": "28", "D": "34", "E": "18"}'::jsonb, 'B', NULL, 'x ən böyük ədəddirsə, median 18. (Cəm + x)/5 = 18 ⇒ x = 5·18 − 61 = 29.');
INSERT INTO public.questions VALUES (892, 15, 'g9-stat-avg-q3-12', 3, 12, 'hard', 'single', 'a və b ədədlərinin ədədi ortası 30,5, b və c-nin 34, a və c-nin isə 18,5. Bu üç ədəddən ən böyüyünü tapın.', NULL, NULL, '{"A": "83/2", "B": "45", "C": "47", "D": "83", "E": "46"}'::jsonb, 'E', NULL, 'a + b = 61, b + c = 68, a + c = 37. Toplasaq: 2(a + b + c) = 166, a + b + c = 83. a = 15, b = 46, c = 22. Ən böyüyü 46.');
INSERT INTO public.questions VALUES (893, 15, 'g9-stat-avg-q3-13', 3, 13, 'hard', 'single', 'Sinifdəki 25 şagirdin orta balı 80 idi. Sinfə yeni şagird gəldikdən sonra orta bal 80,5 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "118", "B": "81", "C": "13", "D": "93", "E": "68"}'::jsonb, 'D', NULL, 'Əvvəlki cəm 25·80 = 2000, yeni cəm 26·80,5 = 2093. Fərq: 93.');
INSERT INTO public.questions VALUES (894, 15, 'g9-stat-avg-q3-14', 3, 14, 'hard', 'open', 'Birinci qrupdakı 5 şagirdin orta balı 56, ikinci qrupdakı 15 şagirdin orta balı 52-dir. Bütün şagirdlərin orta balını tapın.', NULL, NULL, NULL, NULL, '53', 'Ümumi cəm 5·56 + 15·52 = 1060, şagird sayı 20. Orta: 53.');
INSERT INTO public.questions VALUES (895, 15, 'g9-stat-avg-q3-15', 3, 15, 'hard', 'single', '16, 3, 23, 27, x ədədlərinin ədədi ortası medianına bərabərdir. x > 27 olarsa, x-i tapın.', NULL, NULL, '{"A": "47", "B": "45", "C": "46", "D": "23", "E": "51"}'::jsonb, 'C', NULL, 'x ən böyük ədəddirsə, median 23. (Cəm + x)/5 = 23 ⇒ x = 5·23 − 69 = 46.');
INSERT INTO public.questions VALUES (896, 15, 'g9-stat-avg-q3-16', 3, 16, 'hard', 'single', 'Birinci qrupdakı 23 şagirdin orta balı 73, ikinci qrupdakı 5 şagirdin orta balı 87-dir. Bütün şagirdlərin orta balını tapın.', NULL, NULL, '{"A": "153/2", "B": "151/2", "C": "149/2", "D": "80", "E": "169/2"}'::jsonb, 'B', NULL, 'Ümumi cəm 23·73 + 5·87 = 2114, şagird sayı 28. Orta: 151/2.');
INSERT INTO public.questions VALUES (897, 15, 'g9-stat-avg-q3-17', 3, 17, 'hard', 'single', 'Testdə şagirdlərin balları belə paylanıb: 5 — 5 dəfə; 6 — 9 dəfə; 7 — 7 dəfə; 9 — 6 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, '{"A": "13", "B": "12", "C": "11", "D": "15", "E": "344/27"}'::jsonb, 'B', NULL, 'n = 27, median = 6, moda = 6. Cəm: 12.');
INSERT INTO public.questions VALUES (898, 15, 'g9-stat-avg-q3-18', 3, 18, 'hard', 'single', 'a və b ədədlərinin ədədi ortası 22, b və c-nin 16, a və c-nin isə 7. a, b, c ədədlərinin ədədi ortasını tapın.', NULL, NULL, '{"A": "14", "B": "16", "C": "45", "D": "45/2", "E": "15"}'::jsonb, 'E', NULL, 'a + b = 44, b + c = 32, a + c = 14. Toplasaq: 2(a + b + c) = 90, a + b + c = 45. Orta: 15.');
INSERT INTO public.questions VALUES (899, 15, 'g9-stat-avg-q3-19', 3, 19, 'hard', 'single', '5, 37, 34, 11, x ədədlərinin ədədi ortası medianına bərabərdir. x > 37 olarsa, x-i tapın.', NULL, NULL, '{"A": "83", "B": "88", "C": "34", "D": "84", "E": "82"}'::jsonb, 'A', NULL, 'x ən böyük ədəddirsə, median 34. (Cəm + x)/5 = 34 ⇒ x = 5·34 − 87 = 83.');
INSERT INTO public.questions VALUES (900, 15, 'g9-stat-avg-q3-20', 3, 20, 'hard', 'single', 'Sinifdəki 23 şagirdin orta balı 76 idi. Sinfə yeni şagird gəldikdən sonra orta bal 77 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "77", "B": "123", "C": "78", "D": "24", "E": "100"}'::jsonb, 'E', NULL, 'Əvvəlki cəm 23·76 = 1748, yeni cəm 24·77 = 1848. Fərq: 100.');
INSERT INTO public.questions VALUES (901, 16, 'g9-stat-prob-q1-01', 1, 1, 'hard', 'single', '6 nəfər, o cümlədən Anar və Bəhruz, təsadüfi qaydada bir cərgədə düzülür. Anar ilə Bəhruzun arasında düz bir nəfərin durması ehtimalını tapın.', NULL, NULL, '{"A": "1/6", "B": "11/15", "C": "8/15", "D": "2/5", "E": "4/15"}'::jsonb, 'E', NULL, 'Anar və Bəhruzun yer cütü (i, i + 2): 4 variant, 2 sıra, qalanlar 4! yolla. P = 4/15.');
INSERT INTO public.questions VALUES (902, 16, 'g9-stat-prob-q1-02', 1, 2, 'hard', 'single', 'Qutuda 4 qırmızı, 2 ağ, 6 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "32/495", "B": "16/495", "C": "1/4", "D": "4/495", "E": "8/81"}'::jsonb, 'A', NULL, 'Bütün hallar: C(12, 4) = 495. Əlverişli: C(4, 3)·C(8, 1) = 32. P = 32/495.');
INSERT INTO public.questions VALUES (903, 16, 'g9-stat-prob-q1-03', 1, 3, 'hard', 'single', 'Sinifdə 5 oğlan və 4 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "52/63", "B": "4/9", "C": "53/63", "D": "5/6", "E": "1/6"}'::jsonb, 'D', NULL, 'Tamamlayıcı: 0 qız — C(5, 5) = 1, 1 qız — 4·C(5, 4) = 20. P = 1 − (1 + 20)/126 = 5/6.');
INSERT INTO public.questions VALUES (904, 16, 'g9-stat-prob-q1-04', 1, 4, 'hard', 'single', '7 nəfər, o cümlədən Anar, Bəhruz və Cavid, təsadüfi qaydada bir cərgədə düzülür. Anarın Bəhruzdan, Bəhruzun isə Caviddən solda durması ehtimalını tapın (yan-yana olmaları vacib deyil).', NULL, NULL, '{"A": "1/7", "B": "1/3", "C": "1/42", "D": "1/6", "E": "5/6"}'::jsonb, 'D', NULL, 'Üç nəfərin qarşılıqlı düzülüşü 3! = 6 cür, onlardan biri əlverişlidir. P = 1/6.');
INSERT INTO public.questions VALUES (905, 16, 'g9-stat-prob-q1-05', 1, 5, 'hard', 'single', 'Qutuda 5 qırmızı və 8 ağ şar var. Qaytarmadan ardıcıl üç şar götürülür. Üç şarın eyni rəngdə olması ehtimalını tapın.', NULL, NULL, '{"A": "6/13", "B": "3/13", "C": "49/169", "D": "5/143", "E": "10/13"}'::jsonb, 'B', NULL, 'P = (5·4·3 + 8·7·6)/(13·12·11) = 3/13.');
INSERT INTO public.questions VALUES (906, 16, 'g9-stat-prob-q1-06', 1, 6, 'hard', 'single', 'Qutuda 8 qırmızı və 5 ağ şar var. Qaytarmadan ardıcıl iki şar götürülür. İkinci şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "8/13", "B": "2/3", "C": "5/13", "D": "7/12", "E": "14/39"}'::jsonb, 'A', NULL, 'Tam ehtimal: 8/13·7/12 + 5/13·8/12 = 8/13 (birinci şar haqqında məlumat olmadıqda ikinci şar da 8/13 ehtimalla qırmızıdır).');
INSERT INTO public.questions VALUES (907, 16, 'g9-stat-prob-q1-07', 1, 7, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,2; 0,9; 0,2. Atıcılardan ən azı birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,926", "B": "0,936", "C": "0,064", "D": "0,036", "E": "0,946"}'::jsonb, 'B', NULL, 'q = 1 − p: q₁ = 0,8, q₂ = 0,1, q₃ = 0,8. P = 1 − q₁q₂q₃ = 0,936.');
INSERT INTO public.questions VALUES (908, 16, 'g9-stat-prob-q1-08', 1, 8, 'hard', 'single', '1-dən 300-ə qədər natural ədədlərdən biri təsadüfi seçilir. Onun 10-a və ya 7-yə bölünməsi, lakin 5-ə bölünməməsi ehtimalını tapın.', NULL, NULL, '{"A": "17/75", "B": "1/25", "C": "7/60", "D": "17/150", "E": "6/25"}'::jsonb, 'D', NULL, 'Daxiletmə–xaricetmə: 10 və ya 7-yə bölünənlər 68, onlardan 5-ə də bölünənlər 34. Fərq 34. P = 17/150.');
INSERT INTO public.questions VALUES (909, 16, 'g9-stat-prob-q1-09', 1, 9, 'hard', 'single', 'Qutuda 3 qırmızı, 5 ağ, 5 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "27/143", "B": "3/26", "C": "3/715", "D": "5400/28561", "E": "27/286"}'::jsonb, 'A', NULL, 'Bütün hallar: C(13, 4) = 715. Əlverişli: C(3, 2)·C(10, 2) = 135. P = 27/143.');
INSERT INTO public.questions VALUES (910, 16, 'g9-stat-prob-q1-10', 1, 10, 'hard', 'single', '3 zər atılır. Düşən xalların hasilinin 6-ya bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "67/108", "B": "133/18", "C": "83/216", "D": "133/216", "E": "11/18"}'::jsonb, 'D', NULL, 'Hasil 6-ya bölünən hallar: 133, bütün hallar 216. P = 133/216.');
INSERT INTO public.questions VALUES (911, 16, 'g9-stat-prob-q1-11', 1, 11, 'hard', 'single', 'Sinifdə 8 oğlan və 7 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "22/65", "B": "902/1365", "C": "43/65", "D": "904/1365", "E": "7/15"}'::jsonb, 'C', NULL, 'Tamamlayıcı: 0 qız — C(8, 4) = 70, 1 qız — 7·C(8, 3) = 392. P = 1 − (70 + 392)/1365 = 43/65.');
INSERT INTO public.questions VALUES (912, 16, 'g9-stat-prob-q1-12', 1, 12, 'hard', 'single', '3 zər atılır. Düşən xallardan ən böyüyünün 5 olması ehtimalını tapın.', NULL, NULL, '{"A": "61/108", "B": "155/216", "C": "5/18", "D": "31/108", "E": "61/216"}'::jsonb, 'E', NULL, 'P(max ≤ 5) − P(max ≤ 4) = (5^3 − 4^3)/216 = 61/216. P = 61/216.');
INSERT INTO public.questions VALUES (913, 16, 'g9-stat-prob-q1-13', 1, 13, 'hard', 'single', '5 nəfər, o cümlədən Anar və Bəhruz, təsadüfi qaydada bir cərgədə düzülür. Anar ilə Bəhruzun yan-yana durması ehtimalını tapın.', NULL, NULL, '{"A": "1/5", "B": "1/4", "C": "2/5", "D": "4/5", "E": "3/5"}'::jsonb, 'C', NULL, 'Anar ilə Bəhruzu bir blok sayın: 2·4! hal. P = 2·4!/5! = 2/5. P = 2/5.');
INSERT INTO public.questions VALUES (914, 16, 'g9-stat-prob-q1-14', 1, 14, 'hard', 'open', '1-dən 90-a qədər natural ədədlərdən biri təsadüfi seçilir. Onun 9-a və ya 6-ya bölünməsi, lakin 7-yə bölünməməsi ehtimalını tapın.', NULL, NULL, NULL, NULL, '17/90', 'Daxiletmə–xaricetmə: 9 və ya 6-ya bölünənlər 20, onlardan 7-yə də bölünənlər 3. Fərq 17. P = 17/90.');
INSERT INTO public.questions VALUES (915, 16, 'g9-stat-prob-q1-15', 1, 15, 'hard', 'single', '1-dən 240-a qədər natural ədədlərdən biri təsadüfi seçilir. Onun 9-a və ya 3-ə bölünməsi, lakin 5-ə bölünməməsi ehtimalını tapın.', NULL, NULL, '{"A": "4/15", "B": "29/120", "C": "1/3", "D": "53/120", "E": "13/48"}'::jsonb, 'A', NULL, 'Daxiletmə–xaricetmə: 9 və ya 3-ə bölünənlər 80, onlardan 5-ə də bölünənlər 16. Fərq 64. P = 4/15.');
INSERT INTO public.questions VALUES (916, 16, 'g9-stat-prob-q1-16', 1, 16, 'hard', 'single', '3 zər atılır. Düşən xalların cəminin 10 olması ehtimalını tapın.', NULL, NULL, '{"A": "7/8", "B": "1/8", "C": "7/54", "D": "1/4", "E": "13/108"}'::jsonb, 'B', NULL, 'Cəmi 10 olan hallar: 27, bütün hallar 6^3 = 216. P = 1/8.');
INSERT INTO public.questions VALUES (917, 16, 'g9-stat-prob-q1-17', 1, 17, 'hard', 'single', 'Sinifdə 3 oğlan və 6 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "55/63", "B": "37/42", "C": "2/3", "D": "8/9", "E": "5/42"}'::jsonb, 'B', NULL, 'Tamamlayıcı: hamısı oğlan (0) və ya hamısı qız (15). P = 1 − 15/126 = 37/42.');
INSERT INTO public.questions VALUES (918, 16, 'g9-stat-prob-q1-18', 1, 18, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,4; 0,2; 0,4. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,446", "B": "0,032", "C": "0,456", "D": "0,466", "E": "0,544"}'::jsonb, 'C', NULL, 'q = 1 − p: q₁ = 0,6, q₂ = 0,8, q₃ = 0,6. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,456.');
INSERT INTO public.questions VALUES (919, 16, 'g9-stat-prob-q1-19', 1, 19, 'hard', 'single', 'Qutuda 4 qırmızı, 2 ağ, 5 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "14/165", "B": "3/11", "C": "2/165", "D": "1792/14641", "E": "7/165"}'::jsonb, 'A', NULL, 'Bütün hallar: C(11, 4) = 330. Əlverişli: C(4, 3)·C(7, 1) = 28. P = 14/165.');
INSERT INTO public.questions VALUES (920, 16, 'g9-stat-prob-q1-20', 1, 20, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,6; 0,9; 0,9. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,078", "B": "0,922", "C": "0,068", "D": "0,486", "E": "0,088"}'::jsonb, 'A', NULL, 'q = 1 − p: q₁ = 0,4, q₂ = 0,1, q₃ = 0,1. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,078.');
INSERT INTO public.questions VALUES (921, 16, 'g9-stat-prob-q2-01', 2, 1, 'hard', 'single', '3 zər atılır. Düşən xallardan ən böyüyünün 6 olması ehtimalını tapın.', NULL, NULL, '{"A": "23/54", "B": "91/108", "C": "91/216", "D": "5/12", "E": "125/216"}'::jsonb, 'C', NULL, 'P(max ≤ 6) − P(max ≤ 5) = (6^3 − 5^3)/216 = 91/216. P = 91/216.');
INSERT INTO public.questions VALUES (922, 16, 'g9-stat-prob-q2-02', 2, 2, 'hard', 'single', 'Sinifdə 6 oğlan və 9 qız var. Təsadüfi olaraq 3 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "8/35", "B": "27/35", "C": "10/13", "D": "352/455", "E": "3/5"}'::jsonb, 'B', NULL, 'Tamamlayıcı: hamısı oğlan (20) və ya hamısı qız (84). P = 1 − 104/455 = 27/35.');
INSERT INTO public.questions VALUES (923, 16, 'g9-stat-prob-q2-03', 2, 3, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,4; 0,4; 0,5. Atıcılardan ən azı birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,08", "B": "0,18", "C": "0,81", "D": "0,83", "E": "0,82"}'::jsonb, 'E', NULL, 'q = 1 − p: q₁ = 0,6, q₂ = 0,6, q₃ = 0,5. P = 1 − q₁q₂q₃ = 0,82.');
INSERT INTO public.questions VALUES (924, 16, 'g9-stat-prob-q2-04', 2, 4, 'hard', 'single', 'Sinifdə 7 oğlan və 5 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "35/36", "B": "5/12", "C": "257/264", "D": "769/792", "E": "1/36"}'::jsonb, 'A', NULL, 'Tamamlayıcı: hamısı oğlan (21) və ya hamısı qız (1). P = 1 − 22/792 = 35/36.');
INSERT INTO public.questions VALUES (925, 16, 'g9-stat-prob-q2-05', 2, 5, 'hard', 'single', 'Qutuda 4 qırmızı, 4 ağ, 6 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz birinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "240/1001", "B": "4/1001", "C": "1000/2401", "D": "480/1001", "E": "1/14"}'::jsonb, 'D', NULL, 'Bütün hallar: C(14, 4) = 1001. Əlverişli: C(4, 1)·C(10, 3) = 480. P = 480/1001.');
INSERT INTO public.questions VALUES (926, 16, 'g9-stat-prob-q2-06', 2, 6, 'hard', 'single', 'Qutuda 5 qırmızı, 2 ağ, 4 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "125/1331", "B": "5/11", "C": "1/33", "D": "2/33", "E": "1/15"}'::jsonb, 'D', NULL, 'Bütün hallar: C(11, 3) = 165. Əlverişli: C(5, 3)·C(6, 0) = 10. P = 2/33.');
INSERT INTO public.questions VALUES (927, 16, 'g9-stat-prob-q2-07', 2, 7, 'hard', 'open', '5 nəfər, o cümlədən Anar, Bəhruz və Cavid, təsadüfi qaydada bir cərgədə düzülür. Cavidin cərgənin kənarında durması, Anar ilə Bəhruzun isə yan-yana durmaması ehtimalını tapın.', NULL, NULL, NULL, NULL, '1/5', 'Cavid kənarda: 2 yol. Qalan 4 yerə 4 nəfər: 24, onlardan Anar və Bəhruzun yan-yana olduğu 2·3! = 12 hal çıxılır. P = 1/5.');
INSERT INTO public.questions VALUES (928, 16, 'g9-stat-prob-q2-08', 2, 8, 'hard', 'single', 'Qutuda 4 qırmızı və 3 ağ şar var. Qaytarmadan ardıcıl üç şar götürülür. Üç şarın eyni rəngdə olması ehtimalını tapın.', NULL, NULL, '{"A": "4/35", "B": "1/7", "C": "13/49", "D": "6/7", "E": "2/7"}'::jsonb, 'B', NULL, 'P = (4·3·2 + 3·2·1)/(7·6·5) = 1/7.');
INSERT INTO public.questions VALUES (929, 16, 'g9-stat-prob-q2-09', 2, 9, 'hard', 'single', '5 nəfər, o cümlədən Anar və Bəhruz, təsadüfi qaydada bir cərgədə düzülür. Anar ilə Bəhruzun arasında düz bir nəfərin durması ehtimalını tapın.', NULL, NULL, '{"A": "3/5", "B": "7/10", "C": "1/2", "D": "3/10", "E": "1/5"}'::jsonb, 'D', NULL, 'Anar və Bəhruzun yer cütü (i, i + 2): 3 variant, 2 sıra, qalanlar 3! yolla. P = 3/10.');
INSERT INTO public.questions VALUES (930, 16, 'g9-stat-prob-q2-10', 2, 10, 'hard', 'single', '1-dən 180-ə qədər natural ədədlərdən biri təsadüfi seçilir. Onun 7-yə və ya 6-ya bölünməsi, lakin 5-ə bölünməməsi ehtimalını tapın.', NULL, NULL, '{"A": "17/60", "B": "19/180", "C": "11/36", "D": "41/180", "E": "2/9"}'::jsonb, 'E', NULL, 'Daxiletmə–xaricetmə: 7 və ya 6-ya bölünənlər 51, onlardan 5-ə də bölünənlər 11. Fərq 40. P = 2/9.');
INSERT INTO public.questions VALUES (931, 16, 'g9-stat-prob-q2-11', 2, 11, 'hard', 'single', 'Sinifdə 5 oğlan və 3 qız var. Təsadüfi olaraq 3 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "17/56", "B": "5/7", "C": "15/56", "D": "2/7", "E": "3/8"}'::jsonb, 'D', NULL, 'Tamamlayıcı: 0 qız — C(5, 3) = 10, 1 qız — 3·C(5, 2) = 30. P = 1 − (10 + 30)/56 = 2/7.');
INSERT INTO public.questions VALUES (932, 16, 'g9-stat-prob-q2-12', 2, 12, 'hard', 'single', '3 zər atılır. Düşən xalların cəminin 5 olması ehtimalını tapın.', NULL, NULL, '{"A": "1/18", "B": "5/216", "C": "7/216", "D": "1/36", "E": "35/36"}'::jsonb, 'D', NULL, 'Cəmi 5 olan hallar: 6, bütün hallar 6^3 = 216. P = 1/36.');
INSERT INTO public.questions VALUES (933, 16, 'g9-stat-prob-q2-13', 2, 13, 'hard', 'single', 'Qutuda 4 qırmızı və 8 ağ şar var. Qaytarmadan ardıcıl üç şar götürülür. Üç şarın eyni rəngdə olması ehtimalını tapın.', NULL, NULL, '{"A": "3/11", "B": "1/3", "C": "6/11", "D": "1/55", "E": "8/11"}'::jsonb, 'A', NULL, 'P = (4·3·2 + 8·7·6)/(12·11·10) = 3/11.');
INSERT INTO public.questions VALUES (934, 16, 'g9-stat-prob-q2-14', 2, 14, 'hard', 'open', '1-dən 150-yə qədər natural ədədlərdən biri təsadüfi seçilir. Onun 4-ə və ya 7-yə bölünməsi, lakin 3-ə bölünməməsi ehtimalını tapın.', NULL, NULL, NULL, NULL, '7/30', 'Daxiletmə–xaricetmə: 4 və ya 7-yə bölünənlər 53, onlardan 3-ə də bölünənlər 18. Fərq 35. P = 7/30.');
INSERT INTO public.questions VALUES (935, 16, 'g9-stat-prob-q2-15', 2, 15, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,4; 0,3; 0,7. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,568", "B": "0,442", "C": "0,422", "D": "0,084", "E": "0,432"}'::jsonb, 'E', NULL, 'q = 1 − p: q₁ = 0,6, q₂ = 0,7, q₃ = 0,3. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,432.');
INSERT INTO public.questions VALUES (936, 16, 'g9-stat-prob-q2-16', 2, 16, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,5; 0,5; 0,2. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,05", "B": "0,46", "C": "0,55", "D": "0,45", "E": "0,44"}'::jsonb, 'D', NULL, 'q = 1 − p: q₁ = 0,5, q₂ = 0,5, q₃ = 0,8. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,45.');
INSERT INTO public.questions VALUES (937, 16, 'g9-stat-prob-q2-17', 2, 17, 'hard', 'single', 'Qutuda 4 qırmızı, 4 ağ, 3 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "21/110", "B": "21/55", "C": "1/55", "D": "2/11", "E": "4704/14641"}'::jsonb, 'B', NULL, 'Bütün hallar: C(11, 4) = 330. Əlverişli: C(4, 2)·C(7, 2) = 126. P = 21/55.');
INSERT INTO public.questions VALUES (938, 16, 'g9-stat-prob-q2-18', 2, 18, 'hard', 'single', 'Qutuda 5 qırmızı və 6 ağ şar var. Qaytarmadan ardıcıl üç şar götürülür. Üç şarın eyni rəngdə olması ehtimalını tapın.', NULL, NULL, '{"A": "2/33", "B": "9/11", "C": "4/11", "D": "31/121", "E": "2/11"}'::jsonb, 'E', NULL, 'P = (5·4·3 + 6·5·4)/(11·10·9) = 2/11.');
INSERT INTO public.questions VALUES (939, 16, 'g9-stat-prob-q2-19', 2, 19, 'hard', 'single', '3 zər atılır. Düşən xalların cəminin 15-dən kiçik olmaması ehtimalını tapın.', NULL, NULL, '{"A": "7/72", "B": "5/54", "C": "49/54", "D": "5/27", "E": "19/216"}'::jsonb, 'B', NULL, 'Cəmi ≥ 15 olan hallar: 20 (və ya tamamlayıcı hadisə ilə), bütün hallar 216. P = 5/54.');
INSERT INTO public.questions VALUES (940, 16, 'g9-stat-prob-q2-20', 2, 20, 'hard', 'single', '1-dən 200-ə qədər natural ədədlərdən biri təsadüfi seçilir. Onun 5-ə və ya 9-a bölünməsi, lakin 4-ə bölünməməsi ehtimalını tapın.', NULL, NULL, '{"A": "3/50", "B": "29/100", "C": "9/40", "D": "31/100", "E": "11/50"}'::jsonb, 'E', NULL, 'Daxiletmə–xaricetmə: 5 və ya 9-a bölünənlər 58, onlardan 4-ə də bölünənlər 14. Fərq 44. P = 11/50.');
INSERT INTO public.questions VALUES (941, 16, 'g9-stat-prob-q3-01', 3, 1, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,8; 0,6; 0,1. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,048", "B": "0,414", "C": "0,404", "D": "0,394", "E": "0,596"}'::jsonb, 'C', NULL, 'q = 1 − p: q₁ = 0,2, q₂ = 0,4, q₃ = 0,9. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,404.');
INSERT INTO public.questions VALUES (942, 16, 'g9-stat-prob-q3-02', 3, 2, 'hard', 'single', 'Sinifdə 7 oğlan və 7 qız var. Təsadüfi olaraq 3 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "295/364", "B": "1/2", "C": "293/364", "D": "5/26", "E": "21/26"}'::jsonb, 'E', NULL, 'Tamamlayıcı: hamısı oğlan (35) və ya hamısı qız (35). P = 1 − 70/364 = 21/26.');
INSERT INTO public.questions VALUES (943, 16, 'g9-stat-prob-q3-03', 3, 3, 'hard', 'single', 'Sinifdə 4 oğlan və 7 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "76/77", "B": "227/231", "C": "65/66", "D": "1/66", "E": "7/11"}'::jsonb, 'C', NULL, 'Tamamlayıcı: 0 qız — C(4, 5) = 0, 1 qız — 7·C(4, 4) = 7. P = 1 − (0 + 7)/462 = 65/66.');
INSERT INTO public.questions VALUES (944, 16, 'g9-stat-prob-q3-04', 3, 4, 'hard', 'single', '1-dən 100-ə qədər natural ədədlərdən biri təsadüfi seçilir. Onun 4-ə və ya 3-ə bölünməsi, lakin 7-yə bölünməməsi ehtimalını tapın.', NULL, NULL, '{"A": "9/20", "B": "1/2", "C": "11/25", "D": "43/100", "E": "29/50"}'::jsonb, 'C', NULL, 'Daxiletmə–xaricetmə: 4 və ya 3-ə bölünənlər 50, onlardan 7-yə də bölünənlər 6. Fərq 44. P = 11/25.');
INSERT INTO public.questions VALUES (945, 16, 'g9-stat-prob-q3-05', 3, 5, 'hard', 'single', '2 zər atılır. Düşən xalların fərqinin modulunun 2-dən kiçik olmaması ehtimalını tapın.', NULL, NULL, '{"A": "19/36", "B": "7/12", "C": "5/9", "D": "4/9", "E": "5/3"}'::jsonb, 'C', NULL, '|a − b| ≥ 2 olan hallar: 20, bütün hallar 36. P = 5/9.');
INSERT INTO public.questions VALUES (946, 16, 'g9-stat-prob-q3-06', 3, 6, 'hard', 'single', 'Sinifdə 6 oğlan və 3 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada qızların oğlanlardan çox olması ehtimalını tapın.', NULL, NULL, '{"A": "5/42", "B": "8/63", "C": "1/9", "D": "1/3", "E": "37/42"}'::jsonb, 'A', NULL, 'Σ C(3, j)·C(6, 5 − j), j > 5 − j, bölünsün C(9, 5) = 5/42.');
INSERT INTO public.questions VALUES (947, 16, 'g9-stat-prob-q3-07', 3, 7, 'hard', 'single', 'Qutuda 3 qırmızı, 5 ağ, 3 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "2/165", "B": "27/1331", "C": "1/330", "D": "3/11", "E": "1/165"}'::jsonb, 'E', NULL, 'Bütün hallar: C(11, 3) = 165. Əlverişli: C(3, 3)·C(8, 0) = 1. P = 1/165.');
INSERT INTO public.questions VALUES (948, 16, 'g9-stat-prob-q3-08', 3, 8, 'hard', 'single', '3 zər atılır. Düşən xalların cəminin 8 olması ehtimalını tapın.', NULL, NULL, '{"A": "11/108", "B": "7/36", "C": "5/54", "D": "7/72", "E": "65/72"}'::jsonb, 'D', NULL, 'Cəmi 8 olan hallar: 21, bütün hallar 6^3 = 216. P = 7/72.');
INSERT INTO public.questions VALUES (949, 16, 'g9-stat-prob-q3-09', 3, 9, 'hard', 'single', '7 nəfər, o cümlədən Anar və Bəhruz, təsadüfi qaydada bir cərgədə düzülür. Anar ilə Bəhruzun arasında düz bir nəfərin durması ehtimalını tapın.', NULL, NULL, '{"A": "1/3", "B": "5/21", "C": "16/21", "D": "10/21", "E": "1/7"}'::jsonb, 'B', NULL, 'Anar və Bəhruzun yer cütü (i, i + 2): 5 variant, 2 sıra, qalanlar 5! yolla. P = 5/21.');
INSERT INTO public.questions VALUES (950, 16, 'g9-stat-prob-q3-10', 3, 10, 'hard', 'single', 'Qutuda 6 qırmızı və 8 ağ şar var. Qaytarmadan ardıcıl iki şar götürülür. Şarların müxtəlif rəngdə olması ehtimalını tapın.', NULL, NULL, '{"A": "48/91", "B": "43/91", "C": "24/49", "D": "24/91", "E": "97/182"}'::jsonb, 'A', NULL, 'P = 6/14·8/13 + 8/14·6/13 = 48/91.');
INSERT INTO public.questions VALUES (951, 16, 'g9-stat-prob-q3-11', 3, 11, 'hard', 'single', 'Qutuda 3 qırmızı və 3 ağ şar var. Qaytarmadan ardıcıl iki şar götürülür. İkinci şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "1/5", "B": "3/5", "C": "2/3", "D": "1/2", "E": "2/5"}'::jsonb, 'D', NULL, 'Tam ehtimal: 3/6·2/5 + 3/6·3/5 = 1/2 (birinci şar haqqında məlumat olmadıqda ikinci şar da 3/6 ehtimalla qırmızıdır).');
INSERT INTO public.questions VALUES (952, 16, 'g9-stat-prob-q3-12', 3, 12, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,3; 0,1; 0,1. Atıcılardan ən azı birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,5", "B": "0,567", "C": "0,003", "D": "0,433", "E": "0,443"}'::jsonb, 'D', NULL, 'q = 1 − p: q₁ = 0,7, q₂ = 0,9, q₃ = 0,9. P = 1 − q₁q₂q₃ = 0,433.');
INSERT INTO public.questions VALUES (953, 16, 'g9-stat-prob-q3-13', 3, 13, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,1; 0,9; 0,5. Atıcılardan ən azı birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,955", "B": "0,945", "C": "0,975", "D": "0,045", "E": "0,965"}'::jsonb, 'A', NULL, 'q = 1 − p: q₁ = 0,9, q₂ = 0,1, q₃ = 0,5. P = 1 − q₁q₂q₃ = 0,955.');
INSERT INTO public.questions VALUES (954, 16, 'g9-stat-prob-q3-14', 3, 14, 'hard', 'open', '1-dən 120-yə qədər natural ədədlərdən biri təsadüfi seçilir. Onun 2-yə və ya 6-ya bölünməsi, lakin 3-ə bölünməməsi ehtimalını tapın.', NULL, NULL, NULL, NULL, '1/3', 'Daxiletmə–xaricetmə: 2 və ya 6-ya bölünənlər 60, onlardan 3-ə də bölünənlər 20. Fərq 40. P = 1/3.');
INSERT INTO public.questions VALUES (955, 16, 'g9-stat-prob-q3-15', 3, 15, 'hard', 'single', 'Qutuda 5 qırmızı və 9 ağ şar var. Qaytarmadan ardıcıl iki şar götürülür. İkinci şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "4/13", "B": "5/14", "C": "9/14", "D": "10/91", "E": "5/13"}'::jsonb, 'B', NULL, 'Tam ehtimal: 5/14·4/13 + 9/14·5/13 = 5/14 (birinci şar haqqında məlumat olmadıqda ikinci şar da 5/14 ehtimalla qırmızıdır).');
INSERT INTO public.questions VALUES (956, 16, 'g9-stat-prob-q3-16', 3, 16, 'hard', 'single', '1-dən 240-a qədər natural ədədlərdən biri təsadüfi seçilir. Onun 7-yə və ya 3-ə bölünməsi, lakin 4-ə bölünməməsi ehtimalını tapın.', NULL, NULL, '{"A": "13/40", "B": "77/240", "C": "103/240", "D": "19/40", "E": "9/40"}'::jsonb, 'B', NULL, 'Daxiletmə–xaricetmə: 7 və ya 3-ə bölünənlər 103, onlardan 4-ə də bölünənlər 26. Fərq 77. P = 77/240.');
INSERT INTO public.questions VALUES (957, 16, 'g9-stat-prob-q3-17', 3, 17, 'hard', 'single', '7 nəfər, o cümlədən Anar və Bəhruz, təsadüfi qaydada bir cərgədə düzülür. Anar ilə Bəhruzun yan-yana durması ehtimalını tapın.', NULL, NULL, '{"A": "2/7", "B": "1/6", "C": "5/7", "D": "1/7", "E": "4/7"}'::jsonb, 'A', NULL, 'Anar ilə Bəhruzu bir blok sayın: 2·6! hal. P = 2·6!/7! = 2/7. P = 2/7.');
INSERT INTO public.questions VALUES (958, 16, 'g9-stat-prob-q3-18', 3, 18, 'hard', 'single', 'Qutuda 4 qırmızı, 3 ağ, 4 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "7/55", "B": "14/55", "C": "2/55", "D": "336/1331", "E": "8/33"}'::jsonb, 'B', NULL, 'Bütün hallar: C(11, 3) = 165. Əlverişli: C(4, 2)·C(7, 1) = 42. P = 14/55.');
INSERT INTO public.questions VALUES (959, 16, 'g9-stat-prob-q3-19', 3, 19, 'hard', 'single', '3 zər atılır. Düşən xalların cəminin 11 olması ehtimalını tapın.', NULL, NULL, '{"A": "1/8", "B": "13/108", "C": "1/4", "D": "7/54", "E": "7/8"}'::jsonb, 'A', NULL, 'Cəmi 11 olan hallar: 27, bütün hallar 6^3 = 216. P = 1/8.');
INSERT INTO public.questions VALUES (960, 16, 'g9-stat-prob-q3-20', 3, 20, 'hard', 'single', 'Qutuda 3 qırmızı, 2 ağ, 6 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz birinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "28/55", "B": "1/110", "C": "3/44", "D": "14/55", "E": "6144/14641"}'::jsonb, 'A', NULL, 'Bütün hallar: C(11, 4) = 330. Əlverişli: C(3, 1)·C(8, 3) = 168. P = 28/55.');
INSERT INTO public.questions VALUES (961, 17, 'g9-aze-sound-q1-01', 1, 1, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə son heca qapalıdır və bütün saitlər qalındır?', NULL, NULL, '{"A": "duman, qatar, süt", "B": "ada, axşam, ulduz", "C": "boz, daş, savadlı", "D": "dastan, kitablar, top", "E": "kaman, oyun, tor"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (962, 17, 'g9-aze-sound-q1-02', 1, 2, 'hard', 'single', 'Hansı sözdə 1 kar samit var və söz samitlə başlayır?', NULL, NULL, '{"A": "dələ", "B": "tutuquşu", "C": "zürafə", "D": "səxavətli", "E": "qapıçı"}'::jsonb, 'C', NULL, '«zürafə»: hecalar — zü-ra-fə; saitlər — 3 (1 qalın, 2 incə, 1 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (963, 17, 'g9-aze-sound-q1-03', 1, 3, 'hard', 'single', 'Hansı sözdə həm qalın, həm də incə sait var və 1 açıq heca var?', NULL, NULL, '{"A": "karandaş", "B": "meymun", "C": "gümüş", "D": "alma", "E": "qızılgül"}'::jsonb, 'E', NULL, '«qızılgül»: hecalar — qı-zıl-gül; saitlər — 3 (2 qalın, 1 incə, 1 dodaqlanan); samitlər — 5 (5 cingiltili, 0 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (964, 17, 'g9-aze-sound-q1-04', 1, 4, 'hard', 'single', '«dəqiqə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (4 açıq, 0 qapalı); 4 sait (0 qalın, 4 incə); 3 samit (3 cingiltili, 0 kar)", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar)", "C": "4 heca (4 açıq, 0 qapalı); 4 sait (1 qalın, 3 incə); 3 samit (3 cingiltili, 0 kar)", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (3 cingiltili, 0 kar)", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (3 cingiltili, 0 kar)"}'::jsonb, 'D', NULL, '«dəqiqə» — hecalar: də-qi-qə. 3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (3 cingiltili, 0 kar).');
INSERT INTO public.questions VALUES (965, 17, 'g9-aze-sound-q1-05', 1, 5, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür?', NULL, NULL, '{"A": "sə-xa-vətl-i", "B": "ça-rpa-yı", "C": "na-rın-cı", "D": "sə-nə-tkar", "E": "ka-ra-ndaş"}'::jsonb, 'C', NULL, 'Düzgün bölgü: na-rın-cı. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (966, 17, 'g9-aze-sound-q1-06', 1, 6, 'hard', 'single', 'Hansı sözdə 4 səs var və 2 kar samit var?', NULL, NULL, '{"A": "hörmət", "B": "fəhlə", "C": "xala", "D": "keçi", "E": "masa"}'::jsonb, 'D', NULL, '«keçi»: hecalar — ke-çi; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 2 (0 cingiltili, 2 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (967, 17, 'g9-aze-sound-q1-07', 1, 7, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə dodaqlanan sait yoxdur və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "qara, təbaşir, çinar", "B": "divan, ildırım, mehriban", "C": "dəniz, səhra, yasəmən", "D": "cəsarət, təyyarə, zaman", "E": "hakim, nişan, nənə"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (968, 17, 'g9-aze-sound-q1-08', 1, 8, 'hard', 'single', '«sevgi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar)", "D": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar)", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'E', NULL, '«sevgi» — hecalar: sev-gi. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (969, 17, 'g9-aze-sound-q1-09', 1, 9, 'hard', 'single', 'Hansı sözdə 3 cingiltili samit var və 2 sonor samit var?', NULL, NULL, '{"A": "mühəndis", "B": "oyun", "C": "roman", "D": "xəyal", "E": "qarpız"}'::jsonb, 'A', NULL, '«mühəndis»: hecalar — mü-hən-dis; saitlər — 3 (0 qalın, 3 incə, 1 dodaqlanan); samitlər — 5 (3 cingiltili, 2 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (970, 17, 'g9-aze-sound-q1-10', 1, 10, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 açıq (geniş) sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "arzu, qaranquş, yaşıl", "B": "sarı, çarpayı, şam", "C": "nişan, qarpız, top", "D": "kartof, qoyun, sol", "E": "duman, maşın, oyunçu"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (971, 17, 'g9-aze-sound-q1-11', 1, 11, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə dodaqlanan sait yoxdur və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "kitablar, pəncərə, xiyar", "B": "cəsarət, həyat, çarpayı", "C": "addım, gilas, saniyə", "D": "kənar, pəncərə, sahil", "E": "divar, səhra, xəyal"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (972, 17, 'g9-aze-sound-q1-12', 1, 12, 'hard', 'single', '«xətkeş» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (0 cingiltili, 4 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (0 cingiltili, 4 kar)", "C": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə); 4 samit (0 cingiltili, 4 kar)", "D": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (0 cingiltili, 4 kar)", "E": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (0 cingiltili, 4 kar)"}'::jsonb, 'D', NULL, '«xətkeş» — hecalar: xət-keş. 2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (0 cingiltili, 4 kar).');
INSERT INTO public.questions VALUES (973, 17, 'g9-aze-sound-q1-13', 1, 13, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə kar samitlər cingiltili samitlərdən çoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "parça, ulduz, çanta", "B": "ata, axşam, sahil", "C": "qapıçı, qara, xalça", "D": "dost, hakim, tufan", "E": "kartof, tamaşa, tutuquşu"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (974, 17, 'g9-aze-sound-q1-14', 1, 14, 'hard', 'single', '«həkim» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (1 cingiltili, 3 kar)", "D": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)"}'::jsonb, 'E', NULL, '«həkim» — hecalar: hə-kim. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar).');
INSERT INTO public.questions VALUES (975, 17, 'g9-aze-sound-q1-15', 1, 15, 'hard', 'single', 'Hansı sözdə qapalı (dar) sait yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "masa", "B": "maşın", "C": "oyunçu", "D": "sərçə", "E": "kətə"}'::jsonb, 'A', NULL, '«masa»: hecalar — ma-sa; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 2 (1 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (976, 17, 'g9-aze-sound-q1-16', 1, 16, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir?', NULL, NULL, '{"A": "acı – gül", "B": "qatar – xiyar", "C": "nar – təyyarə", "D": "limon – tülkü", "E": "kətə – rəssam"}'::jsonb, 'E', NULL, '«kətə»: kə-tə; «rəssam»: rəs-sam. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (977, 17, 'g9-aze-sound-q1-17', 1, 17, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "alma – səma", "B": "güzgü – rəssam", "C": "dastan – şirin", "D": "komanda – tutuquşu", "E": "turş – şirin"}'::jsonb, 'B', NULL, '«güzgü»: güz-gü; «rəssam»: rəs-sam. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (978, 17, 'g9-aze-sound-q1-18', 1, 18, 'hard', 'single', '«hekayə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (3 açıq, 0 qapalı); 3 sait (2 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar)", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar)", "C": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 4 samit (1 cingiltili, 3 kar)", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "E": "4 heca (4 açıq, 0 qapalı); 4 sait (1 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar)"}'::jsonb, 'D', NULL, '«hekayə» — hecalar: he-ka-yə. 3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar).');
INSERT INTO public.questions VALUES (979, 17, 'g9-aze-sound-q1-19', 1, 19, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "muzey – vətən", "B": "pozan – əkinçi", "C": "aslan – təpə", "D": "bacı – kirpi", "E": "duz – təyyarə"}'::jsonb, 'A', NULL, '«muzey»: mu-zey; «vətən»: və-tən. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (980, 17, 'g9-aze-sound-q1-20', 1, 20, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 açıq (geniş) sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "səbir, top, toy", "B": "oyunçu, qatar, yaşıl", "C": "acı, yazıçı, yuxarı", "D": "cəsur, qoyun, tar", "E": "ada, dar, nar"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (981, 17, 'g9-aze-sound-q1-21', 1, 21, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "kaman – xəyal", "B": "dünya – musiqi", "C": "divan – yemiş", "D": "səbir – şəkər", "E": "gündüz – süfrə"}'::jsonb, 'E', NULL, '«gündüz»: gün-düz; «süfrə»: süf-rə. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (982, 17, 'g9-aze-sound-q1-22', 1, 22, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür?', NULL, NULL, '{"A": "qa-ranq-uş", "B": "mü-hə-ndis", "C": "sən-ət-kar", "D": "qı-zıl-gül", "E": "me-hri-ban"}'::jsonb, 'D', NULL, 'Düzgün bölgü: qı-zıl-gül. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (983, 17, 'g9-aze-sound-q1-23', 1, 23, 'hard', 'single', 'Hansı sözdə bütün saitlər qalındır və 2 kar samit var?', NULL, NULL, '{"A": "kətə", "B": "süfrə", "C": "cavablar", "D": "karandaş", "E": "zaman"}'::jsonb, 'D', NULL, '«karandaş»: hecalar — ka-ran-daş; saitlər — 3 (3 qalın, 0 incə, 0 dodaqlanan); samitlər — 5 (3 cingiltili, 2 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (984, 17, 'g9-aze-sound-q1-24', 1, 24, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın?', NULL, NULL, '{"A": "liman – şirin", "B": "dəniz – süfrə", "C": "meymun – sürücü", "D": "aslan – güzgü", "E": "qələm – tülkü"}'::jsonb, 'D', NULL, '«aslan»: as-lan; «güzgü»: güz-gü. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (985, 17, 'g9-aze-sound-q1-25', 1, 25, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "qorxu – rəf", "B": "tar – top", "C": "həsrət – qatar", "D": "konsert – mis", "E": "gözəl – hörmət"}'::jsonb, 'E', NULL, '«gözəl»: gö-zəl; «hörmət»: hör-mət. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (986, 17, 'g9-aze-sound-q1-26', 1, 26, 'hard', 'single', '«xəritə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (4 açıq, 0 qapalı); 4 sait (1 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar)", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar)", "C": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (2 cingiltili, 2 kar)", "E": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'B', NULL, '«xəritə» — hecalar: xə-ri-tə. 3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar).');
INSERT INTO public.questions VALUES (987, 17, 'g9-aze-sound-q1-27', 1, 27, 'hard', 'single', '«çinar» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (2 cingiltili, 2 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (3 cingiltili, 0 kar)", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'B', NULL, '«çinar» — hecalar: çi-nar. 2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (988, 17, 'g9-aze-sound-q1-28', 1, 28, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir?', NULL, NULL, '{"A": "heyva – qapıçı", "B": "qapıçı – səhər", "C": "divar – mənzərə", "D": "səxavətli – zaman", "E": "həsrət – pərdə"}'::jsonb, 'E', NULL, '«həsrət»: həs-rət; «pərdə»: pər-də. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (989, 17, 'g9-aze-sound-q1-29', 1, 29, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə kar samit yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "uzun, yazıçı, yol", "B": "addım, baba, qum", "C": "cavablar, dayı, parça", "D": "nar, qar, yuxu", "E": "bal, narıncı, pozan"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (990, 17, 'g9-aze-sound-q1-30', 1, 30, 'hard', 'single', 'Hansı sözdə 3 açıq (geniş) sait var və cingiltili samitlər kar samitlərdən çoxdur?', NULL, NULL, '{"A": "pəncərə", "B": "çinar", "C": "lampa", "D": "dülgər", "E": "yol"}'::jsonb, 'A', NULL, '«pəncərə»: hecalar — pən-cə-rə; saitlər — 3 (0 qalın, 3 incə, 0 dodaqlanan); samitlər — 4 (3 cingiltili, 1 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (991, 17, 'g9-aze-sound-q2-01', 2, 1, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə son heca qapalıdır və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "cəsur, muzey, üzüm", "B": "divar, dəmir, xəyal", "C": "ozan, pomidor, xiyar", "D": "cəsarət, həsrət, meymun", "E": "kənar, sənətkar, təbaşir"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (992, 17, 'g9-aze-sound-q2-02', 2, 2, 'hard', 'single', '«qırmızı» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar)", "B": "4 heca (3 açıq, 1 qapalı); 4 sait (3 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar)", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 5 samit (4 cingiltili, 1 kar)", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar)", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar)"}'::jsonb, 'E', NULL, '«qırmızı» — hecalar: qır-mı-zı. 3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar).');
INSERT INTO public.questions VALUES (993, 17, 'g9-aze-sound-q2-03', 2, 3, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir?', NULL, NULL, '{"A": "qapıçı – zürafə", "B": "ada – dolu", "C": "savadlı – çöl", "D": "addım – yarış", "E": "dəftər – təyyarə"}'::jsonb, 'D', NULL, '«addım»: ad-dım; «yarış»: ya-rış. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (994, 17, 'g9-aze-sound-q2-04', 2, 4, 'hard', 'single', 'Hansı sözdə 5 səs var və bütün saitlər qalındır?', NULL, NULL, '{"A": "şirin", "B": "səhər", "C": "sinif", "D": "divar", "E": "çoban"}'::jsonb, 'E', NULL, '«çoban»: hecalar — ço-ban; saitlər — 2 (2 qalın, 0 incə, 1 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (995, 17, 'g9-aze-sound-q2-05', 2, 5, 'hard', 'single', 'Hansı sözdə açıq heca yoxdur və kar samit yoxdur?', NULL, NULL, '{"A": "bal", "B": "gecə", "C": "güzgü", "D": "durna", "E": "bostan"}'::jsonb, 'A', NULL, '«bal»: hecalar — bal; saitlər — 1 (1 qalın, 0 incə, 0 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (996, 17, 'g9-aze-sound-q2-06', 2, 6, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın?', NULL, NULL, '{"A": "qısa – qızılgül", "B": "həsrət – pomidor", "C": "aslan – gilas", "D": "süfrə – zürafə", "E": "xala – üzüm"}'::jsonb, 'E', NULL, '«xala»: xa-la; «üzüm»: ü-züm. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (997, 17, 'g9-aze-sound-q2-07', 2, 7, 'hard', 'single', 'Hansı sözdə kar və cingiltili samitlərin sayı bərabərdir və 1 dodaqlanan sait var?', NULL, NULL, '{"A": "muzey", "B": "dastan", "C": "tor", "D": "duz", "E": "dost"}'::jsonb, 'C', NULL, '«tor»: hecalar — tor; saitlər — 1 (1 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (1 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (998, 17, 'g9-aze-sound-q2-08', 2, 8, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 kar samit var və bütün saitlər incədir?', NULL, NULL, '{"A": "geniş, pəncərə, yumurta", "B": "göyərçin, süt, çəmən", "C": "mis, savadlı, əsr", "D": "fil, günəş, hündür", "E": "meşə, xəyal, şirin"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (999, 17, 'g9-aze-sound-q2-09', 2, 9, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "dəniz – qorxu", "B": "tarla – şorba", "C": "gəmi – lalə", "D": "həsrət – təpə", "E": "küçə – səma"}'::jsonb, 'E', NULL, '«küçə»: kü-çə; «səma»: sə-ma. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1000, 17, 'g9-aze-sound-q2-10', 2, 10, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "divan – təpə", "B": "konsert – səmimi", "C": "orta – sərin", "D": "addım – kətə", "E": "oyun – süt"}'::jsonb, 'C', NULL, '«orta»: or-ta; «sərin»: sə-rin. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1001, 17, 'g9-aze-sound-q2-11', 2, 11, 'hard', 'single', '«tülkü» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)"}'::jsonb, 'C', NULL, '«tülkü» — hecalar: tül-kü. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar).');
INSERT INTO public.questions VALUES (1002, 17, 'g9-aze-sound-q2-12', 2, 12, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə son heca qapalıdır və bütün saitlər qalındır?', NULL, NULL, '{"A": "geniş, zaman, çoban", "B": "aslan, karandaş, səhər", "C": "duz, roman, çəmən", "D": "qar, turş, yarış", "E": "divan, kaman, çay"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1003, 17, 'g9-aze-sound-q2-13', 2, 13, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür?', NULL, NULL, '{"A": "can-a-var", "B": "sə-yah-ət", "C": "qa-ranq-uş", "D": "gö-yə-rçin", "E": "sə-nət-kar"}'::jsonb, 'E', NULL, 'Düzgün bölgü: sə-nət-kar. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (1004, 17, 'g9-aze-sound-q2-14', 2, 14, 'hard', 'single', '«oyunçu» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (3 açıq, 1 qapalı); 4 sait (3 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)", "D": "4 heca (3 açıq, 1 qapalı); 4 sait (4 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "E": "3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'B', NULL, '«oyunçu» — hecalar: o-yun-çu. 3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (1005, 17, 'g9-aze-sound-q2-15', 2, 15, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "dələ, həftə, kartof", "B": "pendir, pərdə, qara", "C": "dərin, gecə, tarix", "D": "dəftər, fəhlə, tarla", "E": "isti, qələm, süfrə"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1006, 17, 'g9-aze-sound-q2-16', 2, 16, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə sonor samit yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "baba, boz, daş", "B": "lampa, qapı, top", "C": "ada, kaman, tutuquşu", "D": "maşın, qapıçı, qısa", "E": "acı, ata, kaman"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1007, 17, 'g9-aze-sound-q2-17', 2, 17, 'hard', 'single', '«güzgü» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (3 cingiltili, 0 kar)", "B": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar)", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)"}'::jsonb, 'D', NULL, '«güzgü» — hecalar: güz-gü. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar).');
