INSERT INTO public.questions VALUES (1009, 17, 'g9-aze-sound-q2-19', 2, 19, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir?', NULL, NULL, '{"A": "lampa – əsr", "B": "bayram – güzgü", "C": "gümüş – səmimi", "D": "göl – hədiyyə", "E": "həkim – əkinçi"}'::jsonb, 'B', NULL, '«bayram»: bay-ram; «güzgü»: güz-gü. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1010, 17, 'g9-aze-sound-q2-20', 2, 20, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın?', NULL, NULL, '{"A": "divan – günəş", "B": "karandaş – mənzərə", "C": "kirpi – sərin", "D": "körpü – qara", "E": "baba – üzüm"}'::jsonb, 'C', NULL, '«kirpi»: kir-pi; «sərin»: sə-rin. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1011, 17, 'g9-aze-sound-q2-21', 2, 21, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 qapalı heca var və bütün saitlər qalındır?', NULL, NULL, '{"A": "dastan, kartof, xalça", "B": "axşam, cavablar, qapı", "C": "qardaş, qarpız, sənətkar", "D": "addım, aslan, bayram", "E": "karandaş, pozan, qartal"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1012, 17, 'g9-aze-sound-q2-22', 2, 22, 'hard', 'single', 'Hansı sözdə açıq (geniş) sait yoxdur və dodaqlanan sait yoxdur?', NULL, NULL, '{"A": "qırmızı", "B": "dəmir", "C": "dələ", "D": "qələbə", "E": "qara"}'::jsonb, 'A', NULL, '«qırmızı»: hecalar — qır-mı-zı; saitlər — 3 (3 qalın, 0 incə, 0 dodaqlanan); samitlər — 4 (4 cingiltili, 0 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1013, 17, 'g9-aze-sound-q2-23', 2, 23, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 qapalı heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "göl, kədər, çinar", "B": "mənzərə, pəncərə, səs", "C": "gəlin, qoyun, qələm", "D": "güzgü, heyva, sərin", "E": "sinif, sərgi, şaftalı"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1014, 17, 'g9-aze-sound-q2-24', 2, 24, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür?', NULL, NULL, '{"A": "ki-tabl-ar", "B": "cəs-a-rət", "C": "meh-ri-ban", "D": "yu-mu-rta", "E": "şag-ird-lər"}'::jsonb, 'C', NULL, 'Düzgün bölgü: meh-ri-ban. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (1015, 17, 'g9-aze-sound-q2-25', 2, 25, 'hard', 'single', '«pendir» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar)", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar)", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar)", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (3 cingiltili, 1 kar)", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 5 samit (4 cingiltili, 1 kar)"}'::jsonb, 'C', NULL, '«pendir» — hecalar: pen-dir. 2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (1016, 17, 'g9-aze-sound-q2-26', 2, 26, 'hard', 'single', '«fəhlə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar)", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar)", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (1 cingiltili, 3 kar)"}'::jsonb, 'C', NULL, '«fəhlə» — hecalar: fəh-lə. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar).');
INSERT INTO public.questions VALUES (1017, 17, 'g9-aze-sound-q2-27', 2, 27, 'hard', 'single', 'Hansı sözdə cingiltili samitlər kar samitlərdən çoxdur və dodaqlanan sait yoxdur?', NULL, NULL, '{"A": "meşə", "B": "duman", "C": "meymun", "D": "parça", "E": "savadlı"}'::jsonb, 'E', NULL, '«savadlı»: hecalar — sa-vad-lı; saitlər — 3 (3 qalın, 0 incə, 0 dodaqlanan); samitlər — 4 (3 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1018, 17, 'g9-aze-sound-q2-28', 2, 28, 'hard', 'single', '«kaman» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar)", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "E": "2 heca (2 açıq, 0 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'D', NULL, '«kaman» — hecalar: ka-man. 2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (1019, 17, 'g9-aze-sound-q2-29', 2, 29, 'hard', 'single', 'Hansı sözdə 1 açıq heca var və 2 cingiltili samit var?', NULL, NULL, '{"A": "səhər", "B": "nar", "C": "ozan", "D": "dəmir", "E": "göyərçin"}'::jsonb, 'C', NULL, '«ozan»: hecalar — o-zan; saitlər — 2 (2 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1020, 17, 'g9-aze-sound-q2-30', 2, 30, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "masa – sərin", "B": "dərin – şorba", "C": "gəlin – yoldaş", "D": "kölgə – mavi", "E": "acı – yaşıl"}'::jsonb, 'D', NULL, '«kölgə»: köl-gə; «mavi»: ma-vi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1021, 17, 'g9-aze-sound-q3-01', 3, 1, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür?', NULL, NULL, '{"A": "ək-in-çi", "B": "sə-yah-ət", "C": "ca-na-var", "D": "ya-səm-ən", "E": "sa-va-dlı"}'::jsonb, 'C', NULL, 'Düzgün bölgü: ca-na-var. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (1022, 17, 'g9-aze-sound-q3-02', 3, 2, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür?', NULL, NULL, '{"A": "tə-yya-rə", "B": "ka-ra-ndaş", "C": "həd-iy-yə", "D": "ki-tab-lar", "E": "qı-rmı-zı"}'::jsonb, 'D', NULL, 'Düzgün bölgü: ki-tab-lar. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (1023, 17, 'g9-aze-sound-q3-03', 3, 3, 'hard', 'single', 'Hansı sözdə 2 cingiltili samit var və cingiltili samitlər kar samitlərdən çoxdur?', NULL, NULL, '{"A": "divar", "B": "muzey", "C": "çəmən", "D": "hündür", "E": "acı"}'::jsonb, 'C', NULL, '«çəmən»: hecalar — çə-mən; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1024, 17, 'g9-aze-sound-q3-04', 3, 4, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "divan – sahil", "B": "geniş – xəyal", "C": "ilan – qartal", "D": "dolu – roman", "E": "karandaş – zürafə"}'::jsonb, 'D', NULL, '«dolu»: do-lu; «roman»: ro-man. Yalnız bu cüt bütün şərtləri ödəyir.');
