INSERT INTO public.questions VALUES (1026, 17, 'g9-aze-sound-q3-06', 3, 6, 'hard', 'single', 'Hansı sözdə 1 açıq heca var və 1 qapalı (dar) sait var?', NULL, NULL, '{"A": "geri", "B": "sevgi", "C": "üzüm", "D": "kino", "E": "karandaş"}'::jsonb, 'B', NULL, '«sevgi»: hecalar — sev-gi; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1027, 17, 'g9-aze-sound-q3-07', 3, 7, 'hard', 'single', 'Hansı sözdə qapalı (dar) sait yoxdur və 1 açıq (geniş) sait var?', NULL, NULL, '{"A": "qatar", "B": "mavi", "C": "pərdə", "D": "cəsarət", "E": "yol"}'::jsonb, 'E', NULL, '«yol»: hecalar — yol; saitlər — 1 (1 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1028, 17, 'g9-aze-sound-q3-08', 3, 8, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə kar samit yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "alma, tamaşa, yun", "B": "acı, duz, irəli", "C": "arzu, qələm, yol", "D": "bacı, dolu, qızıl", "E": "dəmir, nar, ulduz"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1029, 17, 'g9-aze-sound-q3-09', 3, 9, 'hard', 'single', '«yaşıl» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 4 samit (2 cingiltili, 2 kar)", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (3 cingiltili, 0 kar)", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'B', NULL, '«yaşıl» — hecalar: ya-şıl. 2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar).');
