INSERT INTO public.questions VALUES (1040, 17, 'g9-aze-sound-q3-20', 3, 20, 'hard', 'single', '«gəlin» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (4 cingiltili, 0 kar)", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)", "D": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar)"}'::jsonb, 'C', NULL, '«gəlin» — hecalar: gə-lin. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar).');
INSERT INTO public.questions VALUES (1041, 17, 'g9-aze-sound-q3-21', 3, 21, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var?', NULL, NULL, '{"A": "gəmi – səma", "B": "dolu – vətən", "C": "boz – komanda", "D": "isti – xəyal", "E": "addım – yuxu"}'::jsonb, 'B', NULL, '«dolu»: do-lu; «vətən»: və-tən. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1042, 17, 'g9-aze-sound-q3-22', 3, 22, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə açıq heca yoxdur və bütün saitlər incədir?', NULL, NULL, '{"A": "bülbül, dülgər, hörmət", "B": "dəftər, irəli, nərgiz", "C": "fil, süt, üzüm", "D": "dəqiqə, hündür, səs", "E": "mis, səhər, çöl"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1043, 17, 'g9-aze-sound-q3-23', 3, 23, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz saitlə başlayır və bütün saitlər qalındır?', NULL, NULL, '{"A": "arzu, aslan, çanta", "B": "arı, karandaş, ozan", "C": "alça, orta, oyunçu", "D": "acı, addım, çarpayı", "E": "ana, ayı, tarla"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1044, 17, 'g9-aze-sound-q3-24', 3, 24, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın?', NULL, NULL, '{"A": "qələm – səhər", "B": "kətə – yazıçı", "C": "cəsur – qalay", "D": "nəfəs – zürafə", "E": "addım – gilas"}'::jsonb, 'C', NULL, '«cəsur»: cə-sur; «qalay»: qa-lay. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1045, 17, 'g9-aze-sound-q3-25', 3, 25, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 3 heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "hədiyyə, isti, tələbə", "B": "mənzərə, pəncərə, sürücü", "C": "xəritə, şirin, əkinçi", "D": "dəqiqə, mühəndis, şüşə", "E": "həsrət, irəli, səmimi"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1046, 17, 'g9-aze-sound-q3-26', 3, 26, 'hard', 'single', '«yaşıl» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (3 cingiltili, 0 kar)", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar)", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar)"}'::jsonb, 'D', NULL, '«yaşıl» — hecalar: ya-şıl. 2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (1047, 17, 'g9-aze-sound-q3-27', 3, 27, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın?', NULL, NULL, '{"A": "fəhlə – heyva", "B": "cəsur – göl", "C": "kitablar – çinar", "D": "heyva – tarla", "E": "dəniz – hakim"}'::jsonb, 'A', NULL, '«fəhlə»: fəh-lə; «heyva»: hey-va. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (1048, 17, 'g9-aze-sound-q3-28', 3, 28, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 qapalı (dar) sait var və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "mavi, qaranquş, şagirdlər", "B": "meymun, muzey, xəritə", "C": "hakim, kitablar, liman", "D": "həyat, kino, nişan", "E": "ildırım, sahil, çinar"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (1049, 17, 'g9-aze-sound-q3-29', 3, 29, 'hard', 'single', '«savadlı» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar)", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar)", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar)", "D": "4 heca (3 açıq, 1 qapalı); 4 sait (4 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar)", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 5 samit (4 cingiltili, 1 kar)"}'::jsonb, 'C', NULL, '«savadlı» — hecalar: sa-vad-lı. 3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar).');
INSERT INTO public.questions VALUES (1050, 17, 'g9-aze-sound-q3-30', 3, 30, 'hard', 'single', 'Hansı sözdə sonor samit yoxdur və qapalı heca yoxdur?', NULL, NULL, '{"A": "dolu", "B": "boz", "C": "saz", "D": "səma", "E": "ada"}'::jsonb, 'E', NULL, '«ada»: hecalar — a-da; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 1 (1 cingiltili, 0 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1051, 18, 'g9-aze-orth-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "1945-cı ildə məktəbimizin 46-cı buraxılışı oldu.", "B": "1945-ci ildə məktəbimizin 46-cü buraxılışı oldu.", "C": "1945-ci ildə məktəbimizin 46-cı buraxılışı oldu.", "D": "1945-cü ildə məktəbimizin 46-cı buraxılışı oldu.", "E": "1945-ci ildə məktəbimizin 46-ci buraxılışı oldu."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1945-ci, 46-cı.');
INSERT INTO public.questions VALUES (1052, 18, 'g9-aze-orth-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə kökü dəyişməyən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «köynəyi» və «uşağı» sözləri işlənmişdi.", "B": "Diktantda «qəfəsi» və «sinifi» sözləri işlənmişdi.", "C": "Diktantda «çörəki» və «qəfsi» sözləri işlənmişdi.", "D": "Diktantda «xalqı» və «yarpağı» sözləri işlənmişdi.", "E": "Diktantda «çörəki» və «qəfəsi» sözləri işlənmişdi."}'::jsonb, 'D', NULL, 'xalq → xalqı (dəyişmir), yarpaq → yarpağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1053, 18, 'g9-aze-orth-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə kökü dəyişməyən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «xalğı» və «fərği» sözləri işlənmişdi.", "B": "Diktantda «hüququ» və «fikri» sözləri işlənmişdi.", "C": "Diktantda «dirəki» və «fərği» sözləri işlənmişdi.", "D": "Diktantda «çiçəyi» və «dənzi» sözləri işlənmişdi.", "E": "Diktantda «nitqi» və «boyunu» sözləri işlənmişdi."}'::jsonb, 'B', NULL, 'hüquq → hüququ (dəyişmir), fikir → fikri (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1054, 18, 'g9-aze-orth-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2026-cı ildə məktəbimizin 60-cı buraxılışı oldu.", "B": "2026-cı ildə məktəbimizin 60-cü buraxılışı oldu.", "C": "2026-cu ildə məktəbimizin 60-cı buraxılışı oldu.", "D": "2026-cü ildə məktəbimizin 60-cı buraxılışı oldu.", "E": "2026-cı ildə məktəbimizin 60-cu buraxılışı oldu."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 60-cı.');
INSERT INTO public.questions VALUES (1055, 18, 'g9-aze-orth-q1-05', 1, 5, 'hard', 'single', 'Tələffüzü [ağaç] və [kəpənəy''] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Bağdakı ağaçın altında bir kəpənəq görünürdü.", "B": "Bağdakı ağacın altında bir kəpənəq görünürdü.", "C": "Bağdakı ağacın altında bir kəpənək görünürdü.", "D": "Bağdakı ağacın altında bir kəpənəy görünürdü.", "E": "Bağdakı ağaçın altında bir kəpənək görünürdü."}'::jsonb, 'C', NULL, '«ağac» — Sonda c yazılır; «kəpənək» — Sonda k yazılır. Düzgün: Bağdakı ağacın altında bir kəpənək görünürdü.');
INSERT INTO public.questions VALUES (1056, 18, 'g9-aze-orth-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2003-cu ildə 23-cü yerə çıxdıq.", "B": "Biz 2003-cü ildə 23-cü yerə çıxdıq.", "C": "Biz 2003-cı ildə 23-cü yerə çıxdıq.", "D": "Biz 2003-cü ildə 23-ci yerə çıxdıq.", "E": "Biz 2003-ci ildə 23-cü yerə çıxdıq."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2003-cü, 23-cü.');
INSERT INTO public.questions VALUES (1057, 18, 'g9-aze-orth-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1991-cü ildə 50-ci dəfə sərgi açdı.", "B": "Muzey 1991-cı ildə 50-ci dəfə sərgi açdı.", "C": "Muzey 1991-ci ildə 50-cü dəfə sərgi açdı.", "D": "Muzey 1991-cu ildə 50-ci dəfə sərgi açdı.", "E": "Muzey 1991-ci ildə 50-ci dəfə sərgi açdı."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1991-ci, 50-ci.');
INSERT INTO public.questions VALUES (1058, 18, 'g9-aze-orth-q1-08', 1, 8, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, sual ədatının (-mı, -mi), «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə-gülə danışırdı. Sən bu kitabı oxudunmu? Səndə bu işdə iştirak et.", "B": "Gülə gülə danışırdı. Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et.", "C": "Gülə-gülə danışırdı. Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et.", "D": "Gülə gülə danışırdı. Sən bu kitabı oxudunmu? Səndə bu işdə iştirak et.", "E": "Gülə-gülə danışırdı. Sən bu kitabı oxudun mu? Sən də bu işdə iştirak et."}'::jsonb, 'C', NULL, 'Düzgün: Gülə-gülə danışırdı. Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1059, 18, 'g9-aze-orth-q1-09', 1, 9, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yarım ada dənizə uzanır. Qızılgül bağçanı bəzəyirdi. Günəbaxan günəşə tərəf dönür.", "B": "Yarımada dənizə uzanır. Qızıl gül bağçanı bəzəyirdi. Günəbaxan günəşə tərəf dönür.", "C": "Yarım ada dənizə uzanır. Qızılgül bağçanı bəzəyirdi. Günə baxan günəşə tərəf dönür.", "D": "Yarımada dənizə uzanır. Qızılgül bağçanı bəzəyirdi. Günə baxan günəşə tərəf dönür.", "E": "Yarımada dənizə uzanır. Qızılgül bağçanı bəzəyirdi. Günəbaxan günəşə tərəf dönür."}'::jsonb, 'E', NULL, 'Düzgün: Yarımada dənizə uzanır. Qızılgül bağçanı bəzəyirdi. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1060, 18, 'g9-aze-orth-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «hüququ» və «inəyi» sözləri işlənmişdi.", "B": "Diktantda «yarpaqı» və «burnu» sözləri işlənmişdi.", "C": "Diktantda «bayrağı» və «dənizi» sözləri işlənmişdi.", "D": "Diktantda «ayağı» və «qulaqı» sözləri işlənmişdi.", "E": "Diktantda «yarpağı» və «burunu» sözləri işlənmişdi."}'::jsonb, 'C', NULL, 'bayraq → bayrağı (q→ğ), dəniz → dənizi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1061, 18, 'g9-aze-orth-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1969-ci ildə 16-cı yerə çıxdıq.", "B": "Biz 1969-cu ildə 16-cı yerə çıxdıq.", "C": "Biz 1969-cü ildə 16-cı yerə çıxdıq.", "D": "Biz 1969-cu ildə 16-ci yerə çıxdıq.", "E": "Biz 1969-cu ildə 16-cü yerə çıxdıq."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1969-cu, 16-cı.');
INSERT INTO public.questions VALUES (1062, 18, 'g9-aze-orth-q1-12', 1, 12, 'hard', 'single', 'Tələffüzü [kənt] və [qonaxlıx] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Bizim kəntdə hər il qonaqlıq keçirilir.", "B": "Bizim kənddə hər il qonaqlıq keçirilir.", "C": "Bizim kənddə hər il qonaqlıx keçirilir.", "D": "Bizim kənddə hər il qonaxlıx keçirilir.", "E": "Bizim kənddə hər il qonaxlıq keçirilir."}'::jsonb, 'B', NULL, '«kənd» — Sonda d yazılır; «qonaqlıq» — q yazılır. Düzgün: Bizim kənddə hər il qonaqlıq keçirilir.');
INSERT INTO public.questions VALUES (1063, 18, 'g9-aze-orth-q1-13', 1, 13, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ataana övladını qoruyar. Dedi ki, sabah gələcək. Bu, əngözəl mənzərədir.", "B": "Ata-ana övladını qoruyar. Dedi ki, sabah gələcək. Bu, ən gözəl mənzərədir.", "C": "Ataana övladını qoruyar. Dedi ki, sabah gələcək. Bu, ən gözəl mənzərədir.", "D": "Ata-ana övladını qoruyar. Dedi ki, sabah gələcək. Bu, əngözəl mənzərədir.", "E": "Ata-ana övladını qoruyar. Dediki, sabah gələcək. Bu, ən gözəl mənzərədir."}'::jsonb, 'B', NULL, 'Düzgün: Ata-ana övladını qoruyar. Dedi ki, sabah gələcək. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1064, 18, 'g9-aze-orth-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «parkı», «şəhəri» sözlərini misal gətirdi.", "B": "Müəllim «bıçaqı», «alını» sözlərini misal gətirdi.", "C": "Müəllim «uşağı», «könlü» sözlərini misal gətirdi.", "D": "Müəllim «dirəki», «burnu» sözlərini misal gətirdi.", "E": "Müəllim «tankı», «könülü» sözlərini misal gətirdi."}'::jsonb, 'C', NULL, 'uşaq → uşağı (q→ğ), könül → könlü (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1065, 18, 'g9-aze-orth-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «qulağı» və «ağzı» sözlərini lövhəyə yazdı.", "B": "Şagird «xalqı» və «ürəyi» sözlərini lövhəyə yazdı.", "C": "Şagird «dirəki» və «ömrü» sözlərini lövhəyə yazdı.", "D": "Şagird «ittifağı» və «fikiri» sözlərini lövhəyə yazdı.", "E": "Şagird «dənzi» və «burnu» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'qulaq → qulağı (q→ğ), ağız → ağzı (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1066, 18, 'g9-aze-orth-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə kökü dəyişməyən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «ittifağı» və «hüququ» sözlərini lövhəyə yazdı.", "B": "Şagird «ittifaqı» və «hüquğu» sözlərini lövhəyə yazdı.", "C": "Şagird «nitqi» və «çörəyi» sözlərini lövhəyə yazdı.", "D": "Şagird «nitği» və «ağzı» sözlərini lövhəyə yazdı.", "E": "Şagird «şəkli» və «hüquğu» sözlərini lövhəyə yazdı."}'::jsonb, 'C', NULL, 'nitq → nitqi (dəyişmir), çörək → çörəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1067, 18, 'g9-aze-orth-q1-17', 1, 17, 'hard', 'single', 'Tələffüzü [uşax] və [oyuncax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Uşaq pəncərənin qarşısında oyuncaqla oynayırdı.", "B": "Uşaq pəncərənin qarşısında oyuncaxla oynayırdı.", "C": "Uşax pəncərənin qarşısında oyuncaqla oynayırdı.", "D": "Uşağ pəncərənin qarşısında oyuncaqla oynayırdı.", "E": "Uşaq pəncərənin qarşısında oyuncağla oynayırdı."}'::jsonb, 'A', NULL, '«uşaq» — Sonda q yazılır; «oyuncaq» — Sonda q yazılır. Düzgün: Uşaq pəncərənin qarşısında oyuncaqla oynayırdı.');
INSERT INTO public.questions VALUES (1068, 18, 'g9-aze-orth-q1-18', 1, 18, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yavaş yavaş irəlilədik. Bilirəm ki, sən haqlısan. Qızılgül bağçanı bəzəyirdi.", "B": "Yavaş yavaş irəlilədik. Bilirəmki, sən haqlısan. Qızılgül bağçanı bəzəyirdi.", "C": "Yavaş-yavaş irəlilədik. Bilirəmki, sən haqlısan. Qızılgül bağçanı bəzəyirdi.", "D": "Yavaş-yavaş irəlilədik. Bilirəm ki, sən haqlısan. Qızılgül bağçanı bəzəyirdi.", "E": "Yavaş-yavaş irəlilədik. Bilirəm ki, sən haqlısan. Qızıl gül bağçanı bəzəyirdi."}'::jsonb, 'D', NULL, 'Düzgün: Yavaş-yavaş irəlilədik. Bilirəm ki, sən haqlısan. Qızılgül bağçanı bəzəyirdi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1069, 18, 'g9-aze-orth-q1-19', 1, 19, 'hard', 'single', 'Tələffüzü [yarpaxlar] və [torpax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Yerə düşən yarpaxlar küləkdə torpağa qarışdı.", "B": "Yerə düşən yarpaqlar küləkdə torpaxa qarışdı.", "C": "Yerə düşən yarpaqlar küləkdə torpağa qarışdı.", "D": "Yerə düşən yarpaqlar küləkdə torpaqa qarışdı.", "E": "Yerə düşən yarpaxlar küləkdə torpaxa qarışdı."}'::jsonb, 'C', NULL, '«yarpaqlar» — q yazılır; «torpaq» — Sonda q yazılır. Düzgün: Yerə düşən yarpaqlar küləkdə torpağa qarışdı.');
INSERT INTO public.questions VALUES (1070, 18, 'g9-aze-orth-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «uşağı» və «parkı» sözləri işlənmişdi.", "B": "Diktantda «dənizi» və «sinfi» sözləri işlənmişdi.", "C": "Diktantda «yarpağı» və «ömürü» sözləri işlənmişdi.", "D": "Diktantda «ittifaqı» və «bankı» sözləri işlənmişdi.", "E": "Diktantda «uşağı» və «parğı» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'uşaq → uşağı (q→ğ), park → parkı (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1071, 18, 'g9-aze-orth-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «qulaqı» və «sinfi» sözləri işlənmişdi.", "B": "Diktantda «qulağı» və «sinifi» sözləri işlənmişdi.", "C": "Diktantda «sinfi» və «qarnı» sözləri işlənmişdi.", "D": "Diktantda «qulaqı» və «sinifi» sözləri işlənmişdi.", "E": "Diktantda «bıçağı» və «dənizi» sözləri işlənmişdi."}'::jsonb, 'C', NULL, 'sinif → sinfi (sait düşümü), qarın → qarnı (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1072, 18, 'g9-aze-orth-q1-22', 1, 22, 'hard', 'single', 'Tələffüzü [axsaxqal] və [qonax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Ağsaqal qonaqları qəbul etdi.", "B": "Ağsaqqal qonağları qəbul etdi.", "C": "Ağsaqqal qonaxları qəbul etdi.", "D": "Ağsaqqal qonaqları qəbul etdi.", "E": "Axsaqqal qonaqları qəbul etdi."}'::jsonb, 'D', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «qonaq» — Sonda q yazılır. Düzgün: Ağsaqqal qonaqları qəbul etdi.');
INSERT INTO public.questions VALUES (1073, 18, 'g9-aze-orth-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «burnu», «uşaqı» sözlərini misal gətirdi.", "B": "Müəllim «ağzı», «uşağı» sözlərini misal gətirdi.", "C": "Müəllim «sinfi», «köynəyi» sözlərini misal gətirdi.", "D": "Müəllim «burunu», «uşaqı» sözlərini misal gətirdi.", "E": "Müəllim «fərqi», «oğlu» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'ağız → ağzı (sait düşümü), uşaq → uşağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1074, 18, 'g9-aze-orth-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2026-cı ildə 64-cu yerə çıxdıq.", "B": "Biz 2026-ci ildə 64-cü yerə çıxdıq.", "C": "Biz 2026-cu ildə 64-cü yerə çıxdıq.", "D": "Biz 2026-cı ildə 64-ci yerə çıxdıq.", "E": "Biz 2026-cı ildə 64-cü yerə çıxdıq."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 64-cü.');
INSERT INTO public.questions VALUES (1075, 18, 'g9-aze-orth-q1-25', 1, 25, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yarımada dənizə uzanır. Məndə sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "B": "Yarım ada dənizə uzanır. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "C": "Yarımada dənizə uzanır. Mən də sizinlə gedəcəyəm. Bu, əngözəl mənzərədir.", "D": "Yarımada dənizə uzanır. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "E": "Yarımada dənizə uzanır. Məndə sizinlə gedəcəyəm. Bu, əngözəl mənzərədir."}'::jsonb, 'D', NULL, 'Düzgün: Yarımada dənizə uzanır. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1076, 18, 'g9-aze-orth-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2005-cı ildə 27-ci yerə çıxdıq.", "B": "Biz 2005-ci ildə 27-cü yerə çıxdıq.", "C": "Biz 2005-ci ildə 27-ci yerə çıxdıq.", "D": "Biz 2005-cü ildə 27-ci yerə çıxdıq.", "E": "Biz 2005-ci ildə 27-cı yerə çıxdıq."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2005-ci, 27-ci.');
INSERT INTO public.questions VALUES (1077, 18, 'g9-aze-orth-q1-27', 1, 27, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bilirəmki, sən haqlısan. Ağsaqqal söz aldı. Günə baxan günəşə tərəf dönür.", "B": "Bilirəmki, sən haqlısan. Ağsaqqal söz aldı. Günəbaxan günəşə tərəf dönür.", "C": "Bilirəm ki, sən haqlısan. Ağ saqqal söz aldı. Günəbaxan günəşə tərəf dönür.", "D": "Bilirəm ki, sən haqlısan. Ağsaqqal söz aldı. Günəbaxan günəşə tərəf dönür.", "E": "Bilirəm ki, sən haqlısan. Ağsaqqal söz aldı. Günə baxan günəşə tərəf dönür."}'::jsonb, 'D', NULL, 'Düzgün: Bilirəm ki, sən haqlısan. Ağsaqqal söz aldı. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1078, 18, 'g9-aze-orth-q1-28', 1, 28, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşımda, bacımda gəldi. Ataana övladını qoruyar. Günəbaxan günəşə tərəf dönür.", "B": "Qardaşım da, bacım da gəldi. Ata-ana övladını qoruyar. Günəbaxan günəşə tərəf dönür.", "C": "Qardaşım da, bacım da gəldi. Ataana övladını qoruyar. Günəbaxan günəşə tərəf dönür.", "D": "Qardaşımda, bacımda gəldi. Ata-ana övladını qoruyar. Günəbaxan günəşə tərəf dönür.", "E": "Qardaşım da, bacım da gəldi. Ata-ana övladını qoruyar. Günə baxan günəşə tərəf dönür."}'::jsonb, 'B', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Ata-ana övladını qoruyar. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1079, 18, 'g9-aze-orth-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 2014-cü ildə 6-cü dəfə sərgi açdı.", "B": "Muzey 2014-cı ildə 6-cı dəfə sərgi açdı.", "C": "Muzey 2014-ci ildə 6-cı dəfə sərgi açdı.", "D": "Muzey 2014-cü ildə 6-cı dəfə sərgi açdı.", "E": "Muzey 2014-cü ildə 6-ci dəfə sərgi açdı."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2014-cü, 6-cı.');
INSERT INTO public.questions VALUES (1080, 18, 'g9-aze-orth-q1-30', 1, 30, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Ata-ana övladını qoruyar.", "B": "Yavaş-yavaş irəlilədik. Kitab ev də qalıb. Ata-ana övladını qoruyar.", "C": "Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Ataana övladını qoruyar.", "D": "Yavaş yavaş irəlilədik. Kitab evdə qalıb. Ata-ana övladını qoruyar.", "E": "Yavaş yavaş irəlilədik. Kitab ev də qalıb. Ata-ana övladını qoruyar."}'::jsonb, 'A', NULL, 'Düzgün: Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Ata-ana övladını qoruyar. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1081, 18, 'g9-aze-orth-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə k samiti y ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «dənizi» və «könlü» sözlərini lövhəyə yazdı.", "B": "Şagird «boyunu» və «dirəyi» sözlərini lövhəyə yazdı.", "C": "Şagird «ittifaqı» və «parkı» sözlərini lövhəyə yazdı.", "D": "Şagird «boynu» və «dirəyi» sözlərini lövhəyə yazdı.", "E": "Şagird «ittifaqı» və «bıçağı» sözlərini lövhəyə yazdı."}'::jsonb, 'D', NULL, 'boyun → boynu (sait düşümü), dirək → dirəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1082, 18, 'g9-aze-orth-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2020-ci ildə məktəbimizin 23-ci buraxılışı oldu.", "B": "2020-ci ildə məktəbimizin 23-cu buraxılışı oldu.", "C": "2020-ci ildə məktəbimizin 23-cü buraxılışı oldu.", "D": "2020-ci ildə məktəbimizin 23-cı buraxılışı oldu.", "E": "2020-cü ildə məktəbimizin 23-cü buraxılışı oldu."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2020-ci, 23-cü.');
INSERT INTO public.questions VALUES (1083, 18, 'g9-aze-orth-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2020-cu ildə 10-cu yerə çıxdıq.", "B": "Biz 2020-cü ildə 10-cu yerə çıxdıq.", "C": "Biz 2020-cı ildə 10-cu yerə çıxdıq.", "D": "Biz 2020-ci ildə 10-ci yerə çıxdıq.", "E": "Biz 2020-ci ildə 10-cu yerə çıxdıq."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2020-ci, 10-cu.');
INSERT INTO public.questions VALUES (1084, 18, 'g9-aze-orth-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 2005-ci ildə 100-cü dəfə sərgi açdı.", "B": "Muzey 2005-cü ildə 100-cü dəfə sərgi açdı.", "C": "Muzey 2005-ci ildə 100-ci dəfə sərgi açdı.", "D": "Muzey 2005-ci ildə 100-cı dəfə sərgi açdı.", "E": "Muzey 2005-cu ildə 100-cü dəfə sərgi açdı."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2005-ci, 100-cü.');
INSERT INTO public.questions VALUES (1085, 18, 'g9-aze-orth-q2-05', 2, 5, 'hard', 'single', 'Tələffüzü [axsaxqal] və [qonax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Ağsaqqal qonağları qəbul etdi.", "B": "Ağsaqal qonaqları qəbul etdi.", "C": "Axsaqqal qonaqları qəbul etdi.", "D": "Ağsaxqal qonaqları qəbul etdi.", "E": "Ağsaqqal qonaqları qəbul etdi."}'::jsonb, 'E', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «qonaq» — Sonda q yazılır. Düzgün: Ağsaqqal qonaqları qəbul etdi.');
INSERT INTO public.questions VALUES (1086, 18, 'g9-aze-orth-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə k samiti y ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «ayağı» və «ağzı» sözlərini lövhəyə yazdı.", "B": "Şagird «dirəki» və «uşağı» sözlərini lövhəyə yazdı.", "C": "Şagird «parğı» və «dirəyi» sözlərini lövhəyə yazdı.", "D": "Şagird «parğı» və «dirəki» sözlərini lövhəyə yazdı.", "E": "Şagird «qulağı» və «inəyi» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'qulaq → qulağı (q→ğ), inək → inəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1087, 18, 'g9-aze-orth-q2-07', 2, 7, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ağsaqqal söz aldı. Qardaşım da, bacım da gəldi. Bu, əngözəl mənzərədir.", "B": "Ağ saqqal söz aldı. Qardaşım da, bacım da gəldi. Bu, ən gözəl mənzərədir.", "C": "Ağsaqqal söz aldı. Qardaşım da, bacım da gəldi. Bu, ən gözəl mənzərədir.", "D": "Ağsaqqal söz aldı. Qardaşımda, bacımda gəldi. Bu, əngözəl mənzərədir.", "E": "Ağsaqqal söz aldı. Qardaşımda, bacımda gəldi. Bu, ən gözəl mənzərədir."}'::jsonb, 'C', NULL, 'Düzgün: Ağsaqqal söz aldı. Qardaşım da, bacım da gəldi. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1088, 18, 'g9-aze-orth-q2-08', 2, 8, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Mən də sizinlə gedəcəyəm. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi.", "B": "Mən də sizinlə gedəcəyəm. Sən də bu işdə iştirak et. Qızıl gül bağçanı bəzəyirdi.", "C": "Mən də sizinlə gedəcəyəm. Səndə bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi.", "D": "Məndə sizinlə gedəcəyəm. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi.", "E": "Mən də sizinlə gedəcəyəm. Səndə bu işdə iştirak et. Qızıl gül bağçanı bəzəyirdi."}'::jsonb, 'A', NULL, 'Düzgün: Mən də sizinlə gedəcəyəm. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1089, 18, 'g9-aze-orth-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2003-ci ildə məktəbimizin 16-cı buraxılışı oldu.", "B": "2003-cü ildə məktəbimizin 16-cü buraxılışı oldu.", "C": "2003-cü ildə məktəbimizin 16-cı buraxılışı oldu.", "D": "2003-cu ildə məktəbimizin 16-cı buraxılışı oldu.", "E": "2003-cü ildə məktəbimizin 16-cu buraxılışı oldu."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2003-cü, 16-cı.');
INSERT INTO public.questions VALUES (1090, 18, 'g9-aze-orth-q2-10', 2, 10, 'hard', 'single', 'Tələffüzü [çərşəmbə] və [köynəy''] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Atam çərşənbə günü mənə köynəq aldı.", "B": "Atam çərşənbə günü mənə köynəy aldı.", "C": "Atam çərşənbə günü mənə köynək aldı.", "D": "Atam çərşəmbə günü mənə köynəy aldı.", "E": "Atam çərşəmbə günü mənə köynək aldı."}'::jsonb, 'C', NULL, '«çərşənbə» — n yazılır; «köynək» — Sonda k yazılır. Düzgün: Atam çərşənbə günü mənə köynək aldı.');
INSERT INTO public.questions VALUES (1091, 18, 'g9-aze-orth-q2-11', 2, 11, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Onlar artıq gəldilərmi? Heçkim bu suala cavab vermədi. Heç nə görmədim.", "B": "Onlar artıq gəldilərmi? Heç kim bu suala cavab vermədi. Heçnə görmədim.", "C": "Onlar artıq gəldilərmi? Heçkim bu suala cavab vermədi. Heçnə görmədim.", "D": "Onlar artıq gəldilər mi? Heç kim bu suala cavab vermədi. Heç nə görmədim.", "E": "Onlar artıq gəldilərmi? Heç kim bu suala cavab vermədi. Heç nə görmədim."}'::jsonb, 'E', NULL, 'Düzgün: Onlar artıq gəldilərmi? Heç kim bu suala cavab vermədi. Heç nə görmədim. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1092, 18, 'g9-aze-orth-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «fərqi», «fikri» sözlərini misal gətirdi.", "B": "Müəllim «qulaqı», «şərği» sözlərini misal gətirdi.", "C": "Müəllim «çiçəyi», «burnu» sözlərini misal gətirdi.", "D": "Müəllim «boynu», «şəkli» sözlərini misal gətirdi.", "E": "Müəllim «şəhəri», «qulağı» sözlərini misal gətirdi."}'::jsonb, 'E', NULL, 'şəhər → şəhəri (dəyişmir), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1093, 18, 'g9-aze-orth-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «qulaqı» və «sinfi» sözlərini lövhəyə yazdı.", "B": "Şagird «burnu» və «ömrü» sözlərini lövhəyə yazdı.", "C": "Şagird «çörəyi» və «fərqi» sözlərini lövhəyə yazdı.", "D": "Şagird «uşağı» və «çiçəki» sözlərini lövhəyə yazdı.", "E": "Şagird «ürəyi» və «uşağı» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'ürək → ürəyi (k→y), uşaq → uşağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1094, 18, 'g9-aze-orth-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə kökü dəyişməyən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «uşağı», «fikri» sözlərini misal gətirdi.", "B": "Müəllim «könlü», «burnu» sözlərini misal gətirdi.", "C": "Müəllim «hüququ», «bayraqı» sözlərini misal gətirdi.", "D": "Müəllim «qəfəsi», «çiçəki» sözlərini misal gətirdi.", "E": "Müəllim «bayrağı», «qəfəsi» sözlərini misal gətirdi."}'::jsonb, 'E', NULL, 'bayraq → bayrağı (q→ğ), qəfəs → qəfəsi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1095, 18, 'g9-aze-orth-q2-15', 2, 15, 'hard', 'single', 'Tələffüzü [çərşəmbə] və [köynəy''] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Atam çərşəmbə günü mənə köynək aldı.", "B": "Atam çərşənbə günü mənə köynəq aldı.", "C": "Atam çərşəmbə günü mənə köynəq aldı.", "D": "Atam çərşənbə günü mənə köynək aldı.", "E": "Atam çərşənbə günü mənə köynəy aldı."}'::jsonb, 'D', NULL, '«çərşənbə» — n yazılır; «köynək» — Sonda k yazılır. Düzgün: Atam çərşənbə günü mənə köynək aldı.');
INSERT INTO public.questions VALUES (1096, 18, 'g9-aze-orth-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2003-ci ildə 20-ci yerə çıxdıq.", "B": "Biz 2003-cü ildə 20-ci yerə çıxdıq.", "C": "Biz 2003-cü ildə 20-cu yerə çıxdıq.", "D": "Biz 2003-cu ildə 20-ci yerə çıxdıq.", "E": "Biz 2003-cü ildə 20-cü yerə çıxdıq."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2003-cü, 20-ci.');
INSERT INTO public.questions VALUES (1097, 18, 'g9-aze-orth-q2-17', 2, 17, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et. Ata-ana övladını qoruyar.", "B": "Qardaşım da, bacım da gəldi. Səndə bu işdə iştirak et. Ata-ana övladını qoruyar.", "C": "Qardaşımda, bacımda gəldi. Sən də bu işdə iştirak et. Ata-ana övladını qoruyar.", "D": "Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et. Ataana övladını qoruyar.", "E": "Qardaşımda, bacımda gəldi. Sən də bu işdə iştirak et. Ataana övladını qoruyar."}'::jsonb, 'A', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et. Ata-ana övladını qoruyar. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1098, 18, 'g9-aze-orth-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2026-cu ildə məktəbimizin 46-cı buraxılışı oldu.", "B": "2026-cı ildə məktəbimizin 46-cü buraxılışı oldu.", "C": "2026-cı ildə məktəbimizin 46-ci buraxılışı oldu.", "D": "2026-ci ildə məktəbimizin 46-cı buraxılışı oldu.", "E": "2026-cı ildə məktəbimizin 46-cı buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 46-cı.');
INSERT INTO public.questions VALUES (1099, 18, 'g9-aze-orth-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1945-ci ildə 7-cu yerə çıxdıq.", "B": "Biz 1945-ci ildə 7-cü yerə çıxdıq.", "C": "Biz 1945-ci ildə 7-ci yerə çıxdıq.", "D": "Biz 1945-cu ildə 7-ci yerə çıxdıq.", "E": "Biz 1945-cı ildə 7-ci yerə çıxdıq."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1945-ci, 7-ci.');
INSERT INTO public.questions VALUES (1100, 18, 'g9-aze-orth-q2-20', 2, 20, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə gülə danışırdı. Yarımada dənizə uzanır. Ata-ana övladını qoruyar.", "B": "Gülə-gülə danışırdı. Yarım ada dənizə uzanır. Ata-ana övladını qoruyar.", "C": "Gülə gülə danışırdı. Yarım ada dənizə uzanır. Ata-ana övladını qoruyar.", "D": "Gülə-gülə danışırdı. Yarımada dənizə uzanır. Ata-ana övladını qoruyar.", "E": "Gülə-gülə danışırdı. Yarımada dənizə uzanır. Ataana övladını qoruyar."}'::jsonb, 'D', NULL, 'Düzgün: Gülə-gülə danışırdı. Yarımada dənizə uzanır. Ata-ana övladını qoruyar. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1101, 18, 'g9-aze-orth-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «şəkili» və «burunu» sözləri işlənmişdi.", "B": "Diktantda «fikiri» və «köynəki» sözləri işlənmişdi.", "C": "Diktantda «fikri» və «köynəki» sözləri işlənmişdi.", "D": "Diktantda «alını» və «fərqi» sözləri işlənmişdi.", "E": "Diktantda «oğlu» və «ayağı» sözləri işlənmişdi."}'::jsonb, 'E', NULL, 'oğul → oğlu (sait düşümü), ayaq → ayağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1102, 18, 'g9-aze-orth-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə k samiti y ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «inəyi», «dənzi» sözlərini misal gətirdi.", "B": "Müəllim «ayaqı», «köynəki» sözlərini misal gətirdi.", "C": "Müəllim «bayrağı», «burnu» sözlərini misal gətirdi.", "D": "Müəllim «inəyi», «dənizi» sözlərini misal gətirdi.", "E": "Müəllim «bayrağı», «ağzı» sözlərini misal gətirdi."}'::jsonb, 'D', NULL, 'inək → inəyi (k→y), dəniz → dənizi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1103, 18, 'g9-aze-orth-q2-23', 2, 23, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yavaş yavaş irəlilədik. Qardaşım da, bacım da gəldi. Günəbaxan günəşə tərəf dönür.", "B": "Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi. Günəbaxan günəşə tərəf dönür.", "C": "Yavaş yavaş irəlilədik. Qardaşım da, bacım da gəldi. Günə baxan günəşə tərəf dönür.", "D": "Yavaş-yavaş irəlilədik. Qardaşımda, bacımda gəldi. Günəbaxan günəşə tərəf dönür.", "E": "Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi. Günə baxan günəşə tərəf dönür."}'::jsonb, 'B', NULL, 'Düzgün: Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1104, 18, 'g9-aze-orth-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «tankı» və «qulağı» sözlərini lövhəyə yazdı.", "B": "Şagird «nitqi» və «hüququ» sözlərini lövhəyə yazdı.", "C": "Şagird «ittifağı» və «uşağı» sözlərini lövhəyə yazdı.", "D": "Şagird «ayaqı» və «parkı» sözlərini lövhəyə yazdı.", "E": "Şagird «ayaqı» və «parğı» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'tank → tankı (dəyişmir), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1105, 18, 'g9-aze-orth-q2-25', 2, 25, 'hard', 'single', 'Tələffüzü [çörəy''] və [qənt] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Nənəm isti çörəq və qənd süfrəyə qoydu.", "B": "Nənəm isti çörəy və qənd süfrəyə qoydu.", "C": "Nənəm isti çörək və qənd süfrəyə qoydu.", "D": "Nənəm isti çörək və qənt süfrəyə qoydu.", "E": "Nənəm isti çörəq və qənt süfrəyə qoydu."}'::jsonb, 'C', NULL, '«çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır; «qənd» — Sonda d yazılır. Düzgün: Nənəm isti çörək və qənd süfrəyə qoydu.');
INSERT INTO public.questions VALUES (1106, 18, 'g9-aze-orth-q2-26', 2, 26, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Dedi ki, sabah gələcək. Qardaşım da, bacım da gəldi. Səndə bu işdə iştirak et.", "B": "Dediki, sabah gələcək. Qardaşım da, bacım da gəldi. Səndə bu işdə iştirak et.", "C": "Dedi ki, sabah gələcək. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et.", "D": "Dedi ki, sabah gələcək. Qardaşımda, bacımda gəldi. Sən də bu işdə iştirak et.", "E": "Dediki, sabah gələcək. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et."}'::jsonb, 'C', NULL, 'Düzgün: Dedi ki, sabah gələcək. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1107, 18, 'g9-aze-orth-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1990-cı ildə 100-cü yerə çıxdıq.", "B": "Biz 1990-cu ildə 100-cü yerə çıxdıq.", "C": "Biz 1990-cü ildə 100-cü yerə çıxdıq.", "D": "Biz 1990-ci ildə 100-cü yerə çıxdıq.", "E": "Biz 1990-cı ildə 100-ci yerə çıxdıq."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1990-cı, 100-cü.');
INSERT INTO public.questions VALUES (1108, 18, 'g9-aze-orth-q2-28', 2, 28, 'hard', 'single', 'Tələffüzü [qonax] və [baxça] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Qonax bağçanın yolunu tanıyırdı.", "B": "Qonağ baxçanın yolunu tanıyırdı.", "C": "Qonaq bağçanın yolunu tanıyırdı.", "D": "Qonaq baxçanın yolunu tanıyırdı.", "E": "Qonağ bağçanın yolunu tanıyırdı."}'::jsonb, 'C', NULL, '«qonaq» — Sonda q yazılır; «bağça» — ğ kar samitdən əvvəl x kimi tələffüz olunur, ğ yazılır. Düzgün: Qonaq bağçanın yolunu tanıyırdı.');
INSERT INTO public.questions VALUES (1109, 18, 'g9-aze-orth-q2-29', 2, 29, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «heç» sözünün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağ saqqal söz aldı.", "B": "Bilirəm ki, sən haqlısan. Heçnə görmədim. Ağsaqqal söz aldı.", "C": "Bilirəmki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı.", "D": "Bilirəm ki, sən haqlısan. Heçnə görmədim. Ağ saqqal söz aldı.", "E": "Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı."}'::jsonb, 'E', NULL, 'Düzgün: Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1110, 18, 'g9-aze-orth-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 2026-cı ildə 23-cü dəfə sərgi açdı.", "B": "Muzey 2026-ci ildə 23-cü dəfə sərgi açdı.", "C": "Muzey 2026-cı ildə 23-ci dəfə sərgi açdı.", "D": "Muzey 2026-cı ildə 23-cu dəfə sərgi açdı.", "E": "Muzey 2026-cü ildə 23-cü dəfə sərgi açdı."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 23-cü.');
INSERT INTO public.questions VALUES (1111, 18, 'g9-aze-orth-q3-01', 3, 1, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşım da, bacım da gəldi. Masadakı kitab mənimdir. Ayaqqabılarını təmizlədi.", "B": "Qardaşım da, bacım da gəldi. Masada ki kitab mənimdir. Ayaqqabılarını təmizlədi.", "C": "Qardaşımda, bacımda gəldi. Masadakı kitab mənimdir. Ayaq qabılarını təmizlədi.", "D": "Qardaşım da, bacım da gəldi. Masadakı kitab mənimdir. Ayaq qabılarını təmizlədi.", "E": "Qardaşımda, bacımda gəldi. Masadakı kitab mənimdir. Ayaqqabılarını təmizlədi."}'::jsonb, 'A', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Masadakı kitab mənimdir. Ayaqqabılarını təmizlədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1112, 18, 'g9-aze-orth-q3-02', 3, 2, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ən» ədatının, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bu, ən gözəl mənzərədir. Dediki, sabah gələcək. Evdə ki hamı yatmışdı.", "B": "Bu, ən gözəl mənzərədir. Dediki, sabah gələcək. Evdəki hamı yatmışdı.", "C": "Bu, ən gözəl mənzərədir. Dedi ki, sabah gələcək. Evdəki hamı yatmışdı.", "D": "Bu, ən gözəl mənzərədir. Dedi ki, sabah gələcək. Evdə ki hamı yatmışdı.", "E": "Bu, əngözəl mənzərədir. Dedi ki, sabah gələcək. Evdəki hamı yatmışdı."}'::jsonb, 'C', NULL, 'Düzgün: Bu, ən gözəl mənzərədir. Dedi ki, sabah gələcək. Evdəki hamı yatmışdı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1113, 18, 'g9-aze-orth-q3-03', 3, 3, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Mən də sizinlə gedəcəyəm. Ata-ana övladını qoruyar. Evdəki hamı yatmışdı.", "B": "Məndə sizinlə gedəcəyəm. Ataana övladını qoruyar. Evdəki hamı yatmışdı.", "C": "Mən də sizinlə gedəcəyəm. Ataana övladını qoruyar. Evdəki hamı yatmışdı.", "D": "Mən də sizinlə gedəcəyəm. Ata-ana övladını qoruyar. Evdə ki hamı yatmışdı.", "E": "Məndə sizinlə gedəcəyəm. Ata-ana övladını qoruyar. Evdəki hamı yatmışdı."}'::jsonb, 'A', NULL, 'Düzgün: Mən də sizinlə gedəcəyəm. Ata-ana övladını qoruyar. Evdəki hamı yatmışdı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1114, 18, 'g9-aze-orth-q3-04', 3, 4, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Masada ki kitab mənimdir. Evdəki hamı yatmışdı. Bu, ən gözəl mənzərədir.", "B": "Masadakı kitab mənimdir. Evdəki hamı yatmışdı. Bu, əngözəl mənzərədir.", "C": "Masadakı kitab mənimdir. Evdəki hamı yatmışdı. Bu, ən gözəl mənzərədir.", "D": "Masadakı kitab mənimdir. Evdə ki hamı yatmışdı. Bu, ən gözəl mənzərədir.", "E": "Masada ki kitab mənimdir. Evdəki hamı yatmışdı. Bu, əngözəl mənzərədir."}'::jsonb, 'C', NULL, 'Düzgün: Masadakı kitab mənimdir. Evdəki hamı yatmışdı. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1115, 18, 'g9-aze-orth-q3-05', 3, 5, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, «heç» sözünün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Günə baxan günəşə tərəf dönür. Heç nə görmədim. Qardaşım da, bacım da gəldi.", "B": "Günəbaxan günəşə tərəf dönür. Heç nə görmədim. Qardaşımda, bacımda gəldi.", "C": "Günəbaxan günəşə tərəf dönür. Heçnə görmədim. Qardaşımda, bacımda gəldi.", "D": "Günəbaxan günəşə tərəf dönür. Heçnə görmədim. Qardaşım da, bacım da gəldi.", "E": "Günəbaxan günəşə tərəf dönür. Heç nə görmədim. Qardaşım da, bacım da gəldi."}'::jsonb, 'E', NULL, 'Düzgün: Günəbaxan günəşə tərəf dönür. Heç nə görmədim. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1116, 18, 'g9-aze-orth-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2023-cu ildə məktəbimizin 79-cu buraxılışı oldu.", "B": "2023-cü ildə məktəbimizin 79-cı buraxılışı oldu.", "C": "2023-cü ildə məktəbimizin 79-ci buraxılışı oldu.", "D": "2023-cı ildə məktəbimizin 79-cu buraxılışı oldu.", "E": "2023-cü ildə məktəbimizin 79-cu buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2023-cü, 79-cu.');
INSERT INTO public.questions VALUES (1117, 18, 'g9-aze-orth-q3-07', 3, 7, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, sual ədatının (-mı, -mi), «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Mən də sizinlə gedəcəyəm. Onlar artıq gəldilərmi? Masadakı kitab mənimdir.", "B": "Məndə sizinlə gedəcəyəm. Onlar artıq gəldilərmi? Masadakı kitab mənimdir.", "C": "Məndə sizinlə gedəcəyəm. Onlar artıq gəldilərmi? Masada ki kitab mənimdir.", "D": "Mən də sizinlə gedəcəyəm. Onlar artıq gəldilər mi? Masadakı kitab mənimdir.", "E": "Mən də sizinlə gedəcəyəm. Onlar artıq gəldilərmi? Masada ki kitab mənimdir."}'::jsonb, 'A', NULL, 'Düzgün: Mən də sizinlə gedəcəyəm. Onlar artıq gəldilərmi? Masadakı kitab mənimdir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1118, 18, 'g9-aze-orth-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə q samiti ğ ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «bıçağı», «bayrağı» sözlərini misal gətirdi.", "B": "Müəllim «şəhri», «bayrağı» sözlərini misal gətirdi.", "C": "Müəllim «inəyi», «qulaqı» sözlərini misal gətirdi.", "D": "Müəllim «bıçaqı», «bayrağı» sözlərini misal gətirdi.", "E": "Müəllim «bayraqı», «dənizi» sözlərini misal gətirdi."}'::jsonb, 'A', NULL, 'bıçaq → bıçağı (q→ğ), bayraq → bayrağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1119, 18, 'g9-aze-orth-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «oğlu» və «banğı» sözlərini lövhəyə yazdı.", "B": "Şagird «uşağı» və «qulağı» sözlərini lövhəyə yazdı.", "C": "Şagird «könlü» və «parğı» sözlərini lövhəyə yazdı.", "D": "Şagird «tankı» və «ismi» sözlərini lövhəyə yazdı.", "E": "Şagird «hüquğu» və «oğulu» sözlərini lövhəyə yazdı."}'::jsonb, 'D', NULL, 'tank → tankı (dəyişmir), isim → ismi (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1120, 18, 'g9-aze-orth-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1990-cı ildə 7-ci dəfə sərgi açdı.", "B": "Muzey 1990-cı ildə 7-cu dəfə sərgi açdı.", "C": "Muzey 1990-cu ildə 7-ci dəfə sərgi açdı.", "D": "Muzey 1990-cü ildə 7-ci dəfə sərgi açdı.", "E": "Muzey 1990-cı ildə 7-cü dəfə sərgi açdı."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1990-cı, 7-ci.');
INSERT INTO public.questions VALUES (1121, 18, 'g9-aze-orth-q3-11', 3, 11, 'hard', 'single', 'Tələffüzü [doxquz] və [cavap] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim doqquz sualın cavabını yazdı.", "B": "Müəllim doquz sualın cavabını yazdı.", "C": "Müəllim doquz sualın cavapını yazdı.", "D": "Müəllim doxquz sualın cavabını yazdı.", "E": "Müəllim doqquz sualın cavapını yazdı."}'::jsonb, 'A', NULL, '«doqquz» — qq birləşməsində birinci q x kimi tələffüz olunur, qq yazılır; «cavab» — Sonda b yazılır. Düzgün: Müəllim doqquz sualın cavabını yazdı.');
INSERT INTO public.questions VALUES (1122, 18, 'g9-aze-orth-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1996-cu ildə 20-ci yerə çıxdıq.", "B": "Biz 1996-cı ildə 20-cı yerə çıxdıq.", "C": "Biz 1996-cü ildə 20-ci yerə çıxdıq.", "D": "Biz 1996-cı ildə 20-ci yerə çıxdıq.", "E": "Biz 1996-cı ildə 20-cu yerə çıxdıq."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1996-cı, 20-ci.');
INSERT INTO public.questions VALUES (1123, 18, 'g9-aze-orth-q3-13', 3, 13, 'hard', 'single', 'Tələffüzü [axsaxqal] və [qonax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Axsaqqal qonaqları qəbul etdi.", "B": "Ağsaqqal qonaqları qəbul etdi.", "C": "Axsaxqal qonaqları qəbul etdi.", "D": "Ağsaqqal qonaxları qəbul etdi.", "E": "Ağsaqqal qonağları qəbul etdi."}'::jsonb, 'B', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «qonaq» — Sonda q yazılır. Düzgün: Ağsaqqal qonaqları qəbul etdi.');
INSERT INTO public.questions VALUES (1124, 18, 'g9-aze-orth-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə k samiti y ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «ürəyi», «ittifağı» sözlərini misal gətirdi.", "B": "Müəllim «bıçağı», «qəfəsi» sözlərini misal gətirdi.", "C": "Müəllim «inəyi», «dənizi» sözlərini misal gətirdi.", "D": "Müəllim «parkı», «könlü» sözlərini misal gətirdi.", "E": "Müəllim «ürəki», «ittifaqı» sözlərini misal gətirdi."}'::jsonb, 'C', NULL, 'inək → inəyi (k→y), dəniz → dənizi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1125, 18, 'g9-aze-orth-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə k samiti y ilə əvəzlənən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «uşağı» və «çiçəki» sözlərini lövhəyə yazdı.", "B": "Şagird «inəki» və «şərği» sözlərini lövhəyə yazdı.", "C": "Şagird «hüququ» və «fikri» sözlərini lövhəyə yazdı.", "D": "Şagird «fərqi» və «ürəyi» sözlərini lövhəyə yazdı.", "E": "Şagird «fərqi» və «ürəki» sözlərini lövhəyə yazdı."}'::jsonb, 'D', NULL, 'fərq → fərqi (dəyişmir), ürək → ürəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1126, 18, 'g9-aze-orth-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2005-ci ildə məktəbimizin 3-cı buraxılışı oldu.", "B": "2005-cı ildə məktəbimizin 3-cü buraxılışı oldu.", "C": "2005-ci ildə məktəbimizin 3-cü buraxılışı oldu.", "D": "2005-ci ildə məktəbimizin 3-cu buraxılışı oldu.", "E": "2005-cü ildə məktəbimizin 3-cü buraxılışı oldu."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2005-ci, 3-cü.');
INSERT INTO public.questions VALUES (1127, 18, 'g9-aze-orth-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «fərqi» və «oğlu» sözləri işlənmişdi.", "B": "Diktantda «çörəyi» və «şəkili» sözləri işlənmişdi.", "C": "Diktantda «çiçəyi» və «hüququ» sözləri işlənmişdi.", "D": "Diktantda «isimi» və «parkı» sözləri işlənmişdi.", "E": "Diktantda «dirəyi» və «çörəyi» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'fərq → fərqi (dəyişmir), oğul → oğlu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1128, 18, 'g9-aze-orth-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2003-ci ildə məktəbimizin 23-cü buraxılışı oldu.", "B": "2003-cü ildə məktəbimizin 23-cu buraxılışı oldu.", "C": "2003-cü ildə məktəbimizin 23-cü buraxılışı oldu.", "D": "2003-cü ildə məktəbimizin 23-ci buraxılışı oldu.", "E": "2003-cü ildə məktəbimizin 23-cı buraxılışı oldu."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2003-cü, 23-cü.');
INSERT INTO public.questions VALUES (1129, 18, 'g9-aze-orth-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "1945-ci ildə məktəbimizin 30-cü buraxılışı oldu.", "B": "1945-cı ildə məktəbimizin 30-cu buraxılışı oldu.", "C": "1945-ci ildə məktəbimizin 30-cı buraxılışı oldu.", "D": "1945-cu ildə məktəbimizin 30-cu buraxılışı oldu.", "E": "1945-ci ildə məktəbimizin 30-cu buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1945-ci, 30-cu.');
INSERT INTO public.questions VALUES (1130, 18, 'g9-aze-orth-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Şagird «bankı» və «yarpağı» sözlərini lövhəyə yazdı.", "B": "Şagird «bıçağı» və «ömrü» sözlərini lövhəyə yazdı.", "C": "Şagird «ürəyi» və «bayrağı» sözlərini lövhəyə yazdı.", "D": "Şagird «burunu» və «oğulu» sözlərini lövhəyə yazdı.", "E": "Şagird «hüququ» və «ayağı» sözlərini lövhəyə yazdı."}'::jsonb, 'B', NULL, 'bıçaq → bıçağı (q→ğ), ömür → ömrü (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1131, 18, 'g9-aze-orth-q3-21', 3, 21, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, sual ədatının (-mı, -mi), «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Evdə ki hamı yatmışdı. Sən bu kitabı oxudunmu? Heç kim bu suala cavab vermədi.", "B": "Evdəki hamı yatmışdı. Sən bu kitabı oxudun mu? Heç kim bu suala cavab vermədi.", "C": "Evdə ki hamı yatmışdı. Sən bu kitabı oxudun mu? Heç kim bu suala cavab vermədi.", "D": "Evdəki hamı yatmışdı. Sən bu kitabı oxudunmu? Heçkim bu suala cavab vermədi.", "E": "Evdəki hamı yatmışdı. Sən bu kitabı oxudunmu? Heç kim bu suala cavab vermədi."}'::jsonb, 'E', NULL, 'Düzgün: Evdəki hamı yatmışdı. Sən bu kitabı oxudunmu? Heç kim bu suala cavab vermədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1132, 18, 'g9-aze-orth-q3-22', 3, 22, 'hard', 'single', 'Tələffüzü [saxqal] və [bıçax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Babamın uzun saxqalı və köhnə bıçağı var idi.", "B": "Babamın uzun saqqalı və köhnə bıçaxı var idi.", "C": "Babamın uzun saqqalı və köhnə bıçaqı var idi.", "D": "Babamın uzun saqqalı və köhnə bıçağı var idi.", "E": "Babamın uzun saqalı və köhnə bıçağı var idi."}'::jsonb, 'D', NULL, '«saqqal» — qq yazılır; «bıçaq» — Sonda q yazılır. Düzgün: Babamın uzun saqqalı və köhnə bıçağı var idi.');
INSERT INTO public.questions VALUES (1133, 18, 'g9-aze-orth-q3-23', 3, 23, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Evdəki hamı yatmışdı. Yarımada dənizə uzanır. Ara-sıra bizə baş çəkir.", "B": "Evdəki hamı yatmışdı. Yarımada dənizə uzanır. Arasıra bizə baş çəkir.", "C": "Evdə ki hamı yatmışdı. Yarımada dənizə uzanır. Arasıra bizə baş çəkir.", "D": "Evdəki hamı yatmışdı. Yarım ada dənizə uzanır. Ara-sıra bizə baş çəkir.", "E": "Evdə ki hamı yatmışdı. Yarımada dənizə uzanır. Ara-sıra bizə baş çəkir."}'::jsonb, 'A', NULL, 'Düzgün: Evdəki hamı yatmışdı. Yarımada dənizə uzanır. Ara-sıra bizə baş çəkir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1134, 18, 'g9-aze-orth-q3-24', 3, 24, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2023-cü ildə 90-cı yerə çıxdıq.", "B": "Biz 2023-cu ildə 90-cı yerə çıxdıq.", "C": "Biz 2023-cü ildə 90-cü yerə çıxdıq.", "D": "Biz 2023-ci ildə 90-cı yerə çıxdıq.", "E": "Biz 2023-cü ildə 90-ci yerə çıxdıq."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2023-cü, 90-cı.');
INSERT INTO public.questions VALUES (1135, 18, 'g9-aze-orth-q3-25', 3, 25, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ən» ədatının, qoşa sözün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bu, ən gözəl mənzərədir. Ara-sıra bizə baş çəkir. Yarımada dənizə uzanır.", "B": "Bu, ən gözəl mənzərədir. Arasıra bizə baş çəkir. Yarımada dənizə uzanır.", "C": "Bu, ən gözəl mənzərədir. Ara-sıra bizə baş çəkir. Yarım ada dənizə uzanır.", "D": "Bu, ən gözəl mənzərədir. Arasıra bizə baş çəkir. Yarım ada dənizə uzanır.", "E": "Bu, əngözəl mənzərədir. Ara-sıra bizə baş çəkir. Yarımada dənizə uzanır."}'::jsonb, 'A', NULL, 'Düzgün: Bu, ən gözəl mənzərədir. Ara-sıra bizə baş çəkir. Yarımada dənizə uzanır. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (1136, 18, 'g9-aze-orth-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 2026-cı ildə 40-cu dəfə sərgi açdı.", "B": "Muzey 2026-cı ildə 40-cı dəfə sərgi açdı.", "C": "Muzey 2026-cı ildə 40-cü dəfə sərgi açdı.", "D": "Muzey 2026-cı ildə 40-ci dəfə sərgi açdı.", "E": "Muzey 2026-ci ildə 40-cı dəfə sərgi açdı."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 40-cı.');
INSERT INTO public.questions VALUES (1137, 18, 'g9-aze-orth-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə kökündə sait düşən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Diktantda «parkı» və «şəhəri» sözləri işlənmişdi.", "B": "Diktantda «ürəyi» və «qulağı» sözləri işlənmişdi.", "C": "Diktantda «ittifağı» və «oğlu» sözləri işlənmişdi.", "D": "Diktantda «ittifağı» və «oğulu» sözləri işlənmişdi.", "E": "Diktantda «fikri» və «fərqi» sözləri işlənmişdi."}'::jsonb, 'E', NULL, 'fikir → fikri (sait düşümü), fərq → fərqi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1138, 18, 'g9-aze-orth-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə kökü dəyişməyən söz var və cümlədə orfoqrafik səhv yoxdur?', NULL, NULL, '{"A": "Müəllim «xalğı», «dirəyi» sözlərini misal gətirdi.", "B": "Müəllim «hüququ», «bıçağı» sözlərini misal gətirdi.", "C": "Müəllim «ağzı», «alnı» sözlərini misal gətirdi.", "D": "Müəllim «qəfsi», «yarpaqı» sözlərini misal gətirdi.", "E": "Müəllim «yarpağı», «qəfsi» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'hüquq → hüququ (dəyişmir), bıçaq → bıçağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (1139, 18, 'g9-aze-orth-q3-29', 3, 29, 'hard', 'single', 'Tələffüzü [qonax] və [baxça] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Qonax baxçanın yolunu tanıyırdı.", "B": "Qonaq bağçanın yolunu tanıyırdı.", "C": "Qonax bağçanın yolunu tanıyırdı.", "D": "Qonaq baxçanın yolunu tanıyırdı.", "E": "Qonağ bağçanın yolunu tanıyırdı."}'::jsonb, 'B', NULL, '«qonaq» — Sonda q yazılır; «bağça» — ğ kar samitdən əvvəl x kimi tələffüz olunur, ğ yazılır. Düzgün: Qonaq bağçanın yolunu tanıyırdı.');
INSERT INTO public.questions VALUES (1140, 18, 'g9-aze-orth-q3-30', 3, 30, 'hard', 'single', 'Tələffüzü [yarpaxlar] və [torpax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Yerə düşən yarpaqlar küləkdə torpaqa qarışdı.", "B": "Yerə düşən yarpaqlar küləkdə torpaxa qarışdı.", "C": "Yerə düşən yarpaxlar küləkdə torpaqa qarışdı.", "D": "Yerə düşən yarpaxlar küləkdə torpağa qarışdı.", "E": "Yerə düşən yarpaqlar küləkdə torpağa qarışdı."}'::jsonb, 'E', NULL, '«yarpaqlar» — q yazılır; «torpaq» — Sonda q yazılır. Düzgün: Yerə düşən yarpaqlar küləkdə torpağa qarışdı.');
INSERT INTO public.questions VALUES (1141, 19, 'g9-aze-syn-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Gənc müəllim cavan həmkarına kömək etdi. (gənc – cavan: antonim)", "B": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: sinonim)", "C": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: antonim)", "D": "Bu gülü sənə verirəm, bir az gül. (gül – gül: omonim)", "E": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: omonim)"}'::jsonb, 'D', NULL, '«gül» və «gül» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1142, 19, 'g9-aze-syn-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə omonimlər müxtəlif nitq hissələrinə aiddir və sinonim işlənməyib?', NULL, NULL, '{"A": "Sevinclə kədər bir-birini əvəz edirdi.", "B": "Tut ağacından tut dər, səbəti möhkəm tut.", "C": "Çay kənarında oturub isti çay içdik.", "D": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi.", "E": "Gecənin sükutu gündüzün səs-küyünü unutdurdu."}'::jsonb, 'B', NULL, 'Cümlədə: tut – tut (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1143, 19, 'g9-aze-syn-q1-03', 1, 3, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Çay kənarında oturub isti çay içdik. (çay – çay: sinonim)", "B": "Gecənin sükutu gündüzün səs-küyünü unutdurdu. (gecə – gündüz: antonim)", "C": "Ağır çantanı yüngül səbətlə dəyişdi. (ağır – yüngül: sinonim)", "D": "Qız saçını daradı, sonra quşlara dən saçdı. (saç – saç: sinonim)", "E": "Bu gözəl şəhərin qəşəng küçələri var. (gözəl – qəşəng: antonim)"}'::jsonb, 'B', NULL, '«gecə» və «gündüz» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1144, 19, 'g9-aze-syn-q1-04', 1, 4, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır. (kasıb – varlı: omonim)", "B": "Çay kənarında oturub isti çay içdik. (çay – çay: antonim)", "C": "Gecənin sükutu gündüzün səs-küyünü unutdurdu. (gecə – gündüz: sinonim)", "D": "Tut ağacından tut dər, səbəti möhkəm tut. (tut – tut: antonim)", "E": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi. (tənbəl – çalışqan: antonim)"}'::jsonb, 'E', NULL, '«tənbəl» və «çalışqan» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1145, 19, 'g9-aze-syn-q1-05', 1, 5, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Atı tövləyə apar, topu da bura at. (at – at: sinonim)", "B": "Yaz gəldi, dəftərinə bu şeiri yaz. (yaz – yaz: antonim)", "C": "Dolu yağanda vedrə su ilə dolu idi. (dolu – dolu: omonim)", "D": "Yeni dərslikləri köhnə kitabların yanına qoydu. (yeni – köhnə: omonim)", "E": "İsti yay günlərində soyuq su içməyi xoşlayırıq. (isti – soyuq: omonim)"}'::jsonb, 'C', NULL, '«dolu» və «dolu» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1146, 19, 'g9-aze-syn-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə antonim işlənməyib və sinonim işlənib?', NULL, NULL, '{"A": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "B": "Bu gülü sənə verirəm, bir az gül.", "C": "Dolu yağanda vedrə su ilə dolu idi.", "D": "Atı tövləyə apar, topu da bura at.", "E": "Qoca bağban ahıl qonşusu ilə söhbət edirdi."}'::jsonb, 'E', NULL, 'Cümlədə: qoca – ahıl (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1147, 19, 'g9-aze-syn-q1-07', 1, 7, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Atı tövləyə apar, topu da bura at. (at – at: antonim)", "B": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır. (kasıb – varlı: antonim)", "C": "Yaz gəldi, dəftərinə bu şeiri yaz. (yaz – yaz: sinonim)", "D": "Bu gülü sənə verirəm, bir az gül. (gül – gül: sinonim)", "E": "Atı tövləyə apar, topu da bura at. (at – at: sinonim)"}'::jsonb, 'B', NULL, '«kasıb» və «varlı» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1148, 19, 'g9-aze-syn-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə antonim işlənib və omonim işlənməyib?', NULL, NULL, '{"A": "Gənc müəllim cavan həmkarına kömək etdi.", "B": "Qoca bağban ahıl qonşusu ilə söhbət edirdi.", "C": "Gecənin sükutu gündüzün səs-küyünü unutdurdu.", "D": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı.", "E": "Uşaqların sevinci və fərəhi hamıya yoluxdu."}'::jsonb, 'C', NULL, 'Cümlədə: gecə – gündüz (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1149, 19, 'g9-aze-syn-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə sinonimlər sifətlə ifadə olunub və omonim işlənməyib?', NULL, NULL, '{"A": "Qoca bağban ahıl qonşusu ilə söhbət edirdi.", "B": "İsti yay günlərində soyuq su içməyi xoşlayırıq.", "C": "Dost da, düşmən də onun cəsarətini etiraf etdi.", "D": "Sevinclə kədər bir-birini əvəz edirdi.", "E": "Uzun yolu qısa vaxtda qət etdik."}'::jsonb, 'A', NULL, 'Cümlədə: qoca – ahıl (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1150, 19, 'g9-aze-syn-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə omonimlər müxtəlif nitq hissələrinə aiddir və antonim işlənməyib?', NULL, NULL, '{"A": "Qardaşım yavaş, asta addımlarla otağa girdi.", "B": "Bu gözəl şəhərin qəşəng küçələri var.", "C": "Gənc müəllim cavan həmkarına kömək etdi.", "D": "Tut ağacından tut dər, səbəti möhkəm tut.", "E": "Çay kənarında oturub isti çay içdik."}'::jsonb, 'D', NULL, 'Cümlədə: tut – tut (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1151, 19, 'g9-aze-syn-q1-11', 1, 11, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi. (cəsur – igid: omonim)", "B": "Qoca bağban ahıl qonşusu ilə söhbət edirdi. (qoca – ahıl: sinonim)", "C": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: omonim)", "D": "Sevinclə kədər bir-birini əvəz edirdi. (sevinc – kədər: omonim)", "E": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: antonim)"}'::jsonb, 'B', NULL, '«qoca» və «ahıl» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1152, 19, 'g9-aze-syn-q1-12', 1, 12, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: antonim)", "B": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: sinonim)", "C": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi. (cəsur – igid: omonim)", "D": "Qız saçını daradı, sonra quşlara dən saçdı. (saç – saç: sinonim)", "E": "İsti yay günlərində soyuq su içməyi xoşlayırıq. (isti – soyuq: omonim)"}'::jsonb, 'B', NULL, '«kədər» və «qəm» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1153, 19, 'g9-aze-syn-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə omonim işlənib və sinonim işlənməyib?', NULL, NULL, '{"A": "Uzun yolu qısa vaxtda qət etdik.", "B": "Çay kənarında oturub isti çay içdik.", "C": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "D": "Gecənin sükutu gündüzün səs-küyünü unutdurdu.", "E": "İsti yay günlərində soyuq su içməyi xoşlayırıq."}'::jsonb, 'B', NULL, 'Cümlədə: çay – çay (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1154, 19, 'g9-aze-syn-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə omonimlər müxtəlif nitq hissələrinə aiddir və sinonim işlənməyib?', NULL, NULL, '{"A": "Səhərdən axşama qədər bağda işlədik.", "B": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "C": "Dolu yağanda vedrə su ilə dolu idi.", "D": "Sevinclə kədər bir-birini əvəz edirdi.", "E": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır."}'::jsonb, 'C', NULL, 'Cümlədə: dolu – dolu (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
