INSERT INTO public.questions VALUES (1156, 19, 'g9-aze-syn-q1-16', 1, 16, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Uşaqların sevinci və fərəhi hamıya yoluxdu. (sevinc – fərəh: omonim)", "B": "Ağır çantanı yüngül səbətlə dəyişdi. (ağır – yüngül: omonim)", "C": "Bu gözəl şəhərin qəşəng küçələri var. (gözəl – qəşəng: omonim)", "D": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: sinonim)", "E": "Dolu yağanda vedrə su ilə dolu idi. (dolu – dolu: omonim)"}'::jsonb, 'E', NULL, '«dolu» və «dolu» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
