INSERT INTO public.questions VALUES (1159, 19, 'g9-aze-syn-q1-19', 1, 19, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Yeni dərslikləri köhnə kitabların yanına qoydu. (yeni – köhnə: sinonim)", "B": "Qız saçını daradı, sonra quşlara dən saçdı. (saç – saç: antonim)", "C": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi. (tənbəl – çalışqan: omonim)", "D": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: omonim)", "E": "Gecənin sükutu gündüzün səs-küyünü unutdurdu. (gecə – gündüz: antonim)"}'::jsonb, 'E', NULL, '«gecə» və «gündüz» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1160, 19, 'g9-aze-syn-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib və omonimlər müxtəlif nitq hissələrinə aiddir?', NULL, NULL, '{"A": "Tut ağacından tut dər, səbəti möhkəm tut.", "B": "Gecənin sükutu gündüzün səs-küyünü unutdurdu.", "C": "İsti yay günlərində soyuq su içməyi xoşlayırıq.", "D": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "E": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı."}'::jsonb, 'A', NULL, 'Cümlədə: tut – tut (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1161, 19, 'g9-aze-syn-q1-21', 1, 21, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: sinonim)", "B": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: antonim)", "C": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: sinonim)", "D": "Bu gözəl şəhərin qəşəng küçələri var. (gözəl – qəşəng: antonim)", "E": "Bu gözəl şəhərin qəşəng küçələri var. (gözəl – qəşəng: omonim)"}'::jsonb, 'A', NULL, '«vətən» və «yurd» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1162, 19, 'g9-aze-syn-q1-22', 1, 22, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Yaz gəldi, dəftərinə bu şeiri yaz. (yaz – yaz: antonim)", "B": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi. (tənbəl – çalışqan: antonim)", "C": "Yaz gəldi, dəftərinə bu şeiri yaz. (yaz – yaz: sinonim)", "D": "Gənc müəllim cavan həmkarına kömək etdi. (gənc – cavan: omonim)", "E": "Sevinclə kədər bir-birini əvəz edirdi. (sevinc – kədər: omonim)"}'::jsonb, 'B', NULL, '«tənbəl» və «çalışqan» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1163, 19, 'g9-aze-syn-q1-23', 1, 23, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Dolu yağanda vedrə su ilə dolu idi. (dolu – dolu: antonim)", "B": "Bu gözəl şəhərin qəşəng küçələri var. (gözəl – qəşəng: antonim)", "C": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: antonim)", "D": "Qardaşım yavaş, asta addımlarla otağa girdi. (yavaş – asta: sinonim)", "E": "Sevinclə kədər bir-birini əvəz edirdi. (sevinc – kədər: sinonim)"}'::jsonb, 'D', NULL, '«yavaş» və «asta» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1164, 19, 'g9-aze-syn-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib və sinonimlər sifətlə ifadə olunub?', NULL, NULL, '{"A": "Səhərdən axşama qədər bağda işlədik.", "B": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi.", "C": "Dost da, düşmən də onun cəsarətini etiraf etdi.", "D": "Qoca bağban ahıl qonşusu ilə söhbət edirdi.", "E": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır."}'::jsonb, 'D', NULL, 'Cümlədə: qoca – ahıl (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1165, 19, 'g9-aze-syn-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə omonim işlənib və antonim işlənməyib?', NULL, NULL, '{"A": "Uşaqların sevinci və fərəhi hamıya yoluxdu.", "B": "Tut ağacından tut dər, səbəti möhkəm tut.", "C": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "D": "Bu gözəl şəhərin qəşəng küçələri var.", "E": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi."}'::jsonb, 'B', NULL, 'Cümlədə: tut – tut (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1166, 19, 'g9-aze-syn-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə antonim işlənib və omonim işlənməyib?', NULL, NULL, '{"A": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi.", "B": "Kədər və qəm onun ürəyini sıxırdı.", "C": "Vətən torpağı, ana yurd hər kəs üçün əzizdir.", "D": "Bu gözəl şəhərin qəşəng küçələri var.", "E": "Kitabxanada oxucular sakit oturub kitab oxuyurdular."}'::jsonb, 'A', NULL, 'Cümlədə: tənbəl – çalışqan (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1167, 19, 'g9-aze-syn-q1-27', 1, 27, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Gecənin sükutu gündüzün səs-küyünü unutdurdu. (gecə – gündüz: sinonim)", "B": "Bu gülü sənə verirəm, bir az gül. (gül – gül: sinonim)", "C": "Yaz gəldi, dəftərinə bu şeiri yaz. (yaz – yaz: sinonim)", "D": "Gecənin sükutu gündüzün səs-küyünü unutdurdu. (gecə – gündüz: omonim)", "E": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: antonim)"}'::jsonb, 'E', NULL, '«səhər» və «axşam» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1168, 19, 'g9-aze-syn-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə antonim işlənməyib və omonim işlənib?', NULL, NULL, '{"A": "Qardaşım yavaş, asta addımlarla otağa girdi.", "B": "Ocağın yanında oturma, yanarsan.", "C": "Uşaqların sevinci və fərəhi hamıya yoluxdu.", "D": "Vətən torpağı, ana yurd hər kəs üçün əzizdir.", "E": "Qoca bağban ahıl qonşusu ilə söhbət edirdi."}'::jsonb, 'B', NULL, 'Cümlədə: yan – yan (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1169, 19, 'g9-aze-syn-q1-29', 1, 29, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Ağır çantanı yüngül səbətlə dəyişdi. (ağır – yüngül: sinonim)", "B": "Yeni dərslikləri köhnə kitabların yanına qoydu. (yeni – köhnə: omonim)", "C": "Yeni dərslikləri köhnə kitabların yanına qoydu. (yeni – köhnə: sinonim)", "D": "Atı tövləyə apar, topu da bura at. (at – at: omonim)", "E": "Qardaşım yavaş, asta addımlarla otağa girdi. (yavaş – asta: omonim)"}'::jsonb, 'D', NULL, '«at» və «at» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
