INSERT INTO public.questions VALUES (1184, 19, 'g9-aze-syn-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib və sinonim işlənib?', NULL, NULL, '{"A": "Bu gözəl şəhərin qəşəng küçələri var.", "B": "Sevinclə kədər bir-birini əvəz edirdi.", "C": "Gecənin sükutu gündüzün səs-küyünü unutdurdu.", "D": "Uzun yolu qısa vaxtda qət etdik.", "E": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı."}'::jsonb, 'A', NULL, 'Cümlədə: gözəl – qəşəng (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1185, 19, 'g9-aze-syn-q2-15', 2, 15, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Dolu yağanda vedrə su ilə dolu idi. (dolu – dolu: omonim)", "B": "Ağır çantanı yüngül səbətlə dəyişdi. (ağır – yüngül: omonim)", "C": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır. (kasıb – varlı: omonim)", "D": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi. (cəsur – igid: omonim)", "E": "Sevinclə kədər bir-birini əvəz edirdi. (sevinc – kədər: omonim)"}'::jsonb, 'A', NULL, '«dolu» və «dolu» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1186, 19, 'g9-aze-syn-q2-16', 2, 16, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Yeni dərslikləri köhnə kitabların yanına qoydu. (yeni – köhnə: sinonim)", "B": "Atı tövləyə apar, topu da bura at. (at – at: antonim)", "C": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi. (tənbəl – çalışqan: sinonim)", "D": "İsti yay günlərində soyuq su içməyi xoşlayırıq. (isti – soyuq: antonim)", "E": "Sevinclə kədər bir-birini əvəz edirdi. (sevinc – kədər: omonim)"}'::jsonb, 'D', NULL, '«isti» və «soyuq» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1187, 19, 'g9-aze-syn-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə omonim işlənib və antonim işlənməyib?', NULL, NULL, '{"A": "Kədər və qəm onun ürəyini sıxırdı.", "B": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi.", "C": "Atı tövləyə apar, topu da bura at.", "D": "Qardaşım yavaş, asta addımlarla otağa girdi.", "E": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı."}'::jsonb, 'C', NULL, 'Cümlədə: at – at (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1188, 19, 'g9-aze-syn-q2-18', 2, 18, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Gənc müəllim cavan həmkarına kömək etdi. (gənc – cavan: antonim)", "B": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: sinonim)", "C": "Dost da, düşmən də onun cəsarətini etiraf etdi. (dost – düşmən: sinonim)", "D": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: omonim)", "E": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: omonim)"}'::jsonb, 'B', NULL, '«kədər» və «qəm» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1189, 19, 'g9-aze-syn-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə antonimlər sifətlə ifadə olunub və omonim işlənməyib?', NULL, NULL, '{"A": "Səhərdən axşama qədər bağda işlədik.", "B": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi.", "C": "Kədər və qəm onun ürəyini sıxırdı.", "D": "Vətən torpağı, ana yurd hər kəs üçün əzizdir.", "E": "Dost da, düşmən də onun cəsarətini etiraf etdi."}'::jsonb, 'B', NULL, 'Cümlədə: tənbəl – çalışqan (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1190, 19, 'g9-aze-syn-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib və sinonimlər isimlə ifadə olunub?', NULL, NULL, '{"A": "Vətən torpağı, ana yurd hər kəs üçün əzizdir.", "B": "Qardaşım yavaş, asta addımlarla otağa girdi.", "C": "Ağır çantanı yüngül səbətlə dəyişdi.", "D": "İsti yay günlərində soyuq su içməyi xoşlayırıq.", "E": "Gecənin sükutu gündüzün səs-küyünü unutdurdu."}'::jsonb, 'A', NULL, 'Cümlədə: vətən – yurd (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1191, 19, 'g9-aze-syn-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə sinonimlər sifətlə ifadə olunub və omonim işlənməyib?', NULL, NULL, '{"A": "Bu gözəl şəhərin qəşəng küçələri var.", "B": "Kədər və qəm onun ürəyini sıxırdı.", "C": "Sevinclə kədər bir-birini əvəz edirdi.", "D": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "E": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır."}'::jsonb, 'A', NULL, 'Cümlədə: gözəl – qəşəng (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
