INSERT INTO public.questions VALUES (1206, 19, 'g9-aze-syn-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə sinonim işlənib və omonim işlənməyib?', NULL, NULL, '{"A": "Uşaqların sevinci və fərəhi hamıya yoluxdu.", "B": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi.", "C": "Sevinclə kədər bir-birini əvəz edirdi.", "D": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı.", "E": "Uzun yolu qısa vaxtda qət etdik."}'::jsonb, 'A', NULL, 'Cümlədə: sevinc – fərəh (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1207, 19, 'g9-aze-syn-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə antonim işlənməyib və sinonimlər isimlə ifadə olunub?', NULL, NULL, '{"A": "Kədər və qəm onun ürəyini sıxırdı.", "B": "Ocağın yanında oturma, yanarsan.", "C": "Qız saçını daradı, sonra quşlara dən saçdı.", "D": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı.", "E": "Bu gülü sənə verirəm, bir az gül."}'::jsonb, 'A', NULL, 'Cümlədə: kədər – qəm (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1208, 19, 'g9-aze-syn-q3-08', 3, 8, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Uzun yolu qısa vaxtda qət etdik. (uzun – qısa: sinonim)", "B": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: antonim)", "C": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır. (kasıb – varlı: antonim)", "D": "Bu gülü sənə verirəm, bir az gül. (gül – gül: antonim)", "E": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: sinonim)"}'::jsonb, 'C', NULL, '«kasıb» və «varlı» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1209, 19, 'g9-aze-syn-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib və antonimlər sifətlə ifadə olunub?', NULL, NULL, '{"A": "Bu gülü sənə verirəm, bir az gül.", "B": "İsti yay günlərində soyuq su içməyi xoşlayırıq.", "C": "Atı tövləyə apar, topu da bura at.", "D": "Tut ağacından tut dər, səbəti möhkəm tut.", "E": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı."}'::jsonb, 'B', NULL, 'Cümlədə: isti – soyuq (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1210, 19, 'g9-aze-syn-q3-10', 3, 10, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Gənc müəllim cavan həmkarına kömək etdi. (gənc – cavan: omonim)", "B": "Uzun yolu qısa vaxtda qət etdik. (uzun – qısa: omonim)", "C": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır. (kasıb – varlı: omonim)", "D": "Gecənin sükutu gündüzün səs-küyünü unutdurdu. (gecə – gündüz: antonim)", "E": "Yeni dərslikləri köhnə kitabların yanına qoydu. (yeni – köhnə: sinonim)"}'::jsonb, 'D', NULL, '«gecə» və «gündüz» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1211, 19, 'g9-aze-syn-q3-11', 3, 11, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi. (cəsur – igid: sinonim)", "B": "İsti yay günlərində soyuq su içməyi xoşlayırıq. (isti – soyuq: omonim)", "C": "Dost da, düşmən də onun cəsarətini etiraf etdi. (dost – düşmən: sinonim)", "D": "Ocağın yanında oturma, yanarsan. (yan – yan: sinonim)", "E": "Gənc müəllim cavan həmkarına kömək etdi. (gənc – cavan: antonim)"}'::jsonb, 'A', NULL, '«cəsur» və «igid» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1212, 19, 'g9-aze-syn-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib və sinonim işlənməyib?', NULL, NULL, '{"A": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi.", "B": "Atı tövləyə apar, topu da bura at.", "C": "Gənc müəllim cavan həmkarına kömək etdi.", "D": "Tut ağacından tut dər, səbəti möhkəm tut.", "E": "Kədər və qəm onun ürəyini sıxırdı."}'::jsonb, 'A', NULL, 'Cümlədə: tənbəl – çalışqan (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1213, 19, 'g9-aze-syn-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib və antonim işlənib?', NULL, NULL, '{"A": "Kitabxanada oxucular sakit oturub kitab oxuyurdular.", "B": "Uşaq gülə-gülə qapını açdı və həyətə qaçdı.", "C": "Yeni dərslikləri köhnə kitabların yanına qoydu.", "D": "Qız saçını daradı, sonra quşlara dən saçdı.", "E": "Yaz gəldi, dəftərinə bu şeiri yaz."}'::jsonb, 'C', NULL, 'Cümlədə: yeni – köhnə (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1214, 19, 'g9-aze-syn-q3-14', 3, 14, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Gənc müəllim cavan həmkarına kömək etdi. (gənc – cavan: sinonim)", "B": "Çay kənarında oturub isti çay içdik. (çay – çay: antonim)", "C": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: antonim)", "D": "Sevinclə kədər bir-birini əvəz edirdi. (sevinc – kədər: sinonim)", "E": "Kədər və qəm onun ürəyini sıxırdı. (kədər – qəm: omonim)"}'::jsonb, 'A', NULL, '«gənc» və «cavan» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1215, 19, 'g9-aze-syn-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə omonimlər müxtəlif nitq hissələrinə aiddir və omonim işlənib?', NULL, NULL, '{"A": "İsti yay günlərində soyuq su içməyi xoşlayırıq.", "B": "Səhərdən axşama qədər bağda işlədik.", "C": "Ocağın yanında oturma, yanarsan.", "D": "Dost da, düşmən də onun cəsarətini etiraf etdi.", "E": "Çay kənarında oturub isti çay içdik."}'::jsonb, 'C', NULL, 'Cümlədə: yan – yan (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1216, 19, 'g9-aze-syn-q3-16', 3, 16, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Uşaqların sevinci və fərəhi hamıya yoluxdu. (sevinc – fərəh: antonim)", "B": "Bu gülü sənə verirəm, bir az gül. (gül – gül: antonim)", "C": "Dolu yağanda vedrə su ilə dolu idi. (dolu – dolu: sinonim)", "D": "Səhərdən axşama qədər bağda işlədik. (səhər – axşam: omonim)", "E": "Tut ağacından tut dər, səbəti möhkəm tut. (tut – tut: omonim)"}'::jsonb, 'E', NULL, '«tut» və «tut» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
