INSERT INTO public.questions VALUES (1229, 19, 'g9-aze-syn-q3-29', 3, 29, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib?', NULL, NULL, '{"A": "Vətən torpağı, ana yurd hər kəs üçün əzizdir. (vətən – yurd: sinonim)", "B": "Uzun yolu qısa vaxtda qət etdik. (uzun – qısa: sinonim)", "C": "Kasıb ailələr də, varlı ailələr də bu bayramı sevinclə qarşılayır. (kasıb – varlı: omonim)", "D": "Qoca bağban ahıl qonşusu ilə söhbət edirdi. (qoca – ahıl: omonim)", "E": "Yaz gəldi, dəftərinə bu şeiri yaz. (yaz – yaz: sinonim)"}'::jsonb, 'A', NULL, '«vətən» və «yurd» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (1230, 19, 'g9-aze-syn-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib və sinonim işlənməyib?', NULL, NULL, '{"A": "Ocağın yanında oturma, yanarsan.", "B": "Qız saçını daradı, sonra quşlara dən saçdı.", "C": "Qardaşım yavaş, asta addımlarla otağa girdi.", "D": "Cəsur əsgərlər igid komandirlərinin ardınca irəlilədi.", "E": "Tənbəl qardaşı ilə çalışqan bacısı tamamilə fərqli idi."}'::jsonb, 'E', NULL, 'Cümlədə: tənbəl – çalışqan (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1231, 20, 'g9-aze-idiom-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — intizarla gözləmək)", "B": "Qonşumuz darda qalanlara həmişə əl tutur. («əl tutmaq» — çox fikirləşmək)", "C": "Müəllim soruşanda o, ağzına su aldı. («ağzına su almaq» — diqqətlə dinləmək)", "D": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu. («qulaqardına vurmaq» — eşitməzliyə vurmaq)", "E": "Müəllim soruşanda o, ağzına su aldı. («ağzına su almaq» — çox zəhmət çəkmək)"}'::jsonb, 'D', NULL, '«qulaqardına vurmaq» — eşitməzliyə vurmaq.');
INSERT INTO public.questions VALUES (1232, 20, 'g9-aze-idiom-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə «susmaq, danışmamaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "B": "Komandamız uduzanda hamımızın qanı qaraldı.", "C": "Uşaq anasının qolundan tutub çəkdi.", "D": "Susayan uşaq ağzına bir qurtum su aldı.", "E": "Müəllim soruşanda o, ağzına su aldı."}'::jsonb, 'E', NULL, 'Cümlədəki frazeologizmlər: «ağzına su almaq» — susmaq, danışmamaq.');
INSERT INTO public.questions VALUES (1233, 20, 'g9-aze-idiom-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Kəndlilər çörək üçün alın təri tökürdülər.", "B": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "C": "Dərsdən sonra uşaqlar parkda oynadılar.", "D": "Müəllim soruşanda o, ağzına su aldı.", "E": "Susayan uşaq ağzına bir qurtum su aldı."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1234, 20, 'g9-aze-idiom-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Direktor əmrə qol çəkdi.", "B": "Babamın saçına dən düşsə də, hələ gümrah idi.", "C": "Dərsdən sonra uşaqlar parkda oynadılar.", "D": "Babam bizə həmişə ürək-dirək verirdi.", "E": "Həkim xəstənin qulağını diqqətlə yoxladı."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1235, 20, 'g9-aze-idiom-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə «çox fikirləşmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Hədiyyəni görəndə qızın ağzı qulağına çatdı.", "B": "Qəfil səsdən hamının ürəyi ağzına gəldi.", "C": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "D": "Babamın saçına dən düşsə də, hələ gümrah idi.", "E": "Məsələni həll etmək üçün xeyli baş sındırdım."}'::jsonb, 'E', NULL, 'Cümlədəki frazeologizmlər: «baş sındırmaq» — çox fikirləşmək.');
INSERT INTO public.questions VALUES (1236, 20, 'g9-aze-idiom-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə «eşitməzliyə vurmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu.", "B": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "C": "Müəllim soruşanda o, ağzına su aldı.", "D": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "E": "Məsələni həll etmək üçün xeyli baş sındırdım."}'::jsonb, 'A', NULL, 'Cümlədəki frazeologizmlər: «qulaqardına vurmaq» — eşitməzliyə vurmaq.');
INSERT INTO public.questions VALUES (1237, 20, 'g9-aze-idiom-q1-07', 1, 7, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — görməzlikdən gəlmək)", "B": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — ümidini kəsmək)", "C": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — diqqətlə dinləmək)", "D": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur. («əlini ağdan qaraya vurmamaq» — eşitməzliyə vurmaq)", "E": "Direktor əmrə qol çəkdi. («qol çəkmək» — çox fikirləşmək)"}'::jsonb, 'C', NULL, '«qulaq kəsilmək» — diqqətlə dinləmək.');
INSERT INTO public.questions VALUES (1238, 20, 'g9-aze-idiom-q1-08', 1, 8, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — etiraf etmək)", "B": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — kefi pozulmaq)", "C": "Babam bizə həmişə ürək-dirək verirdi. («ürək-dirək vermək» — vəfat etmək)", "D": "Babam bizə həmişə ürək-dirək verirdi. («ürək-dirək vermək» — ruhlandırmaq)", "E": "Qəfil səsdən hamının ürəyi ağzına gəldi. («ürəyi ağzına gəlmək» — vəd etmək)"}'::jsonb, 'D', NULL, '«ürək-dirək vermək» — ruhlandırmaq.');
INSERT INTO public.questions VALUES (1239, 20, 'g9-aze-idiom-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə «qocalmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Həkim xəstənin qulağını diqqətlə yoxladı.", "B": "Babamın saçına dən düşsə də, hələ gümrah idi.", "C": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "D": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər.", "E": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «saçına dən düşmək» — qocalmaq.');
INSERT INTO public.questions VALUES (1240, 20, 'g9-aze-idiom-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Dərsdən sonra uşaqlar parkda oynadılar.", "B": "Həkim xəstənin qulağını diqqətlə yoxladı.", "C": "Direktor əmrə qol çəkdi.", "D": "Dostum sabah gələcəyinə söz verdi.", "E": "Hədiyyəni görəndə qızın ağzı qulağına çatdı."}'::jsonb, 'B', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1241, 20, 'g9-aze-idiom-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Məsələni həll etmək üçün xeyli baş sındırdım.", "B": "Hədiyyəni görəndə qızın ağzı qulağına çatdı.", "C": "Dərsdən sonra uşaqlar parkda oynadılar.", "D": "Komandamız uduzanda hamımızın qanı qaraldı.", "E": "Həkim xəstənin qulağını diqqətlə yoxladı."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1242, 20, 'g9-aze-idiom-q1-12', 1, 12, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — qocalmaq)", "B": "Kəndlilər çörək üçün alın təri tökürdülər. («alın təri tökmək» — vəd etmək)", "C": "Yalan danışdığını biləndə utandı, sanki yerə girdi. («yerə girmək» — çox utanmaq)", "D": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — birləşib birgə çalışmaq)", "E": "Nənəmin gözü nəvəsinin yolunda qalmışdı. («gözü yolda qalmaq» — ruhlandırmaq)"}'::jsonb, 'C', NULL, '«yerə girmək» — çox utanmaq.');
INSERT INTO public.questions VALUES (1243, 20, 'g9-aze-idiom-q1-13', 1, 13, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — çox fikirləşmək)", "B": "Müəllim soruşanda o, ağzına su aldı. («ağzına su almaq» — susmaq, danışmamaq)", "C": "Nənəmin gözü nəvəsinin yolunda qalmışdı. («gözü yolda qalmaq» — çox utanmaq)", "D": "Hədiyyəni görəndə qızın ağzı qulağına çatdı. («ağzı qulağına çatmaq» — kefi pozulmaq)", "E": "Nənəmin gözü nəvəsinin yolunda qalmışdı. («gözü yolda qalmaq» — çox qorxmaq)"}'::jsonb, 'B', NULL, '«ağzına su almaq» — susmaq, danışmamaq.');
INSERT INTO public.questions VALUES (1244, 20, 'g9-aze-idiom-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə «diqqətlə dinləmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Qonşumuz darda qalanlara həmişə əl tutur.", "B": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "C": "Yalan danışdığını biləndə utandı, sanki yerə girdi.", "D": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər.", "E": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «qulaq kəsilmək» — diqqətlə dinləmək.');
INSERT INTO public.questions VALUES (1245, 20, 'g9-aze-idiom-q1-15', 1, 15, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — qocalmaq)", "B": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — ümidini kəsmək)", "C": "Babam bizə həmişə ürək-dirək verirdi. («ürək-dirək vermək» — çox hirslənmək)", "D": "Müəllim soruşanda o, ağzına su aldı. («ağzına su almaq» — etiraf etmək)", "E": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər. («ayaqdan düşmək» — heç bir iş görməmək)"}'::jsonb, 'A', NULL, '«saçına dən düşmək» — qocalmaq.');
INSERT INTO public.questions VALUES (1246, 20, 'g9-aze-idiom-q1-16', 1, 16, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Yalan danışdığını biləndə utandı, sanki yerə girdi. («yerə girmək» — aldatmaq)", "B": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər. («ayaqdan düşmək» — etiraf etmək)", "C": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — ruhlandırmaq)", "D": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — başa düşmək, anlamaq)", "E": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — vəd etmək)"}'::jsonb, 'D', NULL, '«başı çıxmaq» — başa düşmək, anlamaq.');
INSERT INTO public.questions VALUES (1247, 20, 'g9-aze-idiom-q1-17', 1, 17, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — imzalamaq)", "B": "Müəllim soruşanda o, ağzına su aldı. («ağzına su almaq» — susmaq, danışmamaq)", "C": "Məsələni həll etmək üçün xeyli baş sındırdım. («baş sındırmaq» — çox utanmaq)", "D": "Müəllim soruşanda o, ağzına su aldı. («ağzına su almaq» — heyrətlənmək)", "E": "İtirilmiş itin tapılacağından əlimizi üzmüşdük. («əlini üzmək» — etiraf etmək)"}'::jsonb, 'B', NULL, '«ağzına su almaq» — susmaq, danışmamaq.');
INSERT INTO public.questions VALUES (1248, 20, 'g9-aze-idiom-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə «çox yorulmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Kəndlilər çörək üçün alın təri tökürdülər.", "B": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu.", "C": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü.", "D": "Məsələni həll etmək üçün xeyli baş sındırdım.", "E": "Yalan danışdığını biləndə utandı, sanki yerə girdi."}'::jsonb, 'C', NULL, 'Cümlədəki frazeologizmlər: «əldən düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (1249, 20, 'g9-aze-idiom-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə «qocalmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "B": "Babamın saçına dən düşsə də, hələ gümrah idi.", "C": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu.", "D": "Babam bizə həmişə ürək-dirək verirdi.", "E": "Uşaq səhvini boynuna aldı."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «saçına dən düşmək» — qocalmaq.');
INSERT INTO public.questions VALUES (1250, 20, 'g9-aze-idiom-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə «çox zəhmət çəkmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Kəndlilər çörək üçün alın təri tökürdülər.", "B": "Susayan uşaq ağzına bir qurtum su aldı.", "C": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "D": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "E": "Babamın saçına dən düşsə də, hələ gümrah idi."}'::jsonb, 'A', NULL, 'Cümlədəki frazeologizmlər: «alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (1251, 20, 'g9-aze-idiom-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Dərsdən sonra uşaqlar parkda oynadılar.", "B": "Həkim xəstənin qulağını diqqətlə yoxladı.", "C": "Babamın saçına dən düşsə də, hələ gümrah idi.", "D": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "E": "Hədiyyəni görəndə qızın ağzı qulağına çatdı."}'::jsonb, 'B', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1252, 20, 'g9-aze-idiom-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "B": "Həkim xəstənin qulağını diqqətlə yoxladı.", "C": "Komandamız uduzanda hamımızın qanı qaraldı.", "D": "Qəfil səsdən hamının ürəyi ağzına gəldi.", "E": "Dərsdən sonra uşaqlar parkda oynadılar."}'::jsonb, 'B', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1253, 20, 'g9-aze-idiom-q1-23', 1, 23, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Məsələni həll etmək üçün xeyli baş sındırdım. («baş sındırmaq» — görməzlikdən gəlmək)", "B": "Hədiyyəni görəndə qızın ağzı qulağına çatdı. («ağzı qulağına çatmaq» — çox sevinmək)", "C": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər. («ayaqdan düşmək» — vəfat etmək)", "D": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — vəd etmək)", "E": "Kəndlilər çörək üçün alın təri tökürdülər. («alın təri tökmək» — kefi pozulmaq)"}'::jsonb, 'B', NULL, '«ağzı qulağına çatmaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (1254, 20, 'g9-aze-idiom-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə «çox zəhmət çəkmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Dərsdən sonra uşaqlar parkda oynadılar.", "B": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "C": "Qonşumuz darda qalanlara həmişə əl tutur.", "D": "Direktor əmrə qol çəkdi.", "E": "Kəndlilər çörək üçün alın təri tökürdülər."}'::jsonb, 'E', NULL, 'Cümlədəki frazeologizmlər: «alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (1255, 20, 'g9-aze-idiom-q1-25', 1, 25, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Hədiyyəni görəndə qızın ağzı qulağına çatdı. («ağzı qulağına çatmaq» — çox sevinmək)", "B": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — ümidini kəsmək)", "C": "Məsələni həll etmək üçün xeyli baş sındırdım. («baş sındırmaq» — heç bir iş görməmək)", "D": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur. («əlini ağdan qaraya vurmamaq» — görməzlikdən gəlmək)", "E": "Qəfil səsdən hamının ürəyi ağzına gəldi. («ürəyi ağzına gəlmək» — intizarla gözləmək)"}'::jsonb, 'A', NULL, '«ağzı qulağına çatmaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (1256, 20, 'g9-aze-idiom-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Direktor əmrə qol çəkdi.", "B": "Uşaq anasının qolundan tutub çəkdi.", "C": "Uşaq səhvini boynuna aldı.", "D": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur.", "E": "Dərsdən sonra uşaqlar parkda oynadılar."}'::jsonb, 'B', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1257, 20, 'g9-aze-idiom-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə «çox yorulmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər.", "B": "Qonşumuz darda qalanlara həmişə əl tutur.", "C": "Bu çətin mövzudan heç cür başım çıxmır.", "D": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu.", "E": "Uşaq anasının qolundan tutub çəkdi."}'::jsonb, 'A', NULL, 'Cümlədəki frazeologizmlər: «ayaqdan düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (1258, 20, 'g9-aze-idiom-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "B": "Bu çətin mövzudan heç cür başım çıxmır.", "C": "Uşaq anasının qolundan tutub çəkdi.", "D": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "E": "Dərsdən sonra uşaqlar parkda oynadılar."}'::jsonb, 'C', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1259, 20, 'g9-aze-idiom-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə «etiraf etmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Uşaq səhvini boynuna aldı.", "B": "Qonşumuz darda qalanlara həmişə əl tutur.", "C": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər.", "D": "Bu çətin mövzudan heç cür başım çıxmır.", "E": "Yalan danışdığını biləndə utandı, sanki yerə girdi."}'::jsonb, 'A', NULL, 'Cümlədəki frazeologizmlər: «boynuna almaq» — etiraf etmək.');
INSERT INTO public.questions VALUES (1260, 20, 'g9-aze-idiom-q1-30', 1, 30, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — heç bir iş görməmək)", "B": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — susmaq, danışmamaq)", "C": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — çox zəhmət çəkmək)", "D": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər. («ayaqdan düşmək» — çox yorulmaq)", "E": "Yolda gördüyü mənzərədən ağzı açıla qaldı. («ağzı açıla qalmaq» — görməzlikdən gəlmək)"}'::jsonb, 'D', NULL, '«ayaqdan düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (1261, 20, 'g9-aze-idiom-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə «çox zəhmət çəkmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Susayan uşaq ağzına bir qurtum su aldı.", "B": "Kəndlilər çörək üçün alın təri tökürdülər.", "C": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər.", "D": "Qonşumuz darda qalanlara həmişə əl tutur.", "E": "Müəllim soruşanda o, ağzına su aldı."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (1262, 20, 'g9-aze-idiom-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Dərsdən sonra uşaqlar parkda oynadılar.", "B": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər.", "C": "Müəllim soruşanda o, ağzına su aldı.", "D": "Qonşumuz darda qalanlara həmişə əl tutur.", "E": "Susayan uşaq ağzına bir qurtum su aldı."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1263, 20, 'g9-aze-idiom-q2-03', 2, 3, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu. («qulaqardına vurmaq» — çox fikirləşmək)", "B": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — çox utanmaq)", "C": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — susmaq, danışmamaq)", "D": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — çox qorxmaq)", "E": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur. («əlini ağdan qaraya vurmamaq» — heç bir iş görməmək)"}'::jsonb, 'E', NULL, '«əlini ağdan qaraya vurmamaq» — heç bir iş görməmək.');
INSERT INTO public.questions VALUES (1264, 20, 'g9-aze-idiom-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə «ruhlandırmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Həkim xəstənin qulağını diqqətlə yoxladı.", "B": "Babam bizə həmişə ürək-dirək verirdi.", "C": "Uşaq səhvini boynuna aldı.", "D": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "E": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «ürək-dirək vermək» — ruhlandırmaq.');
INSERT INTO public.questions VALUES (1265, 20, 'g9-aze-idiom-q2-05', 2, 5, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "İtirilmiş itin tapılacağından əlimizi üzmüşdük. («əlini üzmək» — ruhlandırmaq)", "B": "Yalan danışdığını biləndə utandı, sanki yerə girdi. («yerə girmək» — heyrətlənmək)", "C": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — başa düşmək, anlamaq)", "D": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — vəd etmək)", "E": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — qocalmaq)"}'::jsonb, 'D', NULL, '«söz vermək» — vəd etmək.');
INSERT INTO public.questions VALUES (1266, 20, 'g9-aze-idiom-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə «ümidini kəsmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Qonşumuz darda qalanlara həmişə əl tutur.", "B": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "C": "Uşaq anasının qolundan tutub çəkdi.", "D": "Babamın saçına dən düşsə də, hələ gümrah idi.", "E": "Uşaq səhvini boynuna aldı."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «əlini üzmək» — ümidini kəsmək.');
