INSERT INTO public.questions VALUES (1275, 20, 'g9-aze-idiom-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə «çox utanmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Uşaq səhvini boynuna aldı.", "B": "Susayan uşaq ağzına bir qurtum su aldı.", "C": "Komandamız uduzanda hamımızın qanı qaraldı.", "D": "Yalan danışdığını biləndə utandı, sanki yerə girdi.", "E": "Babam bizə həmişə ürək-dirək verirdi."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «yerə girmək» — çox utanmaq.');
INSERT INTO public.questions VALUES (1276, 20, 'g9-aze-idiom-q2-16', 2, 16, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Babam bizə həmişə ürək-dirək verirdi. («ürək-dirək vermək» — ruhlandırmaq)", "B": "İtirilmiş itin tapılacağından əlimizi üzmüşdük. («əlini üzmək» — görməzlikdən gəlmək)", "C": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — çox utanmaq)", "D": "Qonşumuz darda qalanlara həmişə əl tutur. («əl tutmaq» — çox qorxmaq)", "E": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur. («əlini ağdan qaraya vurmamaq» — kefi pozulmaq)"}'::jsonb, 'A', NULL, '«ürək-dirək vermək» — ruhlandırmaq.');
INSERT INTO public.questions VALUES (1277, 20, 'g9-aze-idiom-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə «imzalamaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Babamın saçına dən düşsə də, hələ gümrah idi.", "B": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur.", "C": "Direktor əmrə qol çəkdi.", "D": "Hədiyyəni görəndə qızın ağzı qulağına çatdı.", "E": "Müəllim soruşanda o, ağzına su aldı."}'::jsonb, 'C', NULL, 'Cümlədəki frazeologizmlər: «qol çəkmək» — imzalamaq.');
INSERT INTO public.questions VALUES (1278, 20, 'g9-aze-idiom-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Dərsdən sonra uşaqlar parkda oynadılar.", "B": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu.", "C": "Susayan uşaq ağzına bir qurtum su aldı.", "D": "Qonşumuz darda qalanlara həmişə əl tutur.", "E": "İtirilmiş itin tapılacağından əlimizi üzmüşdük."}'::jsonb, 'C', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1279, 20, 'g9-aze-idiom-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Yolda gördüyü mənzərədən ağzı açıla qaldı.", "B": "Uşaq anasının qolundan tutub çəkdi.", "C": "Dərsdən sonra uşaqlar parkda oynadılar.", "D": "Uşaq səhvini boynuna aldı.", "E": "İtirilmiş itin tapılacağından əlimizi üzmüşdük."}'::jsonb, 'B', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1280, 20, 'g9-aze-idiom-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə «etiraf etmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Həkim xəstənin qulağını diqqətlə yoxladı.", "B": "Babamın saçına dən düşsə də, hələ gümrah idi.", "C": "Babam bizə həmişə ürək-dirək verirdi.", "D": "Uşaq səhvini boynuna aldı.", "E": "Qəfil səsdən hamının ürəyi ağzına gəldi."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «boynuna almaq» — etiraf etmək.');
INSERT INTO public.questions VALUES (1281, 20, 'g9-aze-idiom-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Dərsdən sonra uşaqlar parkda oynadılar.", "B": "Bu çətin mövzudan heç cür başım çıxmır.", "C": "Uşaq anasının qolundan tutub çəkdi.", "D": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü.", "E": "Babam bizə həmişə ürək-dirək verirdi."}'::jsonb, 'C', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
