INSERT INTO public.questions VALUES (1300, 20, 'g9-aze-idiom-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Uşaq səhvini boynuna aldı.", "B": "Həkim xəstənin qulağını diqqətlə yoxladı.", "C": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "D": "Direktor əmrə qol çəkdi.", "E": "Dərsdən sonra uşaqlar parkda oynadılar."}'::jsonb, 'B', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1301, 20, 'g9-aze-idiom-q3-11', 3, 11, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Direktor əmrə qol çəkdi. («qol çəkmək» — başa düşmək, anlamaq)", "B": "Nənəmin gözü nəvəsinin yolunda qalmışdı. («gözü yolda qalmaq» — çox fikirləşmək)", "C": "İtirilmiş itin tapılacağından əlimizi üzmüşdük. («əlini üzmək» — çox zəhmət çəkmək)", "D": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — diqqətlə dinləmək)", "E": "Məsələni həll etmək üçün xeyli baş sındırdım. («baş sındırmaq» — çox fikirləşmək)"}'::jsonb, 'E', NULL, '«baş sındırmaq» — çox fikirləşmək.');
INSERT INTO public.questions VALUES (1302, 20, 'g9-aze-idiom-q3-12', 3, 12, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "İtirilmiş itin tapılacağından əlimizi üzmüşdük. («əlini üzmək» — qocalmaq)", "B": "Yolda gördüyü mənzərədən ağzı açıla qaldı. («ağzı açıla qalmaq» — kömək etmək)", "C": "Babam bizə həmişə ürək-dirək verirdi. («ürək-dirək vermək» — ümidini kəsmək)", "D": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — ümidini kəsmək)", "E": "Yolda gördüyü mənzərədən ağzı açıla qaldı. («ağzı açıla qalmaq» — heyrətlənmək)"}'::jsonb, 'E', NULL, '«ağzı açıla qalmaq» — heyrətlənmək.');
INSERT INTO public.questions VALUES (1303, 20, 'g9-aze-idiom-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə «kefi pozulmaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Yolda gördüyü mənzərədən ağzı açıla qaldı.", "B": "Dostum sabah gələcəyinə söz verdi.", "C": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "D": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "E": "Komandamız uduzanda hamımızın qanı qaraldı."}'::jsonb, 'E', NULL, 'Cümlədəki frazeologizmlər: «qanı qaralmaq» — kefi pozulmaq.');
INSERT INTO public.questions VALUES (1304, 20, 'g9-aze-idiom-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə «başa düşmək, anlamaq» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Anam dəfələrlə tapşırdı, amma o, sözləri qulaqardına vurdu.", "B": "Müəllim soruşanda o, ağzına su aldı.", "C": "Bu çətin mövzudan heç cür başım çıxmır.", "D": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "E": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər."}'::jsonb, 'C', NULL, 'Cümlədəki frazeologizmlər: «başı çıxmaq» — başa düşmək, anlamaq.');
INSERT INTO public.questions VALUES (1305, 20, 'g9-aze-idiom-q3-15', 3, 15, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Qonşumuz darda qalanlara həmişə əl tutur. («əl tutmaq» — ümidini kəsmək)", "B": "Kəndlilər çörək üçün alın təri tökürdülər. («alın təri tökmək» — heyrətlənmək)", "C": "Kəndlilər çörək üçün alın təri tökürdülər. («alın təri tökmək» — vəfat etmək)", "D": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — çox yorulmaq)", "E": "Qonşumuz darda qalanlara həmişə əl tutur. («əl tutmaq» — imzalamaq)"}'::jsonb, 'D', NULL, '«əldən düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (1306, 20, 'g9-aze-idiom-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü.", "B": "Dərsdən sonra uşaqlar parkda oynadılar.", "C": "Bu çətin mövzudan heç cür başım çıxmır.", "D": "Nənəmin gözü nəvəsinin yolunda qalmışdı.", "E": "Həkim xəstənin qulağını diqqətlə yoxladı."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1307, 20, 'g9-aze-idiom-q3-17', 3, 17, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Qonşumuz darda qalanlara həmişə əl tutur. («əl tutmaq» — çox qorxmaq)", "B": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər. («qulaq kəsilmək» — başa düşmək, anlamaq)", "C": "Yolda gördüyü mənzərədən ağzı açıla qaldı. («ağzı açıla qalmaq» — heyrətlənmək)", "D": "Babam bizə həmişə ürək-dirək verirdi. («ürək-dirək vermək» — kömək etmək)", "E": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — ruhlandırmaq)"}'::jsonb, 'C', NULL, '«ağzı açıla qalmaq» — heyrətlənmək.');
INSERT INTO public.questions VALUES (1308, 20, 'g9-aze-idiom-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə «ümidini kəsmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur.", "B": "Yolda gördüyü mənzərədən ağzı açıla qaldı.", "C": "Qəfil səsdən hamının ürəyi ağzına gəldi.", "D": "İtirilmiş itin tapılacağından əlimizi üzmüşdük.", "E": "Babam bizə həmişə ürək-dirək verirdi."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «əlini üzmək» — ümidini kəsmək.');
INSERT INTO public.questions VALUES (1309, 20, 'g9-aze-idiom-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Müəllim soruşanda o, ağzına su aldı.", "B": "Qonşumuz darda qalanlara həmişə əl tutur.", "C": "Susayan uşaq ağzına bir qurtum su aldı.", "D": "Uşaq səhvini boynuna aldı.", "E": "Dərsdən sonra uşaqlar parkda oynadılar."}'::jsonb, 'C', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1310, 20, 'g9-aze-idiom-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Dostum sabah gələcəyinə söz verdi.", "B": "Yalan danışdığını biləndə utandı, sanki yerə girdi.", "C": "Uşaq anasının qolundan tutub çəkdi.", "D": "Dərsdən sonra uşaqlar parkda oynadılar.", "E": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur."}'::jsonb, 'C', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (1311, 20, 'g9-aze-idiom-q3-21', 3, 21, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Direktor əmrə qol çəkdi. («qol çəkmək» — imzalamaq)", "B": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — aldatmaq)", "C": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — heyrətlənmək)", "D": "Yolda gördüyü mənzərədən ağzı açıla qaldı. («ağzı açıla qalmaq» — kefi pozulmaq)", "E": "Bütün günü bağda işləyən babam axşam əldən düşmüşdü. («əldən düşmək» — çox fikirləşmək)"}'::jsonb, 'A', NULL, '«qol çəkmək» — imzalamaq.');
INSERT INTO public.questions VALUES (1312, 20, 'g9-aze-idiom-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə «çox zəhmət çəkmək» mənasında frazeoloji birləşmə işlənib?', NULL, NULL, '{"A": "Kəndlilər çörək üçün alın təri tökürdülər.", "B": "Dostum sabah gələcəyinə söz verdi.", "C": "Tənbəl qardaşım evdə əlini ağdan qaraya vurmur.", "D": "Şagirdlər müəllimin hekayəsinə qulaq kəsilmişdilər.", "E": "Səhər tezdən işə başlayan fəhlələr günortaya qədər ayaqdan düşdülər."}'::jsonb, 'A', NULL, 'Cümlədəki frazeologizmlər: «alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (1313, 20, 'g9-aze-idiom-q3-23', 3, 23, 'hard', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — qocalmaq)", "B": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — qocalmaq)", "C": "Dostum sabah gələcəyinə söz verdi. («söz vermək» — intizarla gözləmək)", "D": "Babamın saçına dən düşsə də, hələ gümrah idi. («saçına dən düşmək» — çox zəhmət çəkmək)", "E": "Bu çətin mövzudan heç cür başım çıxmır. («başı çıxmaq» — çox qorxmaq)"}'::jsonb, 'A', NULL, '«saçına dən düşmək» — qocalmaq.');
