INSERT INTO public.questions VALUES (1589, 23, 'g9-aze-say-q3-29', 3, 29, 'hard', 'single', '«Anam bazardan beş alma aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "say — 2; isim — 3", "B": "say — 1; isim — 4", "C": "say — 0; isim — 3", "D": "say — 2; isim — 2", "E": "say — 1; isim — 3"}'::jsonb, 'E', NULL, '«Anam bazardan beş alma aldı.»: «beş» — miqdar sayı, təyin. Düzgün: say — 1; isim — 3.');
INSERT INTO public.questions VALUES (1590, 23, 'g9-aze-say-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə sıra sayı var və ədat yoxdur?', NULL, NULL, '{"A": "Heç kim bu tapmacanı tapmadı.", "B": "Ura, komandamız kuboku qazandı!", "C": "Üçüncü cərgədə iki boş yer qalmışdı.", "D": "Dünən biz qədim qalaya qədər piyada getdik.", "E": "Evə çatanda anam məni qarşıladı."}'::jsonb, 'C', NULL, '«Üçüncü cərgədə iki boş yer qalmışdı.»: «Üçüncü» — sıra sayı, təyin; «iki» — miqdar sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1591, 24, 'g9-aze-evez-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə 2 əvəzlik işlənib və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Yalnız Leyla tapşırığı vaxtında bitirdi.", "B": "Oxuyan uşaq başını kitabdan qaldırdı.", "C": "Hər şagird öz dəftərini götürdü.", "D": "Atam qəzet və jurnal oxuyur.", "E": "Dərsdən əvvəl müəllim jurnalı yoxladı."}'::jsonb, 'C', NULL, '«Hər şagird öz dəftərini götürdü.»: «Hər» — təyini əvəzlik, təyin; «öz» — qayıdış əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1592, 24, 'g9-aze-evez-q1-02', 1, 2, 'hard', 'single', '«Bu kitabı mənə dostum bağışladı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 4", "B": "əvəzlik — 3; isim — 2", "C": "əvəzlik — 2; isim — 3", "D": "əvəzlik — 2; isim — 1", "E": "əvəzlik — 2; isim — 2"}'::jsonb, 'E', NULL, '«Bu kitabı mənə dostum bağışladı.»: «Bu» — işarə əvəzliyi, təyin; «mənə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Düzgün: əvəzlik — 2; isim — 2.');
INSERT INTO public.questions VALUES (1593, 24, 'g9-aze-evez-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "O, dostu ilə parkda gəzirdi.", "B": "Axı sən bunu bilirdin.", "C": "Ey dostlar, bura gəlin!", "D": "Əlbəttə, sən bu kitabı oxumalısan.", "E": "Həmin axşam güclü külək əsdi."}'::jsonb, 'A', NULL, '«O, dostu ilə parkda gəzirdi.»: «O» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
