INSERT INTO public.questions VALUES (1596, 24, 'g9-aze-evez-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib və say yoxdur?', NULL, NULL, '{"A": "Gəncə qədim şəhərdir.", "B": "Sınan oyuncağı atam düzəltdi.", "C": "Qoy Anar bu şeiri oxusun.", "D": "O, dostu ilə parkda gəzirdi.", "E": "Hər şagird öz dəftərini götürdü."}'::jsonb, 'D', NULL, '«O, dostu ilə parkda gəzirdi.»: «O» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
