INSERT INTO public.questions VALUES (1601, 24, 'g9-aze-evez-q1-11', 1, 11, 'hard', 'single', '«Dünən biz qədim qalaya qədər piyada getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 0", "B": "əvəzlik — 1; isim — 1", "C": "əvəzlik — 2; isim — 1", "D": "əvəzlik — 3; isim — 1", "E": "əvəzlik — 1; isim — 3"}'::jsonb, 'B', NULL, '«Dünən biz qədim qalaya qədər piyada getdik.»: «biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 1.');
