INSERT INTO public.questions VALUES (1702, 25, 'g9-aze-feil-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır və II şəxs təkdədir?', NULL, NULL, '{"A": "Sən şeiri öyrənmədin.", "B": "Biz şeiri öyrəndik.", "C": "Mən şeiri öyrənmədim.", "D": "Onlar şeiri öyrənmədilər.", "E": "Sən şeiri öyrənmirsən."}'::jsonb, 'A', NULL, '«öyrənmədin» — şühudi keçmiş zaman, II şəxs tək, inkar forması.');
