INSERT INTO public.questions VALUES (1704, 25, 'g9-aze-feil-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və feili bağlama yoxdur?', NULL, NULL, '{"A": "Gəncə qədim şəhərdir.", "B": "Doğrudan da, bu film maraqlıdır.", "C": "Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.", "D": "Evə çatanda anam məni qarşıladı.", "E": "Müəllim lövhəyə iki misal yazdı."}'::jsonb, 'E', NULL, '«Müəllim lövhəyə iki misal yazdı.»: «yazdı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1705, 25, 'g9-aze-feil-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və sifət yoxdur?', NULL, NULL, '{"A": "Hətta kiçik uşaqlar bu mahnını bilirdi.", "B": "Bağçada qırmızı və sarı güllər açmışdı.", "C": "Axşamüstü səmada parlaq ulduzlar göründü.", "D": "O kitabı rəfə qoy.", "E": "Şübhəsiz, bu il məhsul bol olacaq."}'::jsonb, 'D', NULL, '«O kitabı rəfə qoy.»: «qoy» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1706, 25, 'g9-aze-feil-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ancaq sən mənə inanırsan.", "B": "O, dostu ilə parkda gəzirdi.", "C": "Bu kitabı mənə dostum bağışladı.", "D": "Neçə şagird yarışa qatıldı?", "E": "Qardaşım məktəbdən sonra kitabxanaya gedir."}'::jsonb, 'E', NULL, '«Qardaşım məktəbdən sonra kitabxanaya gedir.»: «gedir» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (1707, 25, 'g9-aze-feil-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır və I şəxs cəmdədir?', NULL, NULL, '{"A": "Onlar tapşırığı unutmayacaqlar.", "B": "Sən tapşırığı unutacaqsan.", "C": "Onlar tapşırığı unutacaqlar.", "D": "Biz tapşırığı unutmayacağıq.", "E": "Biz tapşırığı unuturuq."}'::jsonb, 'D', NULL, '«unutmayacağıq» — qəti gələcək zaman, I şəxs cəm, inkar forması.');
