INSERT INTO public.questions VALUES (2307, 31, 'g9-aze-nida-q3-27', 3, 27, 'hard', 'single', '«Ah, mən açarı evdə unutmuşam!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 2; isim — 2", "B": "nida — 2; isim — 1", "C": "nida — 1; isim — 2", "D": "nida — 0; isim — 2", "E": "nida — 1; isim — 1"}'::jsonb, 'C', NULL, '«Ah, mən açarı evdə unutmuşam!»: «Ah» — nida. Düzgün: nida — 1; isim — 2.');
INSERT INTO public.questions VALUES (2308, 31, 'g9-aze-nida-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib və müraciət yoxdur?', NULL, NULL, '{"A": "Afərin, sən bütün tapmacaları tapdın!", "B": "Atam qəzet və jurnal oxuyur.", "C": "Kitab oxumağı sevirəm.", "D": "Həmin axşam güclü külək əsdi.", "E": "Uşaqlar meşəyə tərəf qaçdılar."}'::jsonb, 'A', NULL, '«Afərin, sən bütün tapmacaları tapdın!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (2309, 31, 'g9-aze-nida-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə nida var və məsdər yoxdur?', NULL, NULL, '{"A": "Uşaqlar yuxarı qalxdılar.", "B": "Üçdə bir hissəni qardaşıma verdim.", "C": "Nə qar, nə də yağış yağdı.", "D": "Ah, mən açarı evdə unutmuşam!", "E": "Bağçada qırmızı və sarı güllər açmışdı."}'::jsonb, 'D', NULL, '«Ah, mən açarı evdə unutmuşam!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (2310, 31, 'g9-aze-nida-q3-30', 3, 30, 'hard', 'single', '«Əhsən, siz bu yarışı uddunuz!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 0", "B": "nida — 1; isim — 1", "C": "nida — 2; isim — 1", "D": "nida — 0; isim — 1", "E": "nida — 2; isim — 0"}'::jsonb, 'B', NULL, '«Əhsən, siz bu yarışı uddunuz!»: «Əhsən» — nida. Düzgün: nida — 1; isim — 1.');
INSERT INTO public.questions VALUES (2311, 32, 'g9-aze-member-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Sınan oyuncağı «atam» düzəltdi.", "B": "Həm atam, həm də anam bu «xəbərə» sevindi.", "C": "Yəqin, qonaqlar «yorulublar».", "D": "«Oxuyan» uşaq başını kitabdan qaldırdı.", "E": "Biz axşama qədər «oynadıq»."}'::jsonb, 'D', NULL, '«Oxuyan» — təyin, feili sifət. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2312, 32, 'g9-aze-member-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Yarım çörəyi quşlara verdi.", "B": "Anam bazardan beş alma aldı.", "C": "Sabah yaxud birigün Bakıya gedəcəyik.", "D": "Dərsə gecikməmək üçün evdən erkən çıxdım.", "E": "Bu hədiyyəni sənin üçün almışam."}'::jsonb, 'B', NULL, '«Anam bazardan beş alma aldı.»: mübtəda — Anam; zərflik — bazardan; təyin — beş; vasitəsiz tamamlıq — alma; xəbər — aldı.');
INSERT INTO public.questions VALUES (2313, 32, 'g9-aze-member-q1-03', 1, 3, 'hard', 'single', '«Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Biz — mübtəda; əvvəlcə — zərflik; dərsimizi — xəbər; oxuduq — vasitəsiz tamamlıq", "B": "Biz — vasitəsiz tamamlıq; əvvəlcə — zərflik; dərsimizi — mübtəda; oxuduq — xəbər", "C": "Biz — mübtəda; əvvəlcə — zərflik; dərsimizi — vasitəsiz tamamlıq; oxuduq — mübtəda", "D": "Biz — mübtəda; əvvəlcə — zərflik; dərsimizi — vasitəsiz tamamlıq; oxuduq — təyin", "E": "Biz — mübtəda; əvvəlcə — zərflik; dərsimizi — vasitəsiz tamamlıq; oxuduq — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Biz — mübtəda; əvvəlcə — zərflik; dərsimizi — vasitəsiz tamamlıq; oxuduq — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2314, 32, 'g9-aze-member-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir?', NULL, NULL, '{"A": "Həmin «axşam» güclü külək əsdi.", "B": "Yağış yağanda uşaqlar «evə» qaçdılar.", "C": "O, «kitabı» rəfə qoydu.", "D": "Vay, stəkan «sındı»!", "E": "Vay, «stəkan» sındı!"}'::jsonb, 'E', NULL, '«stəkan» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2315, 32, 'g9-aze-member-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Axşamüstü səmada parlaq ulduzlar göründü.", "B": "Dünən biz qədim qalaya qədər piyada getdik.", "C": "Ey dostlar, bura gəlin!", "D": "Əli ilə Vəli bu məktəbdə oxuyurlar.", "E": "Əlbəttə, sən bu kitabı oxumalısan."}'::jsonb, 'C', NULL, '«Ey dostlar, bura gəlin!»: zərflik — bura; xəbər — gəlin.');
INSERT INTO public.questions VALUES (2316, 32, 'g9-aze-member-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir?', NULL, NULL, '{"A": "«Siz» nə oxuyursunuz?", "B": "Ura, komandamız «kuboku» qazandı!", "C": "Biz «axşama» qədər oynadıq.", "D": "Əhsən, siz bu yarışı «uddunuz»!", "E": "«Beş-altı» quş budağa qondu."}'::jsonb, 'B', NULL, '«kuboku» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2317, 32, 'g9-aze-member-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Gözəl və geniş otaqda qonaqlar oturmuşdular.", "B": "O, kitabı rəfə qoydu.", "C": "Ey dostlar, bura gəlin!", "D": "Kitab oxumağı sevirəm.", "E": "Nənəm nəvələrinə maraqlı nağıllar danışırdı."}'::jsonb, 'B', NULL, '«O, kitabı rəfə qoydu.»: mübtəda — O; vasitəsiz tamamlıq — kitabı; zərflik — rəfə; xəbər — qoydu.');
INSERT INTO public.questions VALUES (2318, 32, 'g9-aze-member-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir?', NULL, NULL, '{"A": "Oxuyan uşaq «başını» kitabdan qaldırdı.", "B": "Ancaq «sən» mənə inanırsan.", "C": "Afərin, sən bütün tapmacaları «tapdın»!", "D": "«Neçə» şagird yarışa qatıldı?", "E": "Səkkiz şagird «olimpiadaya» qatıldı."}'::jsonb, 'A', NULL, '«başını» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2319, 32, 'g9-aze-member-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ancaq sən mənə inanırsan.", "B": "Nənəm nəvələrinə maraqlı nağıllar danışırdı.", "C": "Üçdə bir hissəni qardaşıma verdim.", "D": "Uşaqlar ucadan güldülər.", "E": "Bu hədiyyəni sənin üçün almışam."}'::jsonb, 'D', NULL, '«Uşaqlar ucadan güldülər.»: mübtəda — Uşaqlar; zərflik — ucadan; xəbər — güldülər.');
INSERT INTO public.questions VALUES (2320, 32, 'g9-aze-member-q1-10', 1, 10, 'hard', 'single', '«Kimsə qapını yavaşca döydü.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Kimsə — zərflik; qapını — vasitəsiz tamamlıq; yavaşca — mübtəda; döydü — xəbər", "B": "Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — təyin; döydü — xəbər", "C": "Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — mübtəda", "D": "Kimsə — təyin; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — xəbər", "E": "Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2321, 32, 'g9-aze-member-q1-11', 1, 11, 'hard', 'single', '«Həm atam, həm də anam bu xəbərə sevindi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "atam — təyin; anam — mübtəda; bu — mübtəda; xəbərə — vasitəli tamamlıq", "B": "atam — vasitəli tamamlıq; anam — mübtəda; bu — təyin; xəbərə — mübtəda", "C": "atam — vasitəsiz tamamlıq; anam — mübtəda; bu — təyin; xəbərə — vasitəli tamamlıq", "D": "atam — mübtəda; anam — mübtəda; bu — təyin; xəbərə — vasitəli tamamlıq", "E": "atam — mübtəda; anam — vasitəli tamamlıq; bu — təyin; xəbərə — mübtəda"}'::jsonb, 'D', NULL, 'Düzgün: atam — mübtəda; anam — mübtəda; bu — təyin; xəbərə — vasitəli tamamlıq. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2322, 32, 'g9-aze-member-q1-12', 1, 12, 'hard', 'single', '«O, dostu ilə parkda gəzirdi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "O — mübtəda; dostu ilə — zərflik; parkda — zərflik; gəzirdi — xəbər", "B": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — vasitəli tamamlıq; gəzirdi — xəbər", "C": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — mübtəda", "D": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər", "E": "O — zərflik; dostu ilə — vasitəli tamamlıq; parkda — mübtəda; gəzirdi — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2323, 32, 'g9-aze-member-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Gəncə qədim şəhərdir.", "B": "Hətta kiçik uşaqlar bu mahnını bilirdi.", "C": "Ay uşaqlar, dərhal sinfə qayıdın!", "D": "Doğrudan da, bu film maraqlıdır.", "E": "Bu hədiyyəni sənin üçün almışam."}'::jsonb, 'B', NULL, '«Hətta kiçik uşaqlar bu mahnını bilirdi.»: təyin — kiçik; mübtəda — uşaqlar; təyin — bu; vasitəsiz tamamlıq — mahnını; xəbər — bilirdi.');
INSERT INTO public.questions VALUES (2324, 32, 'g9-aze-member-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir?', NULL, NULL, '{"A": "Afərin, sən «bütün» tapmacaları tapdın!", "B": "Sınan oyuncağı atam «düzəltdi».", "C": "Ura, komandamız «kuboku» qazandı!", "D": "Uşaqlar «yuxarı» qalxdılar.", "E": "Kim bu məktubu «yazıb»?"}'::jsonb, 'C', NULL, '«kuboku» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2325, 32, 'g9-aze-member-q1-15', 1, 15, 'hard', 'single', '«Sən ya çay, ya da şirə iç.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Sən — təyin; çay — vasitəsiz tamamlıq; şirə — vasitəsiz tamamlıq; iç — xəbər", "B": "Sən — vasitəsiz tamamlıq; çay — mübtəda; şirə — vasitəsiz tamamlıq; iç — xəbər", "C": "Sən — mübtəda; çay — vasitəsiz tamamlıq; şirə — vasitəli tamamlıq; iç — xəbər", "D": "Sən — mübtəda; çay — vasitəsiz tamamlıq; şirə — vasitəsiz tamamlıq; iç — xəbər", "E": "Sən — vasitəsiz tamamlıq; çay — vasitəsiz tamamlıq; şirə — mübtəda; iç — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Sən — mübtəda; çay — vasitəsiz tamamlıq; şirə — vasitəsiz tamamlıq; iç — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2326, 32, 'g9-aze-member-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Uşaqlar yuxarı qalxdılar.", "B": "Of, mən yoruldum.", "C": "Heç kim bu tapmacanı tapmadı.", "D": "Ay uşaqlar, dərhal sinfə qayıdın!", "E": "Deməli, siz sabah Bakıya gedirsiniz."}'::jsonb, 'A', NULL, '«Uşaqlar yuxarı qalxdılar.»: mübtəda — Uşaqlar; zərflik — yuxarı; xəbər — qalxdılar.');
INSERT INTO public.questions VALUES (2327, 32, 'g9-aze-member-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Biz axşama qədər oynadıq.", "B": "Ey dostlar, bura gəlin!", "C": "Səhərdən bəri yağış yağır.", "D": "Afərin, sən bütün tapmacaları tapdın!", "E": "Vay, stəkan sındı!"}'::jsonb, 'A', NULL, '«Biz axşama qədər oynadıq.»: mübtəda — Biz; zərflik — axşama qədər; xəbər — oynadıq.');
INSERT INTO public.questions VALUES (2328, 32, 'g9-aze-member-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Üçdə bir hissəni «qardaşıma» verdim.", "B": "Hətta «kiçik» uşaqlar bu mahnını bilirdi.", "C": "Mən çay və «peçenye» aldım.", "D": "Axı sən bunu «bilirdin».", "E": "O, «dostu» ilə parkda gəzirdi."}'::jsonb, 'D', NULL, '«bilirdin» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2329, 32, 'g9-aze-member-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Əlbəttə, «sən» bu kitabı oxumalısan.", "B": "«Səkkiz» şagird olimpiadaya qatıldı.", "C": "Əlbəttə, sən bu kitabı «oxumalısan».", "D": "Ah, mən açarı evdə «unutmuşam»!", "E": "Əhsən, siz bu «yarışı» uddunuz!"}'::jsonb, 'B', NULL, '«Səkkiz» — təyin, say. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2330, 32, 'g9-aze-member-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir?', NULL, NULL, '{"A": "Biz dənizə doğru «irəlilədik».", "B": "Sən ya «çay», ya da şirə iç.", "C": "Təəssüf ki, qatar «vaxtında» gəlmədi.", "D": "Hətta kiçik uşaqlar bu mahnını «bilirdi».", "E": "Kim «bu» məktubu yazıb?"}'::jsonb, 'C', NULL, '«vaxtında» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2331, 32, 'g9-aze-member-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ancaq sən mənə inanırsan.", "B": "Doğrudan da, bu film maraqlıdır.", "C": "Yeddinci sinfin şagirdləri muzeyə getdilər.", "D": "Səkkiz şagird olimpiadaya qatıldı.", "E": "Bu kitabı mənə dostum bağışladı."}'::jsonb, 'C', NULL, '«Yeddinci sinfin şagirdləri muzeyə getdilər.»: təyin — Yeddinci sinfin; mübtəda — şagirdləri; zərflik — muzeyə; xəbər — getdilər.');
INSERT INTO public.questions VALUES (2332, 32, 'g9-aze-member-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir?', NULL, NULL, '{"A": "«Sınan» oyuncağı atam düzəltdi.", "B": "Biz əvvəlcə dərsimizi oxuduq, «sonra» oynadıq.", "C": "Sən ya çay, ya da «şirə» iç.", "D": "«O», dostu ilə parkda gəzirdi.", "E": "Bağçada «qırmızı» və sarı güllər açmışdı."}'::jsonb, 'D', NULL, '«O» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2333, 32, 'g9-aze-member-q1-23', 1, 23, 'hard', 'single', '«Yarım çörəyi quşlara verdi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Yarım — təyin; çörəyi — mübtəda; quşlara — vasitəli tamamlıq; verdi — xəbər", "B": "Yarım — təyin; çörəyi — vasitəsiz tamamlıq; quşlara — zərflik; verdi — xəbər", "C": "Yarım — təyin; çörəyi — vasitəli tamamlıq; quşlara — vasitəli tamamlıq; verdi — xəbər", "D": "Yarım — təyin; çörəyi — vasitəsiz tamamlıq; quşlara — vasitəli tamamlıq; verdi — xəbər", "E": "Yarım — vasitəli tamamlıq; çörəyi — vasitəsiz tamamlıq; quşlara — təyin; verdi — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Yarım — təyin; çörəyi — vasitəsiz tamamlıq; quşlara — vasitəli tamamlıq; verdi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2334, 32, 'g9-aze-member-q1-24', 1, 24, 'hard', 'single', '«O, dostu ilə parkda gəzirdi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — mübtəda", "B": "O — mübtəda; dostu ilə — xəbər; parkda — zərflik; gəzirdi — vasitəli tamamlıq", "C": "O — vasitəli tamamlıq; dostu ilə — mübtəda; parkda — zərflik; gəzirdi — xəbər", "D": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər", "E": "O — vasitəsiz tamamlıq; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2335, 32, 'g9-aze-member-q1-25', 1, 25, 'hard', 'single', '«Nənəm nəvələrinə maraqlı nağıllar danışırdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Nənəm — mübtəda; nəvələrinə — vasitəli tamamlıq; maraqlı — təyin; nağıllar — vasitəsiz tamamlıq", "B": "Nənəm — təyin; nəvələrinə — vasitəli tamamlıq; maraqlı — təyin; nağıllar — vasitəsiz tamamlıq", "C": "Nənəm — mübtəda; nəvələrinə — vasitəli tamamlıq; maraqlı — zərflik; nağıllar — vasitəsiz tamamlıq", "D": "Nənəm — mübtəda; nəvələrinə — vasitəsiz tamamlıq; maraqlı — təyin; nağıllar — vasitəli tamamlıq", "E": "Nənəm — vasitəsiz tamamlıq; nəvələrinə — vasitəli tamamlıq; maraqlı — təyin; nağıllar — mübtəda"}'::jsonb, 'A', NULL, 'Düzgün: Nənəm — mübtəda; nəvələrinə — vasitəli tamamlıq; maraqlı — təyin; nağıllar — vasitəsiz tamamlıq. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2336, 32, 'g9-aze-member-q1-26', 1, 26, 'hard', 'single', '«Uşaqlar meşəyə tərəf qaçdılar.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Uşaqlar — mübtəda; meşəyə tərəf — zərflik; qaçdılar — xəbər", "B": "Uşaqlar — mübtəda; meşəyə tərəf — təyin; qaçdılar — xəbər", "C": "Uşaqlar — xəbər; meşəyə tərəf — zərflik; qaçdılar — mübtəda", "D": "Uşaqlar — təyin; meşəyə tərəf — zərflik; qaçdılar — xəbər", "E": "Uşaqlar — mübtəda; meşəyə tərəf — zərflik; qaçdılar — təyin"}'::jsonb, 'A', NULL, 'Düzgün: Uşaqlar — mübtəda; meşəyə tərəf — zərflik; qaçdılar — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2337, 32, 'g9-aze-member-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir?', NULL, NULL, '{"A": "«Kitab» oxumağı sevirəm.", "B": "«Nənəm» nəvələrinə maraqlı nağıllar danışırdı.", "C": "Hətta babam «kompüterdə» oynayırdı.", "D": "Beş-altı quş budağa «qondu».", "E": "Hətta kiçik uşaqlar «bu» mahnını bilirdi."}'::jsonb, 'C', NULL, '«kompüterdə» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2338, 32, 'g9-aze-member-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Şübhəsiz, bu il məhsul bol olacaq.", "B": "Əlbəttə, sən bu kitabı oxumalısan.", "C": "Siz nə oxuyursunuz?", "D": "Anam bazardan beş alma aldı.", "E": "Oxuyan uşaq başını kitabdan qaldırdı."}'::jsonb, 'C', NULL, '«Siz nə oxuyursunuz?»: mübtəda — Siz; vasitəsiz tamamlıq — nə; xəbər — oxuyursunuz.');
INSERT INTO public.questions VALUES (2339, 32, 'g9-aze-member-q1-29', 1, 29, 'hard', 'single', '«O kitabı rəfə qoy.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "O — təyin; kitabı — vasitəsiz tamamlıq; rəfə — zərflik; qoy — xəbər", "B": "O — təyin; kitabı — xəbər; rəfə — zərflik; qoy — vasitəsiz tamamlıq", "C": "O — zərflik; kitabı — vasitəsiz tamamlıq; rəfə — zərflik; qoy — xəbər", "D": "O — təyin; kitabı — vasitəsiz tamamlıq; rəfə — vasitəli tamamlıq; qoy — xəbər", "E": "O — təyin; kitabı — vasitəsiz tamamlıq; rəfə — zərflik; qoy — mübtəda"}'::jsonb, 'A', NULL, 'Düzgün: O — təyin; kitabı — vasitəsiz tamamlıq; rəfə — zərflik; qoy — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2340, 32, 'g9-aze-member-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və təyin əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Biz yay tətilində dənizə getdik.", "B": "O, dostu ilə parkda gəzirdi.", "C": "Bu hədiyyəni sənin üçün almışam.", "D": "Şübhəsiz, bu il məhsul bol olacaq.", "E": "Əhsən, siz bu yarışı uddunuz!"}'::jsonb, 'E', NULL, '«Əhsən, siz bu yarışı uddunuz!»: mübtəda — siz; təyin — bu; vasitəsiz tamamlıq — yarışı; xəbər — uddunuz.');
INSERT INTO public.questions VALUES (2341, 32, 'g9-aze-member-q2-01', 2, 1, 'hard', 'single', '«Gözəl və geniş otaqda qonaqlar oturmuşdular.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Gözəl — mübtəda; geniş — təyin; otaqda — zərflik; qonaqlar — mübtəda", "B": "Gözəl — təyin; geniş — mübtəda; otaqda — zərflik; qonaqlar — mübtəda", "C": "Gözəl — təyin; geniş — təyin; otaqda — zərflik; qonaqlar — təyin", "D": "Gözəl — təyin; geniş — təyin; otaqda — zərflik; qonaqlar — vasitəsiz tamamlıq", "E": "Gözəl — təyin; geniş — təyin; otaqda — zərflik; qonaqlar — mübtəda"}'::jsonb, 'E', NULL, 'Düzgün: Gözəl — təyin; geniş — təyin; otaqda — zərflik; qonaqlar — mübtəda. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2342, 32, 'g9-aze-member-q2-02', 2, 2, 'hard', 'single', '«O, quş kimi oxuyur.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "O — mübtəda; quş kimi — zərflik; oxuyur — xəbər", "B": "O — zərflik; quş kimi — mübtəda; oxuyur — xəbər", "C": "O — mübtəda; quş kimi — zərflik; oxuyur — mübtəda", "D": "O — mübtəda; quş kimi — təyin; oxuyur — xəbər", "E": "O — xəbər; quş kimi — zərflik; oxuyur — mübtəda"}'::jsonb, 'A', NULL, 'Düzgün: O — mübtəda; quş kimi — zərflik; oxuyur — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2343, 32, 'g9-aze-member-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir?', NULL, NULL, '{"A": "Heç kim bu «tapmacanı» tapmadı.", "B": "Biz əvvəlcə «dərsimizi» oxuduq, sonra oynadıq.", "C": "«Biz» axşama qədər oynadıq.", "D": "Əli ilə Vəli «bu» məktəbdə oxuyurlar.", "E": "Biz «axşama» qədər oynadıq."}'::jsonb, 'E', NULL, '«axşama» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2344, 32, 'g9-aze-member-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Həmin axşam güclü «külək» əsdi.", "B": "«Bu» kitabı mənə dostum bağışladı.", "C": "O, «quş» kimi oxuyur.", "D": "Yəqin, qonaqlar «yorulublar».", "E": "Uşaqlar «meşəyə» tərəf qaçdılar."}'::jsonb, 'D', NULL, '«yorulublar» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2345, 32, 'g9-aze-member-q2-05', 2, 5, 'hard', 'single', '«Kimsə qapını yavaşca döydü.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Kimsə — vasitəsiz tamamlıq; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — xəbər", "B": "Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — mübtəda", "C": "Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — xəbər", "D": "Kimsə — xəbər; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — mübtəda", "E": "Kimsə — mübtəda; qapını — zərflik; yavaşca — vasitəsiz tamamlıq; döydü — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Kimsə — mübtəda; qapını — vasitəsiz tamamlıq; yavaşca — zərflik; döydü — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2346, 32, 'g9-aze-member-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda yoxdur?', NULL, NULL, '{"A": "Anam bazardan beş alma aldı.", "B": "Kitab oxumağı sevirəm.", "C": "Heç kim bu tapmacanı tapmadı.", "D": "Kim bu məktubu yazıb?", "E": "Əlbəttə, sən bu kitabı oxumalısan."}'::jsonb, 'B', NULL, '«Kitab oxumağı sevirəm.»: vasitəsiz tamamlıq — Kitab oxumağı; xəbər — sevirəm.');
INSERT INTO public.questions VALUES (2347, 32, 'g9-aze-member-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir?', NULL, NULL, '{"A": "«Biz» dənizə doğru irəlilədik.", "B": "Sən ya «çay», ya da şirə iç.", "C": "Əlbəttə, «sən» bu kitabı oxumalısan.", "D": "Həmin axşam güclü «külək» əsdi.", "E": "Oxuyan «uşaq» başını kitabdan qaldırdı."}'::jsonb, 'B', NULL, '«çay» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2348, 32, 'g9-aze-member-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin var?', NULL, NULL, '{"A": "Bəs siz sabah gəlmirsiniz?", "B": "Hətta babam kompüterdə oynayırdı.", "C": "Həmin axşam güclü külək əsdi.", "D": "Qardaşım məktəbdən sonra kitabxanaya gedir.", "E": "Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq."}'::jsonb, 'C', NULL, '«Həmin axşam güclü külək əsdi.»: təyin — Həmin; zərflik — axşam; təyin — güclü; mübtəda — külək; xəbər — əsdi.');
INSERT INTO public.questions VALUES (2349, 32, 'g9-aze-member-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə təyin əvəzliklə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Bağçada qırmızı və sarı güllər açmışdı.", "B": "Anam bazardan beş alma aldı.", "C": "Mən çay və peçenye aldım.", "D": "Üçüncü cərgədə iki boş yer qalmışdı.", "E": "Şübhəsiz, bu il məhsul bol olacaq."}'::jsonb, 'E', NULL, '«Şübhəsiz, bu il məhsul bol olacaq.»: təyin — bu; zərflik — il; mübtəda — məhsul; xəbər — bol olacaq.');
INSERT INTO public.questions VALUES (2350, 32, 'g9-aze-member-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Bu kitabı mənə dostum bağışladı.", "B": "Gəncə qədim şəhərdir.", "C": "Evə çatanda anam məni qarşıladı.", "D": "Hətta kiçik uşaqlar bu mahnını bilirdi.", "E": "Ancaq sən mənə inanırsan."}'::jsonb, 'E', NULL, '«Ancaq sən mənə inanırsan.»: mübtəda — sən; vasitəli tamamlıq — mənə; xəbər — inanırsan.');
INSERT INTO public.questions VALUES (2351, 32, 'g9-aze-member-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Of, mən «yoruldum».", "B": "Gülümsəyən «qız» əlini yellədi.", "C": "Həm «atam», həm də anam bu xəbərə sevindi.", "D": "Həmin «axşam» güclü külək əsdi.", "E": "Hər «şagird» öz dəftərini götürdü."}'::jsonb, 'A', NULL, '«yoruldum» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2352, 32, 'g9-aze-member-q2-12', 2, 12, 'hard', 'single', '«Səhərdən bəri yağış yağır.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Səhərdən bəri — təyin; yağış — mübtəda; yağır — xəbər", "B": "Səhərdən bəri — zərflik; yağış — təyin; yağır — xəbər", "C": "Səhərdən bəri — zərflik; yağış — xəbər; yağır — mübtəda", "D": "Səhərdən bəri — zərflik; yağış — vasitəsiz tamamlıq; yağır — xəbər", "E": "Səhərdən bəri — zərflik; yağış — mübtəda; yağır — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Səhərdən bəri — zərflik; yağış — mübtəda; yağır — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2353, 32, 'g9-aze-member-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Nə qar, nə də «yağış» yağdı.", "B": "Əli ilə Vəli «bu» məktəbdə oxuyurlar.", "C": "«Atam» qəzet və jurnal oxuyur.", "D": "Səhərdən bəri «yağış» yağır.", "E": "«Kimsə» qapını yavaşca döydü."}'::jsonb, 'B', NULL, '«bu» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2354, 32, 'g9-aze-member-q2-14', 2, 14, 'hard', 'single', '«Ah, mən açarı evdə unutmuşam!» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "mən — vasitəsiz tamamlıq; açarı — vasitəsiz tamamlıq; evdə — zərflik; unutmuşam — xəbər", "B": "mən — mübtəda; açarı — zərflik; evdə — vasitəsiz tamamlıq; unutmuşam — xəbər", "C": "mən — mübtəda; açarı — vasitəsiz tamamlıq; evdə — zərflik; unutmuşam — mübtəda", "D": "mən — mübtəda; açarı — vasitəsiz tamamlıq; evdə — təyin; unutmuşam — xəbər", "E": "mən — mübtəda; açarı — vasitəsiz tamamlıq; evdə — zərflik; unutmuşam — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: mən — mübtəda; açarı — vasitəsiz tamamlıq; evdə — zərflik; unutmuşam — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2355, 32, 'g9-aze-member-q2-15', 2, 15, 'hard', 'single', '«Bu kitabı mənə dostum bağışladı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Bu — zərflik; kitabı — vasitəsiz tamamlıq; mənə — vasitəli tamamlıq; dostum — mübtəda", "B": "Bu — mübtəda; kitabı — vasitəsiz tamamlıq; mənə — vasitəli tamamlıq; dostum — mübtəda", "C": "Bu — təyin; kitabı — vasitəsiz tamamlıq; mənə — vasitəli tamamlıq; dostum — mübtəda", "D": "Bu — təyin; kitabı — vasitəli tamamlıq; mənə — vasitəli tamamlıq; dostum — mübtəda", "E": "Bu — təyin; kitabı — vasitəsiz tamamlıq; mənə — vasitəsiz tamamlıq; dostum — mübtəda"}'::jsonb, 'C', NULL, 'Düzgün: Bu — təyin; kitabı — vasitəsiz tamamlıq; mənə — vasitəli tamamlıq; dostum — mübtəda. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2356, 32, 'g9-aze-member-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir?', NULL, NULL, '{"A": "Həmin axşam güclü külək «əsdi».", "B": "Qoy Anar bu şeiri «oxusun».", "C": "«Siz» nə oxuyursunuz?", "D": "Doğrudan da, «bu» film maraqlıdır.", "E": "Gözəl və geniş «otaqda» qonaqlar oturmuşdular."}'::jsonb, 'C', NULL, '«Siz» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2357, 32, 'g9-aze-member-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub və zərflik var?', NULL, NULL, '{"A": "Qoy Anar bu şeiri oxusun.", "B": "Ay uşaqlar, dərhal sinfə qayıdın!", "C": "Biz axşama qədər oynadıq.", "D": "Həmin axşam güclü külək əsdi.", "E": "Ey dostlar, bura gəlin!"}'::jsonb, 'D', NULL, '«Həmin axşam güclü külək əsdi.»: təyin — Həmin; zərflik — axşam; təyin — güclü; mübtəda — külək; xəbər — əsdi.');
INSERT INTO public.questions VALUES (2358, 32, 'g9-aze-member-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Məhz sən «bu» işi bacararsan.", "B": "«Bu» kitabı mənə dostum bağışladı.", "C": "Hər şagird «öz» dəftərini götürdü.", "D": "Babam «bizə» iki quzu bağışladı.", "E": "Beş-altı quş budağa «qondu»."}'::jsonb, 'E', NULL, '«qondu» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2359, 32, 'g9-aze-member-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Ura, komandamız kuboku qazandı!", "B": "Biz dənizə doğru irəlilədik.", "C": "Mən çay və peçenye aldım.", "D": "Gülümsəyən qız əlini yellədi.", "E": "Evə çatanda anam məni qarşıladı."}'::jsonb, 'C', NULL, '«Mən çay və peçenye aldım.»: mübtəda — Mən; vasitəsiz tamamlıq — çay; vasitəsiz tamamlıq — peçenye; xəbər — aldım.');
INSERT INTO public.questions VALUES (2360, 32, 'g9-aze-member-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Səkkiz şagird olimpiadaya qatıldı.", "B": "Babam bizə iki quzu bağışladı.", "C": "Neçə şagird yarışa qatıldı?", "D": "Qoy Anar bu şeiri oxusun.", "E": "Ancaq sən mənə inanırsan."}'::jsonb, 'D', NULL, '«Qoy Anar bu şeiri oxusun.»: mübtəda — Anar; təyin — bu; vasitəsiz tamamlıq — şeiri; xəbər — oxusun.');
INSERT INTO public.questions VALUES (2361, 32, 'g9-aze-member-q2-21', 2, 21, 'hard', 'single', '«Mən çay və peçenye aldım.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Mən — mübtəda; çay — mübtəda; peçenye — vasitəsiz tamamlıq; aldım — xəbər", "B": "Mən — mübtəda; çay — vasitəsiz tamamlıq; peçenye — vasitəsiz tamamlıq; aldım — xəbər", "C": "Mən — mübtəda; çay — vasitəsiz tamamlıq; peçenye — vasitəsiz tamamlıq; aldım — təyin", "D": "Mən — vasitəsiz tamamlıq; çay — vasitəsiz tamamlıq; peçenye — mübtəda; aldım — xəbər", "E": "Mən — vasitəsiz tamamlıq; çay — vasitəsiz tamamlıq; peçenye — vasitəsiz tamamlıq; aldım — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Mən — mübtəda; çay — vasitəsiz tamamlıq; peçenye — vasitəsiz tamamlıq; aldım — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2362, 32, 'g9-aze-member-q2-22', 2, 22, 'hard', 'single', '«Qoy uşaqlar həyətdə oynasınlar.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "uşaqlar — mübtəda; həyətdə — vasitəli tamamlıq; oynasınlar — xəbər", "B": "uşaqlar — mübtəda; həyətdə — xəbər; oynasınlar — zərflik", "C": "uşaqlar — xəbər; həyətdə — zərflik; oynasınlar — mübtəda", "D": "uşaqlar — mübtəda; həyətdə — zərflik; oynasınlar — təyin", "E": "uşaqlar — mübtəda; həyətdə — zərflik; oynasınlar — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: uşaqlar — mübtəda; həyətdə — zərflik; oynasınlar — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2363, 32, 'g9-aze-member-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Üçdə bir hissəni qardaşıma verdim.", "B": "Dərsə gecikməmək üçün evdən erkən çıxdım.", "C": "Sabah yaxud birigün Bakıya gedəcəyik.", "D": "Bəs siz sabah gəlmirsiniz?", "E": "Ay uşaqlar, dərhal sinfə qayıdın!"}'::jsonb, 'D', NULL, '«Bəs siz sabah gəlmirsiniz?»: mübtəda — siz; zərflik — sabah; xəbər — gəlmirsiniz.');
INSERT INTO public.questions VALUES (2364, 32, 'g9-aze-member-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə zərflik qoşmalı birləşmə ilə ifadə olunub və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "O, quş kimi oxuyur.", "B": "Həm atam, həm də anam bu xəbərə sevindi.", "C": "Həmin axşam güclü külək əsdi.", "D": "Uşaqlar yuxarı qalxdılar.", "E": "Gəncə qədim şəhərdir."}'::jsonb, 'A', NULL, '«O, quş kimi oxuyur.»: mübtəda — O; zərflik — quş kimi; xəbər — oxuyur.');
INSERT INTO public.questions VALUES (2365, 32, 'g9-aze-member-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Anam bazardan beş «alma» aldı.", "B": "Ey dostlar, bura «gəlin»!", "C": "Qardaşım və bacım kinoya «getdilər».", "D": "Yalnız Leyla «tapşırığı» vaxtında bitirdi.", "E": "«Həmin» axşam güclü külək əsdi."}'::jsonb, 'E', NULL, '«Həmin» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2366, 32, 'g9-aze-member-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir?', NULL, NULL, '{"A": "O, kitabı «rəfə» qoydu.", "B": "Uşaqlar «meşəyə» tərəf qaçdılar.", "C": "Hətta «kiçik» uşaqlar bu mahnını bilirdi.", "D": "Yalnız Leyla tapşırığı vaxtında «bitirdi».", "E": "Üçdə bir «hissəni» qardaşıma verdim."}'::jsonb, 'E', NULL, '«hissəni» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2367, 32, 'g9-aze-member-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "O kitabı rəfə qoy.", "B": "Üçdə bir hissəni qardaşıma verdim.", "C": "Yağış yağanda uşaqlar evə qaçdılar.", "D": "Dərsə gecikməmək üçün evdən erkən çıxdım.", "E": "Doğrudan da, bu film maraqlıdır."}'::jsonb, 'C', NULL, '«Yağış yağanda uşaqlar evə qaçdılar.»: zərflik — Yağış yağanda; mübtəda — uşaqlar; zərflik — evə; xəbər — qaçdılar.');
INSERT INTO public.questions VALUES (2368, 32, 'g9-aze-member-q2-28', 2, 28, 'hard', 'single', '«Atam qəzet və jurnal oxuyur.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Atam — mübtəda; qəzet — xəbər; jurnal — vasitəsiz tamamlıq; oxuyur — vasitəsiz tamamlıq", "B": "Atam — xəbər; qəzet — vasitəsiz tamamlıq; jurnal — vasitəsiz tamamlıq; oxuyur — mübtəda", "C": "Atam — mübtəda; qəzet — vasitəsiz tamamlıq; jurnal — vasitəsiz tamamlıq; oxuyur — xəbər", "D": "Atam — mübtəda; qəzet — vasitəsiz tamamlıq; jurnal — vasitəli tamamlıq; oxuyur — xəbər", "E": "Atam — mübtəda; qəzet — vasitəsiz tamamlıq; jurnal — xəbər; oxuyur — vasitəsiz tamamlıq"}'::jsonb, 'C', NULL, 'Düzgün: Atam — mübtəda; qəzet — vasitəsiz tamamlıq; jurnal — vasitəsiz tamamlıq; oxuyur — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2369, 32, 'g9-aze-member-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Həmin axşam güclü «külək» əsdi.", "B": "Qoy uşaqlar həyətdə «oynasınlar».", "C": "«Həmin» axşam güclü külək əsdi.", "D": "Ey dostlar, «bura» gəlin!", "E": "Qoy Anar bu şeiri «oxusun»."}'::jsonb, 'C', NULL, '«Həmin» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2370, 32, 'g9-aze-member-q2-30', 2, 30, 'hard', 'single', '«Əlbəttə, sən bu kitabı oxumalısan.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "sən — mübtəda; bu — mübtəda; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər", "B": "sən — mübtəda; bu — xəbər; kitabı — vasitəsiz tamamlıq; oxumalısan — təyin", "C": "sən — mübtəda; bu — təyin; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər", "D": "sən — vasitəsiz tamamlıq; bu — təyin; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər", "E": "sən — mübtəda; bu — vasitəsiz tamamlıq; kitabı — təyin; oxumalısan — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: sən — mübtəda; bu — təyin; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2371, 32, 'g9-aze-member-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Atam qəzet və jurnal oxuyur.", "B": "Babam bizə iki quzu bağışladı.", "C": "Nənəm nəvələrinə maraqlı nağıllar danışırdı.", "D": "Bu hədiyyəni sənin üçün almışam.", "E": "Həm atam, həm də anam bu xəbərə sevindi."}'::jsonb, 'A', NULL, '«Atam qəzet və jurnal oxuyur.»: mübtəda — Atam; vasitəsiz tamamlıq — qəzet; vasitəsiz tamamlıq — jurnal; xəbər — oxuyur.');
