INSERT INTO public.questions VALUES (2374, 32, 'g9-aze-member-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub və təyin var?', NULL, NULL, '{"A": "Qız gülə-gülə otağa girdi.", "B": "Bu kitabı mənə dostum bağışladı.", "C": "Yalnız Leyla tapşırığı vaxtında bitirdi.", "D": "Əlbəttə, sən bu kitabı oxumalısan.", "E": "Səhərdən bəri yağış yağır."}'::jsonb, 'B', NULL, '«Bu kitabı mənə dostum bağışladı.»: təyin — Bu; vasitəsiz tamamlıq — kitabı; vasitəli tamamlıq — mənə; mübtəda — dostum; xəbər — bağışladı.');
INSERT INTO public.questions VALUES (2375, 32, 'g9-aze-member-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Əli ilə Vəli «bu» məktəbdə oxuyurlar.", "B": "Qoy Anar bu «şeiri» oxusun.", "C": "Həm atam, həm də anam bu «xəbərə» sevindi.", "D": "Hətta kiçik «uşaqlar» bu mahnını bilirdi.", "E": "Həmin axşam güclü külək «əsdi»."}'::jsonb, 'A', NULL, '«bu» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2376, 32, 'g9-aze-member-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Sınan oyuncağı atam düzəltdi.", "B": "Yarım çörəyi quşlara verdi.", "C": "Atam qəzet və jurnal oxuyur.", "D": "Anam bazardan beş alma aldı.", "E": "Gülümsəyən qız əlini yellədi."}'::jsonb, 'C', NULL, '«Atam qəzet və jurnal oxuyur.»: mübtəda — Atam; vasitəsiz tamamlıq — qəzet; vasitəsiz tamamlıq — jurnal; xəbər — oxuyur.');
INSERT INTO public.questions VALUES (2377, 32, 'g9-aze-member-q3-07', 3, 7, 'hard', 'single', '«Müəllim lövhəyə iki misal yazdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Müəllim — mübtəda; lövhəyə — zərflik; iki — təyin; misal — vasitəsiz tamamlıq", "B": "Müəllim — təyin; lövhəyə — zərflik; iki — mübtəda; misal — vasitəsiz tamamlıq", "C": "Müəllim — vasitəsiz tamamlıq; lövhəyə — zərflik; iki — təyin; misal — vasitəsiz tamamlıq", "D": "Müəllim — mübtəda; lövhəyə — zərflik; iki — mübtəda; misal — vasitəsiz tamamlıq", "E": "Müəllim — mübtəda; lövhəyə — zərflik; iki — zərflik; misal — vasitəsiz tamamlıq"}'::jsonb, 'A', NULL, 'Düzgün: Müəllim — mübtəda; lövhəyə — zərflik; iki — təyin; misal — vasitəsiz tamamlıq. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2378, 32, 'g9-aze-member-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Babam bizə iki quzu bağışladı.", "B": "O kitabı rəfə qoy.", "C": "Qoy Anar bu şeiri oxusun.", "D": "Ancaq sən mənə inanırsan.", "E": "Nənəm nəvələrinə maraqlı nağıllar danışırdı."}'::jsonb, 'D', NULL, '«Ancaq sən mənə inanırsan.»: mübtəda — sən; vasitəli tamamlıq — mənə; xəbər — inanırsan.');
INSERT INTO public.questions VALUES (2379, 32, 'g9-aze-member-q3-09', 3, 9, 'hard', 'single', '«Səkkiz şagird olimpiadaya qatıldı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Səkkiz — təyin; şagird — mübtəda; olimpiadaya — vasitəli tamamlıq; qatıldı — xəbər", "B": "Səkkiz — təyin; şagird — mübtəda; olimpiadaya — vasitəli tamamlıq; qatıldı — mübtəda", "C": "Səkkiz — təyin; şagird — mübtəda; olimpiadaya — vasitəsiz tamamlıq; qatıldı — xəbər", "D": "Səkkiz — təyin; şagird — mübtəda; olimpiadaya — vasitəli tamamlıq; qatıldı — təyin", "E": "Səkkiz — mübtəda; şagird — təyin; olimpiadaya — vasitəli tamamlıq; qatıldı — xəbər"}'::jsonb, 'A', NULL, 'Düzgün: Səkkiz — təyin; şagird — mübtəda; olimpiadaya — vasitəli tamamlıq; qatıldı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2380, 32, 'g9-aze-member-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir?', NULL, NULL, '{"A": "Uşaqlar «ucadan» güldülər.", "B": "Vay, stəkan «sındı»!", "C": "Sınan oyuncağı atam «düzəltdi».", "D": "Əhsən, siz «bu» yarışı uddunuz!", "E": "Oxuyan uşaq «başını» kitabdan qaldırdı."}'::jsonb, 'D', NULL, '«bu» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2381, 32, 'g9-aze-member-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və həmcins mübtədalar var?', NULL, NULL, '{"A": "Əli ilə Vəli bu məktəbdə oxuyurlar.", "B": "O kitabı rəfə qoy.", "C": "Axı sən bunu bilirdin.", "D": "Kim bu məktubu yazıb?", "E": "Bəs siz sabah gəlmirsiniz?"}'::jsonb, 'A', NULL, '«Əli ilə Vəli bu məktəbdə oxuyurlar.»: mübtəda — Əli; mübtəda — Vəli; təyin — bu; zərflik — məktəbdə; xəbər — oxuyurlar.');
INSERT INTO public.questions VALUES (2382, 32, 'g9-aze-member-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Hətta babam «kompüterdə» oynayırdı.", "B": "Gözəl və geniş otaqda «qonaqlar» oturmuşdular.", "C": "Həmin «axşam» güclü külək əsdi.", "D": "Sən ya çay, ya da şirə «iç».", "E": "Biz «əvvəlcə» dərsimizi oxuduq, sonra oynadıq."}'::jsonb, 'D', NULL, '«iç» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2383, 32, 'g9-aze-member-q3-13', 3, 13, 'hard', 'single', '«Kim bu məktubu yazıb?» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Kim — mübtəda; bu — təyin; məktubu — vasitəsiz tamamlıq; yazıb — mübtəda", "B": "Kim — mübtəda; bu — mübtəda; məktubu — vasitəsiz tamamlıq; yazıb — xəbər", "C": "Kim — mübtəda; bu — təyin; məktubu — xəbər; yazıb — vasitəsiz tamamlıq", "D": "Kim — mübtəda; bu — təyin; məktubu — vasitəsiz tamamlıq; yazıb — xəbər", "E": "Kim — mübtəda; bu — təyin; məktubu — vasitəli tamamlıq; yazıb — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Kim — mübtəda; bu — təyin; məktubu — vasitəsiz tamamlıq; yazıb — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2384, 32, 'g9-aze-member-q3-14', 3, 14, 'hard', 'single', '«Heç kim bu tapmacanı tapmadı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Heç kim — vasitəsiz tamamlıq; bu — təyin; tapmacanı — vasitəsiz tamamlıq; tapmadı — xəbər", "B": "Heç kim — mübtəda; bu — təyin; tapmacanı — vasitəsiz tamamlıq; tapmadı — xəbər", "C": "Heç kim — xəbər; bu — təyin; tapmacanı — vasitəsiz tamamlıq; tapmadı — mübtəda", "D": "Heç kim — mübtəda; bu — təyin; tapmacanı — vasitəsiz tamamlıq; tapmadı — təyin", "E": "Heç kim — mübtəda; bu — təyin; tapmacanı — vasitəli tamamlıq; tapmadı — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Heç kim — mübtəda; bu — təyin; tapmacanı — vasitəsiz tamamlıq; tapmadı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2385, 32, 'g9-aze-member-q3-15', 3, 15, 'hard', 'single', '«Əlbəttə, sən bu kitabı oxumalısan.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "sən — mübtəda; bu — xəbər; kitabı — vasitəsiz tamamlıq; oxumalısan — təyin", "B": "sən — mübtəda; bu — təyin; kitabı — mübtəda; oxumalısan — xəbər", "C": "sən — mübtəda; bu — mübtəda; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər", "D": "sən — mübtəda; bu — təyin; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər", "E": "sən — təyin; bu — mübtəda; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: sən — mübtəda; bu — təyin; kitabı — vasitəsiz tamamlıq; oxumalısan — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2386, 32, 'g9-aze-member-q3-16', 3, 16, 'hard', 'single', '«Bəs siz sabah gəlmirsiniz?» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "siz — mübtəda; sabah — zərflik; gəlmirsiniz — mübtəda", "B": "siz — mübtəda; sabah — vasitəli tamamlıq; gəlmirsiniz — xəbər", "C": "siz — mübtəda; sabah — zərflik; gəlmirsiniz — xəbər", "D": "siz — zərflik; sabah — mübtəda; gəlmirsiniz — xəbər", "E": "siz — mübtəda; sabah — zərflik; gəlmirsiniz — təyin"}'::jsonb, 'C', NULL, 'Düzgün: siz — mübtəda; sabah — zərflik; gəlmirsiniz — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2387, 32, 'g9-aze-member-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəli tamamlıq vəzifəsindədir?', NULL, NULL, '{"A": "Gəncə «qədim» şəhərdir.", "B": "Hətta kiçik uşaqlar bu mahnını «bilirdi».", "C": "Babam «bizə» iki quzu bağışladı.", "D": "Hətta kiçik «uşaqlar» bu mahnını bilirdi.", "E": "Qoy Anar bu şeiri «oxusun»."}'::jsonb, 'C', NULL, '«bizə» — vasitəli tamamlıq, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2388, 32, 'g9-aze-member-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir?', NULL, NULL, '{"A": "«Uşaqlar» meşəyə tərəf qaçdılar.", "B": "Siz nə «oxuyursunuz»?", "C": "«Gülümsəyən» qız əlini yellədi.", "D": "Yəqin, qonaqlar «yorulublar».", "E": "Biz «dənizə» doğru irəlilədik."}'::jsonb, 'A', NULL, '«Uşaqlar» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2389, 32, 'g9-aze-member-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə zərflik zərflə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Anam bazardan beş alma aldı.", "B": "Qoy uşaqlar həyətdə oynasınlar.", "C": "Uşaqlar meşəyə tərəf qaçdılar.", "D": "Dünən biz qədim qalaya qədər piyada getdik.", "E": "Sınan oyuncağı atam düzəltdi."}'::jsonb, 'D', NULL, '«Dünən biz qədim qalaya qədər piyada getdik.»: zərflik — Dünən; mübtəda — biz; təyin — qədim; zərflik — qalaya qədər piyada; xəbər — getdik.');
INSERT INTO public.questions VALUES (2390, 32, 'g9-aze-member-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir?', NULL, NULL, '{"A": "Uşaqlar ucadan «güldülər».", "B": "Həm atam, həm də anam bu «xəbərə» sevindi.", "C": "Səhərdən bəri yağış «yağır».", "D": "Bu kitabı mənə «dostum» bağışladı.", "E": "O, «kitabı» rəfə qoydu."}'::jsonb, 'D', NULL, '«dostum» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2391, 32, 'g9-aze-member-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Səkkiz şagird olimpiadaya qatıldı.", "B": "Dünən biz qədim qalaya qədər piyada getdik.", "C": "Kim bu məktubu yazıb?", "D": "Ey dostlar, bura gəlin!", "E": "Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq."}'::jsonb, 'C', NULL, '«Kim bu məktubu yazıb?»: mübtəda — Kim; təyin — bu; vasitəsiz tamamlıq — məktubu; xəbər — yazıb.');
INSERT INTO public.questions VALUES (2392, 32, 'g9-aze-member-q3-22', 3, 22, 'hard', 'single', '«O, dostu ilə parkda gəzirdi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər", "B": "O — mübtəda; dostu ilə — vasitəsiz tamamlıq; parkda — zərflik; gəzirdi — xəbər", "C": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — mübtəda", "D": "O — vasitəsiz tamamlıq; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər", "E": "O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — vasitəli tamamlıq; gəzirdi — xəbər"}'::jsonb, 'A', NULL, 'Düzgün: O — mübtəda; dostu ilə — vasitəli tamamlıq; parkda — zərflik; gəzirdi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2393, 32, 'g9-aze-member-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Yağış yağanda uşaqlar evə «qaçdılar».", "B": "Kim bu «məktubu» yazıb?", "C": "Gəncə «qədim» şəhərdir.", "D": "«Heç kim» bu tapmacanı tapmadı.", "E": "O «kitabı» rəfə qoy."}'::jsonb, 'A', NULL, '«qaçdılar» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2394, 32, 'g9-aze-member-q3-24', 3, 24, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir?', NULL, NULL, '{"A": "Kim bu məktubu «yazıb»?", "B": "Yağış yağanda «uşaqlar» evə qaçdılar.", "C": "Qoy uşaqlar «həyətdə» oynasınlar.", "D": "«Neçə» şagird yarışa qatıldı?", "E": "«Bu» kitabı mənə dostum bağışladı."}'::jsonb, 'B', NULL, '«uşaqlar» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2395, 32, 'g9-aze-member-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə vasitəsiz tamamlıq məsdər və ya onun tərkibi ilə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Dərsdən əvvəl müəllim jurnalı yoxladı.", "B": "Kitab oxumağı sevirəm.", "C": "Bəs siz sabah gəlmirsiniz?", "D": "Hətta babam kompüterdə oynayırdı.", "E": "Axı sən bunu bilirdin."}'::jsonb, 'B', NULL, '«Kitab oxumağı sevirəm.»: vasitəsiz tamamlıq — Kitab oxumağı; xəbər — sevirəm.');
INSERT INTO public.questions VALUES (2396, 32, 'g9-aze-member-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "Bəs «siz» sabah gəlmirsiniz?", "B": "Sən ya çay, ya da şirə «iç».", "C": "«Kimsə» qapını yavaşca döydü.", "D": "Gözəl və «geniş» otaqda qonaqlar oturmuşdular.", "E": "«Anam» bazardan beş alma aldı."}'::jsonb, 'B', NULL, '«iç» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2397, 32, 'g9-aze-member-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir?', NULL, NULL, '{"A": "O kitabı «rəfə» qoy.", "B": "O, «kitabı» rəfə qoydu.", "C": "Nənəm nəvələrinə maraqlı nağıllar «danışırdı».", "D": "Sınan «oyuncağı» atam düzəltdi.", "E": "Afərin, sən bütün «tapmacaları» tapdın!"}'::jsonb, 'C', NULL, '«danışırdı» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (2398, 32, 'g9-aze-member-q3-28', 3, 28, 'hard', 'single', '«Təəssüf ki, qatar vaxtında gəlmədi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "qatar — mübtəda; vaxtında — zərflik; gəlmədi — mübtəda", "B": "qatar — mübtəda; vaxtında — zərflik; gəlmədi — təyin", "C": "qatar — xəbər; vaxtında — zərflik; gəlmədi — mübtəda", "D": "qatar — mübtəda; vaxtında — xəbər; gəlmədi — zərflik", "E": "qatar — mübtəda; vaxtında — zərflik; gəlmədi — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: qatar — mübtəda; vaxtında — zərflik; gəlmədi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2399, 32, 'g9-aze-member-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Atam işdən gec qayıtdı.", "B": "Oxuyan uşaq başını kitabdan qaldırdı.", "C": "Səhərdən bəri yağış yağır.", "D": "Qardaşım məktəbdən sonra kitabxanaya gedir.", "E": "Həm atam, həm də anam bu xəbərə sevindi."}'::jsonb, 'E', NULL, '«Həm atam, həm də anam bu xəbərə sevindi.»: mübtəda — atam; mübtəda — anam; təyin — bu; vasitəli tamamlıq — xəbərə; xəbər — sevindi.');
INSERT INTO public.questions VALUES (2400, 32, 'g9-aze-member-q3-30', 3, 30, 'hard', 'single', '«Nə qar, nə də yağış yağdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "qar — mübtəda; yağış — təyin; yağdı — xəbər", "B": "qar — mübtəda; yağış — mübtəda; yağdı — mübtəda", "C": "qar — mübtəda; yağış — mübtəda; yağdı — xəbər", "D": "qar — xəbər; yağış — mübtəda; yağdı — mübtəda", "E": "qar — təyin; yağış — mübtəda; yağdı — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: qar — mübtəda; yağış — mübtəda; yağdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (2401, 33, 'g9-aze-complex-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "B": "Ya sən gəl, ya da mən gəlim.", "C": "Yağış yağsa da, biz yola çıxdıq.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Elə bir kitab oxudum ki, onu heç unutmaram."}'::jsonb, 'C', NULL, '«Yağış yağsa da, biz yola çıxdıq.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2402, 33, 'g9-aze-complex-q1-02', 1, 2, 'hard', 'single', '«Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "sadə cümlə"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (2403, 33, 'g9-aze-complex-q1-03', 1, 3, 'hard', 'single', '«Əgər yağış yağsa, gəzintiyə çıxmayacağıq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2404, 33, 'g9-aze-complex-q1-04', 1, 4, 'hard', 'single', 'Hansı variantda budaq cümlə «hərçənd» bağlayıcısı ilə bağlanıb və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Erkən yatdım ki, səhər tez durum.", "B": "Nə qədər çox oxusan, o qədər çox bilərsən.", "C": "Hərçənd yorğun idi, o, işini bitirdi.", "D": "Elə bir kitab oxudum ki, onu heç unutmaram.", "E": "Dərsə gecikdim, çünki avtobus gəlmədi."}'::jsonb, 'C', NULL, '«Hərçənd yorğun idi, o, işini bitirdi.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2405, 33, 'g9-aze-complex-q1-05', 1, 5, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Dərsə gecikdim, çünki avtobus gəlmədi.", "B": "Yağış yağsa da, biz yola çıxdıq.", "C": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.", "D": "Nə qədər çox oxusan, o qədər çox bilərsən.", "E": "Erkən yatdım ki, səhər tez durum."}'::jsonb, 'E', NULL, '«Erkən yatdım ki, səhər tez durum.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2406, 33, 'g9-aze-complex-q1-06', 1, 6, 'hard', 'single', '«Hərçənd yorğun idi, o, işini bitirdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2407, 33, 'g9-aze-complex-q1-07', 1, 7, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və budaq cümlə məqsəd budaq cümləsidir?', NULL, NULL, '{"A": "Aydındır ki, bu iş asan deyil.", "B": "Məqsədim budur ki, həkim olum.", "C": "Elə bir kitab oxudum ki, onu heç unutmaram.", "D": "Müəllim dedi ki, sabah imtahan olacaq.", "E": "Erkən yatdım ki, səhər tez durum."}'::jsonb, 'E', NULL, '«Erkən yatdım ki, səhər tez durum.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2408, 33, 'g9-aze-complex-q1-08', 1, 8, 'hard', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Harada bulaq var, orada həyat var.", "B": "Yağış yağsa da, biz yola çıxdıq.", "C": "Nə qədər çox oxusan, o qədər çox bilərsən.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Kim çalışsa, o, qalib gələr."}'::jsonb, 'B', NULL, '«Yağış yağsa da, biz yola çıxdıq.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2409, 33, 'g9-aze-complex-q1-09', 1, 9, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib və cümlə 3 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Yağış dayandı, günəş çıxdı.", "B": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "C": "Çalışsan, uğur qazanarsan.", "D": "Yağış yağsa da, biz yola çıxdıq.", "E": "Zəng çalınanda şagirdlər sinfə daxil oldular."}'::jsonb, 'B', NULL, '«Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 3 komponent).');
INSERT INTO public.questions VALUES (2410, 33, 'g9-aze-complex-q1-10', 1, 10, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Bağçada qızılgüllər, lalələr və nərgizlər açmışdı.", "B": "Yağış dayandı, günəş çıxdı.", "C": "Ya sən gəl, ya da mən gəlim.", "D": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "E": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq."}'::jsonb, 'C', NULL, '«Ya sən gəl, ya da mən gəlim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2411, 33, 'g9-aze-complex-q1-11', 1, 11, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Həm atam gəldi, həm də anam zəng etdi.", "B": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "C": "Yağış dayandı, günəş çıxdı.", "D": "Ya sən gəl, ya da mən gəlim.", "E": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı."}'::jsonb, 'C', NULL, '«Yağış dayandı, günəş çıxdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 2 komponent).');
INSERT INTO public.questions VALUES (2412, 33, 'g9-aze-complex-q1-12', 1, 12, 'hard', 'single', 'Hansı variantda budaq cümlə məqsəd budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o, işini bitirdi.", "B": "Nə qədər çox oxusan, o qədər çox bilərsən.", "C": "Yağış yağsa da, biz yola çıxdıq.", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Dərsə gecikdim, çünki avtobus gəlmədi."}'::jsonb, 'D', NULL, '«Erkən yatdım ki, səhər tez durum.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2413, 33, 'g9-aze-complex-q1-13', 1, 13, 'hard', 'single', '«Elə bir kitab oxudum ki, onu heç unutmaram.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra.');
