INSERT INTO public.questions VALUES (2417, 33, 'g9-aze-complex-q1-17', 1, 17, 'hard', 'single', 'Hansı variantda budaq cümlə kəmiyyət budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Nə qədər çox oxusan, o qədər çox bilərsən.", "B": "Dərsə gecikdim, çünki avtobus gəlmədi.", "C": "Bilirəm ki, sən düz deyirsən.", "D": "Yağış yağsa da, biz yola çıxdıq.", "E": "Müəllim dedi ki, sabah imtahan olacaq."}'::jsonb, 'A', NULL, '«Nə qədər çox oxusan, o qədər çox bilərsən.» — tabeli mürəkkəb cümlədir: budaq cümlə — kəmiyyət, baş cümlədən əvvəl.');
