INSERT INTO public.questions VALUES (2422, 33, 'g9-aze-complex-q1-22', 1, 22, 'hard', 'single', '«Elə bir kitab oxudum ki, onu heç unutmaram.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra.');
