INSERT INTO public.questions VALUES (2424, 33, 'g9-aze-complex-q1-24', 1, 24, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Harada bulaq var, orada həyat var.", "B": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "C": "Hərçənd yorğun idi, o, işini bitirdi.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Yağış yağsa da, biz yola çıxdıq."}'::jsonb, 'D', NULL, '«Elə ki yaz gəldi, quşlar geri qayıtdı.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2425, 33, 'g9-aze-complex-q1-25', 1, 25, 'hard', 'single', '«Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "sadə cümlə", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent.');
INSERT INTO public.questions VALUES (2426, 33, 'g9-aze-complex-q1-26', 1, 26, 'hard', 'single', '«Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "D": "sadə cümlə", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent.');
INSERT INTO public.questions VALUES (2427, 33, 'g9-aze-complex-q1-27', 1, 27, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Kim çalışsa, o, qalib gələr.", "B": "Yağış dayandı, günəş çıxdı.", "C": "Məqsədim budur ki, həkim olum.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Həm atam gəldi, həm də anam zəng etdi."}'::jsonb, 'E', NULL, '«Həm atam gəldi, həm də anam zəng etdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2428, 33, 'g9-aze-complex-q1-28', 1, 28, 'hard', 'single', '«Kim çalışsa, o, qalib gələr.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2429, 33, 'g9-aze-complex-q1-29', 1, 29, 'hard', 'single', 'Hansı variantda budaq cümlə təyin budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Yağış yağsa da, biz yola çıxdıq.", "B": "Harada bulaq var, orada həyat var.", "C": "Elə bir kitab oxudum ki, onu heç unutmaram.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Məqsədim budur ki, həkim olum."}'::jsonb, 'C', NULL, '«Elə bir kitab oxudum ki, onu heç unutmaram.» — tabeli mürəkkəb cümlədir: budaq cümlə — təyin, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2430, 33, 'g9-aze-complex-q1-30', 1, 30, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Yağış dayandı, günəş çıxdı.", "B": "Məqsədim budur ki, həkim olum.", "C": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "D": "O, evə gəldi və dərslərini hazırladı.", "E": "Həm atam gəldi, həm də anam zəng etdi."}'::jsonb, 'E', NULL, '«Həm atam gəldi, həm də anam zəng etdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2431, 33, 'g9-aze-complex-q2-01', 2, 1, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.", "B": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "C": "Həm atam gəldi, həm də anam zəng etdi.", "D": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "E": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi."}'::jsonb, 'B', NULL, '«Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 3 komponent).');
INSERT INTO public.questions VALUES (2432, 33, 'g9-aze-complex-q2-02', 2, 2, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "B": "Dərsə gecikdim, çünki avtobus gəlmədi.", "C": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Hərçənd yorğun idi, o, işini bitirdi."}'::jsonb, 'D', NULL, '«Elə ki yaz gəldi, quşlar geri qayıtdı.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2433, 33, 'g9-aze-complex-q2-03', 2, 3, 'hard', 'single', '«Kim çalışsa, o, qalib gələr.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2434, 33, 'g9-aze-complex-q2-04', 2, 4, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və budaq cümlə xəbər budaq cümləsidir?', NULL, NULL, '{"A": "Elə bir kitab oxudum ki, onu heç unutmaram.", "B": "Aydındır ki, bu iş asan deyil.", "C": "Məqsədim budur ki, həkim olum.", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Müəllim dedi ki, sabah imtahan olacaq."}'::jsonb, 'C', NULL, '«Məqsədim budur ki, həkim olum.» — tabeli mürəkkəb cümlədir: budaq cümlə — xəbər, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2435, 33, 'g9-aze-complex-q2-05', 2, 5, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Müəllim dedi ki, sabah imtahan olacaq.", "B": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "C": "Yağış dayandı, günəş çıxdı.", "D": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "E": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı."}'::jsonb, 'E', NULL, '«Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2436, 33, 'g9-aze-complex-q2-06', 2, 6, 'hard', 'single', 'Hansı variantda budaq cümlə bağlayıcısız, xəbərin şəkilçisi vasitəsilə bağlanıb və budaq cümlə şərt budaq cümləsidir?', NULL, NULL, '{"A": "Yağış yağsa da, biz yola çıxdıq.", "B": "Çalışsan, uğur qazanarsan.", "C": "Hərçənd yorğun idi, o, işini bitirdi.", "D": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "E": "Kim çalışsa, o, qalib gələr."}'::jsonb, 'B', NULL, '«Çalışsan, uğur qazanarsan.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2437, 33, 'g9-aze-complex-q2-07', 2, 7, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "B": "Bilirəm ki, sən düz deyirsən.", "C": "Müəllim dedi ki, sabah imtahan olacaq.", "D": "Nə qədər çox oxusan, o qədər çox bilərsən.", "E": "Hava soyudu, amma biz gəzintiyə çıxdıq."}'::jsonb, 'E', NULL, '«Hava soyudu, amma biz gəzintiyə çıxdıq.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2438, 33, 'g9-aze-complex-q2-08', 2, 8, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Aydındır ki, bu iş asan deyil.", "B": "Dərsə gecikdim, çünki avtobus gəlmədi.", "C": "Çalışsan, uğur qazanarsan.", "D": "Harada bulaq var, orada həyat var.", "E": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı."}'::jsonb, 'A', NULL, '«Aydındır ki, bu iş asan deyil.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
