INSERT INTO public.questions VALUES (2446, 33, 'g9-aze-complex-q2-16', 2, 16, 'hard', 'single', '«Nə qədər çox oxusan, o qədər çox bilərsən.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2447, 33, 'g9-aze-complex-q2-17', 2, 17, 'hard', 'single', '«Kim çalışsa, o, qalib gələr.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2448, 33, 'g9-aze-complex-q2-18', 2, 18, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Məqsədim budur ki, həkim olum.", "B": "Nə qədər çox oxusan, o qədər çox bilərsən.", "C": "Yağış dayandı, günəş çıxdı.", "D": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.", "E": "Müəllim dedi ki, sabah imtahan olacaq."}'::jsonb, 'C', NULL, '«Yağış dayandı, günəş çıxdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 2 komponent).');
INSERT INTO public.questions VALUES (2449, 33, 'g9-aze-complex-q2-19', 2, 19, 'hard', 'single', '«Harada bulaq var, orada həyat var.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən sonra", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2450, 33, 'g9-aze-complex-q2-20', 2, 20, 'hard', 'single', '«Məqsədim budur ki, həkim olum.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2451, 33, 'g9-aze-complex-q2-21', 2, 21, 'hard', 'single', '«Hava soyudu, amma biz gəzintiyə çıxdıq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "sadə cümlə", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (2452, 33, 'g9-aze-complex-q2-22', 2, 22, 'hard', 'single', 'Hansı variantda budaq cümlə xəbər budaq cümləsidir və budaq cümlə «ki» bağlayıcısı ilə bağlanıb?', NULL, NULL, '{"A": "Erkən yatdım ki, səhər tez durum.", "B": "Bilirəm ki, sən düz deyirsən.", "C": "Məqsədim budur ki, həkim olum.", "D": "Müəllim dedi ki, sabah imtahan olacaq.", "E": "Elə bir kitab oxudum ki, onu heç unutmaram."}'::jsonb, 'C', NULL, '«Məqsədim budur ki, həkim olum.» — tabeli mürəkkəb cümlədir: budaq cümlə — xəbər, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2453, 33, 'g9-aze-complex-q2-23', 2, 23, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Ya sən gəl, ya da mən gəlim.", "B": "Dərsə gecikdim, çünki avtobus gəlmədi.", "C": "Çalışsan, uğur qazanarsan.", "D": "Nə qədər çox oxusan, o qədər çox bilərsən.", "E": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq."}'::jsonb, 'A', NULL, '«Ya sən gəl, ya da mən gəlim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2454, 33, 'g9-aze-complex-q2-24', 2, 24, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Kim çalışsa, o, qalib gələr.", "B": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "C": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "D": "Yağış dayandı, günəş çıxdı.", "E": "Yağış yağsa da, biz yola çıxdıq."}'::jsonb, 'C', NULL, '«Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
