INSERT INTO public.questions VALUES (2456, 33, 'g9-aze-complex-q2-26', 2, 26, 'hard', 'single', 'Hansı variantda budaq cümlə təyin budaq cümləsidir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Dərsə gecikdim, çünki avtobus gəlmədi.", "B": "Bilirəm ki, sən düz deyirsən.", "C": "Erkən yatdım ki, səhər tez durum.", "D": "Elə bir kitab oxudum ki, onu heç unutmaram.", "E": "Müəllim dedi ki, sabah imtahan olacaq."}'::jsonb, 'D', NULL, '«Elə bir kitab oxudum ki, onu heç unutmaram.» — tabeli mürəkkəb cümlədir: budaq cümlə — təyin, baş cümlədən sonra.');
