INSERT INTO public.questions VALUES (2465, 33, 'g9-aze-complex-q3-05', 3, 5, 'hard', 'single', '«Yağış dayandı, günəş çıxdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent.');
INSERT INTO public.questions VALUES (2466, 33, 'g9-aze-complex-q3-06', 3, 6, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o, işini bitirdi.", "B": "Elə bir kitab oxudum ki, onu heç unutmaram.", "C": "Yağış dayandı, günəş çıxdı.", "D": "Həm atam gəldi, həm də anam zəng etdi.", "E": "Bilirəm ki, sən düz deyirsən."}'::jsonb, 'D', NULL, '«Həm atam gəldi, həm də anam zəng etdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2467, 33, 'g9-aze-complex-q3-07', 3, 7, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Kim çalışsa, o, qalib gələr.", "B": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "C": "Ya sən gəl, ya da mən gəlim.", "D": "Yağış dayandı, günəş çıxdı.", "E": "Bağçada qızılgüllər, lalələr və nərgizlər açmışdı."}'::jsonb, 'C', NULL, '«Ya sən gəl, ya da mən gəlim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2468, 33, 'g9-aze-complex-q3-08', 3, 8, 'hard', 'single', 'Hansı variantda budaq cümlə şərt budaq cümləsidir və budaq cümlə bağlayıcısız, xəbərin şəkilçisi vasitəsilə bağlanıb?', NULL, NULL, '{"A": "Yağış yağsa da, biz yola çıxdıq.", "B": "Məqsədim budur ki, həkim olum.", "C": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "D": "Çalışsan, uğur qazanarsan.", "E": "Erkən yatdım ki, səhər tez durum."}'::jsonb, 'D', NULL, '«Çalışsan, uğur qazanarsan.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2469, 33, 'g9-aze-complex-q3-09', 3, 9, 'hard', 'single', '«Erkən yatdım ki, səhər tez durum.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2470, 33, 'g9-aze-complex-q3-10', 3, 10, 'hard', 'single', 'Hansı variantda budaq cümlə tamamlıq budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o, işini bitirdi.", "B": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.", "C": "Müəllim dedi ki, sabah imtahan olacaq.", "D": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "E": "Kim çalışsa, o, qalib gələr."}'::jsonb, 'C', NULL, '«Müəllim dedi ki, sabah imtahan olacaq.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2471, 33, 'g9-aze-complex-q3-11', 3, 11, 'hard', 'single', '«Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "sadə cümlə", "D": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (2472, 33, 'g9-aze-complex-q3-12', 3, 12, 'hard', 'single', '«Elə ki yaz gəldi, quşlar geri qayıtdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2473, 33, 'g9-aze-complex-q3-13', 3, 13, 'hard', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Bilirəm ki, sən düz deyirsən.", "B": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "C": "Ya sən gəl, ya da mən gəlim.", "D": "Yağış yağsa da, biz yola çıxdıq.", "E": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi."}'::jsonb, 'D', NULL, '«Yağış yağsa da, biz yola çıxdıq.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2474, 33, 'g9-aze-complex-q3-14', 3, 14, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Yağış dayandı, günəş çıxdı.", "B": "O, evə gəldi və dərslərini hazırladı.", "C": "Dərsə gecikdim, çünki avtobus gəlmədi.", "D": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.", "E": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı."}'::jsonb, 'D', NULL, '«Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2475, 33, 'g9-aze-complex-q3-15', 3, 15, 'hard', 'single', '«Həm atam gəldi, həm də anam zəng etdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "sadə cümlə", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (2476, 33, 'g9-aze-complex-q3-16', 3, 16, 'hard', 'single', '«Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "D": "sadə cümlə", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (2477, 33, 'g9-aze-complex-q3-17', 3, 17, 'hard', 'single', '«Müəllim dedi ki, sabah imtahan olacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2478, 33, 'g9-aze-complex-q3-18', 3, 18, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "B": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "C": "Həm atam gəldi, həm də anam zəng etdi.", "D": "Yağış dayandı, günəş çıxdı.", "E": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı."}'::jsonb, 'D', NULL, '«Yağış dayandı, günəş çıxdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 2 komponent).');
INSERT INTO public.questions VALUES (2479, 33, 'g9-aze-complex-q3-19', 3, 19, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "B": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "C": "Yağış dayandı, günəş çıxdı.", "D": "O, evə gəldi və dərslərini hazırladı.", "E": "Kim çalışsa, o, qalib gələr."}'::jsonb, 'B', NULL, '«Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2480, 33, 'g9-aze-complex-q3-20', 3, 20, 'hard', 'single', 'Hansı variantda budaq cümlə təyin budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Kim çalışsa, o, qalib gələr.", "B": "Çalışsan, uğur qazanarsan.", "C": "Elə bir kitab oxudum ki, onu heç unutmaram.", "D": "Yağış yağsa da, biz yola çıxdıq.", "E": "Harada bulaq var, orada həyat var."}'::jsonb, 'C', NULL, '«Elə bir kitab oxudum ki, onu heç unutmaram.» — tabeli mürəkkəb cümlədir: budaq cümlə — təyin, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2481, 33, 'g9-aze-complex-q3-21', 3, 21, 'hard', 'single', '«Kim çalışsa, o, qalib gələr.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2482, 33, 'g9-aze-complex-q3-22', 3, 22, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Yağış dayandı, günəş çıxdı.", "B": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "C": "Məqsədim budur ki, həkim olum.", "D": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "E": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı."}'::jsonb, 'D', NULL, '«Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (2483, 33, 'g9-aze-complex-q3-23', 3, 23, 'hard', 'single', '«Yağış yağsa da, biz yola çıxdıq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2484, 33, 'g9-aze-complex-q3-24', 3, 24, 'hard', 'single', 'Hansı variantda budaq cümlə mübtəda budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Ya sən gəl, ya da mən gəlim.", "B": "Aydındır ki, bu iş asan deyil.", "C": "Məqsədim budur ki, həkim olum.", "D": "Həm atam gəldi, həm də anam zəng etdi.", "E": "Hava soyudu, amma biz gəzintiyə çıxdıq."}'::jsonb, 'B', NULL, '«Aydındır ki, bu iş asan deyil.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2485, 33, 'g9-aze-complex-q3-25', 3, 25, 'hard', 'single', 'Hansı variantda budaq cümlə «əgər» bağlayıcısı ilə bağlanıb və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Harada bulaq var, orada həyat var.", "B": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "C": "Yağış yağsa da, biz yola çıxdıq.", "D": "Kim çalışsa, o, qalib gələr.", "E": "Nə qədər çox oxusan, o qədər çox bilərsən."}'::jsonb, 'B', NULL, '«Əgər yağış yağsa, gəzintiyə çıxmayacağıq.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
