INSERT INTO public.questions VALUES (2487, 33, 'g9-aze-complex-q3-27', 3, 27, 'hard', 'single', 'Hansı variantda budaq cümlə şərt budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Harada bulaq var, orada həyat var.", "B": "Müəllim dedi ki, sabah imtahan olacaq.", "C": "Məqsədim budur ki, həkim olum.", "D": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "E": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi."}'::jsonb, 'D', NULL, '«Əgər yağış yağsa, gəzintiyə çıxmayacağıq.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2488, 33, 'g9-aze-complex-q3-28', 3, 28, 'hard', 'single', 'Hansı variantda budaq cümlə tamamlıq budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Erkən yatdım ki, səhər tez durum.", "B": "Bilirəm ki, sən düz deyirsən.", "C": "Kim çalışsa, o, qalib gələr.", "D": "Elə bir kitab oxudum ki, onu heç unutmaram.", "E": "Çalışsan, uğur qazanarsan."}'::jsonb, 'B', NULL, '«Bilirəm ki, sən düz deyirsən.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2489, 33, 'g9-aze-complex-q3-29', 3, 29, 'hard', 'single', '«Harada bulaq var, orada həyat var.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (2490, 33, 'g9-aze-complex-q3-30', 3, 30, 'hard', 'single', '«Bilirəm ki, sən düz deyirsən.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (2491, 34, 'g9-aze-punct-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hətta kiçik uşaqlar bu mahnını bilirdi.", "B": "Üçüncü cərgədə iki boş yer qalmışdı.", "C": "Gülümsəyən qız əlini yellədi.", "D": "Yağış dayandı, günəş çıxdı.", "E": "Deməli, siz sabah Bakıya gedirsiniz."}'::jsonb, 'D', NULL, 'Düzgün: «Yağış dayandı, günəş çıxdı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2492, 34, 'g9-aze-punct-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Sabah yaxud birigün Bakıya gedəcəyik.", "B": "Kim çalışsa, o, qalib gələr.", "C": "Sən ya çay ya da şirə iç.", "D": "Yağış yağsa da, biz yola çıxdıq.", "E": "Gözəl, və geniş otaqda qonaqlar oturmuşdular."}'::jsonb, 'A', NULL, 'Düzgün: «Sabah yaxud birigün Bakıya gedəcəyik.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2493, 34, 'g9-aze-punct-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Hər şagird öz dəftərini götürdü.", "B": "Şübhəsiz, bu il məhsul bol olacaq.", "C": "Bağçada qırmızı, və sarı güllər açmışdı.", "D": "Sən ya çay, ya da şirə iç.", "E": "Hətta babam kompüterdə oynayırdı."}'::jsonb, 'D', NULL, 'Düzgün: «Sən ya çay, ya da şirə iç.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2494, 34, 'g9-aze-punct-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hərçənd yorğun idi o işini bitirdi.", "B": "Bilirəm, ki sən düz deyirsən.", "C": "Harada bulaq var, orada həyat var.", "D": "Elə ki yaz gəldi quşlar geri qayıtdı.", "E": "Kim çalışsa o, qalib gələr."}'::jsonb, 'C', NULL, 'Düzgün: «Harada bulaq var, orada həyat var.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2495, 34, 'g9-aze-punct-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib?', NULL, NULL, '{"A": "Afərin, sən bütün tapmacaları tapdın!", "B": "Həm atam, həm də anam bu xəbərə sevindi.", "C": "Səhərdən bəri yağış yağır.", "D": "Ey dostlar bura gəlin!", "E": "Biz axşama qədər oynadıq."}'::jsonb, 'A', NULL, 'Düzgün: «Afərin, sən bütün tapmacaları tapdın!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2496, 34, 'g9-aze-punct-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bəs siz sabah gəlmirsiniz.", "B": "Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.", "C": "Ya sən gəl ya da mən gəlim.", "D": "Bilirəm, ki sən düz deyirsən.", "E": "Hətta kiçik, uşaqlar bu mahnını bilirdi."}'::jsonb, 'B', NULL, 'Düzgün: «Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2497, 34, 'g9-aze-punct-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Zəng, çalınanda şagirdlər sinfə daxil oldular.", "B": "Təəssüf, ki qatar vaxtında gəlmədi.", "C": "Çalışsan uğur qazanarsan.", "D": "Bəlkə biz sabah dənizə gedək.", "E": "Doğrudan da, bu film maraqlıdır."}'::jsonb, 'E', NULL, 'Düzgün: «Doğrudan da, bu film maraqlıdır.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2498, 34, 'g9-aze-punct-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Qar yağırdı külək əsirdi yollar buz bağlamışdı.", "B": "Bağçada qızılgüllər, lalələr və nərgizlər açmışdı.", "C": "Atam, işdən gec qayıtdı.", "D": "Əlbəttə sən bu kitabı oxumalısan.", "E": "Bəlkə biz sabah dənizə gedək."}'::jsonb, 'B', NULL, 'Düzgün: «Bağçada qızılgüllər, lalələr və nərgizlər açmışdı.». Digər cümlələrdə: iki vergül buraxılıb; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2499, 34, 'g9-aze-punct-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Qar yağırdı külək əsirdi yollar buz bağlamışdı.", "B": "Əhsən siz bu yarışı uddunuz!", "C": "Ah, mən açarı evdə unutmuşam!", "D": "Kim bu məktubu yazıb.", "E": "Uşaqlar, meşəyə tərəf qaçdılar."}'::jsonb, 'C', NULL, 'Düzgün: «Ah, mən açarı evdə unutmuşam!». Digər cümlələrdə: iki vergül buraxılıb; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; sual cümləsinin sonunda nöqtə qoyulub; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2500, 34, 'g9-aze-punct-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim çalışsa o qalib gələr.", "B": "Elə bir kitab oxudum ki, onu heç unutmaram.", "C": "Dərsə gecikdim çünki, avtobus gəlmədi.", "D": "Aydındır, ki bu iş asan deyil.", "E": "Məqsədim budur ki həkim olum."}'::jsonb, 'B', NULL, 'Düzgün: «Elə bir kitab oxudum ki, onu heç unutmaram.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2501, 34, 'g9-aze-punct-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Ya sən gəl, ya da mən gəlim.", "B": "Aydındır ki, bu iş asan deyil.", "C": "Yağış dayandı günəş çıxdı.", "D": "Gəncə qədim şəhərdir.", "E": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq."}'::jsonb, 'A', NULL, 'Düzgün: «Ya sən gəl, ya da mən gəlim.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2502, 34, 'g9-aze-punct-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Müəllim dedi ki sabah imtahan olacaq.", "B": "Erkən yatdım, ki səhər tez durum.", "C": "Harada bulaq var, orada həyat var.", "D": "Elə ki yaz gəldi quşlar geri qayıtdı.", "E": "Dərsə gecikdim çünki, avtobus gəlmədi."}'::jsonb, 'C', NULL, 'Düzgün: «Harada bulaq var, orada həyat var.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2503, 34, 'g9-aze-punct-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf, ki qatar vaxtında gəlmədi.", "B": "Axşamüstü səmada parlaq, ulduzlar göründü.", "C": "Yəqin, qonaqlar yorulublar.", "D": "Şübhəsiz bu il məhsul bol olacaq.", "E": "Həmin axşam güclü, külək əsdi."}'::jsonb, 'C', NULL, 'Düzgün: «Yəqin, qonaqlar yorulublar.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2504, 34, 'g9-aze-punct-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Yəqin, qonaqlar yorulublar.", "B": "Of, mən yoruldum.", "C": "Kim çalışsa, o, qalib gələr.", "D": "Hətta babam kompüterdə oynayırdı.", "E": "Yalnız Leyla tapşırığı vaxtında bitirdi."}'::jsonb, 'C', NULL, 'Düzgün: «Kim çalışsa, o, qalib gələr.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2505, 34, 'g9-aze-punct-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o, işini bitirdi.", "B": "Biz dənizə doğru irəlilədik.", "C": "Zəng çalınanda şagirdlər sinfə daxil oldular.", "D": "Sınan oyuncağı atam düzəltdi.", "E": "Əlbəttə, sən bu kitabı oxumalısan."}'::jsonb, 'A', NULL, 'Düzgün: «Hərçənd yorğun idi, o, işini bitirdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2506, 34, 'g9-aze-punct-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Uşaqlar, həyətdə oynayırdı, nənələri isə onlara baxırdı.", "B": "Qoy uşaqlar həyətdə oynasınlar.", "C": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "D": "Kim bu məktubu yazıb?", "E": "Erkən yatdım ki, səhər tez durum."}'::jsonb, 'C', NULL, 'Düzgün: «Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2507, 34, 'g9-aze-punct-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ya sən gəl ya da mən gəlim.", "B": "Yağış dayandı, günəş çıxdı.", "C": "Mən, dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "D": "Qar yağırdı külək əsirdi yollar buz bağlamışdı.", "E": "Uşaqlar həyətdə oynayırdı nənələri isə onlara baxırdı."}'::jsonb, 'B', NULL, 'Düzgün: «Yağış dayandı, günəş çıxdı.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2508, 34, 'g9-aze-punct-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sual cümləsidir?', NULL, NULL, '{"A": "Hər şagird öz dəftərini götürdü.", "B": "Qız gülə-gülə otağa girdi.", "C": "Bağçada qızılgüllər, lalələr və nərgizlər açmışdı.", "D": "Qoy Anar bu şeiri oxusun.", "E": "Bəs siz sabah gəlmirsiniz?"}'::jsonb, 'E', NULL, 'Düzgün: «Bəs siz sabah gəlmirsiniz?». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2509, 34, 'g9-aze-punct-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Biz dənizə doğru irəlilədik.", "B": "Dərsə gecikməmək üçün evdən erkən çıxdım.", "C": "Yarım çörəyi quşlara verdi.", "D": "Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.", "E": "Sabah yaxud birigün Bakıya gedəcəyik."}'::jsonb, 'E', NULL, 'Düzgün: «Sabah yaxud birigün Bakıya gedəcəyik.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2510, 34, 'g9-aze-punct-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sual cümləsidir?', NULL, NULL, '{"A": "Bəs siz sabah gəlmirsiniz?", "B": "Sınan oyuncağı atam düzəltdi.", "C": "Üçüncü cərgədə iki boş yer qalmışdı.", "D": "Səkkiz şagird olimpiadaya qatıldı.", "E": "Hətta kiçik uşaqlar bu mahnını bilirdi."}'::jsonb, 'A', NULL, 'Düzgün: «Bəs siz sabah gəlmirsiniz?». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2511, 34, 'g9-aze-punct-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "O, dostu ilə parkda gəzirdi.", "B": "Elə bir kitab oxudum ki, onu heç unutmaram.", "C": "Əgər yağış yağsa gəzintiyə çıxmayacağıq.", "D": "Ah, mən açarı evdə unutmuşam!", "E": "Aydındır ki bu iş asan deyil."}'::jsonb, 'B', NULL, 'Düzgün: «Elə bir kitab oxudum ki, onu heç unutmaram.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2512, 34, 'g9-aze-punct-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bağçada qızılgüllər, lalələr, və nərgizlər açmışdı.", "B": "Vay stəkan sındı!", "C": "Əhsən, siz bu yarışı uddunuz!", "D": "Hərçənd yorğun idi o işini bitirdi.", "E": "Qar yağırdı külək əsirdi, yollar buz bağlamışdı."}'::jsonb, 'C', NULL, 'Düzgün: «Əhsən, siz bu yarışı uddunuz!». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2513, 34, 'g9-aze-punct-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Dərsə gecikdim çünki, avtobus gəlmədi.", "B": "Erkən yatdım ki səhər tez durum.", "C": "Müəllim dedi, ki sabah imtahan olacaq.", "D": "Bilirəm, ki sən düz deyirsən.", "E": "Kim çalışsa, o, qalib gələr."}'::jsonb, 'E', NULL, 'Düzgün: «Kim çalışsa, o, qalib gələr.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2514, 34, 'g9-aze-punct-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Qoy uşaqlar həyətdə oynasınlar.", "B": "Yarım çörəyi quşlara verdi.", "C": "Məqsədim budur ki, həkim olum.", "D": "Ya sən gəl, ya da mən gəlim.", "E": "Babam bizə iki quzu bağışladı."}'::jsonb, 'D', NULL, 'Düzgün: «Ya sən gəl, ya da mən gəlim.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2515, 34, 'g9-aze-punct-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o işini bitirdi.", "B": "Qar yağırdı külək əsirdi, yollar buz bağlamışdı.", "C": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "D": "Mən, dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "E": "Atam qəzet, və jurnal oxuyur."}'::jsonb, 'C', NULL, 'Düzgün: «Hava soyudu, amma biz gəzintiyə çıxdıq.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2516, 34, 'g9-aze-punct-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Səkkiz şagird olimpiadaya qatıldı.", "B": "Yalnız Leyla tapşırığı vaxtında bitirdi.", "C": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "D": "Ura, komandamız kuboku qazandı!", "E": "Hərçənd yorğun idi o, işini bitirdi."}'::jsonb, 'C', NULL, 'Düzgün: «Elə ki yaz gəldi, quşlar geri qayıtdı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2517, 34, 'g9-aze-punct-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Mən çay, və peçenye aldım.", "B": "Həm atam həm də anam bu xəbərə sevindi.", "C": "Atam qəzet, və jurnal oxuyur.", "D": "Nə qar, nə də yağış yağdı.", "E": "Əli, ilə Vəli bu məktəbdə oxuyurlar."}'::jsonb, 'D', NULL, 'Düzgün: «Nə qar, nə də yağış yağdı.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2518, 34, 'g9-aze-punct-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "O quş kimi oxuyur.", "B": "Harada bulaq var orada həyat var.", "C": "Müəllim, lövhəyə iki misal yazdı.", "D": "O, evə gəldi, və dərslərini hazırladı.", "E": "O, dostu ilə parkda gəzirdi."}'::jsonb, 'E', NULL, 'Düzgün: «O, dostu ilə parkda gəzirdi.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2519, 34, 'g9-aze-punct-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Heç kim bu tapmacanı tapmadı.", "B": "Hətta babam kompüterdə oynayırdı.", "C": "Biz yay tətilində dənizə getdik.", "D": "Dərsə gecikdim çünki avtobus gəlmədi.", "E": "Elə bir kitab oxudum ki, onu heç unutmaram."}'::jsonb, 'E', NULL, 'Düzgün: «Elə bir kitab oxudum ki, onu heç unutmaram.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2520, 34, 'g9-aze-punct-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim çalışsa, o, qalib gələr.", "B": "Aydındır, ki bu iş asan deyil.", "C": "Hərçənd yorğun idi o, işini bitirdi.", "D": "Dərsə gecikdim çünki, avtobus gəlmədi.", "E": "Erkən yatdım ki səhər tez durum."}'::jsonb, 'A', NULL, 'Düzgün: «Kim çalışsa, o, qalib gələr.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2521, 34, 'g9-aze-punct-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Əli, ilə Vəli bu məktəbdə oxuyurlar.", "B": "Qar yağırdı, külək əsirdi yollar buz bağlamışdı.", "C": "Uşaqlar, həyətdə oynayırdı, nənələri isə onlara baxırdı.", "D": "Yağış dayandı, günəş çıxdı.", "E": "Gəncə qədim, şəhərdir."}'::jsonb, 'D', NULL, 'Düzgün: «Yağış dayandı, günəş çıxdı.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2522, 34, 'g9-aze-punct-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bağçada qızılgüllər, lalələr, və nərgizlər açmışdı.", "B": "O, dostu ilə parkda gəzirdi.", "C": "O quş kimi oxuyur.", "D": "Bağçada qırmızı, və sarı güllər açmışdı.", "E": "Hərçənd yorğun idi o işini bitirdi."}'::jsonb, 'B', NULL, 'Düzgün: «O, dostu ilə parkda gəzirdi.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2523, 34, 'g9-aze-punct-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Təəssüf ki, qatar vaxtında gəlmədi.", "B": "Aydındır ki, bu iş asan deyil.", "C": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "D": "Həm atam, həm də anam bu xəbərə sevindi.", "E": "Mən dərsimi hazırladım, qardaşım isə rəsm çəkdi."}'::jsonb, 'D', NULL, 'Düzgün: «Həm atam, həm də anam bu xəbərə sevindi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2524, 34, 'g9-aze-punct-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Yəqin, qonaqlar yorulublar.", "B": "Bəlkə biz sabah dənizə gedək.", "C": "Təəssüf, ki qatar vaxtında gəlmədi.", "D": "Həm atam həm də anam bu xəbərə sevindi.", "E": "Qar yağırdı külək əsirdi yollar buz bağlamışdı."}'::jsonb, 'A', NULL, 'Düzgün: «Yəqin, qonaqlar yorulublar.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2525, 34, 'g9-aze-punct-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o, işini bitirdi.", "B": "Həm atam, həm də anam bu xəbərə sevindi.", "C": "Məqsədim budur ki, həkim olum.", "D": "Oxuyan uşaq başını kitabdan qaldırdı.", "E": "Zəng çalınanda şagirdlər sinfə daxil oldular."}'::jsonb, 'B', NULL, 'Düzgün: «Həm atam, həm də anam bu xəbərə sevindi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2526, 34, 'g9-aze-punct-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bəlkə biz sabah dənizə gedək.", "B": "Qız, gülə-gülə otağa girdi.", "C": "Təəssüf ki, qatar vaxtında gəlmədi.", "D": "Bağçada, qızılgüllər, lalələr və nərgizlər açmışdı.", "E": "Anam, bazardan beş alma aldı."}'::jsonb, 'C', NULL, 'Düzgün: «Təəssüf ki, qatar vaxtında gəlmədi.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2527, 34, 'g9-aze-punct-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Uşaqlar, həyətdə oynayırdı, nənələri isə onlara baxırdı.", "B": "Qar yağırdı külək əsirdi yollar buz bağlamışdı.", "C": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "D": "Mən dərsimi hazırladım qardaşım isə rəsm çəkdi.", "E": "Ya sən gəl ya da mən gəlim."}'::jsonb, 'C', NULL, 'Düzgün: «Hava soyudu, amma biz gəzintiyə çıxdıq.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2528, 34, 'g9-aze-punct-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Aydındır ki bu iş asan deyil.", "B": "Müəllim dedi, ki sabah imtahan olacaq.", "C": "Nə qədər çox oxusan o qədər çox bilərsən.", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Kim çalışsa o qalib gələr."}'::jsonb, 'D', NULL, 'Düzgün: «Erkən yatdım ki, səhər tez durum.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2529, 34, 'g9-aze-punct-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Erkən yatdım ki, səhər tez durum.", "B": "Kimsə qapını yavaşca döydü.", "C": "Atam işdən qayıdıb nahar etdi.", "D": "Gülümsəyən qız əlini yellədi.", "E": "Hətta kiçik uşaqlar bu mahnını bilirdi."}'::jsonb, 'A', NULL, 'Düzgün: «Erkən yatdım ki, səhər tez durum.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2530, 34, 'g9-aze-punct-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sadədir?', NULL, NULL, '{"A": "Nənəm nəvələrinə maraqlı nağıllar danışırdı.", "B": "Bağçada qırmızı və sarı güllər açmışdı.", "C": "Zəng çalınanda şagirdlər sinfə daxil oldular.", "D": "Həm atam, həm də anam bu xəbərə sevindi.", "E": "Qoy Anar bu şeiri oxusun."}'::jsonb, 'C', NULL, 'Düzgün: «Zəng çalınanda şagirdlər sinfə daxil oldular.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2531, 34, 'g9-aze-punct-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sual cümləsidir?', NULL, NULL, '{"A": "Bu hədiyyəni sənin üçün almışam.", "B": "Harada bulaq var, orada həyat var.", "C": "Üçdə bir hissəni qardaşıma verdim.", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Bəs siz sabah gəlmirsiniz?"}'::jsonb, 'E', NULL, 'Düzgün: «Bəs siz sabah gəlmirsiniz?». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2532, 34, 'g9-aze-punct-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Elə bir kitab oxudum, ki onu heç unutmaram.", "B": "Hərçənd yorğun idi, o, işini bitirdi.", "C": "Erkən yatdım ki səhər tez durum.", "D": "Məqsədim budur ki həkim olum.", "E": "Kim çalışsa o qalib gələr."}'::jsonb, 'B', NULL, 'Düzgün: «Hərçənd yorğun idi, o, işini bitirdi.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2533, 34, 'g9-aze-punct-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Yağış yağsa da, biz yola çıxdıq.", "B": "Kim çalışsa o qalib gələr.", "C": "Elə bir kitab oxudum ki onu heç unutmaram.", "D": "Bilirəm, ki sən düz deyirsən.", "E": "Harada bulaq var orada həyat var."}'::jsonb, 'A', NULL, 'Düzgün: «Yağış yağsa da, biz yola çıxdıq.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2534, 34, 'g9-aze-punct-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ura komandamız kuboku qazandı!", "B": "Bilirəm, ki sən düz deyirsən.", "C": "Afərin, sən bütün tapmacaları tapdın!", "D": "O, evə gəldi, və dərslərini hazırladı.", "E": "Dünən biz qədim, qalaya qədər piyada getdik."}'::jsonb, 'C', NULL, 'Düzgün: «Afərin, sən bütün tapmacaları tapdın!». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2535, 34, 'g9-aze-punct-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Əlbəttə, sən bu kitabı oxumalısan.", "B": "Həm atam, həm də anam bu xəbərə sevindi.", "C": "Həm atam gəldi, həm də anam zəng etdi.", "D": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "E": "Səkkiz şagird olimpiadaya qatıldı."}'::jsonb, 'A', NULL, 'Düzgün: «Əlbəttə, sən bu kitabı oxumalısan.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2536, 34, 'g9-aze-punct-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Yağış, dayandı, günəş çıxdı.", "B": "Gözəl, və geniş otaqda qonaqlar oturmuşdular.", "C": "Qar yağırdı, külək əsirdi yollar buz bağlamışdı.", "D": "Ya sən gəl, ya da mən gəlim.", "E": "Nənəm nəvələrinə maraqlı, nağıllar danışırdı."}'::jsonb, 'D', NULL, 'Düzgün: «Ya sən gəl, ya da mən gəlim.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2537, 34, 'g9-aze-punct-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Sınan oyuncağı atam düzəltdi.", "B": "Yəqin, qonaqlar yorulublar.", "C": "O, kitabı rəfə qoydu.", "D": "Ey dostlar, bura gəlin!", "E": "Qoy Anar bu şeiri oxusun."}'::jsonb, 'B', NULL, 'Düzgün: «Yəqin, qonaqlar yorulublar.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2538, 34, 'g9-aze-punct-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Yağış yağanda uşaqlar evə qaçdılar.", "B": "Yağış yağsa da biz yola çıxdıq.", "C": "Ura, komandamız kuboku qazandı!", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Erkən yatdım ki səhər tez durum."}'::jsonb, 'D', NULL, 'Düzgün: «Erkən yatdım ki, səhər tez durum.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2539, 34, 'g9-aze-punct-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib?', NULL, NULL, '{"A": "Qoy Anar bu şeiri oxusun.", "B": "Ay uşaqlar dərhal sinfə qayıdın!", "C": "Zəng çalınanda şagirdlər sinfə daxil oldular.", "D": "Əhsən, siz bu yarışı uddunuz!", "E": "Dərsdən əvvəl müəllim jurnalı yoxladı."}'::jsonb, 'D', NULL, 'Düzgün: «Əhsən, siz bu yarışı uddunuz!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2540, 34, 'g9-aze-punct-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Qar yağırdı külək əsirdi yollar buz bağlamışdı.", "B": "Mən, dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "C": "Hava soyudu amma biz gəzintiyə çıxdıq.", "D": "Yağış, dayandı, günəş çıxdı.", "E": "Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı."}'::jsonb, 'E', NULL, 'Düzgün: «Uşaqlar həyətdə oynayırdı, nənələri isə onlara baxırdı.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2541, 34, 'g9-aze-punct-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Neçə şagird yarışa qatıldı?", "B": "Erkən yatdım, ki səhər tez durum.", "C": "Üçüncü cərgədə iki boş yer qalmışdı.", "D": "Sabah yaxud birigün Bakıya gedəcəyik.", "E": "Nə qədər çox oxusan, o qədər çox bilərsən."}'::jsonb, 'E', NULL, 'Düzgün: «Nə qədər çox oxusan, o qədər çox bilərsən.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2542, 34, 'g9-aze-punct-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Nənəm nəvələrinə maraqlı, nağıllar danışırdı.", "B": "Ah, mən açarı evdə unutmuşam!", "C": "Of mən yoruldum.", "D": "Hava, soyudu, amma biz gəzintiyə çıxdıq.", "E": "Bilirəm, ki sən düz deyirsən."}'::jsonb, 'B', NULL, 'Düzgün: «Ah, mən açarı evdə unutmuşam!». Digər cümlələrdə: birinci sözdən sonra artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2543, 34, 'g9-aze-punct-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Doğrudan da, bu film maraqlıdır.", "B": "Əli ilə Vəli bu məktəbdə oxuyurlar.", "C": "Bilirəm ki, sən düz deyirsən.", "D": "Uşaqlar ucadan güldülər.", "E": "Təəssüf ki qatar vaxtında gəlmədi."}'::jsonb, 'A', NULL, 'Düzgün: «Doğrudan da, bu film maraqlıdır.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2544, 34, 'g9-aze-punct-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hətta kiçik uşaqlar bu mahnını bilirdi.", "B": "Kim bu məktubu yazıb?", "C": "Elə bir kitab oxudum ki, onu heç unutmaram.", "D": "Siz nə oxuyursunuz?", "E": "Bağçada qızılgüllər, lalələr və nərgizlər açmışdı."}'::jsonb, 'C', NULL, 'Düzgün: «Elə bir kitab oxudum ki, onu heç unutmaram.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2545, 34, 'g9-aze-punct-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Müəllim lövhəyə iki misal yazdı.", "B": "Beş-altı quş budağa qondu.", "C": "Təəssüf ki, qatar vaxtında gəlmədi.", "D": "Müəllim dedi ki, sabah imtahan olacaq.", "E": "Sabah yaxud birigün Bakıya gedəcəyik."}'::jsonb, 'C', NULL, 'Düzgün: «Təəssüf ki, qatar vaxtında gəlmədi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2546, 34, 'g9-aze-punct-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Kitab oxumağı sevirəm.", "B": "Gəncə qədim şəhərdir.", "C": "Atam qəzet və jurnal oxuyur.", "D": "Müəllim dedi ki, sabah imtahan olacaq.", "E": "Ay uşaqlar, dərhal sinfə qayıdın!"}'::jsonb, 'D', NULL, 'Düzgün: «Müəllim dedi ki, sabah imtahan olacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2547, 34, 'g9-aze-punct-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Şübhəsiz, bu il məhsul bol olacaq.", "B": "Gəncə, qədim şəhərdir.", "C": "Əlbəttə sən bu kitabı oxumalısan.", "D": "Aydındır ki bu iş asan deyil.", "E": "Təəssüf, ki qatar vaxtında gəlmədi."}'::jsonb, 'A', NULL, 'Düzgün: «Şübhəsiz, bu il məhsul bol olacaq.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2548, 34, 'g9-aze-punct-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o işini bitirdi.", "B": "Məqsədim budur, ki həkim olum.", "C": "Dərsə gecikdim çünki, avtobus gəlmədi.", "D": "Müəllim dedi, ki sabah imtahan olacaq.", "E": "Çalışsan, uğur qazanarsan."}'::jsonb, 'E', NULL, 'Düzgün: «Çalışsan, uğur qazanarsan.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2549, 34, 'g9-aze-punct-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hərçənd yorğun idi o işini bitirdi.", "B": "Məqsədim budur ki, həkim olum.", "C": "Kim çalışsa o qalib gələr.", "D": "Erkən yatdım, ki səhər tez durum.", "E": "Aydındır ki bu iş asan deyil."}'::jsonb, 'B', NULL, 'Düzgün: «Məqsədim budur ki, həkim olum.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2550, 34, 'g9-aze-punct-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Yarım çörəyi quşlara verdi.", "B": "Nə qar, nə də yağış yağdı.", "C": "Ya sən gəl, ya da mən gəlim.", "D": "Sən ya çay, ya da şirə iç.", "E": "Zəng çalınanda şagirdlər sinfə daxil oldular."}'::jsonb, 'C', NULL, 'Düzgün: «Ya sən gəl, ya da mən gəlim.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2551, 34, 'g9-aze-punct-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Nə qədər çox oxusan, o qədər çox bilərsən.", "B": "Qardaşım məktəbdən sonra kitabxanaya gedir.", "C": "Hava soyudu, amma biz gəzintiyə çıxdıq.", "D": "Neçə şagird yarışa qatıldı?", "E": "Aydındır ki, bu iş asan deyil."}'::jsonb, 'C', NULL, 'Düzgün: «Hava soyudu, amma biz gəzintiyə çıxdıq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2552, 34, 'g9-aze-punct-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Mən, dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "B": "Təəssüf, ki qatar vaxtında gəlmədi.", "C": "Kim çalışsa, o qalib gələr.", "D": "Yağış dayandı, günəş çıxdı.", "E": "Qar yağırdı külək əsirdi, yollar buz bağlamışdı."}'::jsonb, 'D', NULL, 'Düzgün: «Yağış dayandı, günəş çıxdı.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2553, 34, 'g9-aze-punct-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Atam işdən qayıdıb nahar etdi.", "B": "Müəllim dedi, ki sabah imtahan olacaq.", "C": "Atam qəzet və jurnal oxuyur.", "D": "Biz yay tətilində dənizə getdik.", "E": "Müəllim dedi ki, sabah imtahan olacaq."}'::jsonb, 'E', NULL, 'Düzgün: «Müəllim dedi ki, sabah imtahan olacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2554, 34, 'g9-aze-punct-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Sınan oyuncağı atam düzəltdi.", "B": "Ah, mən açarı evdə unutmuşam!", "C": "Erkən yatdım ki, səhər tez durum.", "D": "Atam işdən gec qayıtdı.", "E": "Elə bir kitab oxudum ki onu heç unutmaram."}'::jsonb, 'C', NULL, 'Düzgün: «Erkən yatdım ki, səhər tez durum.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2555, 34, 'g9-aze-punct-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Dərsə gecikdim çünki, avtobus gəlmədi.", "B": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq.", "C": "Hərçənd yorğun idi o işini bitirdi.", "D": "Kim çalışsa, o qalib gələr.", "E": "Erkən yatdım, ki səhər tez durum."}'::jsonb, 'B', NULL, 'Düzgün: «Əgər yağış yağsa, gəzintiyə çıxmayacağıq.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2556, 34, 'g9-aze-punct-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var?', NULL, NULL, '{"A": "Nə qar, nə də yağış yağdı.", "B": "Oxuyan uşaq başını kitabdan qaldırdı.", "C": "Atam işdən gec qayıtdı.", "D": "Neçə şagird yarışa qatıldı?", "E": "Ey dostlar, bura gəlin!"}'::jsonb, 'E', NULL, 'Düzgün: «Ey dostlar, bura gəlin!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2557, 34, 'g9-aze-punct-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf ki, qatar vaxtında gəlmədi.", "B": "Doğrudan da bu film maraqlıdır.", "C": "Neçə şagird yarışa qatıldı.", "D": "Mən, dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "E": "Mən çay, və peçenye aldım."}'::jsonb, 'A', NULL, 'Düzgün: «Təəssüf ki, qatar vaxtında gəlmədi.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; sual cümləsinin sonunda nöqtə qoyulub; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2558, 34, 'g9-aze-punct-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Müəllim dedi ki sabah imtahan olacaq.", "B": "Dərsə gecikdim çünki, avtobus gəlmədi.", "C": "Elə ki yaz gəldi, quşlar geri qayıtdı.", "D": "Məqsədim budur, ki həkim olum.", "E": "Kim çalışsa o qalib gələr."}'::jsonb, 'C', NULL, 'Düzgün: «Elə ki yaz gəldi, quşlar geri qayıtdı.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2559, 34, 'g9-aze-punct-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Yağış yağanda uşaqlar evə qaçdılar.", "B": "Sınan oyuncağı atam düzəltdi.", "C": "Doğrudan da, bu film maraqlıdır.", "D": "Ey dostlar, bura gəlin!", "E": "Afərin, sən bütün tapmacaları tapdın!"}'::jsonb, 'C', NULL, 'Düzgün: «Doğrudan da, bu film maraqlıdır.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2560, 34, 'g9-aze-punct-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bağçada qızılgüllər, lalələr, və nərgizlər açmışdı.", "B": "Hərçənd yorğun idi o işini bitirdi.", "C": "Əlbəttə sən bu kitabı oxumalısan.", "D": "Deməli, siz sabah Bakıya gedirsiniz.", "E": "Təəssüf, ki qatar vaxtında gəlmədi."}'::jsonb, 'D', NULL, 'Düzgün: «Deməli, siz sabah Bakıya gedirsiniz.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2561, 34, 'g9-aze-punct-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Uşaqlar ucadan güldülər.", "B": "Nə qar nə də yağış yağdı.", "C": "Bağçada qırmızı və sarı güllər açmışdı.", "D": "Kim çalışsa, o, qalib gələr.", "E": "Biz axşama qədər oynadıq."}'::jsonb, 'C', NULL, 'Düzgün: «Bağçada qırmızı və sarı güllər açmışdı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2562, 34, 'g9-aze-punct-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim çalışsa, o, qalib gələr.", "B": "Erkən yatdım, ki səhər tez durum.", "C": "Aydındır ki bu iş asan deyil.", "D": "Çalışsan uğur qazanarsan.", "E": "Hərçənd yorğun idi o işini bitirdi."}'::jsonb, 'A', NULL, 'Düzgün: «Kim çalışsa, o, qalib gələr.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2563, 34, 'g9-aze-punct-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Sən ya çay ya da şirə iç.", "B": "Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.", "C": "O quş kimi oxuyur.", "D": "Bağçada qızılgüllər, lalələr, və nərgizlər açmışdı.", "E": "Hətta kiçik, uşaqlar bu mahnını bilirdi."}'::jsonb, 'B', NULL, 'Düzgün: «Biz əvvəlcə dərsimizi oxuduq, sonra oynadıq.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2564, 34, 'g9-aze-punct-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hava, soyudu, amma biz gəzintiyə çıxdıq.", "B": "Ay uşaqlar dərhal sinfə qayıdın!", "C": "Kim çalışsa o qalib gələr.", "D": "Aydındır, ki bu iş asan deyil.", "E": "Vay, stəkan sındı!"}'::jsonb, 'E', NULL, 'Düzgün: «Vay, stəkan sındı!». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2565, 34, 'g9-aze-punct-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Yağış yağsa da biz yola çıxdıq.", "B": "Kim çalışsa o qalib gələr.", "C": "Elə ki yaz gəldi quşlar geri qayıtdı.", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Elə bir kitab oxudum, ki onu heç unutmaram."}'::jsonb, 'D', NULL, 'Düzgün: «Erkən yatdım ki, səhər tez durum.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2566, 34, 'g9-aze-punct-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Doğrudan da bu film maraqlıdır.", "B": "Əlbəttə, sən bu kitabı oxumalısan.", "C": "Təəssüf, ki qatar vaxtında gəlmədi.", "D": "Kim çalışsa o qalib gələr.", "E": "Bağçada qızılgüllər, lalələr, və nərgizlər açmışdı."}'::jsonb, 'B', NULL, 'Düzgün: «Əlbəttə, sən bu kitabı oxumalısan.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (2567, 34, 'g9-aze-punct-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Məqsədim budur ki həkim olum.", "B": "Hərçənd yorğun idi o işini bitirdi.", "C": "Harada bulaq var orada həyat var.", "D": "Elə bir kitab oxudum, ki onu heç unutmaram.", "E": "Nə qədər çox oxusan, o qədər çox bilərsən."}'::jsonb, 'E', NULL, 'Düzgün: «Nə qədər çox oxusan, o qədər çox bilərsən.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2568, 34, 'g9-aze-punct-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Vay, stəkan sındı!", "B": "Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.", "C": "Mən, dərsimi hazırladım, qardaşım isə rəsm çəkdi.", "D": "O, kitabı rəfə qoydu.", "E": "Harada bulaq var, orada həyat var."}'::jsonb, 'B', NULL, 'Düzgün: «Qar yağırdı, külək əsirdi, yollar buz bağlamışdı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2569, 34, 'g9-aze-punct-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Kim bu məktubu yazıb?", "B": "O kitabı rəfə qoy.", "C": "Təəssüf ki, qatar vaxtında gəlmədi.", "D": "Əhsən, siz bu yarışı uddunuz!", "E": "Bəs siz sabah gəlmirsiniz?"}'::jsonb, 'C', NULL, 'Düzgün: «Təəssüf ki, qatar vaxtında gəlmədi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2570, 34, 'g9-aze-punct-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də mübtəda «o» və ya «bu» əvəzliyi ilə ifadə olunub?', NULL, NULL, '{"A": "Bəs siz sabah gəlmirsiniz?", "B": "Mən çay və peçenye aldım.", "C": "Aydındır ki, bu iş asan deyil.", "D": "O, dostu ilə parkda gəzirdi.", "E": "Qardaşım və bacım kinoya getdilər."}'::jsonb, 'D', NULL, 'Düzgün: «O, dostu ilə parkda gəzirdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2571, 34, 'g9-aze-punct-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Qız gülə-gülə otağa girdi.", "B": "Müəllim dedi, ki sabah imtahan olacaq.", "C": "Müəllim dedi ki, sabah imtahan olacaq.", "D": "Biz dənizə doğru irəlilədik.", "E": "Anam bazardan beş alma aldı."}'::jsonb, 'C', NULL, 'Düzgün: «Müəllim dedi ki, sabah imtahan olacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2572, 34, 'g9-aze-punct-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Dərsə gecikdim çünki, avtobus gəlmədi.", "B": "Məqsədim budur ki, həkim olum.", "C": "Kim çalışsa o qalib gələr.", "D": "Elə ki yaz gəldi quşlar geri qayıtdı.", "E": "Elə bir kitab oxudum, ki onu heç unutmaram."}'::jsonb, 'B', NULL, 'Düzgün: «Məqsədim budur ki, həkim olum.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (2573, 34, 'g9-aze-punct-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Erkən yatdım ki səhər tez durum.", "B": "Müəllim dedi, ki sabah imtahan olacaq.", "C": "Müəllim dedi ki, sabah imtahan olacaq.", "D": "Əgər yağış yağsa gəzintiyə çıxmayacağıq.", "E": "Atam işdən qayıdıb nahar etdi."}'::jsonb, 'C', NULL, 'Düzgün: «Müəllim dedi ki, sabah imtahan olacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2574, 34, 'g9-aze-punct-q3-24', 3, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Dərsə gecikdim çünki, avtobus gəlmədi.", "B": "Erkən yatdım, ki səhər tez durum.", "C": "Əli ilə Vəli bu məktəbdə oxuyurlar.", "D": "Uşaqlar yuxarı qalxdılar.", "E": "Əgər yağış yağsa, gəzintiyə çıxmayacağıq."}'::jsonb, 'E', NULL, 'Düzgün: «Əgər yağış yağsa, gəzintiyə çıxmayacağıq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2575, 34, 'g9-aze-punct-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Ancaq sən mənə inanırsan.", "B": "Nə qar, nə də yağış yağdı.", "C": "Yəqin, qonaqlar yorulublar.", "D": "Erkən yatdım ki, səhər tez durum.", "E": "Yeddinci sinfin şagirdləri muzeyə getdilər."}'::jsonb, 'B', NULL, 'Düzgün: «Nə qar, nə də yağış yağdı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2576, 34, 'g9-aze-punct-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Sən ya çay, ya da şirə iç.", "B": "Babam bizə iki quzu bağışladı.", "C": "Heç kim bu tapmacanı tapmadı.", "D": "O, evə gəldi və dərslərini hazırladı.", "E": "Hərçənd yorğun idi, o, işini bitirdi."}'::jsonb, 'A', NULL, 'Düzgün: «Sən ya çay, ya da şirə iç.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2577, 34, 'g9-aze-punct-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Həm atam gəldi, həm də anam zəng etdi.", "B": "Qar, yağırdı, külək əsirdi, yollar buz bağlamışdı.", "C": "Bilirəm, ki sən düz deyirsən.", "D": "Mən dərsimi hazırladım qardaşım isə rəsm çəkdi.", "E": "Müəllim, lövhəyə iki misal yazdı."}'::jsonb, 'A', NULL, 'Düzgün: «Həm atam gəldi, həm də anam zəng etdi.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2578, 34, 'g9-aze-punct-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də mübtəda «o» və ya «bu» əvəzliyi ilə ifadə olunub?', NULL, NULL, '{"A": "Əhsən, siz bu yarışı uddunuz!", "B": "O, kitabı rəfə qoydu.", "C": "Çalışsan, uğur qazanarsan.", "D": "Həm atam gəldi, həm də anam zəng etdi.", "E": "Üçüncü cərgədə iki boş yer qalmışdı."}'::jsonb, 'B', NULL, 'Düzgün: «O, kitabı rəfə qoydu.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (2579, 34, 'g9-aze-punct-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Of, mən yoruldum.", "B": "Afərin sən bütün tapmacaları tapdın!", "C": "Bəlkə biz sabah dənizə gedək.", "D": "Kim çalışsa o qalib gələr.", "E": "Yağış, dayandı, günəş çıxdı."}'::jsonb, 'A', NULL, 'Düzgün: «Of, mən yoruldum.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; vergül buraxılıb.');
INSERT INTO public.questions VALUES (2580, 34, 'g9-aze-punct-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hərçənd yorğun idi, o işini bitirdi.", "B": "Erkən yatdım, ki səhər tez durum.", "C": "Elə bir kitab oxudum ki onu heç unutmaram.", "D": "Harada bulaq var, orada həyat var.", "E": "Kim çalışsa o qalib gələr."}'::jsonb, 'D', NULL, 'Düzgün: «Harada bulaq var, orada həyat var.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (2581, 35, 'g9-eng-tense-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We cook dinner when the lights suddenly went out.", "B": "My brother paints the fence three times since January.", "C": "Every Sunday the students had watched a documentary; it is a family tradition.", "D": "Look! The students clean the kitchen right now.", "E": "My brother watched a documentary two days ago."}'::jsonb, 'E', NULL, 'Correct: «My brother watched a documentary two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
