INSERT INTO public.questions VALUES (2654, 35, 'g9-eng-tense-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She ___ (translate) the article two days ago. (2) Every Sunday I ___ (read) the report; it is a family tradition.', NULL, NULL, '{"A": "translated / was reading", "B": "translates / read", "C": "translated / had read", "D": "translated / read", "E": "translated / will have read"}'::jsonb, 'D', NULL, '(1) translated — Past Simple: «ago» ilə (2) read — Present Simple: müntəzəm adət (Every Sunday … it is a tradition)');
INSERT INTO public.questions VALUES (2655, 35, 'g9-eng-tense-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They ___ (paint) the fence three times since January. (2) Our neighbours ___ (write) a long letter two days ago.', NULL, NULL, '{"A": "have painted / have written", "B": "have painted / wrote", "C": "have painted / write", "D": "painted / wrote", "E": "have painted / will write"}'::jsonb, 'B', NULL, '(1) have painted — Present Perfect: «since» + təkrar sayı (2) wrote — Past Simple: «ago» ilə');
INSERT INTO public.questions VALUES (2656, 35, 'g9-eng-tense-q3-16', 3, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Look! She cooked dinner right now.", "B": "By the time we arrived, they had already wash the dishes.", "C": "Our neighbours have finished the project three times since January.", "D": "We will teach the younger kids two days ago.", "E": "Every Sunday he had washed the dishes; it is a family tradition."}'::jsonb, 'C', NULL, 'Correct: «Our neighbours have finished the project three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2657, 35, 'g9-eng-tense-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She will be teaching the younger kids when the lights suddenly went out.", "B": "Every Sunday our neighbours had read the report; it is a family tradition.", "C": "My brother was cleaning the kitchen when the lights suddenly went out.", "D": "By the time we arrived, they had already teach the younger kids.", "E": "We will teach the younger kids two days ago."}'::jsonb, 'C', NULL, 'Correct: «My brother was cleaning the kitchen when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2658, 35, 'g9-eng-tense-q3-18', 3, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, she had already ___ (design) a poster. (2) Look! We ___ (translate) the article right now.', NULL, NULL, '{"A": "design / are translating", "B": "designed / translated", "C": "designed / translate", "D": "designed / are translating", "E": "designed / have translated"}'::jsonb, 'D', NULL, '(1) designed — Past Perfect: had + V3 (2) are translating — Present Continuous: «right now», «Look!»');
INSERT INTO public.questions VALUES (2659, 35, 'g9-eng-tense-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, they had already ___ (buy) a new laptop. (2) They ___ (study) for the exam two days ago.', NULL, NULL, '{"A": "bought / study", "B": "bought / studied", "C": "buying / studied", "D": "bought / have studied", "E": "bought / will study"}'::jsonb, 'B', NULL, '(1) bought — Past Perfect: had + V3 (2) studied — Past Simple: «ago» ilə');
INSERT INTO public.questions VALUES (2660, 35, 'g9-eng-tense-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every Sunday my brother will have studied for the exam; it is a family tradition.", "B": "She watches a documentary when the lights suddenly went out.", "C": "I will clean the kitchen two days ago.", "D": "Look! They are watching a documentary right now.", "E": "They design a poster two days ago."}'::jsonb, 'D', NULL, 'Correct: «Look! They are watching a documentary right now.» — Present Continuous: «right now», «Look!». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2661, 35, 'g9-eng-tense-q3-21', 3, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I will call you as soon as I to design a poster.", "B": "Every Sunday he was buying a new laptop; it is a family tradition.", "C": "By the time we arrived, I had already washing the dishes.", "D": "My brother has repaired the old bike two days ago.", "E": "She watched a documentary two days ago."}'::jsonb, 'E', NULL, 'Correct: «She watched a documentary two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2662, 35, 'g9-eng-tense-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Our neighbours bought a new laptop three times since January.", "B": "They were painting the fence when the lights suddenly went out.", "C": "I will call you as soon as I will clean the kitchen.", "D": "Look! I wash the dishes right now.", "E": "He is reading the report when the lights suddenly went out."}'::jsonb, 'B', NULL, 'Correct: «They were painting the fence when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2663, 35, 'g9-eng-tense-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They wash the dishes when the lights suddenly went out.", "B": "Every Sunday I was cleaning the kitchen; it is a family tradition.", "C": "Our neighbours are reading the report three times since January.", "D": "My brother will be visiting the museum when the lights suddenly went out.", "E": "Every Sunday we plant trees in the garden; it is a family tradition."}'::jsonb, 'E', NULL, 'Correct: «Every Sunday we plant trees in the garden; it is a family tradition.» — Present Simple: müntəzəm adət (Every Sunday … it is a tradition). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2664, 35, 'g9-eng-tense-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The students ___ (finish) the project two days ago. (2) He ___ (clean) the kitchen three times since January.', NULL, NULL, '{"A": "will finish / has cleaned", "B": "finished / cleans", "C": "finished / has cleaned", "D": "finished / is cleaning", "E": "have finished / has cleaned"}'::jsonb, 'C', NULL, '(1) finished — Past Simple: «ago» ilə (2) has cleaned — Present Perfect: «since» + təkrar sayı');
INSERT INTO public.questions VALUES (2665, 35, 'g9-eng-tense-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every Sunday the students will have cooked dinner; it is a family tradition.", "B": "By the time we arrived, he had already finish the project.", "C": "Look! My brother finished the project right now.", "D": "Look! My brother is repairing the old bike right now.", "E": "He is translating the article when the lights suddenly went out."}'::jsonb, 'D', NULL, 'Correct: «Look! My brother is repairing the old bike right now.» — Present Continuous: «right now», «Look!». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2666, 35, 'g9-eng-tense-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Look! She ___ (write) a long letter right now. (2) I ___ (paint) the fence two days ago.', NULL, NULL, '{"A": "is writing / have painted", "B": "wrote / painted", "C": "has written / painted", "D": "is writing / paint", "E": "is writing / painted"}'::jsonb, 'E', NULL, '(1) is writing — Present Continuous: «right now», «Look!» (2) painted — Past Simple: «ago» ilə');
INSERT INTO public.questions VALUES (2667, 35, 'g9-eng-tense-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, he had already designing a poster.", "B": "We were cooking dinner when the lights suddenly went out.", "C": "Every Sunday they were studying for the exam; it is a family tradition.", "D": "She will be studying for the exam when the lights suddenly went out.", "E": "Every Sunday we were cooking dinner; it is a family tradition."}'::jsonb, 'B', NULL, 'Correct: «We were cooking dinner when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2668, 35, 'g9-eng-tense-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The students ___ (cook) dinner when the lights suddenly went out. (2) Look! He ___ (teach) the younger kids right now.', NULL, NULL, '{"A": "were cooking / is teaching", "B": "have cooked / is teaching", "C": "were cooking / has taught", "D": "will be cooking / is teaching", "E": "cook / is teaching"}'::jsonb, 'A', NULL, '(1) were cooking — Past Continuous: kəsilən proses (2) is teaching — Present Continuous: «right now», «Look!»');
INSERT INTO public.questions VALUES (2669, 35, 'g9-eng-tense-q3-29', 3, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My brother has cleaned the kitchen three times since January.", "B": "Every Sunday my brother had bought a new laptop; it is a family tradition.", "C": "We write a long letter when the lights suddenly went out.", "D": "The students are repairing the old bike three times since January.", "E": "They will repair the old bike two days ago."}'::jsonb, 'A', NULL, 'Correct: «My brother has cleaned the kitchen three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2670, 35, 'g9-eng-tense-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Every Sunday the students ___ (cook) dinner; it is a family tradition. (2) Look! The students ___ (clean) the kitchen right now.', NULL, NULL, '{"A": "were cooking / are cleaning", "B": "cook / clean", "C": "had cooked / are cleaning", "D": "will have cooked / are cleaning", "E": "cook / are cleaning"}'::jsonb, 'E', NULL, '(1) cook — Present Simple: müntəzəm adət (Every Sunday … it is a tradition) (2) are cleaning — Present Continuous: «right now», «Look!»');
INSERT INTO public.questions VALUES (2671, 36, 'g9-eng-cond-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she had practised every day, she ___ (win) the competition. (2) I wish I ___ taller. (be)', NULL, NULL, '{"A": "will win / were", "B": "would have won / were", "C": "will have won / were", "D": "would have won / being", "E": "would have won / am"}'::jsonb, 'B', NULL, '(1) would have won — III tip şərt: If + Past Perfect, would have + V3 (2) were — wish + were (bütün şəxslərdə)');
INSERT INTO public.questions VALUES (2672, 36, 'g9-eng-cond-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If they ___ (save) enough money, they will buy a new house. (2) If you heat ice, it ___.', NULL, NULL, '{"A": "save / melts", "B": "save / will melted", "C": "save / is melt", "D": "save / melting", "E": "saved / melts"}'::jsonb, 'A', NULL, '(1) save — I tip şərt: If + Present Simple, will + V1 (2) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple');
INSERT INTO public.questions VALUES (2673, 36, 'g9-eng-cond-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If they ___ (save) enough money, they will buy a new house. (2) If she had practised every day, she ___ (win) the competition.', NULL, NULL, '{"A": "save / will have won", "B": "will save / would have won", "C": "had saved / would have won", "D": "save / would have won", "E": "save / had won"}'::jsonb, 'D', NULL, '(1) save — I tip şərt: If + Present Simple, will + V1 (2) would have won — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (2674, 36, 'g9-eng-cond-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If they save enough money, they will buy a new house.", "B": "If he will check the figures, he will find the mistake.", "C": "Unless I would have more time, I won''t visit my grandparents.", "D": "If she practised every day, she will win the competition.", "E": "If he had checked the figures, he will have found the mistake."}'::jsonb, 'A', NULL, 'Correct: «If they save enough money, they will buy a new house.» — I tip şərt: If + Present Simple, will + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2675, 36, 'g9-eng-cond-q1-05', 1, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he had checked the figures, he had found the mistake.", "B": "Unless they will save enough money, they won''t buy a new house.", "C": "If you will study harder, you would pass the exam.", "D": "I wish I knew the answer to this question.", "E": "If I had had more time, I will visit my grandparents."}'::jsonb, 'D', NULL, 'Correct: «I wish I knew the answer to this question.» — wish + Past Simple: indiki vəziyyətə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2676, 36, 'g9-eng-cond-q1-06', 1, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If plants don''t get water, they dies.", "B": "If we had left now, we had caught the train.", "C": "If they saved enough money, they would buy a new house.", "D": "If we will leave now, we would catch the train.", "E": "If you mix red and blue, you got to purple."}'::jsonb, 'C', NULL, 'Correct: «If they saved enough money, they would buy a new house.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2677, 36, 'g9-eng-cond-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she had practised every day, she ___ (win) the competition. (2) If they had saved enough money, they ___ (buy) a new house.', NULL, NULL, '{"A": "would have won / would have bought", "B": "would have won / had bought", "C": "will have won / would have bought", "D": "had won / would have bought", "E": "would have won / will buy"}'::jsonb, 'A', NULL, '(1) would have won — III tip şərt: If + Past Perfect, would have + V3 (2) would have bought — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (2678, 36, 'g9-eng-cond-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you had studied harder, you will pass the exam.", "B": "If I had had more time, I will visit my grandparents.", "C": "I wish I knew the answer to this question.", "D": "If he had checked the figures, he will find the mistake.", "E": "Unless they will save enough money, they won''t buy a new house."}'::jsonb, 'C', NULL, 'Correct: «I wish I knew the answer to this question.» — wish + Past Simple: indiki vəziyyətə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2679, 36, 'g9-eng-cond-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I ___ (have) more time, I would visit my grandparents. (2) If I had had more time, I ___ (visit) my grandparents.', NULL, NULL, '{"A": "will have / would have visited", "B": "had / would have visited", "C": "have / would have visited", "D": "had / will visit", "E": "had / had visited"}'::jsonb, 'B', NULL, '(1) had — II tip şərt: If + Past Simple, would + V1 (2) would have visited — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (2680, 36, 'g9-eng-cond-q1-10', 1, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If we had left now, we ___ (catch) the train. (2) Unless he ___ (check) the figures, he won''t find the mistake.', NULL, NULL, '{"A": "will catch / checks", "B": "would have caught / checks", "C": "will have caught / checks", "D": "would have caught / will check", "E": "would have caught / won''t check"}'::jsonb, 'B', NULL, '(1) would have caught — III tip şərt: If + Past Perfect, would have + V3 (2) checks — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (2681, 36, 'g9-eng-cond-q1-11', 1, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish I ___ the answer to this question. (know) (2) If they had saved enough money, they ___ (buy) a new house.', NULL, NULL, '{"A": "knew / would have bought", "B": "knew / will buy", "C": "know / would have bought", "D": "will know / would have bought", "E": "knew / had bought"}'::jsonb, 'A', NULL, '(1) knew — wish + Past Simple: indiki vəziyyətə təəssüf (2) would have bought — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (2682, 36, 'g9-eng-cond-q1-12', 1, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless she ___ (practise) every day, she won''t win the competition. (2) Unless we ___ (leave) now, we won''t catch the train.', NULL, NULL, '{"A": "practises / leave", "B": "won''t practise / leave", "C": "will practise / leave", "D": "practises / would leave", "E": "would practise / leave"}'::jsonb, 'A', NULL, '(1) practises — Unless = if not; zaman/şərt hissəsində Present Simple (2) leave — Unless = if not; zaman/şərt hissəsində Present Simple');
