INSERT INTO public.questions VALUES (2684, 36, 'g9-eng-cond-q1-14', 1, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If they ___ (save) enough money, they would buy a new house. (2) If water reaches 100°C, it ___.', NULL, NULL, '{"A": "will save / boils", "B": "have saved / boils", "C": "saved / boil", "D": "saved / boils", "E": "saved / is boil"}'::jsonb, 'D', NULL, '(1) saved — II tip şərt: If + Past Simple, would + V1 (2) boils — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple');
INSERT INTO public.questions VALUES (2685, 36, 'g9-eng-cond-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she ___ (practise) every day, she will win the competition. (2) If he had checked the figures, he ___ (find) the mistake.', NULL, NULL, '{"A": "practises / will find", "B": "practises / would have found", "C": "will practise / would have found", "D": "practises / will have found", "E": "practised / would have found"}'::jsonb, 'B', NULL, '(1) practises — I tip şərt: If + Present Simple, will + V1 (2) would have found — III tip şərt: If + Past Perfect, would have + V3');
