INSERT INTO public.questions VALUES (2687, 36, 'g9-eng-cond-q1-17', 1, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I had had more time, I would have visited my grandparents.", "B": "If they had saved enough money, they had bought a new house.", "C": "If you mix red and blue, you gets purple.", "D": "If plants don''t get water, they dying.", "E": "Unless you will study harder, you won''t pass the exam."}'::jsonb, 'A', NULL, 'Correct: «If I had had more time, I would have visited my grandparents.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
