INSERT INTO public.questions VALUES (2689, 36, 'g9-eng-cond-q1-19', 1, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he has checked the figures, he would find the mistake.", "B": "If he checked the figures, he will find the mistake.", "C": "If I will have more time, I would visit my grandparents.", "D": "If they saved enough money, they would buy a new house.", "E": "If you studied harder, you will pass the exam."}'::jsonb, 'D', NULL, 'Correct: «If they saved enough money, they would buy a new house.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2690, 36, 'g9-eng-cond-q1-20', 1, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you studied harder, you will pass the exam.", "B": "Unless you study harder, you won''t pass the exam.", "C": "If I will have more time, I would visit my grandparents.", "D": "I wish I knowing the answer to this question.", "E": "If I had had more time, I will visit my grandparents."}'::jsonb, 'B', NULL, 'Correct: «Unless you study harder, you won''t pass the exam.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2691, 36, 'g9-eng-cond-q1-21', 1, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I had had more time, I ___ (visit) my grandparents. (2) If I ___ (have) more time, I will visit my grandparents.', NULL, NULL, '{"A": "had visited / have", "B": "would have visited / have", "C": "will visit / have", "D": "would have visited / will have", "E": "would have visited / had had"}'::jsonb, 'B', NULL, '(1) would have visited — III tip şərt: If + Past Perfect, would have + V3 (2) have — I tip şərt: If + Present Simple, will + V1');
