INSERT INTO public.questions VALUES (2693, 36, 'g9-eng-cond-q1-23', 1, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If we ___ (leave) now, we will catch the train. (2) If she ___ (practise) every day, she will win the competition.', NULL, NULL, '{"A": "leave / practised", "B": "left / practises", "C": "will leave / practises", "D": "had left / practises", "E": "leave / practises"}'::jsonb, 'E', NULL, '(1) leave — I tip şərt: If + Present Simple, will + V1 (2) practises — I tip şərt: If + Present Simple, will + V1');
INSERT INTO public.questions VALUES (2694, 36, 'g9-eng-cond-q1-24', 1, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I wish I will be taller.", "B": "If she had practised every day, she would have won the competition.", "C": "If water reaches 100°C, it boil.", "D": "If they had saved enough money, they will buy a new house.", "E": "If you had studied harder, you will have passed the exam."}'::jsonb, 'B', NULL, 'Correct: «If she had practised every day, she would have won the competition.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2695, 36, 'g9-eng-cond-q1-25', 1, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If we have left now, we would catch the train.", "B": "If she practised every day, she will win the competition.", "C": "If they had saved enough money, they will have bought a new house.", "D": "Unless he checks the figures, he won''t find the mistake.", "E": "If he had checked the figures, he will have found the mistake."}'::jsonb, 'D', NULL, 'Correct: «Unless he checks the figures, he won''t find the mistake.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2696, 36, 'g9-eng-cond-q1-26', 1, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you study harder, you would pass the exam.", "B": "If water reaches 100°C, it boils.", "C": "Unless you won''t study harder, you won''t pass the exam.", "D": "If we left now, we will catch the train.", "E": "If I had had more time, I had visited my grandparents."}'::jsonb, 'B', NULL, 'Correct: «If water reaches 100°C, it boils.» — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2697, 36, 'g9-eng-cond-q1-27', 1, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I wish I being taller.", "B": "If water reaches 100°C, it is boil.", "C": "If they will save enough money, they will buy a new house.", "D": "If they saved enough money, they would buy a new house.", "E": "If we have left now, we would catch the train."}'::jsonb, 'D', NULL, 'Correct: «If they saved enough money, they would buy a new house.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2698, 36, 'g9-eng-cond-q1-28', 1, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish I ___ taller. (be) (2) If I had had more time, I ___ (visit) my grandparents.', NULL, NULL, '{"A": "being / would have visited", "B": "will be / would have visited", "C": "were / would have visited", "D": "were / will have visited", "E": "am / would have visited"}'::jsonb, 'C', NULL, '(1) were — wish + were (bütün şəxslərdə) (2) would have visited — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (2699, 36, 'g9-eng-cond-q1-29', 1, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless you will study harder, you won''t pass the exam.", "B": "Unless he will check the figures, he won''t find the mistake.", "C": "I wish I knowing the answer to this question.", "D": "If we will leave now, we will catch the train.", "E": "If she practises every day, she will win the competition."}'::jsonb, 'E', NULL, 'Correct: «If she practises every day, she will win the competition.» — I tip şərt: If + Present Simple, will + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2700, 36, 'g9-eng-cond-q1-30', 1, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I had had more time, I ___ (visit) my grandparents. (2) I wish I ___ the answer to this question. (know)', NULL, NULL, '{"A": "would have visited / knew", "B": "would have visited / know", "C": "will visit / knew", "D": "will have visited / knew", "E": "would have visited / knowing"}'::jsonb, 'A', NULL, '(1) would have visited — III tip şərt: If + Past Perfect, would have + V3 (2) knew — wish + Past Simple: indiki vəziyyətə təəssüf');
INSERT INTO public.questions VALUES (2701, 36, 'g9-eng-cond-q2-01', 2, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If they had saved enough money, they will have bought a new house.", "B": "I wish I knew the answer to this question.", "C": "Unless she will practise every day, she won''t win the competition.", "D": "If you mix red and blue, you got to purple.", "E": "If she practises every day, she would win the competition."}'::jsonb, 'B', NULL, 'Correct: «I wish I knew the answer to this question.» — wish + Past Simple: indiki vəziyyətə təəssüf. The other sentences each contain an error.');
