INSERT INTO public.questions VALUES (2853, 38, 'g9-eng-article-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Netherlands is famous for its tulips. (2) He became ___ engineer after graduating.', NULL, NULL, '{"A": "The / —", "B": "The / a", "C": "— / an", "D": "The / an", "E": "A / an"}'::jsonb, 'D', NULL, '(1) The — Cəm formalı ölkə adları ilə the (2) an — Peşə bildirəndə: an engineer');
INSERT INTO public.questions VALUES (2854, 38, 'g9-eng-article-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) We have ___ breakfast at seven. (2) He was born in ___ 1990s.', NULL, NULL, '{"A": "an / the", "B": "a / the", "C": "— / —", "D": "— / the", "E": "— / a"}'::jsonb, 'D', NULL, '(1) — — Yemək adları ilə (breakfast, lunch) artikl işlənmir (2) the — Onilliklər: in the 1990s');
INSERT INTO public.questions VALUES (2855, 38, 'g9-eng-article-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) What ___ beautiful day it is! (2) He was born in ___ 1990s.', NULL, NULL, '{"A": "— / the", "B": "a / the", "C": "the / the", "D": "a / —", "E": "a / a"}'::jsonb, 'B', NULL, '(1) a — What a + saylan tək isim (nida) (2) the — Onilliklər: in the 1990s');
