INSERT INTO public.questions VALUES (2857, 38, 'g9-eng-article-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He became ___ engineer after graduating. (2) What ___ beautiful day it is!', NULL, NULL, '{"A": "— / a", "B": "an / a", "C": "a / a", "D": "an / —", "E": "an / the"}'::jsonb, 'B', NULL, '(1) an — Peşə bildirəndə: an engineer (2) a — What a + saylan tək isim (nida)');
INSERT INTO public.questions VALUES (2858, 38, 'g9-eng-article-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ history is my favourite subject. (2) I visit my grandparents twice ___ month.', NULL, NULL, '{"A": "A / a", "B": "— / a", "C": "— / —", "D": "The / a", "E": "— / the"}'::jsonb, 'B', NULL, '(1) — — Fənn adları ümumi mənada artiklsiz (2) a — twice a month — «hər» mənasında a');
