INSERT INTO public.questions VALUES (2918, 38, 'g9-eng-article-q3-08', 3, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) Germany is ___ European country. (2) She is ___ only person who knows the truth.', NULL, NULL, '{"A": "a / the", "B": "an / the", "C": "a / an", "D": "a / a", "E": "an / a"}'::jsonb, 'A', NULL, '(1) a — «European» [ju] səsi ilə başlayır → a (2) the — «only» ilə the');
INSERT INTO public.questions VALUES (2919, 38, 'g9-eng-article-q3-09', 3, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) This is ___ most interesting book I have ever read. (2) I bought ___ one-way ticket.', NULL, NULL, '{"A": "an / a", "B": "the / a", "C": "— / an", "D": "— / a", "E": "the / an"}'::jsonb, 'B', NULL, '(1) the — Üstünlük dərəcəsi ilə the (2) a — «one» [w] səsi ilə başlayır → a');
INSERT INTO public.questions VALUES (2920, 38, 'g9-eng-article-q3-10', 3, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) They climbed ___ Alps last summer. (2) ___ Mount Everest is the highest mountain in the world.', NULL, NULL, '{"A": "the / A", "B": "— / —", "C": "the / The", "D": "an / —", "E": "the / —"}'::jsonb, 'E', NULL, '(1) the — Dağ silsilələri ilə the (2) — — Tək dağ adları ilə artikl işlənmir');
INSERT INTO public.questions VALUES (2921, 38, 'g9-eng-article-q3-11', 3, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She goes to an bed at ten o''clock.", "B": "She is a only person who knows the truth.", "C": "We waited for an hour.", "D": "We have an breakfast at seven.", "E": "They play the football every Saturday."}'::jsonb, 'C', NULL, 'Correct: «We waited for an hour.» — «hour»da h oxunmur → an. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2922, 38, 'g9-eng-article-q3-12', 3, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Rich should help the poor.", "B": "The sun rises in the east.", "C": "We sailed across Pacific Ocean.", "D": "My cousin lives in the Azerbaijan.", "E": "She is a honest person."}'::jsonb, 'B', NULL, 'Correct: «The sun rises in the east.» — Yeganə obyektlər: the sun, the moon. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2923, 38, 'g9-eng-article-q3-13', 3, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She is a honest person.", "B": "Mount Everest is the highest mountain in the world.", "C": "They play the football every Saturday.", "D": "My cousin lives in the Azerbaijan.", "E": "He became a engineer after graduating."}'::jsonb, 'B', NULL, 'Correct: «Mount Everest is the highest mountain in the world.» — Tək dağ adları ilə artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2924, 38, 'g9-eng-article-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ English language has many irregular verbs. (2) ___ Nile is the longest river in Africa.', NULL, NULL, '{"A": "The / The", "B": "The / —", "C": "— / The", "D": "The / A", "E": "An / The"}'::jsonb, 'A', NULL, '(1) The — «the English language» — language sözü ilə the (2) The — Çay adları ilə the');
INSERT INTO public.questions VALUES (2925, 38, 'g9-eng-article-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) We waited for ___ hour. (2) He speaks ___ English fluently.', NULL, NULL, '{"A": "an / —", "B": "an / the", "C": "a / —", "D": "a / the", "E": "an / an"}'::jsonb, 'A', NULL, '(1) an — «hour»da h oxunmur → an (2) — — Dil adları ilə artikl işlənmir');
INSERT INTO public.questions VALUES (2926, 38, 'g9-eng-article-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) She is ___ only person who knows the truth. (2) This is ___ most interesting book I have ever read.', NULL, NULL, '{"A": "the / the", "B": "a / the", "C": "an / the", "D": "the / an", "E": "the / —"}'::jsonb, 'A', NULL, '(1) the — «only» ilə the (2) the — Üstünlük dərəcəsi ilə the');
INSERT INTO public.questions VALUES (2927, 38, 'g9-eng-article-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The Nile is the longest river in Africa.", "B": "My cousin lives in an Azerbaijan.", "C": "He was born in a 1990s.", "D": "He works at an university in Baku.", "E": "What the beautiful day it is!"}'::jsonb, 'A', NULL, 'Correct: «The Nile is the longest river in Africa.» — Çay adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2928, 38, 'g9-eng-article-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We sailed across Pacific Ocean.", "B": "Sun rises in the east.", "C": "Netherlands is famous for its tulips.", "D": "I''d like a glass of water, please.", "E": "Nile is the longest river in Africa."}'::jsonb, 'D', NULL, 'Correct: «I''d like a glass of water, please.» — Saylan tək isimlə ilk dəfə: a. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2929, 38, 'g9-eng-article-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) She lives in ___ United Kingdom. (2) ___ history is my favourite subject.', NULL, NULL, '{"A": "— / —", "B": "a / —", "C": "the / A", "D": "the / —", "E": "the / The"}'::jsonb, 'D', NULL, '(1) the — «Kingdom, States, Republic» olan ölkə adları ilə the (2) — — Fənn adları ümumi mənada artiklsiz');
INSERT INTO public.questions VALUES (2930, 38, 'g9-eng-article-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The Caspian Sea is the largest lake in the world.", "B": "He speaks an English fluently.", "C": "Sun rises in the east.", "D": "Germany is an European country.", "E": "We went there by a bus."}'::jsonb, 'A', NULL, 'Correct: «The Caspian Sea is the largest lake in the world.» — Dəniz adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2931, 38, 'g9-eng-article-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) It was ___ unusual decision. (2) ___ sun rises in the east.', NULL, NULL, '{"A": "an / The", "B": "an / A", "C": "a / The", "D": "an / —", "E": "a / A"}'::jsonb, 'A', NULL, '(1) an — «unusual» sait səsi ilə başlayır → an (2) The — Yeganə obyektlər: the sun, the moon');
INSERT INTO public.questions VALUES (2932, 38, 'g9-eng-article-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This is an most interesting book I have ever read.", "B": "What the beautiful day it is!", "C": "He was born in a 1990s.", "D": "English language has many irregular verbs.", "E": "The Caspian Sea is the largest lake in the world."}'::jsonb, 'E', NULL, 'Correct: «The Caspian Sea is the largest lake in the world.» — Dəniz adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2933, 38, 'g9-eng-article-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Nile is the longest river in Africa. (2) We have ___ breakfast at seven.', NULL, NULL, '{"A": "The / an", "B": "The / a", "C": "A / —", "D": "The / —", "E": "— / —"}'::jsonb, 'D', NULL, '(1) The — Çay adları ilə the (2) — — Yemək adları ilə (breakfast, lunch) artikl işlənmir');
INSERT INTO public.questions VALUES (2934, 38, 'g9-eng-article-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) This is ___ most interesting book I have ever read. (2) They climbed ___ Alps last summer.', NULL, NULL, '{"A": "— / the", "B": "an / the", "C": "the / —", "D": "the / the", "E": "the / an"}'::jsonb, 'D', NULL, '(1) the — Üstünlük dərəcəsi ilə the (2) the — Dağ silsilələri ilə the');
INSERT INTO public.questions VALUES (2935, 38, 'g9-eng-article-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) This is ___ most interesting book I have ever read. (2) I''d like ___ glass of water, please.', NULL, NULL, '{"A": "the / an", "B": "the / a", "C": "an / a", "D": "the / —", "E": "— / a"}'::jsonb, 'B', NULL, '(1) the — Üstünlük dərəcəsi ilə the (2) a — Saylan tək isimlə ilk dəfə: a');
INSERT INTO public.questions VALUES (2936, 38, 'g9-eng-article-q3-26', 3, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They play a football every Saturday.", "B": "It was a unusual decision.", "C": "She lives in United Kingdom.", "D": "We sailed across the Pacific Ocean.", "E": "Germany is an European country."}'::jsonb, 'D', NULL, 'Correct: «We sailed across the Pacific Ocean.» — Okean adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2937, 38, 'g9-eng-article-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I''d like an glass of water, please.", "B": "He works at a university in Baku.", "C": "She lives in United Kingdom.", "D": "The history is my favourite subject.", "E": "They play the football every Saturday."}'::jsonb, 'B', NULL, 'Correct: «He works at a university in Baku.» — «university» [ju] səsi ilə başlayır → a. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2938, 38, 'g9-eng-article-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ sun rises in the east. (2) He works at ___ university in Baku.', NULL, NULL, '{"A": "The / a", "B": "— / an", "C": "A / a", "D": "— / a", "E": "The / an"}'::jsonb, 'A', NULL, '(1) The — Yeganə obyektlər: the sun, the moon (2) a — «university» [ju] səsi ilə başlayır → a');
INSERT INTO public.questions VALUES (2939, 38, 'g9-eng-article-q3-29', 3, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We went there by a bus.", "B": "He works at an university in Baku.", "C": "They play the football every Saturday.", "D": "He was born in the 1990s.", "E": "I bought an one-way ticket."}'::jsonb, 'D', NULL, 'Correct: «He was born in the 1990s.» — Onilliklər: in the 1990s. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2940, 38, 'g9-eng-article-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He works at a university in Baku.", "B": "We went there by a bus.", "C": "A Mount Everest is the highest mountain in the world.", "D": "She is a honest person.", "E": "I bought an one-way ticket."}'::jsonb, 'A', NULL, 'Correct: «He works at a university in Baku.» — «university» [ju] səsi ilə başlayır → a. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2941, 39, 'g9-eng-quant-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How much students are there in your class?", "B": "Either the children enjoyed the trip.", "C": "She gave me many useful advice.", "D": "We had several problems with the new software.", "E": "There isn''t a few milk left in the fridge."}'::jsonb, 'D', NULL, 'Correct: «We had several problems with the new software.» — several + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2942, 39, 'g9-eng-quant-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There are ___ apples in the basket. (2) ___ child needs love and attention.', NULL, NULL, '{"A": "some / All", "B": "some / Every", "C": "much / Every", "D": "a little / Every", "E": "some / Both"}'::jsonb, 'B', NULL, '(1) some — Təsdiq cümləsində some (2) Every — every + tək isim');
INSERT INTO public.questions VALUES (2943, 39, 'g9-eng-quant-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ the children enjoyed the trip. (2) I''ve got ___ homework to do tonight.', NULL, NULL, '{"A": "All / several", "B": "Each / a lot of", "C": "Either / a lot of", "D": "All / a lot of", "E": "Every / a lot of"}'::jsonb, 'D', NULL, '(1) All — all (of) the + cəm (2) a lot of — homework saylanmayandır → a lot of / much');
INSERT INTO public.questions VALUES (2944, 39, 'g9-eng-quant-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She gave me an useful advice.", "B": "We had much problems with the new software.", "C": "Only much students came to the lecture, so it was cancelled.", "D": "It was such a long journey that we were exhausted.", "E": "There are a little apples in the basket."}'::jsonb, 'D', NULL, 'Correct: «It was such a long journey that we were exhausted.» — such + (a) + sifət + isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2945, 39, 'g9-eng-quant-q1-05', 1, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Are there any questions?", "B": "I''ve got a few homework to do tonight.", "C": "There isn''t a few milk left in the fridge.", "D": "She has little friends, so she often feels lonely.", "E": "I don''t have few information about this topic."}'::jsonb, 'A', NULL, 'Correct: «Are there any questions?» — Sual cümləsində any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2946, 39, 'g9-eng-quant-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Are there ___ questions? (2) I have ___ money, so I can buy you a coffee.', NULL, NULL, '{"A": "any / a few", "B": "any / a little", "C": "any / many", "D": "a little / a little", "E": "a few of / a little"}'::jsonb, 'B', NULL, '(1) any — Sual cümləsində any (2) a little — a little + saylanmayan (müsbət məna: bir az var)');
INSERT INTO public.questions VALUES (2947, 39, 'g9-eng-quant-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We had a great deal problems with the new software.", "B": "We bought some furniture for the new flat.", "C": "She gave me a few useful advice.", "D": "We have a few time; we must hurry.", "E": "Both of the cakes is mine; take the other one."}'::jsonb, 'B', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2948, 39, 'g9-eng-quant-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) It was ___ a long journey that we were exhausted.', NULL, NULL, '{"A": "How much / too", "B": "How much / so", "C": "How many / such", "D": "How much / such", "E": "How a lot / such"}'::jsonb, 'D', NULL, '(1) How much — luggage saylanmayandır → how much (2) such — such + (a) + sifət + isim');
INSERT INTO public.questions VALUES (2949, 39, 'g9-eng-quant-q1-09', 1, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "All of the cakes is mine; take the other one.", "B": "You can take all road; both lead to the city centre.", "C": "I''ve got a lot of homework to do tonight.", "D": "I have many money, so I can buy you a coffee.", "E": "We had a little problems with the new software."}'::jsonb, 'C', NULL, 'Correct: «I''ve got a lot of homework to do tonight.» — homework saylanmayandır → a lot of / much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2950, 39, 'g9-eng-quant-q1-10', 1, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) She gave me ___ useful advice. (2) I don''t have ___ information about this topic.', NULL, NULL, '{"A": "some / a few", "B": "some / many", "C": "some / few", "D": "a few / much", "E": "some / much"}'::jsonb, 'E', NULL, '(1) some — advice saylanmayandır → some advice (2) much — information saylanmayandır → much');
INSERT INTO public.questions VALUES (2951, 39, 'g9-eng-quant-q1-11', 1, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She gave me an useful advice.", "B": "Every child needs love and attention.", "C": "You can take all road; both lead to the city centre.", "D": "She has little friends, so she often feels lonely.", "E": "Each the children enjoyed the trip."}'::jsonb, 'B', NULL, 'Correct: «Every child needs love and attention.» — every + tək isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2952, 39, 'g9-eng-quant-q1-12', 1, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) You can take ___ road; both lead to the city centre. (2) She has ___ friends, so she often feels lonely.', NULL, NULL, '{"A": "either / a little", "B": "either / few", "C": "both / few", "D": "all / few", "E": "either / little"}'::jsonb, 'B', NULL, '(1) either — either + tək isim: ikisindən hər hansı biri (2) few — few + saylan (mənfi məna: az, demək olar ki, yox)');
INSERT INTO public.questions VALUES (2953, 39, 'g9-eng-quant-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was very a long journey that we were exhausted.", "B": "Only much students came to the lecture, so it was cancelled.", "C": "I don''t have many information about this topic.", "D": "You can take all road; both lead to the city centre.", "E": "How much luggage do you have?"}'::jsonb, 'E', NULL, 'Correct: «How much luggage do you have?» — luggage saylanmayandır → how much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2954, 39, 'g9-eng-quant-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every of my parents are doctors.", "B": "I don''t have much information about this topic.", "C": "All child needs love and attention.", "D": "She has much friends, so she often feels lonely.", "E": "There isn''t many milk left in the fridge."}'::jsonb, 'B', NULL, 'Correct: «I don''t have much information about this topic.» — information saylanmayandır → much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2955, 39, 'g9-eng-quant-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There isn''t ___ milk left in the fridge. (2) ___ student in the class received a certificate.', NULL, NULL, '{"A": "much / Both", "B": "much / Many", "C": "much / Each", "D": "a few / Each", "E": "much / All"}'::jsonb, 'C', NULL, '(1) much — much + saylanmayan isim (inkarda) (2) Each — each/every + saylan tək isim');
INSERT INTO public.questions VALUES (2956, 39, 'g9-eng-quant-q1-16', 1, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I have ___ money, so I can buy you a coffee. (2) You can take ___ road; both lead to the city centre.', NULL, NULL, '{"A": "few / either", "B": "a few / either", "C": "many / either", "D": "a little / all", "E": "a little / either"}'::jsonb, 'E', NULL, '(1) a little — a little + saylanmayan (müsbət məna: bir az var) (2) either — either + tək isim: ikisindən hər hansı biri');
INSERT INTO public.questions VALUES (2957, 39, 'g9-eng-quant-q1-17', 1, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ student in the class received a certificate. (2) We bought ___ furniture for the new flat.', NULL, NULL, '{"A": "Each / several", "B": "Each / many", "C": "Each / a few", "D": "All / some", "E": "Each / some"}'::jsonb, 'E', NULL, '(1) Each — each/every + saylan tək isim (2) some — furniture saylanmayandır → some');
INSERT INTO public.questions VALUES (2958, 39, 'g9-eng-quant-q1-18', 1, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every child needs love and attention.", "B": "Each the children enjoyed the trip.", "C": "You can take both road; both lead to the city centre.", "D": "All student in the class received a certificate.", "E": "There are a little apples in the basket."}'::jsonb, 'A', NULL, 'Correct: «Every child needs love and attention.» — every + tək isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2959, 39, 'g9-eng-quant-q1-19', 1, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She has a little friends, so she often feels lonely.", "B": "All the children enjoyed the trip.", "C": "How a lot luggage do you have?", "D": "How little students are there in your class?", "E": "Many student in the class received a certificate."}'::jsonb, 'B', NULL, 'Correct: «All the children enjoyed the trip.» — all (of) the + cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2960, 39, 'g9-eng-quant-q1-20', 1, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Each student in the class received a certificate.", "B": "Both child needs love and attention.", "C": "How many luggage do you have?", "D": "Are there much questions?", "E": "Some of the cakes is mine; take the other one."}'::jsonb, 'A', NULL, 'Correct: «Each student in the class received a certificate.» — each/every + saylan tək isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2961, 39, 'g9-eng-quant-q1-21', 1, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) We bought ___ furniture for the new flat. (2) I don''t have ___ information about this topic.', NULL, NULL, '{"A": "many / much", "B": "some / a few", "C": "some / many", "D": "a few / much", "E": "some / much"}'::jsonb, 'E', NULL, '(1) some — furniture saylanmayandır → some (2) much — information saylanmayandır → much');
INSERT INTO public.questions VALUES (2962, 39, 'g9-eng-quant-q1-22', 1, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought a few furniture for the new flat.", "B": "There are much apples in the basket.", "C": "Are there any questions?", "D": "How few luggage do you have?", "E": "Much of my parents are doctors."}'::jsonb, 'C', NULL, 'Correct: «Are there any questions?» — Sual cümləsində any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (2963, 39, 'g9-eng-quant-q1-23', 1, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) It was ___ a long journey that we were exhausted. (2) There are ___ apples in the basket.', NULL, NULL, '{"A": "such / a little", "B": "such / much", "C": "such / some", "D": "such / any", "E": "so / some"}'::jsonb, 'C', NULL, '(1) such — such + (a) + sifət + isim (2) some — Təsdiq cümləsində some');
INSERT INTO public.questions VALUES (2964, 39, 'g9-eng-quant-q1-24', 1, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How many luggage do you have?", "B": "Much of my parents are doctors.", "C": "Are there much questions?", "D": "One of the cakes is mine; take the other one.", "E": "Many student in the class received a certificate."}'::jsonb, 'D', NULL, 'Correct: «One of the cakes is mine; take the other one.» — one of + cəm isim + tək feil. The other sentences each contain an error.');
