INSERT INTO public.questions VALUES (3011, 39, 'g9-eng-quant-q3-11', 3, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Are there a little questions?", "B": "She gave me many useful advice.", "C": "We had a great deal problems with the new software.", "D": "It was very a long journey that we were exhausted.", "E": "Only a few students came to the lecture, so it was cancelled."}'::jsonb, 'E', NULL, 'Correct: «Only a few students came to the lecture, so it was cancelled.» — only a few + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3012, 39, 'g9-eng-quant-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "How many / One", "B": "How a lot / One", "C": "How much / One", "D": "How few / One", "E": "How much / Some"}'::jsonb, 'C', NULL, '(1) How much — luggage saylanmayandır → how much (2) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (3013, 39, 'g9-eng-quant-q3-13', 3, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I don''t have ___ information about this topic. (2) We had ___ problems with the new software.', NULL, NULL, '{"A": "much / a little", "B": "many / several", "C": "much / several", "D": "a few / several", "E": "few / several"}'::jsonb, 'C', NULL, '(1) much — information saylanmayandır → much (2) several — several + saylan cəm');
