INSERT INTO public.questions VALUES (3015, 39, 'g9-eng-quant-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Either the children enjoyed the trip.", "B": "How little students are there in your class?", "C": "Many student in the class received a certificate.", "D": "Every child needs love and attention.", "E": "There are a little apples in the basket."}'::jsonb, 'D', NULL, 'Correct: «Every child needs love and attention.» — every + tək isim. The other sentences each contain an error.');
