INSERT INTO public.questions VALUES (3017, 39, 'g9-eng-quant-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) How ___ students are there in your class? (2) We bought ___ furniture for the new flat.', NULL, NULL, '{"A": "much / some", "B": "a little / some", "C": "many / many", "D": "many / some", "E": "many / a few"}'::jsonb, 'D', NULL, '(1) many — many + saylan cəm isim (2) some — furniture saylanmayandır → some');
