INSERT INTO public.questions VALUES (3019, 39, 'g9-eng-quant-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Only a little students came to the lecture, so it was cancelled.", "B": "You can take all road; both lead to the city centre.", "C": "She has a little friends, so she often feels lonely.", "D": "She gave me an useful advice.", "E": "We bought some furniture for the new flat."}'::jsonb, 'E', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
