INSERT INTO public.questions VALUES (3021, 39, 'g9-eng-quant-q3-21', 3, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every child needs love and attention.", "B": "Both student in the class received a certificate.", "C": "Some of the cakes is mine; take the other one.", "D": "Each the children enjoyed the trip.", "E": "We bought several furniture for the new flat."}'::jsonb, 'A', NULL, 'Correct: «Every child needs love and attention.» — every + tək isim. The other sentences each contain an error.');
