INSERT INTO public.questions VALUES (3108, 40, 'g9-eng-noun-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I bought two loaf of bread.", "B": "There were three womens in the picture.", "C": "My parents'' car is very old.", "D": "There were three leavs in the picture.", "E": "We need new a furniture for the office."}'::jsonb, 'C', NULL, 'Correct: «My parents'' car is very old.» — Cəm -s ilə: parents''. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3109, 40, 'g9-eng-noun-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (goose) in the picture. (2) The news ___ shocking.', NULL, NULL, '{"A": "geeses / was", "B": "geese / was", "C": "gooses / was", "D": "geese / were", "E": "geese / have been"}'::jsonb, 'B', NULL, '(1) geese — goose → geese (2) was — news + tək feil');
