INSERT INTO public.questions VALUES (3114, 40, 'g9-eng-noun-q3-24', 3, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The scissors has been on the table.", "B": "Mathematics are my favourite subject.", "C": "There were three feets in the picture.", "D": "The news on TV was very bad today.", "E": "There were three childs in the picture."}'::jsonb, 'D', NULL, 'Correct: «The news on TV was very bad today.» — news tək sayılır (the news was). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3115, 40, 'g9-eng-noun-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) These are the ___ toys. (children) (2) Our ___ was lost at the airport.', NULL, NULL, '{"A": "children''s / a luggage", "B": "childrens'' / luggage", "C": "children''s / luggage''s", "D": "children''s / luggage", "E": "children'' / luggage"}'::jsonb, 'D', NULL, '(1) children''s — Qeyri-adi cəmdə yiyəlik: children''s (2) luggage — luggage saylanmayandır');
