INSERT INTO public.questions VALUES (3125, 41, 'g9-eng-adj-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This test is ___ (difficult) than the last one. (2) This book is ___ (thin) than that one.', NULL, NULL, '{"A": "more difficult / thinner", "B": "difficulter / thinner", "C": "more difficulter / thinner", "D": "most difficult / thinner", "E": "more difficult / more thin"}'::jsonb, 'A', NULL, '(1) more difficult — Müqayisə dərəcəsi: difficult → more difficult (2) thinner — Müqayisə dərəcəsi: thin → thinner');
