INSERT INTO public.questions VALUES (3151, 41, 'g9-eng-adj-q2-01', 2, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He isn''t old ___ to drive. (2) They live in a ___ house.', NULL, NULL, '{"A": "too / lovely old stone", "B": "enough / lovely stone old", "C": "very / lovely old stone", "D": "enough / stone lovely old", "E": "enough / lovely old stone"}'::jsonb, 'E', NULL, '(1) enough — sifət + enough (2) lovely old stone — Sifət sırası: rəy – yaş – material');
INSERT INTO public.questions VALUES (3152, 41, 'g9-eng-adj-q2-02', 2, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (modern) office in the area. (2) My sister looks ___ (happy) than before.', NULL, NULL, '{"A": "most modern / happyer", "B": "more modern / happier", "C": "most modern / more happier", "D": "modernest / happier", "E": "most modern / happier"}'::jsonb, 'E', NULL, '(1) most modern — Üstünlük dərəcəsi: modern → the most modern (2) happier — Müqayisə dərəcəsi: happy → happier');
INSERT INTO public.questions VALUES (3153, 41, 'g9-eng-adj-q2-03', 2, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) We were ___ by the news. (2) He is the ___ (careful) driver I know.', NULL, NULL, '{"A": "shocked / most carefullest", "B": "shocked / more careful", "C": "shock / most careful", "D": "shocked / most careful", "E": "shocked / carefulest"}'::jsonb, 'D', NULL, '(1) shocked — -ed: hiss (be shocked by) (2) most careful — Üstünlük dərəcəsi: careful → the most careful');
INSERT INTO public.questions VALUES (3154, 41, 'g9-eng-adj-q2-04', 2, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This test is ___ (difficult) than the last one. (2) It is the ___ (thin) book on the shelf.', NULL, NULL, '{"A": "most difficult / thinnest", "B": "more difficult / most thin", "C": "more difficult / thinnest", "D": "more difficult / thinest", "E": "difficulter / thinnest"}'::jsonb, 'C', NULL, '(1) more difficult — Müqayisə dərəcəsi: difficult → more difficult (2) thinnest — Üstünlük dərəcəsi: thin → the thinnest');
INSERT INTO public.questions VALUES (3155, 41, 'g9-eng-adj-q2-05', 2, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the dryest month of the year.", "B": "It was the difficultest question in the exam.", "C": "They live in a lovely old stone house.", "D": "It is the busier street in the city.", "E": "The film was so boringly that I fell asleep."}'::jsonb, 'C', NULL, 'Correct: «They live in a lovely old stone house.» — Sifət sırası: rəy – yaş – material. The other sentences each contain an error.');
