INSERT INTO public.questions VALUES (3162, 41, 'g9-eng-adj-q2-12', 2, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) My sister looks ___ (happy) than before. (2) He isn''t old ___ to drive.', NULL, NULL, '{"A": "happier / too", "B": "happier / so", "C": "happyer / enough", "D": "happier / very", "E": "happier / enough"}'::jsonb, 'E', NULL, '(1) happier — Müqayisə dərəcəsi: happy → happier (2) enough — sifət + enough');
INSERT INTO public.questions VALUES (3163, 41, 'g9-eng-adj-q2-13', 2, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the baddest storm in ten years.", "B": "It was the difficultest question in the exam.", "C": "Leyla is carefuler than her brother.", "D": "Their office is most modern than ours.", "E": "Your English is getting better and better."}'::jsonb, 'E', NULL, 'Correct: «Your English is getting better and better.» — Artan dəyişiklik: comparative and comparative. The other sentences each contain an error.');
