INSERT INTO public.questions VALUES (3166, 41, 'g9-eng-adj-q2-16', 2, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (good) plan we have. (2) He isn''t old ___ to drive.', NULL, NULL, '{"A": "best / enough", "B": "best / very", "C": "best / too", "D": "goodest / enough", "E": "better / enough"}'::jsonb, 'A', NULL, '(1) best — Üstünlük dərəcəsi: good → the best (2) enough — sifət + enough');
