INSERT INTO public.questions VALUES (3195, 41, 'g9-eng-adj-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (thin) book on the shelf. (2) The box was ___ heavy for me to carry.', NULL, NULL, '{"A": "most thin / too", "B": "thinnest / so much", "C": "thinnest / enough", "D": "thinner / too", "E": "thinnest / too"}'::jsonb, 'E', NULL, '(1) thinnest — Üstünlük dərəcəsi: thin → the thinnest (2) too — too + sifət + for + to-infinitive');
