INSERT INTO public.questions VALUES (3197, 41, 'g9-eng-adj-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their new flat is ___ (big) than the old one. (2) The weather today is ___ (bad) than yesterday.', NULL, NULL, '{"A": "bigger / worse", "B": "bigger / badder", "C": "biger / worse", "D": "bigger / more worse", "E": "bigger / worst"}'::jsonb, 'A', NULL, '(1) bigger — Müqayisə dərəcəsi: big → bigger (2) worse — Müqayisə dərəcəsi: bad → worse');
INSERT INTO public.questions VALUES (3198, 41, 'g9-eng-adj-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Their office is moderner than ours.", "B": "This summer was drier than last summer.", "C": "This plan is best than the first one.", "D": "She felt tiring after the long walk.", "E": "The box was so much heavy for me to carry."}'::jsonb, 'B', NULL, 'Correct: «This summer was drier than last summer.» — Müqayisə dərəcəsi: dry → drier. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3199, 41, 'g9-eng-adj-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She felt tire after the long walk.", "B": "Their office is more modern than ours.", "C": "This bag is not as expensive so that one.", "D": "He isn''t old too to drive.", "E": "They live in a old lovely stone house."}'::jsonb, 'B', NULL, 'Correct: «Their office is more modern than ours.» — Müqayisə dərəcəsi: modern → more modern. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3200, 41, 'g9-eng-adj-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They live in a lovely stone old house.", "B": "The weather today is more worse than yesterday.", "C": "It is getting harder to find a cheap flat in the city.", "D": "The film was so bore that I fell asleep.", "E": "It is the busyest street in the city."}'::jsonb, 'C', NULL, 'Correct: «It is getting harder to find a cheap flat in the city.» — hard → harder. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3201, 41, 'g9-eng-adj-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She felt ___ after the long walk. (2) This summer was ___ (dry) than last summer.', NULL, NULL, '{"A": "tiring / drier", "B": "tiredly / drier", "C": "tired / drier", "D": "tired / driest", "E": "tire / drier"}'::jsonb, 'C', NULL, '(1) tired — feel + sifət (-ed: hiss) (2) drier — Müqayisə dərəcəsi: dry → drier');
INSERT INTO public.questions VALUES (3202, 41, 'g9-eng-adj-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This street is busyer than ours.", "B": "He is the carefulest driver I know.", "C": "It is the most busier street in the city.", "D": "This book is more thin than that one.", "E": "It is the thinnest book on the shelf."}'::jsonb, 'E', NULL, 'Correct: «It is the thinnest book on the shelf.» — Üstünlük dərəcəsi: thin → the thinnest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3203, 41, 'g9-eng-adj-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is the busiest street in the city.", "B": "This plan is best than the first one.", "C": "She is the happyest girl in the class.", "D": "He has a black small Japanese car.", "E": "This street is more busier than ours."}'::jsonb, 'A', NULL, 'Correct: «It is the busiest street in the city.» — Üstünlük dərəcəsi: busy → the busiest. The other sentences each contain an error.');
