INSERT INTO public.questions VALUES (3205, 41, 'g9-eng-adj-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This summer was ___ (dry) than last summer. (2) This street is ___ (busy) than ours.', NULL, NULL, '{"A": "more drier / busier", "B": "dryier / busier", "C": "driest / busier", "D": "drier / more busier", "E": "drier / busier"}'::jsonb, 'E', NULL, '(1) drier — Müqayisə dərəcəsi: dry → drier (2) busier — Müqayisə dərəcəsi: busy → busier');
INSERT INTO public.questions VALUES (3206, 41, 'g9-eng-adj-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He has a ___ car. (2) Leyla is ___ (careful) than her brother.', NULL, NULL, '{"A": "small black Japanese / carefuler", "B": "small black Japanese / more careful", "C": "small Japanese black / more careful", "D": "black small Japanese / more careful", "E": "Japanese small black / more careful"}'::jsonb, 'B', NULL, '(1) small black Japanese — Sifət sırası: ölçü – rəng – mənşə (2) more careful — Müqayisə dərəcəsi: careful → more careful');
INSERT INTO public.questions VALUES (3207, 41, 'g9-eng-adj-q3-27', 3, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (busy) street in the city. (2) He isn''t old ___ to drive.', NULL, NULL, '{"A": "busier / enough", "B": "busiest / enough", "C": "most busier / enough", "D": "busiest / very", "E": "busiest / so"}'::jsonb, 'B', NULL, '(1) busiest — Üstünlük dərəcəsi: busy → the busiest (2) enough — sifət + enough');
