INSERT INTO public.questions VALUES (3736, 47, 'g9-eng-prep-q3-16', 3, 16, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "In my opinion, the film was too long.", "B": "The children were on danger, so the police acted quickly.", "C": "They accused him about stealing the money.", "D": "She insisted for paying for dinner.", "E": "He apologised of being late."}'::jsonb, 'A', NULL, 'Correct: «In my opinion, the film was too long.» — in my opinion. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3737, 47, 'g9-eng-prep-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He is good ___ solving difficult puzzles. (2) This road leads ___ the city centre.', NULL, NULL, '{"A": "at / at", "B": "on / to", "C": "about / to", "D": "of / to", "E": "at / to"}'::jsonb, 'E', NULL, '(1) at — good at + V-ing (2) to — lead to');
INSERT INTO public.questions VALUES (3738, 47, 'g9-eng-prep-q3-18', 3, 18, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "She is married on a doctor.", "B": "They accused him about stealing the money.", "C": "She was born in 5 May 2008.", "D": "He did it by his own, without any help.", "E": "I''m afraid of spiders."}'::jsonb, 'E', NULL, 'Correct: «I''m afraid of spiders.» — afraid of. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3739, 47, 'g9-eng-prep-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I''ll meet you ___ the weekend. (2) I broke the vase by accident, not ___ purpose.', NULL, NULL, '{"A": "of / on", "B": "to / on", "C": "at / on", "D": "in / on", "E": "at / with"}'::jsonb, 'C', NULL, '(1) at — at the weekend (BrE) (2) on — on purpose — qəsdən');
INSERT INTO public.questions VALUES (3740, 47, 'g9-eng-prep-q3-20', 3, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The lift is ___ of order, so we have to use the stairs. (2) She is very interested ___ ancient history.', NULL, NULL, '{"A": "off / in", "B": "without / in", "C": "under / in", "D": "out / in", "E": "out / on"}'::jsonb, 'D', NULL, '(1) out — out of order — xarab (2) in — interested in');
INSERT INTO public.questions VALUES (3741, 47, 'g9-eng-prep-q3-21', 3, 21, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "Mr Aliyev is on charge of the sales department.", "B": "This book is different with the one I read last year.", "C": "She was born at 5 May 2008.", "D": "The children were on danger, so the police acted quickly.", "E": "I have known her for ten years."}'::jsonb, 'E', NULL, 'Correct: «I have known her for ten years.» — for + müddət. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3742, 47, 'g9-eng-prep-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She is jealous ___ her sister''s success. (2) He was ___ a hurry and forgot his keys.', NULL, NULL, '{"A": "about / in", "B": "of / on", "C": "of / at", "D": "of / in", "E": "of / with"}'::jsonb, 'D', NULL, '(1) of — jealous of (2) in — in a hurry');
INSERT INTO public.questions VALUES (3743, 47, 'g9-eng-prep-q3-23', 3, 23, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He succeeded to finding a new job.", "B": "For my opinion, the film was too long.", "C": "Are you aware on the risks?", "D": "He did it on his own, without any help.", "E": "He has lived here at 2010."}'::jsonb, 'D', NULL, 'Correct: «He did it on his own, without any help.» — on his own — təkbaşına. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (3744, 47, 'g9-eng-prep-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I''m not keen ___ horror films. (2) They accused him ___ stealing the money.', NULL, NULL, '{"A": "of / of", "B": "with / of", "C": "on / of", "D": "on / with", "E": "on / about"}'::jsonb, 'C', NULL, '(1) on — keen on (2) of — accuse somebody of');
