INSERT INTO public.questions VALUES (3746, 47, 'g9-eng-prep-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She is jealous ___ her sister''s success. (2) She is very interested ___ ancient history.', NULL, NULL, '{"A": "of / on", "B": "of / at", "C": "on / in", "D": "of / in", "E": "about / in"}'::jsonb, 'D', NULL, '(1) of — jealous of (2) in — interested in');
