INSERT INTO public.questions VALUES (3749, 47, 'g9-eng-prep-q3-29', 3, 29, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "They accused him with stealing the money.", "B": "I know the poem by heart.", "C": "You have to book the tickets at advance.", "D": "The result depends from the weather.", "E": "This road leads for the city centre."}'::jsonb, 'B', NULL, 'Correct: «I know the poem by heart.» — by heart — əzbər. The other sentences each contain an error.');
