INSERT INTO public.questions VALUES (3831, 49, 'g10-num-real-q1-01', 1, 1, 'medium', 'single', '−√75 ≤ x < ∛438 bərabərsizliyini ödəyən neçə tam x ədədi var?', NULL, NULL, '{"A": "17", "B": "16", "C": "15", "D": "18", "E": "14"}'::jsonb, 'B', NULL, '√75 ≈ 8,66, deməli x ≥ −8. 7³ = 343 < 438, 8³ = 512 ≥ 438, deməli x ≤ 7. Tam ədədlər: −8, …, 7 — cəmi 16.');
INSERT INTO public.questions VALUES (3832, 49, 'g10-num-real-q1-02', 1, 2, 'hard', 'single', 'Sadələşdirin: (√26 + √21) / (√26 − √21)', NULL, NULL, '{"A": "47/5 + √546/5", "B": "47/5 + 2√546/5", "C": "47/5 − 2√546/5", "D": "5/47 + 2√546/47", "E": "1 + 2√546/5"}'::jsonb, 'B', NULL, 'Surəti və məxrəci (√26 + √21)-yə vurun: (26 + 21 + 2√546) / (26 − 21) = 47/5 + 2√546/5.');
INSERT INTO public.questions VALUES (3833, 49, 'g10-num-real-q1-03', 1, 3, 'hard', 'single', 'Sadələşdirin: (√26 + √5) / (√26 − √5)', NULL, NULL, '{"A": "21/31 + 2√130/31", "B": "31/21 + √130/21", "C": "31/21 + 2√130/21", "D": "1 + 2√130/21", "E": "31/21 − 2√130/21"}'::jsonb, 'C', NULL, 'Surəti və məxrəci (√26 + √5)-yə vurun: (26 + 5 + 2√130) / (26 − 5) = 31/21 + 2√130/21.');
INSERT INTO public.questions VALUES (3834, 49, 'g10-num-real-q1-04', 1, 4, 'medium', 'single', '−√61 ≤ x < ∛681 bərabərsizliyini ödəyən neçə tam x ədədi var?', NULL, NULL, '{"A": "17", "B": "18", "C": "16", "D": "15", "E": "14"}'::jsonb, 'C', NULL, '√61 ≈ 7,81, deməli x ≥ −7. 8³ = 512 < 681, 9³ = 729 ≥ 681, deməli x ≤ 8. Tam ədədlər: −7, …, 8 — cəmi 16.');
INSERT INTO public.questions VALUES (3835, 49, 'g10-num-real-q1-05', 1, 5, 'hard', 'single', 'x = 8 + √63 olarsa, x² + 1/x² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "258", "B": "254", "C": "255", "D": "256", "E": "252"}'::jsonb, 'B', NULL, '1/x = 8 − √63 (çünki 8² − 63 = 1), x + 1/x = 16. x² + 1/x² = 16² − 2 = 254.');
INSERT INTO public.questions VALUES (3836, 49, 'g10-num-real-q1-06', 1, 6, 'hard', 'single', 'Sadələşdirin: (√20 + √10) / (√20 − √10)', NULL, NULL, '{"A": "1/3 + 2√2/3", "B": "1 + 2√2", "C": "3 + 2√2", "D": "3 + √2", "E": "3 − 2√2"}'::jsonb, 'C', NULL, 'Surəti və məxrəci (√20 + √10)-yə vurun: (20 + 10 + 2√200) / (20 − 10) = 3 + 2√2.');
