INSERT INTO public.questions VALUES (3878, 49, 'g10-num-real-q3-08', 3, 8, 'medium', 'single', 'a = 2√2, b = 5√5, c = 4√7. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < a < b", "B": "a < b < c", "C": "c < b < a", "D": "a < c < b", "E": "b < a < c"}'::jsonb, 'D', NULL, 'Kvadratlarını müqayisə edin: a² = 4·2 = 8, b² = 25·5 = 125, c² = 16·7 = 112. Ardıcıllıq: a < c < b.');
INSERT INTO public.questions VALUES (3879, 49, 'g10-num-real-q3-09', 3, 9, 'hard', 'single', 'x = 4 + √15 olarsa, x² + 1/x² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "63", "B": "64", "C": "62", "D": "66", "E": "60"}'::jsonb, 'C', NULL, '1/x = 4 − √15 (çünki 4² − 15 = 1), x + 1/x = 8. x² + 1/x² = 8² − 2 = 62.');
INSERT INTO public.questions VALUES (3880, 49, 'g10-num-real-q3-10', 3, 10, 'hard', 'single', 'Hesablayın: 1/(√9 + √10) + 1/(√10 + √11) + … + 1/(√195 + √196)', NULL, NULL, '{"A": "12", "B": "187", "C": "17", "D": "11", "E": "10"}'::jsonb, 'D', NULL, '1/(√k + √(k+1)) = √(k+1) − √k. Cəm teleskopik olur: √196 − √9 = 11.');
INSERT INTO public.questions VALUES (3881, 49, 'g10-num-real-q3-11', 3, 11, 'hard', 'single', 'Sadələşdirin: (√19 + √14) / (√19 − √14)', NULL, NULL, '{"A": "5/33 + 2√266/33", "B": "33/5 + 2√266/5", "C": "33/5 − 2√266/5", "D": "33/5 + √266/5", "E": "1 + 2√266/5"}'::jsonb, 'B', NULL, 'Surəti və məxrəci (√19 + √14)-yə vurun: (19 + 14 + 2√266) / (19 − 14) = 33/5 + 2√266/5.');
INSERT INTO public.questions VALUES (3882, 49, 'g10-num-real-q3-12', 3, 12, 'medium', 'single', 'Hesablayın: √(27 + 8√11) + √(27 − 8√11)', NULL, NULL, '{"A": "2√11", "B": "8 + 2√11", "C": "8", "D": "4", "E": "9"}'::jsonb, 'C', NULL, '27 ± 8√11 = (4 ± √11)². √((m − √n)²) = |m − √n|. 4 > √11, deməli |4 − √11| = 4 − √11. Cəm: 2·4 = 8.');
INSERT INTO public.questions VALUES (3883, 49, 'g10-num-real-q3-13', 3, 13, 'hard', 'single', 'Hesablayın: 1/(√1 + √2) + 1/(√2 + √3) + … + 1/(√143 + √144)', NULL, NULL, '{"A": "13", "B": "10", "C": "12", "D": "11", "E": "143"}'::jsonb, 'D', NULL, '1/(√k + √(k+1)) = √(k+1) − √k. Cəm teleskopik olur: √144 − √1 = 11.');
INSERT INTO public.questions VALUES (3884, 49, 'g10-num-real-q3-14', 3, 14, 'medium', 'single', 'a = 6√7, b = 7√5, c = 4√6. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < b < a", "B": "a < c < b", "C": "b < c < a", "D": "c < a < b", "E": "a < b < c"}'::jsonb, 'A', NULL, 'Kvadratlarını müqayisə edin: a² = 36·7 = 252, b² = 49·5 = 245, c² = 16·6 = 96. Ardıcıllıq: c < b < a.');
INSERT INTO public.questions VALUES (3885, 49, 'g10-num-real-q3-15', 3, 15, 'medium', 'single', 'a = 2√6, b = 5√7, c = 3√3. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < b < a", "B": "b < c < a", "C": "a < b < c", "D": "a < c < b", "E": "b < a < c"}'::jsonb, 'D', NULL, 'Kvadratlarını müqayisə edin: a² = 4·6 = 24, b² = 25·7 = 175, c² = 9·3 = 27. Ardıcıllıq: a < c < b.');
INSERT INTO public.questions VALUES (3886, 49, 'g10-num-real-q3-16', 3, 16, 'hard', 'single', 'Hesablayın: 1/(√9 + √10) + 1/(√10 + √11) + … + 1/(√99 + √100)', NULL, NULL, '{"A": "6", "B": "91", "C": "13", "D": "7", "E": "8"}'::jsonb, 'D', NULL, '1/(√k + √(k+1)) = √(k+1) − √k. Cəm teleskopik olur: √100 − √9 = 7.');
INSERT INTO public.questions VALUES (3887, 49, 'g10-num-real-q3-17', 3, 17, 'medium', 'single', 'Hesablayın: √(49 + 8√33) + √(49 − 8√33)', NULL, NULL, '{"A": "8 + 2√33", "B": "8", "C": "2√34", "D": "√33", "E": "2√33"}'::jsonb, 'E', NULL, '49 ± 8√33 = (4 ± √33)². √((m − √n)²) = |m − √n|. 4 < √33, deməli |4 − √33| = √33 − 4. Cəm: 2√33.');
INSERT INTO public.questions VALUES (3888, 49, 'g10-num-real-q3-18', 3, 18, 'medium', 'single', '−√140 ≤ x < ∛118 bərabərsizliyini ödəyən neçə tam x ədədi var?', NULL, NULL, '{"A": "16", "B": "17", "C": "14", "D": "15", "E": "18"}'::jsonb, 'A', NULL, '√140 ≈ 11,83, deməli x ≥ −11. 4³ = 64 < 118, 5³ = 125 ≥ 118, deməli x ≤ 4. Tam ədədlər: −11, …, 4 — cəmi 16.');
INSERT INTO public.questions VALUES (3889, 49, 'g10-num-real-q3-19', 3, 19, 'medium', 'single', 'Hesablayın: √(37 + 6√28) + √(37 − 6√28)', NULL, NULL, '{"A": "4√7", "B": "2√7", "C": "6 + 2√28", "D": "6", "E": "2√29"}'::jsonb, 'A', NULL, '37 ± 6√28 = (3 ± √28)². √((m − √n)²) = |m − √n|. 3 < √28, deməli |3 − √28| = √28 − 3. Cəm: 2√28.');
INSERT INTO public.questions VALUES (3890, 49, 'g10-num-real-q3-20', 3, 20, 'hard', 'single', 'x = 3 + √8 olarsa, x² + 1/x² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "32", "B": "38", "C": "34", "D": "36", "E": "35"}'::jsonb, 'C', NULL, '1/x = 3 − √8 (çünki 3² − 8 = 1), x + 1/x = 6. x² + 1/x² = 6² − 2 = 34.');
INSERT INTO public.questions VALUES (3891, 50, 'g10-num-frac-q1-01', 1, 1, 'hard', 'single', 'Hovuzu birinci boru 3 saata, ikinci boru 6 saata doldurur, üçüncü boru isə dolu hovuzu 16 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "23/7", "B": "30/7", "C": "16/9", "D": "2", "E": "16/7"}'::jsonb, 'E', NULL, 'Saatlıq məhsuldarlıq: 1/3 + 1/6 − 1/16 = 7/16. Vaxt: 1 : 7/16 = 16/7 saat.');
INSERT INTO public.questions VALUES (3892, 50, 'g10-num-frac-q1-02', 1, 2, 'hard', 'single', 'x : y = 7 : 8 olarsa, (4x² − 2xy) / (2y² + 5xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−7/34", "B": "77/102", "C": "7/34", "D": "182/37", "E": "8/21"}'::jsonb, 'C', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 7/8: (4t² − 2t)/(2 + 5t) = (49/16 − 7/4)/(2 + 35/8) = 7/34.');
INSERT INTO public.questions VALUES (3893, 50, 'g10-num-frac-q1-03', 1, 3, 'hard', 'single', 'Hesablayın: 1/(1·5) + 1/(5·9) + … + 1/(37·41)', NULL, NULL, '{"A": "9/37", "B": "9/205", "C": "40/41", "D": "160/41", "E": "10/41"}'::jsonb, 'E', NULL, '1/(k(k+4)) = (1/k − 1/(k+4))/4. Cəm: (1/1 − 1/41)/4 = 10/41.');
INSERT INTO public.questions VALUES (3894, 50, 'g10-num-frac-q1-04', 1, 4, 'hard', 'single', 'x : y = 8 : 5 olarsa, (2x² − 6xy) / (5y² + 3xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "16/35", "B": "−19/44", "C": "80/29", "D": "368/245", "E": "−16/35"}'::jsonb, 'E', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 8/5: (2t² − 6t)/(5 + 3t) = (128/25 − 48/5)/(5 + 24/5) = −16/35.');
INSERT INTO public.questions VALUES (3895, 50, 'g10-num-frac-q1-05', 1, 5, 'hard', 'single', 'Şagird pulunun 1/4 hissəsini kitaba, qalanın 1/3 hissəsini dəftərə, yenə qalanın 1/8 hissəsini qələmə xərclədi. Ondan 70 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "160", "B": "176", "C": "240", "D": "280", "E": "144"}'::jsonb, 'A', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·3/4·2/3·7/8 = 70, x·7/16 = 70, x = 160.');
INSERT INTO public.questions VALUES (3896, 50, 'g10-num-frac-q1-06', 1, 6, 'hard', 'single', 'Hovuzu birinci boru 7 saata, ikinci boru 6 saata doldurur, üçüncü boru isə dolu hovuzu 14 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "31/5", "B": "26/5", "C": "21/8", "D": "21/5", "E": "42/13"}'::jsonb, 'D', NULL, 'Saatlıq məhsuldarlıq: 1/7 + 1/6 − 1/14 = 5/21. Vaxt: 1 : 5/21 = 21/5 saat.');
INSERT INTO public.questions VALUES (3897, 50, 'g10-num-frac-q1-07', 1, 7, 'hard', 'single', 'Hesablayın: 1/(5·9) + 1/(9·13) + … + 1/(73·77)', NULL, NULL, '{"A": "17/365", "B": "18/385", "C": "72/385", "D": "17/693", "E": "288/385"}'::jsonb, 'B', NULL, '1/(k(k+4)) = (1/k − 1/(k+4))/4. Cəm: (1/5 − 1/77)/4 = 18/385.');
INSERT INTO public.questions VALUES (3898, 50, 'g10-num-frac-q1-08', 1, 8, 'hard', 'single', 'Şagird pulunun 1/3 hissəsini kitaba, qalanın 1/3 hissəsini dəftərə, yenə qalanın 1/7 hissəsini qələmə xərclədi. Ondan 64 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "336", "B": "189", "C": "192", "D": "147", "E": "168"}'::jsonb, 'E', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·2/3·2/3·6/7 = 64, x·8/21 = 64, x = 168.');
INSERT INTO public.questions VALUES (3899, 50, 'g10-num-frac-q1-09', 1, 9, 'hard', 'single', 'Hovuzu birinci boru 15 saata, ikinci boru 3 saata doldurur, üçüncü boru isə dolu hovuzu 8 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "51/11", "B": "40/11", "C": "5/2", "D": "40/21", "E": "10"}'::jsonb, 'B', NULL, 'Saatlıq məhsuldarlıq: 1/15 + 1/3 − 1/8 = 11/40. Vaxt: 1 : 11/40 = 40/11 saat.');
INSERT INTO public.questions VALUES (3900, 50, 'g10-num-frac-q1-10', 1, 10, 'hard', 'single', 'Şagird pulunun 1/6 hissəsini kitaba, qalanın 1/4 hissəsini dəftərə, yenə qalanın 1/8 hissəsini qələmə xərclədi. Ondan 210 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "448", "B": "5040/11", "C": "1260", "D": "320", "E": "384"}'::jsonb, 'E', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·5/6·3/4·7/8 = 210, x·35/64 = 210, x = 384.');
INSERT INTO public.questions VALUES (3901, 50, 'g10-num-frac-q1-11', 1, 11, 'hard', 'single', 'Hesablayın: 1/(6·11) + 1/(11·16) + … + 1/(66·71)', NULL, NULL, '{"A": "65/426", "B": "325/426", "C": "13/426", "D": "12/781", "E": "1/33"}'::jsonb, 'C', NULL, '1/(k(k+5)) = (1/k − 1/(k+5))/5. Cəm: (1/6 − 1/71)/5 = 13/426.');
