INSERT INTO public.questions VALUES (3903, 50, 'g10-num-frac-q1-13', 1, 13, 'medium', 'single', 'Hesablayın: (1 3/8 − 0,075) : 0,25 + 8/9 · 2,7', NULL, NULL, '{"A": "26/53", "B": "38/5", "C": "411/25", "D": "41/5", "E": "109/40"}'::jsonb, 'B', NULL, '1 3/8 − 0,075 = 13/10; 13/10 : 0,25 = 26/5; 8/9 · 2,7 = 12/5. Cəm: 38/5. (Əvvəl vurma/bölmə, sonra toplama.)');
INSERT INTO public.questions VALUES (3904, 50, 'g10-num-frac-q1-14', 1, 14, 'hard', 'open', 'Hovuzu birinci boru 12 saata, ikinci boru 6 saata doldurur, üçüncü boru isə dolu hovuzu 7 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, NULL, NULL, '28/3', 'Saatlıq məhsuldarlıq: 1/12 + 1/6 − 1/7 = 3/28. Vaxt: 1 : 3/28 = 28/3 saat.');
