INSERT INTO public.questions VALUES (3907, 50, 'g10-num-frac-q1-17', 1, 17, 'medium', 'single', 'Hesablayın: (1 1/8 − 0,75) : 0,05 + 1/3 · 2,1', NULL, NULL, '{"A": "1/2", "B": "191/5", "C": "23/32", "D": "41/5", "E": "329/20"}'::jsonb, 'D', NULL, '1 1/8 − 0,75 = 3/8; 3/8 : 0,05 = 15/2; 1/3 · 2,1 = 7/10. Cəm: 41/5. (Əvvəl vurma/bölmə, sonra toplama.)');
INSERT INTO public.questions VALUES (3908, 50, 'g10-num-frac-q1-18', 1, 18, 'hard', 'single', 'Hesablayın: 1/(3·6) + 1/(6·9) + … + 1/(27·30)', NULL, NULL, '{"A": "9/10", "B": "8/81", "C": "2/45", "D": "3/10", "E": "1/10"}'::jsonb, 'E', NULL, '1/(k(k+3)) = (1/k − 1/(k+3))/3. Cəm: (1/3 − 1/30)/3 = 1/10.');
INSERT INTO public.questions VALUES (3909, 50, 'g10-num-frac-q1-19', 1, 19, 'hard', 'single', 'Şagird pulunun 1/4 hissəsini kitaba, qalanın 1/6 hissəsini dəftərə, yenə qalanın 1/8 hissəsini qələmə xərclədi. Ondan 140 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "256", "B": "320", "C": "3360/11", "D": "192", "E": "560"}'::jsonb, 'A', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·3/4·5/6·7/8 = 140, x·35/64 = 140, x = 256.');
INSERT INTO public.questions VALUES (3910, 50, 'g10-num-frac-q1-20', 1, 20, 'hard', 'single', 'x : y = 3 : 7 olarsa, (5x² − 2xy) / (2y² + xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "203/39", "B": "39/5", "C": "−3/119", "D": "87/119", "E": "3/119"}'::jsonb, 'E', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 3/7: (5t² − 2t)/(2 + 1t) = (45/49 − 6/7)/(2 + 3/7) = 3/119.');
INSERT INTO public.questions VALUES (3911, 50, 'g10-num-frac-q2-01', 2, 1, 'hard', 'single', 'Şagird pulunun 1/4 hissəsini kitaba, qalanın 1/4 hissəsini dəftərə, yenə qalanın 1/4 hissəsini qələmə xərclədi. Ondan 81 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "192", "B": "128", "C": "144", "D": "256", "E": "324"}'::jsonb, 'A', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·3/4·3/4·3/4 = 81, x·27/64 = 81, x = 192.');
INSERT INTO public.questions VALUES (3912, 50, 'g10-num-frac-q2-02', 2, 2, 'hard', 'single', 'Hovuzu birinci boru 4 saata, ikinci boru 6 saata doldurur, üçüncü boru isə dolu hovuzu 12 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "5", "B": "4", "C": "3", "D": "2", "E": "12/5"}'::jsonb, 'C', NULL, 'Saatlıq məhsuldarlıq: 1/4 + 1/6 − 1/12 = 1/3. Vaxt: 1 : 1/3 = 3 saat.');
INSERT INTO public.questions VALUES (3913, 50, 'g10-num-frac-q2-03', 2, 3, 'hard', 'single', 'Şagird pulunun 1/6 hissəsini kitaba, qalanın 1/4 hissəsini dəftərə, yenə qalanın 1/8 hissəsini qələmə xərclədi. Ondan 420 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "10080/11", "B": "832", "C": "768", "D": "2520", "E": "704"}'::jsonb, 'C', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·5/6·3/4·7/8 = 420, x·35/64 = 420, x = 768.');
INSERT INTO public.questions VALUES (3914, 50, 'g10-num-frac-q2-04', 2, 4, 'hard', 'single', 'Hesablayın: 1/(8·12) + 1/(12·16) + … + 1/(28·32)', NULL, NULL, '{"A": "3/128", "B": "5/384", "C": "5/224", "D": "3/8", "E": "3/32"}'::jsonb, 'A', NULL, '1/(k(k+4)) = (1/k − 1/(k+4))/4. Cəm: (1/8 − 1/32)/4 = 3/128.');
INSERT INTO public.questions VALUES (3915, 50, 'g10-num-frac-q2-05', 2, 5, 'hard', 'single', 'Hesablayın: 1/(7·9) + 1/(9·11) + … + 1/(25·27)', NULL, NULL, '{"A": "20/189", "B": "9/175", "C": "40/189", "D": "10/189", "E": "1/27"}'::jsonb, 'D', NULL, '1/(k(k+2)) = (1/k − 1/(k+2))/2. Cəm: (1/7 − 1/27)/2 = 10/189.');
