INSERT INTO public.questions VALUES (4007, 51, 'g10-num-pow-q3-17', 3, 17, 'hard', 'single', '2^34 · 5^18 · 3^6 ədədi neçə rəqəmlidir?', NULL, NULL, '{"A": "27", "B": "18", "C": "25", "D": "26", "E": "28"}'::jsonb, 'D', NULL, '2^18·5^18 = 10^18. Qalan vuruq: 47775744 (8 rəqəmli). Cəmi 18 + 8 = 26 rəqəm.');
INSERT INTO public.questions VALUES (4008, 51, 'g10-num-pow-q3-18', 3, 18, 'medium', 'single', 'Hesablayın: 32^(2/5) + 4^(−1/2) · 49^(2/2)', NULL, NULL, '{"A": "102", "B": "−41/2", "C": "441/2", "D": "57/2", "E": "393/98"}'::jsonb, 'D', NULL, '32^(2/5) = 4, 4^(−1/2) = 1/2, 49^(2/2) = 49. Nəticə: 4 + 1/2·49 = 57/2.');
INSERT INTO public.questions VALUES (4009, 51, 'g10-num-pow-q3-19', 3, 19, 'medium', 'single', 'Hesablayın: (2^10 · 6^3) / (3^2 · 4^7)', NULL, NULL, '{"A": "9/2", "B": "3", "C": "3/4", "D": "3/2", "E": "1/2"}'::jsonb, 'D', NULL, '6^3 = 2^3·3^3, 4^7 = 2^14. 2-nin üstü: 10 + 3 − 14 = −1; 3-ün üstü: 3 − 2 = 1. Nəticə: 3/2.');
INSERT INTO public.questions VALUES (4010, 51, 'g10-num-pow-q3-20', 3, 20, 'medium', 'single', 'Hesablayın: 64^(3/3) + 216^(−2/3) · 49^(1/2)', NULL, NULL, '{"A": "316", "B": "16135/36", "C": "2311/36", "D": "16129/252", "E": "2297/36"}'::jsonb, 'C', NULL, '64^(3/3) = 64, 216^(−2/3) = 1/36, 49^(1/2) = 7. Nəticə: 64 + 1/36·7 = 2311/36.');
INSERT INTO public.questions VALUES (4011, 52, 'g10-num-abs-q1-01', 1, 1, 'hard', 'single', '|x − 7| = −3x + 4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "3/2", "B": "−5/2", "C": "5/4", "D": "−3/2", "E": "−1/2"}'::jsonb, 'D', NULL, 'x ≥ 7: x − 7 = −3x + 4; x < 7: −(x − 7) = −3x + 4. Şərti ödəyən köklər: −3/2. Cəm: −3/2.');
INSERT INTO public.questions VALUES (4012, 52, 'g10-num-abs-q1-02', 1, 2, 'medium', 'single', '|x − 2| + |x − 7| < 21 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "22", "B": "21", "C": "20", "D": "18", "E": "19"}'::jsonb, 'C', NULL, 'Sərhədlər: |x − 2| + |x − 7| = 21 ⇒ x = −6 və x = 15. Həllər: −6 < x < 15, tam ədədlər — 20.');
INSERT INTO public.questions VALUES (4013, 52, 'g10-num-abs-q1-03', 1, 3, 'hard', 'single', '|x + 5| + |x − 2| = 13 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "88", "B": "89", "C": "115", "D": "9", "E": "−40"}'::jsonb, 'B', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −8, x₂ = 5 (aralıqda ifadə sabitdir və 7 ≠ 13). Cavab: 89.');
INSERT INTO public.questions VALUES (4014, 52, 'g10-num-abs-q1-04', 1, 4, 'medium', 'single', '|x − 3| + |x − 4| < 4 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "5", "B": "2", "C": "6", "D": "4", "E": "3"}'::jsonb, 'D', NULL, 'Sərhədlər: |x − 3| + |x − 4| = 4 ⇒ x = 3/2 və x = 11/2. Həllər: 3/2 < x < 11/2, tam ədədlər — 4.');
