INSERT INTO public.questions VALUES (4051, 52, 'g10-num-abs-q3-01', 3, 1, 'medium', 'single', '|x + 6| + |x + 1| < 16 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "16", "B": "17", "C": "14", "D": "18", "E": "15"}'::jsonb, 'A', NULL, 'Sərhədlər: |x + 6| + |x + 1| = 16 ⇒ x = −23/2 və x = 9/2. Həllər: −23/2 < x < 9/2, tam ədədlər — 16.');
INSERT INTO public.questions VALUES (4052, 52, 'g10-num-abs-q3-02', 3, 2, 'hard', 'single', '|x − 7| = (1/2)x + 3 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−68/3", "B": "71/3", "C": "65/3", "D": "74/3", "E": "68/3"}'::jsonb, 'E', NULL, 'x ≥ 7: x − 7 = (1/2)x + 3; x < 7: −(x − 7) = (1/2)x + 3. Şərti ödəyən köklər: 20, 8/3. Cəm: 68/3.');
INSERT INTO public.questions VALUES (4053, 52, 'g10-num-abs-q3-03', 3, 3, 'medium', 'single', '|x − 1| + |x − 5| < 11 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "11", "B": "13", "C": "10", "D": "9", "E": "12"}'::jsonb, 'A', NULL, 'Sərhədlər: |x − 1| + |x − 5| = 11 ⇒ x = −5/2 və x = 17/2. Həllər: −5/2 < x < 17/2, tam ədədlər — 11.');
INSERT INTO public.questions VALUES (4054, 52, 'g10-num-abs-q3-04', 3, 4, 'hard', 'single', '|x − 3| = −2x − 3 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−5", "B": "−7", "C": "−6", "D": "6", "E": "−4"}'::jsonb, 'C', NULL, 'x ≥ 3: x − 3 = −2x − 3; x < 3: −(x − 3) = −2x − 3. Şərti ödəyən köklər: −6. Cəm: −6.');
INSERT INTO public.questions VALUES (4055, 52, 'g10-num-abs-q3-05', 3, 5, 'medium', 'single', '|x − 3| + |x − 5| < 18 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "19", "B": "18", "C": "16", "D": "15", "E": "17"}'::jsonb, 'E', NULL, 'Sərhədlər: |x − 3| + |x − 5| = 18 ⇒ x = −5 və x = 13. Həllər: −5 < x < 13, tam ədədlər — 17.');
INSERT INTO public.questions VALUES (4056, 52, 'g10-num-abs-q3-06', 3, 6, 'medium', 'single', 'Hesablayın: √((11 − √18)²) + √((6 − √18)²)', NULL, NULL, '{"A": "17 − 6√2", "B": "17", "C": "5", "D": "6√2", "E": "−17 + 6√2"}'::jsonb, 'A', NULL, '√(t²) = |t|. √18 ≈ 4,24. 11 > √18 və 6 > √18: (11 − √18) + (6 − √18) = 17 − 6√2.');
INSERT INTO public.questions VALUES (4057, 52, 'g10-num-abs-q3-07', 3, 7, 'hard', 'open', 'f(x) = |x + 8| + |x − 7| + |x − 12| funksiyasının ən kiçik qiymətini tapın.', NULL, NULL, NULL, NULL, '20', 'Modulların cəminin minimumu medianda (orta nöqtələr arasında) alınır: (12 − (−8)) = 20.');
