INSERT INTO public.questions VALUES (4059, 52, 'g10-num-abs-q3-09', 3, 9, 'hard', 'single', '|x + 2| + |x − 2| = 16 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "0", "B": "160", "C": "−64", "D": "128", "E": "127"}'::jsonb, 'D', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −8, x₂ = 8 (aralıqda ifadə sabitdir və 4 ≠ 16). Cavab: 128.');
INSERT INTO public.questions VALUES (4060, 52, 'g10-num-abs-q3-10', 3, 10, 'hard', 'single', '|x + 8| = −2x − 6 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−17/3", "B": "−11/3", "C": "−14/3", "D": "−8/3", "E": "14/3"}'::jsonb, 'C', NULL, 'x ≥ −8: x + 8 = −2x − 6; x < −8: −(x + 8) = −2x − 6. Şərti ödəyən köklər: −14/3. Cəm: −14/3.');
INSERT INTO public.questions VALUES (4061, 52, 'g10-num-abs-q3-11', 3, 11, 'hard', 'single', '|x − 5| + |x − 6| = 13 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "144", "B": "−12", "C": "171", "D": "145", "E": "121"}'::jsonb, 'D', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −1, x₂ = 12 (aralıqda ifadə sabitdir və 1 ≠ 13). Cavab: 145.');
INSERT INTO public.questions VALUES (4062, 52, 'g10-num-abs-q3-12', 3, 12, 'hard', 'single', '|x − 7| + |x| = 11 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "85", "B": "84", "C": "107", "D": "49", "E": "−18"}'::jsonb, 'A', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −2, x₂ = 9 (aralıqda ifadə sabitdir və 7 ≠ 11). Cavab: 85.');
