INSERT INTO public.questions VALUES (4064, 52, 'g10-num-abs-q3-14', 3, 14, 'hard', 'open', 'f(x) = |x| + |x − 1| + |x − 13| funksiyasının ən kiçik qiymətini tapın.', NULL, NULL, NULL, NULL, '13', 'Modulların cəminin minimumu medianda (orta nöqtələr arasında) alınır: (13 − 0) = 13.');
INSERT INTO public.questions VALUES (4065, 52, 'g10-num-abs-q3-15', 3, 15, 'hard', 'single', '|x − 2| + |x − 6| = 18 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "194", "B": "230", "C": "64", "D": "−65", "E": "193"}'::jsonb, 'A', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −5, x₂ = 13 (aralıqda ifadə sabitdir və 4 ≠ 18). Cavab: 194.');
INSERT INTO public.questions VALUES (4066, 52, 'g10-num-abs-q3-16', 3, 16, 'medium', 'single', 'Hesablayın: √((9 − √59)²) + √((0 − √59)²)', NULL, NULL, '{"A": "2√59", "B": "9 + 2√59", "C": "9 − 2√59", "D": "−9 + 2√59", "E": "9"}'::jsonb, 'E', NULL, '√(t²) = |t|. √59 ≈ 7,68. √59 ədədi 0 ilə 9 arasındadır, modullar açılır: 9 − 0 = 9.');
INSERT INTO public.questions VALUES (4067, 52, 'g10-num-abs-q3-17', 3, 17, 'medium', 'single', 'Hesablayın: √((3 − √14)²) + √((9 − √14)²)', NULL, NULL, '{"A": "12 − 2√14", "B": "12", "C": "2√14", "D": "6", "E": "−12 + 2√14"}'::jsonb, 'D', NULL, '√(t²) = |t|. √14 ≈ 3,74. √14 ədədi 3 ilə 9 arasındadır, modullar açılır: 9 − 3 = 6.');
