INSERT INTO public.questions VALUES (4069, 52, 'g10-num-abs-q3-19', 3, 19, 'medium', 'single', 'Hesablayın: √((2 − √48)²) + √((11 − √48)²)', NULL, NULL, '{"A": "−13 + 8√3", "B": "9", "C": "8√3", "D": "13", "E": "13 − 8√3"}'::jsonb, 'B', NULL, '√(t²) = |t|. √48 ≈ 6,93. √48 ədədi 2 ilə 11 arasındadır, modullar açılır: 11 − 2 = 9.');
