INSERT INTO public.questions VALUES (4071, 53, 'g10-num-pct-q1-01', 1, 1, 'medium', 'single', 'Məhsulun qiyməti əvvəlcə 50% artırıldı, sonra 40% endirildi, daha sonra 5% artırıldı. Son qiymət ilkin qiymətlə müqayisədə neçə faiz dəyişdi? (artım müsbət, azalma mənfi)', NULL, NULL, '{"A": "15%", "B": "−5,5%", "C": "5,5%", "D": "−6,5%", "E": "−4,5%"}'::jsonb, 'B', NULL, 'Əmsallar: 1,5 · 0,6 · 1,05 = 0,945. Qiymət 5,5% azaldı.');
INSERT INTO public.questions VALUES (4072, 53, 'g10-num-pct-q1-02', 1, 2, 'hard', 'single', 'A ədədi B-dən 60% çox, B ədədi isə C-dən 40% azdır. A ədədi C-dən neçə faiz azdır?', NULL, NULL, '{"A": "9%", "B": "20%", "C": "4%", "D": "6%", "E": "24%"}'::jsonb, 'C', NULL, 'A = 1,6·B = 1,6·0,6·C = 0,96·C. Fərq: 4%.');
