INSERT INTO public.questions VALUES (4074, 53, 'g10-num-pct-q1-04', 1, 4, 'medium', 'single', 'Satıcı malın qiymətini maya dəyərindən 25% yuxarı qoydu, sonra bu qiymətə 15% endirim etdi. Satıcı maya dəyərinə nəzərən neçə faiz qazanc əldə etdi?', NULL, NULL, '{"A": "4,25%", "B": "8,25%", "C": "11,25%", "D": "6,25%", "E": "10%"}'::jsonb, 'D', NULL, 'Satış qiyməti: 1,25·0,85 = 1,0625 maya dəyəri. Qazanc: 6,25%.');
