INSERT INTO public.questions VALUES (4131, 54, 'g10-alg-eq-q1-01', 1, 1, 'hard', 'single', '√(x + 20) = x tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "1", "B": "4", "C": "5", "D": "6", "E": "−4"}'::jsonb, 'C', NULL, 'Kvadrata yüksəldin: x + 20 = (x)² ⇒ x² − x − 20 = 0, x = 5 və x = −4. Sağ tərəf mənfi olmamalıdır: x ≥ 0. x = −4 yad kökdür. Cavab: 5.');
INSERT INTO public.questions VALUES (4132, 54, 'g10-alg-eq-q1-02', 1, 2, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x − 3)/(x − 2) − 1/(x + 2) = −4/(x² − 4)', NULL, NULL, '{"A": "2", "B": "1", "C": "0", "D": "−2", "E": "−1"}'::jsonb, 'C', NULL, 'Ortaq məxrəc x² − 4: (x − 3)(x + 2) − 1(x − 2) = −4 ⇒ x² − 2x = 0, köklər 2 və 0. x = 2 məxrəci sıfra çevirir (yad kök). Cavab: 0.');
INSERT INTO public.questions VALUES (4133, 54, 'g10-alg-eq-q1-03', 1, 3, 'hard', 'single', '√(x + 13) = x + 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "3", "B": "−1", "C": "2", "D": "−4", "E": "4"}'::jsonb, 'A', NULL, 'Kvadrata yüksəldin: x + 13 = (x + 1)² ⇒ x² + x − 12 = 0, x = 3 və x = −4. Sağ tərəf mənfi olmamalıdır: x ≥ −1. x = −4 yad kökdür. Cavab: 3.');
INSERT INTO public.questions VALUES (4134, 54, 'g10-alg-eq-q1-04', 1, 4, 'medium', 'single', 'İki usta birlikdə işi 78/5 saata bitirir. Birinci usta təklikdə ikincidən 13 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "156/5", "B": "52", "C": "40", "D": "39", "E": "26"}'::jsonb, 'D', NULL, 'Birinci x saat, ikinci x + 13 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 13) = 5/78 ⇒ x = 26. İkinci usta: 39 saat.');
INSERT INTO public.questions VALUES (4135, 54, 'g10-alg-eq-q1-05', 1, 5, 'hard', 'single', 'x⁴ − 2x² − 99 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "−99", "B": "12", "C": "11", "D": "−11", "E": "99"}'::jsonb, 'D', NULL, 't = x² ≥ 0: t² − 2t − 99 = 0, t = −9 və t = 11. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: −11.');
INSERT INTO public.questions VALUES (4136, 54, 'g10-alg-eq-q1-06', 1, 6, 'hard', 'single', 'Qayıq çay axını ilə 90 km gedib geri qayıtdı və bütün yola 54 saat sərf etdi. Çayın axın sürəti 4 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "2", "B": "7", "C": "10", "D": "6", "E": "5"}'::jsonb, 'D', NULL, '90/(x + 4) + 90/(x − 4) = 54 ⇒ x = 6 km/saat (ikinci kök mənfidir və ya x ≤ 4).');
INSERT INTO public.questions VALUES (4137, 54, 'g10-alg-eq-q1-07', 1, 7, 'hard', 'single', 'x⁴ + 7x² − 18 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "3", "B": "0", "C": "2", "D": "1", "E": "4"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² + 7t − 18 = 0, t = −9 və t = 2. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (4138, 54, 'g10-alg-eq-q1-08', 1, 8, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x + 4)/(x − 2) − 1/(x + 2) = 24/(x² − 4)', NULL, NULL, '{"A": "−5", "B": "−6", "C": "−7", "D": "7", "E": "2"}'::jsonb, 'C', NULL, 'Ortaq məxrəc x² − 4: (x + 4)(x + 2) − 1(x − 2) = 24 ⇒ x² + 5x − 14 = 0, köklər 2 və −7. x = 2 məxrəci sıfra çevirir (yad kök). Cavab: −7.');
INSERT INTO public.questions VALUES (4139, 54, 'g10-alg-eq-q1-09', 1, 9, 'medium', 'single', 'İki usta birlikdə işi 35/2 saata bitirir. Birinci usta təklikdə ikincidən 12 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "35", "B": "54", "C": "30", "D": "43", "E": "42"}'::jsonb, 'E', NULL, 'Birinci x saat, ikinci x + 12 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 12) = 2/35 ⇒ x = 30. İkinci usta: 42 saat.');
INSERT INTO public.questions VALUES (4140, 54, 'g10-alg-eq-q1-10', 1, 10, 'hard', 'single', '√(x + 36) = x − 6 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "12", "B": "14", "C": "0", "D": "−13", "E": "13"}'::jsonb, 'E', NULL, 'Kvadrata yüksəldin: x + 36 = (x − 6)² ⇒ x² − 13x = 0, x = 13 və x = 0. Sağ tərəf mənfi olmamalıdır: x ≥ 6. x = 0 yad kökdür. Cavab: 13.');
INSERT INTO public.questions VALUES (4141, 54, 'g10-alg-eq-q1-11', 1, 11, 'hard', 'single', 'x⁴ − 4x² − 96 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "−96", "B": "−12", "C": "96", "D": "13", "E": "12"}'::jsonb, 'B', NULL, 't = x² ≥ 0: t² − 4t − 96 = 0, t = 12 və t = −8. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: −12.');
INSERT INTO public.questions VALUES (4142, 54, 'g10-alg-eq-q1-12', 1, 12, 'hard', 'single', '√(x + 46) = x + 4 tənliyinin kökünü tapın.', NULL, NULL, '{"A": "−10", "B": "4", "C": "2", "D": "−7", "E": "3"}'::jsonb, 'E', NULL, 'Kvadrata yüksəldin: x + 46 = (x + 4)² ⇒ x² + 7x − 30 = 0, x = 3 və x = −10. Sağ tərəf mənfi olmamalıdır: x ≥ −4. x = −10 yad kökdür. Cavab: 3.');
INSERT INTO public.questions VALUES (4143, 54, 'g10-alg-eq-q1-13', 1, 13, 'hard', 'single', 'Qayıq çay axını ilə 72 km gedib geri qayıtdı və bütün yola 48 saat sərf etdi. Çayın axın sürəti 2 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "2", "B": "5", "C": "4", "D": "6", "E": "3"}'::jsonb, 'C', NULL, '72/(x + 2) + 72/(x − 2) = 48 ⇒ x = 4 km/saat (ikinci kök mənfidir və ya x ≤ 2).');
INSERT INTO public.questions VALUES (4144, 54, 'g10-alg-eq-q1-14', 1, 14, 'hard', 'open', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 5)/(x − 2) − 2/(x + 2) = −12/(x² − 4)', NULL, NULL, NULL, NULL, '3', 'Ortaq məxrəc x² − 4: (x − 5)(x + 2) − 2(x − 2) = −12 ⇒ x² − 5x + 6 = 0, köklər 2 və 3. x = 2 məxrəci sıfra çevirir (yad kök). Cavab: 3.');
INSERT INTO public.questions VALUES (4145, 54, 'g10-alg-eq-q1-15', 1, 15, 'hard', 'single', 'x⁴ − 9 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "0", "B": "4", "C": "3", "D": "2", "E": "1"}'::jsonb, 'D', NULL, 't = x² ≥ 0: t² − 9 = 0, t = 3 və t = −3. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (4146, 54, 'g10-alg-eq-q1-16', 1, 16, 'hard', 'single', 'x⁴ − 2x² − 63 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "9", "B": "−63", "C": "10", "D": "−9", "E": "63"}'::jsonb, 'D', NULL, 't = x² ≥ 0: t² − 2t − 63 = 0, t = 9 və t = −7. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: −9.');
INSERT INTO public.questions VALUES (4147, 54, 'g10-alg-eq-q1-17', 1, 17, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 15)/(x − 7) − 2/(x + 7) = −112/(x² − 49)', NULL, NULL, '{"A": "7", "B": "4", "C": "10", "D": "3", "E": "−3"}'::jsonb, 'D', NULL, 'Ortaq məxrəc x² − 49: (x − 15)(x + 7) − 2(x − 7) = −112 ⇒ x² − 10x + 21 = 0, köklər 7 və 3. x = 7 məxrəci sıfra çevirir (yad kök). Cavab: 3.');
INSERT INTO public.questions VALUES (4148, 54, 'g10-alg-eq-q1-18', 1, 18, 'hard', 'single', 'Qayıq çay axını ilə 30 km gedib geri qayıtdı və bütün yola 16/3 saat sərf etdi. Çayın axın sürəti 3 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "12", "B": "13", "C": "15", "D": "9", "E": "11"}'::jsonb, 'A', NULL, '30/(x + 3) + 30/(x − 3) = 16/3 ⇒ x = 12 km/saat (ikinci kök mənfidir və ya x ≤ 3).');
INSERT INTO public.questions VALUES (4149, 54, 'g10-alg-eq-q1-19', 1, 19, 'hard', 'single', 'Qayıq çay axını ilə 24 km gedib geri qayıtdı və bütün yola 2 saat sərf etdi. Çayın axın sürəti 5 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "26", "B": "30", "C": "24", "D": "25", "E": "20"}'::jsonb, 'D', NULL, '24/(x + 5) + 24/(x − 5) = 2 ⇒ x = 25 km/saat (ikinci kök mənfidir və ya x ≤ 5).');
INSERT INTO public.questions VALUES (4150, 54, 'g10-alg-eq-q1-20', 1, 20, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 10)/(x − 4) − 3/(x + 4) = −48/(x² − 16)', NULL, NULL, '{"A": "4", "B": "6", "C": "9", "D": "5", "E": "−5"}'::jsonb, 'D', NULL, 'Ortaq məxrəc x² − 16: (x − 10)(x + 4) − 3(x − 4) = −48 ⇒ x² − 9x + 20 = 0, köklər 4 və 5. x = 4 məxrəci sıfra çevirir (yad kök). Cavab: 5.');
INSERT INTO public.questions VALUES (4151, 54, 'g10-alg-eq-q2-01', 2, 1, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x − 9)/(x − 4) − 5/(x + 4) = −40/(x² − 16)', NULL, NULL, '{"A": "10", "B": "−6", "C": "7", "D": "6", "E": "4"}'::jsonb, 'D', NULL, 'Ortaq məxrəc x² − 16: (x − 9)(x + 4) − 5(x − 4) = −40 ⇒ x² − 10x + 24 = 0, köklər 4 və 6. x = 4 məxrəci sıfra çevirir (yad kök). Cavab: 6.');
INSERT INTO public.questions VALUES (4152, 54, 'g10-alg-eq-q2-02', 2, 2, 'hard', 'single', '√(x + 2) = x − 4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "8", "B": "6", "C": "9", "D": "2", "E": "7"}'::jsonb, 'E', NULL, 'Kvadrata yüksəldin: x + 2 = (x − 4)² ⇒ x² − 9x + 14 = 0, x = 7 və x = 2. Sağ tərəf mənfi olmamalıdır: x ≥ 4. x = 2 yad kökdür. Cavab: 7.');
INSERT INTO public.questions VALUES (4153, 54, 'g10-alg-eq-q2-03', 2, 3, 'medium', 'single', 'İki usta birlikdə işi 36/5 saata bitirir. Birinci usta təklikdə ikincidən 6 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "12", "B": "72/5", "C": "24", "D": "18", "E": "19"}'::jsonb, 'D', NULL, 'Birinci x saat, ikinci x + 6 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 6) = 5/36 ⇒ x = 12. İkinci usta: 18 saat.');
INSERT INTO public.questions VALUES (4154, 54, 'g10-alg-eq-q2-04', 2, 4, 'hard', 'single', 'x⁴ − x² − 56 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "3", "B": "0", "C": "2", "D": "1", "E": "4"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − t − 56 = 0, t = −7 və t = 8. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (4155, 54, 'g10-alg-eq-q2-05', 2, 5, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x − 9)/(x − 3) − 5/(x + 3) = −36/(x² − 9)', NULL, NULL, '{"A": "8", "B": "9", "C": "3", "D": "−8", "E": "11"}'::jsonb, 'A', NULL, 'Ortaq məxrəc x² − 9: (x − 9)(x + 3) − 5(x − 3) = −36 ⇒ x² − 11x + 24 = 0, köklər 3 və 8. x = 3 məxrəci sıfra çevirir (yad kök). Cavab: 8.');
INSERT INTO public.questions VALUES (4156, 54, 'g10-alg-eq-q2-06', 2, 6, 'medium', 'single', 'İki usta birlikdə işi 6 saata bitirir. Birinci usta təklikdə ikincidən 5 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "20", "B": "15", "C": "16", "D": "12", "E": "10"}'::jsonb, 'B', NULL, 'Birinci x saat, ikinci x + 5 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 5) = 1/6 ⇒ x = 10. İkinci usta: 15 saat.');
INSERT INTO public.questions VALUES (4157, 54, 'g10-alg-eq-q2-07', 2, 7, 'hard', 'single', 'x⁴ − 12x² + 32 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "0", "B": "2", "C": "4", "D": "1", "E": "3"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 12t + 32 = 0, t = 8 və t = 4. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 4.');
INSERT INTO public.questions VALUES (4158, 54, 'g10-alg-eq-q2-08', 2, 8, 'hard', 'single', 'Qayıq çay axını ilə 18 km gedib geri qayıtdı və bütün yola 3/2 saat sərf etdi. Çayın axın sürəti 5 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "30", "B": "25", "C": "24", "D": "26", "E": "20"}'::jsonb, 'B', NULL, '18/(x + 5) + 18/(x − 5) = 3/2 ⇒ x = 25 km/saat (ikinci kök mənfidir və ya x ≤ 5).');
INSERT INTO public.questions VALUES (4159, 54, 'g10-alg-eq-q2-09', 2, 9, 'hard', 'single', '√(x + 71) = x − 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−7", "B": "3", "C": "10", "D": "9", "E": "11"}'::jsonb, 'C', NULL, 'Kvadrata yüksəldin: x + 71 = (x − 1)² ⇒ x² − 3x − 70 = 0, x = 10 və x = −7. Sağ tərəf mənfi olmamalıdır: x ≥ 1. x = −7 yad kökdür. Cavab: 10.');
INSERT INTO public.questions VALUES (4160, 54, 'g10-alg-eq-q2-10', 2, 10, 'hard', 'single', '√(x + 13) = x − 7 tənliyinin kökünü tapın.', NULL, NULL, '{"A": "13", "B": "12", "C": "15", "D": "11", "E": "3"}'::jsonb, 'B', NULL, 'Kvadrata yüksəldin: x + 13 = (x − 7)² ⇒ x² − 15x + 36 = 0, x = 12 və x = 3. Sağ tərəf mənfi olmamalıdır: x ≥ 7. x = 3 yad kökdür. Cavab: 12.');
INSERT INTO public.questions VALUES (4161, 54, 'g10-alg-eq-q2-11', 2, 11, 'hard', 'single', 'Qayıq çay axını ilə 60 km gedib geri qayıtdı və bütün yola 19/3 saat sərf etdi. Çayın axın sürəti 1 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "18", "B": "360/19", "C": "20", "D": "21", "E": "19"}'::jsonb, 'E', NULL, '60/(x + 1) + 60/(x − 1) = 19/3 ⇒ x = 19 km/saat (ikinci kök mənfidir və ya x ≤ 1).');
INSERT INTO public.questions VALUES (4162, 54, 'g10-alg-eq-q2-12', 2, 12, 'hard', 'single', 'Qayıq çay axını ilə 54 km gedib geri qayıtdı və bütün yola 63/2 saat sərf etdi. Çayın axın sürəti 5 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "8", "B": "6", "C": "7", "D": "12", "E": "2"}'::jsonb, 'C', NULL, '54/(x + 5) + 54/(x − 5) = 63/2 ⇒ x = 7 km/saat (ikinci kök mənfidir və ya x ≤ 5).');
INSERT INTO public.questions VALUES (4163, 54, 'g10-alg-eq-q2-13', 2, 13, 'hard', 'single', 'Qayıq çay axını ilə 36 km gedib geri qayıtdı və bütün yola 45/2 saat sərf etdi. Çayın axın sürəti 3 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "5", "B": "4", "C": "6", "D": "8", "E": "2"}'::jsonb, 'A', NULL, '36/(x + 3) + 36/(x − 3) = 45/2 ⇒ x = 5 km/saat (ikinci kök mənfidir və ya x ≤ 3).');
INSERT INTO public.questions VALUES (4164, 54, 'g10-alg-eq-q2-14', 2, 14, 'hard', 'open', '√(x + 59) = x + 3 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '5', 'Kvadrata yüksəldin: x + 59 = (x + 3)² ⇒ x² + 5x − 50 = 0, x = 5 və x = −10. Sağ tərəf mənfi olmamalıdır: x ≥ −3. x = −10 yad kökdür. Cavab: 5.');
INSERT INTO public.questions VALUES (4165, 54, 'g10-alg-eq-q2-15', 2, 15, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x + 5)/(x − 4) − 4/(x + 4) = 72/(x² − 16)', NULL, NULL, '{"A": "−8", "B": "9", "C": "−9", "D": "−5", "E": "4"}'::jsonb, 'C', NULL, 'Ortaq məxrəc x² − 16: (x + 5)(x + 4) − 4(x − 4) = 72 ⇒ x² + 5x − 36 = 0, köklər 4 və −9. x = 4 məxrəci sıfra çevirir (yad kök). Cavab: −9.');
INSERT INTO public.questions VALUES (4166, 54, 'g10-alg-eq-q2-16', 2, 16, 'hard', 'single', 'x⁴ − 14x² + 24 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "−24", "B": "25", "C": "24", "D": "23", "E": "14"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 14t + 24 = 0, t = 12 və t = 2. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 24.');
INSERT INTO public.questions VALUES (4167, 54, 'g10-alg-eq-q2-17', 2, 17, 'hard', 'single', 'Qayıq çay axını ilə 78 km gedib geri qayıtdı və bütün yola 52 saat sərf etdi. Çayın axın sürəti 2 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "6", "B": "5", "C": "2", "D": "3", "E": "4"}'::jsonb, 'E', NULL, '78/(x + 2) + 78/(x − 2) = 52 ⇒ x = 4 km/saat (ikinci kök mənfidir və ya x ≤ 2).');
INSERT INTO public.questions VALUES (4168, 54, 'g10-alg-eq-q2-18', 2, 18, 'hard', 'single', 'x⁴ + 3x² − 18 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "3", "B": "2", "C": "0", "D": "1", "E": "4"}'::jsonb, 'B', NULL, 't = x² ≥ 0: t² + 3t − 18 = 0, t = 3 və t = −6. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (4169, 54, 'g10-alg-eq-q2-19', 2, 19, 'hard', 'single', '√(x + 48) = x − 8 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "16", "B": "17", "C": "1", "D": "−16", "E": "15"}'::jsonb, 'A', NULL, 'Kvadrata yüksəldin: x + 48 = (x − 8)² ⇒ x² − 17x + 16 = 0, x = 16 və x = 1. Sağ tərəf mənfi olmamalıdır: x ≥ 8. x = 1 yad kökdür. Cavab: 16.');
INSERT INTO public.questions VALUES (4170, 54, 'g10-alg-eq-q2-20', 2, 20, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x + 3)/(x − 3) − 4/(x + 3) = 36/(x² − 9)', NULL, NULL, '{"A": "−2", "B": "5", "C": "−4", "D": "3", "E": "−5"}'::jsonb, 'E', NULL, 'Ortaq məxrəc x² − 9: (x + 3)(x + 3) − 4(x − 3) = 36 ⇒ x² + 2x − 15 = 0, köklər 3 və −5. x = 3 məxrəci sıfra çevirir (yad kök). Cavab: −5.');
INSERT INTO public.questions VALUES (4171, 54, 'g10-alg-eq-q3-01', 3, 1, 'medium', 'single', 'İki usta birlikdə işi 5/2 saata bitirir. Birinci usta təklikdə ikincidən 12 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "27", "B": "3", "C": "16", "D": "15", "E": "5"}'::jsonb, 'D', NULL, 'Birinci x saat, ikinci x + 12 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 12) = 2/5 ⇒ x = 3. İkinci usta: 15 saat.');
INSERT INTO public.questions VALUES (4172, 54, 'g10-alg-eq-q3-02', 3, 2, 'hard', 'single', 'x⁴ − 81 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "10", "B": "−81", "C": "−9", "D": "9", "E": "81"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 81 = 0, t = −9 və t = 9. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: −9.');
INSERT INTO public.questions VALUES (4173, 54, 'g10-alg-eq-q3-03', 3, 3, 'hard', 'single', 'x⁴ − 14x² − 32 = 0 tənliyinin həqiqi köklərinin hasilini tapın.', NULL, NULL, '{"A": "−16", "B": "16", "C": "32", "D": "−32", "E": "17"}'::jsonb, 'A', NULL, 't = x² ≥ 0: t² − 14t − 32 = 0, t = 16 və t = −2. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: −16.');
INSERT INTO public.questions VALUES (4174, 54, 'g10-alg-eq-q3-04', 3, 4, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x − 16)/(x − 6) − 3/(x + 6) = −120/(x² − 36)', NULL, NULL, '{"A": "8", "B": "13", "C": "6", "D": "7", "E": "−7"}'::jsonb, 'D', NULL, 'Ortaq məxrəc x² − 36: (x − 16)(x + 6) − 3(x − 6) = −120 ⇒ x² − 13x + 42 = 0, köklər 6 və 7. x = 6 məxrəci sıfra çevirir (yad kök). Cavab: 7.');
INSERT INTO public.questions VALUES (4175, 54, 'g10-alg-eq-q3-05', 3, 5, 'hard', 'single', 'Qayıq çay axını ilə 84 km gedib geri qayıtdı və bütün yola 21 saat sərf etdi. Çayın axın sürəti 3 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "10", "B": "8", "C": "9", "D": "6", "E": "12"}'::jsonb, 'C', NULL, '84/(x + 3) + 84/(x − 3) = 21 ⇒ x = 9 km/saat (ikinci kök mənfidir və ya x ≤ 3).');
INSERT INTO public.questions VALUES (4176, 54, 'g10-alg-eq-q3-06', 3, 6, 'medium', 'single', 'İki usta birlikdə işi 10/3 saata bitirir. Birinci usta təklikdə ikincidən 5 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "5", "B": "15", "C": "20/3", "D": "10", "E": "11"}'::jsonb, 'D', NULL, 'Birinci x saat, ikinci x + 5 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 5) = 3/10 ⇒ x = 5. İkinci usta: 10 saat.');
INSERT INTO public.questions VALUES (4177, 54, 'g10-alg-eq-q3-07', 3, 7, 'hard', 'open', 'Tənliyi həll edin və kökünü tapın: (x − 2)/(x − 4) − 3/(x + 4) = 16/(x² − 16)', NULL, NULL, NULL, NULL, '−3', 'Ortaq məxrəc x² − 16: (x − 2)(x + 4) − 3(x − 4) = 16 ⇒ x² − x − 12 = 0, köklər 4 və −3. x = 4 məxrəci sıfra çevirir (yad kök). Cavab: −3.');
INSERT INTO public.questions VALUES (4178, 54, 'g10-alg-eq-q3-08', 3, 8, 'hard', 'single', '√(x + 5) = x − 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "3", "B": "5", "C": "−4", "D": "4", "E": "−1"}'::jsonb, 'D', NULL, 'Kvadrata yüksəldin: x + 5 = (x − 1)² ⇒ x² − 3x − 4 = 0, x = 4 və x = −1. Sağ tərəf mənfi olmamalıdır: x ≥ 1. x = −1 yad kökdür. Cavab: 4.');
INSERT INTO public.questions VALUES (4179, 54, 'g10-alg-eq-q3-09', 3, 9, 'hard', 'single', 'Qayıq çay axını ilə 54 km gedib geri qayıtdı və bütün yola 63/4 saat sərf etdi. Çayın axın sürəti 1 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "6", "B": "7", "C": "9", "D": "8", "E": "48/7"}'::jsonb, 'B', NULL, '54/(x + 1) + 54/(x − 1) = 63/4 ⇒ x = 7 km/saat (ikinci kök mənfidir və ya x ≤ 1).');
INSERT INTO public.questions VALUES (4180, 54, 'g10-alg-eq-q3-10', 3, 10, 'hard', 'single', 'x⁴ − 4x² − 117 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "3", "B": "1", "C": "2", "D": "0", "E": "4"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 4t − 117 = 0, t = 13 və t = −9. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 2.');
INSERT INTO public.questions VALUES (4181, 54, 'g10-alg-eq-q3-11', 3, 11, 'hard', 'single', 'Qayıq çay axını ilə 54 km gedib geri qayıtdı və bütün yola 39/4 saat sərf etdi. Çayın axın sürəti 5 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "12", "B": "14", "C": "18", "D": "8", "E": "13"}'::jsonb, 'E', NULL, '54/(x + 5) + 54/(x − 5) = 39/4 ⇒ x = 13 km/saat (ikinci kök mənfidir və ya x ≤ 5).');
INSERT INTO public.questions VALUES (4182, 54, 'g10-alg-eq-q3-12', 3, 12, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x − 3)/(x − 6) − 6/(x + 6) = 36/(x² − 36)', NULL, NULL, '{"A": "−2", "B": "−6", "C": "3", "D": "6", "E": "−3"}'::jsonb, 'E', NULL, 'Ortaq məxrəc x² − 36: (x − 3)(x + 6) − 6(x − 6) = 36 ⇒ x² − 3x − 18 = 0, köklər 6 və −3. x = 6 məxrəci sıfra çevirir (yad kök). Cavab: −3.');
INSERT INTO public.questions VALUES (4183, 54, 'g10-alg-eq-q3-13', 3, 13, 'hard', 'single', '√(x + 39) = x − 3 tənliyinin kökünü tapın.', NULL, NULL, '{"A": "7", "B": "−3", "C": "9", "D": "10", "E": "11"}'::jsonb, 'D', NULL, 'Kvadrata yüksəldin: x + 39 = (x − 3)² ⇒ x² − 7x − 30 = 0, x = 10 və x = −3. Sağ tərəf mənfi olmamalıdır: x ≥ 3. x = −3 yad kökdür. Cavab: 10.');
INSERT INTO public.questions VALUES (4184, 54, 'g10-alg-eq-q3-14', 3, 14, 'hard', 'single', 'x⁴ − 20x² + 91 = 0 tənliyinin neçə həqiqi kökü var?', NULL, NULL, '{"A": "2", "B": "3", "C": "4", "D": "0", "E": "1"}'::jsonb, 'C', NULL, 't = x² ≥ 0: t² − 20t + 91 = 0, t = 7 və t = 13. Yalnız müsbət t həqiqi kök verir: x = ±√t. Cavab: 4.');
INSERT INTO public.questions VALUES (4185, 54, 'g10-alg-eq-q3-15', 3, 15, 'hard', 'single', 'Tənliyi həll edin və köklərinin cəmini tapın: (x − 15)/(x − 5) − 3/(x + 5) = −100/(x² − 25)', NULL, NULL, '{"A": "−8", "B": "5", "C": "8", "D": "9", "E": "13"}'::jsonb, 'C', NULL, 'Ortaq məxrəc x² − 25: (x − 15)(x + 5) − 3(x − 5) = −100 ⇒ x² − 13x + 40 = 0, köklər 5 və 8. x = 5 məxrəci sıfra çevirir (yad kök). Cavab: 8.');
INSERT INTO public.questions VALUES (4186, 54, 'g10-alg-eq-q3-16', 3, 16, 'hard', 'single', '√(x + 16) = x − 4 tənliyinin kökünü tapın.', NULL, NULL, '{"A": "8", "B": "10", "C": "0", "D": "−9", "E": "9"}'::jsonb, 'E', NULL, 'Kvadrata yüksəldin: x + 16 = (x − 4)² ⇒ x² − 9x = 0, x = 9 və x = 0. Sağ tərəf mənfi olmamalıdır: x ≥ 4. x = 0 yad kökdür. Cavab: 9.');
INSERT INTO public.questions VALUES (4187, 54, 'g10-alg-eq-q3-17', 3, 17, 'hard', 'single', 'Tənliyi həll edin və kökünü tapın: (x + 2)/(x − 2) − 5/(x + 2) = 16/(x² − 4)', NULL, NULL, '{"A": "0", "B": "1", "C": "−1", "D": "−2", "E": "2"}'::jsonb, 'C', NULL, 'Ortaq məxrəc x² − 4: (x + 2)(x + 2) − 5(x − 2) = 16 ⇒ x² − x − 2 = 0, köklər 2 və −1. x = 2 məxrəci sıfra çevirir (yad kök). Cavab: −1.');
INSERT INTO public.questions VALUES (4188, 54, 'g10-alg-eq-q3-18', 3, 18, 'medium', 'single', 'İki usta birlikdə işi 9/2 saata bitirir. Birinci usta təklikdə ikincidən 12 saat tez bitirir. İkinci usta işi təklikdə neçə saata bitirər?', NULL, NULL, '{"A": "6", "B": "9", "C": "18", "D": "19", "E": "30"}'::jsonb, 'C', NULL, 'Birinci x saat, ikinci x + 12 saat. Birlikdə saatlıq iş: 1/x + 1/(x + 12) = 2/9 ⇒ x = 6. İkinci usta: 18 saat.');
INSERT INTO public.questions VALUES (4189, 54, 'g10-alg-eq-q3-19', 3, 19, 'hard', 'single', 'Qayıq çay axını ilə 48 km gedib geri qayıtdı və bütün yola 14/3 saat sərf etdi. Çayın axın sürəti 3 km/saatdırsa, qayığın durğun sudakı sürəti neçə km/saatdır?', NULL, NULL, '{"A": "18", "B": "22", "C": "20", "D": "21", "E": "24"}'::jsonb, 'D', NULL, '48/(x + 3) + 48/(x − 3) = 14/3 ⇒ x = 21 km/saat (ikinci kök mənfidir və ya x ≤ 3).');
INSERT INTO public.questions VALUES (4190, 54, 'g10-alg-eq-q3-20', 3, 20, 'hard', 'single', '√(x + 7) = x + 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "1", "B": "−1", "C": "3", "D": "−3", "E": "2"}'::jsonb, 'E', NULL, 'Kvadrata yüksəldin: x + 7 = (x + 1)² ⇒ x² + x − 6 = 0, x = 2 və x = −3. Sağ tərəf mənfi olmamalıdır: x ≥ −1. x = −3 yad kökdür. Cavab: 2.');
INSERT INTO public.questions VALUES (4191, 55, 'g10-alg-sys-q1-01', 1, 1, 'medium', 'single', 'Teatrda böyük bileti 4 manat, uşaq bileti 3 manatdır. Cəmi 119 bilet satıldı və 403 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "−25", "B": "−27", "C": "−29", "D": "−26", "E": "27"}'::jsonb, 'B', NULL, 'x + y = 119, 4x + 3y = 403 ⇒ x = 46, y = 73.');
INSERT INTO public.questions VALUES (4192, 55, 'g10-alg-sys-q1-02', 1, 2, 'medium', 'single', 'x² − y² = −75 və x + y = 3 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−155", "B": "−154", "C": "154", "D": "317", "E": "−151"}'::jsonb, 'B', NULL, 'x − y = −75 : 3 = −25. x = −11, y = 14. Cavab: −154.');
INSERT INTO public.questions VALUES (4193, 55, 'g10-alg-sys-q1-03', 1, 3, 'hard', 'single', 'x + y = 7 və xy = −3 olarsa, x⁴ + y⁴ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "3025", "B": "3043", "C": "3007", "D": "2383", "E": "3016"}'::jsonb, 'C', NULL, 'x² + y² = 55; x⁴ + y⁴ = (x² + y²)² − 2(xy)² = 3025 − 18 = 3007.');
INSERT INTO public.questions VALUES (4194, 55, 'g10-alg-sys-q1-04', 1, 4, 'medium', 'single', '{2x + 8y = −10; −5x + 5y = −25} sistemi üçün xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−6", "B": "1", "C": "−7", "D": "6", "E": "−5"}'::jsonb, 'A', NULL, 'Toplama və ya əvəzləmə üsulu: x = 3, y = −2. xy = −6.');
INSERT INTO public.questions VALUES (4195, 55, 'g10-alg-sys-q1-05', 1, 5, 'medium', 'single', 'x² − y² = 21 və x + y = 21 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "109", "B": "110", "C": "131", "D": "−110", "E": "221"}'::jsonb, 'B', NULL, 'x − y = 21 : 21 = 1. x = 11, y = 10. Cavab: 110.');
INSERT INTO public.questions VALUES (4196, 55, 'g10-alg-sys-q1-06', 1, 6, 'hard', 'single', 'a-nın hansı qiymətində {ax + 3y = 3; 3x + ay = −3} sisteminin həlli yoxdur?', NULL, NULL, '{"A": "9", "B": "3", "C": "4", "D": "0", "E": "−3"}'::jsonb, 'B', NULL, 'Həll yeganə deyilsə, a/3 = 3/a ⇒ a = ±3. a = 3: 3x + 3y = 3 və 3x + 3y = −3; a = −3: −3x + 3y = 3 və 3x − 3y = −3, yəni −3x + 3y = 3. Sağ tərəflər üst-üstə düşəndə sonsuz həll, fərqli olanda həll yoxdur. Cavab: a = 3.');
INSERT INTO public.questions VALUES (4197, 55, 'g10-alg-sys-q1-07', 1, 7, 'medium', 'open', 'x² − y² = 40 və x + y = 10 olarsa, xy ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '21', 'x − y = 40 : 10 = 4. x = 7, y = 3. Cavab: 21.');
INSERT INTO public.questions VALUES (4198, 55, 'g10-alg-sys-q1-08', 1, 8, 'medium', 'single', 'Teatrda böyük bileti 9 manat, uşaq bileti 7 manatdır. Cəmi 44 bilet satıldı və 358 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "27", "B": "25", "C": "23", "D": "26", "E": "19"}'::jsonb, 'B', NULL, 'x + y = 44, 9x + 7y = 358 ⇒ x = 25, y = 19.');
INSERT INTO public.questions VALUES (4199, 55, 'g10-alg-sys-q1-09', 1, 9, 'medium', 'single', '{−4x + 4y = −60; −7x + 3y = −93} sistemi üçün xy ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9", "B": "−37", "C": "−35", "D": "36", "E": "−36"}'::jsonb, 'E', NULL, 'Toplama və ya əvəzləmə üsulu: x = 12, y = −3. xy = −36.');
INSERT INTO public.questions VALUES (4200, 55, 'g10-alg-sys-q1-10', 1, 10, 'medium', 'single', 'Teatrda böyük bileti 11 manat, uşaq bileti 2 manatdır. Cəmi 45 bilet satıldı və 252 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "16", "B": "19", "C": "20", "D": "18", "E": "27"}'::jsonb, 'D', NULL, 'x + y = 45, 11x + 2y = 252 ⇒ x = 18, y = 27.');
INSERT INTO public.questions VALUES (4201, 55, 'g10-alg-sys-q1-11', 1, 11, 'medium', 'single', 'x + y = 3 və xy = −3 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "55", "B": "0", "C": "27", "D": "54", "E": "36"}'::jsonb, 'D', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 27 − (−27) = 54.');
INSERT INTO public.questions VALUES (4202, 55, 'g10-alg-sys-q1-12', 1, 12, 'hard', 'single', 'a-nın hansı qiymətində {ax + 5y = 8; 5x + ay = 8} sisteminin sonsuz sayda həlli var?', NULL, NULL, '{"A": "25", "B": "−5", "C": "0", "D": "5", "E": "6"}'::jsonb, 'D', NULL, 'Həll yeganə deyilsə, a/5 = 5/a ⇒ a = ±5. a = 5: 5x + 5y = 8 və 5x + 5y = 8; a = −5: −5x + 5y = 8 və 5x − 5y = 8, yəni −5x + 5y = −8. Sağ tərəflər üst-üstə düşəndə sonsuz həll, fərqli olanda həll yoxdur. Cavab: a = 5.');
INSERT INTO public.questions VALUES (4203, 55, 'g10-alg-sys-q1-13', 1, 13, 'medium', 'single', 'x² − y² = −24 və x + y = 12 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "73", "B": "86", "C": "−74", "D": "35", "E": "74"}'::jsonb, 'E', NULL, 'x − y = −24 : 12 = −2. x = 5, y = 7. Cavab: 74.');
INSERT INTO public.questions VALUES (4204, 55, 'g10-alg-sys-q1-14', 1, 14, 'hard', 'open', 'x + y = 9 və xy = −13 olarsa, x⁴ + y⁴ ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '11111', 'x² + y² = 107; x⁴ + y⁴ = (x² + y²)² − 2(xy)² = 11449 − 338 = 11111.');
INSERT INTO public.questions VALUES (4205, 55, 'g10-alg-sys-q1-15', 1, 15, 'medium', 'single', 'x + y = −7 və xy = −17 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−700", "B": "14", "C": "−462", "D": "−699", "E": "−343"}'::jsonb, 'A', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = (−343) − 357 = −700.');
INSERT INTO public.questions VALUES (4206, 55, 'g10-alg-sys-q1-16', 1, 16, 'medium', 'single', 'Teatrda böyük bileti 13 manat, uşaq bileti 9 manatdır. Cəmi 16 bilet satıldı və 164 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, '{"A": "−8", "B": "−6", "C": "6", "D": "−4", "E": "−5"}'::jsonb, 'B', NULL, 'x + y = 16, 13x + 9y = 164 ⇒ x = 5, y = 11.');
INSERT INTO public.questions VALUES (4207, 55, 'g10-alg-sys-q1-17', 1, 17, 'hard', 'single', 'a-nın hansı qiymətində {ax + 2y = 12; 2x + ay = 12} sisteminin həlli yoxdur?', NULL, NULL, '{"A": "4", "B": "−2", "C": "−1", "D": "0", "E": "2"}'::jsonb, 'B', NULL, 'Həll yeganə deyilsə, a/2 = 2/a ⇒ a = ±2. a = 2: 2x + 2y = 12 və 2x + 2y = 12; a = −2: −2x + 2y = 12 və 2x − 2y = 12, yəni −2x + 2y = −12. Sağ tərəflər üst-üstə düşəndə sonsuz həll, fərqli olanda həll yoxdur. Cavab: a = −2.');
INSERT INTO public.questions VALUES (4208, 55, 'g10-alg-sys-q1-18', 1, 18, 'medium', 'single', '{4x + y = 26; 8x + 4y = 56} sistemi üçün x − y ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "3", "B": "5", "C": "4", "D": "−4", "E": "8"}'::jsonb, 'C', NULL, 'Toplama və ya əvəzləmə üsulu: x = 6, y = 2. x − y = 4.');
INSERT INTO public.questions VALUES (4209, 55, 'g10-alg-sys-q1-19', 1, 19, 'hard', 'single', 'a-nın hansı qiymətində {ax + 2y = 6; 2x + ay = 6} sisteminin həlli yoxdur?', NULL, NULL, '{"A": "−1", "B": "0", "C": "−2", "D": "2", "E": "4"}'::jsonb, 'C', NULL, 'Həll yeganə deyilsə, a/2 = 2/a ⇒ a = ±2. a = 2: 2x + 2y = 6 və 2x + 2y = 6; a = −2: −2x + 2y = 6 və 2x − 2y = 6, yəni −2x + 2y = −6. Sağ tərəflər üst-üstə düşəndə sonsuz həll, fərqli olanda həll yoxdur. Cavab: a = −2.');
INSERT INTO public.questions VALUES (4210, 55, 'g10-alg-sys-q1-20', 1, 20, 'medium', 'single', '{9x − 7y = 54; 7x + 6y = 42} sistemi üçün x − y ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "5", "B": "8", "C": "7", "D": "6", "E": "−6"}'::jsonb, 'D', NULL, 'Toplama və ya əvəzləmə üsulu: x = 6, y = 0. x − y = 6.');
INSERT INTO public.questions VALUES (4211, 55, 'g10-alg-sys-q2-01', 2, 1, 'medium', 'single', 'x² − y² = −13 və x + y = −13 olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−85", "B": "84", "C": "72", "D": "42", "E": "85"}'::jsonb, 'E', NULL, 'x − y = −13 : (−13) = 1. x = −6, y = −7. Cavab: 85.');
INSERT INTO public.questions VALUES (4212, 55, 'g10-alg-sys-q2-02', 2, 2, 'hard', 'single', 'a-nın hansı qiymətində {ax + 2y = 5; 2x + ay = 5} sisteminin həlli yoxdur?', NULL, NULL, '{"A": "0", "B": "4", "C": "2", "D": "−2", "E": "−1"}'::jsonb, 'D', NULL, 'Həll yeganə deyilsə, a/2 = 2/a ⇒ a = ±2. a = 2: 2x + 2y = 5 və 2x + 2y = 5; a = −2: −2x + 2y = 5 və 2x − 2y = 5, yəni −2x + 2y = −5. Sağ tərəflər üst-üstə düşəndə sonsuz həll, fərqli olanda həll yoxdur. Cavab: a = −2.');
INSERT INTO public.questions VALUES (4213, 55, 'g10-alg-sys-q2-03', 2, 3, 'medium', 'single', 'x + y = 6 və xy = −10 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "396", "B": "397", "C": "276", "D": "216", "E": "36"}'::jsonb, 'A', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = 216 − (−180) = 396.');
INSERT INTO public.questions VALUES (4214, 55, 'g10-alg-sys-q2-04', 2, 4, 'medium', 'single', 'Teatrda böyük bileti 15 manat, uşaq bileti 4 manatdır. Cəmi 77 bilet satıldı və 649 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "31", "B": "46", "C": "32", "D": "33", "E": "29"}'::jsonb, 'A', NULL, 'x + y = 77, 15x + 4y = 649 ⇒ x = 31, y = 46.');
INSERT INTO public.questions VALUES (4215, 55, 'g10-alg-sys-q2-05', 2, 5, 'medium', 'single', 'Teatrda böyük bileti 15 manat, uşaq bileti 6 manatdır. Cəmi 28 bilet satıldı və 330 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "10", "B": "19", "C": "20", "D": "18", "E": "16"}'::jsonb, 'D', NULL, 'x + y = 28, 15x + 6y = 330 ⇒ x = 18, y = 10.');
