INSERT INTO public.questions VALUES (4217, 55, 'g10-alg-sys-q2-07', 2, 7, 'medium', 'open', 'Teatrda böyük bileti 4 manat, uşaq bileti 2 manatdır. Cəmi 92 bilet satıldı və 312 manat gəlir əldə edildi. Böyüklər üçün bilet uşaqlar üçün olandan neçə ədəd çox (mənfi — az) satılıb?', NULL, NULL, NULL, NULL, '36', 'x + y = 92, 4x + 2y = 312 ⇒ x = 64, y = 28.');
INSERT INTO public.questions VALUES (4218, 55, 'g10-alg-sys-q2-08', 2, 8, 'hard', 'single', 'x + y = −8 və xy = −6 olarsa, x⁴ + y⁴ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "4024", "B": "5776", "C": "5848", "D": "5704", "E": "5740"}'::jsonb, 'D', NULL, 'x² + y² = 76; x⁴ + y⁴ = (x² + y²)² − 2(xy)² = 5776 − 72 = 5704.');
