INSERT INTO public.questions VALUES (4247, 55, 'g10-alg-sys-q3-17', 3, 17, 'medium', 'single', 'Teatrda böyük bileti 6 manat, uşaq bileti 5 manatdır. Cəmi 76 bilet satıldı və 430 manat gəlir əldə edildi. Böyüklər üçün neçə bilet satılıb?', NULL, NULL, '{"A": "48", "B": "52", "C": "26", "D": "50", "E": "51"}'::jsonb, 'D', NULL, 'x + y = 76, 6x + 5y = 430 ⇒ x = 50, y = 26.');
