INSERT INTO public.questions VALUES (4250, 55, 'g10-alg-sys-q3-20', 3, 20, 'medium', 'single', 'x + y = −9 və xy = −12 olarsa, x³ + y³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1053", "B": "−837", "C": "−729", "D": "−1052", "E": "−405"}'::jsonb, 'A', NULL, 'x³ + y³ = (x + y)³ − 3xy(x + y) = (−729) − 324 = −1053.');
INSERT INTO public.questions VALUES (4251, 56, 'g10-alg-quad-q1-01', 1, 1, 'hard', 'single', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 1)x + m² − 4 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−1", "B": "−2", "C": "−3", "D": "−4", "E": "0"}'::jsonb, 'B', NULL, 'D/4 = (m + 1)² − (m² − 4) = 2m + 5 > 0 ⇒ m > −5/2. Ən kiçik tam qiymət: −2.');
INSERT INTO public.questions VALUES (4252, 56, 'g10-alg-quad-q1-02', 1, 2, 'hard', 'single', 'm-in hansı ən böyük tam qiymətində x² − 2(m − 5)x + m² + 17 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "1", "B": "2", "C": "0", "D": "−1", "E": "−2"}'::jsonb, 'C', NULL, 'D/4 = (m − 5)² − (m² + 17) = −10m + 8 > 0 ⇒ m < 4/5. Ən böyük tam qiymət: 0.');
INSERT INTO public.questions VALUES (4253, 56, 'g10-alg-quad-q1-03', 1, 3, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² + 12x − 6 = 0 tənliyinin kökləridir. x₁³ + x₂³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−270", "B": "−234", "C": "270", "D": "−162", "E": "−216"}'::jsonb, 'A', NULL, 'Viyet teoremi: x₁ + x₂ = −6, x₁x₂ = −3. x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂) = −216 − 54 = −270.');
INSERT INTO public.questions VALUES (4254, 56, 'g10-alg-quad-q1-04', 1, 4, 'hard', 'single', 'x² − mx + 12 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "12", "B": "9", "C": "7", "D": "−8", "E": "8"}'::jsonb, 'E', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 12 ⇒ x₂² = 4, x₂ = 2, x₁ = 6. m = x₁ + x₂ = 8.');
INSERT INTO public.questions VALUES (4255, 56, 'g10-alg-quad-q1-05', 1, 5, 'hard', 'single', 'x² − mx + 6 = 0 tənliyinin köklərindən biri digərindən 3/2 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "6", "B": "4", "C": "10", "D": "5", "E": "−5"}'::jsonb, 'D', NULL, 'x₁ = (3/2)·x₂, x₁x₂ = (3/2)·x₂² = 6 ⇒ x₂² = 4, x₂ = 2, x₁ = 3. m = x₁ + x₂ = 5.');
INSERT INTO public.questions VALUES (4256, 56, 'g10-alg-quad-q1-06', 1, 6, 'hard', 'single', 'x² − 8x + 3 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 1 və x₂ + 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "11", "B": "12", "C": "−4", "D": "13", "E": "4"}'::jsonb, 'B', NULL, 'q = (x₁ + 1)(x₂ + 1) = x₁x₂ + 1(x₁ + x₂) + 1 = 3 + 8 + 1 = 12.');
INSERT INTO public.questions VALUES (4257, 56, 'g10-alg-quad-q1-07', 1, 7, 'hard', 'open', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 1)x + m² + 17 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, NULL, NULL, '9', 'D/4 = (m + 1)² − (m² + 17) = 2m − 16 > 0 ⇒ m > 8. Ən kiçik tam qiymət: 9.');
INSERT INTO public.questions VALUES (4258, 56, 'g10-alg-quad-q1-08', 1, 8, 'hard', 'single', 'x² − 11x − 15 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 4 və x₂ − 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−43", "B": "−59", "C": "45", "D": "1", "E": "−42"}'::jsonb, 'A', NULL, 'q = (x₁ − 4)(x₂ − 4) = x₁x₂ − 4(x₁ + x₂) + 16 = −15 − 44 + 16 = −43.');
INSERT INTO public.questions VALUES (4259, 56, 'g10-alg-quad-q1-09', 1, 9, 'medium', 'single', '3x² + 54x + 135 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "14", "B": "13", "C": "11", "D": "15", "E": "12"}'::jsonb, 'B', NULL, 'Köklər −15 və −3; a > 0, həllər köklər arasındadır. Tam həllər: 13.');
INSERT INTO public.questions VALUES (4260, 56, 'g10-alg-quad-q1-10', 1, 10, 'medium', 'single', 'x² + 5x − 66 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "16", "B": "20", "C": "18", "D": "19", "E": "17"}'::jsonb, 'C', NULL, 'Köklər −11 və 6; a > 0, həllər köklər arasındadır. Tam həllər: 18.');
INSERT INTO public.questions VALUES (4261, 56, 'g10-alg-quad-q1-11', 1, 11, 'hard', 'single', 'm-in hansı ən böyük tam qiymətində x² − 2(m − 1)x + m² − 5 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "0", "B": "2", "C": "4", "D": "1", "E": "3"}'::jsonb, 'B', NULL, 'D/4 = (m − 1)² − (m² − 5) = −2m + 6 > 0 ⇒ m < 3. Ən böyük tam qiymət: 2.');
INSERT INTO public.questions VALUES (4262, 56, 'g10-alg-quad-q1-12', 1, 12, 'medium', 'single', '3x² − 84x + 396 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "17", "B": "16", "C": "15", "D": "18", "E": "19"}'::jsonb, 'A', NULL, 'Köklər 6 və 22; a > 0, həllər köklər arasındadır. Tam həllər: 17.');
INSERT INTO public.questions VALUES (4263, 56, 'g10-alg-quad-q1-13', 1, 13, 'hard', 'single', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 6)x + m² − 5 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−2", "B": "−5", "C": "−1", "D": "−3", "E": "−4"}'::jsonb, 'D', NULL, 'D/4 = (m + 6)² − (m² − 5) = 12m + 41 > 0 ⇒ m > −41/12. Ən kiçik tam qiymət: −3.');
INSERT INTO public.questions VALUES (4264, 56, 'g10-alg-quad-q1-14', 1, 14, 'medium', 'open', 'x₁ və x₂ ədədləri x² + 12x + 6 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '132', 'Viyet teoremi: x₁ + x₂ = −12, x₁x₂ = 6. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 144 − 12 = 132.');
INSERT INTO public.questions VALUES (4265, 56, 'g10-alg-quad-q1-15', 1, 15, 'medium', 'single', '3x² + 45x + 108 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "11", "B": "12", "C": "8", "D": "9", "E": "10"}'::jsonb, 'E', NULL, 'Köklər −12 və −3; a > 0, həllər köklər arasındadır. Tam həllər: 10.');
INSERT INTO public.questions VALUES (4266, 56, 'g10-alg-quad-q1-16', 1, 16, 'hard', 'single', 'x² + 9x − 4 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 4 və x₂ − 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "12", "B": "48", "C": "49", "D": "32", "E": "−24"}'::jsonb, 'B', NULL, 'q = (x₁ − 4)(x₂ − 4) = x₁x₂ − 4(x₁ + x₂) + 16 = −4 + 36 + 16 = 48.');
INSERT INTO public.questions VALUES (4267, 56, 'g10-alg-quad-q1-17', 1, 17, 'medium', 'single', 'x₁ və x₂ ədədləri 2x² + 12x − 10 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "26", "B": "−46", "C": "36", "D": "41", "E": "46"}'::jsonb, 'E', NULL, 'Viyet teoremi: x₁ + x₂ = −6, x₁x₂ = −5. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 36 − (−10) = 46.');
INSERT INTO public.questions VALUES (4268, 56, 'g10-alg-quad-q1-18', 1, 18, 'medium', 'single', '3x² + 19x + 16 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "3", "B": "7", "C": "4", "D": "5", "E": "6"}'::jsonb, 'D', NULL, 'Köklər −16/3 və −1; a > 0, həllər köklər arasındadır. Tam həllər: 5.');
INSERT INTO public.questions VALUES (4269, 56, 'g10-alg-quad-q1-19', 1, 19, 'hard', 'single', 'x² + 8x − 8 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 3 və x₂ − 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "16", "B": "−23", "C": "25", "D": "1", "E": "26"}'::jsonb, 'C', NULL, 'q = (x₁ − 3)(x₂ − 3) = x₁x₂ − 3(x₁ + x₂) + 9 = −8 + 24 + 9 = 25.');
INSERT INTO public.questions VALUES (4270, 56, 'g10-alg-quad-q1-20', 1, 20, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² − 5x − 15 = 0 tənliyinin kökləridir. 1/x₁² + 1/x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "45/17", "B": "17/45", "C": "−7/45", "D": "−17/6", "E": "1/9"}'::jsonb, 'B', NULL, 'Viyet teoremi: x₁ + x₂ = 5/2, x₁x₂ = −15/2. 1/x₁² + 1/x₂² = (x₁² + x₂²)/(x₁x₂)² = (85/4)/225/4 = 17/45.');
INSERT INTO public.questions VALUES (4271, 56, 'g10-alg-quad-q2-01', 2, 1, 'hard', 'single', 'm-in hansı ən böyük tam qiymətində x² − 2(m − 4)x + m² − 8 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "2", "B": "3", "C": "1", "D": "4", "E": "0"}'::jsonb, 'A', NULL, 'D/4 = (m − 4)² − (m² − 8) = −8m + 24 > 0 ⇒ m < 3. Ən böyük tam qiymət: 2.');
INSERT INTO public.questions VALUES (4272, 56, 'g10-alg-quad-q2-02', 2, 2, 'medium', 'single', 'x₁ və x₂ ədədləri 2x² − 11x + 3 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−109/4", "B": "115/4", "C": "109/4", "D": "121/4", "E": "133/4"}'::jsonb, 'C', NULL, 'Viyet teoremi: x₁ + x₂ = 11/2, x₁x₂ = 3/2. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 121/4 − 3 = 109/4.');
INSERT INTO public.questions VALUES (4273, 56, 'g10-alg-quad-q2-03', 2, 3, 'medium', 'single', 'x₁ və x₂ ədədləri 3x² + 12x − 12 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "20", "B": "16", "C": "−24", "D": "24", "E": "8"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = −4, x₁x₂ = −4. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 16 − (−8) = 24.');
INSERT INTO public.questions VALUES (4274, 56, 'g10-alg-quad-q2-04', 2, 4, 'hard', 'single', 'x² − 5x − 11 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 3 və x₂ − 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−17", "B": "−16", "C": "13", "D": "−26", "E": "−2"}'::jsonb, 'A', NULL, 'q = (x₁ − 3)(x₂ − 3) = x₁x₂ − 3(x₁ + x₂) + 9 = −11 − 15 + 9 = −17.');
INSERT INTO public.questions VALUES (4275, 56, 'g10-alg-quad-q2-05', 2, 5, 'hard', 'single', 'x₁ və x₂ ədədləri x² + 4x − 13 = 0 tənliyinin kökləridir. 1/x₁² + 1/x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "169/42", "B": "−42/13", "C": "−10/169", "D": "42/169", "E": "16/169"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = −4, x₁x₂ = −13. 1/x₁² + 1/x₂² = (x₁² + x₂²)/(x₁x₂)² = (42)/169 = 42/169.');
INSERT INTO public.questions VALUES (4276, 56, 'g10-alg-quad-q2-06', 2, 6, 'hard', 'single', 'x² + 5x − 11 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 4 və x₂ + 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "5", "B": "−15", "C": "−14", "D": "−31", "E": "25"}'::jsonb, 'B', NULL, 'q = (x₁ + 4)(x₂ + 4) = x₁x₂ + 4(x₁ + x₂) + 16 = −11 − 20 + 16 = −15.');
INSERT INTO public.questions VALUES (4277, 56, 'g10-alg-quad-q2-07', 2, 7, 'hard', 'open', 'x² − mx + 36 = 0 tənliyinin köklərindən biri digərindən 4 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, NULL, NULL, '15', 'x₁ = 4x₂, x₁x₂ = 4x₂² = 36 ⇒ x₂² = 9, x₂ = 3, x₁ = 12. m = x₁ + x₂ = 15.');
INSERT INTO public.questions VALUES (4278, 56, 'g10-alg-quad-q2-08', 2, 8, 'hard', 'single', 'x² + 3x − 10 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 4 və x₂ + 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−6", "B": "−22", "C": "18", "D": "−5", "E": "6"}'::jsonb, 'A', NULL, 'q = (x₁ + 4)(x₂ + 4) = x₁x₂ + 4(x₁ + x₂) + 16 = −10 − 12 + 16 = −6.');
INSERT INTO public.questions VALUES (4279, 56, 'g10-alg-quad-q2-09', 2, 9, 'medium', 'single', 'x² − 38x + 345 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "10", "B": "8", "C": "9", "D": "11", "E": "7"}'::jsonb, 'C', NULL, 'Köklər 15 və 23; a > 0, həllər köklər arasındadır. Tam həllər: 9.');
INSERT INTO public.questions VALUES (4280, 56, 'g10-alg-quad-q2-10', 2, 10, 'hard', 'single', 'x² − 8x + 9 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 1 və x₂ − 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "18", "B": "3", "C": "1", "D": "2", "E": "10"}'::jsonb, 'D', NULL, 'q = (x₁ − 1)(x₂ − 1) = x₁x₂ − 1(x₁ + x₂) + 1 = 9 − 8 + 1 = 2.');
INSERT INTO public.questions VALUES (4281, 56, 'g10-alg-quad-q2-11', 2, 11, 'medium', 'single', 'x² + 19x − 20 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "22", "B": "21", "C": "23", "D": "24", "E": "20"}'::jsonb, 'A', NULL, 'Köklər −20 və 1; a > 0, həllər köklər arasındadır. Tam həllər: 22.');
INSERT INTO public.questions VALUES (4282, 56, 'g10-alg-quad-q2-12', 2, 12, 'hard', 'single', 'm-in hansı ən böyük tam qiymətində x² − 2(m − 2)x + m² + 5 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−3", "B": "−1", "C": "−2", "D": "0", "E": "1"}'::jsonb, 'B', NULL, 'D/4 = (m − 2)² − (m² + 5) = −4m − 1 > 0 ⇒ m < −1/4. Ən böyük tam qiymət: −1.');
INSERT INTO public.questions VALUES (4283, 56, 'g10-alg-quad-q2-13', 2, 13, 'hard', 'single', 'x² − mx + 27 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "27", "B": "−12", "C": "13", "D": "12", "E": "11"}'::jsonb, 'D', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 27 ⇒ x₂² = 9, x₂ = 3, x₁ = 9. m = x₁ + x₂ = 12.');
INSERT INTO public.questions VALUES (4284, 56, 'g10-alg-quad-q2-14', 2, 14, 'medium', 'open', 'x₁ və x₂ ədədləri 3x² + 11x − 13 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '199/9', 'Viyet teoremi: x₁ + x₂ = −11/3, x₁x₂ = −13/3. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 121/9 − (−26/3) = 199/9.');
INSERT INTO public.questions VALUES (4285, 56, 'g10-alg-quad-q2-15', 2, 15, 'medium', 'single', 'x² − 28x + 171 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "12", "B": "13", "C": "11", "D": "9", "E": "10"}'::jsonb, 'C', NULL, 'Köklər 9 və 19; a > 0, həllər köklər arasındadır. Tam həllər: 11.');
INSERT INTO public.questions VALUES (4286, 56, 'g10-alg-quad-q2-16', 2, 16, 'hard', 'single', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 4)x + m² + 17 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−1", "B": "1", "C": "0", "D": "2", "E": "3"}'::jsonb, 'B', NULL, 'D/4 = (m + 4)² − (m² + 17) = 8m − 1 > 0 ⇒ m > 1/8. Ən kiçik tam qiymət: 1.');
INSERT INTO public.questions VALUES (4287, 56, 'g10-alg-quad-q2-17', 2, 17, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² + 8x − 3 = 0 tənliyinin kökləridir. x₁³ + x₂³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−46", "B": "−82", "C": "82", "D": "−70", "E": "−64"}'::jsonb, 'B', NULL, 'Viyet teoremi: x₁ + x₂ = −4, x₁x₂ = −3/2. x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂) = −64 − 18 = −82.');
INSERT INTO public.questions VALUES (4288, 56, 'g10-alg-quad-q2-18', 2, 18, 'hard', 'single', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 3)x + m² + 2 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−3", "B": "−1", "C": "1", "D": "0", "E": "−2"}'::jsonb, 'B', NULL, 'D/4 = (m + 3)² − (m² + 2) = 6m + 7 > 0 ⇒ m > −7/6. Ən kiçik tam qiymət: −1.');
INSERT INTO public.questions VALUES (4289, 56, 'g10-alg-quad-q2-19', 2, 19, 'medium', 'single', '2x² − 10x < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "4", "B": "3", "C": "5", "D": "6", "E": "2"}'::jsonb, 'A', NULL, 'Köklər 0 və 5; a > 0, həllər köklər arasındadır. Tam həllər: 4.');
INSERT INTO public.questions VALUES (4290, 56, 'g10-alg-quad-q2-20', 2, 20, 'medium', 'single', '2x² − 50x + 200 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "17", "B": "15", "C": "18", "D": "16", "E": "14"}'::jsonb, 'D', NULL, 'Köklər 5 və 20; a > 0, həllər köklər arasındadır. Tam həllər: 16.');
INSERT INTO public.questions VALUES (4291, 56, 'g10-alg-quad-q3-01', 3, 1, 'medium', 'single', '3x² + 120x + 1197 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "−1", "B": "1", "C": "3", "D": "0", "E": "2"}'::jsonb, 'B', NULL, 'Köklər −21 və −19; a > 0, həllər köklər arasındadır. Tam həllər: 1.');
INSERT INTO public.questions VALUES (4292, 56, 'g10-alg-quad-q3-02', 3, 2, 'hard', 'single', 'x² − mx + 54 = 0 tənliyinin köklərindən biri digərindən 3/2 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "15", "B": "16", "C": "14", "D": "−15", "E": "54"}'::jsonb, 'A', NULL, 'x₁ = (3/2)·x₂, x₁x₂ = (3/2)·x₂² = 54 ⇒ x₂² = 36, x₂ = 6, x₁ = 9. m = x₁ + x₂ = 15.');
INSERT INTO public.questions VALUES (4293, 56, 'g10-alg-quad-q3-03', 3, 3, 'hard', 'single', 'x² − 9x − 12 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 4 və x₂ + 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "40", "B": "4", "C": "24", "D": "−32", "E": "41"}'::jsonb, 'A', NULL, 'q = (x₁ + 4)(x₂ + 4) = x₁x₂ + 4(x₁ + x₂) + 16 = −12 + 36 + 16 = 40.');
INSERT INTO public.questions VALUES (4294, 56, 'g10-alg-quad-q3-04', 3, 4, 'medium', 'single', '3x² − x − 102 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "12", "B": "11", "C": "9", "D": "10", "E": "13"}'::jsonb, 'B', NULL, 'Köklər −17/3 və 6; a > 0, həllər köklər arasındadır. Tam həllər: 11.');
INSERT INTO public.questions VALUES (4295, 56, 'g10-alg-quad-q3-05', 3, 5, 'medium', 'single', 'x₁ və x₂ ədədləri 3x² − 7x − 1 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "49/9", "B": "55/9", "C": "52/9", "D": "43/9", "E": "−55/9"}'::jsonb, 'B', NULL, 'Viyet teoremi: x₁ + x₂ = 7/3, x₁x₂ = −1/3. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 49/9 − (−2/3) = 55/9.');
INSERT INTO public.questions VALUES (4296, 56, 'g10-alg-quad-q3-06', 3, 6, 'hard', 'single', 'x² + 12x − 10 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 4 və x₂ − 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "54", "B": "55", "C": "38", "D": "−42", "E": "6"}'::jsonb, 'A', NULL, 'q = (x₁ − 4)(x₂ − 4) = x₁x₂ − 4(x₁ + x₂) + 16 = −10 + 48 + 16 = 54.');
INSERT INTO public.questions VALUES (4297, 56, 'g10-alg-quad-q3-07', 3, 7, 'hard', 'open', 'm-in hansı ən böyük tam qiymətində x² − 2(m − 1)x + m² + 12 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, NULL, NULL, '−6', 'D/4 = (m − 1)² − (m² + 12) = −2m − 11 > 0 ⇒ m < −11/2. Ən böyük tam qiymət: −6.');
INSERT INTO public.questions VALUES (4298, 56, 'g10-alg-quad-q3-08', 3, 8, 'hard', 'single', 'x₁ və x₂ ədədləri −x² − 12x + 7 = 0 tənliyinin kökləridir. x₁³ + x₂³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1728", "B": "−1812", "C": "1980", "D": "−1980", "E": "−1476"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = −12, x₁x₂ = −7. x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂) = −1728 − 252 = −1980.');
INSERT INTO public.questions VALUES (4299, 56, 'g10-alg-quad-q3-09', 3, 9, 'hard', 'single', 'x² − mx + 48 = 0 tənliyinin köklərindən biri digərindən 3 dəfə böyükdür. m-in müsbət qiymətini tapın.', NULL, NULL, '{"A": "17", "B": "48", "C": "15", "D": "16", "E": "−16"}'::jsonb, 'D', NULL, 'x₁ = 3x₂, x₁x₂ = 3x₂² = 48 ⇒ x₂² = 16, x₂ = 4, x₁ = 12. m = x₁ + x₂ = 16.');
INSERT INTO public.questions VALUES (4300, 56, 'g10-alg-quad-q3-10', 3, 10, 'hard', 'single', 'x² − 4x − 11 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 3 və x₂ + 3 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−14", "B": "−2", "C": "11", "D": "1", "E": "10"}'::jsonb, 'E', NULL, 'q = (x₁ + 3)(x₂ + 3) = x₁x₂ + 3(x₁ + x₂) + 9 = −11 + 12 + 9 = 10.');
INSERT INTO public.questions VALUES (4301, 56, 'g10-alg-quad-q3-11', 3, 11, 'hard', 'single', 'x² − 4x + 2 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ + 1 və x₂ + 1 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "8", "B": "3", "C": "6", "D": "−1", "E": "7"}'::jsonb, 'E', NULL, 'q = (x₁ + 1)(x₂ + 1) = x₁x₂ + 1(x₁ + x₂) + 1 = 2 + 4 + 1 = 7.');
INSERT INTO public.questions VALUES (4302, 56, 'g10-alg-quad-q3-12', 3, 12, 'hard', 'single', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 5)x + m² − 7 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−5", "B": "−3", "C": "−2", "D": "−1", "E": "−4"}'::jsonb, 'B', NULL, 'D/4 = (m + 5)² − (m² − 7) = 10m + 32 > 0 ⇒ m > −16/5. Ən kiçik tam qiymət: −3.');
INSERT INTO public.questions VALUES (4303, 56, 'g10-alg-quad-q3-13', 3, 13, 'hard', 'single', 'm-in hansı ən böyük tam qiymətində x² − 2(m − 1)x + m² + 7 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "−2", "B": "−6", "C": "−3", "D": "−4", "E": "−5"}'::jsonb, 'D', NULL, 'D/4 = (m − 1)² − (m² + 7) = −2m − 6 > 0 ⇒ m < −3. Ən böyük tam qiymət: −4.');
INSERT INTO public.questions VALUES (4304, 56, 'g10-alg-quad-q3-14', 3, 14, 'medium', 'open', 'x₁ və x₂ ədədləri 2x² + 8x − 11 = 0 tənliyinin kökləridir. x₁² + x₂² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '27', 'Viyet teoremi: x₁ + x₂ = −4, x₁x₂ = −11/2. x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 16 − (−11) = 27.');
INSERT INTO public.questions VALUES (4305, 56, 'g10-alg-quad-q3-15', 3, 15, 'hard', 'single', 'm-in hansı ən kiçik tam qiymətində x² − 2(m + 3)x + m² − 8 = 0 tənliyinin iki müxtəlif həqiqi kökü var?', NULL, NULL, '{"A": "0", "B": "−2", "C": "−4", "D": "−1", "E": "−3"}'::jsonb, 'B', NULL, 'D/4 = (m + 3)² − (m² − 8) = 6m + 17 > 0 ⇒ m > −17/6. Ən kiçik tam qiymət: −2.');
INSERT INTO public.questions VALUES (4306, 56, 'g10-alg-quad-q3-16', 3, 16, 'hard', 'single', 'x₁ və x₂ ədədləri 3x² − 5x + 1 = 0 tənliyinin kökləridir. x₁³ + x₂³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "110/27", "B": "170/27", "C": "−80/27", "D": "80/27", "E": "125/27"}'::jsonb, 'D', NULL, 'Viyet teoremi: x₁ + x₂ = 5/3, x₁x₂ = 1/3. x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂) = 125/27 − 5/3 = 80/27.');
INSERT INTO public.questions VALUES (4307, 56, 'g10-alg-quad-q3-17', 3, 17, 'medium', 'single', '3x² + 60x + 288 < 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "2", "B": "3", "C": "1", "D": "5", "E": "4"}'::jsonb, 'B', NULL, 'Köklər −12 və −8; a > 0, həllər köklər arasındadır. Tam həllər: 3.');
INSERT INTO public.questions VALUES (4308, 56, 'g10-alg-quad-q3-18', 3, 18, 'medium', 'single', '3x² − 37x + 70 ≤ 0 bərabərsizliyini ödəyən tam ədədlərin sayını tapın.', NULL, NULL, '{"A": "8", "B": "9", "C": "7", "D": "6", "E": "10"}'::jsonb, 'A', NULL, 'Köklər 7/3 və 10; a > 0, həllər köklər arasındadır. Tam həllər: 8.');
INSERT INTO public.questions VALUES (4309, 56, 'g10-alg-quad-q3-19', 3, 19, 'hard', 'single', 'x² − 9x − 6 = 0 tənliyinin kökləri x₁ və x₂-dir. Kökləri x₁ − 4 və x₂ − 4 olan x² + px + q = 0 tənliyində q-nü tapın.', NULL, NULL, '{"A": "−42", "B": "−25", "C": "−26", "D": "10", "E": "46"}'::jsonb, 'C', NULL, 'q = (x₁ − 4)(x₂ − 4) = x₁x₂ − 4(x₁ + x₂) + 16 = −6 − 36 + 16 = −26.');
INSERT INTO public.questions VALUES (4310, 56, 'g10-alg-quad-q3-20', 3, 20, 'hard', 'single', 'x₁ və x₂ ədədləri 2x² − 11x − 3 = 0 tənliyinin kökləridir. x₁³ + x₂³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1529/8", "B": "1397/8", "C": "1529/8", "D": "1133/8", "E": "1331/8"}'::jsonb, 'C', NULL, 'Viyet teoremi: x₁ + x₂ = 11/2, x₁x₂ = −3/2. x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂) = 1331/8 − (−99/4) = 1529/8.');
INSERT INTO public.questions VALUES (4311, 57, 'g10-alg-prog-q1-01', 1, 1, 'hard', 'single', 'Sonsuz azalan həndəsi silsilənin hədlərinin cəmi −33/5, hədlərin kvadratlarının cəmi isə 1089/5-dir. Silsilənin birinci həddini tapın.', NULL, NULL, '{"A": "−11", "B": "−10", "C": "−22", "D": "11", "E": "5/3"}'::jsonb, 'A', NULL, 'b₁/(1 − q) = −33/5, b₁²/(1 − q²) = 1089/5. Bölsək: b₁/(1 + q) = −33. İki tənlikdən q = −2/3, b₁ = −11.');
INSERT INTO public.questions VALUES (4312, 57, 'g10-alg-prog-q1-02', 1, 2, 'hard', 'single', 'Həndəsi silsilədə b₃ = 54 və b₅ = 486 (q < 0). İlk 7 həddin cəmini tapın.', NULL, NULL, '{"A": "3288", "B": "−1092", "C": "−3282", "D": "3282", "E": "−14214"}'::jsonb, 'D', NULL, 'q^2 = b₅/b₃ = 9 ⇒ q = −3, b₁ = 6. S₇ = b₁(qⁿ − 1)/(q − 1) = 3282.');
INSERT INTO public.questions VALUES (4313, 57, 'g10-alg-prog-q1-03', 1, 3, 'medium', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 6 və a₇ = 94 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "8", "B": "6", "C": "10", "D": "7", "E": "9"}'::jsonb, 'A', NULL, 'a₂ = x olsun: a₃ = 6 + x, a₄ = 6 + 2x, … a₇ = 5·6 + 8x = 94 ⇒ x = 8.');
INSERT INTO public.questions VALUES (4314, 57, 'g10-alg-prog-q1-04', 1, 4, 'medium', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 7 və a₈ = 69 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "0", "B": "2", "C": "1", "D": "−1", "E": "3"}'::jsonb, 'C', NULL, 'a₂ = x olsun: a₃ = 7 + x, a₄ = 7 + 2x, … a₈ = 8·7 + 13x = 69 ⇒ x = 1.');
INSERT INTO public.questions VALUES (4315, 57, 'g10-alg-prog-q1-05', 1, 5, 'hard', 'single', 'Sonsuz azalan həndəsi silsilənin hədlərinin cəmi −33/2, hədlərin kvadratlarının cəmi isə 1089/8-dir. Silsilənin vuruğunu (q) tapın.', NULL, NULL, '{"A": "−1/3", "B": "1/9", "C": "2/3", "D": "1/3", "E": "4/3"}'::jsonb, 'D', NULL, 'b₁/(1 − q) = −33/2, b₁²/(1 − q²) = 1089/8. Bölsək: b₁/(1 + q) = −33/4. İki tənlikdən q = 1/3, b₁ = −11.');
INSERT INTO public.questions VALUES (4316, 57, 'g10-alg-prog-q1-06', 1, 6, 'medium', 'single', 'Ədədi silsilədə a₅ + a₁₁ = 12 və a₇ = 7 olarsa, ilk 12 həddin cəmini tapın.', NULL, NULL, '{"A": "90", "B": "92", "C": "102", "D": "96", "E": "78"}'::jsonb, 'A', NULL, '2a₁ + 14d = 12, a₁ + 6d = 7 ⇒ a₁ = 13, d = −1. S₁₂ = (2a₁ + 11d)·12/2 = 90.');
INSERT INTO public.questions VALUES (4317, 57, 'g10-alg-prog-q1-07', 1, 7, 'hard', 'single', 'Həndəsi silsilədə b₃ = −1/4 və b₆ = 1/32. İlk 8 həddin cəmini tapın.', NULL, NULL, '{"A": "−43/64", "B": "85/128", "C": "−85/128", "D": "−213/128", "E": "−173/256"}'::jsonb, 'C', NULL, 'q^3 = b₆/b₃ = −1/8 ⇒ q = −1/2, b₁ = −1. S₈ = b₁(qⁿ − 1)/(q − 1) = −85/128.');
INSERT INTO public.questions VALUES (4318, 57, 'g10-alg-prog-q1-08', 1, 8, 'medium', 'single', 'Ədədi silsilədə a₁₄ + a₇ = 105 və a₈ = 35 olarsa, ilk 30 həddin cəmini tapın.', NULL, NULL, '{"A": "2814", "B": "2415", "C": "2835", "D": "2625", "E": "2520"}'::jsonb, 'D', NULL, '2a₁ + 19d = 105, a₁ + 7d = 35 ⇒ a₁ = −14, d = 7. S₃₀ = (2a₁ + 29d)·30/2 = 2625.');
INSERT INTO public.questions VALUES (4319, 57, 'g10-alg-prog-q1-09', 1, 9, 'hard', 'single', 'Ardıcıllıq a₁ = −1 və aₙ₊₁ = 3·aₙ − 5 qaydası ilə verilib. a₅ həddini tapın.', NULL, NULL, '{"A": "−848", "B": "−92", "C": "−276", "D": "−281", "E": "−286"}'::jsonb, 'D', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + −5/2 = (a₁ + −5/2)·3ⁿ⁻¹ ilə): a₅ = −281.');
INSERT INTO public.questions VALUES (4320, 57, 'g10-alg-prog-q1-10', 1, 10, 'hard', 'single', 'Ardıcıllıq a₁ = 1 və aₙ₊₁ = 2·aₙ + 5 qaydası ilə verilib. a₇ həddini tapın.', NULL, NULL, '{"A": "379", "B": "187", "C": "374", "D": "384", "E": "763"}'::jsonb, 'A', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + 5 = (a₁ + 5)·2ⁿ⁻¹ ilə): a₇ = 379.');
INSERT INTO public.questions VALUES (4321, 57, 'g10-alg-prog-q1-11', 1, 11, 'hard', 'single', 'aₙ = n² − 12n + 1 ardıcıllığının neçə həddi mənfidir?', NULL, NULL, '{"A": "11", "B": "12", "C": "10", "D": "13", "E": "9"}'::jsonb, 'A', NULL, 'n² − 12n + 1 < 0 ⇒ 0,08 < n < 11,92. Natural n-lər: 11.');
INSERT INTO public.questions VALUES (4322, 57, 'g10-alg-prog-q1-12', 1, 12, 'medium', 'single', 'Ədədi silsilədə a₁₁ + a₂ = 112 və a₁₉ = 131 olarsa, ilk 14 həddin cəmini tapın.', NULL, NULL, '{"A": "969", "B": "868", "C": "952", "D": "826", "E": "784"}'::jsonb, 'B', NULL, '2a₁ + 11d = 112, a₁ + 18d = 131 ⇒ a₁ = 23, d = 6. S₁₄ = (2a₁ + 13d)·14/2 = 868.');
INSERT INTO public.questions VALUES (4323, 57, 'g10-alg-prog-q1-13', 1, 13, 'hard', 'single', 'Ardıcıllıq a₁ = 0 və aₙ₊₁ = (−2)·aₙ + 6 qaydası ilə verilib. a₅ həddini tapın.', NULL, NULL, '{"A": "18", "B": "−30", "C": "−36", "D": "−24", "E": "66"}'::jsonb, 'B', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + −2 = (a₁ + −2)·(−2)ⁿ⁻¹ ilə): a₅ = −30.');
INSERT INTO public.questions VALUES (4324, 57, 'g10-alg-prog-q1-14', 1, 14, 'medium', 'open', 'Ədədi silsilədə a₇ + a₈ = −50 və a₁₀ = −30 olarsa, ilk 13 həddin cəmini tapın.', NULL, NULL, NULL, NULL, '−312', '2a₁ + 13d = −50, a₁ + 9d = −30 ⇒ a₁ = −12, d = −2. S₁₃ = (2a₁ + 12d)·13/2 = −312.');
INSERT INTO public.questions VALUES (4325, 57, 'g10-alg-prog-q1-15', 1, 15, 'hard', 'single', 'aₙ = n² − 10n + 21 ardıcıllığının ən kiçik həddini tapın.', NULL, NULL, '{"A": "−4", "B": "−2", "C": "−5", "D": "−3", "E": "−6"}'::jsonb, 'A', NULL, 'Parabolanın təpəsi n = 5. Ən yaxın natural n: 5. Ən kiçik hədd: −4.');
INSERT INTO public.questions VALUES (4326, 57, 'g10-alg-prog-q1-16', 1, 16, 'hard', 'single', 'aₙ = n² − 19n + 2 ardıcıllığının neçə həddi mənfidir?', NULL, NULL, '{"A": "16", "B": "17", "C": "18", "D": "20", "E": "19"}'::jsonb, 'C', NULL, 'n² − 19n + 2 < 0 ⇒ 0,11 < n < 18,89. Natural n-lər: 18.');
INSERT INTO public.questions VALUES (4327, 57, 'g10-alg-prog-q1-17', 1, 17, 'hard', 'single', 'aₙ = n² − 26n + 17 ardıcıllığının ən kiçik həddini tapın.', NULL, NULL, '{"A": "−152", "B": "−153", "C": "−150", "D": "−154", "E": "−151"}'::jsonb, 'A', NULL, 'Parabolanın təpəsi n = 13. Ən yaxın natural n: 13. Ən kiçik hədd: −152.');
INSERT INTO public.questions VALUES (4328, 57, 'g10-alg-prog-q1-18', 1, 18, 'hard', 'single', 'Həndəsi silsilədə b₂ = −1 və b₄ = −1/4 (q < 0). İlk 8 həddin cəmini tapın.', NULL, NULL, '{"A": "213/64", "B": "−85/64", "C": "173/128", "D": "85/64", "E": "43/32"}'::jsonb, 'D', NULL, 'q^2 = b₄/b₂ = 1/4 ⇒ q = −1/2, b₁ = 2. S₈ = b₁(qⁿ − 1)/(q − 1) = 85/64.');
INSERT INTO public.questions VALUES (4329, 57, 'g10-alg-prog-q1-19', 1, 19, 'hard', 'single', 'Həndəsi silsilədə b₃ = 4 və b₅ = 16 (q > 0). İlk 7 həddin cəmini tapın.', NULL, NULL, '{"A": "−127", "B": "128", "C": "191", "D": "127", "E": "63"}'::jsonb, 'D', NULL, 'q^2 = b₅/b₃ = 4 ⇒ q = 2, b₁ = 1. S₇ = b₁(qⁿ − 1)/(q − 1) = 127.');
INSERT INTO public.questions VALUES (4330, 57, 'g10-alg-prog-q1-20', 1, 20, 'hard', 'single', 'Sonsuz azalan həndəsi silsilənin hədlərinin cəmi −4, hədlərin kvadratlarının cəmi isə 48/5-dir. Silsilənin birinci həddini tapın.', NULL, NULL, '{"A": "3", "B": "−3", "C": "−6", "D": "−2", "E": "3/4"}'::jsonb, 'B', NULL, 'b₁/(1 − q) = −4, b₁²/(1 − q²) = 48/5. Bölsək: b₁/(1 + q) = −12/5. İki tənlikdən q = 1/4, b₁ = −3.');
INSERT INTO public.questions VALUES (4331, 57, 'g10-alg-prog-q2-01', 2, 1, 'hard', 'single', 'Həndəsi silsilədə b₂ = −6 və b₆ = −486 (q < 0). İlk 6 həddin cəmini tapın.', NULL, NULL, '{"A": "−362", "B": "−364", "C": "122", "D": "1580", "E": "364"}'::jsonb, 'B', NULL, 'q^4 = b₆/b₂ = 81 ⇒ q = −3, b₁ = 2. S₆ = b₁(qⁿ − 1)/(q − 1) = −364.');
INSERT INTO public.questions VALUES (4332, 57, 'g10-alg-prog-q2-02', 2, 2, 'medium', 'single', 'Ədədi silsilədə a₁₁ + a₇ = 20 və a₁₃ = 6 olarsa, ilk 29 həddin cəmini tapın.', NULL, NULL, '{"A": "87", "B": "115", "C": "106", "D": "145", "E": "116"}'::jsonb, 'E', NULL, '2a₁ + 16d = 20, a₁ + 12d = 6 ⇒ a₁ = 18, d = −1. S₂₉ = (2a₁ + 28d)·29/2 = 116.');
INSERT INTO public.questions VALUES (4333, 57, 'g10-alg-prog-q2-03', 2, 3, 'hard', 'single', 'Sonsuz azalan həndəsi silsilənin hədlərinin cəmi 28/9, hədlərin kvadratlarının cəmi isə 784/45-dir. Silsilənin birinci həddini tapın.', NULL, NULL, '{"A": "5", "B": "−4", "C": "4", "D": "8", "E": "9/7"}'::jsonb, 'C', NULL, 'b₁/(1 − q) = 28/9, b₁²/(1 − q²) = 784/45. Bölsək: b₁/(1 + q) = 28/5. İki tənlikdən q = −2/7, b₁ = 4.');
INSERT INTO public.questions VALUES (4334, 57, 'g10-alg-prog-q2-04', 2, 4, 'hard', 'single', 'Həndəsi silsilədə b₃ = −1/2 və b₅ = −1/8 (q > 0). İlk 5 həddin cəmini tapın.', NULL, NULL, '{"A": "−61/16", "B": "31/8", "C": "−15/4", "D": "−47/8", "E": "−31/8"}'::jsonb, 'E', NULL, 'q^2 = b₅/b₃ = 1/4 ⇒ q = 1/2, b₁ = −2. S₅ = b₁(qⁿ − 1)/(q − 1) = −31/8.');
INSERT INTO public.questions VALUES (4335, 57, 'g10-alg-prog-q2-05', 2, 5, 'medium', 'single', 'Ədədi silsilədə a₁₂ + a₁₁ = 1 və a₄ = −7 olarsa, ilk 29 həddin cəmini tapın.', NULL, NULL, '{"A": "87", "B": "116", "C": "145", "D": "117", "E": "134"}'::jsonb, 'B', NULL, '2a₁ + 21d = 1, a₁ + 3d = −7 ⇒ a₁ = −10, d = 1. S₂₉ = (2a₁ + 28d)·29/2 = 116.');
INSERT INTO public.questions VALUES (4336, 57, 'g10-alg-prog-q2-06', 2, 6, 'medium', 'single', 'Ardıcıllıqda hər hədd (üçüncüdən başlayaraq) özündən əvvəlki iki həddin cəminə bərabərdir. a₁ = 7 və a₈ = 134 olarsa, a₂ həddini tapın.', NULL, NULL, '{"A": "7", "B": "5", "C": "4", "D": "6", "E": "8"}'::jsonb, 'D', NULL, 'a₂ = x olsun: a₃ = 7 + x, a₄ = 7 + 2x, … a₈ = 8·7 + 13x = 134 ⇒ x = 6.');
INSERT INTO public.questions VALUES (4337, 57, 'g10-alg-prog-q2-07', 2, 7, 'hard', 'open', 'aₙ = n² − 4n − 19 ardıcıllığının ən kiçik həddini tapın.', NULL, NULL, NULL, NULL, '−23', 'Parabolanın təpəsi n = 2. Ən yaxın natural n: 2. Ən kiçik hədd: −23.');
INSERT INTO public.questions VALUES (4338, 57, 'g10-alg-prog-q2-08', 2, 8, 'hard', 'single', 'Ardıcıllıq a₁ = 1 və aₙ₊₁ = 2·aₙ + 6 qaydası ilə verilib. a₆ həddini tapın.', NULL, NULL, '{"A": "212", "B": "224", "C": "442", "D": "106", "E": "218"}'::jsonb, 'E', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + 6 = (a₁ + 6)·2ⁿ⁻¹ ilə): a₆ = 218.');
INSERT INTO public.questions VALUES (4339, 57, 'g10-alg-prog-q2-09', 2, 9, 'hard', 'single', 'Ardıcıllıq a₁ = −4 və aₙ₊₁ = 2·aₙ + 1 qaydası ilə verilib. a₉ həddini tapın.', NULL, NULL, '{"A": "−770", "B": "−769", "C": "−768", "D": "−385", "E": "−1537"}'::jsonb, 'B', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + 1 = (a₁ + 1)·2ⁿ⁻¹ ilə): a₉ = −769.');
INSERT INTO public.questions VALUES (4340, 57, 'g10-alg-prog-q2-10', 2, 10, 'hard', 'single', 'Sonsuz azalan həndəsi silsilənin hədlərinin cəmi 9, hədlərin kvadratlarının cəmi isə 162-dir. Silsilənin birinci həddini tapın.', NULL, NULL, '{"A": "24", "B": "12", "C": "4/3", "D": "−12", "E": "13"}'::jsonb, 'B', NULL, 'b₁/(1 − q) = 9, b₁²/(1 − q²) = 162. Bölsək: b₁/(1 + q) = 18. İki tənlikdən q = −1/3, b₁ = 12.');
INSERT INTO public.questions VALUES (4341, 57, 'g10-alg-prog-q2-11', 2, 11, 'hard', 'single', 'Həndəsi silsilədə b₄ = −81 və b₅ = 243. İlk 7 həddin cəmini tapın.', NULL, NULL, '{"A": "1641", "B": "1644", "C": "−1641", "D": "−7107", "E": "−546"}'::jsonb, 'A', NULL, 'q = b₅/b₄ = −3, b₁ = 3. S₇ = b₁(qⁿ − 1)/(q − 1) = 1641.');
