INSERT INTO public.questions VALUES (4370, 57, 'g10-alg-prog-q3-20', 3, 20, 'hard', 'single', 'Ardıcıllıq a₁ = 5 və aₙ₊₁ = 2·aₙ − 1 qaydası ilə verilib. a₇ həddini tapın.', NULL, NULL, '{"A": "258", "B": "129", "C": "257", "D": "513", "E": "256"}'::jsonb, 'C', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + −1 = (a₁ + −1)·2ⁿ⁻¹ ilə): a₇ = 257.');
INSERT INTO public.questions VALUES (4371, 58, 'g10-alg-func-q1-01', 1, 1, 'medium', 'single', 'f(3x − 3) = x² + 4x + 1 olarsa, f(7) qiymətini tapın.', NULL, NULL, '{"A": "238/9", "B": "397", "C": "229/9", "D": "78", "E": "73/9"}'::jsonb, 'C', NULL, '3x − 3 = 7 ⇒ x = 10/3. f(7) = 10/3² + 4·10/3 + 1 = 229/9.');
INSERT INTO public.questions VALUES (4372, 58, 'g10-alg-func-q1-02', 1, 2, 'hard', 'single', 'f(x) = −2x² + 4x − 4 funksiyasının [1; 5] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "31", "B": "33", "C": "2", "D": "−2", "E": "32"}'::jsonb, 'E', NULL, 'Təpə x₀ = 1 (parçaya düşür). Qiymətlər: f(1) = −2, f(5) = −34, f(1) = −2. Fərq: 32.');
INSERT INTO public.questions VALUES (4373, 58, 'g10-alg-func-q1-03', 1, 3, 'hard', 'single', 'y = √(12 − |x + 5|) / (x² − 3) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "26", "B": "25", "C": "24", "D": "27", "E": "23"}'::jsonb, 'B', NULL, '|x + 5| ≤ 12 ⇒ −17 ≤ x ≤ 7: 25 tam ədəd. x² ≠ 3 şərti bu aralıqda heç nə çıxarmır. Cavab: 25.');
INSERT INTO public.questions VALUES (4374, 58, 'g10-alg-func-q1-04', 1, 4, 'medium', 'single', 'f(2x + 4) = x² + 3x + 2 olarsa, f(−7) qiymətini tapın.', NULL, NULL, '{"A": "63/4", "B": "30", "C": "72", "D": "−1/4", "E": "67/4"}'::jsonb, 'A', NULL, '2x + 4 = −7 ⇒ x = −11/2. f(−7) = (−11/2)² + 3·(−11/2) + 2 = 63/4.');
INSERT INTO public.questions VALUES (4375, 58, 'g10-alg-func-q1-05', 1, 5, 'medium', 'single', 'f(x) = 3x + 4, g(x) = x² + 5x − 3. f(g(x)) = 7 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−5", "B": "−10", "C": "−4", "D": "1", "E": "5"}'::jsonb, 'A', NULL, 'f(g(x)) = 3g(x) + 4 = 7 ⇒ g(x) = 1 ⇒ x² + 5x − 4 = 0 (D > 0). Köklərin cəmi −5.');
INSERT INTO public.questions VALUES (4376, 58, 'g10-alg-func-q1-06', 1, 6, 'hard', 'single', 'f(x) = x² − 6x − 2 funksiyasının [−5; 0] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "55", "B": "11", "C": "54", "D": "56", "E": "53"}'::jsonb, 'A', NULL, 'Təpə x₀ = 3 (parçadan kənardadır). Qiymətlər: f(−5) = 53, f(0) = −2. Fərq: 55.');
INSERT INTO public.questions VALUES (4377, 58, 'g10-alg-func-q1-07', 1, 7, 'medium', 'open', 'f(x) = (6x + 1)/(4x + 5) funksiyası üçün f⁻¹(8) qiymətini tapın.', NULL, NULL, NULL, NULL, '−3/2', 'f(x) = 8 tənliyini həll edin: 6x + 1 = 8(4x + 5) ⇒ x = −3/2.');
INSERT INTO public.questions VALUES (4378, 58, 'g10-alg-func-q1-08', 1, 8, 'hard', 'single', 'f(x) = x² − x + 4 funksiyasının [−5; −1] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "27", "B": "15/4", "C": "34", "D": "28", "E": "29"}'::jsonb, 'D', NULL, 'Təpə x₀ = 1/2 (parçadan kənardadır). Qiymətlər: f(−5) = 34, f(−1) = 6. Fərq: 28.');
INSERT INTO public.questions VALUES (4379, 58, 'g10-alg-func-q1-09', 1, 9, 'medium', 'single', 'f(x) = 3x − 5, g(x) = x² − 2x − 2. f(g(x)) = 9 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "14/3", "B": "−2", "C": "3", "D": "2", "E": "4"}'::jsonb, 'D', NULL, 'f(g(x)) = 3g(x) − 5 = 9 ⇒ g(x) = 14/3 ⇒ x² − 2x − 20/3 = 0 (D > 0). Köklərin cəmi 2.');
INSERT INTO public.questions VALUES (4380, 58, 'g10-alg-func-q1-10', 1, 10, 'hard', 'single', 'f(x) = x² + 8x + 9 funksiyasının [2; 7] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "84", "B": "86", "C": "7", "D": "85", "E": "114"}'::jsonb, 'D', NULL, 'Təpə x₀ = −4 (parçadan kənardadır). Qiymətlər: f(2) = 29, f(7) = 114. Fərq: 85.');
INSERT INTO public.questions VALUES (4381, 58, 'g10-alg-func-q1-11', 1, 11, 'medium', 'single', 'f(x) = (x + 3)/(3x + 5) funksiyası üçün f⁻¹(8) qiymətini tapın.', NULL, NULL, '{"A": "11/29", "B": "−37/23", "C": "37/23", "D": "−23/37", "E": "43/23"}'::jsonb, 'B', NULL, 'f(x) = 8 tənliyini həll edin: x + 3 = 8(3x + 5) ⇒ x = −37/23.');
INSERT INTO public.questions VALUES (4382, 58, 'g10-alg-func-q1-12', 1, 12, 'hard', 'single', 'y = √(6 − |x + 3|) / (x² − 16) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "11", "B": "12", "C": "10", "D": "13", "E": "14"}'::jsonb, 'B', NULL, '|x + 3| ≤ 6 ⇒ −9 ≤ x ≤ 3: 13 tam ədəd. x² ≠ 16 şərti çıxarır: −4. Cavab: 12.');
INSERT INTO public.questions VALUES (4383, 58, 'g10-alg-func-q1-13', 1, 13, 'medium', 'single', 'f(−2x + 5) = x² − x + 1 olarsa, f(10) qiymətini tapın.', NULL, NULL, '{"A": "91", "B": "39/4", "C": "241", "D": "43/4", "E": "259/4"}'::jsonb, 'B', NULL, '−2x + 5 = 10 ⇒ x = −5/2. f(10) = (−5/2)² − 1·(−5/2) + 1 = 39/4.');
INSERT INTO public.questions VALUES (4384, 58, 'g10-alg-func-q1-14', 1, 14, 'hard', 'open', 'y = √(8 − |x + 2|) / (x² − 3) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, NULL, NULL, '17', '|x + 2| ≤ 8 ⇒ −10 ≤ x ≤ 6: 17 tam ədəd. x² ≠ 3 şərti bu aralıqda heç nə çıxarmır. Cavab: 17.');
INSERT INTO public.questions VALUES (4385, 58, 'g10-alg-func-q1-15', 1, 15, 'medium', 'single', 'f(x) = −2x + 5, g(x) = x² + 2x − 2. f(g(x)) = 2 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "3/2", "B": "2", "C": "−2", "D": "−1", "E": "−4"}'::jsonb, 'C', NULL, 'f(g(x)) = −2g(x) + 5 = 2 ⇒ g(x) = 3/2 ⇒ x² + 2x − 7/2 = 0 (D > 0). Köklərin cəmi −2.');
INSERT INTO public.questions VALUES (4386, 58, 'g10-alg-func-q1-16', 1, 16, 'medium', 'single', 'f(4x + 3) = x² + x − 6 olarsa, f(4) qiymətini tapın.', NULL, NULL, '{"A": "−19/16", "B": "14", "C": "−91/16", "D": "374", "E": "−75/16"}'::jsonb, 'C', NULL, '4x + 3 = 4 ⇒ x = 1/4. f(4) = 1/4² + 1·1/4 − 6 = −91/16.');
INSERT INTO public.questions VALUES (4387, 58, 'g10-alg-func-q1-17', 1, 17, 'medium', 'single', 'f(x) = (−5x + 1)/(x − 6) funksiyası üçün f⁻¹(−8) qiymətini tapın.', NULL, NULL, '{"A": "−47/3", "B": "−41/14", "C": "−49/3", "D": "3/47", "E": "47/3"}'::jsonb, 'E', NULL, 'f(x) = −8 tənliyini həll edin: −5x + 1 = −8(x − 6) ⇒ x = 47/3.');
INSERT INTO public.questions VALUES (4388, 58, 'g10-alg-func-q1-18', 1, 18, 'hard', 'single', 'y = √(7 − |x − 1|) / (x² − 9) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "12", "B": "11", "C": "15", "D": "14", "E": "13"}'::jsonb, 'E', NULL, '|x − 1| ≤ 7 ⇒ −6 ≤ x ≤ 8: 15 tam ədəd. x² ≠ 9 şərti çıxarır: −3, 3. Cavab: 13.');
INSERT INTO public.questions VALUES (4389, 58, 'g10-alg-func-q1-19', 1, 19, 'medium', 'single', 'f(x) = (5x − 6)/(3x − 1) funksiyası üçün f⁻¹(−4) qiymətini tapın.', NULL, NULL, '{"A": "2/17", "B": "17/10", "C": "2", "D": "−10/17", "E": "10/17"}'::jsonb, 'E', NULL, 'f(x) = −4 tənliyini həll edin: 5x − 6 = −4(3x − 1) ⇒ x = 10/17.');
INSERT INTO public.questions VALUES (4390, 58, 'g10-alg-func-q1-20', 1, 20, 'medium', 'single', 'f(x) = 2x − 6, g(x) = x² + 4x + 3. f(g(x)) = −3 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−3", "B": "−8", "C": "−4", "D": "4", "E": "3/2"}'::jsonb, 'C', NULL, 'f(g(x)) = 2g(x) − 6 = −3 ⇒ g(x) = 3/2 ⇒ x² + 4x + 3/2 = 0 (D > 0). Köklərin cəmi −4.');
INSERT INTO public.questions VALUES (4391, 58, 'g10-alg-func-q2-01', 2, 1, 'hard', 'single', 'y = √(6 − |x + 4|) / (x² − 1) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "10", "B": "9", "C": "13", "D": "11", "E": "12"}'::jsonb, 'D', NULL, '|x + 4| ≤ 6 ⇒ −10 ≤ x ≤ 2: 13 tam ədəd. x² ≠ 1 şərti çıxarır: −1, 1. Cavab: 11.');
INSERT INTO public.questions VALUES (4392, 58, 'g10-alg-func-q2-02', 2, 2, 'medium', 'single', 'f(x) = 2x − 6, g(x) = x² − 5x + 1. f(g(x)) = 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "7/2", "B": "−5", "C": "6", "D": "5", "E": "10"}'::jsonb, 'D', NULL, 'f(g(x)) = 2g(x) − 6 = 1 ⇒ g(x) = 7/2 ⇒ x² − 5x − 5/2 = 0 (D > 0). Köklərin cəmi 5.');
INSERT INTO public.questions VALUES (4393, 58, 'g10-alg-func-q2-03', 2, 3, 'hard', 'single', 'y = √(12 − |x − 2|) / (x² − 4) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "24", "B": "25", "C": "23", "D": "21", "E": "22"}'::jsonb, 'C', NULL, '|x − 2| ≤ 12 ⇒ −10 ≤ x ≤ 14: 25 tam ədəd. x² ≠ 4 şərti çıxarır: −2, 2. Cavab: 23.');
INSERT INTO public.questions VALUES (4394, 58, 'g10-alg-func-q2-04', 2, 4, 'medium', 'single', 'f(x) = 2x + 2, g(x) = x² − 2x + 2. f(g(x)) = 7 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−2", "B": "4", "C": "5/2", "D": "3", "E": "2"}'::jsonb, 'E', NULL, 'f(g(x)) = 2g(x) + 2 = 7 ⇒ g(x) = 5/2 ⇒ x² − 2x − 1/2 = 0 (D > 0). Köklərin cəmi 2.');
INSERT INTO public.questions VALUES (4395, 58, 'g10-alg-func-q2-05', 2, 5, 'hard', 'single', 'f(x) = x² − 3x − 5 funksiyasının [−4; −1] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "29/4", "B": "24", "C": "23", "D": "25", "E": "26"}'::jsonb, 'B', NULL, 'Təpə x₀ = 3/2 (parçadan kənardadır). Qiymətlər: f(−4) = 23, f(−1) = −1. Fərq: 24.');
