INSERT INTO public.questions VALUES (4397, 58, 'g10-alg-func-q2-07', 2, 7, 'hard', 'open', 'f(x) = −2x² + x + 6 funksiyasının [−3; 1] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, NULL, NULL, '169/8', 'Təpə x₀ = 1/4 (parçaya düşür). Qiymətlər: f(−3) = −15, f(1) = 5, f(1/4) = 49/8. Fərq: 169/8.');
INSERT INTO public.questions VALUES (4398, 58, 'g10-alg-func-q2-08', 2, 8, 'medium', 'single', 'f(3x + 2) = x² − 2 olarsa, f(1) qiymətini tapın.', NULL, NULL, '{"A": "−8/9", "B": "−17/9", "C": "−1", "D": "−26/9", "E": "23"}'::jsonb, 'B', NULL, '3x + 2 = 1 ⇒ x = −1/3. f(1) = (−1/3)² − 2 = −17/9.');
INSERT INTO public.questions VALUES (4399, 58, 'g10-alg-func-q2-09', 2, 9, 'medium', 'single', 'f(−2x − 5) = x² + 4x − 2 olarsa, f(10) qiymətini tapın.', NULL, NULL, '{"A": "−23/4", "B": "523", "C": "97/4", "D": "138", "E": "101/4"}'::jsonb, 'C', NULL, '−2x − 5 = 10 ⇒ x = −15/2. f(10) = (−15/2)² + 4·(−15/2) − 2 = 97/4.');
INSERT INTO public.questions VALUES (4400, 58, 'g10-alg-func-q2-10', 2, 10, 'medium', 'single', 'f(x) = −2x − 6, g(x) = x² − 2x − 6. f(g(x)) = −2 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "1", "B": "4", "C": "−2", "D": "3", "E": "2"}'::jsonb, 'E', NULL, 'f(g(x)) = −2g(x) − 6 = −2 ⇒ g(x) = −2 ⇒ x² − 2x − 4 = 0 (D > 0). Köklərin cəmi 2.');
INSERT INTO public.questions VALUES (4401, 58, 'g10-alg-func-q2-11', 2, 11, 'medium', 'single', 'f(x) = (−2x + 5)/(x − 4) funksiyası üçün f⁻¹(−8) qiymətini tapın.', NULL, NULL, '{"A": "−7/4", "B": "−9/2", "C": "2/9", "D": "9/2", "E": "−37/6"}'::jsonb, 'D', NULL, 'f(x) = −8 tənliyini həll edin: −2x + 5 = −8(x − 4) ⇒ x = 9/2.');
