INSERT INTO public.questions VALUES (4403, 58, 'g10-alg-func-q2-13', 2, 13, 'hard', 'single', 'f(x) = −x² + 6x − 7 funksiyasının [−5; 3] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "2", "B": "66", "C": "63", "D": "64", "E": "65"}'::jsonb, 'D', NULL, 'Təpə x₀ = 3 (parçaya düşür). Qiymətlər: f(−5) = −62, f(3) = 2, f(3) = 2. Fərq: 64.');
