INSERT INTO public.questions VALUES (4405, 58, 'g10-alg-func-q2-15', 2, 15, 'medium', 'single', 'f(x) = (−5x − 6)/(3x + 5) funksiyası üçün f⁻¹(−7) qiymətini tapın.', NULL, NULL, '{"A": "−16/29", "B": "41/16", "C": "−29/16", "D": "29/16", "E": "−13/16"}'::jsonb, 'C', NULL, 'f(x) = −7 tənliyini həll edin: −5x − 6 = −7(3x + 5) ⇒ x = −29/16.');
