INSERT INTO public.questions VALUES (4408, 58, 'g10-alg-func-q2-18', 2, 18, 'medium', 'single', 'f(x) = (4x + 2)/(4x − 3) funksiyası üçün f⁻¹(−3) qiymətini tapın.', NULL, NULL, '{"A": "−7/16", "B": "2/3", "C": "16/7", "D": "7/16", "E": "−11/16"}'::jsonb, 'D', NULL, 'f(x) = −3 tənliyini həll edin: 4x + 2 = −3(4x − 3) ⇒ x = 7/16.');
