INSERT INTO public.questions VALUES (4410, 58, 'g10-alg-func-q2-20', 2, 20, 'medium', 'single', 'f(x) = −2x + 6, g(x) = x² − 4x − 6. f(g(x)) = 19 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "5", "B": "−13/2", "C": "−4", "D": "4", "E": "8"}'::jsonb, 'D', NULL, 'f(g(x)) = −2g(x) + 6 = 19 ⇒ g(x) = −13/2 ⇒ x² − 4x + 1/2 = 0 (D > 0). Köklərin cəmi 4.');
