INSERT INTO public.questions VALUES (4412, 58, 'g10-alg-func-q3-02', 3, 2, 'hard', 'single', 'f(x) = −x² + 5x − 6 funksiyasının [2; 10] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "56", "B": "221/4", "C": "229/4", "D": "1/4", "E": "225/4"}'::jsonb, 'E', NULL, 'Təpə x₀ = 5/2 (parçaya düşür). Qiymətlər: f(2) = 0, f(10) = −56, f(5/2) = 1/4. Fərq: 225/4.');
INSERT INTO public.questions VALUES (4413, 58, 'g10-alg-func-q3-03', 3, 3, 'hard', 'single', 'f(x) = −2x² − 6x − 3 funksiyasının [1; 5] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "72", "B": "3/2", "C": "−11", "D": "73", "E": "71"}'::jsonb, 'A', NULL, 'Təpə x₀ = −3/2 (parçadan kənardadır). Qiymətlər: f(1) = −11, f(5) = −83. Fərq: 72.');
INSERT INTO public.questions VALUES (4414, 58, 'g10-alg-func-q3-04', 3, 4, 'medium', 'single', 'f(x) = (−3x − 7)/(4x) funksiyası üçün f⁻¹(−7) qiymətini tapın.', NULL, NULL, '{"A": "−1/2", "B": "32/25", "C": "7/25", "D": "−7/25", "E": "25/7"}'::jsonb, 'C', NULL, 'f(x) = −7 tənliyini həll edin: −3x − 7 = −7(4x) ⇒ x = 7/25.');
INSERT INTO public.questions VALUES (4415, 58, 'g10-alg-func-q3-05', 3, 5, 'hard', 'single', 'y = √(6 − |x − 3|) / (x² − 4) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "10", "B": "12", "C": "11", "D": "9", "E": "13"}'::jsonb, 'C', NULL, '|x − 3| ≤ 6 ⇒ −3 ≤ x ≤ 9: 13 tam ədəd. x² ≠ 4 şərti çıxarır: −2, 2. Cavab: 11.');
INSERT INTO public.questions VALUES (4416, 58, 'g10-alg-func-q3-06', 3, 6, 'medium', 'single', 'f(3x − 1) = x² − 2x − 1 olarsa, f(−1) qiymətini tapın.', NULL, NULL, '{"A": "0", "B": "7/9", "C": "23", "D": "−1", "E": "2"}'::jsonb, 'D', NULL, '3x − 1 = −1 ⇒ x = 0. f(−1) = 0² − 2·0 − 1 = −1.');
INSERT INTO public.questions VALUES (4417, 58, 'g10-alg-func-q3-07', 3, 7, 'medium', 'open', 'f(x) = 2x + 3, g(x) = x² − 2x + 6. f(g(x)) = 17 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '2', 'f(g(x)) = 2g(x) + 3 = 17 ⇒ g(x) = 7 ⇒ x² − 2x − 1 = 0 (D > 0). Köklərin cəmi 2.');
INSERT INTO public.questions VALUES (4418, 58, 'g10-alg-func-q3-08', 3, 8, 'medium', 'single', 'f(x) = x − 5, g(x) = x² + x + 9. f(g(x)) = 5 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "10", "B": "0", "C": "−2", "D": "−1", "E": "1"}'::jsonb, 'D', NULL, 'f(g(x)) = g(x) − 5 = 5 ⇒ g(x) = 10 ⇒ x² + x − 1 = 0 (D > 0). Köklərin cəmi −1.');
INSERT INTO public.questions VALUES (4419, 58, 'g10-alg-func-q3-09', 3, 9, 'medium', 'single', 'f(x) = (−5x − 5)/(x) funksiyası üçün f⁻¹(−7) qiymətini tapın.', NULL, NULL, '{"A": "7/2", "B": "−5/2", "C": "5/2", "D": "2/5", "E": "−30/7"}'::jsonb, 'C', NULL, 'f(x) = −7 tənliyini həll edin: −5x − 5 = −7(x) ⇒ x = 5/2.');
INSERT INTO public.questions VALUES (4420, 58, 'g10-alg-func-q3-10', 3, 10, 'medium', 'single', 'f(3x) = x² + 6 olarsa, f(10) qiymətini tapın.', NULL, NULL, '{"A": "145/9", "B": "154/9", "C": "906", "D": "163/9", "E": "106"}'::jsonb, 'B', NULL, '3x = 10 ⇒ x = 10/3. f(10) = 10/3² + 6 = 154/9.');
INSERT INTO public.questions VALUES (4421, 58, 'g10-alg-func-q3-11', 3, 11, 'medium', 'single', 'f(−2x − 2) = x² + 4x + 3 olarsa, f(−2) qiymətini tapın.', NULL, NULL, '{"A": "4", "B": "15", "C": "2", "D": "3", "E": "−1"}'::jsonb, 'D', NULL, '−2x − 2 = −2 ⇒ x = 0. f(−2) = 0² + 4·0 + 3 = 3.');
INSERT INTO public.questions VALUES (4422, 58, 'g10-alg-func-q3-12', 3, 12, 'medium', 'single', 'f(x) = (2x − 6)/(4x + 2) funksiyası üçün f⁻¹(0) qiymətini tapın.', NULL, NULL, '{"A": "3", "B": "1/3", "C": "−3", "D": "2", "E": "4"}'::jsonb, 'A', NULL, 'f(x) = 0 tənliyini həll edin: 2x − 6 = 0(4x + 2) ⇒ x = 3.');
INSERT INTO public.questions VALUES (4423, 58, 'g10-alg-func-q3-13', 3, 13, 'hard', 'single', 'f(x) = −x² − 10 funksiyasının [−5; 2] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "−10", "B": "24", "C": "25", "D": "21", "E": "26"}'::jsonb, 'C', NULL, 'Təpə x₀ = 0 (parçaya düşür). Qiymətlər: f(−5) = −35, f(2) = −14, f(0) = −10. Fərq: 25.');
INSERT INTO public.questions VALUES (4424, 58, 'g10-alg-func-q3-14', 3, 14, 'medium', 'open', 'f(x) = −2x, g(x) = x² − 2x. f(g(x)) = −4 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '2', 'f(g(x)) = −2g(x) = −4 ⇒ g(x) = 2 ⇒ x² − 2x − 2 = 0 (D > 0). Köklərin cəmi 2.');
INSERT INTO public.questions VALUES (4425, 58, 'g10-alg-func-q3-15', 3, 15, 'medium', 'single', 'f(x) = (3x + 1)/(2x + 1) funksiyası üçün f⁻¹(4) qiymətini tapın.', NULL, NULL, '{"A": "−3/5", "B": "13/9", "C": "1", "D": "−5/3", "E": "3/5"}'::jsonb, 'A', NULL, 'f(x) = 4 tənliyini həll edin: 3x + 1 = 4(2x + 1) ⇒ x = −3/5.');
INSERT INTO public.questions VALUES (4426, 58, 'g10-alg-func-q3-16', 3, 16, 'medium', 'single', 'f(x) = (−4x)/(4x − 2) funksiyası üçün f⁻¹(−8) qiymətini tapın.', NULL, NULL, '{"A": "11/7", "B": "−4/7", "C": "4/7", "D": "7/4", "E": "−16/17"}'::jsonb, 'C', NULL, 'f(x) = −8 tənliyini həll edin: −4x = −8(4x − 2) ⇒ x = 4/7.');
INSERT INTO public.questions VALUES (4427, 58, 'g10-alg-func-q3-17', 3, 17, 'medium', 'single', 'f(4x − 5) = x² + 3x − 2 olarsa, f(0) qiymətini tapın.', NULL, NULL, '{"A": "−2", "B": "53/16", "C": "8", "D": "69/16", "E": "−67/16"}'::jsonb, 'B', NULL, '4x − 5 = 0 ⇒ x = 5/4. f(0) = 5/4² + 3·5/4 − 2 = 53/16.');
INSERT INTO public.questions VALUES (4428, 58, 'g10-alg-func-q3-18', 3, 18, 'medium', 'single', 'f(x) = x, g(x) = x² − 6x − 6. f(g(x)) = 18 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "−6", "B": "7", "C": "12", "D": "6", "E": "18"}'::jsonb, 'D', NULL, 'f(g(x)) = g(x) = 18 ⇒ g(x) = 18 ⇒ x² − 6x − 24 = 0 (D > 0). Köklərin cəmi 6.');
INSERT INTO public.questions VALUES (4429, 58, 'g10-alg-func-q3-19', 3, 19, 'hard', 'single', 'y = √(10 − |x − 6|) / (x² − 4) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "20", "B": "17", "C": "21", "D": "19", "E": "18"}'::jsonb, 'D', NULL, '|x − 6| ≤ 10 ⇒ −4 ≤ x ≤ 16: 21 tam ədəd. x² ≠ 4 şərti çıxarır: −2, 2. Cavab: 19.');
INSERT INTO public.questions VALUES (4430, 58, 'g10-alg-func-q3-20', 3, 20, 'hard', 'single', 'y = √(6 − |x − 2|) / (x² − 4) funksiyasının təyin oblastına neçə tam ədəd daxildir?', NULL, NULL, '{"A": "9", "B": "10", "C": "12", "D": "11", "E": "13"}'::jsonb, 'D', NULL, '|x − 2| ≤ 6 ⇒ −4 ≤ x ≤ 8: 13 tam ədəd. x² ≠ 4 şərti çıxarır: −2, 2. Cavab: 11.');
INSERT INTO public.questions VALUES (4431, 59, 'g10-geo-basic-q1-01', 1, 1, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 13, BC = 21. Ən böyük tərəfə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="39.4,186.0 280.6,186.0 78.0,34.0"/><text x="27.9" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.9" y="195.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="71.8" y="27.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.7" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="47.3" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="189.8" y="109.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text><line x1="39.4" y1="186.0" x2="126.2" y2="70.2" stroke-dasharray="5 4"/></svg>', '{"A": "13", "B": "63/5", "C": "252/13", "D": "12", "E": "6"}'::jsonb, 'D', NULL, 'p = 27, S = √(p(p − a)(p − b)(p − c)) = 126. h = 2S/21 = 12.');
INSERT INTO public.questions VALUES (4432, 59, 'g10-geo-basic-q1-02', 1, 2, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 42°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 101.7,186.0 218.3,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="91.8" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="228.2" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="101.7" y1="186.0" x2="188.4" y2="107.9" stroke-dasharray="5 4"/><text x="198.0" y="104.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "48°", "B": "69°", "C": "42°", "D": "27°", "E": "33°"}'::jsonb, 'D', NULL, '∠B = ∠C = (180° − 42°)/2 = 69°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·69° = 42°. ∠ABD = 69° − 42° = 27°.');
INSERT INTO public.questions VALUES (4433, 59, 'g10-geo-basic-q1-03', 1, 3, 'medium', 'single', 'ABC üçbucağında AB = 16, AC = 15, BC = 9. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,175.3 286.0,175.3 230.9,44.7"/><text x="21.5" y="183.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.0" y="185.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.1" y="38.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="154.3" y="190.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="121.4" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="270.0" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><line x1="34.0" y1="175.3" x2="258.4" y2="110.0" stroke-dasharray="5 4"/><text x="270.9" y="111.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√962/2", "B": "√1762/2", "C": "√1043/2", "D": "√881/2", "E": "√885/2"}'::jsonb, 'D', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (512 + 450 − 81)/4 = 881/4 ⇒ AM = √881/2.');
INSERT INTO public.questions VALUES (4434, 59, 'g10-geo-basic-q1-04', 1, 4, 'medium', 'single', 'ABC üçbucağında AB = 5, AC = 10, BC = 8. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="101.5,186.0 197.4,186.0 218.5,34.0"/><text x="90.9" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="203.1" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="223.9" y="27.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="144.5" y="201.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="154.7" y="104.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="217.7" y="108.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><line x1="101.5" y1="186.0" x2="208.0" y2="110.0" stroke-dasharray="5 4"/><text x="218.5" y="107.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√93", "B": "√314/2", "C": "√190/2", "D": "5√10/2", "E": "√186/2"}'::jsonb, 'E', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (50 + 200 − 64)/4 = 93/2 ⇒ AM = √186/2.');
INSERT INTO public.questions VALUES (4435, 59, 'g10-geo-basic-q1-05', 1, 5, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 14 və HB = 12 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.8 286.0,172.8 169.7,47.2"/><line x1="169.7" y1="47.2" x2="169.7" y2="172.8" stroke-dasharray="5 4"/><polyline points="179.7,172.8 179.7,162.8 169.7,162.8" stroke-width="1.2"/><polyline points="162.4,54.0 169.1,61.3 176.5,54.5" stroke-width="1.2"/><text x="21.6" y="181.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="170.7" y="39.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="169.7" y="190.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="96.1" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="232.9" y="188.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "2√78", "B": "2√85", "C": "13", "D": "2√91", "E": "2√42"}'::jsonb, 'E', NULL, 'CH² = AH·HB = 14·12 = 168 ⇒ CH = 2√42.');
INSERT INTO public.questions VALUES (4436, 59, 'g10-geo-basic-q1-06', 1, 6, 'medium', 'single', 'ABC üçbucağında ∠A = 32°, ∠B = 80°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,180.9 286.0,180.9 261.0,39.1"/><text x="21.5" y="189.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="191.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="268.5" y="33.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="180.9" x2="221.8" y2="127.1" stroke-dasharray="5 4"/><line x1="286.0" y1="180.9" x2="221.8" y2="127.1" stroke-dasharray="5 4"/><circle cx="221.8" cy="127.1" r="2.6" fill="currentColor"/><text x="216.5" y="143.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "106°", "B": "56°", "C": "146°", "D": "124°", "E": "112°"}'::jsonb, 'D', NULL, '∠C = 180° − 32° − 80° = 68°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 124°.');
INSERT INTO public.questions VALUES (4437, 59, 'g10-geo-basic-q1-07', 1, 7, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 2 və HB = 13 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.8 286.0,152.8 67.6,67.2"/><line x1="67.6" y1="67.2" x2="67.6" y2="152.8" stroke-dasharray="5 4"/><polyline points="77.6,152.8 77.6,142.8 67.6,142.8" stroke-width="1.2"/><polyline points="63.9,76.5 73.3,80.1 76.9,70.8" stroke-width="1.2"/><text x="21.5" y="161.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="160.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="58.1" y="63.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="67.6" y="170.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="48.5" y="169.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="186.2" y="165.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text></svg>', '{"A": "15√26/2", "B": "15√26/4", "C": "15√30/2", "D": "√26", "E": "15√26"}'::jsonb, 'A', NULL, 'CH = √(AH·HB) = √26. S = AB·CH/2 = 15·√26/2 = 15√26/2.');
INSERT INTO public.questions VALUES (4438, 59, 'g10-geo-basic-q1-08', 1, 8, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 12, BC = 13. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="130.8,180.2 189.2,180.2 130.8,39.8"/><text x="125.8" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="197.6" y="195.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="128.1" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="162.4" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="123.1" y="105.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="164.6" y="103.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "2", "B": "15/2", "C": "195/31", "D": "13", "E": "13/2"}'::jsonb, 'E', NULL, 'p = 15, S = √(p(p − a)(p − b)(p − c)) = 30. R = abc/(4S) = 780/120 = 13/2.');
INSERT INTO public.questions VALUES (4439, 59, 'g10-geo-basic-q1-09', 1, 9, 'medium', 'single', 'ABC üçbucağında ∠A = 28°, ∠B = 42°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.1 286.0,152.1 192.4,67.9"/><text x="21.3" y="159.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="160.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.1" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="152.1" x2="186.8" y2="114.0" stroke-dasharray="5 4"/><line x1="286.0" y1="152.1" x2="186.8" y2="114.0" stroke-dasharray="5 4"/><circle cx="186.8" cy="114.0" r="2.6" fill="currentColor"/><text x="185.2" y="131.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "70°", "B": "35°", "C": "104°", "D": "145°", "E": "125°"}'::jsonb, 'D', NULL, '∠C = 180° − 28° − 42° = 110°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 145°.');
INSERT INTO public.questions VALUES (4440, 59, 'g10-geo-basic-q1-10', 1, 10, 'hard', 'single', 'ABC üçbucağında AB = 11, AC = 17, BC = 13. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="95.7,186.0 224.3,186.0 223.8,34.0"/><text x="84.5" y="197.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="232.7" y="200.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="228.8" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="155.4" y="202.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="152.0" y="105.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="234.4" y="108.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="95.7" y1="186.0" x2="224.1" y2="126.3" stroke-dasharray="5 4"/><text x="235.9" y="125.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "13/2", "B": "143/17", "C": "221/28", "D": "143/28", "E": "121/28"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 11 : 17. BD = 13·11/(11 + 17) = 143/28.');
INSERT INTO public.questions VALUES (4441, 59, 'g10-geo-basic-q1-11', 1, 11, 'hard', 'single', 'ABC üçbucağında AB = 18, AC = 15, BC = 13. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,184.6 286.0,184.6 181.8,35.4"/><text x="21.8" y="194.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.0" y="194.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="183.7" y="27.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.3" y="201.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="96.8" y="110.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="245.1" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="34.0" y1="184.6" x2="229.2" y2="103.2" stroke-dasharray="5 4"/><text x="241.1" y="103.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "78/11", "B": "78/5", "C": "65/11", "D": "108/11", "E": "13/2"}'::jsonb, 'A', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 18 : 15. BD = 13·18/(18 + 15) = 78/11.');
INSERT INTO public.questions VALUES (4442, 59, 'g10-geo-basic-q1-12', 1, 12, 'medium', 'single', 'ABC üçbucağında ∠A = 106°, ∠B = 22°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="63.2,160.9 286.0,160.9 34.0,59.1"/><text x="51.7" y="172.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="168.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.5" y="56.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="59.1" x2="34.0" y2="160.9" stroke-dasharray="5 4"/><line x1="34.0" y1="59.1" x2="125.7" y2="160.9" stroke-dasharray="5 4"/><polyline points="44.0,160.9 44.0,150.9 34.0,150.9" stroke-width="1.2"/><text x="34.0" y="178.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="134.4" y="175.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "26°", "B": "47°", "C": "42°", "D": "32°", "E": "84°"}'::jsonb, 'C', NULL, '∠C = 52°, ∠ACL = 26°. ∠ACH = 90° − ∠A = -16°. Aradakı bucaq |26° − (-16°)| = |∠A − ∠B|/2 = 42°.');
INSERT INTO public.questions VALUES (4443, 59, 'g10-geo-basic-q1-13', 1, 13, 'medium', 'single', 'ABC üçbucağında ∠A = 58°, ∠B = 56°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="61.2,186.0 258.8,186.0 156.2,34.0"/><text x="49.7" y="197.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="270.3" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="155.9" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="61.2" y1="186.0" x2="157.9" y2="132.4" stroke-dasharray="5 4"/><line x1="258.8" y1="186.0" x2="157.9" y2="132.4" stroke-dasharray="5 4"/><circle cx="157.9" cy="132.4" r="2.6" fill="currentColor"/><text x="158.2" y="150.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "147°", "B": "114°", "C": "123°", "D": "119°", "E": "57°"}'::jsonb, 'C', NULL, '∠C = 180° − 58° − 56° = 66°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 123°.');
INSERT INTO public.questions VALUES (4444, 59, 'g10-geo-basic-q1-14', 1, 14, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 8 və HB = 15 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,170.0 286.0,170.0 121.7,50.0"/><line x1="121.7" y1="50.0" x2="121.7" y2="170.0" stroke-dasharray="5 4"/><polyline points="131.7,170.0 131.7,160.0 121.7,160.0" stroke-width="1.2"/><polyline points="115.8,58.1 123.8,64.0 129.7,55.9" stroke-width="1.2"/><text x="21.7" y="179.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="178.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="117.7" y="42.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="121.7" y="188.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="73.7" y="186.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="210.6" y="184.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "8√30", "B": "23√46", "C": "46√30", "D": "23√30", "E": "23√30/2"}'::jsonb, 'D', NULL, 'CH = √(AH·HB) = 2√30. S = AB·CH/2 = 23·2√30/2 = 23√30.');
INSERT INTO public.questions VALUES (4445, 59, 'g10-geo-basic-q1-15', 1, 15, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 32°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 116.4,186.0 203.6,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="107.9" y="200.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="212.1" y="200.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="116.4" y1="186.0" x2="190.3" y2="139.8" stroke-dasharray="5 4"/><text x="201.4" y="137.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "48°", "B": "74°", "C": "42°", "D": "58°", "E": "32°"}'::jsonb, 'C', NULL, '∠B = ∠C = (180° − 32°)/2 = 74°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·74° = 32°. ∠ABD = 74° − 32° = 42°.');
INSERT INTO public.questions VALUES (4446, 59, 'g10-geo-basic-q1-16', 1, 16, 'hard', 'single', 'ABC üçbucağında AB = 17, AC = 16, BC = 17. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="92.9,145.8 227.1,145.8 152.3,34.4"/><text x="81.7" y="157.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="238.5" y="156.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="151.5" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.8" y="162.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="112.1" y="89.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="200.1" y="89.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "319/30", "B": "289/15", "C": "24/5", "D": "17/2", "E": "289/30"}'::jsonb, 'E', NULL, 'p = 25, S = √(p(p − a)(p − b)(p − c)) = 120. R = abc/(4S) = 4624/480 = 289/30.');
INSERT INTO public.questions VALUES (4447, 59, 'g10-geo-basic-q1-17', 1, 17, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 7, BC = 11. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,150.3 286.0,150.3 119.7,69.7"/><text x="21.4" y="158.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="157.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="113.9" y="63.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.4" y="166.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="65.1" y="112.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="214.5" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="34.0" y1="150.3" x2="172.6" y2="95.4" stroke-dasharray="5 4"/><text x="184.7" y="95.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "225/22", "B": "15/2", "C": "11/2", "D": "165/7", "E": "7/2"}'::jsonb, 'B', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 15 : 7. BD = 11·15/(15 + 7) = 15/2.');
INSERT INTO public.questions VALUES (4448, 59, 'g10-geo-basic-q1-18', 1, 18, 'hard', 'single', 'ABC üçbucağında AB = 30, AC = 11, BC = 25. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="87.0,88.7 233.0,88.7 119.1,45.9"/><text x="74.4" y="96.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.8" y="95.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="110.2" y="41.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.3" y="102.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="91.3" y="70.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="187.7" y="69.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "125/8", "B": "15", "C": "133/8", "D": "125/4", "E": "4"}'::jsonb, 'A', NULL, 'p = 33, S = √(p(p − a)(p − b)(p − c)) = 132. R = abc/(4S) = 8250/528 = 125/8.');
INSERT INTO public.questions VALUES (4449, 59, 'g10-geo-basic-q1-19', 1, 19, 'medium', 'single', 'ABC üçbucağında AB = 8, AC = 11, BC = 6. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="39.1,186.0 246.8,186.0 280.9,34.0"/><text x="26.8" y="195.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="256.6" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="289.6" y="29.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="134.9" y="199.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="151.0" y="107.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="275.2" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="39.1" y1="186.0" x2="263.8" y2="110.0" stroke-dasharray="5 4"/><text x="276.2" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√406/2", "B": "√167", "C": "√370/2", "D": "√334/2", "E": "13√2/2"}'::jsonb, 'D', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (128 + 242 − 36)/4 = 167/2 ⇒ AM = √334/2.');
INSERT INTO public.questions VALUES (4450, 59, 'g10-geo-basic-q1-20', 1, 20, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 6 və HB = 1 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,154.1 286.0,154.1 250.0,65.9"/><line x1="250.0" y1="65.9" x2="250.0" y2="154.1" stroke-dasharray="5 4"/><polyline points="260.0,154.1 260.0,144.1 250.0,144.1" stroke-width="1.2"/><polyline points="240.7,69.7 244.5,78.9 253.8,75.2" stroke-width="1.2"/><text x="21.2" y="161.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="162.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="259.3" y="61.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="250.0" y="172.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="132.7" y="166.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="270.4" y="170.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">1</text></svg>', '{"A": "7√6", "B": "7√42/2", "C": "7√6/4", "D": "7√6/2", "E": "3√6"}'::jsonb, 'D', NULL, 'CH = √(AH·HB) = √6. S = AB·CH/2 = 7·√6/2 = 7√6/2.');
INSERT INTO public.questions VALUES (4451, 59, 'g10-geo-basic-q2-01', 2, 1, 'hard', 'single', 'ABC üçbucağında AB = 18, AC = 11, BC = 17. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,180.8 286.0,180.8 94.7,39.2"/><text x="22.2" y="191.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="189.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="89.2" y="32.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.0" y="196.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="52.9" y="111.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="201.3" y="110.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="34.0" y1="180.8" x2="167.2" y2="92.9" stroke-dasharray="5 4"/><text x="178.1" y="90.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√503/2", "B": "√110137/29", "C": "12√759/29", "D": "√601/2", "E": "3√22"}'::jsonb, 'C', NULL, 'BD = 306/29, DC = 187/29. AD² = AB·AC − BD·DC = 198 − 57222/841 = 109296/841 ⇒ AD = 12√759/29.');
INSERT INTO public.questions VALUES (4452, 59, 'g10-geo-basic-q2-02', 2, 2, 'medium', 'single', 'ABC üçbucağında ∠A = 48°, ∠B = 26°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.7 286.0,152.7 110.9,67.3"/><text x="21.4" y="161.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="160.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="104.4" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="110.9" y1="67.3" x2="110.9" y2="152.7" stroke-dasharray="5 4"/><line x1="110.9" y1="67.3" x2="127.5" y2="152.7" stroke-dasharray="5 4"/><polyline points="120.9,152.7 120.9,142.7 110.9,142.7" stroke-width="1.2"/><text x="110.9" y="170.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="130.0" y="170.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "11°", "B": "22°", "C": "16°", "D": "53°", "E": "37/2°"}'::jsonb, 'A', NULL, '∠C = 106°, ∠ACL = 53°. ∠ACH = 90° − ∠A = 42°. Aradakı bucaq |53° − (42°)| = |∠A − ∠B|/2 = 11°.');
INSERT INTO public.questions VALUES (4453, 59, 'g10-geo-basic-q2-03', 2, 3, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 6 və HB = 2 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 223.0,55.4"/><line x1="223.0" y1="55.4" x2="223.0" y2="164.6" stroke-dasharray="5 4"/><polyline points="233.0,164.6 233.0,154.6 223.0,154.6" stroke-width="1.2"/><polyline points="214.3,60.4 219.3,69.1 228.0,64.1" stroke-width="1.2"/><text x="21.4" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.0" y="182.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="120.6" y="178.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="257.8" y="181.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text></svg>', '{"A": "8√3", "B": "16√3", "C": "2√3", "D": "4√3", "E": "6√3"}'::jsonb, 'A', NULL, 'CH = √(AH·HB) = 2√3. S = AB·CH/2 = 8·2√3/2 = 8√3.');
INSERT INTO public.questions VALUES (4454, 59, 'g10-geo-basic-q2-04', 2, 4, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 25, BC = 17. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="127.8,178.8 192.2,178.8 235.1,98.4"/><text x="116.0" y="189.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="195.5" y="196.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="244.0" y="93.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="151.8" y="192.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="178.4" y="132.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="224.5" y="138.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "85/3", "B": "10/3", "C": "25/2", "D": "85/6", "E": "91/6"}'::jsonb, 'D', NULL, 'p = 27, S = √(p(p − a)(p − b)(p − c)) = 90. R = abc/(4S) = 5100/360 = 85/6.');
INSERT INTO public.questions VALUES (4455, 59, 'g10-geo-basic-q2-05', 2, 5, 'hard', 'single', 'ABC üçbucağında AB = 11, AC = 15, BC = 6. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,156.0 230.7,156.0 286.0,64.0"/><text x="21.3" y="163.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="241.6" y="168.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.2" y="62.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.1" y="167.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="149.9" y="108.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="270.1" y="112.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="156.0" x2="254.1" y2="117.1" stroke-dasharray="5 4"/><text x="266.9" y="119.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "45/13", "B": "121/26", "C": "3", "D": "33/13", "E": "22/5"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 11 : 15. BD = 6·11/(11 + 15) = 33/13.');
INSERT INTO public.questions VALUES (4456, 59, 'g10-geo-basic-q2-06', 2, 6, 'hard', 'single', 'ABC üçbucağında AB = 24, AC = 20, BC = 20. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 274.0,186.0 160.0,34.0"/><text x="34.1" y="196.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="285.9" y="196.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="92.0" y="110.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="228.0" y="110.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><circle cx="160.0" cy="129.0" r="57.0"/></svg>', '{"A": "25/2", "B": "6", "C": "3", "D": "12", "E": "7"}'::jsonb, 'B', NULL, 'p = 32, S = √(p(p − a)(p − b)(p − c)) = 192. r = S/p = 192/32 = 6.');
INSERT INTO public.questions VALUES (4457, 59, 'g10-geo-basic-q2-07', 2, 7, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 4 və HB = 2 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,169.4 286.0,169.4 202.0,50.6"/><line x1="202.0" y1="50.6" x2="202.0" y2="169.4" stroke-dasharray="5 4"/><polyline points="212.0,169.4 212.0,159.4 202.0,159.4" stroke-width="1.2"/><polyline points="193.8,56.4 199.6,64.5 207.8,58.8" stroke-width="1.2"/><text x="21.5" y="177.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="178.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="206.3" y="43.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="202.0" y="187.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="111.1" y="184.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="248.0" y="185.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text></svg>', '{"A": "2√6", "B": "2√3", "C": "4√3", "D": "2√2", "E": "2√5"}'::jsonb, 'A', NULL, 'AC² = AH·AB = 4·6 = 24 ⇒ AC = 2√6.');
INSERT INTO public.questions VALUES (4458, 59, 'g10-geo-basic-q2-08', 2, 8, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 12 və HB = 8 parçalarına bölür. Üçbucağın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.7 286.0,171.7 185.2,48.3"/><line x1="185.2" y1="48.3" x2="185.2" y2="171.7" stroke-dasharray="5 4"/><polyline points="195.2,171.7 195.2,161.7 185.2,161.7" stroke-width="1.2"/><polyline points="177.5,54.6 183.8,62.3 191.5,56.0" stroke-width="1.2"/><text x="21.6" y="180.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="181.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.8" y="40.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="185.2" y="189.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="103.3" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="240.1" y="187.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "24√6", "B": "80√6", "C": "20√6", "D": "40√6", "E": "40√15"}'::jsonb, 'D', NULL, 'CH = √(AH·HB) = 4√6. S = AB·CH/2 = 20·4√6/2 = 40√6.');
INSERT INTO public.questions VALUES (4459, 59, 'g10-geo-basic-q2-09', 2, 9, 'medium', 'single', 'ABC üçbucağında AB = 12, AC = 8, BC = 9. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 145.1,47.0"/><text x="21.7" y="182.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="143.6" y="39.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="161.4" y="189.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="78.1" y="111.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="226.9" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><line x1="34.0" y1="173.0" x2="215.6" y2="110.0" stroke-dasharray="5 4"/><text x="227.8" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√335/2", "B": "√339/2", "C": "2√26", "D": "√497/2", "E": "√670/2"}'::jsonb, 'A', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (288 + 128 − 81)/4 = 335/4 ⇒ AM = √335/2.');
INSERT INTO public.questions VALUES (4460, 59, 'g10-geo-basic-q2-10', 2, 10, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 6 və HB = 7 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.8 286.0,172.8 150.3,47.2"/><line x1="150.3" y1="47.2" x2="150.3" y2="172.8" stroke-dasharray="5 4"/><polyline points="160.3,172.8 160.3,162.8 150.3,162.8" stroke-width="1.2"/><polyline points="143.5,54.5 150.9,61.3 157.6,54.0" stroke-width="1.2"/><text x="21.7" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="181.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="149.3" y="39.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="150.3" y="190.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="87.1" y="188.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="223.9" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "√85", "B": "√42", "C": "√133", "D": "√78", "E": "√91"}'::jsonb, 'D', NULL, 'AC² = AH·AB = 6·13 = 78 ⇒ AC = √78.');
INSERT INTO public.questions VALUES (4461, 59, 'g10-geo-basic-q2-11', 2, 11, 'hard', 'single', 'ABC üçbucağında AB = 21, AC = 17, BC = 10. Ən böyük tərəfə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,158.0 286.0,158.0 214.0,62.0"/><text x="21.3" y="165.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="166.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="220.4" y="55.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="154.1" y="173.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text><text x="112.5" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="261.7" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="214.0" y1="62.0" x2="214.0" y2="158.0" stroke-dasharray="5 4"/></svg>', '{"A": "84/5", "B": "9", "C": "4", "D": "8", "E": "168/17"}'::jsonb, 'D', NULL, 'p = 24, S = √(p(p − a)(p − b)(p − c)) = 84. h = 2S/21 = 8.');
INSERT INTO public.questions VALUES (4462, 59, 'g10-geo-basic-q2-12', 2, 12, 'medium', 'single', 'ABC üçbucağında ∠A = 72°, ∠B = 76°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="116.4,186.0 203.6,186.0 165.7,34.0"/><text x="107.7" y="200.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="211.9" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="166.2" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="116.4" y1="186.0" x2="161.6" y2="153.1" stroke-dasharray="5 4"/><line x1="203.6" y1="186.0" x2="161.6" y2="153.1" stroke-dasharray="5 4"/><circle cx="161.6" cy="153.1" r="2.6" fill="currentColor"/><text x="161.1" y="171.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "148°", "B": "74°", "C": "126°", "D": "164°", "E": "106°"}'::jsonb, 'E', NULL, '∠C = 180° − 72° − 76° = 32°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 106°.');
INSERT INTO public.questions VALUES (4463, 59, 'g10-geo-basic-q2-13', 2, 13, 'medium', 'single', 'ABC üçbucağında ∠A = 22°, ∠B = 104°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,160.9 260.6,160.9 286.0,59.1"/><text x="21.3" y="168.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="272.2" y="171.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.5" y="56.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="34.0" y1="160.9" x2="230.7" y2="122.7" stroke-dasharray="5 4"/><line x1="260.6" y1="160.9" x2="230.7" y2="122.7" stroke-dasharray="5 4"/><circle cx="230.7" cy="122.7" r="2.6" fill="currentColor"/><text x="222.2" y="137.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "117°", "B": "153°", "C": "101°", "D": "63°", "E": "126°"}'::jsonb, 'A', NULL, '∠C = 180° − 22° − 104° = 54°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 117°.');
INSERT INTO public.questions VALUES (4464, 59, 'g10-geo-basic-q2-14', 2, 14, 'hard', 'open', 'ABC üçbucağında AB = 15, AC = 24, BC = 15. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.4,170.8 205.6,170.8 231.1,83.2"/><text x="102.4" y="180.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.4" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="239.3" y="78.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="152.4" y="185.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="165.6" y="122.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="229.4" y="127.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', NULL, NULL, '25/2', 'p = 27, S = √(p(p − a)(p − b)(p − c)) = 108. R = abc/(4S) = 5400/432 = 25/2.');
INSERT INTO public.questions VALUES (4465, 59, 'g10-geo-basic-q2-15', 2, 15, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 22°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 130.5,186.0 189.5,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="123.9" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="196.1" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="130.5" y1="186.0" x2="185.2" y2="163.9" stroke-dasharray="5 4"/><text x="197.3" y="164.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "79°", "B": "68°", "C": "57°", "D": "63°", "E": "22°"}'::jsonb, 'C', NULL, '∠B = ∠C = (180° − 22°)/2 = 79°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·79° = 22°. ∠ABD = 79° − 22° = 57°.');
INSERT INTO public.questions VALUES (4466, 59, 'g10-geo-basic-q2-16', 2, 16, 'medium', 'single', 'ABC üçbucağında AB = 11, AC = 14, BC = 6. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,166.5 251.0,166.5 286.0,53.5"/><text x="21.4" y="174.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="262.1" y="178.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.2" y="50.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="133.1" y="179.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="149.8" y="108.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="280.2" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="166.5" x2="268.5" y2="110.0" stroke-dasharray="5 4"/><text x="281.2" y="112.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√670/2", "B": "√598/2", "C": "√602/2", "D": "√634/2", "E": "√299"}'::jsonb, 'B', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (242 + 392 − 36)/4 = 299/2 ⇒ AM = √598/2.');
INSERT INTO public.questions VALUES (4467, 59, 'g10-geo-basic-q2-17', 2, 17, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 13, BC = 6. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,153.3 286.0,153.3 234.5,66.7"/><text x="21.2" y="160.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="161.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="243.0" y="61.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="152.2" y="167.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="122.7" y="111.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="272.0" y="112.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="153.3" x2="258.4" y2="106.9" stroke-dasharray="5 4"/><text x="271.1" y="109.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "90/13", "B": "39/14", "C": "3", "D": "225/28", "E": "45/14"}'::jsonb, 'E', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 15 : 13. BD = 6·15/(15 + 13) = 45/14.');
INSERT INTO public.questions VALUES (4468, 59, 'g10-geo-basic-q2-18', 2, 18, 'hard', 'single', 'ABC üçbucağında AB = 11, AC = 8, BC = 17. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="109.7,161.7 286.0,161.7 34.0,58.3"/><text x="100.7" y="176.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="169.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.0" y="56.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="208.0" y="173.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="60.2" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="168.4" y="106.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="109.7" y1="161.7" x2="140.1" y2="101.8" stroke-dasharray="5 4"/><text x="146.0" y="95.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "121/19", "B": "187/8", "C": "17/2", "D": "136/19", "E": "187/19"}'::jsonb, 'E', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 11 : 8. BD = 17·11/(11 + 8) = 187/19.');
INSERT INTO public.questions VALUES (4469, 59, 'g10-geo-basic-q2-19', 2, 19, 'medium', 'single', 'ABC üçbucağında AB = 10, AC = 12, BC = 15. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="96.5,186.0 223.5,186.0 108.5,34.0"/><text x="87.7" y="200.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="234.5" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="104.4" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="163.8" y="202.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="92.3" y="108.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="174.1" y="106.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><line x1="96.5" y1="186.0" x2="166.0" y2="110.0" stroke-dasharray="5 4"/><text x="174.8" y="105.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√263/2", "B": "√526/2", "C": "√713/2", "D": "√122", "E": "√267/2"}'::jsonb, 'A', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (200 + 288 − 225)/4 = 263/4 ⇒ AM = √263/2.');
INSERT INTO public.questions VALUES (4470, 59, 'g10-geo-basic-q2-20', 2, 20, 'medium', 'single', 'ABC üçbucağında AB = 9, AC = 11, BC = 4. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,156.0 253.5,156.0 286.0,64.0"/><text x="21.2" y="163.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="265.1" y="166.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.9" y="62.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="133.7" y="167.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="149.2" y="109.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="281.5" y="112.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><line x1="34.0" y1="156.0" x2="269.7" y2="110.0" stroke-dasharray="5 4"/><text x="282.5" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "7√2", "B": "√97", "C": "√194", "D": "√101", "E": "√105"}'::jsonb, 'B', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (162 + 242 − 16)/4 = 97 ⇒ AM = √97.');
INSERT INTO public.questions VALUES (4471, 59, 'g10-geo-basic-q3-01', 3, 1, 'medium', 'single', 'ABC üçbucağında ∠A = 100°, ∠B = 46°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="113.4,186.0 233.4,186.0 86.6,34.0"/><text x="106.6" y="202.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="244.7" y="197.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="80.2" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="113.4" y1="186.0" x2="144.9" y2="148.4" stroke-dasharray="5 4"/><line x1="233.4" y1="186.0" x2="144.9" y2="148.4" stroke-dasharray="5 4"/><circle cx="144.9" cy="148.4" r="2.6" fill="currentColor"/><text x="150.8" y="165.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "163°", "B": "146°", "C": "107°", "D": "140°", "E": "73°"}'::jsonb, 'C', NULL, '∠C = 180° − 100° − 46° = 34°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 107°.');
INSERT INTO public.questions VALUES (4472, 59, 'g10-geo-basic-q3-02', 3, 2, 'hard', 'single', 'ABC üçbucağında AB = 9, AC = 13, BC = 12. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="101.0,186.0 219.0,186.0 178.2,34.0"/><text x="90.7" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="228.4" y="200.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="179.8" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.6" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="130.9" y="106.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="208.1" y="107.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="101.0" y1="186.0" x2="202.3" y2="123.8" stroke-dasharray="5 4"/><text x="213.4" y="122.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√89", "B": "9", "C": "3√1105/11", "D": "√10066/11", "E": "3√13"}'::jsonb, 'C', NULL, 'BD = 54/11, DC = 78/11. AD² = AB·AC − BD·DC = 117 − 4212/121 = 9945/121 ⇒ AD = 3√1105/11.');
INSERT INTO public.questions VALUES (4473, 59, 'g10-geo-basic-q3-03', 3, 3, 'hard', 'single', 'ABC üçbucağında AB = 24, AC = 30, BC = 18. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="99.2,155.6 220.8,155.6 220.8,64.4"/><text x="87.0" y="165.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="231.2" y="168.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="228.0" y="58.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="153.3" y="170.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="150.4" y="107.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="232.0" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "6", "B": "15", "C": "30", "D": "16", "E": "3240/217"}'::jsonb, 'B', NULL, 'p = 36, S = √(p(p − a)(p − b)(p − c)) = 216. R = abc/(4S) = 12960/864 = 15.');
INSERT INTO public.questions VALUES (4474, 59, 'g10-geo-basic-q3-04', 3, 4, 'medium', 'single', 'ABC üçbucağında ∠A = 50°, ∠B = 46°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,179.8 286.0,179.8 151.2,40.2"/><text x="21.8" y="189.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.2" y="189.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="150.3" y="32.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="151.2" y1="40.2" x2="151.2" y2="179.8" stroke-dasharray="5 4"/><line x1="151.2" y1="40.2" x2="156.0" y2="179.8" stroke-dasharray="5 4"/><polyline points="161.2,179.8 161.2,169.8 151.2,169.8" stroke-width="1.2"/><text x="151.2" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="156.5" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "4°", "B": "24°", "C": "42°", "D": "2°", "E": "7°"}'::jsonb, 'D', NULL, '∠C = 84°, ∠ACL = 42°. ∠ACH = 90° − ∠A = 40°. Aradakı bucaq |42° − (40°)| = |∠A − ∠B|/2 = 2°.');
INSERT INTO public.questions VALUES (4475, 59, 'g10-geo-basic-q3-05', 3, 5, 'medium', 'single', 'ABC üçbucağında ∠A = 98°, ∠B = 46°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="108.0,186.0 233.4,186.0 86.6,34.0"/><text x="100.6" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="244.7" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="80.3" y="27.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="86.6" y1="34.0" x2="86.6" y2="186.0" stroke-dasharray="5 4"/><line x1="86.6" y1="34.0" x2="160.7" y2="186.0" stroke-dasharray="5 4"/><polyline points="96.6,186.0 96.6,176.0 86.6,176.0" stroke-width="1.2"/><text x="86.6" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="166.4" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "36°", "B": "31°", "C": "18°", "D": "26°", "E": "52°"}'::jsonb, 'D', NULL, '∠C = 36°, ∠ACL = 18°. ∠ACH = 90° − ∠A = -8°. Aradakı bucaq |18° − (-8°)| = |∠A − ∠B|/2 = 26°.');
INSERT INTO public.questions VALUES (4476, 59, 'g10-geo-basic-q3-06', 3, 6, 'medium', 'single', 'ABC üçbucağında AB = 18, AC = 17, BC = 13. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="43.1,186.0 276.9,186.0 203.3,34.0"/><text x="30.9" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="288.6" y="196.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="206.9" y="26.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="156.7" y="202.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="112.4" y="109.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="251.3" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="43.1" y1="186.0" x2="240.1" y2="110.0" stroke-dasharray="5 4"/><text x="252.2" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√1061/2", "B": "√2114/2", "C": "3√155/2", "D": "√1226/2", "E": "√1057/2"}'::jsonb, 'E', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (648 + 578 − 169)/4 = 1057/4 ⇒ AM = √1057/2.');
INSERT INTO public.questions VALUES (4477, 59, 'g10-geo-basic-q3-07', 3, 7, 'medium', 'single', 'ABC üçbucağında AB = 16, AC = 7, BC = 14. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,158.2 286.0,158.2 87.6,61.8"/><text x="21.6" y="167.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="165.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="79.8" y="56.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="167.2" y="172.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="49.1" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="198.3" y="111.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="34.0" y1="158.2" x2="186.8" y2="110.0" stroke-dasharray="5 4"/><text x="199.2" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "3√23", "B": "√806/2", "C": "√610/2", "D": "√418/2", "E": "3√46/2"}'::jsonb, 'E', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (512 + 98 − 196)/4 = 207/2 ⇒ AM = 3√46/2.');
INSERT INTO public.questions VALUES (4478, 59, 'g10-geo-basic-q3-08', 3, 8, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 7, BC = 9. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="35.8,186.0 284.2,186.0 120.3,34.0"/><text x="24.0" y="196.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="296.4" y="195.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="117.0" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="163.0" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="66.8" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="213.1" y="110.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><line x1="35.8" y1="186.0" x2="187.8" y2="96.6" stroke-dasharray="5 4"/><text x="199.0" y="95.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "100/17", "B": "9/2", "C": "63/17", "D": "90/17", "E": "90/7"}'::jsonb, 'D', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 10 : 7. BD = 9·10/(10 + 7) = 90/17.');
INSERT INTO public.questions VALUES (4479, 59, 'g10-geo-basic-q3-09', 3, 9, 'medium', 'single', 'ABC üçbucağında ∠A = 94°, ∠B = 52°. A və B bucaqlarının tənbölənləri O nöqtəsində kəsişir. ∠AOB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="111.3,186.0 219.4,186.0 100.6,34.0"/><text x="104.2" y="201.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.2" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="95.5" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="111.3" y1="186.0" x2="145.1" y2="149.8" stroke-dasharray="5 4"/><line x1="219.4" y1="186.0" x2="145.1" y2="149.8" stroke-dasharray="5 4"/><circle cx="145.1" cy="149.8" r="2.6" fill="currentColor"/><text x="149.7" y="166.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "146°", "B": "107°", "C": "163°", "D": "73°", "E": "137°"}'::jsonb, 'B', NULL, '∠C = 180° − 94° − 52° = 34°. ∠AOB = 180° − (∠A + ∠B)/2 = 90° + ∠C/2 = 107°.');
INSERT INTO public.questions VALUES (4480, 59, 'g10-geo-basic-q3-10', 3, 10, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 8, BC = 10. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="122.6,186.0 218.5,186.0 101.5,34.0"/><text x="116.9" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="229.1" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="96.1" y="27.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="175.5" y="201.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="102.3" y="108.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="165.3" y="104.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="122.6" y1="186.0" x2="173.5" y2="127.5" stroke-dasharray="5 4"/><text x="182.0" y="122.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "80/13", "B": "25/4", "C": "50/13", "D": "5", "E": "25/13"}'::jsonb, 'C', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 5 : 8. BD = 10·5/(5 + 8) = 50/13.');
INSERT INTO public.questions VALUES (4481, 59, 'g10-geo-basic-q3-11', 3, 11, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 15 və HB = 10 parçalarına bölür. CH hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.7 286.0,171.7 185.2,48.3"/><line x1="185.2" y1="48.3" x2="185.2" y2="171.7" stroke-dasharray="5 4"/><polyline points="195.2,171.7 195.2,161.7 185.2,161.7" stroke-width="1.2"/><polyline points="177.5,54.6 183.8,62.3 191.5,56.0" stroke-width="1.2"/><text x="21.6" y="180.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="181.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.8" y="40.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="185.2" y="189.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="103.3" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="240.1" y="187.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "5√15", "B": "5√10", "C": "5√13", "D": "25/2", "E": "5√6"}'::jsonb, 'E', NULL, 'CH² = AH·HB = 15·10 = 150 ⇒ CH = 5√6.');
INSERT INTO public.questions VALUES (4482, 59, 'g10-geo-basic-q3-12', 3, 12, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 8, BC = 5. Ən böyük tərəfə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="58.7,186.0 217.0,186.0 261.3,34.0"/><text x="46.7" y="196.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="224.8" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="269.5" y="28.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="130.3" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="152.8" y="105.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="250.2" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><line x1="217.0" y1="186.0" x2="160.0" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "6", "B": "4", "C": "3/2", "D": "24/5", "E": "3"}'::jsonb, 'E', NULL, 'p = 9, S = √(p(p − a)(p − b)(p − c)) = 12. h = 2S/8 = 3.');
INSERT INTO public.questions VALUES (4483, 59, 'g10-geo-basic-q3-13', 3, 13, 'medium', 'single', 'ABC üçbucağında AB = 13, AC = 6, BC = 12. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,163.5 286.0,163.5 79.5,56.5"/><text x="21.8" y="172.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="171.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="71.7" y="51.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="167.2" y="178.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="45.1" y="112.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="194.0" y="110.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="34.0" y1="163.5" x2="182.7" y2="110.0" stroke-dasharray="5 4"/><text x="195.0" y="110.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√410/2", "B": "√266/2", "C": "3√30/2", "D": "√133", "E": "√554/2"}'::jsonb, 'B', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (338 + 72 − 144)/4 = 133/2 ⇒ AM = √266/2.');
INSERT INTO public.questions VALUES (4484, 59, 'g10-geo-basic-q3-14', 3, 14, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 9 və HB = 15 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.0 286.0,171.0 128.5,49.0"/><line x1="128.5" y1="49.0" x2="128.5" y2="171.0" stroke-dasharray="5 4"/><polyline points="138.5,171.0 138.5,161.0 128.5,161.0" stroke-width="1.2"/><polyline points="122.4,56.9 130.3,63.0 136.4,55.1" stroke-width="1.2"/><text x="21.7" y="180.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="179.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="125.2" y="41.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="128.5" y="189.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="76.9" y="187.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="213.8" y="186.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "3√34", "B": "3√55", "C": "3√15", "D": "6√6", "E": "6√10"}'::jsonb, 'D', NULL, 'AC² = AH·AB = 9·24 = 216 ⇒ AC = 6√6.');
INSERT INTO public.questions VALUES (4485, 59, 'g10-geo-basic-q3-15', 3, 15, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 14°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 141.3,186.0 178.7,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="136.8" y="203.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="183.2" y="203.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="141.3" y1="186.0" x2="177.6" y2="177.0" stroke-dasharray="5 4"/><text x="190.2" y="178.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "76°", "B": "83°", "C": "69°", "D": "14°", "E": "75°"}'::jsonb, 'C', NULL, '∠B = ∠C = (180° − 14°)/2 = 83°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·83° = 14°. ∠ABD = 83° − 14° = 69°.');
INSERT INTO public.questions VALUES (4486, 59, 'g10-geo-basic-q3-16', 3, 16, 'hard', 'single', 'ABC bərabəryanlı üçbucağında AB = AC və ∠A = 40°. AC tərəfi üzərində D nöqtəsi elə götürülüb ki, BD = BC. ∠ABD-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 104.7,186.0 215.3,186.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="95.1" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="224.9" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="104.7" y1="186.0" x2="189.4" y2="114.9" stroke-dasharray="5 4"/><text x="199.4" y="111.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "30°", "B": "50°", "C": "40°", "D": "70°", "E": "36°"}'::jsonb, 'A', NULL, '∠B = ∠C = (180° − 40°)/2 = 70°. BDC bərabəryanlıdır: ∠BDC = ∠C, ∠DBC = 180° − 2·70° = 40°. ∠ABD = 70° − 40° = 30°.');
INSERT INTO public.questions VALUES (4487, 59, 'g10-geo-basic-q3-17', 3, 17, 'hard', 'single', 'ABC üçbucağında AB = 26, AC = 8, BC = 30. Ən böyük tərəfə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="60.7,142.0 286.0,142.0 34.0,78.0"/><text x="48.3" y="151.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="148.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="22.2" y="77.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="184.2" y="152.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">26</text><text x="35.4" y="113.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="171.4" y="111.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><line x1="60.7" y1="142.0" x2="74.3" y2="88.2" stroke-dasharray="5 4"/></svg>', '{"A": "16/5", "B": "32/5", "C": "24", "D": "96/13", "E": "37/5"}'::jsonb, 'B', NULL, 'p = 32, S = √(p(p − a)(p − b)(p − c)) = 96. h = 2S/30 = 32/5.');
INSERT INTO public.questions VALUES (4488, 59, 'g10-geo-basic-q3-18', 3, 18, 'medium', 'single', 'ABC üçbucağında AB = 6, AC = 8, BC = 12. A təpəsindən çəkilmiş AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="135.1,186.0 263.3,186.0 56.7,34.0"/><text x="131.0" y="203.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="275.2" y="196.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="47.8" y="29.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="207.4" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="84.9" y="110.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="163.7" y="103.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="135.1" y1="186.0" x2="160.0" y2="110.0" stroke-dasharray="5 4"/><text x="164.1" y="102.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "2√7", "B": "√15", "C": "√14", "D": "5√2", "E": "√86"}'::jsonb, 'C', NULL, 'm² = (2AB² + 2AC² − BC²)/4 = (72 + 128 − 144)/4 = 14 ⇒ AM = √14.');
INSERT INTO public.questions VALUES (4489, 59, 'g10-geo-basic-q3-19', 3, 19, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlüyü hipotenuzu AH = 4 və HB = 12 parçalarına bölür. AC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 97.0,55.4"/><line x1="97.0" y1="55.4" x2="97.0" y2="164.6" stroke-dasharray="5 4"/><polyline points="107.0,164.6 107.0,154.6 97.0,154.6" stroke-width="1.2"/><polyline points="92.0,64.1 100.7,69.1 105.7,60.4" stroke-width="1.2"/><text x="21.7" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="90.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="97.0" y="182.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="62.2" y="181.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="199.4" y="178.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "8√3", "B": "4√10", "C": "4√15", "D": "4√3", "E": "8"}'::jsonb, 'E', NULL, 'AC² = AH·AB = 4·16 = 64 ⇒ AC = 8.');
INSERT INTO public.questions VALUES (4490, 59, 'g10-geo-basic-q3-20', 3, 20, 'hard', 'single', 'ABC üçbucağında AB = 14, AC = 13, BC = 7. AD — A bucağının tənbölənidir (D ∈ BC). BD parçasını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,168.1 286.0,168.1 237.1,51.9"/><text x="21.4" y="176.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.1" y="177.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="244.3" y="46.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="153.4" y="183.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="124.4" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="273.2" y="112.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><line x1="34.0" y1="168.1" x2="260.7" y2="107.8" stroke-dasharray="5 4"/><text x="273.2" y="109.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "91/27", "B": "98/27", "C": "7/2", "D": "98/13", "E": "196/27"}'::jsonb, 'B', NULL, 'Tənbölən xassəsi: BD : DC = AB : AC = 14 : 13. BD = 7·14/(14 + 13) = 98/27.');
INSERT INTO public.questions VALUES (4491, 60, 'g10-geo-poly-q1-01', 1, 1, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 25 və 13, yan tərəfi 12 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,162.4 286.0,162.4 225.5,57.6 94.5,57.6"/><text x="22.0" y="172.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.0" y="172.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="235.7" y="54.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="84.3" y="54.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="160.0" y="50.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="267.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="52.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "57√3", "B": "114√3", "C": "228", "D": "228√3", "E": "19√109"}'::jsonb, 'B', NULL, 'h = √(12² − 6²) = 6√3. S = (25 + 13)/2 · h = 114√3.');
INSERT INTO public.questions VALUES (4492, 60, 'g10-geo-poly-q1-02', 1, 2, 'medium', 'single', 'Rombun diaqonalları 30 və 72 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 191.7,110.0 160.0,186.0 128.3,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="204.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="115.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="191.7" y1="110.0" x2="128.3" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "360/13", "B": "373/13", "C": "51", "D": "720/13", "E": "180/13"}'::jsonb, 'A', NULL, 'Tərəf: √(15² + 36²) = 39. S = d₁d₂/2 = 1080. h = S/a = 1080/39 = 360/13.');
INSERT INTO public.questions VALUES (4493, 60, 'g10-geo-poly-q1-03', 1, 3, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 15 və 7, yan tərəfi 14 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="75.0,186.0 245.0,186.0 199.7,34.0 120.3,34.0"/><text x="65.3" y="199.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="254.7" y="199.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="205.7" y="27.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="114.3" y="27.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="234.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="85.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "33√5", "B": "154", "C": "66√5", "D": "132√5", "E": "11√181"}'::jsonb, 'C', NULL, 'h = √(14² − 4²) = 6√5. S = (15 + 7)/2 · h = 66√5.');
INSERT INTO public.questions VALUES (4494, 60, 'g10-geo-poly-q1-04', 1, 4, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 11 və 3, yan tərəfi 9 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="56.3,186.0 263.7,186.0 188.3,34.0 131.7,34.0"/><text x="45.8" y="198.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="274.2" y="198.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="192.8" y="26.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="127.2" y="26.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="238.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="82.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text></svg>', '{"A": "7√66", "B": "7√65/2", "C": "14√65", "D": "63", "E": "7√65"}'::jsonb, 'E', NULL, 'h = √(9² − 4²) = √65. S = (11 + 3)/2 · h = 7√65.');
INSERT INTO public.questions VALUES (4495, 60, 'g10-geo-poly-q1-05', 1, 5, 'medium', 'single', 'Paraleloqramın tərəfləri 6 və 4, aralarındakı bucaq 45° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,150.4 205.3,150.4 286.0,69.6 114.7,69.6"/><text x="21.6" y="159.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="215.0" y="164.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.4" y="70.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="105.0" y="66.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="111.1" y="163.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="62.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><path d="M52.0,150.4 A18,18 0 0 0 46.7,137.6" stroke-width="1.2"/><text x="62.6" y="143.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text></svg>', '{"A": "12√3", "B": "12√2", "C": "12", "D": "24", "E": "24√2"}'::jsonb, 'B', NULL, 'S = a·b·sin 45° = 6·4·√2/2 = 12√2.');
INSERT INTO public.questions VALUES (4496, 60, 'g10-geo-poly-q1-06', 1, 6, 'medium', 'single', 'Rombun diaqonalları 16 və 30 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 200.5,110.0 160.0,186.0 119.5,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="106.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="200.5" y1="110.0" x2="119.5" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "257/17", "B": "480/17", "C": "240/17", "D": "23", "E": "120/17"}'::jsonb, 'C', NULL, 'Tərəf: √(8² + 15²) = 17. S = d₁d₂/2 = 240. h = S/a = 240/17 = 240/17.');
INSERT INTO public.questions VALUES (4497, 60, 'g10-geo-poly-q1-07', 1, 7, 'medium', 'open', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 6 : 4 nisbətində bölür. Düzbucaqlının perimetri 32 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,185.6 34.0,34.4 286.0,34.4 286.0,185.6"/><text x="22.9" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.9" y="32.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.1" y="32.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.1" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="185.6" x2="185.2" y2="34.4" stroke-dasharray="5 4"/><text x="194.4" y="30.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', NULL, NULL, '60', '∠BAK = 45° ⇒ AB = BK = 6t, BC = 10t. Perimetr 2(16t) = 32 ⇒ t = 1. S = 6·10 = 60.');
INSERT INTO public.questions VALUES (4498, 60, 'g10-geo-poly-q1-08', 1, 8, 'medium', 'single', 'Düzgün altıbucaqlının tərəfi 7 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "147√3", "B": "147√3/4", "C": "294", "D": "147√3/2", "E": "49√3/4"}'::jsonb, 'D', NULL, '6 bərabərtərəfli üçbucaq: S = 6·7²√3/4 = 147√3/2.');
INSERT INTO public.questions VALUES (4499, 60, 'g10-geo-poly-q1-09', 1, 9, 'medium', 'single', 'Düzgün altıbucaqlının tərəfi 2 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "24", "B": "3√3", "C": "12√3", "D": "6√3", "E": "√3"}'::jsonb, 'D', NULL, '6 bərabərtərəfli üçbucaq: S = 6·2²√3/4 = 6√3.');
INSERT INTO public.questions VALUES (4500, 60, 'g10-geo-poly-q1-10', 1, 10, 'medium', 'single', 'Paraleloqramın tərəfləri 4 və 9, aralarındakı bucaq 45° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="36.2,186.0 131.8,186.0 283.8,34.0 188.2,34.0"/><text x="25.2" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="127.2" y="203.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="294.8" y="32.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="192.8" y="26.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="75.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="100.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><path d="M54.2,186.0 A18,18 0 0 0 49.0,173.3" stroke-width="1.2"/><text x="64.9" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text></svg>', '{"A": "36√2", "B": "18", "C": "18√2", "D": "36", "E": "18√3"}'::jsonb, 'C', NULL, 'S = a·b·sin 45° = 4·9·√2/2 = 18√2.');
INSERT INTO public.questions VALUES (4501, 60, 'g10-geo-poly-q1-11', 1, 11, 'medium', 'single', 'Paraleloqramın tərəfləri 14 və 5, aralarındakı bucaq 30° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,127.2 226.5,127.2 286.0,92.8 93.5,92.8"/><text x="21.1" y="133.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="239.1" y="135.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.9" y="96.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="80.9" y="94.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="119.8" y="138.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="51.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M52.0,127.2 A18,18 0 0 0 49.6,118.2" stroke-width="1.2"/><text x="63.9" y="124.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text></svg>', '{"A": "35/2", "B": "70", "C": "35", "D": "35√2", "E": "35√3"}'::jsonb, 'C', NULL, 'S = a·b·sin 30° = 14·5·1/2 = 35.');
INSERT INTO public.questions VALUES (4502, 60, 'g10-geo-poly-q1-12', 1, 12, 'medium', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 8. AC diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><line x1="247.8" y1="110.0" x2="116.1" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "8√2", "B": "16√3", "C": "16", "D": "4√3", "E": "8√3"}'::jsonb, 'E', NULL, '∠ABC = 120°: AC² = 8² + 8² − 2·8·8·cos 120° = 3·64 ⇒ AC = 8√3.');
INSERT INTO public.questions VALUES (4503, 60, 'g10-geo-poly-q1-13', 1, 13, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 9 və 3, yan tərəfi 13 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="105.9,186.0 214.1,186.0 178.0,34.0 142.0,34.0"/><text x="98.4" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="221.6" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="181.0" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="139.0" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="208.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="112.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="105.9" y1="186.0" x2="178.0" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√241", "B": "14", "C": "√178", "D": "13", "E": "√197"}'::jsonb, 'B', NULL, 'Hündürlük: h² = 13² − ((9 − 3)/2)² = 160. Diaqonalın proyeksiyası (9 + 3)/2 = 6. d = √(160 + 36) = 14.');
INSERT INTO public.questions VALUES (4504, 60, 'g10-geo-poly-q1-14', 1, 14, 'medium', 'open', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 6 : 3 nisbətində bölür. Düzbucaqlının perimetri 120 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 46.0,34.0 274.0,34.0 274.0,186.0"/><text x="35.2" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="35.2" y="31.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="284.8" y="31.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="284.8" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="46.0" y1="186.0" x2="198.0" y2="34.0" stroke-dasharray="5 4"/><text x="207.2" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', NULL, NULL, '864', '∠BAK = 45° ⇒ AB = BK = 6t, BC = 9t. Perimetr 2(15t) = 120 ⇒ t = 4. S = 24·36 = 864.');
INSERT INTO public.questions VALUES (4505, 60, 'g10-geo-poly-q1-15', 1, 15, 'medium', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 2160° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "11", "B": "154", "C": "84", "D": "77", "E": "90"}'::jsonb, 'D', NULL, '180°(n − 2) = 2160° ⇒ n = 14. Diaqonallar: n(n − 3)/2 = 77.');
INSERT INTO public.questions VALUES (4506, 60, 'g10-geo-poly-q1-16', 1, 16, 'medium', 'single', 'Paraleloqramın tərəfləri 4 və 13, aralarındakı bucaq 60° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="89.1,186.0 143.1,186.0 230.9,34.0 176.9,34.0"/><text x="80.3" y="200.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="140.3" y="203.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="239.7" y="29.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="179.7" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="110.1" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="121.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><path d="M107.1,186.0 A18,18 0 0 0 98.1,170.4" stroke-width="1.2"/><text x="116.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="89.1" y1="186.0" x2="230.9" y2="34.0" stroke-dasharray="5 4"/><line x1="143.1" y1="186.0" x2="176.9" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√133", "B": "√370", "C": "17", "D": "√237", "E": "√185"}'::jsonb, 'D', NULL, 'Kosinuslar teoremi: d² = 4² + 13² ∓ 2·4·13·cos 60°. Böyük diaqonal √237, kiçik diaqonal √133. Cavab: √237.');
INSERT INTO public.questions VALUES (4507, 60, 'g10-geo-poly-q1-17', 1, 17, 'medium', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 5940° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "577", "B": "594", "C": "560", "D": "32", "E": "1120"}'::jsonb, 'C', NULL, '180°(n − 2) = 5940° ⇒ n = 35. Diaqonallar: n(n − 3)/2 = 560.');
INSERT INTO public.questions VALUES (4508, 60, 'g10-geo-poly-q1-18', 1, 18, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 5 : 6 nisbətində bölür. Düzbucaqlının perimetri 32 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,167.3 34.0,52.7 286.0,52.7 286.0,167.3"/><text x="22.2" y="177.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.2" y="52.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.8" y="52.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.8" y="177.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="167.3" x2="148.5" y2="52.7" stroke-dasharray="5 4"/><text x="157.7" y="48.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "121", "B": "60", "C": "25", "D": "55", "E": "50"}'::jsonb, 'D', NULL, '∠BAK = 45° ⇒ AB = BK = 5t, BC = 11t. Perimetr 2(16t) = 32 ⇒ t = 1. S = 5·11 = 55.');
INSERT INTO public.questions VALUES (4509, 60, 'g10-geo-poly-q1-19', 1, 19, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 6, KC = 8 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.0 34.0,56.0 286.0,56.0 286.0,164.0"/><text x="22.1" y="174.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.1" y="55.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.9" y="55.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.9" y="174.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="164.0" x2="142.0" y2="56.0" stroke-dasharray="5 4"/><text x="151.2" y="51.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "24", "B": "40", "C": "28", "D": "44", "E": "52"}'::jsonb, 'B', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 6. BC = 14. P = 2(6 + 14) = 40.');
INSERT INTO public.questions VALUES (4510, 60, 'g10-geo-poly-q1-20', 1, 20, 'medium', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 4680° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "700", "B": "377", "C": "25", "D": "364", "E": "350"}'::jsonb, 'E', NULL, '180°(n − 2) = 4680° ⇒ n = 28. Diaqonallar: n(n − 3)/2 = 350.');
INSERT INTO public.questions VALUES (4511, 60, 'g10-geo-poly-q2-01', 2, 1, 'medium', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 9. AC diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><line x1="247.8" y1="110.0" x2="116.1" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "18√3", "B": "18", "C": "9√2", "D": "9√3", "E": "9√3/2"}'::jsonb, 'D', NULL, '∠ABC = 120°: AC² = 9² + 9² − 2·9·9·cos 120° = 3·81 ⇒ AC = 9√3.');
INSERT INTO public.questions VALUES (4512, 60, 'g10-geo-poly-q2-02', 2, 2, 'medium', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 3780° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "20", "B": "241", "C": "460", "D": "252", "E": "230"}'::jsonb, 'E', NULL, '180°(n − 2) = 3780° ⇒ n = 23. Diaqonallar: n(n − 3)/2 = 230.');
INSERT INTO public.questions VALUES (4513, 60, 'g10-geo-poly-q2-03', 2, 3, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 14 və 6, yan tərəfi 18 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="99.4,186.0 220.6,186.0 186.0,34.0 134.0,34.0"/><text x="91.3" y="201.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="228.7" y="201.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="190.2" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="129.8" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="215.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="104.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text></svg>', '{"A": "10√309", "B": "20√77", "C": "180", "D": "40√77", "E": "10√77"}'::jsonb, 'B', NULL, 'h = √(18² − 4²) = 2√77. S = (14 + 6)/2 · h = 20√77.');
INSERT INTO public.questions VALUES (4514, 60, 'g10-geo-poly-q2-04', 2, 4, 'medium', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 6. ACE üçbucağının sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><polygon points="247.8,110.0 116.1,34.0 116.1,186.0"/></svg>', '{"A": "18√3", "B": "9√3", "C": "27√3/2", "D": "27√3", "E": "54√3"}'::jsonb, 'D', NULL, 'ACE bərabərtərəflidir, tərəfi AC = 6√3. S = (√3/4)·3·36 = 27√3. (Altıbucaqlının sahəsinin yarısı.)');
INSERT INTO public.questions VALUES (4515, 60, 'g10-geo-poly-q2-05', 2, 5, 'medium', 'single', 'Rombun diaqonalları 42 və 144 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 182.2,110.0 160.0,186.0 137.8,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="195.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="124.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="182.2" y1="110.0" x2="137.8" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "93", "B": "504/25", "C": "2016/25", "D": "1033/25", "E": "1008/25"}'::jsonb, 'E', NULL, 'Tərəf: √(21² + 72²) = 75. S = d₁d₂/2 = 3024. h = S/a = 3024/75 = 1008/25.');
INSERT INTO public.questions VALUES (4516, 60, 'g10-geo-poly-q2-06', 2, 6, 'medium', 'single', 'Paraleloqramın tərəfləri 5 və 6, aralarındakı bucaq 135° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="149.7,167.8 286.0,167.8 170.3,52.2 34.0,52.2"/><text x="147.4" y="185.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.8" y="178.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="172.6" y="44.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="22.2" y="51.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="226.3" y="181.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="79.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M167.7,167.8 A18,18 0 0 0 136.9,155.1" stroke-width="1.2"/><text x="161.5" y="144.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text></svg>', '{"A": "15√3", "B": "15√2", "C": "15", "D": "30√2", "E": "30"}'::jsonb, 'B', NULL, 'S = a·b·sin 135° = 5·6·√2/2 = 15√2.');
INSERT INTO public.questions VALUES (4517, 60, 'g10-geo-poly-q2-07', 2, 7, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 13 və 3, yan tərəfi 19 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="106.1,186.0 213.9,186.0 172.4,34.0 147.6,34.0"/><text x="98.6" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="221.4" y="201.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="174.5" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="145.5" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="205.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><text x="114.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text></svg>', '{"A": "8√337", "B": "32√21", "C": "152", "D": "64√21", "E": "16√21"}'::jsonb, 'B', NULL, 'h = √(19² − 5²) = 4√21. S = (13 + 3)/2 · h = 32√21.');
INSERT INTO public.questions VALUES (4518, 60, 'g10-geo-poly-q2-08', 2, 8, 'medium', 'single', 'Paraleloqramın tərəfləri 11 və 10, aralarındakı bucaq 135° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="132.6,159.3 286.0,159.3 187.4,60.7 34.0,60.7"/><text x="126.3" y="175.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.1" y="169.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="193.7" y="54.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.9" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="217.8" y="172.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="71.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><path d="M150.6,159.3 A18,18 0 0 0 119.9,146.6" stroke-width="1.2"/><text x="144.5" y="135.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text></svg>', '{"A": "55√2", "B": "110", "C": "55√3", "D": "110√2", "E": "55"}'::jsonb, 'A', NULL, 'S = a·b·sin 135° = 11·10·√2/2 = 55√2.');
INSERT INTO public.questions VALUES (4519, 60, 'g10-geo-poly-q2-09', 2, 9, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 12 və 2, yan tərəfi 9 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="38.1,186.0 281.9,186.0 180.3,34.0 139.7,34.0"/><text x="27.1" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.9" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="183.7" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="136.3" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="243.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="76.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><line x1="38.1" y1="186.0" x2="180.3" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√105", "B": "√85", "C": "√106", "D": "9", "E": "10√2"}'::jsonb, 'A', NULL, 'Hündürlük: h² = 9² − ((12 − 2)/2)² = 56. Diaqonalın proyeksiyası (12 + 2)/2 = 7. d = √(56 + 49) = √105.');
INSERT INTO public.questions VALUES (4520, 60, 'g10-geo-poly-q2-10', 2, 10, 'medium', 'single', 'Düzgün altıbucaqlının tərəfi 4 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "48√3", "B": "24√3", "C": "4√3", "D": "12√3", "E": "96"}'::jsonb, 'B', NULL, '6 bərabərtərəfli üçbucaq: S = 6·4²√3/4 = 24√3.');
INSERT INTO public.questions VALUES (4521, 60, 'g10-geo-poly-q2-11', 2, 11, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 4 və 2, yan tərəfi 14 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="138.2,186.0 181.8,186.0 170.9,34.0 149.1,34.0"/><text x="134.7" y="203.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="185.3" y="203.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="172.7" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="147.3" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="188.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="131.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "42", "B": "4√195", "C": "3√195", "D": "3√195/2", "E": "6√195"}'::jsonb, 'C', NULL, 'h = √(14² − 1²) = √195. S = (4 + 2)/2 · h = 3√195.');
INSERT INTO public.questions VALUES (4522, 60, 'g10-geo-poly-q2-12', 2, 12, 'medium', 'single', 'Paraleloqramın tərəfləri 4 və 11, aralarındakı bucaq 30° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,161.2 108.5,161.2 286.0,58.8 211.5,58.8"/><text x="22.0" y="171.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="99.3" y="175.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.0" y="58.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="220.7" y="54.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="60.9" y="172.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="110.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><path d="M52.0,161.2 A18,18 0 0 0 49.6,152.2" stroke-width="1.2"/><text x="63.9" y="158.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text></svg>', '{"A": "22√2", "B": "22√3", "C": "44", "D": "22", "E": "11"}'::jsonb, 'D', NULL, 'S = a·b·sin 30° = 4·11·1/2 = 22.');
INSERT INTO public.questions VALUES (4523, 60, 'g10-geo-poly-q2-13', 2, 13, 'medium', 'single', 'Rombun diaqonalları 32 və 60 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 200.5,110.0 160.0,186.0 119.5,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="106.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="200.5" y1="110.0" x2="119.5" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "960/17", "B": "480/17", "C": "46", "D": "240/17", "E": "497/17"}'::jsonb, 'B', NULL, 'Tərəf: √(16² + 30²) = 34. S = d₁d₂/2 = 960. h = S/a = 960/34 = 480/17.');
INSERT INTO public.questions VALUES (4524, 60, 'g10-geo-poly-q2-14', 2, 14, 'medium', 'open', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 12, KC = 12 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 34.0,47.0 286.0,47.0 286.0,173.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.4" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.6" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="173.0" x2="160.0" y2="47.0" stroke-dasharray="5 4"/><text x="169.2" y="42.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', NULL, NULL, '72', '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 12. BC = 24. P = 2(12 + 24) = 72.');
INSERT INTO public.questions VALUES (4525, 60, 'g10-geo-poly-q2-15', 2, 15, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 15, KC = 18 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,167.3 34.0,52.7 286.0,52.7 286.0,167.3"/><text x="22.2" y="177.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.2" y="52.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.8" y="52.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.8" y="177.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="167.3" x2="148.5" y2="52.7" stroke-dasharray="5 4"/><text x="157.7" y="48.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "102", "B": "60", "C": "126", "D": "66", "E": "96"}'::jsonb, 'E', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 15. BC = 33. P = 2(15 + 33) = 96.');
INSERT INTO public.questions VALUES (4526, 60, 'g10-geo-poly-q2-16', 2, 16, 'medium', 'single', 'Rombun diaqonalları 120 və 126 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 232.4,110.0 160.0,186.0 87.6,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="74.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="232.4" y1="110.0" x2="87.6" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "2520/29", "B": "5040/29", "C": "123", "D": "1260/29", "E": "2549/29"}'::jsonb, 'A', NULL, 'Tərəf: √(60² + 63²) = 87. S = d₁d₂/2 = 7560. h = S/a = 7560/87 = 2520/29.');
INSERT INTO public.questions VALUES (4527, 60, 'g10-geo-poly-q2-17', 2, 17, 'medium', 'single', 'Paraleloqramın tərəfləri 13 və 14, aralarındakı bucaq 150° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="155.6,145.1 286.0,145.1 164.4,74.9 34.0,74.9"/><text x="154.0" y="163.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="153.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="166.0" y="67.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.5" y="76.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="231.2" y="156.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="82.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><path d="M173.6,145.1 A18,18 0 0 0 140.0,136.1" stroke-width="1.2"/><text x="163.6" y="120.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">150°</text></svg>', '{"A": "91√2", "B": "91", "C": "91/2", "D": "91√3", "E": "182"}'::jsonb, 'B', NULL, 'S = a·b·sin 150° = 13·14·1/2 = 91.');
INSERT INTO public.questions VALUES (4528, 60, 'g10-geo-poly-q2-18', 2, 18, 'medium', 'single', 'Düzgün çoxbucaqlının hər daxili bucağı 140° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "27", "B": "6", "C": "35", "D": "54", "E": "31"}'::jsonb, 'A', NULL, 'Xarici bucaq 180° − 140° = 40°, n = 360 : 40 = 9. Diaqonallar: n(n − 3)/2 = 27.');
INSERT INTO public.questions VALUES (4529, 60, 'g10-geo-poly-q2-19', 2, 19, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 6 : 6 nisbətində bölür. Düzbucaqlının perimetri 144 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 34.0,47.0 286.0,47.0 286.0,173.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.4" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.6" y="46.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="173.0" x2="160.0" y2="47.0" stroke-dasharray="5 4"/><text x="169.2" y="42.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "2304", "B": "1176", "C": "1128", "D": "1152", "E": "576"}'::jsonb, 'D', NULL, '∠BAK = 45° ⇒ AB = BK = 6t, BC = 12t. Perimetr 2(18t) = 144 ⇒ t = 4. S = 24·48 = 1152.');
INSERT INTO public.questions VALUES (4530, 60, 'g10-geo-poly-q2-20', 2, 20, 'medium', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 3420° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "189", "B": "199", "C": "209", "D": "18", "E": "378"}'::jsonb, 'A', NULL, '180°(n − 2) = 3420° ⇒ n = 21. Diaqonallar: n(n − 3)/2 = 189.');
INSERT INTO public.questions VALUES (4531, 60, 'g10-geo-poly-q3-01', 3, 1, 'medium', 'single', 'Rombun diaqonalları 40 və 42 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 232.4,110.0 160.0,186.0 87.6,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="74.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="232.4" y1="110.0" x2="87.6" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="52.4"/></svg>', '{"A": "840/29", "B": "29/2", "C": "210/29", "D": "420/29", "E": "449/29"}'::jsonb, 'D', NULL, 'Tərəf 29. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 840/58 = 420/29.');
INSERT INTO public.questions VALUES (4532, 60, 'g10-geo-poly-q3-02', 3, 2, 'medium', 'single', 'Paraleloqramın tərəfləri 9 və 8, aralarındakı bucaq 150° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="143.6,141.6 286.0,141.6 176.4,78.4 34.0,78.4"/><text x="137.6" y="158.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="149.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="182.4" y="71.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.4" y="80.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="225.2" y="152.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="76.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><path d="M161.6,141.6 A18,18 0 0 0 128.0,132.6" stroke-width="1.2"/><text x="151.6" y="116.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">150°</text></svg>', '{"A": "72", "B": "18", "C": "36√2", "D": "36", "E": "36√3"}'::jsonb, 'D', NULL, 'S = a·b·sin 150° = 9·8·1/2 = 36.');
INSERT INTO public.questions VALUES (4533, 60, 'g10-geo-poly-q3-03', 3, 3, 'medium', 'single', 'Paraleloqramın tərəfləri 3 və 5, aralarındakı bucaq 120° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="151.2,186.0 256.5,186.0 168.8,34.0 63.5,34.0"/><text x="149.7" y="203.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="266.7" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="170.3" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="53.3" y="31.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="209.9" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="95.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M169.2,186.0 A18,18 0 0 0 142.2,170.4" stroke-width="1.2"/><text x="166.7" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="151.2" y1="186.0" x2="168.8" y2="34.0" stroke-dasharray="5 4"/><line x1="256.5" y1="186.0" x2="63.5" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "7", "B": "√34", "C": "2√17", "D": "8", "E": "√19"}'::jsonb, 'A', NULL, 'Kosinuslar teoremi: d² = 3² + 5² ∓ 2·3·5·cos 60°. Böyük diaqonal √49, kiçik diaqonal √19. Cavab: 7.');
INSERT INTO public.questions VALUES (4534, 60, 'g10-geo-poly-q3-04', 3, 4, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 4, KC = 1 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="65.0,186.0 65.0,34.0 255.0,34.0 255.0,186.0"/><text x="54.8" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="54.8" y="30.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="265.2" y="30.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="265.2" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="65.0" y1="186.0" x2="217.0" y2="34.0" stroke-dasharray="5 4"/><text x="226.2" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "18", "B": "10", "C": "16", "D": "12", "E": "26"}'::jsonb, 'A', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 4. BC = 5. P = 2(4 + 5) = 18.');
INSERT INTO public.questions VALUES (4535, 60, 'g10-geo-poly-q3-05', 3, 5, 'medium', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 12. ACE üçbucağının sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><polygon points="247.8,110.0 116.1,34.0 116.1,186.0"/></svg>', '{"A": "216√3", "B": "36√3", "C": "72√3", "D": "54√3", "E": "108√3"}'::jsonb, 'E', NULL, 'ACE bərabərtərəflidir, tərəfi AC = 12√3. S = (√3/4)·3·144 = 108√3. (Altıbucaqlının sahəsinin yarısı.)');
INSERT INTO public.questions VALUES (4536, 60, 'g10-geo-poly-q3-06', 3, 6, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində BK : KC = 5 : 1 nisbətində bölür. Düzbucaqlının perimetri 22 olarsa, sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="68.8,186.0 68.8,34.0 251.2,34.0 251.2,186.0"/><text x="58.8" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="58.8" y="30.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="261.2" y="30.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="261.2" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="68.8" y1="186.0" x2="220.8" y2="34.0" stroke-dasharray="5 4"/><text x="230.0" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "15", "B": "25", "C": "36", "D": "30", "E": "35"}'::jsonb, 'D', NULL, '∠BAK = 45° ⇒ AB = BK = 5t, BC = 6t. Perimetr 2(11t) = 22 ⇒ t = 1. S = 5·6 = 30.');
INSERT INTO public.questions VALUES (4537, 60, 'g10-geo-poly-q3-07', 3, 7, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 24 və 12, yan tərəfi 9 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,145.2 286.0,145.2 223.0,74.8 97.0,74.8"/><text x="21.5" y="153.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="153.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="234.3" y="73.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="85.7" y="73.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="162.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="160.0" y="67.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="266.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="53.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><line x1="34.0" y1="145.2" x2="223.0" y2="74.8" stroke-dasharray="5 4"/></svg>', '{"A": "9", "B": "√370", "C": "3√69", "D": "3√41", "E": "15"}'::jsonb, 'D', NULL, 'Hündürlük: h² = 9² − ((24 − 12)/2)² = 45. Diaqonalın proyeksiyası (24 + 12)/2 = 18. d = √(45 + 324) = 3√41.');
INSERT INTO public.questions VALUES (4538, 60, 'g10-geo-poly-q3-08', 3, 8, 'medium', 'single', 'Düzgün altıbucaqlının tərəfi 11 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "363√3/4", "B": "726", "C": "363√3/2", "D": "363√3", "E": "121√3/4"}'::jsonb, 'C', NULL, '6 bərabərtərəfli üçbucaq: S = 6·11²√3/4 = 363√3/2.');
INSERT INTO public.questions VALUES (4539, 60, 'g10-geo-poly-q3-09', 3, 9, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 16, KC = 4 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="65.0,186.0 65.0,34.0 255.0,34.0 255.0,186.0"/><text x="54.8" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="54.8" y="30.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="265.2" y="30.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="265.2" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="65.0" y1="186.0" x2="217.0" y2="34.0" stroke-dasharray="5 4"/><text x="226.2" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "104", "B": "64", "C": "72", "D": "40", "E": "48"}'::jsonb, 'C', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 16. BC = 20. P = 2(16 + 20) = 72.');
INSERT INTO public.questions VALUES (4540, 60, 'g10-geo-poly-q3-10', 3, 10, 'medium', 'single', 'Paraleloqramın tərəfləri 9 və 5, aralarındakı bucaq 60° olarsa, onun böyük diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,157.4 231.2,157.4 286.0,62.6 88.8,62.6"/><text x="21.8" y="167.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="242.0" y="169.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.2" y="63.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="78.0" y="60.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="126.6" y="172.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="49.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M52.0,157.4 A18,18 0 0 0 43.0,141.9" stroke-width="1.2"/><text x="60.8" y="146.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="157.4" x2="286.0" y2="62.6" stroke-dasharray="5 4"/><line x1="231.2" y1="157.4" x2="88.8" y2="62.6" stroke-dasharray="5 4"/></svg>', '{"A": "√61", "B": "√106", "C": "2√53", "D": "14", "E": "√151"}'::jsonb, 'E', NULL, 'Kosinuslar teoremi: d² = 9² + 5² ∓ 2·9·5·cos 60°. Böyük diaqonal √151, kiçik diaqonal √61. Cavab: √151.');
INSERT INTO public.questions VALUES (4541, 60, 'g10-geo-poly-q3-11', 3, 11, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 8 və 2, yan tərəfi 12 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="107.7,186.0 212.3,186.0 173.1,34.0 146.9,34.0"/><text x="100.3" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="219.7" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="175.3" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="144.7" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="204.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="115.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "60", "B": "10√34", "C": "15√15/2", "D": "15√15", "E": "30√15"}'::jsonb, 'D', NULL, 'h = √(12² − 3²) = 3√15. S = (8 + 2)/2 · h = 15√15.');
INSERT INTO public.questions VALUES (4542, 60, 'g10-geo-poly-q3-12', 3, 12, 'medium', 'single', 'Paraleloqramın tərəfləri 8 və 6, aralarındakı bucaq 60° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,169.5 217.3,169.5 286.0,50.5 102.7,50.5"/><text x="22.2" y="180.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="226.3" y="183.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.8" y="49.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="93.7" y="46.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="119.6" y="184.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="56.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M52.0,169.5 A18,18 0 0 0 43.0,153.9" stroke-width="1.2"/><text x="60.8" y="159.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="169.5" x2="286.0" y2="50.5" stroke-dasharray="5 4"/><line x1="217.3" y1="169.5" x2="102.7" y2="50.5" stroke-dasharray="5 4"/></svg>', '{"A": "14", "B": "2√13", "C": "10√2", "D": "2√37", "E": "10"}'::jsonb, 'B', NULL, 'Kosinuslar teoremi: d² = 8² + 6² ∓ 2·8·6·cos 60°. Böyük diaqonal √148, kiçik diaqonal √52. Cavab: 2√13.');
INSERT INTO public.questions VALUES (4543, 60, 'g10-geo-poly-q3-13', 3, 13, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 20 və 10, yan tərəfi 16 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="60.0,186.0 260.0,186.0 210.0,34.0 110.0,34.0"/><text x="49.6" y="198.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="270.4" y="198.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="217.1" y="28.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="102.9" y="28.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="247.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="73.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><line x1="60.0" y1="186.0" x2="210.0" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√457", "B": "√631", "C": "2√114", "D": "2√89", "E": "16"}'::jsonb, 'C', NULL, 'Hündürlük: h² = 16² − ((20 − 10)/2)² = 231. Diaqonalın proyeksiyası (20 + 10)/2 = 15. d = √(231 + 225) = 2√114.');
INSERT INTO public.questions VALUES (4544, 60, 'g10-geo-poly-q3-14', 3, 14, 'medium', 'open', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 5220° olarsa, onun neçə diaqonalı var?', NULL, NULL, NULL, NULL, '434', '180°(n − 2) = 5220° ⇒ n = 31. Diaqonallar: n(n − 3)/2 = 434.');
INSERT INTO public.questions VALUES (4545, 60, 'g10-geo-poly-q3-15', 3, 15, 'medium', 'single', 'ABCD düzbucaqlısında A bucağının tənböləni BC tərəfini K nöqtəsində kəsir. BK = 20, KC = 15 olarsa, düzbucaqlının perimetrini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,182.0 34.0,38.0 286.0,38.0 286.0,182.0"/><text x="22.7" y="193.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="22.7" y="36.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.3" y="36.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="297.3" y="193.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="34.0" y1="182.0" x2="178.0" y2="38.0" stroke-dasharray="5 4"/><text x="187.2" y="33.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "70", "B": "100", "C": "80", "D": "110", "E": "150"}'::jsonb, 'D', NULL, '∠BAK = ∠AKB = 45°, ABK bərabəryanlıdır: AB = BK = 20. BC = 35. P = 2(20 + 35) = 110.');
INSERT INTO public.questions VALUES (4546, 60, 'g10-geo-poly-q3-16', 3, 16, 'medium', 'single', 'Rombun diaqonalları 80 və 84 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 232.4,110.0 160.0,186.0 87.6,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="74.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="232.4" y1="110.0" x2="87.6" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "840/29", "B": "3360/29", "C": "82", "D": "1680/29", "E": "1709/29"}'::jsonb, 'D', NULL, 'Tərəf: √(40² + 42²) = 58. S = d₁d₂/2 = 3360. h = S/a = 3360/58 = 1680/29.');
INSERT INTO public.questions VALUES (4547, 60, 'g10-geo-poly-q3-17', 3, 17, 'medium', 'single', 'Rombun diaqonalları 120 və 126 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 232.4,110.0 160.0,186.0 87.6,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="74.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="232.4" y1="110.0" x2="87.6" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="52.4"/></svg>', '{"A": "1289/29", "B": "1260/29", "C": "2520/29", "D": "87/2", "E": "630/29"}'::jsonb, 'B', NULL, 'Tərəf 87. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 7560/174 = 1260/29.');
INSERT INTO public.questions VALUES (4548, 60, 'g10-geo-poly-q3-18', 3, 18, 'medium', 'single', 'Qabarıq çoxbucaqlının daxili bucaqlarının cəmi 4320° olarsa, onun neçə diaqonalı var?', NULL, NULL, '{"A": "324", "B": "23", "C": "299", "D": "598", "E": "312"}'::jsonb, 'C', NULL, '180°(n − 2) = 4320° ⇒ n = 26. Diaqonallar: n(n − 3)/2 = 299.');
INSERT INTO public.questions VALUES (4549, 60, 'g10-geo-poly-q3-19', 3, 19, 'medium', 'single', 'Düzgün altıbucaqlının tərəfi 13 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "507√3/4", "B": "507√3/2", "C": "169√3/4", "D": "507√3", "E": "1014"}'::jsonb, 'B', NULL, '6 bərabərtərəfli üçbucaq: S = 6·13²√3/4 = 507√3/2.');
INSERT INTO public.questions VALUES (4550, 60, 'g10-geo-poly-q3-20', 3, 20, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 11 və 9, yan tərəfi 7 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="39.3,186.0 280.7,186.0 258.7,34.0 61.3,34.0"/><text x="28.3" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="291.7" y="197.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="269.0" y="31.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="51.0" y="31.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="281.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="38.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "20√3", "B": "80√3", "C": "40√3", "D": "41√3", "E": "70"}'::jsonb, 'C', NULL, 'h = √(7² − 1²) = 4√3. S = (11 + 9)/2 · h = 40√3.');
INSERT INTO public.questions VALUES (4551, 61, 'g10-geo-circle-q1-01', 1, 1, 'hard', 'single', 'Bərabəryanlı trapesiyaya radiusu 15/2 olan çevrə daxil çəkilib. Kiçik oturacaq 9 olarsa, trapesiyanın yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,185.6 286.0,185.6 205.4,34.4 114.6,34.4"/><text x="22.9" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.1" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="212.0" y="28.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="108.0" y="28.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="160.0" y="27.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><circle cx="160.0" cy="110.0" r="75.6"/></svg>', '{"A": "17", "B": "8", "C": "25", "D": "15", "E": "18"}'::jsonb, 'A', NULL, 'h = 2r = 15. h² = ab ⇒ a = 225/9 = 25. c = (a + b)/2 = 17.');
INSERT INTO public.questions VALUES (4552, 61, 'g10-geo-circle-q1-02', 1, 2, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 4√7 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "56π", "B": "112π", "C": "14π", "D": "29π", "E": "28π"}'::jsonb, 'E', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 28. Halqanın sahəsi π(R² − r²) = 28π.');
INSERT INTO public.questions VALUES (4553, 61, 'g10-geo-circle-q1-03', 1, 3, 'hard', 'single', 'Radiusu 26 olan çevrədə uzunluqları 20 və 48 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="130.8" y1="39.8" x2="189.2" y2="39.8"/><line x1="89.8" y1="139.2" x2="230.2" y2="139.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "14", "B": "35", "C": "33", "D": "36", "E": "34"}'::jsonb, 'E', NULL, 'Mərkəzdən məsafələr: √(26² − 10²) = 24 və √(26² − 24²) = 10. Cəm: 34.');
INSERT INTO public.questions VALUES (4554, 61, 'g10-geo-circle-q1-04', 1, 4, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 6 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "9π", "B": "36π", "C": "10π", "D": "9π/2", "E": "18π"}'::jsonb, 'A', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 9. Halqanın sahəsi π(R² − r²) = 9π.');
INSERT INTO public.questions VALUES (4555, 61, 'g10-geo-circle-q1-05', 1, 5, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 1 : 5 : 4 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 221.5,65.3 98.5,154.7"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="232.0" y="62.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="88.0" y="167.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "18°", "B": "180°", "C": "100°", "D": "72°", "E": "90°"}'::jsonb, 'E', NULL, 'Qövslər: 36°, 180°, 144°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 180°/2 = 90°.');
INSERT INTO public.questions VALUES (4556, 61, 'g10-geo-circle-q1-06', 1, 6, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 9 : 4 : 2 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 98.5,154.7 210.9,166.5"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="88.0" y="167.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="219.6" y="181.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "24°", "B": "118°", "C": "216°", "D": "108°", "E": "48°"}'::jsonb, 'D', NULL, 'Qövslər: 216°, 96°, 48°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 216°/2 = 108°.');
INSERT INTO public.questions VALUES (4557, 61, 'g10-geo-circle-q1-07', 1, 7, 'hard', 'open', 'Radiusu 17 olan çevrədə uzunluqları 16 və 30 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="124.2" y1="42.9" x2="195.8" y2="42.9"/><line x1="92.9" y1="145.8" x2="227.1" y2="145.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', NULL, NULL, '23', 'Mərkəzdən məsafələr: √(17² − 8²) = 15 və √(17² − 15²) = 8. Cəm: 23.');
INSERT INTO public.questions VALUES (4558, 61, 'g10-geo-circle-q1-08', 1, 8, 'hard', 'single', 'Radiusu 5 olan çevrədə uzunluqları 8 və 6 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><line x1="114.4" y1="170.8" x2="205.6" y2="170.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "6", "B": "9", "C": "8", "D": "1", "E": "7"}'::jsonb, 'E', NULL, 'Mərkəzdən məsafələr: √(5² − 4²) = 3 və √(5² − 3²) = 4. Cəm: 7.');
INSERT INTO public.questions VALUES (4559, 61, 'g10-geo-circle-q1-09', 1, 9, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 15, EB = 13, CE = 9 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="101.4" y1="61.6" x2="218.6" y2="61.6"/><line x1="134.5" y1="38.4" x2="235.6" y2="117.4"/><circle cx="164.2" cy="61.6" r="2.6" fill="currentColor"/><text x="91.4" y="58.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="228.6" y="58.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="130.1" y="31.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="248.6" y="123.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="164.2" y="53.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "65/3", "B": "252/13", "C": "92/3", "D": "95/3", "E": "28"}'::jsonb, 'C', NULL, 'AE·EB = CE·ED ⇒ ED = 65/3. CD = 9 + 65/3 = 92/3.');
INSERT INTO public.questions VALUES (4560, 61, 'g10-geo-circle-q1-10', 1, 10, 'medium', 'single', 'Düzbucaqlı üçbucağın katetləri 60 və 63 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="107.6,165.0 212.4,165.0 107.6,55.0"/><text x="98.6" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.9" y="176.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="102.0" y="48.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="117.6,165.0 117.6,155.0 107.6,155.0" stroke-width="1.2"/><circle cx="139.0" cy="133.6" r="31.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="165.2" y="180.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">60</text><text x="97.0" y="109.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">63</text></svg>', '{"A": "123/2", "B": "125/2", "C": "105", "D": "123", "E": "62"}'::jsonb, 'A', NULL, 'Hipotenuz 87. r = (a + b − c)/2 = 18, R = c/2 = 87/2. Cəm: 123/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (4561, 61, 'g10-geo-circle-q1-11', 1, 11, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 8, EB = 4, CE = 6 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="84.6" y1="119.2" x2="235.4" y2="119.2"/><line x1="199.5" y1="45.1" x2="172.4" y2="185.0"/><circle cx="185.1" cy="119.2" r="2.6" fill="currentColor"/><text x="71.6" y="125.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.4" y="125.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="206.3" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="174.5" y="202.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="185.1" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "3", "B": "12", "C": "6", "D": "16/3", "E": "19/3"}'::jsonb, 'D', NULL, 'AE·EB = CE·ED ⇒ ED = 8·4/6 = 16/3.');
INSERT INTO public.questions VALUES (4562, 61, 'g10-geo-circle-q1-12', 1, 12, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 8 : 4 : 3 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 85.7,125.8 183.5,182.3"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="72.9" y="133.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.5" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "106°", "B": "48°", "C": "192°", "D": "96°", "E": "36°"}'::jsonb, 'D', NULL, 'Qövslər: 192°, 96°, 72°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 192°/2 = 96°.');
INSERT INTO public.questions VALUES (4563, 61, 'g10-geo-circle-q1-13', 1, 13, 'medium', 'single', 'Düzbucaqlı üçbucağın katetləri 14 və 48 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="138.7,183.0 181.3,183.0 138.7,37.0"/><text x="135.1" y="200.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="187.8" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="136.8" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="148.7,183.0 148.7,173.0 138.7,173.0" stroke-width="1.2"/><circle cx="157.0" cy="164.7" r="18.2"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.7" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="132.7" y="104.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">48</text></svg>', '{"A": "32", "B": "62", "C": "30", "D": "31", "E": "56"}'::jsonb, 'D', NULL, 'Hipotenuz 50. r = (a + b − c)/2 = 6, R = c/2 = 25. Cəm: 31 (= (a + b)/2).');
INSERT INTO public.questions VALUES (4564, 61, 'g10-geo-circle-q1-14', 1, 14, 'hard', 'open', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 27 və 3 olarsa, çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.0 286.0,152.0 174.0,68.0 146.0,68.0"/><text x="21.7" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.1" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="141.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="169.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">27</text><text x="160.0" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><circle cx="160.0" cy="110.0" r="42.0"/></svg>', NULL, NULL, '9/2', 'Toxunanlar xassəsi: 2c = 27 + 3 ⇒ c = 15. h = √(c² − ((27 − 3)/2)²) = √81 = 9, r = h/2 = 9/2.');
INSERT INTO public.questions VALUES (4565, 61, 'g10-geo-circle-q1-15', 1, 15, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 25 və 9 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,185.6 286.0,185.6 205.4,34.4 114.6,34.4"/><text x="22.9" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.1" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="212.0" y="28.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="108.0" y="28.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="160.0" y="27.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><circle cx="160.0" cy="110.0" r="75.6"/></svg>', '{"A": "289", "B": "255", "C": "270", "D": "225", "E": "255/2"}'::jsonb, 'B', NULL, 'c = (25 + 9)/2 = 17, h = √(ab) = 15. S = (25 + 9)/2·15 = 255.');
INSERT INTO public.questions VALUES (4566, 61, 'g10-geo-circle-q1-16', 1, 16, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 15, EB = 5, CE = 9 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="84.6" y1="100.4" x2="235.4" y2="100.4"/><line x1="176.7" y1="35.9" x2="217.1" y2="160.1"/><circle cx="197.7" cy="100.4" r="2.6" fill="currentColor"/><text x="71.7" y="103.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.3" y="103.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="179.6" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="226.9" y="173.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="197.7" y="92.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "25/3", "B": "36", "C": "55/3", "D": "20", "E": "52/3"}'::jsonb, 'E', NULL, 'AE·EB = CE·ED ⇒ ED = 25/3. CD = 9 + 25/3 = 52/3.');
INSERT INTO public.questions VALUES (4567, 61, 'g10-geo-circle-q1-17', 1, 17, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 12, EB = 5, CE = 3 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="104.5" y1="58.0" x2="215.5" y2="58.0"/><line x1="194.3" y1="42.2" x2="106.1" y2="163.6"/><circle cx="182.8" cy="58.0" r="2.6" fill="currentColor"/><text x="95.1" y="54.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="224.9" y="54.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="200.2" y="35.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="96.9" y="177.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="182.8" y="50.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "20", "B": "51/5", "C": "23", "D": "24", "E": "17"}'::jsonb, 'C', NULL, 'AE·EB = CE·ED ⇒ ED = 20. CD = 3 + 20 = 23.');
INSERT INTO public.questions VALUES (4568, 61, 'g10-geo-circle-q1-18', 1, 18, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 8 və 15 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="124.2,177.1 195.8,177.1 124.2,42.9"/><text x="118.1" y="193.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="205.2" y="191.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="120.9" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="134.2,177.1 134.2,167.1 124.2,167.1" stroke-width="1.2"/><circle cx="151.1" cy="150.2" r="26.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="163.1" y="193.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="115.5" y="106.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "√493/2", "B": "√85/2", "C": "11/2", "D": "√253/2", "E": "√187/2"}'::jsonb, 'B', NULL, 'r = 3, R = 17/2. Eyler düsturu: d² = R² − 2Rr = 289/4 − 51 = 85/4 ⇒ d = √85/2.');
INSERT INTO public.questions VALUES (4569, 61, 'g10-geo-circle-q1-19', 1, 19, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 8√6 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "192π", "B": "48π", "C": "96π", "D": "384π", "E": "97π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 96. Halqanın sahəsi π(R² − r²) = 96π.');
INSERT INTO public.questions VALUES (4570, 61, 'g10-geo-circle-q1-20', 1, 20, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 10√7 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "350π", "B": "176π", "C": "175π/2", "D": "700π", "E": "175π"}'::jsonb, 'E', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 175. Halqanın sahəsi π(R² − r²) = 175π.');
INSERT INTO public.questions VALUES (4571, 61, 'g10-geo-circle-q2-01', 2, 1, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 14, EB = 4, CE = 4 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="86.4" y1="90.9" x2="233.6" y2="90.9"/><line x1="221.9" y1="65.9" x2="127.3" y2="178.6"/><circle cx="200.9" cy="90.9" r="2.6" fill="currentColor"/><text x="73.8" y="92.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="246.2" y="92.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="232.5" y="63.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="121.7" y="195.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="200.9" y="82.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "15", "B": "14", "C": "8/7", "D": "13", "E": "56/5"}'::jsonb, 'B', NULL, 'AE·EB = CE·ED ⇒ ED = 14·4/4 = 14.');
INSERT INTO public.questions VALUES (4572, 61, 'g10-geo-circle-q2-02', 2, 2, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 8 : 7 : 3 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 88.6,84.0 198.0,175.8"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="76.4" y="84.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="204.5" y="192.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "90°", "B": "30°", "C": "160°", "D": "70°", "E": "80°"}'::jsonb, 'E', NULL, 'Qövslər: 160°, 140°, 60°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 160°/2 = 80°.');
INSERT INTO public.questions VALUES (4573, 61, 'g10-geo-circle-q2-03', 2, 3, 'hard', 'single', 'Radiusu 13 olan çevrədə 60°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "169π/6 − 169√3/4", "B": "169π/6", "C": "169π/6 − 169√3/2", "D": "169π/3 − 169√3/4", "E": "169π/6 + 169√3/4"}'::jsonb, 'A', NULL, 'Seqment = sektor − üçbucaq: πR²·60/360 − ½R²·sin 60° = 169π/6 − 169√3/4.');
INSERT INTO public.questions VALUES (4574, 61, 'g10-geo-circle-q2-04', 2, 4, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 3 : 5 : 4 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 160.0,34.0 122.0,175.8"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="115.5" y="192.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "45°", "B": "85°", "C": "75°", "D": "60°", "E": "150°"}'::jsonb, 'C', NULL, 'Qövslər: 90°, 150°, 120°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 150°/2 = 75°.');
INSERT INTO public.questions VALUES (4575, 61, 'g10-geo-circle-q2-05', 2, 5, 'hard', 'single', 'Radiusu 13 olan çevrədə uzunluqları 24 və 10 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="89.8" y1="80.8" x2="230.2" y2="80.8"/><line x1="130.8" y1="39.8" x2="189.2" y2="39.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "8", "B": "6", "C": "7", "D": "9", "E": "17"}'::jsonb, 'C', NULL, 'Mərkəzdən məsafələr: √(13² − 12²) = 5 və √(13² − 5²) = 12. Fərq: 7.');
INSERT INTO public.questions VALUES (4576, 61, 'g10-geo-circle-q2-06', 2, 6, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 6√5 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "45π/2", "B": "46π", "C": "45π", "D": "180π", "E": "90π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 45. Halqanın sahəsi π(R² − r²) = 45π.');
INSERT INTO public.questions VALUES (4577, 61, 'g10-geo-circle-q2-07', 2, 7, 'medium', 'open', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 5, EB = 6, CE = 15 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="110.8" y1="168.0" x2="209.2" y2="168.0"/><line x1="162.5" y1="34.0" x2="154.6" y2="185.8"/><circle cx="155.5" cy="168.0" r="2.6" fill="currentColor"/><text x="102.4" y="182.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="217.6" y="182.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="163.0" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="153.7" y="203.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="155.5" y="160.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', NULL, NULL, '17', 'AE·EB = CE·ED ⇒ ED = 2. CD = 15 + 2 = 17.');
INSERT INTO public.questions VALUES (4578, 61, 'g10-geo-circle-q2-08', 2, 8, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 16 və 4 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "100", "B": "80", "C": "88", "D": "40", "E": "64"}'::jsonb, 'B', NULL, 'c = (16 + 4)/2 = 10, h = √(ab) = 8. S = (16 + 4)/2·8 = 80.');
INSERT INTO public.questions VALUES (4579, 61, 'g10-geo-circle-q2-09', 2, 9, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 4 : 7 : 9 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 183.5,37.7 87.7,133.5"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="187.5" y="30.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="75.4" y="142.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "162°", "B": "81°", "C": "36°", "D": "63°", "E": "91°"}'::jsonb, 'B', NULL, 'Qövslər: 72°, 126°, 162°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 162°/2 = 81°.');
INSERT INTO public.questions VALUES (4580, 61, 'g10-geo-circle-q2-10', 2, 10, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 9 və 40 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="143.3,184.1 176.7,184.1 143.3,35.9"/><text x="140.5" y="201.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="182.0" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="141.9" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="153.3,184.1 153.3,174.1 143.3,174.1" stroke-width="1.2"/><circle cx="158.1" cy="169.3" r="14.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.3" y="201.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="138.4" y="104.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">40</text></svg>', '{"A": "7√33/2", "B": "33/2", "C": "√1353/2", "D": "5√41/2", "E": "√2337/2"}'::jsonb, 'D', NULL, 'r = 4, R = 41/2. Eyler düsturu: d² = R² − 2Rr = 1681/4 − 164 = 1025/4 ⇒ d = 5√41/2.');
INSERT INTO public.questions VALUES (4581, 61, 'g10-geo-circle-q2-11', 2, 11, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 40 və 42 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="107.6,165.0 212.4,165.0 107.6,55.0"/><text x="98.6" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.9" y="176.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="102.0" y="48.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="117.6,165.0 117.6,155.0 107.6,155.0" stroke-width="1.2"/><circle cx="139.0" cy="133.6" r="31.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="165.2" y="180.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">40</text><text x="97.0" y="109.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">42</text></svg>', '{"A": "√145", "B": "17", "C": "√493", "D": "√1537", "E": "√697"}'::jsonb, 'A', NULL, 'r = 12, R = 29. Eyler düsturu: d² = R² − 2Rr = 841 − 696 = 145 ⇒ d = √145.');
INSERT INTO public.questions VALUES (4582, 61, 'g10-geo-circle-q2-12', 2, 12, 'hard', 'single', 'Radiusu 14 olan çevrədə 90°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "49π − 98", "B": "49π", "C": "49π − 196", "D": "49π + 98", "E": "98π − 98"}'::jsonb, 'A', NULL, 'Seqment = sektor − üçbucaq: πR²·90/360 − ½R²·sin 90° = 49π − 98.');
INSERT INTO public.questions VALUES (4583, 61, 'g10-geo-circle-q2-13', 2, 13, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 18 və 8 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 274.0,186.0 210.7,34.0 109.3,34.0"/><text x="35.2" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="284.8" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="217.9" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="102.1" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "78", "B": "156", "C": "144", "D": "168", "E": "169"}'::jsonb, 'B', NULL, 'c = (18 + 8)/2 = 13, h = √(ab) = 12. S = (18 + 8)/2·12 = 156.');
INSERT INTO public.questions VALUES (4584, 61, 'g10-geo-circle-q2-14', 2, 14, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 9 və 12 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.4,170.8 205.6,170.8 114.4,49.2"/><text x="106.6" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="216.4" y="183.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="109.8" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="124.4,170.8 124.4,160.8 114.4,160.8" stroke-width="1.2"/><circle cx="144.8" cy="140.4" r="30.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="164.2" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="104.4" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "3√21/2", "B": "3√15/2", "C": "9√5/2", "D": "3√5/2", "E": "9/2"}'::jsonb, 'D', NULL, 'r = 3, R = 15/2. Eyler düsturu: d² = R² − 2Rr = 225/4 − 45 = 45/4 ⇒ d = 3√5/2.');
INSERT INTO public.questions VALUES (4585, 61, 'g10-geo-circle-q2-15', 2, 15, 'hard', 'single', 'Radiusu 17 olan çevrədə uzunluqları 30 və 16 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="92.9" y1="74.2" x2="227.1" y2="74.2"/><line x1="124.2" y1="42.9" x2="195.8" y2="42.9"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "7", "B": "9", "C": "23", "D": "8", "E": "6"}'::jsonb, 'A', NULL, 'Mərkəzdən məsafələr: √(17² − 15²) = 8 və √(17² − 8²) = 15. Fərq: 7.');
INSERT INTO public.questions VALUES (4586, 61, 'g10-geo-circle-q2-16', 2, 16, 'hard', 'single', 'Bərabəryanlı trapesiyaya radiusu 9/2 olan çevrə daxil çəkilib. Kiçik oturacaq 3 olarsa, trapesiyanın yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.0 286.0,152.0 174.0,68.0 146.0,68.0"/><text x="21.7" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.1" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="141.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="169.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">27</text><text x="160.0" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><circle cx="160.0" cy="110.0" r="42.0"/></svg>', '{"A": "9", "B": "16", "C": "27", "D": "12", "E": "15"}'::jsonb, 'E', NULL, 'h = 2r = 9. h² = ab ⇒ a = 81/3 = 27. c = (a + b)/2 = 15.');
INSERT INTO public.questions VALUES (4587, 61, 'g10-geo-circle-q2-17', 2, 17, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 14, EB = 12, CE = 7 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="96.3" y1="68.5" x2="223.7" y2="68.5"/><line x1="172.0" y1="35.0" x2="140.5" y2="183.4"/><circle cx="164.9" cy="68.5" r="2.6" fill="currentColor"/><text x="85.5" y="66.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="234.5" y="66.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="174.1" y="27.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="137.1" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="164.9" y="60.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "24", "B": "91/6", "C": "32", "D": "31", "E": "26"}'::jsonb, 'D', NULL, 'AE·EB = CE·ED ⇒ ED = 24. CD = 7 + 24 = 31.');
INSERT INTO public.questions VALUES (4588, 61, 'g10-geo-circle-q2-18', 2, 18, 'hard', 'single', 'Radiusu 5 olan çevrədə uzunluqları 6 və 8 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "1", "B": "2", "C": "3", "D": "7", "E": "0"}'::jsonb, 'A', NULL, 'Mərkəzdən məsafələr: √(5² − 3²) = 4 və √(5² − 4²) = 3. Fərq: 1.');
INSERT INTO public.questions VALUES (4589, 61, 'g10-geo-circle-q2-19', 2, 19, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 13, EB = 8, CE = 3 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="121.6" y1="44.4" x2="198.4" y2="44.4"/><line x1="165.2" y1="34.2" x2="214.6" y2="162.9"/><circle cx="169.1" cy="44.4" r="2.6" fill="currentColor"/><text x="115.0" y="38.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="205.0" y="38.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="166.1" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.9" y="176.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="169.1" y="36.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "39/8", "B": "104/3", "C": "24/13", "D": "18", "E": "107/3"}'::jsonb, 'B', NULL, 'AE·EB = CE·ED ⇒ ED = 13·8/3 = 104/3.');
INSERT INTO public.questions VALUES (4590, 61, 'g10-geo-circle-q2-20', 2, 20, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 4√11 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "22π", "B": "88π", "C": "44π", "D": "45π", "E": "176π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 44. Halqanın sahəsi π(R² − r²) = 44π.');
INSERT INTO public.questions VALUES (4591, 61, 'g10-geo-circle-q3-01', 3, 1, 'hard', 'single', 'Radiusu 15 olan çevrədə uzunluqları 18 və 24 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "5", "B": "3", "C": "2", "D": "21", "E": "4"}'::jsonb, 'B', NULL, 'Mərkəzdən məsafələr: √(15² − 9²) = 12 və √(15² − 12²) = 9. Fərq: 3.');
INSERT INTO public.questions VALUES (4592, 61, 'g10-geo-circle-q3-02', 3, 2, 'hard', 'single', 'Bərabəryanlı trapesiyaya radiusu 2 olan çevrə daxil çəkilib. Kiçik oturacaq 2 olarsa, trapesiyanın yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "3", "B": "4", "C": "8", "D": "6", "E": "5"}'::jsonb, 'E', NULL, 'h = 2r = 4. h² = ab ⇒ a = 16/2 = 8. c = (a + b)/2 = 5.');
INSERT INTO public.questions VALUES (4593, 61, 'g10-geo-circle-q3-03', 3, 3, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 4 : 8 : 3 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 152.1,34.4 183.5,182.3"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="150.7" y="26.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.5" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "192°", "B": "36°", "C": "106°", "D": "96°", "E": "48°"}'::jsonb, 'D', NULL, 'Qövslər: 96°, 192°, 72°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 192°/2 = 96°.');
INSERT INTO public.questions VALUES (4594, 61, 'g10-geo-circle-q3-04', 3, 4, 'hard', 'single', 'Radiusu 13 olan çevrədə 120°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "169π/3 + 169√3/4", "B": "169π/3 − 169√3/2", "C": "169π/3", "D": "338π/3 − 169√3/4", "E": "169π/3 − 169√3/4"}'::jsonb, 'E', NULL, 'Seqment = sektor − üçbucaq: πR²·120/360 − ½R²·sin 120° = 169π/3 − 169√3/4.');
INSERT INTO public.questions VALUES (4595, 61, 'g10-geo-circle-q3-05', 3, 5, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 7 : 3 : 5 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 85.7,94.2 122.0,175.8"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="72.9" y="96.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="115.5" y="192.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "94°", "B": "60°", "C": "36°", "D": "168°", "E": "84°"}'::jsonb, 'E', NULL, 'Qövslər: 168°, 72°, 120°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 168°/2 = 84°.');
INSERT INTO public.questions VALUES (4596, 61, 'g10-geo-circle-q3-06', 3, 6, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 6 və 8 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.4,170.8 205.6,170.8 114.4,49.2"/><text x="106.6" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="216.4" y="183.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="109.8" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="124.4,170.8 124.4,160.8 114.4,160.8" stroke-width="1.2"/><circle cx="144.8" cy="140.4" r="30.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="164.2" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="104.4" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "√15", "B": "3√5", "C": "√21", "D": "3", "E": "√5"}'::jsonb, 'E', NULL, 'r = 2, R = 5. Eyler düsturu: d² = R² − 2Rr = 25 − 20 = 5 ⇒ d = √5.');
INSERT INTO public.questions VALUES (4597, 61, 'g10-geo-circle-q3-07', 3, 7, 'medium', 'open', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 2, EB = 15, CE = 4 olarsa, CD vətərini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="84.1" y1="114.5" x2="235.9" y2="114.5"/><line x1="89.8" y1="80.9" x2="124.9" y2="177.4"/><circle cx="102.0" cy="114.5" r="2.6" fill="currentColor"/><text x="71.2" y="120.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.8" y="120.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="77.8" y="81.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="118.9" y="193.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="102.0" y="106.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', NULL, NULL, '23/2', 'AE·EB = CE·ED ⇒ ED = 15/2. CD = 4 + 15/2 = 23/2.');
INSERT INTO public.questions VALUES (4598, 61, 'g10-geo-circle-q3-08', 3, 8, 'medium', 'single', 'Çevrəyə daxil çəkilmiş ABC üçbucağının təpələri çevrəni uzunluqları 2 : 6 : 4 nisbətində olan qövslərə bölür. Üçbucağın ən böyük bucağını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><polygon points="236.0,110.0 198.0,44.2 122.0,175.8"/><text x="249.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="204.5" y="37.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="115.5" y="192.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text></svg>', '{"A": "100°", "B": "60°", "C": "30°", "D": "180°", "E": "90°"}'::jsonb, 'E', NULL, 'Qövslər: 60°, 180°, 120°. Daxili bucaq söykəndiyi qövsün yarısına bərabərdir: 180°/2 = 90°.');
INSERT INTO public.questions VALUES (4599, 61, 'g10-geo-circle-q3-09', 3, 9, 'hard', 'single', 'Bərabəryanlı trapesiyaya radiusu 6 olan çevrə daxil çəkilib. Kiçik oturacaq 8 olarsa, trapesiyanın yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 274.0,186.0 210.7,34.0 109.3,34.0"/><text x="35.2" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="284.8" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="217.9" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="102.1" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "5", "B": "18", "C": "14", "D": "12", "E": "13"}'::jsonb, 'E', NULL, 'h = 2r = 12. h² = ab ⇒ a = 144/8 = 18. c = (a + b)/2 = 13.');
INSERT INTO public.questions VALUES (4600, 61, 'g10-geo-circle-q3-10', 3, 10, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 18 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "324π", "B": "81π", "C": "162π", "D": "81π/2", "E": "82π"}'::jsonb, 'B', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 81. Halqanın sahəsi π(R² − r²) = 81π.');
INSERT INTO public.questions VALUES (4601, 61, 'g10-geo-circle-q3-11', 3, 11, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 8 və 2 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "24", "B": "25", "C": "16", "D": "10", "E": "20"}'::jsonb, 'E', NULL, 'c = (8 + 2)/2 = 5, h = √(ab) = 4. S = (8 + 2)/2·4 = 20.');
INSERT INTO public.questions VALUES (4602, 61, 'g10-geo-circle-q3-12', 3, 12, 'medium', 'single', 'Düzbucaqlı üçbucağın katetləri 36 və 105 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="135.4,181.9 184.6,181.9 135.4,38.1"/><text x="131.1" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="192.0" y="197.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="133.2" y="30.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="145.4,181.9 145.4,171.9 135.4,171.9" stroke-width="1.2"/><circle cx="155.9" cy="161.4" r="20.5"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="162.0" y="198.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">36</text><text x="128.6" y="105.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">105</text></svg>', '{"A": "126", "B": "71", "C": "141/2", "D": "141", "E": "143/2"}'::jsonb, 'C', NULL, 'Hipotenuz 111. r = (a + b − c)/2 = 15, R = c/2 = 111/2. Cəm: 141/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (4603, 61, 'g10-geo-circle-q3-13', 3, 13, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 15, EB = 14, CE = 10 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="89.6" y1="81.5" x2="230.4" y2="81.5"/><line x1="183.7" y1="37.8" x2="117.7" y2="173.1"/><circle cx="162.4" cy="81.5" r="2.6" fill="currentColor"/><text x="77.5" y="81.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="242.5" y="81.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.8" y="30.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="110.5" y="188.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="162.4" y="73.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "22", "B": "75/7", "C": "28/3", "D": "19", "E": "21"}'::jsonb, 'E', NULL, 'AE·EB = CE·ED ⇒ ED = 15·14/10 = 21.');
INSERT INTO public.questions VALUES (4604, 61, 'g10-geo-circle-q3-14', 3, 14, 'medium', 'open', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 15, EB = 4, CE = 2 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="125.7" y1="42.2" x2="194.3" y2="42.2"/><line x1="176.5" y1="35.8" x2="230.7" y2="137.8"/><circle cx="179.9" cy="42.2" r="2.6" fill="currentColor"/><text x="119.8" y="35.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="200.2" y="35.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="179.3" y="28.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="242.8" y="147.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="179.9" y="34.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', NULL, NULL, '30', 'AE·EB = CE·ED ⇒ ED = 15·4/2 = 30.');
INSERT INTO public.questions VALUES (4605, 61, 'g10-geo-circle-q3-15', 3, 15, 'hard', 'single', 'Radiusu 10 olan çevrədə uzunluqları 12 və 16 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "2", "B": "3", "C": "4", "D": "1", "E": "14"}'::jsonb, 'A', NULL, 'Mərkəzdən məsafələr: √(10² − 6²) = 8 və √(10² − 8²) = 6. Fərq: 2.');
INSERT INTO public.questions VALUES (4606, 61, 'g10-geo-circle-q3-16', 3, 16, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 60 və 63 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="107.6,165.0 212.4,165.0 107.6,55.0"/><text x="98.6" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.9" y="176.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="102.0" y="48.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="117.6,165.0 117.6,155.0 107.6,155.0" stroke-width="1.2"/><circle cx="139.0" cy="133.6" r="31.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="165.2" y="180.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">60</text><text x="97.0" y="109.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">63</text></svg>', '{"A": "51/2", "B": "3√697/2", "C": "3√1537/2", "D": "3√493/2", "E": "3√145/2"}'::jsonb, 'E', NULL, 'r = 18, R = 87/2. Eyler düsturu: d² = R² − 2Rr = 7569/4 − 1566 = 1305/4 ⇒ d = 3√145/2.');
INSERT INTO public.questions VALUES (4607, 61, 'g10-geo-circle-q3-17', 3, 17, 'hard', 'single', 'Radiusu 11 olan çevrədə 120°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "121π/3 + 121√3/4", "B": "121π/3 − 121√3/4", "C": "121π/3", "D": "242π/3 − 121√3/4", "E": "121π/3 − 121√3/2"}'::jsonb, 'B', NULL, 'Seqment = sektor − üçbucaq: πR²·120/360 − ½R²·sin 120° = 121π/3 − 121√3/4.');
INSERT INTO public.questions VALUES (4608, 61, 'g10-geo-circle-q3-18', 3, 18, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 24 və 6 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "180", "B": "90", "C": "144", "D": "192", "E": "225"}'::jsonb, 'A', NULL, 'c = (24 + 6)/2 = 15, h = √(ab) = 12. S = (24 + 6)/2·12 = 180.');
INSERT INTO public.questions VALUES (4609, 61, 'g10-geo-circle-q3-19', 3, 19, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 36 və 105 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="135.4,181.9 184.6,181.9 135.4,38.1"/><text x="131.1" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="192.0" y="197.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="133.2" y="30.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="145.4,181.9 145.4,171.9 135.4,171.9" stroke-width="1.2"/><circle cx="155.9" cy="161.4" r="20.5"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="162.0" y="198.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">36</text><text x="128.6" y="105.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">105</text></svg>', '{"A": "9√141/2", "B": "9√111/2", "C": "3√629/2", "D": "3√2109/2", "E": "81/2"}'::jsonb, 'C', NULL, 'r = 15, R = 111/2. Eyler düsturu: d² = R² − 2Rr = 12321/4 − 1665 = 5661/4 ⇒ d = 3√629/2.');
INSERT INTO public.questions VALUES (4610, 61, 'g10-geo-circle-q3-20', 3, 20, 'medium', 'single', 'Çevrənin AB və CD vətərləri E nöqtəsində kəsişir. AE = 12, EB = 3, CE = 4 olarsa, ED-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="84.1" y1="107.1" x2="235.9" y2="107.1"/><line x1="225.8" y1="72.0" x2="160.0" y2="186.0"/><circle cx="205.6" cy="107.1" r="2.6" fill="currentColor"/><text x="71.1" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.9" y="111.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.1" y="70.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="205.6" y="99.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text></svg>', '{"A": "11", "B": "1", "C": "16", "D": "10", "E": "9"}'::jsonb, 'E', NULL, 'AE·EB = CE·ED ⇒ ED = 12·3/4 = 9.');
INSERT INTO public.questions VALUES (4611, 62, 'g10-geo-trig-q1-01', 1, 1, 'hard', 'single', 'sin α = −5/13 və 3π/2 < α < 2π olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "144/169", "B": "−120/169", "C": "119/169", "D": "−119/169", "E": "288/169"}'::jsonb, 'C', NULL, 'cos α = √(1 − 25/169) = 12/13 (rüb işarəsinə görə). cos 2α = 119/169.');
INSERT INTO public.questions VALUES (4612, 62, 'g10-geo-trig-q1-02', 1, 2, 'medium', 'single', 'sin α = 3/5 və 0 < α < π/2 olarsa, sin(3π/2 − α) · tg(π + α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "0", "B": "3/5", "C": "−3/5", "D": "−3/10", "E": "−6/5"}'::jsonb, 'C', NULL, 'cos α = 4/5. Çevirmə düsturları: sin(3π/2 − α) · tg(π + α) = (−cos α)·tg α = −sin α = −3/5.');
INSERT INTO public.questions VALUES (4613, 62, 'g10-geo-trig-q1-03', 1, 3, 'medium', 'single', 'ABC üçbucağında AB = 14, AC = 6, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="78.5,148.5 286.0,148.5 34.0,71.5"/><text x="66.7" y="159.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="155.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="22.5" y="70.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="192.9" y="159.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="44.4" y="113.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M96.5,148.5 A18,18 0 0 0 69.5,132.9" stroke-width="1.2"/><text x="94.0" y="126.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "20", "B": "9", "C": "2√79", "D": "2√58", "E": "2√37"}'::jsonb, 'C', NULL, 'BC² = 6² + 14² − 2·6·14·cos 120° = 316 ⇒ BC = 2√79.');
INSERT INTO public.questions VALUES (4614, 62, 'g10-geo-trig-q1-04', 1, 4, 'hard', 'single', 'sin α = −8/17 və π < α < 3π/2 olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "161/289", "B": "120/289", "C": "240/289", "D": "−240/289", "E": "−120/289"}'::jsonb, 'C', NULL, 'cos α = −√(1 − 64/289) = −15/17 (rüb işarəsinə görə). sin 2α = 240/289.');
INSERT INTO public.questions VALUES (4615, 62, 'g10-geo-trig-q1-05', 1, 5, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 6, ∠A = 60°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="84.8,99.1 235.2,99.1 113.0,50.3"/><text x="72.2" y="107.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.0" y="106.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="104.0" y="45.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.3" y="112.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="87.1" y="77.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M102.8,99.1 A18,18 0 0 0 93.8,83.6" stroke-width="1.2"/><text x="111.6" y="88.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "7√2", "B": "14√3/3", "C": "28√3/3", "D": "14", "E": "√597/3"}'::jsonb, 'B', NULL, 'BC² = 196 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 60° ⇒ R = √196/√3 = 14√3/3.');
INSERT INTO public.questions VALUES (4616, 62, 'g10-geo-trig-q1-06', 1, 6, 'hard', 'single', 'sin α + cos α = 1/2 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1/8", "B": "5/4", "C": "5/16", "D": "7/8", "E": "11/16"}'::jsonb, 'E', NULL, 'sin α cos α = −3/8; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = 1/2·11/8 = 11/16.');
INSERT INTO public.questions VALUES (4617, 62, 'g10-geo-trig-q1-07', 1, 7, 'medium', 'open', 'ABC üçbucağında BC = 3, ∠A = 60°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="72.2,186.0 247.8,186.0 160.0,34.0"/><text x="61.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="259.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M90.2,186.0 A18,18 0 0 0 81.2,170.4" stroke-width="1.2"/><text x="99.1" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M238.8,170.4 A18,18 0 0 0 229.8,186.0" stroke-width="1.2"/><text x="220.9" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="214.3" y="109.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text></svg>', NULL, NULL, '3', 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 3·sin 60°/sin 60° = 3.');
INSERT INTO public.questions VALUES (4618, 62, 'g10-geo-trig-q1-08', 1, 8, 'medium', 'single', 'ABC üçbucağında AB = 3, AC = 14, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="116.1,186.0 153.7,186.0 203.9,34.0"/><text x="107.8" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="152.7" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="209.2" y="27.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="130.0" y="201.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="161.0" y="103.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><path d="M134.1,186.0 A18,18 0 0 0 125.1,170.4" stroke-width="1.2"/><text x="143.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "12", "B": "9√2", "C": "√247", "D": "√205", "E": "√163"}'::jsonb, 'E', NULL, 'BC² = 14² + 3² − 2·14·3·cos 60° = 163 ⇒ BC = √163.');
INSERT INTO public.questions VALUES (4619, 62, 'g10-geo-trig-q1-09', 1, 9, 'medium', 'single', 'ABC üçbucağında BC = 14, ∠A = 60°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 127.9,34.0"/><text x="28.3" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="125.2" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 49.1,170.4" stroke-width="1.2"/><text x="67.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M267.2,173.3 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="251.2" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="214.8" y="109.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "14√2", "B": "7√6", "C": "14", "D": "14√6", "E": "14√6/3"}'::jsonb, 'E', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 14·sin 45°/sin 60° = 14√6/3.');
INSERT INTO public.questions VALUES (4620, 62, 'g10-geo-trig-q1-10', 1, 10, 'medium', 'single', 'cos α = 7/25 və 3π/2 < α < 2π olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−23/7", "B": "7/24", "C": "−7/24", "D": "24/7", "E": "−24/7"}'::jsonb, 'E', NULL, 'sin α = −√(1 − 49/625) = −24/25 (rüb işarəsinə görə). tg α = −24/7.');
INSERT INTO public.questions VALUES (4621, 62, 'g10-geo-trig-q1-11', 1, 11, 'medium', 'single', 'tg α = −2 olarsa, 2sin²α − 3cos²α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1", "B": "−1", "C": "5", "D": "5/4", "E": "−2"}'::jsonb, 'A', NULL, 'Bölün sin²α + cos²α = 1-ə, sonra cos²α-ya: (2·tg²α + (−3))/(tg²α + 1) = (8 + (−3))/5 = 1.');
INSERT INTO public.questions VALUES (4622, 62, 'g10-geo-trig-q1-12', 1, 12, 'medium', 'single', 'ABC üçbucağında BC = 9, ∠A = 30°, ∠B = 135°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,182.7 140.5,182.7 286.0,37.3"/><text x="22.0" y="192.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="137.1" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.5" y="34.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,182.7 A18,18 0 0 0 49.6,173.7" stroke-width="1.2"/><text x="63.9" y="179.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M153.2,170.0 A18,18 0 0 0 122.5,182.7" stroke-width="1.2"/><text x="128.6" y="159.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text><text x="224.4" y="110.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text></svg>', '{"A": "9√2", "B": "10√2", "C": "8√2", "D": "9", "E": "9√2/2"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 9·sin 135°/sin 30° = 9√2.');
INSERT INTO public.questions VALUES (4623, 62, 'g10-geo-trig-q1-13', 1, 13, 'hard', 'single', 'sin α + cos α = 6/5 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "183/125", "B": "267/250", "C": "117/125", "D": "216/125", "E": "84/125"}'::jsonb, 'C', NULL, 'sin α cos α = 11/50; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = 6/5·39/50 = 117/125.');
INSERT INTO public.questions VALUES (4624, 62, 'g10-geo-trig-q1-14', 1, 14, 'hard', 'single', 'cos α = −12/37 və π < α < 3π/2 olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1081/1369", "B": "288/1369", "C": "1081/1369", "D": "840/1369", "E": "144/1369"}'::jsonb, 'A', NULL, 'sin α = −√(1 − 144/1369) = −35/37 (rüb işarəsinə görə). cos 2α = −1081/1369.');
INSERT INTO public.questions VALUES (4625, 62, 'g10-geo-trig-q1-15', 1, 15, 'medium', 'single', 'sin α = 20/29 və 0 < α < π/2 olarsa, cos(π + α) − sin(π/2 − α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−22/29", "B": "−21/29", "C": "−42/29", "D": "−84/29", "E": "42/29"}'::jsonb, 'C', NULL, 'cos α = 21/29. Çevirmə düsturları: cos(π + α) − sin(π/2 − α) = −cos α − cos α = −42/29.');
INSERT INTO public.questions VALUES (4626, 62, 'g10-geo-trig-q1-16', 1, 16, 'hard', 'single', 'sin α + cos α = −9/7 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1065/343", "B": "−153/343", "C": "−297/343", "D": "−585/343", "E": "−729/343"}'::jsonb, 'C', NULL, 'sin α cos α = 16/49; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = −9/7·33/49 = −297/343.');
INSERT INTO public.questions VALUES (4627, 62, 'g10-geo-trig-q1-17', 1, 17, 'medium', 'single', 'tg α = 3 olarsa, 5sin²α + 3cos²α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "16/3", "B": "−24/5", "C": "24/5", "D": "48", "E": "16/5"}'::jsonb, 'C', NULL, 'Bölün sin²α + cos²α = 1-ə, sonra cos²α-ya: (5·tg²α + 3)/(tg²α + 1) = (45 + 3)/10 = 24/5.');
INSERT INTO public.questions VALUES (4628, 62, 'g10-geo-trig-q1-18', 1, 18, 'medium', 'single', 'tg α = 1 olarsa, 4sin²α + 3cos²α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−7/2", "B": "9/2", "C": "7/2", "D": "7", "E": "4"}'::jsonb, 'C', NULL, 'Bölün sin²α + cos²α = 1-ə, sonra cos²α-ya: (4·tg²α + 3)/(tg²α + 1) = (4 + 3)/2 = 7/2.');
INSERT INTO public.questions VALUES (4629, 62, 'g10-geo-trig-q1-19', 1, 19, 'medium', 'single', 'sin α = 20/29 və 0 < α < π/2 olarsa, sin(3π/2 − α) · tg(π + α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "0", "B": "−20/29", "C": "20/29", "D": "−40/29", "E": "−10/29"}'::jsonb, 'B', NULL, 'cos α = 21/29. Çevirmə düsturları: sin(3π/2 − α) · tg(π + α) = (−cos α)·tg α = −sin α = −20/29.');
INSERT INTO public.questions VALUES (4630, 62, 'g10-geo-trig-q1-20', 1, 20, 'medium', 'single', 'ABC üçbucağında BC = 11, ∠A = 30°, ∠B = 135°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,182.7 140.5,182.7 286.0,37.3"/><text x="22.0" y="192.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="137.1" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.5" y="34.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,182.7 A18,18 0 0 0 49.6,173.7" stroke-width="1.2"/><text x="63.9" y="179.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M153.2,170.0 A18,18 0 0 0 122.5,182.7" stroke-width="1.2"/><text x="128.6" y="159.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text><text x="224.4" y="110.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text></svg>', '{"A": "11√2/2", "B": "11", "C": "12√2", "D": "10√2", "E": "11√2"}'::jsonb, 'E', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 11·sin 135°/sin 30° = 11√2.');
INSERT INTO public.questions VALUES (4631, 62, 'g10-geo-trig-q2-01', 2, 1, 'hard', 'single', 'sin α + cos α = 4/5 olarsa, sin α · cos α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9/50", "B": "−9/25", "C": "2/5", "D": "−9/50", "E": "41/50"}'::jsonb, 'D', NULL, '(sin α + cos α)² = 1 + 2sin α cos α ⇒ sin α cos α = (16/25 − 1)/2 = −9/50.');
INSERT INTO public.questions VALUES (4632, 62, 'g10-geo-trig-q2-02', 2, 2, 'medium', 'single', 'sin α = 5/13 və 0 < α < π/2 olarsa, cos(π/2 + α) · ctg(3π/2 − α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "35/156", "B": "−25/156", "C": "25/156", "D": "−25/312", "E": "−25/78"}'::jsonb, 'B', NULL, 'cos α = 12/13. Çevirmə düsturları: cos(π/2 + α) · ctg(3π/2 − α) = (−sin α)·tg α = −25/156.');
INSERT INTO public.questions VALUES (4633, 62, 'g10-geo-trig-q2-03', 2, 3, 'medium', 'single', 'tg α = −5/4 olarsa, 4sin²α + 3cos²α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−148/41", "B": "37/4", "C": "148/41", "D": "139/41", "E": "148/25"}'::jsonb, 'C', NULL, 'Bölün sin²α + cos²α = 1-ə, sonra cos²α-ya: (4·tg²α + 3)/(tg²α + 1) = (25/4 + 3)/41/16 = 148/41.');
INSERT INTO public.questions VALUES (4634, 62, 'g10-geo-trig-q2-04', 2, 4, 'medium', 'single', 'ABC üçbucağında BC = 14, ∠A = 45°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 192.1,34.0"/><text x="28.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="291.7" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="194.8" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 52.8,173.3" stroke-width="1.2"/><text x="68.8" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M270.9,170.4 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="253.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="247.2" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "7√6", "B": "14√3", "C": "14√6", "D": "14√6/3", "E": "14"}'::jsonb, 'A', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 14·sin 60°/sin 45° = 7√6.');
INSERT INTO public.questions VALUES (4635, 62, 'g10-geo-trig-q2-05', 2, 5, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 5, ∠A = 120°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="104.6,162.0 215.4,162.0 87.3,132.0"/><text x="92.2" y="171.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="228.3" y="168.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="75.2" y="132.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="171.1" y="171.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="84.0" y="150.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M122.6,162.0 A18,18 0 0 0 95.6,146.4" stroke-width="1.2"/><text x="120.1" y="140.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "2√273/3", "B": "38√3/3", "C": "19√2/2", "D": "19", "E": "19√3/3"}'::jsonb, 'E', NULL, 'BC² = 361 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 120° ⇒ R = √361/√3 = 19√3/3.');
INSERT INTO public.questions VALUES (4636, 62, 'g10-geo-trig-q2-06', 2, 6, 'medium', 'single', 'sin α = 7/25 və π/2 < α < π olarsa, tg(π − α) + ctg(π/2 + α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "259/300", "B": "7/24", "C": "7/12", "D": "−7/12", "E": "7/6"}'::jsonb, 'C', NULL, 'cos α = −24/25. Çevirmə düsturları: tg(π − α) + ctg(π/2 + α) = −tg α − tg α = 7/12.');
INSERT INTO public.questions VALUES (4637, 62, 'g10-geo-trig-q2-07', 2, 7, 'medium', 'single', 'ABC üçbucağında BC = 5, ∠A = 45°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 192.1,34.0"/><text x="28.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="291.7" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="194.8" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 52.8,173.3" stroke-width="1.2"/><text x="68.8" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M270.9,170.4 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="253.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="247.2" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text></svg>', '{"A": "5√3", "B": "5√6", "C": "5√6/2", "D": "5√6/3", "E": "5"}'::jsonb, 'C', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 5·sin 60°/sin 45° = 5√6/2.');
INSERT INTO public.questions VALUES (4638, 62, 'g10-geo-trig-q2-08', 2, 8, 'hard', 'single', 'cos α = −12/37 və π < α < 3π/2 olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "840/1369", "B": "−1081/1369", "C": "−840/1369", "D": "420/1369", "E": "−420/1369"}'::jsonb, 'A', NULL, 'sin α = −√(1 − 144/1369) = −35/37 (rüb işarəsinə görə). sin 2α = 840/1369.');
INSERT INTO public.questions VALUES (4639, 62, 'g10-geo-trig-q2-09', 2, 9, 'hard', 'single', 'cos α = 9/41 və 3π/2 < α < 2π olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "720/1681", "B": "−720/1681", "C": "−719/1681", "D": "−360/1681", "E": "−1519/1681"}'::jsonb, 'B', NULL, 'sin α = −√(1 − 81/1681) = −40/41 (rüb işarəsinə görə). sin 2α = −720/1681.');
INSERT INTO public.questions VALUES (4640, 62, 'g10-geo-trig-q2-10', 2, 10, 'medium', 'single', 'tg α = 3 olarsa, (2sin α − cos α) / (5sin α − 3cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "5/18", "B": "7/12", "C": "5/12", "D": "−5/12", "E": "1/4"}'::jsonb, 'C', NULL, 'Surəti və məxrəci cos α-ya bölün: (2·tg α + (−1))/(5·tg α − 3) = (6 + (−1))/(15 − 3) = 5/12.');
INSERT INTO public.questions VALUES (4641, 62, 'g10-geo-trig-q2-11', 2, 11, 'medium', 'single', 'ABC üçbucağında AB = 3, AC = 2, ∠A = 120°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="97.0,164.6 286.0,164.6 34.0,55.4"/><text x="87.2" y="178.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.3" y="53.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="201.4" y="176.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="53.9" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><path d="M115.0,164.6 A18,18 0 0 0 88.0,149.0" stroke-width="1.2"/><text x="112.5" y="142.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text></svg>', '{"A": "√13", "B": "2", "C": "5", "D": "√7", "E": "√19"}'::jsonb, 'E', NULL, 'BC² = 2² + 3² − 2·2·3·cos 120° = 19 ⇒ BC = √19.');
INSERT INTO public.questions VALUES (4642, 62, 'g10-geo-trig-q2-12', 2, 12, 'medium', 'single', 'sin α = 3/5 və π/2 < α < π olarsa, sin(π − α) + cos(3π/2 + α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9/5", "B": "−6/5", "C": "12/5", "D": "3/5", "E": "6/5"}'::jsonb, 'E', NULL, 'cos α = −4/5. Çevirmə düsturları: sin(π − α) + cos(3π/2 + α) = sin α + sin α = 6/5.');
INSERT INTO public.questions VALUES (4643, 62, 'g10-geo-trig-q2-13', 2, 13, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 7, ∠A = 60°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="84.1,107.1 235.9,107.1 119.5,45.7"/><text x="71.7" y="116.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="248.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="112.3" y="39.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="166.6" y="122.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="90.1" y="78.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><path d="M102.1,107.1 A18,18 0 0 0 93.1,91.5" stroke-width="1.2"/><text x="110.9" y="96.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "13√3/3", "B": "13", "C": "26√3/3", "D": "2√129/3", "E": "13√2/2"}'::jsonb, 'A', NULL, 'BC² = 169 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 60° ⇒ R = √169/√3 = 13√3/3.');
INSERT INTO public.questions VALUES (4644, 62, 'g10-geo-trig-q2-14', 2, 14, 'medium', 'open', 'tg α = −4 olarsa, (4sin α + 2cos α) / (sin α + cos α) ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '14/3', 'Surəti və məxrəci cos α-ya bölün: (4·tg α + 2)/(1·tg α − (−1)) = (−16 + 2)/(−4 − (−1)) = 14/3.');
INSERT INTO public.questions VALUES (4645, 62, 'g10-geo-trig-q2-15', 2, 15, 'hard', 'single', 'sin α + cos α = 8/7 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "512/343", "B": "332/343", "C": "272/343", "D": "452/343", "E": "709/686"}'::jsonb, 'B', NULL, 'sin α cos α = 15/98; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = 8/7·83/98 = 332/343.');
INSERT INTO public.questions VALUES (4646, 62, 'g10-geo-trig-q2-16', 2, 16, 'medium', 'single', 'sin α = −7/25 və π < α < 3π/2 olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1/3", "B": "24/7", "C": "−24/7", "D": "7/24", "E": "−7/24"}'::jsonb, 'D', NULL, 'cos α = −√(1 − 49/625) = −24/25 (rüb işarəsinə görə). tg α = 7/24.');
INSERT INTO public.questions VALUES (4647, 62, 'g10-geo-trig-q2-17', 2, 17, 'hard', 'single', 'sin α + cos α = 9/7 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "153/343", "B": "585/343", "C": "297/343", "D": "393/343", "E": "729/343"}'::jsonb, 'C', NULL, 'sin α cos α = 16/49; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = 9/7·33/49 = 297/343.');
INSERT INTO public.questions VALUES (4648, 62, 'g10-geo-trig-q2-18', 2, 18, 'medium', 'single', 'tg α = 2 olarsa, sin²α + 5cos²α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−9/5", "B": "9", "C": "21/5", "D": "9/5", "E": "9/4"}'::jsonb, 'D', NULL, 'Bölün sin²α + cos²α = 1-ə, sonra cos²α-ya: (1·tg²α + 5)/(tg²α + 1) = (4 + 5)/5 = 9/5.');
INSERT INTO public.questions VALUES (4649, 62, 'g10-geo-trig-q2-19', 2, 19, 'medium', 'single', 'sin α = 5/13 və π/2 < α < π olarsa, cos(π + α) − sin(π/2 − α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "48/13", "B": "29/13", "C": "24/13", "D": "12/13", "E": "−24/13"}'::jsonb, 'C', NULL, 'cos α = −12/13. Çevirmə düsturları: cos(π + α) − sin(π/2 − α) = −cos α − cos α = 24/13.');
INSERT INTO public.questions VALUES (4650, 62, 'g10-geo-trig-q2-20', 2, 20, 'medium', 'single', 'ABC üçbucağında BC = 8, ∠A = 45°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.1,186.0 279.9,186.0 192.1,34.0"/><text x="28.0" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="291.7" y="196.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="194.8" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M58.1,186.0 A18,18 0 0 0 52.8,173.3" stroke-width="1.2"/><text x="68.8" y="179.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M270.9,170.4 A18,18 0 0 0 261.9,186.0" stroke-width="1.2"/><text x="253.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="247.2" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "8√6", "B": "8", "C": "4√6", "D": "8√6/3", "E": "8√3"}'::jsonb, 'C', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 8·sin 60°/sin 45° = 4√6.');
INSERT INTO public.questions VALUES (4651, 62, 'g10-geo-trig-q3-01', 3, 1, 'hard', 'single', 'sin α + cos α = −6/7 olarsa, sin α · cos α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−13/49", "B": "−13/98", "C": "−3/7", "D": "85/98", "E": "13/98"}'::jsonb, 'B', NULL, '(sin α + cos α)² = 1 + 2sin α cos α ⇒ sin α cos α = (36/49 − 1)/2 = −13/98.');
INSERT INTO public.questions VALUES (4652, 62, 'g10-geo-trig-q3-02', 3, 2, 'medium', 'single', 'tg α = −3/4 olarsa, (5sin α − 3cos α) / (5sin α − 4cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "3/31", "B": "−27/31", "C": "27/31", "D": "29/32", "E": "−27"}'::jsonb, 'C', NULL, 'Surəti və məxrəci cos α-ya bölün: (5·tg α + (−3))/(5·tg α − 4) = (−15/4 + (−3))/(−15/4 − 4) = 27/31.');
INSERT INTO public.questions VALUES (4653, 62, 'g10-geo-trig-q3-03', 3, 3, 'hard', 'single', 'sin α + cos α = 2/3 olarsa, sin α · cos α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−5/9", "B": "13/18", "C": "1/3", "D": "−5/18", "E": "5/18"}'::jsonb, 'D', NULL, '(sin α + cos α)² = 1 + 2sin α cos α ⇒ sin α cos α = (4/9 − 1)/2 = −5/18.');
INSERT INTO public.questions VALUES (4654, 62, 'g10-geo-trig-q3-04', 3, 4, 'medium', 'single', 'ABC üçbucağında BC = 7, ∠A = 60°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="72.2,186.0 247.8,186.0 160.0,34.0"/><text x="61.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="259.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M90.2,186.0 A18,18 0 0 0 81.2,170.4" stroke-width="1.2"/><text x="99.1" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M238.8,170.4 A18,18 0 0 0 229.8,186.0" stroke-width="1.2"/><text x="220.9" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="214.3" y="109.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text></svg>', '{"A": "21/2", "B": "14", "C": "7√3", "D": "8", "E": "7"}'::jsonb, 'E', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 7·sin 60°/sin 60° = 7.');
INSERT INTO public.questions VALUES (4655, 62, 'g10-geo-trig-q3-05', 3, 5, 'medium', 'single', 'tg α = −2 olarsa, (sin α + cos α) / (3sin α − cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1/7", "B": "−1/7", "C": "−1/5", "D": "3/7", "E": "1/5"}'::jsonb, 'A', NULL, 'Surəti və məxrəci cos α-ya bölün: (1·tg α + 1)/(3·tg α − 1) = (−2 + 1)/(−6 − 1) = 1/7.');
INSERT INTO public.questions VALUES (4656, 62, 'g10-geo-trig-q3-06', 3, 6, 'medium', 'single', 'sin α = −9/41 və π < α < 3π/2 olarsa, tg α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−40/9", "B": "9/40", "C": "40/9", "D": "−9/40", "E": "1/4"}'::jsonb, 'B', NULL, 'cos α = −√(1 − 81/1681) = −40/41 (rüb işarəsinə görə). tg α = 9/40.');
INSERT INTO public.questions VALUES (4657, 62, 'g10-geo-trig-q3-07', 3, 7, 'medium', 'single', 'ABC üçbucağında AB = 5, AC = 13, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="116.1,186.0 183.6,186.0 203.9,34.0"/><text x="106.8" y="200.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="187.5" y="203.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="208.2" y="26.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="145.9" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="156.4" y="103.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><path d="M134.1,186.0 A18,18 0 0 0 125.1,170.4" stroke-width="1.2"/><text x="143.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "√194", "B": "√129", "C": "8√2", "D": "9", "E": "√259"}'::jsonb, 'B', NULL, 'BC² = 13² + 5² − 2·13·5·cos 60° = 129 ⇒ BC = √129.');
INSERT INTO public.questions VALUES (4658, 62, 'g10-geo-trig-q3-08', 3, 8, 'medium', 'single', 'tg α = 1/3 olarsa, 2sin²α − 5cos²α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−43/10", "B": "−43/9", "C": "13/10", "D": "43/10", "E": "−43"}'::jsonb, 'A', NULL, 'Bölün sin²α + cos²α = 1-ə, sonra cos²α-ya: (2·tg²α + (−5))/(tg²α + 1) = (2/9 + (−5))/10/9 = −43/10.');
INSERT INTO public.questions VALUES (4659, 62, 'g10-geo-trig-q3-09', 3, 9, 'hard', 'single', 'sin α = −3/5 və π < α < 3π/2 olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "24/25", "B": "7/25", "C": "−7/25", "D": "16/25", "E": "32/25"}'::jsonb, 'B', NULL, 'cos α = −√(1 − 9/25) = −4/5 (rüb işarəsinə görə). cos 2α = 7/25.');
INSERT INTO public.questions VALUES (4660, 62, 'g10-geo-trig-q3-10', 3, 10, 'medium', 'single', 'sin α = 7/25 və π/2 < α < π olarsa, sin(π − α) + cos(3π/2 + α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "14/25", "B": "21/25", "C": "−14/25", "D": "28/25", "E": "7/25"}'::jsonb, 'A', NULL, 'cos α = −24/25. Çevirmə düsturları: sin(π − α) + cos(3π/2 + α) = sin α + sin α = 14/25.');
INSERT INTO public.questions VALUES (4661, 62, 'g10-geo-trig-q3-11', 3, 11, 'medium', 'single', 'ABC üçbucağında BC = 12, ∠A = 30°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,156.1 286.0,156.1 193.8,63.9"/><text x="21.3" y="164.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="164.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="198.2" y="56.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,156.1 A18,18 0 0 0 49.6,147.1" stroke-width="1.2"/><text x="63.9" y="153.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text><path d="M273.3,143.4 A18,18 0 0 0 268.0,156.1" stroke-width="1.2"/><text x="257.4" y="149.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="251.6" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "13√2", "B": "12√2", "C": "12", "D": "11√2", "E": "6√2"}'::jsonb, 'B', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 12·sin 45°/sin 30° = 12√2.');
INSERT INTO public.questions VALUES (4662, 62, 'g10-geo-trig-q3-12', 3, 12, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 20, ∠A = 120°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="131.8,180.6 188.2,180.6 84.8,99.1"/><text x="130.3" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="199.8" y="191.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="76.0" y="94.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.1" y="194.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="97.6" y="139.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><path d="M149.8,180.6 A18,18 0 0 0 122.8,165.0" stroke-width="1.2"/><text x="147.3" y="158.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "28", "B": "56√3/3", "C": "28√3/3", "D": "√2361/3", "E": "14√2"}'::jsonb, 'C', NULL, 'BC² = 784 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 120° ⇒ R = √784/√3 = 28√3/3.');
INSERT INTO public.questions VALUES (4663, 62, 'g10-geo-trig-q3-13', 3, 13, 'medium', 'single', 'sin α = 7/25 və 0 < α < π/2 olarsa, cos(π + α) − sin(π/2 − α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−96/25", "B": "−41/25", "C": "−48/25", "D": "48/25", "E": "−24/25"}'::jsonb, 'C', NULL, 'cos α = 24/25. Çevirmə düsturları: cos(π + α) − sin(π/2 − α) = −cos α − cos α = −48/25.');
INSERT INTO public.questions VALUES (4664, 62, 'g10-geo-trig-q3-14', 3, 14, 'medium', 'single', 'ABC üçbucağında AB = 13, AC = 15, ∠A = 60°. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="83.9,186.0 236.1,186.0 171.7,34.0"/><text x="73.0" y="198.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="246.7" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="172.7" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="159.1" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="118.0" y="108.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><path d="M101.9,186.0 A18,18 0 0 0 92.9,170.4" stroke-width="1.2"/><text x="110.8" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text></svg>', '{"A": "3", "B": "3√22", "C": "√394", "D": "√589", "E": "√199"}'::jsonb, 'E', NULL, 'BC² = 15² + 13² − 2·15·13·cos 60° = 199 ⇒ BC = √199.');
INSERT INTO public.questions VALUES (4665, 62, 'g10-geo-trig-q3-15', 3, 15, 'medium', 'single', 'sin α = 20/29 və π/2 < α < π olarsa, sin(3π/2 − α) · tg(π + α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "0", "B": "−20/29", "C": "−40/29", "D": "−10/29", "E": "20/29"}'::jsonb, 'B', NULL, 'cos α = −21/29. Çevirmə düsturları: sin(3π/2 − α) · tg(π + α) = (−cos α)·tg α = −sin α = −20/29.');
INSERT INTO public.questions VALUES (4666, 62, 'g10-geo-trig-q3-16', 3, 16, 'hard', 'single', 'cos α = −7/25 və π/2 < α < π olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−168/625", "B": "−67/125", "C": "336/625", "D": "−527/625", "E": "−336/625"}'::jsonb, 'E', NULL, 'sin α = √(1 − 49/625) = 24/25 (rüb işarəsinə görə). sin 2α = −336/625.');
INSERT INTO public.questions VALUES (4667, 62, 'g10-geo-trig-q3-17', 3, 17, 'medium', 'single', 'ABC üçbucağında BC = 5, ∠A = 45°, ∠B = 45°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 160.0,47.0"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M52.0,173.0 A18,18 0 0 0 46.7,160.3" stroke-width="1.2"/><text x="62.6" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><path d="M273.3,160.3 A18,18 0 0 0 268.0,173.0" stroke-width="1.2"/><text x="257.4" y="166.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">45°</text><text x="234.4" y="111.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text></svg>', '{"A": "4", "B": "6", "C": "5", "D": "10", "E": "5√2"}'::jsonb, 'C', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 5·sin 45°/sin 45° = 5.');
INSERT INTO public.questions VALUES (4668, 62, 'g10-geo-trig-q3-18', 3, 18, 'hard', 'single', 'sin α + cos α = −1/5 olarsa, sin α · cos α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−24/25", "B": "12/25", "C": "13/25", "D": "−1/10", "E": "−12/25"}'::jsonb, 'E', NULL, '(sin α + cos α)² = 1 + 2sin α cos α ⇒ sin α cos α = (1/25 − 1)/2 = −12/25.');
INSERT INTO public.questions VALUES (4669, 62, 'g10-geo-trig-q3-19', 3, 19, 'medium', 'single', 'tg α = 1/2 olarsa, (3sin α + 3cos α) / (3sin α + 5cos α) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9/11", "B": "9/13", "C": "−9/7", "D": "−9/13", "E": "−3/13"}'::jsonb, 'B', NULL, 'Surəti və məxrəci cos α-ya bölün: (3·tg α + 3)/(3·tg α − (−5)) = (3/2 + 3)/(3/2 − (−5)) = 9/13.');
INSERT INTO public.questions VALUES (4670, 62, 'g10-geo-trig-q3-20', 3, 20, 'medium', 'single', 'ABC üçbucağında BC = 5, ∠A = 60°, ∠B = 60°. AC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="72.2,186.0 247.8,186.0 160.0,34.0"/><text x="61.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="259.0" y="197.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><path d="M90.2,186.0 A18,18 0 0 0 81.2,170.4" stroke-width="1.2"/><text x="99.1" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><path d="M238.8,170.4 A18,18 0 0 0 229.8,186.0" stroke-width="1.2"/><text x="220.9" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="214.3" y="109.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text></svg>', '{"A": "10", "B": "15/2", "C": "5", "D": "6", "E": "5√3"}'::jsonb, 'C', NULL, 'Sinuslar teoremi: AC/sin B = BC/sin A ⇒ AC = 5·sin 60°/sin 60° = 5.');
INSERT INTO public.questions VALUES (4671, 63, 'g10-stat-avg-q1-01', 1, 1, 'medium', 'single', 'Testdə şagirdlərin balları belə paylanıb: 5 — 7 dəfə; 6 — 3 dəfə; 8 — 3 dəfə; 9 — 8 dəfə. Balların ədədi ortası ilə medianının fərqini tapın.', NULL, NULL, '{"A": "−19/21", "B": "2/21", "C": "−40/21", "D": "19/21", "E": "−1"}'::jsonb, 'A', NULL, 'n = 21, orta = 149/21, median = 8. Fərq: −19/21.');
INSERT INTO public.questions VALUES (4672, 63, 'g10-stat-avg-q1-02', 1, 2, 'hard', 'single', 'Birinci qrupdakı 16 şagirdin orta balı 79, ikinci qrupdakı şagirdlərin orta balı 75-dir. Bütün şagirdlərin orta balı 233/3 olarsa, ikinci qrupda neçə şagird var?', NULL, NULL, '{"A": "9", "B": "8", "C": "10", "D": "7", "E": "16"}'::jsonb, 'B', NULL, '16·79 + x·75 = (16 + x)·233/3 ⇒ x = 8.');
INSERT INTO public.questions VALUES (4673, 63, 'g10-stat-avg-q1-03', 1, 3, 'hard', 'single', '20, 39, 13, 34, 14, 38, x ədədlərinin ədədi ortası medianına bərabərdir. x > 39 olarsa, x-i tapın.', NULL, NULL, '{"A": "34", "B": "87", "C": "81", "D": "80", "E": "79"}'::jsonb, 'D', NULL, 'x ən böyük ədəddirsə, median 34. (Cəm + x)/7 = 34 ⇒ x = 7·34 − 158 = 80.');
INSERT INTO public.questions VALUES (4674, 63, 'g10-stat-avg-q1-04', 1, 4, 'medium', 'single', 'Sinifdəki 8 şagirdin orta balı 89 idi. Sinfə yeni şagird gəldikdən sonra orta bal 87 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "71", "B": "85", "C": "−18", "D": "79", "E": "63"}'::jsonb, 'A', NULL, 'Əvvəlki cəm 8·89 = 712, yeni cəm 9·87 = 783. Fərq: 71.');
INSERT INTO public.questions VALUES (4675, 63, 'g10-stat-avg-q1-05', 1, 5, 'medium', 'single', 'Birinci qrupdakı 10 şagirdin orta balı 92, ikinci qrupdakı 20 şagirdin orta balı 57-dir. Bütün şagirdlərin orta balını tapın.', NULL, NULL, '{"A": "203/3", "B": "149/2", "C": "209/3", "D": "206/3", "E": "241/3"}'::jsonb, 'D', NULL, 'Ümumi cəm 10·92 + 20·57 = 2060, şagird sayı 30. Orta: 206/3.');
