INSERT INTO public.questions VALUES (4719, 63, 'g10-stat-avg-q3-09', 3, 9, 'hard', 'single', 'Birinci qrupdakı 13 şagirdin orta balı 59, ikinci qrupdakı şagirdlərin orta balı 81-dir. Bütün şagirdlərin orta balı 217/3 olarsa, ikinci qrupda neçə şagird var?', NULL, NULL, '{"A": "20", "B": "21", "C": "13", "D": "22", "E": "19"}'::jsonb, 'A', NULL, '13·59 + x·81 = (13 + x)·217/3 ⇒ x = 20.');
INSERT INTO public.questions VALUES (4720, 63, 'g10-stat-avg-q3-10', 3, 10, 'hard', 'single', 'Birinci qrupdakı 14 şagirdin orta balı 87, ikinci qrupdakı şagirdlərin orta balı 52-dir. Bütün şagirdlərin orta balı 191/3 olarsa, ikinci qrupda neçə şagird var?', NULL, NULL, '{"A": "14", "B": "30", "C": "29", "D": "28", "E": "27"}'::jsonb, 'D', NULL, '14·87 + x·52 = (14 + x)·191/3 ⇒ x = 28.');
INSERT INTO public.questions VALUES (4721, 63, 'g10-stat-avg-q3-11', 3, 11, 'medium', 'single', 'Sinifdəki 9 şagirdin orta balı 25 idi. Sinfə yeni şagird gəldikdən sonra orta bal 28,5 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "32", "B": "60", "C": "69", "D": "51", "E": "35"}'::jsonb, 'B', NULL, 'Əvvəlki cəm 9·25 = 225, yeni cəm 10·28,5 = 285. Fərq: 60.');
INSERT INTO public.questions VALUES (4722, 63, 'g10-stat-avg-q3-12', 3, 12, 'medium', 'single', 'Sinifdəki 14 şagirdin orta balı 31 idi. Sinfə yeni şagird gəldikdən sonra orta bal 33 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "47", "B": "75", "C": "30", "D": "61", "E": "35"}'::jsonb, 'D', NULL, 'Əvvəlki cəm 14·31 = 434, yeni cəm 15·33 = 495. Fərq: 61.');
INSERT INTO public.questions VALUES (4723, 63, 'g10-stat-avg-q3-13', 3, 13, 'hard', 'single', '33, 8, 25, 38, 23, 39, x ədədlərinin ədədi ortası medianına bərabərdir. x > 39 olarsa, x-i tapın.', NULL, NULL, '{"A": "64", "B": "66", "C": "72", "D": "65", "E": "33"}'::jsonb, 'D', NULL, 'x ən böyük ədəddirsə, median 33. (Cəm + x)/7 = 33 ⇒ x = 7·33 − 166 = 65.');
INSERT INTO public.questions VALUES (4724, 63, 'g10-stat-avg-q3-14', 3, 14, 'hard', 'open', '4, 20, 8, 22, 30, 23, x ədədlərinin ədədi ortası medianına bərabərdir. x > 30 olarsa, x-i tapın.', NULL, NULL, NULL, NULL, '47', 'x ən böyük ədəddirsə, median 22. (Cəm + x)/7 = 22 ⇒ x = 7·22 − 107 = 47.');
INSERT INTO public.questions VALUES (4725, 63, 'g10-stat-avg-q3-15', 3, 15, 'hard', 'single', '8, 26, 6, 23, 20, 5, x ədədlərinin ədədi ortası medianına bərabərdir. x > 26 olarsa, x-i tapın.', NULL, NULL, '{"A": "59", "B": "51", "C": "20", "D": "52", "E": "53"}'::jsonb, 'D', NULL, 'x ən böyük ədəddirsə, median 20. (Cəm + x)/7 = 20 ⇒ x = 7·20 − 88 = 52.');
INSERT INTO public.questions VALUES (4726, 63, 'g10-stat-avg-q3-16', 3, 16, 'hard', 'single', '2, 8, 5, 11, 3, 19 verilənlərinin dispersiyasını tapın.', NULL, NULL, '{"A": "103/3", "B": "100/3", "C": "40", "D": "200/3", "E": "41"}'::jsonb, 'B', NULL, 'Orta: 8. Dispersiya: Σ(xᵢ − 8)²/6 = 100/3.');
INSERT INTO public.questions VALUES (4727, 63, 'g10-stat-avg-q3-17', 3, 17, 'hard', 'single', '3, 8, 15, 15, 8, 14, 15 verilənlərinin hər biri 4-ə vurulub, sonra −4 əlavə edilərsə, yeni verilənlərin ədədi ortası neçə olar?', NULL, NULL, '{"A": "1220/7", "B": "50/7", "C": "200/7", "D": "312/7", "E": "284/7"}'::jsonb, 'E', NULL, 'Əvvəlki orta 78/7, dispersiya 972/49. Yeni orta = 4·78/7 + (-4) = 284/7.');
INSERT INTO public.questions VALUES (4728, 63, 'g10-stat-avg-q3-18', 3, 18, 'hard', 'single', '9, 10, 20, 19, 1, 7 verilənlərinin dispersiyasını tapın.', NULL, NULL, '{"A": "271/5", "B": "136/3", "C": "133/3", "D": "266/5", "E": "266/3"}'::jsonb, 'C', NULL, 'Orta: 11. Dispersiya: Σ(xᵢ − 11)²/6 = 133/3.');
INSERT INTO public.questions VALUES (4729, 63, 'g10-stat-avg-q3-19', 3, 19, 'medium', 'single', 'Testdə şagirdlərin balları belə paylanıb: 2 — 3 dəfə; 5 — 8 dəfə; 6 — 3 dəfə; 7 — 4 dəfə. Balların medianı ilə modasının cəmini tapın.', NULL, NULL, '{"A": "9", "B": "11", "C": "91/9", "D": "10", "E": "12"}'::jsonb, 'D', NULL, 'n = 18, median = 5, moda = 5. Cəm: 10.');
INSERT INTO public.questions VALUES (4730, 63, 'g10-stat-avg-q3-20', 3, 20, 'medium', 'single', 'Sinifdəki 13 şagirdin orta balı 33 idi. Sinfə yeni şagird gəldikdən sonra orta bal 34 oldu. Yeni şagirdin balı neçədir?', NULL, NULL, '{"A": "60", "B": "35", "C": "34", "D": "47", "E": "14"}'::jsonb, 'D', NULL, 'Əvvəlki cəm 13·33 = 429, yeni cəm 14·34 = 476. Fərq: 47.');
INSERT INTO public.questions VALUES (4731, 64, 'g10-stat-prob-q1-01', 1, 1, 'hard', 'single', 'İki zər atılıb və xalların fərqinin modulunun ən azı 2 olduğu məlumdur. Xalların cəminin 7-dən böyük olmaması ehtimalını tapın.', NULL, NULL, '{"A": "2/5", "B": "5/9", "C": "13/20", "D": "3/5", "E": "1/3"}'::jsonb, 'D', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). |a − b| ≥ 2: 20 hal, onlardan cəmi ≤ 7: 12. P = 3/5.');
INSERT INTO public.questions VALUES (4732, 64, 'g10-stat-prob-q1-02', 1, 2, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,5; 0,4; 0,8. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,33", "B": "0,35", "C": "0,16", "D": "0,66", "E": "0,34"}'::jsonb, 'E', NULL, 'q = 1 − p: q₁ = 0,5, q₂ = 0,6, q₃ = 0,2. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,34.');
INSERT INTO public.questions VALUES (4733, 64, 'g10-stat-prob-q1-03', 1, 3, 'hard', 'single', 'Sinifdə 5 oğlan və 9 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "134/143", "B": "9/14", "C": "1875/2002", "D": "127/2002", "E": "937/1001"}'::jsonb, 'C', NULL, 'Tamamlayıcı: hamısı oğlan (1) və ya hamısı qız (126). P = 1 − 127/2002 = 1875/2002.');
INSERT INTO public.questions VALUES (4734, 64, 'g10-stat-prob-q1-04', 1, 4, 'hard', 'single', 'Qutuda 3 qırmızı, 3 ağ, 3 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "8/81", "B": "1/126", "C": "1/4", "D": "1/42", "E": "1/21"}'::jsonb, 'E', NULL, 'Bütün hallar: C(9, 4) = 126. Əlverişli: C(3, 3)·C(6, 1) = 6. P = 1/21.');
INSERT INTO public.questions VALUES (4735, 64, 'g10-stat-prob-q1-05', 1, 5, 'hard', 'single', 'Qutuda 6 qırmızı, 6 ağ, 3 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "216/625", "B": "36/91", "C": "18/91", "D": "1/91", "E": "1/5"}'::jsonb, 'B', NULL, 'Bütün hallar: C(15, 4) = 1365. Əlverişli: C(6, 2)·C(9, 2) = 540. P = 36/91.');
INSERT INTO public.questions VALUES (4736, 64, 'g10-stat-prob-q1-06', 1, 6, 'hard', 'single', 'Sinifdə 7 oğlan və 8 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "1259/1365", "B": "97/105", "C": "1/13", "D": "12/13", "E": "8/15"}'::jsonb, 'D', NULL, 'Tamamlayıcı: hamısı oğlan (35) və ya hamısı qız (70). P = 1 − 105/1365 = 12/13.');
INSERT INTO public.questions VALUES (4737, 64, 'g10-stat-prob-q1-07', 1, 7, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,9; 0,8; 0,9. Atıcılardan düz ikisinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,648", "B": "0,316", "C": "0,296", "D": "0,306", "E": "0,694"}'::jsonb, 'D', NULL, 'q = 1 − p: q₁ = 0,1, q₂ = 0,2, q₃ = 0,1. P = p₁p₂q₃ + p₁q₂p₃ + q₁p₂p₃ = 0,306.');
INSERT INTO public.questions VALUES (4738, 64, 'g10-stat-prob-q1-08', 1, 8, 'hard', 'single', 'İki zər atılıb və xalların cəminin 9-dan kiçik olmadığı məlumdur. Zərlərdən ən azı birində 6 düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "7/10", "B": "7/36", "C": "5/18", "D": "3/10", "E": "4/5"}'::jsonb, 'A', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). Cəmi ≥ 9 olan hallar: 10, onlardan 6 olanlar: 7. P = 7/10.');
INSERT INTO public.questions VALUES (4739, 64, 'g10-stat-prob-q1-09', 1, 9, 'hard', 'single', 'Birinci qutuda 6 qırmızı və 8 ağ, ikinci qutuda 2 qırmızı və 4 ağ şar var. Zər atılır: 1-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "1/14", "B": "8/21", "C": "22/63", "D": "41/63", "E": "2/5"}'::jsonb, 'C', NULL, 'Tam ehtimal düsturu: 1/6·3/7 + 5/6·1/3 = 22/63.');
INSERT INTO public.questions VALUES (4740, 64, 'g10-stat-prob-q1-10', 1, 10, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,6; 0,6; 0,6. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,298", "B": "0,712", "C": "0,288", "D": "0,216", "E": "0,278"}'::jsonb, 'C', NULL, 'q = 1 − p: q₁ = 0,4, q₂ = 0,4, q₃ = 0,4. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,288.');
INSERT INTO public.questions VALUES (4741, 64, 'g10-stat-prob-q1-11', 1, 11, 'hard', 'single', 'Sinifdə 3 oğlan və 7 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "0", "B": "251/252", "C": "7/10", "D": "1", "E": "253/252"}'::jsonb, 'D', NULL, 'Tamamlayıcı: 0 qız — C(3, 5) = 0, 1 qız — 7·C(3, 4) = 0. P = 1 − (0 + 0)/252 = 1.');
INSERT INTO public.questions VALUES (4742, 64, 'g10-stat-prob-q1-12', 1, 12, 'hard', 'single', 'Qutuda 5 qırmızı, 2 ağ, 2 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "10/21", "B": "5/21", "C": "5/18", "D": "5/63", "E": "800/2187"}'::jsonb, 'A', NULL, 'Bütün hallar: C(9, 4) = 126. Əlverişli: C(5, 2)·C(4, 2) = 60. P = 10/21.');
INSERT INTO public.questions VALUES (4743, 64, 'g10-stat-prob-q1-13', 1, 13, 'hard', 'single', '1, 2, 5, 6, 8 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 3-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "2/5", "B": "24/125", "C": "1/3", "D": "3/5", "E": "5/12"}'::jsonb, 'A', NULL, 'Bütün ədədlər: 60 (birinci rəqəm 0 ola bilməz). 3-ə bölünənlər: 24. P = 2/5.');
INSERT INTO public.questions VALUES (4744, 64, 'g10-stat-prob-q1-14', 1, 14, 'hard', 'single', 'Birinci qutuda 3 qırmızı və 6 ağ, ikinci qutuda 3 qırmızı və 7 ağ şar var. Zər atılır: 5-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "5/18", "B": "59/180", "C": "6/19", "D": "19/60", "E": "121/180"}'::jsonb, 'B', NULL, 'Tam ehtimal düsturu: 5/6·1/3 + 1/6·3/10 = 59/180.');
INSERT INTO public.questions VALUES (4745, 64, 'g10-stat-prob-q1-15', 1, 15, 'hard', 'single', 'Birinci qutuda 4 qırmızı və 8 ağ, ikinci qutuda 1 qırmızı və 8 ağ şar var. Zər atılır: 5-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "8/27", "B": "19/27", "C": "5/18", "D": "5/21", "E": "2/9"}'::jsonb, 'A', NULL, 'Tam ehtimal düsturu: 5/6·1/3 + 1/6·1/9 = 8/27.');
INSERT INTO public.questions VALUES (4746, 64, 'g10-stat-prob-q1-16', 1, 16, 'hard', 'single', 'Testdə 4 sual var, hər sualın 3 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 2 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "1/9", "B": "8/27", "C": "16/27", "D": "11/27", "E": "65/81"}'::jsonb, 'D', NULL, 'p = 1/3, q = 2/3. P(X ≥ 2) = 1 − Σ C(4, j)·p^j·q^(4 − j), j = 0…1 = 11/27.');
INSERT INTO public.questions VALUES (4747, 64, 'g10-stat-prob-q1-17', 1, 17, 'hard', 'single', '1, 3, 5, 8, 9 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 3-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "5/12", "B": "2/5", "C": "24/125", "D": "1/3", "E": "3/5"}'::jsonb, 'B', NULL, 'Bütün ədədlər: 60 (birinci rəqəm 0 ola bilməz). 3-ə bölünənlər: 24. P = 2/5.');
INSERT INTO public.questions VALUES (4748, 64, 'g10-stat-prob-q1-18', 1, 18, 'hard', 'single', '0, 3, 5, 6, 7, 9 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 9-a bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "2/27", "B": "17/100", "C": "4/25", "D": "21/25", "E": "1/9"}'::jsonb, 'C', NULL, 'Bütün ədədlər: 100 (birinci rəqəm 0 ola bilməz). 9-a bölünənlər: 16. P = 4/25.');
INSERT INTO public.questions VALUES (4749, 64, 'g10-stat-prob-q1-19', 1, 19, 'hard', 'single', 'Testdə 4 sual var, hər sualın 2 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 3 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "5/16", "B": "1/4", "C": "15/16", "D": "1/8", "E": "11/16"}'::jsonb, 'A', NULL, 'p = 1/2, q = 1/2. P(X ≥ 3) = 1 − Σ C(4, j)·p^j·q^(4 − j), j = 0…2 = 5/16.');
INSERT INTO public.questions VALUES (4750, 64, 'g10-stat-prob-q1-20', 1, 20, 'hard', 'single', 'Basketbolçu topu səbətə 2/3 ehtimalla salır. O, 6 atış edir (atışlar asılı deyil). Onun düz 1 dəfə topu səbətə salması ehtimalını tapın.', NULL, NULL, '{"A": "8/243", "B": "4", "C": "4/243", "D": "2/729", "E": "1/6"}'::jsonb, 'C', NULL, 'p = 2/3, q = 1/3. Bernulli düsturu: C(6, 1)·p^1·q^5 = 4/243.');
INSERT INTO public.questions VALUES (4751, 64, 'g10-stat-prob-q2-01', 2, 1, 'hard', 'single', 'Birinci qutuda 1 qırmızı və 6 ağ, ikinci qutuda 8 qırmızı və 2 ağ şar var. Zər atılır: 4-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "38/105", "B": "67/105", "C": "9/17", "D": "2/21", "E": "33/70"}'::jsonb, 'A', NULL, 'Tam ehtimal düsturu: 2/3·1/7 + 1/3·4/5 = 38/105.');
INSERT INTO public.questions VALUES (4752, 64, 'g10-stat-prob-q2-02', 2, 2, 'hard', 'single', 'Sinifdə 8 oğlan və 8 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "37/130", "B": "1303/1820", "C": "93/130", "D": "1/2", "E": "1301/1820"}'::jsonb, 'C', NULL, 'Tamamlayıcı: 0 qız — C(8, 4) = 70, 1 qız — 8·C(8, 3) = 448. P = 1 − (70 + 448)/1820 = 93/130.');
INSERT INTO public.questions VALUES (4753, 64, 'g10-stat-prob-q2-03', 2, 3, 'hard', 'single', 'Qutuda 6 qırmızı, 5 ağ, 2 göy şar var. Təsadüfi olaraq eyni anda 4 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "6048/28561", "B": "9/26", "C": "4/143", "D": "14/143", "E": "28/143"}'::jsonb, 'E', NULL, 'Bütün hallar: C(13, 4) = 715. Əlverişli: C(6, 3)·C(7, 1) = 140. P = 28/143.');
INSERT INTO public.questions VALUES (4754, 64, 'g10-stat-prob-q2-04', 2, 4, 'hard', 'single', '1, 4, 5, 7, 8 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 4-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/4", "B": "1/10", "C": "6/125", "D": "9/10", "E": "7/60"}'::jsonb, 'B', NULL, 'Bütün ədədlər: 60 (birinci rəqəm 0 ola bilməz). 4-ə bölünənlər: 6. P = 1/10.');
INSERT INTO public.questions VALUES (4755, 64, 'g10-stat-prob-q2-05', 2, 5, 'hard', 'single', '0, 1, 2, 4, 6, 8 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 6-ya bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "17/108", "B": "17/50", "C": "7/20", "D": "33/50", "E": "1/6"}'::jsonb, 'B', NULL, 'Bütün ədədlər: 100 (birinci rəqəm 0 ola bilməz). 6-ya bölünənlər: 34. P = 17/50.');
INSERT INTO public.questions VALUES (4756, 64, 'g10-stat-prob-q2-06', 2, 6, 'hard', 'single', 'Qutuda 2 qırmızı, 2 ağ, 2 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "1/20", "B": "1/10", "C": "2/9", "D": "1/4", "E": "1/5"}'::jsonb, 'E', NULL, 'Bütün hallar: C(6, 3) = 20. Əlverişli: C(2, 2)·C(4, 1) = 4. P = 1/5.');
INSERT INTO public.questions VALUES (4757, 64, 'g10-stat-prob-q2-07', 2, 7, 'hard', 'single', 'Testdə 5 sual var, hər sualın 3 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun düz 3 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "3/5", "B": "80/243", "C": "4/243", "D": "10/27", "E": "40/243"}'::jsonb, 'E', NULL, 'p = 1/3, q = 2/3. Bernulli düsturu: C(5, 3)·p^3·q^2 = 40/243.');
INSERT INTO public.questions VALUES (4758, 64, 'g10-stat-prob-q2-08', 2, 8, 'hard', 'single', 'Birinci qutuda 6 qırmızı və 1 ağ, ikinci qutuda 1 qırmızı və 2 ağ şar var. Zər atılır: 1-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "73/126", "B": "7/10", "C": "25/42", "D": "1/7", "E": "53/126"}'::jsonb, 'E', NULL, 'Tam ehtimal düsturu: 1/6·6/7 + 5/6·1/3 = 53/126.');
INSERT INTO public.questions VALUES (4759, 64, 'g10-stat-prob-q2-09', 2, 9, 'hard', 'single', '0, 2, 4, 5, 7 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 3-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/3", "B": "2/3", "C": "16/125", "D": "16/53", "E": "17/48"}'::jsonb, 'A', NULL, 'Bütün ədədlər: 48 (birinci rəqəm 0 ola bilməz). 3-ə bölünənlər: 16. P = 1/3.');
INSERT INTO public.questions VALUES (4760, 64, 'g10-stat-prob-q2-10', 2, 10, 'hard', 'single', 'Testdə 4 sual var, hər sualın 4 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 3 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "3/64", "B": "243/256", "C": "13/256", "D": "1/64", "E": "175/256"}'::jsonb, 'C', NULL, 'p = 1/4, q = 3/4. P(X ≥ 3) = 1 − Σ C(4, j)·p^j·q^(4 − j), j = 0…2 = 13/256.');
INSERT INTO public.questions VALUES (4761, 64, 'g10-stat-prob-q2-11', 2, 11, 'hard', 'single', 'Sinifdə 6 oğlan və 8 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "4/7", "B": "85/1001", "C": "916/1001", "D": "915/1001", "E": "131/143"}'::jsonb, 'C', NULL, 'Tamamlayıcı: hamısı oğlan (15) və ya hamısı qız (70). P = 1 − 85/1001 = 916/1001.');
INSERT INTO public.questions VALUES (4762, 64, 'g10-stat-prob-q2-12', 2, 12, 'hard', 'single', 'İki zər atılıb və xalların cəminin 8-dən kiçik olmadığı məlumdur. Zərlərdən ən azı birində 6 düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/4", "B": "2/3", "C": "3/5", "D": "5/12", "E": "2/5"}'::jsonb, 'C', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). Cəmi ≥ 8 olan hallar: 15, onlardan 6 olanlar: 9. P = 3/5.');
INSERT INTO public.questions VALUES (4763, 64, 'g10-stat-prob-q2-13', 2, 13, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,1; 0,8; 0,7. Atıcılardan ən azı ikisinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,402", "B": "0,598", "C": "0,056", "D": "0,608", "E": "0,588"}'::jsonb, 'B', NULL, 'q = 1 − p: q₁ = 0,9, q₂ = 0,2, q₃ = 0,3. P = p₁p₂q₃ + p₁q₂p₃ + q₁p₂p₃ + p₁p₂p₃ = 0,598.');
INSERT INTO public.questions VALUES (4764, 64, 'g10-stat-prob-q2-14', 2, 14, 'hard', 'open', 'Birinci qutuda 6 qırmızı və 8 ağ, ikinci qutuda 3 qırmızı və 2 ağ şar var. Zər atılır: 2-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, NULL, NULL, '19/35', 'Tam ehtimal düsturu: 1/3·3/7 + 2/3·3/5 = 19/35.');
INSERT INTO public.questions VALUES (4765, 64, 'g10-stat-prob-q2-15', 2, 15, 'hard', 'single', 'Qutuda 3 qırmızı, 2 ağ, 6 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz ikisinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "216/1331", "B": "8/55", "C": "2/11", "D": "1/55", "E": "4/55"}'::jsonb, 'B', NULL, 'Bütün hallar: C(11, 3) = 165. Əlverişli: C(3, 2)·C(8, 1) = 24. P = 8/55.');
INSERT INTO public.questions VALUES (4766, 64, 'g10-stat-prob-q2-16', 2, 16, 'hard', 'single', 'Sinifdə 6 oğlan və 4 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada ən azı 2 qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "58/105", "B": "19/42", "C": "19/35", "D": "23/42", "E": "2/5"}'::jsonb, 'D', NULL, 'Tamamlayıcı: 0 qız — C(6, 4) = 15, 1 qız — 4·C(6, 3) = 80. P = 1 − (15 + 80)/210 = 23/42.');
INSERT INTO public.questions VALUES (4767, 64, 'g10-stat-prob-q2-17', 2, 17, 'hard', 'single', 'İki zər atılıb və xalların cəminin 10 olduğu məlumdur. Hər iki zərdə eyni xalın düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/3", "B": "1/4", "C": "1/12", "D": "1/36", "E": "2/3"}'::jsonb, 'A', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). Cəmi 10: 3 hal, onlardan cüt (a = b): 1. P = 1/3.');
INSERT INTO public.questions VALUES (4768, 64, 'g10-stat-prob-q2-18', 2, 18, 'hard', 'single', 'Testdə 4 sual var, hər sualın 2 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun düz 3 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "3/8", "B": "1/16", "C": "1/2", "D": "1/4", "E": "3/4"}'::jsonb, 'D', NULL, 'p = 1/2, q = 1/2. Bernulli düsturu: C(4, 3)·p^3·q^1 = 1/4.');
INSERT INTO public.questions VALUES (4769, 64, 'g10-stat-prob-q2-19', 2, 19, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,3; 0,8; 0,9. Atıcılardan ən azı ikisinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,798", "B": "0,216", "C": "0,808", "D": "0,788", "E": "0,202"}'::jsonb, 'A', NULL, 'q = 1 − p: q₁ = 0,7, q₂ = 0,2, q₃ = 0,1. P = p₁p₂q₃ + p₁q₂p₃ + q₁p₂p₃ + p₁p₂p₃ = 0,798.');
INSERT INTO public.questions VALUES (4770, 64, 'g10-stat-prob-q2-20', 2, 20, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,7; 0,6; 0,7. Atıcılardan düz ikisinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,294", "B": "0,552", "C": "0,448", "D": "0,458", "E": "0,438"}'::jsonb, 'C', NULL, 'q = 1 − p: q₁ = 0,3, q₂ = 0,4, q₃ = 0,3. P = p₁p₂q₃ + p₁q₂p₃ + q₁p₂p₃ = 0,448.');
INSERT INTO public.questions VALUES (4771, 64, 'g10-stat-prob-q3-01', 3, 1, 'hard', 'single', 'Sinifdə 8 oğlan və 8 qız var. Təsadüfi olaraq 5 nəfərlik komissiya seçilir. Komissiyada həm oğlan, həm də qızın olması ehtimalını tapın.', NULL, NULL, '{"A": "38/39", "B": "1/39", "C": "1/2", "D": "1419/1456", "E": "4255/4368"}'::jsonb, 'A', NULL, 'Tamamlayıcı: hamısı oğlan (56) və ya hamısı qız (56). P = 1 − 112/4368 = 38/39.');
INSERT INTO public.questions VALUES (4772, 64, 'g10-stat-prob-q3-02', 3, 2, 'hard', 'single', 'Qutuda 2 qırmızı, 4 ağ, 3 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz birinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "98/243", "B": "1/42", "C": "1/4", "D": "2/27", "E": "1/2"}'::jsonb, 'E', NULL, 'Bütün hallar: C(9, 3) = 84. Əlverişli: C(2, 1)·C(7, 2) = 42. P = 1/2.');
INSERT INTO public.questions VALUES (4773, 64, 'g10-stat-prob-q3-03', 3, 3, 'hard', 'single', '2, 3, 4, 5, 6, 9 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 5-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "5/6", "B": "1/6", "C": "5/54", "D": "1/5", "E": "7/40"}'::jsonb, 'B', NULL, 'Bütün ədədlər: 120 (birinci rəqəm 0 ola bilməz). 5-ə bölünənlər: 20. P = 1/6.');
INSERT INTO public.questions VALUES (4774, 64, 'g10-stat-prob-q3-04', 3, 4, 'hard', 'single', 'Birinci qutuda 6 qırmızı və 7 ağ, ikinci qutuda 8 qırmızı və 3 ağ şar var. Zər atılır: 5-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "212/429", "B": "85/143", "C": "7/12", "D": "217/429", "E": "5/13"}'::jsonb, 'D', NULL, 'Tam ehtimal düsturu: 5/6·6/13 + 1/6·8/11 = 217/429.');
INSERT INTO public.questions VALUES (4775, 64, 'g10-stat-prob-q3-05', 3, 5, 'hard', 'single', 'Qutuda 3 qırmızı, 3 ağ, 3 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz birinin qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "15/28", "B": "15/56", "C": "4/9", "D": "1/28", "E": "1/9"}'::jsonb, 'A', NULL, 'Bütün hallar: C(9, 3) = 84. Əlverişli: C(3, 1)·C(6, 2) = 45. P = 15/28.');
INSERT INTO public.questions VALUES (4776, 64, 'g10-stat-prob-q3-06', 3, 6, 'hard', 'single', '0, 2, 3, 4, 7 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 9-a bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/9", "B": "2/25", "C": "5/24", "D": "11/48", "E": "19/24"}'::jsonb, 'C', NULL, 'Bütün ədədlər: 48 (birinci rəqəm 0 ola bilməz). 9-a bölünənlər: 10. P = 5/24.');
INSERT INTO public.questions VALUES (4777, 64, 'g10-stat-prob-q3-07', 3, 7, 'hard', 'single', 'Testdə 4 sual var, hər sualın 5 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 3 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "17/625", "B": "608/625", "C": "369/625", "D": "16/625", "E": "1/125"}'::jsonb, 'A', NULL, 'p = 1/5, q = 4/5. P(X ≥ 3) = 1 − Σ C(4, j)·p^j·q^(4 − j), j = 0…2 = 17/625.');
INSERT INTO public.questions VALUES (4778, 64, 'g10-stat-prob-q3-08', 3, 8, 'hard', 'single', 'Sinifdə 8 oğlan və 5 qız var. Təsadüfi olaraq 4 nəfərlik komissiya seçilir. Komissiyada qızların oğlanlardan çox olması ehtimalını tapın.', NULL, NULL, '{"A": "126/143", "B": "84/715", "C": "5/13", "D": "17/143", "E": "86/715"}'::jsonb, 'D', NULL, 'Σ C(5, j)·C(8, 4 − j), j > 4 − j, bölünsün C(13, 4) = 17/143.');
INSERT INTO public.questions VALUES (4779, 64, 'g10-stat-prob-q3-09', 3, 9, 'hard', 'single', '2, 3, 4, 5, 6, 8 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 4-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "5/27", "B": "2/3", "C": "1/4", "D": "1/3", "E": "41/120"}'::jsonb, 'D', NULL, 'Bütün ədədlər: 120 (birinci rəqəm 0 ola bilməz). 4-ə bölünənlər: 40. P = 1/3.');
INSERT INTO public.questions VALUES (4780, 64, 'g10-stat-prob-q3-10', 3, 10, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,4; 0,4; 0,5. Atıcılardan ən azı ikisinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,6", "B": "0,39", "C": "0,4", "D": "0,41", "E": "0,08"}'::jsonb, 'C', NULL, 'q = 1 − p: q₁ = 0,6, q₂ = 0,6, q₃ = 0,5. P = p₁p₂q₃ + p₁q₂p₃ + q₁p₂p₃ + p₁p₂p₃ = 0,4.');
INSERT INTO public.questions VALUES (4781, 64, 'g10-stat-prob-q3-11', 3, 11, 'hard', 'single', 'Birinci qutuda 4 qırmızı və 1 ağ, ikinci qutuda 5 qırmızı və 3 ağ şar var. Zər atılır: 1-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "157/240", "B": "2/15", "C": "9/13", "D": "83/240", "E": "57/80"}'::jsonb, 'A', NULL, 'Tam ehtimal düsturu: 1/6·4/5 + 5/6·5/8 = 157/240.');
INSERT INTO public.questions VALUES (4782, 64, 'g10-stat-prob-q3-12', 3, 12, 'hard', 'single', 'İki zər atılıb və xalların fərqinin modulunun ən azı 2 olduğu məlumdur. Xalların cəminin 6-dan böyük olmaması ehtimalını tapın.', NULL, NULL, '{"A": "2/9", "B": "5/9", "C": "9/20", "D": "2/5", "E": "3/5"}'::jsonb, 'D', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). |a − b| ≥ 2: 20 hal, onlardan cəmi ≤ 6: 8. P = 2/5.');
INSERT INTO public.questions VALUES (4783, 64, 'g10-stat-prob-q3-13', 3, 13, 'hard', 'single', 'İki zər atılıb və xalların fərqinin modulunun ən azı 2 olduğu məlumdur. Xalların cəminin 9-dan böyük olmaması ehtimalını tapın.', NULL, NULL, '{"A": "19/20", "B": "1/10", "C": "1/2", "D": "5/9", "E": "9/10"}'::jsonb, 'E', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). |a − b| ≥ 2: 20 hal, onlardan cəmi ≤ 9: 18. P = 9/10.');
INSERT INTO public.questions VALUES (4784, 64, 'g10-stat-prob-q3-14', 3, 14, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,2; 0,8; 0,9. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,212", "B": "0,202", "C": "0,144", "D": "0,788", "E": "0,222"}'::jsonb, 'A', NULL, 'q = 1 − p: q₁ = 0,8, q₂ = 0,2, q₃ = 0,1. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,212.');
INSERT INTO public.questions VALUES (4785, 64, 'g10-stat-prob-q3-15', 3, 15, 'hard', 'single', 'Birinci qutuda 8 qırmızı və 2 ağ, ikinci qutuda 1 qırmızı və 6 ağ şar var. Zər atılır: 5-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "29/42", "B": "13/42", "C": "2/3", "D": "33/70", "E": "9/17"}'::jsonb, 'A', NULL, 'Tam ehtimal düsturu: 5/6·4/5 + 1/6·1/7 = 29/42.');
INSERT INTO public.questions VALUES (4786, 64, 'g10-stat-prob-q3-16', 3, 16, 'hard', 'single', 'İki zər atılıb və xalların fərqinin modulunun ən azı 2 olduğu məlumdur. Xalların cəminin 5-dən böyük olmaması ehtimalını tapın.', NULL, NULL, '{"A": "1/9", "B": "1/5", "C": "5/9", "D": "1/4", "E": "4/5"}'::jsonb, 'B', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). |a − b| ≥ 2: 20 hal, onlardan cəmi ≤ 5: 4. P = 1/5.');
INSERT INTO public.questions VALUES (4787, 64, 'g10-stat-prob-q3-17', 3, 17, 'hard', 'single', 'Basketbolçu topu səbətə 2/3 ehtimalla salır. O, 4 atış edir (atışlar asılı deyil). Onun düz 1 dəfə topu səbətə salması ehtimalını tapın.', NULL, NULL, '{"A": "8/3", "B": "2/81", "C": "8/81", "D": "16/81", "E": "1/4"}'::jsonb, 'C', NULL, 'p = 2/3, q = 1/3. Bernulli düsturu: C(4, 1)·p^1·q^3 = 8/81.');
INSERT INTO public.questions VALUES (4788, 64, 'g10-stat-prob-q3-18', 3, 18, 'hard', 'single', 'Qutuda 3 qırmızı, 3 ağ, 5 göy şar var. Təsadüfi olaraq eyni anda 3 şar götürülür. Onlardan düz üçünün qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "1/330", "B": "27/1331", "C": "3/11", "D": "2/165", "E": "1/165"}'::jsonb, 'E', NULL, 'Bütün hallar: C(11, 3) = 165. Əlverişli: C(3, 3)·C(8, 0) = 1. P = 1/165.');
INSERT INTO public.questions VALUES (4789, 64, 'g10-stat-prob-q3-19', 3, 19, 'hard', 'single', 'Üç atıcı hədəfə bir-birindən asılı olmadan bir dəfə atəş açır. Hədəfi vurma ehtimalları uyğun olaraq 0,7; 0,3; 0,3. Atıcılardan yalnız birinin hədəfi vurması ehtimalını tapın.', NULL, NULL, '{"A": "0,459", "B": "0,469", "C": "0,479", "D": "0,063", "E": "0,531"}'::jsonb, 'B', NULL, 'q = 1 − p: q₁ = 0,3, q₂ = 0,7, q₃ = 0,7. P = p₁q₂q₃ + q₁p₂q₃ + q₁q₂p₃ = 0,469.');
INSERT INTO public.questions VALUES (4790, 64, 'g10-stat-prob-q3-20', 3, 20, 'hard', 'single', 'Testdə 5 sual var, hər sualın 4 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 1 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "391/512", "B": "243/1024", "C": "405/1024", "D": "1/4", "E": "781/1024"}'::jsonb, 'E', NULL, 'p = 1/4, q = 3/4. P(X ≥ 1) = 1 − Σ C(5, j)·p^j·q^(5 − j), j = 0…0 = 781/1024.');
INSERT INTO public.questions VALUES (4791, 65, 'g10-aze-sound-q1-01', 1, 1, 'hard', 'single', '«kirpi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar), 1 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'D', NULL, '«kirpi» — hecalar: kir-pi. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4792, 65, 'g10-aze-sound-q1-02', 1, 2, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "ko-man-da", "B": "qırm-ı-zı", "C": "hə-diyy-ə", "D": "o-yunç-u", "E": "i-ldı-rım"}'::jsonb, 'A', NULL, 'Düzgün bölgü: ko-man-da. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (4793, 65, 'g10-aze-sound-q1-03', 1, 3, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz samitlə başlayır, 1 açıq (geniş) sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "geniş, narıncı, yol", "B": "qısa, sarı, tufan", "C": "dolu, kaman, qonşu", "D": "arzu, duman, sol", "E": "masa, nar, qoyun"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4794, 65, 'g10-aze-sound-q1-04', 1, 4, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "dost – meşə", "B": "dayı – təpə", "C": "komanda – nərgiz", "D": "aslan – divan", "E": "qarpız – səmimi"}'::jsonb, 'A', NULL, '«dost»: dost; «meşə»: me-şə. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4795, 65, 'g10-aze-sound-q1-05', 1, 5, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə həm qalın, həm də incə sait var, son heca qapalıdır və 1 qapalı (dar) sait var?', NULL, NULL, '{"A": "cəsur, maşın, muzey", "B": "hakim, sahil, yaşıl", "C": "fil, kitablar, mehriban", "D": "alim, ilan, meymun", "E": "liman, qaranquş, çinar"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4796, 65, 'g10-aze-sound-q1-06', 1, 6, 'hard', 'single', '«bayram» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor", "B": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor", "D": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor"}'::jsonb, 'E', NULL, '«bayram» — hecalar: bay-ram. 2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor.');
INSERT INTO public.questions VALUES (4797, 65, 'g10-aze-sound-q1-07', 1, 7, 'hard', 'single', '«səhra» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 0 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'C', NULL, '«səhra» — hecalar: səh-ra. 2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4798, 65, 'g10-aze-sound-q1-08', 1, 8, 'hard', 'single', '«mehriban» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (4 cingiltili, 1 kar), 3 sonor", "B": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə); 5 samit (4 cingiltili, 1 kar), 4 sonor", "C": "3 heca (0 açıq, 3 qapalı); 3 sait (1 qalın, 2 incə); 5 samit (4 cingiltili, 1 kar), 3 sonor", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə); 5 samit (3 cingiltili, 2 kar), 3 sonor", "E": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə); 5 samit (4 cingiltili, 1 kar), 3 sonor"}'::jsonb, 'E', NULL, '«mehriban» — hecalar: meh-ri-ban. 3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə); 5 samit (4 cingiltili, 1 kar), 3 sonor.');
INSERT INTO public.questions VALUES (4799, 65, 'g10-aze-sound-q1-09', 1, 9, 'medium', 'single', 'Hansı sözdə son heca qapalıdır və 3 qapalı (dar) sait var?', NULL, NULL, '{"A": "çöl", "B": "divan", "C": "cəsarət", "D": "ildırım", "E": "dəniz"}'::jsonb, 'D', NULL, '«ildırım»: hecalar — il-dı-rım; saitlər — 3 (2 qalın, 1 incə, 0 dodaqlanan); samitlər — 4 (4 cingiltili, 0 kar, 3 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4800, 65, 'g10-aze-sound-q1-10', 1, 10, 'hard', 'single', '«sərin» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "E": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'D', NULL, '«sərin» — hecalar: sə-rin. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4801, 65, 'g10-aze-sound-q1-11', 1, 11, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "aslan – zaman", "B": "dastan – gəlin", "C": "tar – əmi", "D": "həkim – sərin", "E": "hekayə – qardaş"}'::jsonb, 'C', NULL, '«tar»: tar; «əmi»: ə-mi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4802, 65, 'g10-aze-sound-q1-12', 1, 12, 'medium', 'single', 'Hansı sözdə son heca açıqdır və kar samit yoxdur?', NULL, NULL, '{"A": "gül", "B": "təyyarə", "C": "səma", "D": "musiqi", "E": "gecə"}'::jsonb, 'E', NULL, '«gecə»: hecalar — ge-cə; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4803, 65, 'g10-aze-sound-q1-13', 1, 13, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "gilas – parça", "B": "həsrət – zaman", "C": "cəsur – qonşu", "D": "hündür – isti", "E": "daş – fil"}'::jsonb, 'B', NULL, '«həsrət»: həs-rət; «zaman»: za-man. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4804, 65, 'g10-aze-sound-q1-14', 1, 14, 'medium', 'single', 'Hansı sözdə 2 heca var və 7 səs var?', NULL, NULL, '{"A": "konsert", "B": "gecə", "C": "duman", "D": "şaftalı", "E": "qara"}'::jsonb, 'A', NULL, '«konsert»: hecalar — kon-sert; saitlər — 2 (1 qalın, 1 incə, 1 dodaqlanan); samitlər — 5 (2 cingiltili, 3 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4805, 65, 'g10-aze-sound-q1-15', 1, 15, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 açıq heca var, dodaqlanan sait yoxdur və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "medal, yarış, çinar", "B": "ildırım, mehriban, sevgi", "C": "tarix, xəyal, yarış", "D": "gəlin, sahil, şagirdlər", "E": "alim, gilas, kitablar"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4806, 65, 'g10-aze-sound-q1-16', 1, 16, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "bayram – dolma", "B": "qum – çəmən", "C": "dərin – lalə", "D": "qapı – səma", "E": "dəmir – kartof"}'::jsonb, 'E', NULL, '«dəmir»: də-mir; «kartof»: kar-tof. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4807, 65, 'g10-aze-sound-q1-17', 1, 17, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "nəfəs – yarış", "B": "alça – şirin", "C": "dayı – oyun", "D": "mehriban – tələbə", "E": "baba – qələm"}'::jsonb, 'E', NULL, '«baba»: ba-ba; «qələm»: qə-ləm. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4808, 65, 'g10-aze-sound-q1-18', 1, 18, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz samitlə başlayır, 1 qapalı (dar) sait var və bütün saitlər incədir?', NULL, NULL, '{"A": "gül, nərgiz, pendir", "B": "geniş, sevgi, çöl", "C": "geri, gəlin, əmi", "D": "dəmir, gecə, yemiş", "E": "küçə, süfrə, sürücü"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4809, 65, 'g10-aze-sound-q1-19', 1, 19, 'hard', 'single', 'Hansı sözdə bütün saitlər qalındır, kar samitlər cingiltili samitlərdən çoxdur və 1 qapalı heca var?', NULL, NULL, '{"A": "zaman", "B": "boz", "C": "top", "D": "sol", "E": "həftə"}'::jsonb, 'C', NULL, '«top»: hecalar — top; saitlər — 1 (1 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (0 cingiltili, 2 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4810, 65, 'g10-aze-sound-q1-20', 1, 20, 'medium', 'single', 'Hansı sözdə dodaqlanan sait yoxdur və açıq heca yoxdur?', NULL, NULL, '{"A": "çinar", "B": "kənar", "C": "qalay", "D": "bülbül", "E": "nar"}'::jsonb, 'E', NULL, '«nar»: hecalar — nar; saitlər — 1 (1 qalın, 0 incə, 0 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4811, 65, 'g10-aze-sound-q1-21', 1, 21, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "tor – əmi", "B": "tamaşa – yemiş", "C": "dolu – isti", "D": "aslan – kölgə", "E": "kirpi – yarış"}'::jsonb, 'A', NULL, '«tor»: tor; «əmi»: ə-mi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4812, 65, 'g10-aze-sound-q1-22', 1, 22, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 qapalı heca var, söz samitlə başlayır və bütün saitlər qalındır?', NULL, NULL, '{"A": "parça, qırmızı, yoldaş", "B": "nişan, yaşıl, çanta", "C": "qoyun, turş, çinar", "D": "gil, pozan, şorba", "E": "lampa, nar, qonşu"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4813, 65, 'g10-aze-sound-q1-23', 1, 23, 'hard', 'single', 'Hansı sözdə kar samitlər cingiltili samitlərdən çoxdur, 2 açıq (geniş) sait var və 1 açıq heca var?', NULL, NULL, '{"A": "körpü", "B": "şagirdlər", "C": "tarla", "D": "tufan", "E": "xalça"}'::jsonb, 'E', NULL, '«xalça»: hecalar — xal-ça; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4814, 65, 'g10-aze-sound-q1-24', 1, 24, 'medium', 'single', 'Hansı sözdə 1 qapalı heca var və kar samit yoxdur?', NULL, NULL, '{"A": "qum", "B": "körpü", "C": "dələ", "D": "ildırım", "E": "sərin"}'::jsonb, 'A', NULL, '«qum»: hecalar — qum; saitlər — 1 (1 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4815, 65, 'g10-aze-sound-q1-25', 1, 25, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "ca-vabl-ar", "B": "çar-pa-yı", "C": "yas-ə-mən", "D": "qırm-ı-zı", "E": "sə-nə-tkar"}'::jsonb, 'B', NULL, 'Düzgün bölgü: çar-pa-yı. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (4816, 65, 'g10-aze-sound-q1-26', 1, 26, 'hard', 'single', '«tarix» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor"}'::jsonb, 'A', NULL, '«tarix» — hecalar: ta-rix. 2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4817, 65, 'g10-aze-sound-q1-27', 1, 27, 'hard', 'single', '«kirpi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar), 1 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'D', NULL, '«kirpi» — hecalar: kir-pi. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4818, 65, 'g10-aze-sound-q1-28', 1, 28, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "qapıçı – səmimi", "B": "həyat – yemiş", "C": "addım – dəmir", "D": "qapıçı – səbir", "E": "aslan – əmi"}'::jsonb, 'A', NULL, '«qapıçı»: qa-pı-çı; «səmimi»: sə-mi-mi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4819, 65, 'g10-aze-sound-q1-29', 1, 29, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə dodaqlanan sait yoxdur, qapalı heca yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "ayı, sarı, çanta", "B": "ada, bacı, yarış", "C": "dayı, hekayə, qapıçı", "D": "ana, ata, saniyə", "E": "arı, qısa, yazıçı"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4820, 65, 'g10-aze-sound-q1-30', 1, 30, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz samitlə başlayır, kar samit yoxdur və bütün saitlər incədir?', NULL, NULL, '{"A": "dərə, gözəl, mis", "B": "dəniz, güzgü, körpü", "C": "gül, nərgiz, pəncərə", "D": "bülbül, dəqiqə, çəmən", "E": "geri, gil, gündüz"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4821, 65, 'g10-aze-sound-q2-01', 2, 1, 'hard', 'single', 'Hansı sözdə 3 qapalı (dar) sait var, qapalı heca yoxdur və 3 açıq heca var?', NULL, NULL, '{"A": "yazıçı", "B": "qapıçı", "C": "xəritə", "D": "dəqiqə", "E": "sürücü"}'::jsonb, 'E', NULL, '«sürücü»: hecalar — sü-rü-cü; saitlər — 3 (0 qalın, 3 incə, 3 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4822, 65, 'g10-aze-sound-q2-02', 2, 2, 'hard', 'single', '«pomidor» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (2 cingiltili, 2 kar), 2 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar), 3 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor", "E": "4 heca (3 açıq, 1 qapalı); 4 sait (3 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'C', NULL, '«pomidor» — hecalar: po-mi-dor. 3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4823, 65, 'g10-aze-sound-q2-03', 2, 3, 'hard', 'single', '«dərin» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (4 cingiltili, 0 kar), 2 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "C": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor"}'::jsonb, 'D', NULL, '«dərin» — hecalar: də-rin. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4824, 65, 'g10-aze-sound-q2-04', 2, 4, 'hard', 'single', '«qızılgül» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (2 açıq, 2 qapalı); 4 sait (3 qalın, 1 incə); 5 samit (5 cingiltili, 0 kar), 2 sonor", "B": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə); 6 samit (5 cingiltili, 1 kar), 2 sonor", "C": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə); 5 samit (5 cingiltili, 0 kar), 2 sonor", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə); 5 samit (5 cingiltili, 0 kar), 2 sonor", "E": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə); 5 samit (4 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'C', NULL, '«qızılgül» — hecalar: qı-zıl-gül. 3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə); 5 samit (5 cingiltili, 0 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4825, 65, 'g10-aze-sound-q2-05', 2, 5, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 dodaqlanan sait var, 1 açıq (geniş) sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "boz, qısa, toy", "B": "arzu, durna, günəş", "C": "tufan, yol, çay", "D": "dost, duman, yuxarı", "E": "kino, sol, top"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4826, 65, 'g10-aze-sound-q2-06', 2, 6, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "bostan – xala", "B": "kino – nar", "C": "qələm – sərin", "D": "acı – bayram", "E": "arzu – səs"}'::jsonb, 'A', NULL, '«bostan»: bos-tan; «xala»: xa-la. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4827, 65, 'g10-aze-sound-q2-07', 2, 7, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə cingiltili samitlər kar samitlərdən çoxdur, 1 qapalı heca var və bütün saitlər qalındır?', NULL, NULL, '{"A": "bal, duman, xəyal", "B": "canavar, durna, narıncı", "C": "aslan, qum, çoban", "D": "ozan, pozan, çinar", "E": "duz, lampa, qardaş"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4828, 65, 'g10-aze-sound-q2-08', 2, 8, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "konsert – ozan", "B": "kölgə – nar", "C": "gilas – yun", "D": "daş – gözəl", "E": "axşam – meymun"}'::jsonb, 'A', NULL, '«konsert»: kon-sert; «ozan»: o-zan. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4829, 65, 'g10-aze-sound-q2-09', 2, 9, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 açıq heca var, 1 açıq (geniş) sait var və bütün saitlər incədir?', NULL, NULL, '{"A": "divan, dəmir, günəş", "B": "dərin, geniş, sərin", "C": "dəniz, qorxu, yemiş", "D": "isti, mühəndis, səbir", "E": "arzu, gəlin, körpü"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4830, 65, 'g10-aze-sound-q2-10', 2, 10, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "gəmi – qızıl", "B": "qalay – tarla", "C": "masa – meşə", "D": "kino – sinif", "E": "göl – gəlin"}'::jsonb, 'D', NULL, '«kino»: ki-no; «sinif»: si-nif. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4831, 65, 'g10-aze-sound-q2-11', 2, 11, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə dodaqlanan sait yoxdur, qapalı (dar) sait yoxdur və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "kənar, rəssam, səhər", "B": "həyat, mavi, sənətkar", "C": "cəsarət, medal, xəyal", "D": "hekayə, heyva, sahil", "E": "ana, lalə, səyahət"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4832, 65, 'g10-aze-sound-q2-12', 2, 12, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "ozan – üzüm", "B": "ata – gəlin", "C": "aslan – dərə", "D": "dost – gəmi", "E": "kədər – medal"}'::jsonb, 'D', NULL, '«dost»: dost; «gəmi»: gə-mi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4833, 65, 'g10-aze-sound-q2-13', 2, 13, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "geniş – liman", "B": "dost – qardaş", "C": "küçə – tufan", "D": "hörmət – mənzərə", "E": "gündüz – nişan"}'::jsonb, 'E', NULL, '«gündüz»: gün-düz; «nişan»: ni-şan. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4834, 65, 'g10-aze-sound-q2-14', 2, 14, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "ko-mand-a", "B": "təy-ya-rə", "C": "pə-ncə-rə", "D": "gö-yərç-in", "E": "şaf-tal-ı"}'::jsonb, 'B', NULL, 'Düzgün bölgü: təy-ya-rə. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (4835, 65, 'g10-aze-sound-q2-15', 2, 15, 'medium', 'single', 'Hansı sözdə 1 açıq (geniş) sait var və 3 səs var?', NULL, NULL, '{"A": "dünya", "B": "duman", "C": "nərgiz", "D": "top", "E": "səbir"}'::jsonb, 'D', NULL, '«top»: hecalar — top; saitlər — 1 (1 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (0 cingiltili, 2 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4836, 65, 'g10-aze-sound-q2-16', 2, 16, 'medium', 'single', 'Hansı sözdə cingiltili samitlər kar samitlərdən çoxdur və açıq (geniş) sait yoxdur?', NULL, NULL, '{"A": "yaşıl", "B": "yol", "C": "geniş", "D": "sərin", "E": "qızıl"}'::jsonb, 'E', NULL, '«qızıl»: hecalar — qı-zıl; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 3 (3 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4837, 65, 'g10-aze-sound-q2-17', 2, 17, 'hard', 'single', 'Hansı sözdə 4 səs var, 2 sonor samit var və cingiltili samitlər kar samitlərdən çoxdur?', NULL, NULL, '{"A": "şirin", "B": "medal", "C": "alim", "D": "gecə", "E": "dayı"}'::jsonb, 'C', NULL, '«alim»: hecalar — a-lim; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4838, 65, 'g10-aze-sound-q2-18', 2, 18, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 açıq heca var, söz samitlə başlayır və bütün saitlər incədir?', NULL, NULL, '{"A": "dəniz, fikir, şəkər", "B": "güzgü, mühəndis, səmimi", "C": "dəmirçi, fəhlə, kölgə", "D": "duman, həkim, yemiş", "E": "gümüş, heyva, süfrə"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4839, 65, 'g10-aze-sound-q2-19', 2, 19, 'hard', 'single', '«dəniz» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 0 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar), 1 sonor"}'::jsonb, 'B', NULL, '«dəniz» — hecalar: də-niz. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4840, 65, 'g10-aze-sound-q2-20', 2, 20, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 qapalı heca var, 1 dodaqlanan sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "duman, kölgə, pozan", "B": "maşın, ozan, toy", "C": "dolma, orta, turş", "D": "durna, duz, göl", "E": "arzu, qalay, sol"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4841, 65, 'g10-aze-sound-q2-21', 2, 21, 'medium', 'single', 'Hansı sözdə 1 qapalı heca var və bütün saitlər qalındır?', NULL, NULL, '{"A": "yarış", "B": "tamaşa", "C": "kartof", "D": "pomidor", "E": "alim"}'::jsonb, 'A', NULL, '«yarış»: hecalar — ya-rış; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4842, 65, 'g10-aze-sound-q2-22', 2, 22, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "axşam – qorxu", "B": "durna – sərçə", "C": "dost – meşə", "D": "qapı – qələbə", "E": "tarix – xiyar"}'::jsonb, 'C', NULL, '«dost»: dost; «meşə»: me-şə. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4843, 65, 'g10-aze-sound-q2-23', 2, 23, 'hard', 'single', '«saniyə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (4 açıq, 0 qapalı); 4 sait (1 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "C": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "E": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar), 2 sonor"}'::jsonb, 'D', NULL, '«saniyə» — hecalar: sa-ni-yə. 3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4844, 65, 'g10-aze-sound-q2-24', 2, 24, 'hard', 'single', '«mühəndis» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (3 cingiltili, 2 kar), 1 sonor", "B": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (4 cingiltili, 1 kar), 2 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (3 cingiltili, 2 kar), 2 sonor", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (3 cingiltili, 2 kar), 2 sonor", "E": "3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (2 cingiltili, 3 kar), 2 sonor"}'::jsonb, 'D', NULL, '«mühəndis» — hecalar: mü-hən-dis. 3 heca (1 açıq, 2 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (3 cingiltili, 2 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4845, 65, 'g10-aze-sound-q2-25', 2, 25, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə açıq heca yoxdur, 1 qapalı heca var və bütün saitlər qalındır?', NULL, NULL, '{"A": "dost, tor, yoldaş", "B": "daş, duz, çay", "C": "boz, uzun, şam", "D": "bal, duman, toy", "E": "qar, top, şorba"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4846, 65, 'g10-aze-sound-q2-26', 2, 26, 'hard', 'single', '«süfrə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 0 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "E": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'D', NULL, '«süfrə» — hecalar: süf-rə. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4847, 65, 'g10-aze-sound-q2-27', 2, 27, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "ca-nav-ar", "B": "mehr-i-ban", "C": "nar-ın-cı", "D": "sə-xa-və-tli", "E": "tə-ba-şir"}'::jsonb, 'E', NULL, 'Düzgün bölgü: tə-ba-şir. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (4848, 65, 'g10-aze-sound-q2-28', 2, 28, 'hard', 'single', 'Hansı sözdə söz samitlə başlayır, son heca qapalıdır və cingiltili samitlər kar samitlərdən çoxdur?', NULL, NULL, '{"A": "cəsarət", "B": "pozan", "C": "həsrət", "D": "güzgü", "E": "səhər"}'::jsonb, 'B', NULL, '«pozan»: hecalar — po-zan; saitlər — 2 (2 qalın, 0 incə, 1 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4849, 65, 'g10-aze-sound-q2-29', 2, 29, 'hard', 'single', 'Hansı sözdə 2 heca var, 1 açıq (geniş) sait var və 4 səs var?', NULL, NULL, '{"A": "sərgi", "B": "küçə", "C": "kətə", "D": "tarix", "E": "xala"}'::jsonb, 'B', NULL, '«küçə»: hecalar — kü-çə; saitlər — 2 (0 qalın, 2 incə, 1 dodaqlanan); samitlər — 2 (0 cingiltili, 2 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4850, 65, 'g10-aze-sound-q2-30', 2, 30, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "musiqi – çarpayı", "B": "dülgər – əkinçi", "C": "dərə – ilan", "D": "mavi – yemiş", "E": "orta – savadlı"}'::jsonb, 'A', NULL, '«musiqi»: mu-si-qi; «çarpayı»: çar-pa-yı. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4851, 65, 'g10-aze-sound-q3-01', 3, 1, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə qapalı (dar) sait yoxdur, açıq heca yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "aslan, daş, həsrət", "B": "bal, tar, tarla", "C": "nar, toy, yoldaş", "D": "axşam, masa, sol", "E": "bayram, masa, saz"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4852, 65, 'g10-aze-sound-q3-02', 3, 2, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "bayram – kətə", "B": "kino – şəkər", "C": "duz – fəhlə", "D": "yun – əmi", "E": "günəş – güzgü"}'::jsonb, 'B', NULL, '«kino»: ki-no; «şəkər»: şə-kər. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4853, 65, 'g10-aze-sound-q3-03', 3, 3, 'hard', 'single', '«meymun» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar), 4 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (4 cingiltili, 0 kar), 4 sonor", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar), 4 sonor", "D": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar), 3 sonor", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə); 4 samit (4 cingiltili, 0 kar), 4 sonor"}'::jsonb, 'C', NULL, '«meymun» — hecalar: mey-mun. 2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə); 4 samit (4 cingiltili, 0 kar), 4 sonor.');
INSERT INTO public.questions VALUES (4854, 65, 'g10-aze-sound-q3-04', 3, 4, 'hard', 'single', '«oyunçu» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (3 açıq, 1 qapalı); 4 sait (4 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'C', NULL, '«oyunçu» — hecalar: o-yun-çu. 3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4855, 65, 'g10-aze-sound-q3-05', 3, 5, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə bütün saitlər qalındır, söz samitlə başlayır və son heca qapalıdır?', NULL, NULL, '{"A": "göl, top, yaşıl", "B": "canavar, dəftər, qartal", "C": "qar, qatar, yol", "D": "dastan, tamaşa, tufan", "E": "bostan, sol, yazıçı"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4856, 65, 'g10-aze-sound-q3-06', 3, 6, 'hard', 'single', '«dəmirçi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (3 cingiltili, 1 kar), 3 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (3 cingiltili, 1 kar), 1 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (3 cingiltili, 2 kar), 2 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 5 samit (4 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'D', NULL, '«dəmirçi» — hecalar: də-mir-çi. 3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4857, 65, 'g10-aze-sound-q3-07', 3, 7, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "duz – dərin", "B": "gilas – gündüz", "C": "ozan – şəkər", "D": "göl – ozan", "E": "dolu – geniş"}'::jsonb, 'E', NULL, '«dolu»: do-lu; «geniş»: ge-niş. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4858, 65, 'g10-aze-sound-q3-08', 3, 8, 'medium', 'single', 'Hansı sözdə dodaqlanan sait yoxdur və kar samitlər cingiltili samitlərdən çoxdur?', NULL, NULL, '{"A": "mis", "B": "qısa", "C": "yarış", "D": "şəkər", "E": "səma"}'::jsonb, 'D', NULL, '«şəkər»: hecalar — şə-kər; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4859, 65, 'g10-aze-sound-q3-09', 3, 9, 'medium', 'single', 'Hansı sözdə 3 kar samit var və 1 açıq heca var?', NULL, NULL, '{"A": "gilas", "B": "həftə", "C": "səhra", "D": "yemiş", "E": "alça"}'::jsonb, 'B', NULL, '«həftə»: hecalar — həf-tə; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (0 cingiltili, 3 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4860, 65, 'g10-aze-sound-q3-10', 3, 10, 'hard', 'single', 'Hansı sözdə 1 kar samit var, söz samitlə başlayır və 1 dodaqlanan sait var?', NULL, NULL, '{"A": "şagirdlər", "B": "musiqi", "C": "sərin", "D": "saniyə", "E": "lampa"}'::jsonb, 'B', NULL, '«musiqi»: hecalar — mu-si-qi; saitlər — 3 (1 qalın, 2 incə, 1 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4861, 65, 'g10-aze-sound-q3-11', 3, 11, 'hard', 'single', '«yazıçı» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 4 samit (3 cingiltili, 1 kar), 1 sonor", "E": "4 heca (4 açıq, 0 qapalı); 4 sait (3 qalın, 1 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor"}'::jsonb, 'C', NULL, '«yazıçı» — hecalar: ya-zı-çı. 3 heca (3 açıq, 0 qapalı); 3 sait (3 qalın, 0 incə); 3 samit (2 cingiltili, 1 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4862, 65, 'g10-aze-sound-q3-12', 3, 12, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə kar samitlər cingiltili samitlərdən çoxdur, söz samitlə başlayır və bütün saitlər incədir?', NULL, NULL, '{"A": "həftə, süt, səbir", "B": "pendir, səhər, səs", "C": "dəmir, fikir, şüşə", "D": "həkim, kirpi, körpü", "E": "fəhlə, hədiyyə, təpə"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4863, 65, 'g10-aze-sound-q3-13', 3, 13, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 1 açıq heca var?', NULL, NULL, '{"A": "ka-ran-daş", "B": "pənc-ə-rə", "C": "o-yunç-u", "D": "kom-an-da", "E": "cəs-a-rət"}'::jsonb, 'A', NULL, 'Düzgün bölgü: ka-ran-daş. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (4864, 65, 'g10-aze-sound-q3-14', 3, 14, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə cingiltili samitlər kar samitlərdən çoxdur, kar samit yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "ayı, bal, göl", "B": "acı, gül, qum", "C": "narıncı, qalay, qırmızı", "D": "ada, dayı, yazıçı", "E": "canavar, qələm, yun"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4865, 65, 'g10-aze-sound-q3-15', 3, 15, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "qartal – qorxu", "B": "karandaş – oyunçu", "C": "sahil – tar", "D": "dost – geniş", "E": "durna – dəftər"}'::jsonb, 'E', NULL, '«durna»: dur-na; «dəftər»: dəf-tər. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4866, 65, 'g10-aze-sound-q3-16', 3, 16, 'hard', 'single', 'Hansı sözdə son heca qapalıdır, 3 sonor samit var və 4 cingiltili samit var?', NULL, NULL, '{"A": "qaranquş", "B": "mehriban", "C": "şagirdlər", "D": "meymun", "E": "bülbül"}'::jsonb, 'B', NULL, '«mehriban»: hecalar — meh-ri-ban; saitlər — 3 (1 qalın, 2 incə, 0 dodaqlanan); samitlər — 5 (4 cingiltili, 1 kar, 3 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4867, 65, 'g10-aze-sound-q3-17', 3, 17, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "həsrət – rəssam", "B": "ada – sinif", "C": "konsert – mavi", "D": "tarix – şəkər", "E": "bostan – şaftalı"}'::jsonb, 'C', NULL, '«konsert»: kon-sert; «mavi»: ma-vi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4868, 65, 'g10-aze-sound-q3-18', 3, 18, 'hard', 'single', '«səmimi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor", "D": "4 heca (4 açıq, 0 qapalı); 4 sait (1 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "E": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 4 samit (2 cingiltili, 2 kar), 2 sonor"}'::jsonb, 'B', NULL, '«səmimi» — hecalar: sə-mi-mi. 3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4869, 65, 'g10-aze-sound-q3-19', 3, 19, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə kar samit yoxdur, 1 açıq (geniş) sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "irəli, nar, yol", "B": "alma, bal, qoyun", "C": "dayı, durna, qapıçı", "D": "duman, narıncı, toy", "E": "dolu, oyun, qar"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4870, 65, 'g10-aze-sound-q3-20', 3, 20, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "bostan – qələbə", "B": "baba – dərə", "C": "həkim – qalay", "D": "top – çəmən", "E": "mis – qar"}'::jsonb, 'A', NULL, '«bostan»: bos-tan; «qələbə»: qə-lə-bə. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4871, 65, 'g10-aze-sound-q3-21', 3, 21, 'medium', 'single', 'Hansı sözdə 1 sonor samit var və cingiltili samitlər kar samitlərdən çoxdur?', NULL, NULL, '{"A": "alim", "B": "alma", "C": "ozan", "D": "nənə", "E": "həsrət"}'::jsonb, 'C', NULL, '«ozan»: hecalar — o-zan; saitlər — 2 (2 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4872, 65, 'g10-aze-sound-q3-22', 3, 22, 'hard', 'single', '«gəlin» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (3 cingiltili, 1 kar), 2 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 3 sonor"}'::jsonb, 'B', NULL, '«gəlin» — hecalar: gə-lin. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (3 cingiltili, 0 kar), 2 sonor.');
INSERT INTO public.questions VALUES (4873, 65, 'g10-aze-sound-q3-23', 3, 23, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "fikir – çinar", "B": "çoban – əmi", "C": "fikir – lampa", "D": "alça – üzüm", "E": "arı – süt"}'::jsonb, 'D', NULL, '«alça»: al-ça; «üzüm»: ü-züm. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4874, 65, 'g10-aze-sound-q3-24', 3, 24, 'medium', 'single', 'Hansı sözdə cingiltili samitlər kar samitlərdən çoxdur və söz samitlə başlayır?', NULL, NULL, '{"A": "fil", "B": "arı", "C": "dolu", "D": "ozan", "E": "şaftalı"}'::jsonb, 'C', NULL, '«dolu»: hecalar — do-lu; saitlər — 2 (2 qalın, 0 incə, 2 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4875, 65, 'g10-aze-sound-q3-25', 3, 25, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə cingiltili samitlər kar samitlərdən çoxdur, bütün saitlər qalındır və 2 açıq (geniş) sait var?', NULL, NULL, '{"A": "baba, boz, qara", "B": "acı, kaman, zaman", "C": "kədər, ozan, qartal", "D": "aslan, nahar, qalay", "E": "ana, kənar, yoldaş"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4876, 65, 'g10-aze-sound-q3-26', 3, 26, 'hard', 'single', 'Hansı sözdə 2 heca var, cingiltili samitlər kar samitlərdən çoxdur və bütün saitlər incədir?', NULL, NULL, '{"A": "gilas", "B": "həsrət", "C": "gündüz", "D": "bacı", "E": "dolma"}'::jsonb, 'C', NULL, '«gündüz»: hecalar — gün-düz; saitlər — 2 (0 qalın, 2 incə, 2 dodaqlanan); samitlər — 4 (4 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4877, 65, 'g10-aze-sound-q3-27', 3, 27, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 1 açıq heca var?', NULL, NULL, '{"A": "qa-ra-nquş", "B": "müh-ən-dis", "C": "cəs-a-rət", "D": "pən-cər-ə", "E": "sə-nət-kar"}'::jsonb, 'E', NULL, 'Düzgün bölgü: sə-nət-kar. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (4878, 65, 'g10-aze-sound-q3-28', 3, 28, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "dastan – əkinçi", "B": "dolma – körpü", "C": "ata – gil", "D": "kaman – qızıl", "E": "bostan – xətkeş"}'::jsonb, 'C', NULL, '«ata»: a-ta; «gil»: gil. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (4879, 65, 'g10-aze-sound-q3-29', 3, 29, 'hard', 'single', '«fəhlə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "D": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 4 samit (2 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'A', NULL, '«fəhlə» — hecalar: fəh-lə. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə); 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (4880, 65, 'g10-aze-sound-q3-30', 3, 30, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 heca var, həm qalın, həm də incə sait var və son heca qapalıdır?', NULL, NULL, '{"A": "limon, medal, yarış", "B": "meymun, nişan, səma", "C": "alim, dərin, çinar", "D": "hakim, kaman, xiyar", "E": "cəsur, divan, divar"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (4881, 66, 'g10-aze-orth-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin, «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yarımada dənizə uzanır. Sən də bu işdə iştirak et. Heç kim bu suala cavab vermədi.", "B": "Yarımada dənizə uzanır. Sən də bu işdə iştirak et. Heçkim bu suala cavab vermədi.", "C": "Yarımada dənizə uzanır. Səndə bu işdə iştirak et. Heç kim bu suala cavab vermədi.", "D": "Yarım ada dənizə uzanır. Sən də bu işdə iştirak et. Heçkim bu suala cavab vermədi.", "E": "Yarım ada dənizə uzanır. Sən də bu işdə iştirak et. Heç kim bu suala cavab vermədi."}'::jsonb, 'A', NULL, 'Düzgün: Yarımada dənizə uzanır. Sən də bu işdə iştirak et. Heç kim bu suala cavab vermədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4882, 66, 'g10-aze-orth-q1-02', 1, 2, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («heç» sözünün, «da/də» bağlayıcısının və ya şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Heç nə görmədim. Məndə sizinlə gedəcəyəm. Bu, əngözəl mənzərədir.", "B": "Heç nə görmədim. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "C": "Heç nə görmədim. Mən də sizinlə gedəcəyəm. Bu, əngözəl mənzərədir.", "D": "Heçnə görmədim. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "E": "Heç nə görmədim. Məndə sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir."}'::jsonb, 'B', NULL, 'Düzgün: Heç nə görmədim. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4883, 66, 'g10-aze-orth-q1-03', 1, 3, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2023-ci ildə 100-cü yerə çıxdıq.", "B": "Biz 2023-cü ildə 100-cü yerə çıxdıq.", "C": "Biz 2023-cü ildə 100-ci yerə çıxdıq.", "D": "Biz 2023-cü ildə 100-cı yerə çıxdıq.", "E": "Biz 2023-cu ildə 100-cü yerə çıxdıq."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2023-cü, 100-cü.');
INSERT INTO public.questions VALUES (4884, 66, 'g10-aze-orth-q1-04', 1, 4, 'hard', 'single', 'Tələffüzü [qaçtı] və [qonax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Qız gülümsəyib qaçtı və qonaqa əlini yellədi.", "B": "Qız gülümsəyib qaçdı və qonaxa əlini yellədi.", "C": "Qız gülümsəyib qaçdı və qonaqa əlini yellədi.", "D": "Qız gülümsəyib qaçtı və qonağa əlini yellədi.", "E": "Qız gülümsəyib qaçdı və qonağa əlini yellədi."}'::jsonb, 'E', NULL, '«qaçdı» — Kar samitdən sonra d t kimi tələffüz olunur, d yazılır; «qonaq» — Sonda q yazılır. Düzgün: Qız gülümsəyib qaçdı və qonağa əlini yellədi.');
INSERT INTO public.questions VALUES (4885, 66, 'g10-aze-orth-q1-05', 1, 5, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2026-cı ildə məktəbimizin 88-ci buraxılışı oldu.", "B": "2026-cı ildə məktəbimizin 88-cu buraxılışı oldu.", "C": "2026-cü ildə məktəbimizin 88-ci buraxılışı oldu.", "D": "2026-cı ildə məktəbimizin 88-cü buraxılışı oldu.", "E": "2026-cı ildə məktəbimizin 88-cı buraxılışı oldu."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 88-ci.');
INSERT INTO public.questions VALUES (4886, 66, 'g10-aze-orth-q1-06', 1, 6, 'hard', 'single', 'Tələffüzü [axsaxqal] və [hesap] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Axsaxqal hesabı nəvələrinə izah etdi.", "B": "Ağsaxqal hesabı nəvələrinə izah etdi.", "C": "Ağsaqqal hesapı nəvələrinə izah etdi.", "D": "Ağsaqqal hesabı nəvələrinə izah etdi.", "E": "Axsaqqal hesabı nəvələrinə izah etdi."}'::jsonb, 'D', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «hesab» — Sonda b yazılır. Düzgün: Ağsaqqal hesabı nəvələrinə izah etdi.');
INSERT INTO public.questions VALUES (4887, 66, 'g10-aze-orth-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «köynəyi» və «fikri» sözləri işlənmişdi.", "B": "Diktantda «şəkli» və «tankı» sözləri işlənmişdi.", "C": "Diktantda «dirəyi» və «bayrağı» sözləri işlənmişdi.", "D": "Diktantda «bankı» və «uşağı» sözləri işlənmişdi.", "E": "Diktantda «köynəyi» və «tankı» sözləri işlənmişdi."}'::jsonb, 'E', NULL, 'köynək → köynəyi (k→y), tank → tankı (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4888, 66, 'g10-aze-orth-q1-08', 1, 8, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Evdəki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi. Dediki, sabah gələcək.", "B": "Evdə ki hamı yatmışdı. Qızıl gül bağçanı bəzəyirdi. Dedi ki, sabah gələcək.", "C": "Evdəki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi. Dedi ki, sabah gələcək.", "D": "Evdəki hamı yatmışdı. Qızıl gül bağçanı bəzəyirdi. Dedi ki, sabah gələcək.", "E": "Evdə ki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi. Dedi ki, sabah gələcək."}'::jsonb, 'C', NULL, 'Düzgün: Evdəki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi. Dedi ki, sabah gələcək. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4889, 66, 'g10-aze-orth-q1-09', 1, 9, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «heç» sözünün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Dediki, sabah gələcək. Heçnə görmədim. Yarımada dənizə uzanır.", "B": "Dedi ki, sabah gələcək. Heç nə görmədim. Yarım ada dənizə uzanır.", "C": "Dediki, sabah gələcək. Heç nə görmədim. Yarımada dənizə uzanır.", "D": "Dedi ki, sabah gələcək. Heç nə görmədim. Yarımada dənizə uzanır.", "E": "Dedi ki, sabah gələcək. Heçnə görmədim. Yarımada dənizə uzanır."}'::jsonb, 'D', NULL, 'Düzgün: Dedi ki, sabah gələcək. Heç nə görmədim. Yarımada dənizə uzanır. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4890, 66, 'g10-aze-orth-q1-10', 1, 10, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1945-cü ildə 10-cu yerə çıxdıq.", "B": "Biz 1945-ci ildə 10-cü yerə çıxdıq.", "C": "Biz 1945-cı ildə 10-cu yerə çıxdıq.", "D": "Biz 1945-ci ildə 10-cu yerə çıxdıq.", "E": "Biz 1945-ci ildə 10-cı yerə çıxdıq."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1945-ci, 10-cu.');
INSERT INTO public.questions VALUES (4891, 66, 'g10-aze-orth-q1-11', 1, 11, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1937-ci ildə 100-cü dəfə sərgi açdı.", "B": "Muzey 1937-cu ildə 100-cü dəfə sərgi açdı.", "C": "Muzey 1937-cü ildə 100-cü dəfə sərgi açdı.", "D": "Muzey 1937-ci ildə 100-ci dəfə sərgi açdı.", "E": "Muzey 1937-cı ildə 100-cü dəfə sərgi açdı."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1937-ci, 100-cü.');
INSERT INTO public.questions VALUES (4892, 66, 'g10-aze-orth-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «qulağı» və «burunu» sözləri işlənmişdi.", "B": "Diktantda «bıçağı» və «ağızı» sözləri işlənmişdi.", "C": "Diktantda «ayağı» və «tankı» sözləri işlənmişdi.", "D": "Diktantda «ağzı» və «dənizi» sözləri işlənmişdi.", "E": "Diktantda «qulağı» və «burnu» sözləri işlənmişdi."}'::jsonb, 'E', NULL, 'qulaq → qulağı (q→ğ), burun → burnu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4893, 66, 'g10-aze-orth-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «ürəyi» və «isimi» sözlərini lövhəyə yazdı.", "B": "Şagird «ürəki» və «ismi» sözlərini lövhəyə yazdı.", "C": "Şagird «qarnı» və «şərqi» sözlərini lövhəyə yazdı.", "D": "Şagird «dirəki» və «burnu» sözlərini lövhəyə yazdı.", "E": "Şagird «dirəyi» və «burnu» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'dirək → dirəyi (k→y), burun → burnu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4894, 66, 'g10-aze-orth-q1-14', 1, 14, 'hard', 'single', 'Tələffüzü [təmbəl] və [məxtəp] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Bu təmbəl oğlan heç vaxt məktəbə getmir.", "B": "Bu tənbəl oğlan heç vaxt məktəpə getmir.", "C": "Bu tənbəl oğlan heç vaxt məxtəbə getmir.", "D": "Bu tənbəl oğlan heç vaxt məktəbə getmir.", "E": "Bu tənbəl oğlan heç vaxt məxtəpə getmir."}'::jsonb, 'D', NULL, '«tənbəl» — n yazılır; «məktəb» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: Bu tənbəl oğlan heç vaxt məktəbə getmir.');
INSERT INTO public.questions VALUES (4895, 66, 'g10-aze-orth-q1-15', 1, 15, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1828-ci ildə 100-ci dəfə sərgi açdı.", "B": "Muzey 1828-ci ildə 100-cü dəfə sərgi açdı.", "C": "Muzey 1828-cu ildə 100-cü dəfə sərgi açdı.", "D": "Muzey 1828-cı ildə 100-cü dəfə sərgi açdı.", "E": "Muzey 1828-ci ildə 100-cu dəfə sərgi açdı."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1828-ci, 100-cü.');
INSERT INTO public.questions VALUES (4896, 66, 'g10-aze-orth-q1-16', 1, 16, 'hard', 'single', 'Tələffüzü [doxquz] və [cavap] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Şagird doquz tapşırığın cavapını tapdı.", "B": "Şagird doxquz tapşırığın cavabını tapdı.", "C": "Şagird doqquz tapşırığın cavapını tapdı.", "D": "Şagird doqquz tapşırığın cavabını tapdı.", "E": "Şagird doquz tapşırığın cavabını tapdı."}'::jsonb, 'D', NULL, '«doqquz» — qq birləşməsində birinci q x kimi tələffüz olunur, qq yazılır; «cavab» — Sonda b yazılır. Düzgün: Şagird doqquz tapşırığın cavabını tapdı.');
INSERT INTO public.questions VALUES (4897, 66, 'g10-aze-orth-q1-17', 1, 17, 'hard', 'single', 'Tələffüzü [çərşəmbə] və [qonax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Çərşənbə günü qonağ gəldi.", "B": "Çərşəmbə günü qonax gəldi.", "C": "Çərşənbə günü qonaq gəldi.", "D": "Çərşəmbə günü qonaq gəldi.", "E": "Çərşənbə günü qonax gəldi."}'::jsonb, 'C', NULL, '«çərşənbə» — n yazılır; «qonaq» — Sonda q yazılır. Düzgün: Çərşənbə günü qonaq gəldi.');
INSERT INTO public.questions VALUES (4898, 66, 'g10-aze-orth-q1-18', 1, 18, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1990-cü ildə 79-cu yerə çıxdıq.", "B": "Biz 1990-cı ildə 79-cü yerə çıxdıq.", "C": "Biz 1990-cı ildə 79-cu yerə çıxdıq.", "D": "Biz 1990-cı ildə 79-cı yerə çıxdıq.", "E": "Biz 1990-cu ildə 79-cu yerə çıxdıq."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1990-cı, 79-cu.');
INSERT INTO public.questions VALUES (4899, 66, 'g10-aze-orth-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «şərqi» və «çiçəyi» sözləri işlənmişdi.", "B": "Diktantda «bıçağı» və «xalqı» sözləri işlənmişdi.", "C": "Diktantda «tankı» və «sinfi» sözləri işlənmişdi.", "D": "Diktantda «bayrağı» və «şəhəri» sözləri işlənmişdi.", "E": "Diktantda «çörəyi» və «uşağı» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'şərq → şərqi (dəyişmir), çiçək → çiçəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4900, 66, 'g10-aze-orth-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «köynəyi» və «bayraqı» sözləri işlənmişdi.", "B": "Diktantda «köynəyi» və «bayrağı» sözləri işlənmişdi.", "C": "Diktantda «bıçağı» və «şərqi» sözləri işlənmişdi.", "D": "Diktantda «hüququ» və «ürəyi» sözləri işlənmişdi.", "E": "Diktantda «uşağı» və «qəfəsi» sözləri işlənmişdi."}'::jsonb, 'B', NULL, 'köynək → köynəyi (k→y), bayraq → bayrağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4901, 66, 'g10-aze-orth-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «bıçağı», «ürəyi» sözlərini misal gətirdi.", "B": "Müəllim «uşaqı», «boynu» sözlərini misal gətirdi.", "C": "Müəllim «uşağı», «boynu» sözlərini misal gətirdi.", "D": "Müəllim «ürəyi», «burnu» sözlərini misal gətirdi.", "E": "Müəllim «uşaqı», «sinfi» sözlərini misal gətirdi."}'::jsonb, 'C', NULL, 'uşaq → uşağı (q→ğ), boyun → boynu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4902, 66, 'g10-aze-orth-q1-22', 1, 22, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, mürəkkəb sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə-gülə danışırdı. Qızıl gül bağçanı bəzəyirdi. Evdəki hamı yatmışdı.", "B": "Gülə-gülə danışırdı. Qızılgül bağçanı bəzəyirdi. Evdəki hamı yatmışdı.", "C": "Gülə gülə danışırdı. Qızıl gül bağçanı bəzəyirdi. Evdəki hamı yatmışdı.", "D": "Gülə-gülə danışırdı. Qızılgül bağçanı bəzəyirdi. Evdə ki hamı yatmışdı.", "E": "Gülə gülə danışırdı. Qızılgül bağçanı bəzəyirdi. Evdəki hamı yatmışdı."}'::jsonb, 'B', NULL, 'Düzgün: Gülə-gülə danışırdı. Qızılgül bağçanı bəzəyirdi. Evdəki hamı yatmışdı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4903, 66, 'g10-aze-orth-q1-23', 1, 23, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2003-cü ildə məktəbimizin 60-cı buraxılışı oldu.", "B": "2003-cu ildə məktəbimizin 60-cı buraxılışı oldu.", "C": "2003-cü ildə məktəbimizin 60-ci buraxılışı oldu.", "D": "2003-cı ildə məktəbimizin 60-cı buraxılışı oldu.", "E": "2003-cü ildə məktəbimizin 60-cü buraxılışı oldu."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2003-cü, 60-cı.');
INSERT INTO public.questions VALUES (4904, 66, 'g10-aze-orth-q1-24', 1, 24, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, qoşa sözün, «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Evdəki hamı yatmışdı. Ata-ana övladını qoruyar. Heçnə görmədim.", "B": "Evdə ki hamı yatmışdı. Ataana övladını qoruyar. Heç nə görmədim.", "C": "Evdəki hamı yatmışdı. Ata-ana övladını qoruyar. Heç nə görmədim.", "D": "Evdə ki hamı yatmışdı. Ata-ana övladını qoruyar. Heç nə görmədim.", "E": "Evdəki hamı yatmışdı. Ataana övladını qoruyar. Heç nə görmədim."}'::jsonb, 'C', NULL, 'Düzgün: Evdəki hamı yatmışdı. Ata-ana övladını qoruyar. Heç nə görmədim. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4905, 66, 'g10-aze-orth-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «çörəyi» və «ittifaqı» sözlərini lövhəyə yazdı.", "B": "Şagird «tankı» və «bıçağı» sözlərini lövhəyə yazdı.", "C": "Şagird «ömrü» və «xalqı» sözlərini lövhəyə yazdı.", "D": "Şagird «alnı» və «dənizi» sözlərini lövhəyə yazdı.", "E": "Şagird «çörəki» və «ittifağı» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'çörək → çörəyi (k→y), ittifaq → ittifaqı (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4906, 66, 'g10-aze-orth-q1-26', 1, 26, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Arasıra bizə baş çəkir. Ağsaqqal söz aldı. Sən də bu işdə iştirak et.", "B": "Arasıra bizə baş çəkir. Ağ saqqal söz aldı. Sən də bu işdə iştirak et.", "C": "Ara-sıra bizə baş çəkir. Ağsaqqal söz aldı. Səndə bu işdə iştirak et.", "D": "Ara-sıra bizə baş çəkir. Ağ saqqal söz aldı. Sən də bu işdə iştirak et.", "E": "Ara-sıra bizə baş çəkir. Ağsaqqal söz aldı. Sən də bu işdə iştirak et."}'::jsonb, 'E', NULL, 'Düzgün: Ara-sıra bizə baş çəkir. Ağsaqqal söz aldı. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4907, 66, 'g10-aze-orth-q1-27', 1, 27, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "1991-cu ildə məktəbimizin 70-ci buraxılışı oldu.", "B": "1991-ci ildə məktəbimizin 70-cu buraxılışı oldu.", "C": "1991-ci ildə məktəbimizin 70-cı buraxılışı oldu.", "D": "1991-cü ildə məktəbimizin 70-ci buraxılışı oldu.", "E": "1991-ci ildə məktəbimizin 70-ci buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1991-ci, 70-ci.');
INSERT INTO public.questions VALUES (4908, 66, 'g10-aze-orth-q1-28', 1, 28, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Məndə sizinlə gedəcəyəm. Dediki, sabah gələcək. Sən də bu işdə iştirak et.", "B": "Mən də sizinlə gedəcəyəm. Dediki, sabah gələcək. Sən də bu işdə iştirak et.", "C": "Məndə sizinlə gedəcəyəm. Dedi ki, sabah gələcək. Sən də bu işdə iştirak et.", "D": "Mən də sizinlə gedəcəyəm. Dedi ki, sabah gələcək. Sən də bu işdə iştirak et.", "E": "Mən də sizinlə gedəcəyəm. Dedi ki, sabah gələcək. Səndə bu işdə iştirak et."}'::jsonb, 'D', NULL, 'Düzgün: Mən də sizinlə gedəcəyəm. Dedi ki, sabah gələcək. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4909, 66, 'g10-aze-orth-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «ayağı» və «şəhəri» sözlərini lövhəyə yazdı.", "B": "Şagird «şəhəri» və «ömrü» sözlərini lövhəyə yazdı.", "C": "Şagird «dirəyi» və «şərqi» sözlərini lövhəyə yazdı.", "D": "Şagird «şəkli» və «dənizi» sözlərini lövhəyə yazdı.", "E": "Şagird «dirəki» və «şərği» sözlərini lövhəyə yazdı."}'::jsonb, 'C', NULL, 'dirək → dirəyi (k→y), şərq → şərqi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4910, 66, 'g10-aze-orth-q1-30', 1, 30, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2023-cü ildə 20-cu yerə çıxdıq.", "B": "Biz 2023-ci ildə 20-ci yerə çıxdıq.", "C": "Biz 2023-cı ildə 20-ci yerə çıxdıq.", "D": "Biz 2023-cü ildə 20-cı yerə çıxdıq.", "E": "Biz 2023-cü ildə 20-ci yerə çıxdıq."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2023-cü, 20-ci.');
INSERT INTO public.questions VALUES (4911, 66, 'g10-aze-orth-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «ağzı», «qəfəsi» sözlərini misal gətirdi.", "B": "Müəllim «nitqi», «qulağı» sözlərini misal gətirdi.", "C": "Müəllim «könlü», «bayrağı» sözlərini misal gətirdi.", "D": "Müəllim «nitği», «qulağı» sözlərini misal gətirdi.", "E": "Müəllim «dənizi», «şəkli» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'nitq → nitqi (dəyişmir), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4912, 66, 'g10-aze-orth-q2-02', 2, 2, 'hard', 'single', 'Tələffüzü [ürəy''] və [məxtup] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "O, ürəkdən gələn sözləri məktubda yazdı.", "B": "O, ürəkdən gələn sözləri məxtupda yazdı.", "C": "O, ürəkdən gələn sözləri məxtubda yazdı.", "D": "O, ürəydən gələn sözləri məktubda yazdı.", "E": "O, ürəqdən gələn sözləri məktubda yazdı."}'::jsonb, 'A', NULL, '«ürək» — Sonda k yazılır; «məktub» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: O, ürəkdən gələn sözləri məktubda yazdı.');
INSERT INTO public.questions VALUES (4913, 66, 'g10-aze-orth-q2-03', 2, 3, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, sual ədatının (-mı, -mi) yazılışına diqqət edin)?', NULL, NULL, '{"A": "Dedi ki, sabah gələcək. Onlar artıq gəldilər mi? Bilirəm ki, sən haqlısan.", "B": "Dedi ki, sabah gələcək. Onlar artıq gəldilər mi? Bilirəmki, sən haqlısan.", "C": "Dedi ki, sabah gələcək. Onlar artıq gəldilərmi? Bilirəmki, sən haqlısan.", "D": "Dediki, sabah gələcək. Onlar artıq gəldilərmi? Bilirəm ki, sən haqlısan.", "E": "Dedi ki, sabah gələcək. Onlar artıq gəldilərmi? Bilirəm ki, sən haqlısan."}'::jsonb, 'E', NULL, 'Düzgün: Dedi ki, sabah gələcək. Onlar artıq gəldilərmi? Bilirəm ki, sən haqlısan. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4914, 66, 'g10-aze-orth-q2-04', 2, 4, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2003-ci ildə məktəbimizin 64-cü buraxılışı oldu.", "B": "2003-cü ildə məktəbimizin 64-ci buraxılışı oldu.", "C": "2003-cu ildə məktəbimizin 64-cü buraxılışı oldu.", "D": "2003-cü ildə məktəbimizin 64-cu buraxılışı oldu.", "E": "2003-cü ildə məktəbimizin 64-cü buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2003-cü, 64-cü.');
INSERT INTO public.questions VALUES (4915, 66, 'g10-aze-orth-q2-05', 2, 5, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə-gülə danışırdı. Ayaq qabılarını təmizlədi. Kitab evdə qalıb.", "B": "Gülə gülə danışırdı. Ayaq qabılarını təmizlədi. Kitab evdə qalıb.", "C": "Gülə-gülə danışırdı. Ayaqqabılarını təmizlədi. Kitab evdə qalıb.", "D": "Gülə-gülə danışırdı. Ayaqqabılarını təmizlədi. Kitab ev də qalıb.", "E": "Gülə gülə danışırdı. Ayaqqabılarını təmizlədi. Kitab evdə qalıb."}'::jsonb, 'C', NULL, 'Düzgün: Gülə-gülə danışırdı. Ayaqqabılarını təmizlədi. Kitab evdə qalıb. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4916, 66, 'g10-aze-orth-q2-06', 2, 6, 'hard', 'single', 'Tələffüzü [axsaxqal] və [saxqal] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Ağsaqqal uzun saxqalını sığallayırdı.", "B": "Axsaqqal uzun saqqalını sığallayırdı.", "C": "Ağsaqqal uzun saqalını sığallayırdı.", "D": "Ağsaqal uzun saqqalını sığallayırdı.", "E": "Ağsaqqal uzun saqqalını sığallayırdı."}'::jsonb, 'E', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «saqqal» — qq yazılır. Düzgün: Ağsaqqal uzun saqqalını sığallayırdı.');
INSERT INTO public.questions VALUES (4917, 66, 'g10-aze-orth-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «inəyi» və «qəfəsi» sözlərini lövhəyə yazdı.", "B": "Şagird «inəyi» və «qəfsi» sözlərini lövhəyə yazdı.", "C": "Şagird «bayrağı» və «çörəyi» sözlərini lövhəyə yazdı.", "D": "Şagird «inəki» və «qəfəsi» sözlərini lövhəyə yazdı.", "E": "Şagird «ürəki» və «parğı» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'inək → inəyi (k→y), qəfəs → qəfəsi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4918, 66, 'g10-aze-orth-q2-08', 2, 8, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşım da, bacım da gəldi. Ağsaqqal söz aldı. Günə baxan günəşə tərəf dönür.", "B": "Qardaşımda, bacımda gəldi. Ağsaqqal söz aldı. Günə baxan günəşə tərəf dönür.", "C": "Qardaşım da, bacım da gəldi. Ağ saqqal söz aldı. Günəbaxan günəşə tərəf dönür.", "D": "Qardaşım da, bacım da gəldi. Ağsaqqal söz aldı. Günəbaxan günəşə tərəf dönür.", "E": "Qardaşımda, bacımda gəldi. Ağsaqqal söz aldı. Günəbaxan günəşə tərəf dönür."}'::jsonb, 'D', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Ağsaqqal söz aldı. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4919, 66, 'g10-aze-orth-q2-09', 2, 9, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1991-cı ildə 3-cü dəfə sərgi açdı.", "B": "Muzey 1991-ci ildə 3-cü dəfə sərgi açdı.", "C": "Muzey 1991-cü ildə 3-cü dəfə sərgi açdı.", "D": "Muzey 1991-cu ildə 3-cü dəfə sərgi açdı.", "E": "Muzey 1991-ci ildə 3-ci dəfə sərgi açdı."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1991-ci, 3-cü.');
INSERT INTO public.questions VALUES (4920, 66, 'g10-aze-orth-q2-10', 2, 10, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Kitab evdə qalıb. Yavaş-yavaş irəlilədik. Qardaşımda, bacımda gəldi.", "B": "Kitab evdə qalıb. Yavaş yavaş irəlilədik. Qardaşım da, bacım da gəldi.", "C": "Kitab ev də qalıb. Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi.", "D": "Kitab evdə qalıb. Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi.", "E": "Kitab ev də qalıb. Yavaş yavaş irəlilədik. Qardaşım da, bacım da gəldi."}'::jsonb, 'D', NULL, 'Düzgün: Kitab evdə qalıb. Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4921, 66, 'g10-aze-orth-q2-11', 2, 11, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yarım ada dənizə uzanır. Ayaqqabılarını təmizlədi. Heçnə görmədim.", "B": "Yarımada dənizə uzanır. Ayaqqabılarını təmizlədi. Heçnə görmədim.", "C": "Yarım ada dənizə uzanır. Ayaqqabılarını təmizlədi. Heç nə görmədim.", "D": "Yarımada dənizə uzanır. Ayaq qabılarını təmizlədi. Heç nə görmədim.", "E": "Yarımada dənizə uzanır. Ayaqqabılarını təmizlədi. Heç nə görmədim."}'::jsonb, 'E', NULL, 'Düzgün: Yarımada dənizə uzanır. Ayaqqabılarını təmizlədi. Heç nə görmədim. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4922, 66, 'g10-aze-orth-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «parkı», «bayrağı» sözlərini misal gətirdi.", "B": "Müəllim «ağzı», «xalqı» sözlərini misal gətirdi.", "C": "Müəllim «fərqi», «boynu» sözlərini misal gətirdi.", "D": "Müəllim «parğı», «bayrağı» sözlərini misal gətirdi.", "E": "Müəllim «parkı», «bayraqı» sözlərini misal gətirdi."}'::jsonb, 'A', NULL, 'park → parkı (dəyişmir), bayraq → bayrağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4923, 66, 'g10-aze-orth-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «inəyi» və «burnu» sözlərini lövhəyə yazdı.", "B": "Şagird «ürəki» və «bayraqı» sözlərini lövhəyə yazdı.", "C": "Şagird «çörəyi» və «bıçaqı» sözlərini lövhəyə yazdı.", "D": "Şagird «dirəyi» və «burnu» sözlərini lövhəyə yazdı.", "E": "Şagird «çörəyi» və «bıçağı» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'çörək → çörəyi (k→y), bıçaq → bıçağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4924, 66, 'g10-aze-orth-q2-14', 2, 14, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1990-cı ildə 90-cu yerə çıxdıq.", "B": "Biz 1990-cı ildə 90-ci yerə çıxdıq.", "C": "Biz 1990-cü ildə 90-cı yerə çıxdıq.", "D": "Biz 1990-cı ildə 90-cı yerə çıxdıq.", "E": "Biz 1990-cı ildə 90-cü yerə çıxdıq."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1990-cı, 90-cı.');
INSERT INTO public.questions VALUES (4925, 66, 'g10-aze-orth-q2-15', 2, 15, 'hard', 'single', 'Tələffüzü [yarpaxlar] və [torpax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Payızda yarpaqlar torpağı örtmüşdü.", "B": "Payızda yarpaxlar torpaxı örtmüşdü.", "C": "Payızda yarpaxlar torpağı örtmüşdü.", "D": "Payızda yarpaqlar torpaxı örtmüşdü.", "E": "Payızda yarpaqlar torpaqı örtmüşdü."}'::jsonb, 'A', NULL, '«yarpaqlar» — q yazılır; «torpaq» — Sonda q yazılır. Düzgün: Payızda yarpaqlar torpağı örtmüşdü.');
INSERT INTO public.questions VALUES (4926, 66, 'g10-aze-orth-q2-16', 2, 16, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 1996-ci ildə 64-cü yerə çıxdıq.", "B": "Biz 1996-cü ildə 64-cü yerə çıxdıq.", "C": "Biz 1996-cı ildə 64-cü yerə çıxdıq.", "D": "Biz 1996-cı ildə 64-ci yerə çıxdıq.", "E": "Biz 1996-cı ildə 64-cu yerə çıxdıq."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1996-cı, 64-cü.');
INSERT INTO public.questions VALUES (4927, 66, 'g10-aze-orth-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «şəkli» və «dirəyi» sözlərini lövhəyə yazdı.", "B": "Şagird «ağzı» və «bıçağı» sözlərini lövhəyə yazdı.", "C": "Şagird «köynəyi» və «bayrağı» sözlərini lövhəyə yazdı.", "D": "Şagird «nitqi» və «alnı» sözlərini lövhəyə yazdı.", "E": "Şagird «şəkili» və «dirəki» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'şəkil → şəkli (sait düşümü), dirək → dirəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4928, 66, 'g10-aze-orth-q2-18', 2, 18, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1918-ci ildə 40-cü dəfə sərgi açdı.", "B": "Muzey 1918-cü ildə 40-cı dəfə sərgi açdı.", "C": "Muzey 1918-ci ildə 40-ci dəfə sərgi açdı.", "D": "Muzey 1918-ci ildə 40-cu dəfə sərgi açdı.", "E": "Muzey 1918-ci ildə 40-cı dəfə sərgi açdı."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1918-ci, 40-cı.');
INSERT INTO public.questions VALUES (4929, 66, 'g10-aze-orth-q2-19', 2, 19, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "1945-cı ildə məktəbimizin 6-cı buraxılışı oldu.", "B": "1945-ci ildə məktəbimizin 6-cı buraxılışı oldu.", "C": "1945-cü ildə məktəbimizin 6-cı buraxılışı oldu.", "D": "1945-ci ildə məktəbimizin 6-cu buraxılışı oldu.", "E": "1945-ci ildə məktəbimizin 6-cü buraxılışı oldu."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1945-ci, 6-cı.');
INSERT INTO public.questions VALUES (4930, 66, 'g10-aze-orth-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «uşağı», «parkı» sözlərini misal gətirdi.", "B": "Müəllim «fərqi», «fikri» sözlərini misal gətirdi.", "C": "Müəllim «çiçəyi», «şəkli» sözlərini misal gətirdi.", "D": "Müəllim «ayağı», «nitqi» sözlərini misal gətirdi.", "E": "Müəllim «çiçəyi», «şəhəri» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'fərq → fərqi (dəyişmir), fikir → fikri (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4931, 66, 'g10-aze-orth-q2-21', 2, 21, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Evdə ki hamı yatmışdı. Masadakı kitab mənimdir. Ayaqqabılarını təmizlədi.", "B": "Evdəki hamı yatmışdı. Masadakı kitab mənimdir. Ayaq qabılarını təmizlədi.", "C": "Evdə ki hamı yatmışdı. Masadakı kitab mənimdir. Ayaq qabılarını təmizlədi.", "D": "Evdəki hamı yatmışdı. Masada ki kitab mənimdir. Ayaqqabılarını təmizlədi.", "E": "Evdəki hamı yatmışdı. Masadakı kitab mənimdir. Ayaqqabılarını təmizlədi."}'::jsonb, 'E', NULL, 'Düzgün: Evdəki hamı yatmışdı. Masadakı kitab mənimdir. Ayaqqabılarını təmizlədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4932, 66, 'g10-aze-orth-q2-22', 2, 22, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ən» ədatının, mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bu, ən gözəl mənzərədir. Qızılgül bağçanı bəzəyirdi. Sən də bu işdə iştirak et.", "B": "Bu, əngözəl mənzərədir. Qızılgül bağçanı bəzəyirdi. Sən də bu işdə iştirak et.", "C": "Bu, əngözəl mənzərədir. Qızıl gül bağçanı bəzəyirdi. Sən də bu işdə iştirak et.", "D": "Bu, ən gözəl mənzərədir. Qızıl gül bağçanı bəzəyirdi. Sən də bu işdə iştirak et.", "E": "Bu, ən gözəl mənzərədir. Qızılgül bağçanı bəzəyirdi. Səndə bu işdə iştirak et."}'::jsonb, 'A', NULL, 'Düzgün: Bu, ən gözəl mənzərədir. Qızılgül bağçanı bəzəyirdi. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4933, 66, 'g10-aze-orth-q2-23', 2, 23, 'hard', 'single', 'Tələffüzü [torpax] və [sümbül] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Kəndli torpaqdan sünbülləri yığdı.", "B": "Kəndli torpaxdan sümbülləri yığdı.", "C": "Kəndli torpaxdan sünbülləri yığdı.", "D": "Kəndli torpaqdan sümbülləri yığdı.", "E": "Kəndli torpağdan sünbülləri yığdı."}'::jsonb, 'A', NULL, '«torpaq» — Sonda q yazılır; «sünbül» — n b-dən əvvəl m kimi tələffüz olunur, n yazılır. Düzgün: Kəndli torpaqdan sünbülləri yığdı.');
INSERT INTO public.questions VALUES (4934, 66, 'g10-aze-orth-q2-24', 2, 24, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2010-cı ildə məktəbimizin 80-ci buraxılışı oldu.", "B": "2010-cu ildə məktəbimizin 80-cu buraxılışı oldu.", "C": "2010-ci ildə məktəbimizin 80-ci buraxılışı oldu.", "D": "2010-cu ildə məktəbimizin 80-ci buraxılışı oldu.", "E": "2010-cu ildə məktəbimizin 80-cü buraxılışı oldu."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2010-cu, 80-ci.');
INSERT INTO public.questions VALUES (4935, 66, 'g10-aze-orth-q2-25', 2, 25, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. Məndə sizinlə gedəcəyəm.", "B": "Qızıl gül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. Məndə sizinlə gedəcəyəm.", "C": "Qızıl gül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm.", "D": "Qızılgül bağçanı bəzəyirdi. Qardaşımda, bacımda gəldi. Mən də sizinlə gedəcəyəm.", "E": "Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm."}'::jsonb, 'E', NULL, 'Düzgün: Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4936, 66, 'g10-aze-orth-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «boynu» və «parkı» sözlərini lövhəyə yazdı.", "B": "Şagird «oğlu» və «parğı» sözlərini lövhəyə yazdı.", "C": "Şagird «parkı» və «bıçağı» sözlərini lövhəyə yazdı.", "D": "Şagird «sinfi» və «bıçağı» sözlərini lövhəyə yazdı.", "E": "Şagird «tankı» və «inəyi» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'boyun → boynu (sait düşümü), park → parkı (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4937, 66, 'g10-aze-orth-q2-27', 2, 27, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Sən bu kitabı oxudun mu? Evdəki hamı yatmışdı. Bilirəm ki, sən haqlısan.", "B": "Sən bu kitabı oxudunmu? Evdə ki hamı yatmışdı. Bilirəm ki, sən haqlısan.", "C": "Sən bu kitabı oxudun mu? Evdə ki hamı yatmışdı. Bilirəm ki, sən haqlısan.", "D": "Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Bilirəmki, sən haqlısan.", "E": "Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Bilirəm ki, sən haqlısan."}'::jsonb, 'E', NULL, 'Düzgün: Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Bilirəm ki, sən haqlısan. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4938, 66, 'g10-aze-orth-q2-28', 2, 28, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2014-ci ildə 7-ci yerə çıxdıq.", "B": "Biz 2014-cu ildə 7-ci yerə çıxdıq.", "C": "Biz 2014-cı ildə 7-ci yerə çıxdıq.", "D": "Biz 2014-cü ildə 7-cu yerə çıxdıq.", "E": "Biz 2014-cü ildə 7-ci yerə çıxdıq."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2014-cü, 7-ci.');
INSERT INTO public.questions VALUES (4939, 66, 'g10-aze-orth-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «bıçaqı» və «parkı» sözlərini lövhəyə yazdı.", "B": "Şagird «qəfəsi» və «bayrağı» sözlərini lövhəyə yazdı.", "C": "Şagird «inəyi» və «xalqı» sözlərini lövhəyə yazdı.", "D": "Şagird «qəfsi» və «bayraqı» sözlərini lövhəyə yazdı.", "E": "Şagird «inəyi» və «bayrağı» sözlərini lövhəyə yazdı."}'::jsonb, 'B', NULL, 'qəfəs → qəfəsi (dəyişmir), bayraq → bayrağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4940, 66, 'g10-aze-orth-q2-30', 2, 30, 'hard', 'single', 'Tələffüzü [uşax] və [ayaxqabı] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Uşaq yeni ayaxqabı geyib həyətə çıxdı.", "B": "Uşağ yeni ayaqqabı geyib həyətə çıxdı.", "C": "Uşax yeni ayaqqabı geyib həyətə çıxdı.", "D": "Uşaq yeni ayaqqabı geyib həyətə çıxdı.", "E": "Uşaq yeni ayaqabı geyib həyətə çıxdı."}'::jsonb, 'D', NULL, '«uşaq» — Sonda q yazılır; «ayaqqabı» — qq yazılır. Düzgün: Uşaq yeni ayaqqabı geyib həyətə çıxdı.');
INSERT INTO public.questions VALUES (4941, 66, 'g10-aze-orth-q3-01', 3, 1, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2026-cü ildə məktəbimizin 64-cü buraxılışı oldu.", "B": "2026-ci ildə məktəbimizin 64-cü buraxılışı oldu.", "C": "2026-cı ildə məktəbimizin 64-cu buraxılışı oldu.", "D": "2026-cı ildə məktəbimizin 64-cü buraxılışı oldu.", "E": "2026-cı ildə məktəbimizin 64-ci buraxılışı oldu."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2026-cı, 64-cü.');
INSERT INTO public.questions VALUES (4942, 66, 'g10-aze-orth-q3-02', 3, 2, 'hard', 'single', 'Tələffüzü [ürəy''] və [məxtup] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "O, ürəkdən gələn sözləri məktupda yazdı.", "B": "O, ürəqdən gələn sözləri məktubda yazdı.", "C": "O, ürəydən gələn sözləri məktubda yazdı.", "D": "O, ürəkdən gələn sözləri məktubda yazdı.", "E": "O, ürəkdən gələn sözləri məxtupda yazdı."}'::jsonb, 'D', NULL, '«ürək» — Sonda k yazılır; «məktub» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: O, ürəkdən gələn sözləri məktubda yazdı.');
INSERT INTO public.questions VALUES (4943, 66, 'g10-aze-orth-q3-03', 3, 3, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Səndə bu işdə iştirak et. Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir.", "B": "Sən də bu işdə iştirak et. Ataana övladını qoruyar. Arasıra bizə baş çəkir.", "C": "Sən də bu işdə iştirak et. Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir.", "D": "Sən də bu işdə iştirak et. Ata-ana övladını qoruyar. Arasıra bizə baş çəkir.", "E": "Sən də bu işdə iştirak et. Ataana övladını qoruyar. Ara-sıra bizə baş çəkir."}'::jsonb, 'C', NULL, 'Düzgün: Sən də bu işdə iştirak et. Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4944, 66, 'g10-aze-orth-q3-04', 3, 4, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2010-cu ildə məktəbimizin 50-ci buraxılışı oldu.", "B": "2010-cu ildə məktəbimizin 50-cı buraxılışı oldu.", "C": "2010-cı ildə məktəbimizin 50-ci buraxılışı oldu.", "D": "2010-cü ildə məktəbimizin 50-ci buraxılışı oldu.", "E": "2010-ci ildə məktəbimizin 50-ci buraxılışı oldu."}'::jsonb, 'A', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2010-cu, 50-ci.');
INSERT INTO public.questions VALUES (4945, 66, 'g10-aze-orth-q3-05', 3, 5, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «da/də» bağlayıcısının və ya şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Masadakı kitab mənimdir. Məndə sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "B": "Masadakı kitab mənimdir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "C": "Masadakı kitab mənimdir. Mən də sizinlə gedəcəyəm. Bu, əngözəl mənzərədir.", "D": "Masada ki kitab mənimdir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "E": "Masada ki kitab mənimdir. Mən də sizinlə gedəcəyəm. Bu, əngözəl mənzərədir."}'::jsonb, 'B', NULL, 'Düzgün: Masadakı kitab mənimdir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4946, 66, 'g10-aze-orth-q3-06', 3, 6, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2020-ci ildə 30-cı yerə çıxdıq.", "B": "Biz 2020-ci ildə 30-cu yerə çıxdıq.", "C": "Biz 2020-ci ildə 30-cü yerə çıxdıq.", "D": "Biz 2020-cı ildə 30-cu yerə çıxdıq.", "E": "Biz 2020-cü ildə 30-cu yerə çıxdıq."}'::jsonb, 'B', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2020-ci, 30-cu.');
INSERT INTO public.questions VALUES (4947, 66, 'g10-aze-orth-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «ayağı» və «dirəyi» sözlərini lövhəyə yazdı.", "B": "Şagird «qulağı» və «ağzı» sözlərini lövhəyə yazdı.", "C": "Şagird «tankı» və «bıçağı» sözlərini lövhəyə yazdı.", "D": "Şagird «ayaqı» və «dirəyi» sözlərini lövhəyə yazdı.", "E": "Şagird «qulağı» və «dənizi» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'ayaq → ayağı (q→ğ), dirək → dirəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4948, 66, 'g10-aze-orth-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «dirəki», «boyunu» sözlərini misal gətirdi.", "B": "Müəllim «dirəki», «ağzı» sözlərini misal gətirdi.", "C": "Müəllim «dirəyi», «ağızı» sözlərini misal gətirdi.", "D": "Müəllim «dirəyi», «boynu» sözlərini misal gətirdi.", "E": "Müəllim «qəfəsi», «ürəyi» sözlərini misal gətirdi."}'::jsonb, 'D', NULL, 'dirək → dirəyi (k→y), boyun → boynu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4949, 66, 'g10-aze-orth-q3-09', 3, 9, 'hard', 'single', 'Tələffüzü [çərşəmbə] və [qonax] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Çərşənbə günü qonaq gəldi.", "B": "Çərşəmbə günü qonağ gəldi.", "C": "Çərşənbə günü qonax gəldi.", "D": "Çərşəmbə günü qonaq gəldi.", "E": "Çərşənbə günü qonağ gəldi."}'::jsonb, 'A', NULL, '«çərşənbə» — n yazılır; «qonaq» — Sonda q yazılır. Düzgün: Çərşənbə günü qonaq gəldi.');
INSERT INTO public.questions VALUES (4950, 66, 'g10-aze-orth-q3-10', 3, 10, 'hard', 'single', 'Tələffüzü [ürəy''] və [məxtup] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "O, ürəkdən gələn sözləri məxtubda yazdı.", "B": "O, ürəkdən gələn sözləri məktupda yazdı.", "C": "O, ürəkdən gələn sözləri məxtupda yazdı.", "D": "O, ürəkdən gələn sözləri məktubda yazdı.", "E": "O, ürəydən gələn sözləri məktubda yazdı."}'::jsonb, 'D', NULL, '«ürək» — Sonda k yazılır; «məktub» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: O, ürəkdən gələn sözləri məktubda yazdı.');
INSERT INTO public.questions VALUES (4951, 66, 'g10-aze-orth-q3-11', 3, 11, 'hard', 'single', 'Tələffüzü [torpax] və [sümbül] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Kəndli torpağdan sümbülləri yığdı.", "B": "Kəndli torpağdan sünbülləri yığdı.", "C": "Kəndli torpaxdan sünbülləri yığdı.", "D": "Kəndli torpaqdan sünbülləri yığdı.", "E": "Kəndli torpaqdan sümbülləri yığdı."}'::jsonb, 'D', NULL, '«torpaq» — Sonda q yazılır; «sünbül» — n b-dən əvvəl m kimi tələffüz olunur, n yazılır. Düzgün: Kəndli torpaqdan sünbülləri yığdı.');
INSERT INTO public.questions VALUES (4952, 66, 'g10-aze-orth-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «qarnı», «şəhəri» sözlərini misal gətirdi.", "B": "Müəllim «şərqi», «çörəyi» sözlərini misal gətirdi.", "C": "Müəllim «şərqi», «çörəki» sözlərini misal gətirdi.", "D": "Müəllim «qulağı», «dənizi» sözlərini misal gətirdi.", "E": "Müəllim «tanğı», «inəki» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'şərq → şərqi (dəyişmir), çörək → çörəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4953, 66, 'g10-aze-orth-q3-13', 3, 13, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Muzey 1828-ci ildə 90-cu dəfə sərgi açdı.", "B": "Muzey 1828-cu ildə 90-cı dəfə sərgi açdı.", "C": "Muzey 1828-cı ildə 90-cı dəfə sərgi açdı.", "D": "Muzey 1828-ci ildə 90-cı dəfə sərgi açdı.", "E": "Muzey 1828-cü ildə 90-cı dəfə sərgi açdı."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1828-ci, 90-cı.');
INSERT INTO public.questions VALUES (4954, 66, 'g10-aze-orth-q3-14', 3, 14, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "Biz 2010-cü ildə 40-cı yerə çıxdıq.", "B": "Biz 2010-ci ildə 40-cı yerə çıxdıq.", "C": "Biz 2010-cu ildə 40-cu yerə çıxdıq.", "D": "Biz 2010-cu ildə 40-cı yerə çıxdıq.", "E": "Biz 2010-cu ildə 40-ci yerə çıxdıq."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2010-cu, 40-cı.');
INSERT INTO public.questions VALUES (4955, 66, 'g10-aze-orth-q3-15', 3, 15, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2020-ci ildə məktəbimizin 64-cu buraxılışı oldu.", "B": "2020-ci ildə məktəbimizin 64-cı buraxılışı oldu.", "C": "2020-cı ildə məktəbimizin 64-cü buraxılışı oldu.", "D": "2020-cu ildə məktəbimizin 64-cü buraxılışı oldu.", "E": "2020-ci ildə məktəbimizin 64-cü buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2020-ci, 64-cü.');
INSERT INTO public.questions VALUES (4956, 66, 'g10-aze-orth-q3-16', 3, 16, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "1918-ci ildə məktəbimizin 50-cu buraxılışı oldu.", "B": "1918-cü ildə məktəbimizin 50-ci buraxılışı oldu.", "C": "1918-cı ildə məktəbimizin 50-ci buraxılışı oldu.", "D": "1918-cu ildə məktəbimizin 50-ci buraxılışı oldu.", "E": "1918-ci ildə məktəbimizin 50-ci buraxılışı oldu."}'::jsonb, 'E', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 1918-ci, 50-ci.');
INSERT INTO public.questions VALUES (4957, 66, 'g10-aze-orth-q3-17', 3, 17, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2005-cü ildə məktəbimizin 100-cü buraxılışı oldu.", "B": "2005-cı ildə məktəbimizin 100-cü buraxılışı oldu.", "C": "2005-ci ildə məktəbimizin 100-cü buraxılışı oldu.", "D": "2005-ci ildə məktəbimizin 100-cı buraxılışı oldu.", "E": "2005-ci ildə məktəbimizin 100-cu buraxılışı oldu."}'::jsonb, 'C', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2005-ci, 100-cü.');
INSERT INTO public.questions VALUES (4958, 66, 'g10-aze-orth-q3-18', 3, 18, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ən» ədatının, qoşa sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bu, əngözəl mənzərədir. Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi.", "B": "Bu, əngözəl mənzərədir. Yavaş yavaş irəlilədik. Qardaşım da, bacım da gəldi.", "C": "Bu, ən gözəl mənzərədir. Yavaş-yavaş irəlilədik. Qardaşımda, bacımda gəldi.", "D": "Bu, ən gözəl mənzərədir. Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi.", "E": "Bu, ən gözəl mənzərədir. Yavaş yavaş irəlilədik. Qardaşım da, bacım da gəldi."}'::jsonb, 'D', NULL, 'Düzgün: Bu, ən gözəl mənzərədir. Yavaş-yavaş irəlilədik. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4959, 66, 'g10-aze-orth-q3-19', 3, 19, 'hard', 'single', 'Tələffüzü [bıçax] və [çörəy''] olan sözlər hansı cümlədə düzgün yazılıb?', NULL, NULL, '{"A": "Nənə bıçaq ilə çörəyi kəsdi.", "B": "Nənə bıçaq ilə çörəki kəsdi.", "C": "Nənə bıçax ilə çörəyi kəsdi.", "D": "Nənə bıçağ ilə çörəyi kəsdi.", "E": "Nənə bıçax ilə çörəki kəsdi."}'::jsonb, 'A', NULL, '«bıçaq» — Sonda q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Nənə bıçaq ilə çörəyi kəsdi.');
INSERT INTO public.questions VALUES (4960, 66, 'g10-aze-orth-q3-20', 3, 20, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («heç» sözünün, qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Heç kim bu suala cavab vermədi. Ara-sıra bizə baş çəkir. Bilirəm ki, sən haqlısan.", "B": "Heçkim bu suala cavab vermədi. Arasıra bizə baş çəkir. Bilirəm ki, sən haqlısan.", "C": "Heç kim bu suala cavab vermədi. Ara-sıra bizə baş çəkir. Bilirəmki, sən haqlısan.", "D": "Heç kim bu suala cavab vermədi. Arasıra bizə baş çəkir. Bilirəm ki, sən haqlısan.", "E": "Heçkim bu suala cavab vermədi. Ara-sıra bizə baş çəkir. Bilirəm ki, sən haqlısan."}'::jsonb, 'A', NULL, 'Düzgün: Heç kim bu suala cavab vermədi. Ara-sıra bizə baş çəkir. Bilirəm ki, sən haqlısan. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4961, 66, 'g10-aze-orth-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «şərqi» və «qulağı» sözləri işlənmişdi.", "B": "Diktantda «dirəyi» və «hüququ» sözləri işlənmişdi.", "C": "Diktantda «burnu» və «ayağı» sözləri işlənmişdi.", "D": "Diktantda «parkı» və «dirəyi» sözləri işlənmişdi.", "E": "Diktantda «şəhəri» və «şəkli» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'şərq → şərqi (dəyişmir), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4962, 66, 'g10-aze-orth-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «ürəyi», «fərqi» sözlərini misal gətirdi.", "B": "Müəllim «ürəyi», «yarpağı» sözlərini misal gətirdi.", "C": "Müəllim «ürəyi», «yarpaqı» sözlərini misal gətirdi.", "D": "Müəllim «ürəki», «yarpaqı» sözlərini misal gətirdi.", "E": "Müəllim «ürəki», «yarpağı» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'ürək → ürəyi (k→y), yarpaq → yarpağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4963, 66, 'g10-aze-orth-q3-23', 3, 23, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), «da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Onlar artıq gəldilər mi? Kitab evdə qalıb. Yavaş yavaş irəlilədik.", "B": "Onlar artıq gəldilərmi? Kitab evdə qalıb. Yavaş yavaş irəlilədik.", "C": "Onlar artıq gəldilərmi? Kitab evdə qalıb. Yavaş-yavaş irəlilədik.", "D": "Onlar artıq gəldilərmi? Kitab ev də qalıb. Yavaş-yavaş irəlilədik.", "E": "Onlar artıq gəldilər mi? Kitab evdə qalıb. Yavaş-yavaş irəlilədik."}'::jsonb, 'C', NULL, 'Düzgün: Onlar artıq gəldilərmi? Kitab evdə qalıb. Yavaş-yavaş irəlilədik. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4964, 66, 'g10-aze-orth-q3-24', 3, 24, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, «heç» sözünün, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Sən də bu işdə iştirak et. Heçkim bu suala cavab vermədi. Gülə-gülə danışırdı.", "B": "Sən də bu işdə iştirak et. Heç kim bu suala cavab vermədi. Gülə gülə danışırdı.", "C": "Səndə bu işdə iştirak et. Heç kim bu suala cavab vermədi. Gülə-gülə danışırdı.", "D": "Sən də bu işdə iştirak et. Heçkim bu suala cavab vermədi. Gülə gülə danışırdı.", "E": "Sən də bu işdə iştirak et. Heç kim bu suala cavab vermədi. Gülə-gülə danışırdı."}'::jsonb, 'E', NULL, 'Düzgün: Sən də bu işdə iştirak et. Heç kim bu suala cavab vermədi. Gülə-gülə danışırdı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4965, 66, 'g10-aze-orth-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «boynu» və «çiçəyi» sözləri işlənmişdi.", "B": "Diktantda «bıçağı» və «inəyi» sözləri işlənmişdi.", "C": "Diktantda «boyunu» və «çiçəki» sözləri işlənmişdi.", "D": "Diktantda «ömürü» və «ürəyi» sözləri işlənmişdi.", "E": "Diktantda «ömrü» və «hüququ» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'boyun → boynu (sait düşümü), çiçək → çiçəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4966, 66, 'g10-aze-orth-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə sıra sayları rəqəmlə düzgün yazılıb?', NULL, NULL, '{"A": "2005-ci ildə məktəbimizin 64-cu buraxılışı oldu.", "B": "2005-cü ildə məktəbimizin 64-cü buraxılışı oldu.", "C": "2005-ci ildə məktəbimizin 64-cı buraxılışı oldu.", "D": "2005-ci ildə məktəbimizin 64-cü buraxılışı oldu.", "E": "2005-cı ildə məktəbimizin 64-cü buraxılışı oldu."}'::jsonb, 'D', NULL, 'Şəkilçi sayın oxunuşundakı son saitə uyğunlaşır: 2005-ci, 64-cü.');
INSERT INTO public.questions VALUES (4967, 66, 'g10-aze-orth-q3-27', 3, 27, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ata-ana övladını qoruyar. Bilirəmki, sən haqlısan. Ara-sıra bizə baş çəkir.", "B": "Ataana övladını qoruyar. Bilirəm ki, sən haqlısan. Ara-sıra bizə baş çəkir.", "C": "Ata-ana övladını qoruyar. Bilirəm ki, sən haqlısan. Arasıra bizə baş çəkir.", "D": "Ataana övladını qoruyar. Bilirəm ki, sən haqlısan. Arasıra bizə baş çəkir.", "E": "Ata-ana övladını qoruyar. Bilirəm ki, sən haqlısan. Ara-sıra bizə baş çəkir."}'::jsonb, 'E', NULL, 'Düzgün: Ata-ana övladını qoruyar. Bilirəm ki, sən haqlısan. Ara-sıra bizə baş çəkir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4968, 66, 'g10-aze-orth-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «şəhəri» və «çörəyi» sözləri işlənmişdi.", "B": "Diktantda «çiçəki» və «tanğı» sözləri işlənmişdi.", "C": "Diktantda «köynəki» və «dənizi» sözləri işlənmişdi.", "D": "Diktantda «hüququ» və «qulağı» sözləri işlənmişdi.", "E": "Diktantda «hüququ» və «ayağı» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'şəhər → şəhəri (dəyişmir), çörək → çörəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (4969, 66, 'g10-aze-orth-q3-29', 3, 29, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Onlar artıq gəldilərmi? Dedi ki, sabah gələcək. Bu, əngözəl mənzərədir.", "B": "Onlar artıq gəldilərmi? Dediki, sabah gələcək. Bu, əngözəl mənzərədir.", "C": "Onlar artıq gəldilərmi? Dediki, sabah gələcək. Bu, ən gözəl mənzərədir.", "D": "Onlar artıq gəldilərmi? Dedi ki, sabah gələcək. Bu, ən gözəl mənzərədir.", "E": "Onlar artıq gəldilər mi? Dedi ki, sabah gələcək. Bu, ən gözəl mənzərədir."}'::jsonb, 'D', NULL, 'Düzgün: Onlar artıq gəldilərmi? Dedi ki, sabah gələcək. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4970, 66, 'g10-aze-orth-q3-30', 3, 30, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ara-sıra bizə baş çəkir. Evdə ki hamı yatmışdı. Qızıl gül bağçanı bəzəyirdi.", "B": "Ara-sıra bizə baş çəkir. Evdəki hamı yatmışdı. Qızıl gül bağçanı bəzəyirdi.", "C": "Ara-sıra bizə baş çəkir. Evdəki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi.", "D": "Ara-sıra bizə baş çəkir. Evdə ki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi.", "E": "Arasıra bizə baş çəkir. Evdəki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi."}'::jsonb, 'C', NULL, 'Düzgün: Ara-sıra bizə baş çəkir. Evdəki hamı yatmışdı. Qızılgül bağçanı bəzəyirdi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (4971, 67, 'g10-aze-syn-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: omonim)", "B": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: omonim)", "C": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: antonim)", "D": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: antonim)", "E": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: omonim)"}'::jsonb, 'C', NULL, '«işıq» və «qaranlıq» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4972, 67, 'g10-aze-syn-q1-02', 1, 2, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Qapını açan uşaq pəncərəni bağlamağı unutdu. (açmaq – bağlamaq: sinonim)", "B": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: sinonim)", "C": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: sinonim)", "D": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu. (varlı – kasıb: antonim)", "E": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: sinonim)"}'::jsonb, 'B', NULL, '«məqsəd» və «niyyət» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4973, 67, 'g10-aze-syn-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə omonim işlənib, omonimlər müxtəlif nitq hissələrinə aiddir və sinonim işlənməyib?', NULL, NULL, '{"A": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu.", "B": "Bağda oynayan uşaq ayaqqabısının bağını bağladı.", "C": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi.", "D": "Dolu yağdı, səbət isə almalarla dolu qaldı.", "E": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi."}'::jsonb, 'D', NULL, 'Cümlədə: dolu – dolu (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4974, 67, 'g10-aze-syn-q1-04', 1, 4, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Gəlmək asandır, getmək çətin. (asan – çətin: antonim)", "B": "Qalib komanda məğlub rəqibini təbrik etdi. (qalib – məğlub: antonim)", "C": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı. (ilk – son: sinonim)", "D": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: sinonim)", "E": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: omonim)"}'::jsonb, 'D', NULL, '«xəta» və «səhv» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4975, 67, 'g10-aze-syn-q1-05', 1, 5, 'medium', 'single', 'Hansı cümlədə omonim işlənib və sinonim işlənməyib?', NULL, NULL, '{"A": "Qapını açan uşaq pəncərəni bağlamağı unutdu.", "B": "Köhnə dostunu görən kimi ağladı, sonra güldü.", "C": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "D": "Dolu yağdı, səbət isə almalarla dolu qaldı.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'D', NULL, 'Cümlədə: dolu – dolu (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4976, 67, 'g10-aze-syn-q1-06', 1, 6, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: sinonim)", "B": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: antonim)", "C": "Gəlmək asandır, getmək çətin. (asan – çətin: antonim)", "D": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: antonim)", "E": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: antonim)"}'::jsonb, 'C', NULL, '«asan» və «çətin» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4977, 67, 'g10-aze-syn-q1-07', 1, 7, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: omonim)", "B": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: omonim)", "C": "Qapını açan uşaq pəncərəni bağlamağı unutdu. (açmaq – bağlamaq: omonim)", "D": "Təzə paltarını geyindi, əski paltarlarını isə kasıblara payladı. (təzə – əski: sinonim)", "E": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu. (varlı – kasıb: antonim)"}'::jsonb, 'B', NULL, '«bal» və «bal» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4978, 67, 'g10-aze-syn-q1-08', 1, 8, 'medium', 'single', 'Hansı cümlədə omonim işlənməyib və antonim işlənməyib?', NULL, NULL, '{"A": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq.", "B": "Kitabı aldı, dəftəri isə dostuna verdi.", "C": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı.", "D": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi.", "E": "Təzə paltarını geyindi, əski paltarlarını isə kasıblara payladı."}'::jsonb, 'E', NULL, 'Cümlədə: təzə – əski (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4979, 67, 'g10-aze-syn-q1-09', 1, 9, 'medium', 'single', 'Hansı cümlədə sinonim işlənib və antonim işlənməyib?', NULL, NULL, '{"A": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "B": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq.", "C": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi.", "D": "Dolu yağdı, səbət isə almalarla dolu qaldı.", "E": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi."}'::jsonb, 'C', NULL, 'Cümlədə: xəta – səhv (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4980, 67, 'g10-aze-syn-q1-10', 1, 10, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: omonim)", "B": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: omonim)", "C": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: omonim)", "D": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır. (ahıl – qoca: omonim)", "E": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: sinonim)"}'::jsonb, 'C', NULL, '«sağ» və «sağ» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4981, 67, 'g10-aze-syn-q1-11', 1, 11, 'medium', 'single', 'Hansı cümlədə omonimlər eyni nitq hissəsinə aiddir və sinonim işlənməyib?', NULL, NULL, '{"A": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu.", "B": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu.", "C": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq.", "D": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı.", "E": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi."}'::jsonb, 'B', NULL, 'Cümlədə: qol – qol (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4982, 67, 'g10-aze-syn-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə sinonimlər sifətlə ifadə olunub, antonim işlənməyib və omonim işlənməyib?', NULL, NULL, '{"A": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "B": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "C": "Yağışlı havada uşaqlar evdə qaldılar.", "D": "Qorxu və vahimə bütün kəndi bürümüşdü.", "E": "Məqsədi aydın idi, niyyəti isə təmiz."}'::jsonb, 'B', NULL, 'Cümlədə: dinc – sakit (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4983, 67, 'g10-aze-syn-q1-13', 1, 13, 'medium', 'single', 'Hansı cümlədə antonimlər sifətlə ifadə olunub və sinonim işlənməyib?', NULL, NULL, '{"A": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik.", "B": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "C": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "D": "Qış soyuğunu yayın istisi ilə müqayisə etmək olmaz.", "E": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu."}'::jsonb, 'A', NULL, 'Cümlədə: dərin – dayaz (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4984, 67, 'g10-aze-syn-q1-14', 1, 14, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik. (dərin – dayaz: sinonim)", "B": "Gəlmək asandır, getmək çətin. (gəlmək – getmək: sinonim)", "C": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: sinonim)", "D": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu. (varlı – kasıb: antonim)", "E": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: sinonim)"}'::jsonb, 'C', NULL, '«xəta» və «səhv» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4985, 67, 'g10-aze-syn-q1-15', 1, 15, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: sinonim)", "B": "Qış soyuğunu yayın istisi ilə müqayisə etmək olmaz. (qış – yay: antonim)", "C": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: omonim)", "D": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: sinonim)", "E": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı. (ilk – son: sinonim)"}'::jsonb, 'D', NULL, '«xəta» və «səhv» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4986, 67, 'g10-aze-syn-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə antonimlər feillə ifadə olunub, omonim işlənməyib və antonim işlənib?', NULL, NULL, '{"A": "Köhnə dostunu görən kimi ağladı, sonra güldü.", "B": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "C": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu.", "D": "Hündür binaların yanında alçaq evlər kiçik görünürdü.", "E": "Qalib komanda məğlub rəqibini təbrik etdi."}'::jsonb, 'A', NULL, 'Cümlədə: ağlamaq – gülmək (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4987, 67, 'g10-aze-syn-q1-17', 1, 17, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: sinonim)", "B": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: omonim)", "C": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: sinonim)", "D": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: sinonim)", "E": "Uca dağların hündür zirvələri qarla örtülmüşdü. (uca – hündür: sinonim)"}'::jsonb, 'E', NULL, '«uca» və «hündür» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4988, 67, 'g10-aze-syn-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə omonim işlənib, antonim işlənməyib və sinonim işlənməyib?', NULL, NULL, '{"A": "Qapını açan uşaq pəncərəni bağlamağı unutdu.", "B": "Dolu yağdı, səbət isə almalarla dolu qaldı.", "C": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "D": "Yağışlı havada uşaqlar evdə qaldılar.", "E": "Uca dağların hündür zirvələri qarla örtülmüşdü."}'::jsonb, 'B', NULL, 'Cümlədə: dolu – dolu (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4989, 67, 'g10-aze-syn-q1-19', 1, 19, 'medium', 'single', 'Hansı cümlədə sinonimlər sifətlə ifadə olunub və sinonim işlənib?', NULL, NULL, '{"A": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir.", "B": "Qorxu və vahimə bütün kəndi bürümüşdü.", "C": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi.", "D": "Məqsədi aydın idi, niyyəti isə təmiz.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'A', NULL, 'Cümlədə: tanınmış – məşhur (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4990, 67, 'g10-aze-syn-q1-20', 1, 20, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Qış soyuğunu yayın istisi ilə müqayisə etmək olmaz. (qış – yay: sinonim)", "B": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: sinonim)", "C": "Bağda oynayan uşaq ayaqqabısının bağını bağladı. (bağ – bağ: sinonim)", "D": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: omonim)", "E": "Köhnə dostunu görən kimi ağladı, sonra güldü. (ağlamaq – gülmək: sinonim)"}'::jsonb, 'B', NULL, '«tanınmış» və «məşhur» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4991, 67, 'g10-aze-syn-q1-21', 1, 21, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: sinonim)", "B": "Qalib komanda məğlub rəqibini təbrik etdi. (qalib – məğlub: sinonim)", "C": "Gəlmək asandır, getmək çətin. (gəlmək – getmək: antonim)", "D": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: antonim)", "E": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: sinonim)"}'::jsonb, 'E', NULL, '«məqsəd» və «niyyət» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4992, 67, 'g10-aze-syn-q1-22', 1, 22, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: omonim)", "B": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: sinonim)", "C": "Qış soyuğunu yayın istisi ilə müqayisə etmək olmaz. (qış – yay: antonim)", "D": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: omonim)", "E": "Qalib komanda məğlub rəqibini təbrik etdi. (qalib – məğlub: antonim)"}'::jsonb, 'B', NULL, '«tanınmış» və «məşhur» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4993, 67, 'g10-aze-syn-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə antonim işlənməyib, sinonim işlənməyib və omonimlər eyni nitq hissəsinə aiddir?', NULL, NULL, '{"A": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "B": "Yağışlı havada uşaqlar evdə qaldılar.", "C": "Dolu yağdı, səbət isə almalarla dolu qaldı.", "D": "Bağda oynayan uşaq ayaqqabısının bağını bağladı.", "E": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq."}'::jsonb, 'D', NULL, 'Cümlədə: bağ – bağ (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4994, 67, 'g10-aze-syn-q1-24', 1, 24, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: omonim)", "B": "Köhnə dostunu görən kimi ağladı, sonra güldü. (ağlamaq – gülmək: omonim)", "C": "Gəlmək asandır, getmək çətin. (asan – çətin: antonim)", "D": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: omonim)", "E": "Hündür binaların yanında alçaq evlər kiçik görünürdü. (hündür – alçaq: omonim)"}'::jsonb, 'A', NULL, '«qol» və «qol» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4995, 67, 'g10-aze-syn-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib, antonim işlənməyib və sinonim işlənib?', NULL, NULL, '{"A": "Gəlmək asandır, getmək çətin.", "B": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "C": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi.", "D": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'C', NULL, 'Cümlədə: xəta – səhv (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4996, 67, 'g10-aze-syn-q1-26', 1, 26, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Gəlmək asandır, getmək çətin. (gəlmək – getmək: sinonim)", "B": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik. (dərin – dayaz: sinonim)", "C": "Təzə paltarını geyindi, əski paltarlarını isə kasıblara payladı. (təzə – əski: sinonim)", "D": "Hündür binaların yanında alçaq evlər kiçik görünürdü. (hündür – alçaq: sinonim)", "E": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: omonim)"}'::jsonb, 'C', NULL, '«təzə» və «əski» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4997, 67, 'g10-aze-syn-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə sinonimlər isimlə ifadə olunub, omonim işlənməyib və antonim işlənməyib?', NULL, NULL, '{"A": "Qorxu və vahimə bütün kəndi bürümüşdü.", "B": "Yağışlı havada uşaqlar evdə qaldılar.", "C": "Uca dağların hündür zirvələri qarla örtülmüşdü.", "D": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "E": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir."}'::jsonb, 'A', NULL, 'Cümlədə: qorxu – vahimə (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (4998, 67, 'g10-aze-syn-q1-28', 1, 28, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: omonim)", "B": "Gəlmək asandır, getmək çətin. (gəlmək – getmək: antonim)", "C": "Uca dağların hündür zirvələri qarla örtülmüşdü. (uca – hündür: omonim)", "D": "Qorxu və vahimə bütün kəndi bürümüşdü. (qorxu – vahimə: omonim)", "E": "Qalib komanda məğlub rəqibini təbrik etdi. (qalib – məğlub: antonim)"}'::jsonb, 'A', NULL, '«dolu» və «dolu» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (4999, 67, 'g10-aze-syn-q1-29', 1, 29, 'medium', 'single', 'Hansı cümlədə antonim işlənib və omonim işlənməyib?', NULL, NULL, '{"A": "Zəhmətkeş kəndlilər çalışqan gənclərə nümunə idilər.", "B": "Qalib komanda məğlub rəqibini təbrik etdi.", "C": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "D": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'B', NULL, 'Cümlədə: qalib – məğlub (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
