INSERT INTO public.questions VALUES (5006, 67, 'g10-aze-syn-q2-06', 2, 6, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Uca dağların hündür zirvələri qarla örtülmüşdü. (uca – hündür: antonim)", "B": "Gəlmək asandır, getmək çətin. (asan – çətin: antonim)", "C": "Qorxu və vahimə bütün kəndi bürümüşdü. (qorxu – vahimə: antonim)", "D": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: antonim)", "E": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: omonim)"}'::jsonb, 'B', NULL, '«asan» və «çətin» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5007, 67, 'g10-aze-syn-q2-07', 2, 7, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır. (ahıl – qoca: sinonim)", "B": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı. (dinc – sakit: omonim)", "C": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: omonim)", "D": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: sinonim)", "E": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: omonim)"}'::jsonb, 'C', NULL, '«dolu» və «dolu» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5008, 67, 'g10-aze-syn-q2-08', 2, 8, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Qalib komanda məğlub rəqibini təbrik etdi. (qalib – məğlub: sinonim)", "B": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: omonim)", "C": "Qalib komanda məğlub rəqibini təbrik etdi. (qalib – məğlub: antonim)", "D": "Qorxu və vahimə bütün kəndi bürümüşdü. (qorxu – vahimə: sinonim)", "E": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: sinonim)"}'::jsonb, 'D', NULL, '«qorxu» və «vahimə» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5009, 67, 'g10-aze-syn-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib, omonim işlənməyib və antonimlər feillə ifadə olunub?', NULL, NULL, '{"A": "Qalib komanda məğlub rəqibini təbrik etdi.", "B": "Yağışlı havada uşaqlar evdə qaldılar.", "C": "Hündür binaların yanında alçaq evlər kiçik görünürdü.", "D": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "E": "Qapını açan uşaq pəncərəni bağlamağı unutdu."}'::jsonb, 'E', NULL, 'Cümlədə: açmaq – bağlamaq (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5010, 67, 'g10-aze-syn-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə omonim işlənib, antonim işlənməyib və sinonim işlənməyib?', NULL, NULL, '{"A": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi.", "B": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "C": "Köhnə dostunu görən kimi ağladı, sonra güldü.", "D": "Yağışlı havada uşaqlar evdə qaldılar.", "E": "Qorxu və vahimə bütün kəndi bürümüşdü."}'::jsonb, 'A', NULL, 'Cümlədə: sağ – sağ (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5011, 67, 'g10-aze-syn-q2-11', 2, 11, 'medium', 'single', 'Hansı cümlədə sinonim işlənməyib və antonimlər feillə ifadə olunub?', NULL, NULL, '{"A": "Gəlmək asandır, getmək çətin.", "B": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu.", "C": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik.", "D": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "E": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı."}'::jsonb, 'A', NULL, 'Cümlədə: gəlmək – getmək (antonim); asan – çətin (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5012, 67, 'g10-aze-syn-q2-12', 2, 12, 'medium', 'single', 'Hansı cümlədə iki leksik cüt (sinonim, antonim və ya omonim) var və sinonim işlənməyib?', NULL, NULL, '{"A": "Gəlmək asandır, getmək çətin.", "B": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "C": "Köhnə dostunu görən kimi ağladı, sonra güldü.", "D": "Qapını açan uşaq pəncərəni bağlamağı unutdu.", "E": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı."}'::jsonb, 'A', NULL, 'Cümlədə: gəlmək – getmək (antonim); asan – çətin (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5013, 67, 'g10-aze-syn-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə sinonimlər sifətlə ifadə olunub, omonim işlənməyib və antonim işlənməyib?', NULL, NULL, '{"A": "Qorxu və vahimə bütün kəndi bürümüşdü.", "B": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "C": "Məqsədi aydın idi, niyyəti isə təmiz.", "D": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'B', NULL, 'Cümlədə: dinc – sakit (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5014, 67, 'g10-aze-syn-q2-14', 2, 14, 'medium', 'single', 'Hansı cümlədə sinonim işlənməyib və antonimlər sifətlə ifadə olunub?', NULL, NULL, '{"A": "Köhnə dostunu görən kimi ağladı, sonra güldü.", "B": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi.", "C": "Hündür binaların yanında alçaq evlər kiçik görünürdü.", "D": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "E": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi."}'::jsonb, 'C', NULL, 'Cümlədə: hündür – alçaq (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5015, 67, 'g10-aze-syn-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə antonimlər isimlə ifadə olunub, antonim işlənib və sinonim işlənməyib?', NULL, NULL, '{"A": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik.", "B": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "C": "Köhnə dostunu görən kimi ağladı, sonra güldü.", "D": "Gəlmək asandır, getmək çətin.", "E": "Qalib komanda məğlub rəqibini təbrik etdi."}'::jsonb, 'B', NULL, 'Cümlədə: işıq – qaranlıq (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5016, 67, 'g10-aze-syn-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə antonimlər feillə ifadə olunub, sinonim işlənməyib və omonim işlənməyib?', NULL, NULL, '{"A": "Qalib komanda məğlub rəqibini təbrik etdi.", "B": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik.", "C": "Yağışlı havada uşaqlar evdə qaldılar.", "D": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı.", "E": "Kitabı aldı, dəftəri isə dostuna verdi."}'::jsonb, 'E', NULL, 'Cümlədə: almaq – vermək (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5017, 67, 'g10-aze-syn-q2-17', 2, 17, 'medium', 'single', 'Hansı cümlədə sinonim işlənməyib və omonim işlənməyib?', NULL, NULL, '{"A": "Qorxu və vahimə bütün kəndi bürümüşdü.", "B": "Bağda oynayan uşaq ayaqqabısının bağını bağladı.", "C": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik.", "D": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "E": "Zəhmətkeş kəndlilər çalışqan gənclərə nümunə idilər."}'::jsonb, 'C', NULL, 'Cümlədə: dərin – dayaz (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5018, 67, 'g10-aze-syn-q2-18', 2, 18, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Bağda oynayan uşaq ayaqqabısının bağını bağladı. (bağ – bağ: omonim)", "B": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır. (ahıl – qoca: sinonim)", "C": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: antonim)", "D": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: antonim)", "E": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu. (varlı – kasıb: antonim)"}'::jsonb, 'E', NULL, '«varlı» və «kasıb» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5019, 67, 'g10-aze-syn-q2-19', 2, 19, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: omonim)", "B": "Qorxu və vahimə bütün kəndi bürümüşdü. (qorxu – vahimə: omonim)", "C": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: sinonim)", "D": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı. (dinc – sakit: omonim)", "E": "Gəlmək asandır, getmək çətin. (asan – çətin: omonim)"}'::jsonb, 'A', NULL, '«qol» və «qol» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5020, 67, 'g10-aze-syn-q2-20', 2, 20, 'medium', 'single', 'Hansı cümlədə sinonim işlənməyib və omonim işlənməyib?', NULL, NULL, '{"A": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır.", "B": "Qalib komanda məğlub rəqibini təbrik etdi.", "C": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq.", "D": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi.", "E": "Zəhmətkeş kəndlilər çalışqan gənclərə nümunə idilər."}'::jsonb, 'B', NULL, 'Cümlədə: qalib – məğlub (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5021, 67, 'g10-aze-syn-q2-21', 2, 21, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: omonim)", "B": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: sinonim)", "C": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik. (dərin – dayaz: sinonim)", "D": "Bağda oynayan uşaq ayaqqabısının bağını bağladı. (bağ – bağ: sinonim)", "E": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi. (işıq – qaranlıq: sinonim)"}'::jsonb, 'B', NULL, '«məqsəd» və «niyyət» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
