INSERT INTO public.questions VALUES (5028, 67, 'g10-aze-syn-q2-28', 2, 28, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı. (dinc – sakit: sinonim)", "B": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: omonim)", "C": "Köhnə dostunu görən kimi ağladı, sonra güldü. (ağlamaq – gülmək: antonim)", "D": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu. (varlı – kasıb: sinonim)", "E": "Qapını açan uşaq pəncərəni bağlamağı unutdu. (açmaq – bağlamaq: antonim)"}'::jsonb, 'A', NULL, '«dinc» və «sakit» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5029, 67, 'g10-aze-syn-q2-29', 2, 29, 'medium', 'single', 'Hansı cümlədə antonim işlənib və sinonim işlənməyib?', NULL, NULL, '{"A": "Dolu yağdı, səbət isə almalarla dolu qaldı.", "B": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq.", "C": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "D": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi.", "E": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi."}'::jsonb, 'C', NULL, 'Cümlədə: işıq – qaranlıq (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5030, 67, 'g10-aze-syn-q2-30', 2, 30, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Qapını açan uşaq pəncərəni bağlamağı unutdu. (açmaq – bağlamaq: antonim)", "B": "Dolu yağdı, səbət isə almalarla dolu qaldı. (dolu – dolu: omonim)", "C": "Məqsədi aydın idi, niyyəti isə təmiz. (məqsəd – niyyət: omonim)", "D": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı. (dinc – sakit: omonim)", "E": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: sinonim)"}'::jsonb, 'B', NULL, '«dolu» və «dolu» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5031, 67, 'g10-aze-syn-q3-01', 3, 1, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt omonimdir?', NULL, NULL, '{"A": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu. (varlı – kasıb: antonim)", "B": "Uca dağların hündür zirvələri qarla örtülmüşdü. (uca – hündür: sinonim)", "C": "Zəhmətkeş kəndlilər çalışqan gənclərə nümunə idilər. (zəhmətkeş – çalışqan: omonim)", "D": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik. (dərin – dayaz: omonim)", "E": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: omonim)"}'::jsonb, 'E', NULL, '«qol» və «qol» — omonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5032, 67, 'g10-aze-syn-q3-02', 3, 2, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Hündür binaların yanında alçaq evlər kiçik görünürdü. (hündür – alçaq: antonim)", "B": "Şagirdin xətası müəllimin diqqətindən yayınmadı, o, səhvini dərhal düzəltdi. (xəta – səhv: sinonim)", "C": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: omonim)", "D": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: omonim)", "E": "Təzə paltarını geyindi, əski paltarlarını isə kasıblara payladı. (təzə – əski: antonim)"}'::jsonb, 'A', NULL, '«hündür» və «alçaq» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5033, 67, 'g10-aze-syn-q3-03', 3, 3, 'medium', 'single', 'Hansı cümlədə antonimlər feillə ifadə olunub və omonim işlənməyib?', NULL, NULL, '{"A": "Gəlmək asandır, getmək çətin.", "B": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "C": "Qış soyuğunu yayın istisi ilə müqayisə etmək olmaz.", "D": "Qalib komanda məğlub rəqibini təbrik etdi.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'A', NULL, 'Cümlədə: gəlmək – getmək (antonim); asan – çətin (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5034, 67, 'g10-aze-syn-q3-04', 3, 4, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Bağda oynayan uşaq ayaqqabısının bağını bağladı. (bağ – bağ: antonim)", "B": "Yaralı əsgər sağ qaldı, amma sağ əli zədələnmişdi. (sağ – sağ: antonim)", "C": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır. (ahıl – qoca: sinonim)", "D": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: antonim)", "E": "Köhnə dostunu görən kimi ağladı, sonra güldü. (ağlamaq – gülmək: antonim)"}'::jsonb, 'E', NULL, '«ağlamaq» və «gülmək» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5035, 67, 'g10-aze-syn-q3-05', 3, 5, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı. (ilk – son: antonim)", "B": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq. (aş – aş: omonim)", "C": "Uca dağların hündür zirvələri qarla örtülmüşdü. (uca – hündür: sinonim)", "D": "Zəhmətkeş kəndlilər çalışqan gənclərə nümunə idilər. (zəhmətkeş – çalışqan: sinonim)", "E": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: omonim)"}'::jsonb, 'A', NULL, '«ilk» və «son» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5036, 67, 'g10-aze-syn-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib, omonim işlənməyib və antonim işlənib?', NULL, NULL, '{"A": "Uşaq anasının əlindən tutub yavaş-yavaş yeriyirdi.", "B": "Qorxu və vahimə bütün kəndi bürümüşdü.", "C": "Uca dağların hündür zirvələri qarla örtülmüşdü.", "D": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik.", "E": "Yağışlı havada uşaqlar evdə qaldılar."}'::jsonb, 'D', NULL, 'Cümlədə: dərin – dayaz (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5037, 67, 'g10-aze-syn-q3-07', 3, 7, 'medium', 'single', 'Hansı cümlədə iki leksik cüt (sinonim, antonim və ya omonim) var və antonimlər feillə ifadə olunub?', NULL, NULL, '{"A": "Qapını açan uşaq pəncərəni bağlamağı unutdu.", "B": "Gəlmək asandır, getmək çətin.", "C": "Kitabı aldı, dəftəri isə dostuna verdi.", "D": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı.", "E": "Köhnə dostunu görən kimi ağladı, sonra güldü."}'::jsonb, 'B', NULL, 'Cümlədə: gəlmək – getmək (antonim); asan – çətin (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5038, 67, 'g10-aze-syn-q3-08', 3, 8, 'medium', 'single', 'Hansı cümlədə iki leksik cüt (sinonim, antonim və ya omonim) var və sinonim işlənməyib?', NULL, NULL, '{"A": "Aşpaz aş bişirdi, biz isə həmin gün dağı aşdıq.", "B": "Gəlmək asandır, getmək çətin.", "C": "Kitabı aldı, dəftəri isə dostuna verdi.", "D": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı.", "E": "Qış soyuğunu yayın istisi ilə müqayisə etmək olmaz."}'::jsonb, 'B', NULL, 'Cümlədə: gəlmək – getmək (antonim); asan – çətin (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5039, 67, 'g10-aze-syn-q3-09', 3, 9, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir?', NULL, NULL, '{"A": "Ahıl kişi dedi ki, qoca çinar kəndin tarixini yaxşı xatırlayır. (ahıl – qoca: sinonim)", "B": "Gəlmək asandır, getmək çətin. (gəlmək – getmək: sinonim)", "C": "Hündür binaların yanında alçaq evlər kiçik görünürdü. (hündür – alçaq: sinonim)", "D": "İmtahanda yüksək bal toplayan nəvəsinə nənəsi bal göndərdi. (bal – bal: sinonim)", "E": "Dərin dərədən dayaz çaya qədər hər yeri gəzdik. (dərin – dayaz: antonim)"}'::jsonb, 'A', NULL, '«ahıl» və «qoca» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5040, 67, 'g10-aze-syn-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə antonimlər sifətlə ifadə olunub, omonim işlənməyib və iki leksik cüt (sinonim, antonim və ya omonim) var?', NULL, NULL, '{"A": "Qalib komanda məğlub rəqibini təbrik etdi.", "B": "Hündür binaların yanında alçaq evlər kiçik görünürdü.", "C": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu.", "D": "Gəlmək asandır, getmək çətin.", "E": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı."}'::jsonb, 'D', NULL, 'Cümlədə: gəlmək – getmək (antonim); asan – çətin (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5041, 67, 'g10-aze-syn-q3-11', 3, 11, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir?', NULL, NULL, '{"A": "Bu tanınmış alim dünyada məşhur kitabların müəllifidir. (tanınmış – məşhur: antonim)", "B": "Yolun sonunda yorğun səyyahı dinc və sakit bir kənd qarşıladı. (dinc – sakit: sinonim)", "C": "Qorxu və vahimə bütün kəndi bürümüşdü. (qorxu – vahimə: sinonim)", "D": "Köhnə dostunu görən kimi ağladı, sonra güldü. (ağlamaq – gülmək: antonim)", "E": "Futbolçu qolunu zədələsə də, oyunun sonunda qol vurdu. (qol – qol: antonim)"}'::jsonb, 'D', NULL, '«ağlamaq» və «gülmək» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (5042, 67, 'g10-aze-syn-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib, antonim işlənib və antonimlər feillə ifadə olunub?', NULL, NULL, '{"A": "Hündür binaların yanında alçaq evlər kiçik görünürdü.", "B": "İşıqla qaranlığın sərhədində bir kölgə tərpəndi.", "C": "Kitabın ilk səhifəsi ilə son səhifəsi arasında böyük fərq vardı.", "D": "Qapını açan uşaq pəncərəni bağlamağı unutdu.", "E": "Varlı tacir kasıb qonşusuna həmişə əl tuturdu."}'::jsonb, 'D', NULL, 'Cümlədə: açmaq – bağlamaq (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
