INSERT INTO public.questions VALUES (5111, 68, 'g10-aze-idiom-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə «qocalmaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar.", "B": "Atası çağıranda oğlan dilini dişləyib susdu.", "C": "Rəhbər bəzi nöqsanlara göz yumurdu.", "D": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi.", "E": "Ədalətsizliyi görən hakimin gözü qızdı."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «beli bükülmək» — qocalmaq.');
INSERT INTO public.questions VALUES (5112, 68, 'g10-aze-idiom-q2-22', 2, 22, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı. («qanı qaralmaq» — eşitməzliyə vurmaq)", "B": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («alın təri tökmək» — başa düşmək, anlamaq)", "C": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi. («dünyasını dəyişmək» — vəfat etmək)", "D": "Barmağını belə tərpətməyən oğlan hamıdan çox tərif gözləyirdi. («barmağını belə tərpətməmək» — diqqətlə dinləmək)", "E": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi. («ödü ağzına gəlmək» — çox fikirləşmək)"}'::jsonb, 'C', NULL, '«dünyasını dəyişmək» — vəfat etmək.');
INSERT INTO public.questions VALUES (5113, 68, 'g10-aze-idiom-q2-23', 2, 23, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar. («yerə-göyə sığmamaq» — heç bir iş görməmək)", "B": "Rəhbər bəzi nöqsanlara göz yumurdu. («göz yummaq» — intizarla gözləmək)", "C": "Müəllimin tənqidindən sonra uşaq yerə girdi. («yerə girmək» — çox utanmaq)", "D": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı. («qanı qaralmaq» — çox zəhmət çəkmək)", "E": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — başa düşmək, anlamaq)"}'::jsonb, 'C', NULL, '«yerə girmək» — çox utanmaq.');
INSERT INTO public.questions VALUES (5114, 68, 'g10-aze-idiom-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə «çox sevinmək» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi.", "B": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər.", "C": "Atası çağıranda oğlan dilini dişləyib susdu.", "D": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar.", "E": "Yaşlı ana illərlə oğlunun yolunu gözlədi, gözü yolda qaldı."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «yerə-göyə sığmamaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (5115, 68, 'g10-aze-idiom-q2-25', 2, 25, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı. («ağzı qulağına çatmaq» — çox sevinmək)", "B": "Satıcı müştərinin başını tovlayıb ona köhnə mal satdı. («başını tovlamaq» — kefi pozulmaq)", "C": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («alın təri tökmək» — imzalamaq)", "D": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («alın təri tökmək» — başa düşmək, anlamaq)", "E": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi. («beli bükülmək» — vəfat etmək)"}'::jsonb, 'A', NULL, '«ağzı qulağına çatmaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (5116, 68, 'g10-aze-idiom-q2-26', 2, 26, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu. («başına papaq qoymaq» — çox hirslənmək)", "B": "Ədalətsizliyi görən hakimin gözü qızdı. («gözü qızmaq» — aldatmaq)", "C": "Satıcı müştərinin başını tovlayıb ona köhnə mal satdı. («başını tovlamaq» — qocalmaq)", "D": "Çalışqan gənclər əl-ələ verib kəndi abadlaşdırdılar. («əl-ələ vermək» — birləşib birgə çalışmaq)", "E": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — heyrətlənmək)"}'::jsonb, 'D', NULL, '«əl-ələ vermək» — birləşib birgə çalışmaq.');
INSERT INTO public.questions VALUES (5117, 68, 'g10-aze-idiom-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə «kefi pozulmaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər.", "B": "Tapşırığın mənasını ağlım kəsmədi.", "C": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu.", "D": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı.", "E": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı."}'::jsonb, 'E', NULL, 'Cümlədəki frazeologizmlər: «qanı qaralmaq» — kefi pozulmaq.');
INSERT INTO public.questions VALUES (5118, 68, 'g10-aze-idiom-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə «susmaq, danışmamaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Ədalətsizliyi görən hakimin gözü qızdı.", "B": "Atası çağıranda oğlan dilini dişləyib susdu.", "C": "Rəhbər bəzi nöqsanlara göz yumurdu.", "D": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu.", "E": "Xəbəri eşidən rəis od püskürürdü."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «dilini dişləmək» — susmaq, danışmamaq.');
INSERT INTO public.questions VALUES (5119, 68, 'g10-aze-idiom-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə «kefi pozulmaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu.", "B": "Barmağını belə tərpətməyən oğlan hamıdan çox tərif gözləyirdi.", "C": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi.", "D": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı.", "E": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «qanı qaralmaq» — kefi pozulmaq.');
INSERT INTO public.questions VALUES (5120, 68, 'g10-aze-idiom-q2-30', 2, 30, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — çox hirslənmək)", "B": "Tapşırığın mənasını ağlım kəsmədi. («ağlı kəsmək» — heyrətlənmək)", "C": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — çox qorxmaq)", "D": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar. («yerə-göyə sığmamaq» — susmaq, danışmamaq)", "E": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («dəridən-qabıqdan çıxmaq» — ruhlandırmaq)"}'::jsonb, 'A', NULL, '«od püskürmək» — çox hirslənmək.');
INSERT INTO public.questions VALUES (5121, 68, 'g10-aze-idiom-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə «başa düşmək, anlamaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi.", "B": "Tapşırığın mənasını ağlım kəsmədi.", "C": "Barmağını belə tərpətməyən oğlan hamıdan çox tərif gözləyirdi.", "D": "Xəbəri eşidən rəis od püskürürdü.", "E": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «ağlı kəsmək» — başa düşmək, anlamaq.');
INSERT INTO public.questions VALUES (5122, 68, 'g10-aze-idiom-q3-02', 3, 2, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Yarışdan qayıdan idmançılar əldən düşmüş, ayaqdan düşmüşdülər. («ayaqdan düşmək» — çox yorulmaq)", "B": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — aldatmaq)", "C": "Ədalətsizliyi görən hakimin gözü qızdı. («gözü qızmaq» — çox sevinmək)", "D": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu. («başına papaq qoymaq» — çox utanmaq)", "E": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı. («ağzı qulağına çatmaq» — çox qorxmaq)"}'::jsonb, 'A', NULL, '«ayaqdan düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (5123, 68, 'g10-aze-idiom-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə iki frazeologizm işlənib və onlar mənaca bir-birinə yaxındır (sinonimdir)?', NULL, NULL, '{"A": "Ədalətsizliyi görən hakimin gözü qızdı.", "B": "Satıcı müştərinin başını tovlayıb ona köhnə mal satdı.", "C": "Çalışqan gənclər əl-ələ verib kəndi abadlaşdırdılar.", "D": "Yaşlı ana illərlə oğlunun yolunu gözlədi, gözü yolda qaldı.", "E": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: «dəridən-qabıqdan çıxmaq» — çox zəhmət çəkmək; «alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (5124, 68, 'g10-aze-idiom-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Uşaq dişini ağrıdan dodağını dişlədi.", "B": "Atası çağıranda oğlan dilini dişləyib susdu.", "C": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu.", "D": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi.", "E": "Səyahətdən qayıdan bacım hər şeyi bir-bir danışdı."}'::jsonb, 'A', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (5125, 68, 'g10-aze-idiom-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə «kefi pozulmaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Xəbəri eşidən rəis od püskürürdü.", "B": "Barmağını belə tərpətməyən oğlan hamıdan çox tərif gözləyirdi.", "C": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı.", "D": "Usta öz şagirdinə həmişə əl uzadırdı.", "E": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu."}'::jsonb, 'C', NULL, 'Cümlədəki frazeologizmlər: «qanı qaralmaq» — kefi pozulmaq.');
INSERT INTO public.questions VALUES (5126, 68, 'g10-aze-idiom-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə «kefi pozulmaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Tapşırığın mənasını ağlım kəsmədi.", "B": "Satıcı müştərinin başını tovlayıb ona köhnə mal satdı.", "C": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı.", "D": "Barmağını belə tərpətməyən oğlan hamıdan çox tərif gözləyirdi.", "E": "Rəhbər bəzi nöqsanlara göz yumurdu."}'::jsonb, 'C', NULL, 'Cümlədəki frazeologizmlər: «qanı qaralmaq» — kefi pozulmaq.');
INSERT INTO public.questions VALUES (5127, 68, 'g10-aze-idiom-q3-07', 3, 7, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər. («barmağını dişləmək» — heyrətlənmək)", "B": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi. («beli bükülmək» — kömək etmək)", "C": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi. («beli bükülmək» — ruhlandırmaq)", "D": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər. («barmağını dişləmək» — vəd etmək)", "E": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər. («barmağını dişləmək» — diqqətlə dinləmək)"}'::jsonb, 'A', NULL, '«barmağını dişləmək» — heyrətlənmək.');
