INSERT INTO public.questions VALUES (5132, 68, 'g10-aze-idiom-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə «çox hirslənmək» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Müəllimin tənqidindən sonra uşaq yerə girdi.", "B": "Tapşırığın mənasını ağlım kəsmədi.", "C": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı.", "D": "Xəbəri eşidən rəis od püskürürdü.", "E": "Şahid bütün günahları boynuna aldı."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «od püskürmək» — çox hirslənmək.');
INSERT INTO public.questions VALUES (5133, 68, 'g10-aze-idiom-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Səyahətdən qayıdan bacım hər şeyi bir-bir danışdı.", "B": "Ədalətsizliyi görən hakimin gözü qızdı.", "C": "Şahid bütün günahları boynuna aldı.", "D": "Rəhbər bəzi nöqsanlara göz yumurdu.", "E": "Qız gözlərini yumub bir az dincəldi."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (5134, 68, 'g10-aze-idiom-q3-14', 3, 14, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («alın təri tökmək» — çox zəhmət çəkmək)", "B": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı. («qanı qaralmaq» — ruhlandırmaq)", "C": "Ədalətsizliyi görən hakimin gözü qızdı. («gözü qızmaq» — ruhlandırmaq)", "D": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi. («ödü ağzına gəlmək» — vəfat etmək)", "E": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («alın təri tökmək» — intizarla gözləmək)"}'::jsonb, 'A', NULL, '«alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (5135, 68, 'g10-aze-idiom-q3-15', 3, 15, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Atası çağıranda oğlan dilini dişləyib susdu. («dilini dişləmək» — susmaq, danışmamaq)", "B": "Usta öz şagirdinə həmişə əl uzadırdı. («əl uzatmaq» — çox yorulmaq)", "C": "Yarışdan qayıdan idmançılar əldən düşmüş, ayaqdan düşmüşdülər. («əldən düşmək» — intizarla gözləmək)", "D": "Yarışdan qayıdan idmançılar əldən düşmüş, ayaqdan düşmüşdülər. («ayaqdan düşmək» — kefi pozulmaq)", "E": "Yaşlı ana illərlə oğlunun yolunu gözlədi, gözü yolda qaldı. («gözü yolda qalmaq» — çox utanmaq)"}'::jsonb, 'A', NULL, '«dilini dişləmək» — susmaq, danışmamaq.');
INSERT INTO public.questions VALUES (5136, 68, 'g10-aze-idiom-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə «kefi pozulmaq» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi.", "B": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi.", "C": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər.", "D": "Müəllimin tənqidindən sonra uşaq yerə girdi.", "E": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı."}'::jsonb, 'E', NULL, 'Cümlədəki frazeologizmlər: «qanı qaralmaq» — kefi pozulmaq.');
INSERT INTO public.questions VALUES (5137, 68, 'g10-aze-idiom-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə iki frazeologizm işlənib və onlar mənaca bir-birinə yaxındır (sinonimdir)?', NULL, NULL, '{"A": "Usta öz şagirdinə həmişə əl uzadırdı.", "B": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu.", "C": "Yarışdan qayıdan idmançılar əldən düşmüş, ayaqdan düşmüşdülər.", "D": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi.", "E": "Tapşırığın mənasını ağlım kəsmədi."}'::jsonb, 'C', NULL, 'Düzgün cümlədə: «əldən düşmək» — çox yorulmaq; «ayaqdan düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (5138, 68, 'g10-aze-idiom-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə «heç bir iş görməmək» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Tapşırığın mənasını ağlım kəsmədi.", "B": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı.", "C": "Barmağını belə tərpətməyən oğlan hamıdan çox tərif gözləyirdi.", "D": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar.", "E": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər."}'::jsonb, 'C', NULL, 'Cümlədəki frazeologizmlər: «barmağını belə tərpətməmək» — heç bir iş görməmək.');
INSERT INTO public.questions VALUES (5139, 68, 'g10-aze-idiom-q3-19', 3, 19, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Sınaqdan keçə bilməyən şagirdin qanı qaraldı. («qanı qaralmaq» — heyrətlənmək)", "B": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi. («ödü ağzına gəlmək» — kömək etmək)", "C": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi. («dünyasını dəyişmək» — vəfat etmək)", "D": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi. («beli bükülmək» — kömək etmək)", "E": "Müəllimin tənqidindən sonra uşaq yerə girdi. («yerə girmək» — etiraf etmək)"}'::jsonb, 'C', NULL, '«dünyasını dəyişmək» — vəfat etmək.');
INSERT INTO public.questions VALUES (5140, 68, 'g10-aze-idiom-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Rəhbər bəzi nöqsanlara göz yumurdu.", "B": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi.", "C": "Tapşırığın mənasını ağlım kəsmədi.", "D": "Səyahətdən qayıdan bacım hər şeyi bir-bir danışdı.", "E": "Bağban budağı kəsmək üçün əlini uzatdı."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (5141, 68, 'g10-aze-idiom-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə «çox sevinmək» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Ədalətsizliyi görən hakimin gözü qızdı.", "B": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar.", "C": "Satıcı müştərinin başını tovlayıb ona köhnə mal satdı.", "D": "Yaşlı ana illərlə oğlunun yolunu gözlədi, gözü yolda qaldı.", "E": "Usta öz şagirdinə həmişə əl uzadırdı."}'::jsonb, 'B', NULL, 'Cümlədəki frazeologizmlər: «yerə-göyə sığmamaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (5142, 68, 'g10-aze-idiom-q3-22', 3, 22, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Ədalətsizliyi görən hakimin gözü qızdı. («gözü qızmaq» — çox zəhmət çəkmək)", "B": "Müəllimin tənqidindən sonra uşaq yerə girdi. («yerə girmək» — kömək etmək)", "C": "Şahid bütün günahları boynuna aldı. («boynuna almaq» — çox yorulmaq)", "D": "Atası çağıranda oğlan dilini dişləyib susdu. («dilini dişləmək» — susmaq, danışmamaq)", "E": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu. («başına papaq qoymaq» — intizarla gözləmək)"}'::jsonb, 'D', NULL, '«dilini dişləmək» — susmaq, danışmamaq.');
INSERT INTO public.questions VALUES (5143, 68, 'g10-aze-idiom-q3-23', 3, 23, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Tapşırığın mənasını ağlım kəsmədi. («ağlı kəsmək» — heyrətlənmək)", "B": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi. («dünyasını dəyişmək» — intizarla gözləmək)", "C": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı. («ağzı qulağına çatmaq» — birləşib birgə çalışmaq)", "D": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü. («dəridən-qabıqdan çıxmaq» — çox zəhmət çəkmək)", "E": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi. («ödü ağzına gəlmək» — başa düşmək, anlamaq)"}'::jsonb, 'D', NULL, '«dəridən-qabıqdan çıxmaq» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (5144, 68, 'g10-aze-idiom-q3-24', 3, 24, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı. («ağzı qulağına çatmaq» — etiraf etmək)", "B": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — aldatmaq)", "C": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi. («ödü ağzına gəlmək» — çox qorxmaq)", "D": "Ədalətsizliyi görən hakimin gözü qızdı. («gözü qızmaq» — çox utanmaq)", "E": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu. («başına papaq qoymaq» — birləşib birgə çalışmaq)"}'::jsonb, 'C', NULL, '«ödü ağzına gəlmək» — çox qorxmaq.');
INSERT INTO public.questions VALUES (5145, 68, 'g10-aze-idiom-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə frazeologizm işlənməyib, lakin frazeologizmin tərkibindəki sözlər həqiqi mənada işlənib?', NULL, NULL, '{"A": "Qız gözlərini yumub bir az dincəldi.", "B": "Səyahətdən qayıdan bacım hər şeyi bir-bir danışdı.", "C": "Şahid bütün günahları boynuna aldı.", "D": "Möcüzəli mənzərəni görən turistlər barmaqlarını dişlədilər.", "E": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu."}'::jsonb, 'A', NULL, 'Düzgün cümlədə: frazeologizm yoxdur, sözlər həqiqi mənadadır.');
INSERT INTO public.questions VALUES (5146, 68, 'g10-aze-idiom-q3-26', 3, 26, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Atası çağıranda oğlan dilini dişləyib susdu. («dilini dişləmək» — etiraf etmək)", "B": "Qaranlıq meşədə canavar səsi eşidəndə ödüm ağzıma gəldi. («ödü ağzına gəlmək» — çox zəhmət çəkmək)", "C": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — ruhlandırmaq)", "D": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar. («yerə-göyə sığmamaq» — ruhlandırmaq)", "E": "Yarışdan qayıdan idmançılar əldən düşmüş, ayaqdan düşmüşdülər. («əldən düşmək» — çox yorulmaq)"}'::jsonb, 'E', NULL, '«əldən düşmək» — çox yorulmaq.');
INSERT INTO public.questions VALUES (5147, 68, 'g10-aze-idiom-q3-27', 3, 27, 'medium', 'single', 'Hansı variantda cümlədəki frazeoloji birləşmənin mənası düzgün izah olunub?', NULL, NULL, '{"A": "Rəhbər bəzi nöqsanlara göz yumurdu. («göz yummaq» — çox hirslənmək)", "B": "Usta öz şagirdinə həmişə əl uzadırdı. («əl uzatmaq» — kömək etmək)", "C": "Yarışdan qayıdan idmançılar əldən düşmüş, ayaqdan düşmüşdülər. («əldən düşmək» — görməzlikdən gəlmək)", "D": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı. («ağzı qulağına çatmaq» — qocalmaq)", "E": "Xəbəri eşidən rəis od püskürürdü. («od püskürmək» — çox zəhmət çəkmək)"}'::jsonb, 'B', NULL, '«əl uzatmaq» — kömək etmək.');
INSERT INTO public.questions VALUES (5148, 68, 'g10-aze-idiom-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə «çox sevinmək» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "İmtahan nəticəsini eşidən tələbənin sevincdən ağzı qulağına çatdı.", "B": "Fırıldaqçı sadəlövh alıcının başına papaq qoydu.", "C": "Atası çağıranda oğlan dilini dişləyib susdu.", "D": "Xəbəri eşidən rəis od püskürürdü.", "E": "Yaşlı ana illərlə oğlunun yolunu gözlədi, gözü yolda qaldı."}'::jsonb, 'A', NULL, 'Cümlədəki frazeologizmlər: «ağzı qulağına çatmaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (5149, 68, 'g10-aze-idiom-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə «çox sevinmək» mənasında frazeoloji birləşmə işlənib və cümlədə başqa frazeologizm yoxdur?', NULL, NULL, '{"A": "Satıcı müştərinin başını tovlayıb ona köhnə mal satdı.", "B": "Çalışqan gənclər əl-ələ verib kəndi abadlaşdırdılar.", "C": "Atası çağıranda oğlan dilini dişləyib susdu.", "D": "Komandamızın qələbəsindən sevinən azarkeşlər yerə-göyə sığmırdılar.", "E": "Rəhbər bəzi nöqsanlara göz yumurdu."}'::jsonb, 'D', NULL, 'Cümlədəki frazeologizmlər: «yerə-göyə sığmamaq» — çox sevinmək.');
INSERT INTO public.questions VALUES (5150, 68, 'g10-aze-idiom-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə iki frazeologizm işlənib və onlar mənaca bir-birinə yaxındır (sinonimdir)?', NULL, NULL, '{"A": "Nənəmin beli bükülsə də, bağda işləməyə davam edirdi.", "B": "Ağsaqqal ömrünün son günlərində dünyasını dəyişdi.", "C": "Xəbəri eşidən rəis od püskürürdü.", "D": "Tapşırığın mənasını ağlım kəsmədi.", "E": "Bu iş üçün o, dəridən-qabıqdan çıxdı, alın təri tökdü."}'::jsonb, 'E', NULL, 'Düzgün cümlədə: «dəridən-qabıqdan çıxmaq» — çox zəhmət çəkmək; «alın təri tökmək» — çox zəhmət çəkmək.');
INSERT INTO public.questions VALUES (5151, 69, 'g10-aze-isim-q1-01', 1, 1, 'medium', 'single', 'Hansı cümlədə «lüğət» ismi mənsubiyyətin I şəxs təkində işlənib və yönlük halındadır?', NULL, NULL, '{"A": "Müəllim sənin lüğətinə yüksək qiymət verdi.", "B": "Müəllim mənim lüğətimə yüksək qiymət verdi.", "C": "Müəllim onun lüğətinə yüksək qiymət verdi.", "D": "Mənim lüğətimdə bir neçə səhv tapdıq.", "E": "Müəllim bizim lüğətimizə yüksək qiymət verdi."}'::jsonb, 'B', NULL, '«lüğətimə» — I şəxs tək mənsubiyyət, yönlük hal (mənim lüğət). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5152, 69, 'g10-aze-isim-q1-02', 1, 2, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'C', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «qonaqlar» — isim, adlıq hal, mübtəda; «axşama» — isim, yönlük hal, zərflik. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5153, 69, 'g10-aze-isim-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə isim zərflik vəzifəsində işlənib, zərf yoxdur və bağlayıcı var?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Bağda alma, armud və heyva yetişmişdi.", "C": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "D": "Mən üzməyi yayda öyrəndim.", "E": "Sən ya rəsm, ya da musiqi seç."}'::jsonb, 'B', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «Bağda» — isim, yerlik hal, zərflik; «alma» — isim, adlıq hal, mübtəda; «armud» — isim, adlıq hal, mübtəda; «heyva» — isim, adlıq hal, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5154, 69, 'g10-aze-isim-q1-04', 1, 4, 'medium', 'single', 'Hansı cümlədə «məqalə» ismi mənsubiyyətin I şəxs təkində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Mənim məqaləm masanın üstündə qalıb.", "B": "Dostum mənim məqaləmi maraqla nəzərdən keçirdi.", "C": "Mənim məqaləmdə bir neçə səhv tapdıq.", "D": "Bizim məqaləmiz masanın üstündə qalıb.", "E": "Sənin məqalən masanın üstündə qalıb."}'::jsonb, 'A', NULL, '«məqaləm» — I şəxs tək mənsubiyyət, adlıq hal (mənim məqalə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5155, 69, 'g10-aze-isim-q1-05', 1, 5, 'medium', 'single', 'Hansı cümlədə 1 isim işlənib və zərflik yoxdur?', NULL, NULL, '{"A": "Ey gənclər, Vətəni sevin!", "B": "Həm oxuyur, həm də işləyir.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Danışmaq asandır."}'::jsonb, 'C', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «həqiqəti» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5156, 69, 'g10-aze-isim-q1-06', 1, 6, 'hard', 'single', '«Axı biz bu yolu tanımırıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 4", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'A', NULL, '«Axı biz bu yolu tanımırıq.»: «yolu» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5157, 69, 'g10-aze-isim-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə isim zərflik vəzifəsində işlənib, say yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Atam mənim üçün velosiped aldı.", "C": "Bağda alma, armud və heyva yetişmişdi.", "D": "Əlbəttə, biz sizə inanırıq.", "E": "Həm riyaziyyatı, həm də fizikanı sevirəm."}'::jsonb, 'C', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «Bağda» — isim, yerlik hal, zərflik; «alma» — isim, adlıq hal, mübtəda; «armud» — isim, adlıq hal, mübtəda; «heyva» — isim, adlıq hal, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5158, 69, 'g10-aze-isim-q1-08', 1, 8, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 4", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2"}'::jsonb, 'E', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «həqiqəti» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5159, 69, 'g10-aze-isim-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə təsirlik halında isim var, feili sifət yoxdur və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Ay Leyla, pəncərəni bağla!", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Biz iki-üç saat gözlədik.", "D": "Üç-dörd günə qədər işimizi bitirəcəyik.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'E', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «stansiyada» — isim, yerlik hal, zərflik; «qatarı» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5160, 69, 'g10-aze-isim-q1-10', 1, 10, 'hard', 'single', '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 1", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'B', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «dağın» — isim, yiyəlik hal, təyin; «zirvəsinə» — isim, yönlük hal, zərflik. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5161, 69, 'g10-aze-isim-q1-11', 1, 11, 'medium', 'single', 'Hansı cümlədə təsirlik halında isim var və modal söz yoxdur?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Biz iki-üç saat gözlədik.", "C": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "D": "Danışmaq asandır.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'C', NULL, '«Ucadan gülən uşaqlar müəllimi görüb susdular.»: «uşaqlar» — isim, adlıq hal, mübtəda; «müəllimi» — isim, təsirlik hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5162, 69, 'g10-aze-isim-q1-12', 1, 12, 'hard', 'single', '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "B": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0"}'::jsonb, 'D', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «əsgərlər» — isim, adlıq hal, mübtəda; «düşməni» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5163, 69, 'g10-aze-isim-q1-13', 1, 13, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1"}'::jsonb, 'B', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «quşu» — isim, təsirlik hal, vasitəsiz tamamlıq; «vaxtında» — isim, yerlik hal, zərflik; «həkimə» — isim, yönlük hal, vasitəli tamamlıq. Düzgün: isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5164, 69, 'g10-aze-isim-q1-14', 1, 14, 'medium', 'single', 'Hansı cümlədə «layihə» ismi mənsubiyyətin I şəxs təkində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Onun layihəsi masanın üstündə qalıb.", "B": "Tələbələr mənim layihəmdən çox şey öyrəndilər.", "C": "Dostum mənim layihəmi maraqla nəzərdən keçirdi.", "D": "Mənim layihəm masanın üstündə qalıb.", "E": "Mənim layihəmin cildi köhnəlib."}'::jsonb, 'D', NULL, '«layihəm» — I şəxs tək mənsubiyyət, adlıq hal (mənim layihə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5165, 69, 'g10-aze-isim-q1-15', 1, 15, 'medium', 'single', 'Hansı cümlədə 1 isim işlənib və müraciət yoxdur?', NULL, NULL, '{"A": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "B": "Məhz bu kənddə böyük şair doğulub.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "E": "Bu, lap yeni maşındır."}'::jsonb, 'E', NULL, '«Bu, lap yeni maşındır.»: «maşındır» — isim, adlıq hal, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5166, 69, 'g10-aze-isim-q1-16', 1, 16, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1"}'::jsonb, 'B', NULL, '«Atam mənim üçün velosiped aldı.»: «Atam» — isim, adlıq hal, mübtəda; «velosiped» — isim, adlıq hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5167, 69, 'g10-aze-isim-q1-17', 1, 17, 'medium', 'single', 'Hansı cümlədə «çanta» ismi mənsubiyyətin I şəxs təkində işlənib və yönlük halındadır?', NULL, NULL, '{"A": "Mənim çantamın cildi köhnəlib.", "B": "Dostum mənim çantamı maraqla nəzərdən keçirdi.", "C": "Müəllim sənin çantana yüksək qiymət verdi.", "D": "Müəllim mənim çantama yüksək qiymət verdi.", "E": "Mənim çantam masanın üstündə qalıb."}'::jsonb, 'D', NULL, '«çantama» — I şəxs tək mənsubiyyət, yönlük hal (mənim çanta). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5168, 69, 'g10-aze-isim-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə 2 isim işlənib, vasitəli tamamlıq yoxdur və mübtəda var?', NULL, NULL, '{"A": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "B": "Anam ilə atam toya getdilər.", "C": "Of, bu çanta ağırdır!", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı."}'::jsonb, 'A', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «əsgərlər» — isim, adlıq hal, mübtəda; «düşməni» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5169, 69, 'g10-aze-isim-q1-19', 1, 19, 'hard', 'single', '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 6; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "B": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "C": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "D": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1"}'::jsonb, 'D', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.»: «Qatar» — isim, adlıq hal, zərflik; «stansiyaya» — isim, yönlük hal, zərflik; «sərnişinlər» — isim, adlıq hal, mübtəda; «vaqonlardan» — isim, çıxışlıq hal, zərflik. Düzgün: isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5170, 69, 'g10-aze-isim-q1-20', 1, 20, 'medium', 'single', 'Hansı cümlədə «şeir» ismi mənsubiyyətin II şəxs təkində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Bizim şeirimiz masanın üstündə qalıb.", "B": "Sənin şeirin masanın üstündə qalıb.", "C": "Dostum sənin şeirini maraqla nəzərdən keçirdi.", "D": "Sizin şeiriniz masanın üstündə qalıb.", "E": "Müəllim sənin şeirinə yüksək qiymət verdi."}'::jsonb, 'B', NULL, '«şeirin» — II şəxs tək mənsubiyyət, adlıq hal (sənin şeir). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5171, 69, 'g10-aze-isim-q1-21', 1, 21, 'medium', 'single', 'Hansı cümlədə təsirlik halında isim var və təyin var?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Qoy hamı bu həqiqəti bilsin.", "C": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "D": "Biz stansiyada qatarı xeyli gözlədik.", "E": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək."}'::jsonb, 'B', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «həqiqəti» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5172, 69, 'g10-aze-isim-q1-22', 1, 22, 'medium', 'single', 'Hansı cümlədə «kitab» ismi mənsubiyyətin II şəxs təkində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Müəllim sənin kitabına yüksək qiymət verdi.", "B": "Mənim kitabımda bir neçə səhv tapdıq.", "C": "Sənin kitabında bir neçə səhv tapdıq.", "D": "Sənin kitabının cildi köhnəlib.", "E": "Tələbələr sənin kitabından çox şey öyrəndilər."}'::jsonb, 'C', NULL, '«kitabında» — II şəxs tək mənsubiyyət, yerlik hal (sənin kitab). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5173, 69, 'g10-aze-isim-q1-23', 1, 23, 'hard', 'single', '«Vay, buzlu yolda maşın sürüşdü!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0"}'::jsonb, 'C', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «yolda» — isim, yerlik hal, zərflik; «maşın» — isim, adlıq hal, mübtəda. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5174, 69, 'g10-aze-isim-q1-24', 1, 24, 'medium', 'single', 'Hansı cümlədə «dəftər» ismi mənsubiyyətin I şəxs cəmində işlənib və yönlük halındadır?', NULL, NULL, '{"A": "Tələbələr bizim dəftərimizdən çox şey öyrəndilər.", "B": "Müəllim sənin dəftərinə yüksək qiymət verdi.", "C": "Bizim dəftərimizdə bir neçə səhv tapdıq.", "D": "Bizim dəftərimiz masanın üstündə qalıb.", "E": "Müəllim bizim dəftərimizə yüksək qiymət verdi."}'::jsonb, 'E', NULL, '«dəftərimizə» — I şəxs cəm mənsubiyyət, yönlük hal (bizim dəftər). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5175, 69, 'g10-aze-isim-q1-25', 1, 25, 'medium', 'single', 'Hansı cümlədə «çanta» ismi mənsubiyyətin III şəxs təkində işlənib və təsirlik halındadır?', NULL, NULL, '{"A": "Onun çantasında bir neçə səhv tapdıq.", "B": "Dostum sizin çantanızı maraqla nəzərdən keçirdi.", "C": "Dostum mənim çantamı maraqla nəzərdən keçirdi.", "D": "Müəllim onun çantasına yüksək qiymət verdi.", "E": "Dostum onun çantasını maraqla nəzərdən keçirdi."}'::jsonb, 'E', NULL, '«çantasını» — III şəxs tək mənsubiyyət, təsirlik hal (onun çanta). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5176, 69, 'g10-aze-isim-q1-26', 1, 26, 'medium', 'single', 'Hansı cümlədə yerlik halında isim var və modal söz var?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "C": "Bir sözlə, hamı məmnun qaldı.", "D": "Əlbəttə, biz sizə inanırıq.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'A', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «quşu» — isim, təsirlik hal, vasitəsiz tamamlıq; «vaxtında» — isim, yerlik hal, zərflik; «həkimə» — isim, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5177, 69, 'g10-aze-isim-q1-27', 1, 27, 'medium', 'single', 'Hansı cümlədə «məktub» ismi mənsubiyyətin I şəxs təkində işlənib və yönlük halındadır?', NULL, NULL, '{"A": "Müəllim sənin məktubuna yüksək qiymət verdi.", "B": "Müəllim mənim məktubuma yüksək qiymət verdi.", "C": "Mənim məktubumun cildi köhnəlib.", "D": "Dostum mənim məktubumu maraqla nəzərdən keçirdi.", "E": "Mənim məktubumda bir neçə səhv tapdıq."}'::jsonb, 'B', NULL, '«məktubuma» — I şəxs tək mənsubiyyət, yönlük hal (mənim məktub). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5178, 69, 'g10-aze-isim-q1-28', 1, 28, 'hard', 'single', '«Əhsən! Bu rəsmi kim çəkib?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 0; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2"}'::jsonb, 'E', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «rəsmi» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5179, 69, 'g10-aze-isim-q1-29', 1, 29, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3", "C": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «çayın» — isim, yiyəlik hal, təyin; «sahili» — isim, adlıq hal, zərflik. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5180, 69, 'g10-aze-isim-q1-30', 1, 30, 'medium', 'single', 'Hansı cümlədə «məqalə» ismi mənsubiyyətin I şəxs təkində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Sənin məqaləndə bir neçə səhv tapdıq.", "B": "Bizim məqaləmizdə bir neçə səhv tapdıq.", "C": "Mənim məqaləmdə bir neçə səhv tapdıq.", "D": "Dostum mənim məqaləmi maraqla nəzərdən keçirdi.", "E": "Müəllim mənim məqaləmə yüksək qiymət verdi."}'::jsonb, 'C', NULL, '«məqaləmdə» — I şəxs tək mənsubiyyət, yerlik hal (mənim məqalə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5181, 69, 'g10-aze-isim-q2-01', 2, 1, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "D": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1"}'::jsonb, 'B', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «çayın» — isim, yiyəlik hal, təyin; «sahili» — isim, adlıq hal, zərflik. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5182, 69, 'g10-aze-isim-q2-02', 2, 2, 'medium', 'single', 'Hansı cümlədə «çanta» ismi mənsubiyyətin III şəxs təkində işlənib və yönlük halındadır?', NULL, NULL, '{"A": "Müəllim mənim çantama yüksək qiymət verdi.", "B": "Onun çantasında bir neçə səhv tapdıq.", "C": "Müəllim onun çantasına yüksək qiymət verdi.", "D": "Müəllim sizin çantanıza yüksək qiymət verdi.", "E": "Onun çantasının cildi köhnəlib."}'::jsonb, 'C', NULL, '«çantasına» — III şəxs tək mənsubiyyət, yönlük hal (onun çanta). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5183, 69, 'g10-aze-isim-q2-03', 2, 3, 'medium', 'single', 'Hansı cümlədə «layihə» ismi mənsubiyyətin II şəxs təkində işlənib və çıxışlıq halındadır?', NULL, NULL, '{"A": "Sənin layihənin cildi köhnəlib.", "B": "Sənin layihəndə bir neçə səhv tapdıq.", "C": "Tələbələr bizim layihəmizdən çox şey öyrəndilər.", "D": "Tələbələr sənin layihəndən çox şey öyrəndilər.", "E": "Dostum sənin layihəni maraqla nəzərdən keçirdi."}'::jsonb, 'D', NULL, '«layihəndən» — II şəxs tək mənsubiyyət, çıxışlıq hal (sənin layihə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5184, 69, 'g10-aze-isim-q2-04', 2, 4, 'hard', 'single', '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 5; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "B": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "C": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "D": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'C', NULL, '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.»: «həftə» — isim, adlıq hal, zərflik; «sinfimiz» — isim, adlıq hal, mübtəda; «təbiət» — isim, adlıq hal, təyin; «muzeyinə» — isim, yönlük hal, zərflik. Düzgün: isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5185, 69, 'g10-aze-isim-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə 1 isim işlənib, say yoxdur və zərflik var?', NULL, NULL, '{"A": "Məhz bu kənddə böyük şair doğulub.", "B": "Mən üzməyi yayda öyrəndim.", "C": "Uşaq vazanı bilərəkdən sındırmamışdı.", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular."}'::jsonb, 'B', NULL, '«Mən üzməyi yayda öyrəndim.»: «yayda» — isim, yerlik hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5186, 69, 'g10-aze-isim-q2-06', 2, 6, 'hard', 'single', '«Qardaşım məktubu qələm ilə yazdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «Qardaşım» — isim, adlıq hal, mübtəda; «məktubu» — isim, təsirlik hal, vasitəsiz tamamlıq; «qələm» — isim, adlıq hal, vasitəli tamamlıq. Düzgün: isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5187, 69, 'g10-aze-isim-q2-07', 2, 7, 'medium', 'single', 'Hansı cümlədə «lüğət» ismi mənsubiyyətin II şəxs təkində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Sənin lüğətinin cildi köhnəlib.", "B": "Tələbələr sənin lüğətindən çox şey öyrəndilər.", "C": "Sənin lüğətində bir neçə səhv tapdıq.", "D": "Sənin lüğətin masanın üstündə qalıb.", "E": "Onun lüğətində bir neçə səhv tapdıq."}'::jsonb, 'C', NULL, '«lüğətində» — II şəxs tək mənsubiyyət, yerlik hal (sənin lüğət). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5188, 69, 'g10-aze-isim-q2-08', 2, 8, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "D": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 0; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2"}'::jsonb, 'D', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «həqiqəti» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5189, 69, 'g10-aze-isim-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə isim vasitəsiz tamamlıq vəzifəsində işlənib, vasitəli tamamlıq yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Yağışa görə oyun dayandırıldı.", "B": "Biz sizdən sonra gəldik.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Biz iki-üç saat gözlədik.", "E": "Bu məktubu özüm yazacağam."}'::jsonb, 'E', NULL, '«Bu məktubu özüm yazacağam.»: «məktubu» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5190, 69, 'g10-aze-isim-q2-10', 2, 10, 'medium', 'single', 'Hansı cümlədə «çanta» ismi mənsubiyyətin I şəxs təkində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Mənim çantam masanın üstündə qalıb.", "B": "Mənim çantamda bir neçə səhv tapdıq.", "C": "Dostum mənim çantamı maraqla nəzərdən keçirdi.", "D": "Onun çantası masanın üstündə qalıb.", "E": "Müəllim mənim çantama yüksək qiymət verdi."}'::jsonb, 'A', NULL, '«çantam» — I şəxs tək mənsubiyyət, adlıq hal (mənim çanta). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5191, 69, 'g10-aze-isim-q2-11', 2, 11, 'hard', 'single', '«Qardaşım məktubu qələm ilə yazdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0"}'::jsonb, 'C', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «Qardaşım» — isim, adlıq hal, mübtəda; «məktubu» — isim, təsirlik hal, vasitəsiz tamamlıq; «qələm» — isim, adlıq hal, vasitəli tamamlıq. Düzgün: isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5192, 69, 'g10-aze-isim-q2-12', 2, 12, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «qızım» — isim, adlıq hal; «sözləri» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5193, 69, 'g10-aze-isim-q2-13', 2, 13, 'medium', 'single', 'Hansı cümlədə «məqalə» ismi mənsubiyyətin II şəxs təkində işlənib və təsirlik halındadır?', NULL, NULL, '{"A": "Sənin məqalənin cildi köhnəlib.", "B": "Tələbələr sənin məqaləndən çox şey öyrəndilər.", "C": "Dostum onun məqaləsini maraqla nəzərdən keçirdi.", "D": "Dostum sənin məqaləni maraqla nəzərdən keçirdi.", "E": "Sənin məqalən masanın üstündə qalıb."}'::jsonb, 'D', NULL, '«məqaləni» — II şəxs tək mənsubiyyət, təsirlik hal (sənin məqalə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5194, 69, 'g10-aze-isim-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə isim vasitəsiz tamamlıq vəzifəsində işlənib, modal söz var və zərf var?', NULL, NULL, '{"A": "Uşaq vazanı bilərəkdən sındırmamışdı.", "B": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "C": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "D": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "E": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular."}'::jsonb, 'C', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «xəbəri» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5195, 69, 'g10-aze-isim-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə isim vasitəsiz tamamlıq vəzifəsində işlənib, vasitəli tamamlıq yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Ay Leyla, pəncərəni bağla!", "C": "Bacım məndən kitab istədi.", "D": "Ay qızım, bu sözləri kimdən eşitdin?", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'B', NULL, '«Ay Leyla, pəncərəni bağla!»: «Leyla» — isim, adlıq hal; «pəncərəni» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5196, 69, 'g10-aze-isim-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə 2 isim işlənib, zərf yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "C": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "D": "Həm oxuyur, həm də işləyir.", "E": "Həm riyaziyyatı, həm də fizikanı sevirəm."}'::jsonb, 'E', NULL, '«Həm riyaziyyatı, həm də fizikanı sevirəm.»: «riyaziyyatı» — isim, təsirlik hal, vasitəsiz tamamlıq; «fizikanı» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5197, 69, 'g10-aze-isim-q2-17', 2, 17, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 5; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 4; əvəzlik — 0", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2"}'::jsonb, 'D', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «quşu» — isim, təsirlik hal, vasitəsiz tamamlıq; «vaxtında» — isim, yerlik hal, zərflik; «həkimə» — isim, yönlük hal, vasitəli tamamlıq. Düzgün: isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5198, 69, 'g10-aze-isim-q2-18', 2, 18, 'hard', 'single', '«Onuncu sinfin şagirdləri teatra getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "D": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Onuncu sinfin şagirdləri teatra getdilər.»: «sinfin» — isim, yiyəlik hal, təyin; «şagirdləri» — isim, adlıq hal, mübtəda; «teatra» — isim, yönlük hal, zərflik. Düzgün: isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5199, 69, 'g10-aze-isim-q2-19', 2, 19, 'hard', 'single', '«Ən çətin sualları hətta kiçik qardaşım tapdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Ən çətin sualları hətta kiçik qardaşım tapdı.»: «sualları» — isim, təsirlik hal, vasitəsiz tamamlıq; «qardaşım» — isim, adlıq hal, mübtəda. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5200, 69, 'g10-aze-isim-q2-20', 2, 20, 'hard', 'single', '«Məhz bu kənddə böyük şair doğulub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'D', NULL, '«Məhz bu kənddə böyük şair doğulub.»: «kənddə» — isim, yerlik hal, zərflik; «şair» — isim, adlıq hal, mübtəda. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5201, 69, 'g10-aze-isim-q2-21', 2, 21, 'medium', 'single', 'Hansı cümlədə «lüğət» ismi mənsubiyyətin I şəxs cəmində işlənib və çıxışlıq halındadır?', NULL, NULL, '{"A": "Tələbələr sənin lüğətindən çox şey öyrəndilər.", "B": "Tələbələr mənim lüğətimdən çox şey öyrəndilər.", "C": "Bizim lüğətimiz masanın üstündə qalıb.", "D": "Dostum bizim lüğətimizi maraqla nəzərdən keçirdi.", "E": "Tələbələr bizim lüğətimizdən çox şey öyrəndilər."}'::jsonb, 'E', NULL, '«lüğətimizdən» — I şəxs cəm mənsubiyyət, çıxışlıq hal (bizim lüğət). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5202, 69, 'g10-aze-isim-q2-22', 2, 22, 'medium', 'single', 'Hansı cümlədə «rəsm» ismi mənsubiyyətin II şəxs cəmində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Sizin rəsminiz masanın üstündə qalıb.", "B": "Müəllim sizin rəsminizə yüksək qiymət verdi.", "C": "Sizin rəsminizdə bir neçə səhv tapdıq.", "D": "Mənim rəsmim masanın üstündə qalıb.", "E": "Bizim rəsmimiz masanın üstündə qalıb."}'::jsonb, 'A', NULL, '«rəsminiz» — II şəxs cəm mənsubiyyət, adlıq hal (sizin rəsm). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5203, 69, 'g10-aze-isim-q2-23', 2, 23, 'medium', 'single', 'Hansı cümlədə «layihə» ismi mənsubiyyətin II şəxs cəmində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Tələbələr sizin layihənizdən çox şey öyrəndilər.", "B": "Sənin layihən masanın üstündə qalıb.", "C": "Sizin layihənizin cildi köhnəlib.", "D": "Sizin layihənizdə bir neçə səhv tapdıq.", "E": "Sizin layihəniz masanın üstündə qalıb."}'::jsonb, 'E', NULL, '«layihəniz» — II şəxs cəm mənsubiyyət, adlıq hal (sizin layihə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5204, 69, 'g10-aze-isim-q2-24', 2, 24, 'hard', 'single', '«Biz stansiyada qatarı xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 1", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 3", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2"}'::jsonb, 'D', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «stansiyada» — isim, yerlik hal, zərflik; «qatarı» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5205, 69, 'g10-aze-isim-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə yerlik halında isim var, qoşma yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "B": "Bacım məndən kitab istədi.", "C": "Bu məktubu özüm yazacağam.", "D": "Oxumaq insanı zənginləşdirir.", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'E', NULL, '«Hansı şəhərdə doğulmusan?»: «şəhərdə» — isim, yerlik hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5206, 69, 'g10-aze-isim-q2-26', 2, 26, 'medium', 'single', 'Hansı cümlədə «dəftər» ismi mənsubiyyətin III şəxs təkində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Müəllim onun dəftərinə yüksək qiymət verdi.", "B": "Onun dəftərində bir neçə səhv tapdıq.", "C": "Onun dəftəri masanın üstündə qalıb.", "D": "Onun dəftərinin cildi köhnəlib.", "E": "Bizim dəftərimizdə bir neçə səhv tapdıq."}'::jsonb, 'B', NULL, '«dəftərində» — III şəxs tək mənsubiyyət, yerlik hal (onun dəftər). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5207, 69, 'g10-aze-isim-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə yönlük halında isim var, say var və qoşma var?', NULL, NULL, '{"A": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "B": "Onuncu sinfin şagirdləri teatra getdilər.", "C": "Yarışa on səkkiz komanda qatıldı.", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Üç-dörd günə qədər işimizi bitirəcəyik."}'::jsonb, 'E', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «günə» — isim, yönlük hal, zərflik; «işimizi» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5208, 69, 'g10-aze-isim-q2-28', 2, 28, 'medium', 'single', 'Hansı cümlədə «çanta» ismi mənsubiyyətin III şəxs təkində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Onun çantasında bir neçə səhv tapdıq.", "B": "Bizim çantamızda bir neçə səhv tapdıq.", "C": "Onun çantasının cildi köhnəlib.", "D": "Müəllim onun çantasına yüksək qiymət verdi.", "E": "Mənim çantamda bir neçə səhv tapdıq."}'::jsonb, 'A', NULL, '«çantasında» — III şəxs tək mənsubiyyət, yerlik hal (onun çanta). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5209, 69, 'g10-aze-isim-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə 1 isim işlənib, mübtəda isimlə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ura, bayram gəldi!", "B": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "E": "Onuncu sinfin şagirdləri teatra getdilər."}'::jsonb, 'A', NULL, '«Ura, bayram gəldi!»: «bayram» — isim, adlıq hal, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5210, 69, 'g10-aze-isim-q2-30', 2, 30, 'medium', 'single', 'Hansı cümlədə «şeir» ismi mənsubiyyətin I şəxs cəmində işlənib və təsirlik halındadır?', NULL, NULL, '{"A": "Tələbələr bizim şeirimizdən çox şey öyrəndilər.", "B": "Dostum onun şeirini maraqla nəzərdən keçirdi.", "C": "Bizim şeirimiz masanın üstündə qalıb.", "D": "Dostum bizim şeirimizi maraqla nəzərdən keçirdi.", "E": "Bizim şeirimizin cildi köhnəlib."}'::jsonb, 'D', NULL, '«şeirimizi» — I şəxs cəm mənsubiyyət, təsirlik hal (bizim şeir). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5211, 69, 'g10-aze-isim-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə 2 isim işlənib, ədat yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Səndən başqa hamı gəldi.", "B": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "D": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "E": "Uşaq şirniyyatı gizlicə yedi."}'::jsonb, 'E', NULL, '«Uşaq şirniyyatı gizlicə yedi.»: «Uşaq» — isim, adlıq hal, mübtəda; «şirniyyatı» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5212, 69, 'g10-aze-isim-q3-02', 3, 2, 'medium', 'single', 'Hansı cümlədə «lüğət» ismi mənsubiyyətin I şəxs cəmində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Bizim lüğətimiz masanın üstündə qalıb.", "B": "Dostum bizim lüğətimizi maraqla nəzərdən keçirdi.", "C": "Bizim lüğətimizdə bir neçə səhv tapdıq.", "D": "Sənin lüğətində bir neçə səhv tapdıq.", "E": "Onun lüğətində bir neçə səhv tapdıq."}'::jsonb, 'C', NULL, '«lüğətimizdə» — I şəxs cəm mənsubiyyət, yerlik hal (bizim lüğət). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5213, 69, 'g10-aze-isim-q3-03', 3, 3, 'hard', 'single', '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "B": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1", "C": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 4; əvəzlik — 0", "D": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.»: «Qatar» — isim, adlıq hal, zərflik; «stansiyaya» — isim, yönlük hal, zərflik; «sərnişinlər» — isim, adlıq hal, mübtəda; «vaqonlardan» — isim, çıxışlıq hal, zərflik. Düzgün: isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5214, 69, 'g10-aze-isim-q3-04', 3, 4, 'medium', 'single', 'Hansı cümlədə yönlük halında isim var və feili bağlama yoxdur?', NULL, NULL, '{"A": "Uşaq şirniyyatı gizlicə yedi.", "B": "Ay qızım, bu sözləri kimdən eşitdin?", "C": "Of, bu çanta ağırdır!", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'D', NULL, '«O, ikinci dəfə bu şəhərə gəlir.»: «dəfə» — isim, adlıq hal, zərflik; «şəhərə» — isim, yönlük hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5215, 69, 'g10-aze-isim-q3-05', 3, 5, 'medium', 'single', 'Hansı cümlədə «rəsm» ismi mənsubiyyətin III şəxs təkində işlənib və yönlük halındadır?', NULL, NULL, '{"A": "Müəllim mənim rəsmimə yüksək qiymət verdi.", "B": "Onun rəsmi masanın üstündə qalıb.", "C": "Müəllim sənin rəsminə yüksək qiymət verdi.", "D": "Tələbələr onun rəsmindən çox şey öyrəndilər.", "E": "Müəllim onun rəsminə yüksək qiymət verdi."}'::jsonb, 'E', NULL, '«rəsminə» — III şəxs tək mənsubiyyət, yönlük hal (onun rəsm). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5216, 69, 'g10-aze-isim-q3-06', 3, 6, 'hard', 'single', '«Axı biz bu yolu tanımırıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "D": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3"}'::jsonb, 'D', NULL, '«Axı biz bu yolu tanımırıq.»: «yolu» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5217, 69, 'g10-aze-isim-q3-07', 3, 7, 'medium', 'single', 'Hansı cümlədə isim zərflik vəzifəsində işlənib və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Yazılmış məktubu poçta apardım.", "B": "Qoy hamı bu həqiqəti bilsin.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Bəs sən hara gedirsən?", "E": "Tortun dörddə birini qonaqlara verdik."}'::jsonb, 'A', NULL, '«Yazılmış məktubu poçta apardım.»: «məktubu» — isim, təsirlik hal, vasitəsiz tamamlıq; «poçta» — isim, yönlük hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5218, 69, 'g10-aze-isim-q3-08', 3, 8, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 3; əvəzlik — 0", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 1", "D": "isim — 5; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «quşu» — isim, təsirlik hal, vasitəsiz tamamlıq; «vaxtında» — isim, yerlik hal, zərflik; «həkimə» — isim, yönlük hal, vasitəli tamamlıq. Düzgün: isim — 3; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5219, 69, 'g10-aze-isim-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə isim vasitəsiz tamamlıq vəzifəsində işlənib, zərf yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Hansı şəhərdə doğulmusan?", "C": "Axı biz bu yolu tanımırıq.", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'C', NULL, '«Axı biz bu yolu tanımırıq.»: «yolu» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5220, 69, 'g10-aze-isim-q3-10', 3, 10, 'medium', 'single', 'Hansı cümlədə «şeir» ismi mənsubiyyətin III şəxs təkində işlənib və yiyəlik halındadır?', NULL, NULL, '{"A": "Onun şeiri masanın üstündə qalıb.", "B": "Onun şeirinin cildi köhnəlib.", "C": "Bizim şeirimizin cildi köhnəlib.", "D": "Dostum onun şeirini maraqla nəzərdən keçirdi.", "E": "Mənim şeirimin cildi köhnəlib."}'::jsonb, 'B', NULL, '«şeirinin» — III şəxs tək mənsubiyyət, yiyəlik hal (onun şeir). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5221, 69, 'g10-aze-isim-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə 3 isim işlənib, mübtəda var və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Bir sözlə, hamı məmnun qaldı.", "B": "Məhz bu kənddə böyük şair doğulub.", "C": "Yarışa on səkkiz komanda qatıldı.", "D": "Onuncu sinfin şagirdləri teatra getdilər.", "E": "Bəs sən hara gedirsən?"}'::jsonb, 'D', NULL, '«Onuncu sinfin şagirdləri teatra getdilər.»: «sinfin» — isim, yiyəlik hal, təyin; «şagirdləri» — isim, adlıq hal, mübtəda; «teatra» — isim, yönlük hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5222, 69, 'g10-aze-isim-q3-12', 3, 12, 'medium', 'single', 'Hansı cümlədə «məktub» ismi mənsubiyyətin I şəxs cəmində işlənib və təsirlik halındadır?', NULL, NULL, '{"A": "Dostum sənin məktubunu maraqla nəzərdən keçirdi.", "B": "Dostum onun məktubunu maraqla nəzərdən keçirdi.", "C": "Dostum bizim məktubumuzu maraqla nəzərdən keçirdi.", "D": "Dostum mənim məktubumu maraqla nəzərdən keçirdi.", "E": "Bizim məktubumuzun cildi köhnəlib."}'::jsonb, 'C', NULL, '«məktubumuzu» — I şəxs cəm mənsubiyyət, təsirlik hal (bizim məktub). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5223, 69, 'g10-aze-isim-q3-13', 3, 13, 'medium', 'single', 'Hansı cümlədə «kitab» ismi mənsubiyyətin II şəxs təkində işlənib və yiyəlik halındadır?', NULL, NULL, '{"A": "Bizim kitabımızın cildi köhnəlib.", "B": "Sənin kitabının cildi köhnəlib.", "C": "Mənim kitabımın cildi köhnəlib.", "D": "Sənin kitabında bir neçə səhv tapdıq.", "E": "Müəllim sənin kitabına yüksək qiymət verdi."}'::jsonb, 'B', NULL, '«kitabının» — II şəxs tək mənsubiyyət, yiyəlik hal (sənin kitab). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5224, 69, 'g10-aze-isim-q3-14', 3, 14, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "D": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 4; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2"}'::jsonb, 'C', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «qızım» — isim, adlıq hal; «sözləri» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5225, 69, 'g10-aze-isim-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə 2 isim işlənib, feili sifət yoxdur və sifət var?', NULL, NULL, '{"A": "Atam mənim üçün velosiped aldı.", "B": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "C": "Vay, buzlu yolda maşın sürüşdü!", "D": "Yağışa görə oyun dayandırıldı.", "E": "Həm riyaziyyatı, həm də fizikanı sevirəm."}'::jsonb, 'C', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «yolda» — isim, yerlik hal, zərflik; «maşın» — isim, adlıq hal, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5226, 69, 'g10-aze-isim-q3-16', 3, 16, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2", "D": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1"}'::jsonb, 'D', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «həqiqəti» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5227, 69, 'g10-aze-isim-q3-17', 3, 17, 'hard', 'single', '«Ucadan gülən uşaqlar müəllimi görüb susdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "B": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "D": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 0"}'::jsonb, 'C', NULL, '«Ucadan gülən uşaqlar müəllimi görüb susdular.»: «uşaqlar» — isim, adlıq hal, mübtəda; «müəllimi» — isim, təsirlik hal, zərflik. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5228, 69, 'g10-aze-isim-q3-18', 3, 18, 'medium', 'single', 'Hansı cümlədə isim zərflik vəzifəsində işlənib və modal söz var?', NULL, NULL, '{"A": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Heç nə demədən otaqdan çıxdı.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'E', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «quşu» — isim, təsirlik hal, vasitəsiz tamamlıq; «vaxtında» — isim, yerlik hal, zərflik; «həkimə» — isim, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5229, 69, 'g10-aze-isim-q3-19', 3, 19, 'medium', 'single', 'Hansı cümlədə «məqalə» ismi mənsubiyyətin III şəxs təkində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Dostum onun məqaləsini maraqla nəzərdən keçirdi.", "B": "Onun məqaləsində bir neçə səhv tapdıq.", "C": "Onun məqaləsinin cildi köhnəlib.", "D": "Müəllim onun məqaləsinə yüksək qiymət verdi.", "E": "Onun məqaləsi masanın üstündə qalıb."}'::jsonb, 'E', NULL, '«məqaləsi» — III şəxs tək mənsubiyyət, adlıq hal (onun məqalə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5230, 69, 'g10-aze-isim-q3-20', 3, 20, 'medium', 'single', 'Hansı cümlədə «kitab» ismi mənsubiyyətin II şəxs təkində işlənib və yerlik halındadır?', NULL, NULL, '{"A": "Mənim kitabımda bir neçə səhv tapdıq.", "B": "Dostum sənin kitabını maraqla nəzərdən keçirdi.", "C": "Sənin kitabında bir neçə səhv tapdıq.", "D": "Sizin kitabınızda bir neçə səhv tapdıq.", "E": "Bizim kitabımızda bir neçə səhv tapdıq."}'::jsonb, 'C', NULL, '«kitabında» — II şəxs tək mənsubiyyət, yerlik hal (sənin kitab). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5231, 69, 'g10-aze-isim-q3-21', 3, 21, 'hard', 'single', '«Biz stansiyada qatarı xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 1", "C": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1", "D": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 0", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 3"}'::jsonb, 'C', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «stansiyada» — isim, yerlik hal, zərflik; «qatarı» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5232, 69, 'g10-aze-isim-q3-22', 3, 22, 'medium', 'single', 'Hansı cümlədə «məktub» ismi mənsubiyyətin I şəxs cəmində işlənib və çıxışlıq halındadır?', NULL, NULL, '{"A": "Tələbələr bizim məktubumuzdan çox şey öyrəndilər.", "B": "Bizim məktubumuzda bir neçə səhv tapdıq.", "C": "Tələbələr mənim məktubumdan çox şey öyrəndilər.", "D": "Tələbələr onun məktubundan çox şey öyrəndilər.", "E": "Tələbələr sənin məktubundan çox şey öyrəndilər."}'::jsonb, 'A', NULL, '«məktubumuzdan» — I şəxs cəm mənsubiyyət, çıxışlıq hal (bizim məktub). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5233, 69, 'g10-aze-isim-q3-23', 3, 23, 'hard', 'single', '«Əhsən! Bu rəsmi kim çəkib?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 0; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "C": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "D": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3", "E": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2"}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «rəsmi» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5234, 69, 'g10-aze-isim-q3-24', 3, 24, 'medium', 'single', 'Hansı cümlədə «hekayə» ismi mənsubiyyətin II şəxs cəmində işlənib və çıxışlıq halındadır?', NULL, NULL, '{"A": "Sizin hekayənizdə bir neçə səhv tapdıq.", "B": "Müəllim sizin hekayənizə yüksək qiymət verdi.", "C": "Dostum sizin hekayənizi maraqla nəzərdən keçirdi.", "D": "Tələbələr sizin hekayənizdən çox şey öyrəndilər.", "E": "Sizin hekayənizin cildi köhnəlib."}'::jsonb, 'D', NULL, '«hekayənizdən» — II şəxs cəm mənsubiyyət, çıxışlıq hal (sizin hekayə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5235, 69, 'g10-aze-isim-q3-25', 3, 25, 'medium', 'single', 'Hansı cümlədə «rəsm» ismi mənsubiyyətin I şəxs cəmində işlənib və adlıq halındadır?', NULL, NULL, '{"A": "Dostum bizim rəsmimizi maraqla nəzərdən keçirdi.", "B": "Onun rəsmi masanın üstündə qalıb.", "C": "Bizim rəsmimizdə bir neçə səhv tapdıq.", "D": "Bizim rəsmimiz masanın üstündə qalıb.", "E": "Mənim rəsmim masanın üstündə qalıb."}'::jsonb, 'D', NULL, '«rəsmimiz» — I şəxs cəm mənsubiyyət, adlıq hal (bizim rəsm). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5236, 69, 'g10-aze-isim-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə yiyəlik halında isim var, zərf var və qoşma var?', NULL, NULL, '{"A": "Biz çayın sahili ilə xeyli getdik.", "B": "Uşaq vazanı bilərəkdən sındırmamışdı.", "C": "Onuncu sinfin şagirdləri teatra getdilər.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Tortun dörddə birini qonaqlara verdik."}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «çayın» — isim, yiyəlik hal, təyin; «sahili» — isim, adlıq hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5237, 69, 'g10-aze-isim-q3-27', 3, 27, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "B": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 2; əvəzlik — 2", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3", "E": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 1"}'::jsonb, 'A', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «qızım» — isim, adlıq hal; «sözləri» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5238, 69, 'g10-aze-isim-q3-28', 3, 28, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 1; əvəzlik — 2", "B": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "C": "isim — 3; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "D": "isim — 2; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2", "E": "isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 3"}'::jsonb, 'B', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «həqiqəti» — isim, təsirlik hal, vasitəsiz tamamlıq. Düzgün: isim — 1; yönlük, yerlik və çıxışlıq halında isim — 0; əvəzlik — 2.');
INSERT INTO public.questions VALUES (5239, 69, 'g10-aze-isim-q3-29', 3, 29, 'medium', 'single', 'Hansı cümlədə «hekayə» ismi mənsubiyyətin III şəxs təkində işlənib və yiyəlik halındadır?', NULL, NULL, '{"A": "Onun hekayəsinin cildi köhnəlib.", "B": "Sizin hekayənizin cildi köhnəlib.", "C": "Müəllim onun hekayəsinə yüksək qiymət verdi.", "D": "Mənim hekayəmin cildi köhnəlib.", "E": "Sənin hekayənin cildi köhnəlib."}'::jsonb, 'A', NULL, '«hekayəsinin» — III şəxs tək mənsubiyyət, yiyəlik hal (onun hekayə). II və III şəxsin təkində bəzi formalar eyni yazılır (kitabına), şəxsi əvəzlik müəyyən edir.');
INSERT INTO public.questions VALUES (5240, 69, 'g10-aze-isim-q3-30', 3, 30, 'medium', 'single', 'Hansı cümlədə 1 isim işlənib və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Anam ilə atam toya getdilər.", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Yağışa görə oyun dayandırıldı."}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «rəsmi» — isim, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5241, 70, 'g10-aze-sifet-q1-01', 1, 1, 'hard', 'single', '«Vay, buzlu yolda maşın sürüşdü!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 2; əvəzlik — 0", "B": "sifət — 1; isim — 4; əvəzlik — 0", "C": "sifət — 2; isim — 2; əvəzlik — 0", "D": "sifət — 3; isim — 2; əvəzlik — 0", "E": "sifət — 1; isim — 2; əvəzlik — 2"}'::jsonb, 'A', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «buzlu» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5242, 70, 'g10-aze-sifet-q1-02', 1, 2, 'hard', 'single', '«Ən çətin sualları hətta kiçik qardaşım tapdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 3; isim — 1; əvəzlik — 0", "B": "sifət — 2; isim — 2; əvəzlik — 0", "C": "sifət — 1; isim — 2; əvəzlik — 0", "D": "sifət — 2; isim — 2; əvəzlik — 1", "E": "sifət — 4; isim — 2; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Ən çətin sualları hətta kiçik qardaşım tapdı.»: «çətin» — sifət, təyin; «kiçik» — sifət, təyin. Düzgün: sifət — 2; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5243, 70, 'g10-aze-sifet-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə sifət xəbər vəzifəsində işlənib, say yoxdur və mübtəda var?', NULL, NULL, '{"A": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "B": "Uşaq şirniyyatı gizlicə yedi.", "C": "Danışmaq asandır.", "D": "Sərnişinlər avtobusa dalbadal mindilər.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'C', NULL, '«Danışmaq asandır.»: «asandır» — sifət, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5244, 70, 'g10-aze-sifet-q1-04', 1, 4, 'hard', 'single', '«Vay, buzlu yolda maşın sürüşdü!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 3; əvəzlik — 0", "B": "sifət — 2; isim — 2; əvəzlik — 0", "C": "sifət — 1; isim — 2; əvəzlik — 1", "D": "sifət — 1; isim — 2; əvəzlik — 0", "E": "sifət — 1; isim — 1; əvəzlik — 0"}'::jsonb, 'D', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «buzlu» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5245, 70, 'g10-aze-sifet-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib, feili bağlama yoxdur və təyin var?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Bu məktubu özüm yazacağam.", "C": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "D": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "E": "Üç-dörd günə qədər işimizi bitirəcəyik."}'::jsonb, 'A', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «buzlu» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5246, 70, 'g10-aze-sifet-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə 1 sifət işlənib, ədat yoxdur və mübtəda var?', NULL, NULL, '{"A": "Danışmaq asandır.", "B": "Təəssüf ki, mən toya getmədim.", "C": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "D": "Bu məktubu özüm yazacağam.", "E": "Ura, bayram gəldi!"}'::jsonb, 'A', NULL, '«Danışmaq asandır.»: «asandır» — sifət, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5247, 70, 'g10-aze-sifet-q1-07', 1, 7, 'hard', 'single', '«Vay, buzlu yolda maşın sürüşdü!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 2; əvəzlik — 0", "B": "sifət — 1; isim — 1; əvəzlik — 0", "C": "sifət — 1; isim — 2; əvəzlik — 1", "D": "sifət — 1; isim — 4; əvəzlik — 0", "E": "sifət — 0; isim — 2; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «buzlu» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5248, 70, 'g10-aze-sifet-q1-08', 1, 8, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 3; əvəzlik — 0", "B": "sifət — 0; isim — 3; əvəzlik — 0", "C": "sifət — 1; isim — 2; əvəzlik — 0", "D": "sifət — 1; isim — 3; əvəzlik — 1", "E": "sifət — 1; isim — 3; əvəzlik — 2"}'::jsonb, 'A', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «yaralı» — sifət, təyin. Düzgün: sifət — 1; isim — 3; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5249, 70, 'g10-aze-sifet-q1-09', 1, 9, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 2; əvəzlik — 2", "B": "sifət — 1; isim — 2; əvəzlik — 1", "C": "sifət — 2; isim — 2; əvəzlik — 0", "D": "sifət — 1; isim — 4; əvəzlik — 1", "E": "sifət — 2; isim — 1; əvəzlik — 1"}'::jsonb, 'B', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «təzə» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5250, 70, 'g10-aze-sifet-q1-10', 1, 10, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 2; əvəzlik — 1", "B": "sifət — 2; isim — 2; əvəzlik — 0", "C": "sifət — 1; isim — 3; əvəzlik — 0", "D": "sifət — 1; isim — 3; əvəzlik — 1", "E": "sifət — 1; isim — 2; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «təzə» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5251, 70, 'g10-aze-sifet-q1-11', 1, 11, 'medium', 'single', 'Hansı cümlədə 1 sifət işlənib və zərflik yoxdur?', NULL, NULL, '{"A": "Ay Leyla, pəncərəni bağla!", "B": "Axı biz bu yolu tanımırıq.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "E": "Ən çətin sualları hətta kiçik qardaşım tapdı."}'::jsonb, 'D', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «təzə» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5252, 70, 'g10-aze-sifet-q1-12', 1, 12, 'medium', 'single', 'Hansı cümlədə 1 sifət işlənib və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "B": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "C": "Bu, lap yeni maşındır.", "D": "Biz çayın sahili ilə xeyli getdik.", "E": "O, ikinci dəfə bu şəhərə gəlir."}'::jsonb, 'C', NULL, '«Bu, lap yeni maşındır.»: «yeni» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5253, 70, 'g10-aze-sifet-q1-13', 1, 13, 'medium', 'single', 'Hansı cümlədə sifət xəbər vəzifəsində işlənib və zərflik yoxdur?', NULL, NULL, '{"A": "Bir sözlə, hamı məmnun qaldı.", "B": "Ey gənclər, Vətəni sevin!", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Oxumaq insanı zənginləşdirir.", "E": "Sən ya rəsm, ya da musiqi seç."}'::jsonb, 'A', NULL, '«Bir sözlə, hamı məmnun qaldı.»: «məmnun» — sifət, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5254, 70, 'g10-aze-sifet-q1-14', 1, 14, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 3; əvəzlik — 1", "B": "sifət — 2; isim — 3; əvəzlik — 0", "C": "sifət — 1; isim — 2; əvəzlik — 0", "D": "sifət — 2; isim — 2; əvəzlik — 0", "E": "sifət — 1; isim — 3; əvəzlik — 0"}'::jsonb, 'E', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «yaralı» — sifət, təyin. Düzgün: sifət — 1; isim — 3; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5255, 70, 'g10-aze-sifet-q1-15', 1, 15, 'hard', 'single', '«Ah, köhnə dostumu uzun müddət görmədim!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 2; isim — 2; əvəzlik — 2", "B": "sifət — 1; isim — 2; əvəzlik — 0", "C": "sifət — 2; isim — 2; əvəzlik — 0", "D": "sifət — 2; isim — 1; əvəzlik — 0", "E": "sifət — 3; isim — 2; əvəzlik — 0"}'::jsonb, 'C', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «köhnə» — sifət, təyin; «uzun» — sifət, təyin. Düzgün: sifət — 2; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5256, 70, 'g10-aze-sifet-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə 1 sifət işlənib, vasitəli tamamlıq var və modal söz var?', NULL, NULL, '{"A": "Əlbəttə, biz sizə inanırıq.", "B": "Bu, lap yeni maşındır.", "C": "Bir sözlə, hamı məmnun qaldı.", "D": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "E": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı."}'::jsonb, 'D', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «yaralı» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5257, 70, 'g10-aze-sifet-q1-17', 1, 17, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 2; isim — 2; əvəzlik — 1", "B": "sifət — 1; isim — 2; əvəzlik — 1", "C": "sifət — 1; isim — 2; əvəzlik — 2", "D": "sifət — 1; isim — 1; əvəzlik — 1", "E": "sifət — 1; isim — 2; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «təzə» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5258, 70, 'g10-aze-sifet-q1-18', 1, 18, 'medium', 'single', 'Hansı cümlədə sifət vasitəsiz tamamlığı izah edir və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Ah, köhnə dostumu uzun müddət görmədim!", "B": "Of, bu çanta ağırdır!", "C": "Heç nə demədən otaqdan çıxdı.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Axı biz bu yolu tanımırıq."}'::jsonb, 'A', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «köhnə» — sifət, təyin; «uzun» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
