INSERT INTO public.questions VALUES (5280, 70, 'g10-aze-sifet-q2-10', 2, 10, 'medium', 'single', 'Hansı cümlədə sifət xəbər vəzifəsində işlənib və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "O, ikinci dəfə bu şəhərə gəlir.", "B": "Hansı şəhərdə doğulmusan?", "C": "Danışmaq asandır.", "D": "Yağışa görə oyun dayandırıldı.", "E": "Təəssüf ki, mən toya getmədim."}'::jsonb, 'C', NULL, '«Danışmaq asandır.»: «asandır» — sifət, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5281, 70, 'g10-aze-sifet-q2-11', 2, 11, 'hard', 'single', '«Ən çətin sualları hətta kiçik qardaşım tapdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 2; isim — 4; əvəzlik — 0", "B": "sifət — 3; isim — 2; əvəzlik — 0", "C": "sifət — 2; isim — 2; əvəzlik — 0", "D": "sifət — 2; isim — 2; əvəzlik — 2", "E": "sifət — 3; isim — 1; əvəzlik — 0"}'::jsonb, 'C', NULL, '«Ən çətin sualları hətta kiçik qardaşım tapdı.»: «çətin» — sifət, təyin; «kiçik» — sifət, təyin. Düzgün: sifət — 2; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5282, 70, 'g10-aze-sifet-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə sifət xəbər vəzifəsində işlənib, qoşma yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "D": "Vay, buzlu yolda maşın sürüşdü!", "E": "Bir sözlə, hamı məmnun qaldı."}'::jsonb, 'E', NULL, '«Bir sözlə, hamı məmnun qaldı.»: «məmnun» — sifət, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5283, 70, 'g10-aze-sifet-q2-13', 2, 13, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 3; isim — 2; əvəzlik — 1", "B": "sifət — 1; isim — 2; əvəzlik — 1", "C": "sifət — 1; isim — 2; əvəzlik — 0", "D": "sifət — 1; isim — 2; əvəzlik — 3", "E": "sifət — 1; isim — 3; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «təzə» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5284, 70, 'g10-aze-sifet-q2-14', 2, 14, 'medium', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib və qoşma yoxdur?', NULL, NULL, '{"A": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "B": "Ay qızım, bu sözləri kimdən eşitdin?", "C": "Bu, lap yeni maşındır.", "D": "Ura, bayram gəldi!", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'C', NULL, '«Bu, lap yeni maşındır.»: «yeni» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5285, 70, 'g10-aze-sifet-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə 1 sifət işlənib, vasitəli tamamlıq yoxdur və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "B": "Dərslərini oxumadan oynamağa getdi.", "C": "Məhz bu kənddə böyük şair doğulub.", "D": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "E": "Ura, bayram gəldi!"}'::jsonb, 'C', NULL, '«Məhz bu kənddə böyük şair doğulub.»: «böyük» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
