INSERT INTO public.questions VALUES (5304, 70, 'g10-aze-sifet-q3-04', 3, 4, 'hard', 'single', '«Məhz bu kənddə böyük şair doğulub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "sifət — 1; isim — 3; əvəzlik — 1", "B": "sifət — 1; isim — 2; əvəzlik — 1", "C": "sifət — 2; isim — 2; əvəzlik — 0", "D": "sifət — 2; isim — 1; əvəzlik — 1", "E": "sifət — 1; isim — 2; əvəzlik — 3"}'::jsonb, 'B', NULL, '«Məhz bu kənddə böyük şair doğulub.»: «böyük» — sifət, təyin. Düzgün: sifət — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5305, 70, 'g10-aze-sifet-q3-05', 3, 5, 'medium', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib və feili bağlama yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Ya sabah, ya da birigün gələcəyəm.", "C": "Of, bu çanta ağırdır!", "D": "Ura, bayram gəldi!", "E": "Mən üzməyi yayda öyrəndim."}'::jsonb, 'A', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «yaralı» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5306, 70, 'g10-aze-sifet-q3-06', 3, 6, 'medium', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib və müraciət yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Of, bu çanta ağırdır!", "C": "Vay, buzlu yolda maşın sürüşdü!", "D": "Danışmaq asandır.", "E": "O, ikinci dəfə bu şəhərə gəlir."}'::jsonb, 'C', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «buzlu» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5307, 70, 'g10-aze-sifet-q3-07', 3, 7, 'medium', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib və müraciət yoxdur?', NULL, NULL, '{"A": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "B": "Yalnız zəhmət insanı ucaldır.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Qoy hamı bu həqiqəti bilsin."}'::jsonb, 'A', NULL, '«Ən çətin sualları hətta kiçik qardaşım tapdı.»: «çətin» — sifət, təyin; «kiçik» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
