INSERT INTO public.questions VALUES (5330, 70, 'g10-aze-sifet-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib, feili bağlama yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Yazılmış məktubu poçta apardım.", "B": "Məhz bu kənddə böyük şair doğulub.", "C": "Biz stansiyada qatarı xeyli gözlədik.", "D": "Biz iki-üç saat gözlədik.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'B', NULL, '«Məhz bu kənddə böyük şair doğulub.»: «böyük» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5331, 71, 'g10-aze-say-q1-01', 1, 1, 'medium', 'single', 'Hansı cümlədə 1 say işlənib və məsdər yoxdur?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Üç-dörd günə qədər işimizi bitirəcəyik.", "C": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Ah, köhnə dostumu uzun müddət görmədim!"}'::jsonb, 'B', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «Üç-dörd» — təxmini say, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
