INSERT INTO public.questions VALUES (5405, 71, 'g10-aze-say-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə təxmini say var, nida yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Hansı şəhərdə doğulmusan?", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Biz iki-üç saat gözlədik.", "D": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'C', NULL, '«Biz iki-üç saat gözlədik.»: «iki-üç» — təxmini say, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
