INSERT INTO public.questions VALUES (5426, 72, 'g10-aze-evez-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə işarə əvəzliyi var, məsdər yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "B": "Təəssüf ki, mən toya getmədim.", "C": "Qardaşım məktubu qələm ilə yazdı.", "D": "Ey gənclər, Vətəni sevin!", "E": "O, ikinci dəfə bu şəhərə gəlir."}'::jsonb, 'E', NULL, '«O, ikinci dəfə bu şəhərə gəlir.»: «O» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
