INSERT INTO public.questions VALUES (5428, 72, 'g10-aze-evez-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə təyini əvəzlik var, vasitəli tamamlıq yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Məhz bu kənddə böyük şair doğulub.", "C": "Biz çayın sahili ilə xeyli getdik.", "D": "Qoy hamı bu həqiqəti bilsin.", "E": "Ah, köhnə dostumu uzun müddət görmədim!"}'::jsonb, 'D', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «hamı» — təyini əvəzlik, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5429, 72, 'g10-aze-evez-q1-09', 1, 9, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 4; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 0"}'::jsonb, 'B', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «bu» — işarə əvəzliyi, təyin; «kimdən» — sual əvəzliyi, çıxışlıq hal, vasitəli tamamlıq. Düzgün: əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (5430, 72, 'g10-aze-evez-q1-10', 1, 10, 'hard', 'single', '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "B": "əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "E": "əvəzlik — 3; isim — 4; şəxs əvəzliyi — 0"}'::jsonb, 'A', NULL, '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.»: «hər» — təyini əvəzlik, təyin. Düzgün: əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (5431, 72, 'g10-aze-evez-q1-11', 1, 11, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "B": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5432, 72, 'g10-aze-evez-q1-12', 1, 12, 'medium', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib və say var?', NULL, NULL, '{"A": "O, ikinci dəfə bu şəhərə gəlir.", "B": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "C": "Bəs sən hara gedirsən?", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'A', NULL, '«O, ikinci dəfə bu şəhərə gəlir.»: «O» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
