INSERT INTO public.questions VALUES (5450, 72, 'g10-aze-evez-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, vasitəli tamamlıq yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Ey gənclər, Vətəni sevin!", "B": "Axı biz bu yolu tanımırıq.", "C": "Bu, lap yeni maşındır.", "D": "Biz iki-üç saat gözlədik.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'B', NULL, '«Axı biz bu yolu tanımırıq.»: «biz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5451, 72, 'g10-aze-evez-q2-01', 2, 1, 'medium', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib və say yoxdur?', NULL, NULL, '{"A": "Mən üzməyi yayda öyrəndim.", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Oxumaq insanı zənginləşdirir.", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'E', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5452, 72, 'g10-aze-evez-q2-02', 2, 2, 'hard', 'single', '«Biz stansiyada qatarı xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5453, 72, 'g10-aze-evez-q2-03', 2, 3, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'C', NULL, '«Atam mənim üçün velosiped aldı.»: «mənim» — şəxs əvəzliyi, yiyəlik hal, vasitəli tamamlıq. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5454, 72, 'g10-aze-evez-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə qayıdış əvəzliyi var, vasitəli tamamlıq yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Bu məktubu özüm yazacağam.", "B": "Oxumaq insanı zənginləşdirir.", "C": "Sən ya rəsm, ya da musiqi seç.", "D": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "E": "Ehtimal ki, qonaqlar axşama kimi gələcəklər."}'::jsonb, 'A', NULL, '«Bu məktubu özüm yazacağam.»: «Bu» — işarə əvəzliyi, təyin; «özüm» — qayıdış əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5455, 72, 'g10-aze-evez-q2-05', 2, 5, 'hard', 'single', '«Biz stansiyada qatarı xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1"}'::jsonb, 'B', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5456, 72, 'g10-aze-evez-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə 2 əvəzlik işlənib, feili sifət yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Tortun dörddə birini qonaqlara verdik.", "B": "Yarışa on səkkiz komanda qatıldı.", "C": "O, ikinci dəfə bu şəhərə gəlir.", "D": "Həm oxuyur, həm də işləyir.", "E": "Ah, köhnə dostumu uzun müddət görmədim!"}'::jsonb, 'C', NULL, '«O, ikinci dəfə bu şəhərə gəlir.»: «O» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5457, 72, 'g10-aze-evez-q2-07', 2, 7, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "B": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5458, 72, 'g10-aze-evez-q2-08', 2, 8, 'medium', 'single', 'Hansı cümlədə yiyəlik halında əvəzlik var və nida yoxdur?', NULL, NULL, '{"A": "Atam mənim üçün velosiped aldı.", "B": "Danışmaq asandır.", "C": "Anam ilə atam toya getdilər.", "D": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'A', NULL, '«Atam mənim üçün velosiped aldı.»: «mənim» — şəxs əvəzliyi, yiyəlik hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5459, 72, 'g10-aze-evez-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, say yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Dərslərini oxumadan oynamağa getdi.", "B": "Qardaşım məktubu qələm ilə yazdı.", "C": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "D": "Biz çayın sahili ilə xeyli getdik.", "E": "Danışmaq asandır."}'::jsonb, 'D', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «Biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5460, 72, 'g10-aze-evez-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, feili bağlama yoxdur və təyin var?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Üç-dörd günə qədər işimizi bitirəcəyik.", "E": "Ay qızım, bu sözləri kimdən eşitdin?"}'::jsonb, 'C', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «hamı» — təyini əvəzlik, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5461, 72, 'g10-aze-evez-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, zərflik yoxdur və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Biz sizdən sonra gəldik.", "B": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "C": "Bir sözlə, hamı məmnun qaldı.", "D": "Ura, bayram gəldi!", "E": "Bəs sən hara gedirsən?"}'::jsonb, 'C', NULL, '«Bir sözlə, hamı məmnun qaldı.»: «hamı» — təyini əvəzlik, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
