INSERT INTO public.questions VALUES (5472, 72, 'g10-aze-evez-q2-22', 2, 22, 'hard', 'single', '«Əhsən! Bu rəsmi kim çəkib?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 2", "B": "əvəzlik — 2; isim — 0; şəxs əvəzliyi — 0", "C": "əvəzlik — 3; isim — 0; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 0"}'::jsonb, 'D', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Bu» — işarə əvəzliyi, təyin; «kim» — sual əvəzliyi, mübtəda. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (5473, 72, 'g10-aze-evez-q2-23', 2, 23, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 1"}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5474, 72, 'g10-aze-evez-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, müraciət yoxdur və zərflik yoxdur?', NULL, NULL, '{"A": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "D": "Məhz bu kənddə böyük şair doğulub.", "E": "Danışmaq asandır."}'::jsonb, 'C', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5475, 72, 'g10-aze-evez-q2-25', 2, 25, 'hard', 'single', '«Əhsən! Bu rəsmi kim çəkib?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 2", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 4; isim — 1; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 0; şəxs əvəzliyi — 0"}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Bu» — işarə əvəzliyi, təyin; «kim» — sual əvəzliyi, mübtəda. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (5476, 72, 'g10-aze-evez-q2-26', 2, 26, 'hard', 'single', '«Axı biz bu yolu tanımırıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 2"}'::jsonb, 'C', NULL, '«Axı biz bu yolu tanımırıq.»: «biz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5477, 72, 'g10-aze-evez-q2-27', 2, 27, 'hard', 'single', '«Axı biz bu yolu tanımırıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 0; şəxs əvəzliyi — 1", "B": "əvəzlik — 3; isim — 0; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 3", "E": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1"}'::jsonb, 'C', NULL, '«Axı biz bu yolu tanımırıq.»: «biz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5478, 72, 'g10-aze-evez-q2-28', 2, 28, 'medium', 'single', 'Hansı cümlədə çıxışlıq halında əvəzlik var və zərf yoxdur?', NULL, NULL, '{"A": "Bu məktubu özüm yazacağam.", "B": "Ura, bayram gəldi!", "C": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "D": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "E": "Ay qızım, bu sözləri kimdən eşitdin?"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «bu» — işarə əvəzliyi, təyin; «kimdən» — sual əvəzliyi, çıxışlıq hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5479, 72, 'g10-aze-evez-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, zərf var və sifət yoxdur?', NULL, NULL, '{"A": "Əhsən! Bu rəsmi kim çəkib?", "B": "Ya sabah, ya da birigün gələcəyəm.", "C": "O, ikinci dəfə bu şəhərə gəlir.", "D": "Biz iki-üç saat gözlədik.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'E', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5480, 72, 'g10-aze-evez-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə işarə əvəzliyi var, feili bağlama yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Sərnişinlər avtobusa dalbadal mindilər.", "B": "Məhz bu kənddə böyük şair doğulub.", "C": "Biz çayın sahili ilə xeyli getdik.", "D": "Ay qızım, bu sözləri kimdən eşitdin?", "E": "Bağda alma, armud və heyva yetişmişdi."}'::jsonb, 'D', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «bu» — işarə əvəzliyi, təyin; «kimdən» — sual əvəzliyi, çıxışlıq hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5481, 72, 'g10-aze-evez-q3-01', 3, 1, 'medium', 'single', 'Hansı cümlədə şəxs əvəzliyi var və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Qardaşım məktubu qələm ilə yazdı.", "C": "Bağda alma, armud və heyva yetişmişdi.", "D": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "E": "Sərnişinlər avtobusa dalbadal mindilər."}'::jsonb, 'D', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
