INSERT INTO public.questions VALUES (5494, 72, 'g10-aze-evez-q3-14', 3, 14, 'medium', 'single', 'Hansı cümlədə işarə əvəzliyi var və feili sifət yoxdur?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Of, bu çanta ağırdır!", "C": "Bacım məndən kitab istədi.", "D": "Biz sizdən sonra gəldik.", "E": "Heç nə demədən otaqdan çıxdı."}'::jsonb, 'B', NULL, '«Of, bu çanta ağırdır!»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5495, 72, 'g10-aze-evez-q3-15', 3, 15, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2"}'::jsonb, 'D', NULL, '«Atam mənim üçün velosiped aldı.»: «mənim» — şəxs əvəzliyi, yiyəlik hal, vasitəli tamamlıq. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5496, 72, 'g10-aze-evez-q3-16', 3, 16, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2", "C": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'D', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5497, 72, 'g10-aze-evez-q3-17', 3, 17, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "B": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'C', NULL, '«Atam mənim üçün velosiped aldı.»: «mənim» — şəxs əvəzliyi, yiyəlik hal, vasitəli tamamlıq. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5498, 72, 'g10-aze-evez-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, vasitəsiz tamamlıq yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Atam mənim üçün velosiped aldı.", "B": "Bacım məndən kitab istədi.", "C": "Of, bu çanta ağırdır!", "D": "Dərslərini oxumadan oynamağa getdi.", "E": "Onuncu sinfin şagirdləri teatra getdilər."}'::jsonb, 'C', NULL, '«Of, bu çanta ağırdır!»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5499, 72, 'g10-aze-evez-q3-19', 3, 19, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'A', NULL, '«Atam mənim üçün velosiped aldı.»: «mənim» — şəxs əvəzliyi, yiyəlik hal, vasitəli tamamlıq. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5500, 72, 'g10-aze-evez-q3-20', 3, 20, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 2", "E": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'A', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «bu» — işarə əvəzliyi, təyin; «kimdən» — sual əvəzliyi, çıxışlıq hal, vasitəli tamamlıq. Düzgün: əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (5501, 72, 'g10-aze-evez-q3-21', 3, 21, 'hard', 'single', '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "B": "əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0", "C": "əvəzlik — 0; isim — 4; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0"}'::jsonb, 'E', NULL, '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.»: «hər» — təyini əvəzlik, təyin. Düzgün: əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (5502, 72, 'g10-aze-evez-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə yönlük halında əvəzlik var, vasitəsiz tamamlıq yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "B": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "E": "Ura, bayram gəldi!"}'::jsonb, 'C', NULL, '«Əlbəttə, biz sizə inanırıq.»: «biz» — şəxs əvəzliyi, mübtəda; «sizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5503, 72, 'g10-aze-evez-q3-23', 3, 23, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "B": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Atam mənim üçün velosiped aldı.»: «mənim» — şəxs əvəzliyi, yiyəlik hal, vasitəli tamamlıq. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5504, 72, 'g10-aze-evez-q3-24', 3, 24, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "B": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "E": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1"}'::jsonb, 'C', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (5505, 72, 'g10-aze-evez-q3-25', 3, 25, 'medium', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib və zərf yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "B": "Anam ilə atam toya getdilər.", "C": "Yazılmış məktubu poçta apardım.", "D": "Bağda alma, armud və heyva yetişmişdi.", "E": "Axı biz bu yolu tanımırıq."}'::jsonb, 'E', NULL, '«Axı biz bu yolu tanımırıq.»: «biz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5506, 72, 'g10-aze-evez-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə 1 əvəzlik işlənib və sifət yoxdur?', NULL, NULL, '{"A": "Oxumaq insanı zənginləşdirir.", "B": "Axı biz bu yolu tanımırıq.", "C": "Yağışa görə oyun dayandırıldı.", "D": "Hansı şəhərdə doğulmusan?", "E": "Ehtimal ki, qonaqlar axşama kimi gələcəklər."}'::jsonb, 'D', NULL, '«Hansı şəhərdə doğulmusan?»: «Hansı» — sual əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5507, 72, 'g10-aze-evez-q3-27', 3, 27, 'medium', 'single', 'Hansı cümlədə çıxışlıq halında əvəzlik var və nida yoxdur?', NULL, NULL, '{"A": "Biz çayın sahili ilə xeyli getdik.", "B": "Anam ilə atam toya getdilər.", "C": "Biz sizdən sonra gəldik.", "D": "Yazılmış məktubu poçta apardım.", "E": "Qardaşım məktubu qələm ilə yazdı."}'::jsonb, 'C', NULL, '«Biz sizdən sonra gəldik.»: «Biz» — şəxs əvəzliyi, mübtəda; «sizdən» — şəxs əvəzliyi, çıxışlıq hal, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5508, 72, 'g10-aze-evez-q3-28', 3, 28, 'medium', 'single', 'Hansı cümlədə işarə əvəzliyi var və say yoxdur?', NULL, NULL, '{"A": "Mahnı oxuya-oxuya işləyirdi.", "B": "Səndən başqa hamı gəldi.", "C": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'D', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Bu» — işarə əvəzliyi, təyin; «kim» — sual əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5509, 72, 'g10-aze-evez-q3-29', 3, 29, 'medium', 'single', 'Hansı cümlədə təyini əvəzlik var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Bağda alma, armud və heyva yetişmişdi.", "C": "Bacım məndən kitab istədi.", "D": "Mən üzməyi yayda öyrəndim.", "E": "Qoy hamı bu həqiqəti bilsin."}'::jsonb, 'E', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «hamı» — təyini əvəzlik, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5510, 72, 'g10-aze-evez-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, ədat yoxdur və zərf var?', NULL, NULL, '{"A": "Mən üzməyi yayda öyrəndim.", "B": "Biz iki-üç saat gözlədik.", "C": "Uşaq vazanı bilərəkdən sındırmamışdı.", "D": "Bu məktubu özüm yazacağam.", "E": "Biz dağın zirvəsinə doğru yuxarı qalxdıq."}'::jsonb, 'E', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «Biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5511, 73, 'g10-aze-feil-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, zərf yoxdur və təyin var?', NULL, NULL, '{"A": "Bu, lap yeni maşındır.", "B": "Vay, buzlu yolda maşın sürüşdü!", "C": "Ura, bayram gəldi!", "D": "Of, bu çanta ağırdır!", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'B', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «sürüşdü» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5512, 73, 'g10-aze-feil-q1-02', 1, 2, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 1", "E": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'A', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «gülümsəyən» — feili sifət, təyin; «uzatdı» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (5513, 73, 'g10-aze-feil-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Mən bu mahnını sevəcəyəm.", "B": "Onlar bu mahnını sevirlər.", "C": "Siz bu mahnını sevəcəksiniz.", "D": "O, bu mahnını sevəcək.", "E": "Onlar bu mahnını sevəcəklər."}'::jsonb, 'E', NULL, '«sevəcəklər» — qəti gələcək zaman, III şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (5514, 73, 'g10-aze-feil-q1-04', 1, 4, 'medium', 'single', 'Hansı cümlədə məsdər var və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Biz iki-üç saat gözlədik.", "B": "Mən üzməyi yayda öyrəndim.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Danışmaq asandır.", "E": "Biz dağın zirvəsinə doğru yuxarı qalxdıq."}'::jsonb, 'D', NULL, '«Danışmaq asandır.»: «Danışmaq» — məsdər, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5515, 73, 'g10-aze-feil-q1-05', 1, 5, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 1", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'D', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «gülümsəyən» — feili sifət, təyin; «uzatdı» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (5516, 73, 'g10-aze-feil-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, bileti almayacaq.", "B": "O, bileti alacaq.", "C": "Mən bileti alacağam.", "D": "Siz bileti alacaqsınız.", "E": "O, bileti aldı."}'::jsonb, 'B', NULL, '«alacaq» — qəti gələcək zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (5517, 73, 'g10-aze-feil-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Sən tapşırığı unutursan.", "B": "Mən tapşırığı unutmuram.", "C": "Sən tapşırığı unutmayacaqsan.", "D": "Sən tapşırığı unutmursan.", "E": "Siz tapşırığı unutmursunuz."}'::jsonb, 'D', NULL, '«unutmursan» — indiki zaman, II şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5518, 73, 'g10-aze-feil-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, vasitəsiz tamamlıq var və say yoxdur?', NULL, NULL, '{"A": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "B": "Bağda alma, armud və heyva yetişmişdi.", "C": "Biz sizdən sonra gəldik.", "D": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "E": "Qardaşım məktubu qələm ilə yazdı."}'::jsonb, 'E', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «yazdı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5519, 73, 'g10-aze-feil-q1-09', 1, 9, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və zərf yoxdur?', NULL, NULL, '{"A": "Sərnişinlər avtobusa dalbadal mindilər.", "B": "Uşaq şirniyyatı gizlicə yedi.", "C": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'E', NULL, '«Hansı şəhərdə doğulmusan?»: «doğulmusan» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5520, 73, 'g10-aze-feil-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən kitabı oxudun.", "B": "Onlar kitabı oxudular.", "C": "Biz kitabı oxuduq.", "D": "Biz kitabı oxuyuruq.", "E": "Biz kitabı oxumadıq."}'::jsonb, 'C', NULL, '«oxuduq» — şühudi keçmiş zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (5521, 73, 'g10-aze-feil-q1-11', 1, 11, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'A', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «çatdırdıq» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3.');
INSERT INTO public.questions VALUES (5522, 73, 'g10-aze-feil-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili sifət yoxdur və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Vay, buzlu yolda maşın sürüşdü!", "C": "Tortun dörddə birini qonaqlara verdik.", "D": "Ah, köhnə dostumu uzun müddət görmədim!", "E": "Ey gənclər, Vətəni sevin!"}'::jsonb, 'B', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «sürüşdü» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5523, 73, 'g10-aze-feil-q1-13', 1, 13, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Ah, köhnə dostumu uzun müddət görmədim!", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Həm oxuyur, həm də işləyir.", "D": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "E": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular."}'::jsonb, 'B', NULL, '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.»: «yaşayan» — feili sifət, təyin; «qaçır» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5524, 73, 'g10-aze-feil-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Mən kitabı oxuyacağam.", "B": "Mən kitabı oxumuram.", "C": "Onlar kitabı oxumayacaqlar.", "D": "Mən kitabı oxumayacağam.", "E": "Biz kitabı oxumayacağıq."}'::jsonb, 'D', NULL, '«oxumayacağam» — qəti gələcək zaman, I şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5525, 73, 'g10-aze-feil-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, evi tikməyəcək.", "B": "Mən evi tikəcəyəm.", "C": "Siz evi tikməyəcəksiniz.", "D": "Mən evi tikməyəcəyəm.", "E": "Mən evi tikmirəm."}'::jsonb, 'D', NULL, '«tikməyəcəyəm» — qəti gələcək zaman, I şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5526, 73, 'g10-aze-feil-q1-16', 1, 16, 'hard', 'single', '«Üç-dörd günə qədər işimizi bitirəcəyik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'D', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «bitirəcəyik» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5527, 73, 'g10-aze-feil-q1-17', 1, 17, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'D', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «getdik» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5528, 73, 'g10-aze-feil-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, II şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Sən evi tikdin.", "B": "Siz evi tikmədiniz.", "C": "Sən evi tikmirsən.", "D": "Sən evi tikmədin.", "E": "Biz evi tikmədik."}'::jsonb, 'D', NULL, '«tikmədin» — şühudi keçmiş zaman, II şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5529, 73, 'g10-aze-feil-q1-19', 1, 19, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və feili bağlama yoxdur?', NULL, NULL, '{"A": "Bu, lap yeni maşındır.", "B": "Danışmaq asandır.", "C": "Bağda alma, armud və heyva yetişmişdi.", "D": "Mahnı oxuya-oxuya işləyirdi.", "E": "Heç nə demədən otaqdan çıxdı."}'::jsonb, 'C', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «yetişmişdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5530, 73, 'g10-aze-feil-q1-20', 1, 20, 'hard', 'single', '«Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3", "D": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 1; isim — 3", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'E', NULL, '«Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.»: «götürdüyüm» — feili sifət, təyin; «qaytardım» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3.');
INSERT INTO public.questions VALUES (5531, 73, 'g10-aze-feil-q1-21', 1, 21, 'hard', 'single', '«Kimsə həyətdə ucadan mahnı oxuyurdu.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'C', NULL, '«Kimsə həyətdə ucadan mahnı oxuyurdu.»: «oxuyurdu» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5532, 73, 'g10-aze-feil-q1-22', 1, 22, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "B": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 0", "E": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 1"}'::jsonb, 'A', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «bilsin» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1.');
INSERT INTO public.questions VALUES (5533, 73, 'g10-aze-feil-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, cavabı bilməyəcək.", "B": "Siz cavabı bilməyəcəksiniz.", "C": "Onlar cavabı bilməyəcəklər.", "D": "Onlar cavabı biləcəklər.", "E": "Biz cavabı bilməyəcəyik."}'::jsonb, 'C', NULL, '«bilməyəcəklər» — qəti gələcək zaman, III şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (5534, 73, 'g10-aze-feil-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Siz açarı tapmayacaqsınız.", "B": "Mən açarı tapmayacağam.", "C": "Onlar açarı tapmayacaqlar.", "D": "Sən açarı tapmayacaqsan.", "E": "Biz açarı tapmayacağıq."}'::jsonb, 'E', NULL, '«tapmayacağıq» — qəti gələcək zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (5535, 73, 'g10-aze-feil-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, müraciət yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Həm oxuyur, həm də işləyir.", "B": "Qoy hamı bu həqiqəti bilsin.", "C": "Vay, buzlu yolda maşın sürüşdü!", "D": "Danışmaq asandır.", "E": "Əhsən! Bu rəsmi kim çəkib?"}'::jsonb, 'B', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «bilsin» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5536, 73, 'g10-aze-feil-q1-26', 1, 26, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "D": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'C', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «gülümsəyən» — feili sifət, təyin; «uzatdı» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (5537, 73, 'g10-aze-feil-q1-27', 1, 27, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və feili sifət yoxdur?', NULL, NULL, '{"A": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "B": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "C": "Yazılmış məktubu poçta apardım.", "D": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "E": "Yalnız zəhmət insanı ucaldır."}'::jsonb, 'E', NULL, '«Yalnız zəhmət insanı ucaldır.»: «ucaldır» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5538, 73, 'g10-aze-feil-q1-28', 1, 28, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Bu məktubu özüm yazacağam.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'B', NULL, '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.»: «yaşayan» — feili sifət, təyin; «qaçır» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5539, 73, 'g10-aze-feil-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, lövhəni silir.", "B": "Sən lövhəni silirsən.", "C": "Biz lövhəni silirik.", "D": "Sən lövhəni sildin.", "E": "Siz lövhəni silirsiniz."}'::jsonb, 'B', NULL, '«silirsən» — indiki zaman, II şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (5540, 73, 'g10-aze-feil-q1-30', 1, 30, 'hard', 'single', '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'B', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.»: «çatan kimi» — feili bağlama, zərflik; «düşdülər» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4.');
INSERT INTO public.questions VALUES (5541, 73, 'g10-aze-feil-q2-01', 2, 1, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və modal söz yoxdur?', NULL, NULL, '{"A": "Of, bu çanta ağırdır!", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "D": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "E": "Heç nə demədən otaqdan çıxdı."}'::jsonb, 'E', NULL, '«Heç nə demədən otaqdan çıxdı.»: «demədən» — feili bağlama, zərflik; «çıxdı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5542, 73, 'g10-aze-feil-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, II şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Siz tapşırığı unutmayacaqsınız.", "B": "Mən tapşırığı unutmayacağam.", "C": "O, tapşırığı unutmayacaq.", "D": "Sən tapşırığı unutmayacaqsan.", "E": "Biz tapşırığı unutmayacağıq."}'::jsonb, 'D', NULL, '«unutmayacaqsan» — qəti gələcək zaman, II şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5543, 73, 'g10-aze-feil-q2-03', 2, 3, 'hard', 'single', '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "D": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 2"}'::jsonb, 'A', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «vuruşan» — feili sifət, təyin; «oturtdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (5544, 73, 'g10-aze-feil-q2-04', 2, 4, 'hard', 'single', '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 6", "B": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 3", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 4", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4"}'::jsonb, 'E', NULL, '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.»: «Gələn» — feili sifət, təyin; «gedəcək» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4.');
INSERT INTO public.questions VALUES (5545, 73, 'g10-aze-feil-q2-05', 2, 5, 'hard', 'single', '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 6", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'B', NULL, '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.»: «Gələn» — feili sifət, təyin; «gedəcək» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4.');
INSERT INTO public.questions VALUES (5546, 73, 'g10-aze-feil-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, I şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Siz qapını açmırsınız.", "B": "Mən qapını açmadım.", "C": "O, qapını açmır.", "D": "Sən qapını açmırsan.", "E": "Mən qapını açmıram."}'::jsonb, 'E', NULL, '«açmıram» — indiki zaman, I şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5547, 73, 'g10-aze-feil-q2-07', 2, 7, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və qoşma yoxdur?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Tortun dörddə birini qonaqlara verdik.", "D": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'C', NULL, '«Tortun dörddə birini qonaqlara verdik.»: «verdik» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5548, 73, 'g10-aze-feil-q2-08', 2, 8, 'hard', 'single', '«Ucadan gülən uşaqlar müəllimi görüb susdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 2"}'::jsonb, 'A', NULL, '«Ucadan gülən uşaqlar müəllimi görüb susdular.»: «gülən» — feili sifət, təyin; «görüb» — feili bağlama, zərflik; «susdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2.');
INSERT INTO public.questions VALUES (5549, 73, 'g10-aze-feil-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, təyin var və nida yoxdur?', NULL, NULL, '{"A": "Ya sabah, ya da birigün gələcəyəm.", "B": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "C": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "D": "Atam mənim üçün velosiped aldı.", "E": "Dərslərini oxumadan oynamağa getdi."}'::jsonb, 'B', NULL, '«Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.»: «götürdüyüm» — feili sifət, təyin; «qaytardım» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5550, 73, 'g10-aze-feil-q2-10', 2, 10, 'hard', 'single', '«Ən çətin sualları hətta kiçik qardaşım tapdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'C', NULL, '«Ən çətin sualları hətta kiçik qardaşım tapdı.»: «tapdı» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5551, 73, 'g10-aze-feil-q2-11', 2, 11, 'hard', 'single', '«Üç-dörd günə qədər işimizi bitirəcəyik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'E', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «bitirəcəyik» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5552, 73, 'g10-aze-feil-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Siz lövhəni silmədiniz.", "B": "Biz lövhəni sildik.", "C": "Biz lövhəni silmədik.", "D": "Sən lövhəni silmədin.", "E": "Biz lövhəni silməyəcəyik."}'::jsonb, 'C', NULL, '«silmədik» — şühudi keçmiş zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (5553, 73, 'g10-aze-feil-q2-13', 2, 13, 'hard', 'single', '«Ucadan gülən uşaqlar müəllimi görüb susdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 4; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'E', NULL, '«Ucadan gülən uşaqlar müəllimi görüb susdular.»: «gülən» — feili sifət, təyin; «görüb» — feili bağlama, zərflik; «susdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2.');
INSERT INTO public.questions VALUES (5554, 73, 'g10-aze-feil-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, pəncərəni bağlamadı.", "B": "O, pəncərəni bağladı.", "C": "Sən pəncərəni bağladın.", "D": "O, pəncərəni bağlayır.", "E": "Biz pəncərəni bağladıq."}'::jsonb, 'B', NULL, '«bağladı» — şühudi keçmiş zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (5555, 73, 'g10-aze-feil-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, II şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Siz tamaşanı görmədiniz.", "B": "Mən tamaşanı gördüm.", "C": "Siz tamaşanı gördünüz.", "D": "Onlar tamaşanı gördülər.", "E": "Biz tamaşanı gördük."}'::jsonb, 'C', NULL, '«gördünüz» — şühudi keçmiş zaman, II şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (5556, 73, 'g10-aze-feil-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, modal söz yoxdur və say yoxdur?', NULL, NULL, '{"A": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "B": "Üç-dörd günə qədər işimizi bitirəcəyik.", "C": "Həm oxuyur, həm də işləyir.", "D": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "E": "Yağışa görə oyun dayandırıldı."}'::jsonb, 'E', NULL, '«Yağışa görə oyun dayandırıldı.»: «dayandırıldı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5557, 73, 'g10-aze-feil-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Biz tapşırığı unutmuruq.", "B": "Sən tapşırığı unutmayacaqsan.", "C": "Siz tapşırığı unutmayacaqsınız.", "D": "Onlar tapşırığı unutmayacaqlar.", "E": "Biz tapşırığı unutmayacağıq."}'::jsonb, 'E', NULL, '«unutmayacağıq» — qəti gələcək zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (5558, 73, 'g10-aze-feil-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, qapını açmayacaq.", "B": "O, qapını açır.", "C": "O, qapını açacaq.", "D": "Mən qapını açacağam.", "E": "O, qapını açdı."}'::jsonb, 'C', NULL, '«açacaq» — qəti gələcək zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (5559, 73, 'g10-aze-feil-q2-19', 2, 19, 'medium', 'single', 'Hansı cümlədə feili bağlama var və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "B": "Uşaq şirniyyatı gizlicə yedi.", "C": "Mahnı oxuya-oxuya işləyirdi.", "D": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'C', NULL, '«Mahnı oxuya-oxuya işləyirdi.»: «oxuya-oxuya» — feili bağlama, zərflik; «işləyirdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5560, 73, 'g10-aze-feil-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, mübtəda yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Ya sabah, ya da birigün gələcəyəm.", "B": "Uşaq şirniyyatı gizlicə yedi.", "C": "Bu məktubu özüm yazacağam.", "D": "Təəssüf ki, mən toya getmədim.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'A', NULL, '«Ya sabah, ya da birigün gələcəyəm.»: «gələcəyəm» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5561, 73, 'g10-aze-feil-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, çantanı götürəcək.", "B": "Siz çantanı götürürsünüz.", "C": "O, çantanı götürdü.", "D": "Sən çantanı götürürsən.", "E": "O, çantanı götürür."}'::jsonb, 'E', NULL, '«götürür» — indiki zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (5562, 73, 'g10-aze-feil-q2-22', 2, 22, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1"}'::jsonb, 'C', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «getdik» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5563, 73, 'g10-aze-feil-q2-23', 2, 23, 'medium', 'single', 'Hansı cümlədə feili bağlama var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Mahnı oxuya-oxuya işləyirdi.", "D": "Ura, bayram gəldi!", "E": "O, ikinci dəfə bu şəhərə gəlir."}'::jsonb, 'C', NULL, '«Mahnı oxuya-oxuya işləyirdi.»: «oxuya-oxuya» — feili bağlama, zərflik; «işləyirdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5564, 73, 'g10-aze-feil-q2-24', 2, 24, 'hard', 'single', '«Ah, köhnə dostumu uzun müddət görmədim!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'D', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «görmədim» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5565, 73, 'g10-aze-feil-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Biz evi tikmədik.", "B": "Sən evi tikmədin.", "C": "Biz evi tikdik.", "D": "Biz evi tikmirik.", "E": "O, evi tikmədi."}'::jsonb, 'A', NULL, '«tikmədik» — şühudi keçmiş zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (5566, 73, 'g10-aze-feil-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, vasitəli tamamlıq yoxdur və say yoxdur?', NULL, NULL, '{"A": "Atam mənim üçün velosiped aldı.", "B": "Həm oxuyur, həm də işləyir.", "C": "Qardaşım məktubu qələm ilə yazdı.", "D": "Danışmaq asandır.", "E": "Məhz bu kənddə böyük şair doğulub."}'::jsonb, 'E', NULL, '«Məhz bu kənddə böyük şair doğulub.»: «doğulub» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5567, 73, 'g10-aze-feil-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən qapını açacaqsan.", "B": "Biz qapını açırıq.", "C": "Siz qapını açacaqsınız.", "D": "Biz qapını açacağıq.", "E": "Mən qapını açacağam."}'::jsonb, 'D', NULL, '«açacağıq» — qəti gələcək zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (5568, 73, 'g10-aze-feil-q2-28', 2, 28, 'hard', 'single', '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'C', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «vuruşan» — feili sifət, təyin; «oturtdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (5569, 73, 'g10-aze-feil-q2-29', 2, 29, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və ədat yoxdur?', NULL, NULL, '{"A": "Yalnız zəhmət insanı ucaldır.", "B": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "D": "Axı biz bu yolu tanımırıq.", "E": "Həm oxuyur, həm də işləyir."}'::jsonb, 'B', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.»: «çatan kimi» — feili bağlama, zərflik; «düşdülər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5570, 73, 'g10-aze-feil-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, modal söz yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Ya sabah, ya da birigün gələcəyəm.", "B": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "C": "Bəs sən hara gedirsən?", "D": "Anam ilə atam toya getdilər.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'C', NULL, '«Bəs sən hara gedirsən?»: «gedirsən» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5571, 73, 'g10-aze-feil-q3-01', 3, 1, 'hard', 'single', '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 4", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 4"}'::jsonb, 'D', NULL, '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.»: «yaşayan» — feili sifət, təyin; «qaçır» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4.');
INSERT INTO public.questions VALUES (5572, 73, 'g10-aze-feil-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, modal söz yoxdur və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Axı biz bu yolu tanımırıq.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'E', NULL, '«Biz sizdən sonra gəldik.»: «gəldik» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5573, 73, 'g10-aze-feil-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, kitabı oxumadı.", "B": "Siz kitabı oxumayacaqsınız.", "C": "O, kitabı oxumayacaq.", "D": "Sən kitabı oxumayacaqsan.", "E": "O, kitabı oxumur."}'::jsonb, 'C', NULL, '«oxumayacaq» — qəti gələcək zaman, III şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5574, 73, 'g10-aze-feil-q3-04', 3, 4, 'hard', 'single', '«Ah, köhnə dostumu uzun müddət görmədim!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'E', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «görmədim» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5575, 73, 'g10-aze-feil-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Siz məktubu yazırsınız.", "B": "O, məktubu yazır.", "C": "Siz məktubu yazacaqsınız.", "D": "Biz məktubu yazırıq.", "E": "Onlar məktubu yazırlar."}'::jsonb, 'A', NULL, '«yazırsınız» — indiki zaman, II şəxs cəm, təsdiq forması.');
