INSERT INTO public.questions VALUES (5577, 73, 'g10-aze-feil-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Biz şeiri öyrənirik.", "B": "O, şeiri öyrəndi.", "C": "Siz şeiri öyrənirsiniz.", "D": "O, şeiri öyrənir.", "E": "O, şeiri öyrənmir."}'::jsonb, 'D', NULL, '«öyrənir» — indiki zaman, III şəxs tək, təsdiq forması.');
