INSERT INTO public.questions VALUES (5579, 73, 'g10-aze-feil-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, II şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, şəkli çəkməyəcək.", "B": "Siz şəkli çəkməyəcəksiniz.", "C": "Biz şəkli çəkməyəcəyik.", "D": "Mən şəkli çəkməyəcəyəm.", "E": "Sən şəkli çəkməyəcəksən."}'::jsonb, 'E', NULL, '«çəkməyəcəksən» — qəti gələcək zaman, II şəxs tək, inkar forması.');
