INSERT INTO public.questions VALUES (5581, 73, 'g10-aze-feil-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, evi tikmədi.", "B": "Biz evi tikmədik.", "C": "Siz evi tikmədiniz.", "D": "Sən evi tikmədin.", "E": "Biz evi tikməyəcəyik."}'::jsonb, 'B', NULL, '«tikmədik» — şühudi keçmiş zaman, I şəxs cəm, inkar forması.');
