INSERT INTO public.questions VALUES (5583, 73, 'g10-aze-feil-q3-13', 3, 13, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "C": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «eşitdin» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5584, 73, 'g10-aze-feil-q3-14', 3, 14, 'medium', 'single', 'Hansı cümlədə feili sifət var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "C": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "D": "Biz sizdən sonra gəldik.", "E": "Axı biz bu yolu tanımırıq."}'::jsonb, 'C', NULL, '«Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.»: «götürdüyüm» — feili sifət, təyin; «qaytardım» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5585, 73, 'g10-aze-feil-q3-15', 3, 15, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və təyin var?', NULL, NULL, '{"A": "Bacım məndən kitab istədi.", "B": "Yağışa görə oyun dayandırıldı.", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Ay Leyla, pəncərəni bağla!", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'E', NULL, '«Hansı şəhərdə doğulmusan?»: «doğulmusan» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5586, 73, 'g10-aze-feil-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Mən lövhəni silmirəm.", "B": "Biz lövhəni silmirik.", "C": "Siz lövhəni silmirsiniz.", "D": "Sən lövhəni silmirsən.", "E": "Sən lövhəni silməyəcəksən."}'::jsonb, 'D', NULL, '«silmirsən» — indiki zaman, II şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5587, 73, 'g10-aze-feil-q3-17', 3, 17, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və sifət yoxdur?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "D": "Oxumaq insanı zənginləşdirir.", "E": "Ən çətin sualları hətta kiçik qardaşım tapdı."}'::jsonb, 'D', NULL, '«Oxumaq insanı zənginləşdirir.»: «Oxumaq» — məsdər, mübtəda; «zənginləşdirir» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5588, 73, 'g10-aze-feil-q3-18', 3, 18, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "C": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «getdik» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (5589, 73, 'g10-aze-feil-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, I şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Mən çayı içmədim.", "B": "Mən çayı içirəm.", "C": "O, çayı içmir.", "D": "Mən çayı içmirəm.", "E": "Mən çayı içməyəcəyəm."}'::jsonb, 'D', NULL, '«içmirəm» — indiki zaman, I şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (5590, 73, 'g10-aze-feil-q3-20', 3, 20, 'hard', 'single', '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 4"}'::jsonb, 'D', NULL, '«Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.»: «yaşayan» — feili sifət, təyin; «qaçır» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4.');
INSERT INTO public.questions VALUES (5591, 73, 'g10-aze-feil-q3-21', 3, 21, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və modal söz yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Təəssüf ki, mən toya getmədim.", "C": "Of, bu çanta ağırdır!", "D": "Səndən başqa hamı gəldi.", "E": "Bu, lap yeni maşındır."}'::jsonb, 'D', NULL, '«Səndən başqa hamı gəldi.»: «gəldi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5592, 73, 'g10-aze-feil-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, ədat yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Bacım məndən kitab istədi.", "B": "Qoy hamı bu həqiqəti bilsin.", "C": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "D": "Həm oxuyur, həm də işləyir.", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'E', NULL, '«Hansı şəhərdə doğulmusan?»: «doğulmusan» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5593, 73, 'g10-aze-feil-q3-23', 3, 23, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və məsdər yoxdur?', NULL, NULL, '{"A": "Of, bu çanta ağırdır!", "B": "Əhsən! Bu rəsmi kim çəkib?", "C": "Mən üzməyi yayda öyrəndim.", "D": "Oxumaq insanı zənginləşdirir.", "E": "Bu, lap yeni maşındır."}'::jsonb, 'B', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «çəkib» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5594, 73, 'g10-aze-feil-q3-24', 3, 24, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və bağlayıcı var?', NULL, NULL, '{"A": "Biz sizdən sonra gəldik.", "B": "Tortun dörddə birini qonaqlara verdik.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Ehtimal ki, qonaqlar axşama kimi gələcəklər."}'::jsonb, 'D', NULL, '«Sən ya rəsm, ya da musiqi seç.»: «seç» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5595, 73, 'g10-aze-feil-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, kitabı oxudu.", "B": "Sən kitabı oxudun.", "C": "Biz kitabı oxuyacağıq.", "D": "Biz kitabı oxuduq.", "E": "Mən kitabı oxudum."}'::jsonb, 'D', NULL, '«oxuduq» — şühudi keçmiş zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (5596, 73, 'g10-aze-feil-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib və qoşma yoxdur?', NULL, NULL, '{"A": "Biz sizdən sonra gəldik.", "B": "Oxumaq insanı zənginləşdirir.", "C": "Danışmaq asandır.", "D": "Həm oxuyur, həm də işləyir.", "E": "Bu, lap yeni maşındır."}'::jsonb, 'B', NULL, '«Oxumaq insanı zənginləşdirir.»: «Oxumaq» — məsdər, mübtəda; «zənginləşdirir» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5597, 73, 'g10-aze-feil-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, təyin var və zərf var?', NULL, NULL, '{"A": "O, ikinci dəfə bu şəhərə gəlir.", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Ah, köhnə dostumu uzun müddət görmədim!", "D": "Uşaq şirniyyatı gizlicə yedi.", "E": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular."}'::jsonb, 'E', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «vuruşan» — feili sifət, təyin; «oturtdular» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5598, 73, 'g10-aze-feil-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, cavabı bilmədi.", "B": "Biz cavabı bilmədik.", "C": "Biz cavabı bilməyəcəyik.", "D": "Biz cavabı bilmirik.", "E": "Sən cavabı bilmədin."}'::jsonb, 'B', NULL, '«bilmədik» — şühudi keçmiş zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (5599, 73, 'g10-aze-feil-q3-29', 3, 29, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'A', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «gülümsəyən» — feili sifət, təyin; «uzatdı» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (5600, 73, 'g10-aze-feil-q3-30', 3, 30, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 5", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'B', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «çatdırdıq» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3.');
INSERT INTO public.questions VALUES (5601, 74, 'g10-aze-zerf-q1-01', 1, 1, 'medium', 'single', 'Hansı cümlədə 1 zərf işlənib və təyin var?', NULL, NULL, '{"A": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "B": "Bu, lap yeni maşındır.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Yarışa on səkkiz komanda qatıldı.", "E": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək."}'::jsonb, 'C', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «Dostcasına» — tərzi-hərəkət zərfi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5602, 74, 'g10-aze-zerf-q1-02', 1, 2, 'hard', 'single', '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 2; isim — 2; əvəzlik — 1", "B": "zərf — 2; isim — 2; əvəzlik — 0", "C": "zərf — 2; isim — 4; əvəzlik — 0", "D": "zərf — 2; isim — 1; əvəzlik — 0", "E": "zərf — 1; isim — 2; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «Qəhrəmancasına» — tərzi-hərəkət zərfi, təyin; «geri» — yer zərfi, zərflik. Düzgün: zərf — 2; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (5603, 74, 'g10-aze-zerf-q1-03', 1, 3, 'medium', 'single', 'Hansı cümlədə 1 zərf işlənib və sifət yoxdur?', NULL, NULL, '{"A": "Tortun dörddə birini qonaqlara verdik.", "B": "Ey gənclər, Vətəni sevin!", "C": "Bəs sən hara gedirsən?", "D": "Biz iki-üç saat gözlədik.", "E": "Kimsə həyətdə ucadan mahnı oxuyurdu."}'::jsonb, 'E', NULL, '«Kimsə həyətdə ucadan mahnı oxuyurdu.»: «ucadan» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5604, 74, 'g10-aze-zerf-q1-04', 1, 4, 'medium', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Mən üzməyi yayda öyrəndim.", "B": "Mahnı oxuya-oxuya işləyirdi.", "C": "Ay Leyla, pəncərəni bağla!", "D": "Biz stansiyada qatarı xeyli gözlədik.", "E": "Ucadan gülən uşaqlar müəllimi görüb susdular."}'::jsonb, 'D', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «xeyli» — kəmiyyət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5605, 74, 'g10-aze-zerf-q1-05', 1, 5, 'medium', 'single', 'Hansı cümlədə 1 zərf işlənib və mübtəda var?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Of, bu çanta ağırdır!", "D": "Bəs sən hara gedirsən?", "E": "Oxumaq insanı zənginləşdirir."}'::jsonb, 'B', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «xeyli» — kəmiyyət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5606, 74, 'g10-aze-zerf-q1-06', 1, 6, 'hard', 'single', '«Biz stansiyada qatarı xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 2; isim — 2; əvəzlik — 0", "B": "zərf — 1; isim — 3; əvəzlik — 1", "C": "zərf — 1; isim — 2; əvəzlik — 1", "D": "zərf — 1; isim — 2; əvəzlik — 2", "E": "zərf — 1; isim — 4; əvəzlik — 1"}'::jsonb, 'C', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «xeyli» — kəmiyyət zərfi, zərflik. Düzgün: zərf — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5607, 74, 'g10-aze-zerf-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə 1 zərf işlənib, məsdər yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Biz stansiyada qatarı xeyli gözlədik.", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Bu məktubu özüm yazacağam.", "D": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "E": "Biz çayın sahili ilə xeyli getdik."}'::jsonb, 'A', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «xeyli» — kəmiyyət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5608, 74, 'g10-aze-zerf-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə tərzi-hərəkət zərfi var, sifət yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "Uşaq vazanı bilərəkdən sındırmamışdı.", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Heç nə demədən otaqdan çıxdı.", "E": "Onuncu sinfin şagirdləri teatra getdilər."}'::jsonb, 'C', NULL, '«Kimsə həyətdə ucadan mahnı oxuyurdu.»: «ucadan» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5609, 74, 'g10-aze-zerf-q1-09', 1, 9, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 2; isim — 2; əvəzlik — 1", "B": "zərf — 1; isim — 2; əvəzlik — 1", "C": "zərf — 1; isim — 2; əvəzlik — 2", "D": "zərf — 1; isim — 1; əvəzlik — 1", "E": "zərf — 1; isim — 4; əvəzlik — 1"}'::jsonb, 'B', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «Dostcasına» — tərzi-hərəkət zərfi, təyin. Düzgün: zərf — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5610, 74, 'g10-aze-zerf-q1-10', 1, 10, 'medium', 'single', 'Hansı cümlədə 1 zərf işlənib və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "Biz sizdən sonra gəldik.", "C": "Bu məktubu özüm yazacağam.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'D', NULL, '«Ucadan gülən uşaqlar müəllimi görüb susdular.»: «Ucadan» — tərzi-hərəkət zərfi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5611, 74, 'g10-aze-zerf-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə zərf feili sifət tərkibinin daxilindədir, modal söz yoxdur və feili sifət var?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "B": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "C": "Yazılmış məktubu poçta apardım.", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım."}'::jsonb, 'A', NULL, '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.»: «Dostcasına» — tərzi-hərəkət zərfi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5612, 74, 'g10-aze-zerf-q1-12', 1, 12, 'hard', 'single', '«Kimsə həyətdə ucadan mahnı oxuyurdu.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 4; əvəzlik — 1", "B": "zərf — 2; isim — 2; əvəzlik — 0", "C": "zərf — 1; isim — 2; əvəzlik — 1", "D": "zərf — 1; isim — 1; əvəzlik — 1", "E": "zərf — 1; isim — 2; əvəzlik — 2"}'::jsonb, 'C', NULL, '«Kimsə həyətdə ucadan mahnı oxuyurdu.»: «ucadan» — tərzi-hərəkət zərfi, zərflik. Düzgün: zərf — 1; isim — 2; əvəzlik — 1.');
