INSERT INTO public.questions VALUES (5614, 74, 'g10-aze-zerf-q1-14', 1, 14, 'medium', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir və sifət yoxdur?', NULL, NULL, '{"A": "Anam ilə atam toya getdilər.", "B": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "C": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "D": "Qoy hamı bu həqiqəti bilsin.", "E": "Həm oxuyur, həm də işləyir."}'::jsonb, 'B', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «Qəhrəmancasına» — tərzi-hərəkət zərfi, təyin; «geri» — yer zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5615, 74, 'g10-aze-zerf-q1-15', 1, 15, 'medium', 'single', 'Hansı cümlədə zaman zərfi var və modal söz var?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'E', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «dünən» — zaman zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5616, 74, 'g10-aze-zerf-q1-16', 1, 16, 'medium', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Biz çayın sahili ilə xeyli getdik.", "B": "Of, bu çanta ağırdır!", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "E": "Məhz bu kənddə böyük şair doğulub."}'::jsonb, 'C', NULL, '«Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.»: «Qəhrəmancasına» — tərzi-hərəkət zərfi, təyin; «geri» — yer zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
