INSERT INTO public.questions VALUES (5635, 74, 'g10-aze-zerf-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir, vasitəli tamamlıq yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Biz stansiyada qatarı xeyli gözlədik.", "B": "Oxumaq insanı zənginləşdirir.", "C": "Biz çayın sahili ilə xeyli getdik.", "D": "Ay Leyla, pəncərəni bağla!", "E": "Heç nə demədən otaqdan çıxdı."}'::jsonb, 'A', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: «xeyli» — kəmiyyət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
