INSERT INTO public.questions VALUES (5637, 74, 'g10-aze-zerf-q2-07', 2, 7, 'medium', 'single', 'Hansı cümlədə 1 zərf işlənib və məsdər yoxdur?', NULL, NULL, '{"A": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "B": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "C": "Ah, köhnə dostumu uzun müddət görmədim!", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Bu, lap yeni maşındır."}'::jsonb, 'A', NULL, '«Ucadan gülən uşaqlar müəllimi görüb susdular.»: «Ucadan» — tərzi-hərəkət zərfi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5638, 74, 'g10-aze-zerf-q2-08', 2, 8, 'medium', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir və bağlayıcı var?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular."}'::jsonb, 'D', NULL, '«Ya sabah, ya da birigün gələcəyəm.»: «sabah» — zaman zərfi, zərflik; «birigün» — zaman zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5639, 74, 'g10-aze-zerf-q2-09', 2, 9, 'hard', 'single', '«Yəqin, siz bu xəbəri dünən eşitmisiniz.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 1; əvəzlik — 1", "B": "zərf — 1; isim — 0; əvəzlik — 2", "C": "zərf — 1; isim — 1; əvəzlik — 2", "D": "zərf — 2; isim — 1; əvəzlik — 2", "E": "zərf — 0; isim — 1; əvəzlik — 2"}'::jsonb, 'C', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «dünən» — zaman zərfi, zərflik. Düzgün: zərf — 1; isim — 1; əvəzlik — 2.');
