INSERT INTO public.questions VALUES (5641, 74, 'g10-aze-zerf-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə kəmiyyət zərfi var, xəbər feillə ifadə olunub və müraciət yoxdur?', NULL, NULL, '{"A": "Biz çayın sahili ilə xeyli getdik.", "B": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "C": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "D": "Uşaq vazanı bilərəkdən sındırmamışdı.", "E": "Yazılmış məktubu poçta apardım."}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «xeyli» — kəmiyyət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
