INSERT INTO public.questions VALUES (5679, 74, 'g10-aze-zerf-q3-19', 3, 19, 'medium', 'single', 'Hansı cümlədə zaman zərfi var və mübtəda var?', NULL, NULL, '{"A": "Yarışa on səkkiz komanda qatıldı.", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "D": "Bir sözlə, hamı məmnun qaldı.", "E": "Vay, buzlu yolda maşın sürüşdü!"}'::jsonb, 'C', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «dünən» — zaman zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5680, 74, 'g10-aze-zerf-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir, xəbər feillə ifadə olunub və məsdər yoxdur?', NULL, NULL, '{"A": "Yağışa görə oyun dayandırıldı.", "B": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "C": "Qardaşım məktubu qələm ilə yazdı.", "D": "Tortun dörddə birini qonaqlara verdik.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'B', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «yuxarı» — yer zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5681, 74, 'g10-aze-zerf-q3-21', 3, 21, 'hard', 'single', '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 3; isim — 2; əvəzlik — 1", "B": "zərf — 1; isim — 2; əvəzlik — 0", "C": "zərf — 2; isim — 1; əvəzlik — 1", "D": "zərf — 0; isim — 2; əvəzlik — 1", "E": "zərf — 1; isim — 2; əvəzlik — 1"}'::jsonb, 'E', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «yuxarı» — yer zərfi, zərflik. Düzgün: zərf — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (5682, 74, 'g10-aze-zerf-q3-22', 3, 22, 'medium', 'single', 'Hansı cümlədə 1 zərf işlənib və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Üç-dörd günə qədər işimizi bitirəcəyik.", "B": "Of, bu çanta ağırdır!", "C": "Bir sözlə, hamı məmnun qaldı.", "D": "Uşaq şirniyyatı gizlicə yedi.", "E": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər."}'::jsonb, 'D', NULL, '«Uşaq şirniyyatı gizlicə yedi.»: «gizlicə» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
