INSERT INTO public.questions VALUES (5685, 74, 'g10-aze-zerf-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir, təyin yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Həm oxuyur, həm də işləyir.", "B": "Mahnı oxuya-oxuya işləyirdi.", "C": "Bəs sən hara gedirsən?", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Kimsə həyətdə ucadan mahnı oxuyurdu."}'::jsonb, 'E', NULL, '«Kimsə həyətdə ucadan mahnı oxuyurdu.»: «ucadan» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5686, 74, 'g10-aze-zerf-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə yer zərfi var və feili bağlama yoxdur?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Ura, bayram gəldi!", "C": "Oxumaq insanı zənginləşdirir.", "D": "Ey gənclər, Vətəni sevin!", "E": "Biz dağın zirvəsinə doğru yuxarı qalxdıq."}'::jsonb, 'E', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «yuxarı» — yer zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
