INSERT INTO public.questions VALUES (5691, 75, 'g10-aze-qosma-q1-01', 1, 1, 'hard', 'single', '«Üç-dörd günə qədər işimizi bitirəcəyik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "B": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5692, 75, 'g10-aze-qosma-q1-02', 1, 2, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin?", "B": "Tortun dörddə birini qonaqlara verdik.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Əlbəttə, biz sizə inanırıq.", "E": "Qardaşım məktubu qələm ilə yazdı."}'::jsonb, 'E', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «ilə» — qoşma, adlıq hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
