INSERT INTO public.questions VALUES (5700, 75, 'g10-aze-qosma-q1-10', 1, 10, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5701, 75, 'g10-aze-qosma-q1-11', 1, 11, 'medium', 'single', 'Hansı cümlədə qoşma vasitəli tamamlığın tərkibindədir və məsdər yoxdur?', NULL, NULL, '{"A": "Yazılmış məktubu poçta apardım.", "B": "Hansı şəhərdə doğulmusan?", "C": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'E', NULL, '«Atam mənim üçün velosiped aldı.»: «üçün» — qoşma, yiyəlik hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5702, 75, 'g10-aze-qosma-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə qoşma var, ədat yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Mən üzməyi yayda öyrəndim.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "E": "Yağışa görə oyun dayandırıldı."}'::jsonb, 'E', NULL, '«Yağışa görə oyun dayandırıldı.»: «görə» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5703, 75, 'g10-aze-qosma-q1-13', 1, 13, 'medium', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var və modal söz var?', NULL, NULL, '{"A": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "B": "Yağışa görə oyun dayandırıldı.", "C": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "D": "Təəssüf ki, mən toya getmədim.", "E": "Biz dağın zirvəsinə doğru yuxarı qalxdıq."}'::jsonb, 'C', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5704, 75, 'g10-aze-qosma-q1-14', 1, 14, 'medium', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib və feili bağlama yoxdur?', NULL, NULL, '{"A": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "B": "Səndən başqa hamı gəldi.", "C": "Qardaşım məktubu qələm ilə yazdı.", "D": "Bir sözlə, hamı məmnun qaldı.", "E": "Anam ilə atam toya getdilər."}'::jsonb, 'E', NULL, '«Anam ilə atam toya getdilər.»: qoşma yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5705, 75, 'g10-aze-qosma-q1-15', 1, 15, 'medium', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib və zərf yoxdur?', NULL, NULL, '{"A": "Bu məktubu özüm yazacağam.", "B": "Anam ilə atam toya getdilər.", "C": "Hansı şəhərdə doğulmusan?", "D": "Mən üzməyi yayda öyrəndim.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'B', NULL, '«Anam ilə atam toya getdilər.»: qoşma yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
