INSERT INTO public.questions VALUES (5719, 75, 'g10-aze-qosma-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib, modal söz yoxdur və say yoxdur?', NULL, NULL, '{"A": "Ura, bayram gəldi!", "B": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "Anam ilə atam toya getdilər.", "D": "Hansı şəhərdə doğulmusan?", "E": "Vay, buzlu yolda maşın sürüşdü!"}'::jsonb, 'C', NULL, '«Anam ilə atam toya getdilər.»: qoşma yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
