INSERT INTO public.questions VALUES (5721, 75, 'g10-aze-qosma-q2-01', 2, 1, 'medium', 'single', 'Hansı cümlədə adlıq və ya yiyəlik halını idarə edən qoşma var və sifət yoxdur?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Axı biz bu yolu tanımırıq.", "C": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "D": "Biz sizdən sonra gəldik.", "E": "Anam ilə atam toya getdilər."}'::jsonb, 'A', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «ilə» — qoşma, adlıq hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
