INSERT INTO public.questions VALUES (5734, 75, 'g10-aze-qosma-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə qoşma vasitəli tamamlığın tərkibindədir, vasitəsiz tamamlıq var və müraciət yoxdur?', NULL, NULL, '{"A": "Əhsən! Bu rəsmi kim çəkib?", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Atam mənim üçün velosiped aldı.", "D": "Uşaq şirniyyatı gizlicə yedi.", "E": "Kimsə həyətdə ucadan mahnı oxuyurdu."}'::jsonb, 'C', NULL, '«Atam mənim üçün velosiped aldı.»: «üçün» — qoşma, yiyəlik hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5735, 75, 'g10-aze-qosma-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə qoşma vasitəli tamamlığın tərkibindədir, mübtəda var və məsdər yoxdur?', NULL, NULL, '{"A": "Biz stansiyada qatarı xeyli gözlədik.", "B": "Anam ilə atam toya getdilər.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Qardaşım məktubu qələm ilə yazdı.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'D', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «ilə» — qoşma, adlıq hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5736, 75, 'g10-aze-qosma-q2-16', 2, 16, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5737, 75, 'g10-aze-qosma-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib, modal söz yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Yağışa görə oyun dayandırıldı.", "C": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "D": "Anam ilə atam toya getdilər.", "E": "Əhsən! Bu rəsmi kim çəkib?"}'::jsonb, 'D', NULL, '«Anam ilə atam toya getdilər.»: qoşma yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5738, 75, 'g10-aze-qosma-q2-18', 2, 18, 'hard', 'single', '«Qardaşım məktubu qələm ilə yazdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "qoşma — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: «ilə» — qoşma, adlıq hal (idarə edir), vasitəli tamamlıq. Düzgün: qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5739, 75, 'g10-aze-qosma-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə qoşma var, ədat yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Ura, bayram gəldi!", "B": "Üç-dörd günə qədər işimizi bitirəcəyik.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "E": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər."}'::jsonb, 'B', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5740, 75, 'g10-aze-qosma-q2-20', 2, 20, 'medium', 'single', 'Hansı cümlədə qoşma vasitəli tamamlığın tərkibindədir və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Yarışa on səkkiz komanda qatıldı.", "B": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Atam mənim üçün velosiped aldı.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'D', NULL, '«Atam mənim üçün velosiped aldı.»: «üçün» — qoşma, yiyəlik hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5741, 75, 'g10-aze-qosma-q2-21', 2, 21, 'medium', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var və nida yoxdur?', NULL, NULL, '{"A": "Dərslərini oxumadan oynamağa getdi.", "B": "Bu məktubu özüm yazacağam.", "C": "Səndən başqa hamı gəldi.", "D": "Bəs sən hara gedirsən?", "E": "Ya sabah, ya da birigün gələcəyəm."}'::jsonb, 'C', NULL, '«Səndən başqa hamı gəldi.»: «başqa» — qoşma, çıxışlıq hal (idarə edir). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5742, 75, 'g10-aze-qosma-q2-22', 2, 22, 'medium', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var və müraciət yoxdur?', NULL, NULL, '{"A": "Üç-dörd günə qədər işimizi bitirəcəyik.", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Sən ya rəsm, ya da musiqi seç.", "D": "Heç nə demədən otaqdan çıxdı.", "E": "Həm oxuyur, həm də işləyir."}'::jsonb, 'A', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
