INSERT INTO public.questions VALUES (5747, 75, 'g10-aze-qosma-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə qoşma var, müraciət yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ura, bayram gəldi!", "B": "Bu, lap yeni maşındır.", "C": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "D": "Qardaşım məktubu qələm ilə yazdı.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'E', NULL, '«Biz sizdən sonra gəldik.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
