INSERT INTO public.questions VALUES (5751, 75, 'g10-aze-qosma-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, feili sifət yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Bir sözlə, hamı məmnun qaldı.", "B": "Səndən başqa hamı gəldi.", "C": "Sərnişinlər avtobusa dalbadal mindilər.", "D": "Tortun dörddə birini qonaqlara verdik.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'B', NULL, '«Səndən başqa hamı gəldi.»: «başqa» — qoşma, çıxışlıq hal (idarə edir). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5752, 75, 'g10-aze-qosma-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə qoşma vasitəli tamamlığın tərkibindədir, feili bağlama yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "Həm oxuyur, həm də işləyir.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Ay qızım, bu sözləri kimdən eşitdin?", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'E', NULL, '«Atam mənim üçün velosiped aldı.»: «üçün» — qoşma, yiyəlik hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
