INSERT INTO public.questions VALUES (5757, 75, 'g10-aze-qosma-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, feili bağlama yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Biz iki-üç saat gözlədik.", "B": "Onuncu sinfin şagirdləri teatra getdilər.", "C": "Yağışa görə oyun dayandırıldı.", "D": "Qoy hamı bu həqiqəti bilsin.", "E": "Biz çayın sahili ilə xeyli getdik."}'::jsonb, 'C', NULL, '«Yağışa görə oyun dayandırıldı.»: «görə» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5758, 75, 'g10-aze-qosma-q3-08', 3, 8, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və ədat yoxdur?', NULL, NULL, '{"A": "Ey gənclər, Vətəni sevin!", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Biz stansiyada qatarı xeyli gözlədik.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Biz çayın sahili ilə xeyli getdik."}'::jsonb, 'E', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «ilə» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5759, 75, 'g10-aze-qosma-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, təyin var və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "D": "Məhz bu kənddə böyük şair doğulub.", "E": "Onuncu sinfin şagirdləri teatra getdilər."}'::jsonb, 'B', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «ilə» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5760, 75, 'g10-aze-qosma-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə qoşma var, xəbər feillə ifadə olunub və nida yoxdur?', NULL, NULL, '{"A": "Anam ilə atam toya getdilər.", "B": "Dərslərini oxumadan oynamağa getdi.", "C": "Üç-dörd günə qədər işimizi bitirəcəyik.", "D": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "E": "Məhz bu kənddə böyük şair doğulub."}'::jsonb, 'C', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5761, 75, 'g10-aze-qosma-q3-11', 3, 11, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Atam mənim üçün velosiped aldı.»: «üçün» — qoşma, yiyəlik hal (idarə edir), vasitəli tamamlıq. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5762, 75, 'g10-aze-qosma-q3-12', 3, 12, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5763, 75, 'g10-aze-qosma-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə adlıq və ya yiyəlik halını idarə edən qoşma var, zərflik yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Ura, bayram gəldi!", "B": "Yarışa on səkkiz komanda qatıldı.", "C": "Tortun dörddə birini qonaqlara verdik.", "D": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'E', NULL, '«Atam mənim üçün velosiped aldı.»: «üçün» — qoşma, yiyəlik hal (idarə edir), vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5764, 75, 'g10-aze-qosma-q3-14', 3, 14, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "D": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «ilə» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5765, 75, 'g10-aze-qosma-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, say yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "B": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "C": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "D": "Sərnişinlər avtobusa dalbadal mindilər.", "E": "Vay, buzlu yolda maşın sürüşdü!"}'::jsonb, 'C', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5766, 75, 'g10-aze-qosma-q3-16', 3, 16, 'hard', 'single', '«Üç-dörd günə qədər işimizi bitirəcəyik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "qoşma — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5767, 75, 'g10-aze-qosma-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə qoşma var, bağlayıcı yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Uşaq şirniyyatı gizlicə yedi.", "B": "Sərnişinlər avtobusa dalbadal mindilər.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Bu, lap yeni maşındır.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'E', NULL, '«Biz sizdən sonra gəldik.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
