INSERT INTO public.questions VALUES (5775, 75, 'g10-aze-qosma-q3-25', 3, 25, 'hard', 'single', '«Biz çayın sahili ilə xeyli getdik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Biz çayın sahili ilə xeyli getdik.»: «ilə» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5776, 75, 'g10-aze-qosma-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "B": "Anam ilə atam toya getdilər.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "E": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır."}'::jsonb, 'B', NULL, '«Anam ilə atam toya getdilər.»: qoşma yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5777, 75, 'g10-aze-qosma-q3-27', 3, 27, 'hard', 'single', '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «doğru» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5778, 75, 'g10-aze-qosma-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə qoşma var, zərflik var və zərf var?', NULL, NULL, '{"A": "Uşaq şirniyyatı gizlicə yedi.", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Kimsə həyətdə ucadan mahnı oxuyurdu."}'::jsonb, 'C', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «doğru» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5779, 75, 'g10-aze-qosma-q3-29', 3, 29, 'medium', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var və təyin var?', NULL, NULL, '{"A": "Yarışa on səkkiz komanda qatıldı.", "B": "Yağışa görə oyun dayandırıldı.", "C": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "D": "Tortun dörddə birini qonaqlara verdik.", "E": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı."}'::jsonb, 'C', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: «doğru» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5780, 75, 'g10-aze-qosma-q3-30', 3, 30, 'hard', 'single', '«Üç-dörd günə qədər işimizi bitirəcəyik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5781, 76, 'g10-aze-bag-q1-01', 1, 1, 'hard', 'single', '«Bağda alma, armud və heyva yetişmişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "B": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
