INSERT INTO public.questions VALUES (5783, 76, 'g10-aze-bag-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib, modal söz yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Biz çayın sahili ilə xeyli getdik.", "B": "O, ikinci dəfə bu şəhərə gəlir.", "C": "Hansı şəhərdə doğulmusan?", "D": "Həm oxuyur, həm də işləyir.", "E": "Of, bu çanta ağırdır!"}'::jsonb, 'A', NULL, '«Biz çayın sahili ilə xeyli getdik.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
