INSERT INTO public.questions VALUES (5785, 76, 'g10-aze-bag-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə bağlayıcı bir dəfə işlənib, vasitəsiz tamamlıq yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Ya sabah, ya da birigün gələcəyəm.", "B": "Anam ilə atam toya getdilər.", "C": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "D": "Onuncu sinfin şagirdləri teatra getdilər.", "E": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək."}'::jsonb, 'B', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
