INSERT INTO public.questions VALUES (5789, 76, 'g10-aze-bag-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, ədat yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Bağda alma, armud və heyva yetişmişdi.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "E": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər."}'::jsonb, 'B', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5790, 76, 'g10-aze-bag-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins mübtədaları bağlayır, vasitəsiz tamamlıq yoxdur və say yoxdur?', NULL, NULL, '{"A": "Danışmaq asandır.", "B": "Bu, lap yeni maşındır.", "C": "Məhz bu kənddə böyük şair doğulub.", "D": "Ura, bayram gəldi!", "E": "Anam ilə atam toya getdilər."}'::jsonb, 'E', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
