INSERT INTO public.questions VALUES (5792, 76, 'g10-aze-bag-q1-12', 1, 12, 'medium', 'single', 'Hansı cümlədə bağlayıcı həmcins vasitəsiz tamamlıqları bağlayır və modal söz yoxdur?', NULL, NULL, '{"A": "Ah, köhnə dostumu uzun müddət görmədim!", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Biz sizdən sonra gəldik.", "D": "Heç nə demədən otaqdan çıxdı.", "E": "Kimsə həyətdə ucadan mahnı oxuyurdu."}'::jsonb, 'B', NULL, '«Sən ya rəsm, ya da musiqi seç.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5793, 76, 'g10-aze-bag-q1-13', 1, 13, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5794, 76, 'g10-aze-bag-q1-14', 1, 14, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və qoşma var?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Səndən başqa hamı gəldi.", "C": "Atam mənim üçün velosiped aldı.", "D": "Üç-dörd günə qədər işimizi bitirəcəyik.", "E": "Yağışa görə oyun dayandırıldı."}'::jsonb, 'A', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5795, 76, 'g10-aze-bag-q1-15', 1, 15, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 0; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "bağlayıcı — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5796, 76, 'g10-aze-bag-q1-16', 1, 16, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və məsdər yoxdur?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Biz iki-üç saat gözlədik.", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Biz çayın sahili ilə xeyli getdik.", "E": "Axı biz bu yolu tanımırıq."}'::jsonb, 'D', NULL, '«Biz çayın sahili ilə xeyli getdik.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5797, 76, 'g10-aze-bag-q1-17', 1, 17, 'medium', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib və feili sifət yoxdur?', NULL, NULL, '{"A": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "B": "Biz iki-üç saat gözlədik.", "C": "Dərslərini oxumadan oynamağa getdi.", "D": "Həm oxuyur, həm də işləyir.", "E": "Vay, buzlu yolda maşın sürüşdü!"}'::jsonb, 'D', NULL, '«Həm oxuyur, həm də işləyir.»: «Həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5798, 76, 'g10-aze-bag-q1-18', 1, 18, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'B', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5799, 76, 'g10-aze-bag-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə «ya» bağlayıcısı var, sifət yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Uşaq vazanı bilərəkdən sındırmamışdı.", "B": "Ura, bayram gəldi!", "C": "Onuncu sinfin şagirdləri teatra getdilər.", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Ay qızım, bu sözləri kimdən eşitdin?"}'::jsonb, 'D', NULL, '«Ya sabah, ya da birigün gələcəyəm.»: «Ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
