INSERT INTO public.questions VALUES (5802, 76, 'g10-aze-bag-q1-22', 1, 22, 'medium', 'single', 'Hansı cümlədə bağlayıcı həmcins xəbərləri bağlayır və zərflik yoxdur?', NULL, NULL, '{"A": "Həm oxuyur, həm də işləyir.", "B": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "E": "Bu məktubu özüm yazacağam."}'::jsonb, 'A', NULL, '«Həm oxuyur, həm də işləyir.»: «Həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5803, 76, 'g10-aze-bag-q1-23', 1, 23, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və feili bağlama yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "B": "Həm oxuyur, həm də işləyir.", "C": "Qardaşım məktubu qələm ilə yazdı.", "D": "Əlbəttə, biz sizə inanırıq.", "E": "Mən üzməyi yayda öyrəndim."}'::jsonb, 'C', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
