INSERT INTO public.questions VALUES (5816, 76, 'g10-aze-bag-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, zərflik var və müraciət yoxdur?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Anam ilə atam toya getdilər."}'::jsonb, 'E', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5817, 76, 'g10-aze-bag-q2-07', 2, 7, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5818, 76, 'g10-aze-bag-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, qoşma yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Yalnız zəhmət insanı ucaldır.", "B": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "C": "Anam ilə atam toya getdilər.", "D": "Əlbəttə, biz sizə inanırıq.", "E": "Ey gənclər, Vətəni sevin!"}'::jsonb, 'C', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5819, 76, 'g10-aze-bag-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə «ya» bağlayıcısı var, mübtəda var və nida yoxdur?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "C": "Sən ya rəsm, ya da musiqi seç.", "D": "Yarışa on səkkiz komanda qatıldı.", "E": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər."}'::jsonb, 'C', NULL, '«Sən ya rəsm, ya da musiqi seç.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
