INSERT INTO public.questions VALUES (5821, 76, 'g10-aze-bag-q2-11', 2, 11, 'hard', 'single', '«Bağda alma, armud və heyva yetişmişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5822, 76, 'g10-aze-bag-q2-12', 2, 12, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və feili sifət yoxdur?', NULL, NULL, '{"A": "Hansı şəhərdə doğulmusan?", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Anam ilə atam toya getdilər.", "D": "Yağışa görə oyun dayandırıldı.", "E": "Ehtimal ki, qonaqlar axşama kimi gələcəklər."}'::jsonb, 'B', NULL, '«Biz çayın sahili ilə xeyli getdik.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
