INSERT INTO public.questions VALUES (5829, 76, 'g10-aze-bag-q2-19', 2, 19, 'hard', 'single', '«Bağda alma, armud və heyva yetişmişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "D": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5830, 76, 'g10-aze-bag-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, məsdər yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Ya sabah, ya da birigün gələcəyəm.", "B": "Bu məktubu özüm yazacağam.", "C": "Hansı şəhərdə doğulmusan?", "D": "Təəssüf ki, mən toya getmədim.", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'A', NULL, '«Ya sabah, ya da birigün gələcəyəm.»: «Ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5831, 76, 'g10-aze-bag-q2-21', 2, 21, 'medium', 'single', 'Hansı cümlədə bağlayıcı var və məsdər yoxdur?', NULL, NULL, '{"A": "Səndən başqa hamı gəldi.", "B": "Ay qızım, bu sözləri kimdən eşitdin?", "C": "Bu, lap yeni maşındır.", "D": "Ay Leyla, pəncərəni bağla!", "E": "Sən ya rəsm, ya da musiqi seç."}'::jsonb, 'E', NULL, '«Sən ya rəsm, ya da musiqi seç.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5832, 76, 'g10-aze-bag-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib, sifət yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Yalnız zəhmət insanı ucaldır.", "B": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "C": "Üç-dörd günə qədər işimizi bitirəcəyik.", "D": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "E": "Uşaq şirniyyatı gizlicə yedi."}'::jsonb, 'B', NULL, '«Həm riyaziyyatı, həm də fizikanı sevirəm.»: «Həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5833, 76, 'g10-aze-bag-q2-23', 2, 23, 'medium', 'single', 'Hansı cümlədə bağlayıcı var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Hansı şəhərdə doğulmusan?", "B": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "C": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "D": "Həm oxuyur, həm də işləyir.", "E": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım."}'::jsonb, 'D', NULL, '«Həm oxuyur, həm də işləyir.»: «Həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5834, 76, 'g10-aze-bag-q2-24', 2, 24, 'hard', 'single', '«Bağda alma, armud və heyva yetişmişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "D": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5835, 76, 'g10-aze-bag-q2-25', 2, 25, 'medium', 'single', 'Hansı cümlədə bağlayıcı həmcins mübtədaları bağlayır və məsdər yoxdur?', NULL, NULL, '{"A": "Axı biz bu yolu tanımırıq.", "B": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Anam ilə atam toya getdilər.", "E": "Biz dağın zirvəsinə doğru yuxarı qalxdıq."}'::jsonb, 'D', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5836, 76, 'g10-aze-bag-q2-26', 2, 26, 'medium', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib və sifət yoxdur?', NULL, NULL, '{"A": "Heç nə demədən otaqdan çıxdı.", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Ya sabah, ya da birigün gələcəyəm.", "D": "Əlbəttə, biz sizə inanırıq.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'C', NULL, '«Ya sabah, ya da birigün gələcəyəm.»: «Ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5837, 76, 'g10-aze-bag-q2-27', 2, 27, 'hard', 'single', '«Bağda alma, armud və heyva yetişmişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3"}'::jsonb, 'C', NULL, '«Bağda alma, armud və heyva yetişmişdi.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5838, 76, 'g10-aze-bag-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, say yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Heç nə demədən otaqdan çıxdı.", "B": "Hansı şəhərdə doğulmusan?", "C": "Həm oxuyur, həm də işləyir.", "D": "Vay, buzlu yolda maşın sürüşdü!", "E": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər."}'::jsonb, 'C', NULL, '«Həm oxuyur, həm də işləyir.»: «Həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5839, 76, 'g10-aze-bag-q2-29', 2, 29, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Yarışa on səkkiz komanda qatıldı.", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Of, bu çanta ağırdır!", "D": "Vay, buzlu yolda maşın sürüşdü!", "E": "Onuncu sinfin şagirdləri teatra getdilər."}'::jsonb, 'B', NULL, '«Biz çayın sahili ilə xeyli getdik.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
