INSERT INTO public.questions VALUES (5845, 76, 'g10-aze-bag-q3-05', 3, 5, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5846, 76, 'g10-aze-bag-q3-06', 3, 6, 'medium', 'single', 'Hansı cümlədə «ya» bağlayıcısı var və say yoxdur?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Of, bu çanta ağırdır!", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Bu, lap yeni maşındır.", "E": "Qardaşım məktubu qələm ilə yazdı."}'::jsonb, 'A', NULL, '«Sən ya rəsm, ya da musiqi seç.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5847, 76, 'g10-aze-bag-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, ədat yoxdur və zərf var?', NULL, NULL, '{"A": "Ya sabah, ya da birigün gələcəyəm.", "B": "Həm oxuyur, həm də işləyir.", "C": "Biz çayın sahili ilə xeyli getdik.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Həm riyaziyyatı, həm də fizikanı sevirəm."}'::jsonb, 'A', NULL, '«Ya sabah, ya da birigün gələcəyəm.»: «Ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
