INSERT INTO public.questions VALUES (5852, 76, 'g10-aze-bag-q3-12', 3, 12, 'medium', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib və ədat yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Ay Leyla, pəncərəni bağla!", "C": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "D": "Qardaşım məktubu qələm ilə yazdı.", "E": "Tortun dörddə birini qonaqlara verdik."}'::jsonb, 'D', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5853, 76, 'g10-aze-bag-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib, vasitəli tamamlıq yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Biz iki-üç saat gözlədik.", "B": "Anam ilə atam toya getdilər.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Həm oxuyur, həm də işləyir."}'::jsonb, 'B', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5854, 76, 'g10-aze-bag-q3-14', 3, 14, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
