INSERT INTO public.questions VALUES (5856, 76, 'g10-aze-bag-q3-16', 3, 16, 'hard', 'single', '«Anam ilə atam toya getdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 0; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5857, 76, 'g10-aze-bag-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib, zərf yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Bəs sən hara gedirsən?", "B": "Bir sözlə, hamı məmnun qaldı.", "C": "Sən ya rəsm, ya da musiqi seç.", "D": "Dərslərini oxumadan oynamağa getdi.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'C', NULL, '«Sən ya rəsm, ya da musiqi seç.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5858, 76, 'g10-aze-bag-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə «ilə» qoşma kimi işlənib, vasitəsiz tamamlıq var və məsdər yoxdur?', NULL, NULL, '{"A": "Qardaşım məktubu qələm ilə yazdı.", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Bu məktubu özüm yazacağam.", "E": "Ən çətin sualları hətta kiçik qardaşım tapdı."}'::jsonb, 'A', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: bağlayıcı yoxdur. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5859, 76, 'g10-aze-bag-q3-19', 3, 19, 'medium', 'single', 'Hansı cümlədə «həm» bağlayıcısı var və nida yoxdur?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "Biz çayın sahili ilə xeyli getdik.", "C": "Məhz bu kənddə böyük şair doğulub.", "D": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "E": "Ya sabah, ya da birigün gələcəyəm."}'::jsonb, 'D', NULL, '«Həm riyaziyyatı, həm də fizikanı sevirəm.»: «Həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5860, 76, 'g10-aze-bag-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə «ilə» bağlayıcı kimi işlənib, feili sifət yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Anam ilə atam toya getdilər.", "B": "Uşaq vazanı bilərəkdən sındırmamışdı.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'A', NULL, '«Anam ilə atam toya getdilər.»: «ilə» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
