INSERT INTO public.questions VALUES (5878, 77, 'g10-aze-edat-q1-08', 1, 8, 'medium', 'single', 'Hansı cümlədə «lap» ədatı işlənib və zərf yoxdur?', NULL, NULL, '{"A": "Bu, lap yeni maşındır.", "B": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "Yalnız zəhmət insanı ucaldır.", "D": "Dərslərini oxumadan oynamağa getdi.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'A', NULL, '«Bu, lap yeni maşındır.»: «lap» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
