INSERT INTO public.questions VALUES (5881, 77, 'g10-aze-edat-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə «yalnız» ədatı işlənib, zərf yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "B": "Yalnız zəhmət insanı ucaldır.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "E": "Heç nə demədən otaqdan çıxdı."}'::jsonb, 'B', NULL, '«Yalnız zəhmət insanı ucaldır.»: «Yalnız» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
