INSERT INTO public.questions VALUES (5883, 77, 'g10-aze-edat-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə «lap» ədatı işlənib, bağlayıcı yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Of, bu çanta ağırdır!", "B": "Vay, buzlu yolda maşın sürüşdü!", "C": "Sərnişinlər avtobusa dalbadal mindilər.", "D": "Bu, lap yeni maşındır.", "E": "Mahnı oxuya-oxuya işləyirdi."}'::jsonb, 'D', NULL, '«Bu, lap yeni maşındır.»: «lap» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
