INSERT INTO public.questions VALUES (5914, 77, 'g10-aze-edat-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə ədat var, nida yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "B": "O, ikinci dəfə bu şəhərə gəlir.", "C": "Bu, lap yeni maşındır.", "D": "Yalnız zəhmət insanı ucaldır.", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'D', NULL, '«Yalnız zəhmət insanı ucaldır.»: «Yalnız» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5915, 77, 'g10-aze-edat-q2-15', 2, 15, 'medium', 'single', 'Hansı cümlədə «axı» ədatı işlənib və müraciət yoxdur?', NULL, NULL, '{"A": "Məhz bu kənddə böyük şair doğulub.", "B": "Vay, buzlu yolda maşın sürüşdü!", "C": "Of, bu çanta ağırdır!", "D": "Axı biz bu yolu tanımırıq.", "E": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır."}'::jsonb, 'D', NULL, '«Axı biz bu yolu tanımırıq.»: «Axı» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
