INSERT INTO public.questions VALUES (5917, 77, 'g10-aze-edat-q2-17', 2, 17, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "ədat — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "ədat — 0; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "ədat — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «Qoy» — ədat. Düzgün: ədat — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5918, 77, 'g10-aze-edat-q2-18', 2, 18, 'medium', 'single', 'Hansı cümlədə ədat var və qoşma yoxdur?', NULL, NULL, '{"A": "Biz iki-üç saat gözlədik.", "B": "Axı biz bu yolu tanımırıq.", "C": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "D": "Yarışa on səkkiz komanda qatıldı.", "E": "Ucadan gülən uşaqlar müəllimi görüb susdular."}'::jsonb, 'B', NULL, '«Axı biz bu yolu tanımırıq.»: «Axı» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
