INSERT INTO public.questions VALUES (5936, 77, 'g10-aze-edat-q3-06', 3, 6, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "ədat — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "ədat — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "ədat — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "ədat — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Qoy hamı bu həqiqəti bilsin.»: «Qoy» — ədat. Düzgün: ədat — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (5937, 77, 'g10-aze-edat-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə ədat var, təyin yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "B": "Qardaşım məktubu qələm ilə yazdı.", "C": "Həm oxuyur, həm də işləyir.", "D": "Yalnız zəhmət insanı ucaldır.", "E": "Mahnı oxuya-oxuya işləyirdi."}'::jsonb, 'D', NULL, '«Yalnız zəhmət insanı ucaldır.»: «Yalnız» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
