INSERT INTO public.questions VALUES (5939, 77, 'g10-aze-edat-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə «yalnız» ədatı işlənib, zərf yoxdur və nida yoxdur?', NULL, NULL, '{"A": "O, ikinci dəfə bu şəhərə gəlir.", "B": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "C": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "D": "Yalnız zəhmət insanı ucaldır.", "E": "Yazılmış məktubu poçta apardım."}'::jsonb, 'D', NULL, '«Yalnız zəhmət insanı ucaldır.»: «Yalnız» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5940, 77, 'g10-aze-edat-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə ədat var, sifət var və qoşma yoxdur?', NULL, NULL, '{"A": "Ah, köhnə dostumu uzun müddət görmədim!", "B": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Bir sözlə, hamı məmnun qaldı.", "E": "Danışmaq asandır."}'::jsonb, 'B', NULL, '«Ən çətin sualları hətta kiçik qardaşım tapdı.»: «Ən» — ədat; «hətta» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5941, 77, 'g10-aze-edat-q3-11', 3, 11, 'hard', 'single', '«Məhz bu kənddə böyük şair doğulub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "ədat — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "ədat — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "ədat — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Məhz bu kənddə böyük şair doğulub.»: «Məhz» — ədat. Düzgün: ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
