INSERT INTO public.questions VALUES (5961, 78, 'g10-aze-modal-q1-01', 1, 1, 'hard', 'single', '«Yəqin, siz bu xəbəri dünən eşitmisiniz.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «Yəqin» — modal söz. Düzgün: modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (5962, 78, 'g10-aze-modal-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə modal söz nəticə, yekun bildirir, say yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Yalnız zəhmət insanı ucaldır.", "B": "Bir sözlə, hamı məmnun qaldı.", "C": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "D": "Bəs sən hara gedirsən?", "E": "Bacım məndən kitab istədi."}'::jsonb, 'B', NULL, '«Bir sözlə, hamı məmnun qaldı.»: «Bir sözlə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5963, 78, 'g10-aze-modal-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, qoşma yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "B": "Axı biz bu yolu tanımırıq.", "C": "Ey gənclər, Vətəni sevin!", "D": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "E": "Təəssüf ki, mən toya getmədim."}'::jsonb, 'D', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «Xoşbəxtlikdən» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5964, 78, 'g10-aze-modal-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, feili bağlama yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Ya sabah, ya da birigün gələcəyəm.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Ay Leyla, pəncərəni bağla!", "E": "Yalnız zəhmət insanı ucaldır."}'::jsonb, 'A', NULL, '«Təəssüf ki, mən toya getmədim.»: «Təəssüf ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5965, 78, 'g10-aze-modal-q1-05', 1, 5, 'medium', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir və say yoxdur?', NULL, NULL, '{"A": "Mahnı oxuya-oxuya işləyirdi.", "B": "Bir sözlə, hamı məmnun qaldı.", "C": "Ya sabah, ya da birigün gələcəyəm.", "D": "Ey gənclər, Vətəni sevin!", "E": "Qoy hamı bu həqiqəti bilsin."}'::jsonb, 'B', NULL, '«Bir sözlə, hamı məmnun qaldı.»: «Bir sözlə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
