INSERT INTO public.questions VALUES (5978, 78, 'g10-aze-modal-q1-18', 1, 18, 'medium', 'single', 'Hansı cümlədə modal söz təəssüf bildirir və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Biz iki-üç saat gözlədik.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Mahnı oxuya-oxuya işləyirdi.", "E": "Dərslərini oxumadan oynamağa getdi."}'::jsonb, 'C', NULL, '«Təəssüf ki, mən toya getmədim.»: «Təəssüf ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5979, 78, 'g10-aze-modal-q1-19', 1, 19, 'medium', 'single', 'Hansı cümlədə modal söz təəssüf bildirir və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Üç-dörd günə qədər işimizi bitirəcəyik.", "C": "Sərnişinlər avtobusa dalbadal mindilər.", "D": "Bacım məndən kitab istədi.", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'A', NULL, '«Təəssüf ki, mən toya getmədim.»: «Təəssüf ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
