INSERT INTO public.questions VALUES (5983, 78, 'g10-aze-modal-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, feili bağlama yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Məhz bu kənddə böyük şair doğulub.", "B": "Hansı şəhərdə doğulmusan?", "C": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "D": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "E": "Bu məktubu özüm yazacağam."}'::jsonb, 'D', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «Xoşbəxtlikdən» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
