INSERT INTO public.questions VALUES (5998, 78, 'g10-aze-modal-q2-08', 2, 8, 'medium', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir və zərflik yoxdur?', NULL, NULL, '{"A": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "D": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "E": "Təəssüf ki, mən toya getmədim."}'::jsonb, 'C', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «Sözsüz» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (5999, 78, 'g10-aze-modal-q2-09', 2, 9, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "modal söz — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "modal söz — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «Ehtimal ki» — modal söz. Düzgün: modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (6000, 78, 'g10-aze-modal-q2-10', 2, 10, 'medium', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir və feili sifət yoxdur?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin?", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Biz iki-üç saat gözlədik.", "D": "Bağda alma, armud və heyva yetişmişdi.", "E": "Sərnişinlər avtobusa dalbadal mindilər."}'::jsonb, 'B', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «Ehtimal ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6001, 78, 'g10-aze-modal-q2-11', 2, 11, 'medium', 'single', 'Hansı cümlədə modal söz var və təyin var?', NULL, NULL, '{"A": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "B": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "C": "Onuncu sinfin şagirdləri teatra getdilər.", "D": "Üç-dörd günə qədər işimizi bitirəcəyik.", "E": "Tortun dörddə birini qonaqlara verdik."}'::jsonb, 'B', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «Xoşbəxtlikdən» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6002, 78, 'g10-aze-modal-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir, vasitəli tamamlıq yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Biz iki-üç saat gözlədik.", "B": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "C": "Vay, buzlu yolda maşın sürüşdü!", "D": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "E": "Həm riyaziyyatı, həm də fizikanı sevirəm."}'::jsonb, 'D', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «Sözsüz» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6003, 78, 'g10-aze-modal-q2-13', 2, 13, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «Xoşbəxtlikdən» — modal söz. Düzgün: modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6004, 78, 'g10-aze-modal-q2-14', 2, 14, 'medium', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir və feili bağlama yoxdur?', NULL, NULL, '{"A": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "B": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "C": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "D": "Bağda alma, armud və heyva yetişmişdi.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'E', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «Sözsüz» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6005, 78, 'g10-aze-modal-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə modal söz var, mübtəda var və say yoxdur?', NULL, NULL, '{"A": "Əlbəttə, biz sizə inanırıq.", "B": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "C": "Bacım məndən kitab istədi.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'A', NULL, '«Əlbəttə, biz sizə inanırıq.»: «Əlbəttə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6006, 78, 'g10-aze-modal-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir, qoşma yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Sərnişinlər avtobusa dalbadal mindilər.", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.", "E": "Mən üzməyi yayda öyrəndim."}'::jsonb, 'B', NULL, '«Əlbəttə, biz sizə inanırıq.»: «Əlbəttə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
