INSERT INTO public.questions VALUES (6008, 78, 'g10-aze-modal-q2-18', 2, 18, 'medium', 'single', 'Hansı cümlədə modal söz var və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Biz sizdən sonra gəldik.", "C": "Yazılmış məktubu poçta apardım.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'E', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «Sözsüz» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
