INSERT INTO public.questions VALUES (6010, 78, 'g10-aze-modal-q2-20', 2, 20, 'medium', 'single', 'Hansı cümlədə modal söz ehtimal, şübhə bildirir və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "B": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "C": "Sərnişinlər avtobusa dalbadal mindilər.", "D": "Məhz bu kənddə böyük şair doğulub.", "E": "Bəs sən hara gedirsən?"}'::jsonb, 'A', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «Ehtimal ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6011, 78, 'g10-aze-modal-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, feili bağlama yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Bir sözlə, hamı məmnun qaldı.", "B": "Uşaq vazanı bilərəkdən sındırmamışdı.", "C": "Axı biz bu yolu tanımırıq.", "D": "Mən üzməyi yayda öyrəndim.", "E": "Uşaq şirniyyatı gizlicə yedi."}'::jsonb, 'A', NULL, '«Bir sözlə, hamı məmnun qaldı.»: «Bir sözlə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
