INSERT INTO public.questions VALUES (6013, 78, 'g10-aze-modal-q2-23', 2, 23, 'hard', 'single', '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 0; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «Xoşbəxtlikdən» — modal söz. Düzgün: modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
