INSERT INTO public.questions VALUES (6030, 78, 'g10-aze-modal-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə modal söz var, xəbər feillə ifadə olunub və sifət yoxdur?', NULL, NULL, '{"A": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "B": "Mahnı oxuya-oxuya işləyirdi.", "C": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "D": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'C', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «Yəqin» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6031, 78, 'g10-aze-modal-q3-11', 3, 11, 'medium', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir və say yoxdur?', NULL, NULL, '{"A": "Ura, bayram gəldi!", "B": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "C": "Ah, köhnə dostumu uzun müddət görmədim!", "D": "Qardaşım məktubu qələm ilə yazdı.", "E": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım."}'::jsonb, 'B', NULL, '«Sözsüz, sizin əməyiniz qiymətləndiriləcək.»: «Sözsüz» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6032, 78, 'g10-aze-modal-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə modal söz ehtimal, şübhə bildirir, say yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "C": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "D": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'E', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: «Yəqin» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6033, 78, 'g10-aze-modal-q3-13', 3, 13, 'medium', 'single', 'Hansı cümlədə modal söz sevinc bildirir və ədat yoxdur?', NULL, NULL, '{"A": "Üç-dörd günə qədər işimizi bitirəcəyik.", "B": "Biz iki-üç saat gözlədik.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Mahnı oxuya-oxuya işləyirdi.", "E": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'E', NULL, '«Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.»: «Xoşbəxtlikdən» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6034, 78, 'g10-aze-modal-q3-14', 3, 14, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "modal söz — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "modal söz — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: «Ehtimal ki» — modal söz. Düzgün: modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (6035, 78, 'g10-aze-modal-q3-15', 3, 15, 'medium', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir və feili sifət yoxdur?', NULL, NULL, '{"A": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "E": "Yarışa on səkkiz komanda qatıldı."}'::jsonb, 'B', NULL, '«Əlbəttə, biz sizə inanırıq.»: «Əlbəttə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6036, 78, 'g10-aze-modal-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə modal söz təəssüf bildirir, təyin yoxdur və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Bəs sən hara gedirsən?", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Mən üzməyi yayda öyrəndim.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'C', NULL, '«Təəssüf ki, mən toya getmədim.»: «Təəssüf ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
