INSERT INTO public.questions VALUES (6054, 79, 'g10-aze-nida-q1-04', 1, 4, 'medium', 'single', 'Hansı cümlədə nida müraciətsiz işlənib və təyin var?', NULL, NULL, '{"A": "Qoy hamı bu həqiqəti bilsin.", "B": "O, ikinci dəfə bu şəhərə gəlir.", "C": "Ah, köhnə dostumu uzun müddət görmədim!", "D": "Yarışa on səkkiz komanda qatıldı.", "E": "Yəqin, siz bu xəbəri dünən eşitmisiniz."}'::jsonb, 'C', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
