INSERT INTO public.questions VALUES (6056, 79, 'g10-aze-nida-q1-06', 1, 6, 'medium', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib və ədat yoxdur?', NULL, NULL, '{"A": "Biz çayın sahili ilə xeyli getdik.", "B": "Yarışa on səkkiz komanda qatıldı.", "C": "Dərslərini oxumadan oynamağa getdi.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Oxumaq insanı zənginləşdirir."}'::jsonb, 'D', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
