INSERT INTO public.questions VALUES (6071, 79, 'g10-aze-nida-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, vasitəsiz tamamlıq yoxdur və cümlə nida cümləsidir?', NULL, NULL, '{"A": "Ah, köhnə dostumu uzun müddət görmədim!", "B": "Ura, bayram gəldi!", "C": "O, ikinci dəfə bu şəhərə gəlir.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'B', NULL, '«Ura, bayram gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6072, 79, 'g10-aze-nida-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə nida müraciətlə birlikdə işlənib, ədat yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Bacım məndən kitab istədi.", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Danışmaq asandır.", "D": "Ay qızım, bu sözləri kimdən eşitdin?", "E": "Heç nə demədən otaqdan çıxdı."}'::jsonb, 'D', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6073, 79, 'g10-aze-nida-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə nida var, feili sifət yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Yalnız zəhmət insanı ucaldır.", "C": "Heç nə demədən otaqdan çıxdı.", "D": "Ey gənclər, Vətəni sevin!", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'D', NULL, '«Ey gənclər, Vətəni sevin!»: «Ey» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6074, 79, 'g10-aze-nida-q1-24', 1, 24, 'medium', 'single', 'Hansı cümlədə nida müraciətlə birlikdə işlənib və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "B": "Bu məktubu özüm yazacağam.", "C": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "D": "Qoy hamı bu həqiqəti bilsin.", "E": "Ay Leyla, pəncərəni bağla!"}'::jsonb, 'E', NULL, '«Ay Leyla, pəncərəni bağla!»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6075, 79, 'g10-aze-nida-q1-25', 1, 25, 'hard', 'single', '«Ah, köhnə dostumu uzun müddət görmədim!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6076, 79, 'g10-aze-nida-q1-26', 1, 26, 'hard', 'single', '«Əhsən! Bu rəsmi kim çəkib?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 0; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Əhsən» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6077, 79, 'g10-aze-nida-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, zərflik var və zərf yoxdur?', NULL, NULL, '{"A": "Məhz bu kənddə böyük şair doğulub.", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Ah, köhnə dostumu uzun müddət görmədim!", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Yağışa görə oyun dayandırıldı."}'::jsonb, 'C', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6078, 79, 'g10-aze-nida-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, zərf yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "B": "Anam ilə atam toya getdilər.", "C": "Təəssüf ki, mən toya getmədim.", "D": "Ah, köhnə dostumu uzun müddət görmədim!", "E": "Qardaşım məktubu qələm ilə yazdı."}'::jsonb, 'D', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
