INSERT INTO public.questions VALUES (6080, 79, 'g10-aze-nida-q1-30', 1, 30, 'medium', 'single', 'Hansı cümlədə nida var və feili sifət yoxdur?', NULL, NULL, '{"A": "Anam ilə atam toya getdilər.", "B": "Heç nə demədən otaqdan çıxdı.", "C": "Biz iki-üç saat gözlədik.", "D": "Ah, köhnə dostumu uzun müddət görmədim!", "E": "Ya sabah, ya da birigün gələcəyəm."}'::jsonb, 'D', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
