INSERT INTO public.questions VALUES (6093, 79, 'g10-aze-nida-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, say yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Həm oxuyur, həm də işləyir.", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Dərslərini oxumadan oynamağa getdi."}'::jsonb, 'B', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6094, 79, 'g10-aze-nida-q2-14', 2, 14, 'medium', 'single', 'Hansı cümlədə nida müraciətsiz işlənib və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Hansı şəhərdə doğulmusan?", "B": "Anam ilə atam toya getdilər.", "C": "Məhz bu kənddə böyük şair doğulub.", "D": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "E": "Ura, bayram gəldi!"}'::jsonb, 'E', NULL, '«Ura, bayram gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6095, 79, 'g10-aze-nida-q2-15', 2, 15, 'hard', 'single', '«Ah, köhnə dostumu uzun müddət görmədim!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6096, 79, 'g10-aze-nida-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, qoşma yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Həm oxuyur, həm də işləyir.", "B": "Of, bu çanta ağırdır!", "C": "Ay qızım, bu sözləri kimdən eşitdin?", "D": "Ay Leyla, pəncərəni bağla!", "E": "Ya sabah, ya da birigün gələcəyəm."}'::jsonb, 'B', NULL, '«Of, bu çanta ağırdır!»: «Of» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6097, 79, 'g10-aze-nida-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə nida var, qoşma yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Yalnız zəhmət insanı ucaldır.", "B": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "C": "Bağda alma, armud və heyva yetişmişdi.", "D": "Bəs sən hara gedirsən?", "E": "Ura, bayram gəldi!"}'::jsonb, 'E', NULL, '«Ura, bayram gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6098, 79, 'g10-aze-nida-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə nida var, vasitəli tamamlıq yoxdur və zərflik yoxdur?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin?", "B": "Ey gənclər, Vətəni sevin!", "C": "Danışmaq asandır.", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'B', NULL, '«Ey gənclər, Vətəni sevin!»: «Ey» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6099, 79, 'g10-aze-nida-q2-19', 2, 19, 'medium', 'single', 'Hansı cümlədə nida var və cümlə sual cümləsidir?', NULL, NULL, '{"A": "Ay Leyla, pəncərəni bağla!", "B": "Ah, köhnə dostumu uzun müddət görmədim!", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Ey gənclər, Vətəni sevin!", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
