INSERT INTO public.questions VALUES (6116, 79, 'g10-aze-nida-q3-06', 3, 6, 'medium', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib və mübtəda var?', NULL, NULL, '{"A": "Biz stansiyada qatarı xeyli gözlədik.", "B": "Qoy hamı bu həqiqəti bilsin.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Yalnız zəhmət insanı ucaldır.", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6117, 79, 'g10-aze-nida-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə nida var, məsdər yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Tortun dörddə birini qonaqlara verdik.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Ura, bayram gəldi!", "E": "Bu, lap yeni maşındır."}'::jsonb, 'D', NULL, '«Ura, bayram gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6118, 79, 'g10-aze-nida-q3-08', 3, 8, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6119, 79, 'g10-aze-nida-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, mübtəda var və cümlə nida cümləsidir?', NULL, NULL, '{"A": "Bu məktubu özüm yazacağam.", "B": "Əhsən! Bu rəsmi kim çəkib?", "C": "Vay, buzlu yolda maşın sürüşdü!", "D": "Ah, köhnə dostumu uzun müddət görmədim!", "E": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular."}'::jsonb, 'C', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «Vay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6120, 79, 'g10-aze-nida-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, məsdər yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Mahnı oxuya-oxuya işləyirdi.", "B": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Məhz bu kənddə böyük şair doğulub."}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
