INSERT INTO public.questions VALUES (6135, 79, 'g10-aze-nida-q3-25', 3, 25, 'hard', 'single', '«Vay, buzlu yolda maşın sürüşdü!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Vay, buzlu yolda maşın sürüşdü!»: «Vay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6136, 79, 'g10-aze-nida-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə nida var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Hansı şəhərdə doğulmusan?", "B": "Ey gənclər, Vətəni sevin!", "C": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "D": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "E": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı."}'::jsonb, 'B', NULL, '«Ey gənclər, Vətəni sevin!»: «Ey» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (6137, 79, 'g10-aze-nida-q3-27', 3, 27, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6138, 79, 'g10-aze-nida-q3-28', 3, 28, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6139, 79, 'g10-aze-nida-q3-29', 3, 29, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6140, 79, 'g10-aze-nida-q3-30', 3, 30, 'hard', 'single', '«Ah, köhnə dostumu uzun müddət görmədim!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ah, köhnə dostumu uzun müddət görmədim!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (6141, 80, 'g10-aze-member-q1-01', 1, 1, 'medium', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və təyin var?', NULL, NULL, '{"A": "Axı biz bu yolu tanımırıq.", "B": "Təəssüf ki, mən toya getmədim.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Onuncu sinfin şagirdləri teatra getdilər.", "E": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'A', NULL, '«Axı biz bu yolu tanımırıq.»: mübtəda — biz; təyin — bu; vasitəsiz tamamlıq — yolu; xəbər — tanımırıq.');
INSERT INTO public.questions VALUES (6142, 80, 'g10-aze-member-q1-02', 1, 2, 'hard', 'single', '«Atam mənim üçün velosiped aldı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Atam — vasitəsiz tamamlıq; mənim üçün — vasitəli tamamlıq; velosiped — vasitəsiz tamamlıq; aldı — xəbər", "B": "Atam — vasitəsiz tamamlıq; mənim üçün — vasitəli tamamlıq; velosiped — mübtəda; aldı — xəbər", "C": "Atam — mübtəda; mənim üçün — vasitəli tamamlıq; velosiped — vasitəsiz tamamlıq; aldı — mübtəda", "D": "Atam — mübtəda; mənim üçün — vasitəli tamamlıq; velosiped — vasitəsiz tamamlıq; aldı — xəbər", "E": "Atam — mübtəda; mənim üçün — vasitəli tamamlıq; velosiped — mübtəda; aldı — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Atam — mübtəda; mənim üçün — vasitəli tamamlıq; velosiped — vasitəsiz tamamlıq; aldı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6143, 80, 'g10-aze-member-q1-03', 1, 3, 'medium', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və zərflik var?', NULL, NULL, '{"A": "Bəs sən hara gedirsən?", "B": "Mahnı oxuya-oxuya işləyirdi.", "C": "Axı biz bu yolu tanımırıq.", "D": "Heç nə demədən otaqdan çıxdı.", "E": "Uşaq şirniyyatı gizlicə yedi."}'::jsonb, 'A', NULL, '«Bəs sən hara gedirsən?»: mübtəda — sən; zərflik — hara; xəbər — gedirsən.');
INSERT INTO public.questions VALUES (6144, 80, 'g10-aze-member-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Of, bu çanta «ağırdır»!", "B": "Danışmaq «asandır».", "C": "Əlbəttə, biz sizə «inanırıq».", "D": "Ah, köhnə «dostumu» uzun müddət görmədim!", "E": "Bu, lap yeni «maşındır»."}'::jsonb, 'C', NULL, '«inanırıq» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6145, 80, 'g10-aze-member-q1-05', 1, 5, 'hard', 'single', '«Üç-dörd günə qədər işimizi bitirəcəyik.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Üç-dörd — təyin; günə qədər — xəbər; işimizi — vasitəsiz tamamlıq; bitirəcəyik — zərflik", "B": "Üç-dörd — təyin; günə qədər — zərflik; işimizi — vasitəsiz tamamlıq; bitirəcəyik — xəbər", "C": "Üç-dörd — təyin; günə qədər — zərflik; işimizi — mübtəda; bitirəcəyik — xəbər", "D": "Üç-dörd — zərflik; günə qədər — zərflik; işimizi — vasitəsiz tamamlıq; bitirəcəyik — xəbər", "E": "Üç-dörd — mübtəda; günə qədər — zərflik; işimizi — vasitəsiz tamamlıq; bitirəcəyik — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Üç-dörd — təyin; günə qədər — zərflik; işimizi — vasitəsiz tamamlıq; bitirəcəyik — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6146, 80, 'g10-aze-member-q1-06', 1, 6, 'hard', 'single', '«Həm riyaziyyatı, həm də fizikanı sevirəm.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "riyaziyyatı — vasitəsiz tamamlıq; fizikanı — vasitəsiz tamamlıq; sevirəm — xəbər", "B": "riyaziyyatı — vasitəsiz tamamlıq; fizikanı — vasitəli tamamlıq; sevirəm — xəbər", "C": "riyaziyyatı — vasitəsiz tamamlıq; fizikanı — xəbər; sevirəm — vasitəsiz tamamlıq", "D": "riyaziyyatı — mübtəda; fizikanı — vasitəsiz tamamlıq; sevirəm — xəbər", "E": "riyaziyyatı — vasitəsiz tamamlıq; fizikanı — vasitəsiz tamamlıq; sevirəm — mübtəda"}'::jsonb, 'A', NULL, 'Düzgün: riyaziyyatı — vasitəsiz tamamlıq; fizikanı — vasitəsiz tamamlıq; sevirəm — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6147, 80, 'g10-aze-member-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəli tamamlıq var və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Əlbəttə, biz sizə inanırıq.", "B": "Bu məktubu özüm yazacağam.", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Ay qızım, bu sözləri kimdən eşitdin?"}'::jsonb, 'E', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: təyin — bu; vasitəsiz tamamlıq — sözləri; vasitəli tamamlıq — kimdən; xəbər — eşitdin.');
INSERT INTO public.questions VALUES (6148, 80, 'g10-aze-member-q1-08', 1, 8, 'hard', 'single', '«Mən üzməyi yayda öyrəndim.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Mən — mübtəda; üzməyi — xəbər; yayda — zərflik; öyrəndim — vasitəsiz tamamlıq", "B": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — təyin", "C": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər", "D": "Mən — mübtəda; üzməyi — zərflik; yayda — vasitəsiz tamamlıq; öyrəndim — xəbər", "E": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — mübtəda"}'::jsonb, 'C', NULL, 'Düzgün: Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6149, 80, 'g10-aze-member-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "«Mən» üzməyi yayda öyrəndim.", "B": "«Ucadan» gülən uşaqlar müəllimi görüb susdular.", "C": "Bəs «sən» hara gedirsən?", "D": "Bu məktubu «özüm» yazacağam.", "E": "«Hansı» şəhərdə doğulmusan?"}'::jsonb, 'E', NULL, '«Hansı» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6150, 80, 'g10-aze-member-q1-10', 1, 10, 'hard', 'single', '«Təəssüf ki, mən toya getmədim.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "mən — təyin; toya — zərflik; getmədim — xəbər", "B": "mən — xəbər; toya — zərflik; getmədim — mübtəda", "C": "mən — mübtəda; toya — təyin; getmədim — xəbər", "D": "mən — zərflik; toya — mübtəda; getmədim — xəbər", "E": "mən — mübtəda; toya — zərflik; getmədim — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: mən — mübtəda; toya — zərflik; getmədim — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6151, 80, 'g10-aze-member-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Qoy hamı bu «həqiqəti» bilsin.", "B": "«Yağışa» görə oyun dayandırıldı.", "C": "Üç-dörd «günə» qədər işimizi bitirəcəyik.", "D": "Ura, «bayram» gəldi!", "E": "Ehtimal ki, «qonaqlar» axşama kimi gələcəklər."}'::jsonb, 'A', NULL, '«həqiqəti» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6152, 80, 'g10-aze-member-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "«Üç-dörd» günə qədər işimizi bitirəcəyik.", "B": "Atam «mənim» üçün velosiped aldı.", "C": "Axı «biz» bu yolu tanımırıq.", "D": "Ay qızım, «bu» sözləri kimdən eşitdin?", "E": "Biz «sizdən» sonra gəldik."}'::jsonb, 'D', NULL, '«bu» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6153, 80, 'g10-aze-member-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Of, bu çanta «ağırdır»!", "B": "Bu, lap yeni «maşındır».", "C": "Danışmaq «asandır».", "D": "Məhz bu «kənddə» böyük şair doğulub.", "E": "Həm «oxuyur», həm də işləyir."}'::jsonb, 'E', NULL, '«oxuyur» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6154, 80, 'g10-aze-member-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Yağışa görə oyun «dayandırıldı».", "B": "Gələn «həftə» sinfimiz təbiət muzeyinə gedəcək.", "C": "Bu «məktubu» özüm yazacağam.", "D": "Mən üzməyi yayda «öyrəndim».", "E": "Bu, lap yeni «maşındır»."}'::jsonb, 'E', NULL, '«maşındır» — xəbər, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6155, 80, 'g10-aze-member-q1-15', 1, 15, 'hard', 'single', '«Qoy hamı bu həqiqəti bilsin.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "hamı — mübtəda; bu — təyin; həqiqəti — mübtəda; bilsin — xəbər", "B": "hamı — mübtəda; bu — təyin; həqiqəti — vasitəsiz tamamlıq; bilsin — xəbər", "C": "hamı — vasitəsiz tamamlıq; bu — təyin; həqiqəti — mübtəda; bilsin — xəbər", "D": "hamı — xəbər; bu — təyin; həqiqəti — vasitəsiz tamamlıq; bilsin — mübtəda", "E": "hamı — mübtəda; bu — təyin; həqiqəti — vasitəli tamamlıq; bilsin — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: hamı — mübtəda; bu — təyin; həqiqəti — vasitəsiz tamamlıq; bilsin — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6156, 80, 'g10-aze-member-q1-16', 1, 16, 'medium', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və təyin var?', NULL, NULL, '{"A": "Biz sizdən sonra gəldik.", "B": "Biz iki-üç saat gözlədik.", "C": "Sərnişinlər avtobusa dalbadal mindilər.", "D": "Mahnı oxuya-oxuya işləyirdi.", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'B', NULL, '«Biz iki-üç saat gözlədik.»: mübtəda — Biz; təyin — iki-üç; zərflik — saat; xəbər — gözlədik.');
INSERT INTO public.questions VALUES (6157, 80, 'g10-aze-member-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə xəbər ismi xəbərdir (isim və ya sifətlə ifadə olunub), vasitəli tamamlıq yoxdur və təyin var?', NULL, NULL, '{"A": "Of, bu çanta ağırdır!", "B": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "C": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Yazılmış məktubu poçta apardım."}'::jsonb, 'A', NULL, '«Of, bu çanta ağırdır!»: təyin — bu; mübtəda — çanta; xəbər — ağırdır.');
INSERT INTO public.questions VALUES (6158, 80, 'g10-aze-member-q1-18', 1, 18, 'hard', 'single', '«Qardaşım məktubu qələm ilə yazdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Qardaşım — mübtəda; məktubu — xəbər; qələm ilə — vasitəli tamamlıq; yazdı — vasitəsiz tamamlıq", "B": "Qardaşım — mübtəda; məktubu — vasitəsiz tamamlıq; qələm ilə — vasitəli tamamlıq; yazdı — xəbər", "C": "Qardaşım — mübtəda; məktubu — vasitəsiz tamamlıq; qələm ilə — vasitəli tamamlıq; yazdı — mübtəda", "D": "Qardaşım — təyin; məktubu — vasitəsiz tamamlıq; qələm ilə — vasitəli tamamlıq; yazdı — xəbər", "E": "Qardaşım — mübtəda; məktubu — vasitəsiz tamamlıq; qələm ilə — vasitəli tamamlıq; yazdı — təyin"}'::jsonb, 'B', NULL, 'Düzgün: Qardaşım — mübtəda; məktubu — vasitəsiz tamamlıq; qələm ilə — vasitəli tamamlıq; yazdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6159, 80, 'g10-aze-member-q1-19', 1, 19, 'hard', 'single', '«Gələn həftə sinfimiz təbiət muzeyinə gedəcək.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Gələn — təyin; həftə — zərflik; sinfimiz — mübtəda; təbiət — təyin; muzeyinə — xəbər; gedəcək — zərflik", "B": "Gələn — təyin; həftə — zərflik; sinfimiz — mübtəda; təbiət — xəbər; muzeyinə — zərflik; gedəcək — təyin", "C": "Gələn — təyin; həftə — xəbər; sinfimiz — mübtəda; təbiət — təyin; muzeyinə — zərflik; gedəcək — zərflik", "D": "Gələn — təyin; həftə — zərflik; sinfimiz — mübtəda; təbiət — təyin; muzeyinə — zərflik; gedəcək — xəbər", "E": "Gələn — təyin; həftə — zərflik; sinfimiz — mübtəda; təbiət — zərflik; muzeyinə — təyin; gedəcək — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Gələn — təyin; həftə — zərflik; sinfimiz — mübtəda; təbiət — təyin; muzeyinə — zərflik; gedəcək — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6160, 80, 'g10-aze-member-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Yəqin, siz bu «xəbəri» dünən eşitmisiniz.", "B": "Danışmaq «asandır».", "C": "Ay qızım, bu sözləri kimdən «eşitdin»?", "D": "Of, bu çanta «ağırdır»!", "E": "Bu, lap yeni «maşındır»."}'::jsonb, 'C', NULL, '«eşitdin» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6161, 80, 'g10-aze-member-q1-21', 1, 21, 'medium', 'single', 'Hansı cümlədə təyin feili sifət və ya onun tərkibi ilə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Dərslərini oxumadan oynamağa getdi.", "B": "Uşaq şirniyyatı gizlicə yedi.", "C": "Axı biz bu yolu tanımırıq.", "D": "Bəs sən hara gedirsən?", "E": "Kitabxanadan götürdüyüm kitabları vaxtında qaytardım."}'::jsonb, 'E', NULL, '«Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.»: təyin — Kitabxanadan götürdüyüm; vasitəsiz tamamlıq — kitabları; zərflik — vaxtında; xəbər — qaytardım.');
INSERT INTO public.questions VALUES (6162, 80, 'g10-aze-member-q1-22', 1, 22, 'hard', 'single', '«Tortun dörddə birini qonaqlara verdik.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəsiz tamamlıq; verdik — xəbər", "B": "Tortun — mübtəda; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər", "C": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — təyin", "D": "Tortun — təyin; dörddə birini — mübtəda; qonaqlara — vasitəli tamamlıq; verdik — xəbər", "E": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6163, 80, 'g10-aze-member-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, mübtəda var və zərflik var?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Ya sabah, ya da birigün gələcəyəm.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Bu məktubu özüm yazacağam.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'A', NULL, '«Onuncu sinfin şagirdləri teatra getdilər.»: təyin — Onuncu sinfin; mübtəda — şagirdləri; zərflik — teatra; xəbər — getdilər.');
INSERT INTO public.questions VALUES (6164, 80, 'g10-aze-member-q1-24', 1, 24, 'medium', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Danışmaq asandır.", "B": "Məhz bu kənddə böyük şair doğulub.", "C": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "D": "Ay Leyla, pəncərəni bağla!", "E": "Vay, buzlu yolda maşın sürüşdü!"}'::jsonb, 'C', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: mübtəda — Biz; təyin — dağın; zərflik — zirvəsinə doğru yuxarı; xəbər — qalxdıq.');
INSERT INTO public.questions VALUES (6165, 80, 'g10-aze-member-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə «meyvə» uzatdı.", "B": "Gələn həftə sinfimiz təbiət «muzeyinə» gedəcək.", "C": "Qəhrəmancasına vuruşan «əsgərlər» düşməni geri oturtdular.", "D": "Əhsən! Bu «rəsmi» kim çəkib?", "E": "Anam ilə «atam» toya getdilər."}'::jsonb, 'B', NULL, '«muzeyinə» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6166, 80, 'g10-aze-member-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub, xəbər feillə ifadə olunub və təyin əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin?", "B": "Biz iki-üç saat gözlədik.", "C": "Biz sizdən sonra gəldik.", "D": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "E": "Məhz bu kənddə böyük şair doğulub."}'::jsonb, 'D', NULL, '«Yəqin, siz bu xəbəri dünən eşitmisiniz.»: mübtəda — siz; təyin — bu; vasitəsiz tamamlıq — xəbəri; zərflik — dünən; xəbər — eşitmisiniz.');
INSERT INTO public.questions VALUES (6167, 80, 'g10-aze-member-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "«Atam» mənim üçün velosiped aldı.", "B": "Qatar «stansiyaya» çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "«Anam» ilə atam toya getdilər.", "D": "«Qatar» stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "E": "Əhsən! Bu «rəsmi» kim çəkib?"}'::jsonb, 'E', NULL, '«rəsmi» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6168, 80, 'g10-aze-member-q1-28', 1, 28, 'medium', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub və zərflik yoxdur?', NULL, NULL, '{"A": "Məhz bu kənddə böyük şair doğulub.", "B": "Yarışa on səkkiz komanda qatıldı.", "C": "Uşaq şirniyyatı gizlicə yedi.", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Onuncu sinfin şagirdləri teatra getdilər."}'::jsonb, 'B', NULL, '«Yarışa on səkkiz komanda qatıldı.»: vasitəli tamamlıq — Yarışa; təyin — on səkkiz; mübtəda — komanda; xəbər — qatıldı.');
INSERT INTO public.questions VALUES (6169, 80, 'g10-aze-member-q1-29', 1, 29, 'hard', 'single', '«Mən üzməyi yayda öyrəndim.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Mən — vasitəsiz tamamlıq; üzməyi — mübtəda; yayda — zərflik; öyrəndim — xəbər", "B": "Mən — mübtəda; üzməyi — zərflik; yayda — vasitəsiz tamamlıq; öyrəndim — xəbər", "C": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — vasitəli tamamlıq; öyrəndim — xəbər", "D": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər", "E": "Mən — xəbər; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — mübtəda"}'::jsonb, 'D', NULL, 'Düzgün: Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6170, 80, 'g10-aze-member-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Ucadan gülən «uşaqlar» müəllimi görüb susdular.", "B": "Gələn həftə «sinfimiz» təbiət muzeyinə gedəcək.", "C": "Uşaq «şirniyyatı» gizlicə yedi.", "D": "Qatar stansiyaya çatan kimi «sərnişinlər» vaqonlardan düşdülər.", "E": "Gələn həftə sinfimiz təbiət «muzeyinə» gedəcək."}'::jsonb, 'C', NULL, '«şirniyyatı» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6171, 80, 'g10-aze-member-q2-01', 2, 1, 'hard', 'single', '«Yazılmış məktubu poçta apardım.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Yazılmış — təyin; məktubu — vasitəsiz tamamlıq; poçta — xəbər; apardım — zərflik", "B": "Yazılmış — xəbər; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — təyin", "C": "Yazılmış — təyin; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — xəbər", "D": "Yazılmış — təyin; məktubu — zərflik; poçta — vasitəsiz tamamlıq; apardım — xəbər", "E": "Yazılmış — təyin; məktubu — mübtəda; poçta — zərflik; apardım — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Yazılmış — təyin; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6172, 80, 'g10-aze-member-q2-02', 2, 2, 'medium', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda yoxdur?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Bu məktubu özüm yazacağam.", "C": "Üç-dörd günə qədər işimizi bitirəcəyik.", "D": "Yarışa on səkkiz komanda qatıldı.", "E": "Ən çətin sualları hətta kiçik qardaşım tapdı."}'::jsonb, 'C', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: təyin — Üç-dörd; zərflik — günə qədər; vasitəsiz tamamlıq — işimizi; xəbər — bitirəcəyik.');
INSERT INTO public.questions VALUES (6173, 80, 'g10-aze-member-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Bu, lap yeni «maşındır».", "B": "Tortun dörddə birini qonaqlara «verdik».", "C": "Yarışa «on səkkiz» komanda qatıldı.", "D": "Of, bu çanta «ağırdır»!", "E": "Danışmaq «asandır»."}'::jsonb, 'B', NULL, '«verdik» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6174, 80, 'g10-aze-member-q2-04', 2, 4, 'hard', 'single', '«Mən üzməyi yayda öyrəndim.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Mən — vasitəsiz tamamlıq; üzməyi — mübtəda; yayda — zərflik; öyrəndim — xəbər", "B": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — mübtəda", "C": "Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər", "D": "Mən — təyin; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər", "E": "Mən — vasitəsiz tamamlıq; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Mən — mübtəda; üzməyi — vasitəsiz tamamlıq; yayda — zərflik; öyrəndim — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6175, 80, 'g10-aze-member-q2-05', 2, 5, 'hard', 'single', '«Biz sizdən sonra gəldik.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Biz — mübtəda; sizdən sonra — zərflik; gəldik — təyin", "B": "Biz — xəbər; sizdən sonra — zərflik; gəldik — mübtəda", "C": "Biz — mübtəda; sizdən sonra — zərflik; gəldik — xəbər", "D": "Biz — vasitəsiz tamamlıq; sizdən sonra — zərflik; gəldik — xəbər", "E": "Biz — mübtəda; sizdən sonra — təyin; gəldik — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Biz — mübtəda; sizdən sonra — zərflik; gəldik — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6176, 80, 'g10-aze-member-q2-06', 2, 6, 'hard', 'single', '«Tortun dörddə birini qonaqlara verdik.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Tortun — zərflik; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər", "B": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər", "C": "Tortun — vasitəli tamamlıq; dörddə birini — vasitəsiz tamamlıq; qonaqlara — təyin; verdik — xəbər", "D": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — mübtəda", "E": "Tortun — təyin; dörddə birini — vasitəli tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6177, 80, 'g10-aze-member-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub, zərflik var və təyin yoxdur?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "O, ikinci dəfə bu şəhərə gəlir.", "C": "Biz stansiyada qatarı xeyli gözlədik.", "D": "Heç nə demədən otaqdan çıxdı.", "E": "Ehtimal ki, qonaqlar axşama kimi gələcəklər."}'::jsonb, 'C', NULL, '«Biz stansiyada qatarı xeyli gözlədik.»: mübtəda — Biz; zərflik — stansiyada; vasitəsiz tamamlıq — qatarı; zərflik — xeyli; xəbər — gözlədik.');
INSERT INTO public.questions VALUES (6178, 80, 'g10-aze-member-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəsiz tamamlıq yoxdur və zərflik feili bağlama və ya onun tərkibi ilə ifadə olunub?', NULL, NULL, '{"A": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "B": "Anam ilə atam toya getdilər.", "C": "Heç nə demədən otaqdan çıxdı.", "D": "Ura, bayram gəldi!", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'C', NULL, '«Heç nə demədən otaqdan çıxdı.»: zərflik — Heç nə demədən otaqdan; xəbər — çıxdı.');
INSERT INTO public.questions VALUES (6179, 80, 'g10-aze-member-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, mübtəda yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "B": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "C": "Hansı şəhərdə doğulmusan?", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'B', NULL, '«Həm riyaziyyatı, həm də fizikanı sevirəm.»: vasitəsiz tamamlıq — riyaziyyatı; vasitəsiz tamamlıq — fizikanı; xəbər — sevirəm.');
INSERT INTO public.questions VALUES (6180, 80, 'g10-aze-member-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Yəqin, siz bu «xəbəri» dünən eşitmisiniz.", "B": "Ehtimal ki, «qonaqlar» axşama kimi gələcəklər.", "C": "O, ikinci «dəfə» bu şəhərə gəlir.", "D": "Yəqin, siz bu xəbəri «dünən» eşitmisiniz.", "E": "Gələn həftə «sinfimiz» təbiət muzeyinə gedəcək."}'::jsonb, 'C', NULL, '«dəfə» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6181, 80, 'g10-aze-member-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, vasitəsiz tamamlıq var və təyin yoxdur?', NULL, NULL, '{"A": "Mən üzməyi yayda öyrəndim.", "B": "Ən çətin sualları hətta kiçik qardaşım tapdı.", "C": "Həm riyaziyyatı, həm də fizikanı sevirəm.", "D": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "E": "Yalnız zəhmət insanı ucaldır."}'::jsonb, 'E', NULL, '«Yalnız zəhmət insanı ucaldır.»: mübtəda — zəhmət; vasitəsiz tamamlıq — insanı; xəbər — ucaldır.');
INSERT INTO public.questions VALUES (6182, 80, 'g10-aze-member-q2-12', 2, 12, 'medium', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və zərflik yoxdur?', NULL, NULL, '{"A": "Biz stansiyada qatarı xeyli gözlədik.", "B": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Yalnız zəhmət insanı ucaldır.", "E": "Dərslərini oxumadan oynamağa getdi."}'::jsonb, 'D', NULL, '«Yalnız zəhmət insanı ucaldır.»: mübtəda — zəhmət; vasitəsiz tamamlıq — insanı; xəbər — ucaldır.');
INSERT INTO public.questions VALUES (6183, 80, 'g10-aze-member-q2-13', 2, 13, 'medium', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və mübtəda yoxdur?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin?", "B": "Oxumaq insanı zənginləşdirir.", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Bir sözlə, hamı məmnun qaldı.", "E": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək."}'::jsonb, 'A', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: təyin — bu; vasitəsiz tamamlıq — sözləri; vasitəli tamamlıq — kimdən; xəbər — eşitdin.');
INSERT INTO public.questions VALUES (6184, 80, 'g10-aze-member-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Sən ya rəsm, ya da «musiqi» seç.", "B": "Təəssüf ki, mən «toya» getmədim.", "C": "«Danışmaq» asandır.", "D": "Uşaq «vazanı» bilərəkdən sındırmamışdı.", "E": "Ucadan gülən «uşaqlar» müəllimi görüb susdular."}'::jsonb, 'E', NULL, '«uşaqlar» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6185, 80, 'g10-aze-member-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, zərflik var və mübtəda yoxdur?', NULL, NULL, '{"A": "Üç-dörd günə qədər işimizi bitirəcəyik.", "B": "Tortun dörddə birini qonaqlara verdik.", "C": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "D": "Təəssüf ki, mən toya getmədim.", "E": "Biz stansiyada qatarı xeyli gözlədik."}'::jsonb, 'A', NULL, '«Üç-dörd günə qədər işimizi bitirəcəyik.»: təyin — Üç-dörd; zərflik — günə qədər; vasitəsiz tamamlıq — işimizi; xəbər — bitirəcəyik.');
INSERT INTO public.questions VALUES (6186, 80, 'g10-aze-member-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "«Qardaşım» məktubu qələm ilə yazdı.", "B": "«Yağışa» görə oyun dayandırıldı.", "C": "Atam mənim üçün «velosiped» aldı.", "D": "Əhsən! Bu rəsmi «kim» çəkib?", "E": "Anam ilə atam «toya» getdilər."}'::jsonb, 'A', NULL, '«Qardaşım» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6187, 80, 'g10-aze-member-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Sözsüz, sizin «əməyiniz» qiymətləndiriləcək.", "B": "Yağışa görə «oyun» dayandırıldı.", "C": "Yazılmış «məktubu» poçta apardım.", "D": "Məhz bu «kənddə» böyük şair doğulub.", "E": "Ehtimal ki, qonaqlar «axşama» kimi gələcəklər."}'::jsonb, 'C', NULL, '«məktubu» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6188, 80, 'g10-aze-member-q2-18', 2, 18, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəsiz tamamlıq; eşitdin — xəbər", "B": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — təyin", "C": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — mübtəda", "D": "bu — zərflik; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — xəbər", "E": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6189, 80, 'g10-aze-member-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir və məsdərlə ifadə olunub?', NULL, NULL, '{"A": "«Anam» ilə atam toya getdilər.", "B": "Əlbəttə, «biz» sizə inanırıq.", "C": "«Danışmaq» asandır.", "D": "«Bacım» məndən kitab istədi.", "E": "«Atam» mənim üçün velosiped aldı."}'::jsonb, 'C', NULL, '«Danışmaq» — mübtəda, məsdər. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6190, 80, 'g10-aze-member-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə zərflik qoşmalı birləşmə ilə ifadə olunub, mübtəda əvəzliklə ifadə olunub və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "B": "Bir sözlə, hamı məmnun qaldı.", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Təəssüf ki, mən toya getmədim."}'::jsonb, 'A', NULL, '«Biz dağın zirvəsinə doğru yuxarı qalxdıq.»: mübtəda — Biz; təyin — dağın; zərflik — zirvəsinə doğru yuxarı; xəbər — qalxdıq.');
INSERT INTO public.questions VALUES (6191, 80, 'g10-aze-member-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Bu, lap yeni «maşındır».", "B": "Of, bu çanta «ağırdır»!", "C": "Danışmaq «asandır».", "D": "Qoy hamı bu həqiqəti «bilsin».", "E": "O, ikinci dəfə «bu» şəhərə gəlir."}'::jsonb, 'D', NULL, '«bilsin» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6192, 80, 'g10-aze-member-q2-22', 2, 22, 'hard', 'single', '«Oxumaq insanı zənginləşdirir.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Oxumaq — mübtəda; insanı — vasitəsiz tamamlıq; zənginləşdirir — təyin", "B": "Oxumaq — vasitəsiz tamamlıq; insanı — mübtəda; zənginləşdirir — xəbər", "C": "Oxumaq — mübtəda; insanı — vasitəsiz tamamlıq; zənginləşdirir — xəbər", "D": "Oxumaq — mübtəda; insanı — vasitəli tamamlıq; zənginləşdirir — xəbər", "E": "Oxumaq — mübtəda; insanı — xəbər; zənginləşdirir — vasitəsiz tamamlıq"}'::jsonb, 'C', NULL, 'Düzgün: Oxumaq — mübtəda; insanı — vasitəsiz tamamlıq; zənginləşdirir — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6193, 80, 'g10-aze-member-q2-23', 2, 23, 'hard', 'single', '«Bacım məndən kitab istədi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Bacım — təyin; məndən — vasitəli tamamlıq; kitab — vasitəsiz tamamlıq; istədi — xəbər", "B": "Bacım — mübtəda; məndən — xəbər; kitab — vasitəsiz tamamlıq; istədi — vasitəli tamamlıq", "C": "Bacım — vasitəli tamamlıq; məndən — mübtəda; kitab — vasitəsiz tamamlıq; istədi — xəbər", "D": "Bacım — mübtəda; məndən — zərflik; kitab — vasitəsiz tamamlıq; istədi — xəbər", "E": "Bacım — mübtəda; məndən — vasitəli tamamlıq; kitab — vasitəsiz tamamlıq; istədi — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Bacım — mübtəda; məndən — vasitəli tamamlıq; kitab — vasitəsiz tamamlıq; istədi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6194, 80, 'g10-aze-member-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəli tamamlıq vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Qardaşım məktubu «qələm» ilə yazdı.", "B": "«Mahnı» oxuya-oxuya işləyirdi.", "C": "Dostcasına gülümsəyən satıcı «bizə» təzə meyvə uzatdı.", "D": "Qatar stansiyaya çatan kimi «sərnişinlər» vaqonlardan düşdülər.", "E": "Qatar stansiyaya çatan kimi sərnişinlər «vaqonlardan» düşdülər."}'::jsonb, 'A', NULL, '«qələm» — vasitəli tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6195, 80, 'g10-aze-member-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə zərflik qoşmalı birləşmə ilə ifadə olunub, vasitəli tamamlıq yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Biz iki-üç saat gözlədik.", "D": "Mən üzməyi yayda öyrəndim.", "E": "Həm oxuyur, həm də işləyir."}'::jsonb, 'B', NULL, '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.»: mübtəda — qonaqlar; zərflik — axşama kimi; xəbər — gələcəklər.');
INSERT INTO public.questions VALUES (6196, 80, 'g10-aze-member-q2-26', 2, 26, 'hard', 'single', '«Təəssüf ki, mən toya getmədim.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "mən — mübtəda; toya — xəbər; getmədim — zərflik", "B": "mən — təyin; toya — zərflik; getmədim — xəbər", "C": "mən — vasitəsiz tamamlıq; toya — zərflik; getmədim — xəbər", "D": "mən — zərflik; toya — mübtəda; getmədim — xəbər", "E": "mən — mübtəda; toya — zərflik; getmədim — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: mən — mübtəda; toya — zərflik; getmədim — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6197, 80, 'g10-aze-member-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "«Yağışa» görə oyun dayandırıldı.", "B": "Kitabxanadan götürdüyüm «kitabları» vaxtında qaytardım.", "C": "Gələn həftə sinfimiz «təbiət» muzeyinə gedəcək.", "D": "Yəqin, «siz» bu xəbəri dünən eşitmisiniz.", "E": "«Uşaq» şirniyyatı gizlicə yedi."}'::jsonb, 'E', NULL, '«Uşaq» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6198, 80, 'g10-aze-member-q2-28', 2, 28, 'hard', 'single', '«Oxumaq insanı zənginləşdirir.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Oxumaq — mübtəda; insanı — vasitəli tamamlıq; zənginləşdirir — xəbər", "B": "Oxumaq — mübtəda; insanı — vasitəsiz tamamlıq; zənginləşdirir — təyin", "C": "Oxumaq — mübtəda; insanı — vasitəsiz tamamlıq; zənginləşdirir — xəbər", "D": "Oxumaq — xəbər; insanı — vasitəsiz tamamlıq; zənginləşdirir — mübtəda", "E": "Oxumaq — təyin; insanı — vasitəsiz tamamlıq; zənginləşdirir — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Oxumaq — mübtəda; insanı — vasitəsiz tamamlıq; zənginləşdirir — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6199, 80, 'g10-aze-member-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Biz «sizdən» sonra gəldik.", "B": "Atam «mənim» üçün velosiped aldı.", "C": "«Uşaq» şirniyyatı gizlicə yedi.", "D": "Məhz bu kənddə böyük «şair» doğulub.", "E": "Əlbəttə, «biz» sizə inanırıq."}'::jsonb, 'E', NULL, '«biz» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6200, 80, 'g10-aze-member-q2-30', 2, 30, 'hard', 'single', '«Uşaq vazanı bilərəkdən sındırmamışdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Uşaq — təyin; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər", "B": "Uşaq — xəbər; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — mübtəda", "C": "Uşaq — mübtəda; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər", "D": "Uşaq — mübtəda; vazanı — vasitəli tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər", "E": "Uşaq — mübtəda; vazanı — mübtəda; bilərəkdən — zərflik; sındırmamışdı — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Uşaq — mübtəda; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6201, 80, 'g10-aze-member-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Əhsən! Bu rəsmi «kim» çəkib?", "B": "«Uşaq» şirniyyatı gizlicə yedi.", "C": "Biz «sizdən» sonra gəldik.", "D": "Bəs sən «hara» gedirsən?", "E": "Anam ilə «atam» toya getdilər."}'::jsonb, 'A', NULL, '«kim» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6202, 80, 'g10-aze-member-q3-02', 3, 2, 'hard', 'single', '«Ay qızım, bu sözləri kimdən eşitdin?» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — zərflik; eşitdin — xəbər", "B": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — xəbər", "C": "bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — mübtəda", "D": "bu — zərflik; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — xəbər", "E": "bu — xəbər; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — təyin"}'::jsonb, 'B', NULL, 'Düzgün: bu — təyin; sözləri — vasitəsiz tamamlıq; kimdən — vasitəli tamamlıq; eşitdin — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6203, 80, 'g10-aze-member-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Biz stansiyada qatarı xeyli «gözlədik».", "B": "Qatar stansiyaya çatan kimi sərnişinlər «vaqonlardan» düşdülər.", "C": "Bu, lap yeni «maşındır».", "D": "Danışmaq «asandır».", "E": "Of, bu çanta «ağırdır»!"}'::jsonb, 'A', NULL, '«gözlədik» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6204, 80, 'g10-aze-member-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, zərflik var və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Üç-dörd günə qədər işimizi bitirəcəyik.", "B": "Ya sabah, ya da birigün gələcəyəm.", "C": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "D": "O, ikinci dəfə bu şəhərə gəlir.", "E": "Of, bu çanta ağırdır!"}'::jsonb, 'C', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.»: zərflik — Qatar stansiyaya çatan kimi; mübtəda — sərnişinlər; zərflik — vaqonlardan; xəbər — düşdülər.');
INSERT INTO public.questions VALUES (6205, 80, 'g10-aze-member-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Uşaq «vazanı» bilərəkdən sındırmamışdı.", "B": "«Mahnı» oxuya-oxuya işləyirdi.", "C": "Yəqin, siz bu «xəbəri» dünən eşitmisiniz.", "D": "«Uşaq» şirniyyatı gizlicə yedi.", "E": "Ehtimal ki, «qonaqlar» axşama kimi gələcəklər."}'::jsonb, 'B', NULL, '«Mahnı» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6206, 80, 'g10-aze-member-q3-06', 3, 6, 'hard', 'single', '«Uşaq vazanı bilərəkdən sındırmamışdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Uşaq — xəbər; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — mübtəda", "B": "Uşaq — mübtəda; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər", "C": "Uşaq — zərflik; vazanı — vasitəsiz tamamlıq; bilərəkdən — mübtəda; sındırmamışdı — xəbər", "D": "Uşaq — mübtəda; vazanı — zərflik; bilərəkdən — vasitəsiz tamamlıq; sındırmamışdı — xəbər", "E": "Uşaq — vasitəsiz tamamlıq; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Uşaq — mübtəda; vazanı — vasitəsiz tamamlıq; bilərəkdən — zərflik; sındırmamışdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6207, 80, 'g10-aze-member-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə təyin yiyəlik halında olan isimlə ifadə olunub, zərflik yoxdur və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Tortun dörddə birini qonaqlara verdik.", "B": "Əlbəttə, biz sizə inanırıq.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Yarışa on səkkiz komanda qatıldı.", "E": "Ay qızım, bu sözləri kimdən eşitdin?"}'::jsonb, 'A', NULL, '«Tortun dörddə birini qonaqlara verdik.»: təyin — Tortun; vasitəsiz tamamlıq — dörddə birini; vasitəli tamamlıq — qonaqlara; xəbər — verdik.');
INSERT INTO public.questions VALUES (6208, 80, 'g10-aze-member-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, zərflik var və təyin yoxdur?', NULL, NULL, '{"A": "Hansı şəhərdə doğulmusan?", "B": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "C": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "D": "Oxumaq insanı zənginləşdirir.", "E": "Biz çayın sahili ilə xeyli getdik."}'::jsonb, 'B', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.»: zərflik — Qatar stansiyaya çatan kimi; mübtəda — sərnişinlər; zərflik — vaqonlardan; xəbər — düşdülər.');
INSERT INTO public.questions VALUES (6209, 80, 'g10-aze-member-q3-09', 3, 9, 'hard', 'single', '«Kitabxanadan götürdüyüm kitabları vaxtında qaytardım.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Kitabxanadan götürdüyüm — təyin; kitabları — xəbər; vaxtında — zərflik; qaytardım — vasitəsiz tamamlıq", "B": "Kitabxanadan götürdüyüm — təyin; kitabları — vasitəsiz tamamlıq; vaxtında — zərflik; qaytardım — xəbər", "C": "Kitabxanadan götürdüyüm — təyin; kitabları — vasitəli tamamlıq; vaxtında — zərflik; qaytardım — xəbər", "D": "Kitabxanadan götürdüyüm — təyin; kitabları — vasitəsiz tamamlıq; vaxtında — xəbər; qaytardım — zərflik", "E": "Kitabxanadan götürdüyüm — təyin; kitabları — mübtəda; vaxtında — zərflik; qaytardım — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Kitabxanadan götürdüyüm — təyin; kitabları — vasitəsiz tamamlıq; vaxtında — zərflik; qaytardım — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6210, 80, 'g10-aze-member-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir və feillə ifadə olunub?', NULL, NULL, '{"A": "Of, bu çanta «ağırdır»!", "B": "Bu, lap yeni «maşındır».", "C": "Təəssüf ki, «mən» toya getmədim.", "D": "Atam mənim üçün velosiped «aldı».", "E": "Danışmaq «asandır»."}'::jsonb, 'D', NULL, '«aldı» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6211, 80, 'g10-aze-member-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Bəs sən «hara» gedirsən?", "B": "Bu, lap «yeni» maşındır.", "C": "«Dostcasına» gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Ay qızım, «bu» sözləri kimdən eşitdin?", "E": "«Biz» iki-üç saat gözlədik."}'::jsonb, 'D', NULL, '«bu» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6212, 80, 'g10-aze-member-q3-12', 3, 12, 'hard', 'single', '«Yazılmış məktubu poçta apardım.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Yazılmış — təyin; məktubu — zərflik; poçta — vasitəsiz tamamlıq; apardım — xəbər", "B": "Yazılmış — təyin; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — xəbər", "C": "Yazılmış — xəbər; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — təyin", "D": "Yazılmış — zərflik; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — xəbər", "E": "Yazılmış — təyin; məktubu — mübtəda; poçta — zərflik; apardım — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Yazılmış — təyin; məktubu — vasitəsiz tamamlıq; poçta — zərflik; apardım — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6213, 80, 'g10-aze-member-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə təyin əvəzliklə ifadə olunub, zərflik yoxdur və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Bir sözlə, hamı məmnun qaldı.", "B": "Of, bu çanta ağırdır!", "C": "Əhsən! Bu rəsmi kim çəkib?", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'C', NULL, '«Əhsən! Bu rəsmi kim çəkib?»: təyin — Bu; vasitəsiz tamamlıq — rəsmi; mübtəda — kim; xəbər — çəkib.');
INSERT INTO public.questions VALUES (6214, 80, 'g10-aze-member-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Yarışa «on səkkiz» komanda qatıldı.", "B": "«Hansı» şəhərdə doğulmusan?", "C": "«Biz» stansiyada qatarı xeyli gözlədik.", "D": "Məhz bu kənddə «böyük» şair doğulub.", "E": "Bacım «məndən» kitab istədi."}'::jsonb, 'B', NULL, '«Hansı» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6215, 80, 'g10-aze-member-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə mübtəda əvəzliklə ifadə olunub, vasitəli tamamlıq var və vasitəli tamamlıq əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Atam mənim üçün velosiped aldı.", "B": "Ay qızım, bu sözləri kimdən eşitdin?", "C": "Əlbəttə, biz sizə inanırıq.", "D": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "E": "Bacım məndən kitab istədi."}'::jsonb, 'C', NULL, '«Əlbəttə, biz sizə inanırıq.»: mübtəda — biz; vasitəli tamamlıq — sizə; xəbər — inanırıq.');
INSERT INTO public.questions VALUES (6216, 80, 'g10-aze-member-q3-16', 3, 16, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Dostcasına gülümsəyən — təyin; satıcı — təyin; bizə — vasitəli tamamlıq; təzə — mübtəda; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər", "B": "Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — xəbər; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — vasitəli tamamlıq", "C": "Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəli tamamlıq; uzatdı — xəbər", "D": "Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəsiz tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər", "E": "Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6217, 80, 'g10-aze-member-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir və sayla ifadə olunub?', NULL, NULL, '{"A": "Ən «çətin» sualları hətta kiçik qardaşım tapdı.", "B": "Axı biz «bu» yolu tanımırıq.", "C": "«Üç-dörd» günə qədər işimizi bitirəcəyik.", "D": "«Hansı» şəhərdə doğulmusan?", "E": "Dostcasına «gülümsəyən» satıcı bizə təzə meyvə uzatdı."}'::jsonb, 'C', NULL, '«Üç-dörd» — təyin, say. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6218, 80, 'g10-aze-member-q3-18', 3, 18, 'hard', 'single', '«Biz iki-üç saat gözlədik.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Biz — mübtəda; iki-üç — təyin; saat — təyin; gözlədik — xəbər", "B": "Biz — zərflik; iki-üç — təyin; saat — mübtəda; gözlədik — xəbər", "C": "Biz — mübtəda; iki-üç — təyin; saat — zərflik; gözlədik — xəbər", "D": "Biz — mübtəda; iki-üç — təyin; saat — zərflik; gözlədik — təyin", "E": "Biz — mübtəda; iki-üç — mübtəda; saat — zərflik; gözlədik — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Biz — mübtəda; iki-üç — təyin; saat — zərflik; gözlədik — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6219, 80, 'g10-aze-member-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəsiz tamamlıq var və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "B": "Mən üzməyi yayda öyrəndim.", "C": "Bəs sən hara gedirsən?", "D": "Hansı şəhərdə doğulmusan?", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'B', NULL, '«Mən üzməyi yayda öyrəndim.»: mübtəda — Mən; vasitəsiz tamamlıq — üzməyi; zərflik — yayda; xəbər — öyrəndim.');
INSERT INTO public.questions VALUES (6220, 80, 'g10-aze-member-q3-20', 3, 20, 'medium', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "C": "Qardaşım məktubu qələm ilə yazdı.", "D": "Anam ilə atam toya getdilər.", "E": "Uşaq vazanı bilərəkdən sındırmamışdı."}'::jsonb, 'C', NULL, '«Qardaşım məktubu qələm ilə yazdı.»: mübtəda — Qardaşım; vasitəsiz tamamlıq — məktubu; vasitəli tamamlıq — qələm ilə; xəbər — yazdı.');
INSERT INTO public.questions VALUES (6221, 80, 'g10-aze-member-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə vasitəli tamamlıq əvəzliklə ifadə olunub, zərflik yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Sən ya rəsm, ya da musiqi seç.", "B": "Ay qızım, bu sözləri kimdən eşitdin?", "C": "Bu məktubu özüm yazacağam.", "D": "Axı biz bu yolu tanımırıq.", "E": "Həm riyaziyyatı, həm də fizikanı sevirəm."}'::jsonb, 'B', NULL, '«Ay qızım, bu sözləri kimdən eşitdin?»: təyin — bu; vasitəsiz tamamlıq — sözləri; vasitəli tamamlıq — kimdən; xəbər — eşitdin.');
INSERT INTO public.questions VALUES (6222, 80, 'g10-aze-member-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir və feili bağlama ilə ifadə olunub?', NULL, NULL, '{"A": "Anam ilə atam «toya» getdilər.", "B": "O, ikinci «dəfə» bu şəhərə gəlir.", "C": "Yəqin, siz bu xəbəri «dünən» eşitmisiniz.", "D": "Ucadan gülən uşaqlar müəllimi «görüb» susdular.", "E": "Qatar stansiyaya çatan kimi sərnişinlər «vaqonlardan» düşdülər."}'::jsonb, 'D', NULL, '«görüb» — zərflik, feili bağlama. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6223, 80, 'g10-aze-member-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir və sifətlə ifadə olunub?', NULL, NULL, '{"A": "Of, «bu» çanta ağırdır!", "B": "Əhsən! «Bu» rəsmi kim çəkib?", "C": "Qoy hamı «bu» həqiqəti bilsin.", "D": "Məhz bu kənddə «böyük» şair doğulub.", "E": "«Yazılmış» məktubu poçta apardım."}'::jsonb, 'D', NULL, '«böyük» — təyin, sifət. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6224, 80, 'g10-aze-member-q3-24', 3, 24, 'medium', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Ucadan gülən uşaqlar müəllimi görüb susdular.", "B": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "C": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "D": "Sərnişinlər avtobusa dalbadal mindilər.", "E": "Qoy hamı bu həqiqəti bilsin."}'::jsonb, 'E', NULL, '«Qoy hamı bu həqiqəti bilsin.»: mübtəda — hamı; təyin — bu; vasitəsiz tamamlıq — həqiqəti; xəbər — bilsin.');
INSERT INTO public.questions VALUES (6225, 80, 'g10-aze-member-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, təyin yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Atam mənim üçün velosiped aldı.", "B": "Mahnı oxuya-oxuya işləyirdi.", "C": "Anam ilə atam toya getdilər.", "D": "Yağışa görə oyun dayandırıldı.", "E": "Tortun dörddə birini qonaqlara verdik."}'::jsonb, 'A', NULL, '«Atam mənim üçün velosiped aldı.»: mübtəda — Atam; vasitəli tamamlıq — mənim üçün; vasitəsiz tamamlıq — velosiped; xəbər — aldı.');
INSERT INTO public.questions VALUES (6226, 80, 'g10-aze-member-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir və əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "«Biz» stansiyada qatarı xeyli gözlədik.", "B": "Ucadan gülən uşaqlar müəllimi «görüb» susdular.", "C": "Bəs sən «hara» gedirsən?", "D": "Məhz bu «kənddə» böyük şair doğulub.", "E": "Biz stansiyada qatarı «xeyli» gözlədik."}'::jsonb, 'C', NULL, '«hara» — zərflik, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (6227, 80, 'g10-aze-member-q3-27', 3, 27, 'hard', 'single', '«Tortun dörddə birini qonaqlara verdik.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəsiz tamamlıq; verdik — xəbər", "B": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — zərflik; verdik — xəbər", "C": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər", "D": "Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — mübtəda", "E": "Tortun — mübtəda; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Tortun — təyin; dörddə birini — vasitəsiz tamamlıq; qonaqlara — vasitəli tamamlıq; verdik — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6228, 80, 'g10-aze-member-q3-28', 3, 28, 'hard', 'single', '«Ehtimal ki, qonaqlar axşama kimi gələcəklər.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "qonaqlar — vasitəsiz tamamlıq; axşama kimi — zərflik; gələcəklər — xəbər", "B": "qonaqlar — mübtəda; axşama kimi — zərflik; gələcəklər — xəbər", "C": "qonaqlar — zərflik; axşama kimi — mübtəda; gələcəklər — xəbər", "D": "qonaqlar — təyin; axşama kimi — zərflik; gələcəklər — xəbər", "E": "qonaqlar — xəbər; axşama kimi — zərflik; gələcəklər — mübtəda"}'::jsonb, 'B', NULL, 'Düzgün: qonaqlar — mübtəda; axşama kimi — zərflik; gələcəklər — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6229, 80, 'g10-aze-member-q3-29', 3, 29, 'hard', 'single', '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Qatar stansiyaya çatan kimi — zərflik; sərnişinlər — vasitəsiz tamamlıq; vaqonlardan — zərflik; düşdülər — xəbər", "B": "Qatar stansiyaya çatan kimi — mübtəda; sərnişinlər — zərflik; vaqonlardan — zərflik; düşdülər — xəbər", "C": "Qatar stansiyaya çatan kimi — zərflik; sərnişinlər — mübtəda; vaqonlardan — zərflik; düşdülər — xəbər", "D": "Qatar stansiyaya çatan kimi — zərflik; sərnişinlər — mübtəda; vaqonlardan — zərflik; düşdülər — mübtəda", "E": "Qatar stansiyaya çatan kimi — təyin; sərnişinlər — mübtəda; vaqonlardan — zərflik; düşdülər — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Qatar stansiyaya çatan kimi — zərflik; sərnişinlər — mübtəda; vaqonlardan — zərflik; düşdülər — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6230, 80, 'g10-aze-member-q3-30', 3, 30, 'hard', 'single', '«Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Dostcasına gülümsəyən — zərflik; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər", "B": "Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — xəbər; meyvə — vasitəsiz tamamlıq; uzatdı — təyin", "C": "Dostcasına gülümsəyən — təyin; satıcı — təyin; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər", "D": "Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər", "E": "Dostcasına gülümsəyən — təyin; satıcı — vasitəli tamamlıq; bizə — mübtəda; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Dostcasına gülümsəyən — təyin; satıcı — mübtəda; bizə — vasitəli tamamlıq; təzə — təyin; meyvə — vasitəsiz tamamlıq; uzatdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (6231, 81, 'g10-aze-complex-q1-01', 1, 1, 'hard', 'single', '«Kim ki vətənini sevir, o, onu qorumağa hazırdır.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6232, 81, 'g10-aze-complex-q1-02', 1, 2, 'hard', 'single', 'Hansı variantda budaq cümlə xəbər budaq cümləsidir, cümlə tabeli mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Hara getsən, orada dost tapacaqsan.", "B": "Arzum odur ki, universitetə qəbul olum.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "E": "Tez yola düşdük ki, qatara çataq."}'::jsonb, 'B', NULL, '«Arzum odur ki, universitetə qəbul olum.» — tabeli mürəkkəb cümlədir: budaq cümlə — xəbər, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6233, 81, 'g10-aze-complex-q1-03', 1, 3, 'hard', 'single', '«Hava yaxşı olsa, ekskursiyaya gedəcəyik.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6234, 81, 'g10-aze-complex-q1-04', 1, 4, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Nə o gəldi, nə də mən getdim.", "B": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "C": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "D": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "E": "Şagirdlər həm oxuyur, həm də işləyirlər."}'::jsonb, 'E', NULL, '«Şagirdlər həm oxuyur, həm də işləyirlər.» — sadə cümlədir (həmcins xəbərlər).');
INSERT INTO public.questions VALUES (6235, 81, 'g10-aze-complex-q1-05', 1, 5, 'hard', 'single', '«Tez yola düşdük ki, qatara çataq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6236, 81, 'g10-aze-complex-q1-06', 1, 6, 'medium', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "B": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "E": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz."}'::jsonb, 'A', NULL, '«Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6237, 81, 'g10-aze-complex-q1-07', 1, 7, 'hard', 'single', '«Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent.');
INSERT INTO public.questions VALUES (6238, 81, 'g10-aze-complex-q1-08', 1, 8, 'hard', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir, cümlə tabeli mürəkkəbdir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "B": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "C": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "D": "Hara getsən, orada dost tapacaqsan.", "E": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan."}'::jsonb, 'C', NULL, '«Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6239, 81, 'g10-aze-complex-q1-09', 1, 9, 'hard', 'single', '«Ona görə gecikdim ki, yolda tıxac var idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6240, 81, 'g10-aze-complex-q1-10', 1, 10, 'medium', 'single', 'Hansı variantda budaq cümlə tamamlıq budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "B": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "C": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "D": "Ona görə gecikdim ki, yolda tıxac var idi.", "E": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü."}'::jsonb, 'C', NULL, '«Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6241, 81, 'g10-aze-complex-q1-11', 1, 11, 'hard', 'single', '«Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6242, 81, 'g10-aze-complex-q1-12', 1, 12, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Tez yola düşdük ki, qatara çataq.", "B": "Hara getsən, orada dost tapacaqsan.", "C": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "D": "Şagirdlər həm oxuyur, həm də işləyirlər.", "E": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi."}'::jsonb, 'D', NULL, '«Şagirdlər həm oxuyur, həm də işləyirlər.» — sadə cümlədir (həmcins xəbərlər).');
INSERT INTO public.questions VALUES (6243, 81, 'g10-aze-complex-q1-13', 1, 13, 'hard', 'single', '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6244, 81, 'g10-aze-complex-q1-14', 1, 14, 'hard', 'single', '«İstəyirəm ki, hamı xoşbəxt olsun.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6245, 81, 'g10-aze-complex-q1-15', 1, 15, 'hard', 'single', '«Hava yaxşı olsa, ekskursiyaya gedəcəyik.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6246, 81, 'g10-aze-complex-q1-16', 1, 16, 'hard', 'single', '«Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6247, 81, 'g10-aze-complex-q1-17', 1, 17, 'medium', 'single', 'Hansı variantda budaq cümlə səbəb budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "B": "Tez yola düşdük ki, qatara çataq.", "C": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "D": "Hara getsən, orada dost tapacaqsan.", "E": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik."}'::jsonb, 'C', NULL, '«Uşaq ağlayırdı, çünki oyuncağı sınmışdı.» — tabeli mürəkkəb cümlədir: budaq cümlə — səbəb, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6248, 81, 'g10-aze-complex-q1-18', 1, 18, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Tez yola düşdük ki, qatara çataq.", "B": "Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.", "C": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "D": "Nə o gəldi, nə də mən getdim.", "E": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan."}'::jsonb, 'B', NULL, '«Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.» — sadə cümlədir (həmcins mübtədalar).');
INSERT INTO public.questions VALUES (6249, 81, 'g10-aze-complex-q1-19', 1, 19, 'hard', 'single', '«Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "sadə cümlə", "D": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (6250, 81, 'g10-aze-complex-q1-20', 1, 20, 'hard', 'single', '«Əgər sən gəlməsən, mən də getməyəcəyəm.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6251, 81, 'g10-aze-complex-q1-21', 1, 21, 'hard', 'single', '«Ona görə gecikdim ki, yolda tıxac var idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6252, 81, 'g10-aze-complex-q1-22', 1, 22, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "B": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "C": "Qonaqlar gəldi və süfrə açıldı.", "D": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "E": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı."}'::jsonb, 'A', NULL, '«Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6253, 81, 'g10-aze-complex-q1-23', 1, 23, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə tabesiz mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "B": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "C": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan."}'::jsonb, 'A', NULL, '«Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (6254, 81, 'g10-aze-complex-q1-24', 1, 24, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir, budaq cümlə baş cümlədən əvvəl gəlir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "B": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "E": "Əgər sən gəlməsən, mən də getməyəcəyəm."}'::jsonb, 'A', NULL, '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6255, 81, 'g10-aze-complex-q1-25', 1, 25, 'medium', 'single', 'Hansı variantda budaq cümlə «çünki» bağlayıcısı ilə bağlanıb və budaq cümlə səbəb budaq cümləsidir?', NULL, NULL, '{"A": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "B": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "C": "Ona görə gecikdim ki, yolda tıxac var idi.", "D": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "E": "Tez yola düşdük ki, qatara çataq."}'::jsonb, 'B', NULL, '«Uşaq ağlayırdı, çünki oyuncağı sınmışdı.» — tabeli mürəkkəb cümlədir: budaq cümlə — səbəb, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6256, 81, 'g10-aze-complex-q1-26', 1, 26, 'medium', 'single', 'Hansı variantda budaq cümlə kəmiyyət budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "B": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "C": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "D": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "E": "İstəyirəm ki, hamı xoşbəxt olsun."}'::jsonb, 'C', NULL, '«Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.» — tabeli mürəkkəb cümlədir: budaq cümlə — kəmiyyət, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6257, 81, 'g10-aze-complex-q1-27', 1, 27, 'hard', 'single', '«Hara getsən, orada dost tapacaqsan.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6258, 81, 'g10-aze-complex-q1-28', 1, 28, 'medium', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə 3 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "B": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "C": "Nə o gəldi, nə də mən getdim.", "D": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "E": "Qonaqlar gəldi və süfrə açıldı."}'::jsonb, 'A', NULL, '«Səhər oldu, amma günəş görünmədi, göy buludlu idi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 3 komponent).');
INSERT INTO public.questions VALUES (6259, 81, 'g10-aze-complex-q1-29', 1, 29, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, budaq cümlə xəbər budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "B": "Arzum odur ki, universitetə qəbul olum.", "C": "Tez yola düşdük ki, qatara çataq.", "D": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "E": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir."}'::jsonb, 'B', NULL, '«Arzum odur ki, universitetə qəbul olum.» — tabeli mürəkkəb cümlədir: budaq cümlə — xəbər, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6260, 81, 'g10-aze-complex-q1-30', 1, 30, 'hard', 'single', '«Hava yaxşı olsa, ekskursiyaya gedəcəyik.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6261, 81, 'g10-aze-complex-q2-01', 2, 1, 'hard', 'single', '«Kim ki vətənini sevir, o, onu qorumağa hazırdır.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6262, 81, 'g10-aze-complex-q2-02', 2, 2, 'hard', 'single', '«Hara getsən, orada dost tapacaqsan.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6263, 81, 'g10-aze-complex-q2-03', 2, 3, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, budaq cümlə tamamlıq budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "İstəyirəm ki, hamı xoşbəxt olsun.", "B": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "C": "Arzum odur ki, universitetə qəbul olum.", "D": "Ona görə gecikdim ki, yolda tıxac var idi.", "E": "Tez yola düşdük ki, qatara çataq."}'::jsonb, 'A', NULL, '«İstəyirəm ki, hamı xoşbəxt olsun.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6264, 81, 'g10-aze-complex-q2-04', 2, 4, 'hard', 'single', '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6265, 81, 'g10-aze-complex-q2-05', 2, 5, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "B": "İstəyirəm ki, hamı xoşbəxt olsun.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "E": "Dağa qalxdıqca hava soyuyurdu."}'::jsonb, 'E', NULL, '«Dağa qalxdıqca hava soyuyurdu.» — sadə cümlədir (feili bağlama).');
INSERT INTO public.questions VALUES (6266, 81, 'g10-aze-complex-q2-06', 2, 6, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "B": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "C": "Nə o gəldi, nə də mən getdim.", "D": "Hara getsən, orada dost tapacaqsan.", "E": "Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım."}'::jsonb, 'E', NULL, '«Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım.» — sadə cümlədir (feili bağlama tərkibi).');
INSERT INTO public.questions VALUES (6267, 81, 'g10-aze-complex-q2-07', 2, 7, 'medium', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "İstəyirəm ki, hamı xoşbəxt olsun.", "B": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "C": "Nə o gəldi, nə də mən getdim.", "D": "Ona görə gecikdim ki, yolda tıxac var idi.", "E": "Hara getsən, orada dost tapacaqsan."}'::jsonb, 'C', NULL, '«Nə o gəldi, nə də mən getdim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (6268, 81, 'g10-aze-complex-q2-08', 2, 8, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "B": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "C": "Dağa qalxdıqca hava soyuyurdu.", "D": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "E": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı."}'::jsonb, 'C', NULL, '«Dağa qalxdıqca hava soyuyurdu.» — sadə cümlədir (feili bağlama).');
INSERT INTO public.questions VALUES (6269, 81, 'g10-aze-complex-q2-09', 2, 9, 'hard', 'single', 'Hansı variantda budaq cümlə kəmiyyət budaq cümləsidir, cümlə tabeli mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "B": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "İstəyirəm ki, hamı xoşbəxt olsun.", "E": "Hava yaxşı olsa, ekskursiyaya gedəcəyik."}'::jsonb, 'B', NULL, '«Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.» — tabeli mürəkkəb cümlədir: budaq cümlə — kəmiyyət, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6270, 81, 'g10-aze-complex-q2-10', 2, 10, 'medium', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Nə o gəldi, nə də mən getdim.", "B": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "C": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "D": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "E": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü."}'::jsonb, 'A', NULL, '«Nə o gəldi, nə də mən getdim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (6271, 81, 'g10-aze-complex-q2-11', 2, 11, 'hard', 'single', '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6272, 81, 'g10-aze-complex-q2-12', 2, 12, 'medium', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Arzum odur ki, universitetə qəbul olum.", "B": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "E": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik."}'::jsonb, 'A', NULL, '«Arzum odur ki, universitetə qəbul olum.» — tabeli mürəkkəb cümlədir: budaq cümlə — xəbər, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6273, 81, 'g10-aze-complex-q2-13', 2, 13, 'hard', 'single', '«Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6274, 81, 'g10-aze-complex-q2-14', 2, 14, 'medium', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "B": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "C": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "D": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "E": "Arzum odur ki, universitetə qəbul olum."}'::jsonb, 'D', NULL, '«Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6275, 81, 'g10-aze-complex-q2-15', 2, 15, 'hard', 'single', '«Qonaqlar gəldi və süfrə açıldı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (6276, 81, 'g10-aze-complex-q2-16', 2, 16, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə tabesiz mürəkkəbdir və cümlə 3 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "B": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "C": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "D": "Nə o gəldi, nə də mən getdim.", "E": "Qonaqlar gəldi və süfrə açıldı."}'::jsonb, 'A', NULL, '«Səhər oldu, amma günəş görünmədi, göy buludlu idi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 3 komponent).');
INSERT INTO public.questions VALUES (6277, 81, 'g10-aze-complex-q2-17', 2, 17, 'hard', 'single', '«Əgər sən gəlməsən, mən də getməyəcəyəm.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6278, 81, 'g10-aze-complex-q2-18', 2, 18, 'hard', 'single', '«Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "sadə cümlə", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (6279, 81, 'g10-aze-complex-q2-19', 2, 19, 'medium', 'single', 'Hansı variantda budaq cümlə xəbər budaq cümləsidir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "B": "İstəyirəm ki, hamı xoşbəxt olsun.", "C": "Arzum odur ki, universitetə qəbul olum.", "D": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "E": "Ona görə gecikdim ki, yolda tıxac var idi."}'::jsonb, 'C', NULL, '«Arzum odur ki, universitetə qəbul olum.» — tabeli mürəkkəb cümlədir: budaq cümlə — xəbər, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6280, 81, 'g10-aze-complex-q2-20', 2, 20, 'hard', 'single', 'Hansı variantda budaq cümlə bağlayıcısız, xəbərin şəkilçisi vasitəsilə bağlanıb, budaq cümlə şərt budaq cümləsidir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "B": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "C": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "D": "Hara getsən, orada dost tapacaqsan.", "E": "Əgər sən gəlməsən, mən də getməyəcəyəm."}'::jsonb, 'A', NULL, '«Hava yaxşı olsa, ekskursiyaya gedəcəyik.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6281, 81, 'g10-aze-complex-q2-21', 2, 21, 'hard', 'single', '«Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6282, 81, 'g10-aze-complex-q2-22', 2, 22, 'hard', 'single', '«Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6283, 81, 'g10-aze-complex-q2-23', 2, 23, 'hard', 'single', '«Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6284, 81, 'g10-aze-complex-q2-24', 2, 24, 'hard', 'single', '«Arzum odur ki, universitetə qəbul olum.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6285, 81, 'g10-aze-complex-q2-25', 2, 25, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 2 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Tez yola düşdük ki, qatara çataq.", "B": "Nə o gəldi, nə də mən getdim.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "E": "Hara getsən, orada dost tapacaqsan."}'::jsonb, 'B', NULL, '«Nə o gəldi, nə də mən getdim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (6286, 81, 'g10-aze-complex-q2-26', 2, 26, 'hard', 'single', '«Arzum odur ki, universitetə qəbul olum.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6287, 81, 'g10-aze-complex-q2-27', 2, 27, 'medium', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "B": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "C": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "D": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "E": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz."}'::jsonb, 'E', NULL, '«Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6288, 81, 'g10-aze-complex-q2-28', 2, 28, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "B": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "C": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "D": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "E": "Dağa qalxdıqca hava soyuyurdu."}'::jsonb, 'E', NULL, '«Dağa qalxdıqca hava soyuyurdu.» — sadə cümlədir (feili bağlama).');
INSERT INTO public.questions VALUES (6289, 81, 'g10-aze-complex-q2-29', 2, 29, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 2 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "B": "Nə o gəldi, nə də mən getdim.", "C": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "D": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "E": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi."}'::jsonb, 'B', NULL, '«Nə o gəldi, nə də mən getdim.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (6290, 81, 'g10-aze-complex-q2-30', 2, 30, 'hard', 'single', '«Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6291, 81, 'g10-aze-complex-q3-01', 3, 1, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib, cümlə 3 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Nə o gəldi, nə də mən getdim.", "B": "Qonaqlar gəldi və süfrə açıldı.", "C": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "D": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "E": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi."}'::jsonb, 'E', NULL, '«Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 3 komponent).');
INSERT INTO public.questions VALUES (6292, 81, 'g10-aze-complex-q3-02', 3, 2, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə tabeli mürəkkəbdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "B": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "C": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "D": "Tez yola düşdük ki, qatara çataq.", "E": "Hava yaxşı olsa, ekskursiyaya gedəcəyik."}'::jsonb, 'D', NULL, '«Tez yola düşdük ki, qatara çataq.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6293, 81, 'g10-aze-complex-q3-03', 3, 3, 'hard', 'single', 'Hansı variantda budaq cümlə kəmiyyət budaq cümləsidir, cümlə tabeli mürəkkəbdir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "B": "Hara getsən, orada dost tapacaqsan.", "C": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "D": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "E": "Əgər sən gəlməsən, mən də getməyəcəyəm."}'::jsonb, 'D', NULL, '«Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.» — tabeli mürəkkəb cümlədir: budaq cümlə — kəmiyyət, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6294, 81, 'g10-aze-complex-q3-04', 3, 4, 'hard', 'single', '«Ona görə gecikdim ki, yolda tıxac var idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6295, 81, 'g10-aze-complex-q3-05', 3, 5, 'hard', 'single', '«Əgər sən gəlməsən, mən də getməyəcəyəm.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6296, 81, 'g10-aze-complex-q3-06', 3, 6, 'hard', 'single', 'Hansı variantda budaq cümlə məqsəd budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "B": "Tez yola düşdük ki, qatara çataq.", "C": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Arzum odur ki, universitetə qəbul olum."}'::jsonb, 'B', NULL, '«Tez yola düşdük ki, qatara çataq.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6297, 81, 'g10-aze-complex-q3-07', 3, 7, 'medium', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "B": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "C": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "D": "İstəyirəm ki, hamı xoşbəxt olsun.", "E": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı."}'::jsonb, 'D', NULL, '«İstəyirəm ki, hamı xoşbəxt olsun.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6298, 81, 'g10-aze-complex-q3-08', 3, 8, 'hard', 'single', '«Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6299, 81, 'g10-aze-complex-q3-09', 3, 9, 'hard', 'single', '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6300, 81, 'g10-aze-complex-q3-10', 3, 10, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "B": "Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.", "C": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "D": "Tez yola düşdük ki, qatara çataq.", "E": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı."}'::jsonb, 'B', NULL, '«Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.» — sadə cümlədir (həmcins mübtədalar).');
INSERT INTO public.questions VALUES (6301, 81, 'g10-aze-complex-q3-11', 3, 11, 'medium', 'single', 'Hansı variantda budaq cümlə bağlayıcısız, xəbərin şəkilçisi vasitəsilə bağlanıb və budaq cümlə şərt budaq cümləsidir?', NULL, NULL, '{"A": "Qonaqlar gəldi və süfrə açıldı.", "B": "Ona görə gecikdim ki, yolda tıxac var idi.", "C": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "D": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "E": "Dağa qalxdıqca hava soyuyurdu."}'::jsonb, 'C', NULL, '«Hava yaxşı olsa, ekskursiyaya gedəcəyik.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6302, 81, 'g10-aze-complex-q3-12', 3, 12, 'hard', 'single', '«Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6303, 81, 'g10-aze-complex-q3-13', 3, 13, 'hard', 'single', '«Tez yola düşdük ki, qatara çataq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6304, 81, 'g10-aze-complex-q3-14', 3, 14, 'hard', 'single', '«Uşaq ağlayırdı, çünki oyuncağı sınmışdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6305, 81, 'g10-aze-complex-q3-15', 3, 15, 'hard', 'single', '«İstəyirəm ki, hamı xoşbəxt olsun.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6306, 81, 'g10-aze-complex-q3-16', 3, 16, 'medium', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "B": "Arzum odur ki, universitetə qəbul olum.", "C": "İstəyirəm ki, hamı xoşbəxt olsun.", "D": "Ona görə gecikdim ki, yolda tıxac var idi.", "E": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik."}'::jsonb, 'E', NULL, '«Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6307, 81, 'g10-aze-complex-q3-17', 3, 17, 'hard', 'single', '«Nə o gəldi, nə də mən getdim.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "sadə cümlə", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (6308, 81, 'g10-aze-complex-q3-18', 3, 18, 'hard', 'single', '«Əgər sən gəlməsən, mən də getməyəcəyəm.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6309, 81, 'g10-aze-complex-q3-19', 3, 19, 'hard', 'single', 'Hansı variantda budaq cümlə «əgər» bağlayıcısı ilə bağlanıb, budaq cümlə şərt budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "B": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "C": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "D": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "E": "Ona görə gecikdim ki, yolda tıxac var idi."}'::jsonb, 'B', NULL, '«Əgər sən gəlməsən, mən də getməyəcəyəm.» — tabeli mürəkkəb cümlədir: budaq cümlə — şərt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6310, 81, 'g10-aze-complex-q3-20', 3, 20, 'hard', 'single', 'Hansı variantda budaq cümlə kəmiyyət budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "B": "Ona görə gecikdim ki, yolda tıxac var idi.", "C": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan."}'::jsonb, 'E', NULL, '«Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.» — tabeli mürəkkəb cümlədir: budaq cümlə — kəmiyyət, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6311, 81, 'g10-aze-complex-q3-21', 3, 21, 'hard', 'single', '«Arzum odur ki, universitetə qəbul olum.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6312, 81, 'g10-aze-complex-q3-22', 3, 22, 'hard', 'single', '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6313, 81, 'g10-aze-complex-q3-23', 3, 23, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "B": "Qonaqlar gəldi və süfrə açıldı.", "C": "Arzum odur ki, universitetə qəbul olum.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım."}'::jsonb, 'E', NULL, '«Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım.» — sadə cümlədir (feili bağlama tərkibi).');
INSERT INTO public.questions VALUES (6314, 81, 'g10-aze-complex-q3-24', 3, 24, 'hard', 'single', '«İstəyirəm ki, hamı xoşbəxt olsun.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6315, 81, 'g10-aze-complex-q3-25', 3, 25, 'hard', 'single', '«Əgər sən gəlməsən, mən də getməyəcəyəm.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6316, 81, 'g10-aze-complex-q3-26', 3, 26, 'medium', 'single', 'Hansı variantda budaq cümlə tamamlıq budaq cümləsidir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "B": "Hara getsən, orada dost tapacaqsan.", "C": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan."}'::jsonb, 'A', NULL, '«Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (6317, 81, 'g10-aze-complex-q3-27', 3, 27, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.", "B": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "C": "Hara getsən, orada dost tapacaqsan.", "D": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "E": "Kim ki vətənini sevir, o, onu qorumağa hazırdır."}'::jsonb, 'A', NULL, '«Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.» — sadə cümlədir (həmcins mübtədalar).');
INSERT INTO public.questions VALUES (6318, 81, 'g10-aze-complex-q3-28', 3, 28, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir, cümlə tabeli mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "B": "Ona görə gecikdim ki, yolda tıxac var idi.", "C": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "D": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "E": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir."}'::jsonb, 'D', NULL, '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6319, 81, 'g10-aze-complex-q3-29', 3, 29, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir, cümlə tabeli mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "B": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "C": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar."}'::jsonb, 'E', NULL, '«Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (6320, 81, 'g10-aze-complex-q3-30', 3, 30, 'medium', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "B": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "C": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "D": "Dağa qalxdıqca hava soyuyurdu.", "E": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar."}'::jsonb, 'D', NULL, '«Dağa qalxdıqca hava soyuyurdu.» — sadə cümlədir (feili bağlama).');
INSERT INTO public.questions VALUES (6321, 82, 'g10-aze-punct-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Onu da bilirəm, ki siz bu işə çox əmək sərf etmisiniz.", "B": "Tez yola düşdük ki qatara çataq.", "C": "Sən nə qədər çalışsan bir o qədər uğur qazanarsan.", "D": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "E": "Kim ki vətənini sevir o onu qorumağa hazırdır."}'::jsonb, 'D', NULL, 'Düzgün: «Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6322, 82, 'g10-aze-punct-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim ki vətənini sevir, o onu qorumağa hazırdır.", "B": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "C": "Ona görə gecikdim ki yolda tıxac var idi.", "D": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "E": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir."}'::jsonb, 'D', NULL, 'Düzgün: «Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6323, 82, 'g10-aze-punct-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Ona görə gecikdim ki, yolda tıxac var idi.", "B": "Onu da bilirəm ki siz bu işə çox əmək sərf etmisiniz.", "C": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "D": "Müəllim soruşdu, ki tapşırığı kim yerinə yetirib.", "E": "İstəyirəm ki hamı xoşbəxt olsun."}'::jsonb, 'A', NULL, 'Düzgün: «Ona görə gecikdim ki, yolda tıxac var idi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6324, 82, 'g10-aze-punct-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq.", "C": "Ah, köhnə dostumu uzun, müddət görmədim!", "D": "Ehtimal ki qonaqlar axşama kimi gələcəklər.", "E": "Tez yola düşdük, ki qatara çataq."}'::jsonb, 'A', NULL, 'Düzgün: «Təəssüf ki, mən toya getmədim.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6325, 82, 'g10-aze-punct-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Hara getsən, orada dost tapacaqsan.", "B": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "C": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "D": "Müəllim soruşdu, ki tapşırığı kim yerinə yetirib.", "E": "Arzum odur, ki universitetə qəbul olum."}'::jsonb, 'C', NULL, 'Düzgün: «Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6326, 82, 'g10-aze-punct-q1-06', 1, 6, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "B": "Dərslərini oxumadan oynamağa getdi.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "E": "Nə vaxt ki qar yağdı uşaqlar həyətə çıxdılar."}'::jsonb, 'A', NULL, 'Düzgün: «Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6327, 82, 'g10-aze-punct-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Kim ki vətənini sevir o, onu qorumağa hazırdır.", "B": "Tez yola düşdük ki qatara çataq.", "C": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "D": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "E": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik."}'::jsonb, 'E', NULL, 'Düzgün: «Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6328, 82, 'g10-aze-punct-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hara getsən, orada dost tapacaqsan.", "B": "Onu da bilirəm ki siz bu işə çox əmək sərf etmisiniz.", "C": "İstəyirəm ki hamı xoşbəxt olsun.", "D": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "E": "Arzum odur ki, universitetə qəbul olum."}'::jsonb, 'E', NULL, 'Düzgün: «Arzum odur ki, universitetə qəbul olum.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6329, 82, 'g10-aze-punct-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ona görə gecikdim, ki yolda tıxac var idi.", "B": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "C": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "D": "Arzum odur ki universitetə qəbul olum.", "E": "Elə bir yer seçdik, ki oradan bütün şəhər görünürdü."}'::jsonb, 'B', NULL, 'Düzgün: «Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6330, 82, 'g10-aze-punct-q1-10', 1, 10, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Yazılmış məktubu poçta apardım.", "B": "Ya sabah, ya da birigün gələcəyəm.", "C": "Biz iki-üç saat gözlədik.", "D": "Onuncu sinfin şagirdləri teatra getdilər.", "E": "Atam mənim üçün velosiped aldı."}'::jsonb, 'B', NULL, 'Düzgün: «Ya sabah, ya da birigün gələcəyəm.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6331, 82, 'g10-aze-punct-q1-11', 1, 11, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Bu məktubu özüm yazacağam.", "C": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "D": "Təəssüf ki, mən toya getmədim.", "E": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar."}'::jsonb, 'D', NULL, 'Düzgün: «Təəssüf ki, mən toya getmədim.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6332, 82, 'g10-aze-punct-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və müraciət var?', NULL, NULL, '{"A": "Ay Leyla pəncərəni bağla!", "B": "Ay qızım bu sözləri kimdən eşitdin?", "C": "Vay, buzlu yolda maşın sürüşdü!", "D": "Ey gənclər Vətəni sevin!", "E": "Ay Leyla, pəncərəni bağla!"}'::jsonb, 'E', NULL, 'Düzgün: «Ay Leyla, pəncərəni bağla!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6333, 82, 'g10-aze-punct-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Sən nə qədər çalışsan bir o qədər uğur qazanarsan.", "B": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "C": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "D": "Hara getsən orada dost tapacaqsan.", "E": "Elə bir yer seçdik, ki oradan bütün şəhər görünürdü."}'::jsonb, 'C', NULL, 'Düzgün: «Uşaq ağlayırdı, çünki oyuncağı sınmışdı.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6334, 82, 'g10-aze-punct-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ah, köhnə dostumu uzun, müddət görmədim!", "B": "Ura bayram gəldi!", "C": "Əhsən! Bu rəsmi kim çəkib.", "D": "Ey gənclər Vətəni sevin!", "E": "Of, bu çanta ağırdır!"}'::jsonb, 'E', NULL, 'Düzgün: «Of, bu çanta ağırdır!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6335, 82, 'g10-aze-punct-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "B": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "C": "İstəyirəm ki hamı xoşbəxt olsun.", "D": "Elə bir yer seçdik ki oradan bütün şəhər görünürdü.", "E": "Arzum odur, ki universitetə qəbul olum."}'::jsonb, 'A', NULL, 'Düzgün: «Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6336, 82, 'g10-aze-punct-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ehtimal, ki qonaqlar axşama kimi gələcəklər.", "B": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq.", "C": "Yəqin siz bu xəbəri dünən eşitmisiniz.", "D": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "E": "Bir sözlə hamı məmnun qaldı."}'::jsonb, 'D', NULL, 'Düzgün: «Sözsüz, sizin əməyiniz qiymətləndiriləcək.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6337, 82, 'g10-aze-punct-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bağda alma, armud, və heyva yetişmişdi.", "B": "Həm riyaziyyatı həm də fizikanı sevirəm.", "C": "Anam, ilə atam toya getdilər.", "D": "Ya sabah ya da birigün gələcəyəm.", "E": "Sən ya rəsm, ya da musiqi seç."}'::jsonb, 'E', NULL, 'Düzgün: «Sən ya rəsm, ya da musiqi seç.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6338, 82, 'g10-aze-punct-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "B": "Ona görə gecikdim ki yolda tıxac var idi.", "C": "Onu da bilirəm ki siz bu işə çox əmək sərf etmisiniz.", "D": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir.", "E": "Baxmayaraq ki hava soyuq idi biz dənizə getdik."}'::jsonb, 'A', NULL, 'Düzgün: «Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6339, 82, 'g10-aze-punct-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Sən ya rəsm ya da musiqi seç.", "B": "Anam, ilə atam toya getdilər.", "C": "Həm oxuyur, həm də işləyir.", "D": "Həm riyaziyyatı həm də fizikanı sevirəm.", "E": "Bağda alma, armud, və heyva yetişmişdi."}'::jsonb, 'C', NULL, 'Düzgün: «Həm oxuyur, həm də işləyir.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6340, 82, 'g10-aze-punct-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "B": "İstəyirəm, ki hamı xoşbəxt olsun.", "C": "Tez yola düşdük ki qatara çataq.", "D": "Arzum odur ki universitetə qəbul olum.", "E": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü."}'::jsonb, 'E', NULL, 'Düzgün: «Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6341, 82, 'g10-aze-punct-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Müəllim soruşdu ki tapşırığı kim yerinə yetirib.", "B": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "C": "Ona görə gecikdim ki, yolda tıxac var idi.", "D": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir.", "E": "Onu da bilirəm ki siz bu işə çox əmək sərf etmisiniz."}'::jsonb, 'C', NULL, 'Düzgün: «Ona görə gecikdim ki, yolda tıxac var idi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6342, 82, 'g10-aze-punct-q1-22', 1, 22, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sadədir?', NULL, NULL, '{"A": "Bu məktubu özüm yazacağam.", "B": "Yağışa görə oyun dayandırıldı.", "C": "Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım.", "D": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "E": "Sən ya rəsm, ya da musiqi seç."}'::jsonb, 'C', NULL, 'Düzgün: «Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6343, 82, 'g10-aze-punct-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "B": "Ona görə gecikdim ki yolda tıxac var idi.", "C": "Hara getsən, orada dost tapacaqsan.", "D": "Onu da bilirəm, ki siz bu işə çox əmək sərf etmisiniz.", "E": "Uşaq ağlayırdı çünki, oyuncağı sınmışdı."}'::jsonb, 'C', NULL, 'Düzgün: «Hara getsən, orada dost tapacaqsan.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (6344, 82, 'g10-aze-punct-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Arzum odur, ki universitetə qəbul olum.", "B": "Ona görə gecikdim, ki yolda tıxac var idi.", "C": "Elə bir yer seçdik ki oradan bütün şəhər görünürdü.", "D": "Arzum odur ki, universitetə qəbul olum.", "E": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir."}'::jsonb, 'D', NULL, 'Düzgün: «Arzum odur ki, universitetə qəbul olum.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6345, 82, 'g10-aze-punct-q1-25', 1, 25, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Uşaq ağlayırdı çünki oyuncağı sınmışdı.", "B": "Yarışa on səkkiz komanda qatıldı.", "C": "Anam ilə atam toya getdilər.", "D": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "E": "Ona görə gecikdim ki, yolda tıxac var idi."}'::jsonb, 'E', NULL, 'Düzgün: «Ona görə gecikdim ki, yolda tıxac var idi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6346, 82, 'g10-aze-punct-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Yəqin siz bu xəbəri dünən eşitmisiniz.", "B": "Kitabı, oxuyub bitirəndən sonra onu kitabxanaya qaytardım.", "C": "Of bu çanta ağırdır!", "D": "Ehtimal, ki qonaqlar axşama kimi gələcəklər.", "E": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'E', NULL, 'Düzgün: «Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6347, 82, 'g10-aze-punct-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Əhsən! Bu rəsmi kim çəkib.", "B": "Vay, buzlu, yolda maşın sürüşdü!", "C": "Ey gənclər, Vətəni sevin!", "D": "Bacım, məndən kitab istədi.", "E": "Ay qızım bu sözləri kimdən eşitdin?"}'::jsonb, 'C', NULL, 'Düzgün: «Ey gənclər, Vətəni sevin!». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6348, 82, 'g10-aze-punct-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Of bu çanta ağırdır!", "B": "Ura, bayram gəldi!", "C": "Ey gənclər Vətəni sevin!", "D": "Ay qızım, bu sözləri kimdən eşitdin.", "E": "Ah, köhnə, dostumu uzun müddət görmədim!"}'::jsonb, 'B', NULL, 'Düzgün: «Ura, bayram gəldi!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6349, 82, 'g10-aze-punct-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Elə bir yer seçdik ki oradan bütün şəhər görünürdü.", "B": "Baxmayaraq ki, hava soyuq idi biz dənizə getdik.", "C": "Hara getsən, orada dost tapacaqsan.", "D": "Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.", "E": "Onu da bilirəm ki siz bu işə çox əmək sərf etmisiniz."}'::jsonb, 'D', NULL, 'Düzgün: «Nə vaxt ki qar yağdı, uşaqlar həyətə çıxdılar.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6350, 82, 'g10-aze-punct-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və cümlə sual cümləsidir?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin.", "B": "Vay, buzlu yolda maşın sürüşdü!", "C": "Əhsən! Bu rəsmi kim çəkib.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Of, bu çanta ağırdır!"}'::jsonb, 'D', NULL, 'Düzgün: «Əhsən! Bu rəsmi kim çəkib?». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6351, 82, 'g10-aze-punct-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ah, köhnə, dostumu uzun müddət görmədim!", "B": "Şagirdlər həm oxuyur, həm də işləyirlər.", "C": "Kim ki vətənini sevir o, onu qorumağa hazırdır.", "D": "Ona görə gecikdim ki yolda tıxac var idi.", "E": "Hansı şəhərdə doğulmusan."}'::jsonb, 'B', NULL, 'Düzgün: «Şagirdlər həm oxuyur, həm də işləyirlər.». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6352, 82, 'g10-aze-punct-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "B": "Ona görə gecikdim ki yolda tıxac var idi.", "C": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "D": "Baxmayaraq, ki hava soyuq idi, biz dənizə getdik.", "E": "Nə vaxt ki qar yağdı uşaqlar həyətə çıxdılar."}'::jsonb, 'A', NULL, 'Düzgün: «Əgər sən gəlməsən, mən də getməyəcəyəm.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6353, 82, 'g10-aze-punct-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hara getsən orada dost tapacaqsan.", "B": "Uşaq ağlayırdı çünki, oyuncağı sınmışdı.", "C": "Hamıya məlumdur ki Bakı Xəzərin sahilində yerləşir.", "D": "Baxmayaraq, ki hava soyuq idi, biz dənizə getdik.", "E": "Kim ki vətənini sevir, o, onu qorumağa hazırdır."}'::jsonb, 'E', NULL, 'Düzgün: «Kim ki vətənini sevir, o, onu qorumağa hazırdır.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; vergül «çünki»dən sonra qoyulub.');
INSERT INTO public.questions VALUES (6354, 82, 'g10-aze-punct-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ey gənclər Vətəni sevin!", "B": "Vay, buzlu, yolda maşın sürüşdü!", "C": "Əhsən! Bu rəsmi kim çəkib.", "D": "Ay qızım, bu sözləri kimdən eşitdin.", "E": "Ura, bayram gəldi!"}'::jsonb, 'E', NULL, 'Düzgün: «Ura, bayram gəldi!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6355, 82, 'g10-aze-punct-q2-05', 2, 5, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də mübtəda «o» və ya «bu» əvəzliyi ilə ifadə olunub?', NULL, NULL, '{"A": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "B": "Danışmaq asandır.", "C": "Xoşbəxtlikdən, yaralı quşu vaxtında həkimə çatdırdıq.", "D": "Yağışa görə oyun dayandırıldı.", "E": "Bu, lap yeni maşındır."}'::jsonb, 'E', NULL, 'Düzgün: «Bu, lap yeni maşındır.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6356, 82, 'g10-aze-punct-q2-06', 2, 6, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sual cümləsidir?', NULL, NULL, '{"A": "Anam, atam və bacım bayramı nənəmgildə qeyd etdilər.", "B": "Yalnız zəhmət insanı ucaldır.", "C": "Ay Leyla, pəncərəni bağla!", "D": "Uşaq şirniyyatı gizlicə yedi.", "E": "Əhsən! Bu rəsmi kim çəkib?"}'::jsonb, 'E', NULL, 'Düzgün: «Əhsən! Bu rəsmi kim çəkib?». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6357, 82, 'g10-aze-punct-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "İstəyirəm, ki hamı xoşbəxt olsun.", "B": "Elə bir yer seçdik, ki oradan bütün şəhər görünürdü.", "C": "Müəllim soruşdu ki tapşırığı kim yerinə yetirib.", "D": "Hamıya məlumdur ki Bakı Xəzərin sahilində yerləşir.", "E": "Arzum odur ki, universitetə qəbul olum."}'::jsonb, 'E', NULL, 'Düzgün: «Arzum odur ki, universitetə qəbul olum.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6358, 82, 'g10-aze-punct-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Həm riyaziyyatı həm də fizikanı sevirəm.", "B": "Bağda alma, armud, və heyva yetişmişdi.", "C": "Həm oxuyur həm də işləyir.", "D": "Sən ya rəsm, ya da musiqi seç.", "E": "Anam, ilə atam toya getdilər."}'::jsonb, 'D', NULL, 'Düzgün: «Sən ya rəsm, ya da musiqi seç.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6359, 82, 'g10-aze-punct-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Of bu çanta ağırdır!", "B": "Ay qızım, bu sözləri kimdən eşitdin.", "C": "Ah, köhnə dostumu uzun, müddət görmədim!", "D": "Ay Leyla pəncərəni bağla!", "E": "Ey gənclər, Vətəni sevin!"}'::jsonb, 'E', NULL, 'Düzgün: «Ey gənclər, Vətəni sevin!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6360, 82, 'g10-aze-punct-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "B": "Ehtimal, ki qonaqlar axşama kimi gələcəklər.", "C": "Yəqin siz bu xəbəri dünən eşitmisiniz.", "D": "Əlbəttə biz sizə inanırıq.", "E": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'A', NULL, 'Düzgün: «Sözsüz, sizin əməyiniz qiymətləndiriləcək.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6361, 82, 'g10-aze-punct-q2-11', 2, 11, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Biz sizdən sonra gəldik.", "B": "Səndən başqa hamı gəldi.", "C": "Mahnı oxuya-oxuya işləyirdi.", "D": "Məhz bu kənddə böyük şair doğulub.", "E": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi."}'::jsonb, 'E', NULL, 'Düzgün: «Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6362, 82, 'g10-aze-punct-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bu, lap yeni maşındır.", "B": "Təəssüf, ki mən toya getmədim.", "C": "Ura bayram gəldi!", "D": "Ah, köhnə, dostumu uzun müddət görmədim!", "E": "O ikinci dəfə bu şəhərə gəlir."}'::jsonb, 'A', NULL, 'Düzgün: «Bu, lap yeni maşındır.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6363, 82, 'g10-aze-punct-q2-13', 2, 13, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "B": "Tez yola düşdük, ki qatara çataq.", "C": "Şagirdlər həm oxuyur, həm də işləyirlər.", "D": "Baxmayaraq ki hava soyuq idi, biz dənizə getdik.", "E": "Tez yola düşdük ki qatara çataq."}'::jsonb, 'A', NULL, 'Düzgün: «Əgər sən gəlməsən, mən də getməyəcəyəm.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6364, 82, 'g10-aze-punct-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ay qızım, bu sözləri kimdən eşitdin.", "B": "Ay Leyla pəncərəni bağla!", "C": "Vay, buzlu, yolda maşın sürüşdü!", "D": "Ah, köhnə, dostumu uzun müddət görmədim!", "E": "Ey gənclər, Vətəni sevin!"}'::jsonb, 'E', NULL, 'Düzgün: «Ey gənclər, Vətəni sevin!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6365, 82, 'g10-aze-punct-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Həm oxuyur həm də işləyir.", "B": "Anam, ilə atam toya getdilər.", "C": "Bağda alma, armud, və heyva yetişmişdi.", "D": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir.", "E": "Sən ya rəsm, ya da musiqi seç."}'::jsonb, 'E', NULL, 'Düzgün: «Sən ya rəsm, ya da musiqi seç.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6366, 82, 'g10-aze-punct-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Hara getsən, orada dost tapacaqsan.", "B": "Müəllim soruşdu ki tapşırığı kim yerinə yetirib.", "C": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "D": "Baxmayaraq, ki hava soyuq idi, biz dənizə getdik.", "E": "Tez yola düşdük ki qatara çataq."}'::jsonb, 'C', NULL, 'Düzgün: «Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6367, 82, 'g10-aze-punct-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Vay, buzlu yolda maşın sürüşdü!", "B": "Əhsən! Bu rəsmi kim çəkib.", "C": "Ah, köhnə dostumu uzun, müddət görmədim!", "D": "Hava qaraldı ulduzlar göründü kənd sakitləşdi.", "E": "Ay qızım bu sözləri kimdən eşitdin?"}'::jsonb, 'A', NULL, 'Düzgün: «Vay, buzlu yolda maşın sürüşdü!». Digər cümlələrdə: iki vergül buraxılıb; sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6368, 82, 'g10-aze-punct-q2-18', 2, 18, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib?', NULL, NULL, '{"A": "Uşaq vazanı bilərəkdən sındırmamışdı.", "B": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı.", "C": "Ay Leyla, pəncərəni bağla!", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Əgər sən gəlməsən, mən də getməyəcəyəm."}'::jsonb, 'C', NULL, 'Düzgün: «Ay Leyla, pəncərəni bağla!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6369, 82, 'g10-aze-punct-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Elə bir yer seçdik ki oradan bütün şəhər görünürdü.", "B": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.", "C": "Kim ki vətənini sevir o, onu qorumağa hazırdır.", "D": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "E": "Hara getsən, orada dost tapacaqsan."}'::jsonb, 'D', NULL, 'Düzgün: «Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6370, 82, 'g10-aze-punct-q2-20', 2, 20, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Dərslərini oxumadan oynamağa getdi.", "B": "Qonaqlar gəldi və süfrə açıldı.", "C": "Ey gənclər, Vətəni sevin!", "D": "Təəssüf ki, mən toya getmədim.", "E": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı."}'::jsonb, 'B', NULL, 'Düzgün: «Qonaqlar gəldi və süfrə açıldı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6371, 82, 'g10-aze-punct-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ehtimal, ki qonaqlar axşama kimi gələcəklər.", "B": "Xoşbəxtlikdən yaralı quşu vaxtında həkimə çatdırdıq.", "C": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "D": "Hava qaraldı ulduzlar göründü, kənd sakitləşdi.", "E": "Qonaqlar, gəldi və süfrə açıldı."}'::jsonb, 'C', NULL, 'Düzgün: «Sözsüz, sizin əməyiniz qiymətləndiriləcək.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6372, 82, 'g10-aze-punct-q2-22', 2, 22, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib?', NULL, NULL, '{"A": "Of, bu çanta ağırdır!", "B": "Həm oxuyur, həm də işləyir.", "C": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "D": "Sözsüz, sizin əməyiniz qiymətləndiriləcək.", "E": "Of bu çanta ağırdır!"}'::jsonb, 'A', NULL, 'Düzgün: «Of, bu çanta ağırdır!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6373, 82, 'g10-aze-punct-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Bağda alma, armud və heyva yetişmişdi.", "B": "Həm oxuyur həm də işləyir.", "C": "Dağa, qalxdıqca hava soyuyurdu.", "D": "Anam, ilə atam toya getdilər.", "E": "Uşaq, vazanı bilərəkdən sındırmamışdı."}'::jsonb, 'A', NULL, 'Düzgün: «Bağda alma, armud və heyva yetişmişdi.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6374, 82, 'g10-aze-punct-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf, ki mən toya getmədim.", "B": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq.", "C": "Sözsüz sizin əməyiniz qiymətləndiriləcək.", "D": "Yəqin, siz bu xəbəri dünən eşitmisiniz.", "E": "Ehtimal ki qonaqlar axşama kimi gələcəklər."}'::jsonb, 'D', NULL, 'Düzgün: «Yəqin, siz bu xəbəri dünən eşitmisiniz.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6375, 82, 'g10-aze-punct-q2-25', 2, 25, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Səhər oldu amma günəş görünmədi, göy buludlu idi.", "B": "Səhər oldu, amma günəş görünmədi göy buludlu idi.", "C": "Ona görə gecikdim ki, yolda tıxac var idi.", "D": "Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.", "E": "Biz sizdən sonra gəldik."}'::jsonb, 'D', NULL, 'Düzgün: «Hava qaraldı, ulduzlar göründü, kənd sakitləşdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6376, 82, 'g10-aze-punct-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "İstəyirəm ki hamı xoşbəxt olsun.", "B": "Uşaq ağlayırdı çünki oyuncağı sınmışdı.", "C": "Müəllim soruşdu, ki tapşırığı kim yerinə yetirib.", "D": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "E": "Hava yaxşı olsa, ekskursiyaya gedəcəyik."}'::jsonb, 'E', NULL, 'Düzgün: «Hava yaxşı olsa, ekskursiyaya gedəcəyik.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6377, 82, 'g10-aze-punct-q2-27', 2, 27, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Dərslərini oxumadan oynamağa getdi.", "B": "Oxumaq insanı zənginləşdirir.", "C": "İstəyirəm, ki hamı xoşbəxt olsun.", "D": "Ey gənclər, Vətəni sevin!", "E": "Əgər sən gəlməsən, mən də getməyəcəyəm."}'::jsonb, 'E', NULL, 'Düzgün: «Əgər sən gəlməsən, mən də getməyəcəyəm.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6378, 82, 'g10-aze-punct-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "B": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir.", "C": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "D": "İstəyirəm, ki hamı xoşbəxt olsun.", "E": "Onu da bilirəm, ki siz bu işə çox əmək sərf etmisiniz."}'::jsonb, 'A', NULL, 'Düzgün: «Kim ki vətənini sevir, o, onu qorumağa hazırdır.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6379, 82, 'g10-aze-punct-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Anam, ilə atam toya getdilər.", "B": "Sən ya rəsm, ya da musiqi seç.", "C": "Ey gənclər Vətəni sevin!", "D": "Həm riyaziyyatı həm də fizikanı sevirəm.", "E": "Bağda alma, armud, və heyva yetişmişdi."}'::jsonb, 'B', NULL, 'Düzgün: «Sən ya rəsm, ya da musiqi seç.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6380, 82, 'g10-aze-punct-q2-30', 2, 30, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var?', NULL, NULL, '{"A": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "B": "Ey gənclər, Vətəni sevin!", "C": "Qoy hamı bu həqiqəti bilsin.", "D": "Heç nə demədən otaqdan çıxdı.", "E": "Qardaşım məktubu qələm ilə yazdı."}'::jsonb, 'B', NULL, 'Düzgün: «Ey gənclər, Vətəni sevin!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6381, 82, 'g10-aze-punct-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hamıya məlumdur ki Bakı Xəzərin sahilində yerləşir.", "B": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "C": "Onu da bilirəm, ki siz bu işə çox əmək sərf etmisiniz.", "D": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "E": "Nə vaxt ki qar yağdı uşaqlar həyətə çıxdılar."}'::jsonb, 'D', NULL, 'Düzgün: «Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6382, 82, 'g10-aze-punct-q3-02', 3, 2, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Onu da bilirəm ki siz bu işə çox əmək sərf etmisiniz.", "B": "Yazılmış məktubu poçta apardım.", "C": "Dağa qalxdıqca hava soyuyurdu.", "D": "Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.", "E": "Biz çayın sahili ilə xeyli getdik."}'::jsonb, 'D', NULL, 'Düzgün: «Onu da bilirəm ki, siz bu işə çox əmək sərf etmisiniz.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6383, 82, 'g10-aze-punct-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hava, qaraldı, ulduzlar göründü, kənd sakitləşdi.", "B": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "C": "Bağda alma, armud və heyva yetişmişdi.", "D": "Həm oxuyur həm də işləyir.", "E": "Anam, ilə atam toya getdilər."}'::jsonb, 'C', NULL, 'Düzgün: «Bağda alma, armud və heyva yetişmişdi.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6384, 82, 'g10-aze-punct-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Biz stansiyaya çatdıq lakin qatar artıq getmişdi.", "B": "Qonaqlar gəldi, və süfrə açıldı.", "C": "Nə o gəldi, nə də mən getdim.", "D": "Səhər, oldu, amma günəş görünmədi, göy buludlu idi.", "E": "Hava qaraldı, ulduzlar göründü kənd sakitləşdi."}'::jsonb, 'C', NULL, 'Düzgün: «Nə o gəldi, nə də mən getdim.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6385, 82, 'g10-aze-punct-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "B": "Ona görə gecikdim ki, yolda tıxac var idi.", "C": "Nə vaxt ki qar yağdı uşaqlar həyətə çıxdılar.", "D": "Hamıya məlumdur ki Bakı Xəzərin sahilində yerləşir.", "E": "Arzum odur, ki universitetə qəbul olum."}'::jsonb, 'B', NULL, 'Düzgün: «Ona görə gecikdim ki, yolda tıxac var idi.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6386, 82, 'g10-aze-punct-q3-06', 3, 6, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Kimsə həyətdə ucadan mahnı oxuyurdu.", "B": "Kim ki vətənini sevir, o onu qorumağa hazırdır.", "C": "Ona görə gecikdim ki yolda tıxac var idi.", "D": "Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.", "E": "Əhsən! Bu rəsmi kim çəkib?"}'::jsonb, 'D', NULL, 'Düzgün: «Elə bir yer seçdik ki, oradan bütün şəhər görünürdü.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6387, 82, 'g10-aze-punct-q3-07', 3, 7, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Onuncu sinfin şagirdləri teatra getdilər.", "B": "Nə o gəldi, nə də mən getdim.", "C": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "D": "Elə bir yer seçdik ki oradan bütün şəhər görünürdü.", "E": "Tez yola düşdük ki, qatara çataq."}'::jsonb, 'E', NULL, 'Düzgün: «Tez yola düşdük ki, qatara çataq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6388, 82, 'g10-aze-punct-q3-08', 3, 8, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Ona görə gecikdim ki, yolda tıxac var idi.", "B": "Biz dağın zirvəsinə doğru yuxarı qalxdıq.", "C": "Ay Leyla, pəncərəni bağla!", "D": "Ya sabah, ya da birigün gələcəyəm.", "E": "Ey gənclər, Vətəni sevin!"}'::jsonb, 'A', NULL, 'Düzgün: «Ona görə gecikdim ki, yolda tıxac var idi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6389, 82, 'g10-aze-punct-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Yəqin siz bu xəbəri dünən eşitmisiniz.", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Təəssüf, ki mən toya getmədim.", "D": "Sərnişinlər, avtobusa dalbadal mindilər.", "E": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'B', NULL, 'Düzgün: «Ehtimal ki, qonaqlar axşama kimi gələcəklər.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6390, 82, 'g10-aze-punct-q3-10', 3, 10, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də ara söz (modal söz) var?', NULL, NULL, '{"A": "Yazılmış məktubu poçta apardım.", "B": "Tez yola düşdük ki, qatara çataq.", "C": "Bacım məndən kitab istədi.", "D": "Baxmayaraq ki, hava soyuq idi, biz dənizə getdik.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'E', NULL, 'Düzgün: «Sözsüz, sizin əməyiniz qiymətləndiriləcək.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6391, 82, 'g10-aze-punct-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Arzum odur, ki universitetə qəbul olum.", "B": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "C": "Əgər sən gəlməsən, mən də getməyəcəyəm.", "D": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "E": "Uşaq ağlayırdı çünki oyuncağı sınmışdı."}'::jsonb, 'C', NULL, 'Düzgün: «Əgər sən gəlməsən, mən də getməyəcəyəm.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6392, 82, 'g10-aze-punct-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Tez yola düşdük, ki qatara çataq.", "B": "Ona görə gecikdim ki yolda tıxac var idi.", "C": "Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.", "D": "Baxmayaraq, ki hava soyuq idi, biz dənizə getdik.", "E": "Kim ki vətənini sevir o onu qorumağa hazırdır."}'::jsonb, 'C', NULL, 'Düzgün: «Hamıya məlumdur ki, Bakı Xəzərin sahilində yerləşir.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6393, 82, 'g10-aze-punct-q3-13', 3, 13, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Bir sözlə, hamı məmnun qaldı.", "B": "Bağda alma, armud və heyva yetişmişdi.", "C": "Həm riyaziyyatı həm də fizikanı sevirəm.", "D": "Ay Leyla, pəncərəni bağla!", "E": "Hansı şəhərdə doğulmusan?"}'::jsonb, 'B', NULL, 'Düzgün: «Bağda alma, armud və heyva yetişmişdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6394, 82, 'g10-aze-punct-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf, ki mən toya getmədim.", "B": "Ehtimal ki qonaqlar axşama kimi gələcəklər.", "C": "Əlbəttə biz sizə inanırıq.", "D": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq.", "E": "Sözsüz, sizin əməyiniz qiymətləndiriləcək."}'::jsonb, 'E', NULL, 'Düzgün: «Sözsüz, sizin əməyiniz qiymətləndiriləcək.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6395, 82, 'g10-aze-punct-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Ona görə gecikdim, ki yolda tıxac var idi.", "B": "Kim ki vətənini sevir, o onu qorumağa hazırdır.", "C": "Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.", "D": "Arzum odur, ki universitetə qəbul olum.", "E": "Onu da bilirəm, ki siz bu işə çox əmək sərf etmisiniz."}'::jsonb, 'C', NULL, 'Düzgün: «Müəllim soruşdu ki, tapşırığı kim yerinə yetirib.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6396, 82, 'g10-aze-punct-q3-16', 3, 16, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "B": "Bacım məndən kitab istədi.", "C": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşdülər.", "D": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "E": "Həm oxuyur, həm də işləyir."}'::jsonb, 'E', NULL, 'Düzgün: «Həm oxuyur, həm də işləyir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6397, 82, 'g10-aze-punct-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq.", "B": "Bir sözlə hamı məmnun qaldı.", "C": "Təəssüf, ki mən toya getmədim.", "D": "Ehtimal, ki qonaqlar axşama kimi gələcəklər.", "E": "Əlbəttə, biz sizə inanırıq."}'::jsonb, 'E', NULL, 'Düzgün: «Əlbəttə, biz sizə inanırıq.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6398, 82, 'g10-aze-punct-q3-18', 3, 18, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sadədir?', NULL, NULL, '{"A": "Gələn həftə sinfimiz təbiət muzeyinə gedəcək.", "B": "Dostcasına gülümsəyən satıcı bizə təzə meyvə uzatdı.", "C": "Mahnı oxuya-oxuya işləyirdi.", "D": "Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım.", "E": "Qoy hamı bu həqiqəti bilsin."}'::jsonb, 'D', NULL, 'Düzgün: «Kitabı oxuyub bitirəndən sonra onu kitabxanaya qaytardım.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6399, 82, 'g10-aze-punct-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf, ki mən toya getmədim.", "B": "Ehtimal ki, qonaqlar axşama kimi gələcəklər.", "C": "Yəqin siz bu xəbəri dünən eşitmisiniz.", "D": "Əlbəttə biz sizə inanırıq.", "E": "Xoşbəxtlikdən, yaralı, quşu vaxtında həkimə çatdırdıq."}'::jsonb, 'B', NULL, 'Düzgün: «Ehtimal ki, qonaqlar axşama kimi gələcəklər.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6400, 82, 'g10-aze-punct-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Baxmayaraq, ki hava soyuq idi, biz dənizə getdik.", "B": "Müəllim soruşdu ki tapşırığı kim yerinə yetirib.", "C": "Ona görə gecikdim ki yolda tıxac var idi.", "D": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "E": "Sən nə qədər çalışsan, bir o qədər uğur qazanarsan."}'::jsonb, 'E', NULL, 'Düzgün: «Sən nə qədər çalışsan, bir o qədər uğur qazanarsan.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6401, 82, 'g10-aze-punct-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "B": "Baxmayaraq ki, hava soyuq idi biz dənizə getdik.", "C": "Kim ki vətənini sevir, o, onu qorumağa hazırdır.", "D": "Onu da bilirəm, ki siz bu işə çox əmək sərf etmisiniz.", "E": "Tez yola düşdük ki qatara çataq."}'::jsonb, 'C', NULL, 'Düzgün: «Kim ki vətənini sevir, o, onu qorumağa hazırdır.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6402, 82, 'g10-aze-punct-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Şagirdlər həm oxuyur, həm də işləyirlər.", "B": "Elə bir yer seçdik, ki oradan bütün şəhər görünürdü.", "C": "Hava, qaraldı, ulduzlar göründü, kənd sakitləşdi.", "D": "Qardaşım, məktubu qələm ilə yazdı.", "E": "Həm oxuyur həm də işləyir."}'::jsonb, 'A', NULL, 'Düzgün: «Şagirdlər həm oxuyur, həm də işləyirlər.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6403, 82, 'g10-aze-punct-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Tez yola düşdük ki qatara çataq.", "B": "Kim ki vətənini sevir o onu qorumağa hazırdır.", "C": "Hamıya məlumdur, ki Bakı Xəzərin sahilində yerləşir.", "D": "Əgər sən gəlməsən mən də getməyəcəyəm.", "E": "Uşaq ağlayırdı, çünki oyuncağı sınmışdı."}'::jsonb, 'E', NULL, 'Düzgün: «Uşaq ağlayırdı, çünki oyuncağı sınmışdı.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6404, 82, 'g10-aze-punct-q3-24', 3, 24, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də həmcins üzvlər var?', NULL, NULL, '{"A": "Təəssüf ki, mən toya getmədim.", "B": "Vay, buzlu yolda maşın sürüşdü!", "C": "Həm oxuyur, həm də işləyir.", "D": "Bağda alma armud və heyva yetişmişdi.", "E": "Dağa qalxdıqca hava soyuyurdu."}'::jsonb, 'C', NULL, 'Düzgün: «Həm oxuyur, həm də işləyir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6405, 82, 'g10-aze-punct-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Qonaqlar gəldi, və süfrə açıldı.", "B": "Səhər, oldu, amma günəş görünmədi, göy buludlu idi.", "C": "Biz, stansiyaya çatdıq, lakin qatar artıq getmişdi.", "D": "Hava qaraldı ulduzlar göründü, kənd sakitləşdi.", "E": "Nə o gəldi, nə də mən getdim."}'::jsonb, 'E', NULL, 'Düzgün: «Nə o gəldi, nə də mən getdim.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (6406, 82, 'g10-aze-punct-q3-26', 3, 26, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib?', NULL, NULL, '{"A": "Səhər oldu, amma günəş görünmədi, göy buludlu idi.", "B": "Ey gənclər, Vətəni sevin!", "C": "Ay Leyla pəncərəni bağla!", "D": "Səkkizinci mərtəbədə yaşayan qonşumuz hər səhər parkda qaçır.", "E": "Of bu çanta ağırdır!"}'::jsonb, 'B', NULL, 'Düzgün: «Ey gənclər, Vətəni sevin!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6407, 82, 'g10-aze-punct-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Əhsən! Bu rəsmi kim çəkib.", "B": "Ah, köhnə, dostumu uzun müddət görmədim!", "C": "Ura bayram gəldi!", "D": "Ay Leyla pəncərəni bağla!", "E": "Of, bu çanta ağırdır!"}'::jsonb, 'E', NULL, 'Düzgün: «Of, bu çanta ağırdır!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (6408, 82, 'g10-aze-punct-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Baxmayaraq ki hava soyuq idi biz dənizə getdik.", "B": "Hava yaxşı olsa, ekskursiyaya gedəcəyik.", "C": "Nə vaxt ki qar yağdı uşaqlar həyətə çıxdılar.", "D": "Hara getsən orada dost tapacaqsan.", "E": "Tez yola düşdük, ki qatara çataq."}'::jsonb, 'B', NULL, 'Düzgün: «Hava yaxşı olsa, ekskursiyaya gedəcəyik.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (6409, 82, 'g10-aze-punct-q3-29', 3, 29, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabesiz mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hava qaraldı, ulduzlar göründü kənd sakitləşdi.", "B": "Qəhrəmancasına vuruşan əsgərlər düşməni geri oturtdular.", "C": "Nə o gəldi, nə də mən getdim.", "D": "Qardaşım məktubu qələm ilə yazdı.", "E": "Dərslərini oxumadan oynamağa getdi."}'::jsonb, 'C', NULL, 'Düzgün: «Nə o gəldi, nə də mən getdim.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6410, 82, 'g10-aze-punct-q3-30', 3, 30, 'medium', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə sual cümləsidir?', NULL, NULL, '{"A": "Oxumaq insanı zənginləşdirir.", "B": "Tez yola düşdük ki, qatara çataq.", "C": "Biz stansiyaya çatdıq, lakin qatar artıq getmişdi.", "D": "Əhsən! Bu rəsmi kim çəkib?", "E": "Vay, buzlu yolda maşın sürüşdü!"}'::jsonb, 'D', NULL, 'Düzgün: «Əhsən! Bu rəsmi kim çəkib?». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (6411, 83, 'g10-eng-tense-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He ___ (watch) a documentary two days ago. (2) By the time we arrived, he had already ___ (finish) the project.', NULL, NULL, '{"A": "watched / finished", "B": "watched / finishing", "C": "will watch / finished", "D": "watched / finish", "E": "has watched / finished"}'::jsonb, 'A', NULL, '(1) watched — Past Simple: «ago» ilə (2) finished — Past Perfect: had + V3');
INSERT INTO public.questions VALUES (6412, 83, 'g10-eng-tense-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Our neighbours ___ (clean) the kitchen three times since January. (2) They ___ (buy) a new laptop two days ago.', NULL, NULL, '{"A": "have cleaned / have bought", "B": "cleaned / bought", "C": "have cleaned / bought", "D": "clean / bought", "E": "have cleaned / buy"}'::jsonb, 'C', NULL, '(1) have cleaned — Present Perfect: «since» + təkrar sayı (2) bought — Past Simple: «ago» ilə');
INSERT INTO public.questions VALUES (6413, 83, 'g10-eng-tense-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, they had already ___ (design) a poster. (2) We ___ (translate) the article two days ago.', NULL, NULL, '{"A": "designing / translated", "B": "designed / translate", "C": "design / translated", "D": "designed / have translated", "E": "designed / translated"}'::jsonb, 'E', NULL, '(1) designed — Past Perfect: had + V3 (2) translated — Past Simple: «ago» ilə');
INSERT INTO public.questions VALUES (6414, 83, 'g10-eng-tense-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, I ___ (translate) the article. (2) Our neighbours ___ (design) a poster three times since January.', NULL, NULL, '{"A": "was translating / have designed", "B": "had translated / have designed", "C": "have been translating / have designed", "D": "will be translating / design", "E": "will be translating / have designed"}'::jsonb, 'E', NULL, '(1) will be translating — Future Continuous: «this time tomorrow» (2) have designed — Present Perfect: «since» + təkrar sayı');
INSERT INTO public.questions VALUES (6415, 83, 'g10-eng-tense-q1-05', 1, 5, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We have repaired the old bike two days ago.", "B": "Our neighbours washed the dishes two days ago.", "C": "This time tomorrow, she visited the museum.", "D": "By the time we arrived, he had already buy a new laptop.", "E": "This time tomorrow, she bought a new laptop."}'::jsonb, 'B', NULL, 'Correct: «Our neighbours washed the dishes two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6416, 83, 'g10-eng-tense-q1-06', 1, 6, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The students finished the project two days ago.", "B": "By the time we arrived, I had already wash the dishes.", "C": "Look! I visit the museum right now.", "D": "Every Sunday our neighbours will have bought a new laptop; it is a family tradition.", "E": "By the time we arrived, they had already wash the dishes."}'::jsonb, 'A', NULL, 'Correct: «The students finished the project two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6417, 83, 'g10-eng-tense-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Look! He cooks dinner right now.", "B": "They are visiting the museum when the lights suddenly went out.", "C": "By next July, they will have translated the article.", "D": "By the time we arrived, I paint the fence.", "E": "Every Sunday they had painted the fence; it is a family tradition."}'::jsonb, 'C', NULL, 'Correct: «By next July, they will have translated the article.» — Future Perfect: «by next July». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6418, 83, 'g10-eng-tense-q1-08', 1, 8, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My brother has taught the younger kids two days ago.", "B": "By next July, they watched a documentary.", "C": "By the time we arrived, she had already buying a new laptop.", "D": "He cleaned the kitchen two days ago.", "E": "By the time we arrived, they study for the exam."}'::jsonb, 'D', NULL, 'Correct: «He cleaned the kitchen two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6419, 83, 'g10-eng-tense-q1-09', 1, 9, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My brother watches a documentary three times since January.", "B": "By the time we arrived, he will have designed a poster.", "C": "Every Sunday they design a poster; it is a family tradition.", "D": "Look! I translated the article right now.", "E": "By the time we arrived, they have written a long letter."}'::jsonb, 'C', NULL, 'Correct: «Every Sunday they design a poster; it is a family tradition.» — Present Simple: müntəzəm adət (Every Sunday … it is a tradition). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6420, 83, 'g10-eng-tense-q1-10', 1, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By next July, she has watched a documentary.", "B": "Every Sunday he will have repaired the old bike; it is a family tradition.", "C": "He was repairing the old bike when the lights suddenly went out.", "D": "This time tomorrow, I have been painting the fence.", "E": "She is designing a poster three times since January."}'::jsonb, 'C', NULL, 'Correct: «He was repairing the old bike when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6421, 83, 'g10-eng-tense-q1-11', 1, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This time tomorrow, I will be translating the article.", "B": "Look! She studied for the exam right now.", "C": "Every Sunday my brother had planted trees in the garden; it is a family tradition.", "D": "I have studied for the exam two days ago.", "E": "This time tomorrow, they had studied for the exam."}'::jsonb, 'A', NULL, 'Correct: «This time tomorrow, I will be translating the article.» — Future Continuous: «this time tomorrow». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6422, 83, 'g10-eng-tense-q1-12', 1, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He ___ (paint) the fence three times since January. (2) By the time we arrived, they ___ (read) the report.', NULL, NULL, '{"A": "paints / had read", "B": "has painted / read", "C": "painted / had read", "D": "has painted / had read", "E": "is painting / had read"}'::jsonb, 'D', NULL, '(1) has painted — Present Perfect: «since» + təkrar sayı (2) had read — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (6423, 83, 'g10-eng-tense-q1-13', 1, 13, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every Sunday we were finishing the project; it is a family tradition.", "B": "Every Sunday the students had washed the dishes; it is a family tradition.", "C": "This time tomorrow, he has been cleaning the kitchen.", "D": "My brother wrote a long letter two days ago.", "E": "They have painted the fence two days ago."}'::jsonb, 'D', NULL, 'Correct: «My brother wrote a long letter two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6424, 83, 'g10-eng-tense-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, they had already translate the article.", "B": "By next July, she taught the younger kids.", "C": "He was finishing the project when the lights suddenly went out.", "D": "I visit the museum when the lights suddenly went out.", "E": "This time tomorrow, we were studying for the exam."}'::jsonb, 'C', NULL, 'Correct: «He was finishing the project when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6425, 83, 'g10-eng-tense-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, they ___ (paint) the fence. (2) I will call you as soon as I ___ (clean) the kitchen.', NULL, NULL, '{"A": "painted / clean", "B": "will be painting / clean", "C": "will be painting / would clean", "D": "will be painting / will clean", "E": "were painting / clean"}'::jsonb, 'B', NULL, '(1) will be painting — Future Continuous: «this time tomorrow» (2) clean — Zaman budaq cümləsində (as soon as, when) gələcək Present Simple ilə ifadə olunur');
INSERT INTO public.questions VALUES (6426, 83, 'g10-eng-tense-q1-16', 1, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, they ___ (visit) the museum. (2) She ___ (paint) the fence for two hours, and she still hasn''t finished.', NULL, NULL, '{"A": "will have visited / has been painting", "B": "had visited / has been painting", "C": "have visited / has been painting", "D": "had visited / is painting", "E": "had visited / painted"}'::jsonb, 'B', NULL, '(1) had visited — Past Perfect: «by the time» + keçmiş (2) has been painting — Present Perfect Continuous: davam edən proses');
INSERT INTO public.questions VALUES (6427, 83, 'g10-eng-tense-q1-17', 1, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, I had already ___ (visit) the museum. (2) By the time we arrived, she had already ___ (study) for the exam.', NULL, NULL, '{"A": "visiting / studied", "B": "visited / study", "C": "visited / studied", "D": "visited / studying", "E": "visit / studied"}'::jsonb, 'C', NULL, '(1) visited — Past Perfect: had + V3 (2) studied — Past Perfect: had + V3');
INSERT INTO public.questions VALUES (6428, 83, 'g10-eng-tense-q1-18', 1, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This time tomorrow, they watched a documentary.", "B": "I have written a long letter when the lights suddenly went out.", "C": "By the time we arrived, he had already cleaning the kitchen.", "D": "This time tomorrow, he was reading the report.", "E": "I will call you as soon as I finish the project."}'::jsonb, 'E', NULL, 'Correct: «I will call you as soon as I finish the project.» — Zaman budaq cümləsində (as soon as, when) gələcək Present Simple ilə ifadə olunur. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6429, 83, 'g10-eng-tense-q1-19', 1, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, I had already writing a long letter.", "B": "Every Sunday we had bought a new laptop; it is a family tradition.", "C": "We have planted trees in the garden two days ago.", "D": "They have planted trees in the garden three times since January.", "E": "My brother has translated the article when the lights suddenly went out."}'::jsonb, 'D', NULL, 'Correct: «They have planted trees in the garden three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6430, 83, 'g10-eng-tense-q1-20', 1, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This time tomorrow, he will be cooking dinner.", "B": "Every Sunday I will have visited the museum; it is a family tradition.", "C": "The students teach the younger kids two days ago.", "D": "We designed a poster three times since January.", "E": "He writes a long letter two days ago."}'::jsonb, 'A', NULL, 'Correct: «This time tomorrow, he will be cooking dinner.» — Future Continuous: «this time tomorrow». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6431, 83, 'g10-eng-tense-q1-21', 1, 21, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) Look! He ___ (wash) the dishes right now. (2) Every Sunday he ___ (teach) the younger kids; it is a family tradition.', NULL, NULL, '{"A": "washes / teaches", "B": "is washing / was teaching", "C": "has washed / teaches", "D": "is washing / teaches", "E": "washed / teaches"}'::jsonb, 'D', NULL, '(1) is washing — Present Continuous: «right now», «Look!» (2) teaches — Present Simple: müntəzəm adət (Every Sunday … it is a tradition)');
INSERT INTO public.questions VALUES (6432, 83, 'g10-eng-tense-q1-22', 1, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, he ___ (teach) the younger kids. (2) The students ___ (wash) the dishes two days ago.', NULL, NULL, '{"A": "will be teaching / will wash", "B": "will be teaching / wash", "C": "had taught / washed", "D": "was teaching / washed", "E": "will be teaching / washed"}'::jsonb, 'E', NULL, '(1) will be teaching — Future Continuous: «this time tomorrow» (2) washed — Past Simple: «ago» ilə');
INSERT INTO public.questions VALUES (6433, 83, 'g10-eng-tense-q1-23', 1, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, she ___ (teach) the younger kids. (2) Look! I ___ (buy) a new laptop right now.', NULL, NULL, '{"A": "had taught / bought", "B": "teaches / am buying", "C": "has taught / am buying", "D": "had taught / am buying", "E": "had taught / buy"}'::jsonb, 'D', NULL, '(1) had taught — Past Perfect: «by the time» + keçmiş (2) am buying — Present Continuous: «right now», «Look!»');
INSERT INTO public.questions VALUES (6434, 83, 'g10-eng-tense-q1-24', 1, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By next July, he read the report.", "B": "My brother was buying a new laptop when the lights suddenly went out.", "C": "He was planting trees in the garden for two hours, and he still hasn''t finished.", "D": "She was visiting the museum for two hours, and she still hasn''t finished.", "E": "My brother is cleaning the kitchen for two hours, and he still hasn''t finished."}'::jsonb, 'B', NULL, 'Correct: «My brother was buying a new laptop when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6435, 83, 'g10-eng-tense-q1-25', 1, 25, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) They ___ (translate) the article two days ago. (2) Our neighbours ___ (read) the report two days ago.', NULL, NULL, '{"A": "translated / read", "B": "translate / read", "C": "translated / will read", "D": "translated / have read", "E": "have translated / read"}'::jsonb, 'A', NULL, '(1) translated — Past Simple: «ago» ilə (2) read — Past Simple: «ago» ilə');
