INSERT INTO public.questions VALUES (6478, 83, 'g10-eng-tense-q3-08', 3, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She will be watching a documentary when the lights suddenly went out.", "B": "By next July, she washed the dishes.", "C": "This time tomorrow, they will be reading the report.", "D": "I have cooked dinner two days ago.", "E": "My brother cleaned the kitchen three times since January."}'::jsonb, 'C', NULL, 'Correct: «This time tomorrow, they will be reading the report.» — Future Continuous: «this time tomorrow». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6479, 83, 'g10-eng-tense-q3-09', 3, 9, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Look! My brother has designed a poster right now.", "B": "This time tomorrow, they were painting the fence.", "C": "This time tomorrow, he translated the article.", "D": "Look! My brother is writing a long letter right now.", "E": "By the time we arrived, they had already studying for the exam."}'::jsonb, 'D', NULL, 'Correct: «Look! My brother is writing a long letter right now.» — Present Continuous: «right now», «Look!». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6480, 83, 'g10-eng-tense-q3-10', 3, 10, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Our neighbours teach the younger kids two days ago.", "B": "Every Sunday he will have visited the museum; it is a family tradition.", "C": "By the time we arrived, he had already studying for the exam.", "D": "They watched a documentary two days ago.", "E": "Look! She translates the article right now."}'::jsonb, 'D', NULL, 'Correct: «They watched a documentary two days ago.» — Past Simple: «ago» ilə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6481, 83, 'g10-eng-tense-q3-11', 3, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She is studying for the exam when the lights suddenly went out.", "B": "Every Sunday the students had read the report; it is a family tradition.", "C": "I have washed the dishes two days ago.", "D": "The students were repairing the old bike when the lights suddenly went out.", "E": "This time tomorrow, they studied for the exam."}'::jsonb, 'D', NULL, 'Correct: «The students were repairing the old bike when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6482, 83, 'g10-eng-tense-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Look! They ___ (teach) the younger kids right now. (2) They ___ (visit) the museum when the lights suddenly went out.', NULL, NULL, '{"A": "teach / were visiting", "B": "are teaching / were visiting", "C": "are teaching / visit", "D": "are teaching / will be visiting", "E": "are teaching / are visiting"}'::jsonb, 'B', NULL, '(1) are teaching — Present Continuous: «right now», «Look!» (2) were visiting — Past Continuous: kəsilən proses');
INSERT INTO public.questions VALUES (6483, 83, 'g10-eng-tense-q3-13', 3, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Look! The students ___ (read) the report right now. (2) By the time we arrived, they ___ (plant) trees in the garden.', NULL, NULL, '{"A": "are reading / will have planted", "B": "are reading / had planted", "C": "are reading / plant", "D": "are reading / have planted", "E": "read / had planted"}'::jsonb, 'B', NULL, '(1) are reading — Present Continuous: «right now», «Look!» (2) had planted — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (6484, 83, 'g10-eng-tense-q3-14', 3, 14, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Look! She is studying for the exam right now.", "B": "We have taught the younger kids two days ago.", "C": "By the time we arrived, they had already teaching the younger kids.", "D": "Look! I planted trees in the garden right now.", "E": "They will plant trees in the garden two days ago."}'::jsonb, 'A', NULL, 'Correct: «Look! She is studying for the exam right now.» — Present Continuous: «right now», «Look!». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6485, 83, 'g10-eng-tense-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, they ___ (buy) a new laptop. (2) He ___ (repair) the old bike for two hours, and he still hasn''t finished.', NULL, NULL, '{"A": "had bought / repaired", "B": "had bought / has been repairing", "C": "have bought / has been repairing", "D": "had bought / was repairing", "E": "will have bought / has been repairing"}'::jsonb, 'B', NULL, '(1) had bought — Past Perfect: «by the time» + keçmiş (2) has been repairing — Present Perfect Continuous: davam edən proses');
INSERT INTO public.questions VALUES (6486, 83, 'g10-eng-tense-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Look! I ___ (write) a long letter right now. (2) He ___ (write) a long letter three times since January.', NULL, NULL, '{"A": "am writing / writes", "B": "am writing / is writing", "C": "wrote / has written", "D": "am writing / has written", "E": "write / has written"}'::jsonb, 'D', NULL, '(1) am writing — Present Continuous: «right now», «Look!» (2) has written — Present Perfect: «since» + təkrar sayı');
INSERT INTO public.questions VALUES (6487, 83, 'g10-eng-tense-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She has washed the dishes three times since January.", "B": "My brother repaired the old bike three times since January.", "C": "This time tomorrow, we had visited the museum.", "D": "By next July, they had read the report.", "E": "My brother has cleaned the kitchen two days ago."}'::jsonb, 'A', NULL, 'Correct: «She has washed the dishes three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6488, 83, 'g10-eng-tense-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The students bought a new laptop three times since January.", "B": "Look! My brother watches a documentary right now.", "C": "By next July, they will have repaired the old bike.", "D": "They are translating the article three times since January.", "E": "Look! We have bought a new laptop right now."}'::jsonb, 'C', NULL, 'Correct: «By next July, they will have repaired the old bike.» — Future Perfect: «by next July». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6489, 83, 'g10-eng-tense-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, they ___ (paint) the fence. (2) By the time we arrived, he ___ (plant) trees in the garden.', NULL, NULL, '{"A": "were painting / had planted", "B": "have been painting / had planted", "C": "will be painting / has planted", "D": "will be painting / had planted", "E": "will be painting / plants"}'::jsonb, 'D', NULL, '(1) will be painting — Future Continuous: «this time tomorrow» (2) had planted — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (6490, 83, 'g10-eng-tense-q3-20', 3, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They ___ (write) a long letter when the lights suddenly went out. (2) The students ___ (wash) the dishes three times since January.', NULL, NULL, '{"A": "were writing / wash", "B": "were writing / have washed", "C": "were writing / washed", "D": "write / have washed", "E": "have written / have washed"}'::jsonb, 'B', NULL, '(1) were writing — Past Continuous: kəsilən proses (2) have washed — Present Perfect: «since» + təkrar sayı');
INSERT INTO public.questions VALUES (6491, 83, 'g10-eng-tense-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, they ___ (wash) the dishes. (2) This time tomorrow, he ___ (write) a long letter.', NULL, NULL, '{"A": "will be washing / will be writing", "B": "will be washing / wrote", "C": "will be washing / was writing", "D": "will be washing / had written", "E": "have been washing / will be writing"}'::jsonb, 'A', NULL, '(1) will be washing — Future Continuous: «this time tomorrow» (2) will be writing — Future Continuous: «this time tomorrow»');
INSERT INTO public.questions VALUES (6492, 83, 'g10-eng-tense-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They ___ (translate) the article three times since January. (2) By the time we arrived, he ___ (design) a poster.', NULL, NULL, '{"A": "have translated / had designed", "B": "translate / had designed", "C": "are translating / had designed", "D": "have translated / designs", "E": "have translated / will have designed"}'::jsonb, 'A', NULL, '(1) have translated — Present Perfect: «since» + təkrar sayı (2) had designed — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (6493, 83, 'g10-eng-tense-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I ___ (repair) the old bike three times since January. (2) Look! The students ___ (cook) dinner right now.', NULL, NULL, '{"A": "have repaired / are cooking", "B": "have repaired / cooked", "C": "repair / are cooking", "D": "have repaired / cook", "E": "repaired / are cooking"}'::jsonb, 'A', NULL, '(1) have repaired — Present Perfect: «since» + təkrar sayı (2) are cooking — Present Continuous: «right now», «Look!»');
INSERT INTO public.questions VALUES (6494, 83, 'g10-eng-tense-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They ___ (plant) trees in the garden three times since January. (2) By the time we arrived, he had already ___ (repair) the old bike.', NULL, NULL, '{"A": "are planting / repaired", "B": "have planted / repaired", "C": "have planted / repairing", "D": "have planted / repair", "E": "planted / repaired"}'::jsonb, 'B', NULL, '(1) have planted — Present Perfect: «since» + təkrar sayı (2) repaired — Past Perfect: had + V3');
INSERT INTO public.questions VALUES (6495, 83, 'g10-eng-tense-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She finishes the project three times since January.", "B": "By the time we arrived, they read the report.", "C": "By next July, we will have visited the museum.", "D": "By next July, I have written a long letter.", "E": "This time tomorrow, she designed a poster."}'::jsonb, 'C', NULL, 'Correct: «By next July, we will have visited the museum.» — Future Perfect: «by next July». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6496, 83, 'g10-eng-tense-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, he ___ (buy) a new laptop. (2) By the time we arrived, she ___ (buy) a new laptop.', NULL, NULL, '{"A": "had bought / had bought", "B": "has bought / had bought", "C": "had bought / has bought", "D": "had bought / will have bought", "E": "buys / had bought"}'::jsonb, 'A', NULL, '(1) had bought — Past Perfect: «by the time» + keçmiş (2) had bought — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (6497, 83, 'g10-eng-tense-q3-27', 3, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, they ___ (wash) the dishes. (2) Every Sunday I ___ (visit) the museum; it is a family tradition.', NULL, NULL, '{"A": "will be washing / was visiting", "B": "were washing / visit", "C": "will be washing / visit", "D": "washed / visit", "E": "had washed / visit"}'::jsonb, 'C', NULL, '(1) will be washing — Future Continuous: «this time tomorrow» (2) visit — Present Simple: müntəzəm adət (Every Sunday … it is a tradition)');
INSERT INTO public.questions VALUES (6498, 83, 'g10-eng-tense-q3-28', 3, 28, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, he had already buying a new laptop.", "B": "Our neighbours will clean the kitchen two days ago.", "C": "Look! The students translate the article right now.", "D": "By the time we arrived, they had bought a new laptop.", "E": "Look! He studied for the exam right now."}'::jsonb, 'D', NULL, 'Correct: «By the time we arrived, they had bought a new laptop.» — Past Perfect: «by the time» + keçmiş. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6499, 83, 'g10-eng-tense-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She ___ (buy) a new laptop for two hours, and she still hasn''t finished. (2) By the time we arrived, I ___ (design) a poster.', NULL, NULL, '{"A": "is buying / had designed", "B": "has been buying / had designed", "C": "has been buying / will have designed", "D": "has been buying / have designed", "E": "has been buying / design"}'::jsonb, 'B', NULL, '(1) has been buying — Present Perfect Continuous: davam edən proses (2) had designed — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (6500, 83, 'g10-eng-tense-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every Sunday he will have planted trees in the garden; it is a family tradition.", "B": "Every Sunday he will have watched a documentary; it is a family tradition.", "C": "They plant trees in the garden two days ago.", "D": "The students have planted trees in the garden when the lights suddenly went out.", "E": "By the time we arrived, he had already painted the fence."}'::jsonb, 'E', NULL, 'Correct: «By the time we arrived, he had already painted the fence.» — Past Perfect: had + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6501, 84, 'g10-eng-cond-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless I would have more time, I won''t visit my grandparents.", "B": "Unless you study harder, you won''t pass the exam.", "C": "If you have studied harder, you would pass the exam.", "D": "Had I known about the meeting, I had attended it.", "E": "If she has practised every day, she would win the competition."}'::jsonb, 'B', NULL, 'Correct: «Unless you study harder, you won''t pass the exam.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6502, 84, 'g10-eng-cond-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she had studied medicine, she would be a doctor now.", "B": "If you mix red and blue, you got to purple.", "C": "If he had taken the medicine, he hadn''t felt ill now.", "D": "Unless we would leave now, we won''t catch the train.", "E": "If she would have practised every day, she would have won the competition."}'::jsonb, 'A', NULL, 'Correct: «If she had studied medicine, she would be a doctor now.» — Qarışıq şərt: keçmiş şərt, indiki nəticə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6503, 84, 'g10-eng-cond-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If only I drove more carefully yesterday!", "B": "If he will check the figures, he would find the mistake.", "C": "If I wasn''t been afraid of flying, I would have visited you last summer.", "D": "She wishes she had gone to the party last night.", "E": "If they have saved enough money, they would have bought a new house."}'::jsonb, 'D', NULL, 'Correct: «She wishes she had gone to the party last night.» — wish + Past Perfect: keçmişə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6504, 84, 'g10-eng-cond-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I had had more time, I will have visited my grandparents.", "B": "If we left now, we will catch the train.", "C": "If we will leave now, we would catch the train.", "D": "Unless I will have more time, I won''t visit my grandparents.", "E": "If I had had more time, I would have visited my grandparents."}'::jsonb, 'E', NULL, 'Correct: «If I had had more time, I would have visited my grandparents.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6505, 84, 'g10-eng-cond-q1-05', 1, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless she practises every day, she won''t win the competition.", "B": "If I will have more time, I would visit my grandparents.", "C": "If I had had more time, I will have visited my grandparents.", "D": "If plants don''t get water, they dying.", "E": "If she will practise every day, she will win the competition."}'::jsonb, 'A', NULL, 'Correct: «Unless she practises every day, she won''t win the competition.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6506, 84, 'g10-eng-cond-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she had studied medicine, she ___ a doctor now. (be) (2) If they ___ (save) enough money, they would buy a new house.', NULL, NULL, '{"A": "would be / will save", "B": "would be / save", "C": "had been / saved", "D": "would be / saved", "E": "would be / have saved"}'::jsonb, 'D', NULL, '(1) would be — Qarışıq şərt: keçmiş şərt, indiki nəticə (2) saved — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (6507, 84, 'g10-eng-cond-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he will have checked the figures, he would have found the mistake.", "B": "I wish I knowing the answer to this question.", "C": "If you will study harder, you will pass the exam.", "D": "If I had had more time, I would have visited my grandparents.", "E": "If she would have practised every day, she would have won the competition."}'::jsonb, 'D', NULL, 'Correct: «If I had had more time, I would have visited my grandparents.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6508, 84, 'g10-eng-cond-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If plants don''t get water, they ___. (2) If we ___ (leave) now, we would catch the train.', NULL, NULL, '{"A": "die / will leave", "B": "dying / left", "C": "die / leave", "D": "dies / left", "E": "die / left"}'::jsonb, 'E', NULL, '(1) die — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) left — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (6509, 84, 'g10-eng-cond-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless he ___ (check) the figures, he won''t find the mistake. (2) If she ___ (practise) every day, she will win the competition.', NULL, NULL, '{"A": "checks / practised", "B": "will check / practises", "C": "won''t check / practises", "D": "checks / practises", "E": "checks / will practise"}'::jsonb, 'D', NULL, '(1) checks — Unless = if not; zaman/şərt hissəsində Present Simple (2) practises — I tip şərt: If + Present Simple, will + V1');
INSERT INTO public.questions VALUES (6510, 84, 'g10-eng-cond-q1-10', 1, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you study harder, you would pass the exam.", "B": "Had I known about the meeting, I had attended it.", "C": "If they will have saved enough money, they would have bought a new house.", "D": "Unless I won''t have more time, I won''t visit my grandparents.", "E": "I wish I knew the answer to this question."}'::jsonb, 'E', NULL, 'Correct: «I wish I knew the answer to this question.» — wish + Past Simple: indiki vəziyyətə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6511, 84, 'g10-eng-cond-q1-11', 1, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I had had more time, I will visit my grandparents.", "B": "If he had checked the figures, he will find the mistake.", "C": "If he had taken the medicine, he hadn''t felt ill now.", "D": "I wish I knew the answer to this question.", "E": "Unless you won''t study harder, you won''t pass the exam."}'::jsonb, 'D', NULL, 'Correct: «I wish I knew the answer to this question.» — wish + Past Simple: indiki vəziyyətə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6512, 84, 'g10-eng-cond-q1-12', 1, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If water reaches 100°C, it is boil.", "B": "Unless he checks the figures, he won''t find the mistake.", "C": "Unless we won''t leave now, we won''t catch the train.", "D": "If we will leave now, we will catch the train.", "E": "If only I drive more carefully yesterday!"}'::jsonb, 'B', NULL, 'Correct: «Unless he checks the figures, he won''t find the mistake.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6513, 84, 'g10-eng-cond-q1-13', 1, 13, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) If water reaches 100°C, it ___. (2) If we ___ (leave) now, we will catch the train.', NULL, NULL, '{"A": "boil / leave", "B": "boils / left", "C": "boils / will leave", "D": "boils / leave", "E": "boils / had left"}'::jsonb, 'D', NULL, '(1) boils — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) leave — I tip şərt: If + Present Simple, will + V1');
INSERT INTO public.questions VALUES (6514, 84, 'g10-eng-cond-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have more time, I would visit my grandparents.", "B": "I wish I am taller.", "C": "Had I known about the meeting, I will attend it.", "D": "If she practised every day, she would win the competition.", "E": "If they had saved enough money, they will buy a new house."}'::jsonb, 'D', NULL, 'Correct: «If she practised every day, she would win the competition.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6515, 84, 'g10-eng-cond-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she had studied medicine, she ___ a doctor now. (be) (2) If I ___ (have) more time, I would have visited my grandparents.', NULL, NULL, '{"A": "had been / had had", "B": "would be / would have had", "C": "would be / have had", "D": "would be / had had", "E": "would be / will have had"}'::jsonb, 'D', NULL, '(1) would be — Qarışıq şərt: keçmiş şərt, indiki nəticə (2) had had — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6516, 84, 'g10-eng-cond-q1-16', 1, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless he will check the figures, he won''t find the mistake.", "B": "If I have had more time, I would visit my grandparents.", "C": "If water reaches 100°C, it boiling.", "D": "If you had studied harder, you will pass the exam.", "E": "If only I had driven more carefully yesterday!"}'::jsonb, 'E', NULL, 'Correct: «If only I had driven more carefully yesterday!» — If only + Past Perfect: keçmişə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6517, 84, 'g10-eng-cond-q1-17', 1, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish I ___ the answer to this question. (know) (2) If you ___ (study) harder, you will pass the exam.', NULL, NULL, '{"A": "knowing / study", "B": "knew / study", "C": "knew / studied", "D": "know / study", "E": "will know / study"}'::jsonb, 'B', NULL, '(1) knew — wish + Past Simple: indiki vəziyyətə təəssüf (2) study — I tip şərt: If + Present Simple, will + V1');
INSERT INTO public.questions VALUES (6518, 84, 'g10-eng-cond-q1-18', 1, 18, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless they will save enough money, they won''t buy a new house.", "B": "If you study harder, you will pass the exam.", "C": "Unless we would leave now, we won''t catch the train.", "D": "If I will have had more time, I would have visited my grandparents.", "E": "If he had taken the medicine, he doesn''t feel ill now."}'::jsonb, 'B', NULL, 'Correct: «If you study harder, you will pass the exam.» — I tip şərt: If + Present Simple, will + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6519, 84, 'g10-eng-cond-q1-19', 1, 19, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you mix red and blue, you getting purple.", "B": "If you heat ice, it will melted.", "C": "If you studied harder, you will pass the exam.", "D": "I wish I am taller.", "E": "If I have more time, I will visit my grandparents."}'::jsonb, 'E', NULL, 'Correct: «If I have more time, I will visit my grandparents.» — I tip şərt: If + Present Simple, will + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6520, 84, 'g10-eng-cond-q1-20', 1, 20, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) If you heat ice, it ___. (2) If water reaches 100°C, it ___.', NULL, NULL, '{"A": "melts / is boil", "B": "melts / boil", "C": "melts / boils", "D": "melting / boils", "E": "will melted / boils"}'::jsonb, 'C', NULL, '(1) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) boils — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple');
INSERT INTO public.questions VALUES (6521, 84, 'g10-eng-cond-q1-21', 1, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Should you need any help, ___ me. (call) (2) If you ___ (study) harder, you would have passed the exam.', NULL, NULL, '{"A": "calling / had studied", "B": "to call / had studied", "C": "call / would have studied", "D": "call / had studied", "E": "call / will have studied"}'::jsonb, 'D', NULL, '(1) call — İnversiya: Should you need = If you need; əmr (2) had studied — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6522, 84, 'g10-eng-cond-q1-22', 1, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I have more time, I would visit my grandparents.", "B": "If we left now, we would catch the train.", "C": "If we will leave now, we will catch the train.", "D": "If they had saved enough money, they will buy a new house.", "E": "If she have practised every day, she would have won the competition."}'::jsonb, 'B', NULL, 'Correct: «If we left now, we would catch the train.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6523, 84, 'g10-eng-cond-q1-23', 1, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She wishes she went to the party last night.", "B": "If we had left now, we would have caught the train.", "C": "If they had saved enough money, they will buy a new house.", "D": "If she would have practised every day, she would have won the competition.", "E": "If you had studied harder, you will have passed the exam."}'::jsonb, 'B', NULL, 'Correct: «If we had left now, we would have caught the train.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6524, 84, 'g10-eng-cond-q1-24', 1, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If they ___ (save) enough money, they would have bought a new house. (2) Unless I ___ (have) more time, I won''t visit my grandparents.', NULL, NULL, '{"A": "have saved / have", "B": "will have saved / have", "C": "had saved / will have", "D": "had saved / have", "E": "had saved / would have"}'::jsonb, 'D', NULL, '(1) had saved — III tip şərt: şərt hissəsində Past Perfect (2) have — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (6525, 84, 'g10-eng-cond-q1-25', 1, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you mix red and blue, you ___ purple. (2) If she ___ (practise) every day, she would have won the competition.', NULL, NULL, '{"A": "gets / had practised", "B": "get / would have practised", "C": "get / will have practised", "D": "getting / had practised", "E": "get / had practised"}'::jsonb, 'E', NULL, '(1) get — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) had practised — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6526, 84, 'g10-eng-cond-q1-26', 1, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I had had more time, I ___ (visit) my grandparents. (2) Unless you ___ (study) harder, you won''t pass the exam.', NULL, NULL, '{"A": "had visited / study", "B": "would have visited / study", "C": "would have visited / will study", "D": "will visit / study", "E": "would have visited / won''t study"}'::jsonb, 'B', NULL, '(1) would have visited — III tip şərt: If + Past Perfect, would have + V3 (2) study — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (6527, 84, 'g10-eng-cond-q1-27', 1, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she had practised every day, she ___ (win) the competition. (2) Should you need any help, ___ me. (call)', NULL, NULL, '{"A": "would have won / call", "B": "will win / call", "C": "would have won / to call", "D": "will have won / call", "E": "would have won / called"}'::jsonb, 'A', NULL, '(1) would have won — III tip şərt: If + Past Perfect, would have + V3 (2) call — İnversiya: Should you need = If you need; əmr');
INSERT INTO public.questions VALUES (6528, 84, 'g10-eng-cond-q1-28', 1, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If he ___ (check) the figures, he would find the mistake. (2) If he ___ (check) the figures, he will find the mistake.', NULL, NULL, '{"A": "checked / checks", "B": "checks / checks", "C": "checked / had checked", "D": "checked / will check", "E": "checked / checked"}'::jsonb, 'A', NULL, '(1) checked — II tip şərt: If + Past Simple, would + V1 (2) checks — I tip şərt: If + Present Simple, will + V1');
INSERT INTO public.questions VALUES (6529, 84, 'g10-eng-cond-q1-29', 1, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If they ___ (save) enough money, they would buy a new house. (2) If she had studied medicine, she ___ a doctor now. (be)', NULL, NULL, '{"A": "saved / will be", "B": "saved / had been", "C": "saved / would be", "D": "saved / is", "E": "have saved / would be"}'::jsonb, 'C', NULL, '(1) saved — II tip şərt: If + Past Simple, would + V1 (2) would be — Qarışıq şərt: keçmiş şərt, indiki nəticə');
INSERT INTO public.questions VALUES (6530, 84, 'g10-eng-cond-q1-30', 1, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you mix red and blue, you ___ purple. (2) If you had studied harder, you ___ (pass) the exam.', NULL, NULL, '{"A": "get / will have passed", "B": "getting / would have passed", "C": "get / would have passed", "D": "got to / would have passed", "E": "get / had passed"}'::jsonb, 'C', NULL, '(1) get — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) would have passed — III tip şərt: If + Past Perfect, would have + V3');
