INSERT INTO public.questions VALUES (6537, 84, 'g10-eng-cond-q2-07', 2, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If they have saved enough money, they would buy a new house.", "B": "If she practises every day, she would win the competition.", "C": "If he had checked the figures, he will find the mistake.", "D": "She wishes she had gone to the party last night.", "E": "I wish I know the answer to this question."}'::jsonb, 'D', NULL, 'Correct: «She wishes she had gone to the party last night.» — wish + Past Perfect: keçmişə təəssüf. The other sentences each contain an error.');
