INSERT INTO public.questions VALUES (6556, 84, 'g10-eng-cond-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If only I ___ more carefully yesterday! (drive) (2) If she ___ (practise) every day, she would win the competition.', NULL, NULL, '{"A": "have driven / practised", "B": "had driven / practised", "C": "had driven / has practised", "D": "had driven / practises", "E": "had driven / will practise"}'::jsonb, 'B', NULL, '(1) had driven — If only + Past Perfect: keçmişə təəssüf (2) practised — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (6557, 84, 'g10-eng-cond-q2-27', 2, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I ___ (have) more time, I would have visited my grandparents. (2) If you heat ice, it ___.', NULL, NULL, '{"A": "had had / melting", "B": "will have had / melts", "C": "have had / melts", "D": "had had / is melt", "E": "had had / melts"}'::jsonb, 'E', NULL, '(1) had had — III tip şərt: şərt hissəsində Past Perfect (2) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple');
INSERT INTO public.questions VALUES (6558, 84, 'g10-eng-cond-q2-28', 2, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I ___ (have) more time, I will visit my grandparents. (2) If they ___ (save) enough money, they would have bought a new house.', NULL, NULL, '{"A": "had / had saved", "B": "have / had saved", "C": "have / will have saved", "D": "had had / had saved", "E": "will have / had saved"}'::jsonb, 'B', NULL, '(1) have — I tip şərt: If + Present Simple, will + V1 (2) had saved — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6559, 84, 'g10-eng-cond-q2-29', 2, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish I ___ the answer to this question. (know) (2) Unless they ___ (save) enough money, they won''t buy a new house.', NULL, NULL, '{"A": "knowing / save", "B": "knew / would save", "C": "will know / save", "D": "knew / save", "E": "knew / won''t save"}'::jsonb, 'D', NULL, '(1) knew — wish + Past Simple: indiki vəziyyətə təəssüf (2) save — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (6560, 84, 'g10-eng-cond-q2-30', 2, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I wish I am taller.", "B": "If I had had more time, I would have visited my grandparents.", "C": "If I have had more time, I would have visited my grandparents.", "D": "If they will have saved enough money, they would have bought a new house.", "E": "If they had saved enough money, they had bought a new house."}'::jsonb, 'B', NULL, 'Correct: «If I had had more time, I would have visited my grandparents.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6561, 84, 'g10-eng-cond-q3-01', 3, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If plants don''t get water, they ___. (2) If you ___ (study) harder, you would have passed the exam.', NULL, NULL, '{"A": "die / had studied", "B": "dying / had studied", "C": "die / will have studied", "D": "are die / had studied", "E": "dies / had studied"}'::jsonb, 'A', NULL, '(1) die — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) had studied — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6562, 84, 'g10-eng-cond-q3-02', 3, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless they ___ (save) enough money, they won''t buy a new house. (2) If she ___ (practise) every day, she would have won the competition.', NULL, NULL, '{"A": "save / will have practised", "B": "save / have practised", "C": "save / had practised", "D": "save / would have practised", "E": "will save / had practised"}'::jsonb, 'C', NULL, '(1) save — Unless = if not; zaman/şərt hissəsində Present Simple (2) had practised — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6563, 84, 'g10-eng-cond-q3-03', 3, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she had practised every day, she would have won the competition.", "B": "If she had studied medicine, she is a doctor now.", "C": "If we left now, we will catch the train.", "D": "She wishes she goes to the party last night.", "E": "If plants don''t get water, they dies."}'::jsonb, 'A', NULL, 'Correct: «If she had practised every day, she would have won the competition.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6564, 84, 'g10-eng-cond-q3-04', 3, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he will check the figures, he would find the mistake.", "B": "If he have checked the figures, he would have found the mistake.", "C": "Should you need any help, call me.", "D": "If you will study harder, you would pass the exam.", "E": "If plants don''t get water, they are die."}'::jsonb, 'C', NULL, 'Correct: «Should you need any help, call me.» — İnversiya: Should you need = If you need; əmr. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6565, 84, 'g10-eng-cond-q3-05', 3, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you ___ (study) harder, you would pass the exam. (2) If they ___ (save) enough money, they would have bought a new house.', NULL, NULL, '{"A": "studied / will have saved", "B": "studied / would have saved", "C": "studied / have saved", "D": "studied / had saved", "E": "will study / had saved"}'::jsonb, 'D', NULL, '(1) studied — II tip şərt: If + Past Simple, would + V1 (2) had saved — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6566, 84, 'g10-eng-cond-q3-06', 3, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless they ___ (save) enough money, they won''t buy a new house. (2) If you heat ice, it ___.', NULL, NULL, '{"A": "save / melting", "B": "save / is melt", "C": "save / melts", "D": "would save / melts", "E": "save / will melted"}'::jsonb, 'C', NULL, '(1) save — Unless = if not; zaman/şərt hissəsində Present Simple (2) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple');
INSERT INTO public.questions VALUES (6567, 84, 'g10-eng-cond-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she ___ (practise) every day, she will win the competition. (2) If we had left now, we ___ (catch) the train.', NULL, NULL, '{"A": "practises / had caught", "B": "had practised / would have caught", "C": "practises / will catch", "D": "will practise / would have caught", "E": "practises / would have caught"}'::jsonb, 'E', NULL, '(1) practises — I tip şərt: If + Present Simple, will + V1 (2) would have caught — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (6568, 84, 'g10-eng-cond-q3-08', 3, 8, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) If he ___ (check) the figures, he will find the mistake. (2) If they ___ (save) enough money, they will buy a new house.', NULL, NULL, '{"A": "had checked / save", "B": "checks / save", "C": "checks / had saved", "D": "checks / will save", "E": "checks / saved"}'::jsonb, 'B', NULL, '(1) checks — I tip şərt: If + Present Simple, will + V1 (2) save — I tip şərt: If + Present Simple, will + V1');
INSERT INTO public.questions VALUES (6569, 84, 'g10-eng-cond-q3-09', 3, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish it ___ raining. It has been raining for days. (stop) (2) If she ___ (practise) every day, she would win the competition.', NULL, NULL, '{"A": "would stop / practises", "B": "would stop / practised", "C": "would stop / will practise", "D": "stops / practised", "E": "stopped to / practised"}'::jsonb, 'B', NULL, '(1) would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu (2) practised — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (6570, 84, 'g10-eng-cond-q3-10', 3, 10, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I have more time, I will visit my grandparents.", "B": "If she had practised every day, she will have won the competition.", "C": "If you had studied harder, you will have passed the exam.", "D": "If we had left now, we had caught the train.", "E": "If I have more time, I would visit my grandparents."}'::jsonb, 'A', NULL, 'Correct: «If I have more time, I will visit my grandparents.» — I tip şərt: If + Present Simple, will + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6571, 84, 'g10-eng-cond-q3-11', 3, 11, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have more time, I will visit my grandparents.", "B": "If water reaches 100°C, it boils.", "C": "If she have practised every day, she would have won the competition.", "D": "If we will have left now, we would have caught the train.", "E": "If he will check the figures, he will find the mistake."}'::jsonb, 'B', NULL, 'Correct: «If water reaches 100°C, it boils.» — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6572, 84, 'g10-eng-cond-q3-12', 3, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she will have practised every day, she would have won the competition.", "B": "If they saved enough money, they will buy a new house.", "C": "If I wasn''t been afraid of flying, I would have visited you last summer.", "D": "If they had saved enough money, they would have bought a new house.", "E": "If she had practised every day, she will have won the competition."}'::jsonb, 'D', NULL, 'Correct: «If they had saved enough money, they would have bought a new house.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6573, 84, 'g10-eng-cond-q3-13', 3, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Had I known about the meeting, I will attend it.", "B": "If you heat ice, it melting.", "C": "If plants don''t get water, they are die.", "D": "If you had studied harder, you will pass the exam.", "E": "If they had saved enough money, they would have bought a new house."}'::jsonb, 'E', NULL, 'Correct: «If they had saved enough money, they would have bought a new house.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6574, 84, 'g10-eng-cond-q3-14', 3, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have more time, I will visit my grandparents.", "B": "I wish I will know the answer to this question.", "C": "If they would have saved enough money, they would have bought a new house.", "D": "Unless they save enough money, they won''t buy a new house.", "E": "If I wasn''t been afraid of flying, I would have visited you last summer."}'::jsonb, 'D', NULL, 'Correct: «Unless they save enough money, they won''t buy a new house.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6575, 84, 'g10-eng-cond-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he will check the figures, he would find the mistake.", "B": "If you would have studied harder, you would have passed the exam.", "C": "If only I drive more carefully yesterday!", "D": "If you study harder, you would pass the exam.", "E": "If they had saved enough money, they would have bought a new house."}'::jsonb, 'E', NULL, 'Correct: «If they had saved enough money, they would have bought a new house.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6576, 84, 'g10-eng-cond-q3-16', 3, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless they won''t save enough money, they won''t buy a new house.", "B": "If he had checked the figures, he had found the mistake.", "C": "If you have studied harder, you would pass the exam.", "D": "If we will have left now, we would have caught the train.", "E": "Should you need any help, call me."}'::jsonb, 'E', NULL, 'Correct: «Should you need any help, call me.» — İnversiya: Should you need = If you need; əmr. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6577, 84, 'g10-eng-cond-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she ___ (practise) every day, she will win the competition. (2) Should you need any help, ___ me. (call)', NULL, NULL, '{"A": "practises / call", "B": "had practised / call", "C": "practised / call", "D": "practises / calling", "E": "practises / called"}'::jsonb, 'A', NULL, '(1) practises — I tip şərt: If + Present Simple, will + V1 (2) call — İnversiya: Should you need = If you need; əmr');
INSERT INTO public.questions VALUES (6578, 84, 'g10-eng-cond-q3-18', 3, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If he ___ (check) the figures, he would have found the mistake. (2) If they ___ (save) enough money, they would buy a new house.', NULL, NULL, '{"A": "had checked / have saved", "B": "would have checked / saved", "C": "had checked / will save", "D": "will have checked / saved", "E": "had checked / saved"}'::jsonb, 'E', NULL, '(1) had checked — III tip şərt: şərt hissəsində Past Perfect (2) saved — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (6579, 84, 'g10-eng-cond-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you heat ice, it melting.", "B": "If we leave now, we would catch the train.", "C": "If we would have left now, we would have caught the train.", "D": "If I had had more time, I would have visited my grandparents.", "E": "I wish it stopped to raining. It has been raining for days."}'::jsonb, 'D', NULL, 'Correct: «If I had had more time, I would have visited my grandparents.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6580, 84, 'g10-eng-cond-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she had practised every day, she will win the competition.", "B": "Had I known about the meeting, I had attended it.", "C": "If water reaches 100°C, it boil.", "D": "If we will leave now, we will catch the train.", "E": "Unless we leave now, we won''t catch the train."}'::jsonb, 'E', NULL, 'Correct: «Unless we leave now, we won''t catch the train.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6581, 84, 'g10-eng-cond-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you heat ice, it ___. (2) If I ___ (have) more time, I would have visited my grandparents.', NULL, NULL, '{"A": "will melted / had had", "B": "is melt / had had", "C": "melts / will have had", "D": "melting / had had", "E": "melts / had had"}'::jsonb, 'E', NULL, '(1) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) had had — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6582, 84, 'g10-eng-cond-q3-22', 3, 22, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If water reaches 100°C, it boils.", "B": "If we will have left now, we would have caught the train.", "C": "If I will have more time, I will visit my grandparents.", "D": "If you had studied harder, you will pass the exam.", "E": "Had I known about the meeting, I attended it."}'::jsonb, 'A', NULL, 'Correct: «If water reaches 100°C, it boils.» — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6583, 84, 'g10-eng-cond-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish I ___ taller. (be) (2) If they ___ (save) enough money, they would buy a new house.', NULL, NULL, '{"A": "will be / saved", "B": "am / saved", "C": "were / will save", "D": "were / save", "E": "were / saved"}'::jsonb, 'E', NULL, '(1) were — wish + were (bütün şəxslərdə) (2) saved — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (6584, 84, 'g10-eng-cond-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you heat ice, it ___. (2) If you had studied harder, you ___ (pass) the exam.', NULL, NULL, '{"A": "melting / would have passed", "B": "will melted / would have passed", "C": "melts / will have passed", "D": "melts / would have passed", "E": "is melt / would have passed"}'::jsonb, 'D', NULL, '(1) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) would have passed — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (6585, 84, 'g10-eng-cond-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you heat ice, it ___. (2) If she had practised every day, she ___ (win) the competition.', NULL, NULL, '{"A": "melting / would have won", "B": "melts / will win", "C": "melts / would have won", "D": "melts / had won", "E": "will melted / would have won"}'::jsonb, 'C', NULL, '(1) melts — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple (2) would have won — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (6586, 84, 'g10-eng-cond-q3-26', 3, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she have practised every day, she would have won the competition.", "B": "If water reaches 100°C, it is boil.", "C": "Had I known about the meeting, I would have attended it.", "D": "I wish I being taller.", "E": "If I will have more time, I would visit my grandparents."}'::jsonb, 'C', NULL, 'Correct: «Had I known about the meeting, I would have attended it.» — İnversiya: Had I known = If I had known. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6587, 84, 'g10-eng-cond-q3-27', 3, 27, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless he will check the figures, he won''t find the mistake.", "B": "If he checks the figures, he will find the mistake.", "C": "If I had had more time, I will visit my grandparents.", "D": "If she had practised every day, she will win the competition.", "E": "If plants don''t get water, they are die."}'::jsonb, 'B', NULL, 'Correct: «If he checks the figures, he will find the mistake.» — I tip şərt: If + Present Simple, will + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6588, 84, 'g10-eng-cond-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you ___ (study) harder, you would pass the exam. (2) Had I known about the meeting, I ___ it. (attend)', NULL, NULL, '{"A": "study / would have attended", "B": "studied / would have attended", "C": "studied / will attend", "D": "studied / attended", "E": "will study / would have attended"}'::jsonb, 'B', NULL, '(1) studied — II tip şərt: If + Past Simple, would + V1 (2) would have attended — İnversiya: Had I known = If I had known');
INSERT INTO public.questions VALUES (6589, 84, 'g10-eng-cond-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Should you need any help, ___ me. (call) (2) If she ___ (practise) every day, she would have won the competition.', NULL, NULL, '{"A": "call / will have practised", "B": "call / have practised", "C": "call / had practised", "D": "calling / had practised", "E": "to call / had practised"}'::jsonb, 'C', NULL, '(1) call — İnversiya: Should you need = If you need; əmr (2) had practised — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (6590, 84, 'g10-eng-cond-q3-30', 3, 30, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have more time, I would visit my grandparents.", "B": "She wishes she went to the party last night.", "C": "Unless you will study harder, you won''t pass the exam.", "D": "Unless we won''t leave now, we won''t catch the train.", "E": "If you heat ice, it melts."}'::jsonb, 'E', NULL, 'Correct: «If you heat ice, it melts.» — Sıfır tip şərt: ümumi həqiqət, hər iki hissədə Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6591, 85, 'g10-eng-passive-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The letters must ___ (send) before Friday. (2) The parcel ___ (deliver) at the moment.', NULL, NULL, '{"A": "be sent / is delivering", "B": "be sent / has been delivering", "C": "sent / is being delivered", "D": "be sent / is being delivered", "E": "been sent / is being delivered"}'::jsonb, 'D', NULL, '(1) be sent — Modal + be + V3 (2) is being delivered — Present Continuous Passive: is/are being + V3');
INSERT INTO public.questions VALUES (6592, 85, 'g10-eng-passive-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The bridge ___ (build) by the end of next week. (2) The bikes ___ (repair) since 2010.', NULL, NULL, '{"A": "has been built / have been repaired", "B": "will have been built / are repaired", "C": "will have been built / have been repaired", "D": "had been built / have been repaired", "E": "will have built / have been repaired"}'::jsonb, 'C', NULL, '(1) will have been built — Future Perfect Passive: will have been + V3 (2) have been repaired — Present Perfect Passive: has/have been + V3');
INSERT INTO public.questions VALUES (6593, 85, 'g10-eng-passive-q1-03', 1, 3, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The bikes are being repaired when the storm started.", "B": "The houses were being painted at the moment.", "C": "The thief is believed leaving the country last week.", "D": "He is said be the best player in the team.", "E": "The bridge was built in 2015."}'::jsonb, 'E', NULL, 'Correct: «The bridge was built in 2015.» — Past Simple Passive: was/were + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6594, 85, 'g10-eng-passive-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The parcel must being delivered before Friday.", "B": "The posters are designed in 2015.", "C": "The parcel is being delivered at the moment.", "D": "The houses have been painted by the end of next week.", "E": "The cars are sold since 2010."}'::jsonb, 'C', NULL, 'Correct: «The parcel is being delivered at the moment.» — Present Continuous Passive: is/are being + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6595, 85, 'g10-eng-passive-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I had my car ___ yesterday. (repair) (2) The contract ___ (sign) at the moment.', NULL, NULL, '{"A": "repairing / is being signed", "B": "repaired / has been signing", "C": "repaired / is being signed", "D": "repaired / was being signed", "E": "repair / is being signed"}'::jsonb, 'C', NULL, '(1) repaired — Causative: have + obyekt + V3 (2) is being signed — Present Continuous Passive: is/are being + V3');
