INSERT INTO public.questions VALUES (6735, 86, 'g10-eng-article-q2-25', 2, 25, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We have an breakfast at seven.", "B": "We went there by bus.", "C": "I visit my grandparents twice month.", "D": "A Netherlands is famous for its tulips.", "E": "He speaks an English fluently."}'::jsonb, 'B', NULL, 'Correct: «We went there by bus.» — by + nəqliyyat vasitəsi: artikl yoxdur. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6736, 86, 'g10-eng-article-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) She is ___ only person who knows the truth. (2) We have ___ breakfast at seven.', NULL, NULL, '{"A": "an / —", "B": "the / an", "C": "the / —", "D": "a / —", "E": "the / a"}'::jsonb, 'C', NULL, '(1) the — «only» ilə the (2) — — Yemək adları ilə (breakfast, lunch) artikl işlənmir');
INSERT INTO public.questions VALUES (6737, 86, 'g10-eng-article-q2-27', 2, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) What ___ beautiful day it is! (2) Germany is ___ European country.', NULL, NULL, '{"A": "the / a", "B": "a / a", "C": "— / a", "D": "the / an", "E": "a / an"}'::jsonb, 'B', NULL, '(1) a — What a + saylan tək isim (nida) (2) a — «European» [ju] səsi ilə başlayır → a');
INSERT INTO public.questions VALUES (6738, 86, 'g10-eng-article-q2-28', 2, 28, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He became engineer after graduating.", "B": "We sailed across a Pacific Ocean.", "C": "What a lovely weather we are having!", "D": "I''d like an glass of water, please.", "E": "They climbed the Alps last summer."}'::jsonb, 'E', NULL, 'Correct: «They climbed the Alps last summer.» — Dağ silsilələri ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6739, 86, 'g10-eng-article-q2-29', 2, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A Mount Everest is the highest mountain in the world.", "B": "She is a only person who knows the truth.", "C": "They play a football every Saturday.", "D": "The rich should help the poor.", "E": "A Nile is the longest river in Africa."}'::jsonb, 'D', NULL, 'Correct: «The rich should help the poor.» — the + sifət = sosial qrup (the rich, the poor). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6740, 86, 'g10-eng-article-q2-30', 2, 30, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We went there by bus.", "B": "She is an only person who knows the truth.", "C": "A Caspian Sea is the largest lake in the world.", "D": "He was born in a 1990s.", "E": "What the beautiful day it is!"}'::jsonb, 'A', NULL, 'Correct: «We went there by bus.» — by + nəqliyyat vasitəsi: artikl yoxdur. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6741, 86, 'g10-eng-article-q3-01', 3, 1, 'medium', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) We went there by ___ bus. (2) We waited for ___ hour.', NULL, NULL, '{"A": "an / an", "B": "a / a", "C": "— / an", "D": "a / an", "E": "— / a"}'::jsonb, 'C', NULL, '(1) — — by + nəqliyyat vasitəsi: artikl yoxdur (2) an — «hour»da h oxunmur → an');
INSERT INTO public.questions VALUES (6742, 86, 'g10-eng-article-q3-02', 3, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) What ___ lovely weather we are having! (2) She has ___ MBA from a famous school.', NULL, NULL, '{"A": "the / a", "B": "— / an", "C": "— / a", "D": "a / an", "E": "the / an"}'::jsonb, 'B', NULL, '(1) — — What + saylanmayan isim (weather) — artiklsiz (2) an — «MBA» [em] səsi ilə başlayır → an');
INSERT INTO public.questions VALUES (6743, 86, 'g10-eng-article-q3-03', 3, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Lake Baikal is very deep.", "B": "She goes to a bed at ten o''clock.", "C": "We have an breakfast at seven.", "D": "They climbed Alps last summer.", "E": "He has an unique talent for music."}'::jsonb, 'A', NULL, 'Correct: «Lake Baikal is very deep.» — «Lake + ad» formasında artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6744, 86, 'g10-eng-article-q3-04', 3, 4, 'medium', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) This is ___ most interesting book I have ever read. (2) He speaks ___ English fluently.', NULL, NULL, '{"A": "an / —", "B": "the / —", "C": "the / the", "D": "the / an", "E": "— / —"}'::jsonb, 'B', NULL, '(1) the — Üstünlük dərəcəsi ilə the (2) — — Dil adları ilə artikl işlənmir');
INSERT INTO public.questions VALUES (6745, 86, 'g10-eng-article-q3-05', 3, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He was born in ___ 1990s. (2) He became ___ engineer after graduating.', NULL, NULL, '{"A": "a / an", "B": "the / —", "C": "the / an", "D": "— / an", "E": "the / a"}'::jsonb, 'C', NULL, '(1) the — Onilliklər: in the 1990s (2) an — Peşə bildirəndə: an engineer');
INSERT INTO public.questions VALUES (6746, 86, 'g10-eng-article-q3-06', 3, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Netherlands is famous for its tulips. (2) ___ Lake Baikal is very deep.', NULL, NULL, '{"A": "— / —", "B": "The / The", "C": "The / A", "D": "A / —", "E": "The / —"}'::jsonb, 'E', NULL, '(1) The — Cəm formalı ölkə adları ilə the (2) — — «Lake + ad» formasında artikl işlənmir');
INSERT INTO public.questions VALUES (6747, 86, 'g10-eng-article-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) Germany is ___ European country. (2) We sailed across ___ Pacific Ocean.', NULL, NULL, '{"A": "a / a", "B": "an / the", "C": "an / —", "D": "a / the", "E": "a / —"}'::jsonb, 'D', NULL, '(1) a — «European» [ju] səsi ilə başlayır → a (2) the — Okean adları ilə the');
INSERT INTO public.questions VALUES (6748, 86, 'g10-eng-article-q3-08', 3, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) I visit my grandparents twice ___ month. (2) We went there by ___ bus.', NULL, NULL, '{"A": "a / —", "B": "a / a", "C": "a / an", "D": "— / —", "E": "the / —"}'::jsonb, 'A', NULL, '(1) a — twice a month — «hər» mənasında a (2) — — by + nəqliyyat vasitəsi: artikl yoxdur');
INSERT INTO public.questions VALUES (6749, 86, 'g10-eng-article-q3-09', 3, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I''d like an glass of water, please.", "B": "A Lake Baikal is very deep.", "C": "She lives in United Kingdom.", "D": "I bought an one-way ticket.", "E": "She is the only person who knows the truth."}'::jsonb, 'E', NULL, 'Correct: «She is the only person who knows the truth.» — «only» ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6750, 86, 'g10-eng-article-q3-10', 3, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) I bought ___ one-way ticket. (2) ___ Lake Baikal is very deep.', NULL, NULL, '{"A": "a / —", "B": "a / A", "C": "an / A", "D": "an / —", "E": "a / The"}'::jsonb, 'A', NULL, '(1) a — «one» [w] səsi ilə başlayır → a (2) — — «Lake + ad» formasında artikl işlənmir');
INSERT INTO public.questions VALUES (6751, 86, 'g10-eng-article-q3-11', 3, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My cousin lives in an Azerbaijan.", "B": "We have a breakfast at seven.", "C": "The rich should help the poor.", "D": "A history is my favourite subject.", "E": "He became a engineer after graduating."}'::jsonb, 'C', NULL, 'Correct: «The rich should help the poor.» — the + sifət = sosial qrup (the rich, the poor). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6752, 86, 'g10-eng-article-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) We waited for ___ hour. (2) She is ___ only person who knows the truth.', NULL, NULL, '{"A": "an / a", "B": "a / the", "C": "an / the", "D": "a / an", "E": "an / an"}'::jsonb, 'C', NULL, '(1) an — «hour»da h oxunmur → an (2) the — «only» ilə the');
INSERT INTO public.questions VALUES (6753, 86, 'g10-eng-article-q3-13', 3, 13, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We have breakfast at seven.", "B": "What the beautiful day it is!", "C": "Germany is an European country.", "D": "I''d like glass of water, please.", "E": "She is a honest person."}'::jsonb, 'A', NULL, 'Correct: «We have breakfast at seven.» — Yemək adları ilə (breakfast, lunch) artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6754, 86, 'g10-eng-article-q3-14', 3, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A Netherlands is famous for its tulips.", "B": "She goes to an bed at ten o''clock.", "C": "It''s a honour to meet you.", "D": "I bought an one-way ticket.", "E": "She is the only person who knows the truth."}'::jsonb, 'E', NULL, 'Correct: «She is the only person who knows the truth.» — «only» ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6755, 86, 'g10-eng-article-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We sailed across Pacific Ocean.", "B": "Sun rises in the east.", "C": "The Mount Everest is the highest mountain in the world.", "D": "What a lovely weather we are having!", "E": "The Netherlands is famous for its tulips."}'::jsonb, 'E', NULL, 'Correct: «The Netherlands is famous for its tulips.» — Cəm formalı ölkə adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6756, 86, 'g10-eng-article-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He was born in ___ 1990s. (2) We have ___ breakfast at seven.', NULL, NULL, '{"A": "the / an", "B": "the / —", "C": "the / a", "D": "— / —", "E": "a / —"}'::jsonb, 'B', NULL, '(1) the — Onilliklər: in the 1990s (2) — — Yemək adları ilə (breakfast, lunch) artikl işlənmir');
INSERT INTO public.questions VALUES (6757, 86, 'g10-eng-article-q3-17', 3, 17, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She goes to an bed at ten o''clock.", "B": "The Nile is the longest river in Africa.", "C": "She is a honest person.", "D": "She is an only person who knows the truth.", "E": "The Mount Everest is the highest mountain in the world."}'::jsonb, 'B', NULL, 'Correct: «The Nile is the longest river in Africa.» — Çay adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6758, 86, 'g10-eng-article-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The English language has many irregular verbs.", "B": "We sailed across a Pacific Ocean.", "C": "He was elected an president of the club.", "D": "She lives in United Kingdom.", "E": "The Lake Baikal is very deep."}'::jsonb, 'A', NULL, 'Correct: «The English language has many irregular verbs.» — «the English language» — language sözü ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6759, 86, 'g10-eng-article-q3-19', 3, 19, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The Mount Everest is the highest mountain in the world.", "B": "We waited for a hour.", "C": "The sun rises in the east.", "D": "My cousin lives in an Azerbaijan.", "E": "It was a unusual decision."}'::jsonb, 'C', NULL, 'Correct: «The sun rises in the east.» — Yeganə obyektlər: the sun, the moon. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6760, 86, 'g10-eng-article-q3-20', 3, 20, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We sailed across a Pacific Ocean.", "B": "I visit my grandparents twice the month.", "C": "My cousin lives in an Azerbaijan.", "D": "He became a engineer after graduating.", "E": "They play football every Saturday."}'::jsonb, 'E', NULL, 'Correct: «They play football every Saturday.» — İdman növləri ilə artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6761, 86, 'g10-eng-article-q3-21', 3, 21, 'medium', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He works at ___ university in Baku. (2) This is ___ most interesting book I have ever read.', NULL, NULL, '{"A": "a / —", "B": "an / the", "C": "a / an", "D": "a / the", "E": "an / an"}'::jsonb, 'D', NULL, '(1) a — «university» [ju] səsi ilə başlayır → a (2) the — Üstünlük dərəcəsi ilə the');
INSERT INTO public.questions VALUES (6762, 86, 'g10-eng-article-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A Caspian Sea is the largest lake in the world.", "B": "He became engineer after graduating.", "C": "The Mount Everest is the highest mountain in the world.", "D": "She lives in the United Kingdom.", "E": "She has a MBA from a famous school."}'::jsonb, 'D', NULL, 'Correct: «She lives in the United Kingdom.» — «Kingdom, States, Republic» olan ölkə adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6763, 86, 'g10-eng-article-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ English language has many irregular verbs. (2) She is ___ honest person.', NULL, NULL, '{"A": "The / an", "B": "— / an", "C": "An / an", "D": "The / a", "E": "— / a"}'::jsonb, 'A', NULL, '(1) The — «the English language» — language sözü ilə the (2) an — «honest» saitlə tələffüz olunur (h oxunmur) → an');
INSERT INTO public.questions VALUES (6764, 86, 'g10-eng-article-q3-24', 3, 24, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "What the beautiful day it is!", "B": "They play football every Saturday.", "C": "A Netherlands is famous for its tulips.", "D": "He works at an university in Baku.", "E": "The history is my favourite subject."}'::jsonb, 'B', NULL, 'Correct: «They play football every Saturday.» — İdman növləri ilə artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6765, 86, 'g10-eng-article-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Caspian Sea is the largest lake in the world. (2) What ___ beautiful day it is!', NULL, NULL, '{"A": "The / —", "B": "A / a", "C": "The / the", "D": "The / a", "E": "— / a"}'::jsonb, 'D', NULL, '(1) The — Dəniz adları ilə the (2) a — What a + saylan tək isim (nida)');
INSERT INTO public.questions VALUES (6766, 86, 'g10-eng-article-q3-26', 3, 26, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "An English language has many irregular verbs.", "B": "We sailed across a Pacific Ocean.", "C": "She goes to a bed at ten o''clock.", "D": "We waited for an hour.", "E": "He has an unique talent for music."}'::jsonb, 'D', NULL, 'Correct: «We waited for an hour.» — «hour»da h oxunmur → an. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6767, 86, 'g10-eng-article-q3-27', 3, 27, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He was elected an president of the club.", "B": "This is an most interesting book I have ever read.", "C": "He speaks English fluently.", "D": "She has a MBA from a famous school.", "E": "I visit my grandparents twice the month."}'::jsonb, 'C', NULL, 'Correct: «He speaks English fluently.» — Dil adları ilə artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6768, 86, 'g10-eng-article-q3-28', 3, 28, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I''d like an glass of water, please.", "B": "We sailed across the Pacific Ocean.", "C": "I bought an one-way ticket.", "D": "She lives in United Kingdom.", "E": "A Lake Baikal is very deep."}'::jsonb, 'B', NULL, 'Correct: «We sailed across the Pacific Ocean.» — Okean adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6769, 86, 'g10-eng-article-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Lake Baikal is very deep. (2) ___ Nile is the longest river in Africa.', NULL, NULL, '{"A": "— / —", "B": "— / The", "C": "— / A", "D": "A / The", "E": "The / The"}'::jsonb, 'B', NULL, '(1) — — «Lake + ad» formasında artikl işlənmir (2) The — Çay adları ilə the');
INSERT INTO public.questions VALUES (6770, 86, 'g10-eng-article-q3-30', 3, 30, 'medium', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) She goes to ___ bed at ten o''clock. (2) We went there by ___ bus.', NULL, NULL, '{"A": "— / an", "B": "— / —", "C": "a / —", "D": "— / a", "E": "an / —"}'::jsonb, 'B', NULL, '(1) — — go to bed — sabit ifadə, artiklsiz (2) — — by + nəqliyyat vasitəsi: artikl yoxdur');
INSERT INTO public.questions VALUES (6771, 87, 'g10-eng-quant-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought several furniture for the new flat.", "B": "There''s hardly few sugar left.", "C": "All the children enjoyed the trip.", "D": "He hardly has many free time these days.", "E": "How many luggage do you have?"}'::jsonb, 'C', NULL, 'Correct: «All the children enjoyed the trip.» — all (of) the + cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6772, 87, 'g10-eng-quant-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I have few money, so I can buy you a coffee.", "B": "It was so a long journey that we were exhausted.", "C": "We bought some furniture for the new flat.", "D": "We had a little problems with the new software.", "E": "Plenty many volunteers came to help."}'::jsonb, 'C', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6773, 87, 'g10-eng-quant-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ number of tourists have complained about the hotel. (2) ___ of the students passed the test; it was too difficult.', NULL, NULL, '{"A": "— / None", "B": "A / Nobody", "C": "A / None", "D": "Much / None", "E": "The / None"}'::jsonb, 'C', NULL, '(1) A — a number of (bir neçə) + cəm feil (have) (2) None — none of + cəm (üç və daha çox): heç biri');
INSERT INTO public.questions VALUES (6774, 87, 'g10-eng-quant-q1-04', 1, 4, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both student in the class received a certificate.", "B": "We had a great deal problems with the new software.", "C": "You can take all road; both lead to the city centre.", "D": "There are some apples in the basket.", "E": "Are there a few of questions?"}'::jsonb, 'D', NULL, 'Correct: «There are some apples in the basket.» — Təsdiq cümləsində some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6775, 87, 'g10-eng-quant-q1-05', 1, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of the two answers is correct, so try again.", "B": "I have a little money, so I can buy you a coffee.", "C": "Several child needs love and attention.", "D": "She gave me many useful advice.", "E": "He hardly has some free time these days."}'::jsonb, 'B', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6776, 87, 'g10-eng-quant-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ student in the class received a certificate. (2) ___ of the two answers is correct, so try again.', NULL, NULL, '{"A": "Each / Neither", "B": "Both / Neither", "C": "Each / Both", "D": "All / Neither", "E": "Many / Neither"}'::jsonb, 'A', NULL, '(1) Each — each/every + saylan tək isim (2) Neither — neither of (ikisindən heç biri) + tək feil (is)');
INSERT INTO public.questions VALUES (6777, 87, 'g10-eng-quant-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "All of the two answers is correct, so try again.", "B": "We have little time; we must hurry.", "C": "All child needs love and attention.", "D": "It was very a long journey that we were exhausted.", "E": "We bought many furniture for the new flat."}'::jsonb, 'B', NULL, 'Correct: «We have little time; we must hurry.» — little + saylanmayan (mənfi məna). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6778, 87, 'g10-eng-quant-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We have a few time; we must hurry.", "B": "He hardly has many free time these days.", "C": "Both child needs love and attention.", "D": "We bought some furniture for the new flat.", "E": "Any of the students passed the test; it was too difficult."}'::jsonb, 'D', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6779, 87, 'g10-eng-quant-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the two answers is correct, so try again. (2) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "Neither / Some", "B": "All / One", "C": "Neither / One", "D": "Neither / Both", "E": "Both / One"}'::jsonb, 'C', NULL, '(1) Neither — neither of (ikisindən heç biri) + tək feil (is) (2) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (6780, 87, 'g10-eng-quant-q1-10', 1, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ child needs love and attention. (2) I''ve got ___ homework to do tonight.', NULL, NULL, '{"A": "Every / many", "B": "Every / a lot of", "C": "All / a lot of", "D": "Both / a lot of", "E": "Every / several"}'::jsonb, 'B', NULL, '(1) Every — every + tək isim (2) a lot of — homework saylanmayandır → a lot of / much');
INSERT INTO public.questions VALUES (6781, 87, 'g10-eng-quant-q1-11', 1, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) We have ___ time; we must hurry. (2) Are there ___ questions?', NULL, NULL, '{"A": "little / much", "B": "little / any", "C": "a few / any", "D": "little / a few of", "E": "little / a little"}'::jsonb, 'B', NULL, '(1) little — little + saylanmayan (mənfi məna) (2) any — Sual cümləsində any');
INSERT INTO public.questions VALUES (6782, 87, 'g10-eng-quant-q1-12', 1, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every of my parents are doctors.", "B": "I have many money, so I can buy you a coffee.", "C": "The number of tourists has increased this year.", "D": "The number of tourists have complained about the hotel.", "E": "All child needs love and attention."}'::jsonb, 'C', NULL, 'Correct: «The number of tourists has increased this year.» — the number of + tək feil (has). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6783, 87, 'g10-eng-quant-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of the cakes is mine; take the other one.", "B": "How a lot luggage do you have?", "C": "I don''t have much information about this topic.", "D": "She has much friends, so she often feels lonely.", "E": "We have few time; we must hurry."}'::jsonb, 'C', NULL, 'Correct: «I don''t have much information about this topic.» — information saylanmayandır → much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6784, 87, 'g10-eng-quant-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "All of the two answers is correct, so try again.", "B": "He hardly has any free time these days.", "C": "There were so much people at the concert that we couldn''t find a seat.", "D": "Any of the students passed the test; it was too difficult.", "E": "All of the cakes is mine; take the other one."}'::jsonb, 'B', NULL, 'Correct: «He hardly has any free time these days.» — hardly (inkar mənalı) + any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6785, 87, 'g10-eng-quant-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the cakes is mine; take the other one. (2) Plenty ___ volunteers came to help.', NULL, NULL, '{"A": "Both / of", "B": "All / of", "C": "One / of", "D": "One / —", "E": "One / much"}'::jsonb, 'C', NULL, '(1) One — one of + cəm isim + tək feil (2) of — plenty of + isim');
INSERT INTO public.questions VALUES (6786, 87, 'g10-eng-quant-q1-16', 1, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Every of my parents are doctors.", "B": "Plenty of volunteers came to help.", "C": "There isn''t few milk left in the fridge.", "D": "You can take both road; both lead to the city centre.", "E": "There''s hardly many sugar left."}'::jsonb, 'B', NULL, 'Correct: «Plenty of volunteers came to help.» — plenty of + isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6787, 87, 'g10-eng-quant-q1-17', 1, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Are there ___ questions? (2) She has ___ friends, so she often feels lonely.', NULL, NULL, '{"A": "much / few", "B": "a few of / few", "C": "a little / few", "D": "any / little", "E": "any / few"}'::jsonb, 'E', NULL, '(1) any — Sual cümləsində any (2) few — few + saylan (mənfi məna: az, demək olar ki, yox)');
INSERT INTO public.questions VALUES (6788, 87, 'g10-eng-quant-q1-18', 1, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A number of tourists have complained about the hotel.", "B": "There were such many people at the concert that we couldn''t find a seat.", "C": "I have many money, so I can buy you a coffee.", "D": "You can take both road; both lead to the city centre.", "E": "Both of the two answers is correct, so try again."}'::jsonb, 'A', NULL, 'Correct: «A number of tourists have complained about the hotel.» — a number of (bir neçə) + cəm feil (have). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6789, 87, 'g10-eng-quant-q1-19', 1, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ student in the class received a certificate. (2) You can take ___ road; both lead to the city centre.', NULL, NULL, '{"A": "Each / all", "B": "Both / either", "C": "Each / both", "D": "Many / either", "E": "Each / either"}'::jsonb, 'E', NULL, '(1) Each — each/every + saylan tək isim (2) either — either + tək isim: ikisindən hər hansı biri');
INSERT INTO public.questions VALUES (6790, 87, 'g10-eng-quant-q1-20', 1, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Are there much questions?", "B": "I have few money, so I can buy you a coffee.", "C": "We have many time; we must hurry.", "D": "Both of my parents are doctors.", "E": "There''s hardly many sugar left."}'::jsonb, 'D', NULL, 'Correct: «Both of my parents are doctors.» — both of + cəm, cəm feil (are). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6791, 87, 'g10-eng-quant-q1-21', 1, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) How ___ students are there in your class? (2) ___ of my parents are doctors.', NULL, NULL, '{"A": "a little / Both", "B": "little / Both", "C": "much / Both", "D": "many / Much", "E": "many / Both"}'::jsonb, 'E', NULL, '(1) many — many + saylan cəm isim (2) Both — both of + cəm, cəm feil (are)');
INSERT INTO public.questions VALUES (6792, 87, 'g10-eng-quant-q1-22', 1, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) We have ___ time; we must hurry. (2) Only ___ students came to the lecture, so it was cancelled.', NULL, NULL, '{"A": "a few / a few", "B": "many / a few", "C": "little / a few", "D": "little / little", "E": "few / a few"}'::jsonb, 'C', NULL, '(1) little — little + saylanmayan (mənfi məna) (2) a few — only a few + saylan cəm');
INSERT INTO public.questions VALUES (6793, 87, 'g10-eng-quant-q1-23', 1, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "All child needs love and attention.", "B": "There''s hardly any sugar left.", "C": "Only little students came to the lecture, so it was cancelled.", "D": "I have few money, so I can buy you a coffee.", "E": "Much of my parents are doctors."}'::jsonb, 'B', NULL, 'Correct: «There''s hardly any sugar left.» — hardly any — demək olar ki, heç. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6794, 87, 'g10-eng-quant-q1-24', 1, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How little students are there in your class?", "B": "Several child needs love and attention.", "C": "All of the cakes is mine; take the other one.", "D": "I have many money, so I can buy you a coffee.", "E": "There were so many people at the concert that we couldn''t find a seat."}'::jsonb, 'E', NULL, 'Correct: «There were so many people at the concert that we couldn''t find a seat.» — so many + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6795, 87, 'g10-eng-quant-q1-25', 1, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Only ___ students came to the lecture, so it was cancelled. (2) He hardly has ___ free time these days.', NULL, NULL, '{"A": "a few / many", "B": "a few / some", "C": "much / any", "D": "a few / no", "E": "a few / any"}'::jsonb, 'E', NULL, '(1) a few — only a few + saylan cəm (2) any — hardly (inkar mənalı) + any');
INSERT INTO public.questions VALUES (6796, 87, 'g10-eng-quant-q1-26', 1, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How a lot luggage do you have?", "B": "We bought many furniture for the new flat.", "C": "She gave me many useful advice.", "D": "I''ve got a lot of homework to do tonight.", "E": "Nobody of the students passed the test; it was too difficult."}'::jsonb, 'D', NULL, 'Correct: «I''ve got a lot of homework to do tonight.» — homework saylanmayandır → a lot of / much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6797, 87, 'g10-eng-quant-q1-27', 1, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Plenty ___ volunteers came to help. (2) She has ___ friends, so she often feels lonely.', NULL, NULL, '{"A": "of / few", "B": "many / few", "C": "of / much", "D": "— / few", "E": "much / few"}'::jsonb, 'A', NULL, '(1) of — plenty of + isim (2) few — few + saylan (mənfi məna: az, demək olar ki, yox)');
INSERT INTO public.questions VALUES (6798, 87, 'g10-eng-quant-q1-28', 1, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) It was ___ a long journey that we were exhausted. (2) ___ of my parents are doctors.', NULL, NULL, '{"A": "such / Much", "B": "such / Every", "C": "very / Both", "D": "such / Both", "E": "too / Both"}'::jsonb, 'D', NULL, '(1) such — such + (a) + sifət + isim (2) Both — both of + cəm, cəm feil (are)');
INSERT INTO public.questions VALUES (6799, 87, 'g10-eng-quant-q1-29', 1, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There''s hardly ___ sugar left. (2) ___ number of tourists has increased this year.', NULL, NULL, '{"A": "any / Many", "B": "any / —", "C": "many / The", "D": "any / The", "E": "few / The"}'::jsonb, 'D', NULL, '(1) any — hardly any — demək olar ki, heç (2) The — the number of + tək feil (has)');
INSERT INTO public.questions VALUES (6800, 87, 'g10-eng-quant-q1-30', 1, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I''ve got ___ homework to do tonight. (2) ___ number of tourists have complained about the hotel.', NULL, NULL, '{"A": "a few / A", "B": "a lot of / —", "C": "many / A", "D": "a lot of / Much", "E": "a lot of / A"}'::jsonb, 'E', NULL, '(1) a lot of — homework saylanmayandır → a lot of / much (2) A — a number of (bir neçə) + cəm feil (have)');
INSERT INTO public.questions VALUES (6801, 87, 'g10-eng-quant-q2-01', 2, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I don''t have ___ information about this topic. (2) She gave me ___ useful advice.', NULL, NULL, '{"A": "much / an", "B": "much / some", "C": "much / a few", "D": "few / some", "E": "many / some"}'::jsonb, 'B', NULL, '(1) much — information saylanmayandır → much (2) some — advice saylanmayandır → some advice');
INSERT INTO public.questions VALUES (6802, 87, 'g10-eng-quant-q2-02', 2, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of my parents are doctors.", "B": "Only much students came to the lecture, so it was cancelled.", "C": "Any of the students passed the test; it was too difficult.", "D": "Each the children enjoyed the trip.", "E": "I have few money, so I can buy you a coffee."}'::jsonb, 'A', NULL, 'Correct: «Both of my parents are doctors.» — both of + cəm, cəm feil (are). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6803, 87, 'g10-eng-quant-q2-03', 2, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) We had ___ problems with the new software. (2) Plenty ___ volunteers came to help.', NULL, NULL, '{"A": "a little / of", "B": "much / of", "C": "several / —", "D": "several / of", "E": "several / many"}'::jsonb, 'D', NULL, '(1) several — several + saylan cəm (2) of — plenty of + isim');
INSERT INTO public.questions VALUES (6804, 87, 'g10-eng-quant-q2-04', 2, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought several furniture for the new flat.", "B": "I don''t have many information about this topic.", "C": "Plenty volunteers came to help.", "D": "I have a little money, so I can buy you a coffee.", "E": "She has little friends, so she often feels lonely."}'::jsonb, 'D', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6805, 87, 'g10-eng-quant-q2-05', 2, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We had much problems with the new software.", "B": "We bought several furniture for the new flat.", "C": "Both of my parents are doctors.", "D": "Each the children enjoyed the trip.", "E": "Both of the two answers is correct, so try again."}'::jsonb, 'C', NULL, 'Correct: «Both of my parents are doctors.» — both of + cəm, cəm feil (are). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6806, 87, 'g10-eng-quant-q2-06', 2, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) It was ___ a long journey that we were exhausted. (2) ___ of the two answers is correct, so try again.', NULL, NULL, '{"A": "very / Neither", "B": "such / All", "C": "such / Both", "D": "too / Neither", "E": "such / Neither"}'::jsonb, 'E', NULL, '(1) such — such + (a) + sifət + isim (2) Neither — neither of (ikisindən heç biri) + tək feil (is)');
INSERT INTO public.questions VALUES (6807, 87, 'g10-eng-quant-q2-07', 2, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Any of the students passed the test; it was too difficult.", "B": "Both of the cakes is mine; take the other one.", "C": "There were so many people at the concert that we couldn''t find a seat.", "D": "How a little students are there in your class?", "E": "Many student in the class received a certificate."}'::jsonb, 'C', NULL, 'Correct: «There were so many people at the concert that we couldn''t find a seat.» — so many + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6808, 87, 'g10-eng-quant-q2-08', 2, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Are there a few of questions?", "B": "It was too a long journey that we were exhausted.", "C": "I don''t have few information about this topic.", "D": "How many luggage do you have?", "E": "He hardly has any free time these days."}'::jsonb, 'E', NULL, 'Correct: «He hardly has any free time these days.» — hardly (inkar mənalı) + any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6809, 87, 'g10-eng-quant-q2-09', 2, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Nobody of the students passed the test; it was too difficult.", "B": "A number of tourists has increased this year.", "C": "I''ve got many homework to do tonight.", "D": "We have little time; we must hurry.", "E": "There isn''t a few milk left in the fridge."}'::jsonb, 'D', NULL, 'Correct: «We have little time; we must hurry.» — little + saylanmayan (mənfi məna). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6810, 87, 'g10-eng-quant-q2-10', 2, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Are there ___ questions? (2) I''ve got ___ homework to do tonight.', NULL, NULL, '{"A": "a little / a lot of", "B": "any / a few", "C": "a few of / a lot of", "D": "any / a lot of", "E": "much / a lot of"}'::jsonb, 'D', NULL, '(1) any — Sual cümləsində any (2) a lot of — homework saylanmayandır → a lot of / much');
INSERT INTO public.questions VALUES (6811, 87, 'g10-eng-quant-q2-11', 2, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Much number of tourists have complained about the hotel.", "B": "You can take either road; both lead to the city centre.", "C": "I''ve got a few homework to do tonight.", "D": "Only little students came to the lecture, so it was cancelled.", "E": "I don''t have many information about this topic."}'::jsonb, 'B', NULL, 'Correct: «You can take either road; both lead to the city centre.» — either + tək isim: ikisindən hər hansı biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6812, 87, 'g10-eng-quant-q2-12', 2, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Only a little students came to the lecture, so it was cancelled.", "B": "You can take both road; both lead to the city centre.", "C": "None of the students passed the test; it was too difficult.", "D": "Much number of tourists have complained about the hotel.", "E": "Both student in the class received a certificate."}'::jsonb, 'C', NULL, 'Correct: «None of the students passed the test; it was too difficult.» — none of + cəm (üç və daha çox): heç biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6813, 87, 'g10-eng-quant-q2-13', 2, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ child needs love and attention. (2) ___ luggage do you have?', NULL, NULL, '{"A": "Every / How many", "B": "Every / How a lot", "C": "Several / How much", "D": "Every / How few", "E": "Every / How much"}'::jsonb, 'E', NULL, '(1) Every — every + tək isim (2) How much — luggage saylanmayandır → how much');
INSERT INTO public.questions VALUES (6814, 87, 'g10-eng-quant-q2-14', 2, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He spends many deal of time reading.", "B": "I don''t have few information about this topic.", "C": "We bought several furniture for the new flat.", "D": "None of the students passed the test; it was too difficult.", "E": "Either the children enjoyed the trip."}'::jsonb, 'D', NULL, 'Correct: «None of the students passed the test; it was too difficult.» — none of + cəm (üç və daha çox): heç biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6815, 87, 'g10-eng-quant-q2-15', 2, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) He hardly has ___ free time these days. (2) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "many / One", "B": "any / Some", "C": "no / One", "D": "any / One", "E": "any / Both"}'::jsonb, 'D', NULL, '(1) any — hardly (inkar mənalı) + any (2) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (6816, 87, 'g10-eng-quant-q2-16', 2, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How much students are there in your class?", "B": "There''s hardly any sugar left.", "C": "All of the two answers is correct, so try again.", "D": "There were too much people at the concert that we couldn''t find a seat.", "E": "You can take all road; both lead to the city centre."}'::jsonb, 'B', NULL, 'Correct: «There''s hardly any sugar left.» — hardly any — demək olar ki, heç. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6817, 87, 'g10-eng-quant-q2-17', 2, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "You can take all road; both lead to the city centre.", "B": "How few luggage do you have?", "C": "There''s hardly some sugar left.", "D": "We had several problems with the new software.", "E": "She gave me an useful advice."}'::jsonb, 'D', NULL, 'Correct: «We had several problems with the new software.» — several + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6818, 87, 'g10-eng-quant-q2-18', 2, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) How ___ students are there in your class? (2) I don''t have ___ information about this topic.', NULL, NULL, '{"A": "many / few", "B": "a little / much", "C": "many / much", "D": "many / a few", "E": "much / much"}'::jsonb, 'C', NULL, '(1) many — many + saylan cəm isim (2) much — information saylanmayandır → much');
INSERT INTO public.questions VALUES (6819, 87, 'g10-eng-quant-q2-19', 2, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I don''t have ___ information about this topic. (2) He spends ___ deal of time reading.', NULL, NULL, '{"A": "few / a great", "B": "a few / a great", "C": "many / a great", "D": "much / a lot", "E": "much / a great"}'::jsonb, 'E', NULL, '(1) much — information saylanmayandır → much (2) a great — a great deal of + saylanmayan');
INSERT INTO public.questions VALUES (6820, 87, 'g10-eng-quant-q2-20', 2, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) He hardly has ___ free time these days.', NULL, NULL, '{"A": "How much / many", "B": "How much / some", "C": "How much / any", "D": "How few / any", "E": "How a lot / any"}'::jsonb, 'C', NULL, '(1) How much — luggage saylanmayandır → how much (2) any — hardly (inkar mənalı) + any');
INSERT INTO public.questions VALUES (6821, 87, 'g10-eng-quant-q2-21', 2, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of my parents are doctors. (2) ___ student in the class received a certificate.', NULL, NULL, '{"A": "Both / Many", "B": "Every / Each", "C": "Both / Each", "D": "Both / Both", "E": "Much / Each"}'::jsonb, 'C', NULL, '(1) Both — both of + cəm, cəm feil (are) (2) Each — each/every + saylan tək isim');
INSERT INTO public.questions VALUES (6822, 87, 'g10-eng-quant-q2-22', 2, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) He spends ___ deal of time reading.', NULL, NULL, '{"A": "How much / a large", "B": "How much / a lot", "C": "How few / a great", "D": "How a lot / a great", "E": "How much / a great"}'::jsonb, 'E', NULL, '(1) How much — luggage saylanmayandır → how much (2) a great — a great deal of + saylanmayan');
INSERT INTO public.questions VALUES (6823, 87, 'g10-eng-quant-q2-23', 2, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We have little time; we must hurry.", "B": "I don''t have many information about this topic.", "C": "How a lot luggage do you have?", "D": "Are there a little questions?", "E": "Much of my parents are doctors."}'::jsonb, 'A', NULL, 'Correct: «We have little time; we must hurry.» — little + saylanmayan (mənfi məna). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6824, 87, 'g10-eng-quant-q2-24', 2, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ student in the class received a certificate. (2) ___ of the students passed the test; it was too difficult.', NULL, NULL, '{"A": "Each / None", "B": "All / None", "C": "Each / Nobody", "D": "Both / None", "E": "Each / Any"}'::jsonb, 'A', NULL, '(1) Each — each/every + saylan tək isim (2) None — none of + cəm (üç və daha çox): heç biri');
INSERT INTO public.questions VALUES (6825, 87, 'g10-eng-quant-q2-25', 2, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ the children enjoyed the trip. (2) Are there ___ questions?', NULL, NULL, '{"A": "All / any", "B": "Either / any", "C": "Each / any", "D": "All / a few of", "E": "All / a little"}'::jsonb, 'A', NULL, '(1) All — all (of) the + cəm (2) any — Sual cümləsində any');
INSERT INTO public.questions VALUES (6826, 87, 'g10-eng-quant-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the cakes is mine; take the other one. (2) ___ child needs love and attention.', NULL, NULL, '{"A": "One / Both", "B": "Both / Every", "C": "Some / Every", "D": "All / Every", "E": "One / Every"}'::jsonb, 'E', NULL, '(1) One — one of + cəm isim + tək feil (2) Every — every + tək isim');
INSERT INTO public.questions VALUES (6827, 87, 'g10-eng-quant-q2-27', 2, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were too much people at the concert that we couldn''t find a seat.", "B": "Only little students came to the lecture, so it was cancelled.", "C": "None of the students passed the test; it was too difficult.", "D": "I''ve got many homework to do tonight.", "E": "It was so a long journey that we were exhausted."}'::jsonb, 'C', NULL, 'Correct: «None of the students passed the test; it was too difficult.» — none of + cəm (üç və daha çox): heç biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6828, 87, 'g10-eng-quant-q2-28', 2, 28, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How many students are there in your class?", "B": "All child needs love and attention.", "C": "No of the students passed the test; it was too difficult.", "D": "He spends many deal of time reading.", "E": "There are much apples in the basket."}'::jsonb, 'A', NULL, 'Correct: «How many students are there in your class?» — many + saylan cəm isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6829, 87, 'g10-eng-quant-q2-29', 2, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He hardly has some free time these days.", "B": "All of the cakes is mine; take the other one.", "C": "How much luggage do you have?", "D": "Number of tourists has increased this year.", "E": "Much number of tourists have complained about the hotel."}'::jsonb, 'C', NULL, 'Correct: «How much luggage do you have?» — luggage saylanmayandır → how much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6830, 87, 'g10-eng-quant-q2-30', 2, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the two answers is correct, so try again. (2) There are ___ apples in the basket.', NULL, NULL, '{"A": "Neither / some", "B": "Neither / any", "C": "Neither / much", "D": "All / some", "E": "Neither / a little"}'::jsonb, 'A', NULL, '(1) Neither — neither of (ikisindən heç biri) + tək feil (is) (2) some — Təsdiq cümləsində some');
INSERT INTO public.questions VALUES (6831, 87, 'g10-eng-quant-q3-01', 3, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He spends a great deal of time reading.", "B": "There are a little apples in the basket.", "C": "How a little students are there in your class?", "D": "Both student in the class received a certificate.", "E": "She gave me a few useful advice."}'::jsonb, 'A', NULL, 'Correct: «He spends a great deal of time reading.» — a great deal of + saylanmayan. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6832, 87, 'g10-eng-quant-q3-02', 3, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A number of tourists has increased this year.", "B": "Every the children enjoyed the trip.", "C": "She has a little friends, so she often feels lonely.", "D": "He hardly has some free time these days.", "E": "Only a few students came to the lecture, so it was cancelled."}'::jsonb, 'E', NULL, 'Correct: «Only a few students came to the lecture, so it was cancelled.» — only a few + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6833, 87, 'g10-eng-quant-q3-03', 3, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ number of tourists has increased this year. (2) There were ___ people at the concert that we couldn''t find a seat.', NULL, NULL, '{"A": "Many / so many", "B": "The / so much", "C": "The / so many", "D": "The / such many", "E": "The / too much"}'::jsonb, 'C', NULL, '(1) The — the number of + tək feil (has) (2) so many — so many + saylan cəm');
INSERT INTO public.questions VALUES (6834, 87, 'g10-eng-quant-q3-04', 3, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) ___ the children enjoyed the trip.', NULL, NULL, '{"A": "How few / All", "B": "How much / All", "C": "How much / Either", "D": "How many / All", "E": "How a lot / All"}'::jsonb, 'B', NULL, '(1) How much — luggage saylanmayandır → how much (2) All — all (of) the + cəm');
INSERT INTO public.questions VALUES (6835, 87, 'g10-eng-quant-q3-05', 3, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the two answers is correct, so try again. (2) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "Both / One", "B": "Neither / Some", "C": "Neither / All", "D": "Neither / One", "E": "Neither / Both"}'::jsonb, 'D', NULL, '(1) Neither — neither of (ikisindən heç biri) + tək feil (is) (2) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (6836, 87, 'g10-eng-quant-q3-06', 3, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the cakes is mine; take the other one. (2) There isn''t ___ milk left in the fridge.', NULL, NULL, '{"A": "One / much", "B": "All / much", "C": "Both / much", "D": "One / many", "E": "One / few"}'::jsonb, 'A', NULL, '(1) One — one of + cəm isim + tək feil (2) much — much + saylanmayan isim (inkarda)');
INSERT INTO public.questions VALUES (6837, 87, 'g10-eng-quant-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I have ___ money, so I can buy you a coffee. (2) ___ of the students passed the test; it was too difficult.', NULL, NULL, '{"A": "a little / Nobody", "B": "a little / Any", "C": "many / None", "D": "a little / No", "E": "a little / None"}'::jsonb, 'E', NULL, '(1) a little — a little + saylanmayan (müsbət məna: bir az var) (2) None — none of + cəm (üç və daha çox): heç biri');
INSERT INTO public.questions VALUES (6838, 87, 'g10-eng-quant-q3-08', 3, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) She gave me ___ useful advice. (2) We have ___ time; we must hurry.', NULL, NULL, '{"A": "some / many", "B": "some / little", "C": "some / few", "D": "many / little", "E": "a few / little"}'::jsonb, 'B', NULL, '(1) some — advice saylanmayandır → some advice (2) little — little + saylanmayan (mənfi məna)');
INSERT INTO public.questions VALUES (6839, 87, 'g10-eng-quant-q3-09', 3, 9, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Are there any questions?", "B": "There are any apples in the basket.", "C": "We have many time; we must hurry.", "D": "How a lot luggage do you have?", "E": "She has much friends, so she often feels lonely."}'::jsonb, 'A', NULL, 'Correct: «Are there any questions?» — Sual cümləsində any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6840, 87, 'g10-eng-quant-q3-10', 3, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ child needs love and attention. (2) He hardly has ___ free time these days.', NULL, NULL, '{"A": "Every / no", "B": "Several / any", "C": "Every / any", "D": "Both / any", "E": "All / any"}'::jsonb, 'C', NULL, '(1) Every — every + tək isim (2) any — hardly (inkar mənalı) + any');
INSERT INTO public.questions VALUES (6841, 87, 'g10-eng-quant-q3-11', 3, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Only a little students came to the lecture, so it was cancelled.", "B": "We bought several furniture for the new flat.", "C": "The number of tourists has increased this year.", "D": "How much students are there in your class?", "E": "It was so a long journey that we were exhausted."}'::jsonb, 'C', NULL, 'Correct: «The number of tourists has increased this year.» — the number of + tək feil (has). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6842, 87, 'g10-eng-quant-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) It was ___ a long journey that we were exhausted. (2) He hardly has ___ free time these days.', NULL, NULL, '{"A": "so / any", "B": "such / some", "C": "such / any", "D": "too / any", "E": "very / any"}'::jsonb, 'C', NULL, '(1) such — such + (a) + sifət + isim (2) any — hardly (inkar mənalı) + any');
INSERT INTO public.questions VALUES (6843, 87, 'g10-eng-quant-q3-13', 3, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were such many people at the concert that we couldn''t find a seat.", "B": "How little students are there in your class?", "C": "We had several problems with the new software.", "D": "Each the children enjoyed the trip.", "E": "We bought several furniture for the new flat."}'::jsonb, 'C', NULL, 'Correct: «We had several problems with the new software.» — several + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6844, 87, 'g10-eng-quant-q3-14', 3, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She gave me an useful advice.", "B": "All child needs love and attention.", "C": "We had several problems with the new software.", "D": "We have many time; we must hurry.", "E": "He spends many deal of time reading."}'::jsonb, 'C', NULL, 'Correct: «We had several problems with the new software.» — several + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6845, 87, 'g10-eng-quant-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There are ___ apples in the basket. (2) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "some / All", "B": "much / One", "C": "some / Some", "D": "some / Both", "E": "some / One"}'::jsonb, 'E', NULL, '(1) some — Təsdiq cümləsində some (2) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (6846, 87, 'g10-eng-quant-q3-16', 3, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "All child needs love and attention.", "B": "Some of the cakes is mine; take the other one.", "C": "We have little time; we must hurry.", "D": "There were too much people at the concert that we couldn''t find a seat.", "E": "You can take all road; both lead to the city centre."}'::jsonb, 'C', NULL, 'Correct: «We have little time; we must hurry.» — little + saylanmayan (mənfi məna). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6847, 87, 'g10-eng-quant-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) We bought ___ furniture for the new flat. (2) How ___ students are there in your class?', NULL, NULL, '{"A": "some / a little", "B": "some / much", "C": "some / many", "D": "a few / many", "E": "some / little"}'::jsonb, 'C', NULL, '(1) some — furniture saylanmayandır → some (2) many — many + saylan cəm isim');
INSERT INTO public.questions VALUES (6848, 87, 'g10-eng-quant-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Only little students came to the lecture, so it was cancelled.", "B": "We bought many furniture for the new flat.", "C": "She gave me some useful advice.", "D": "Much of my parents are doctors.", "E": "I''ve got a few homework to do tonight."}'::jsonb, 'C', NULL, 'Correct: «She gave me some useful advice.» — advice saylanmayandır → some advice. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6849, 87, 'g10-eng-quant-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I have a few money, so I can buy you a coffee.", "B": "You can take all road; both lead to the city centre.", "C": "We bought some furniture for the new flat.", "D": "I''ve got several homework to do tonight.", "E": "Both student in the class received a certificate."}'::jsonb, 'C', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6850, 87, 'g10-eng-quant-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We had much problems with the new software.", "B": "How many luggage do you have?", "C": "I have many money, so I can buy you a coffee.", "D": "It was too a long journey that we were exhausted.", "E": "The number of tourists has increased this year."}'::jsonb, 'E', NULL, 'Correct: «The number of tourists has increased this year.» — the number of + tək feil (has). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6851, 87, 'g10-eng-quant-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There isn''t ___ milk left in the fridge. (2) We had ___ problems with the new software.', NULL, NULL, '{"A": "much / several", "B": "much / a great deal", "C": "much / a little", "D": "a few / several", "E": "few / several"}'::jsonb, 'A', NULL, '(1) much — much + saylanmayan isim (inkarda) (2) several — several + saylan cəm');
INSERT INTO public.questions VALUES (6852, 87, 'g10-eng-quant-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought many furniture for the new flat.", "B": "Only much students came to the lecture, so it was cancelled.", "C": "She gave me a few useful advice.", "D": "Neither of the two answers is correct, so try again.", "E": "We had much problems with the new software."}'::jsonb, 'D', NULL, 'Correct: «Neither of the two answers is correct, so try again.» — neither of (ikisindən heç biri) + tək feil (is). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6853, 87, 'g10-eng-quant-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were too much people at the concert that we couldn''t find a seat.", "B": "How much luggage do you have?", "C": "There isn''t a few milk left in the fridge.", "D": "I''ve got several homework to do tonight.", "E": "He spends many deal of time reading."}'::jsonb, 'B', NULL, 'Correct: «How much luggage do you have?» — luggage saylanmayandır → how much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6854, 87, 'g10-eng-quant-q3-24', 3, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought many furniture for the new flat.", "B": "We had much problems with the new software.", "C": "She has little friends, so she often feels lonely.", "D": "He spends many deal of time reading.", "E": "I have a little money, so I can buy you a coffee."}'::jsonb, 'E', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6855, 87, 'g10-eng-quant-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How many luggage do you have?", "B": "Both of the two answers is correct, so try again.", "C": "None of the students passed the test; it was too difficult.", "D": "I have few money, so I can buy you a coffee.", "E": "There were so much people at the concert that we couldn''t find a seat."}'::jsonb, 'C', NULL, 'Correct: «None of the students passed the test; it was too difficult.» — none of + cəm (üç və daha çox): heç biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6856, 87, 'g10-eng-quant-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) He spends ___ deal of time reading. (2) ___ of the two answers is correct, so try again.', NULL, NULL, '{"A": "a lot / Neither", "B": "a great / Neither", "C": "many / Neither", "D": "a great / Both", "E": "a great / All"}'::jsonb, 'B', NULL, '(1) a great — a great deal of + saylanmayan (2) Neither — neither of (ikisindən heç biri) + tək feil (is)');
INSERT INTO public.questions VALUES (6857, 87, 'g10-eng-quant-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought some furniture for the new flat.", "B": "How many luggage do you have?", "C": "Both of the cakes is mine; take the other one.", "D": "She has little friends, so she often feels lonely.", "E": "Are there a few of questions?"}'::jsonb, 'A', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6858, 87, 'g10-eng-quant-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I don''t have ___ information about this topic. (2) There were ___ people at the concert that we couldn''t find a seat.', NULL, NULL, '{"A": "many / so many", "B": "much / so many", "C": "much / too much", "D": "much / such many", "E": "few / so many"}'::jsonb, 'B', NULL, '(1) much — information saylanmayandır → much (2) so many — so many + saylan cəm');
INSERT INTO public.questions VALUES (6859, 87, 'g10-eng-quant-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I don''t have ___ information about this topic. (2) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "much / One", "B": "many / One", "C": "much / All", "D": "few / One", "E": "much / Both"}'::jsonb, 'A', NULL, '(1) much — information saylanmayandır → much (2) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (6860, 87, 'g10-eng-quant-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) He spends ___ deal of time reading. (2) ___ the children enjoyed the trip.', NULL, NULL, '{"A": "a great / Either", "B": "many / All", "C": "a great / All", "D": "a great / Each", "E": "a great / Every"}'::jsonb, 'C', NULL, '(1) a great — a great deal of + saylanmayan (2) All — all (of) the + cəm');
INSERT INTO public.questions VALUES (6861, 88, 'g10-eng-noun-q1-01', 1, 1, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three feets in the picture.", "B": "There were three mother-in-laws in the picture.", "C": "There were three leavs in the picture.", "D": "There were three knives in the picture.", "E": "We need new a furniture for the office."}'::jsonb, 'D', NULL, 'Correct: «There were three knives in the picture.» — knife → knives. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6862, 88, 'g10-eng-noun-q1-02', 1, 2, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The newses on TV was very bad today.", "B": "There were three potatoes in the picture.", "C": "My parentses'' car is very old.", "D": "There were three geeses in the picture.", "E": "These are the childrens toys."}'::jsonb, 'B', NULL, 'Correct: «There were three potatoes in the picture.» — potato → potatoes. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6863, 88, 'g10-eng-noun-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The report mentions three ___ (phenomenon). (2) There were three ___ (tooth) in the picture.', NULL, NULL, '{"A": "phenomena / teeth", "B": "phenomenons / teeth", "C": "phenomena / teeths", "D": "phenomenas / teeth", "E": "phenomena / tooths"}'::jsonb, 'A', NULL, '(1) phenomena — phenomenon → phenomena (2) teeth — tooth → teeth');
INSERT INTO public.questions VALUES (6864, 88, 'g10-eng-noun-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It was a three-___ journey. (2) There were three ___ (potato) in the picture.', NULL, NULL, '{"A": "hour / potatoes", "B": "hourly / potatoes", "C": "hour / potatos", "D": "hours / potatoes", "E": "hour''s / potatoes"}'::jsonb, 'A', NULL, '(1) hour — a three-hour journey — tək forma (2) potatoes — potato → potatoes');
INSERT INTO public.questions VALUES (6865, 88, 'g10-eng-noun-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (hero) in the picture. (2) The report mentions three ___ (crisis).', NULL, NULL, '{"A": "heroes / crisises", "B": "heroes / crisis", "C": "heroies / crises", "D": "heroes / crises", "E": "heros / crises"}'::jsonb, 'D', NULL, '(1) heroes — hero → heroes (2) crises — crisis → crises');
INSERT INTO public.questions VALUES (6866, 88, 'g10-eng-noun-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (mother-in-law) in the picture. (2) Our ___ was lost at the airport.', NULL, NULL, '{"A": "mothers-in-laws / luggage", "B": "mothers-in-law / a luggage", "C": "mothers-in-law / luggage''s", "D": "mothers-in-law / luggage", "E": "mothers-in-law / luggages"}'::jsonb, 'D', NULL, '(1) mothers-in-law — mother-in-law → mothers-in-law (2) luggage — luggage saylanmayandır');
INSERT INTO public.questions VALUES (6867, 88, 'g10-eng-noun-q1-07', 1, 7, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three knives in the picture.", "B": "It was a three-hourly journey.", "C": "There were three roofes in the picture.", "D": "There were three womans in the picture.", "E": "There were three potatos in the picture."}'::jsonb, 'A', NULL, 'Correct: «There were three knives in the picture.» — knife → knives. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6868, 88, 'g10-eng-noun-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (goose) in the picture. (2) The scissors ___ on the table.', NULL, NULL, '{"A": "geese / is", "B": "geeses / are", "C": "geese / are", "D": "geese / was", "E": "geese / has been"}'::jsonb, 'C', NULL, '(1) geese — goose → geese (2) are — scissors cəm feillə');
INSERT INTO public.questions VALUES (6869, 88, 'g10-eng-noun-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (goose) in the picture. (2) The report mentions three ___ (criterion).', NULL, NULL, '{"A": "geese / criteria", "B": "gooses / criteria", "C": "geese / criterias", "D": "geeses / criteria", "E": "geese / criterions"}'::jsonb, 'A', NULL, '(1) geese — goose → geese (2) criteria — criterion → criteria');
