INSERT INTO public.questions VALUES (6956, 89, 'g10-eng-adj-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This test is much ___ (difficult) than the last one. (2) Their new flat is ___ (big) than the old one.', NULL, NULL, '{"A": "more difficult / biggest", "B": "very more difficult / bigger", "C": "most difficult / bigger", "D": "more difficult / more big", "E": "more difficult / bigger"}'::jsonb, 'E', NULL, '(1) more difficult — much/far + müqayisə dərəcəsi (very işlənmir) (2) bigger — Müqayisə dərəcəsi: big → bigger');
