INSERT INTO public.questions VALUES (6963, 89, 'g10-eng-adj-q1-13', 1, 13, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the difficultest question in the exam.", "B": "Their new flat is bigger than the old one.", "C": "He isn''t old so to drive.", "D": "She bought a long beautiful red silk dress.", "E": "She is the happyest girl in the class."}'::jsonb, 'B', NULL, 'Correct: «Their new flat is bigger than the old one.» — Müqayisə dərəcəsi: big → bigger. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6964, 89, 'g10-eng-adj-q1-14', 1, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their office is ___ (modern) than ours. (2) It is the ___ (big) flat in the building.', NULL, NULL, '{"A": "most modern / biggest", "B": "more modern / most big", "C": "more modern / biggest", "D": "more modern / bigest", "E": "moderner / biggest"}'::jsonb, 'C', NULL, '(1) more modern — Müqayisə dərəcəsi: modern → more modern (2) biggest — Üstünlük dərəcəsi: big → the biggest');
INSERT INTO public.questions VALUES (6965, 89, 'g10-eng-adj-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This street is much ___ (busy) than ours. (2) The film was so ___ that I fell asleep.', NULL, NULL, '{"A": "busiest / boring", "B": "busier / bored", "C": "very busier / boring", "D": "busier / boring", "E": "busier / bore"}'::jsonb, 'D', NULL, '(1) busier — much/far + müqayisə dərəcəsi (very işlənmir) (2) boring — -ing: səbəb olan şey (film darıxdırıcıdır)');
INSERT INTO public.questions VALUES (6966, 89, 'g10-eng-adj-q1-16', 1, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their office is ___ (modern) than ours. (2) It is the ___ (busy) street in the city.', NULL, NULL, '{"A": "moderner / busiest", "B": "more modern / busier", "C": "most modern / busiest", "D": "more moderner / busiest", "E": "more modern / busiest"}'::jsonb, 'E', NULL, '(1) more modern — Müqayisə dərəcəsi: modern → more modern (2) busiest — Üstünlük dərəcəsi: busy → the busiest');
INSERT INTO public.questions VALUES (6967, 89, 'g10-eng-adj-q1-17', 1, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the most difficultest question in the exam.", "B": "We were shocked by the news.", "C": "My sister looks happyer than before.", "D": "I found a wooden round dining table at the market.", "E": "It is the modernest office in the area."}'::jsonb, 'B', NULL, 'Correct: «We were shocked by the news.» — -ed: hiss (be shocked by). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6968, 89, 'g10-eng-adj-q1-18', 1, 18, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This book is thinnest than that one.", "B": "Leyla is more careful than her brother.", "C": "The more you read, the most you know.", "D": "My sister looks much happiest than before.", "E": "This street is busyer than ours."}'::jsonb, 'B', NULL, 'Correct: «Leyla is more careful than her brother.» — Müqayisə dərəcəsi: careful → more careful. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6969, 89, 'g10-eng-adj-q1-19', 1, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The weather today is much ___ (bad) than yesterday. (2) It is the ___ (thin) book on the shelf.', NULL, NULL, '{"A": "more worst / thinnest", "B": "worse / thinnest", "C": "worse / thinner", "D": "worse / thinest", "E": "worst / thinnest"}'::jsonb, 'B', NULL, '(1) worse — much/far + müqayisə dərəcəsi (very işlənmir) (2) thinnest — Üstünlük dərəcəsi: thin → the thinnest');
INSERT INTO public.questions VALUES (6970, 89, 'g10-eng-adj-q1-20', 1, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The weather today is badder than yesterday.", "B": "The film was so boringly that I fell asleep.", "C": "My older than brother is a pilot.", "D": "I found a round wooden dining table at the market.", "E": "They live in a old lovely stone house."}'::jsonb, 'D', NULL, 'Correct: «I found a round wooden dining table at the market.» — Sifət sırası: forma – material – təyinat. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6971, 89, 'g10-eng-adj-q1-21', 1, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I found a ___ table at the market. (2) It was the ___ (difficult) question in the exam.', NULL, NULL, '{"A": "dining round wooden / most difficult", "B": "round wooden dining / difficultest", "C": "wooden round dining / most difficult", "D": "round wooden dining / most difficult", "E": "round dining wooden / most difficult"}'::jsonb, 'D', NULL, '(1) round wooden dining — Sifət sırası: forma – material – təyinat (2) most difficult — Üstünlük dərəcəsi: difficult → the most difficult');
INSERT INTO public.questions VALUES (6972, 89, 'g10-eng-adj-q1-22', 1, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) My sister looks ___ (happy) than before. (2) This street is ___ (busy) than ours.', NULL, NULL, '{"A": "happier / busiest", "B": "happyer / busier", "C": "happier / more busier", "D": "more happier / busier", "E": "happier / busier"}'::jsonb, 'E', NULL, '(1) happier — Müqayisə dərəcəsi: happy → happier (2) busier — Müqayisə dərəcəsi: busy → busier');
INSERT INTO public.questions VALUES (6973, 89, 'g10-eng-adj-q1-23', 1, 23, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) The weather today is ___ (bad) than yesterday. (2) The box was ___ heavy for me to carry.', NULL, NULL, '{"A": "worse / too", "B": "badder / too", "C": "worst / too", "D": "more worse / too", "E": "worse / enough"}'::jsonb, 'A', NULL, '(1) worse — Müqayisə dərəcəsi: bad → worse (2) too — too + sifət + for + to-infinitive');
INSERT INTO public.questions VALUES (6974, 89, 'g10-eng-adj-q1-24', 1, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) My sister looks much ___ (happy) than before. (2) It was the ___ film I have ever seen.', NULL, NULL, '{"A": "happier / most bad", "B": "happier / baddest", "C": "more happiest / worst", "D": "happier / worst", "E": "very happier / worst"}'::jsonb, 'D', NULL, '(1) happier — much/far + müqayisə dərəcəsi (very işlənmir) (2) worst — bad → the worst');
INSERT INTO public.questions VALUES (6975, 89, 'g10-eng-adj-q1-25', 1, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This book is thinnest than that one.", "B": "It is the most best plan we have.", "C": "The more you read, the more you know.", "D": "He isn''t old so to drive.", "E": "We were shocking by the news."}'::jsonb, 'C', NULL, 'Correct: «The more you read, the more you know.» — the + comparative ..., the + comparative. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6976, 89, 'g10-eng-adj-q1-26', 1, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This plan is more better than the first one.", "B": "The weather today is much worse than yesterday.", "C": "He isn''t old so to drive.", "D": "It was the worstest storm in ten years.", "E": "Leyla is much most careful than her brother."}'::jsonb, 'B', NULL, 'Correct: «The weather today is much worse than yesterday.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6977, 89, 'g10-eng-adj-q1-27', 1, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This summer was dryier than last summer.", "B": "I found a wooden round dining table at the market.", "C": "We were shocked by the news.", "D": "This plan is much more best than the first one.", "E": "For farer information, please contact our office."}'::jsonb, 'C', NULL, 'Correct: «We were shocked by the news.» — -ed: hiss (be shocked by). The other sentences each contain an error.');
