INSERT INTO public.questions VALUES (6979, 89, 'g10-eng-adj-q1-29', 1, 29, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This plan is much best than the first one.", "B": "This bag is not as expensive as that one.", "C": "Their office is much more moderner than ours.", "D": "This summer was much driest than last summer.", "E": "Their office is more moderner than ours."}'::jsonb, 'B', NULL, 'Correct: «This bag is not as expensive as that one.» — as ... as müqayisəsi. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (6980, 89, 'g10-eng-adj-q1-30', 1, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is getting hardest to find a cheap flat in the city.", "B": "This test is most difficult than the last one.", "C": "This book is much thinner than that one.", "D": "He is the more careful driver I know.", "E": "Their new flat is more big than the old one."}'::jsonb, 'C', NULL, 'Correct: «This book is much thinner than that one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
