INSERT INTO public.questions VALUES (6983, 89, 'g10-eng-adj-q2-03', 2, 3, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "For farer information, please contact our office.", "B": "Leyla is more careful than her brother.", "C": "The weather today is much very worse than yesterday.", "D": "Their new flat is much more biggest than the old one.", "E": "He isn''t old so to drive."}'::jsonb, 'B', NULL, 'Correct: «Leyla is more careful than her brother.» — Müqayisə dərəcəsi: careful → more careful. The other sentences each contain an error.');
