INSERT INTO public.questions VALUES (6990, 89, 'g10-eng-adj-q2-10', 2, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She bought a ___ dress. (2) My sister looks ___ (happy) than before.', NULL, NULL, '{"A": "beautiful long red silk / happier", "B": "beautiful silk long red / happier", "C": "beautiful long red silk / more happier", "D": "red beautiful long silk / happier", "E": "long beautiful red silk / happier"}'::jsonb, 'A', NULL, '(1) beautiful long red silk — Sifət sırası: rəy – ölçü – rəng – material (2) happier — Müqayisə dərəcəsi: happy → happier');
