INSERT INTO public.questions VALUES (7006, 89, 'g10-eng-adj-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It was the ___ (dry) month of the year. (2) It is the ___ (big) flat in the building.', NULL, NULL, '{"A": "driest / bigest", "B": "dryest / biggest", "C": "driest / most big", "D": "driest / biggest", "E": "driest / bigger"}'::jsonb, 'D', NULL, '(1) driest — Üstünlük dərəcəsi: dry → the driest (2) biggest — Üstünlük dərəcəsi: big → the biggest');
INSERT INTO public.questions VALUES (7007, 89, 'g10-eng-adj-q2-27', 2, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The weather today is ___ (bad) than yesterday. (2) It is the ___ (busy) street in the city.', NULL, NULL, '{"A": "worse / busyest", "B": "more worse / busiest", "C": "worse / busier", "D": "worse / busiest", "E": "badder / busiest"}'::jsonb, 'D', NULL, '(1) worse — Müqayisə dərəcəsi: bad → worse (2) busiest — Üstünlük dərəcəsi: busy → the busiest');
INSERT INTO public.questions VALUES (7008, 89, 'g10-eng-adj-q2-28', 2, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This book is much ___ (thin) than that one. (2) Leyla is much ___ (careful) than her brother.', NULL, NULL, '{"A": "thinner / more careful", "B": "thinner / very more careful", "C": "thinner / more carefuler", "D": "more thinnest / more careful", "E": "thinnest / more careful"}'::jsonb, 'A', NULL, '(1) thinner — much/far + müqayisə dərəcəsi (very işlənmir) (2) more careful — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (7009, 89, 'g10-eng-adj-q2-29', 2, 29, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is the biggest flat in the building.", "B": "It was the difficultest question in the exam.", "C": "This book is much more thinnest than that one.", "D": "This street is busyer than ours.", "E": "It is the most best plan we have."}'::jsonb, 'A', NULL, 'Correct: «It is the biggest flat in the building.» — Üstünlük dərəcəsi: big → the biggest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7010, 89, 'g10-eng-adj-q2-30', 2, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is the most best plan we have.", "B": "It is getting harder to find a cheap flat in the city.", "C": "It was the most difficultest question in the exam.", "D": "It was the most driest month of the year.", "E": "Your English is getting more and more good."}'::jsonb, 'B', NULL, 'Correct: «It is getting harder to find a cheap flat in the city.» — hard → harder. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7011, 89, 'g10-eng-adj-q3-01', 3, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This street is much ___ (busy) than ours. (2) This book is ___ (thin) than that one.', NULL, NULL, '{"A": "busier / more thin", "B": "busier / thinner", "C": "more busiest / thinner", "D": "busier / thinnest", "E": "busier / thiner"}'::jsonb, 'B', NULL, '(1) busier — much/far + müqayisə dərəcəsi (very işlənmir) (2) thinner — Müqayisə dərəcəsi: thin → thinner');
INSERT INTO public.questions VALUES (7012, 89, 'g10-eng-adj-q3-02', 3, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Their office is much more modern than ours.", "B": "She bought a long beautiful red silk dress.", "C": "The weather today is worst than yesterday.", "D": "Their new flat is more big than the old one.", "E": "He isn''t old too to drive."}'::jsonb, 'A', NULL, 'Correct: «Their office is much more modern than ours.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7013, 89, 'g10-eng-adj-q3-03', 3, 3, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This street is much busiest than ours.", "B": "The more you read, the most you know.", "C": "She felt tired after the long walk.", "D": "It was the dryest month of the year.", "E": "My sister looks happiest than before."}'::jsonb, 'C', NULL, 'Correct: «She felt tired after the long walk.» — feel + sifət (-ed: hiss). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7014, 89, 'g10-eng-adj-q3-04', 3, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The film was so ___ that I fell asleep. (2) My sister looks much ___ (happy) than before.', NULL, NULL, '{"A": "boring / happiest", "B": "boringly / happier", "C": "boring / very happier", "D": "boring / more happiest", "E": "boring / happier"}'::jsonb, 'E', NULL, '(1) boring — -ing: səbəb olan şey (film darıxdırıcıdır) (2) happier — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (7015, 89, 'g10-eng-adj-q3-05', 3, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I was boredly because the lesson was too long.", "B": "Their new flat is biger than the old one.", "C": "This summer was drier than last summer.", "D": "Your English is getting best and best.", "E": "This test is much very more difficult than the last one."}'::jsonb, 'C', NULL, 'Correct: «This summer was drier than last summer.» — Müqayisə dərəcəsi: dry → drier. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7016, 89, 'g10-eng-adj-q3-06', 3, 6, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "For farther information, please contact our office.", "B": "We were shocking by the news.", "C": "This book is thinnest than that one.", "D": "He isn''t old very to drive.", "E": "The weather today is worse than yesterday."}'::jsonb, 'E', NULL, 'Correct: «The weather today is worse than yesterday.» — Müqayisə dərəcəsi: bad → worse. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7017, 89, 'g10-eng-adj-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their new flat is much ___ (big) than the old one. (2) The box was ___ heavy for me to carry.', NULL, NULL, '{"A": "bigger / too", "B": "more biggest / too", "C": "bigger / enough", "D": "bigger / so much", "E": "very bigger / too"}'::jsonb, 'A', NULL, '(1) bigger — much/far + müqayisə dərəcəsi (very işlənmir) (2) too — too + sifət + for + to-infinitive');
INSERT INTO public.questions VALUES (7018, 89, 'g10-eng-adj-q3-08', 3, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It was the ___ (dry) month of the year. (2) It was the ___ (bad) storm in ten years.', NULL, NULL, '{"A": "drier / worst", "B": "dryest / worst", "C": "driest / baddest", "D": "driest / worst", "E": "driest / worse"}'::jsonb, 'D', NULL, '(1) driest — Üstünlük dərəcəsi: dry → the driest (2) worst — Üstünlük dərəcəsi: bad → the worst');
INSERT INTO public.questions VALUES (7019, 89, 'g10-eng-adj-q3-09', 3, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Their new flat is biger than the old one.", "B": "Leyla is much more careful than her brother.", "C": "This plan is more better than the first one.", "D": "This plan is much best than the first one.", "E": "Their new flat is much biggest than the old one."}'::jsonb, 'B', NULL, 'Correct: «Leyla is much more careful than her brother.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7020, 89, 'g10-eng-adj-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the most bad film I have ever seen.", "B": "It was the most difficult question in the exam.", "C": "He is the most carefullest driver I know.", "D": "I was bore because the lesson was too long.", "E": "It is the bigest flat in the building."}'::jsonb, 'B', NULL, 'Correct: «It was the most difficult question in the exam.» — Üstünlük dərəcəsi: difficult → the most difficult. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7021, 89, 'g10-eng-adj-q3-11', 3, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their office is much ___ (modern) than ours. (2) I was ___ because the lesson was too long.', NULL, NULL, '{"A": "more moderner / bored", "B": "more modern / boring", "C": "more modern / boredly", "D": "more modern / bored", "E": "most modern / bored"}'::jsonb, 'D', NULL, '(1) more modern — much/far + müqayisə dərəcəsi (very işlənmir) (2) bored — -ed: insanın hissi');
INSERT INTO public.questions VALUES (7022, 89, 'g10-eng-adj-q3-12', 3, 12, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The weather today is worst than yesterday.", "B": "I found a dining round wooden table at the market.", "C": "It was the worst storm in ten years.", "D": "This plan is best than the first one.", "E": "The more you read, the many you know."}'::jsonb, 'C', NULL, 'Correct: «It was the worst storm in ten years.» — Üstünlük dərəcəsi: bad → the worst. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7023, 89, 'g10-eng-adj-q3-13', 3, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The more you read, the ___ you know. (2) My ___ brother is a pilot.', NULL, NULL, '{"A": "more / older than", "B": "more / elder", "C": "more / more old", "D": "most / elder", "E": "many / elder"}'::jsonb, 'B', NULL, '(1) more — the + comparative ..., the + comparative (2) elder — elder — ailə üzvləri üçün atributiv');
INSERT INTO public.questions VALUES (7024, 89, 'g10-eng-adj-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their office is much ___ (modern) than ours. (2) It was the ___ film I have ever seen.', NULL, NULL, '{"A": "more modern / worse", "B": "more modern / baddest", "C": "more modern / worst", "D": "very more modern / worst", "E": "more moderner / worst"}'::jsonb, 'C', NULL, '(1) more modern — much/far + müqayisə dərəcəsi (very işlənmir) (2) worst — bad → the worst');
INSERT INTO public.questions VALUES (7025, 89, 'g10-eng-adj-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is getting hardest to find a cheap flat in the city.", "B": "It is the thinnest book on the shelf.", "C": "The more you read, the many you know.", "D": "It is the most busier street in the city.", "E": "It was the baddest storm in ten years."}'::jsonb, 'B', NULL, 'Correct: «It is the thinnest book on the shelf.» — Üstünlük dərəcəsi: thin → the thinnest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7026, 89, 'g10-eng-adj-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) We were ___ by the news. (2) Their new flat is much ___ (big) than the old one.', NULL, NULL, '{"A": "shock / bigger", "B": "shocked / more biggest", "C": "shocking / bigger", "D": "shocked / bigger", "E": "shocked / biggest"}'::jsonb, 'D', NULL, '(1) shocked — -ed: hiss (be shocked by) (2) bigger — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (7027, 89, 'g10-eng-adj-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is the bigger flat in the building.", "B": "She felt tiring after the long walk.", "C": "It was the most driest month of the year.", "D": "It is the thinner book on the shelf.", "E": "My elder brother is a pilot."}'::jsonb, 'E', NULL, 'Correct: «My elder brother is a pilot.» — elder — ailə üzvləri üçün atributiv. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7028, 89, 'g10-eng-adj-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This book is much very thinner than that one.", "B": "Their new flat is much biggest than the old one.", "C": "It is the thinner book on the shelf.", "D": "Their office is much more modern than ours.", "E": "It is the bigest flat in the building."}'::jsonb, 'D', NULL, 'Correct: «Their office is much more modern than ours.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7029, 89, 'g10-eng-adj-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I found a ___ table at the market. (2) My sister looks much ___ (happy) than before.', NULL, NULL, '{"A": "round wooden dining / happiest", "B": "wooden round dining / happier", "C": "dining round wooden / happier", "D": "round wooden dining / happier", "E": "round wooden dining / more happiest"}'::jsonb, 'D', NULL, '(1) round wooden dining — Sifət sırası: forma – material – təyinat (2) happier — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (7030, 89, 'g10-eng-adj-q3-20', 3, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (busy) street in the city. (2) This book is much ___ (thin) than that one.', NULL, NULL, '{"A": "most busier / thinner", "B": "busiest / thinner", "C": "busier / thinner", "D": "busiest / more thinnest", "E": "busiest / very thinner"}'::jsonb, 'B', NULL, '(1) busiest — Üstünlük dərəcəsi: busy → the busiest (2) thinner — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (7031, 89, 'g10-eng-adj-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This summer was much ___ (dry) than last summer. (2) My sister looks ___ (happy) than before.', NULL, NULL, '{"A": "drier / happier", "B": "drier / happiest", "C": "driest / happier", "D": "more driest / happier", "E": "very drier / happier"}'::jsonb, 'A', NULL, '(1) drier — much/far + müqayisə dərəcəsi (very işlənmir) (2) happier — Müqayisə dərəcəsi: happy → happier');
INSERT INTO public.questions VALUES (7032, 89, 'g10-eng-adj-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This plan is best than the first one.", "B": "She bought a beautiful long red silk dress.", "C": "Their new flat is biggest than the old one.", "D": "It is the most modernest office in the area.", "E": "It was the most difficultest question in the exam."}'::jsonb, 'B', NULL, 'Correct: «She bought a beautiful long red silk dress.» — Sifət sırası: rəy – ölçü – rəng – material. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7033, 89, 'g10-eng-adj-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Your English is getting ___. (2) It was the ___ (difficult) question in the exam.', NULL, NULL, '{"A": "best and best / most difficult", "B": "more and more good / most difficult", "C": "better and better / more difficult", "D": "better and better / most difficultest", "E": "better and better / most difficult"}'::jsonb, 'E', NULL, '(1) better and better — Artan dəyişiklik: comparative and comparative (2) most difficult — Üstünlük dərəcəsi: difficult → the most difficult');
INSERT INTO public.questions VALUES (7034, 89, 'g10-eng-adj-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This plan is ___ (good) than the first one. (2) Their new flat is much ___ (big) than the old one.', NULL, NULL, '{"A": "better / more biggest", "B": "better / biggest", "C": "more better / bigger", "D": "best / bigger", "E": "better / bigger"}'::jsonb, 'E', NULL, '(1) better — Müqayisə dərəcəsi: good → better (2) bigger — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (7035, 89, 'g10-eng-adj-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He has a ___ car. (2) She bought a ___ dress.', NULL, NULL, '{"A": "small black Japanese / long beautiful red silk", "B": "small black Japanese / red beautiful long silk", "C": "small black Japanese / beautiful silk long red", "D": "small black Japanese / beautiful long red silk", "E": "black small Japanese / beautiful long red silk"}'::jsonb, 'D', NULL, '(1) small black Japanese — Sifət sırası: ölçü – rəng – mənşə (2) beautiful long red silk — Sifət sırası: rəy – ölçü – rəng – material');
INSERT INTO public.questions VALUES (7036, 89, 'g10-eng-adj-q3-26', 3, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is the thinnest book on the shelf.", "B": "My sister looks happiest than before.", "C": "This bag is not as expensive like that one.", "D": "My sister looks much happiest than before.", "E": "This street is much busiest than ours."}'::jsonb, 'A', NULL, 'Correct: «It is the thinnest book on the shelf.» — Üstünlük dərəcəsi: thin → the thinnest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7037, 89, 'g10-eng-adj-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My sister looks much happier than before.", "B": "The more you read, the much you know.", "C": "It is getting more hard to find a cheap flat in the city.", "D": "It was the most bad film I have ever seen.", "E": "Your English is getting gooder and gooder."}'::jsonb, 'A', NULL, 'Correct: «My sister looks much happier than before.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7038, 89, 'g10-eng-adj-q3-28', 3, 28, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the baddest storm in ten years.", "B": "Leyla is much more careful than her brother.", "C": "We were shocking by the news.", "D": "This bag is not as expensive so that one.", "E": "The film was so boringly that I fell asleep."}'::jsonb, 'B', NULL, 'Correct: «Leyla is much more careful than her brother.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7039, 89, 'g10-eng-adj-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (big) flat in the building. (2) My ___ brother is a pilot.', NULL, NULL, '{"A": "bigest / elder", "B": "bigger / elder", "C": "biggest / elder", "D": "biggest / eldest than", "E": "biggest / more old"}'::jsonb, 'C', NULL, '(1) biggest — Üstünlük dərəcəsi: big → the biggest (2) elder — elder — ailə üzvləri üçün atributiv');
INSERT INTO public.questions VALUES (7040, 89, 'g10-eng-adj-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the worse film I have ever seen.", "B": "The weather today is much more worst than yesterday.", "C": "I was boring because the lesson was too long.", "D": "I found a round dining wooden table at the market.", "E": "For further information, please contact our office."}'::jsonb, 'E', NULL, 'Correct: «For further information, please contact our office.» — further = əlavə (məlumat). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7041, 90, 'g10-eng-pron-q1-01', 1, 1, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The children enjoyed themself at the party.", "B": "She made the cake himself.", "C": "The company changed their''s logo last year.", "D": "She bought a laptop, what was very expensive.", "E": "He hurt himself while playing football."}'::jsonb, 'E', NULL, 'Correct: «He hurt himself while playing football.» — Qayıdış əvəzliyi: he → himself. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7042, 90, 'g10-eng-pron-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A friend of me is coming to visit.", "B": "Everybody has done their homework.", "C": "Is this umbrella your or hers?", "D": "This is the place who we first met.", "E": "The girl whom is sitting next to me is my cousin."}'::jsonb, 'B', NULL, 'Correct: «Everybody has done their homework.» — everybody ilə their (cinsdən asılı olmayan forma). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7043, 90, 'g10-eng-pron-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Everybody has done ___ homework. (2) The company changed ___ logo last year.', NULL, NULL, '{"A": "their / its", "B": "their / it", "C": "they''re / its", "D": "theirs / its", "E": "there / its"}'::jsonb, 'A', NULL, '(1) their — everybody ilə their (cinsdən asılı olmayan forma) (2) its — its — yiyəlik; it''s = it is');
INSERT INTO public.questions VALUES (7044, 90, 'g10-eng-pron-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ are three books on the table. (2) Between you and ___, I don''t trust him.', NULL, NULL, '{"A": "There / me", "B": "This / me", "C": "Their / me", "D": "There / my", "E": "It / me"}'::jsonb, 'A', NULL, '(1) There — Varlıq bildirmə: there are (2) me — Önlükdən sonra obyekt forması: me');
INSERT INTO public.questions VALUES (7045, 90, 'g10-eng-pron-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The woman ___ car was stolen called the police. (2) The man ___ I spoke to was very helpful.', NULL, NULL, '{"A": "who / whom", "B": "whom / whom", "C": "whose / whose", "D": "whose / whom", "E": "which / whom"}'::jsonb, 'D', NULL, '(1) whose — whose — yiyəlik bildirən nisbi əvəzlik (2) whom — whom — obyekt kimi şəxs (formal)');
INSERT INTO public.questions VALUES (7046, 90, 'g10-eng-pron-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He hurt ___ while playing football. (2) The two friends looked at ___ and smiled.', NULL, NULL, '{"A": "himself / itself", "B": "hisself / each other", "C": "he / each other", "D": "himself / theirselves", "E": "himself / each other"}'::jsonb, 'E', NULL, '(1) himself — Qayıdış əvəzliyi: he → himself (2) each other — Qarşılıqlı: each other');
INSERT INTO public.questions VALUES (7047, 90, 'g10-eng-pron-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Everybody has done ___ homework. (2) The girl ___ is sitting next to me is my cousin.', NULL, NULL, '{"A": "there / who", "B": "their / whose", "C": "their / whom", "D": "their / who", "E": "theirs / who"}'::jsonb, 'D', NULL, '(1) their — everybody ilə their (cinsdən asılı olmayan forma) (2) who — Şəxs mübtəda: who');
INSERT INTO public.questions VALUES (7048, 90, 'g10-eng-pron-q1-08', 1, 8, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "What''s did you give the keys to?", "B": "He hurt himself while playing football.", "C": "It are three books on the table.", "D": "I don''t like these shoes. Can I see the black it?", "E": "They blamed theirselves for the mistake."}'::jsonb, 'B', NULL, 'Correct: «He hurt himself while playing football.» — Qayıdış əvəzliyi: he → himself. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7049, 90, 'g10-eng-pron-q1-09', 1, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We did the project by ourself.", "B": "This are three books on the table.", "C": "The two friends looked at each others and smiled.", "D": "She bought a laptop, that was very expensive.", "E": "The company changed its logo last year."}'::jsonb, 'E', NULL, 'Correct: «The company changed its logo last year.» — its — yiyəlik; it''s = it is. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7050, 90, 'g10-eng-pron-q1-10', 1, 10, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "No of them knew the answer, so the teacher explained it again.", "B": "She made the cake herself.", "C": "How did you give the keys to?", "D": "Between you and I, I don''t trust him.", "E": "Neither of the girls brought their own''s book."}'::jsonb, 'B', NULL, 'Correct: «She made the cake herself.» — Qayıdış əvəzliyi: she → herself. The other sentences each contain an error.');
