INSERT INTO public.questions VALUES (7098, 90, 'g10-eng-pron-q2-28', 2, 28, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) The girl ___ is sitting next to me is my cousin. (2) Is this umbrella ___ or hers?', NULL, NULL, '{"A": "whom / yours", "B": "who / you", "C": "which / yours", "D": "who / yours", "E": "who / yourself"}'::jsonb, 'D', NULL, '(1) who — Şəxs mübtəda: who (2) yours — Müstəqil forma: yours');
INSERT INTO public.questions VALUES (7099, 90, 'g10-eng-pron-q2-29', 2, 29, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) Is this umbrella ___ or hers? (2) The children enjoyed ___ at the party.', NULL, NULL, '{"A": "yourself / themselves", "B": "yours / theirselves", "C": "yours / themselfs", "D": "you / themselves", "E": "yours / themselves"}'::jsonb, 'E', NULL, '(1) yours — Müstəqil forma: yours (2) themselves — they → themselves');
INSERT INTO public.questions VALUES (7100, 90, 'g10-eng-pron-q2-30', 2, 30, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She made the cake her.", "B": "That you need is a good night''s sleep.", "C": "Between you and mine, I don''t trust him.", "D": "He hurt himself while playing football.", "E": "The two friends looked at theirselves and smiled."}'::jsonb, 'D', NULL, 'Correct: «He hurt himself while playing football.» — Qayıdış əvəzliyi: he → himself. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7101, 90, 'g10-eng-pron-q3-01', 3, 1, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This is the place whose we first met.", "B": "The woman which car was stolen called the police.", "C": "He hurt himself while playing football.", "D": "The man what I spoke to was very helpful.", "E": "The children enjoyed themself at the party."}'::jsonb, 'C', NULL, 'Correct: «He hurt himself while playing football.» — Qayıdış əvəzliyi: he → himself. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7102, 90, 'g10-eng-pron-q3-02', 3, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I don''t like these shoes. Can I see the black ___? (2) She made the cake ___.', NULL, NULL, '{"A": "them / herself", "B": "ones / her", "C": "it / herself", "D": "ones / herself", "E": "ones / himself"}'::jsonb, 'D', NULL, '(1) ones — Cəm isim əvəzinə ones (2) herself — Qayıdış əvəzliyi: she → herself');
INSERT INTO public.questions VALUES (7103, 90, 'g10-eng-pron-q3-03', 3, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Everybody has done ___ homework. (2) He hurt ___ while playing football.', NULL, NULL, '{"A": "their / his", "B": "their / himself", "C": "there / himself", "D": "theirs / himself", "E": "their / hisself"}'::jsonb, 'B', NULL, '(1) their — everybody ilə their (cinsdən asılı olmayan forma) (2) himself — Qayıdış əvəzliyi: he → himself');
INSERT INTO public.questions VALUES (7104, 90, 'g10-eng-pron-q3-04', 3, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This is the place ___ we first met. (2) I don''t like these shoes. Can I see the black ___?', NULL, NULL, '{"A": "where / ones", "B": "where / it", "C": "which / ones", "D": "who / ones", "E": "whose / ones"}'::jsonb, 'A', NULL, '(1) where — Yer bildirən nisbi zərf: where (2) ones — Cəm isim əvəzinə ones');
INSERT INTO public.questions VALUES (7105, 90, 'g10-eng-pron-q3-05', 3, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They blamed themself for the mistake.", "B": "Everybody has done their homework.", "C": "This is raining heavily outside.", "D": "The company changed it logo last year.", "E": "The woman which car was stolen called the police."}'::jsonb, 'B', NULL, 'Correct: «Everybody has done their homework.» — everybody ilə their (cinsdən asılı olmayan forma). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7106, 90, 'g10-eng-pron-q3-06', 3, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ you need is a good night''s sleep. (2) She made the cake ___.', NULL, NULL, '{"A": "What / itself", "B": "Who / herself", "C": "What / herself", "D": "What / himself", "E": "That / herself"}'::jsonb, 'C', NULL, '(1) What — What = the thing that (2) herself — Qayıdış əvəzliyi: she → herself');
INSERT INTO public.questions VALUES (7107, 90, 'g10-eng-pron-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The children enjoyed ___ at the party. (2) ___ did you give the keys to?', NULL, NULL, '{"A": "themself / Who", "B": "themselves / Who", "C": "themselves / What''s", "D": "themselfs / Who", "E": "themselves / Whose"}'::jsonb, 'B', NULL, '(1) themselves — they → themselves (2) Who — Sual: Who … to?');
INSERT INTO public.questions VALUES (7108, 90, 'g10-eng-pron-q3-08', 3, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "What''s did you give the keys to?", "B": "I don''t like these shoes. Can I see the black it?", "C": "She bought a laptop, what was very expensive.", "D": "This is the place where we first met.", "E": "Neither of the girls brought herself book."}'::jsonb, 'D', NULL, 'Correct: «This is the place where we first met.» — Yer bildirən nisbi zərf: where. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7109, 90, 'g10-eng-pron-q3-09', 3, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "What''s did you give the keys to?", "B": "Nothing of them knew the answer, so the teacher explained it again.", "C": "She bought a laptop, which was very expensive.", "D": "She made the cake itself.", "E": "The woman which car was stolen called the police."}'::jsonb, 'C', NULL, 'Correct: «She bought a laptop, which was very expensive.» — Ayırıcı nisbi cümlədə that işlənmir → which. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7110, 90, 'g10-eng-pron-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The girl which is sitting next to me is my cousin.", "B": "That you need is a good night''s sleep.", "C": "The company changed their''s logo last year.", "D": "The woman whom car was stolen called the police.", "E": "Neither of the girls brought her book."}'::jsonb, 'E', NULL, 'Correct: «Neither of the girls brought her book.» — neither (tək) + her. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7111, 90, 'g10-eng-pron-q3-11', 3, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This book is not yours; it''s ___. (2) She bought a laptop, ___ was very expensive.', NULL, NULL, '{"A": "mine / that", "B": "me / which", "C": "mine / what", "D": "myself / which", "E": "mine / which"}'::jsonb, 'E', NULL, '(1) mine — Müstəqil yiyəlik əvəzliyi: mine (2) which — Ayırıcı nisbi cümlədə that işlənmir → which');
INSERT INTO public.questions VALUES (7112, 90, 'g10-eng-pron-q3-12', 3, 12, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Is this umbrella your or hers?", "B": "This is the place which we first met.", "C": "The children enjoyed theirselves at the party.", "D": "This book is not yours; it''s mine.", "E": "This is the house who I was born in."}'::jsonb, 'D', NULL, 'Correct: «This book is not yours; it''s mine.» — Müstəqil yiyəlik əvəzliyi: mine. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7113, 90, 'g10-eng-pron-q3-13', 3, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This is the place ___ we first met. (2) This is the house ___ I was born in.', NULL, NULL, '{"A": "where / whose", "B": "which / which", "C": "whose / which", "D": "where / which", "E": "where / whom"}'::jsonb, 'D', NULL, '(1) where — Yer bildirən nisbi zərf: where (2) which — Əşya üçün which');
INSERT INTO public.questions VALUES (7114, 90, 'g10-eng-pron-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) A friend of ___ is coming to visit. (2) He hurt ___ while playing football.', NULL, NULL, '{"A": "mine / hisself", "B": "mine / himself", "C": "mine / he", "D": "mine / his", "E": "me / himself"}'::jsonb, 'B', NULL, '(1) mine — a friend of mine — müstəqil forma (2) himself — Qayıdış əvəzliyi: he → himself');
INSERT INTO public.questions VALUES (7115, 90, 'g10-eng-pron-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This is the house ___ I was born in. (2) This is the place ___ we first met.', NULL, NULL, '{"A": "whom / where", "B": "which / whose", "C": "which / who", "D": "which / where", "E": "which / which"}'::jsonb, 'D', NULL, '(1) which — Əşya üçün which (2) where — Yer bildirən nisbi zərf: where');
INSERT INTO public.questions VALUES (7116, 90, 'g10-eng-pron-q3-16', 3, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This is the place who we first met.", "B": "Who did you give the keys to?", "C": "She made the cake her.", "D": "The man whose I spoke to was very helpful.", "E": "This is the house whose I was born in."}'::jsonb, 'B', NULL, 'Correct: «Who did you give the keys to?» — Sual: Who … to?. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7117, 90, 'g10-eng-pron-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She made the cake himself.", "B": "The woman whose car was stolen called the police.", "C": "This is the place who we first met.", "D": "We did the project by we.", "E": "The children enjoyed theirselves at the party."}'::jsonb, 'B', NULL, 'Correct: «The woman whose car was stolen called the police.» — whose — yiyəlik bildirən nisbi əvəzlik. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7118, 90, 'g10-eng-pron-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Is this umbrella your or hers?", "B": "Who did you give the keys to?", "C": "Neither of the girls brought hers book.", "D": "This is the place which we first met.", "E": "This are three books on the table."}'::jsonb, 'B', NULL, 'Correct: «Who did you give the keys to?» — Sual: Who … to?. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7119, 90, 'g10-eng-pron-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They blamed their for the mistake.", "B": "Everybody has done they''re homework.", "C": "What you need is a good night''s sleep.", "D": "She bought a laptop, who was very expensive.", "E": "The woman whom car was stolen called the police."}'::jsonb, 'C', NULL, 'Correct: «What you need is a good night''s sleep.» — What = the thing that. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7120, 90, 'g10-eng-pron-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This are three books on the table.", "B": "Which you need is a good night''s sleep.", "C": "Neither of the girls brought their own''s book.", "D": "The woman whose car was stolen called the police.", "E": "We did the project by we."}'::jsonb, 'D', NULL, 'Correct: «The woman whose car was stolen called the police.» — whose — yiyəlik bildirən nisbi əvəzlik. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7121, 90, 'g10-eng-pron-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She made the cake ___. (2) A friend of ___ is coming to visit.', NULL, NULL, '{"A": "herself / I", "B": "herself / my", "C": "itself / mine", "D": "herself / mine", "E": "her / mine"}'::jsonb, 'D', NULL, '(1) herself — Qayıdış əvəzliyi: she → herself (2) mine — a friend of mine — müstəqil forma');
INSERT INTO public.questions VALUES (7122, 90, 'g10-eng-pron-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She bought a laptop, ___ was very expensive. (2) The girl ___ is sitting next to me is my cousin.', NULL, NULL, '{"A": "that / who", "B": "which / which", "C": "which / whose", "D": "which / whom", "E": "which / who"}'::jsonb, 'E', NULL, '(1) which — Ayırıcı nisbi cümlədə that işlənmir → which (2) who — Şəxs mübtəda: who');
INSERT INTO public.questions VALUES (7123, 90, 'g10-eng-pron-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Is this umbrella ___ or hers? (2) They blamed ___ for the mistake.', NULL, NULL, '{"A": "your / themselves", "B": "you / themselves", "C": "yours / themself", "D": "yours / themselves", "E": "yourself / themselves"}'::jsonb, 'D', NULL, '(1) yours — Müstəqil forma: yours (2) themselves — Qayıdış: they → themselves');
INSERT INTO public.questions VALUES (7124, 90, 'g10-eng-pron-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ you need is a good night''s sleep. (2) The man ___ I spoke to was very helpful.', NULL, NULL, '{"A": "Which / whom", "B": "That / whom", "C": "What / whom", "D": "What / which", "E": "What / whose"}'::jsonb, 'C', NULL, '(1) What — What = the thing that (2) whom — whom — obyekt kimi şəxs (formal)');
INSERT INTO public.questions VALUES (7125, 90, 'g10-eng-pron-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The children enjoyed theirselves at the party.", "B": "Between you and my, I don''t trust him.", "C": "They blamed theirselves for the mistake.", "D": "The woman whom car was stolen called the police.", "E": "We did the project by ourselves."}'::jsonb, 'E', NULL, 'Correct: «We did the project by ourselves.» — by ourselves — öz-özümüzə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7126, 90, 'g10-eng-pron-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I have two brothers, both of ___ are engineers. (2) The woman ___ car was stolen called the police.', NULL, NULL, '{"A": "which / whose", "B": "who / whose", "C": "whom / which", "D": "whom / whose", "E": "whom / who"}'::jsonb, 'D', NULL, '(1) whom — Önlükdən sonra şəxs üçün whom (both of whom) (2) whose — whose — yiyəlik bildirən nisbi əvəzlik');
