INSERT INTO public.questions VALUES (7128, 90, 'g10-eng-pron-q3-28', 3, 28, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They blamed theirselves for the mistake.", "B": "She bought a laptop, what was very expensive.", "C": "I don''t like these shoes. Can I see the black ones?", "D": "Is this umbrella your or hers?", "E": "Between you and my, I don''t trust him."}'::jsonb, 'C', NULL, 'Correct: «I don''t like these shoes. Can I see the black ones?» — Cəm isim əvəzinə ones. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7129, 90, 'g10-eng-pron-q3-29', 3, 29, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The children enjoyed themselves at the party.", "B": "They blamed their for the mistake.", "C": "A friend of me is coming to visit.", "D": "The two friends looked at itself and smiled.", "E": "Everybody has done they''re homework."}'::jsonb, 'A', NULL, 'Correct: «The children enjoyed themselves at the party.» — they → themselves. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7130, 90, 'g10-eng-pron-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Between you and ___, I don''t trust him. (2) The two friends looked at ___ and smiled.', NULL, NULL, '{"A": "my / each other", "B": "me / each others", "C": "me / each other", "D": "me / itself", "E": "me / theirselves"}'::jsonb, 'C', NULL, '(1) me — Önlükdən sonra obyekt forması: me (2) each other — Qarşılıqlı: each other');
INSERT INTO public.questions VALUES (7131, 91, 'g10-eng-num-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I need a dozens of eggs for this cake.", "B": "I''ve told you a dozens times not to do that!", "C": "King Charles third the became king in 2022.", "D": "Can you count from one to twelfe?", "E": "Two thirds of the students are girls."}'::jsonb, 'E', NULL, 'Correct: «Two thirds of the students are girls.» — Kəsr: two thirds (surət >1 olanda məxrəc cəm). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7132, 91, 'g10-eng-num-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Three ___ of the cake were eaten. (3/4) (2) ___ of the students are girls. (2/3)', NULL, NULL, '{"A": "quarters / Two thirds", "B": "quarters / Two third", "C": "quarters / Two threes", "D": "quarter / Two thirds", "E": "fourth / Two thirds"}'::jsonb, 'A', NULL, '(1) quarters — three quarters (2) Two thirds — Kəsr: two thirds (surət >1 olanda məxrəc cəm)');
INSERT INTO public.questions VALUES (7133, 91, 'g10-eng-num-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We live on the twenty-oneth floor.", "B": "Please open your books at page 25.", "C": "Her birthday is on the three of May.", "D": "The meeting is on the nineth floor.", "E": "Water freezes at zero degrees Celsiuses."}'::jsonb, 'B', NULL, 'Correct: «Please open your books at page 25.» — page + rəqəm, artiklsiz. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7134, 91, 'g10-eng-num-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The flight takes a one and half hours.", "B": "It was a five-mile walk.", "C": "I''ve told you dozen times not to do that!", "D": "Prices rose by 2.5 per cent — that is, two comma five per cent.", "E": "Her birthday is on the thirdth of May."}'::jsonb, 'B', NULL, 'Correct: «It was a five-mile walk.» — Mürəkkəb sifət: a five-mile walk. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7135, 91, 'g10-eng-num-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) King Charles ___ became king in 2022. (III) (2) The flight takes ___ hours.', NULL, NULL, '{"A": "the Third / one and a half", "B": "third the / one and a half", "C": "the Third / one half and", "D": "the Three / one and a half", "E": "the Third / one and half"}'::jsonb, 'A', NULL, '(1) the Third — Hökmdar adlarında sıra sayı: Charles the Third (2) one and a half — 1,5: one and a half hours');
INSERT INTO public.questions VALUES (7136, 91, 'g10-eng-num-q1-06', 1, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The flight takes one half and hours.", "B": "It was a fifth-mile walk.", "C": "He came the two in the race.", "D": "She won one prize in the competition.", "E": "Prices rose by 2.5 per cent — that is, two point five per cent."}'::jsonb, 'E', NULL, 'Correct: «Prices rose by 2.5 per cent — that is, two point five per cent.» — Onluq kəsr: two point five. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7137, 91, 'g10-eng-num-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Three ___ of the cake were eaten. (3/4) (2) I''ve told you ___ times not to do that!', NULL, NULL, '{"A": "quarter / dozens of", "B": "four / dozens of", "C": "quarters / dozens of", "D": "quarters / a dozens", "E": "fourth / dozens of"}'::jsonb, 'C', NULL, '(1) quarters — three quarters (2) dozens of — Qeyri-müəyyən: dozens of times');
INSERT INTO public.questions VALUES (7138, 91, 'g10-eng-num-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I''ve told you dozen times not to do that!", "B": "The flight takes one and a half hours.", "C": "The twentieth-one century began in 2001.", "D": "He came the two in the race.", "E": "This is the hundreds time I have told you!"}'::jsonb, 'B', NULL, 'Correct: «The flight takes one and a half hours.» — 1,5: one and a half hours. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7139, 91, 'g10-eng-num-q1-09', 1, 9, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Can you count from one to twelfth?", "B": "The twentieth-one century began in 2001.", "C": "Her birthday is on the third of May.", "D": "The Two World War ended in 1945.", "E": "This is the hundredeth time I have told you!"}'::jsonb, 'C', NULL, 'Correct: «Her birthday is on the third of May.» — Tarix: the third of May. The other sentences each contain an error.');
