INSERT INTO public.questions VALUES (7141, 91, 'g10-eng-num-q1-11', 1, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I need a ___ eggs for this cake. (2) Can you count from one to ___? (12)', NULL, NULL, '{"A": "dozen of / twelve", "B": "dozen / twelfth", "C": "dozen / twelve", "D": "dozen / twelfe", "E": "dozens of / twelve"}'::jsonb, 'C', NULL, '(1) dozen — a dozen eggs (of olmadan) (2) twelve — Miqdar sayı: twelve');
