INSERT INTO public.questions VALUES (7190, 91, 'g10-eng-num-q2-30', 2, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The meeting is on ___ floor. (2) The stadium holds two ___ people.', NULL, NULL, '{"A": "the ninth / thousand", "B": "the nineth / thousand", "C": "the ninth / thousands of", "D": "nine / thousand", "E": "the ninth / thousands"}'::jsonb, 'A', NULL, '(1) the ninth — 9 → ninth (e düşür) (2) thousand — Dəqiq saydan sonra thousand tək qalır');
INSERT INTO public.questions VALUES (7191, 91, 'g10-eng-num-q3-01', 3, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Prices rose by 2.5 per cent — that is, two point five per cent.", "B": "The stadium holds two thousands people.", "C": "Millions people watched the match online.", "D": "She won one prize in the competition.", "E": "The twentieth-one century began in 2001."}'::jsonb, 'A', NULL, 'Correct: «Prices rose by 2.5 per cent — that is, two point five per cent.» — Onluq kəsr: two point five. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7192, 91, 'g10-eng-num-q3-02', 3, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She won the one prize in the competition.", "B": "It was a five-mile walk.", "C": "The stadium holds two thousands people.", "D": "He came the two in the race.", "E": "I need a dozens eggs for this cake."}'::jsonb, 'B', NULL, 'Correct: «It was a five-mile walk.» — Mürəkkəb sifət: a five-mile walk. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7193, 91, 'g10-eng-num-q3-03', 3, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The twenty-oneth century began in 2001.", "B": "We live on the twenty-oneth floor.", "C": "Her birthday is on the three of May.", "D": "King Charles the Three became king in 2022.", "E": "Prices rose by 2.5 per cent — that is, two point five per cent."}'::jsonb, 'E', NULL, 'Correct: «Prices rose by 2.5 per cent — that is, two point five per cent.» — Onluq kəsr: two point five. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7194, 91, 'g10-eng-num-q3-04', 3, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Water freezes at zero degrees ___. (2) We live on the ___ floor.', NULL, NULL, '{"A": "Celsiuses / twenty-first", "B": "Celsius / twenty-first", "C": "Celsius / twentieth-first", "D": "Celsius / twenty-oneth", "E": "of Celsius / twenty-first"}'::jsonb, 'B', NULL, '(1) Celsius — Temperatur: zero degrees Celsius (2) twenty-first — 21 → twenty-first');
INSERT INTO public.questions VALUES (7195, 91, 'g10-eng-num-q3-05', 3, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The meeting is on nine floor.", "B": "This is the hundredth time I have told you!", "C": "Millions people watched the match online.", "D": "It was a five miles'' walk.", "E": "We live on the twentieth-first floor."}'::jsonb, 'B', NULL, 'Correct: «This is the hundredth time I have told you!» — 100-cü: hundredth. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7196, 91, 'g10-eng-num-q3-06', 3, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Can you count from one to ___? (12) (2) She won ___ prize in the competition.', NULL, NULL, '{"A": "twelve / first", "B": "twelveth / first", "C": "twelve / the one", "D": "twelve / firstly", "E": "twelfe / first"}'::jsonb, 'A', NULL, '(1) twelve — Miqdar sayı: twelve (2) first — won first prize — artiklsiz sabit ifadə');
