INSERT INTO public.questions VALUES (7198, 91, 'g10-eng-num-q3-08', 3, 8, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was a five-miles walk.", "B": "Prices rose by 2.5 per cent — that is, two and five per cent.", "C": "Can you count from one to twelve?", "D": "Three fourth of the cake were eaten.", "E": "We live on the twenty-one floor."}'::jsonb, 'C', NULL, 'Correct: «Can you count from one to twelve?» — Miqdar sayı: twelve. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7199, 91, 'g10-eng-num-q3-09', 3, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Her birthday is on the ___ of May. (2) Three ___ of the cake were eaten. (3/4)', NULL, NULL, '{"A": "three / quarters", "B": "threeth / quarters", "C": "third / quarters", "D": "thirdth / quarters", "E": "third / four"}'::jsonb, 'C', NULL, '(1) third — Tarix: the third of May (2) quarters — three quarters');
INSERT INTO public.questions VALUES (7200, 91, 'g10-eng-num-q3-10', 3, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) King Charles ___ became king in 2022. (III) (2) Water freezes at zero degrees ___.', NULL, NULL, '{"A": "the Third / Celsiuses", "B": "the Third / of Celsius", "C": "Three / Celsius", "D": "the Third / Celsius", "E": "the Three / Celsius"}'::jsonb, 'D', NULL, '(1) the Third — Hökmdar adlarında sıra sayı: Charles the Third (2) Celsius — Temperatur: zero degrees Celsius');
INSERT INTO public.questions VALUES (7201, 91, 'g10-eng-num-q3-11', 3, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ of the students are girls. (2/3) (2) The ___ century began in 2001.', NULL, NULL, '{"A": "Second thirds / twenty-first", "B": "Two thirds / twenty-one", "C": "Two thirds / twenty-first", "D": "Two thirds / twentieth-one", "E": "Two third / twenty-first"}'::jsonb, 'C', NULL, '(1) Two thirds — Kəsr: two thirds (surət >1 olanda məxrəc cəm) (2) twenty-first — XXI əsr: the twenty-first century');
INSERT INTO public.questions VALUES (7202, 91, 'g10-eng-num-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ people watched the match online. (2) The meeting is on ___ floor.', NULL, NULL, '{"A": "Million / the ninth", "B": "Millions / the ninth", "C": "Millions of / the ninth", "D": "Millions of / the nineth", "E": "Millions of / nine"}'::jsonb, 'C', NULL, '(1) Millions of — Qeyri-müəyyən çoxluq: millions of (2) the ninth — 9 → ninth (e düşür)');
INSERT INTO public.questions VALUES (7203, 91, 'g10-eng-num-q3-13', 3, 13, 'medium', 'single', 'Choose the option that correctly completes all the gaps: (1) We live on the ___ floor. (2) Her birthday is on the ___ of May.', NULL, NULL, '{"A": "twenty-oneth / third", "B": "twentieth-first / third", "C": "twenty-first / thirdth", "D": "twenty-first / third", "E": "twenty-first / three"}'::jsonb, 'D', NULL, '(1) twenty-first — 21 → twenty-first (2) third — Tarix: the third of May');
INSERT INTO public.questions VALUES (7204, 91, 'g10-eng-num-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She won ___ prize in the competition. (2) ___ birds flew over the lake.', NULL, NULL, '{"A": "firstly / Hundreds of", "B": "first / Hundred of", "C": "first / A hundreds of", "D": "first / Hundreds of", "E": "one / Hundreds of"}'::jsonb, 'D', NULL, '(1) first — won first prize — artiklsiz sabit ifadə (2) Hundreds of — Qeyri-müəyyən: hundreds of');
INSERT INTO public.questions VALUES (7205, 91, 'g10-eng-num-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was a fifth-mile walk.", "B": "He came secondly in the race.", "C": "Please open your books at page 25.", "D": "Three quarter of the cake were eaten.", "E": "We live on the twenty-one floor."}'::jsonb, 'C', NULL, 'Correct: «Please open your books at page 25.» — page + rəqəm, artiklsiz. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7206, 91, 'g10-eng-num-q3-16', 3, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was a five-miles walk.", "B": "A hundreds of birds flew over the lake.", "C": "The flight takes a one and half hours.", "D": "The population is about seven millions of.", "E": "I''ve told you dozens of times not to do that!"}'::jsonb, 'E', NULL, 'Correct: «I''ve told you dozens of times not to do that!» — Qeyri-müəyyən: dozens of times. The other sentences each contain an error.');
