INSERT INTO public.questions VALUES (7210, 91, 'g10-eng-num-q3-20', 3, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The ___ World War ended in 1945. (2) King Charles ___ became king in 2022. (III)', NULL, NULL, '{"A": "Two / the Third", "B": "Second / third the", "C": "Second / the Third", "D": "Secondly / the Third", "E": "Twice / the Third"}'::jsonb, 'C', NULL, '(1) Second — the Second World War (2) the Third — Hökmdar adlarında sıra sayı: Charles the Third');
INSERT INTO public.questions VALUES (7211, 91, 'g10-eng-num-q3-21', 3, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Hundred of birds flew over the lake.", "B": "We live on the twenty-one floor.", "C": "It was a five-miles walk.", "D": "The meeting is on the nineth floor.", "E": "Prices rose by 2.5 per cent — that is, two point five per cent."}'::jsonb, 'E', NULL, 'Correct: «Prices rose by 2.5 per cent — that is, two point five per cent.» — Onluq kəsr: two point five. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7212, 91, 'g10-eng-num-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Can you count from one to ___? (12) (2) It was a ___ walk.', NULL, NULL, '{"A": "twelve / five-mile", "B": "twelve / five-miles", "C": "twelveth / five-mile", "D": "twelve / five miles''", "E": "twelve / fifth-mile"}'::jsonb, 'A', NULL, '(1) twelve — Miqdar sayı: twelve (2) five-mile — Mürəkkəb sifət: a five-mile walk');
INSERT INTO public.questions VALUES (7213, 91, 'g10-eng-num-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Prices rose by 2.5 per cent — that is, two comma five per cent.", "B": "Please open your books at page 25.", "C": "The twenty-oneth century began in 2001.", "D": "We live on the twentieth-first floor.", "E": "The population is about seven million of."}'::jsonb, 'B', NULL, 'Correct: «Please open your books at page 25.» — page + rəqəm, artiklsiz. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7214, 91, 'g10-eng-num-q3-24', 3, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He came the two in the race.", "B": "The population is about seven millions.", "C": "Hundreds birds flew over the lake.", "D": "Two thirds of the students are girls.", "E": "I need a dozen of eggs for this cake."}'::jsonb, 'D', NULL, 'Correct: «Two thirds of the students are girls.» — Kəsr: two thirds (surət >1 olanda məxrəc cəm). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7215, 91, 'g10-eng-num-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Hundreds birds flew over the lake.", "B": "Can you count from one to twelfth?", "C": "Three four of the cake were eaten.", "D": "Second thirds of the students are girls.", "E": "Please open your books at page 25."}'::jsonb, 'E', NULL, 'Correct: «Please open your books at page 25.» — page + rəqəm, artiklsiz. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7216, 91, 'g10-eng-num-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ of the students are girls. (2/3) (2) The ___ century began in 2001.', NULL, NULL, '{"A": "Two thirds / twenty-first", "B": "Two threes / twenty-first", "C": "Two thirds / twenty-one", "D": "Two third / twenty-first", "E": "Second thirds / twenty-first"}'::jsonb, 'A', NULL, '(1) Two thirds — Kəsr: two thirds (surət >1 olanda məxrəc cəm) (2) twenty-first — XXI əsr: the twenty-first century');
INSERT INTO public.questions VALUES (7217, 91, 'g10-eng-num-q3-27', 3, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I need a ___ eggs for this cake. (2) Three ___ of the cake were eaten. (3/4)', NULL, NULL, '{"A": "dozen / fourth", "B": "dozen / quarters", "C": "dozen / quarter", "D": "dozens / quarters", "E": "dozens of / quarters"}'::jsonb, 'B', NULL, '(1) dozen — a dozen eggs (of olmadan) (2) quarters — three quarters');
