INSERT INTO public.questions VALUES (7219, 91, 'g10-eng-num-q3-29', 3, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Water freezes at zero degrees Celsius''s.", "B": "She won firstly prize in the competition.", "C": "The twenty-first century began in 2001.", "D": "I need a dozens eggs for this cake.", "E": "King Charles Three became king in 2022."}'::jsonb, 'C', NULL, 'Correct: «The twenty-first century began in 2001.» — XXI əsr: the twenty-first century. The other sentences each contain an error.');
