INSERT INTO public.questions VALUES (7221, 92, 'g10-eng-adv-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He works harder than every day.", "B": "He speaks English good.", "C": "He was so tired that he fell asleep at once.", "D": "She can fluentlly speak three languages.", "E": "She is ever late for school."}'::jsonb, 'C', NULL, 'Correct: «He was so tired that he fell asleep at once.» — so + sifət + that. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7222, 92, 'g10-eng-adv-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He arrived ___ for the meeting. (2) I have ___ finished; I can help you now.', NULL, NULL, '{"A": "lates / already", "B": "late / yet", "C": "late / already", "D": "latish / already", "E": "late / still"}'::jsonb, 'C', NULL, '(1) late — late — zərf (gec) (2) already — Təsdiqdə already (have ilə V3 arasında)');
INSERT INTO public.questions VALUES (7223, 92, 'g10-eng-adv-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She sings the most beautifully of all the students.", "B": "I have still finished; I can help you now.", "C": "She looked at me angerly.", "D": "Lately had I arrived when the phone rang.", "E": "He speaks English nice."}'::jsonb, 'A', NULL, 'Correct: «She sings the most beautifully of all the students.» — Zərfin üstünlük dərəcəsi: the most + -ly. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7224, 92, 'g10-eng-adv-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She sings beautifullest of all the students.", "B": "She yet lives with her parents.", "C": "She answered the question more confident than I did.", "D": "Never seen I have such a beautiful sunset.", "E": "I can hardly hear you; please speak louder."}'::jsonb, 'E', NULL, 'Correct: «I can hardly hear you; please speak louder.» — hardly = demək olar ki, yox. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7225, 92, 'g10-eng-adv-q1-05', 1, 5, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He ran more fast than anyone else.", "B": "She yet lives with her parents.", "C": "The car was moving very fast.", "D": "Hard had I arrived when the phone rang.", "E": "She drives very carefullly."}'::jsonb, 'C', NULL, 'Correct: «The car was moving very fast.» — fast — zərf də fast. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7226, 92, 'g10-eng-adv-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The soup smells ___. (2) He ran ___ than anyone else.', NULL, NULL, '{"A": "more deliciously / faster", "B": "delicious / faster", "C": "delicious / fastlier", "D": "delicious-ly / faster", "E": "delicious / more fast"}'::jsonb, 'B', NULL, '(1) delicious — Duyğu feilləri (smell, taste) + sifət (2) faster — fast → faster');
INSERT INTO public.questions VALUES (7227, 92, 'g10-eng-adv-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He ran ___ than anyone else. (2) The children played ___ in the garden.', NULL, NULL, '{"A": "fastlier / happily", "B": "faster / happyly", "C": "more faster / happily", "D": "faster / happilly", "E": "faster / happily"}'::jsonb, 'E', NULL, '(1) faster — fast → faster (2) happily — happy → happily (y → i)');
INSERT INTO public.questions VALUES (7228, 92, 'g10-eng-adv-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He works ___ every day. (2) He arrived ___ for the meeting.', NULL, NULL, '{"A": "hardly / late", "B": "hardy / late", "C": "hard / late", "D": "harder than / late", "E": "hard / latish"}'::jsonb, 'C', NULL, '(1) hard — hard — zərf də olur; hardly = demək olar ki, yox (2) late — late — zərf (gec)');
INSERT INTO public.questions VALUES (7229, 92, 'g10-eng-adv-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He works ___ every day. (2) She can ___ speak three languages.', NULL, NULL, '{"A": "hard / fluent", "B": "hardly / fluently", "C": "hard / fluently", "D": "hard / fluency", "E": "harder than / fluently"}'::jsonb, 'C', NULL, '(1) hard — hard — zərf də olur; hardly = demək olar ki, yox (2) fluently — fluent → fluently');
INSERT INTO public.questions VALUES (7230, 92, 'g10-eng-adv-q1-10', 1, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He did ___ in the test. (2) We arrived ___ on time; the doors were closing.', NULL, NULL, '{"A": "badly / still", "B": "worsely / just", "C": "badly / lately", "D": "badily / just", "E": "badly / just"}'::jsonb, 'E', NULL, '(1) badly — bad (sifət) → badly (zərf) (2) just — just — tam, ancaq');
INSERT INTO public.questions VALUES (7231, 92, 'g10-eng-adv-q1-11', 1, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She ever lives with her parents.", "B": "He nearly ever goes to the cinema.", "C": "Have you seen any good films latest?", "D": "She never is late for school.", "E": "I''ll be there soon. Wait for me!"}'::jsonb, 'E', NULL, 'Correct: «I''ll be there soon. Wait for me!» — soon — zaman zərfi. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7232, 92, 'g10-eng-adv-q1-12', 1, 12, 'medium', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He arrived latish for the meeting.", "B": "I can hardily hear you; please speak louder.", "C": "The car was moving very fasted.", "D": "Have you finished your homework yet?", "E": "She looked at me angryly."}'::jsonb, 'D', NULL, 'Correct: «Have you finished your homework yet?» — Sualda yet (cümlənin sonunda). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (7233, 92, 'g10-eng-adv-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She drives very carefullly.", "B": "I can hard hear you; please speak louder.", "C": "Have you seen any good films latest?", "D": "Hard had I arrived when the phone rang.", "E": "He ran faster than anyone else."}'::jsonb, 'E', NULL, 'Correct: «He ran faster than anyone else.» — fast → faster. The other sentences each contain an error.');
