INSERT INTO public.questions VALUES (7285, 92, 'g10-eng-adv-q3-05', 3, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The soup smells ___. (2) She can ___ speak three languages.', NULL, NULL, '{"A": "more deliciously / fluently", "B": "delicious-ly / fluently", "C": "delicious / fluency", "D": "delicious / fluently", "E": "deliciously / fluently"}'::jsonb, 'D', NULL, '(1) delicious — Duyğu feilləri (smell, taste) + sifət (2) fluently — fluent → fluently');
INSERT INTO public.questions VALUES (7286, 92, 'g10-eng-adv-q3-06', 3, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I can hardy hear you; please speak louder.", "B": "He did badily in the test.", "C": "The children played happilly in the garden.", "D": "She can fluent speak three languages.", "E": "You are not working hard enough to pass the exam."}'::jsonb, 'E', NULL, 'Correct: «You are not working hard enough to pass the exam.» — zərf + enough. The other sentences each contain an error.');
