INSERT INTO public.questions VALUES (7288, 92, 'g10-eng-adv-q3-08', 3, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He works ___ every day. (2) He speaks English ___.', NULL, NULL, '{"A": "hardly / well", "B": "hard / well", "C": "hard / nice", "D": "hard / goodly", "E": "hardy / well"}'::jsonb, 'B', NULL, '(1) hard — hard — zərf də olur; hardly = demək olar ki, yox (2) well — good (sifət) → well (zərf)');
