INSERT INTO public.questions VALUES (7661, 97, 'g11-num-real-q1-01', 1, 1, 'hard', 'single', '(√21 + √7)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "51", "B": "52", "C": "54", "D": "28", "E": "53"}'::jsonb, 'B', NULL, '(√21 + √7)² = 28 + 2√147 = 28 + √588. 24² ≤ 588 < 25², deməli tam hissə 52.');
INSERT INTO public.questions VALUES (7662, 97, 'g11-num-real-q1-02', 1, 2, 'hard', 'single', 'x = 1/(√20 − √19) və y = 1/(√20 + √19) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "79", "B": "80", "C": "78", "D": "156", "E": "39"}'::jsonb, 'C', NULL, 'x = (√20 + √19)/1, y = (√20 − √19)/1. x + y = 2√20/1, xy = 1/1. x² + y² = (x + y)² − 2xy = 80/1 − 2/1 = 78.');
INSERT INTO public.questions VALUES (7663, 97, 'g11-num-real-q1-03', 1, 3, 'hard', 'single', 'Hesablayın: 1/(√25 + √27) + 1/(√27 + √29) + … + 1/(√47 + √49)', NULL, NULL, '{"A": "6", "B": "1/2", "C": "2", "D": "1", "E": "3/2"}'::jsonb, 'D', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√49 − √25)/2 = 1.');
INSERT INTO public.questions VALUES (7664, 97, 'g11-num-real-q1-04', 1, 4, 'hard', 'single', 'x = 1/(√20 − √7) və y = 1/(√20 + √7) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "54/13", "B": "27/169", "C": "56/169", "D": "54/169", "E": "108/169"}'::jsonb, 'D', NULL, 'x = (√20 + √7)/13, y = (√20 − √7)/13. x + y = 2√20/13, xy = 1/13. x² + y² = (x + y)² − 2xy = 80/169 − 2/13 = 54/169.');
INSERT INTO public.questions VALUES (7665, 97, 'g11-num-real-q1-05', 1, 5, 'hard', 'single', 'Hesablayın: √(21 + 2√98) − √(21 − 2√98)', NULL, NULL, '{"A": "√14 − √7", "B": "2√21", "C": "2√7", "D": "2√14", "E": "√14"}'::jsonb, 'C', NULL, '21 ± 2√98 = (√14 ± √7)², çünki 14 + 7 = 21 və 14·7 = 98. Fərq: (√14 + √7) − (√14 − √7) = 2√7.');
INSERT INTO public.questions VALUES (7666, 97, 'g11-num-real-q1-06', 1, 6, 'hard', 'single', 'Hesablayın: 1/(√9 + √11) + 1/(√11 + √13) + … + 1/(√79 + √81)', NULL, NULL, '{"A": "6", "B": "5/2", "C": "4", "D": "3", "E": "7/2"}'::jsonb, 'D', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√81 − √9)/2 = 3.');
INSERT INTO public.questions VALUES (7667, 97, 'g11-num-real-q1-07', 1, 7, 'hard', 'single', 'a = √34 − √31, b = √23 − √20, c = 3/(√57 + √54). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < a < b", "B": "c < b < a", "C": "b < c < a", "D": "b < a < c", "E": "a < c < b"}'::jsonb, 'A', NULL, '√x − √y = (x − y)/(√x + √y) = 3/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: c < a < b.');
INSERT INTO public.questions VALUES (7668, 97, 'g11-num-real-q1-08', 1, 8, 'hard', 'single', '(√3 + √20)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "38", "B": "39", "C": "40", "D": "37", "E": "23"}'::jsonb, 'A', NULL, '(√3 + √20)² = 23 + 2√60 = 23 + √240. 15² ≤ 240 < 16², deməli tam hissə 38.');
INSERT INTO public.questions VALUES (7669, 97, 'g11-num-real-q1-09', 1, 9, 'hard', 'single', 'Hesablayın: √(43 + 2√462) − √(43 − 2√462)', NULL, NULL, '{"A": "√22 − √21", "B": "2√21", "C": "√42", "D": "2√43", "E": "2√22"}'::jsonb, 'B', NULL, '43 ± 2√462 = (√22 ± √21)², çünki 22 + 21 = 43 və 22·21 = 462. Fərq: (√22 + √21) − (√22 − √21) = 2√21.');
INSERT INTO public.questions VALUES (7670, 97, 'g11-num-real-q1-10', 1, 10, 'hard', 'single', 'x = 10 + √99 olarsa, x⁴ + 1/x⁴ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "159998", "B": "158402", "C": "158404", "D": "158400", "E": "158406"}'::jsonb, 'B', NULL, '1/x = 10 − √99, x + 1/x = 20, x² + 1/x² = 398, x⁴ + 1/x⁴ = 398² − 2 = 158402.');
INSERT INTO public.questions VALUES (7671, 97, 'g11-num-real-q1-11', 1, 11, 'hard', 'single', 'x = 7 − √48 olarsa, x⁴ + 1/x⁴ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "37634", "B": "37636", "C": "37632", "D": "38414", "E": "37638"}'::jsonb, 'A', NULL, '1/x = 7 + √48, x + 1/x = 14, x² + 1/x² = 194, x⁴ + 1/x⁴ = 194² − 2 = 37634.');
INSERT INTO public.questions VALUES (7672, 97, 'g11-num-real-q1-12', 1, 12, 'hard', 'single', 'Hesablayın: √(13 + 2√42) − √(13 − 2√42)', NULL, NULL, '{"A": "√7 − √6", "B": "2√3", "C": "2√13", "D": "2√6", "E": "2√7"}'::jsonb, 'D', NULL, '13 ± 2√42 = (√7 ± √6)², çünki 7 + 6 = 13 və 7·6 = 42. Fərq: (√7 + √6) − (√7 − √6) = 2√6.');
INSERT INTO public.questions VALUES (7673, 97, 'g11-num-real-q1-13', 1, 13, 'hard', 'single', 'x = 4 + √15 olarsa, x³ + 1/x³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "512", "B": "504", "C": "464", "D": "536", "E": "488"}'::jsonb, 'E', NULL, '1/x = 4 − √15, x + 1/x = 8. x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 512 − 24 = 488.');
INSERT INTO public.questions VALUES (7674, 97, 'g11-num-real-q1-14', 1, 14, 'hard', 'open', 'x = 1/(√16 − √11) və y = 1/(√16 + √11) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '54/25', 'x = (√16 + √11)/5, y = (√16 − √11)/5. x + y = 2√16/5, xy = 1/5. x² + y² = (x + y)² − 2xy = 64/25 − 2/5 = 54/25.');
INSERT INTO public.questions VALUES (7675, 97, 'g11-num-real-q1-15', 1, 15, 'hard', 'single', 'a = √54 − √52, b = √59 − √57, c = 2/(√42 + √40). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "a < c < b", "B": "b < a < c", "C": "b < c < a", "D": "c < a < b", "E": "a < b < c"}'::jsonb, 'B', NULL, '√x − √y = (x − y)/(√x + √y) = 2/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: b < a < c.');
INSERT INTO public.questions VALUES (7676, 97, 'g11-num-real-q1-16', 1, 16, 'hard', 'single', '(√15 + √18)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "66", "B": "64", "C": "65", "D": "33", "E": "67"}'::jsonb, 'C', NULL, '(√15 + √18)² = 33 + 2√270 = 33 + √1080. 32² ≤ 1080 < 33², deməli tam hissə 65.');
INSERT INTO public.questions VALUES (7677, 97, 'g11-num-real-q1-17', 1, 17, 'hard', 'single', 'a = √61 − √58, b = √17 − √14, c = 3/(√44 + √41). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < b < a", "B": "a < b < c", "C": "c < a < b", "D": "b < c < a", "E": "a < c < b"}'::jsonb, 'E', NULL, '√x − √y = (x − y)/(√x + √y) = 3/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: a < c < b.');
INSERT INTO public.questions VALUES (7678, 97, 'g11-num-real-q1-18', 1, 18, 'hard', 'single', 'x = 1/(√24 − √7) və y = 1/(√24 + √7) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "64/289", "B": "62/289", "C": "124/289", "D": "31/289", "E": "62/17"}'::jsonb, 'B', NULL, 'x = (√24 + √7)/17, y = (√24 − √7)/17. x + y = 2√24/17, xy = 1/17. x² + y² = (x + y)² − 2xy = 96/289 − 2/17 = 62/289.');
INSERT INTO public.questions VALUES (7679, 97, 'g11-num-real-q1-19', 1, 19, 'hard', 'single', 'a = √32 − √30, b = √43 − √41, c = 2/(√50 + √48). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "a < b < c", "B": "b < a < c", "C": "b < c < a", "D": "c < a < b", "E": "c < b < a"}'::jsonb, 'E', NULL, '√x − √y = (x − y)/(√x + √y) = 2/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: c < b < a.');
INSERT INTO public.questions VALUES (7680, 97, 'g11-num-real-q1-20', 1, 20, 'hard', 'single', 'Hesablayın: √(16 + 2√39) − √(16 − 2√39)', NULL, NULL, '{"A": "8", "B": "2√13", "C": "√13 − √3", "D": "√6", "E": "2√3"}'::jsonb, 'E', NULL, '16 ± 2√39 = (√13 ± √3)², çünki 13 + 3 = 16 və 13·3 = 39. Fərq: (√13 + √3) − (√13 − √3) = 2√3.');
INSERT INTO public.questions VALUES (7681, 97, 'g11-num-real-q2-01', 2, 1, 'hard', 'single', 'Hesablayın: √(23 + 2√102) − √(23 − 2√102)', NULL, NULL, '{"A": "√17 − √6", "B": "2√6", "C": "2√23", "D": "2√17", "E": "2√3"}'::jsonb, 'B', NULL, '23 ± 2√102 = (√17 ± √6)², çünki 17 + 6 = 23 və 17·6 = 102. Fərq: (√17 + √6) − (√17 − √6) = 2√6.');
INSERT INTO public.questions VALUES (7682, 97, 'g11-num-real-q2-02', 2, 2, 'hard', 'single', 'a = √31 − √29, b = √7 − √5, c = 2/(√12 + √10). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < c < a", "B": "c < b < a", "C": "a < b < c", "D": "a < c < b", "E": "c < a < b"}'::jsonb, 'D', NULL, '√x − √y = (x − y)/(√x + √y) = 2/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: a < c < b.');
INSERT INTO public.questions VALUES (7683, 97, 'g11-num-real-q2-03', 2, 3, 'hard', 'single', 'x = 2 − √3 olarsa, x³ + 1/x³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "40", "B": "60", "C": "64", "D": "52", "E": "76"}'::jsonb, 'D', NULL, '1/x = 2 + √3, x + 1/x = 4. x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 64 − 12 = 52.');
INSERT INTO public.questions VALUES (7684, 97, 'g11-num-real-q2-04', 2, 4, 'hard', 'single', '(√17 + √33)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "50", "B": "96", "C": "99", "D": "97", "E": "98"}'::jsonb, 'D', NULL, '(√17 + √33)² = 50 + 2√561 = 50 + √2244. 47² ≤ 2244 < 48², deməli tam hissə 97.');
INSERT INTO public.questions VALUES (7685, 97, 'g11-num-real-q2-05', 2, 5, 'hard', 'single', 'Hesablayın: 1/(√9 + √11) + 1/(√11 + √13) + … + 1/(√287 + √289)', NULL, NULL, '{"A": "13/2", "B": "14", "C": "8", "D": "10", "E": "7"}'::jsonb, 'E', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√289 − √9)/2 = 7.');
INSERT INTO public.questions VALUES (7686, 97, 'g11-num-real-q2-06', 2, 6, 'hard', 'single', 'a = √23 − √22, b = √39 − √38, c = 1/(√35 + √34). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < a < c", "B": "b < c < a", "C": "a < c < b", "D": "c < a < b", "E": "a < b < c"}'::jsonb, 'B', NULL, '√x − √y = (x − y)/(√x + √y) = 1/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: b < c < a.');
INSERT INTO public.questions VALUES (7687, 97, 'g11-num-real-q2-07', 2, 7, 'hard', 'open', 'x = 10 − √99 olarsa, x³ + 1/x³ ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '7940', '1/x = 10 + √99, x + 1/x = 20. x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 8000 − 60 = 7940.');
INSERT INTO public.questions VALUES (7688, 97, 'g11-num-real-q2-08', 2, 8, 'hard', 'single', 'Hesablayın: 1/(√25 + √27) + 1/(√27 + √29) + … + 1/(√359 + √361)', NULL, NULL, '{"A": "8", "B": "7", "C": "13/2", "D": "14", "E": "12"}'::jsonb, 'B', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√361 − √25)/2 = 7.');
INSERT INTO public.questions VALUES (7689, 97, 'g11-num-real-q2-09', 2, 9, 'hard', 'single', 'Hesablayın: 1/(√49 + √51) + 1/(√51 + √53) + … + 1/(√359 + √361)', NULL, NULL, '{"A": "6", "B": "13", "C": "7", "D": "11/2", "E": "12"}'::jsonb, 'A', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√361 − √49)/2 = 6.');
INSERT INTO public.questions VALUES (7690, 97, 'g11-num-real-q2-10', 2, 10, 'hard', 'single', 'x = 1/(√16 − √7) və y = 1/(√16 + √7) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "46/81", "B": "92/81", "C": "23/81", "D": "16/27", "E": "46/9"}'::jsonb, 'A', NULL, 'x = (√16 + √7)/9, y = (√16 − √7)/9. x + y = 2√16/9, xy = 1/9. x² + y² = (x + y)² − 2xy = 64/81 − 2/9 = 46/81.');
INSERT INTO public.questions VALUES (7691, 97, 'g11-num-real-q2-11', 2, 11, 'hard', 'single', 'a = √31 − √28, b = √47 − √44, c = 3/(√46 + √43). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < c < a", "B": "a < c < b", "C": "a < b < c", "D": "c < a < b", "E": "c < b < a"}'::jsonb, 'A', NULL, '√x − √y = (x − y)/(√x + √y) = 3/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: b < c < a.');
INSERT INTO public.questions VALUES (7692, 97, 'g11-num-real-q2-12', 2, 12, 'hard', 'single', 'Hesablayın: √(18 + 2√77) − √(18 − 2√77)', NULL, NULL, '{"A": "6√2", "B": "√14", "C": "√11 − √7", "D": "2√11", "E": "2√7"}'::jsonb, 'E', NULL, '18 ± 2√77 = (√11 ± √7)², çünki 11 + 7 = 18 və 11·7 = 77. Fərq: (√11 + √7) − (√11 − √7) = 2√7.');
INSERT INTO public.questions VALUES (7693, 97, 'g11-num-real-q2-13', 2, 13, 'hard', 'single', 'x = 1/(√24 − √12) və y = 1/(√24 + √12) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "37/72", "B": "1/2", "C": "6", "D": "1/4", "E": "1"}'::jsonb, 'B', NULL, 'x = (√24 + √12)/12, y = (√24 − √12)/12. x + y = 2√24/12, xy = 1/12. x² + y² = (x + y)² − 2xy = 96/144 − 2/12 = 1/2.');
INSERT INTO public.questions VALUES (7694, 97, 'g11-num-real-q2-14', 2, 14, 'hard', 'open', '(√7 + √36)² ədədinin tam hissəsini tapın.', NULL, NULL, NULL, NULL, '74', '(√7 + √36)² = 43 + 2√252 = 43 + √1008. 31² ≤ 1008 < 32², deməli tam hissə 74.');
INSERT INTO public.questions VALUES (7695, 97, 'g11-num-real-q2-15', 2, 15, 'hard', 'single', 'a = √31 − √28, b = √15 − √12, c = 3/(√10 + √7). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < c < a", "B": "c < a < b", "C": "a < b < c", "D": "a < c < b", "E": "c < b < a"}'::jsonb, 'C', NULL, '√x − √y = (x − y)/(√x + √y) = 3/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: a < b < c.');
INSERT INTO public.questions VALUES (7696, 97, 'g11-num-real-q2-16', 2, 16, 'hard', 'single', '(√7 + √20)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "49", "B": "52", "C": "27", "D": "50", "E": "51"}'::jsonb, 'D', NULL, '(√7 + √20)² = 27 + 2√140 = 27 + √560. 23² ≤ 560 < 24², deməli tam hissə 50.');
INSERT INTO public.questions VALUES (7697, 97, 'g11-num-real-q2-17', 2, 17, 'hard', 'single', '(√28 + √12)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "76", "B": "77", "C": "40", "D": "78", "E": "75"}'::jsonb, 'A', NULL, '(√28 + √12)² = 40 + 2√336 = 40 + √1344. 36² ≤ 1344 < 37², deməli tam hissə 76.');
INSERT INTO public.questions VALUES (7698, 97, 'g11-num-real-q2-18', 2, 18, 'hard', 'single', 'Hesablayın: √(22 + 2√85) − √(22 − 2√85)', NULL, NULL, '{"A": "2√17", "B": "2√5", "C": "2√22", "D": "√17 − √5", "E": "√10"}'::jsonb, 'B', NULL, '22 ± 2√85 = (√17 ± √5)², çünki 17 + 5 = 22 və 17·5 = 85. Fərq: (√17 + √5) − (√17 − √5) = 2√5.');
INSERT INTO public.questions VALUES (7699, 97, 'g11-num-real-q2-19', 2, 19, 'hard', 'single', 'x = 1/(√16 − √10) və y = 1/(√16 + √10) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "13/18", "B": "3/2", "C": "26/9", "D": "26/3", "E": "13/9"}'::jsonb, 'E', NULL, 'x = (√16 + √10)/6, y = (√16 − √10)/6. x + y = 2√16/6, xy = 1/6. x² + y² = (x + y)² − 2xy = 64/36 − 2/6 = 13/9.');
INSERT INTO public.questions VALUES (7700, 97, 'g11-num-real-q2-20', 2, 20, 'hard', 'single', 'x = 9 − √80 olarsa, x⁴ + 1/x⁴ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "103682", "B": "103684", "C": "103680", "D": "103686", "E": "104974"}'::jsonb, 'A', NULL, '1/x = 9 + √80, x + 1/x = 18, x² + 1/x² = 322, x⁴ + 1/x⁴ = 322² − 2 = 103682.');
INSERT INTO public.questions VALUES (7701, 97, 'g11-num-real-q3-01', 3, 1, 'hard', 'single', 'x = 1/(√10 − √3) və y = 1/(√10 + √3) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "13/49", "B": "26/49", "C": "52/49", "D": "26/7", "E": "4/7"}'::jsonb, 'B', NULL, 'x = (√10 + √3)/7, y = (√10 − √3)/7. x + y = 2√10/7, xy = 1/7. x² + y² = (x + y)² − 2xy = 40/49 − 2/7 = 26/49.');
INSERT INTO public.questions VALUES (7702, 97, 'g11-num-real-q3-02', 3, 2, 'hard', 'single', 'Hesablayın: √(9 + 2√14) − √(9 − 2√14)', NULL, NULL, '{"A": "6", "B": "2√2", "C": "2√7", "D": "√7 − √2", "E": "2"}'::jsonb, 'B', NULL, '9 ± 2√14 = (√7 ± √2)², çünki 7 + 2 = 9 və 7·2 = 14. Fərq: (√7 + √2) − (√7 − √2) = 2√2.');
INSERT INTO public.questions VALUES (7703, 97, 'g11-num-real-q3-03', 3, 3, 'hard', 'single', 'Hesablayın: 1/(√9 + √11) + 1/(√11 + √13) + … + 1/(√359 + √361)', NULL, NULL, '{"A": "9", "B": "8", "C": "11", "D": "16", "E": "15/2"}'::jsonb, 'B', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√361 − √9)/2 = 8.');
INSERT INTO public.questions VALUES (7704, 97, 'g11-num-real-q3-04', 3, 4, 'hard', 'single', 'x = 5 + √24 olarsa, x³ + 1/x³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "990", "B": "970", "C": "1030", "D": "1000", "E": "940"}'::jsonb, 'B', NULL, '1/x = 5 − √24, x + 1/x = 10. x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 1000 − 30 = 970.');
INSERT INTO public.questions VALUES (7705, 97, 'g11-num-real-q3-05', 3, 5, 'hard', 'single', '(√27 + √20)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "93", "B": "92", "C": "94", "D": "47", "E": "95"}'::jsonb, 'A', NULL, '(√27 + √20)² = 47 + 2√540 = 47 + √2160. 46² ≤ 2160 < 47², deməli tam hissə 93.');
INSERT INTO public.questions VALUES (7706, 97, 'g11-num-real-q3-06', 3, 6, 'hard', 'single', 'x = 5 + √24 olarsa, x⁴ + 1/x⁴ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "9600", "B": "9602", "C": "9606", "D": "9604", "E": "9998"}'::jsonb, 'B', NULL, '1/x = 5 − √24, x + 1/x = 10, x² + 1/x² = 98, x⁴ + 1/x⁴ = 98² − 2 = 9602.');
INSERT INTO public.questions VALUES (7707, 97, 'g11-num-real-q3-07', 3, 7, 'hard', 'open', 'x = 1/(√6 − √3) və y = 1/(√6 + √3) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '2', 'x = (√6 + √3)/3, y = (√6 − √3)/3. x + y = 2√6/3, xy = 1/3. x² + y² = (x + y)² − 2xy = 24/9 − 2/3 = 2.');
INSERT INTO public.questions VALUES (7708, 97, 'g11-num-real-q3-08', 3, 8, 'hard', 'single', 'a = √13 − √10, b = √15 − √12, c = 3/(√24 + √21). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < a < c", "B": "b < c < a", "C": "a < b < c", "D": "c < b < a", "E": "a < c < b"}'::jsonb, 'D', NULL, '√x − √y = (x − y)/(√x + √y) = 3/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: c < b < a.');
INSERT INTO public.questions VALUES (7709, 97, 'g11-num-real-q3-09', 3, 9, 'hard', 'single', 'x = 1/(√19 − √15) və y = 1/(√19 + √15) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "17/4", "B": "17/2", "C": "35/8", "D": "17/8", "E": "17"}'::jsonb, 'A', NULL, 'x = (√19 + √15)/4, y = (√19 − √15)/4. x + y = 2√19/4, xy = 1/4. x² + y² = (x + y)² − 2xy = 76/16 − 2/4 = 17/4.');
INSERT INTO public.questions VALUES (7710, 97, 'g11-num-real-q3-10', 3, 10, 'hard', 'single', 'Hesablayın: √(20 + 2√91) − √(20 − 2√91)', NULL, NULL, '{"A": "2√7", "B": "2√13", "C": "√14", "D": "√13 − √7", "E": "4√5"}'::jsonb, 'A', NULL, '20 ± 2√91 = (√13 ± √7)², çünki 13 + 7 = 20 və 13·7 = 91. Fərq: (√13 + √7) − (√13 − √7) = 2√7.');
INSERT INTO public.questions VALUES (7711, 97, 'g11-num-real-q3-11', 3, 11, 'hard', 'single', 'Hesablayın: 1/(√9 + √11) + 1/(√11 + √13) + … + 1/(√119 + √121)', NULL, NULL, '{"A": "5", "B": "8", "C": "4", "D": "7/2", "E": "7"}'::jsonb, 'C', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√121 − √9)/2 = 4.');
INSERT INTO public.questions VALUES (7712, 97, 'g11-num-real-q3-12', 3, 12, 'hard', 'single', 'x = 6 + √35 olarsa, x³ + 1/x³ ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1692", "B": "1656", "C": "1728", "D": "1716", "E": "1764"}'::jsonb, 'A', NULL, '1/x = 6 − √35, x + 1/x = 12. x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 1728 − 36 = 1692.');
INSERT INTO public.questions VALUES (7713, 97, 'g11-num-real-q3-13', 3, 13, 'hard', 'single', 'a = √55 − √52, b = √14 − √11, c = 3/(√21 + √18). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "a < c < b", "B": "c < a < b", "C": "a < b < c", "D": "b < a < c", "E": "c < b < a"}'::jsonb, 'A', NULL, '√x − √y = (x − y)/(√x + √y) = 3/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: a < c < b.');
INSERT INTO public.questions VALUES (7714, 97, 'g11-num-real-q3-14', 3, 14, 'hard', 'open', '(√39 + √6)² ədədinin tam hissəsini tapın.', NULL, NULL, NULL, NULL, '75', '(√39 + √6)² = 45 + 2√234 = 45 + √936. 30² ≤ 936 < 31², deməli tam hissə 75.');
INSERT INTO public.questions VALUES (7715, 97, 'g11-num-real-q3-15', 3, 15, 'hard', 'single', 'x = 1/(√16 − √8) və y = 1/(√16 + √8) olarsa, x² + y² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "3/4", "B": "3/2", "C": "3/8", "D": "6", "E": "25/32"}'::jsonb, 'A', NULL, 'x = (√16 + √8)/8, y = (√16 − √8)/8. x + y = 2√16/8, xy = 1/8. x² + y² = (x + y)² − 2xy = 64/64 − 2/8 = 3/4.');
INSERT INTO public.questions VALUES (7716, 97, 'g11-num-real-q3-16', 3, 16, 'hard', 'single', 'Hesablayın: 1/(√1 + √3) + 1/(√3 + √5) + … + 1/(√359 + √361)', NULL, NULL, '{"A": "17/2", "B": "18", "C": "19/2", "D": "9", "E": "10"}'::jsonb, 'D', NULL, '1/(√k + √(k+2)) = (√(k+2) − √k)/2. Cəm teleskopik olur: (√361 − √1)/2 = 9.');
INSERT INTO public.questions VALUES (7717, 97, 'g11-num-real-q3-17', 3, 17, 'hard', 'single', 'a = √8 − √6, b = √50 − √48, c = 2/(√55 + √53). Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < c < a", "B": "b < a < c", "C": "a < b < c", "D": "c < b < a", "E": "a < c < b"}'::jsonb, 'D', NULL, '√x − √y = (x − y)/(√x + √y) = 2/(√x + √y). Surətlər eynidir, məxrəci böyük olan kiçikdir. Ardıcıllıq: c < b < a.');
INSERT INTO public.questions VALUES (7718, 97, 'g11-num-real-q3-18', 3, 18, 'hard', 'single', 'Hesablayın: √(28 + 2√132) − √(28 − 2√132)', NULL, NULL, '{"A": "2√22", "B": "√22 − √6", "C": "2√3", "D": "2√6", "E": "4√7"}'::jsonb, 'D', NULL, '28 ± 2√132 = (√22 ± √6)², çünki 22 + 6 = 28 və 22·6 = 132. Fərq: (√22 + √6) − (√22 − √6) = 2√6.');
INSERT INTO public.questions VALUES (7719, 97, 'g11-num-real-q3-19', 3, 19, 'hard', 'single', '(√25 + √38)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "63", "B": "123", "C": "126", "D": "125", "E": "124"}'::jsonb, 'E', NULL, '(√25 + √38)² = 63 + 2√950 = 63 + √3800. 61² ≤ 3800 < 62², deməli tam hissə 124.');
INSERT INTO public.questions VALUES (7720, 97, 'g11-num-real-q3-20', 3, 20, 'hard', 'single', '(√39 + √31)² ədədinin tam hissəsini tapın.', NULL, NULL, '{"A": "141", "B": "139", "C": "140", "D": "138", "E": "70"}'::jsonb, 'B', NULL, '(√39 + √31)² = 70 + 2√1209 = 70 + √4836. 69² ≤ 4836 < 70², deməli tam hissə 139.');
INSERT INTO public.questions VALUES (7721, 98, 'g11-num-frac-q1-01', 1, 1, 'hard', 'single', 'x : y = 5 : 9 olarsa, (2x² − 2xy) / (y² + 6xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−40/351", "B": "140/351", "C": "72/295", "D": "40/351", "E": "40/31"}'::jsonb, 'A', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 5/9: (2t² − 2t)/(1 + 6t) = (50/81 − 10/9)/(1 + 10/3) = −40/351.');
INSERT INTO public.questions VALUES (7722, 98, 'g11-num-frac-q1-02', 1, 2, 'hard', 'single', 'x : y = 7 : 1 olarsa, (3x² − 6xy) / (2y² + 5xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−39/133", "B": "105/37", "C": "189/37", "D": "−105/37", "E": "37/105"}'::jsonb, 'B', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 7: (3t² − 6t)/(2 + 5t) = (147 − 42)/(2 + 35) = 105/37.');
INSERT INTO public.questions VALUES (7723, 98, 'g11-num-frac-q1-03', 1, 3, 'hard', 'single', 'Hesablayın: 1/(5·6·7) + 1/(6·7·8) + … + 1/(24·25·26)', NULL, NULL, '{"A": "31/1950", "B": "21/260", "C": "31/975", "D": "19/1200", "E": "17/975"}'::jsonb, 'A', NULL, '1/(k(k+1)(k+2)) = ½·[1/(k(k+1)) − 1/((k+1)(k+2))]. Cəm: ½·(1/30 − 1/650) = 31/1950.');
INSERT INTO public.questions VALUES (7724, 98, 'g11-num-frac-q1-04', 1, 4, 'hard', 'single', 'Şagird pulunun 1/6 hissəsini kitaba, qalanın 1/2 hissəsini dəftərə, yenə qalanın 1/8 hissəsini qələmə xərclədi. Ondan 350 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "1680", "B": "2100", "C": "1056", "D": "864", "E": "960"}'::jsonb, 'E', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·5/6·1/2·7/8 = 350, x·35/96 = 350, x = 960.');
