INSERT INTO public.questions VALUES (7764, 98, 'g11-num-frac-q3-04', 3, 4, 'hard', 'single', 'Şagird pulunun 1/4 hissəsini kitaba, qalanın 1/5 hissəsini dəftərə, yenə qalanın 1/5 hissəsini qələmə xərclədi. Ondan 144 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "300", "B": "275", "C": "325", "D": "2880/7", "E": "576"}'::jsonb, 'A', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·3/4·4/5·4/5 = 144, x·12/25 = 144, x = 300.');
INSERT INTO public.questions VALUES (7765, 98, 'g11-num-frac-q3-05', 3, 5, 'hard', 'single', 'Hovuzu birinci boru 7 saata, ikinci boru 4 saata doldurur, üçüncü boru isə dolu hovuzu 28 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "7/3", "B": "19/5", "C": "24/5", "D": "28/11", "E": "14/5"}'::jsonb, 'E', NULL, 'Saatlıq məhsuldarlıq: 1/7 + 1/4 − 1/28 = 5/14. Vaxt: 1 : 5/14 = 14/5 saat.');
INSERT INTO public.questions VALUES (7766, 98, 'g11-num-frac-q3-06', 3, 6, 'hard', 'single', 'Hesablayın: 2 + 1/(4 + 1/(5 + 1/5))', NULL, NULL, '{"A": "97/46", "B": "244/109", "C": "92/41", "D": "1881/820", "E": "53/20"}'::jsonb, 'B', NULL, 'İçəridən başlayın: 5 + 1/5 = 26/5; 4 + 1 : (26/5) = 109/26; 2 + 1 : (109/26) = 244/109.');
INSERT INTO public.questions VALUES (7767, 98, 'g11-num-frac-q3-07', 3, 7, 'hard', 'open', 'Hesablayın: 2 + 1/(3 + 1/(2 + 1/5))', NULL, NULL, NULL, NULL, '87/38', 'İçəridən başlayın: 2 + 1/5 = 11/5; 3 + 1 : (11/5) = 38/11; 2 + 1 : (38/11) = 87/38.');
INSERT INTO public.questions VALUES (7768, 98, 'g11-num-frac-q3-08', 3, 8, 'hard', 'single', 'x : y = 8 : 3 olarsa, (2x² − 4xy) / (y² + 6xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−32/153", "B": "224/153", "C": "96/49", "D": "−3/8", "E": "32/153"}'::jsonb, 'E', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 8/3: (2t² − 4t)/(1 + 6t) = (128/9 − 32/3)/(1 + 16) = 32/153.');
INSERT INTO public.questions VALUES (7769, 98, 'g11-num-frac-q3-09', 3, 9, 'hard', 'single', 'Şagird pulunun 1/5 hissəsini kitaba, qalanın 1/4 hissəsini dəftərə, yenə qalanın 1/5 hissəsini qələmə xərclədi. Ondan 132 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "275", "B": "300", "C": "660", "D": "250", "E": "2640/7"}'::jsonb, 'A', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·4/5·3/4·4/5 = 132, x·12/25 = 132, x = 275.');
INSERT INTO public.questions VALUES (7770, 98, 'g11-num-frac-q3-10', 3, 10, 'hard', 'single', 'Şagird pulunun 1/7 hissəsini kitaba, qalanın 1/5 hissəsini dəftərə, yenə qalanın 1/3 hissəsini qələmə xərclədi. Ondan 48 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "2520/17", "B": "70", "C": "140", "D": "105", "E": "336"}'::jsonb, 'D', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·6/7·4/5·2/3 = 48, x·16/35 = 48, x = 105.');
INSERT INTO public.questions VALUES (7771, 98, 'g11-num-frac-q3-11', 3, 11, 'hard', 'single', 'Hesablayın: 1/(3·4·5) + 1/(4·5·6) + … + 1/(20·21·22)', NULL, NULL, '{"A": "19/132", "B": "25/616", "C": "79/1848", "D": "25/308", "E": "17/420"}'::jsonb, 'B', NULL, '1/(k(k+1)(k+2)) = ½·[1/(k(k+1)) − 1/((k+1)(k+2))]. Cəm: ½·(1/12 − 1/462) = 25/616.');
INSERT INTO public.questions VALUES (7772, 98, 'g11-num-frac-q3-12', 3, 12, 'hard', 'single', 'Şagird pulunun 1/4 hissəsini kitaba, qalanın 1/5 hissəsini dəftərə, yenə qalanın 1/5 hissəsini qələmə xərclədi. Ondan 48 manat qaldı. Şagirdin əvvəlcə neçə manatı var idi?', NULL, NULL, '{"A": "100", "B": "125", "C": "75", "D": "960/7", "E": "192"}'::jsonb, 'A', NULL, 'Hər dəfə qalanın (1 − 1/n) hissəsi qalır: x·3/4·4/5·4/5 = 48, x·12/25 = 48, x = 100.');
INSERT INTO public.questions VALUES (7773, 98, 'g11-num-frac-q3-13', 3, 13, 'hard', 'single', 'Hovuzu birinci boru 15 saata, ikinci boru 8 saata doldurur, üçüncü boru isə dolu hovuzu 10 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "13", "B": "131/11", "C": "24/7", "D": "120/23", "E": "120/11"}'::jsonb, 'E', NULL, 'Saatlıq məhsuldarlıq: 1/15 + 1/8 − 1/10 = 11/120. Vaxt: 1 : 11/120 = 120/11 saat.');
INSERT INTO public.questions VALUES (7774, 98, 'g11-num-frac-q3-14', 3, 14, 'hard', 'single', 'Hesablayın: 1/(7·8·9) + 1/(8·9·10) + … + 1/(24·25·26)', NULL, NULL, '{"A": "19/364", "B": "17/2100", "C": "297/36400", "D": "353/36400", "E": "297/18200"}'::jsonb, 'C', NULL, '1/(k(k+1)(k+2)) = ½·[1/(k(k+1)) − 1/((k+1)(k+2))]. Cəm: ½·(1/56 − 1/650) = 297/36400.');
INSERT INTO public.questions VALUES (7775, 98, 'g11-num-frac-q3-15', 3, 15, 'hard', 'single', 'Hesablayın: 3 + 1/(4 + 1/(3 + 1/7))', NULL, NULL, '{"A": "313/84", "B": "133/41", "C": "1637/492", "D": "157/50", "E": "307/95"}'::jsonb, 'E', NULL, 'İçəridən başlayın: 3 + 1/7 = 22/7; 4 + 1 : (22/7) = 95/22; 3 + 1 : (95/22) = 307/95.');
INSERT INTO public.questions VALUES (7776, 98, 'g11-num-frac-q3-16', 3, 16, 'hard', 'single', 'Hovuzu birinci boru 10 saata, ikinci boru 7 saata doldurur, üçüncü boru isə dolu hovuzu 10 saata boşaldır. Boş hovuzda üç boru birlikdə açılarsa, hovuz neçə saata dolar?', NULL, NULL, '{"A": "8", "B": "70/17", "C": "35/12", "D": "7", "E": "6"}'::jsonb, 'D', NULL, 'Saatlıq məhsuldarlıq: 1/10 + 1/7 − 1/10 = 1/7. Vaxt: 1 : 1/7 = 7 saat.');
INSERT INTO public.questions VALUES (7777, 98, 'g11-num-frac-q3-17', 3, 17, 'hard', 'single', 'x : y = 1 : 8 olarsa, (4x² − 6xy) / (4y² + 2xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−1/3", "B": "−11/68", "C": "13/68", "D": "52/5", "E": "11/68"}'::jsonb, 'B', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 1/8: (4t² − 6t)/(4 + 2t) = (1/16 − 3/4)/(4 + 1/4) = −11/68.');
INSERT INTO public.questions VALUES (7778, 98, 'g11-num-frac-q3-18', 3, 18, 'hard', 'single', 'Hesablayın: 1/(3·4·5) + 1/(4·5·6) + … + 1/(8·9·10)', NULL, NULL, '{"A": "13/180", "B": "13/360", "C": "7/60", "D": "5/144", "E": "17/360"}'::jsonb, 'B', NULL, '1/(k(k+1)(k+2)) = ½·[1/(k(k+1)) − 1/((k+1)(k+2))]. Cəm: ½·(1/12 − 1/90) = 13/360.');
INSERT INTO public.questions VALUES (7779, 98, 'g11-num-frac-q3-19', 3, 19, 'hard', 'single', 'Hesablayın: 3 + 1/(3 + 1/(6 + 1/5))', NULL, NULL, '{"A": "143/46", "B": "113/34", "C": "325/98", "D": "37/10", "E": "517/153"}'::jsonb, 'C', NULL, 'İçəridən başlayın: 6 + 1/5 = 31/5; 3 + 1 : (31/5) = 98/31; 3 + 1 : (98/31) = 325/98.');
INSERT INTO public.questions VALUES (7780, 98, 'g11-num-frac-q3-20', 3, 20, 'hard', 'single', 'x : y = 9 : 7 olarsa, (x² − 4xy) / (6y² + 2xy) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "111/140", "B": "57/140", "C": "−203/612", "D": "−57/140", "E": "15/8"}'::jsonb, 'D', NULL, 'Surəti və məxrəci y²-yə bölün, t = x/y = 9/7: (1t² − 4t)/(6 + 2t) = (81/49 − 36/7)/(6 + 18/7) = −57/140.');
INSERT INTO public.questions VALUES (7781, 99, 'g11-num-pow-q1-01', 1, 1, 'hard', 'single', '4^x + 4^(−x) = 14 və x > 0 olarsa, 8^x + 8^(−x) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "53", "B": "64", "C": "76", "D": "56", "E": "52"}'::jsonb, 'E', NULL, '(2^x + 2^(−x))² = 4^x + 4^(−x) + 2 = 16, deməli 2^x + 2^(−x) = 4. 8^x + 8^(−x) = (2^x + 2^(−x))³ − 3(2^x + 2^(−x)) = 64 − 12 = 52.');
INSERT INTO public.questions VALUES (7782, 99, 'g11-num-pow-q1-02', 1, 2, 'hard', 'single', 'Tənliyi həll edin: 3·2^(x+3) + 5·2^(x−2) = 202', NULL, NULL, '{"A": "2", "B": "1", "C": "3", "D": "4", "E": "6"}'::jsonb, 'C', NULL, '2^x mötərizə xaricinə: 2^x·(3·2^3 + 5/2^2) = 202, 2^x·101/4 = 202, 2^x = 8, x = 3.');
INSERT INTO public.questions VALUES (7783, 99, 'g11-num-pow-q1-03', 1, 3, 'hard', 'single', '2^37 · 5^29 · 3^4 ədədi neçə rəqəmlidir?', NULL, NULL, '{"A": "33", "B": "34", "C": "36", "D": "29", "E": "35"}'::jsonb, 'B', NULL, '2^29·5^29 = 10^29. Qalan vuruq: 20736 (5 rəqəmli). Cəmi 29 + 5 = 34 rəqəm.');
