INSERT INTO public.questions VALUES (7788, 99, 'g11-num-pow-q1-08', 1, 8, 'hard', 'single', '9^x − 90·3^x + 729 = 0 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "6", "B": "90", "C": "729", "D": "5", "E": "7"}'::jsonb, 'A', NULL, 't = 3^x > 0: t² − 90t + 729 = 0, t₁ = 81, t₂ = 9. x₁ = 4, x₂ = 2; cəm: 6.');
