INSERT INTO public.questions VALUES (7803, 99, 'g11-num-pow-q2-03', 2, 3, 'hard', 'single', '4^x + 4^(−x) = 62 və x > 0 olarsa, 8^x + 8^(−x) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "536", "B": "496", "C": "489", "D": "512", "E": "488"}'::jsonb, 'E', NULL, '(2^x + 2^(−x))² = 4^x + 4^(−x) + 2 = 64, deməli 2^x + 2^(−x) = 8. 8^x + 8^(−x) = (2^x + 2^(−x))³ − 3(2^x + 2^(−x)) = 512 − 24 = 488.');
