INSERT INTO public.questions VALUES (7805, 99, 'g11-num-pow-q2-05', 2, 5, 'hard', 'single', '9^x − 28·3^x + 27 = 0 tənliyinin köklərinin hasilini tapın.', NULL, NULL, '{"A": "0", "B": "1", "C": "27", "D": "28", "E": "−1"}'::jsonb, 'A', NULL, 't = 3^x > 0: t² − 28t + 27 = 0, t₁ = 27, t₂ = 1. x₁ = 3, x₂ = 0; hasil: 0.');
