INSERT INTO public.questions VALUES (7807, 99, 'g11-num-pow-q2-07', 2, 7, 'hard', 'open', '2^54 · 5^60 · 3^5 ədədi neçə rəqəmlidir?', NULL, NULL, NULL, NULL, '61', '2^54·5^54 = 10^54. Qalan vuruq: 3796875 (7 rəqəmli). Cəmi 54 + 7 = 61 rəqəm.');
INSERT INTO public.questions VALUES (7808, 99, 'g11-num-pow-q2-08', 2, 8, 'hard', 'single', '2^14 · 5^45 · 3^5 ədədi neçə rəqəmlidir?', NULL, NULL, '{"A": "40", "B": "39", "C": "14", "D": "38", "E": "41"}'::jsonb, 'B', NULL, '2^14·5^14 = 10^14. Qalan vuruq: 1131556928157806396484375 (25 rəqəmli). Cəmi 14 + 25 = 39 rəqəm.');
INSERT INTO public.questions VALUES (7809, 99, 'g11-num-pow-q2-09', 2, 9, 'hard', 'single', 'Tənliyi həll edin: 2^(x+2) + 5·2^(x−2) = 42', NULL, NULL, '{"A": "5", "B": "3", "C": "4", "D": "2", "E": "1"}'::jsonb, 'B', NULL, '2^x mötərizə xaricinə: 2^x·(1·2^2 + 5/2^2) = 42, 2^x·21/4 = 42, 2^x = 8, x = 3.');
INSERT INTO public.questions VALUES (7810, 99, 'g11-num-pow-q2-10', 2, 10, 'hard', 'single', '9^x − 84·3^x + 243 = 0 tənliyinin köklərinin hasilini tapın.', NULL, NULL, '{"A": "3", "B": "243", "C": "5", "D": "4", "E": "84"}'::jsonb, 'D', NULL, 't = 3^x > 0: t² − 84t + 243 = 0, t₁ = 81, t₂ = 3. x₁ = 4, x₂ = 1; hasil: 4.');
INSERT INTO public.questions VALUES (7811, 99, 'g11-num-pow-q2-11', 2, 11, 'hard', 'single', 'a = 2^58, b = 3^30, c = 5^21. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "b < a < c", "B": "a < c < b", "C": "a < b < c", "D": "c < b < a", "E": "b < c < a"}'::jsonb, 'E', NULL, 'Ortaq üstə gətirin və ya loqarifmləri müqayisə edin: 58·lg2 ≈ 17,46, 30·lg3 ≈ 14,31, 21·lg5 ≈ 14,68. Ardıcıllıq: b < c < a.');
INSERT INTO public.questions VALUES (7812, 99, 'g11-num-pow-q2-12', 2, 12, 'hard', 'single', '4^x + 4^(−x) = 79 və x > 0 olarsa, 8^x + 8^(−x) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "711", "B": "756", "C": "703", "D": "702", "E": "729"}'::jsonb, 'D', NULL, '(2^x + 2^(−x))² = 4^x + 4^(−x) + 2 = 81, deməli 2^x + 2^(−x) = 9. 8^x + 8^(−x) = (2^x + 2^(−x))³ − 3(2^x + 2^(−x)) = 729 − 27 = 702.');
INSERT INTO public.questions VALUES (7813, 99, 'g11-num-pow-q2-13', 2, 13, 'hard', 'single', 'a = 2^34, b = 3^22, c = 5^14. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "a < b < c", "B": "a < c < b", "C": "c < b < a", "D": "c < a < b", "E": "b < a < c"}'::jsonb, 'D', NULL, 'Ortaq üstə gətirin və ya loqarifmləri müqayisə edin: 34·lg2 ≈ 10,24, 22·lg3 ≈ 10,50, 14·lg5 ≈ 9,79. Ardıcıllıq: c < a < b.');
INSERT INTO public.questions VALUES (7814, 99, 'g11-num-pow-q2-14', 2, 14, 'hard', 'open', '2^17 · 5^17 · 3^2 ədədi neçə rəqəmlidir?', NULL, NULL, NULL, NULL, '18', '2^17·5^17 = 10^17. Qalan vuruq: 9 (1 rəqəmli). Cəmi 17 + 1 = 18 rəqəm.');
INSERT INTO public.questions VALUES (7815, 99, 'g11-num-pow-q2-15', 2, 15, 'hard', 'single', 'Tənliyi həll edin: 2^(x+1) + 4·2^(x−3) = 320', NULL, NULL, '{"A": "6", "B": "9", "C": "4", "D": "8", "E": "7"}'::jsonb, 'E', NULL, '2^x mötərizə xaricinə: 2^x·(1·2^1 + 4/2^3) = 320, 2^x·5/2 = 320, 2^x = 128, x = 7.');
INSERT INTO public.questions VALUES (7816, 99, 'g11-num-pow-q2-16', 2, 16, 'hard', 'single', '4^x + 4^(−x) = 34 və x > 0 olarsa, 8^x + 8^(−x) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "198", "B": "199", "C": "216", "D": "234", "E": "204"}'::jsonb, 'A', NULL, '(2^x + 2^(−x))² = 4^x + 4^(−x) + 2 = 36, deməli 2^x + 2^(−x) = 6. 8^x + 8^(−x) = (2^x + 2^(−x))³ − 3(2^x + 2^(−x)) = 216 − 18 = 198.');
INSERT INTO public.questions VALUES (7817, 99, 'g11-num-pow-q2-17', 2, 17, 'hard', 'single', 'a = 2^33, b = 3^17, c = 5^11. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < a < b", "B": "a < c < b", "C": "b < a < c", "D": "c < b < a", "E": "b < c < a"}'::jsonb, 'D', NULL, 'Ortaq üstə gətirin və ya loqarifmləri müqayisə edin: 33·lg2 ≈ 9,93, 17·lg3 ≈ 8,11, 11·lg5 ≈ 7,69. Ardıcıllıq: c < b < a.');
