INSERT INTO public.questions VALUES (7823, 99, 'g11-num-pow-q3-03', 3, 3, 'hard', 'single', 'Tənliyi həll edin: 2·2^(x+3) + 5·2^(x−1) = 37', NULL, NULL, '{"A": "4", "B": "0", "C": "1", "D": "3", "E": "2"}'::jsonb, 'C', NULL, '2^x mötərizə xaricinə: 2^x·(2·2^3 + 5/2^1) = 37, 2^x·37/2 = 37, 2^x = 2, x = 1.');
