INSERT INTO public.questions VALUES (7826, 99, 'g11-num-pow-q3-06', 3, 6, 'hard', 'single', '4^x + 4^(−x) = 7 olarsa, 16^x + 16^(−x) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "51", "B": "49", "C": "14", "D": "47", "E": "45"}'::jsonb, 'D', NULL, '16^x + 16^(−x) = (4^x + 4^(−x))² − 2 = 7² − 2 = 47.');
