INSERT INTO public.questions VALUES (7832, 99, 'g11-num-pow-q3-12', 3, 12, 'hard', 'single', '9^x − 90·3^x + 729 = 0 tənliyinin köklərinin hasilini tapın.', NULL, NULL, '{"A": "9", "B": "7", "C": "8", "D": "90", "E": "729"}'::jsonb, 'C', NULL, 't = 3^x > 0: t² − 90t + 729 = 0, t₁ = 81, t₂ = 9. x₁ = 4, x₂ = 2; hasil: 8.');
INSERT INTO public.questions VALUES (7833, 99, 'g11-num-pow-q3-13', 3, 13, 'hard', 'single', '9^x − 10·3^x + 9 = 0 tənliyinin köklərinin hasilini tapın.', NULL, NULL, '{"A": "1", "B": "10", "C": "−1", "D": "0", "E": "9"}'::jsonb, 'D', NULL, 't = 3^x > 0: t² − 10t + 9 = 0, t₁ = 1, t₂ = 9. x₁ = 0, x₂ = 2; hasil: 0.');
INSERT INTO public.questions VALUES (7834, 99, 'g11-num-pow-q3-14', 3, 14, 'hard', 'open', 'Tənliyi həll edin: 5·2^(x+1) + 2^(x−1) = 84', NULL, NULL, NULL, NULL, '3', '2^x mötərizə xaricinə: 2^x·(5·2^1 + 1/2^1) = 84, 2^x·21/2 = 84, 2^x = 8, x = 3.');
INSERT INTO public.questions VALUES (7835, 99, 'g11-num-pow-q3-15', 3, 15, 'hard', 'single', '4^x + 4^(−x) = 7 və x > 0 olarsa, 8^x + 8^(−x) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "21", "B": "36", "C": "18", "D": "27", "E": "19"}'::jsonb, 'C', NULL, '(2^x + 2^(−x))² = 4^x + 4^(−x) + 2 = 9, deməli 2^x + 2^(−x) = 3. 8^x + 8^(−x) = (2^x + 2^(−x))³ − 3(2^x + 2^(−x)) = 27 − 9 = 18.');
INSERT INTO public.questions VALUES (7836, 99, 'g11-num-pow-q3-16', 3, 16, 'hard', 'single', '2^12 · 5^41 · 3^4 ədədi neçə rəqəmlidir?', NULL, NULL, '{"A": "34", "B": "37", "C": "36", "D": "12", "E": "35"}'::jsonb, 'E', NULL, '2^12·5^12 = 10^12. Qalan vuruq: 15087425708770751953125 (23 rəqəmli). Cəmi 12 + 23 = 35 rəqəm.');
