INSERT INTO public.questions VALUES (7838, 99, 'g11-num-pow-q3-18', 3, 18, 'hard', 'single', 'a = 2^54, b = 3^30, c = 5^20. Ədədləri artan sırada düzün.', NULL, NULL, '{"A": "c < b < a", "B": "b < a < c", "C": "c < a < b", "D": "a < c < b", "E": "b < c < a"}'::jsonb, 'A', NULL, 'Ortaq üstə gətirin və ya loqarifmləri müqayisə edin: 54·lg2 ≈ 16,26, 30·lg3 ≈ 14,31, 20·lg5 ≈ 13,98. Ardıcıllıq: c < b < a.');
INSERT INTO public.questions VALUES (7839, 99, 'g11-num-pow-q3-19', 3, 19, 'hard', 'single', '2^13 · 5^27 · 3^3 ədədi neçə rəqəmlidir?', NULL, NULL, '{"A": "24", "B": "27", "C": "25", "D": "26", "E": "13"}'::jsonb, 'C', NULL, '2^13·5^13 = 10^13. Qalan vuruq: 164794921875 (12 rəqəmli). Cəmi 13 + 12 = 25 rəqəm.');
