INSERT INTO public.questions VALUES (7841, 100, 'g11-num-abs-q1-01', 1, 1, 'hard', 'single', '|x − 3| = −(3/2)x − 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "8", "B": "−7", "C": "−36/5", "D": "−9", "E": "−8"}'::jsonb, 'E', NULL, 'x ≥ 3: x − 3 = −(3/2)x − 1; x < 3: −(x − 3) = −(3/2)x − 1. Şərti ödəyən köklər: −8. Cəm: −8.');
INSERT INTO public.questions VALUES (7842, 100, 'g11-num-abs-q1-02', 1, 2, 'hard', 'single', 'f(x) = |x + 7| + |x + 3| + |x − 4| + |x − 6| funksiyasının ən kiçik qiymətini tapın.', NULL, NULL, '{"A": "22", "B": "19", "C": "20", "D": "21", "E": "13"}'::jsonb, 'C', NULL, 'Modulların cəminin minimumu medianda (orta nöqtələr arasında) alınır: (6 − (−7)) + (4 − (−3)) = 20.');
INSERT INTO public.questions VALUES (7843, 100, 'g11-num-abs-q1-03', 1, 3, 'hard', 'single', '|x + 3| = (3/2)x − 1 tənliyinin köklərinin cəmini tapın.', NULL, NULL, '{"A": "8", "B": "36/5", "C": "7", "D": "−8", "E": "9"}'::jsonb, 'A', NULL, 'x ≥ −3: x + 3 = (3/2)x − 1; x < −3: −(x + 3) = (3/2)x − 1. Şərti ödəyən köklər: 8. Cəm: 8.');
INSERT INTO public.questions VALUES (7844, 100, 'g11-num-abs-q1-04', 1, 4, 'hard', 'single', '|x² − 14x| = 39 tənliyinin bütün həqiqi köklərinin cəmini tapın.', NULL, NULL, '{"A": "28", "B": "42", "C": "56", "D": "0", "E": "14"}'::jsonb, 'A', NULL, 'x² − 14x = 39 — diskriminant müsbətdir, 2 kök (cəmi 14). x² − 14x = −39: D/4 = 49 − 39 > 0, daha 2 kök (cəmi 14).');
INSERT INTO public.questions VALUES (7845, 100, 'g11-num-abs-q1-05', 1, 5, 'hard', 'single', 'f(x) = |x| + |x − 5| + |x − 6| + |x − 12| funksiyasının ən kiçik qiymətini tapın.', NULL, NULL, '{"A": "14", "B": "13", "C": "15", "D": "23", "E": "12"}'::jsonb, 'B', NULL, 'Modulların cəminin minimumu medianda (orta nöqtələr arasında) alınır: (12 − 0) + (6 − 5) = 13.');
INSERT INTO public.questions VALUES (7846, 100, 'g11-num-abs-q1-06', 1, 6, 'hard', 'single', '||x − 1| − 3| ≤ 8 bərabərsizliyinin tam həllərinin cəmini tapın.', NULL, NULL, '{"A": "20", "B": "24", "C": "23", "D": "26", "E": "22"}'::jsonb, 'C', NULL, 't = |x − 1| ≥ 0: |t − 3| ≤ 8 ⇒ 0 ≤ t ≤ 11. Hər t > 0 üçün iki həll x = 1 ± t (cəmi 2), t = 0 üçün bir həll x = 1. Cəm: 23.');
INSERT INTO public.questions VALUES (7847, 100, 'g11-num-abs-q1-07', 1, 7, 'hard', 'open', '|x − 7| + |x − 6| = 5 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, NULL, NULL, '97', 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = 4, x₂ = 9 (aralıqda ifadə sabitdir və 1 ≠ 5). Cavab: 97.');
INSERT INTO public.questions VALUES (7848, 100, 'g11-num-abs-q1-08', 1, 8, 'hard', 'single', '|x² − 10x| = 33 tənliyinin bütün həqiqi köklərinin cəmini tapın.', NULL, NULL, '{"A": "−10", "B": "30", "C": "0", "D": "20", "E": "10"}'::jsonb, 'E', NULL, 'x² − 10x = 33 — diskriminant müsbətdir, 2 kök (cəmi 10). x² − 10x = −33: D/4 = 25 − 33 < 0, kök yoxdur.');
INSERT INTO public.questions VALUES (7849, 100, 'g11-num-abs-q1-09', 1, 9, 'hard', 'single', 'f(x) = |x + 10| + |x + 7| + |x| + |x − 12| funksiyasının ən kiçik qiymətini tapın.', NULL, NULL, '{"A": "29", "B": "22", "C": "31", "D": "28", "E": "30"}'::jsonb, 'A', NULL, 'Modulların cəminin minimumu medianda (orta nöqtələr arasında) alınır: (12 − (−10)) + (0 − (−7)) = 29.');
