INSERT INTO public.questions VALUES (7894, 100, 'g11-num-abs-q3-14', 3, 14, 'hard', 'open', '|x + 1| = −3x + 5 tənliyinin köklərinin cəmini tapın.', NULL, NULL, NULL, NULL, '1', 'x ≥ −1: x + 1 = −3x + 5; x < −1: −(x + 1) = −3x + 5. Şərti ödəyən köklər: 1. Cəm: 1.');
INSERT INTO public.questions VALUES (7895, 100, 'g11-num-abs-q3-15', 3, 15, 'hard', 'single', '|x − 4| + |x + 5| = 15 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "112", "B": "1", "C": "143", "D": "113", "E": "−56"}'::jsonb, 'D', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −8, x₂ = 7 (aralıqda ifadə sabitdir və 9 ≠ 15). Cavab: 113.');
INSERT INTO public.questions VALUES (7896, 100, 'g11-num-abs-q3-16', 3, 16, 'hard', 'single', 'f(x) = |x + 11| + |x + 6| + |x − 1| + |x − 13| funksiyasının ən kiçik qiymətini tapın.', NULL, NULL, '{"A": "30", "B": "31", "C": "32", "D": "24", "E": "33"}'::jsonb, 'B', NULL, 'Modulların cəminin minimumu medianda (orta nöqtələr arasında) alınır: (13 − (−11)) + (1 − (−6)) = 31.');
INSERT INTO public.questions VALUES (7897, 100, 'g11-num-abs-q3-17', 3, 17, 'hard', 'single', '|x − 8| + |x − 7| = 9 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "152", "B": "36", "C": "153", "D": "171", "E": "225"}'::jsonb, 'C', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = 3, x₂ = 12 (aralıqda ifadə sabitdir və 1 ≠ 9). Cavab: 153.');
INSERT INTO public.questions VALUES (7898, 100, 'g11-num-abs-q3-18', 3, 18, 'hard', 'single', '|x + 7| + |x + 2| = 13 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "125", "B": "151", "C": "81", "D": "−22", "E": "124"}'::jsonb, 'A', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −11, x₂ = 2 (aralıqda ifadə sabitdir və 5 ≠ 13). Cavab: 125.');
INSERT INTO public.questions VALUES (7899, 100, 'g11-num-abs-q3-19', 3, 19, 'hard', 'single', '|x + 6| + |x − 1| = 15 tənliyinin köklərinin kvadratlarının cəmini tapın.', NULL, NULL, '{"A": "125", "B": "155", "C": "25", "D": "124", "E": "−50"}'::jsonb, 'A', NULL, 'Kökləri x ≤ min və x ≥ max hissələrində axtarın: x₁ = −10, x₂ = 5 (aralıqda ifadə sabitdir və 7 ≠ 15). Cavab: 125.');
INSERT INTO public.questions VALUES (7900, 100, 'g11-num-abs-q3-20', 3, 20, 'hard', 'single', '|x² − 2x| = 14 tənliyinin bütün həqiqi köklərinin cəmini tapın.', NULL, NULL, '{"A": "0", "B": "6", "C": "4", "D": "2", "E": "−2"}'::jsonb, 'D', NULL, 'x² − 2x = 14 — diskriminant müsbətdir, 2 kök (cəmi 2). x² − 2x = −14: D/4 = 1 − 14 < 0, kök yoxdur.');
INSERT INTO public.questions VALUES (7901, 101, 'g11-num-pct-q1-01', 1, 1, 'hard', 'single', 'İşçinin maaşı iki dəfə eyni faizlə artırıldı və 5400 manatdan 12150 manata çatdı. Maaş hər dəfə neçə faiz artırılmışdı?', NULL, NULL, '{"A": "100%", "B": "55%", "C": "50%", "D": "45%", "E": "62,5%"}'::jsonb, 'C', NULL, '5400·(1 + x)² = 12150 ⇒ (1 + x)² = 9/4 ⇒ 1 + x = 1,5, x = 50%.');
INSERT INTO public.questions VALUES (7902, 101, 'g11-num-pct-q1-02', 1, 2, 'hard', 'single', 'İşçinin maaşı iki dəfə eyni faizlə artırıldı və 400 manatdan 1024 manata çatdı. Maaş hər dəfə neçə faiz artırılmışdı?', NULL, NULL, '{"A": "65%", "B": "120%", "C": "78%", "D": "60%", "E": "55%"}'::jsonb, 'D', NULL, '400·(1 + x)² = 1024 ⇒ (1 + x)² = 64/25 ⇒ 1 + x = 1,6, x = 60%.');
INSERT INTO public.questions VALUES (7903, 101, 'g11-num-pct-q1-03', 1, 3, 'hard', 'single', 'A ədədi B-dən 20% çox, B ədədi isə C-dən 25% azdır. A ədədi C-dən neçə faiz azdır?', NULL, NULL, '{"A": "5%", "B": "10%", "C": "9%", "D": "15%", "E": "12%"}'::jsonb, 'B', NULL, 'A = 1,2·B = 1,2·0,75·C = 0,9·C. Fərq: 10%.');
