INSERT INTO public.questions VALUES (7906, 101, 'g11-num-pct-q1-06', 1, 6, 'hard', 'single', 'Bankda illik 50% mürəkkəb faizlə əmanət qoyuldu. Birinci ilin sonunda faiz hesablandıqdan sonra əmanətdən 1600 manat götürüldü. İkinci ilin sonunda hesabda 9300 manat oldu. İlkin əmanət neçə manat idi?', NULL, NULL, '{"A": "5100", "B": "5200", "C": "5733", "D": "4133", "E": "5300"}'::jsonb, 'B', NULL, 'Tərsinə: 9300 : 1,5 = 6200; + 1600 = 7800; : 1,5 = 5200.');
