INSERT INTO public.questions VALUES (8181, 105, 'g11-alg-prog-q3-01', 3, 1, 'hard', 'single', 'Artan ədədi silsilənin üç ardıcıl həddinin cəmi 15-dir. Bu hədlərə uyğun olaraq 2, 1 və 1 əlavə etsək, həndəsi silsilə alınır. Ədədi silsilənin ən böyük həddini tapın.', NULL, NULL, '{"A": "2", "B": "9", "C": "7", "D": "5", "E": "8"}'::jsonb, 'E', NULL, 'Hədlər x − d, x, x + d; 3x = 15 ⇒ x = 5. (x − d + 2)(x + d + 1) = (x + 1)² ⇒ d = 3 (d > 0). Ən böyük hədd: 5 + 3 = 8.');
INSERT INTO public.questions VALUES (8182, 105, 'g11-alg-prog-q3-02', 3, 2, 'hard', 'single', 'Ardıcıllıq a₁ = −3 və aₙ₊₁ = 2·aₙ + 5 qaydası ilə verilib. a₇ həddini tapın.', NULL, NULL, '{"A": "59", "B": "251", "C": "128", "D": "118", "E": "123"}'::jsonb, 'E', NULL, 'Hədləri ardıcıl hesablayın (və ya aₙ + 5 = (a₁ + 5)·2ⁿ⁻¹ ilə): a₇ = 123.');
