INSERT INTO public.questions VALUES (8184, 105, 'g11-alg-prog-q3-04', 3, 4, 'hard', 'single', 'Sonsuz azalan həndəsi silsilənin hədlərinin cəmi −30/7, hədlərin kvadratlarının cəmi isə 180/7-dir. Silsilənin vuruğunu (q) tapın.', NULL, NULL, '{"A": "1/36", "B": "−1/3", "C": "1/6", "D": "−1/6", "E": "5/6"}'::jsonb, 'D', NULL, 'b₁/(1 − q) = −30/7, b₁²/(1 − q²) = 180/7. Bölsək: b₁/(1 + q) = −6. İki tənlikdən q = −1/6, b₁ = −5.');
