INSERT INTO public.questions VALUES (8199, 105, 'g11-alg-prog-q3-19', 3, 19, 'hard', 'single', 'aₙ = n² − 20n − 13 ardıcıllığının ən kiçik həddini tapın.', NULL, NULL, '{"A": "−111", "B": "−114", "C": "−113", "D": "−115", "E": "−112"}'::jsonb, 'C', NULL, 'Parabolanın təpəsi n = 10. Ən yaxın natural n: 10. Ən kiçik hədd: −113.');
