INSERT INTO public.questions VALUES (8201, 106, 'g11-alg-func-q1-01', 1, 1, 'hard', 'single', 'Bütün x üçün 3·f(x) + f(1 − x) = −3x − 4 bərabərliyi doğrudur. f(−2) qiymətini tapın.', NULL, NULL, '{"A": "2/3", "B": "1/2", "C": "−41/8", "D": "−19/8", "E": "19/8"}'::jsonb, 'E', NULL, 'x = −2 və x = 3 qoyun: 3f(−2) + f(3) = 2, 3f(3) + f(−2) = −13. Sistemdən f(−2) = 19/8.');
INSERT INTO public.questions VALUES (8202, 106, 'g11-alg-func-q1-02', 1, 2, 'hard', 'single', 'f(x) = 2x² − 6x + 5 funksiyasının [−5; −1] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "71", "B": "72", "C": "1/2", "D": "85", "E": "73"}'::jsonb, 'B', NULL, 'Təpə x₀ = 3/2 (parçadan kənardadır). Qiymətlər: f(−5) = 85, f(−1) = 13. Fərq: 72.');
INSERT INTO public.questions VALUES (8203, 106, 'g11-alg-func-q1-03', 1, 3, 'hard', 'single', 'f(x) = (4x + 8)/(x + 1) funksiyası üçün f⁻¹(−3) qiymətini tapın.', NULL, NULL, '{"A": "2", "B": "11/7", "C": "−5/7", "D": "−11/7", "E": "−7/11"}'::jsonb, 'D', NULL, 'f(x) = −3 tənliyini həll edin: 4x + 8 = −3(x + 1) ⇒ x = −11/7.');
INSERT INTO public.questions VALUES (8204, 106, 'g11-alg-func-q1-04', 1, 4, 'hard', 'single', 'f(x) = 2x² + 4x + 2 funksiyasının [−6; 2] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "51", "B": "32", "C": "49", "D": "50", "E": "0"}'::jsonb, 'D', NULL, 'Təpə x₀ = −1 (parçaya düşür). Qiymətlər: f(−6) = 50, f(2) = 18, f(−1) = 0. Fərq: 50.');
INSERT INTO public.questions VALUES (8205, 106, 'g11-alg-func-q1-05', 1, 5, 'hard', 'single', 'f(x) = −x² + 8x − 4 funksiyasının [2; 6] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "3", "B": "0", "C": "4", "D": "5", "E": "12"}'::jsonb, 'C', NULL, 'Təpə x₀ = 4 (parçaya düşür). Qiymətlər: f(2) = 8, f(6) = 8, f(4) = 12. Fərq: 4.');
INSERT INTO public.questions VALUES (8206, 106, 'g11-alg-func-q1-06', 1, 6, 'hard', 'single', 'Bütün x üçün 2·f(x) + f(1 − x) = 5x + 4 bərabərliyi doğrudur. f(8) qiymətini tapın.', NULL, NULL, '{"A": "22", "B": "119/3", "C": "−106/3", "D": "−119/3", "E": "44/3"}'::jsonb, 'B', NULL, 'x = 8 və x = −7 qoyun: 2f(8) + f(−7) = 44, 2f(−7) + f(8) = −31. Sistemdən f(8) = 119/3.');
INSERT INTO public.questions VALUES (8207, 106, 'g11-alg-func-q1-07', 1, 7, 'hard', 'open', 'y = x² − 5x + 1 parabolası ilə y = 2x − 9 düz xəttinin kəsişmə nöqtələrinin ordinatlarının cəmini tapın.', NULL, NULL, NULL, NULL, '−4', 'x² − 7x + 10 = 0 ⇒ x₁ = 2, x₂ = 5; y = 2x − 9: y₁ = −5, y₂ = 1. Cavab: −4.');
INSERT INTO public.questions VALUES (8208, 106, 'g11-alg-func-q1-08', 1, 8, 'hard', 'single', 'f(x) tək funksiyadır, əsas dövrü 4-dür və [0; 2] parçasında f(x) = −x(x − 2). f(57) qiymətini tapın.', NULL, NULL, '{"A": "2", "B": "−3135", "C": "0", "D": "−1", "E": "1"}'::jsonb, 'E', NULL, 'Dövrə görə 57 ədədini [−2; 2] aralığına gətirin, mənfi arqument üçün f(−x) = −f(x) istifadə edin. Nəticə: 1.');
INSERT INTO public.questions VALUES (8209, 106, 'g11-alg-func-q1-09', 1, 9, 'hard', 'single', 'Bütün x üçün 2·f(x) + f(1 − x) = 3x + 5 bərabərliyi doğrudur. f(3) qiymətini tapın.', NULL, NULL, '{"A": "7", "B": "14/3", "C": "29/3", "D": "−16/3", "E": "−29/3"}'::jsonb, 'C', NULL, 'x = 3 və x = −2 qoyun: 2f(3) + f(−2) = 14, 2f(−2) + f(3) = −1. Sistemdən f(3) = 29/3.');
