INSERT INTO public.questions VALUES (8211, 106, 'g11-alg-func-q1-11', 1, 11, 'hard', 'single', 'y = x² + 6x − 8 parabolası ilə y = 5x − 6 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−1", "B": "−2", "C": "3", "D": "2", "E": "−3"}'::jsonb, 'B', NULL, 'x² + x − 2 = 0 ⇒ x₁ = −2, x₂ = 1; y = 5x − 6: y₁ = −16, y₂ = −1. Cavab: −2.');
