INSERT INTO public.questions VALUES (8239, 106, 'g11-alg-func-q2-19', 2, 19, 'hard', 'single', 'f(x) tək funksiyadır, əsas dövrü 4-dür və [0; 2] parçasında f(x) = 3x(x − 2). f(129/2) qiymətini tapın.', NULL, NULL, '{"A": "−5/4", "B": "9/4", "C": "−9/4", "D": "48375/4", "E": "−9/2"}'::jsonb, 'C', NULL, 'Dövrə görə 129/2 ədədini [−2; 2] aralığına gətirin, mənfi arqument üçün f(−x) = −f(x) istifadə edin. Nəticə: −9/4.');
INSERT INTO public.questions VALUES (8240, 106, 'g11-alg-func-q2-20', 2, 20, 'hard', 'single', 'f(x) = x² − 2x + 3 funksiyasının [−4; 2] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "27", "B": "24", "C": "25", "D": "26", "E": "2"}'::jsonb, 'C', NULL, 'Təpə x₀ = 1 (parçaya düşür). Qiymətlər: f(−4) = 27, f(2) = 3, f(1) = 2. Fərq: 25.');
INSERT INTO public.questions VALUES (8241, 106, 'g11-alg-func-q3-01', 3, 1, 'hard', 'single', 'f(x) tək funksiyadır, əsas dövrü 4-dür və [0; 2] parçasında f(x) = 3x(x − 2). f(787/3) qiymətini tapın.', NULL, NULL, '{"A": "−5/3", "B": "10/3", "C": "614647/3", "D": "5/3", "E": "8/3"}'::jsonb, 'D', NULL, 'Dövrə görə 787/3 ədədini [−2; 2] aralığına gətirin, mənfi arqument üçün f(−x) = −f(x) istifadə edin. Nəticə: 5/3.');
INSERT INTO public.questions VALUES (8242, 106, 'g11-alg-func-q3-02', 3, 2, 'hard', 'single', 'f(x) = (2x − 7)/(2x − 6) funksiyası üçün f⁻¹(−6) qiymətini tapın.', NULL, NULL, '{"A": "43/14", "B": "19/18", "C": "14/43", "D": "−29/14", "E": "−43/14"}'::jsonb, 'A', NULL, 'f(x) = −6 tənliyini həll edin: 2x − 7 = −6(2x − 6) ⇒ x = 43/14.');
INSERT INTO public.questions VALUES (8243, 106, 'g11-alg-func-q3-03', 3, 3, 'hard', 'single', 'f(x) = −x² − 3x + 8 funksiyasının [1; 6] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "51", "B": "41/4", "C": "4", "D": "50", "E": "49"}'::jsonb, 'D', NULL, 'Təpə x₀ = −3/2 (parçadan kənardadır). Qiymətlər: f(1) = 4, f(6) = −46. Fərq: 50.');
INSERT INTO public.questions VALUES (8244, 106, 'g11-alg-func-q3-04', 3, 4, 'hard', 'single', 'Bütün x üçün (-2)·f(x) + f(1 − x) = −3x + 1 bərabərliyi doğrudur. f(5) qiymətini tapın.', NULL, NULL, '{"A": "7", "B": "14", "C": "−5", "D": "5", "E": "−4"}'::jsonb, 'D', NULL, 'x = 5 və x = −4 qoyun: -2f(5) + f(−4) = −14, -2f(−4) + f(5) = 13. Sistemdən f(5) = 5.');
INSERT INTO public.questions VALUES (8245, 106, 'g11-alg-func-q3-05', 3, 5, 'hard', 'single', 'Bütün x üçün 3·f(x) + f(1 − x) = 6x − 4 bərabərliyi doğrudur. f(−5) qiymətini tapın.', NULL, NULL, '{"A": "67/4", "B": "−67/4", "C": "−17/2", "D": "−34/3", "E": "65/4"}'::jsonb, 'B', NULL, 'x = −5 və x = 6 qoyun: 3f(−5) + f(6) = −34, 3f(6) + f(−5) = 32. Sistemdən f(−5) = −67/4.');
INSERT INTO public.questions VALUES (8246, 106, 'g11-alg-func-q3-06', 3, 6, 'hard', 'single', 'f(x) = −x² − 7x + 7 funksiyasının [−3; 4] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "55", "B": "77/4", "C": "57", "D": "56", "E": "19"}'::jsonb, 'D', NULL, 'Təpə x₀ = −7/2 (parçadan kənardadır). Qiymətlər: f(−3) = 19, f(4) = −37. Fərq: 56.');
INSERT INTO public.questions VALUES (8247, 106, 'g11-alg-func-q3-07', 3, 7, 'hard', 'open', 'y = x² + 2x + 3 parabolası ilə y = −3x − 1 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, NULL, NULL, '4', 'x² + 5x + 4 = 0 ⇒ x₁ = −4, x₂ = −1; y = −3x − 1: y₁ = 11, y₂ = 2. Cavab: 4.');
INSERT INTO public.questions VALUES (8248, 106, 'g11-alg-func-q3-08', 3, 8, 'hard', 'single', 'y = x² + 6x + 1 parabolası ilə y = −4 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "6", "B": "4", "C": "−5", "D": "−6", "E": "5"}'::jsonb, 'E', NULL, 'x² + 6x + 5 = 0 ⇒ x₁ = −5, x₂ = −1; y = −4: y₁ = −4, y₂ = −4. Cavab: 5.');
INSERT INTO public.questions VALUES (8249, 106, 'g11-alg-func-q3-09', 3, 9, 'hard', 'single', 'f(x) = 2x² − 7x − 4 funksiyasının [−3; 0] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "35", "B": "39", "C": "38", "D": "81/8", "E": "40"}'::jsonb, 'B', NULL, 'Təpə x₀ = 7/4 (parçadan kənardadır). Qiymətlər: f(−3) = 35, f(0) = −4. Fərq: 39.');
INSERT INTO public.questions VALUES (8250, 106, 'g11-alg-func-q3-10', 3, 10, 'hard', 'single', 'y = x² + 5x + 6 parabolası ilə y = 6 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−5", "B": "1", "C": "2", "D": "−1", "E": "0"}'::jsonb, 'E', NULL, 'x² + 5x = 0 ⇒ x₁ = −5, x₂ = 0; y = 6: y₁ = 6, y₂ = 6. Cavab: 0.');
INSERT INTO public.questions VALUES (8251, 106, 'g11-alg-func-q3-11', 3, 11, 'hard', 'single', 'f(x) = (−4x − 9)/(x − 6) funksiyası üçün f⁻¹(−8) qiymətini tapın.', NULL, NULL, '{"A": "−57/4", "B": "4/57", "C": "57/4", "D": "−39/4", "E": "−23/14"}'::jsonb, 'C', NULL, 'f(x) = −8 tənliyini həll edin: −4x − 9 = −8(x − 6) ⇒ x = 57/4.');
INSERT INTO public.questions VALUES (8252, 106, 'g11-alg-func-q3-12', 3, 12, 'hard', 'single', 'f(x) = (−x + 5)/(x − 2) funksiyası üçün f⁻¹(2) qiymətini tapın.', NULL, NULL, '{"A": "4", "B": "1/3", "C": "3", "D": "2", "E": "−3"}'::jsonb, 'C', NULL, 'f(x) = 2 tənliyini həll edin: −x + 5 = 2(x − 2) ⇒ x = 3.');
INSERT INTO public.questions VALUES (8253, 106, 'g11-alg-func-q3-13', 3, 13, 'hard', 'single', 'Bütün x üçün (-2)·f(x) + f(1 − x) = −5x + 6 bərabərliyi doğrudur. f(0) qiymətini tapın.', NULL, NULL, '{"A": "−8/3", "B": "−13/3", "C": "13/3", "D": "−3", "E": "−6"}'::jsonb, 'B', NULL, 'x = 0 və x = 1 qoyun: -2f(0) + f(1) = 6, -2f(1) + f(0) = 1. Sistemdən f(0) = −13/3.');
INSERT INTO public.questions VALUES (8254, 106, 'g11-alg-func-q3-14', 3, 14, 'hard', 'open', 'f(x) tək funksiyadır, əsas dövrü 4-dür və [0; 2] parçasında f(x) = 3x(x − 2). f(555/2) qiymətini tapın.', NULL, NULL, NULL, NULL, '−9/4', 'Dövrə görə 555/2 ədədini [−2; 2] aralığına gətirin, mənfi arqument üçün f(−x) = −f(x) istifadə edin. Nəticə: −9/4.');
INSERT INTO public.questions VALUES (8255, 106, 'g11-alg-func-q3-15', 3, 15, 'hard', 'single', 'f(x) tək funksiyadır, əsas dövrü 4-dür və [0; 2] parçasında f(x) = x(x − 2). f(509/2) qiymətini tapın.', NULL, NULL, '{"A": "7/4", "B": "3/2", "C": "−3/4", "D": "257045/4", "E": "3/4"}'::jsonb, 'E', NULL, 'Dövrə görə 509/2 ədədini [−2; 2] aralığına gətirin, mənfi arqument üçün f(−x) = −f(x) istifadə edin. Nəticə: 3/4.');
INSERT INTO public.questions VALUES (8256, 106, 'g11-alg-func-q3-16', 3, 16, 'hard', 'single', 'y = x² + 2x + 1 parabolası ilə y = 2x + 2 düz xəttinin kəsişmə nöqtələrinin absislərinin hasilini tapın.', NULL, NULL, '{"A": "−3", "B": "−2", "C": "0", "D": "−1", "E": "1"}'::jsonb, 'D', NULL, 'x² − 1 = 0 ⇒ x₁ = −1, x₂ = 1; y = 2x + 2: y₁ = 0, y₂ = 4. Cavab: −1.');
INSERT INTO public.questions VALUES (8257, 106, 'g11-alg-func-q3-17', 3, 17, 'hard', 'single', 'f(x) = (6x − 4)/(x + 5) funksiyası üçün f⁻¹(−3) qiymətini tapın.', NULL, NULL, '{"A": "19/9", "B": "−9/11", "C": "11/9", "D": "−11", "E": "−11/9"}'::jsonb, 'E', NULL, 'f(x) = −3 tənliyini həll edin: 6x − 4 = −3(x + 5) ⇒ x = −11/9.');
INSERT INTO public.questions VALUES (8258, 106, 'g11-alg-func-q3-18', 3, 18, 'hard', 'single', 'Bütün x üçün 3·f(x) + f(1 − x) = −3x + 9 bərabərliyi doğrudur. f(3) qiymətini tapın.', NULL, NULL, '{"A": "−15/8", "B": "−7/8", "C": "0", "D": "15/8", "E": "45/8"}'::jsonb, 'A', NULL, 'x = 3 və x = −2 qoyun: 3f(3) + f(−2) = 0, 3f(−2) + f(3) = 15. Sistemdən f(3) = −15/8.');
INSERT INTO public.questions VALUES (8259, 106, 'g11-alg-func-q3-19', 3, 19, 'hard', 'single', 'f(x) = −x² + 6x + 6 funksiyasının [−1; 6] parçasında ən böyük və ən kiçik qiymətlərinin fərqini tapın.', NULL, NULL, '{"A": "7", "B": "18", "C": "16", "D": "15", "E": "17"}'::jsonb, 'C', NULL, 'Təpə x₀ = 3 (parçaya düşür). Qiymətlər: f(−1) = −1, f(6) = 6, f(3) = 15. Fərq: 16.');
INSERT INTO public.questions VALUES (8260, 106, 'g11-alg-func-q3-20', 3, 20, 'hard', 'single', 'f(x) tək funksiyadır, əsas dövrü 6-dır və [0; 3] parçasında f(x) = −x(x − 3). f(−345/2) qiymətini tapın.', NULL, NULL, '{"A": "9/4", "B": "9/2", "C": "−121095/4", "D": "−9/4", "E": "13/4"}'::jsonb, 'A', NULL, 'Dövrə görə −345/2 ədədini [−3; 3] aralığına gətirin, mənfi arqument üçün f(−x) = −f(x) istifadə edin. Nəticə: 9/4.');
INSERT INTO public.questions VALUES (8261, 107, 'g11-geo-basic-q1-01', 1, 1, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 10, AM medianı isə √417/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="39.8,186.0 280.2,186.0 145.1,34.0"/><text x="27.9" y="196.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.2" y="195.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="143.8" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="161.2" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="81.3" y="110.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="39.8" y1="186.0" x2="212.6" y2="110.0" stroke-dasharray="5 4"/><text x="224.5" y="109.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="114.6" y="150.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√417/2</text></svg>', '{"A": "√1735/2", "B": "√269", "C": "√538/2", "D": "11", "E": "12"}'::jsonb, 'D', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 338 + 200 − 417 = 121, BC = 11.');
INSERT INTO public.questions VALUES (8262, 107, 'g11-geo-basic-q1-02', 1, 2, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 10, BC = 10. Daxilə və xaricə çəkilmiş çevrələrin radiuslarının hasilini (r·R) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="46.0,186.0 274.0,186.0 160.0,34.0"/><text x="34.1" y="196.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="285.9" y="196.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="92.0" y="110.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="228.0" y="110.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "19", "B": "75/4", "C": "75/2", "D": "79/4", "E": "37/4"}'::jsonb, 'B', NULL, 'p = 16, S = √(p(p − a)(p − b)(p − c)) = 48. r = S/p = 3, R = abc/(4S) = 25/4. r·R = 75/4.');
INSERT INTO public.questions VALUES (8263, 107, 'g11-geo-basic-q1-03', 1, 3, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 13, BC = 8. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,129.5 286.0,129.5 193.1,90.5"/><text x="21.1" y="135.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="136.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="201.5" y="85.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="152.2" y="143.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="101.6" y="113.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="251.5" y="113.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><line x1="34.0" y1="129.5" x2="229.7" y2="105.9" stroke-dasharray="5 4"/><text x="242.6" y="109.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√1074/2", "B": "10√2665/33", "C": "7√5461/33", "D": "2√61", "E": "2√65"}'::jsonb, 'B', NULL, 'BD = 160/33, DC = 104/33. AD² = AB·AC − BD·DC = 260 − 16640/1089 = 266500/1089 ⇒ AD = 10√2665/33.');
INSERT INTO public.questions VALUES (8264, 107, 'g11-geo-basic-q1-04', 1, 4, 'hard', 'single', 'ABC üçbucağında ∠A = 50°, ∠B = 106°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="162.3,186.0 205.9,186.0 228.6,107.0"/><text x="151.7" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="209.3" y="203.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="235.0" y="100.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="205.9" y1="186.0" x2="91.4" y2="34.0" stroke-dasharray="5 4"/><line x1="162.3" y1="186.0" x2="91.4" y2="34.0" stroke-dasharray="5 4"/><text x="83.6" y="28.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "78°", "B": "102°", "C": "25°", "D": "24°", "E": "12°"}'::jsonb, 'E', NULL, '∠C = 24°. ABK üçbucağında ∠KBA = 53°, ∠KAB = ∠A + (180° − ∠A)/2 = 115°. ∠AKB = 180° − 53° − 115° = ∠C/2 = 12°.');
INSERT INTO public.questions VALUES (8265, 107, 'g11-geo-basic-q1-05', 1, 5, 'hard', 'single', 'ABC üçbucağında ∠A = 40°, ∠B = 74°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.5,186.0 260.9,186.0 232.5,87.0"/><text x="102.3" y="195.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="272.2" y="197.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.8" y="80.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="260.9" y1="186.0" x2="59.1" y2="34.0" stroke-dasharray="5 4"/><line x1="114.5" y1="186.0" x2="59.1" y2="34.0" stroke-dasharray="5 4"/><text x="48.8" y="31.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "33°", "B": "66°", "C": "123°", "D": "20°", "E": "57°"}'::jsonb, 'A', NULL, '∠C = 66°. ABK üçbucağında ∠KBA = 37°, ∠KAB = ∠A + (180° − ∠A)/2 = 110°. ∠AKB = 180° − 37° − 110° = ∠C/2 = 33°.');
INSERT INTO public.questions VALUES (8266, 107, 'g11-geo-basic-q1-06', 1, 6, 'hard', 'single', 'ABC üçbucağında AB = 7, AC = 11, AM medianı isə 2√19. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,181.4 218.3,181.4 286.0,38.6"/><text x="21.6" y="190.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="226.5" y="196.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="295.7" y="35.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="117.2" y="194.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="152.4" y="105.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="34.0" y1="181.4" x2="252.1" y2="110.0" stroke-dasharray="5 4"/><text x="264.5" y="111.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="132.2" y="145.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2√19</text></svg>', '{"A": "√85", "B": "6", "C": "√170", "D": "7", "E": "2√66"}'::jsonb, 'B', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 98 + 242 − 304 = 36, BC = 6.');
INSERT INTO public.questions VALUES (8267, 107, 'g11-geo-basic-q1-07', 1, 7, 'hard', 'open', 'ABC üçbucağında AB = 14, AC = 7, AM medianı isə √409/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,144.5 286.0,144.5 139.4,75.5"/><text x="21.2" y="152.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="151.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="135.7" y="68.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="163.4" y="161.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="74.9" y="113.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><line x1="34.0" y1="144.5" x2="212.7" y2="110.0" stroke-dasharray="5 4"/><text x="225.5" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="111.4" y="131.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√409/2</text></svg>', NULL, NULL, '9', '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 392 + 98 − 409 = 81, BC = 9.');
INSERT INTO public.questions VALUES (8268, 107, 'g11-geo-basic-q1-08', 1, 8, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 4, BC = 15. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,139.3 286.0,139.3 57.1,80.7"/><text x="21.3" y="147.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="145.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="45.8" y="79.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="170.4" y="150.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="33.7" y="113.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="183.3" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><line x1="34.0" y1="139.3" x2="102.9" y2="92.4" stroke-dasharray="5 4"/><text x="113.7" y="90.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "2√7", "B": "√319/2", "C": "8", "D": "√31/2", "E": "√29"}'::jsonb, 'A', NULL, 'BD = 12, DC = 3. AD² = AB·AC − BD·DC = 64 − 36 = 28 ⇒ AD = 2√7.');
INSERT INTO public.questions VALUES (8269, 107, 'g11-geo-basic-q1-09', 1, 9, 'hard', 'single', 'ABC üçbucağında AB = 9, AC = 11, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="88.2,186.0 231.8,186.0 176.0,34.0"/><text x="77.3" y="198.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="242.1" y="198.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="177.3" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.7" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="122.5" y="107.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="88.2" y1="186.0" x2="203.9" y2="110.0" stroke-dasharray="5 4"/><path d="M106.2,186.0 A18,18 0 0 0 97.2,170.4" stroke-width="1.2"/><text x="115.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="214.7" y="107.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "13√3/2", "B": "√301/2", "C": "√103/2", "D": "√103", "E": "√101"}'::jsonb, 'B', NULL, 'Əvvəlcə BC² = 11² + 9² − 2·11·9·cos 60° = 103. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (162 + 242 − 103)/4 = 301/4 ⇒ AM = √301/2.');
INSERT INTO public.questions VALUES (8270, 107, 'g11-geo-basic-q1-10', 1, 10, 'hard', 'single', 'ABC üçbucağında ∠A = 60°, ∠B = 32°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="75.7,158.3 286.0,158.3 131.5,61.7"/><text x="63.5" y="167.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="166.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="125.5" y="55.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="286.0" y1="158.3" x2="34.0" y2="86.0" stroke-dasharray="5 4"/><line x1="75.7" y1="158.3" x2="34.0" y2="86.0" stroke-dasharray="5 4"/><text x="21.5" y="87.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "44°", "B": "88°", "C": "30°", "D": "46°", "E": "134°"}'::jsonb, 'A', NULL, '∠C = 88°. ABK üçbucağında ∠KBA = 16°, ∠KAB = ∠A + (180° − ∠A)/2 = 120°. ∠AKB = 180° − 16° − 120° = ∠C/2 = 44°.');
INSERT INTO public.questions VALUES (8271, 107, 'g11-geo-basic-q1-11', 1, 11, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = √15 və AH = 1 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,141.4 286.0,141.4 50.8,78.6"/><line x1="50.8" y1="78.6" x2="50.8" y2="141.4" stroke-dasharray="5 4"/><polyline points="60.8,141.4 60.8,131.4 50.8,131.4" stroke-width="1.2"/><polyline points="48.2,88.2 57.9,90.8 60.5,81.2" stroke-width="1.2"/><text x="21.3" y="149.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="148.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="39.5" y="77.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="50.8" y="159.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="40.8" y="158.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">1</text><text x="30.5" y="113.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√15</text></svg>', '{"A": "4√15", "B": "√197", "C": "√210", "D": "√14", "E": "√15"}'::jsonb, 'C', NULL, 'AC² = AH·AB ⇒ AB = 15/1 = 15. HB = 15 − 1 = 14. BC² = HB·AB = 14·15 ⇒ BC = √210.');
INSERT INTO public.questions VALUES (8272, 107, 'g11-geo-basic-q1-12', 1, 12, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = √161 və AH = 7 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,168.0 286.0,168.0 110.7,52.0"/><line x1="110.7" y1="52.0" x2="110.7" y2="168.0" stroke-dasharray="5 4"/><polyline points="120.7,168.0 120.7,158.0 110.7,158.0" stroke-width="1.2"/><polyline points="105.2,60.4 113.5,65.9 119.0,57.5" stroke-width="1.2"/><text x="21.7" y="177.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="176.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="105.6" y="45.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="110.7" y="186.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="68.6" y="184.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="60.8" y="111.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√161</text></svg>', '{"A": "4√23", "B": "4√7", "C": "√161", "D": "√690", "E": "√305"}'::jsonb, 'A', NULL, 'AC² = AH·AB ⇒ AB = 161/7 = 23. HB = 23 − 7 = 16. BC² = HB·AB = 16·23 ⇒ BC = 4√23.');
INSERT INTO public.questions VALUES (8273, 107, 'g11-geo-basic-q1-13', 1, 13, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = 3√19 və AH = 9 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.9 286.0,172.9 153.4,47.1"/><line x1="153.4" y1="47.1" x2="153.4" y2="172.9" stroke-dasharray="5 4"/><polyline points="163.4,172.9 163.4,162.9 153.4,162.9" stroke-width="1.2"/><polyline points="146.5,54.3 153.7,61.2 160.6,54.0" stroke-width="1.2"/><text x="21.7" y="182.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="152.7" y="39.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="153.4" y="190.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="88.5" y="188.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="82.3" y="111.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3√19</text></svg>', '{"A": "3√19", "B": "2√133", "C": "√190", "D": "3√10", "E": "√181"}'::jsonb, 'C', NULL, 'AC² = AH·AB ⇒ AB = 171/9 = 19. HB = 19 − 9 = 10. BC² = HB·AB = 10·19 ⇒ BC = √190.');
INSERT INTO public.questions VALUES (8274, 107, 'g11-geo-basic-q1-14', 1, 14, 'hard', 'single', 'ABC üçbucağında AB = 9, AC = 5, ∠A = 120°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="88.8,157.4 286.0,157.4 34.0,62.6"/><text x="78.0" y="169.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="165.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="22.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="197.6" y="168.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="49.7" y="112.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><line x1="88.8" y1="157.4" x2="160.0" y2="110.0" stroke-dasharray="5 4"/><path d="M106.8,157.4 A18,18 0 0 0 79.8,141.9" stroke-width="1.2"/><text x="104.3" y="135.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><text x="170.8" y="107.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√53", "B": "√151", "C": "√151/2", "D": "√61/2", "E": "11√3/2"}'::jsonb, 'D', NULL, 'Əvvəlcə BC² = 5² + 9² − 2·5·9·cos 120° = 151. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (162 + 50 − 151)/4 = 61/4 ⇒ AM = √61/2.');
INSERT INTO public.questions VALUES (8275, 107, 'g11-geo-basic-q1-15', 1, 15, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 4, BC = 17. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="58.3,137.8 286.0,137.8 34.0,82.2"/><text x="45.7" y="146.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="144.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="21.9" y="82.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="183.3" y="147.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="34.2" y="113.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="171.6" y="111.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="58.3" y1="137.8" x2="87.1" y2="93.9" stroke-dasharray="5 4"/><text x="94.2" y="88.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√4681/19", "B": "2√15", "C": "12√30/19", "D": "10√390/19", "E": "√193/2"}'::jsonb, 'C', NULL, 'BD = 255/19, DC = 68/19. AD² = AB·AC − BD·DC = 60 − 17340/361 = 4320/361 ⇒ AD = 12√30/19.');
INSERT INTO public.questions VALUES (8276, 107, 'g11-geo-basic-q1-16', 1, 16, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 8, BC = 5. Üçbucağa daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="58.7,186.0 217.0,186.0 261.3,34.0"/><text x="46.7" y="196.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="224.8" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="269.5" y="28.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="130.3" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="152.8" y="105.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="250.2" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><circle cx="185.3" cy="143.8" r="42.2"/></svg>', '{"A": "25/6", "B": "4/3", "C": "7/3", "D": "2/3", "E": "8/3"}'::jsonb, 'B', NULL, 'p = 9, S = √(p(p − a)(p − b)(p − c)) = 12. r = S/p = 12/9 = 4/3.');
INSERT INTO public.questions VALUES (8277, 107, 'g11-geo-basic-q1-17', 1, 17, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 13, BC = 10. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="89.8,139.2 230.2,139.2 188.6,39.6"/><text x="77.8" y="149.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="241.6" y="150.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="192.2" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="156.7" y="155.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="128.7" y="88.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="220.5" y="89.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "169/24", "B": "10/3", "C": "193/24", "D": "169/12", "E": "13/2"}'::jsonb, 'A', NULL, 'p = 18, S = √(p(p − a)(p − b)(p − c)) = 60. R = abc/(4S) = 1690/240 = 169/24.');
INSERT INTO public.questions VALUES (8278, 107, 'g11-geo-basic-q1-18', 1, 18, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = 4√30 və AH = 16 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.9 286.0,172.9 168.4,47.1"/><line x1="168.4" y1="47.1" x2="168.4" y2="172.9" stroke-dasharray="5 4"/><polyline points="178.4,172.9 178.4,162.9 168.4,162.9" stroke-width="1.2"/><polyline points="161.1,54.0 167.9,61.3 175.2,54.4" stroke-width="1.2"/><text x="21.6" y="181.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="169.3" y="39.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.4" y="190.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="95.5" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="89.8" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4√30</text></svg>', '{"A": "2√113", "B": "2√345", "C": "2√105", "D": "4√30", "E": "4√14"}'::jsonb, 'C', NULL, 'AC² = AH·AB ⇒ AB = 480/16 = 30. HB = 30 − 16 = 14. BC² = HB·AB = 14·30 ⇒ BC = 2√105.');
INSERT INTO public.questions VALUES (8279, 107, 'g11-geo-basic-q1-19', 1, 19, 'hard', 'single', 'ABC üçbucağında AB = 4, AC = 10, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="116.1,186.0 186.3,186.0 203.9,34.0"/><text x="106.8" y="200.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="190.6" y="203.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="208.1" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="147.3" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="156.1" y="103.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="116.1" y1="186.0" x2="195.1" y2="110.0" stroke-dasharray="5 4"/><path d="M134.1,186.0 A18,18 0 0 0 125.1,170.4" stroke-width="1.2"/><text x="143.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="204.5" y="106.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√39", "B": "√19", "C": "√77", "D": "√58", "E": "2√19"}'::jsonb, 'A', NULL, 'Əvvəlcə BC² = 10² + 4² − 2·10·4·cos 60° = 76. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (32 + 200 − 76)/4 = 39 ⇒ AM = √39.');
INSERT INTO public.questions VALUES (8280, 107, 'g11-geo-basic-q1-20', 1, 20, 'hard', 'single', 'ABC üçbucağında AB = 7, AC = 5, ∠A = 120°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="100.3,167.4 286.0,167.4 34.0,52.6"/><text x="90.9" y="181.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="175.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.5" y="50.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="202.9" y="179.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="55.6" y="112.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><line x1="100.3" y1="167.4" x2="160.0" y2="110.0" stroke-dasharray="5 4"/><path d="M118.3,167.4 A18,18 0 0 0 91.3,151.8" stroke-width="1.2"/><text x="115.8" y="145.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><text x="169.4" y="106.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√109/2", "B": "√257/2", "C": "√109", "D": "√39/2", "E": "√37"}'::jsonb, 'D', NULL, 'Əvvəlcə BC² = 5² + 7² − 2·5·7·cos 120° = 109. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (98 + 50 − 109)/4 = 39/4 ⇒ AM = √39/2.');
INSERT INTO public.questions VALUES (8281, 107, 'g11-geo-basic-q2-01', 2, 1, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = √165 və AH = 11 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,165.7 286.0,165.7 218.8,54.3"/><line x1="218.8" y1="54.3" x2="218.8" y2="165.7" stroke-dasharray="5 4"/><polyline points="228.8,165.7 228.8,155.7 218.8,155.7" stroke-width="1.2"/><polyline points="210.2,59.4 215.4,68.0 224.0,62.8" stroke-width="1.2"/><text x="21.4" y="173.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="175.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="224.9" y="47.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="218.8" y="183.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="118.7" y="180.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="115.1" y="111.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√165</text></svg>', '{"A": "√137", "B": "√165", "C": "2√15", "D": "2√11", "E": "√390"}'::jsonb, 'C', NULL, 'AC² = AH·AB ⇒ AB = 165/11 = 15. HB = 15 − 11 = 4. BC² = HB·AB = 4·15 ⇒ BC = 2√15.');
INSERT INTO public.questions VALUES (8282, 107, 'g11-geo-basic-q2-02', 2, 2, 'hard', 'single', 'ABC üçbucağında AB = 8, AC = 12, BC = 10. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="98.7,186.0 221.3,186.0 202.1,34.0"/><text x="87.9" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.1" y="200.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="205.6" y="26.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="156.8" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="142.2" y="106.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="221.7" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="98.7" y1="186.0" x2="213.6" y2="125.2" stroke-dasharray="5 4"/><text x="225.1" y="124.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√73", "B": "√71", "C": "6√2", "D": "√79", "E": "4√6"}'::jsonb, 'C', NULL, 'BD = 4, DC = 6. AD² = AB·AC − BD·DC = 96 − 24 = 72 ⇒ AD = 6√2.');
INSERT INTO public.questions VALUES (8283, 107, 'g11-geo-basic-q2-03', 2, 3, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 5, BC = 13. Daxilə və xaricə çəkilmiş çevrələrin radiuslarının hasilini (r·R) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,162.5 286.0,162.5 34.0,57.5"/><text x="22.0" y="172.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="170.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="24.0" y="54.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="169.2" y="175.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="22.3" y="112.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="171.1" y="110.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text></svg>', '{"A": "12", "B": "13", "C": "26", "D": "14", "E": "17/2"}'::jsonb, 'B', NULL, 'p = 15, S = √(p(p − a)(p − b)(p − c)) = 30. r = S/p = 2, R = abc/(4S) = 13/2. r·R = 13.');
INSERT INTO public.questions VALUES (8284, 107, 'g11-geo-basic-q2-04', 2, 4, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = √30 və AH = 2 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.8 286.0,152.8 67.6,67.2"/><line x1="67.6" y1="67.2" x2="67.6" y2="152.8" stroke-dasharray="5 4"/><polyline points="77.6,152.8 77.6,142.8 67.6,142.8" stroke-width="1.2"/><polyline points="63.9,76.5 73.3,80.1 76.9,70.8" stroke-width="1.2"/><text x="21.5" y="161.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="160.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="58.1" y="63.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="67.6" y="170.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="48.5" y="169.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="39.0" y="112.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√30</text></svg>', '{"A": "√255", "B": "√30", "C": "√195", "D": "√26", "E": "√173"}'::jsonb, 'C', NULL, 'AC² = AH·AB ⇒ AB = 30/2 = 15. HB = 15 − 2 = 13. BC² = HB·AB = 13·15 ⇒ BC = √195.');
INSERT INTO public.questions VALUES (8285, 107, 'g11-geo-basic-q2-05', 2, 5, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 13, BC = 13. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="106.0,163.5 214.0,163.5 160.0,34.0"/><text x="95.9" y="176.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="224.1" y="176.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.0" y="180.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="123.6" y="96.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="196.4" y="96.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "193/24", "B": "13/2", "C": "169/24", "D": "169/12", "E": "10/3"}'::jsonb, 'C', NULL, 'p = 18, S = √(p(p − a)(p − b)(p − c)) = 60. R = abc/(4S) = 1690/240 = 169/24.');
INSERT INTO public.questions VALUES (8286, 107, 'g11-geo-basic-q2-06', 2, 6, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 5, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,155.5 286.0,155.5 86.5,64.5"/><text x="21.5" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="163.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="78.3" y="59.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="167.5" y="169.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="48.5" y="112.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><line x1="34.0" y1="155.5" x2="186.2" y2="110.0" stroke-dasharray="5 4"/><path d="M52.0,155.5 A18,18 0 0 0 43.0,139.9" stroke-width="1.2"/><text x="60.8" y="145.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="198.7" y="111.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√447/2", "B": "√229/2", "C": "√109", "D": "13√2/2", "E": "√109/2"}'::jsonb, 'B', NULL, 'Əvvəlcə BC² = 5² + 12² − 2·5·12·cos 60° = 109. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (288 + 50 − 109)/4 = 229/4 ⇒ AM = √229/2.');
INSERT INTO public.questions VALUES (8287, 107, 'g11-geo-basic-q2-07', 2, 7, 'hard', 'single', 'ABC üçbucağında AB = 7, AC = 4, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,172.4 286.0,172.4 106.0,47.6"/><text x="21.9" y="182.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="181.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="100.8" y="40.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="164.8" y="188.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="58.5" y="111.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><line x1="34.0" y1="172.4" x2="196.0" y2="110.0" stroke-dasharray="5 4"/><path d="M52.0,172.4 A18,18 0 0 0 43.0,156.8" stroke-width="1.2"/><text x="60.8" y="161.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="208.1" y="110.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√167/2", "B": "√93/2", "C": "√37", "D": "√130/2", "E": "√37/2"}'::jsonb, 'B', NULL, 'Əvvəlcə BC² = 4² + 7² − 2·4·7·cos 60° = 37. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (98 + 32 − 37)/4 = 93/4 ⇒ AM = √93/2.');
INSERT INTO public.questions VALUES (8288, 107, 'g11-geo-basic-q2-08', 2, 8, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 24, BC = 13. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="130.8,180.2 189.2,180.2 230.4,138.6"/><text x="118.2" y="188.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="194.2" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="241.6" y="137.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="149.7" y="191.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="176.0" y="153.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="221.4" y="161.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "169/10", "B": "169/5", "C": "179/10", "D": "12", "E": "12/5"}'::jsonb, 'A', NULL, 'p = 25, S = √(p(p − a)(p − b)(p − c)) = 60. R = abc/(4S) = 4056/240 = 169/10.');
INSERT INTO public.questions VALUES (8289, 107, 'g11-geo-basic-q2-09', 2, 9, 'hard', 'single', 'ABC üçbucağında ∠A = 24°, ∠B = 26°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,139.3 286.0,139.3 165.7,80.7"/><text x="21.1" y="146.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="146.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="167.0" y="72.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="165.7" y1="80.7" x2="165.7" y2="139.3" stroke-dasharray="5 4"/><line x1="165.7" y1="80.7" x2="164.7" y2="139.3" stroke-dasharray="5 4"/><polyline points="175.7,139.3 175.7,129.3 165.7,129.3" stroke-width="1.2"/><text x="165.7" y="157.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="164.5" y="157.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "25/2°", "B": "2°", "C": "65°", "D": "6°", "E": "1°"}'::jsonb, 'E', NULL, '∠C = 130°, ∠ACL = 65°. ∠ACH = 90° − ∠A = 66°. Aradakı bucaq |65° − (66°)| = |∠A − ∠B|/2 = 1°.');
INSERT INTO public.questions VALUES (8290, 107, 'g11-geo-basic-q2-10', 2, 10, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = 4√3 və AH = 6 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.6 286.0,164.6 223.0,55.4"/><line x1="223.0" y1="55.4" x2="223.0" y2="164.6" stroke-dasharray="5 4"/><polyline points="233.0,164.6 233.0,154.6 223.0,154.6" stroke-width="1.2"/><polyline points="214.3,60.4 219.3,69.1 228.0,64.1" stroke-width="1.2"/><text x="21.4" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="173.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="229.5" y="49.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.0" y="182.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="120.6" y="178.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="117.2" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4√3</text></svg>', '{"A": "4√3", "B": "2√10", "C": "4√7", "D": "4", "E": "2√3"}'::jsonb, 'D', NULL, 'AC² = AH·AB ⇒ AB = 48/6 = 8. HB = 8 − 6 = 2. BC² = HB·AB = 2·8 ⇒ BC = 4.');
INSERT INTO public.questions VALUES (8291, 107, 'g11-geo-basic-q2-11', 2, 11, 'hard', 'single', 'ABC üçbucağında AB = 18, AC = 12, AM medianı isə √209. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,154.0 286.0,154.0 177.1,66.0"/><text x="21.3" y="161.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="162.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="179.6" y="58.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="157.7" y="170.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="93.9" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="34.0" y1="154.0" x2="231.6" y2="110.0" stroke-dasharray="5 4"/><text x="244.2" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="120.9" y="135.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√209</text></svg>', '{"A": "11", "B": "6√13", "C": "√727", "D": "10", "E": "3√26"}'::jsonb, 'D', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 648 + 288 − 836 = 100, BC = 10.');
INSERT INTO public.questions VALUES (8292, 107, 'g11-geo-basic-q2-12', 2, 12, 'hard', 'single', 'ABC üçbucağında ∠A = 84°, ∠B = 50°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="88.2,186.0 231.8,186.0 104.2,34.0"/><text x="78.8" y="200.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="243.1" y="197.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="99.7" y="26.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="104.2" y1="34.0" x2="104.2" y2="186.0" stroke-dasharray="5 4"/><line x1="104.2" y1="34.0" x2="150.7" y2="186.0" stroke-dasharray="5 4"/><polyline points="114.2,186.0 114.2,176.0 104.2,176.0" stroke-width="1.2"/><text x="104.2" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="154.5" y="203.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "34°", "B": "23°", "C": "67/2°", "D": "17°", "E": "22°"}'::jsonb, 'D', NULL, '∠C = 46°, ∠ACL = 23°. ∠ACH = 90° − ∠A = 6°. Aradakı bucaq |23° − (6°)| = |∠A − ∠B|/2 = 17°.');
INSERT INTO public.questions VALUES (8293, 107, 'g11-geo-basic-q2-13', 2, 13, 'hard', 'single', 'ABC üçbucağında AB = 15, AC = 14, AM medianı isə √698/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="51.7,186.0 268.3,186.0 185.0,34.0"/><text x="39.7" y="196.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="279.9" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.1" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.0" y="202.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="107.6" y="109.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="51.7" y1="186.0" x2="226.7" y2="110.0" stroke-dasharray="5 4"/><text x="238.6" y="109.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="127.7" y="149.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√698/2</text></svg>', '{"A": "12", "B": "√421", "C": "√2670/2", "D": "13", "E": "√842/2"}'::jsonb, 'A', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 450 + 392 − 698 = 144, BC = 12.');
INSERT INTO public.questions VALUES (8294, 107, 'g11-geo-basic-q2-14', 2, 14, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 9, BC = 14. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,144.6 286.0,144.6 123.8,75.4"/><text x="21.3" y="152.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="151.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="117.8" y="68.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.6" y="160.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="67.1" y="113.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="216.6" y="112.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="34.0" y1="144.6" x2="174.1" y2="96.9" stroke-dasharray="5 4"/><text x="186.4" y="97.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "6√5", "B": "√131", "C": "√766/2", "D": "√116941/29", "E": "30√129/29"}'::jsonb, 'E', NULL, 'BD = 280/29, DC = 126/29. AD² = AB·AC − BD·DC = 180 − 35280/841 = 116100/841 ⇒ AD = 30√129/29.');
INSERT INTO public.questions VALUES (8295, 107, 'g11-geo-basic-q2-15', 2, 15, 'hard', 'single', 'ABC üçbucağında AB = 9, AC = 6, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,182.7 286.0,182.7 118.0,37.3"/><text x="22.1" y="192.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="192.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="114.4" y="29.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="163.3" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="64.7" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="182.7" x2="202.0" y2="110.0" stroke-dasharray="5 4"/><path d="M52.0,182.7 A18,18 0 0 0 43.0,167.2" stroke-width="1.2"/><text x="60.8" y="172.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="213.9" y="109.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "3√26/2", "B": "3√7", "C": "3√19/2", "D": "3√7/2", "E": "3√33/2"}'::jsonb, 'C', NULL, 'Əvvəlcə BC² = 6² + 9² − 2·6·9·cos 60° = 63. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (162 + 72 − 63)/4 = 171/4 ⇒ AM = 3√19/2.');
INSERT INTO public.questions VALUES (8296, 107, 'g11-geo-basic-q2-16', 2, 16, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 6, AM medianı isə √329/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,145.3 286.0,145.3 126.4,74.7"/><text x="21.3" y="152.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="152.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="120.9" y="68.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.2" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="68.4" y="113.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="34.0" y1="145.3" x2="206.2" y2="110.0" stroke-dasharray="5 4"/><text x="219.0" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="108.2" y="131.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√329/2</text></svg>', '{"A": "10", "B": "√1311/2", "C": "9", "D": "√410/2", "E": "√205"}'::jsonb, 'C', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 338 + 72 − 329 = 81, BC = 9.');
INSERT INTO public.questions VALUES (8297, 107, 'g11-geo-basic-q2-17', 2, 17, 'hard', 'single', 'ABC üçbucağında ∠A = 100°, ∠B = 34°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="125.8,171.3 286.0,171.3 104.2,48.7"/><text x="116.1" y="184.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.2" y="180.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="95.9" y="43.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="286.0" y1="171.3" x2="34.0" y2="94.3" stroke-dasharray="5 4"/><line x1="125.8" y1="171.3" x2="34.0" y2="94.3" stroke-dasharray="5 4"/><text x="21.6" y="95.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "50°", "B": "67°", "C": "46°", "D": "23°", "E": "113°"}'::jsonb, 'D', NULL, '∠C = 46°. ABK üçbucağında ∠KBA = 17°, ∠KAB = ∠A + (180° − ∠A)/2 = 140°. ∠AKB = 180° − 17° − 140° = ∠C/2 = 23°.');
INSERT INTO public.questions VALUES (8298, 107, 'g11-geo-basic-q2-18', 2, 18, 'hard', 'single', 'ABC üçbucağında AB = 30, AC = 25, BC = 11. Daxilə və xaricə çəkilmiş çevrələrin radiuslarının hasilini (r·R) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,147.0 286.0,147.0 230.6,73.0"/><text x="21.2" y="154.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="155.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="239.5" y="68.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="151.7" y="160.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="120.6" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="270.1" y="113.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text></svg>', '{"A": "127/2", "B": "125", "C": "63", "D": "157/8", "E": "125/2"}'::jsonb, 'E', NULL, 'p = 33, S = √(p(p − a)(p − b)(p − c)) = 132. r = S/p = 4, R = abc/(4S) = 125/8. r·R = 125/2.');
INSERT INTO public.questions VALUES (8299, 107, 'g11-geo-basic-q2-19', 2, 19, 'hard', 'single', 'ABC üçbucağında AB = 12, AC = 11, BC = 15. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="76.1,186.0 243.9,186.0 99.4,34.0"/><text x="65.9" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="255.6" y="196.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="94.6" y="26.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="164.4" y="202.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="77.0" y="109.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="181.0" y="107.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><line x1="76.1" y1="186.0" x2="168.5" y2="106.7" stroke-dasharray="5 4"/><text x="178.4" y="103.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√40657/23", "B": "√305/2", "C": "√303/2", "D": "2√33", "E": "8√627/23"}'::jsonb, 'E', NULL, 'BD = 180/23, DC = 165/23. AD² = AB·AC − BD·DC = 132 − 29700/529 = 40128/529 ⇒ AD = 8√627/23.');
INSERT INTO public.questions VALUES (8300, 107, 'g11-geo-basic-q2-20', 2, 20, 'hard', 'single', 'ABC üçbucağında ∠A = 62°, ∠B = 72°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="146.7,186.0 264.6,186.0 219.9,48.4"/><text x="136.2" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="274.5" y="199.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="221.2" y="40.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="264.6" y1="186.0" x2="55.4" y2="34.0" stroke-dasharray="5 4"/><line x1="146.7" y1="186.0" x2="55.4" y2="34.0" stroke-dasharray="5 4"/><text x="44.9" y="31.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "67°", "B": "46°", "C": "113°", "D": "31°", "E": "23°"}'::jsonb, 'E', NULL, '∠C = 46°. ABK üçbucağında ∠KBA = 36°, ∠KAB = ∠A + (180° − ∠A)/2 = 121°. ∠AKB = 180° − 36° − 121° = ∠C/2 = 23°.');
INSERT INTO public.questions VALUES (8301, 107, 'g11-geo-basic-q3-01', 3, 1, 'hard', 'single', 'ABC üçbucağında AB = 7, AC = 13, AM medianı isə 2√15. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="118.8,186.0 201.2,186.0 137.3,34.0"/><text x="111.6" y="201.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.2" y="200.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="135.4" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="161.8" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="119.7" y="106.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="118.8" y1="186.0" x2="169.3" y2="110.0" stroke-dasharray="5 4"/><text x="176.4" y="104.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="134.0" y="146.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2√15</text></svg>', '{"A": "2√94", "B": "√109", "C": "√218", "D": "14", "E": "15"}'::jsonb, 'D', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 98 + 338 − 240 = 196, BC = 14.');
INSERT INTO public.questions VALUES (8302, 107, 'g11-geo-basic-q3-02', 3, 2, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = 3√15 və AH = 9 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,171.7 286.0,171.7 185.2,48.3"/><line x1="185.2" y1="48.3" x2="185.2" y2="171.7" stroke-dasharray="5 4"/><polyline points="195.2,171.7 195.2,161.7 185.2,161.7" stroke-width="1.2"/><polyline points="177.5,54.6 183.8,62.3 191.5,56.0" stroke-width="1.2"/><text x="21.6" y="180.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="181.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="187.8" y="40.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="185.2" y="189.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="103.3" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="98.3" y="111.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3√15</text></svg>', '{"A": "3√10", "B": "6√10", "C": "3√13", "D": "3√6", "E": "3√15"}'::jsonb, 'A', NULL, 'AC² = AH·AB ⇒ AB = 135/9 = 15. HB = 15 − 9 = 6. BC² = HB·AB = 6·15 ⇒ BC = 3√10.');
INSERT INTO public.questions VALUES (8303, 107, 'g11-geo-basic-q3-03', 3, 3, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = 2√17 və AH = 4 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,163.4 286.0,163.4 93.3,56.6"/><line x1="93.3" y1="56.6" x2="93.3" y2="163.4" stroke-dasharray="5 4"/><polyline points="103.3,163.4 103.3,153.4 93.3,153.4" stroke-width="1.2"/><polyline points="88.4,65.3 97.2,70.1 102.0,61.4" stroke-width="1.2"/><text x="21.7" y="172.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="171.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="86.4" y="50.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="93.3" y="181.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="60.4" y="180.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="52.0" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2√17</text></svg>', '{"A": "2√13", "B": "2√17", "C": "√357", "D": "√221", "E": "√185"}'::jsonb, 'D', NULL, 'AC² = AH·AB ⇒ AB = 68/4 = 17. HB = 17 − 4 = 13. BC² = HB·AB = 13·17 ⇒ BC = √221.');
INSERT INTO public.questions VALUES (8304, 107, 'g11-geo-basic-q3-04', 3, 4, 'hard', 'single', 'ABC üçbucağında ∠A = 48°, ∠B = 62°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="101.4,185.7 286.0,185.7 217.5,56.8"/><text x="89.5" y="195.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="196.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="219.8" y="49.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="286.0" y1="185.7" x2="34.0" y2="34.3" stroke-dasharray="5 4"/><line x1="101.4" y1="185.7" x2="34.0" y2="34.3" stroke-dasharray="5 4"/><text x="22.9" y="32.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "55°", "B": "125°", "C": "35°", "D": "24°", "E": "70°"}'::jsonb, 'C', NULL, '∠C = 70°. ABK üçbucağında ∠KBA = 31°, ∠KAB = ∠A + (180° − ∠A)/2 = 114°. ∠AKB = 180° − 31° − 114° = ∠C/2 = 35°.');
INSERT INTO public.questions VALUES (8305, 107, 'g11-geo-basic-q3-05', 3, 5, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 29, BC = 30. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="147.4,185.0 172.6,185.0 130.3,40.0"/><text x="146.7" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="178.1" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="127.7" y="32.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="162.4" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="133.8" y="106.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">29</text><text x="152.1" y="105.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "725/48", "B": "773/48", "C": "15", "D": "9/4", "E": "725/24"}'::jsonb, 'A', NULL, 'p = 32, S = √(p(p − a)(p − b)(p − c)) = 72. R = abc/(4S) = 4350/288 = 725/48.');
INSERT INTO public.questions VALUES (8306, 107, 'g11-geo-basic-q3-06', 3, 6, 'hard', 'single', 'ABC üçbucağında AB = 14, AC = 5, BC = 11. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,141.5 286.0,141.5 98.3,78.5"/><text x="21.3" y="149.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="148.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="89.2" y="74.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.4" y="155.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="54.3" y="113.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="203.9" y="112.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="34.0" y1="141.5" x2="147.7" y2="95.1" stroke-dasharray="5 4"/><text x="159.7" y="95.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√321/2", "B": "20√42/19", "C": "√70", "D": "√159/2", "E": "131/19"}'::jsonb, 'B', NULL, 'BD = 154/19, DC = 55/19. AD² = AB·AC − BD·DC = 70 − 8470/361 = 16800/361 ⇒ AD = 20√42/19.');
INSERT INTO public.questions VALUES (8307, 107, 'g11-geo-basic-q3-07', 3, 7, 'hard', 'single', 'ABC üçbucağında AB = 6, AC = 11, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="112.1,186.0 207.9,186.0 199.9,34.0"/><text x="102.1" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="215.2" y="201.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="203.2" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="157.0" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="149.2" y="105.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="112.1" y1="186.0" x2="203.9" y2="110.0" stroke-dasharray="5 4"/><path d="M130.1,186.0 A18,18 0 0 0 121.1,170.4" stroke-width="1.2"/><text x="139.0" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="213.9" y="106.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√314/2", "B": "√91", "C": "√223/2", "D": "9√5/2", "E": "√91/2"}'::jsonb, 'C', NULL, 'Əvvəlcə BC² = 11² + 6² − 2·11·6·cos 60° = 91. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (72 + 242 − 91)/4 = 223/4 ⇒ AM = √223/2.');
INSERT INTO public.questions VALUES (8308, 107, 'g11-geo-basic-q3-08', 3, 8, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 12, AM medianı isə √257/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="78.0,186.0 171.2,186.0 242.0,34.0"/><text x="66.8" y="197.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="173.1" y="203.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="249.9" y="28.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="117.3" y="200.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="158.3" y="103.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="78.0" y1="186.0" x2="206.6" y2="110.0" stroke-dasharray="5 4"/><text x="217.8" y="108.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="135.0" y="143.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√257/2</text></svg>', '{"A": "13√2/2", "B": "10", "C": "9", "D": "√1095/2", "E": "13"}'::jsonb, 'C', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 50 + 288 − 257 = 81, BC = 9.');
INSERT INTO public.questions VALUES (8309, 107, 'g11-geo-basic-q3-09', 3, 9, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 14, AM medianı isə 3√70/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="57.1,186.0 262.9,186.0 218.5,34.0"/><text x="45.0" y="196.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="274.1" y="197.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="223.1" y="26.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="155.7" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="127.5" y="108.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="57.1" y1="186.0" x2="240.7" y2="110.0" stroke-dasharray="5 4"/><text x="252.7" y="110.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="137.5" y="149.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3√70/2</text></svg>', '{"A": "√730/2", "B": "10", "C": "11", "D": "√365", "E": "√2290/2"}'::jsonb, 'B', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 338 + 392 − 630 = 100, BC = 10.');
INSERT INTO public.questions VALUES (8310, 107, 'g11-geo-basic-q3-10', 3, 10, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 13, BC = 12. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="93.3,186.0 226.7,186.0 176.7,34.0"/><text x="82.7" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="236.7" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.1" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.7" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="125.8" y="107.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="211.5" y="108.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="93.3" y1="186.0" x2="204.9" y2="119.9" stroke-dasharray="5 4"/><text x="216.1" y="118.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√394/2", "B": "√94", "C": "5√2002/23", "D": "√130", "E": "√50579/23"}'::jsonb, 'C', NULL, 'BD = 120/23, DC = 156/23. AD² = AB·AC − BD·DC = 130 − 18720/529 = 50050/529 ⇒ AD = 5√2002/23.');
INSERT INTO public.questions VALUES (8311, 107, 'g11-geo-basic-q3-11', 3, 11, 'hard', 'single', 'ABC üçbucağında AB = 8, AC = 10, ∠A = 60°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="89.8,186.0 230.2,186.0 177.6,34.0"/><text x="79.0" y="198.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="240.4" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="179.0" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.6" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="124.2" y="107.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="89.8" y1="186.0" x2="203.9" y2="110.0" stroke-dasharray="5 4"/><path d="M107.8,186.0 A18,18 0 0 0 98.8,170.4" stroke-width="1.2"/><text x="116.6" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><text x="214.7" y="107.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√21", "B": "√61", "C": "2√21", "D": "√103", "E": "√82"}'::jsonb, 'B', NULL, 'Əvvəlcə BC² = 10² + 8² − 2·10·8·cos 60° = 84. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (128 + 200 − 84)/4 = 61 ⇒ AM = √61.');
INSERT INTO public.questions VALUES (8312, 107, 'g11-geo-basic-q3-12', 3, 12, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 6, ∠A = 120°. AM medianını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="130.7,186.0 277.0,186.0 43.0,34.0"/><text x="126.1" y="203.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="289.1" y="195.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="33.5" y="30.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="212.6" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="75.7" y="110.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><line x1="130.7" y1="186.0" x2="160.0" y2="110.0" stroke-dasharray="5 4"/><path d="M148.7,186.0 A18,18 0 0 0 121.7,170.4" stroke-width="1.2"/><text x="146.2" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><text x="164.7" y="102.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text></svg>', '{"A": "√91/2", "B": "√91", "C": "√213/2", "D": "√31/2", "E": "√122/2"}'::jsonb, 'D', NULL, 'Əvvəlcə BC² = 6² + 5² − 2·6·5·cos 120° = 91. Sonra AM² = (2AB² + 2AC² − BC²)/4 = (50 + 72 − 91)/4 = 31/4 ⇒ AM = √31/2.');
INSERT INTO public.questions VALUES (8313, 107, 'g11-geo-basic-q3-13', 3, 13, 'hard', 'single', 'ABC üçbucağında AB = 14, AC = 7, BC = 12. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,164.0 286.0,164.0 98.9,56.0"/><text x="21.7" y="173.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="172.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="92.5" y="49.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="165.9" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="54.8" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="203.8" y="111.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="34.0" y1="164.0" x2="161.3" y2="92.0" stroke-dasharray="5 4"/><text x="172.6" y="90.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√67", "B": "7√2", "C": "√66", "D": "√62", "E": "√346/2"}'::jsonb, 'C', NULL, 'BD = 8, DC = 4. AD² = AB·AC − BD·DC = 98 − 32 = 66 ⇒ AD = √66.');
INSERT INTO public.questions VALUES (8314, 107, 'g11-geo-basic-q3-14', 3, 14, 'hard', 'open', 'ABC üçbucağında AB = 10, AC = 10, BC = 12. Daxilə və xaricə çəkilmiş çevrələrin radiuslarının hasilini (r·R) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="80.8,186.0 239.2,186.0 125.2,34.0"/><text x="70.4" y="198.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="250.5" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="122.3" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="162.7" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="92.5" y="109.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="191.8" y="107.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', NULL, NULL, '75/4', 'p = 16, S = √(p(p − a)(p − b)(p − c)) = 48. r = S/p = 3, R = abc/(4S) = 25/4. r·R = 75/4.');
INSERT INTO public.questions VALUES (8315, 107, 'g11-geo-basic-q3-15', 3, 15, 'hard', 'single', 'ABC üçbucağında AB = 13, AC = 16, AM medianı isə √769/2. BC tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="48.2,186.0 267.9,186.0 271.8,34.0"/><text x="35.9" y="195.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="278.5" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="279.6" y="28.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="150.9" y="200.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="150.2" y="108.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><line x1="48.2" y1="186.0" x2="269.8" y2="110.0" stroke-dasharray="5 4"/><text x="282.1" y="110.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">M</text><text x="147.7" y="149.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√769/2</text></svg>', '{"A": "5√17", "B": "5√34/2", "C": "9", "D": "10", "E": "√2631/2"}'::jsonb, 'C', NULL, '4AM² = 2AB² + 2AC² − BC² ⇒ BC² = 338 + 512 − 769 = 81, BC = 9.');
INSERT INTO public.questions VALUES (8316, 107, 'g11-geo-basic-q3-16', 3, 16, 'hard', 'single', 'ABC üçbucağında ∠A = 42°, ∠B = 28°. CH hündürlüyü ilə CL tənböləni arasındakı bucağı tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.1 286.0,152.1 127.6,67.9"/><text x="21.4" y="160.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="159.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="122.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="127.6" y1="67.9" x2="127.6" y2="152.1" stroke-dasharray="5 4"/><line x1="127.6" y1="67.9" x2="137.9" y2="152.1" stroke-dasharray="5 4"/><polyline points="137.6,152.1 137.6,142.1 127.6,142.1" stroke-width="1.2"/><text x="127.6" y="170.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="139.5" y="170.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">L</text></svg>', '{"A": "14°", "B": "35/2°", "C": "55°", "D": "12°", "E": "7°"}'::jsonb, 'E', NULL, '∠C = 110°, ∠ACL = 55°. ∠ACH = 90° − ∠A = 48°. Aradakı bucaq |55° − (48°)| = |∠A − ∠B|/2 = 7°.');
INSERT INTO public.questions VALUES (8317, 107, 'g11-geo-basic-q3-17', 3, 17, 'hard', 'single', 'ABC düzbucaqlı üçbucağında (∠C = 90°) CH hündürlükdür. AC = √105 və AH = 5 olarsa, BC katetini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,163.7 286.0,163.7 94.0,56.3"/><line x1="94.0" y1="56.3" x2="94.0" y2="163.7" stroke-dasharray="5 4"/><polyline points="104.0,163.7 104.0,153.7 94.0,153.7" stroke-width="1.2"/><polyline points="89.1,65.1 97.8,69.9 102.7,61.2" stroke-width="1.2"/><text x="21.7" y="172.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="171.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="87.2" y="50.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="94.0" y="181.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">H</text><text x="60.8" y="180.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="52.3" y="112.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">√105</text></svg>', '{"A": "√546", "B": "√105", "C": "4√5", "D": "√281", "E": "4√21"}'::jsonb, 'E', NULL, 'AC² = AH·AB ⇒ AB = 105/5 = 21. HB = 21 − 5 = 16. BC² = HB·AB = 16·21 ⇒ BC = 4√21.');
INSERT INTO public.questions VALUES (8318, 107, 'g11-geo-basic-q3-18', 3, 18, 'hard', 'single', 'ABC üçbucağında ∠A = 56°, ∠B = 100°. B bucağının tənböləni ilə A təpəsindəki xarici bucağın tənböləni K nöqtəsində kəsişir. ∠AKB-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="168.8,186.0 215.5,186.0 232.0,92.2"/><text x="158.9" y="199.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="219.5" y="203.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.1" y="85.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><line x1="215.5" y1="186.0" x2="88.0" y2="34.0" stroke-dasharray="5 4"/><line x1="168.8" y1="186.0" x2="88.0" y2="34.0" stroke-dasharray="5 4"/><text x="79.6" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">K</text></svg>', '{"A": "102°", "B": "12°", "C": "78°", "D": "28°", "E": "24°"}'::jsonb, 'B', NULL, '∠C = 24°. ABK üçbucağında ∠KBA = 50°, ∠KAB = ∠A + (180° − ∠A)/2 = 118°. ∠AKB = 180° − 50° − 118° = ∠C/2 = 12°.');
INSERT INTO public.questions VALUES (8319, 107, 'g11-geo-basic-q3-19', 3, 19, 'hard', 'single', 'ABC üçbucağında AB = 17, AC = 15, BC = 4. A bucağının tənbölənini (AD) tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,134.0 286.0,134.0 251.1,86.0"/><text x="21.1" y="140.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="141.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="262.6" y="85.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="149.4" y="144.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="130.7" y="113.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="280.5" y="113.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><line x1="34.0" y1="134.0" x2="267.5" y2="108.5" stroke-dasharray="5 4"/><text x="280.4" y="112.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text></svg>', '{"A": "√251", "B": "√255", "C": "√253", "D": "127/8", "E": "3√1785/8"}'::jsonb, 'E', NULL, 'BD = 17/8, DC = 15/8. AD² = AB·AC − BD·DC = 255 − 255/64 = 16065/64 ⇒ AD = 3√1785/8.');
INSERT INTO public.questions VALUES (8320, 107, 'g11-geo-basic-q3-20', 3, 20, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 17, BC = 21. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="124.2,177.1 195.8,177.1 105.6,56.9"/><text x="119.0" y="194.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="206.2" y="189.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="100.3" y="50.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="164.9" y="193.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="105.3" y="114.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="155.5" y="111.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "93/8", "B": "85/4", "C": "7/2", "D": "85/8", "E": "21/2"}'::jsonb, 'D', NULL, 'p = 24, S = √(p(p − a)(p − b)(p − c)) = 84. R = abc/(4S) = 3570/336 = 85/8.');
INSERT INTO public.questions VALUES (8321, 108, 'g11-geo-poly-q1-01', 1, 1, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 19 və 5, yan tərəfi 14 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="40.9,186.0 279.1,186.0 191.3,34.0 128.7,34.0"/><text x="29.9" y="198.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="290.1" y="198.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="196.3" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="123.7" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="247.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="72.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="40.9" y1="186.0" x2="191.3" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√291", "B": "√221", "C": "2√73", "D": "14", "E": "2√127"}'::jsonb, 'A', NULL, 'Hündürlük: h² = 14² − ((19 − 5)/2)² = 147. Diaqonalın proyeksiyası (19 + 5)/2 = 12. d = √(147 + 144) = √291.');
INSERT INTO public.questions VALUES (8322, 108, 'g11-geo-poly-q1-02', 1, 2, 'hard', 'single', 'Trapesiyanın oturacaqları 23 və 3, yan tərəfləri 21 və 13 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,179.0 286.0,179.0 250.9,41.0 218.1,41.0"/><text x="22.0" y="189.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="296.3" y="192.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="258.9" y="35.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="221.8" y="33.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="154.3" y="194.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">23</text><text x="240.2" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="280.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="114.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text></svg>', '{"A": "252/23", "B": "21/2", "C": "68/5", "D": "63/10", "E": "63/5"}'::jsonb, 'E', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 21, 13 və 23 − 3 = 20 olan üçbucaq alınır. Heron düsturu: S = 126. h = 2S/20 = 63/5.');
INSERT INTO public.questions VALUES (8323, 108, 'g11-geo-poly-q1-03', 1, 3, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 22 və 14 olarsa, trapesiyanın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="67.1,186.0 252.9,186.0 219.1,34.0 100.9,34.0"/><text x="57.0" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="263.0" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="227.1" y="28.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="92.9" y="28.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">22</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="67.1" y1="186.0" x2="219.1" y2="34.0" stroke-dasharray="5 4"/><line x1="252.9" y1="186.0" x2="100.9" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,86.0 160.0,79.0 152.9,86.0" stroke-width="1.2"/></svg>', '{"A": "340", "B": "324", "C": "342", "D": "308", "E": "648"}'::jsonb, 'B', NULL, 'Diaqonallar kəsişmə nöqtəsində 45° bucaq altında oturacaqlara düşür, ona görə h = (22 + 14)/2 = 18. S = (22 + 14)/2 · h = 324.');
INSERT INTO public.questions VALUES (8324, 108, 'g11-geo-poly-q1-04', 1, 4, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 19 və 11 olarsa, trapesiyanın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="63.7,186.0 256.3,186.0 215.7,34.0 104.3,34.0"/><text x="53.5" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="266.5" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="223.4" y="28.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="96.6" y="28.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="63.7" y1="186.0" x2="215.7" y2="34.0" stroke-dasharray="5 4"/><line x1="256.3" y1="186.0" x2="104.3" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,82.7 160.0,75.6 152.9,82.7" stroke-width="1.2"/></svg>', '{"A": "225", "B": "209", "C": "241", "D": "240", "E": "450"}'::jsonb, 'A', NULL, 'Diaqonallar kəsişmə nöqtəsində 45° bucaq altında oturacaqlara düşür, ona görə h = (19 + 11)/2 = 15. S = (19 + 11)/2 · h = 225.');
INSERT INTO public.questions VALUES (8325, 108, 'g11-geo-poly-q1-05', 1, 5, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları AB = 25, CD = 13, yan tərəfi 9. Diaqonallar O nöqtəsində kəsişir. O nöqtəsindən AB-yə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,143.8 286.0,143.8 225.5,76.2 94.5,76.2"/><text x="21.4" y="152.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.6" y="152.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.1" y="75.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="82.9" y="75.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="160.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text><text x="160.0" y="69.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="267.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="52.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><line x1="34.0" y1="143.8" x2="225.5" y2="76.2" stroke-dasharray="5 4"/><line x1="286.0" y1="143.8" x2="94.5" y2="76.2" stroke-dasharray="5 4"/><circle cx="160.0" cy="99.3" r="2.6" fill="currentColor"/><text x="172.3" y="100.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "25√46/38", "B": "75√5/13", "C": "3√5/2", "D": "75√5/38", "E": "39√5/38"}'::jsonb, 'D', NULL, 'h = 3√5. AOB ~ COD, oxşarlıq əmsalı 25 : 13, deməli O hündürlüyü 25 : 13 nisbətində bölür: 25/(25 + 13)·h = 75√5/38.');
INSERT INTO public.questions VALUES (8326, 108, 'g11-geo-poly-q1-06', 1, 6, 'hard', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 7. ACE üçbucağının sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><polygon points="247.8,110.0 116.1,34.0 116.1,186.0"/></svg>', '{"A": "147√3/2", "B": "147√3/8", "C": "49√3/4", "D": "49√3/2", "E": "147√3/4"}'::jsonb, 'E', NULL, 'ACE bərabərtərəflidir, tərəfi AC = 7√3. S = (√3/4)·3·49 = 147√3/4. (Altıbucaqlının sahəsinin yarısı.)');
INSERT INTO public.questions VALUES (8327, 108, 'g11-geo-poly-q1-07', 1, 7, 'hard', 'open', 'Rombun tərəfi 15, diaqonallarından biri 18 olarsa, rombun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/></svg>', NULL, NULL, '72/5', 'İkinci yarımdiaqonal √(15² − 9²) = 12, d₂ = 24. S = 18·24/2 = 216. h = S/a = 72/5.');
INSERT INTO public.questions VALUES (8328, 108, 'g11-geo-poly-q1-08', 1, 8, 'hard', 'single', 'Paraleloqramın tərəfləri 11 və 7, aralarındakı bucaq 135° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="112.2,149.1 286.0,149.1 207.8,70.9 34.0,70.9"/><text x="102.1" y="162.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="158.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="217.9" y="67.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.6" y="72.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="207.6" y="162.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="61.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><path d="M130.2,149.1 A18,18 0 0 0 99.5,136.4" stroke-width="1.2"/><text x="124.1" y="125.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text></svg>', '{"A": "77√2", "B": "77/2", "C": "77", "D": "77√3/2", "E": "77√2/2"}'::jsonb, 'E', NULL, 'S = a·b·sin 135° = 11·7·√2/2 = 77√2/2.');
INSERT INTO public.questions VALUES (8329, 108, 'g11-geo-poly-q1-09', 1, 9, 'hard', 'single', 'Trapesiyanın oturacaqları 31 və 11, yan tərəfləri 20 və 24 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="37.3,186.0 282.7,186.0 168.7,34.0 81.6,34.0"/><text x="26.8" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="294.1" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="172.9" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="73.5" y="28.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="162.7" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">31</text><text x="122.5" y="27.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="237.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="47.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text></svg>', '{"A": "12", "B": "96/5", "C": "384/31", "D": "101/5", "E": "48/5"}'::jsonb, 'B', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 20, 24 və 31 − 11 = 20 olan üçbucaq alınır. Heron düsturu: S = 192. h = 2S/20 = 96/5.');
INSERT INTO public.questions VALUES (8330, 108, 'g11-geo-poly-q1-10', 1, 10, 'hard', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 14. ACE üçbucağının sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><polygon points="247.8,110.0 116.1,34.0 116.1,186.0"/></svg>', '{"A": "147√3/2", "B": "147√3", "C": "98√3", "D": "294√3", "E": "49√3"}'::jsonb, 'B', NULL, 'ACE bərabərtərəflidir, tərəfi AC = 14√3. S = (√3/4)·3·196 = 147√3. (Altıbucaqlının sahəsinin yarısı.)');
INSERT INTO public.questions VALUES (8331, 108, 'g11-geo-poly-q1-11', 1, 11, 'hard', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 14. AC diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><line x1="247.8" y1="110.0" x2="116.1" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "7√3", "B": "28", "C": "14√2", "D": "14√3", "E": "28√3"}'::jsonb, 'D', NULL, '∠ABC = 120°: AC² = 14² + 14² − 2·14·14·cos 120° = 3·196 ⇒ AC = 14√3.');
INSERT INTO public.questions VALUES (8332, 108, 'g11-geo-poly-q1-12', 1, 12, 'hard', 'single', 'Rombun diaqonalları 48 və 90 olarsa, ona daxil çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 200.5,110.0 160.0,186.0 119.5,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="106.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="200.5" y1="110.0" x2="119.5" y2="110.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="110.0" r="35.8"/></svg>', '{"A": "51/2", "B": "180/17", "C": "720/17", "D": "377/17", "E": "360/17"}'::jsonb, 'E', NULL, 'Tərəf 51. Radius hündürlüyün yarısıdır: r = (d₁d₂/2)/(2a) = 2160/102 = 360/17.');
INSERT INTO public.questions VALUES (8333, 108, 'g11-geo-poly-q1-13', 1, 13, 'hard', 'single', 'Paraleloqramın tərəfləri 11 və 12, aralarındakı bucaq 60° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="35.7,186.0 196.6,186.0 284.3,34.0 123.4,34.0"/><text x="24.6" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="202.2" y="202.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="295.4" y="32.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="117.8" y="27.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="110.1" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="67.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><path d="M53.7,186.0 A18,18 0 0 0 44.7,170.4" stroke-width="1.2"/><text x="62.5" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="35.7" y1="186.0" x2="284.3" y2="34.0" stroke-dasharray="5 4"/><line x1="196.6" y1="186.0" x2="123.4" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "√265", "B": "23", "C": "√530", "D": "√397", "E": "√133"}'::jsonb, 'E', NULL, 'Kosinuslar teoremi: d² = 11² + 12² ∓ 2·11·12·cos 60°. Böyük diaqonal √397, kiçik diaqonal √133. Cavab: √133.');
INSERT INTO public.questions VALUES (8334, 108, 'g11-geo-poly-q1-14', 1, 14, 'hard', 'open', 'Trapesiyanın oturacaqları 13 və 3, yan tərəfləri 16 və 10 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.9,186.0 240.8,186.0 285.1,34.0 237.6,34.0"/><text x="23.1" y="196.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="246.9" y="202.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="294.8" y="30.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="243.4" y="27.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="130.3" y="200.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="268.9" y="29.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="274.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="124.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text></svg>', NULL, NULL, '48/5', 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 16, 10 və 13 − 3 = 10 olan üçbucaq alınır. Heron düsturu: S = 48. h = 2S/10 = 48/5.');
INSERT INTO public.questions VALUES (8335, 108, 'g11-geo-poly-q1-15', 1, 15, 'hard', 'single', 'Trapesiyanın oturacaqları 30 və 10, yan tərəfləri 25 və 15 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 286.0,47.0 202.0,47.0"/><text x="21.8" y="182.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="296.4" y="185.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="296.4" y="44.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="202.0" y="39.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="153.3" y="188.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">30</text><text x="250.7" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="298.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="106.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text></svg>', '{"A": "300", "B": "320", "C": "315", "D": "600", "E": "150"}'::jsonb, 'A', NULL, 'Yan tərəflər və oturacaqların fərqi (20) üçbucaq əmələ gətirir, onun sahəsi Heron düsturu ilə 150, hündürlüyü 2·150/20 = 15. S = (30 + 10)/2 · 15 = 300.');
INSERT INTO public.questions VALUES (8336, 108, 'g11-geo-poly-q1-16', 1, 16, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 23 və 19 olarsa, trapesiyanın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="76.8,186.0 243.2,186.0 228.8,34.0 91.2,34.0"/><text x="67.2" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="252.8" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="237.5" y="29.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="82.5" y="29.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">23</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">19</text><line x1="76.8" y1="186.0" x2="228.8" y2="34.0" stroke-dasharray="5 4"/><line x1="243.2" y1="186.0" x2="91.2" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,95.7 160.0,88.6 152.9,95.7" stroke-width="1.2"/></svg>', '{"A": "441", "B": "437", "C": "445", "D": "882", "E": "462"}'::jsonb, 'A', NULL, 'Diaqonallar kəsişmə nöqtəsində 45° bucaq altında oturacaqlara düşür, ona görə h = (23 + 19)/2 = 21. S = (23 + 19)/2 · h = 441.');
INSERT INTO public.questions VALUES (8337, 108, 'g11-geo-poly-q1-17', 1, 17, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 23 və 13 olarsa, yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="62.9,186.0 257.1,186.0 214.9,34.0 105.1,34.0"/><text x="52.7" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="267.3" y="199.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="222.5" y="28.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="97.5" y="28.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">23</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><line x1="62.9" y1="186.0" x2="214.9" y2="34.0" stroke-dasharray="5 4"/><line x1="257.1" y1="186.0" x2="105.1" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,81.8 160.0,74.7 152.9,81.8" stroke-width="1.2"/></svg>', '{"A": "√299", "B": "√349", "C": "18", "D": "3√39", "E": "2√349"}'::jsonb, 'B', NULL, 'h = (23 + 13)/2 = 18, yan tərəfin proyeksiyası (23 − 13)/2 = 5. c = √(324 + 25) = √349.');
INSERT INTO public.questions VALUES (8338, 108, 'g11-geo-poly-q1-18', 1, 18, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları AB = 16, CD = 4, yan tərəfi 17. Diaqonallar O nöqtəsində kəsişir. O nöqtəsindən AB-yə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="83.6,186.0 236.4,186.0 179.1,34.0 140.9,34.0"/><text x="74.3" y="200.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.7" y="200.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="182.3" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="137.7" y="26.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="219.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><text x="100.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">17</text><line x1="83.6" y1="186.0" x2="179.1" y2="34.0" stroke-dasharray="5 4"/><line x1="236.4" y1="186.0" x2="140.9" y2="34.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="64.4" r="2.6" fill="currentColor"/><text x="166.9" y="58.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "4√253/5", "B": "4√253", "C": "4√254/5", "D": "√253/2", "E": "√253/5"}'::jsonb, 'A', NULL, 'h = √253. AOB ~ COD, oxşarlıq əmsalı 16 : 4, deməli O hündürlüyü 16 : 4 nisbətində bölür: 16/(16 + 4)·h = 4√253/5.');
INSERT INTO public.questions VALUES (8339, 108, 'g11-geo-poly-q1-19', 1, 19, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 24 və 14, yan tərəfi 20 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="65.8,186.0 254.2,186.0 214.9,34.0 105.1,34.0"/><text x="55.7" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="264.3" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="222.6" y="28.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="97.4" y="28.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="246.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="73.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><line x1="65.8" y1="186.0" x2="214.9" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "20", "B": "2√149", "C": "4√46", "D": "√737", "E": "√951"}'::jsonb, 'C', NULL, 'Hündürlük: h² = 20² − ((24 − 14)/2)² = 375. Diaqonalın proyeksiyası (24 + 14)/2 = 19. d = √(375 + 361) = 4√46.');
INSERT INTO public.questions VALUES (8340, 108, 'g11-geo-poly-q1-20', 1, 20, 'hard', 'single', 'Paraleloqramın tərəfləri 12 və 2, aralarındakı bucaq 135° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="60.6,123.3 286.0,123.3 259.4,96.7 34.0,96.7"/><text x="47.7" y="130.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.9" y="129.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="272.3" y="100.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.1" y="100.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="181.8" y="136.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="35.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><path d="M78.6,123.3 A18,18 0 0 0 47.8,110.6" stroke-width="1.2"/><text x="72.4" y="99.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text></svg>', '{"A": "12√3", "B": "12√2", "C": "24√2", "D": "12", "E": "24"}'::jsonb, 'B', NULL, 'S = a·b·sin 135° = 12·2·√2/2 = 12√2.');
INSERT INTO public.questions VALUES (8341, 108, 'g11-geo-poly-q2-01', 2, 1, 'hard', 'single', 'Paraleloqramın tərəfləri 14 və 15, aralarındakı bucaq 150° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="155.3,145.0 286.0,145.0 164.7,75.0 34.0,75.0"/><text x="153.6" y="162.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.5" y="153.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="166.4" y="67.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.5" y="76.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="231.0" y="156.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="82.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><path d="M173.3,145.0 A18,18 0 0 0 139.7,136.0" stroke-width="1.2"/><text x="163.3" y="120.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">150°</text></svg>', '{"A": "105/2", "B": "105√3", "C": "105", "D": "210", "E": "105√2"}'::jsonb, 'C', NULL, 'S = a·b·sin 150° = 14·15·1/2 = 105.');
INSERT INTO public.questions VALUES (8342, 108, 'g11-geo-poly-q2-02', 2, 2, 'hard', 'single', 'Paraleloqramın tərəfləri 8 və 11, aralarındakı bucaq 30° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,149.5 149.0,149.5 286.0,70.5 171.0,70.5"/><text x="21.6" y="158.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="145.6" y="167.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.4" y="71.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="174.4" y="62.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="81.1" y="160.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="90.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><path d="M52.0,149.5 A18,18 0 0 0 49.6,140.5" stroke-width="1.2"/><text x="63.9" y="146.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text></svg>', '{"A": "22", "B": "88", "C": "44√2", "D": "44", "E": "44√3"}'::jsonb, 'D', NULL, 'S = a·b·sin 30° = 8·11·1/2 = 44.');
INSERT INTO public.questions VALUES (8343, 108, 'g11-geo-poly-q2-03', 2, 3, 'hard', 'single', 'Rombun tərəfi 34, diaqonallarından biri 32 olarsa, rombun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 200.5,110.0 160.0,186.0 119.5,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="213.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="106.5" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="200.5" y1="110.0" x2="119.5" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "480/17", "B": "240/17", "C": "960/17", "D": "1088/69", "E": "497/17"}'::jsonb, 'A', NULL, 'İkinci yarımdiaqonal √(34² − 16²) = 30, d₂ = 60. S = 32·60/2 = 960. h = S/a = 480/17.');
INSERT INTO public.questions VALUES (8344, 108, 'g11-geo-poly-q2-04', 2, 4, 'hard', 'single', 'Trapesiyanın oturacaqları 20 və 2, yan tərəfləri 15 və 15 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,185.6 286.0,185.6 172.6,34.4 147.4,34.4"/><text x="22.9" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.1" y="197.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="174.7" y="26.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="145.3" y="26.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="202.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="160.0" y="27.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="241.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="78.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text></svg>', '{"A": "132", "B": "66", "C": "144", "D": "165", "E": "264"}'::jsonb, 'A', NULL, 'Yan tərəflər və oturacaqların fərqi (18) üçbucaq əmələ gətirir, onun sahəsi Heron düsturu ilə 108, hündürlüyü 2·108/18 = 12. S = (20 + 2)/2 · 12 = 132.');
INSERT INTO public.questions VALUES (8345, 108, 'g11-geo-poly-q2-05', 2, 5, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 15 və 11 olarsa, trapesiyanın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="72.3,186.0 247.7,186.0 224.3,34.0 95.7,34.0"/><text x="62.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="257.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="232.7" y="29.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="87.3" y="29.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><line x1="72.3" y1="186.0" x2="224.3" y2="34.0" stroke-dasharray="5 4"/><line x1="247.7" y1="186.0" x2="95.7" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,91.2 160.0,84.2 152.9,91.2" stroke-width="1.2"/></svg>', '{"A": "165", "B": "173", "C": "182", "D": "338", "E": "169"}'::jsonb, 'E', NULL, 'Diaqonallar kəsişmə nöqtəsində 45° bucaq altında oturacaqlara düşür, ona görə h = (15 + 11)/2 = 13. S = (15 + 11)/2 · h = 169.');
INSERT INTO public.questions VALUES (8346, 108, 'g11-geo-poly-q2-06', 2, 6, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 18 və 4, yan tərəfi 14 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="47.2,186.0 272.8,186.0 185.1,34.0 134.9,34.0"/><text x="36.4" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="283.6" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="189.1" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="130.9" y="26.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><text x="241.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="79.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "77√3/2", "B": "154", "C": "22√37", "D": "154√3", "E": "77√3"}'::jsonb, 'E', NULL, 'h = √(14² − 7²) = 7√3. S = (18 + 4)/2 · h = 77√3.');
INSERT INTO public.questions VALUES (8347, 108, 'g11-geo-poly-q2-07', 2, 7, 'hard', 'single', 'Düzgün altıbucaqlının tərəfi 6 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "216", "B": "108√3", "C": "54√3", "D": "27√3", "E": "9√3"}'::jsonb, 'C', NULL, '6 bərabərtərəfli üçbucaq: S = 6·6²√3/4 = 54√3.');
INSERT INTO public.questions VALUES (8348, 108, 'g11-geo-poly-q2-08', 2, 8, 'hard', 'single', 'Paraleloqramın tərəfləri 10 və 6, aralarındakı bucaq 30° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,134.9 199.8,134.9 286.0,85.1 120.2,85.1"/><text x="21.2" y="142.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.9" y="146.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.8" y="87.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="109.1" y="83.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="106.5" y="145.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="65.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M52.0,134.9 A18,18 0 0 0 49.6,125.9" stroke-width="1.2"/><text x="63.9" y="131.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text></svg>', '{"A": "30√3", "B": "30√2", "C": "15", "D": "30", "E": "60"}'::jsonb, 'D', NULL, 'S = a·b·sin 30° = 10·6·1/2 = 30.');
INSERT INTO public.questions VALUES (8349, 108, 'g11-geo-poly-q2-09', 2, 9, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları AB = 8, CD = 6, yan tərəfi 3. Diaqonallar O nöqtəsində kəsişir. O nöqtəsindən AB-yə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,154.5 286.0,154.5 254.5,65.5 65.5,65.5"/><text x="21.7" y="163.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="163.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="266.3" y="64.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="53.7" y="64.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="171.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="160.0" y="58.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="282.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="37.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><line x1="34.0" y1="154.5" x2="254.5" y2="65.5" stroke-dasharray="5 4"/><line x1="286.0" y1="154.5" x2="65.5" y2="65.5" stroke-dasharray="5 4"/><circle cx="160.0" cy="103.6" r="2.6" fill="currentColor"/><text x="172.1" y="103.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "8√2/7", "B": "12/7", "C": "6√2/7", "D": "8√2/3", "E": "√2"}'::jsonb, 'A', NULL, 'h = 2√2. AOB ~ COD, oxşarlıq əmsalı 8 : 6, deməli O hündürlüyü 8 : 6 nisbətində bölür: 8/(8 + 6)·h = 8√2/7.');
INSERT INTO public.questions VALUES (8350, 108, 'g11-geo-poly-q2-10', 2, 10, 'hard', 'single', 'Paraleloqramın tərəfləri 7 və 4, aralarındakı bucaq 150° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="117.4,134.1 286.0,134.1 202.6,85.9 34.0,85.9"/><text x="106.1" y="145.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="141.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="213.9" y="84.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="21.2" y="88.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="212.1" y="145.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="63.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><path d="M135.4,134.1 A18,18 0 0 0 101.8,125.1" stroke-width="1.2"/><text x="125.4" y="109.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">150°</text></svg>', '{"A": "7", "B": "28", "C": "14", "D": "14√2", "E": "14√3"}'::jsonb, 'C', NULL, 'S = a·b·sin 150° = 7·4·1/2 = 14.');
INSERT INTO public.questions VALUES (8351, 108, 'g11-geo-poly-q2-11', 2, 11, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 16 və 2, yan tərəfi 12 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="35.2,186.0 284.8,186.0 175.6,34.0 144.4,34.0"/><text x="24.1" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="295.9" y="197.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.2" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="141.8" y="26.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="242.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="77.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="35.2" y1="186.0" x2="175.6" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "12", "B": "√177", "C": "4√11", "D": "3√39", "E": "2√37"}'::jsonb, 'C', NULL, 'Hündürlük: h² = 12² − ((16 − 2)/2)² = 95. Diaqonalın proyeksiyası (16 + 2)/2 = 9. d = √(95 + 81) = 4√11.');
INSERT INTO public.questions VALUES (8352, 108, 'g11-geo-poly-q2-12', 2, 12, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 16 və 12 olarsa, yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="73.1,186.0 246.9,186.0 225.1,34.0 94.9,34.0"/><text x="63.4" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="256.6" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="233.6" y="29.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="86.4" y="29.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="73.1" y1="186.0" x2="225.1" y2="34.0" stroke-dasharray="5 4"/><line x1="246.9" y1="186.0" x2="94.9" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,92.1 160.0,85.0 152.9,92.1" stroke-width="1.2"/></svg>', '{"A": "11√2", "B": "14", "C": "8√3", "D": "10√2", "E": "√202"}'::jsonb, 'D', NULL, 'h = (16 + 12)/2 = 14, yan tərəfin proyeksiyası (16 − 12)/2 = 2. c = √(196 + 4) = 10√2.');
INSERT INTO public.questions VALUES (8353, 108, 'g11-geo-poly-q2-13', 2, 13, 'hard', 'single', 'Trapesiyanın oturacaqları 22 və 6, yan tərəfləri 20 və 12 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,178.7 286.0,178.7 286.0,41.3 217.3,41.3"/><text x="21.9" y="188.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="295.9" y="192.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="295.9" y="37.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="219.4" y="33.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="153.3" y="193.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">22</text><text x="258.3" y="36.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="298.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="113.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text></svg>', '{"A": "13", "B": "96/11", "C": "192/23", "D": "12", "E": "6"}'::jsonb, 'D', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 20, 12 və 22 − 6 = 16 olan üçbucaq alınır. Heron düsturu: S = 96. h = 2S/16 = 12.');
INSERT INTO public.questions VALUES (8354, 108, 'g11-geo-poly-q2-14', 2, 14, 'hard', 'open', 'Rombun tərəfi 10, diaqonallarından biri 12 olarsa, rombun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 217.0,110.0 160.0,186.0 103.0,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="230.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="90.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="217.0" y1="110.0" x2="103.0" y2="110.0" stroke-dasharray="5 4"/></svg>', NULL, NULL, '48/5', 'İkinci yarımdiaqonal √(10² − 6²) = 8, d₂ = 16. S = 12·16/2 = 96. h = S/a = 48/5.');
INSERT INTO public.questions VALUES (8355, 108, 'g11-geo-poly-q2-15', 2, 15, 'hard', 'single', 'Trapesiyanın oturacaqları 26 və 11, yan tərəfləri 25 və 20 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="61.2,186.0 258.8,186.0 258.8,34.0 175.2,34.0"/><text x="50.0" y="197.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="267.6" y="200.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="267.6" y="29.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="173.0" y="26.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="155.8" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">26</text><text x="221.2" y="27.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="270.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="106.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">25</text></svg>', '{"A": "20", "B": "150/13", "C": "100/9", "D": "21", "E": "10"}'::jsonb, 'A', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 25, 20 və 26 − 11 = 15 olan üçbucaq alınır. Heron düsturu: S = 150. h = 2S/15 = 20.');
INSERT INTO public.questions VALUES (8356, 108, 'g11-geo-poly-q2-16', 2, 16, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları AB = 14, CD = 8, yan tərəfi 14. Diaqonallar O nöqtəsində kəsişir. O nöqtəsindən AB-yə qədər məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="82.2,186.0 237.8,186.0 204.5,34.0 115.5,34.0"/><text x="72.9" y="200.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="247.1" y="200.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="211.0" y="27.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="109.0" y="27.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="233.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="86.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><line x1="82.2" y1="186.0" x2="204.5" y2="34.0" stroke-dasharray="5 4"/><line x1="237.8" y1="186.0" x2="115.5" y2="34.0" stroke-dasharray="5 4"/><circle cx="160.0" cy="89.3" r="2.6" fill="currentColor"/><text x="168.1" y="84.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "7√187/11", "B": "7√187/4", "C": "14√47/11", "D": "4√187/11", "E": "√187/2"}'::jsonb, 'A', NULL, 'h = √187. AOB ~ COD, oxşarlıq əmsalı 14 : 8, deməli O hündürlüyü 14 : 8 nisbətində bölür: 14/(14 + 8)·h = 7√187/11.');
INSERT INTO public.questions VALUES (8357, 108, 'g11-geo-poly-q2-17', 2, 17, 'hard', 'single', 'Trapesiyanın oturacaqları 15 və 5, yan tərəfləri 10 və 16 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="73.6,178.0 286.0,178.0 104.8,42.0 34.0,42.0"/><text x="65.8" y="193.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.0" y="188.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="101.1" y="34.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="23.6" y="39.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="187.4" y="192.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="61.8" y="37.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="207.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="41.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "48/5", "B": "53/5", "C": "24/5", "D": "6", "E": "32/5"}'::jsonb, 'A', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 10, 16 və 15 − 5 = 10 olan üçbucaq alınır. Heron düsturu: S = 48. h = 2S/10 = 48/5.');
INSERT INTO public.questions VALUES (8358, 108, 'g11-geo-poly-q2-18', 2, 18, 'hard', 'single', 'Düzgün altıbucaqlının tərəfi 10 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text></svg>', '{"A": "75√3", "B": "300√3", "C": "600", "D": "25√3", "E": "150√3"}'::jsonb, 'E', NULL, '6 bərabərtərəfli üçbucaq: S = 6·10²√3/4 = 150√3.');
INSERT INTO public.questions VALUES (8359, 108, 'g11-geo-poly-q2-19', 2, 19, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 7 və 3 olarsa, yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="53.6,186.0 266.4,186.0 205.6,34.0 114.4,34.0"/><text x="43.0" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="277.0" y="198.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="212.3" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="107.7" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><line x1="53.6" y1="186.0" x2="205.6" y2="34.0" stroke-dasharray="5 4"/><line x1="266.4" y1="186.0" x2="114.4" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,72.5 160.0,65.5 152.9,72.5" stroke-width="1.2"/></svg>', '{"A": "2√29", "B": "√29", "C": "√21", "D": "√31", "E": "5"}'::jsonb, 'B', NULL, 'h = (7 + 3)/2 = 5, yan tərəfin proyeksiyası (7 − 3)/2 = 2. c = √(25 + 4) = √29.');
INSERT INTO public.questions VALUES (8360, 108, 'g11-geo-poly-q2-20', 2, 20, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 13 və 7 olarsa, yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="61.2,186.0 258.8,186.0 213.2,34.0 106.8,34.0"/><text x="50.9" y="198.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="269.1" y="198.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="220.7" y="28.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="99.3" y="28.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><line x1="61.2" y1="186.0" x2="213.2" y2="34.0" stroke-dasharray="5 4"/><line x1="258.8" y1="186.0" x2="106.8" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,80.1 160.0,73.1 152.9,80.1" stroke-width="1.2"/></svg>', '{"A": "10", "B": "√91", "C": "√109", "D": "√111", "E": "2√109"}'::jsonb, 'C', NULL, 'h = (13 + 7)/2 = 10, yan tərəfin proyeksiyası (13 − 7)/2 = 3. c = √(100 + 9) = √109.');
INSERT INTO public.questions VALUES (8361, 108, 'g11-geo-poly-q3-01', 3, 1, 'hard', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 6. AC diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><line x1="247.8" y1="110.0" x2="116.1" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "12", "B": "3√3", "C": "12√3", "D": "6√2", "E": "6√3"}'::jsonb, 'E', NULL, '∠ABC = 120°: AC² = 6² + 6² − 2·6·6·cos 120° = 3·36 ⇒ AC = 6√3.');
INSERT INTO public.questions VALUES (8362, 108, 'g11-geo-poly-q3-02', 3, 2, 'hard', 'single', 'Rombun tərəfi 13, diaqonallarından biri 10 olarsa, rombun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 191.7,110.0 160.0,186.0 128.3,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="204.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="115.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="191.7" y1="110.0" x2="128.3" y2="110.0" stroke-dasharray="5 4"/></svg>', '{"A": "133/13", "B": "130/27", "C": "240/13", "D": "120/13", "E": "60/13"}'::jsonb, 'D', NULL, 'İkinci yarımdiaqonal √(13² − 5²) = 12, d₂ = 24. S = 10·24/2 = 120. h = S/a = 120/13.');
INSERT INTO public.questions VALUES (8363, 108, 'g11-geo-poly-q3-03', 3, 3, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 16 və 8 olarsa, trapesiyanın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="58.7,186.0 261.3,186.0 210.7,34.0 109.3,34.0"/><text x="48.3" y="198.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="271.7" y="198.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="217.9" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="102.1" y="28.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><line x1="58.7" y1="186.0" x2="210.7" y2="34.0" stroke-dasharray="5 4"/><line x1="261.3" y1="186.0" x2="109.3" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,77.6 160.0,70.5 152.9,77.6" stroke-width="1.2"/></svg>', '{"A": "144", "B": "156", "C": "160", "D": "128", "E": "288"}'::jsonb, 'A', NULL, 'Diaqonallar kəsişmə nöqtəsində 45° bucaq altında oturacaqlara düşür, ona görə h = (16 + 8)/2 = 12. S = (16 + 8)/2 · h = 144.');
INSERT INTO public.questions VALUES (8364, 108, 'g11-geo-poly-q3-04', 3, 4, 'hard', 'single', 'Trapesiyanın oturacaqları 22 və 12, yan tərəfləri 16 və 10 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,158.8 257.5,158.8 286.0,61.2 164.1,61.2"/><text x="21.6" y="167.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="268.3" y="171.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="297.7" y="60.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="158.9" y="54.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="138.2" y="173.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">22</text><text x="232.6" y="56.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="283.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="87.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text></svg>', '{"A": "1632/5", "B": "864/5", "C": "816/5", "D": "408/5", "E": "170"}'::jsonb, 'C', NULL, 'Yan tərəflər və oturacaqların fərqi (10) üçbucaq əmələ gətirir, onun sahəsi Heron düsturu ilə 48, hündürlüyü 2·48/10 = 48/5. S = (22 + 12)/2 · 48/5 = 816/5.');
INSERT INTO public.questions VALUES (8365, 108, 'g11-geo-poly-q3-05', 3, 5, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 24 və 2 olarsa, yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,178.2 286.0,178.2 170.5,41.8 149.5,41.8"/><text x="22.6" y="189.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.4" y="189.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="172.5" y="33.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="147.5" y="33.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="195.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="160.0" y="34.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><line x1="34.0" y1="178.2" x2="170.5" y2="41.8" stroke-dasharray="5 4"/><line x1="286.0" y1="178.2" x2="149.5" y2="41.8" stroke-dasharray="5 4"/><polyline points="167.1,45.2 160.0,38.1 152.9,45.2" stroke-width="1.2"/></svg>', '{"A": "4√3", "B": "2√73", "C": "2√290", "D": "√290", "E": "13"}'::jsonb, 'D', NULL, 'h = (24 + 2)/2 = 13, yan tərəfin proyeksiyası (24 − 2)/2 = 11. c = √(169 + 121) = √290.');
INSERT INTO public.questions VALUES (8366, 108, 'g11-geo-poly-q3-06', 3, 6, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 14 və 10 olarsa, yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="71.3,186.0 248.7,186.0 223.3,34.0 96.7,34.0"/><text x="61.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="258.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="231.7" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="88.3" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><line x1="71.3" y1="186.0" x2="223.3" y2="34.0" stroke-dasharray="5 4"/><line x1="248.7" y1="186.0" x2="96.7" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,90.3 160.0,83.2 152.9,90.3" stroke-width="1.2"/></svg>', '{"A": "12", "B": "2√35", "C": "3√37", "D": "5√6", "E": "2√37"}'::jsonb, 'E', NULL, 'h = (14 + 10)/2 = 12, yan tərəfin proyeksiyası (14 − 10)/2 = 2. c = √(144 + 4) = 2√37.');
INSERT INTO public.questions VALUES (8367, 108, 'g11-geo-poly-q3-07', 3, 7, 'hard', 'open', 'Rombun tərəfi 87, diaqonallarından biri 120 olarsa, rombun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="160.0,34.0 232.4,110.0 160.0,186.0 87.6,110.0"/><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="74.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><line x1="160.0" y1="34.0" x2="160.0" y2="186.0" stroke-dasharray="5 4"/><line x1="232.4" y1="110.0" x2="87.6" y2="110.0" stroke-dasharray="5 4"/></svg>', NULL, NULL, '2520/29', 'İkinci yarımdiaqonal √(87² − 60²) = 63, d₂ = 126. S = 120·126/2 = 7560. h = S/a = 2520/29.');
INSERT INTO public.questions VALUES (8368, 108, 'g11-geo-poly-q3-08', 3, 8, 'hard', 'single', 'Trapesiyanın oturacaqları 26 və 9, yan tərəfləri 8 və 15 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,144.2 286.0,144.2 157.7,75.8 70.5,75.8"/><text x="21.7" y="153.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="152.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="164.4" y="69.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="58.9" y="74.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="166.7" y="159.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">26</text><text x="107.4" y="70.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="233.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><text x="40.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "120/17", "B": "60/13", "C": "40/9", "D": "137/17", "E": "60/17"}'::jsonb, 'A', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 8, 15 və 26 − 9 = 17 olan üçbucaq alınır. Heron düsturu: S = 60. h = 2S/17 = 120/17.');
INSERT INTO public.questions VALUES (8369, 108, 'g11-geo-poly-q3-09', 3, 9, 'hard', 'single', 'Paraleloqramın tərəfləri 2 və 6, aralarındakı bucaq 135° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="200.2,186.0 271.8,186.0 119.8,34.0 48.2,34.0"/><text x="206.2" y="202.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="282.6" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="113.8" y="27.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="37.4" y="31.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="244.5" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="112.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M218.2,186.0 A18,18 0 0 0 187.4,173.3" stroke-width="1.2"/><text x="212.0" y="162.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">135°</text></svg>', '{"A": "12", "B": "12√2", "C": "6√2", "D": "6", "E": "6√3"}'::jsonb, 'C', NULL, 'S = a·b·sin 135° = 2·6·√2/2 = 6√2.');
INSERT INTO public.questions VALUES (8370, 108, 'g11-geo-poly-q3-10', 3, 10, 'hard', 'single', 'Trapesiyanın oturacaqları 14 və 9, yan tərəfləri 5 və 6 olarsa, onun hündürlüyünü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,153.2 286.0,153.2 221.2,66.8 59.2,66.8"/><text x="21.8" y="162.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="162.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="232.3" y="65.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="47.5" y="66.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="162.7" y="169.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="137.5" y="60.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="265.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="34.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text></svg>', '{"A": "8/5", "B": "29/5", "C": "12/5", "D": "24/5", "E": "12/7"}'::jsonb, 'D', NULL, 'C təpəsindən AD-yə paralel düz xətt çəkin: tərəfləri 5, 6 və 14 − 9 = 5 olan üçbucaq alınır. Heron düsturu: S = 12. h = 2S/5 = 24/5.');
INSERT INTO public.questions VALUES (8371, 108, 'g11-geo-poly-q3-11', 3, 11, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 14 və 8, yan tərəfi 10 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="48.5,186.0 271.5,186.0 223.7,34.0 96.3,34.0"/><text x="37.7" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="282.3" y="198.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="232.1" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="87.9" y="29.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="259.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="60.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "22√91", "B": "22√23", "C": "11√91/2", "D": "11√91", "E": "110"}'::jsonb, 'D', NULL, 'h = √(10² − 3²) = √91. S = (14 + 8)/2 · h = 11√91.');
INSERT INTO public.questions VALUES (8372, 108, 'g11-geo-poly-q3-12', 3, 12, 'hard', 'single', 'Düzgün ABCDEF altıbucaqlısının tərəfi 2. AC diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="247.8,110.0 203.9,34.0 116.1,34.0 72.2,110.0 116.1,186.0 203.9,186.0"/><text x="260.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="210.4" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="109.6" y="27.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="59.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="109.6" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">E</text><text x="210.4" y="202.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">F</text><line x1="247.8" y1="110.0" x2="116.1" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "2√3", "B": "4√3", "C": "2√2", "D": "4", "E": "√3"}'::jsonb, 'A', NULL, '∠ABC = 120°: AC² = 2² + 2² − 2·2·2·cos 120° = 3·4 ⇒ AC = 2√3.');
INSERT INTO public.questions VALUES (8373, 108, 'g11-geo-poly-q3-13', 3, 13, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 18 və 6, yan tərəfi 12 olarsa, onun diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,182.7 286.0,182.7 202.0,37.3 118.0,37.3"/><text x="22.7" y="194.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.3" y="194.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="208.5" y="31.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="111.5" y="31.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="199.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="30.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="256.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><text x="64.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><line x1="34.0" y1="182.7" x2="202.0" y2="37.3" stroke-dasharray="5 4"/></svg>', '{"A": "12", "B": "√253", "C": "6√7", "D": "6√5", "E": "12√3"}'::jsonb, 'C', NULL, 'Hündürlük: h² = 12² − ((18 − 6)/2)² = 108. Diaqonalın proyeksiyası (18 + 6)/2 = 12. d = √(108 + 144) = 6√7.');
INSERT INTO public.questions VALUES (8374, 108, 'g11-geo-poly-q3-14', 3, 14, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 8 və 2, yan tərəfi 14 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="115.5,186.0 204.5,186.0 171.1,34.0 148.9,34.0"/><text x="109.0" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="211.0" y="202.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="173.0" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="147.0" y="26.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><text x="199.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="120.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text></svg>', '{"A": "5√187/2", "B": "70", "C": "10√47", "D": "5√187", "E": "10√187"}'::jsonb, 'D', NULL, 'h = √(14² − 3²) = √187. S = (8 + 2)/2 · h = 5√187.');
INSERT INTO public.questions VALUES (8375, 108, 'g11-geo-poly-q3-15', 3, 15, 'hard', 'single', 'Paraleloqramın tərəfləri 3 və 6, aralarındakı bucaq 60° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="72.2,186.0 160.0,186.0 247.8,34.0 160.0,34.0"/><text x="62.4" y="199.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="160.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="257.6" y="30.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="160.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="110.1" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="104.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M90.2,186.0 A18,18 0 0 0 81.2,170.4" stroke-width="1.2"/><text x="99.1" y="175.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="72.2" y1="186.0" x2="247.8" y2="34.0" stroke-dasharray="5 4"/><line x1="160.0" y1="186.0" x2="160.0" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "3√10", "B": "9", "C": "3√3", "D": "3√5", "E": "3√7"}'::jsonb, 'C', NULL, 'Kosinuslar teoremi: d² = 3² + 6² ∓ 2·3·6·cos 60°. Böyük diaqonal √63, kiçik diaqonal √27. Cavab: 3√3.');
INSERT INTO public.questions VALUES (8376, 108, 'g11-geo-poly-q3-16', 3, 16, 'hard', 'single', 'Paraleloqramın tərəfləri 7 və 13, aralarındakı bucaq 120° olarsa, onun kiçik diaqonalını tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="156.6,186.0 251.1,186.0 163.4,34.0 68.9,34.0"/><text x="156.0" y="204.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="261.1" y="199.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="164.0" y="26.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="58.9" y="30.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="209.9" y="201.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="100.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><path d="M174.6,186.0 A18,18 0 0 0 147.6,170.4" stroke-width="1.2"/><text x="172.1" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="156.6" y1="186.0" x2="163.4" y2="34.0" stroke-dasharray="5 4"/><line x1="251.1" y1="186.0" x2="68.9" y2="34.0" stroke-dasharray="5 4"/></svg>', '{"A": "20", "B": "√309", "C": "2√109", "D": "√218", "E": "√127"}'::jsonb, 'E', NULL, 'Kosinuslar teoremi: d² = 7² + 13² ∓ 2·7·13·cos 60°. Böyük diaqonal √309, kiçik diaqonal √127. Cavab: √127.');
INSERT INTO public.questions VALUES (8377, 108, 'g11-geo-poly-q3-17', 3, 17, 'hard', 'single', 'Trapesiyanın oturacaqları 24 və 11, yan tərəfləri 10 və 13 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,158.5 286.0,158.5 189.9,61.5 74.4,61.5"/><text x="22.1" y="168.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="167.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="198.6" y="56.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="63.6" y="59.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="163.3" y="175.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="128.8" y="55.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="249.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">13</text><text x="42.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text></svg>', '{"A": "175", "B": "2100/13", "C": "1050/13", "D": "2220/13", "E": "4200/13"}'::jsonb, 'B', NULL, 'Yan tərəflər və oturacaqların fərqi (13) üçbucaq əmələ gətirir, onun sahəsi Heron düsturu ilə 60, hündürlüyü 2·60/13 = 120/13. S = (24 + 11)/2 · 120/13 = 2100/13.');
INSERT INTO public.questions VALUES (8378, 108, 'g11-geo-poly-q3-18', 3, 18, 'hard', 'single', 'Paraleloqramın tərəfləri 11 və 4, aralarındakı bucaq 30° olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,127.4 225.6,127.4 286.0,92.6 94.4,92.6"/><text x="21.1" y="134.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="238.2" y="135.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="298.9" y="95.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="81.8" y="94.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="119.4" y="138.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">11</text><text x="52.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><path d="M52.0,127.4 A18,18 0 0 0 49.6,118.4" stroke-width="1.2"/><text x="63.9" y="124.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">30°</text></svg>', '{"A": "22", "B": "11", "C": "44", "D": "22√2", "E": "22√3"}'::jsonb, 'A', NULL, 'S = a·b·sin 30° = 11·4·1/2 = 22.');
INSERT INTO public.questions VALUES (8379, 108, 'g11-geo-poly-q3-19', 3, 19, 'hard', 'single', 'Bərabəryanlı trapesiyanın diaqonalları perpendikulyardır. Oturacaqları 9 və 7 olarsa, trapesiyanın sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="74.5,186.0 245.5,186.0 226.5,34.0 93.5,34.0"/><text x="64.8" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="255.2" y="199.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="235.1" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="84.9" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><line x1="74.5" y1="186.0" x2="226.5" y2="34.0" stroke-dasharray="5 4"/><line x1="245.5" y1="186.0" x2="93.5" y2="34.0" stroke-dasharray="5 4"/><polyline points="167.1,93.4 160.0,86.4 152.9,93.4" stroke-width="1.2"/></svg>', '{"A": "65", "B": "128", "C": "63", "D": "64", "E": "72"}'::jsonb, 'D', NULL, 'Diaqonallar kəsişmə nöqtəsində 45° bucaq altında oturacaqlara düşür, ona görə h = (9 + 7)/2 = 8. S = (9 + 7)/2 · h = 64.');
INSERT INTO public.questions VALUES (8380, 108, 'g11-geo-poly-q3-20', 3, 20, 'hard', 'single', 'Bərabəryanlı trapesiyanın oturacaqları 18 və 14, yan tərəfi 18 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="83.5,186.0 236.5,186.0 219.5,34.0 100.5,34.0"/><text x="74.3" y="200.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="245.7" y="200.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="227.5" y="28.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="92.5" y="28.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="203.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="27.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="240.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="80.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text></svg>', '{"A": "16√321", "B": "256√5", "C": "64√5", "D": "288", "E": "128√5"}'::jsonb, 'E', NULL, 'h = √(18² − 2²) = 8√5. S = (18 + 14)/2 · h = 128√5.');
INSERT INTO public.questions VALUES (8381, 109, 'g11-geo-circle-q1-01', 1, 1, 'hard', 'single', 'Radiusları 37 və 13 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 40-dır. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="143.6" cy="110.0" r="76.0"/><circle cx="225.7" cy="110.0" r="26.7"/><line x1="215.5" y1="85.4" x2="215.5" y2="134.6"/><line x1="143.6" y1="110.0" x2="225.7" y2="110.0" stroke-dasharray="5 4"/><circle cx="143.6" cy="110.0" r="2.6" fill="currentColor"/><circle cx="225.7" cy="110.0" r="2.6" fill="currentColor"/><text x="130.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="238.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "22", "B": "24", "C": "26", "D": "44", "E": "12"}'::jsonb, 'B', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(37² − h²) + √(13² − h²) = 40. h = 12 yoxlanır: √1225 + √25 = 35 + 5 = 40. Vətər 2h = 24.');
INSERT INTO public.questions VALUES (8382, 109, 'g11-geo-circle-q1-02', 1, 2, 'hard', 'single', 'Radiusları 25 və 39 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 56-dır. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="91.8" cy="110.0" r="48.7"/><circle cx="200.9" cy="110.0" r="76.0"/><line x1="130.8" y1="80.8" x2="130.8" y2="139.2"/><line x1="91.8" y1="110.0" x2="200.9" y2="110.0" stroke-dasharray="5 4"/><circle cx="91.8" cy="110.0" r="2.6" fill="currentColor"/><circle cx="200.9" cy="110.0" r="2.6" fill="currentColor"/><text x="78.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="213.9" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "28", "B": "32", "C": "42", "D": "30", "E": "15"}'::jsonb, 'D', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(25² − h²) + √(39² − h²) = 56. h = 15 yoxlanır: √400 + √1296 = 20 + 36 = 56. Vətər 2h = 30.');
INSERT INTO public.questions VALUES (8383, 109, 'g11-geo-circle-q1-03', 1, 3, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 8 və 2 olarsa, çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "5", "B": "5/2", "C": "2", "D": "4", "E": "3"}'::jsonb, 'C', NULL, 'Toxunanlar xassəsi: 2c = 8 + 2 ⇒ c = 5. h = √(c² − ((8 − 2)/2)²) = √16 = 4, r = h/2 = 2.');
INSERT INTO public.questions VALUES (8384, 109, 'g11-geo-circle-q1-04', 1, 4, 'hard', 'single', 'Radiusu 15 olan çevrədə uzunluqları 18 və 24 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="155.6" x2="220.8" y2="155.6"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "21", "B": "23", "C": "22", "D": "20", "E": "3"}'::jsonb, 'A', NULL, 'Mərkəzdən məsafələr: √(15² − 9²) = 12 və √(15² − 12²) = 9. Cəm: 21.');
INSERT INTO public.questions VALUES (8385, 109, 'g11-geo-circle-q1-05', 1, 5, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 1, AB = 2 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="126.5" y1="184.1" x2="176.8" y2="184.1"/><line x1="126.5" y1="184.1" x2="106.0" y2="163.5"/><circle cx="126.5" cy="184.1" r="2.6" fill="currentColor"/><text x="113.5" y="189.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="140.4" y="201.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="179.6" y="201.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="96.8" y="177.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "2", "B": "√6", "C": "√5", "D": "√2", "E": "√3"}'::jsonb, 'E', NULL, 'PB = PA + AB = 3. Toxunan-kəsən teoremi: PT² = PA·PB = 1·3 = 3 ⇒ PT = √3.');
INSERT INTO public.questions VALUES (8386, 109, 'g11-geo-circle-q1-06', 1, 6, 'hard', 'single', 'Radiusu 13 olan çevrədə uzunluqları 24 və 10 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="89.8" y1="80.8" x2="230.2" y2="80.8"/><line x1="130.8" y1="180.2" x2="189.2" y2="180.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "17", "B": "18", "C": "19", "D": "16", "E": "7"}'::jsonb, 'A', NULL, 'Mərkəzdən məsafələr: √(13² − 12²) = 5 və √(13² − 5²) = 12. Cəm: 17.');
INSERT INTO public.questions VALUES (8387, 109, 'g11-geo-circle-q1-07', 1, 7, 'hard', 'single', 'Radiusu 6 olan çevrədə 60°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "6π − 18√3", "B": "6π − 9√3", "C": "6π + 9√3", "D": "6π", "E": "12π − 9√3"}'::jsonb, 'B', NULL, 'Seqment = sektor − üçbucaq: πR²·60/360 − ½R²·sin 60° = 6π − 9√3.');
INSERT INTO public.questions VALUES (8388, 109, 'g11-geo-circle-q1-08', 1, 8, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 5, AB = 23 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="176.3" cy="110.0" r="76.0"/><line x1="67.7" y1="117.0" x2="252.0" y2="117.0"/><line x1="67.7" y1="117.0" x2="119.8" y2="59.2"/><circle cx="67.7" cy="117.0" r="2.6" fill="currentColor"/><text x="54.7" y="122.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="87.7" y="123.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="264.9" y="123.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="110.1" y="55.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "2√35", "B": "√145", "C": "√554", "D": "√115", "E": "2√161"}'::jsonb, 'A', NULL, 'PB = PA + AB = 28. Toxunan-kəsən teoremi: PT² = PA·PB = 5·28 = 140 ⇒ PT = 2√35.');
INSERT INTO public.questions VALUES (8389, 109, 'g11-geo-circle-q1-09', 1, 9, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√21 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "42π", "B": "84π", "C": "21π", "D": "21π/2", "E": "22π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 21. Halqanın sahəsi π(R² − r²) = 21π.');
INSERT INTO public.questions VALUES (8390, 109, 'g11-geo-circle-q1-10', 1, 10, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 20 və 21 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="107.6,165.0 212.4,165.0 107.6,55.0"/><text x="98.6" y="179.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="223.9" y="176.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="102.0" y="48.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="117.6,165.0 117.6,155.0 107.6,155.0" stroke-width="1.2"/><circle cx="139.0" cy="133.6" r="31.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="165.2" y="180.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="97.0" y="109.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">21</text></svg>', '{"A": "√145/2", "B": "√1537/2", "C": "17/2", "D": "√493/2", "E": "√697/2"}'::jsonb, 'A', NULL, 'r = 6, R = 29/2. Eyler düsturu: d² = R² − 2Rr = 841/4 − 174 = 145/4 ⇒ d = √145/2.');
INSERT INTO public.questions VALUES (8391, 109, 'g11-geo-circle-q1-11', 1, 11, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 24 və 45 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="124.2,177.1 195.8,177.1 124.2,42.9"/><text x="118.1" y="193.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="205.2" y="191.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="120.9" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="134.2,177.1 134.2,167.1 124.2,167.1" stroke-width="1.2"/><circle cx="151.1" cy="150.2" r="26.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="163.1" y="193.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="115.5" y="106.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">45</text></svg>', '{"A": "3√187/2", "B": "3√85/2", "C": "3√493/2", "D": "3√253/2", "E": "33/2"}'::jsonb, 'B', NULL, 'r = 9, R = 51/2. Eyler düsturu: d² = R² − 2Rr = 2601/4 − 459 = 765/4 ⇒ d = 3√85/2.');
INSERT INTO public.questions VALUES (8392, 109, 'g11-geo-circle-q1-12', 1, 12, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 16 və 4 olarsa, çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "8", "B": "6", "C": "10", "D": "4", "E": "5"}'::jsonb, 'D', NULL, 'Toxunanlar xassəsi: 2c = 16 + 4 ⇒ c = 10. h = √(c² − ((16 − 4)/2)²) = √64 = 8, r = h/2 = 4.');
INSERT INTO public.questions VALUES (8393, 109, 'g11-geo-circle-q1-13', 1, 13, 'hard', 'single', 'Radiusları 15 və 41 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 52-dir. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="87.7" cy="110.0" r="27.8"/><circle cx="184.1" cy="110.0" r="76.0"/><line x1="110.0" y1="93.3" x2="110.0" y2="126.7"/><line x1="87.7" y1="110.0" x2="184.1" y2="110.0" stroke-dasharray="5 4"/><circle cx="87.7" cy="110.0" r="2.6" fill="currentColor"/><circle cx="184.1" cy="110.0" r="2.6" fill="currentColor"/><text x="74.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="197.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "9", "B": "18", "C": "52", "D": "20", "E": "16"}'::jsonb, 'B', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(15² − h²) + √(41² − h²) = 52. h = 9 yoxlanır: √144 + √1600 = 12 + 40 = 52. Vətər 2h = 18.');
INSERT INTO public.questions VALUES (8394, 109, 'g11-geo-circle-q1-14', 1, 14, 'hard', 'open', 'Radiusu 17 olan çevrədə uzunluqları 30 və 16 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="92.9" y1="74.2" x2="227.1" y2="74.2"/><line x1="124.2" y1="177.1" x2="195.8" y2="177.1"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', NULL, NULL, '23', 'Mərkəzdən məsafələr: √(17² − 15²) = 8 və √(17² − 8²) = 15. Cəm: 23.');
INSERT INTO public.questions VALUES (8395, 109, 'g11-geo-circle-q1-15', 1, 15, 'hard', 'single', 'Radiusu 26 olan çevrədə uzunluqları 48 və 20 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="89.8" y1="80.8" x2="230.2" y2="80.8"/><line x1="130.8" y1="180.2" x2="189.2" y2="180.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "14", "B": "36", "C": "33", "D": "34", "E": "35"}'::jsonb, 'D', NULL, 'Mərkəzdən məsafələr: √(26² − 24²) = 10 və √(26² − 10²) = 24. Cəm: 34.');
INSERT INTO public.questions VALUES (8396, 109, 'g11-geo-circle-q1-16', 1, 16, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 4√14 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "56π", "B": "28π", "C": "112π", "D": "57π", "E": "224π"}'::jsonb, 'A', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 56. Halqanın sahəsi π(R² − r²) = 56π.');
INSERT INTO public.questions VALUES (8397, 109, 'g11-geo-circle-q1-17', 1, 17, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 10√3 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "75π/2", "B": "300π", "C": "75π", "D": "150π", "E": "76π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 75. Halqanın sahəsi π(R² − r²) = 75π.');
INSERT INTO public.questions VALUES (8398, 109, 'g11-geo-circle-q1-18', 1, 18, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 12, AB = 23 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="199.5" cy="110.0" r="76.0"/><line x1="44.5" y1="115.1" x2="275.3" y2="115.1"/><line x1="44.5" y1="115.1" x2="160.1" y2="45.0"/><circle cx="44.5" cy="115.1" r="2.6" fill="currentColor"/><text x="31.5" y="120.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="110.7" y="121.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="288.3" y="121.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="153.3" y="38.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "12√3", "B": "√805", "C": "2√69", "D": "2√105", "E": "√673"}'::jsonb, 'D', NULL, 'PB = PA + AB = 35. Toxunan-kəsən teoremi: PT² = PA·PB = 12·35 = 420 ⇒ PT = 2√105.');
INSERT INTO public.questions VALUES (8399, 109, 'g11-geo-circle-q1-19', 1, 19, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 3 və 4 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.4,170.8 205.6,170.8 114.4,49.2"/><text x="106.6" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="216.4" y="183.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="109.8" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="124.4,170.8 124.4,160.8 114.4,160.8" stroke-width="1.2"/><circle cx="144.8" cy="140.4" r="30.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="164.2" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="104.4" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text></svg>', '{"A": "7", "B": "6", "C": "9/2", "D": "4", "E": "7/2"}'::jsonb, 'E', NULL, 'Hipotenuz 5. r = (a + b − c)/2 = 1, R = c/2 = 5/2. Cəm: 7/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (8400, 109, 'g11-geo-circle-q1-20', 1, 20, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 8, AB = 10 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="201.3" cy="110.0" r="76.0"/><line x1="42.7" y1="155.4" x2="262.3" y2="155.4"/><line x1="42.7" y1="155.4" x2="149.1" y2="54.8"/><circle cx="42.7" cy="155.4" r="2.6" fill="currentColor"/><text x="29.7" y="160.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="129.9" y="168.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="272.7" y="168.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="140.1" y="50.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "2√38", "B": "4√5", "C": "12", "D": "6√5", "E": "2√41"}'::jsonb, 'C', NULL, 'PB = PA + AB = 18. Toxunan-kəsən teoremi: PT² = PA·PB = 8·18 = 144 ⇒ PT = 12.');
INSERT INTO public.questions VALUES (8401, 109, 'g11-geo-circle-q2-01', 2, 1, 'hard', 'single', 'Radiusu 25 olan çevrədə uzunluqları 14 və 40 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="138.7" y1="37.0" x2="181.3" y2="37.0"/><line x1="99.2" y1="155.6" x2="220.8" y2="155.6"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "27", "B": "40", "C": "9", "D": "13", "E": "39"}'::jsonb, 'E', NULL, 'Mərkəzdən məsafələr: √(25² − 7²) = 24 və √(25² − 20²) = 15. Cəm: 39.');
INSERT INTO public.questions VALUES (8402, 109, 'g11-geo-circle-q2-02', 2, 2, 'hard', 'single', 'Radiusları 51 və 26 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 55-dir. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="137.6" cy="110.0" r="76.0"/><circle cx="219.6" cy="110.0" r="38.7"/><line x1="204.7" y1="74.2" x2="204.7" y2="145.8"/><line x1="137.6" y1="110.0" x2="219.6" y2="110.0" stroke-dasharray="5 4"/><circle cx="137.6" cy="110.0" r="2.6" fill="currentColor"/><circle cx="219.6" cy="110.0" r="2.6" fill="currentColor"/><text x="124.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="232.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "46", "B": "48", "C": "24", "D": "50", "E": "52"}'::jsonb, 'B', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(51² − h²) + √(26² − h²) = 55. h = 24 yoxlanır: √2025 + √100 = 45 + 10 = 55. Vətər 2h = 48.');
INSERT INTO public.questions VALUES (8403, 109, 'g11-geo-circle-q2-03', 2, 3, 'hard', 'single', 'Radiusu 10 olan çevrədə uzunluqları 12 və 16 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="155.6" x2="220.8" y2="155.6"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "13", "B": "2", "C": "14", "D": "15", "E": "16"}'::jsonb, 'C', NULL, 'Mərkəzdən məsafələr: √(10² − 6²) = 8 və √(10² − 8²) = 6. Cəm: 14.');
INSERT INTO public.questions VALUES (8404, 109, 'g11-geo-circle-q2-04', 2, 4, 'hard', 'single', 'Radiusu 17 olan çevrədə uzunluqları 16 və 30 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="124.2" y1="42.9" x2="195.8" y2="42.9"/><line x1="92.9" y1="74.2" x2="227.1" y2="74.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "7", "B": "6", "C": "23", "D": "8", "E": "9"}'::jsonb, 'A', NULL, 'Mərkəzdən məsafələr: √(17² − 8²) = 15 və √(17² − 15²) = 8. Fərq: 7.');
INSERT INTO public.questions VALUES (8405, 109, 'g11-geo-circle-q2-05', 2, 5, 'hard', 'single', 'Radiusları 25 və 52 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 63-dür. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="94.2" cy="110.0" r="36.5"/><circle cx="186.3" cy="110.0" r="76.0"/><line x1="116.2" y1="80.8" x2="116.2" y2="139.2"/><line x1="94.2" y1="110.0" x2="186.3" y2="110.0" stroke-dasharray="5 4"/><circle cx="94.2" cy="110.0" r="2.6" fill="currentColor"/><circle cx="186.3" cy="110.0" r="2.6" fill="currentColor"/><text x="81.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="199.3" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "40", "B": "42", "C": "38", "D": "20", "E": "58"}'::jsonb, 'A', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(25² − h²) + √(52² − h²) = 63. h = 20 yoxlanır: √225 + √2304 = 15 + 48 = 63. Vətər 2h = 40.');
INSERT INTO public.questions VALUES (8406, 109, 'g11-geo-circle-q2-06', 2, 6, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 27 və 120 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="143.3,184.1 176.7,184.1 143.3,35.9"/><text x="140.5" y="201.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="182.0" y="201.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="141.9" y="27.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="153.3,184.1 153.3,174.1 143.3,174.1" stroke-width="1.2"/><circle cx="158.1" cy="169.3" r="14.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.3" y="201.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">27</text><text x="138.4" y="104.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">120</text></svg>', '{"A": "74", "B": "147", "C": "135", "D": "149/2", "E": "147/2"}'::jsonb, 'E', NULL, 'Hipotenuz 123. r = (a + b − c)/2 = 12, R = c/2 = 123/2. Cəm: 147/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (8407, 109, 'g11-geo-circle-q2-07', 2, 7, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 1, AB = 10 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="161.8" cy="110.0" r="76.0"/><line x1="82.2" y1="147.2" x2="228.0" y2="147.2"/><line x1="82.2" y1="147.2" x2="86.0" y2="103.4"/><circle cx="82.2" cy="147.2" r="2.6" fill="currentColor"/><text x="69.2" y="152.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="84.2" y="158.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="239.4" y="158.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="73.1" y="107.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√11", "B": "√110", "C": "√10", "D": "2√3", "E": "√101"}'::jsonb, 'A', NULL, 'PB = PA + AB = 11. Toxunan-kəsən teoremi: PT² = PA·PB = 1·11 = 11 ⇒ PT = √11.');
INSERT INTO public.questions VALUES (8408, 109, 'g11-geo-circle-q2-08', 2, 8, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 4, AB = 10 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="174.9" cy="110.0" r="76.0"/><line x1="69.1" y1="158.2" x2="233.6" y2="158.2"/><line x1="69.1" y1="158.2" x2="105.8" y2="78.3"/><circle cx="69.1" cy="158.2" r="2.6" fill="currentColor"/><text x="56.1" y="163.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="106.1" y="171.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="243.7" y="171.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="94.0" y="77.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "2√15", "B": "2√35", "C": "2√29", "D": "2√14", "E": "2√10"}'::jsonb, 'D', NULL, 'PB = PA + AB = 14. Toxunan-kəsən teoremi: PT² = PA·PB = 4·14 = 56 ⇒ PT = 2√14.');
INSERT INTO public.questions VALUES (8409, 109, 'g11-geo-circle-q2-09', 2, 9, 'hard', 'single', 'Radiusu 14 olan çevrədə 60°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "98π/3 + 49√3", "B": "196π/3 − 49√3", "C": "98π/3 − 98√3", "D": "98π/3", "E": "98π/3 − 49√3"}'::jsonb, 'E', NULL, 'Seqment = sektor − üçbucaq: πR²·60/360 − ½R²·sin 60° = 98π/3 − 49√3.');
INSERT INTO public.questions VALUES (8410, 109, 'g11-geo-circle-q2-10', 2, 10, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 18 və 2 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.0 286.0,152.0 174.0,68.0 146.0,68.0"/><text x="21.7" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.1" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="141.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="169.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><circle cx="160.0" cy="110.0" r="42.0"/></svg>', '{"A": "100", "B": "60", "C": "36", "D": "30", "E": "66"}'::jsonb, 'B', NULL, 'c = (18 + 2)/2 = 10, h = √(ab) = 6. S = (18 + 2)/2·6 = 60.');
INSERT INTO public.questions VALUES (8411, 109, 'g11-geo-circle-q2-11', 2, 11, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 8, AB = 14 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="202.5" cy="110.0" r="76.0"/><line x1="41.5" y1="121.1" x2="277.7" y2="121.1"/><line x1="41.5" y1="121.1" x2="162.2" y2="45.6"/><circle cx="41.5" cy="121.1" r="2.6" fill="currentColor"/><text x="28.5" y="126.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="114.5" y="128.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="290.6" y="128.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="155.3" y="39.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "4√7", "B": "2√77", "C": "4√11", "D": "2√65", "E": "2√46"}'::jsonb, 'C', NULL, 'PB = PA + AB = 22. Toxunan-kəsən teoremi: PT² = PA·PB = 8·22 = 176 ⇒ PT = 4√11.');
INSERT INTO public.questions VALUES (8412, 109, 'g11-geo-circle-q2-12', 2, 12, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 24 və 6 olarsa, çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "7", "B": "9", "C": "15/2", "D": "12", "E": "6"}'::jsonb, 'E', NULL, 'Toxunanlar xassəsi: 2c = 24 + 6 ⇒ c = 15. h = √(c² − ((24 − 6)/2)²) = √144 = 12, r = h/2 = 6.');
INSERT INTO public.questions VALUES (8413, 109, 'g11-geo-circle-q2-13', 2, 13, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 24 və 45 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="124.2,177.1 195.8,177.1 124.2,42.9"/><text x="118.1" y="193.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="205.2" y="191.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="120.9" y="35.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="134.2,177.1 134.2,167.1 124.2,167.1" stroke-width="1.2"/><circle cx="151.1" cy="150.2" r="26.8"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="163.1" y="193.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text><text x="115.5" y="106.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">45</text></svg>', '{"A": "71/2", "B": "69", "C": "60", "D": "35", "E": "69/2"}'::jsonb, 'E', NULL, 'Hipotenuz 51. r = (a + b − c)/2 = 9, R = c/2 = 51/2. Cəm: 69/2 (= (a + b)/2).');
INSERT INTO public.questions VALUES (8414, 109, 'g11-geo-circle-q2-14', 2, 14, 'hard', 'single', 'Radiusu 4 olan çevrədə 60°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "8π/3 − 4√3", "B": "8π/3", "C": "16π/3 − 4√3", "D": "8π/3 − 8√3", "E": "8π/3 + 4√3"}'::jsonb, 'A', NULL, 'Seqment = sektor − üçbucaq: πR²·60/360 − ½R²·sin 60° = 8π/3 − 4√3.');
INSERT INTO public.questions VALUES (8415, 109, 'g11-geo-circle-q2-15', 2, 15, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 7 və 24 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="138.7,183.0 181.3,183.0 138.7,37.0"/><text x="135.1" y="200.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="187.8" y="199.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="136.8" y="29.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="148.7,183.0 148.7,173.0 138.7,173.0" stroke-width="1.2"/><circle cx="157.0" cy="164.7" r="18.2"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="161.7" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">7</text><text x="132.7" y="104.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">24</text></svg>', '{"A": "19/2", "B": "5√19/2", "C": "√589/2", "D": "5√13/2", "E": "5√37/2"}'::jsonb, 'D', NULL, 'r = 3, R = 25/2. Eyler düsturu: d² = R² − 2Rr = 625/4 − 75 = 325/4 ⇒ d = 5√13/2.');
INSERT INTO public.questions VALUES (8416, 109, 'g11-geo-circle-q2-16', 2, 16, 'hard', 'single', 'Radiusu 10 olan çevrədə 90°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "25π + 50", "B": "25π − 50", "C": "50π − 50", "D": "25π − 100", "E": "25π"}'::jsonb, 'B', NULL, 'Seqment = sektor − üçbucaq: πR²·90/360 − ½R²·sin 90° = 25π − 50.');
INSERT INTO public.questions VALUES (8417, 109, 'g11-geo-circle-q2-17', 2, 17, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√115 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "115π/2", "B": "230π", "C": "115π", "D": "116π", "E": "460π"}'::jsonb, 'C', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 115. Halqanın sahəsi π(R² − r²) = 115π.');
INSERT INTO public.questions VALUES (8418, 109, 'g11-geo-circle-q2-18', 2, 18, 'hard', 'single', 'Radiusları 13 və 20 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 21-dir. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="106.8" cy="110.0" r="49.4"/><circle cx="186.6" cy="110.0" r="76.0"/><line x1="125.8" y1="64.4" x2="125.8" y2="155.6"/><line x1="106.8" y1="110.0" x2="186.6" y2="110.0" stroke-dasharray="5 4"/><circle cx="106.8" cy="110.0" r="2.6" fill="currentColor"/><circle cx="186.6" cy="110.0" r="2.6" fill="currentColor"/><text x="93.8" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="199.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "22", "B": "12", "C": "17", "D": "24", "E": "26"}'::jsonb, 'D', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(13² − h²) + √(20² − h²) = 21. h = 12 yoxlanır: √25 + √256 = 5 + 16 = 21. Vətər 2h = 24.');
INSERT INTO public.questions VALUES (8419, 109, 'g11-geo-circle-q2-19', 2, 19, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 7, AB = 7 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="193.6" cy="110.0" r="76.0"/><line x1="50.4" y1="169.1" x2="241.3" y2="169.1"/><line x1="50.4" y1="169.1" x2="133.8" y2="63.0"/><circle cx="50.4" cy="169.1" r="2.6" fill="currentColor"/><text x="37.4" y="174.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="137.7" y="184.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="249.5" y="184.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="123.6" y="60.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "7", "B": "√105", "C": "8√2", "D": "21/2", "E": "7√2"}'::jsonb, 'E', NULL, 'PB = PA + AB = 14. Toxunan-kəsən teoremi: PT² = PA·PB = 7·14 = 98 ⇒ PT = 7√2.');
INSERT INTO public.questions VALUES (8420, 109, 'g11-geo-circle-q2-20', 2, 20, 'hard', 'single', 'Radiusu 20 olan çevrədə uzunluqları 24 və 32 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "6", "B": "28", "C": "4", "D": "3", "E": "5"}'::jsonb, 'C', NULL, 'Mərkəzdən məsafələr: √(20² − 12²) = 16 və √(20² − 16²) = 12. Fərq: 4.');
INSERT INTO public.questions VALUES (8421, 109, 'g11-geo-circle-q3-01', 3, 1, 'hard', 'single', 'Radiusu 4 olan çevrədə 120°-li qövsə söykənən vətər çəkilib. Vətərlə bu qövs arasındakı seqmentin sahəsini tapın.', NULL, NULL, '{"A": "32π/3 − 4√3", "B": "16π/3", "C": "16π/3 + 4√3", "D": "16π/3 − 4√3", "E": "16π/3 − 8√3"}'::jsonb, 'D', NULL, 'Seqment = sektor − üçbucaq: πR²·120/360 − ½R²·sin 120° = 16π/3 − 4√3.');
INSERT INTO public.questions VALUES (8422, 109, 'g11-geo-circle-q3-02', 3, 2, 'hard', 'single', 'Bərabəryanlı trapesiyaya çevrə daxil çəkilib. Trapesiyanın oturacaqları 27 və 3 olarsa, onun sahəsini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.0 286.0,152.0 174.0,68.0 146.0,68.0"/><text x="21.7" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.1" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="141.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="169.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">27</text><text x="160.0" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><circle cx="160.0" cy="110.0" r="42.0"/></svg>', '{"A": "144", "B": "135", "C": "81", "D": "225", "E": "135/2"}'::jsonb, 'B', NULL, 'c = (27 + 3)/2 = 15, h = √(ab) = 9. S = (27 + 3)/2·9 = 135.');
INSERT INTO public.questions VALUES (8423, 109, 'g11-geo-circle-q3-03', 3, 3, 'hard', 'single', 'Radiusu 20 olan çevrədə uzunluqları 32 və 24 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><line x1="114.4" y1="170.8" x2="205.6" y2="170.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "30", "B": "27", "C": "4", "D": "29", "E": "28"}'::jsonb, 'E', NULL, 'Mərkəzdən məsafələr: √(20² − 16²) = 12 və √(20² − 12²) = 16. Cəm: 28.');
INSERT INTO public.questions VALUES (8424, 109, 'g11-geo-circle-q3-04', 3, 4, 'hard', 'single', 'Radiusu 20 olan çevrədə uzunluqları 24 və 32 olan paralel vətərlər çəkilib. Vətərlər mərkəzin müxtəlif tərəflərində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><line x1="99.2" y1="155.6" x2="220.8" y2="155.6"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "27", "B": "30", "C": "29", "D": "28", "E": "4"}'::jsonb, 'D', NULL, 'Mərkəzdən məsafələr: √(20² − 12²) = 16 və √(20² − 16²) = 12. Cəm: 28.');
INSERT INTO public.questions VALUES (8425, 109, 'g11-geo-circle-q3-05', 3, 5, 'hard', 'single', 'Radiusu 5 olan çevrədə uzunluqları 8 və 6 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="99.2" y1="64.4" x2="220.8" y2="64.4"/><line x1="114.4" y1="49.2" x2="205.6" y2="49.2"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "3", "B": "0", "C": "2", "D": "7", "E": "1"}'::jsonb, 'E', NULL, 'Mərkəzdən məsafələr: √(5² − 4²) = 3 və √(5² − 3²) = 4. Fərq: 1.');
INSERT INTO public.questions VALUES (8426, 109, 'g11-geo-circle-q3-06', 3, 6, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 3, AB = 25 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="169.1" cy="110.0" r="76.0"/><line x1="74.9" y1="113.9" x2="245.0" y2="113.9"/><line x1="74.9" y1="113.9" x2="105.9" y2="67.7"/><circle cx="74.9" cy="113.9" r="2.6" fill="currentColor"/><text x="61.9" y="118.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="80.2" y="119.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="257.9" y="119.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="95.1" y="65.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√634", "B": "10√7", "C": "5√3", "D": "2√21", "E": "√87"}'::jsonb, 'D', NULL, 'PB = PA + AB = 28. Toxunan-kəsən teoremi: PT² = PA·PB = 3·28 = 84 ⇒ PT = 2√21.');
INSERT INTO public.questions VALUES (8427, 109, 'g11-geo-circle-q3-07', 3, 7, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 5 və 12 olarsa, daxili və xarici çəkilmiş çevrələrin mərkəzləri arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="130.8,180.2 189.2,180.2 130.8,39.8"/><text x="125.8" y="197.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="197.6" y="195.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="128.1" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="140.8,180.2 140.8,170.2 130.8,170.2" stroke-width="1.2"/><circle cx="154.2" cy="156.8" r="23.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="162.4" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="123.1" y="105.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text></svg>', '{"A": "3√17/2", "B": "9/2", "C": "3√13/2", "D": "√65/2", "E": "√273/2"}'::jsonb, 'D', NULL, 'r = 2, R = 13/2. Eyler düsturu: d² = R² − 2Rr = 169/4 − 26 = 65/4 ⇒ d = √65/2.');
INSERT INTO public.questions VALUES (8428, 109, 'g11-geo-circle-q3-08', 3, 8, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√105 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "105π", "B": "106π", "C": "105π/2", "D": "210π", "E": "420π"}'::jsonb, 'A', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 105. Halqanın sahəsi π(R² − r²) = 105π.');
INSERT INTO public.questions VALUES (8429, 109, 'g11-geo-circle-q3-09', 3, 9, 'hard', 'single', 'Bərabəryanlı trapesiyaya radiusu 3 olan çevrə daxil çəkilib. Kiçik oturacaq 2 olarsa, trapesiyanın yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,152.0 286.0,152.0 174.0,68.0 146.0,68.0"/><text x="21.7" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.3" y="161.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="178.1" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="141.9" y="60.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="169.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">18</text><text x="160.0" y="61.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">2</text><circle cx="160.0" cy="110.0" r="42.0"/></svg>', '{"A": "6", "B": "18", "C": "8", "D": "11", "E": "10"}'::jsonb, 'E', NULL, 'h = 2r = 6. h² = ab ⇒ a = 36/2 = 18. c = (a + b)/2 = 10.');
INSERT INTO public.questions VALUES (8430, 109, 'g11-geo-circle-q3-10', 3, 10, 'hard', 'single', 'Radiusları 52 və 29 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 69-dur. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="126.4" cy="110.0" r="76.0"/><circle cx="227.2" cy="110.0" r="42.4"/><line x1="196.5" y1="80.8" x2="196.5" y2="139.2"/><line x1="126.4" y1="110.0" x2="227.2" y2="110.0" stroke-dasharray="5 4"/><circle cx="126.4" cy="110.0" r="2.6" fill="currentColor"/><circle cx="227.2" cy="110.0" r="2.6" fill="currentColor"/><text x="113.4" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="240.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "40", "B": "20", "C": "42", "D": "57", "E": "38"}'::jsonb, 'A', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(52² − h²) + √(29² − h²) = 69. h = 20 yoxlanır: √2304 + √441 = 48 + 21 = 69. Vətər 2h = 40.');
INSERT INTO public.questions VALUES (8431, 109, 'g11-geo-circle-q3-11', 3, 11, 'hard', 'single', 'Radiusları 17 və 10 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 21-dir. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="128.7" cy="110.0" r="76.0"/><circle cx="222.6" cy="110.0" r="44.7"/><line x1="195.8" y1="74.2" x2="195.8" y2="145.8"/><line x1="128.7" y1="110.0" x2="222.6" y2="110.0" stroke-dasharray="5 4"/><circle cx="128.7" cy="110.0" r="2.6" fill="currentColor"/><circle cx="222.6" cy="110.0" r="2.6" fill="currentColor"/><text x="115.7" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="235.6" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "18", "B": "17", "C": "8", "D": "16", "E": "14"}'::jsonb, 'D', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(17² − h²) + √(10² − h²) = 21. h = 8 yoxlanır: √225 + √36 = 15 + 6 = 21. Vətər 2h = 16.');
INSERT INTO public.questions VALUES (8432, 109, 'g11-geo-circle-q3-12', 3, 12, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√55 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "55π", "B": "55π/2", "C": "220π", "D": "110π", "E": "56π"}'::jsonb, 'A', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 55. Halqanın sahəsi π(R² − r²) = 55π.');
INSERT INTO public.questions VALUES (8433, 109, 'g11-geo-circle-q3-13', 3, 13, 'hard', 'single', 'Düzbucaqlı üçbucağın katetləri 6 və 8 olarsa, ona daxil və xaricdən çəkilmiş çevrələrin radiuslarının cəmini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="114.4,170.8 205.6,170.8 114.4,49.2"/><text x="106.6" y="186.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="216.4" y="183.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="109.8" y="42.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><polyline points="124.4,170.8 124.4,160.8 114.4,160.8" stroke-width="1.2"/><circle cx="144.8" cy="140.4" r="30.4"/><circle cx="160.0" cy="110.0" r="76.0"/><text x="164.2" y="187.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><text x="104.4" y="108.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">8</text></svg>', '{"A": "14", "B": "12", "C": "6", "D": "7", "E": "8"}'::jsonb, 'D', NULL, 'Hipotenuz 10. r = (a + b − c)/2 = 2, R = c/2 = 5. Cəm: 7 (= (a + b)/2).');
INSERT INTO public.questions VALUES (8434, 109, 'g11-geo-circle-q3-14', 3, 14, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 11, AB = 21 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="193.2" cy="110.0" r="76.0"/><line x1="50.8" y1="140.6" x2="262.8" y2="140.6"/><line x1="50.8" y1="140.6" x2="140.9" y2="54.9"/><circle cx="50.8" cy="140.6" r="2.6" fill="currentColor"/><text x="37.8" y="145.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="111.8" y="150.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="274.7" y="150.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="131.9" y="50.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√562", "B": "11√3", "C": "4√22", "D": "√231", "E": "4√42"}'::jsonb, 'C', NULL, 'PB = PA + AB = 32. Toxunan-kəsən teoremi: PT² = PA·PB = 11·32 = 352 ⇒ PT = 4√22.');
INSERT INTO public.questions VALUES (8435, 109, 'g11-geo-circle-q3-15', 3, 15, 'hard', 'single', 'Radiusları 39 və 25 olan iki çevrə kəsişir, mərkəzləri arasındakı məsafə 56-dır. Ortaq vətərin uzunluğunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="119.1" cy="110.0" r="76.0"/><circle cx="228.2" cy="110.0" r="48.7"/><line x1="189.2" y1="80.8" x2="189.2" y2="139.2"/><line x1="119.1" y1="110.0" x2="228.2" y2="110.0" stroke-dasharray="5 4"/><circle cx="119.1" cy="110.0" r="2.6" fill="currentColor"/><circle cx="228.2" cy="110.0" r="2.6" fill="currentColor"/><text x="106.1" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₁</text><text x="241.2" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O₂</text></svg>', '{"A": "30", "B": "42", "C": "15", "D": "28", "E": "32"}'::jsonb, 'A', NULL, 'Ortaq vətər O₁O₂-yə perpendikulyardır və onu yarıya bölür. Yarım vətər h: √(39² − h²) + √(25² − h²) = 56. h = 15 yoxlanır: √1296 + √400 = 36 + 20 = 56. Vətər 2h = 30.');
INSERT INTO public.questions VALUES (8436, 109, 'g11-geo-circle-q3-16', 3, 16, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 8, AB = 25 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="178.2" cy="110.0" r="76.0"/><line x1="65.8" y1="142.9" x2="246.7" y2="142.9"/><line x1="65.8" y1="142.9" x2="114.6" y2="68.4"/><circle cx="65.8" cy="142.9" r="2.6" fill="currentColor"/><text x="52.8" y="147.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="97.9" y="153.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="258.4" y="153.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="103.7" y="66.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "√689", "B": "4√17", "C": "5√33", "D": "10√2", "E": "2√66"}'::jsonb, 'E', NULL, 'PB = PA + AB = 33. Toxunan-kəsən teoremi: PT² = PA·PB = 8·33 = 264 ⇒ PT = 2√66.');
INSERT INTO public.questions VALUES (8437, 109, 'g11-geo-circle-q3-17', 3, 17, 'hard', 'single', 'Radiusu 26 olan çevrədə uzunluqları 20 və 48 olan paralel vətərlər çəkilib. Vətərlər mərkəzin eyni tərəfində yerləşir. Vətərlər arasındakı məsafəni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="160.0" cy="110.0" r="76.0"/><line x1="130.8" y1="39.8" x2="189.2" y2="39.8"/><line x1="89.8" y1="80.8" x2="230.2" y2="80.8"/><circle cx="160.0" cy="110.0" r="2.6" fill="currentColor"/><text x="147.0" y="115.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">O</text></svg>', '{"A": "13", "B": "14", "C": "34", "D": "16", "E": "15"}'::jsonb, 'B', NULL, 'Mərkəzdən məsafələr: √(26² − 10²) = 24 və √(26² − 24²) = 10. Fərq: 14.');
INSERT INTO public.questions VALUES (8438, 109, 'g11-geo-circle-q3-18', 3, 18, 'hard', 'single', 'Çevrədən kənardakı P nöqtəsindən PT toxunanı və çevrəni A və B nöqtələrində kəsən kəsən çəkilib (A nöqtəsi P ilə B arasındadır). PA = 2, AB = 12 olarsa, PT-ni tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><circle cx="166.5" cy="110.0" r="76.0"/><line x1="77.5" y1="146.4" x2="233.2" y2="146.4"/><line x1="77.5" y1="146.4" x2="93.2" y2="89.7"/><circle cx="77.5" cy="146.4" r="2.6" fill="currentColor"/><text x="64.5" y="151.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">P</text><text x="88.4" y="157.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="244.6" y="157.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="80.7" y="91.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">T</text></svg>', '{"A": "2√42", "B": "√30", "C": "2√37", "D": "2√7", "E": "2√6"}'::jsonb, 'D', NULL, 'PB = PA + AB = 14. Toxunan-kəsən teoremi: PT² = PA·PB = 2·14 = 28 ⇒ PT = 2√7.');
INSERT INTO public.questions VALUES (8439, 109, 'g11-geo-circle-q3-19', 3, 19, 'hard', 'single', 'Bərabəryanlı trapesiyaya radiusu 4 olan çevrə daxil çəkilib. Kiçik oturacaq 4 olarsa, trapesiyanın yan tərəfini tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,173.0 286.0,173.0 191.5,47.0 128.5,47.0"/><text x="22.4" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="297.6" y="183.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="197.3" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="122.7" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">D</text><text x="160.0" y="190.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="160.0" y="40.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">4</text><circle cx="160.0" cy="110.0" r="63.0"/></svg>', '{"A": "11", "B": "8", "C": "16", "D": "6", "E": "10"}'::jsonb, 'E', NULL, 'h = 2r = 8. h² = ab ⇒ a = 64/4 = 16. c = (a + b)/2 = 10.');
INSERT INTO public.questions VALUES (8440, 109, 'g11-geo-circle-q3-20', 3, 20, 'hard', 'single', 'İki konsentrik çevrədən böyüyünün vətəri kiçiyinə toxunur. Vətərin uzunluğu 2√145 olarsa, çevrələr arasındakı halqanın sahəsini tapın.', NULL, NULL, '{"A": "145π", "B": "146π", "C": "290π", "D": "145π/2", "E": "580π"}'::jsonb, 'A', NULL, 'Vətərin yarısı ℓ/2, R² − r² = (ℓ/2)² = 145. Halqanın sahəsi π(R² − r²) = 145π.');
INSERT INTO public.questions VALUES (8441, 110, 'g11-geo-trig-q1-01', 1, 1, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 14, ∠A = 120°. A təpəsindən BC-yə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="110.7,176.4 286.0,176.4 34.0,43.6"/><text x="102.9" y="191.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.4" y="185.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.9" y="40.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="207.7" y="189.0" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="60.9" y="111.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><path d="M128.7,176.4 A18,18 0 0 0 101.7,160.8" stroke-width="1.2"/><text x="126.2" y="154.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="110.7" y1="176.4" x2="148.8" y2="104.1" stroke-dasharray="5 4"/></svg>', '{"A": "2√42", "B": "28√3/13", "C": "56√339/113", "D": "√9577/13", "E": "56√3/13"}'::jsonb, 'E', NULL, 'BC² = 676. S = ½·14·16·sin 120° = 224√3/4. h = 2S/BC = 224√3/(2√676) ⇒ h = 56√3/13.');
INSERT INTO public.questions VALUES (8442, 110, 'g11-geo-trig-q1-02', 1, 2, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 14, ∠A = 120°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="119.5,174.3 200.5,174.3 84.1,112.9"/><text x="111.7" y="189.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="212.9" y="183.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="73.9" y="109.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="169.3" y="186.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="90.3" y="145.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><path d="M137.5,174.3 A18,18 0 0 0 110.5,158.7" stroke-width="1.2"/><text x="135.0" y="152.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "26√3/3", "B": "52√3/3", "C": "√2037/3", "D": "13√2", "E": "26"}'::jsonb, 'A', NULL, 'BC² = 676 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 120° ⇒ R = √676/√3 = 26√3/3.');
INSERT INTO public.questions VALUES (8443, 110, 'g11-geo-trig-q1-03', 1, 3, 'hard', 'single', 'cos α = −3/5 və π/2 < α < π olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−12/25", "B": "−24/25", "C": "−7/25", "D": "24/25", "E": "−23/25"}'::jsonb, 'B', NULL, 'sin α = √(1 − 9/25) = 4/5 (rüb işarəsinə görə). sin 2α = −24/25.');
INSERT INTO public.questions VALUES (8444, 110, 'g11-geo-trig-q1-04', 1, 4, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 10, ∠A = 60°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="84.8,120.9 235.2,120.9 131.8,39.4"/><text x="72.8" y="130.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="247.6" y="129.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="127.5" y="32.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="163.9" y="137.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="96.9" y="81.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><path d="M102.8,120.9 A18,18 0 0 0 93.8,105.3" stroke-width="1.2"/><text x="111.6" y="110.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "√597/3", "B": "14√3/3", "C": "14", "D": "7√2", "E": "28√3/3"}'::jsonb, 'B', NULL, 'BC² = 196 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 60° ⇒ R = √196/√3 = 14√3/3.');
INSERT INTO public.questions VALUES (8445, 110, 'g11-geo-trig-q1-05', 1, 5, 'hard', 'single', 'sin α + cos α = 2/5 olarsa, sin⁴α + cos⁴α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "809/1250", "B": "46/25", "C": "2116/625", "D": "1691/1250", "E": "2059/2500"}'::jsonb, 'A', NULL, 'sin α cos α = −21/50; sin⁴α + cos⁴α = 1 − 2(sin α cos α)² = 809/1250.');
INSERT INTO public.questions VALUES (8446, 110, 'g11-geo-trig-q1-06', 1, 6, 'hard', 'single', 'f(x) = −6sin x + 8cos x − 2 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, '{"A": "−100", "B": "−95", "C": "104", "D": "−192", "E": "−96"}'::jsonb, 'E', NULL, 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−10; 10]. f-in max = 8, min = -12. Hasil: -96.');
INSERT INTO public.questions VALUES (8447, 110, 'g11-geo-trig-q1-07', 1, 7, 'hard', 'single', 'cos α = −7/25 və π/2 < α < π olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−527/625", "B": "−336/625", "C": "49/625", "D": "98/625", "E": "527/625"}'::jsonb, 'A', NULL, 'sin α = √(1 − 49/625) = 24/25 (rüb işarəsinə görə). cos 2α = −527/625.');
INSERT INTO public.questions VALUES (8448, 110, 'g11-geo-trig-q1-08', 1, 8, 'hard', 'single', 'f(x) = 16sin x + 30cos x + 6 funksiyası neçə tam qiymət alır?', NULL, NULL, '{"A": "69", "B": "67", "C": "93", "D": "70", "E": "68"}'::jsonb, 'A', NULL, '√(16² + 30²) = 34, deməli f-in qiymətlər çoxluğu [−28; 40]. Tam qiymətlər: 69.');
INSERT INTO public.questions VALUES (8449, 110, 'g11-geo-trig-q1-09', 1, 9, 'hard', 'single', '2cos²x − cos x − 3 = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "π", "B": "3π/2", "C": "2π", "D": "3π", "E": "π/2"}'::jsonb, 'A', NULL, 't = cos x: 2t² − 1t − 3 = 0 ⇒ t = 3/2 və ya t = −1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: π. Cəm: π.');
INSERT INTO public.questions VALUES (8450, 110, 'g11-geo-trig-q1-10', 1, 10, 'hard', 'single', '2cos²x + cos x − 3 = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "3π", "B": "4π", "C": "2π", "D": "5π/2", "E": "3π/2"}'::jsonb, 'C', NULL, 't = cos x: 2t² + 1t − 3 = 0 ⇒ t = 1 və ya t = −3/2 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 0, 2π. Cəm: 2π.');
INSERT INTO public.questions VALUES (8451, 110, 'g11-geo-trig-q1-11', 1, 11, 'hard', 'single', 'sin α + cos α = 9/7 olarsa, sin⁴α + cos⁴α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "2145/2401", "B": "2913/2401", "C": "289/2401", "D": "1889/2401", "E": "17/49"}'::jsonb, 'D', NULL, 'sin α cos α = 16/49; sin⁴α + cos⁴α = 1 − 2(sin α cos α)² = 1889/2401.');
INSERT INTO public.questions VALUES (8452, 110, 'g11-geo-trig-q1-12', 1, 12, 'hard', 'single', 'ABC üçbucağında AB = 14, AC = 16, ∠A = 120°. A təpəsindən BC-yə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="127.1,186.0 280.7,186.0 39.3,34.0"/><text x="121.9" y="202.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="292.8" y="195.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="29.8" y="30.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="212.7" y="199.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">14</text><text x="72.0" y="110.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><path d="M145.1,186.0 A18,18 0 0 0 118.1,170.4" stroke-width="1.2"/><text x="142.6" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="127.1" y1="186.0" x2="170.7" y2="116.7" stroke-dasharray="5 4"/></svg>', '{"A": "28√3/13", "B": "√9577/13", "C": "56√339/113", "D": "2√42", "E": "56√3/13"}'::jsonb, 'E', NULL, 'BC² = 676. S = ½·16·14·sin 120° = 224√3/4. h = 2S/BC = 224√3/(2√676) ⇒ h = 56√3/13.');
INSERT INTO public.questions VALUES (8453, 110, 'g11-geo-trig-q1-13', 1, 13, 'hard', 'single', 'cos α = −3/5 və π/2 < α < π olarsa, tg 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "12/7", "B": "24/7", "C": "−24/25", "D": "−24/7", "E": "−8/3"}'::jsonb, 'B', NULL, 'sin α = √(1 − 9/25) = 4/5 (rüb işarəsinə görə). tg 2α = 24/7.');
INSERT INTO public.questions VALUES (8454, 110, 'g11-geo-trig-q1-14', 1, 14, 'hard', 'open', 'cos α = 9/41 və 3π/2 < α < 2π olarsa, tg (α/2) ifadəsinin qiymətini tapın.', NULL, NULL, NULL, NULL, '−4/5', 'sin α = −√(1 − 81/1681) = −40/41 (rüb işarəsinə görə). tg (α/2) = −4/5.');
INSERT INTO public.questions VALUES (8455, 110, 'g11-geo-trig-q1-15', 1, 15, 'hard', 'single', '2sin²x − 3sin x − 2 = 0 tənliyinin [0; 2π] parçasında neçə kökü var?', NULL, NULL, '{"A": "2", "B": "1", "C": "4", "D": "5", "E": "3"}'::jsonb, 'A', NULL, 't = sin x: 2t² − 3t − 2 = 0 ⇒ t = 2 və ya t = −1/2 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 7π/6, 11π/6. Cəmi 2 kök.');
INSERT INTO public.questions VALUES (8456, 110, 'g11-geo-trig-q1-16', 1, 16, 'hard', 'single', 'sin α + cos α = −1/5 olarsa, (sin α − cos α)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−24/25", "B": "51/25", "C": "49/25", "D": "24/25", "E": "37/25"}'::jsonb, 'C', NULL, '(sin α − cos α)² + (sin α + cos α)² = 2 ⇒ (sin α − cos α)² = 2 − 1/25 = 49/25.');
INSERT INTO public.questions VALUES (8457, 110, 'g11-geo-trig-q1-17', 1, 17, 'hard', 'single', 'sin α = −12/37 və π < α < 3π/2 olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "1081/1369", "B": "840/1369", "C": "2450/1369", "D": "1225/1369", "E": "−1081/1369"}'::jsonb, 'A', NULL, 'cos α = −√(1 − 144/1369) = −35/37 (rüb işarəsinə görə). cos 2α = 1081/1369.');
INSERT INTO public.questions VALUES (8458, 110, 'g11-geo-trig-q1-18', 1, 18, 'hard', 'single', 'f(x) = 40sin x + 42cos x − 7 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, '{"A": "−3364", "B": "3413", "C": "−3314", "D": "−6675", "E": "−3315"}'::jsonb, 'E', NULL, 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−58; 58]. f-in max = 51, min = -65. Hasil: -3315.');
INSERT INTO public.questions VALUES (8459, 110, 'g11-geo-trig-q1-19', 1, 19, 'hard', 'single', '2cos²x + 3cos x = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "5π/2", "B": "3π/2", "C": "3π", "D": "4π", "E": "2π"}'::jsonb, 'E', NULL, 't = cos x: 2t² + 3t + 0 = 0 ⇒ t = −3/2 və ya t = 0 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: π/2, 3π/2. Cəm: 2π.');
INSERT INTO public.questions VALUES (8460, 110, 'g11-geo-trig-q1-20', 1, 20, 'hard', 'single', 'f(x) = −7sin x + 24cos x + 2 funksiyası neçə tam qiymət alır?', NULL, NULL, '{"A": "52", "B": "51", "C": "63", "D": "49", "E": "50"}'::jsonb, 'B', NULL, '√(7² + 24²) = 25, deməli f-in qiymətlər çoxluğu [−23; 27]. Tam qiymətlər: 51.');
INSERT INTO public.questions VALUES (8461, 110, 'g11-geo-trig-q2-01', 2, 1, 'hard', 'single', '2cos²x + 5cos x + 2 = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "2π", "B": "3π/2", "C": "4π", "D": "3π", "E": "5π/2"}'::jsonb, 'A', NULL, 't = cos x: 2t² + 5t + 2 = 0 ⇒ t = −1/2 və ya t = −2 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 2π/3, 4π/3. Cəm: 2π.');
INSERT INTO public.questions VALUES (8462, 110, 'g11-geo-trig-q2-02', 2, 2, 'hard', 'single', 'f(x) = 3sin x + 4cos x + 2 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, '{"A": "−21", "B": "29", "C": "−20", "D": "−25", "E": "−45"}'::jsonb, 'A', NULL, 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−5; 5]. f-in max = 7, min = -3. Hasil: -21.');
INSERT INTO public.questions VALUES (8463, 110, 'g11-geo-trig-q2-03', 2, 3, 'hard', 'single', 'ABC üçbucağında AB = 5, AC = 16, ∠A = 120°. A təpəsindən BC-yə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="176.5,186.0 231.3,186.0 88.7,34.0"/><text x="179.2" y="203.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="241.6" y="198.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="80.8" y="28.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="211.1" y="200.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><text x="123.1" y="107.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><path d="M194.5,186.0 A18,18 0 0 0 167.5,170.4" stroke-width="1.2"/><text x="192.0" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="176.5" y1="186.0" x2="205.6" y2="158.6" stroke-dasharray="5 4"/></svg>', '{"A": "40√843/281", "B": "√5161/19", "C": "20√3/19", "D": "40√3/19", "E": "2√15"}'::jsonb, 'D', NULL, 'BC² = 361. S = ½·16·5·sin 120° = 80√3/4. h = 2S/BC = 80√3/(2√361) ⇒ h = 40√3/19.');
INSERT INTO public.questions VALUES (8464, 110, 'g11-geo-trig-q2-04', 2, 4, 'hard', 'single', 'f(x) = 5sin x − 12cos x − 10 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, '{"A": "−189", "B": "−169", "C": "−69", "D": "−68", "E": "269"}'::jsonb, 'C', NULL, 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−13; 13]. f-in max = 3, min = -23. Hasil: -69.');
INSERT INTO public.questions VALUES (8465, 110, 'g11-geo-trig-q2-05', 2, 5, 'hard', 'single', 'ABC üçbucağında AB = 16, AC = 6, ∠A = 60°. A təpəsindən BC-yə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="34.0,153.4 286.0,153.4 81.3,71.6"/><text x="21.5" y="161.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.8" y="160.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="72.2" y="67.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.3" y="167.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><text x="45.8" y="115.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">6</text><path d="M52.0,153.4 A18,18 0 0 0 43.0,137.8" stroke-width="1.2"/><text x="60.8" y="142.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><line x1="34.0" y1="153.4" x2="68.7" y2="66.6" stroke-dasharray="5 4"/></svg>', '{"A": "24√219/73", "B": "12√3/7", "C": "√1777/7", "D": "24√3/7", "E": "6√2"}'::jsonb, 'D', NULL, 'BC² = 196. S = ½·6·16·sin 60° = 96√3/4. h = 2S/BC = 96√3/(2√196) ⇒ h = 24√3/7.');
INSERT INTO public.questions VALUES (8466, 110, 'g11-geo-trig-q2-06', 2, 6, 'hard', 'single', 'sin α + cos α = −4/3 olarsa, sin⁴α + cos⁴α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "4/81", "B": "113/162", "C": "211/162", "D": "275/324", "E": "2/9"}'::jsonb, 'B', NULL, 'sin α cos α = 7/18; sin⁴α + cos⁴α = 1 − 2(sin α cos α)² = 113/162.');
INSERT INTO public.questions VALUES (8467, 110, 'g11-geo-trig-q2-07', 2, 7, 'hard', 'open', 'f(x) = −3sin x + 4cos x − 3 funksiyası neçə tam qiymət alır?', NULL, NULL, NULL, NULL, '11', '√(3² + 4²) = 5, deməli f-in qiymətlər çoxluğu [−8; 2]. Tam qiymətlər: 11.');
INSERT INTO public.questions VALUES (8468, 110, 'g11-geo-trig-q2-08', 2, 8, 'hard', 'single', 'sin α = −8/17 və 3π/2 < α < 2π olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "161/289", "B": "225/289", "C": "−161/289", "D": "450/289", "E": "−240/289"}'::jsonb, 'A', NULL, 'cos α = √(1 − 64/289) = 15/17 (rüb işarəsinə görə). cos 2α = 161/289.');
INSERT INTO public.questions VALUES (8469, 110, 'g11-geo-trig-q2-09', 2, 9, 'hard', 'single', 'sin α + cos α = 1/4 olarsa, (sin α − cos α)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−15/16", "B": "47/32", "C": "31/16", "D": "33/16", "E": "15/16"}'::jsonb, 'C', NULL, '(sin α − cos α)² + (sin α + cos α)² = 2 ⇒ (sin α − cos α)² = 2 − 1/16 = 31/16.');
INSERT INTO public.questions VALUES (8470, 110, 'g11-geo-trig-q2-10', 2, 10, 'hard', 'single', 'sin α = −7/25 və 3π/2 < α < 2π olarsa, tg (α/2) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−7", "B": "0", "C": "−1/7", "D": "1/7", "E": "−2/7"}'::jsonb, 'C', NULL, 'cos α = √(1 − 49/625) = 24/25 (rüb işarəsinə görə). tg (α/2) = −1/7.');
INSERT INTO public.questions VALUES (8471, 110, 'g11-geo-trig-q2-11', 2, 11, 'hard', 'single', 'cos α = −5/13 və π/2 < α < π olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−60/169", "B": "120/169", "C": "−121/169", "D": "−120/169", "E": "−119/169"}'::jsonb, 'D', NULL, 'sin α = √(1 − 25/169) = 12/13 (rüb işarəsinə görə). sin 2α = −120/169.');
INSERT INTO public.questions VALUES (8472, 110, 'g11-geo-trig-q2-12', 2, 12, 'hard', 'single', 'ABC üçbucağında AB = 9, AC = 15, ∠A = 120°. A təpəsindən BC-yə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="151.2,186.0 256.5,186.0 63.5,34.0"/><text x="149.7" y="203.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="268.1" y="196.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="54.6" y="29.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="212.0" y="199.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">9</text><text x="96.7" y="109.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">15</text><path d="M169.2,186.0 A18,18 0 0 0 142.2,170.4" stroke-width="1.2"/><text x="166.7" y="164.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="151.2" y1="186.0" x2="191.5" y2="134.8" stroke-dasharray="5 4"/></svg>', '{"A": "45√3/28", "B": "9√5/2", "C": "45√3/14", "D": "√6271/14", "E": "45√102/68"}'::jsonb, 'C', NULL, 'BC² = 441. S = ½·15·9·sin 120° = 135√3/4. h = 2S/BC = 135√3/(2√441) ⇒ h = 45√3/14.');
INSERT INTO public.questions VALUES (8473, 110, 'g11-geo-trig-q2-13', 2, 13, 'hard', 'single', '2cos²x + 2cos x = 0 tənliyinin [0; 2π] parçasında neçə kökü var?', NULL, NULL, '{"A": "4", "B": "3", "C": "6", "D": "5", "E": "2"}'::jsonb, 'B', NULL, 't = cos x: 2t² + 2t + 0 = 0 ⇒ t = 0 və ya t = −1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: π/2, π, 3π/2. Cəmi 3 kök.');
INSERT INTO public.questions VALUES (8474, 110, 'g11-geo-trig-q2-14', 2, 14, 'hard', 'single', 'cos α = −12/37 və π/2 < α < π olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−420/1369", "B": "−839/1369", "C": "840/1369", "D": "−1081/1369", "E": "−840/1369"}'::jsonb, 'E', NULL, 'sin α = √(1 − 144/1369) = 35/37 (rüb işarəsinə görə). sin 2α = −840/1369.');
INSERT INTO public.questions VALUES (8475, 110, 'g11-geo-trig-q2-15', 2, 15, 'hard', 'single', '2cos²x − 2 = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "3π", "B": "4π", "C": "7π/2", "D": "6π", "E": "5π/2"}'::jsonb, 'A', NULL, 't = cos x: 2t² − 0t − 2 = 0 ⇒ t = 1 və ya t = −1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 0, π, 2π. Cəm: 3π.');
INSERT INTO public.questions VALUES (8476, 110, 'g11-geo-trig-q2-16', 2, 16, 'hard', 'single', 'f(x) = 20sin x + 21cos x − 4 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, '{"A": "−1665", "B": "857", "C": "−824", "D": "−825", "E": "−841"}'::jsonb, 'D', NULL, 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−29; 29]. f-in max = 25, min = -33. Hasil: -825.');
INSERT INTO public.questions VALUES (8477, 110, 'g11-geo-trig-q2-17', 2, 17, 'hard', 'single', 'sin α + cos α = −1/2 olarsa, (sin α − cos α)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "3/4", "B": "9/4", "C": "−3/4", "D": "7/4", "E": "11/8"}'::jsonb, 'D', NULL, '(sin α − cos α)² + (sin α + cos α)² = 2 ⇒ (sin α − cos α)² = 2 − 1/4 = 7/4.');
INSERT INTO public.questions VALUES (8478, 110, 'g11-geo-trig-q2-18', 2, 18, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 12, ∠A = 120°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="113.0,169.7 207.0,169.7 84.8,120.9"/><text x="102.5" y="182.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="219.7" y="177.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="73.9" y="118.8" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="170.1" y="181.3" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="87.2" y="147.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><path d="M131.0,169.7 A18,18 0 0 0 104.0,154.1" stroke-width="1.2"/><text x="128.5" y="147.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "56√3/3", "B": "28", "C": "28√3/3", "D": "√2361/3", "E": "14√2"}'::jsonb, 'C', NULL, 'BC² = 784 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 120° ⇒ R = √784/√3 = 28√3/3.');
INSERT INTO public.questions VALUES (8479, 110, 'g11-geo-trig-q2-19', 2, 19, 'hard', 'single', '2sin²x − 2sin x = 0 tənliyinin [0; 2π] parçasında neçə kökü var?', NULL, NULL, '{"A": "6", "B": "4", "C": "3", "D": "8", "E": "5"}'::jsonb, 'B', NULL, 't = sin x: 2t² − 2t + 0 = 0 ⇒ t = 0 və ya t = 1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 0, π/2, π, 2π. Cəmi 4 kök.');
INSERT INTO public.questions VALUES (8480, 110, 'g11-geo-trig-q2-20', 2, 20, 'hard', 'single', 'sin α + cos α = −2/7 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−188/343", "B": "−8/343", "C": "929/686", "D": "−143/343", "E": "−53/343"}'::jsonb, 'D', NULL, 'sin α cos α = −45/98; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = −2/7·143/98 = −143/343.');
INSERT INTO public.questions VALUES (8481, 110, 'g11-geo-trig-q3-01', 3, 1, 'hard', 'single', 'f(x) = 3sin x − 4cos x − 10 funksiyası neçə tam qiymət alır?', NULL, NULL, '{"A": "10", "B": "12", "C": "9", "D": "15", "E": "11"}'::jsonb, 'E', NULL, '√(3² + 4²) = 5, deməli f-in qiymətlər çoxluğu [−15; -5]. Tam qiymətlər: 11.');
INSERT INTO public.questions VALUES (8482, 110, 'g11-geo-trig-q3-02', 3, 2, 'hard', 'single', 'sin α + cos α = −5/7 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−125/343", "B": "−305/343", "C": "−185/343", "D": "−365/343", "E": "127/343"}'::jsonb, 'B', NULL, 'sin α cos α = −12/49; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = −5/7·61/49 = −305/343.');
INSERT INTO public.questions VALUES (8483, 110, 'g11-geo-trig-q3-03', 3, 3, 'hard', 'single', 'cos α = −7/25 və π/2 < α < π olarsa, tg (α/2) ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "4/3", "B": "5/3", "C": "3/4", "D": "−4/3", "E": "1"}'::jsonb, 'A', NULL, 'sin α = √(1 − 49/625) = 24/25 (rüb işarəsinə görə). tg (α/2) = 4/3.');
INSERT INTO public.questions VALUES (8484, 110, 'g11-geo-trig-q3-04', 3, 4, 'hard', 'single', 'ABC üçbucağında AB = 3, AC = 5, ∠A = 120°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="131.8,180.6 188.2,180.6 84.8,99.1"/><text x="130.3" y="198.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="199.8" y="191.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="76.0" y="94.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="168.1" y="194.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">3</text><text x="97.6" y="139.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">5</text><path d="M149.8,180.6 A18,18 0 0 0 122.8,165.0" stroke-width="1.2"/><text x="147.3" y="158.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "7√3/3", "B": "2√39/3", "C": "7", "D": "7√2/2", "E": "14√3/3"}'::jsonb, 'A', NULL, 'BC² = 49 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 120° ⇒ R = √49/√3 = 7√3/3.');
INSERT INTO public.questions VALUES (8485, 110, 'g11-geo-trig-q3-05', 3, 5, 'hard', 'single', 'sin α + cos α = −2/5 olarsa, sin³α + cos³α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−8/125", "B": "299/250", "C": "−92/125", "D": "−71/125", "E": "−29/125"}'::jsonb, 'D', NULL, 'sin α cos α = −21/50; sin³α + cos³α = (sin α + cos α)(1 − sin α cos α) = −2/5·71/50 = −71/125.');
INSERT INTO public.questions VALUES (8486, 110, 'g11-geo-trig-q3-06', 3, 6, 'hard', 'single', 'cos α = −8/17 və π/2 < α < π olarsa, cos 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "161/289", "B": "128/289", "C": "64/289", "D": "−240/289", "E": "−161/289"}'::jsonb, 'E', NULL, 'sin α = √(1 − 64/289) = 15/17 (rüb işarəsinə görə). cos 2α = −161/289.');
INSERT INTO public.questions VALUES (8487, 110, 'g11-geo-trig-q3-07', 3, 7, 'hard', 'single', 'sin α + cos α = −1/7 olarsa, sin⁴α + cos⁴α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "97/49", "B": "1249/2401", "C": "3553/2401", "D": "1825/2401", "E": "9409/2401"}'::jsonb, 'B', NULL, 'sin α cos α = −24/49; sin⁴α + cos⁴α = 1 − 2(sin α cos α)² = 1249/2401.');
INSERT INTO public.questions VALUES (8488, 110, 'g11-geo-trig-q3-08', 3, 8, 'hard', 'single', 'ABC üçbucağında AB = 20, AC = 12, ∠A = 120°. A təpəsindən BC-yə endirilmiş hündürlüyü tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="92.2,160.4 286.0,160.4 34.0,59.6"/><text x="81.7" y="173.1" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="298.7" y="168.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="23.1" y="57.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="199.1" y="171.9" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">20</text><text x="51.4" y="112.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">12</text><path d="M110.2,160.4 A18,18 0 0 0 83.2,144.8" stroke-width="1.2"/><text x="107.7" y="138.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">120°</text><line x1="92.2" y1="160.4" x2="118.9" y2="93.6" stroke-dasharray="5 4"/></svg>', '{"A": "15√102/17", "B": "30√3/7", "C": "15√3/7", "D": "√2749/7", "E": "6√5"}'::jsonb, 'B', NULL, 'BC² = 784. S = ½·12·20·sin 120° = 240√3/4. h = 2S/BC = 240√3/(2√784) ⇒ h = 30√3/7.');
INSERT INTO public.questions VALUES (8489, 110, 'g11-geo-trig-q3-09', 3, 9, 'hard', 'single', 'cos α = 3/5 və 3π/2 < α < 2π olarsa, tg 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "−8/3", "B": "12/7", "C": "−24/25", "D": "24/7", "E": "−24/7"}'::jsonb, 'D', NULL, 'sin α = −√(1 − 9/25) = −4/5 (rüb işarəsinə görə). tg 2α = 24/7.');
INSERT INTO public.questions VALUES (8490, 110, 'g11-geo-trig-q3-10', 3, 10, 'hard', 'single', 'ABC üçbucağında AB = 10, AC = 16, ∠A = 60°. Üçbucağa xaricdən çəkilmiş çevrənin radiusunu tapın.', NULL, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" width="320" height="220" fill="none" stroke="currentColor" stroke-width="1.6" font-family="sans-serif" font-size="14"><polygon points="113.0,169.7 207.0,169.7 188.2,39.4"/><text x="102.7" y="182.6" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">A</text><text x="215.5" y="184.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">B</text><text x="191.0" y="31.7" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">C</text><text x="157.5" y="186.4" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">10</text><text x="142.7" y="100.5" text-anchor="middle" fill="currentColor" stroke="none" font-size="14">16</text><path d="M131.0,169.7 A18,18 0 0 0 122.0,154.1" stroke-width="1.2"/><text x="139.8" y="159.2" text-anchor="middle" fill="currentColor" stroke="none" font-size="12">60°</text><circle cx="160.0" cy="110.0" r="76.0"/></svg>', '{"A": "√597/3", "B": "14", "C": "28√3/3", "D": "7√2", "E": "14√3/3"}'::jsonb, 'E', NULL, 'BC² = 196 (kosinuslar teoremi). Sinuslar teoremi: 2R = BC/sin 60° ⇒ R = √196/√3 = 14√3/3.');
INSERT INTO public.questions VALUES (8491, 110, 'g11-geo-trig-q3-11', 3, 11, 'hard', 'single', '2sin²x − 4sin x = 0 tənliyinin [0; 2π] parçasında neçə kökü var?', NULL, NULL, '{"A": "6", "B": "3", "C": "2", "D": "4", "E": "5"}'::jsonb, 'B', NULL, 't = sin x: 2t² − 4t + 0 = 0 ⇒ t = 2 və ya t = 0 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 0, π, 2π. Cəmi 3 kök.');
INSERT INTO public.questions VALUES (8492, 110, 'g11-geo-trig-q3-12', 3, 12, 'hard', 'single', 'sin α = −8/17 və 3π/2 < α < 2π olarsa, sin 2α ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "161/289", "B": "−120/289", "C": "−240/289", "D": "−239/289", "E": "240/289"}'::jsonb, 'C', NULL, 'cos α = √(1 − 64/289) = 15/17 (rüb işarəsinə görə). sin 2α = −240/289.');
INSERT INTO public.questions VALUES (8493, 110, 'g11-geo-trig-q3-13', 3, 13, 'hard', 'single', '2sin²x − 3sin x + 1 = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "2π", "B": "3π", "C": "π", "D": "5π/2", "E": "3π/2"}'::jsonb, 'E', NULL, 't = sin x: 2t² − 3t + 1 = 0 ⇒ t = 1/2 və ya t = 1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: π/6, π/2, 5π/6. Cəm: 3π/2.');
INSERT INTO public.questions VALUES (8494, 110, 'g11-geo-trig-q3-14', 3, 14, 'hard', 'open', 'f(x) = 6sin x + 8cos x + 9 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, NULL, NULL, '−19', 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−10; 10]. f-in max = 19, min = -1. Hasil: -19.');
INSERT INTO public.questions VALUES (8495, 110, 'g11-geo-trig-q3-15', 3, 15, 'hard', 'single', '2sin²x − 2 = 0 tənliyinin [0; 2π] parçasında neçə kökü var?', NULL, NULL, '{"A": "5", "B": "4", "C": "3", "D": "2", "E": "1"}'::jsonb, 'D', NULL, 't = sin x: 2t² − 0t − 2 = 0 ⇒ t = −1 və ya t = 1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: π/2, 3π/2. Cəmi 2 kök.');
INSERT INTO public.questions VALUES (8496, 110, 'g11-geo-trig-q3-16', 3, 16, 'hard', 'single', 'sin α + cos α = −2/3 olarsa, (sin α − cos α)² ifadəsinin qiymətini tapın.', NULL, NULL, '{"A": "5/9", "B": "14/9", "C": "23/18", "D": "−5/9", "E": "22/9"}'::jsonb, 'B', NULL, '(sin α − cos α)² + (sin α + cos α)² = 2 ⇒ (sin α − cos α)² = 2 − 4/9 = 14/9.');
INSERT INTO public.questions VALUES (8497, 110, 'g11-geo-trig-q3-17', 3, 17, 'hard', 'single', '2cos²x + 3cos x + 1 = 0 tənliyinin [0; 2π] parçasındakı köklərinin cəmini tapın.', NULL, NULL, '{"A": "5π/2", "B": "4π", "C": "7π/2", "D": "6π", "E": "3π"}'::jsonb, 'E', NULL, 't = cos x: 2t² + 3t + 1 = 0 ⇒ t = −1/2 və ya t = −1 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: 2π/3, π, 4π/3. Cəm: 3π.');
INSERT INTO public.questions VALUES (8498, 110, 'g11-geo-trig-q3-18', 3, 18, 'hard', 'single', 'f(x) = 7sin x − 24cos x − 10 funksiyası neçə tam qiymət alır?', NULL, NULL, '{"A": "63", "B": "49", "C": "51", "D": "52", "E": "50"}'::jsonb, 'C', NULL, '√(7² + 24²) = 25, deməli f-in qiymətlər çoxluğu [−35; 15]. Tam qiymətlər: 51.');
INSERT INTO public.questions VALUES (8499, 110, 'g11-geo-trig-q3-19', 3, 19, 'hard', 'single', '2cos²x + 3cos x = 0 tənliyinin [0; 2π] parçasında neçə kökü var?', NULL, NULL, '{"A": "2", "B": "4", "C": "1", "D": "5", "E": "3"}'::jsonb, 'A', NULL, 't = cos x: 2t² + 3t + 0 = 0 ⇒ t = −3/2 və ya t = 0 (|t| ≤ 1 olanlar qalır). [0; 2π] parçasında həllər: π/2, 3π/2. Cəmi 2 kök.');
INSERT INTO public.questions VALUES (8500, 110, 'g11-geo-trig-q3-20', 3, 20, 'hard', 'single', 'f(x) = 20sin x − 21cos x − 10 funksiyasının ən böyük və ən kiçik qiymətlərinin hasilini tapın.', NULL, NULL, '{"A": "−741", "B": "941", "C": "−1581", "D": "−740", "E": "−841"}'::jsonb, 'A', NULL, 'a sin x + b cos x ifadəsinin qiymətləri [−√(a² + b²); √(a² + b²)] = [−29; 29]. f-in max = 19, min = -39. Hasil: -741.');
INSERT INTO public.questions VALUES (8501, 111, 'g11-stat-prob-q1-01', 1, 1, 'hard', 'single', 'X təsadüfi kəmiyyətinin paylanması: P(X = −4) = 3/10; P(X = 2) = 1/5; P(X = 4) = 3/10; P(X = a) = 1/5. M(X) = 2 olarsa, a-nı tapın.', NULL, NULL, '{"A": "9", "B": "10", "C": "7", "D": "8", "E": "2"}'::jsonb, 'D', NULL, '2/5 + 1/5·a = 2 ⇒ a = 8.');
INSERT INTO public.questions VALUES (8502, 111, 'g11-stat-prob-q1-02', 1, 2, 'hard', 'single', 'Qutuda 5 qırmızı və 6 ağ şar var. Eyni anda 4 şar götürülür. X — götürülən qırmızı şarların sayıdır. X² təsadüfi kəmiyyətinin riyazi gözləməsini tapın.', NULL, NULL, '{"A": "400/121", "B": "84/121", "C": "4", "D": "20/11", "E": "5"}'::jsonb, 'C', NULL, 'M(X) = 20/11, D(X) = 84/121, M(X²) = D(X) + M(X)² = 4.');
INSERT INTO public.questions VALUES (8503, 111, 'g11-stat-prob-q1-03', 1, 3, 'hard', 'single', 'İki zər atılıb və xalların cəminin 8 olduğu məlumdur. Hər iki zərdə eyni xalın düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/36", "B": "5/36", "C": "1/5", "D": "4/5", "E": "2/5"}'::jsonb, 'C', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). Cəmi 8: 5 hal, onlardan cüt (a = b): 1. P = 1/5.');
INSERT INTO public.questions VALUES (8504, 111, 'g11-stat-prob-q1-04', 1, 4, 'hard', 'single', 'X təsadüfi kəmiyyətinin paylanması: P(X = −4) = 1/6; P(X = 2) = 1/3; P(X = 5) = 1/3; P(X = a) = 1/6. M(X) = 3 olarsa, a-nı tapın.', NULL, NULL, '{"A": "3", "B": "9", "C": "10", "D": "8", "E": "7"}'::jsonb, 'D', NULL, '5/3 + 1/6·a = 3 ⇒ a = 8.');
INSERT INTO public.questions VALUES (8505, 111, 'g11-stat-prob-q1-05', 1, 5, 'hard', 'single', 'İki səkkizüzlü (1–8) zər atılır. Düşən xalların fərqinin modulunun riyazi gözləməsini tapın.', NULL, NULL, '{"A": "21/8", "B": "4", "C": "9/2", "D": "25/8", "E": "17/8"}'::jsonb, 'A', NULL, 'P(|a − b| = k) = 2(8 − k)/64 (k ≥ 1). M = Σ k·2(8 − k)/64 = 21/8.');
INSERT INTO public.questions VALUES (8506, 111, 'g11-stat-prob-q1-06', 1, 6, 'hard', 'single', '1, 2, 3, 5, 6, 7 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 6-ya bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "17/120", "B": "13/15", "C": "1/6", "D": "2/15", "E": "2/27"}'::jsonb, 'D', NULL, 'Bütün ədədlər: 120 (birinci rəqəm 0 ola bilməz). 6-ya bölünənlər: 16. P = 2/15.');
INSERT INTO public.questions VALUES (8507, 111, 'g11-stat-prob-q1-07', 1, 7, 'hard', 'open', 'İki səkkizüzlü (1–8) zər atılır. Düşən xallardan ən böyüyünün riyazi gözləməsini tapın.', NULL, NULL, NULL, NULL, '93/16', 'P(max = k) = (2k − 1)/64. M = Σ k(2k − 1)/64 = 93/16.');
INSERT INTO public.questions VALUES (8508, 111, 'g11-stat-prob-q1-08', 1, 8, 'hard', 'single', 'Oyunda iştirak 4 manatdır. İki zər atılır: xalların cəmi 10 və ya daha çox olarsa oyunçu 18 manat alır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "3", "B": "1", "C": "−1", "D": "0", "E": "−2"}'::jsonb, 'C', NULL, 'P(cəm ≥ 10) = 6/36. M = 6/36·18 − 4 = −1.');
INSERT INTO public.questions VALUES (8509, 111, 'g11-stat-prob-q1-09', 1, 9, 'hard', 'single', 'Qutuda 5 qırmızı və 8 ağ şar var. Eyni anda 2 şar götürülür. X — götürülən qırmızı şarların sayıdır. X-in riyazi gözləməsini tapın.', NULL, NULL, '{"A": "16/13", "B": "10/13", "C": "11/13", "D": "5/6", "E": "5/13"}'::jsonb, 'B', NULL, 'Hər şarın seçilmə ehtimalı 2/13, M(X) = 5·2/13 = 10/13.');
INSERT INTO public.questions VALUES (8510, 111, 'g11-stat-prob-q1-10', 1, 10, 'hard', 'single', 'Üzərində A, A, B, C, D hərfləri yazılmış 5 kart təsadüfi qaydada bir cərgədə düzülür. Heç bir eyni hərfin yan-yana düşməməsi ehtimalını tapın.', NULL, NULL, '{"A": "4/5", "B": "2/5", "C": "3/5", "D": "6/5", "E": "3/10"}'::jsonb, 'C', NULL, 'Bərabər ehtimallı fərqli düzülüşlər: 5!/(təkrarların faktorialları) = 60. Əlverişli: 36. P = 3/5.');
INSERT INTO public.questions VALUES (8511, 111, 'g11-stat-prob-q1-11', 1, 11, 'hard', 'single', 'Üzərində A, A, A, B, C hərfləri yazılmış 5 kart təsadüfi qaydada bir cərgədə düzülür. Heç bir eyni hərfin yan-yana düşməməsi ehtimalını tapın.', NULL, NULL, '{"A": "0", "B": "1/10", "C": "9/10", "D": "1/5", "E": "3/10"}'::jsonb, 'B', NULL, 'Bərabər ehtimallı fərqli düzülüşlər: 5!/(təkrarların faktorialları) = 20. Əlverişli: 2. P = 1/10.');
INSERT INTO public.questions VALUES (8512, 111, 'g11-stat-prob-q1-12', 1, 12, 'hard', 'single', 'X diskret təsadüfi kəmiyyəti yalnız −4, −1, 0, 3 qiymətlərini alır: P(X = −4) = 1/6; P(X = −1) = 1/3; P(X = 0) = 1/3; X = 3 qiymətini alma ehtimalı məlum deyil. D(X)-i tapın.', NULL, NULL, '{"A": "15/4", "B": "17/2", "C": "17/4", "D": "9/2", "E": "1/4"}'::jsonb, 'C', NULL, 'P(X = 3) = 1 − 5/6 = 1/6. M(X) = −1/2, M(X²) = 9/2. D(X) = 17/4.');
INSERT INTO public.questions VALUES (8513, 111, 'g11-stat-prob-q1-13', 1, 13, 'hard', 'single', 'İki zər atılıb və xalların fərqinin modulunun ən azı 3 olduğu məlumdur. Xalların cəminin 8-dən böyük olmaması ehtimalını tapın.', NULL, NULL, '{"A": "11/12", "B": "5/6", "C": "5/18", "D": "1/3", "E": "1/6"}'::jsonb, 'B', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). |a − b| ≥ 3: 12 hal, onlardan cəmi ≤ 8: 10. P = 5/6.');
INSERT INTO public.questions VALUES (8514, 111, 'g11-stat-prob-q1-14', 1, 14, 'hard', 'single', 'Testdə 8 sual var, hər sualın 5 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 2 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "196608/390625", "B": "194017/390625", "C": "1/25", "D": "325089/390625", "E": "114688/390625"}'::jsonb, 'B', NULL, 'p = 1/5, q = 4/5. P(X ≥ 2) = 1 − Σ C(8, j)·p^j·q^(8 − j), j = 0…1 = 194017/390625.');
INSERT INTO public.questions VALUES (8515, 111, 'g11-stat-prob-q1-15', 1, 15, 'hard', 'single', 'Oyunda iştirak 2 manatdır. İki zər atılır: xalların cəmi 8 və ya daha çox olarsa oyunçu 7 manat alır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "−1/12", "B": "−11/12", "C": "35/12", "D": "11/12", "E": "23/12"}'::jsonb, 'D', NULL, 'P(cəm ≥ 8) = 15/36. M = 15/36·7 − 2 = 11/12.');
INSERT INTO public.questions VALUES (8516, 111, 'g11-stat-prob-q1-16', 1, 16, 'hard', 'single', 'Birinci qutuda 6 qırmızı və 8 ağ, ikinci qutuda 4 qırmızı və 2 ağ şar var. Zər atılır: 4-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şar qırmızı çıxıb. Onun birinci qutudan götürülməsi ehtimalını tapın.', NULL, NULL, '{"A": "7/16", "B": "9/16", "C": "3/5", "D": "2/3", "E": "2/7"}'::jsonb, 'B', NULL, 'P(qırmızı) = 2/3·3/7 + 1/3·2/3 = 32/63. Bayes: P(I | qırmızı) = (2/7) : (32/63) = 9/16.');
INSERT INTO public.questions VALUES (8517, 111, 'g11-stat-prob-q1-17', 1, 17, 'hard', 'single', '2, 3, 4, 6, 7, 8 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 3-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "49/120", "B": "3/5", "C": "2/5", "D": "1/3", "E": "2/9"}'::jsonb, 'C', NULL, 'Bütün ədədlər: 120 (birinci rəqəm 0 ola bilməz). 3-ə bölünənlər: 48. P = 2/5.');
INSERT INTO public.questions VALUES (8518, 111, 'g11-stat-prob-q1-18', 1, 18, 'hard', 'single', 'Oyunda iştirak 2 manatdır. İki zər atılır: eyni xal düşərsə oyunçu 9 manat, əks halda cəm 10 və ya daha çox olarsa 4 manat alır, qalan hallarda heç nə almır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "−19/18", "B": "17/18", "C": "1/18", "D": "35/18", "E": "−1/18"}'::jsonb, 'E', NULL, 'P(cüt) = 6/36, P(cüt deyil, cəm ≥ 10) = 4/36. M = 6/36·9 + 4/36·4 − 2 = −1/18.');
INSERT INTO public.questions VALUES (8519, 111, 'g11-stat-prob-q1-19', 1, 19, 'hard', 'single', 'Basketbolçu topu səbətə 2/3 ehtimalla salır. O, 5 atış edir (atışlar asılı deyil). Onun düz 3 dəfə topu səbətə salması ehtimalını tapın.', NULL, NULL, '{"A": "160/243", "B": "8/243", "C": "80/27", "D": "80/243", "E": "3/5"}'::jsonb, 'D', NULL, 'p = 2/3, q = 1/3. Bernulli düsturu: C(5, 3)·p^3·q^2 = 80/243.');
INSERT INTO public.questions VALUES (8520, 111, 'g11-stat-prob-q1-20', 1, 20, 'hard', 'single', 'Birinci qutuda 3 qırmızı və 7 ağ, ikinci qutuda 4 qırmızı və 3 ağ şar var. Zər atılır: 4-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "64/105", "B": "7/17", "C": "61/140", "D": "1/5", "E": "41/105"}'::jsonb, 'E', NULL, 'Tam ehtimal düsturu: 2/3·3/10 + 1/3·4/7 = 41/105.');
INSERT INTO public.questions VALUES (8521, 111, 'g11-stat-prob-q2-01', 2, 1, 'hard', 'single', 'X təsadüfi kəmiyyətinin paylanması: P(X = −5) = 1/3; P(X = 3) = 1/3; P(X = 8) = 1/6; P(X = a) = 1/6. M(X) = 5/2 olarsa, a-nı tapın.', NULL, NULL, '{"A": "10", "B": "5/2", "C": "12", "D": "11", "E": "13"}'::jsonb, 'D', NULL, '2/3 + 1/6·a = 5/2 ⇒ a = 11.');
INSERT INTO public.questions VALUES (8522, 111, 'g11-stat-prob-q2-02', 2, 2, 'hard', 'single', 'Üzərində A, A, B, C, D hərfləri yazılmış 5 kart təsadüfi qaydada bir cərgədə düzülür. Bütün A hərflərinin yan-yana düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "3/5", "B": "2/5", "C": "1/3", "D": "4/5", "E": "1/5"}'::jsonb, 'B', NULL, 'Bərabər ehtimallı fərqli düzülüşlər: 5!/(təkrarların faktorialları) = 60. Əlverişli: 24. P = 2/5.');
INSERT INTO public.questions VALUES (8523, 111, 'g11-stat-prob-q2-03', 2, 3, 'hard', 'single', 'Qutuda 5 qırmızı və 5 ağ şar var. Eyni anda 4 şar götürülür. X — götürülən qırmızı şarların sayıdır. X-in riyazi gözləməsini tapın.', NULL, NULL, '{"A": "20/9", "B": "21/10", "C": "3", "D": "1/2", "E": "2"}'::jsonb, 'E', NULL, 'Hər şarın seçilmə ehtimalı 4/10, M(X) = 5·4/10 = 2.');
INSERT INTO public.questions VALUES (8524, 111, 'g11-stat-prob-q2-04', 2, 4, 'hard', 'single', 'Qutuda 6 qırmızı və 4 ağ şar var. Eyni anda 3 şar götürülür. X — götürülən qırmızı şarların sayıdır. X² təsadüfi kəmiyyətinin riyazi gözləməsini tapın.', NULL, NULL, '{"A": "24/5", "B": "81/25", "C": "14/25", "D": "19/5", "E": "9/5"}'::jsonb, 'D', NULL, 'M(X) = 9/5, D(X) = 14/25, M(X²) = D(X) + M(X)² = 19/5.');
INSERT INTO public.questions VALUES (8525, 111, 'g11-stat-prob-q2-05', 2, 5, 'hard', 'single', 'Birinci qutuda 4 qırmızı və 7 ağ, ikinci qutuda 2 qırmızı və 6 ağ şar var. Zər atılır: 4-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şar qırmızı çıxıb. Onun birinci qutudan götürülməsi ehtimalını tapın.', NULL, NULL, '{"A": "11/43", "B": "32/43", "C": "8/33", "D": "43/132", "E": "2/3"}'::jsonb, 'B', NULL, 'P(qırmızı) = 2/3·4/11 + 1/3·1/4 = 43/132. Bayes: P(I | qırmızı) = (8/33) : (43/132) = 32/43.');
INSERT INTO public.questions VALUES (8526, 111, 'g11-stat-prob-q2-06', 2, 6, 'hard', 'single', 'İki adi (1–6) zər atılır. Düşən xalların fərqinin modulunun riyazi gözləməsini tapın.', NULL, NULL, '{"A": "35/18", "B": "7/2", "C": "3", "D": "22/9", "E": "13/9"}'::jsonb, 'A', NULL, 'P(|a − b| = k) = 2(6 − k)/36 (k ≥ 1). M = Σ k·2(6 − k)/36 = 35/18.');
INSERT INTO public.questions VALUES (8527, 111, 'g11-stat-prob-q2-07', 2, 7, 'hard', 'open', 'Birinci qutuda 6 qırmızı və 6 ağ, ikinci qutuda 7 qırmızı və 1 ağ şar var. Zər atılır: 5-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, NULL, NULL, '9/16', 'Tam ehtimal düsturu: 5/6·1/2 + 1/6·7/8 = 9/16.');
INSERT INTO public.questions VALUES (8528, 111, 'g11-stat-prob-q2-08', 2, 8, 'hard', 'single', 'Üzərində A, A, B, B, B, C hərfləri yazılmış 6 kart təsadüfi qaydada bir cərgədə düzülür. Cərgənin hər iki kənarında A hərfinin olması ehtimalını tapın.', NULL, NULL, '{"A": "1/6", "B": "14/15", "C": "2/15", "D": "1/15", "E": "7/30"}'::jsonb, 'D', NULL, 'Bərabər ehtimallı fərqli düzülüşlər: 6!/(təkrarların faktorialları) = 60. Əlverişli: 4. P = 1/15.');
INSERT INTO public.questions VALUES (8529, 111, 'g11-stat-prob-q2-09', 2, 9, 'hard', 'single', 'Oyunda iştirak 1 manatdır. İki zər atılır: eyni xal düşərsə oyunçu 6 manat, əks halda cəm 10 və ya daha çox olarsa 6 manat alır, qalan hallarda heç nə almır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "7/6", "B": "5/3", "C": "−1/3", "D": "−2/3", "E": "2/3"}'::jsonb, 'E', NULL, 'P(cüt) = 6/36, P(cüt deyil, cəm ≥ 10) = 4/36. M = 6/36·6 + 4/36·6 − 1 = 2/3.');
INSERT INTO public.questions VALUES (8530, 111, 'g11-stat-prob-q2-10', 2, 10, 'hard', 'single', 'Birinci qutuda 3 qırmızı və 1 ağ, ikinci qutuda 8 qırmızı və 3 ağ şar var. Zər atılır: 4-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şar qırmızı çıxıb. Onun birinci qutudan götürülməsi ehtimalını tapın.', NULL, NULL, '{"A": "3/11", "B": "1/2", "C": "2/3", "D": "16/49", "E": "33/49"}'::jsonb, 'E', NULL, 'P(qırmızı) = 2/3·3/4 + 1/3·8/11 = 49/66. Bayes: P(I | qırmızı) = (1/2) : (49/66) = 33/49.');
INSERT INTO public.questions VALUES (8531, 111, 'g11-stat-prob-q2-11', 2, 11, 'hard', 'single', 'Qutuda 4 qırmızı və 8 ağ şar var. Eyni anda 4 şar götürülür. X — götürülən qırmızı şarların sayıdır. X-in riyazi gözləməsini tapın.', NULL, NULL, '{"A": "17/12", "B": "1/3", "C": "4/3", "D": "16/11", "E": "8/3"}'::jsonb, 'C', NULL, 'Hər şarın seçilmə ehtimalı 4/12, M(X) = 4·4/12 = 4/3.');
INSERT INTO public.questions VALUES (8532, 111, 'g11-stat-prob-q2-12', 2, 12, 'hard', 'single', 'X diskret təsadüfi kəmiyyəti yalnız −5, 1, 6, 9 qiymətlərini alır: P(X = −5) = 1/6; P(X = 1) = 1/6; P(X = 6) = 1/2; X = 9 qiymətini alma ehtimalı məlum deyil. D(X)-i tapın.', NULL, NULL, '{"A": "529/36", "B": "899/36", "C": "215/6", "D": "761/36", "E": "761/18"}'::jsonb, 'D', NULL, 'P(X = 9) = 1 − 5/6 = 1/6. M(X) = 23/6, M(X²) = 215/6. D(X) = 761/36.');
INSERT INTO public.questions VALUES (8533, 111, 'g11-stat-prob-q2-13', 2, 13, 'hard', 'single', 'İki zər atılıb və xalların cəminin 6 olduğu məlumdur. Hər iki zərdə eyni xalın düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "2/5", "B": "5/36", "C": "4/5", "D": "1/36", "E": "1/5"}'::jsonb, 'E', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). Cəmi 6: 5 hal, onlardan cüt (a = b): 1. P = 1/5.');
INSERT INTO public.questions VALUES (8534, 111, 'g11-stat-prob-q2-14', 2, 14, 'hard', 'open', 'İki zər atılıb və xalların fərqinin modulunun ən azı 1 olduğu məlumdur. Xalların cəminin 9-dan böyük olmaması ehtimalını tapın.', NULL, NULL, NULL, NULL, '13/15', 'Şərti ehtimal: P(A|B) = P(AB)/P(B). |a − b| ≥ 1: 30 hal, onlardan cəmi ≤ 9: 26. P = 13/15.');
INSERT INTO public.questions VALUES (8535, 111, 'g11-stat-prob-q2-15', 2, 15, 'hard', 'single', 'Testdə 4 sual var, hər sualın 3 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun düz 2 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "1/2", "B": "16/27", "C": "8/27", "D": "2/3", "E": "4/81"}'::jsonb, 'C', NULL, 'p = 1/3, q = 2/3. Bernulli düsturu: C(4, 2)·p^2·q^2 = 8/27.');
INSERT INTO public.questions VALUES (8536, 111, 'g11-stat-prob-q2-16', 2, 16, 'hard', 'single', 'Testdə 7 sual var, hər sualın 3 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 2 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "64/243", "B": "1/9", "C": "2059/2187", "D": "179/243", "E": "224/729"}'::jsonb, 'D', NULL, 'p = 1/3, q = 2/3. P(X ≥ 2) = 1 − Σ C(7, j)·p^j·q^(7 − j), j = 0…1 = 179/243.');
INSERT INTO public.questions VALUES (8537, 111, 'g11-stat-prob-q2-17', 2, 17, 'hard', 'single', 'İki tetraedr şəkilli (1–4) zər atılır. Düşən xallardan ən böyüyünün riyazi gözləməsini tapın.', NULL, NULL, '{"A": "21/8", "B": "29/8", "C": "25/8", "D": "2", "E": "5/2"}'::jsonb, 'C', NULL, 'P(max = k) = (2k − 1)/16. M = Σ k(2k − 1)/16 = 25/8.');
INSERT INTO public.questions VALUES (8538, 111, 'g11-stat-prob-q2-18', 2, 18, 'hard', 'single', '1, 3, 4, 6, 8 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 4-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "19/60", "B": "18/125", "C": "7/10", "D": "3/10", "E": "1/4"}'::jsonb, 'D', NULL, 'Bütün ədədlər: 60 (birinci rəqəm 0 ola bilməz). 4-ə bölünənlər: 18. P = 3/10.');
INSERT INTO public.questions VALUES (8539, 111, 'g11-stat-prob-q2-19', 2, 19, 'hard', 'single', 'Oyunda iştirak 5 manatdır. İki zər atılır: eyni xal düşərsə oyunçu 11 manat, əks halda cəm 10 və ya daha çox olarsa 5 manat alır, qalan hallarda heç nə almır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "−47/18", "B": "−29/18", "C": "47/18", "D": "43/18", "E": "−65/18"}'::jsonb, 'A', NULL, 'P(cüt) = 6/36, P(cüt deyil, cəm ≥ 10) = 4/36. M = 6/36·11 + 4/36·5 − 5 = −47/18.');
INSERT INTO public.questions VALUES (8540, 111, 'g11-stat-prob-q2-20', 2, 20, 'hard', 'single', '0, 3, 4, 5, 7 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 9-a bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "4/125", "B": "1/12", "C": "1/9", "D": "5/48", "E": "11/12"}'::jsonb, 'B', NULL, 'Bütün ədədlər: 48 (birinci rəqəm 0 ola bilməz). 9-a bölünənlər: 4. P = 1/12.');
INSERT INTO public.questions VALUES (8541, 111, 'g11-stat-prob-q3-01', 3, 1, 'hard', 'single', 'Testdə 7 sual var, hər sualın 3 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun düz 1 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "7/3", "B": "64/2187", "C": "896/2187", "D": "448/2187", "E": "1/7"}'::jsonb, 'D', NULL, 'p = 1/3, q = 2/3. Bernulli düsturu: C(7, 1)·p^1·q^6 = 448/2187.');
INSERT INTO public.questions VALUES (8542, 111, 'g11-stat-prob-q3-02', 3, 2, 'hard', 'single', 'Testdə 6 sual var, hər sualın 3 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun düz 2 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "5/3", "B": "1/3", "C": "16/729", "D": "80/243", "E": "160/243"}'::jsonb, 'D', NULL, 'p = 1/3, q = 2/3. Bernulli düsturu: C(6, 2)·p^2·q^4 = 80/243.');
INSERT INTO public.questions VALUES (8543, 111, 'g11-stat-prob-q3-03', 3, 3, 'hard', 'single', 'Üzərində A, A, B, B, C, C hərfləri yazılmış 6 kart təsadüfi qaydada bir cərgədə düzülür. Bütün A hərflərinin yan-yana düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "0", "B": "1/2", "C": "1/6", "D": "1/3", "E": "2/3"}'::jsonb, 'D', NULL, 'Bərabər ehtimallı fərqli düzülüşlər: 6!/(təkrarların faktorialları) = 90. Əlverişli: 30. P = 1/3.');
INSERT INTO public.questions VALUES (8544, 111, 'g11-stat-prob-q3-04', 3, 4, 'hard', 'single', 'İki zər atılıb və xalların cəminin 7-dən kiçik olmadığı məlumdur. Zərlərdən ən azı birində 6 düşməsi ehtimalını tapın.', NULL, NULL, '{"A": "11/21", "B": "11/36", "C": "7/12", "D": "10/21", "E": "4/7"}'::jsonb, 'A', NULL, 'Şərti ehtimal: P(A|B) = P(AB)/P(B). Cəmi ≥ 7 olan hallar: 21, onlardan 6 olanlar: 11. P = 11/21.');
INSERT INTO public.questions VALUES (8545, 111, 'g11-stat-prob-q3-05', 3, 5, 'hard', 'single', 'İki tetraedr şəkilli (1–4) zər atılır. Düşən xalların fərqinin modulunun riyazi gözləməsini tapın.', NULL, NULL, '{"A": "5/4", "B": "3/4", "C": "2", "D": "7/4", "E": "5/2"}'::jsonb, 'A', NULL, 'P(|a − b| = k) = 2(4 − k)/16 (k ≥ 1). M = Σ k·2(4 − k)/16 = 5/4.');
INSERT INTO public.questions VALUES (8546, 111, 'g11-stat-prob-q3-06', 3, 6, 'hard', 'single', '3, 4, 5, 6, 8, 9 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 4-ə bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/4", "B": "29/120", "C": "23/30", "D": "7/30", "E": "7/54"}'::jsonb, 'D', NULL, 'Bütün ədədlər: 120 (birinci rəqəm 0 ola bilməz). 4-ə bölünənlər: 28. P = 7/30.');
INSERT INTO public.questions VALUES (8547, 111, 'g11-stat-prob-q3-07', 3, 7, 'hard', 'open', '1, 2, 4, 5, 8, 9 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 5-ə bölünməsi ehtimalını tapın.', NULL, NULL, NULL, NULL, '1/6', 'Bütün ədədlər: 120 (birinci rəqəm 0 ola bilməz). 5-ə bölünənlər: 20. P = 1/6.');
INSERT INTO public.questions VALUES (8548, 111, 'g11-stat-prob-q3-08', 3, 8, 'hard', 'single', 'Birinci qutuda 5 qırmızı və 4 ağ, ikinci qutuda 3 qırmızı və 7 ağ şar var. Zər atılır: 3-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şar qırmızı çıxıb. Onun birinci qutudan götürülməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/2", "B": "5/18", "C": "27/77", "D": "50/77", "E": "5/8"}'::jsonb, 'D', NULL, 'P(qırmızı) = 1/2·5/9 + 1/2·3/10 = 77/180. Bayes: P(I | qırmızı) = (5/18) : (77/180) = 50/77.');
INSERT INTO public.questions VALUES (8549, 111, 'g11-stat-prob-q3-09', 3, 9, 'hard', 'single', 'X diskret təsadüfi kəmiyyəti yalnız −1, 7, 9, 10 qiymətlərini alır: P(X = −1) = 1/8; P(X = 7) = 3/8; P(X = 9) = 1/4; X = 10 qiymətini alma ehtimalı məlum deyil. D(X)-i tapın.', NULL, NULL, '{"A": "295/16", "B": "179/8", "C": "841/16", "D": "255/4", "E": "179/16"}'::jsonb, 'E', NULL, 'P(X = 10) = 1 − 3/4 = 1/4. M(X) = 29/4, M(X²) = 255/4. D(X) = 179/16.');
INSERT INTO public.questions VALUES (8550, 111, 'g11-stat-prob-q3-10', 3, 10, 'hard', 'single', 'X diskret təsadüfi kəmiyyəti yalnız −4, 0, 8, 10 qiymətlərini alır: P(X = −4) = 1/5; P(X = 0) = 1/2; P(X = 8) = 1/5; X = 10 qiymətini alma ehtimalı məlum deyil. D(X)-i tapın.', NULL, NULL, '{"A": "81/25", "B": "569/25", "C": "1138/25", "D": "26", "E": "614/25"}'::jsonb, 'B', NULL, 'P(X = 10) = 1 − 9/10 = 1/10. M(X) = 9/5, M(X²) = 26. D(X) = 569/25.');
INSERT INTO public.questions VALUES (8551, 111, 'g11-stat-prob-q3-11', 3, 11, 'hard', 'single', 'Üzərində A, A, B, B, C, D hərfləri yazılmış 6 kart təsadüfi qaydada bir cərgədə düzülür. Heç bir eyni hərfin yan-yana düşməməsi ehtimalını tapın.', NULL, NULL, '{"A": "19/30", "B": "7/15", "C": "1/6", "D": "14/15", "E": "8/15"}'::jsonb, 'B', NULL, 'Bərabər ehtimallı fərqli düzülüşlər: 6!/(təkrarların faktorialları) = 180. Əlverişli: 84. P = 7/15.');
INSERT INTO public.questions VALUES (8552, 111, 'g11-stat-prob-q3-12', 3, 12, 'hard', 'single', 'Qutuda 3 qırmızı və 7 ağ şar var. Eyni anda 4 şar götürülür. X — götürülən qırmızı şarların sayıdır. X² təsadüfi kəmiyyətinin riyazi gözləməsini tapın.', NULL, NULL, '{"A": "14/25", "B": "2", "C": "36/25", "D": "6/5", "E": "3"}'::jsonb, 'B', NULL, 'M(X) = 6/5, D(X) = 14/25, M(X²) = D(X) + M(X)² = 2.');
INSERT INTO public.questions VALUES (8553, 111, 'g11-stat-prob-q3-13', 3, 13, 'hard', 'single', 'Oyunda iştirak 3 manatdır. İki zər atılır: xalların cəmi 7 və ya daha çox olarsa oyunçu 5 manat alır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "1/12", "B": "−1/12", "C": "35/12", "D": "11/12", "E": "−13/12"}'::jsonb, 'B', NULL, 'P(cəm ≥ 7) = 21/36. M = 21/36·5 − 3 = −1/12.');
INSERT INTO public.questions VALUES (8554, 111, 'g11-stat-prob-q3-14', 3, 14, 'hard', 'open', 'Birinci qutuda 4 qırmızı və 8 ağ, ikinci qutuda 2 qırmızı və 8 ağ şar var. Zər atılır: 3-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şar qırmızı çıxıb. Onun birinci qutudan götürülməsi ehtimalını tapın.', NULL, NULL, NULL, NULL, '5/8', 'P(qırmızı) = 1/2·1/3 + 1/2·1/5 = 4/15. Bayes: P(I | qırmızı) = (1/6) : (4/15) = 5/8.');
INSERT INTO public.questions VALUES (8555, 111, 'g11-stat-prob-q3-15', 3, 15, 'hard', 'single', 'Testdə 7 sual var, hər sualın 4 variantından biri düzgündür. Şagird bütün sualların cavabını təsadüfi seçir. Onun ən azı 3 sualı düzgün cavablandırması ehtimalını tapın.', NULL, NULL, '{"A": "2835/16384", "B": "1/64", "C": "14197/16384", "D": "12393/16384", "E": "3991/16384"}'::jsonb, 'E', NULL, 'p = 1/4, q = 3/4. P(X ≥ 3) = 1 − Σ C(7, j)·p^j·q^(7 − j), j = 0…2 = 3991/16384.');
INSERT INTO public.questions VALUES (8556, 111, 'g11-stat-prob-q3-16', 3, 16, 'hard', 'single', 'Qutuda 5 qırmızı və 2 ağ şar var. Eyni anda 4 şar götürülür. X — götürülən qırmızı şarların sayıdır. X-in dispersiyasını tapın.', NULL, NULL, '{"A": "20/49", "B": "40/49", "C": "20/7", "D": "120/343", "E": "60/7"}'::jsonb, 'A', NULL, 'Paylanma: P(X = j) = C(5, j)·C(2, 4 − j)/C(7, 4). M(X) = 20/7, M(X²) = 60/7, D(X) = M(X²) − M(X)² = 20/49.');
INSERT INTO public.questions VALUES (8557, 111, 'g11-stat-prob-q3-17', 3, 17, 'hard', 'single', 'Qutuda 5 qırmızı və 7 ağ şar var. Eyni anda 3 şar götürülür. X — götürülən qırmızı şarların sayıdır. X-in dispersiyasını tapın.', NULL, NULL, '{"A": "105/176", "B": "5/4", "C": "35/64", "D": "95/44", "E": "35/48"}'::jsonb, 'A', NULL, 'Paylanma: P(X = j) = C(5, j)·C(7, 3 − j)/C(12, 3). M(X) = 5/4, M(X²) = 95/44, D(X) = M(X²) − M(X)² = 105/176.');
INSERT INTO public.questions VALUES (8558, 111, 'g11-stat-prob-q3-18', 3, 18, 'hard', 'single', '0, 2, 3, 4, 5 rəqəmlərindən rəqəmləri təkrarlanmayan üçrəqəmli ədəd təsadüfi düzəldilir. Ədədin 6-ya bölünməsi ehtimalını tapın.', NULL, NULL, '{"A": "1/6", "B": "7/24", "C": "35/48", "D": "13/48", "E": "13/125"}'::jsonb, 'D', NULL, 'Bütün ədədlər: 48 (birinci rəqəm 0 ola bilməz). 6-ya bölünənlər: 13. P = 13/48.');
INSERT INTO public.questions VALUES (8559, 111, 'g11-stat-prob-q3-19', 3, 19, 'hard', 'single', 'Birinci qutuda 4 qırmızı və 7 ağ, ikinci qutuda 7 qırmızı və 5 ağ şar var. Zər atılır: 2-dən böyük olmayan xal düşərsə birinci qutudan, əks halda ikinci qutudan bir şar götürülür. Götürülən şarın qırmızı olması ehtimalını tapın.', NULL, NULL, '{"A": "97/198", "B": "11/23", "C": "125/264", "D": "101/198", "E": "4/33"}'::jsonb, 'D', NULL, 'Tam ehtimal düsturu: 1/3·4/11 + 2/3·7/12 = 101/198.');
INSERT INTO public.questions VALUES (8560, 111, 'g11-stat-prob-q3-20', 3, 20, 'hard', 'single', 'Oyunda iştirak 1 manatdır. İki zər atılır: eyni xal düşərsə oyunçu 17 manat, əks halda cəm 10 və ya daha çox olarsa 7 manat alır, qalan hallarda heç nə almır. Oyunçunun xalis qazancının riyazi gözləməsini tapın (manatla).', NULL, NULL, '{"A": "28/9", "B": "47/18", "C": "29/18", "D": "−47/18", "E": "65/18"}'::jsonb, 'B', NULL, 'P(cüt) = 6/36, P(cüt deyil, cəm ≥ 10) = 4/36. M = 6/36·17 + 4/36·7 − 1 = 47/18.');
INSERT INTO public.questions VALUES (8561, 112, 'g11-aze-sound-q1-01', 1, 1, 'hard', 'single', 'Hansı sözdə 1 sonor samit var, kar samit yoxdur, 1 dodaqlanan sait var, qapalı (dar) sait yoxdur və 1 açıq heca var?', NULL, NULL, '{"A": "dolma", "B": "şorba", "C": "arzu", "D": "orta", "E": "gözəl"}'::jsonb, 'E', NULL, '«gözəl»: hecalar — gö-zəl; saitlər — 2 (0 qalın, 2 incə, 1 dodaqlanan); samitlər — 3 (3 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8562, 112, 'g11-aze-sound-q1-02', 1, 2, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 sonor samit var, kar və cingiltili samitlərin sayı bərabərdir və bütün saitlər qalındır?', NULL, NULL, '{"A": "orta, qorxu, sarı", "B": "bostan, qara, yuxu", "C": "masa, qonşu, xala", "D": "sol, toy, çoban", "E": "tar, çay, şam"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8563, 112, 'g11-aze-sound-q1-03', 1, 3, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "tə-yya-rə", "B": "yu-mu-rta", "C": "kom-an-da", "D": "sən-ət-kar", "E": "şaf-ta-lı"}'::jsonb, 'E', NULL, 'Düzgün bölgü: şaf-ta-lı. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8564, 112, 'g11-aze-sound-q1-04', 1, 4, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 kar samit var, 1 dodaqlanan sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "yun, çoban, şorba", "B": "komanda, toy, şam", "C": "pozan, sol, yuxarı", "D": "tor, yol, yoldaş", "E": "cəsur, orta, qaranquş"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8565, 112, 'g11-aze-sound-q1-05', 1, 5, 'hard', 'single', '«qırmızı» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 5 samit (4 cingiltili, 1 kar), 2 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 2 sonor"}'::jsonb, 'D', NULL, '«qırmızı» — hecalar: qır-mı-zı. 3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8566, 112, 'g11-aze-sound-q1-06', 1, 6, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "süt – tarla", "B": "cəsur – dərin", "C": "fəhlə – lampa", "D": "ana – divar", "E": "arı – pendir"}'::jsonb, 'B', NULL, '«cəsur»: cə-sur; «dərin»: də-rin. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8567, 112, 'g11-aze-sound-q1-07', 1, 7, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "keçi – səma", "B": "kartof – sürücü", "C": "kətə – masa", "D": "bacı – gecə", "E": "alça – bacı"}'::jsonb, 'B', NULL, '«kartof»: kar-tof; «sürücü»: sü-rü-cü. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8568, 112, 'g11-aze-sound-q1-08', 1, 8, 'hard', 'single', 'Hansı sözdə 1 qapalı heca var, 5 səs var, kar samitlər cingiltili samitlərdən çoxdur və həm qalın, həm də incə sait var?', NULL, NULL, '{"A": "körpü", "B": "həkim", "C": "divar", "D": "həyat", "E": "gilas"}'::jsonb, 'D', NULL, '«həyat»: hecalar — hə-yat; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8569, 112, 'g11-aze-sound-q1-09', 1, 9, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "sərin – uzun", "B": "dar – təbaşir", "C": "hakim – lalə", "D": "sənətkar – turş", "E": "ada – ilan"}'::jsonb, 'E', NULL, '«ada»: a-da; «ilan»: i-lan. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8570, 112, 'g11-aze-sound-q1-10', 1, 10, 'hard', 'single', 'Hansı sözdə qapalı (dar) sait yoxdur, 5 səs var, son heca açıqdır və 2 kar samit var?', NULL, NULL, '{"A": "tülkü", "B": "fəhlə", "C": "pərdə", "D": "həftə", "E": "hekayə"}'::jsonb, 'B', NULL, '«fəhlə»: hecalar — fəh-lə; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8571, 112, 'g11-aze-sound-q1-11', 1, 11, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "gözəl – kino", "B": "kədər – sərgi", "C": "gül – xəyal", "D": "göyərçin – kaman", "E": "gündüz – həyat"}'::jsonb, 'E', NULL, '«gündüz»: gün-düz; «həyat»: hə-yat. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8572, 112, 'g11-aze-sound-q1-12', 1, 12, 'hard', 'single', '«yaşıl» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 1 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'A', NULL, '«yaşıl» — hecalar: ya-şıl. 2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8573, 112, 'g11-aze-sound-q1-13', 1, 13, 'hard', 'single', 'Hansı sözdə həm qalın, həm də incə sait var, 2 heca var, 1 qapalı (dar) sait var və 2 cingiltili samit var?', NULL, NULL, '{"A": "gilas", "B": "qonşu", "C": "yarış", "D": "geri", "E": "sahil"}'::jsonb, 'A', NULL, '«gilas»: hecalar — gi-las; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8574, 112, 'g11-aze-sound-q1-14', 1, 14, 'hard', 'single', 'Hansı sözdə 3 açıq heca var, həm qalın, həm də incə sait var, 1 qapalı (dar) sait var və 2 sonor samit var?', NULL, NULL, '{"A": "pomidor", "B": "alim", "C": "muzey", "D": "saniyə", "E": "dünya"}'::jsonb, 'D', NULL, '«saniyə»: hecalar — sa-ni-yə; saitlər — 3 (1 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8575, 112, 'g11-aze-sound-q1-15', 1, 15, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "şaft-a-lı", "B": "meh-rib-an", "C": "ə-kin-çi", "D": "qı-rmı-zı", "E": "sən-ət-kar"}'::jsonb, 'C', NULL, 'Düzgün bölgü: ə-kin-çi. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8576, 112, 'g11-aze-sound-q1-16', 1, 16, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 kar samit var, kar və cingiltili samitlərin sayı bərabərdir və bütün saitlər qalındır?', NULL, NULL, '{"A": "alça, sarı, şam", "B": "orta, qartal, xala", "C": "kino, masa, qısa", "D": "sol, tar, yazıçı", "E": "qapı, çay, çöl"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8577, 112, 'g11-aze-sound-q1-17', 1, 17, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "ə-kinç-i", "B": "ka-rand-aş", "C": "göy-ər-çin", "D": "po-mi-dor", "E": "hə-diyy-ə"}'::jsonb, 'D', NULL, 'Düzgün bölgü: po-mi-dor. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8578, 112, 'g11-aze-sound-q1-18', 1, 18, 'hard', 'single', '«səmimi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "4 heca (4 açıq, 0 qapalı); 4 sait (0 qalın, 4 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "4 heca (4 açıq, 0 qapalı); 4 sait (1 qalın, 3 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "E": "3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor"}'::jsonb, 'B', NULL, '«səmimi» — hecalar: sə-mi-mi. 3 heca (3 açıq, 0 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8579, 112, 'g11-aze-sound-q1-19', 1, 19, 'hard', 'single', 'Hansı sözdə 1 açıq heca var, 1 kar samit var, həm qalın, həm də incə sait var, 2 heca var və söz samitlə başlayır?', NULL, NULL, '{"A": "səbir", "B": "dünya", "C": "maşın", "D": "sahil", "E": "xəyal"}'::jsonb, 'E', NULL, '«xəyal»: hecalar — xə-yal; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8580, 112, 'g11-aze-sound-q1-20', 1, 20, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə bütün saitlər qalındır, 1 kar samit var və dodaqlanan sait yoxdur?', NULL, NULL, '{"A": "dastan, nahar, xala", "B": "qapı, qapıçı, qatar", "C": "acı, kaman, lampa", "D": "maşın, sarı, yazıçı", "E": "daş, qısa, şorba"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8581, 112, 'g11-aze-sound-q1-21', 1, 21, 'hard', 'single', 'Hansı sözdə söz samitlə başlayır, kar və cingiltili samitlərin sayı bərabərdir, dodaqlanan sait yoxdur, son heca qapalıdır və 2 cingiltili samit var?', NULL, NULL, '{"A": "çəmən", "B": "qatar", "C": "rəssam", "D": "yemiş", "E": "xiyar"}'::jsonb, 'C', NULL, '«rəssam»: hecalar — rəs-sam; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 4 (2 cingiltili, 2 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8582, 112, 'g11-aze-sound-q1-22', 1, 22, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "dost – toy", "B": "qorxu – sərin", "C": "ildırım – savadlı", "D": "qatar – qızıl", "E": "nərgiz – yaşıl"}'::jsonb, 'B', NULL, '«qorxu»: qor-xu; «sərin»: sə-rin. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8583, 112, 'g11-aze-sound-q1-23', 1, 23, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz samitlə başlayır, 1 qapalı (dar) sait var və bütün saitlər qalındır?', NULL, NULL, '{"A": "kaman, çarpayı, şaftalı", "B": "duz, qapı, qartal", "C": "qoyun, yarış, çay", "D": "mavi, qorxu, sarı", "E": "qaranquş, qum, yaşıl"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8584, 112, 'g11-aze-sound-q1-24', 1, 24, 'hard', 'single', '«hekayə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 0 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "4 heca (4 açıq, 0 qapalı); 4 sait (2 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "D": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "E": "3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'E', NULL, '«hekayə» — hecalar: he-ka-yə. 3 heca (3 açıq, 0 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8585, 112, 'g11-aze-sound-q1-25', 1, 25, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "dolu – tarla", "B": "tor – yasəmən", "C": "muzey – ulduz", "D": "alma – geri", "E": "turş – çöl"}'::jsonb, 'A', NULL, '«dolu»: do-lu; «tarla»: tar-la. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8586, 112, 'g11-aze-sound-q1-26', 1, 26, 'hard', 'single', '«qızılgül» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 1 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 3 sonor", "B": "4 heca (2 açıq, 2 qapalı); 4 sait (3 qalın, 1 incə), 1 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 2 sonor", "C": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 2 sonor", "D": "4 heca (2 açıq, 2 qapalı); 4 sait (2 qalın, 2 incə), 1 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 2 sonor", "E": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 1 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 2 sonor"}'::jsonb, 'E', NULL, '«qızılgül» — hecalar: qı-zıl-gül. 3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 1 dodaqlanan; 5 samit (5 cingiltili, 0 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8587, 112, 'g11-aze-sound-q1-27', 1, 27, 'hard', 'single', '«aslan» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (2 cingiltili, 2 kar), 2 sonor", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'E', NULL, '«aslan» — hecalar: as-lan. 2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8588, 112, 'g11-aze-sound-q1-28', 1, 28, 'hard', 'single', '«savadlı» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 1 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 1 sonor", "C": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 1 sonor", "D": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 1 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 1 sonor"}'::jsonb, 'A', NULL, '«savadlı» — hecalar: sa-vad-lı. 3 heca (2 açıq, 1 qapalı); 3 sait (3 qalın, 0 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8589, 112, 'g11-aze-sound-q1-29', 1, 29, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 açıq heca var, söz samitlə başlayır və bütün saitlər incədir?', NULL, NULL, '{"A": "dələ, gil, mənzərə", "B": "kino, meşə, təpə", "C": "cəsarət, gəmi, kətə", "D": "gecə, küçə, səma", "E": "dəmirçi, keçi, pəncərə"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8590, 112, 'g11-aze-sound-q1-30', 1, 30, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "parça – qonşu", "B": "acı – rəf", "C": "aslan – gözəl", "D": "nahar – sinif", "E": "fəhlə – günəş"}'::jsonb, 'C', NULL, '«aslan»: as-lan; «gözəl»: gö-zəl. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8591, 112, 'g11-aze-sound-q2-01', 2, 1, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 cingiltili samit var, 1 sonor samit var və bütün saitlər incədir?', NULL, NULL, '{"A": "rəf, sərçə, əkinçi", "B": "dəftər, həkim, kirpi", "C": "gül, şəkər, əsr", "D": "meşə, nəfəs, tor", "E": "dələ, tülkü, çöl"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8592, 112, 'g11-aze-sound-q2-02', 2, 2, 'hard', 'single', 'Hansı sözdə bütün saitlər incədir, 2 heca var, 2 kar samit var, 1 cingiltili samit var və açıq (geniş) sait yoxdur?', NULL, NULL, '{"A": "fəhlə", "B": "körpü", "C": "sinif", "D": "nəfəs", "E": "süfrə"}'::jsonb, 'C', NULL, '«sinif»: hecalar — si-nif; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8593, 112, 'g11-aze-sound-q2-03', 2, 3, 'hard', 'single', '«kirpi» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 4 samit (1 cingiltili, 3 kar), 1 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 0 sonor"}'::jsonb, 'C', NULL, '«kirpi» — hecalar: kir-pi. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8594, 112, 'g11-aze-sound-q2-04', 2, 4, 'hard', 'single', '«yarış» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "2 heca (2 açıq, 0 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'A', NULL, '«yarış» — hecalar: ya-rış. 2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8595, 112, 'g11-aze-sound-q2-05', 2, 5, 'hard', 'single', '«sərin» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'A', NULL, '«sərin» — hecalar: sə-rin. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8596, 112, 'g11-aze-sound-q2-06', 2, 6, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "pozan – zürafə", "B": "vətən – çoban", "C": "dərin – saz", "D": "qələbə – saz", "E": "arzu – geri"}'::jsonb, 'E', NULL, '«arzu»: ar-zu; «geri»: ge-ri. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8597, 112, 'g11-aze-sound-q2-07', 2, 7, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 heca var, söz samitlə başlayır və bütün saitlər incədir?', NULL, NULL, '{"A": "həftə, kətə, rəssam", "B": "baba, geri, şirin", "C": "bülbül, gündüz, liman", "D": "fikir, gümüş, gəlin", "E": "dayı, pərdə, şəkər"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8598, 112, 'g11-aze-sound-q2-08', 2, 8, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "səbir – çanta", "B": "sol – çay", "C": "mavi – xiyar", "D": "ada – dələ", "E": "kirpi – sarı"}'::jsonb, 'B', NULL, '«sol»: sol; «çay»: çay. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8599, 112, 'g11-aze-sound-q2-09', 2, 9, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "hə-diy-yə", "B": "şaf-tal-ı", "C": "cə-sar-ət", "D": "pə-ncə-rə", "E": "yu-mu-rta"}'::jsonb, 'A', NULL, 'Düzgün bölgü: hə-diy-yə. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8600, 112, 'g11-aze-sound-q2-10', 2, 10, 'hard', 'single', 'Hansı sözdə 1 açıq heca var, 3 sonor samit var, 3 heca var, 1 kar samit var və 1 qapalı (dar) sait var?', NULL, NULL, '{"A": "yumurta", "B": "qonşu", "C": "şagirdlər", "D": "hədiyyə", "E": "qaranquş"}'::jsonb, 'C', NULL, '«şagirdlər»: hecalar — şa-gird-lər; saitlər — 3 (1 qalın, 2 incə, 0 dodaqlanan); samitlər — 6 (5 cingiltili, 1 kar, 3 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8601, 112, 'g11-aze-sound-q2-11', 2, 11, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 heca var, 1 açıq heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "geri, həkim, səhər", "B": "geniş, parça, tülkü", "C": "güzgü, kədər, çoban", "D": "fikir, körpü, yemiş", "E": "dərin, sinif, çanta"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8602, 112, 'g11-aze-sound-q2-12', 2, 12, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 1 açıq heca var?', NULL, NULL, '{"A": "sav-ad-lı", "B": "ki-tabl-ar", "C": "il-dı-rım", "D": "mən-zər-ə", "E": "ko-mand-a"}'::jsonb, 'C', NULL, 'Düzgün bölgü: il-dı-rım. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8603, 112, 'g11-aze-sound-q2-13', 2, 13, 'hard', 'single', '«bayram» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "D": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 4 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor"}'::jsonb, 'C', NULL, '«bayram» — hecalar: bay-ram. 2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor.');
INSERT INTO public.questions VALUES (8604, 112, 'g11-aze-sound-q2-14', 2, 14, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "nişan – yoldaş", "B": "həkim – kaman", "C": "boz – sinif", "D": "dəftər – səbir", "E": "duz – saniyə"}'::jsonb, 'A', NULL, '«nişan»: ni-şan; «yoldaş»: yol-daş. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8605, 112, 'g11-aze-sound-q2-15', 2, 15, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "yu-murt-a", "B": "o-yun-çu", "C": "po-mid-or", "D": "sə-yah-ət", "E": "sa-vadl-ı"}'::jsonb, 'B', NULL, 'Düzgün bölgü: o-yun-çu. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8606, 112, 'g11-aze-sound-q2-16', 2, 16, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "medal – sarı", "B": "günəş – kino", "C": "qızılgül – tələbə", "D": "bülbül – xiyar", "E": "qatar – səhra"}'::jsonb, 'A', NULL, '«medal»: me-dal; «sarı»: sa-rı. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8607, 112, 'g11-aze-sound-q2-17', 2, 17, 'hard', 'single', 'Hansı sözdə 2 heca var, dodaqlanan sait yoxdur, bütün saitlər qalındır, son heca açıqdır və 2 açıq (geniş) sait var?', NULL, NULL, '{"A": "ayı", "B": "heyva", "C": "savadlı", "D": "xalça", "E": "səma"}'::jsonb, 'D', NULL, '«xalça»: hecalar — xal-ça; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8608, 112, 'g11-aze-sound-q2-18', 2, 18, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "səma – uzun", "B": "dost – gəmi", "C": "arzu – isti", "D": "bostan – qardaş", "E": "baba – keçi"}'::jsonb, 'B', NULL, '«dost»: dost; «gəmi»: gə-mi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8609, 112, 'g11-aze-sound-q2-19', 2, 19, 'hard', 'single', '«kitablar» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 2 sonor", "B": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 2 sonor", "C": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 1 sonor", "D": "4 heca (2 açıq, 2 qapalı); 4 sait (2 qalın, 2 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 2 sonor", "E": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 3 sonor"}'::jsonb, 'A', NULL, '«kitablar» — hecalar: ki-tab-lar. 3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8610, 112, 'g11-aze-sound-q2-20', 2, 20, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə son heca açıqdır, cingiltili samitlər kar samitlərdən çoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "dolu, qələbə, yuxarı", "B": "acı, bacı, yumurta", "C": "baba, durna, yol", "D": "alma, ana, sərgi", "E": "ata, qonşu, qorxu"}'::jsonb, 'B', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8611, 112, 'g11-aze-sound-q2-21', 2, 21, 'hard', 'single', '«bayram» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 4 sonor", "C": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "D": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 1 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor"}'::jsonb, 'E', NULL, '«bayram» — hecalar: bay-ram. 2 heca (0 açıq, 2 qapalı); 2 sait (2 qalın, 0 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor.');
INSERT INTO public.questions VALUES (8612, 112, 'g11-aze-sound-q2-22', 2, 22, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "həkim – yemiş", "B": "qorxu – xiyar", "C": "yuxarı – zaman", "D": "alim – yaşıl", "E": "nahar – qardaş"}'::jsonb, 'B', NULL, '«qorxu»: qor-xu; «xiyar»: xi-yar. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8613, 112, 'g11-aze-sound-q2-23', 2, 23, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 kar samit var, 2 heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "sinif, səhər, tufan", "B": "körpü, meşə, şəkər", "C": "həkim, kətə, şüşə", "D": "dülgər, nəfəs, sərçə", "E": "fəhlə, küçə, sərgi"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8614, 112, 'g11-aze-sound-q2-24', 2, 24, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "sevgi – çinar", "B": "gəlin – qələm", "C": "dolu – səyahət", "D": "meymun – xəritə", "E": "küçə – qatar"}'::jsonb, 'E', NULL, '«küçə»: kü-çə; «qatar»: qa-tar. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8615, 112, 'g11-aze-sound-q2-25', 2, 25, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 1 açıq heca var?', NULL, NULL, '{"A": "ild-ı-rım", "B": "şa-gird-lər", "C": "ya-səm-ən", "D": "qa-ra-nquş", "E": "pə-ncə-rə"}'::jsonb, 'B', NULL, 'Düzgün bölgü: şa-gird-lər. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8616, 112, 'g11-aze-sound-q2-26', 2, 26, 'hard', 'single', 'Hansı sözdə həm qalın, həm də incə sait var, 2 qapalı heca var, 2 heca var, dodaqlanan sait yoxdur və 2 kar samit var?', NULL, NULL, '{"A": "axşam", "B": "rəssam", "C": "tarix", "D": "kitablar", "E": "həyat"}'::jsonb, 'B', NULL, '«rəssam»: hecalar — rəs-sam; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 4 (2 cingiltili, 2 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8617, 112, 'g11-aze-sound-q2-27', 2, 27, 'hard', 'single', 'Hansı sözdə cingiltili samit yoxdur, 1 qapalı heca var, 3 səs var və açıq heca yoxdur?', NULL, NULL, '{"A": "tor", "B": "süt", "C": "tar", "D": "toy", "E": "boz"}'::jsonb, 'B', NULL, '«süt»: hecalar — süt; saitlər — 1 (0 qalın, 1 incə, 1 dodaqlanan); samitlər — 2 (0 cingiltili, 2 kar, 0 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8618, 112, 'g11-aze-sound-q2-28', 2, 28, 'hard', 'single', 'Hansı sözdə cingiltili samitlər kar samitlərdən çoxdur, son heca açıqdır, qapalı heca yoxdur və 1 qapalı (dar) sait var?', NULL, NULL, '{"A": "baba", "B": "yazıçı", "C": "qorxu", "D": "arı", "E": "qapı"}'::jsonb, 'D', NULL, '«arı»: hecalar — a-rı; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 1 (1 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8619, 112, 'g11-aze-sound-q2-29', 2, 29, 'hard', 'single', '«ildırım» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 1 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "B": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "C": "3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "D": "3 heca (1 açıq, 2 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor", "E": "3 heca (0 açıq, 3 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor"}'::jsonb, 'B', NULL, '«ildırım» — hecalar: il-dı-rım. 3 heca (1 açıq, 2 qapalı); 3 sait (2 qalın, 1 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 3 sonor.');
INSERT INTO public.questions VALUES (8620, 112, 'g11-aze-sound-q2-30', 2, 30, 'hard', 'single', 'Hansı sözdə 1 dodaqlanan sait var, 3 səs var, 1 sonor samit var və 1 qapalı heca var?', NULL, NULL, '{"A": "süfrə", "B": "yun", "C": "sol", "D": "top", "E": "çay"}'::jsonb, 'C', NULL, '«sol»: hecalar — sol; saitlər — 1 (1 qalın, 0 incə, 1 dodaqlanan); samitlər — 2 (1 cingiltili, 1 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8621, 112, 'g11-aze-sound-q3-01', 3, 1, 'hard', 'single', 'Hansı sözdə 2 heca var, son heca qapalıdır, 2 kar samit var və kar və cingiltili samitlərin sayı bərabərdir?', NULL, NULL, '{"A": "həyat", "B": "təbaşir", "C": "sahil", "D": "cəsarət", "E": "dastan"}'::jsonb, 'E', NULL, '«dastan»: hecalar — das-tan; saitlər — 2 (2 qalın, 0 incə, 0 dodaqlanan); samitlər — 4 (2 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8622, 112, 'g11-aze-sound-q3-02', 3, 2, 'hard', 'single', 'Hansı sözdə söz samitlə başlayır, açıq (geniş) sait yoxdur, dodaqlanan sait yoxdur və bütün saitlər incədir?', NULL, NULL, '{"A": "vətən", "B": "gil", "C": "dəqiqə", "D": "qızıl", "E": "keçi"}'::jsonb, 'B', NULL, '«gil»: hecalar — gil; saitlər — 1 (0 qalın, 1 incə, 0 dodaqlanan); samitlər — 2 (2 cingiltili, 0 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8623, 112, 'g11-aze-sound-q3-03', 3, 3, 'hard', 'single', '«sahil» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (2 açıq, 0 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 0 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 4 samit (1 cingiltili, 3 kar), 1 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'B', NULL, '«sahil» — hecalar: sa-hil. 2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8624, 112, 'g11-aze-sound-q3-04', 3, 4, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "keçi – yuxu", "B": "kartof – meşə", "C": "lampa – şəkər", "D": "axşam – pəncərə", "E": "bostan – bülbül"}'::jsonb, 'E', NULL, '«bostan»: bos-tan; «bülbül»: bül-bül. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8625, 112, 'g11-aze-sound-q3-05', 3, 5, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "gözəl – tufan", "B": "mavi – parça", "C": "keçi – xiyar", "D": "səyahət – təyyarə", "E": "dülgər – sahil"}'::jsonb, 'E', NULL, '«dülgər»: dül-gər; «sahil»: sa-hil. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8626, 112, 'g11-aze-sound-q3-06', 3, 6, 'hard', 'single', '«pərdə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (1 qalın, 1 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 1 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 0 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor"}'::jsonb, 'A', NULL, '«pərdə» — hecalar: pər-də. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8627, 112, 'g11-aze-sound-q3-07', 3, 7, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "mü-hənd-is", "B": "ko-man-da", "C": "o-yu-nçu", "D": "çar-pay-ı", "E": "ca-va-blar"}'::jsonb, 'B', NULL, 'Düzgün bölgü: ko-man-da. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8628, 112, 'g11-aze-sound-q3-08', 3, 8, 'hard', 'single', 'Hansı cütdə hər iki sözdə hecaların sayı eynidir, birinci sözdə dodaqlanan sait var, ikincidə isə yoxdur?', NULL, NULL, '{"A": "dastan – sərgi", "B": "gəlin – çinar", "C": "yumurta – şaftalı", "D": "günəş – küçə", "E": "dolu – qonşu"}'::jsonb, 'C', NULL, '«yumurta»: yu-mur-ta; «şaftalı»: şaf-ta-lı. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8629, 112, 'g11-aze-sound-q3-09', 3, 9, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "mə-nzə-rə", "B": "qı-zı-lgül", "C": "sən-ət-kar", "D": "cə-sar-ət", "E": "çar-pa-yı"}'::jsonb, 'E', NULL, 'Düzgün bölgü: çar-pa-yı. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8630, 112, 'g11-aze-sound-q3-10', 3, 10, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "dəniz – uzun", "B": "sənətkar – səyahət", "C": "səma – xəyal", "D": "dar – musiqi", "E": "qara – üzüm"}'::jsonb, 'E', NULL, '«qara»: qa-ra; «üzüm»: ü-züm. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8631, 112, 'g11-aze-sound-q3-11', 3, 11, 'hard', 'single', 'Hansı sözdə 2 cingiltili samit var, 1 açıq (geniş) sait var, bütün saitlər incədir və 2 sonor samit var?', NULL, NULL, '{"A": "dərin", "B": "hörmət", "C": "yemiş", "D": "oyunçu", "E": "oyun"}'::jsonb, 'C', NULL, '«yemiş»: hecalar — ye-miş; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (2 cingiltili, 1 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8632, 112, 'g11-aze-sound-q3-12', 3, 12, 'hard', 'single', '«hündür» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 2 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor", "B": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 1 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 2 dodaqlanan; 4 samit (2 cingiltili, 2 kar), 2 sonor", "D": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 2 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "E": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 2 dodaqlanan; 5 samit (3 cingiltili, 2 kar), 2 sonor"}'::jsonb, 'A', NULL, '«hündür» — hecalar: hün-dür. 2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 2 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8633, 112, 'g11-aze-sound-q3-13', 3, 13, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "arzu – səyahət", "B": "gündüz – nahar", "C": "alça – sərçə", "D": "daş – süt", "E": "canavar – süt"}'::jsonb, 'B', NULL, '«gündüz»: gün-düz; «nahar»: na-har. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8634, 112, 'g11-aze-sound-q3-14', 3, 14, 'hard', 'single', '«fəhlə» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 0 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 4 samit (1 cingiltili, 3 kar), 1 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'B', NULL, '«fəhlə» — hecalar: fəh-lə. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8635, 112, 'g11-aze-sound-q3-15', 3, 15, 'hard', 'single', '«dəmir» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor", "B": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor", "C": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 4 samit (3 cingiltili, 1 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 4 samit (4 cingiltili, 0 kar), 2 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor"}'::jsonb, 'A', NULL, '«dəmir» — hecalar: də-mir. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8636, 112, 'g11-aze-sound-q3-16', 3, 16, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz samitlə başlayır, qapalı (dar) sait yoxdur və bütün saitlər qalındır?', NULL, NULL, '{"A": "axşam, canavar, pozan", "B": "dar, fəhlə, xalça", "C": "nar, qum, xala", "D": "cəsarət, karandaş, masa", "E": "dolma, lampa, çoban"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8637, 112, 'g11-aze-sound-q3-17', 3, 17, 'hard', 'single', 'Hansı cütdə sözlərdə səslərin sayı bərabərdir, birinci sözdə kar samitlər ikincidəkindən çoxdur, birinci sözün saitləri qalın, ikincininki incədir?', NULL, NULL, '{"A": "həyat – sərgi", "B": "hakim – qoyun", "C": "ata – gül", "D": "top – yemiş", "E": "hakim – kədər"}'::jsonb, 'C', NULL, '«ata»: a-ta; «gül»: gül. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8638, 112, 'g11-aze-sound-q3-18', 3, 18, 'hard', 'single', 'Hansı cütdə heca sayı eynidir, açıq hecaların sayı fərqlidir, sözlərdən yalnız birində bütün saitlər qalındır?', NULL, NULL, '{"A": "acı – sevgi", "B": "orta – qısa", "C": "orta – sevgi", "D": "cəsarət – saz", "E": "təpə – xətkeş"}'::jsonb, 'A', NULL, '«acı»: a-cı; «sevgi»: sev-gi. Yalnız bu cüt bütün şərtləri ödəyir.');
INSERT INTO public.questions VALUES (8639, 112, 'g11-aze-sound-q3-19', 3, 19, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 1 açıq heca var?', NULL, NULL, '{"A": "qa-ra-nquş", "B": "mə-nzə-rə", "C": "qız-ıl-gül", "D": "ki-tabl-ar", "E": "ka-ran-daş"}'::jsonb, 'E', NULL, 'Düzgün bölgü: ka-ran-daş. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8640, 112, 'g11-aze-sound-q3-20', 3, 20, 'hard', 'single', '«sərin» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "B": "3 heca (2 açıq, 1 qapalı); 3 sait (0 qalın, 3 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "2 heca (0 açıq, 2 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "E": "3 heca (2 açıq, 1 qapalı); 3 sait (1 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor"}'::jsonb, 'A', NULL, '«sərin» — hecalar: sə-rin. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor.');
INSERT INTO public.questions VALUES (8641, 112, 'g11-aze-sound-q3-21', 3, 21, 'hard', 'single', 'Hansı sözdə 1 qapalı (dar) sait var, 2 qapalı heca var, 2 açıq (geniş) sait var və dodaqlanan sait yoxdur?', NULL, NULL, '{"A": "göyərçin", "B": "kitablar", "C": "çarpayı", "D": "rəssam", "E": "qarpız"}'::jsonb, 'B', NULL, '«kitablar»: hecalar — ki-tab-lar; saitlər — 3 (2 qalın, 1 incə, 0 dodaqlanan); samitlər — 5 (3 cingiltili, 2 kar, 2 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8642, 112, 'g11-aze-sound-q3-22', 3, 22, 'hard', 'single', '«geniş» sözünün fonetik təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "B": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 2 sonor", "C": "2 heca (2 açıq, 0 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor", "D": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (3 cingiltili, 0 kar), 1 sonor", "E": "2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (1 cingiltili, 2 kar), 1 sonor"}'::jsonb, 'A', NULL, '«geniş» — hecalar: ge-niş. 2 heca (1 açıq, 1 qapalı); 2 sait (0 qalın, 2 incə), 0 dodaqlanan; 3 samit (2 cingiltili, 1 kar), 1 sonor.');
INSERT INTO public.questions VALUES (8643, 112, 'g11-aze-sound-q3-23', 3, 23, 'hard', 'single', 'Hansı sözdə dodaqlanan sait yoxdur, kar samitlər cingiltili samitlərdən çoxdur, son heca açıqdır və 1 açıq heca var?', NULL, NULL, '{"A": "süfrə", "B": "sərgi", "C": "qapıçı", "D": "səhra", "E": "sahil"}'::jsonb, 'D', NULL, '«səhra»: hecalar — səh-ra; saitlər — 2 (1 qalın, 1 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8644, 112, 'g11-aze-sound-q3-24', 3, 24, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə söz samitlə başlayır, 2 heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "nənə, sərin, şirin", "B": "dəqiqə, səhər, təpə", "C": "bacı, günəş, sinif", "D": "dəniz, göyərçin, pərdə", "E": "dəftər, gəmi, sarı"}'::jsonb, 'A', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8645, 112, 'g11-aze-sound-q3-25', 3, 25, 'hard', 'single', 'Hansı sözdə 2 kar samit var, 1 qapalı heca var, 1 sonor samit var, dodaqlanan sait yoxdur və söz samitlə başlayır?', NULL, NULL, '{"A": "tülkü", "B": "divar", "C": "qatar", "D": "sinif", "E": "tar"}'::jsonb, 'D', NULL, '«sinif»: hecalar — si-nif; saitlər — 2 (0 qalın, 2 incə, 0 dodaqlanan); samitlər — 3 (1 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8646, 112, 'g11-aze-sound-q3-26', 3, 26, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə qapalı heca yoxdur, son heca açıqdır və bütün saitlər incədir?', NULL, NULL, '{"A": "dələ, masa, qələbə", "B": "sürücü, səma, tələbə", "C": "gəmi, küçə, şüşə", "D": "gecə, nənə, tamaşa", "E": "dəqiqə, dərə, səma"}'::jsonb, 'C', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8647, 112, 'g11-aze-sound-q3-27', 3, 27, 'hard', 'single', 'Hansı sözdə 3 heca var, söz samitlə başlayır, kar və cingiltili samitlərin sayı bərabərdir, həm qalın, həm də incə sait var və 2 cingiltili samit var?', NULL, NULL, '{"A": "çarpayı", "B": "saniyə", "C": "musiqi", "D": "cəsarət", "E": "zürafə"}'::jsonb, 'D', NULL, '«cəsarət»: hecalar — cə-sa-rət; saitlər — 3 (1 qalın, 2 incə, 0 dodaqlanan); samitlər — 4 (2 cingiltili, 2 kar, 1 sonor). Digər sözlər şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8648, 112, 'g11-aze-sound-q3-28', 3, 28, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 2 sonor samit var, 2 heca var və bütün saitlər incədir?', NULL, NULL, '{"A": "geniş, qələm, yemiş", "B": "gecə, nərgiz, pendir", "C": "dülgər, oyun, sərin", "D": "hörmət, nənə, çəmən", "E": "dəmir, dərin, üzüm"}'::jsonb, 'D', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8649, 112, 'g11-aze-sound-q3-29', 3, 29, 'hard', 'single', 'Hansı sözün hecalara bölünməsi düzgündür və həmin sözdə 2 açıq heca var?', NULL, NULL, '{"A": "nar-ın-cı", "B": "mən-zə-rə", "C": "mü-hənd-is", "D": "cəs-a-rət", "E": "meh-rib-an"}'::jsonb, 'B', NULL, 'Düzgün bölgü: mən-zə-rə. Saitlər arasındakı tək samit növbəti hecaya, iki samitdən ikincisi növbəti hecaya keçir.');
INSERT INTO public.questions VALUES (8650, 112, 'g11-aze-sound-q3-30', 3, 30, 'hard', 'single', 'Hansı cərgədəki bütün sözlərdə 1 qapalı (dar) sait var, kar samit yoxdur və bütün saitlər incədir?', NULL, NULL, '{"A": "ayı, gil, gəmi", "B": "alim, dəmir, dəniz", "C": "addım, gəlin, əmi", "D": "dülgər, nərgiz, pendir", "E": "dərin, geri, gül"}'::jsonb, 'E', NULL, 'Düzgün cərgədə hər üç söz şərtləri ödəyir; digər cərgələrdə bir söz şərtlərdən birinə uyğun gəlmir.');
INSERT INTO public.questions VALUES (8651, 113, 'g11-aze-orth-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ən» ədatının, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, sual ədatının (-mı, -mi) yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bu, ən gözəl mənzərədir. Evdəki hamı yatmışdı. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu?", "B": "Bu, ən gözəl mənzərədir. Evdəki hamı yatmışdı. Dedi ki, sabah gələcək. Sən bu kitabı oxudun mu?", "C": "Bu, ən gözəl mənzərədir. Evdə ki hamı yatmışdı. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu?", "D": "Bu, ən gözəl mənzərədir. Evdəki hamı yatmışdı. Dediki, sabah gələcək. Sən bu kitabı oxudunmu?", "E": "Bu, əngözəl mənzərədir. Evdəki hamı yatmışdı. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu?"}'::jsonb, 'A', NULL, 'Düzgün: Bu, ən gözəl mənzərədir. Evdəki hamı yatmışdı. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu? «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8652, 113, 'g11-aze-orth-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "B": "Qonaxlıq süfrəsinə isti çörək qoyuldu.", "C": "Qonaqlığ süfrəsinə isti çörək qoyuldu.", "D": "Qonaxlıx süfrəsinə isti çörək qoyuldu.", "E": "Qonaqlıq süfrəsinə isti çörəy qoyuldu."}'::jsonb, 'A', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8653, 113, 'g11-aze-orth-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «köynəki» və «oğulu» sözləri işlənmişdi.", "B": "Diktantda «köynəyi» və «oğulu» sözləri işlənmişdi.", "C": "Diktantda «nitqi» və «oğlu» sözləri işlənmişdi.", "D": "Diktantda «köynəyi» və «oğlu» sözləri işlənmişdi.", "E": "Diktantda «parkı» və «sinfi» sözləri işlənmişdi."}'::jsonb, 'D', NULL, 'köynək → köynəyi (k→y), oğul → oğlu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8654, 113, 'g11-aze-orth-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «yarpağı» və «könlü» sözlərini lövhəyə yazdı.", "B": "Şagird «qəfəsi» və «sinfi» sözlərini lövhəyə yazdı.", "C": "Şagird «uşağı» və «nitqi» sözlərini lövhəyə yazdı.", "D": "Şagird «qəfsi» və «sinfi» sözlərini lövhəyə yazdı.", "E": "Şagird «qəfsi» və «sinifi» sözlərini lövhəyə yazdı."}'::jsonb, 'B', NULL, 'qəfəs → qəfəsi (dəyişmir), sinif → sinfi (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8655, 113, 'g11-aze-orth-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «uşağı» və «ağzı» sözləri işlənmişdi.", "B": "Diktantda «boynu» və «inəyi» sözləri işlənmişdi.", "C": "Diktantda «boynu» və «inəki» sözləri işlənmişdi.", "D": "Diktantda «ağızı» və «dirəyi» sözləri işlənmişdi.", "E": "Diktantda «ağzı» və «dirəki» sözləri işlənmişdi."}'::jsonb, 'B', NULL, 'boyun → boynu (sait düşümü), inək → inəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8656, 113, 'g11-aze-orth-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə kökləri [doxquz] və [məxtəp] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Ayın doqquzunda məxtəpdə imtahan keçiriləcək.", "B": "Ayın doqquzunda məxtəbdə imtahan keçiriləcək.", "C": "Ayın doxquzunda məktəbdə imtahan keçiriləcək.", "D": "Ayın doqquzunda məktəpdə imtahan keçiriləcək.", "E": "Ayın doqquzunda məktəbdə imtahan keçiriləcək."}'::jsonb, 'E', NULL, '«doqquz» — qq birləşməsində birinci q x kimi tələffüz olunur, qq yazılır; «məktəb» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: Ayın doqquzunda məktəbdə imtahan keçiriləcək.');
INSERT INTO public.questions VALUES (8657, 113, 'g11-aze-orth-q1-07', 1, 7, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Dedi ki, sabah gələcək. Yarımada dənizə uzanır. Evdə ki hamı yatmışdı. Günəbaxan günəşə tərəf dönür.", "B": "Dedi ki, sabah gələcək. Yarım ada dənizə uzanır. Evdəki hamı yatmışdı. Günəbaxan günəşə tərəf dönür.", "C": "Dediki, sabah gələcək. Yarımada dənizə uzanır. Evdəki hamı yatmışdı. Günəbaxan günəşə tərəf dönür.", "D": "Dedi ki, sabah gələcək. Yarımada dənizə uzanır. Evdəki hamı yatmışdı. Günəbaxan günəşə tərəf dönür.", "E": "Dedi ki, sabah gələcək. Yarımada dənizə uzanır. Evdəki hamı yatmışdı. Günə baxan günəşə tərəf dönür."}'::jsonb, 'D', NULL, 'Düzgün: Dedi ki, sabah gələcək. Yarımada dənizə uzanır. Evdəki hamı yatmışdı. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8658, 113, 'g11-aze-orth-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «bıçağı» və «ürəyi» sözlərini lövhəyə yazdı.", "B": "Şagird «ittifağı» və «ayağı» sözlərini lövhəyə yazdı.", "C": "Şagird «şərqi» və «bayrağı» sözlərini lövhəyə yazdı.", "D": "Şagird «fikri» və «fərqi» sözlərini lövhəyə yazdı.", "E": "Şagird «şərqi» və «bayraqı» sözlərini lövhəyə yazdı."}'::jsonb, 'C', NULL, 'şərq → şərqi (dəyişmir), bayraq → bayrağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8659, 113, 'g11-aze-orth-q1-09', 1, 9, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ağsaqqal söz aldı. Yavaş-yavaş irəlilədik. Dediki, sabah gələcək. Bilirəm ki, sən haqlısan.", "B": "Ağsaqqal söz aldı. Yavaş-yavaş irəlilədik. Dedi ki, sabah gələcək. Bilirəm ki, sən haqlısan.", "C": "Ağ saqqal söz aldı. Yavaş-yavaş irəlilədik. Dedi ki, sabah gələcək. Bilirəm ki, sən haqlısan.", "D": "Ağsaqqal söz aldı. Yavaş-yavaş irəlilədik. Dedi ki, sabah gələcək. Bilirəmki, sən haqlısan.", "E": "Ağsaqqal söz aldı. Yavaş yavaş irəlilədik. Dedi ki, sabah gələcək. Bilirəm ki, sən haqlısan."}'::jsonb, 'B', NULL, 'Düzgün: Ağsaqqal söz aldı. Yavaş-yavaş irəlilədik. Dedi ki, sabah gələcək. Bilirəm ki, sən haqlısan. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8660, 113, 'g11-aze-orth-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «nitqi» və «bıçağı» sözləri işlənmişdi.", "B": "Diktantda «nitqi» və «uşağı» sözləri işlənmişdi.", "C": "Diktantda «ittifaqı» və «dirəyi» sözləri işlənmişdi.", "D": "Diktantda «ittifağı» və «dirəyi» sözləri işlənmişdi.", "E": "Diktantda «şərqi» və «dirəki» sözləri işlənmişdi."}'::jsonb, 'C', NULL, 'ittifaq → ittifaqı (dəyişmir), dirək → dirəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8661, 113, 'g11-aze-orth-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə kökləri [qaçtı] və [oyuncax] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Uşaq qaçtı və oyuncaxını itirdi.", "B": "Uşaq qaçdı və oyuncaxını itirdi.", "C": "Uşaq qaçdı və oyuncağını itirdi.", "D": "Uşaq qaçdı və oyuncaqını itirdi.", "E": "Uşaq qaçtı və oyuncağını itirdi."}'::jsonb, 'C', NULL, '«qaçdı» — Kar samitdən sonra d t kimi tələffüz olunur, d yazılır; «oyuncaq» — Sonda q yazılır. Düzgün: Uşaq qaçdı və oyuncağını itirdi.');
INSERT INTO public.questions VALUES (8662, 113, 'g11-aze-orth-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «bayrağı» və «xalqı» sözlərini lövhəyə yazdı.", "B": "Şagird «ürəyi» və «qulağı» sözlərini lövhəyə yazdı.", "C": "Şagird «parkı» və «qulağı» sözlərini lövhəyə yazdı.", "D": "Şagird «ürəki» və «qulağı» sözlərini lövhəyə yazdı.", "E": "Şagird «ittifaqı» və «uşağı» sözlərini lövhəyə yazdı."}'::jsonb, 'B', NULL, 'ürək → ürəyi (k→y), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8663, 113, 'g11-aze-orth-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «köynəyi» və «sinfi» sözlərini lövhəyə yazdı.", "B": "Şagird «ittifağı» və «fikri» sözlərini lövhəyə yazdı.", "C": "Şagird «uşağı» və «könlü» sözlərini lövhəyə yazdı.", "D": "Şagird «şəkli» və «xalğı» sözlərini lövhəyə yazdı.", "E": "Şagird «hüququ» və «qarnı» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'hüquq → hüququ (dəyişmir), qarın → qarnı (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8664, 113, 'g11-aze-orth-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaqlıq süfrəsinə isti çörəq qoyuldu.", "B": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "C": "Qonaqlıq süfrəsinə isti çörəy qoyuldu.", "D": "Qonaqlıx süfrəsinə isti çörək qoyuldu.", "E": "Qonaxlıq süfrəsinə isti çörək qoyuldu."}'::jsonb, 'B', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8665, 113, 'g11-aze-orth-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «qarnı», «dənizi» sözlərini misal gətirdi.", "B": "Müəllim «ittifaqı», «çörəyi» sözlərini misal gətirdi.", "C": "Müəllim «parkı», «yarpağı» sözlərini misal gətirdi.", "D": "Müəllim «qəfəsi», «oğlu» sözlərini misal gətirdi.", "E": "Müəllim «şəhəri», «yarpaqı» sözlərini misal gətirdi."}'::jsonb, 'C', NULL, 'park → parkı (dəyişmir), yarpaq → yarpağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8666, 113, 'g11-aze-orth-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaqlıx süfrəsinə isti çörək qoyuldu.", "B": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "C": "Qonaxlıx süfrəsinə isti çörək qoyuldu.", "D": "Qonaqlıq süfrəsinə isti çörəy qoyuldu.", "E": "Qonaxlıq süfrəsinə isti çörək qoyuldu."}'::jsonb, 'B', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8667, 113, 'g11-aze-orth-q1-17', 1, 17, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), «da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Sən bu kitabı oxudunmu? Səndə bu işdə iştirak et. Kitab evdə qalıb. Ayaqqabılarını təmizlədi.", "B": "Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et. Kitab evdə qalıb. Ayaq qabılarını təmizlədi.", "C": "Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et. Kitab evdə qalıb. Ayaqqabılarını təmizlədi.", "D": "Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et. Kitab ev də qalıb. Ayaqqabılarını təmizlədi.", "E": "Sən bu kitabı oxudun mu? Sən də bu işdə iştirak et. Kitab evdə qalıb. Ayaqqabılarını təmizlədi."}'::jsonb, 'C', NULL, 'Düzgün: Sən bu kitabı oxudunmu? Sən də bu işdə iştirak et. Kitab evdə qalıb. Ayaqqabılarını təmizlədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8668, 113, 'g11-aze-orth-q1-18', 1, 18, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, sual ədatının (-mı, -mi), «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bilirəm ki, sən haqlısan. Onlar artıq gəldilər mi? Evdəki hamı yatmışdı. Sən də bu işdə iştirak et.", "B": "Bilirəm ki, sən haqlısan. Onlar artıq gəldilərmi? Evdəki hamı yatmışdı. Səndə bu işdə iştirak et.", "C": "Bilirəm ki, sən haqlısan. Onlar artıq gəldilərmi? Evdə ki hamı yatmışdı. Sən də bu işdə iştirak et.", "D": "Bilirəmki, sən haqlısan. Onlar artıq gəldilərmi? Evdəki hamı yatmışdı. Sən də bu işdə iştirak et.", "E": "Bilirəm ki, sən haqlısan. Onlar artıq gəldilərmi? Evdəki hamı yatmışdı. Sən də bu işdə iştirak et."}'::jsonb, 'E', NULL, 'Düzgün: Bilirəm ki, sən haqlısan. Onlar artıq gəldilərmi? Evdəki hamı yatmışdı. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8669, 113, 'g11-aze-orth-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə kökləri [sümbül] və [saxqal] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Günəş altında sünbül kimi saqqalı qızılı rəngə çalırdı.", "B": "Günəş altında sünbül kimi saxqalı qızılı rəngə çalırdı.", "C": "Günəş altında sümbül kimi saxqalı qızılı rəngə çalırdı.", "D": "Günəş altında sümbül kimi saqqalı qızılı rəngə çalırdı.", "E": "Günəş altında sünbül kimi saqalı qızılı rəngə çalırdı."}'::jsonb, 'A', NULL, '«sünbül» — n b-dən əvvəl m kimi tələffüz olunur, n yazılır; «saqqal» — qq yazılır. Düzgün: Günəş altında sünbül kimi saqqalı qızılı rəngə çalırdı.');
INSERT INTO public.questions VALUES (8670, 113, 'g11-aze-orth-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «bıçağı», «dənizi» sözlərini misal gətirdi.", "B": "Müəllim «ittifaqı», «fikri» sözlərini misal gətirdi.", "C": "Müəllim «köynəyi», «uşağı» sözlərini misal gətirdi.", "D": "Müəllim «ömrü», «bıçağı» sözlərini misal gətirdi.", "E": "Müəllim «çiçəyi», «bayrağı» sözlərini misal gətirdi."}'::jsonb, 'A', NULL, 'bıçaq → bıçağı (q→ğ), dəniz → dənizi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8671, 113, 'g11-aze-orth-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «alını» və «çörəki» sözləri işlənmişdi.", "B": "Diktantda «ağızı» və «köynəki» sözləri işlənmişdi.", "C": "Diktantda «inəyi» və «burnu» sözləri işlənmişdi.", "D": "Diktantda «ürəyi» və «hüququ» sözləri işlənmişdi.", "E": "Diktantda «ittifaqı» və «ürəyi» sözləri işlənmişdi."}'::jsonb, 'C', NULL, 'inək → inəyi (k→y), burun → burnu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8672, 113, 'g11-aze-orth-q1-22', 1, 22, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («heç» sözünün, mürəkkəb sözün, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Heç nə görmədim. Yarımada dənizə uzanır. Bu, ən gözəl mənzərədir. Ağsaqqal söz aldı.", "B": "Heç nə görmədim. Yarım ada dənizə uzanır. Bu, ən gözəl mənzərədir. Ağsaqqal söz aldı.", "C": "Heç nə görmədim. Yarımada dənizə uzanır. Bu, əngözəl mənzərədir. Ağsaqqal söz aldı.", "D": "Heç nə görmədim. Yarımada dənizə uzanır. Bu, ən gözəl mənzərədir. Ağ saqqal söz aldı.", "E": "Heçnə görmədim. Yarımada dənizə uzanır. Bu, ən gözəl mənzərədir. Ağsaqqal söz aldı."}'::jsonb, 'A', NULL, 'Düzgün: Heç nə görmədim. Yarımada dənizə uzanır. Bu, ən gözəl mənzərədir. Ağsaqqal söz aldı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8673, 113, 'g11-aze-orth-q1-23', 1, 23, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Masadakı kitab mənimdir. Sən də bu işdə iştirak et. Qızıl gül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi.", "B": "Masadakı kitab mənimdir. Səndə bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi.", "C": "Masada ki kitab mənimdir. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi.", "D": "Masadakı kitab mənimdir. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi. Qardaşımda, bacımda gəldi.", "E": "Masadakı kitab mənimdir. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi."}'::jsonb, 'E', NULL, 'Düzgün: Masadakı kitab mənimdir. Sən də bu işdə iştirak et. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8674, 113, 'g11-aze-orth-q1-24', 1, 24, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «heç» sözünün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə gülə danışırdı. Heç kim bu suala cavab vermədi. Masadakı kitab mənimdir. Yavaş-yavaş irəlilədik.", "B": "Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Masadakı kitab mənimdir. Yavaş-yavaş irəlilədik.", "C": "Gülə-gülə danışırdı. Heçkim bu suala cavab vermədi. Masadakı kitab mənimdir. Yavaş-yavaş irəlilədik.", "D": "Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Masada ki kitab mənimdir. Yavaş-yavaş irəlilədik.", "E": "Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Masadakı kitab mənimdir. Yavaş yavaş irəlilədik."}'::jsonb, 'B', NULL, 'Düzgün: Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Masadakı kitab mənimdir. Yavaş-yavaş irəlilədik. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8675, 113, 'g11-aze-orth-q1-25', 1, 25, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «heç» sözünün, mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı. Kitab evdə qalıb.", "B": "Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı. Kitab ev də qalıb.", "C": "Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağ saqqal söz aldı. Kitab evdə qalıb.", "D": "Bilirəmki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı. Kitab evdə qalıb.", "E": "Bilirəm ki, sən haqlısan. Heçnə görmədim. Ağsaqqal söz aldı. Kitab evdə qalıb."}'::jsonb, 'A', NULL, 'Düzgün: Bilirəm ki, sən haqlısan. Heç nə görmədim. Ağsaqqal söz aldı. Kitab evdə qalıb. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8676, 113, 'g11-aze-orth-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə kökləri [məxtəp] və [uşaxlar] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Məxtəbdən qayıdan uşaqlar sevincini gizlədə bilmirdi.", "B": "Məxtəpdən qayıdan uşaqlar sevincini gizlədə bilmirdi.", "C": "Məktəbdən qayıdan uşaxlar sevincini gizlədə bilmirdi.", "D": "Məktəpdən qayıdan uşaqlar sevincini gizlədə bilmirdi.", "E": "Məktəbdən qayıdan uşaqlar sevincini gizlədə bilmirdi."}'::jsonb, 'E', NULL, '«məktəb» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur; «uşaqlar» — q samitdən əvvəl x kimi tələffüz olunur, q yazılır. Düzgün: Məktəbdən qayıdan uşaqlar sevincini gizlədə bilmirdi.');
INSERT INTO public.questions VALUES (8677, 113, 'g11-aze-orth-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «bayraqı» və «çiçəki» sözlərini lövhəyə yazdı.", "B": "Şagird «bankı» və «qulağı» sözlərini lövhəyə yazdı.", "C": "Şagird «bayrağı» və «çiçəyi» sözlərini lövhəyə yazdı.", "D": "Şagird «bıçağı» və «fikri» sözlərini lövhəyə yazdı.", "E": "Şagird «bayraqı» və «çiçəyi» sözlərini lövhəyə yazdı."}'::jsonb, 'C', NULL, 'bayraq → bayrağı (q→ğ), çiçək → çiçəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8678, 113, 'g11-aze-orth-q1-28', 1, 28, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, sual ədatının (-mı, -mi), «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Günəbaxan günəşə tərəf dönür. Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Ayaq qabılarını təmizlədi.", "B": "Günəbaxan günəşə tərəf dönür. Sən bu kitabı oxudunmu? Evdə ki hamı yatmışdı. Ayaqqabılarını təmizlədi.", "C": "Günəbaxan günəşə tərəf dönür. Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Ayaqqabılarını təmizlədi.", "D": "Günəbaxan günəşə tərəf dönür. Sən bu kitabı oxudun mu? Evdəki hamı yatmışdı. Ayaqqabılarını təmizlədi.", "E": "Günə baxan günəşə tərəf dönür. Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Ayaqqabılarını təmizlədi."}'::jsonb, 'C', NULL, 'Düzgün: Günəbaxan günəşə tərəf dönür. Sən bu kitabı oxudunmu? Evdəki hamı yatmışdı. Ayaqqabılarını təmizlədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8679, 113, 'g11-aze-orth-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə kökləri [sümbül] və [saxqal] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Günəş altında sünbül kimi saqqalı qızılı rəngə çalırdı.", "B": "Günəş altında sümbül kimi saqalı qızılı rəngə çalırdı.", "C": "Günəş altında sünbül kimi saxqalı qızılı rəngə çalırdı.", "D": "Günəş altında sümbül kimi saqqalı qızılı rəngə çalırdı.", "E": "Günəş altında sünbül kimi saqalı qızılı rəngə çalırdı."}'::jsonb, 'A', NULL, '«sünbül» — n b-dən əvvəl m kimi tələffüz olunur, n yazılır; «saqqal» — qq yazılır. Düzgün: Günəş altında sünbül kimi saqqalı qızılı rəngə çalırdı.');
INSERT INTO public.questions VALUES (8680, 113, 'g11-aze-orth-q1-30', 1, 30, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşım da, bacım da gəldi. Ara-sıra bizə baş çəkir. Ayaq qabılarını təmizlədi. Günəbaxan günəşə tərəf dönür.", "B": "Qardaşım da, bacım da gəldi. Arasıra bizə baş çəkir. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür.", "C": "Qardaşım da, bacım da gəldi. Ara-sıra bizə baş çəkir. Ayaqqabılarını təmizlədi. Günə baxan günəşə tərəf dönür.", "D": "Qardaşımda, bacımda gəldi. Ara-sıra bizə baş çəkir. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür.", "E": "Qardaşım da, bacım da gəldi. Ara-sıra bizə baş çəkir. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür."}'::jsonb, 'E', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Ara-sıra bizə baş çəkir. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8681, 113, 'g11-aze-orth-q2-01', 2, 1, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün, «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşım da, bacım da gəldi. Kitab evdə qalıb. Arasıra bizə baş çəkir. Heç nə görmədim.", "B": "Qardaşım da, bacım da gəldi. Kitab ev də qalıb. Ara-sıra bizə baş çəkir. Heç nə görmədim.", "C": "Qardaşımda, bacımda gəldi. Kitab evdə qalıb. Ara-sıra bizə baş çəkir. Heç nə görmədim.", "D": "Qardaşım da, bacım da gəldi. Kitab evdə qalıb. Ara-sıra bizə baş çəkir. Heçnə görmədim.", "E": "Qardaşım da, bacım da gəldi. Kitab evdə qalıb. Ara-sıra bizə baş çəkir. Heç nə görmədim."}'::jsonb, 'E', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Kitab evdə qalıb. Ara-sıra bizə baş çəkir. Heç nə görmədim. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8682, 113, 'g11-aze-orth-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «çiçəyi» və «ağzı» sözləri işlənmişdi.", "B": "Diktantda «alnı» və «çörəyi» sözləri işlənmişdi.", "C": "Diktantda «yarpağı» və «inəyi» sözləri işlənmişdi.", "D": "Diktantda «çiçəyi» və «könlü» sözləri işlənmişdi.", "E": "Diktantda «yarpaqı» və «inəki» sözləri işlənmişdi."}'::jsonb, 'C', NULL, 'yarpaq → yarpağı (q→ğ), inək → inəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8683, 113, 'g11-aze-orth-q2-03', 2, 3, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, qoşa sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bilirəm ki, sən haqlısan. Yavaş yavaş irəlilədik. Kitab evdə qalıb. Qardaşım da, bacım da gəldi.", "B": "Bilirəm ki, sən haqlısan. Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Qardaşımda, bacımda gəldi.", "C": "Bilirəmki, sən haqlısan. Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Qardaşım da, bacım da gəldi.", "D": "Bilirəm ki, sən haqlısan. Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Qardaşım da, bacım da gəldi.", "E": "Bilirəm ki, sən haqlısan. Yavaş-yavaş irəlilədik. Kitab ev də qalıb. Qardaşım da, bacım da gəldi."}'::jsonb, 'D', NULL, 'Düzgün: Bilirəm ki, sən haqlısan. Yavaş-yavaş irəlilədik. Kitab evdə qalıb. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8684, 113, 'g11-aze-orth-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «qəfəsi», «ayağı» sözlərini misal gətirdi.", "B": "Müəllim «inəki», «yarpağı» sözlərini misal gətirdi.", "C": "Müəllim «bayrağı», «şəkli» sözlərini misal gətirdi.", "D": "Müəllim «könlü», «ürəyi» sözlərini misal gətirdi.", "E": "Müəllim «inəyi», «yarpağı» sözlərini misal gətirdi."}'::jsonb, 'E', NULL, 'inək → inəyi (k→y), yarpaq → yarpağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8685, 113, 'g11-aze-orth-q2-05', 2, 5, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Yarımada dənizə uzanır. Qardaşımda, bacımda gəldi.", "B": "Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Yarımada dənizə uzanır. Qardaşım da, bacım da gəldi.", "C": "Ata-ana övladını qoruyar. Masada ki kitab mənimdir. Yarımada dənizə uzanır. Qardaşım da, bacım da gəldi.", "D": "Ataana övladını qoruyar. Masadakı kitab mənimdir. Yarımada dənizə uzanır. Qardaşım da, bacım da gəldi.", "E": "Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Yarım ada dənizə uzanır. Qardaşım da, bacım da gəldi."}'::jsonb, 'B', NULL, 'Düzgün: Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Yarımada dənizə uzanır. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8686, 113, 'g11-aze-orth-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə kökləri [qılınç] və [bayrax] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Əsgər qılıncı qınından çıxarıb bayraxı öpdü.", "B": "Əsgər qılıncı qınından çıxarıb bayraqı öpdü.", "C": "Əsgər qılınçı qınından çıxarıb bayrağı öpdü.", "D": "Əsgər qılıncı qınından çıxarıb bayrağı öpdü.", "E": "Əsgər qılınçı qınından çıxarıb bayraqı öpdü."}'::jsonb, 'D', NULL, '«qılınc» — Sonda c yazılır; «bayraq» — Sonda q yazılır. Düzgün: Əsgər qılıncı qınından çıxarıb bayrağı öpdü.');
INSERT INTO public.questions VALUES (8687, 113, 'g11-aze-orth-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə kökləri [axsaxqal] və [çərşəmbə] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Ağsaqqal çərşəmbə günü gəlməyi vəd etdi.", "B": "Ağsaqal çərşənbə günü gəlməyi vəd etdi.", "C": "Axsaqqal çərşənbə günü gəlməyi vəd etdi.", "D": "Ağsaxqal çərşənbə günü gəlməyi vəd etdi.", "E": "Ağsaqqal çərşənbə günü gəlməyi vəd etdi."}'::jsonb, 'E', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «çərşənbə» — n yazılır. Düzgün: Ağsaqqal çərşənbə günü gəlməyi vəd etdi.');
INSERT INTO public.questions VALUES (8688, 113, 'g11-aze-orth-q2-08', 2, 8, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Sən bu kitabı oxudunmu? Yavaş-yavaş irəlilədik. Masada ki kitab mənimdir. Günəbaxan günəşə tərəf dönür.", "B": "Sən bu kitabı oxudunmu? Yavaş-yavaş irəlilədik. Masadakı kitab mənimdir. Günə baxan günəşə tərəf dönür.", "C": "Sən bu kitabı oxudun mu? Yavaş-yavaş irəlilədik. Masadakı kitab mənimdir. Günəbaxan günəşə tərəf dönür.", "D": "Sən bu kitabı oxudunmu? Yavaş yavaş irəlilədik. Masadakı kitab mənimdir. Günəbaxan günəşə tərəf dönür.", "E": "Sən bu kitabı oxudunmu? Yavaş-yavaş irəlilədik. Masadakı kitab mənimdir. Günəbaxan günəşə tərəf dönür."}'::jsonb, 'E', NULL, 'Düzgün: Sən bu kitabı oxudunmu? Yavaş-yavaş irəlilədik. Masadakı kitab mənimdir. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8689, 113, 'g11-aze-orth-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə kökləri [doxquz] və [məxtəp] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Ayın doquzunda məktəbdə imtahan keçiriləcək.", "B": "Ayın doqquzunda məxtəbdə imtahan keçiriləcək.", "C": "Ayın doqquzunda məktəbdə imtahan keçiriləcək.", "D": "Ayın doqquzunda məktəpdə imtahan keçiriləcək.", "E": "Ayın doxquzunda məktəbdə imtahan keçiriləcək."}'::jsonb, 'C', NULL, '«doqquz» — qq birləşməsində birinci q x kimi tələffüz olunur, qq yazılır; «məktəb» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: Ayın doqquzunda məktəbdə imtahan keçiriləcək.');
INSERT INTO public.questions VALUES (8690, 113, 'g11-aze-orth-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə kökləri [axsaxqal] və [çərşəmbə] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Axsaqqal çərşənbə günü gəlməyi vəd etdi.", "B": "Ağsaqal çərşənbə günü gəlməyi vəd etdi.", "C": "Axsaxqal çərşənbə günü gəlməyi vəd etdi.", "D": "Ağsaxqal çərşənbə günü gəlməyi vəd etdi.", "E": "Ağsaqqal çərşənbə günü gəlməyi vəd etdi."}'::jsonb, 'E', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «çərşənbə» — n yazılır. Düzgün: Ağsaqqal çərşənbə günü gəlməyi vəd etdi.');
INSERT INTO public.questions VALUES (8691, 113, 'g11-aze-orth-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «şəkli» və «xalğı» sözlərini lövhəyə yazdı.", "B": "Şagird «ittifaqı» və «ismi» sözlərini lövhəyə yazdı.", "C": "Şagird «ismi» və «qulağı» sözlərini lövhəyə yazdı.", "D": "Şagird «qarını» və «fərği» sözlərini lövhəyə yazdı.", "E": "Şagird «ittifağı» və «ismi» sözlərini lövhəyə yazdı."}'::jsonb, 'B', NULL, 'ittifaq → ittifaqı (dəyişmir), isim → ismi (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8692, 113, 'g11-aze-orth-q2-12', 2, 12, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Kitab evdə qalıb. Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Qardaşımda, bacımda gəldi.", "B": "Kitab evdə qalıb. Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Qardaşım da, bacım da gəldi.", "C": "Kitab evdə qalıb. Ata-ana övladını qoruyar. Masada ki kitab mənimdir. Qardaşım da, bacım da gəldi.", "D": "Kitab ev də qalıb. Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Qardaşım da, bacım da gəldi.", "E": "Kitab evdə qalıb. Ataana övladını qoruyar. Masadakı kitab mənimdir. Qardaşım da, bacım da gəldi."}'::jsonb, 'B', NULL, 'Düzgün: Kitab evdə qalıb. Ata-ana övladını qoruyar. Masadakı kitab mənimdir. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8693, 113, 'g11-aze-orth-q2-13', 2, 13, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, qoşa sözün, sual ədatının (-mı, -mi) yazılışına diqqət edin)?', NULL, NULL, '{"A": "Dedi ki, sabah gələcək. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir.", "B": "Dediki, sabah gələcək. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir.", "C": "Dedi ki, sabah gələcək. Ataana övladını qoruyar. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir.", "D": "Dedi ki, sabah gələcək. Ata-ana övladını qoruyar. Sən bu kitabı oxudun mu? Ara-sıra bizə baş çəkir.", "E": "Dedi ki, sabah gələcək. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu? Arasıra bizə baş çəkir."}'::jsonb, 'A', NULL, 'Düzgün: Dedi ki, sabah gələcək. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8694, 113, 'g11-aze-orth-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «köynəki» və «bayraqı» sözləri işlənmişdi.", "B": "Diktantda «uşağı» və «qarnı» sözləri işlənmişdi.", "C": "Diktantda «oğlu» və «uşağı» sözləri işlənmişdi.", "D": "Diktantda «çörəyi» və «bankı» sözləri işlənmişdi.", "E": "Diktantda «dirəyi» və «ayağı» sözləri işlənmişdi."}'::jsonb, 'E', NULL, 'dirək → dirəyi (k→y), ayaq → ayağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8695, 113, 'g11-aze-orth-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «ayaqı», «sinifi» sözlərini misal gətirdi.", "B": "Müəllim «ayağı», «ağzı» sözlərini misal gətirdi.", "C": "Müəllim «qarnı», «köynəyi» sözlərini misal gətirdi.", "D": "Müəllim «uşağı», «fərqi» sözlərini misal gətirdi.", "E": "Müəllim «ürəyi», «uşağı» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'ayaq → ayağı (q→ğ), ağız → ağzı (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8696, 113, 'g11-aze-orth-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «ağzı», «çörəyi» sözlərini misal gətirdi.", "B": "Müəllim «ömrü», «uşağı» sözlərini misal gətirdi.", "C": "Müəllim «könlü», «xalqı» sözlərini misal gətirdi.", "D": "Müəllim «qarını», «köynəyi» sözlərini misal gətirdi.", "E": "Müəllim «parkı», «sinfi» sözlərini misal gətirdi."}'::jsonb, 'A', NULL, 'ağız → ağzı (sait düşümü), çörək → çörəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8697, 113, 'g11-aze-orth-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə kökləri [köynəy''] və [ayaxqabı] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Köynəyini və ayaqabısını geyinib qonaqlığa getdi.", "B": "Köynəkini və ayaqqabısını geyinib qonaqlığa getdi.", "C": "Köynəkini və ayaqabısını geyinib qonaqlığa getdi.", "D": "Köynəyini və ayaqqabısını geyinib qonaqlığa getdi.", "E": "Köynəyini və ayaxqabısını geyinib qonaqlığa getdi."}'::jsonb, 'D', NULL, '«köynək» — Sonda k yazılır; «ayaqqabı» — qq yazılır. Düzgün: Köynəyini və ayaqqabısını geyinib qonaqlığa getdi.');
INSERT INTO public.questions VALUES (8698, 113, 'g11-aze-orth-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «nitği» və «uşaqı» sözlərini lövhəyə yazdı.", "B": "Şagird «nitqi» və «uşağı» sözlərini lövhəyə yazdı.", "C": "Şagird «burnu» və «xalqı» sözlərini lövhəyə yazdı.", "D": "Şagird «dənizi» və «sinfi» sözlərini lövhəyə yazdı.", "E": "Şagird «parkı» və «çiçəyi» sözlərini lövhəyə yazdı."}'::jsonb, 'B', NULL, 'nitq → nitqi (dəyişmir), uşaq → uşağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8699, 113, 'g11-aze-orth-q2-19', 2, 19, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ən» ədatının, sual ədatının (-mı, -mi) yazılışına diqqət edin)?', NULL, NULL, '{"A": "Ara-sıra bizə baş çəkir. Bu, əngözəl mənzərədir. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu?", "B": "Ara-sıra bizə baş çəkir. Bu, ən gözəl mənzərədir. Ata-ana övladını qoruyar. Sən bu kitabı oxudun mu?", "C": "Arasıra bizə baş çəkir. Bu, ən gözəl mənzərədir. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu?", "D": "Ara-sıra bizə baş çəkir. Bu, ən gözəl mənzərədir. Ataana övladını qoruyar. Sən bu kitabı oxudunmu?", "E": "Ara-sıra bizə baş çəkir. Bu, ən gözəl mənzərədir. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu?"}'::jsonb, 'E', NULL, 'Düzgün: Ara-sıra bizə baş çəkir. Bu, ən gözəl mənzərədir. Ata-ana övladını qoruyar. Sən bu kitabı oxudunmu? «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8700, 113, 'g11-aze-orth-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «xalqı» və «fikri» sözləri işlənmişdi.", "B": "Diktantda «şərqi» və «çiçəyi» sözləri işlənmişdi.", "C": "Diktantda «yarpağı» və «qəfsi» sözləri işlənmişdi.", "D": "Diktantda «fərqi» və «ayağı» sözləri işlənmişdi.", "E": "Diktantda «ağzı» və «xalqı» sözləri işlənmişdi."}'::jsonb, 'D', NULL, 'fərq → fərqi (dəyişmir), ayaq → ayağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8701, 113, 'g11-aze-orth-q2-21', 2, 21, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, qoşa sözün, sual ədatının (-mı, -mi), «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Evdəki hamı yatmışdı. Ara-sıra bizə baş çəkir. Onlar artıq gəldilərmi? Bu, əngözəl mənzərədir.", "B": "Evdə ki hamı yatmışdı. Ara-sıra bizə baş çəkir. Onlar artıq gəldilərmi? Bu, ən gözəl mənzərədir.", "C": "Evdəki hamı yatmışdı. Ara-sıra bizə baş çəkir. Onlar artıq gəldilərmi? Bu, ən gözəl mənzərədir.", "D": "Evdəki hamı yatmışdı. Ara-sıra bizə baş çəkir. Onlar artıq gəldilər mi? Bu, ən gözəl mənzərədir.", "E": "Evdəki hamı yatmışdı. Arasıra bizə baş çəkir. Onlar artıq gəldilərmi? Bu, ən gözəl mənzərədir."}'::jsonb, 'C', NULL, 'Düzgün: Evdəki hamı yatmışdı. Ara-sıra bizə baş çəkir. Onlar artıq gəldilərmi? Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8702, 113, 'g11-aze-orth-q2-22', 2, 22, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (sual ədatının (-mı, -mi), qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Sən bu kitabı oxudunmu? Ata-ana övladını qoruyar. Arasıra bizə baş çəkir. Yavaş-yavaş irəlilədik.", "B": "Sən bu kitabı oxudunmu? Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir. Yavaş yavaş irəlilədik.", "C": "Sən bu kitabı oxudunmu? Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir. Yavaş-yavaş irəlilədik.", "D": "Sən bu kitabı oxudunmu? Ataana övladını qoruyar. Ara-sıra bizə baş çəkir. Yavaş-yavaş irəlilədik.", "E": "Sən bu kitabı oxudun mu? Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir. Yavaş-yavaş irəlilədik."}'::jsonb, 'C', NULL, 'Düzgün: Sən bu kitabı oxudunmu? Ata-ana övladını qoruyar. Ara-sıra bizə baş çəkir. Yavaş-yavaş irəlilədik. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8703, 113, 'g11-aze-orth-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «ayaqı», «qarını» sözlərini misal gətirdi.", "B": "Müəllim «ismi», «ittifaqı» sözlərini misal gətirdi.", "C": "Müəllim «qarını», «bayraqı» sözlərini misal gətirdi.", "D": "Müəllim «ayağı», «qarnı» sözlərini misal gətirdi.", "E": "Müəllim «qulağı», «çiçəyi» sözlərini misal gətirdi."}'::jsonb, 'D', NULL, 'ayaq → ayağı (q→ğ), qarın → qarnı (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8704, 113, 'g11-aze-orth-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «bıçağı» və «çiçəyi» sözləri işlənmişdi.", "B": "Diktantda «ömrü» və «çiçəyi» sözləri işlənmişdi.", "C": "Diktantda «parkı» və «köynəyi» sözləri işlənmişdi.", "D": "Diktantda «uşağı» və «qəfəsi» sözləri işlənmişdi.", "E": "Diktantda «bayrağı» və «ismi» sözləri işlənmişdi."}'::jsonb, 'A', NULL, 'bıçaq → bıçağı (q→ğ), çiçək → çiçəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8705, 113, 'g11-aze-orth-q2-25', 2, 25, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «da/də» bağlayıcısının və ya şəkilçisinin, «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Masadakı kitab mənimdir. Kitab ev də qalıb. Mən də sizinlə gedəcəyəm. Heç kim bu suala cavab vermədi.", "B": "Masadakı kitab mənimdir. Kitab evdə qalıb. Mən də sizinlə gedəcəyəm. Heçkim bu suala cavab vermədi.", "C": "Masadakı kitab mənimdir. Kitab evdə qalıb. Məndə sizinlə gedəcəyəm. Heç kim bu suala cavab vermədi.", "D": "Masada ki kitab mənimdir. Kitab evdə qalıb. Mən də sizinlə gedəcəyəm. Heç kim bu suala cavab vermədi.", "E": "Masadakı kitab mənimdir. Kitab evdə qalıb. Mən də sizinlə gedəcəyəm. Heç kim bu suala cavab vermədi."}'::jsonb, 'E', NULL, 'Düzgün: Masadakı kitab mənimdir. Kitab evdə qalıb. Mən də sizinlə gedəcəyəm. Heç kim bu suala cavab vermədi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8706, 113, 'g11-aze-orth-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaxlıq süfrəsinə isti çörək qoyuldu.", "B": "Qonaqlıq süfrəsinə isti çörəq qoyuldu.", "C": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "D": "Qonaqlıq süfrəsinə isti çörəy qoyuldu.", "E": "Qonaqlığ süfrəsinə isti çörək qoyuldu."}'::jsonb, 'C', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8707, 113, 'g11-aze-orth-q2-27', 2, 27, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («heç» sözünün, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Heç nə görmədim. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi.", "B": "Heç nə görmədim. Ayaqqabılarını təmizlədi. Günə baxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi.", "C": "Heç nə görmədim. Ayaq qabılarını təmizlədi. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi.", "D": "Heç nə görmədim. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür. Qızıl gül bağçanı bəzəyirdi.", "E": "Heçnə görmədim. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi."}'::jsonb, 'A', NULL, 'Düzgün: Heç nə görmədim. Ayaqqabılarını təmizlədi. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8708, 113, 'g11-aze-orth-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaxlıq süfrəsinə isti çörək qoyuldu.", "B": "Qonaqlığ süfrəsinə isti çörək qoyuldu.", "C": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "D": "Qonaqlıx süfrəsinə isti çörək qoyuldu.", "E": "Qonaqlıq süfrəsinə isti çörəq qoyuldu."}'::jsonb, 'C', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8709, 113, 'g11-aze-orth-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə kökləri [qaçtı] və [oyuncax] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Uşaq qaçdı və oyuncağını itirdi.", "B": "Uşaq qaçdı və oyuncaqını itirdi.", "C": "Uşaq qaçtı və oyuncağını itirdi.", "D": "Uşaq qaçtı və oyuncaqını itirdi.", "E": "Uşaq qaçdı və oyuncaxını itirdi."}'::jsonb, 'A', NULL, '«qaçdı» — Kar samitdən sonra d t kimi tələffüz olunur, d yazılır; «oyuncaq» — Sonda q yazılır. Düzgün: Uşaq qaçdı və oyuncağını itirdi.');
INSERT INTO public.questions VALUES (8710, 113, 'g11-aze-orth-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə həm k samiti y ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «fikiri», «köynəki» sözlərini misal gətirdi.", "B": "Müəllim «dirəyi», «ismi» sözlərini misal gətirdi.", "C": "Müəllim «şərqi», «ağzı» sözlərini misal gətirdi.", "D": "Müəllim «ayağı», «könlü» sözlərini misal gətirdi.", "E": "Müəllim «qarnı», «dənizi» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'dirək → dirəyi (k→y), isim → ismi (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8711, 113, 'g11-aze-orth-q3-01', 3, 1, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, «da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Qardaşım da, bacım da gəldi. Gülə-gülə danışırdı.", "B": "Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Qardaşım da, bacım da gəldi. Gülə gülə danışırdı.", "C": "Bilirəmki, sən haqlısan. Sən də bu işdə iştirak et. Qardaşım da, bacım da gəldi. Gülə-gülə danışırdı.", "D": "Bilirəm ki, sən haqlısan. Səndə bu işdə iştirak et. Qardaşım da, bacım da gəldi. Gülə-gülə danışırdı.", "E": "Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Qardaşımda, bacımda gəldi. Gülə-gülə danışırdı."}'::jsonb, 'A', NULL, 'Düzgün: Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Qardaşım da, bacım da gəldi. Gülə-gülə danışırdı. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8712, 113, 'g11-aze-orth-q3-02', 3, 2, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm. Ağsaqqal söz aldı. Sən də bu işdə iştirak et.", "B": "Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm. Ağsaqqal söz aldı. Səndə bu işdə iştirak et.", "C": "Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm. Ağ saqqal söz aldı. Sən də bu işdə iştirak et.", "D": "Qardaşımda, bacımda gəldi. Mən də sizinlə gedəcəyəm. Ağsaqqal söz aldı. Sən də bu işdə iştirak et.", "E": "Qardaşım da, bacım da gəldi. Məndə sizinlə gedəcəyəm. Ağsaqqal söz aldı. Sən də bu işdə iştirak et."}'::jsonb, 'A', NULL, 'Düzgün: Qardaşım da, bacım da gəldi. Mən də sizinlə gedəcəyəm. Ağsaqqal söz aldı. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8713, 113, 'g11-aze-orth-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də q samiti ğ ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «bıçaqı», «hüquğu» sözlərini misal gətirdi.", "B": "Müəllim «köynəyi», «şəhəri» sözlərini misal gətirdi.", "C": "Müəllim «hüququ», «ismi» sözlərini misal gətirdi.", "D": "Müəllim «tankı», «uşağı» sözlərini misal gətirdi.", "E": "Müəllim «hüququ», «fikri» sözlərini misal gətirdi."}'::jsonb, 'D', NULL, 'tank → tankı (dəyişmir), uşaq → uşağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8714, 113, 'g11-aze-orth-q3-04', 3, 4, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «heç» sözünün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə gülə danışırdı. Heç kim bu suala cavab vermədi. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et.", "B": "Gülə-gülə danışırdı. Heçkim bu suala cavab vermədi. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et.", "C": "Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Qardaşımda, bacımda gəldi. Sən də bu işdə iştirak et.", "D": "Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Qardaşım da, bacım da gəldi. Səndə bu işdə iştirak et.", "E": "Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et."}'::jsonb, 'E', NULL, 'Düzgün: Gülə-gülə danışırdı. Heç kim bu suala cavab vermədi. Qardaşım da, bacım da gəldi. Sən də bu işdə iştirak et. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8715, 113, 'g11-aze-orth-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «qəfəsi» və «burnu» sözləri işlənmişdi.", "B": "Diktantda «boyunu» və «ürəki» sözləri işlənmişdi.", "C": "Diktantda «qulağı» və «qarnı» sözləri işlənmişdi.", "D": "Diktantda «ürəyi» və «ağzı» sözləri işlənmişdi.", "E": "Diktantda «boyunu» və «ürəyi» sözləri işlənmişdi."}'::jsonb, 'D', NULL, 'ürək → ürəyi (k→y), ağız → ağzı (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8716, 113, 'g11-aze-orth-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «xalğı», «oğlu» sözlərini misal gətirdi.", "B": "Müəllim «nitqi», «şəkli» sözlərini misal gətirdi.", "C": "Müəllim «ayağı», «ismi» sözlərini misal gətirdi.", "D": "Müəllim «oğulu», «ittifağı» sözlərini misal gətirdi.", "E": "Müəllim «qulağı», «oğlu» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'nitq → nitqi (dəyişmir), şəkil → şəkli (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8717, 113, 'g11-aze-orth-q3-07', 3, 7, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («ən» ədatının, «da/də» bağlayıcısının və ya şəkilçisinin, qoşa sözün, sual ədatının (-mı, -mi) yazılışına diqqət edin)?', NULL, NULL, '{"A": "Bu, əngözəl mənzərədir. Kitab evdə qalıb. Gülə-gülə danışırdı. Onlar artıq gəldilərmi?", "B": "Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Gülə gülə danışırdı. Onlar artıq gəldilərmi?", "C": "Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Gülə-gülə danışırdı. Onlar artıq gəldilərmi?", "D": "Bu, ən gözəl mənzərədir. Kitab ev də qalıb. Gülə-gülə danışırdı. Onlar artıq gəldilərmi?", "E": "Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Gülə-gülə danışırdı. Onlar artıq gəldilər mi?"}'::jsonb, 'C', NULL, 'Düzgün: Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Gülə-gülə danışırdı. Onlar artıq gəldilərmi? «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8718, 113, 'g11-aze-orth-q3-08', 3, 8, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, «ən» ədatının, «da/də» bağlayıcısının və ya şəkilçisinin, «heç» sözünün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Gülə-gülə danışırdı. Bu, əngözəl mənzərədir. Kitab evdə qalıb. Heç nə görmədim.", "B": "Gülə gülə danışırdı. Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Heç nə görmədim.", "C": "Gülə-gülə danışırdı. Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Heç nə görmədim.", "D": "Gülə-gülə danışırdı. Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Heçnə görmədim.", "E": "Gülə-gülə danışırdı. Bu, ən gözəl mənzərədir. Kitab ev də qalıb. Heç nə görmədim."}'::jsonb, 'C', NULL, 'Düzgün: Gülə-gülə danışırdı. Bu, ən gözəl mənzərədir. Kitab evdə qalıb. Heç nə görmədim. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8719, 113, 'g11-aze-orth-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə kökləri [köynəy''] və [ayaxqabı] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Köynəyini və ayaxqabısını geyinib qonaqlığa getdi.", "B": "Köynəyini və ayaqqabısını geyinib qonaqlığa getdi.", "C": "Köynəyini və ayaqabısını geyinib qonaqlığa getdi.", "D": "Köynəkini və ayaqqabısını geyinib qonaqlığa getdi.", "E": "Köynəkini və ayaxqabısını geyinib qonaqlığa getdi."}'::jsonb, 'B', NULL, '«köynək» — Sonda k yazılır; «ayaqqabı» — qq yazılır. Düzgün: Köynəyini və ayaqqabısını geyinib qonaqlığa getdi.');
INSERT INTO public.questions VALUES (8720, 113, 'g11-aze-orth-q3-10', 3, 10, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, mürəkkəb sözün, qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Kitab ev də qalıb. Qızılgül bağçanı bəzəyirdi. Ata-ana övladını qoruyar. Yarımada dənizə uzanır.", "B": "Kitab evdə qalıb. Qızıl gül bağçanı bəzəyirdi. Ata-ana övladını qoruyar. Yarımada dənizə uzanır.", "C": "Kitab evdə qalıb. Qızılgül bağçanı bəzəyirdi. Ata-ana övladını qoruyar. Yarımada dənizə uzanır.", "D": "Kitab evdə qalıb. Qızılgül bağçanı bəzəyirdi. Ata-ana övladını qoruyar. Yarım ada dənizə uzanır.", "E": "Kitab evdə qalıb. Qızılgül bağçanı bəzəyirdi. Ataana övladını qoruyar. Yarımada dənizə uzanır."}'::jsonb, 'C', NULL, 'Düzgün: Kitab evdə qalıb. Qızılgül bağçanı bəzəyirdi. Ata-ana övladını qoruyar. Yarımada dənizə uzanır. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8721, 113, 'g11-aze-orth-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «burnu» və «hüququ» sözləri işlənmişdi.", "B": "Diktantda «ağzı» və «ürəyi» sözləri işlənmişdi.", "C": "Diktantda «fikri» və «ittifaqı» sözləri işlənmişdi.", "D": "Diktantda «hüququ» və «çiçəyi» sözləri işlənmişdi.", "E": "Diktantda «fikri» və «fərqi» sözləri işlənmişdi."}'::jsonb, 'B', NULL, 'ağız → ağzı (sait düşümü), ürək → ürəyi (k→y). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8722, 113, 'g11-aze-orth-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaxlıq süfrəsinə isti çörək qoyuldu.", "B": "Qonaqlıq süfrəsinə isti çörəq qoyuldu.", "C": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "D": "Qonaqlığ süfrəsinə isti çörək qoyuldu.", "E": "Qonaxlıx süfrəsinə isti çörək qoyuldu."}'::jsonb, 'C', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8723, 113, 'g11-aze-orth-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «fikri» və «ittifaqı» sözlərini lövhəyə yazdı.", "B": "Şagird «köynəki» və «şərği» sözlərini lövhəyə yazdı.", "C": "Şagird «bankı» və «burnu» sözlərini lövhəyə yazdı.", "D": "Şagird «köynəki» və «şərqi» sözlərini lövhəyə yazdı.", "E": "Şagird «köynəyi» və «şərqi» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'köynək → köynəyi (k→y), şərq → şərqi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8724, 113, 'g11-aze-orth-q3-14', 3, 14, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, mürəkkəb sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Kitab evdə qalıb. Bilirəmki, sən haqlısan. Sən də bu işdə iştirak et. Günəbaxan günəşə tərəf dönür.", "B": "Kitab evdə qalıb. Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Günə baxan günəşə tərəf dönür.", "C": "Kitab ev də qalıb. Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Günəbaxan günəşə tərəf dönür.", "D": "Kitab evdə qalıb. Bilirəm ki, sən haqlısan. Səndə bu işdə iştirak et. Günəbaxan günəşə tərəf dönür.", "E": "Kitab evdə qalıb. Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Günəbaxan günəşə tərəf dönür."}'::jsonb, 'E', NULL, 'Düzgün: Kitab evdə qalıb. Bilirəm ki, sən haqlısan. Sən də bu işdə iştirak et. Günəbaxan günəşə tərəf dönür. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8725, 113, 'g11-aze-orth-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə kökləri [qonaxlıx] və [çörəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Qonaqlıq süfrəsinə isti çörəq qoyuldu.", "B": "Qonaqlıq süfrəsinə isti çörək qoyuldu.", "C": "Qonaxlıx süfrəsinə isti çörək qoyuldu.", "D": "Qonaqlığ süfrəsinə isti çörək qoyuldu.", "E": "Qonaqlıx süfrəsinə isti çörək qoyuldu."}'::jsonb, 'B', NULL, '«qonaqlıq» — q yazılır; «çörək» — Çoxhecalı sözün sonundakı k y'' kimi tələffüz olunur, k yazılır. Düzgün: Qonaqlıq süfrəsinə isti çörək qoyuldu.');
INSERT INTO public.questions VALUES (8726, 113, 'g11-aze-orth-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə kökləri [yarpaxlar] və [kəpənəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Küləkdən yarpaqlar kəpənəq kimi uçuşurdu.", "B": "Küləkdən yarpaqlar kəpənəy kimi uçuşurdu.", "C": "Küləkdən yarpaqlar kəpənək kimi uçuşurdu.", "D": "Küləkdən yarpaxlar kəpənəq kimi uçuşurdu.", "E": "Küləkdən yarpaxlar kəpənək kimi uçuşurdu."}'::jsonb, 'C', NULL, '«yarpaqlar» — q yazılır; «kəpənək» — Sonda k yazılır. Düzgün: Küləkdən yarpaqlar kəpənək kimi uçuşurdu.');
INSERT INTO public.questions VALUES (8727, 113, 'g11-aze-orth-q3-17', 3, 17, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («heç» sözünün, mürəkkəb sözün, sual ədatının (-mı, -mi) yazılışına diqqət edin)?', NULL, NULL, '{"A": "Heç kim bu suala cavab vermədi. Ağsaqqal söz aldı. Qızılgül bağçanı bəzəyirdi. Onlar artıq gəldilər mi?", "B": "Heç kim bu suala cavab vermədi. Ağsaqqal söz aldı. Qızılgül bağçanı bəzəyirdi. Onlar artıq gəldilərmi?", "C": "Heçkim bu suala cavab vermədi. Ağsaqqal söz aldı. Qızılgül bağçanı bəzəyirdi. Onlar artıq gəldilərmi?", "D": "Heç kim bu suala cavab vermədi. Ağsaqqal söz aldı. Qızıl gül bağçanı bəzəyirdi. Onlar artıq gəldilərmi?", "E": "Heç kim bu suala cavab vermədi. Ağ saqqal söz aldı. Qızılgül bağçanı bəzəyirdi. Onlar artıq gəldilərmi?"}'::jsonb, 'B', NULL, 'Düzgün: Heç kim bu suala cavab vermədi. Ağsaqqal söz aldı. Qızılgül bağçanı bəzəyirdi. Onlar artıq gəldilərmi? «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8728, 113, 'g11-aze-orth-q3-18', 3, 18, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (qoşa sözün, mürəkkəb sözün, «da/də» bağlayıcısının və ya şəkilçisinin yazılışına diqqət edin)?', NULL, NULL, '{"A": "Yavaş-yavaş irəlilədik. Günə baxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi.", "B": "Yavaş-yavaş irəlilədik. Günəbaxan günəşə tərəf dönür. Qızıl gül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi.", "C": "Yavaş yavaş irəlilədik. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi.", "D": "Yavaş-yavaş irəlilədik. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi. Qardaşımda, bacımda gəldi.", "E": "Yavaş-yavaş irəlilədik. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi."}'::jsonb, 'E', NULL, 'Düzgün: Yavaş-yavaş irəlilədik. Günəbaxan günəşə tərəf dönür. Qızılgül bağçanı bəzəyirdi. Qardaşım da, bacım da gəldi. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8729, 113, 'g11-aze-orth-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə kökləri [qılınç] və [bayrax] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Əsgər qılıncı qınından çıxarıb bayrağı öpdü.", "B": "Əsgər qılıncı qınından çıxarıb bayraxı öpdü.", "C": "Əsgər qılınçı qınından çıxarıb bayraxı öpdü.", "D": "Əsgər qılınçı qınından çıxarıb bayrağı öpdü.", "E": "Əsgər qılıncı qınından çıxarıb bayraqı öpdü."}'::jsonb, 'A', NULL, '«qılınc» — Sonda c yazılır; «bayraq» — Sonda q yazılır. Düzgün: Əsgər qılıncı qınından çıxarıb bayrağı öpdü.');
INSERT INTO public.questions VALUES (8730, 113, 'g11-aze-orth-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Diktantda «bıçağı» və «alnı» sözləri işlənmişdi.", "B": "Diktantda «bankı» və «qulağı» sözləri işlənmişdi.", "C": "Diktantda «oğlu» və «bıçağı» sözləri işlənmişdi.", "D": "Diktantda «ömrü» və «qulağı» sözləri işlənmişdi.", "E": "Diktantda «oğlu» və «uşağı» sözləri işlənmişdi."}'::jsonb, 'B', NULL, 'bank → bankı (dəyişmir), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8731, 113, 'g11-aze-orth-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə kökləri [axsaxqal] və [çərşəmbə] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Axsaxqal çərşənbə günü gəlməyi vəd etdi.", "B": "Ağsaqqal çərşənbə günü gəlməyi vəd etdi.", "C": "Ağsaqqal çərşəmbə günü gəlməyi vəd etdi.", "D": "Ağsaqal çərşənbə günü gəlməyi vəd etdi.", "E": "Ağsaxqal çərşənbə günü gəlməyi vəd etdi."}'::jsonb, 'B', NULL, '«ağsaqqal» — ğ kar samitdən əvvəl x kimi tələffüz olunur; ğ və qq yazılır; «çərşənbə» — n yazılır. Düzgün: Ağsaqqal çərşənbə günü gəlməyi vəd etdi.');
INSERT INTO public.questions VALUES (8732, 113, 'g11-aze-orth-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «uşağı», «fərqi» sözlərini misal gətirdi.", "B": "Müəllim «tanğı», «yarpağı» sözlərini misal gətirdi.", "C": "Müəllim «tanğı», «yarpaqı» sözlərini misal gətirdi.", "D": "Müəllim «tankı», «yarpaqı» sözlərini misal gətirdi.", "E": "Müəllim «ağzı», «ayağı» sözlərini misal gətirdi."}'::jsonb, 'A', NULL, 'uşaq → uşağı (q→ğ), fərq → fərqi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8733, 113, 'g11-aze-orth-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə həm kökündə sait düşən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «ağzı» və «bankı» sözlərini lövhəyə yazdı.", "B": "Şagird «dirəki» və «ismi» sözlərini lövhəyə yazdı.", "C": "Şagird «dirəyi» və «isimi» sözlərini lövhəyə yazdı.", "D": "Şagird «dirəyi» və «ismi» sözlərini lövhəyə yazdı.", "E": "Şagird «qarnı» və «şəhəri» sözlərini lövhəyə yazdı."}'::jsonb, 'D', NULL, 'dirək → dirəyi (k→y), isim → ismi (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8734, 113, 'g11-aze-orth-q3-24', 3, 24, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb («da/də» bağlayıcısının və ya şəkilçisinin, «ki» bağlayıcısının və ya -kı/-ki şəkilçisinin, sual ədatının (-mı, -mi), qoşa sözün yazılışına diqqət edin)?', NULL, NULL, '{"A": "Kitab evdə qalıb. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir.", "B": "Kitab evdə qalıb. Dediki, sabah gələcək. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir.", "C": "Kitab evdə qalıb. Dedi ki, sabah gələcək. Sən bu kitabı oxudun mu? Ara-sıra bizə baş çəkir.", "D": "Kitab evdə qalıb. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu? Arasıra bizə baş çəkir.", "E": "Kitab ev də qalıb. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir."}'::jsonb, 'A', NULL, 'Düzgün: Kitab evdə qalıb. Dedi ki, sabah gələcək. Sən bu kitabı oxudunmu? Ara-sıra bizə baş çəkir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8735, 113, 'g11-aze-orth-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə kökləri [ürəy''] və [məxtup] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Ürəyinin sözlərini məxtupda yazan şair dərin fikrə daldı.", "B": "Ürəyinin sözlərini məktupda yazan şair dərin fikrə daldı.", "C": "Ürəyinin sözlərini məktubda yazan şair dərin fikrə daldı.", "D": "Ürəkinin sözlərini məktubda yazan şair dərin fikrə daldı.", "E": "Ürəyinin sözlərini məxtubda yazan şair dərin fikrə daldı."}'::jsonb, 'C', NULL, '«ürək» — Sonda k yazılır; «məktub» — k samitdən əvvəl x kimi, sondakı b isə p kimi tələffüz olunur. Düzgün: Ürəyinin sözlərini məktubda yazan şair dərin fikrə daldı.');
INSERT INTO public.questions VALUES (8736, 113, 'g11-aze-orth-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökündə sait düşən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «qulağı» və «oğlu» sözlərini lövhəyə yazdı.", "B": "Şagird «parkı» və «şəkli» sözlərini lövhəyə yazdı.", "C": "Şagird «qulaqı» və «oğlu» sözlərini lövhəyə yazdı.", "D": "Şagird «çörəyi» və «yarpağı» sözlərini lövhəyə yazdı.", "E": "Şagird «uşağı» və «çiçəyi» sözlərini lövhəyə yazdı."}'::jsonb, 'A', NULL, 'qulaq → qulağı (q→ğ), oğul → oğlu (sait düşümü). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8737, 113, 'g11-aze-orth-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə kökləri [yarpaxlar] və [kəpənəy''] kimi tələffüz olunan sözlərin hər ikisi orfoqrafiya qaydalarına uyğun yazılıb?', NULL, NULL, '{"A": "Küləkdən yarpaqlar kəpənək kimi uçuşurdu.", "B": "Küləkdən yarpaxlar kəpənək kimi uçuşurdu.", "C": "Küləkdən yarpaxlar kəpənəy kimi uçuşurdu.", "D": "Küləkdən yarpaqlar kəpənəy kimi uçuşurdu.", "E": "Küləkdən yarpaqlar kəpənəq kimi uçuşurdu."}'::jsonb, 'A', NULL, '«yarpaqlar» — q yazılır; «kəpənək» — Sonda k yazılır. Düzgün: Küləkdən yarpaqlar kəpənək kimi uçuşurdu.');
INSERT INTO public.questions VALUES (8738, 113, 'g11-aze-orth-q3-28', 3, 28, 'hard', 'single', 'Hansı variantda bütün sözlər düzgün yazılıb (mürəkkəb sözün, qoşa sözün, «da/də» bağlayıcısının və ya şəkilçisinin, «ən» ədatının yazılışına diqqət edin)?', NULL, NULL, '{"A": "Qızılgül bağçanı bəzəyirdi. Ara-sıra bizə baş çəkir. Mən də sizinlə gedəcəyəm. Bu, əngözəl mənzərədir.", "B": "Qızılgül bağçanı bəzəyirdi. Arasıra bizə baş çəkir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "C": "Qızılgül bağçanı bəzəyirdi. Ara-sıra bizə baş çəkir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "D": "Qızıl gül bağçanı bəzəyirdi. Ara-sıra bizə baş çəkir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir.", "E": "Qızılgül bağçanı bəzəyirdi. Ara-sıra bizə baş çəkir. Məndə sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir."}'::jsonb, 'C', NULL, 'Düzgün: Qızılgül bağçanı bəzəyirdi. Ara-sıra bizə baş çəkir. Mən də sizinlə gedəcəyəm. Bu, ən gözəl mənzərədir. «da/də» bağlayıcısı, «ki» bağlayıcısı, «ən», «heç kim» ayrı; -mı ədatı, -dakı/-dəki, mürəkkəb sözlər bitişik; qoşa sözlər defislə yazılır.');
INSERT INTO public.questions VALUES (8739, 113, 'g11-aze-orth-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə həm q samiti ğ ilə əvəzlənən, həm də kökü dəyişməyən söz düzgün yazılıb?', NULL, NULL, '{"A": "Şagird «bıçağı» və «qəfsi» sözlərini lövhəyə yazdı.", "B": "Şagird «şərği» və «qulaqı» sözlərini lövhəyə yazdı.", "C": "Şagird «qulağı» və «parğı» sözlərini lövhəyə yazdı.", "D": "Şagird «tanğı» və «qulağı» sözlərini lövhəyə yazdı.", "E": "Şagird «tankı» və «qulağı» sözlərini lövhəyə yazdı."}'::jsonb, 'E', NULL, 'tank → tankı (dəyişmir), qulaq → qulağı (q→ğ). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8740, 113, 'g11-aze-orth-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə həm kökü dəyişməyən, həm də k samiti y ilə əvəzlənən söz düzgün yazılıb?', NULL, NULL, '{"A": "Müəllim «qulağı», «inəyi» sözlərini misal gətirdi.", "B": "Müəllim «çörəyi», «qəfəsi» sözlərini misal gətirdi.", "C": "Müəllim «çörəyi», «qəfsi» sözlərini misal gətirdi.", "D": "Müəllim «fikri», «şəhəri» sözlərini misal gətirdi.", "E": "Müəllim «ağzı», «şəhəri» sözlərini misal gətirdi."}'::jsonb, 'B', NULL, 'çörək → çörəyi (k→y), qəfəs → qəfəsi (dəyişmir). Çoxhecalı sözlərdə k/q saitlə başlayan şəkilçidən əvvəl y/ğ olur, alınma və birhecalı sözlər (tank, hüquq, xalq) istisnadır; ağız, burun, oğul, sinif kimi sözlərdə ikinci hecanın saiti düşür.');
INSERT INTO public.questions VALUES (8741, 114, 'g11-aze-syn-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə antonimlər sifətlə ifadə olunub, antonim işlənib və sinonim işlənməyib?', NULL, NULL, '{"A": "Səhərin sərinliyi axşamın bürküsünü unutdurdu.", "B": "Uşaq kitabı ehtiyatla rəfə qoydu və otaqdan çıxdı.", "C": "Ocağın yanında oturan qoca qəfildən ayağa qalxdı: «Ehtiyatlı ol, yanarsan!»", "D": "Qələbəni qazanmaq çətin, itirmək isə çox asan oldu.", "E": "Gülümsəyən qız əlindəki gülü müəlliminə uzatdı."}'::jsonb, 'D', NULL, 'Cümlədə: qazanmaq – itirmək (antonim); çətin – asan (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8742, 114, 'g11-aze-syn-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib, antonim işlənməyib və omonimlər müxtəlif nitq hissələrinə aiddir?', NULL, NULL, '{"A": "Dağ başını duman aldı, dərələri isə qalın kölgə bürüdü.", "B": "İmtahandan yüksək bal alan tələbə bal arılarından bəhs edən məqalə yazdı.", "C": "Ocağın yanında oturan qoca qəfildən ayağa qalxdı: «Ehtiyatlı ol, yanarsan!»", "D": "Qolundan yaralanan hücumçu yenə də qol vurmağa can atırdı.", "E": "Uşaq kitabı ehtiyatla rəfə qoydu və otaqdan çıxdı."}'::jsonb, 'C', NULL, 'Cümlədə: yan – yan (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8743, 114, 'g11-aze-syn-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə omonim işlənməyib, antonim işlənməyib və sinonim işlənib?', NULL, NULL, '{"A": "Sülh, barış arzusu xalqları birləşdirir, müharibə isə ayırır.", "B": "Uşaq kitabı ehtiyatla rəfə qoydu və otaqdan çıxdı.", "C": "Hirsini, qəzəbini boğmağı bacaran insan hamının hörmətini qazanır.", "D": "Dağ başını duman aldı, dərələri isə qalın kölgə bürüdü.", "E": "Gülümsəyən qız əlindəki gülü müəlliminə uzatdı."}'::jsonb, 'C', NULL, 'Cümlədə: hirs – qəzəb (sinonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8744, 114, 'g11-aze-syn-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə antonim işlənməyib, omonimlər müxtəlif nitq hissələrinə aiddir və sinonim işlənməyib?', NULL, NULL, '{"A": "Dağ başını duman aldı, dərələri isə qalın kölgə bürüdü.", "B": "Çay qırağında dincələn səyyahlar dəmlənmiş çayın ətrini duydular.", "C": "Gülümsəyən qız əlindəki gülü müəlliminə uzatdı.", "D": "Atı yəhərləyən çoban kəndiri uzağa at deyə oğluna səsləndi.", "E": "Uşaq kitabı ehtiyatla rəfə qoydu və otaqdan çıxdı."}'::jsonb, 'D', NULL, 'Cümlədə: at – at (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8745, 114, 'g11-aze-syn-q1-05', 1, 5, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir və feillə ifadə olunub?', NULL, NULL, '{"A": "Qorxaq döyüşçü çətin anda geri çəkildi, cəsur döyüşçü isə irəli atıldı. (geri – irəli: antonim)", "B": "Qorxaq döyüşçü çətin anda geri çəkildi, cəsur döyüşçü isə irəli atıldı. (qorxaq – cəsur: antonim)", "C": "Səhərin sərinliyi axşamın bürküsünü unutdurdu. (səhər – axşam: antonim)", "D": "Qələbəni qazanmaq çətin, itirmək isə çox asan oldu. (qazanmaq – itirmək: antonim)", "E": "Uzaq kəndlərdən gələn qonaqlar yaxın qohumlarımızın evində qaldılar. (uzaq – yaxın: antonim)"}'::jsonb, 'D', NULL, '«qazanmaq» və «itirmək» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (8746, 114, 'g11-aze-syn-q1-06', 1, 6, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir və isimlə ifadə olunub?', NULL, NULL, '{"A": "Sülh, barış arzusu xalqları birləşdirir, müharibə isə ayırır. (sülh – müharibə: antonim)", "B": "Ocağın yanında oturan qoca qəfildən ayağa qalxdı: «Ehtiyatlı ol, yanarsan!» (yan – yan: omonim)", "C": "Hirsini, qəzəbini boğmağı bacaran insan hamının hörmətini qazanır. (hirs – qəzəb: sinonim)", "D": "İmtahandan yüksək bal alan tələbə bal arılarından bəhs edən məqalə yazdı. (bal – bal: omonim)", "E": "Yaz gələndə nənəm deyərdi: «Bu sevinci dəftərinə yaz». (yaz – yaz: sinonim)"}'::jsonb, 'C', NULL, '«hirs» və «qəzəb» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (8747, 114, 'g11-aze-syn-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib, antonimlər feillə ifadə olunub və antonim işlənib?', NULL, NULL, '{"A": "Uzaq kəndlərdən gələn qonaqlar yaxın qohumlarımızın evində qaldılar.", "B": "Böyük qardaş kiçik bacısına həmişə qayğı göstərirdi.", "C": "Qələbəni qazanmaq çətin, itirmək isə çox asan oldu.", "D": "Dərin fikrə dalan alim dayaz mülahizələri dərhal rədd edirdi.", "E": "Ahıl müəllim cavan tələbələrinə gənclik illərindən danışırdı."}'::jsonb, 'C', NULL, 'Cümlədə: qazanmaq – itirmək (antonim); çətin – asan (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8748, 114, 'g11-aze-syn-q1-08', 1, 8, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir və sifətlə ifadə olunub?', NULL, NULL, '{"A": "Təmiz niyyətlə başlanan iş çirkli hiylələrə uduzmaz. (təmiz – çirkli: sinonim)", "B": "Dərin fikrə dalan alim dayaz mülahizələri dərhal rədd edirdi. (dərin – dayaz: sinonim)", "C": "Böyük qardaş kiçik bacısına həmişə qayğı göstərirdi. (böyük – kiçik: sinonim)", "D": "Uzaq kəndlərdən gələn qonaqlar yaxın qohumlarımızın evində qaldılar. (uzaq – yaxın: sinonim)", "E": "Kəndin sakit, dinc həyatı şəhərin səs-küyündən çox fərqlənirdi. (sakit – dinc: sinonim)"}'::jsonb, 'E', NULL, '«sakit» və «dinc» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (8749, 114, 'g11-aze-syn-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə sinonim işlənməyib, omonimlər müxtəlif nitq hissələrinə aiddir və omonim işlənib?', NULL, NULL, '{"A": "Səhərin sərinliyi axşamın bürküsünü unutdurdu.", "B": "Qolundan yaralanan hücumçu yenə də qol vurmağa can atırdı.", "C": "Çay qırağında dincələn səyyahlar dəmlənmiş çayın ətrini duydular.", "D": "İmtahandan yüksək bal alan tələbə bal arılarından bəhs edən məqalə yazdı.", "E": "Atı yəhərləyən çoban kəndiri uzağa at deyə oğluna səsləndi."}'::jsonb, 'E', NULL, 'Cümlədə: at – at (omonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (8750, 114, 'g11-aze-syn-q1-10', 1, 10, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt sinonimdir və sifətlə ifadə olunub?', NULL, NULL, '{"A": "Böyük qardaş kiçik bacısına həmişə qayğı göstərirdi. (böyük – kiçik: antonim)", "B": "Vəfalı dost sədaqətli olduğu kimi, xain də satqın olur. (vəfalı – sədaqətli: sinonim)", "C": "Uzaq kəndlərdən gələn qonaqlar yaxın qohumlarımızın evində qaldılar. (uzaq – yaxın: antonim)", "D": "Ahıl müəllim cavan tələbələrinə gənclik illərindən danışırdı. (ahıl – cavan: sinonim)", "E": "Təmiz niyyətlə başlanan iş çirkli hiylələrə uduzmaz. (təmiz – çirkli: sinonim)"}'::jsonb, 'B', NULL, '«vəfalı» və «sədaqətli» — sinonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (8751, 114, 'g11-aze-syn-q1-11', 1, 11, 'hard', 'single', 'Hansı variantda cümlədəki leksik cüt və onun növü düzgün göstərilib, həm də bu cüt antonimdir və feillə ifadə olunub?', NULL, NULL, '{"A": "Qələbəni qazanmaq çətin, itirmək isə çox asan oldu. (qazanmaq – itirmək: antonim)", "B": "Böyük qardaş kiçik bacısına həmişə qayğı göstərirdi. (böyük – kiçik: antonim)", "C": "Təmiz niyyətlə başlanan iş çirkli hiylələrə uduzmaz. (təmiz – çirkli: antonim)", "D": "Qorxaq döyüşçü çətin anda geri çəkildi, cəsur döyüşçü isə irəli atıldı. (geri – irəli: antonim)", "E": "Şirin xatirələr acı həqiqətlərin yanında daha qiymətli görünürdü. (şirin – acı: antonim)"}'::jsonb, 'A', NULL, '«qazanmaq» və «itirmək» — antonim. Digər variantlarda ya cütün növü səhv göstərilib, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (8752, 114, 'g11-aze-syn-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə antonim işlənib, omonim işlənməyib, sinonim işlənməyib və antonimlər sifətlə ifadə olunub?', NULL, NULL, '{"A": "Sülh, barış arzusu xalqları birləşdirir, müharibə isə ayırır.", "B": "Gülümsəyən qız əlindəki gülü müəlliminə uzatdı.", "C": "Dərin fikrə dalan alim dayaz mülahizələri dərhal rədd edirdi.", "D": "Dağ başını duman aldı, dərələri isə qalın kölgə bürüdü.", "E": "Səhərin sərinliyi axşamın bürküsünü unutdurdu."}'::jsonb, 'C', NULL, 'Cümlədə: dərin – dayaz (antonim). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
