INSERT INTO public.questions VALUES (9088, 117, 'g11-aze-sifet-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə sifət təyin vəzifəsində işlənib, sifət mübtədanı izah edir, feili sifət var və məsdər yoxdur?', NULL, NULL, '{"A": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "B": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'D', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «uzun» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9089, 117, 'g11-aze-sifet-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə 1 sifət işlənib, sifət təyin vəzifəsində işlənib, qoşma yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "C": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "D": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "E": "Ura, uzun illər gözlədiyimiz qələbə gəldi!"}'::jsonb, 'E', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «uzun» — sifət, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
