INSERT INTO public.questions VALUES (9107, 118, 'g11-aze-say-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə 1 say işlənib, sıra sayı var, xəbər feillə ifadə olunub və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir."}'::jsonb, 'E', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «Beşinci» — sıra sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9108, 118, 'g11-aze-say-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə sıra sayı var, kəsr sayı yoxdur, bağlayıcı yoxdur və say var?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "C": "Bu işi üç nəfər bir həftəyə gördü.", "D": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "E": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'B', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «Beşinci» — sıra sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9109, 118, 'g11-aze-say-q1-09', 1, 9, 'hard', 'single', '«Bu işi üç nəfər bir həftəyə gördü.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "say — 2; isim — 3; əvəzlik — 1", "B": "say — 2; isim — 2; əvəzlik — 1", "C": "say — 3; isim — 2; əvəzlik — 1", "D": "say — 2; isim — 4; əvəzlik — 0", "E": "say — 2; isim — 5; əvəzlik — 1"}'::jsonb, 'A', NULL, '«Bu işi üç nəfər bir həftəyə gördü.»: «üç» — miqdar sayı, təyin; «bir» — miqdar sayı, təyin. Düzgün: say — 2; isim — 3; əvəzlik — 1.');
INSERT INTO public.questions VALUES (9110, 118, 'g11-aze-say-q1-10', 1, 10, 'hard', 'single', '«Kitabın üçüncü fəslini iki-üç dəfə oxudum.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "say — 3; isim — 2; əvəzlik — 0", "B": "say — 4; isim — 3; əvəzlik — 0", "C": "say — 2; isim — 5; əvəzlik — 0", "D": "say — 2; isim — 3; əvəzlik — 1", "E": "say — 2; isim — 3; əvəzlik — 0"}'::jsonb, 'E', NULL, '«Kitabın üçüncü fəslini iki-üç dəfə oxudum.»: «üçüncü» — sıra sayı, təyin; «iki-üç» — təxmini say, təyin. Düzgün: say — 2; isim — 3; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9111, 118, 'g11-aze-say-q1-11', 1, 11, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "say — 1; isim — 4; əvəzlik — 0", "B": "say — 1; isim — 4; əvəzlik — 1", "C": "say — 1; isim — 3; əvəzlik — 0", "D": "say — 0; isim — 4; əvəzlik — 0", "E": "say — 1; isim — 5; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «Beşinci» — sıra sayı, təyin. Düzgün: say — 1; isim — 4; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9112, 118, 'g11-aze-say-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə 1 say işlənib, təxmini say yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "B": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "C": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "D": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'C', NULL, '«Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.»: «iyirmi yeddi» — miqdar sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9113, 118, 'g11-aze-say-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə 2 say işlənib, miqdar sayı var və müraciət yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "D": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "E": "Kitabın üçüncü fəslini iki-üç dəfə oxudum."}'::jsonb, 'A', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «iki» — miqdar sayı, təyin; «on iki» — miqdar sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9114, 118, 'g11-aze-say-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə say təyin vəzifəsində işlənib, miqdar sayı yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "E": "Nə atam, nə də anam bu xəbəri eşitmişdi."}'::jsonb, 'A', NULL, '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.»: «beşdə dörd» — kəsr sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9115, 118, 'g11-aze-say-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə 2 say işlənib, say təyin vəzifəsində işlənib, vasitəsiz tamamlıq yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "B": "Bu işi üç nəfər bir həftəyə gördü.", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "E": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'E', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «iki» — miqdar sayı, təyin; «on iki» — miqdar sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9116, 118, 'g11-aze-say-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə say mübtəda vəzifəsində işlənib, sıra sayı yoxdur, zərf yoxdur və modal söz var?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "D": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "E": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'B', NULL, '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.»: «üçdə biri» — kəsr sayı, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9117, 118, 'g11-aze-say-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə sıra sayı var, miqdar sayı yoxdur, feili sifət yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Əhsən, bu çətin yarışda hamını qabaqladın!", "E": "Kitabın üçüncü fəslini iki-üç dəfə oxudum."}'::jsonb, 'E', NULL, '«Kitabın üçüncü fəslini iki-üç dəfə oxudum.»: «üçüncü» — sıra sayı, təyin; «iki-üç» — təxmini say, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
