INSERT INTO public.questions VALUES (9151, 118, 'g11-aze-say-q2-21', 2, 21, 'hard', 'single', '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "say — 1; isim — 2; əvəzlik — 0", "B": "say — 1; isim — 2; əvəzlik — 1", "C": "say — 1; isim — 2; əvəzlik — 2", "D": "say — 3; isim — 2; əvəzlik — 0", "E": "say — 1; isim — 1; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.»: «üçdə biri» — kəsr sayı, mübtəda. Düzgün: say — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9152, 118, 'g11-aze-say-q2-22', 2, 22, 'hard', 'single', '«Bu işi üç nəfər bir həftəyə gördü.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "say — 2; isim — 3; əvəzlik — 0", "B": "say — 2; isim — 3; əvəzlik — 1", "C": "say — 2; isim — 4; əvəzlik — 0", "D": "say — 4; isim — 3; əvəzlik — 1", "E": "say — 2; isim — 3; əvəzlik — 2"}'::jsonb, 'B', NULL, '«Bu işi üç nəfər bir həftəyə gördü.»: «üç» — miqdar sayı, təyin; «bir» — miqdar sayı, təyin. Düzgün: say — 2; isim — 3; əvəzlik — 1.');
INSERT INTO public.questions VALUES (9153, 118, 'g11-aze-say-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə say təyin vəzifəsində işlənib, miqdar sayı yoxdur, təyin var və sifət yoxdur?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "E": "Kimin əlyazmasını muzeyə verdiniz?"}'::jsonb, 'A', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «Beşinci» — sıra sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9154, 118, 'g11-aze-say-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə sıra sayı var, say təyin vəzifəsində işlənib və zərf yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Bu işi üç nəfər bir həftəyə gördü."}'::jsonb, 'D', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «birinci» — sıra sayı, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9155, 118, 'g11-aze-say-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə sıra sayı var, kəsr sayı yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Bəlkə, biz son qatara çatmayacağıq.", "B": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "C": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "D": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "E": "Babam təkbaşına dağa çıxmağı sevirdi."}'::jsonb, 'D', NULL, '«Kitabın üçüncü fəslini iki-üç dəfə oxudum.»: «üçüncü» — sıra sayı, təyin; «iki-üç» — təxmini say, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
