INSERT INTO public.questions VALUES (9192, 119, 'g11-aze-evez-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə işarə əvəzliyi var, sual əvəzliyi yoxdur və zərflik yoxdur?', NULL, NULL, '{"A": "Alim bu problemi təkbaşına araşdırdı.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Axı siz bu kitabı oxumamısınız.", "D": "Babam təkbaşına dağa çıxmağı sevirdi.", "E": "Məhz bu hadisədən sonra onun həyatı dəyişdi."}'::jsonb, 'C', NULL, '«Axı siz bu kitabı oxumamısınız.»: «siz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9193, 119, 'g11-aze-evez-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə işarə əvəzliyi var, sual əvəzliyi yoxdur, modal söz yoxdur və qoşma var?', NULL, NULL, '{"A": "Karvan dənizə sarı irəliləyirdi.", "B": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'E', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9194, 119, 'g11-aze-evez-q1-04', 1, 4, 'hard', 'single', '«Axı siz bu kitabı oxumamısınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 3", "C": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'A', NULL, '«Axı siz bu kitabı oxumamısınız.»: «siz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9195, 119, 'g11-aze-evez-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, əvəzlik vasitəsiz tamamlıq vəzifəsində işlənib, nida var və say yoxdur?', NULL, NULL, '{"A": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "B": "Əhsən, bu çətin yarışda hamını qabaqladın!", "C": "Ah, gəncliyimdə bu imkanlar olsaydı!", "D": "Mən səni öz qardaşım kimi sevirəm.", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'B', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «bu» — işarə əvəzliyi, təyin; «hamını» — təyini əvəzlik, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9196, 119, 'g11-aze-evez-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, qayıdış əvəzliyi yoxdur və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "B": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "C": "Bəlkə, biz son qatara çatmayacağıq.", "D": "Biz qatarı stansiyada xeyli gözlədik.", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'C', NULL, '«Bəlkə, biz son qatara çatmayacağıq.»: «biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9197, 119, 'g11-aze-evez-q1-07', 1, 7, 'hard', 'single', '«Biz qatarı stansiyada xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3"}'::jsonb, 'A', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9198, 119, 'g11-aze-evez-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, şəxs əvəzliyi var və mübtəda var?', NULL, NULL, '{"A": "Of, bu bitib-tükənməyən yol məni yordu!", "B": "Bəs siz hansı universitetə sənəd vermisiniz?", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "E": "Məncə, bu məsələni yalnız siz bizə anladarsınız."}'::jsonb, 'C', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «Siz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9199, 119, 'g11-aze-evez-q1-09', 1, 9, 'hard', 'single', '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'E', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «hamı» — təyini əvəzlik, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9200, 119, 'g11-aze-evez-q1-10', 1, 10, 'hard', 'single', '«Axı siz bu kitabı oxumamısınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 3", "B": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 4; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Axı siz bu kitabı oxumamısınız.»: «siz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9201, 119, 'g11-aze-evez-q1-11', 1, 11, 'hard', 'single', '«Axı siz bu kitabı oxumamısınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "B": "əvəzlik — 4; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 3", "E": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Axı siz bu kitabı oxumamısınız.»: «siz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9202, 119, 'g11-aze-evez-q1-12', 1, 12, 'hard', 'single', '«Bəlkə, biz son qatara çatmayacağıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 0; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 2", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1", "E": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'D', NULL, '«Bəlkə, biz son qatara çatmayacağıq.»: «biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9203, 119, 'g11-aze-evez-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, qayıdış əvəzliyi yoxdur və mübtəda var?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "C": "Hər kəs öz fikrini yazsın.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Bəlkə, biz son qatara çatmayacağıq."}'::jsonb, 'B', NULL, '«Nə atam, nə də anam bu xəbəri eşitmişdi.»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9204, 119, 'g11-aze-evez-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə şəxs əvəzliyi var, inkar əvəzliyi yoxdur, qoşma yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Babam təkbaşına dağa çıxmağı sevirdi.", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "E": "Bəlkə, biz son qatara çatmayacağıq."}'::jsonb, 'E', NULL, '«Bəlkə, biz son qatara çatmayacağıq.»: «biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9205, 119, 'g11-aze-evez-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə işarə əvəzliyi var, qeyri-müəyyən əvəzlik yoxdur və modal söz var?', NULL, NULL, '{"A": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "B": "Alim bu problemi təkbaşına araşdırdı.", "C": "Bu işi üç nəfər bir həftəyə gördü.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Nə atam, nə də anam bu xəbəri eşitmişdi."}'::jsonb, 'D', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «bu» — işarə əvəzliyi, təyin; «siz» — şəxs əvəzliyi, mübtəda; «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9206, 119, 'g11-aze-evez-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə şəxs əvəzliyi var, işarə əvəzliyi yoxdur, modal söz yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "B": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Hər kəs öz fikrini yazsın.", "D": "Biz qatarı stansiyada xeyli gözlədik.", "E": "Ay bala, kitablarını rəfə yığ."}'::jsonb, 'D', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9207, 119, 'g11-aze-evez-q1-17', 1, 17, 'hard', 'single', '«Biz qatarı stansiyada xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2", "C": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'D', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9208, 119, 'g11-aze-evez-q1-18', 1, 18, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 4; isim — 1; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'B', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «bu» — işarə əvəzliyi, təyin; «məni» — şəxs əvəzliyi, təsirlik hal, vasitəsiz tamamlıq. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9209, 119, 'g11-aze-evez-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, işarə əvəzliyi var, vasitəli tamamlıq yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "B": "Afərin, sən yarışda birinci yeri tutdun!", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'D', NULL, '«Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9210, 119, 'g11-aze-evez-q1-20', 1, 20, 'hard', 'single', '«Axı siz bu kitabı oxumamısınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 3", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 4; isim — 1; şəxs əvəzliyi — 1", "E": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 0"}'::jsonb, 'A', NULL, '«Axı siz bu kitabı oxumamısınız.»: «siz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9211, 119, 'g11-aze-evez-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, işarə əvəzliyi yoxdur, təyin var və feili bağlama yoxdur?', NULL, NULL, '{"A": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "D": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'B', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin; «heç kim» — inkar əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9212, 119, 'g11-aze-evez-q1-22', 1, 22, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 2", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin; «heç kim» — inkar əvəzliyi, mübtəda. Düzgün: əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9213, 119, 'g11-aze-evez-q1-23', 1, 23, 'hard', 'single', '«Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2"}'::jsonb, 'A', NULL, '«Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.»: «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9214, 119, 'g11-aze-evez-q1-24', 1, 24, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "E": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'B', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9215, 119, 'g11-aze-evez-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə şəxs əvəzliyi var, sual əvəzliyi yoxdur, modal söz yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "D": "Biz qatarı stansiyada xeyli gözlədik.", "E": "Mən səni öz qardaşım kimi sevirəm."}'::jsonb, 'D', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
