INSERT INTO public.questions VALUES (9217, 119, 'g11-aze-evez-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, qayıdış əvəzliyi yoxdur, zərf yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Görünür, yağış səhərə kimi dayanmayacaq.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Ay bala, kitablarını rəfə yığ."}'::jsonb, 'D', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9218, 119, 'g11-aze-evez-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə şəxs əvəzliyi var, inkar əvəzliyi yoxdur, zərflik var və modal söz yoxdur?', NULL, NULL, '{"A": "Alim bu problemi təkbaşına araşdırdı.", "B": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Bəs siz hansı universitetə sənəd vermisiniz?", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'D', NULL, '«Bəs siz hansı universitetə sənəd vermisiniz?»: «siz» — şəxs əvəzliyi, mübtəda; «hansı» — sual əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9219, 119, 'g11-aze-evez-q1-29', 1, 29, 'hard', 'single', '«Bəlkə, biz son qatara çatmayacağıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1", "B": "əvəzlik — 0; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 0; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Bəlkə, biz son qatara çatmayacağıq.»: «biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9220, 119, 'g11-aze-evez-q1-30', 1, 30, 'hard', 'single', '«Biz qatarı stansiyada xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2", "D": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9221, 119, 'g11-aze-evez-q2-01', 2, 1, 'hard', 'single', '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0", "B": "əvəzlik — 0; isim — 4; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0"}'::jsonb, 'E', NULL, '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.»: «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0.');
