INSERT INTO public.questions VALUES (9232, 119, 'g11-aze-evez-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, 1 əvəzlik işlənib, feili bağlama yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "B": "Kimin əlyazmasını muzeyə verdiniz?", "C": "Axı siz bu kitabı oxumamısınız.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Əhsən, bu çətin yarışda hamını qabaqladın!"}'::jsonb, 'B', NULL, '«Kimin əlyazmasını muzeyə verdiniz?»: «Kimin» — sual əvəzliyi, yiyəlik hal, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9233, 119, 'g11-aze-evez-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, qeyri-müəyyən əvəzlik yoxdur, müraciət yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "D": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "E": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub."}'::jsonb, 'D', NULL, '«Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.»: «bütün» — təyini əvəzlik, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9234, 119, 'g11-aze-evez-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, inkar əvəzliyi yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Rəqib topu qəsdən kənara vurdu.", "B": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "C": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'E', NULL, '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9235, 119, 'g11-aze-evez-q2-15', 2, 15, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 4; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 3", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin; «heç kim» — inkar əvəzliyi, mübtəda. Düzgün: əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9236, 119, 'g11-aze-evez-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, qeyri-müəyyən əvəzlik yoxdur, müraciət yoxdur və cümlə sual cümləsidir?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Bəlkə, biz son qatara çatmayacağıq.", "C": "Bu işi üç nəfər bir həftəyə gördü.", "D": "Alim bu problemi təkbaşına araşdırdı.", "E": "Ah, gəncliyimdə bu imkanlar olsaydı!"}'::jsonb, 'A', NULL, '«Kimin əlyazmasını muzeyə verdiniz?»: «Kimin» — sual əvəzliyi, yiyəlik hal, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9237, 119, 'g11-aze-evez-q2-17', 2, 17, 'hard', 'single', '«Biz qatarı stansiyada xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 3", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'D', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9238, 119, 'g11-aze-evez-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə şəxs əvəzliyi var, təyini əvəzlik yoxdur və mübtəda var?', NULL, NULL, '{"A": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "B": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'C', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «bu» — işarə əvəzliyi, təyin; «məni» — şəxs əvəzliyi, təsirlik hal, vasitəsiz tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
