INSERT INTO public.questions VALUES (9254, 119, 'g11-aze-evez-q3-04', 3, 4, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 3", "B": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 2", "D": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 2", "E": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 2"}'::jsonb, 'E', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «bu» — işarə əvəzliyi, təyin; «siz» — şəxs əvəzliyi, mübtəda; «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Düzgün: əvəzlik — 3; isim — 1; şəxs əvəzliyi — 2.');
INSERT INTO public.questions VALUES (9255, 119, 'g11-aze-evez-q3-05', 3, 5, 'hard', 'single', '«Bəlkə, biz son qatara çatmayacağıq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1", "B": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 0; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1"}'::jsonb, 'E', NULL, '«Bəlkə, biz son qatara çatmayacağıq.»: «biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9256, 119, 'g11-aze-evez-q3-06', 3, 6, 'hard', 'single', '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 5; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 7; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0"}'::jsonb, 'E', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9257, 119, 'g11-aze-evez-q3-07', 3, 7, 'hard', 'single', '«Bu işi üç nəfər bir həftəyə gördü.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0"}'::jsonb, 'A', NULL, '«Bu işi üç nəfər bir həftəyə gördü.»: «Bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9258, 119, 'g11-aze-evez-q3-08', 3, 8, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 4; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 3"}'::jsonb, 'A', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin; «heç kim» — inkar əvəzliyi, mübtəda. Düzgün: əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9259, 119, 'g11-aze-evez-q3-09', 3, 9, 'hard', 'single', '«Bəs siz hansı universitetə sənəd vermisiniz?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 4; isim — 2; şəxs əvəzliyi — 1", "B": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0"}'::jsonb, 'C', NULL, '«Bəs siz hansı universitetə sənəd vermisiniz?»: «siz» — şəxs əvəzliyi, mübtəda; «hansı» — sual əvəzliyi, təyin. Düzgün: əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9260, 119, 'g11-aze-evez-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, şəxs əvəzliyi var, zərf yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "B": "Hər kəs öz fikrini yazsın.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Biz qatarı stansiyada xeyli gözlədik."}'::jsonb, 'D', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «bu» — işarə əvəzliyi, təyin; «siz» — şəxs əvəzliyi, mübtəda; «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9261, 119, 'g11-aze-evez-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, şəxs əvəzliyi yoxdur, müraciət yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Alim bu problemi təkbaşına araşdırdı.", "B": "Hər kəs öz fikrini yazsın.", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Deməli, bütün çətinliklər arxada qaldı."}'::jsonb, 'A', NULL, '«Alim bu problemi təkbaşına araşdırdı.»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9262, 119, 'g11-aze-evez-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə əvəzlik vasitəli tamamlıq vəzifəsində işlənib, qeyri-müəyyən əvəzlik yoxdur və ədat var?', NULL, NULL, '{"A": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "B": "Bəs siz hansı universitetə sənəd vermisiniz?", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "E": "Məncə, bu məsələni yalnız siz bizə anladarsınız."}'::jsonb, 'E', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «bu» — işarə əvəzliyi, təyin; «siz» — şəxs əvəzliyi, mübtəda; «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9263, 119, 'g11-aze-evez-q3-13', 3, 13, 'hard', 'single', '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "B": "əvəzlik — 1; isim — 6; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0"}'::jsonb, 'D', NULL, '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.»: «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9264, 119, 'g11-aze-evez-q3-14', 3, 14, 'hard', 'single', '«Biz qatarı stansiyada xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "C": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 0"}'::jsonb, 'C', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «Biz» — şəxs əvəzliyi, mübtəda. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9265, 119, 'g11-aze-evez-q3-15', 3, 15, 'hard', 'single', '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 5; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1", "C": "əvəzlik — 2; isim — 2; şəxs əvəzliyi — 1", "D": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 1", "E": "əvəzlik — 1; isim — 3; şəxs əvəzliyi — 1"}'::jsonb, 'B', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: «sənin» — şəxs əvəzliyi, yiyəlik hal, təyin; «hər» — təyini əvəzlik, təyin. Düzgün: əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9266, 119, 'g11-aze-evez-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə işarə əvəzliyi var, təyini əvəzlik yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Rəqib topu qəsdən kənara vurdu.", "B": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "C": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "D": "Bu işi üç nəfər bir həftəyə gördü.", "E": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi."}'::jsonb, 'D', NULL, '«Bu işi üç nəfər bir həftəyə gördü.»: «Bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9267, 119, 'g11-aze-evez-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, sual əvəzliyi yoxdur, məsdər yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "B": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Bəs siz hansı universitetə sənəd vermisiniz?", "E": "Karvan dənizə sarı irəliləyirdi."}'::jsonb, 'A', NULL, '«Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.»: «bütün» — təyini əvəzlik, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9268, 119, 'g11-aze-evez-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə əvəzlik mübtəda vəzifəsində işlənib, işarə əvəzliyi yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Görünür, yağış səhərə kimi dayanmayacaq.", "E": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'B', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «Siz» — şəxs əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9269, 119, 'g11-aze-evez-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə 2 əvəzlik işlənib, əvəzlik mübtəda vəzifəsində işlənib, vasitəli tamamlıq yoxdur və ədat var?', NULL, NULL, '{"A": "Əhsən, bu çətin yarışda hamını qabaqladın!", "B": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "C": "Hər kəs öz fikrini yazsın.", "D": "Axı siz bu kitabı oxumamısınız.", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'D', NULL, '«Axı siz bu kitabı oxumamısınız.»: «siz» — şəxs əvəzliyi, mübtəda; «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9270, 119, 'g11-aze-evez-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, inkar əvəzliyi yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "C": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "D": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "E": "Rəqib topu qəsdən kənara vurdu."}'::jsonb, 'A', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
