INSERT INTO public.questions VALUES (9272, 119, 'g11-aze-evez-q3-22', 3, 22, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1", "C": "əvəzlik — 3; isim — 1; şəxs əvəzliyi — 1", "D": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 2"}'::jsonb, 'B', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «bu» — işarə əvəzliyi, təyin; «məni» — şəxs əvəzliyi, təsirlik hal, vasitəsiz tamamlıq. Düzgün: əvəzlik — 2; isim — 1; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9273, 119, 'g11-aze-evez-q3-23', 3, 23, 'hard', 'single', '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 0", "C": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 3", "D": "əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1", "E": "əvəzlik — 4; isim — 3; şəxs əvəzliyi — 1"}'::jsonb, 'D', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: «sənin» — şəxs əvəzliyi, yiyəlik hal, təyin; «hər» — təyini əvəzlik, təyin. Düzgün: əvəzlik — 2; isim — 3; şəxs əvəzliyi — 1.');
INSERT INTO public.questions VALUES (9274, 119, 'g11-aze-evez-q3-24', 3, 24, 'hard', 'single', '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 0; isim — 4; şəxs əvəzliyi — 0", "B": "əvəzlik — 1; isim — 6; şəxs əvəzliyi — 0", "C": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 1", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0"}'::jsonb, 'D', NULL, '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.»: «bu» — işarə əvəzliyi, təyin. Düzgün: əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9275, 119, 'g11-aze-evez-q3-25', 3, 25, 'hard', 'single', '«Deməli, bütün çətinliklər arxada qaldı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 0; isim — 2; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 1; şəxs əvəzliyi — 0", "C": "əvəzlik — 3; isim — 2; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 2; şəxs əvəzliyi — 2"}'::jsonb, 'D', NULL, '«Deməli, bütün çətinliklər arxada qaldı.»: «bütün» — təyini əvəzlik, təyin. Düzgün: əvəzlik — 1; isim — 2; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9276, 119, 'g11-aze-evez-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə şəxs əvəzliyi var, işarə əvəzliyi yoxdur, xəbər feillə ifadə olunub və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Uşaqlar sakitcə nağılı dinləyirdilər.", "D": "Ay bala, kitablarını rəfə yığ.", "E": "Axı siz bu kitabı oxumamısınız."}'::jsonb, 'B', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «sizin» — şəxs əvəzliyi, yiyəlik hal, təyin; «heç kim» — inkar əvəzliyi, mübtəda. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9277, 119, 'g11-aze-evez-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, qayıdış əvəzliyi yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Bəs siz hansı universitetə sənəd vermisiniz?", "B": "Karvan dənizə sarı irəliləyirdi.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Hər kəs öz fikrini yazsın.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'A', NULL, '«Bəs siz hansı universitetə sənəd vermisiniz?»: «siz» — şəxs əvəzliyi, mübtəda; «hansı» — sual əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9278, 119, 'g11-aze-evez-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə 1 əvəzlik işlənib, əvəzlik təyin vəzifəsində işlənib və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Axı siz bu kitabı oxumamısınız.", "B": "Bu işi üç nəfər bir həftəyə gördü.", "C": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "D": "Əhsən, bu çətin yarışda hamını qabaqladın!", "E": "Ah, gəncliyimdə bu imkanlar olsaydı!"}'::jsonb, 'B', NULL, '«Bu işi üç nəfər bir həftəyə gördü.»: «Bu» — işarə əvəzliyi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9279, 119, 'g11-aze-evez-q3-29', 3, 29, 'hard', 'single', '«Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "əvəzlik — 1; isim — 5; şəxs əvəzliyi — 0", "B": "əvəzlik — 2; isim — 4; şəxs əvəzliyi — 0", "C": "əvəzlik — 0; isim — 4; şəxs əvəzliyi — 0", "D": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0", "E": "əvəzlik — 1; isim — 4; şəxs əvəzliyi — 1"}'::jsonb, 'D', NULL, '«Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.»: «bütün» — təyini əvəzlik, təyin. Düzgün: əvəzlik — 1; isim — 4; şəxs əvəzliyi — 0.');
INSERT INTO public.questions VALUES (9280, 119, 'g11-aze-evez-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə əvəzlik təyin vəzifəsində işlənib, qeyri-müəyyən əvəzlik yoxdur, zərf yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "B": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "C": "Əhsən, bu çətin yarışda hamını qabaqladın!", "D": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'B', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «bu» — işarə əvəzliyi, təyin; «siz» — şəxs əvəzliyi, mübtəda; «bizə» — şəxs əvəzliyi, yönlük hal, vasitəli tamamlıq. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9281, 120, 'g11-aze-feil-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə feili sifət var, feili bağlama yoxdur və nida yoxdur?', NULL, NULL, '{"A": "Bu işi üç nəfər bir həftəyə gördü.", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "D": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "E": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi."}'::jsonb, 'D', NULL, '«Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.»: «yetirdiyi» — feili sifət, təyin; «veriblər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9282, 120, 'g11-aze-feil-q1-02', 1, 2, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 4", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 5", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3"}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «nümayiş etdirilir» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4.');
INSERT INTO public.questions VALUES (9283, 120, 'g11-aze-feil-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Onlar maşını satırlar.", "B": "Biz maşını satacağıq.", "C": "Siz maşını satacaqsınız.", "D": "Onlar maşını satacaqlar.", "E": "Mən maşını satacağam."}'::jsonb, 'D', NULL, '«satacaqlar» — qəti gələcək zaman, III şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9284, 120, 'g11-aze-feil-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə feili bağlama var, feilin təsriflənən formalarından 1 işlənib və say yoxdur?', NULL, NULL, '{"A": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "D": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'D', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «dayanmadan» — feili bağlama, zərflik; «işlədilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9285, 120, 'g11-aze-feil-q1-05', 1, 5, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 1", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 0", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 0"}'::jsonb, 'C', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «bitib-tükənməyən» — feili sifət, təyin; «yordu» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1.');
INSERT INTO public.questions VALUES (9286, 120, 'g11-aze-feil-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, qapını açır.", "B": "Sən qapını açırsan.", "C": "Siz qapını açırsınız.", "D": "Sən qapını açdın.", "E": "Onlar qapını açırlar."}'::jsonb, 'B', NULL, '«açırsan» — indiki zaman, II şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9287, 120, 'g11-aze-feil-q1-07', 1, 7, 'hard', 'single', '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 6", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "E": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 1; isim — 4"}'::jsonb, 'D', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «qayıdan» — feili sifət, təyin; «tikdilər» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4.');
INSERT INTO public.questions VALUES (9288, 120, 'g11-aze-feil-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, III şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, qapını açmadı.", "B": "Onlar qapını açmadılar.", "C": "Sən qapını açmadın.", "D": "O, qapını açmayacaq.", "E": "O, qapını açmır."}'::jsonb, 'A', NULL, '«açmadı» — şühudi keçmiş zaman, III şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (9289, 120, 'g11-aze-feil-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Siz pəncərəni bağlayırsınız.", "B": "O, pəncərəni bağlayır.", "C": "O, pəncərəni bağlamır.", "D": "Sən pəncərəni bağlayırsan.", "E": "O, pəncərəni bağlayacaq."}'::jsonb, 'B', NULL, '«bağlayır» — indiki zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9290, 120, 'g11-aze-feil-q1-10', 1, 10, 'hard', 'single', '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 5", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5", "E": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 1; isim — 5"}'::jsonb, 'D', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «qalan» — feili sifət, təyin; «qoruyun» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5.');
INSERT INTO public.questions VALUES (9291, 120, 'g11-aze-feil-q1-11', 1, 11, 'hard', 'single', '«Bəs siz hansı universitetə sənəd vermisiniz?» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'A', NULL, '«Bəs siz hansı universitetə sənəd vermisiniz?»: «vermisiniz» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (9292, 120, 'g11-aze-feil-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, II şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən məktubu yazmayacaqsan.", "B": "Sən məktubu yazdın.", "C": "Sən məktubu yazacaqsan.", "D": "Biz məktubu yazacağıq.", "E": "Onlar məktubu yazacaqlar."}'::jsonb, 'C', NULL, '«yazacaqsan» — qəti gələcək zaman, II şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9293, 120, 'g11-aze-feil-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur, vasitəsiz tamamlıq yoxdur və zərflik var?', NULL, NULL, '{"A": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "B": "Bu işi üç nəfər bir həftəyə gördü.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "D": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'E', NULL, '«Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.»: «yerləşən» — feili sifət, təyin; «yaşadılır» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9294, 120, 'g11-aze-feil-q1-14', 1, 14, 'hard', 'single', '«Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 5", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 4", "D": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 5", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 5"}'::jsonb, 'B', NULL, '«Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.»: «yetirdiyi» — feili sifət, təyin; «veriblər» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5.');
INSERT INTO public.questions VALUES (9295, 120, 'g11-aze-feil-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Onlar çadırı quracaqlar.", "B": "Biz çadırı quracağıq.", "C": "Biz çadırı qurduq.", "D": "Biz çadırı qururuq.", "E": "Sən çadırı quracaqsan."}'::jsonb, 'B', NULL, '«quracağıq» — qəti gələcək zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9296, 120, 'g11-aze-feil-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, III şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Sən çayı içmədin.", "B": "Onlar çayı içmədilər.", "C": "O, çayı içdi.", "D": "O, çayı içmədi.", "E": "Mən çayı içmədim."}'::jsonb, 'D', NULL, '«içmədi» — şühudi keçmiş zaman, III şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (9297, 120, 'g11-aze-feil-q1-17', 1, 17, 'hard', 'single', '«Axı siz bu kitabı oxumamısınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 0", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 0"}'::jsonb, 'B', NULL, '«Axı siz bu kitabı oxumamısınız.»: «oxumamısınız» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1.');
INSERT INTO public.questions VALUES (9298, 120, 'g11-aze-feil-q1-18', 1, 18, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'D', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «olsaydı» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (9299, 120, 'g11-aze-feil-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "B": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Bu işi üç nəfər bir həftəyə gördü.", "D": "Ay bala, kitablarını rəfə yığ.", "E": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir."}'::jsonb, 'D', NULL, '«Ay bala, kitablarını rəfə yığ.»: «yığ» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9300, 120, 'g11-aze-feil-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili sifət yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Görünür, yağış səhərə kimi dayanmayacaq.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Mən səni öz qardaşım kimi sevirəm.", "D": "Bu işi üç nəfər bir həftəyə gördü.", "E": "Bəs siz hansı universitetə sənəd vermisiniz?"}'::jsonb, 'A', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «dayanmayacaq» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9301, 120, 'g11-aze-feil-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, inkarda olan feil var, qoşma yoxdur və təyin var?', NULL, NULL, '{"A": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "B": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "E": "Ah, gəncliyimdə bu imkanlar olsaydı!"}'::jsonb, 'A', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: «sevdiyi» — feili sifət, təyin; «görən» — feili sifət, təyin; «yorulmur» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9302, 120, 'g11-aze-feil-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Gördüyünüz kimi, bütün sənədlər hazırdır."}'::jsonb, 'D', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «anladarsınız» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9303, 120, 'g11-aze-feil-q1-23', 1, 23, 'hard', 'single', '«Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "C": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 1; isim — 3", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 3", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'E', NULL, '«Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.»: «dinləyə-dinləyə» — feili bağlama, zərflik; «aparırdılar» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3.');
INSERT INTO public.questions VALUES (9304, 120, 'g11-aze-feil-q1-24', 1, 24, 'hard', 'single', '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 5", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 1; isim — 5", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 5", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5"}'::jsonb, 'E', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «qalan» — feili sifət, təyin; «qoruyun» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5.');
INSERT INTO public.questions VALUES (9305, 120, 'g11-aze-feil-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Görünür, yağış səhərə kimi dayanmayacaq.", "B": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "C": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "D": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'E', NULL, '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.»: «qalxmaqdan» — məsdər, çıxışlıq hal, vasitəli tamamlıq; «çəkinirdilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9306, 120, 'g11-aze-feil-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən almaları yığmırsan.", "B": "Sən almaları yığırsan.", "C": "Onlar almaları yığırlar.", "D": "Mən almaları yığıram.", "E": "Siz almaları yığırsınız."}'::jsonb, 'B', NULL, '«yığırsan» — indiki zaman, II şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9307, 120, 'g11-aze-feil-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə məsdər var, feili bağlama yoxdur, vasitəsiz tamamlıq var və mübtəda var?', NULL, NULL, '{"A": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "B": "Babam təkbaşına dağa çıxmağı sevirdi.", "C": "Alim bu problemi təkbaşına araşdırdı.", "D": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "E": "Uşaqlar sakitcə nağılı dinləyirdilər."}'::jsonb, 'B', NULL, '«Babam təkbaşına dağa çıxmağı sevirdi.»: «çıxmağı» — məsdər, təsirlik hal, vasitəsiz tamamlıq; «sevirdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9308, 120, 'g11-aze-feil-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Hər kəs öz fikrini yazsın.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'E', NULL, '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.»: «qalxmaqdan» — məsdər, çıxışlıq hal, vasitəli tamamlıq; «çəkinirdilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9309, 120, 'g11-aze-feil-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Siz bu mahnını sevirsiniz.", "B": "O, bu mahnını sevir.", "C": "O, bu mahnını sevəcək.", "D": "Sən bu mahnını sevirsən.", "E": "Onlar bu mahnını sevirlər."}'::jsonb, 'B', NULL, '«sevir» — indiki zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9310, 120, 'g11-aze-feil-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, II şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, tamaşanı görmədi.", "B": "Biz tamaşanı görmədik.", "C": "Onlar tamaşanı görmədilər.", "D": "Siz tamaşanı görmədiniz.", "E": "Sən tamaşanı görmədin."}'::jsonb, 'D', NULL, '«görmədiniz» — şühudi keçmiş zaman, II şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (9311, 120, 'g11-aze-feil-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, II şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Siz evi tikirsiniz.", "B": "Siz evi tikdiniz.", "C": "Sən evi tikdin.", "D": "Siz evi tikəcəksiniz.", "E": "O, evi tikdi."}'::jsonb, 'B', NULL, '«tikdiniz» — şühudi keçmiş zaman, II şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9312, 120, 'g11-aze-feil-q2-02', 2, 2, 'hard', 'single', '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 3", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'C', NULL, '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.»: «həll etdi» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3.');
INSERT INTO public.questions VALUES (9313, 120, 'g11-aze-feil-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə feili sifət var, feilin təsriflənən formalarından 1 işlənib, modal söz var və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "C": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "D": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "E": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı."}'::jsonb, 'A', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «başlayacaq» — feili sifət, təyin; «yarışacaq» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9314, 120, 'g11-aze-feil-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, II şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən lövhəni siləcəksən.", "B": "Siz lövhəni silirsiniz.", "C": "Onlar lövhəni siləcəklər.", "D": "Siz lövhəni siləcəksiniz.", "E": "Mən lövhəni siləcəyəm."}'::jsonb, 'D', NULL, '«siləcəksiniz» — qəti gələcək zaman, II şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9315, 120, 'g11-aze-feil-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili sifət yoxdur və mübtəda yoxdur?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Alim bu problemi təkbaşına araşdırdı.", "D": "Biz qatarı stansiyada xeyli gözlədik.", "E": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi."}'::jsonb, 'A', NULL, '«Kimin əlyazmasını muzeyə verdiniz?»: «verdiniz» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9316, 120, 'g11-aze-feil-q2-06', 2, 6, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'B', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «dəyişdi» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (9317, 120, 'g11-aze-feil-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə inkarda olan feil var, məsdər yoxdur, say yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "B": "Deməli, bütün çətinliklər arxada qaldı.", "C": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "D": "Kimin əlyazmasını muzeyə verdiniz?", "E": "Axı siz bu kitabı oxumamısınız."}'::jsonb, 'E', NULL, '«Axı siz bu kitabı oxumamısınız.»: «oxumamısınız» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9318, 120, 'g11-aze-feil-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur, zərf yoxdur və zərflik var?', NULL, NULL, '{"A": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "B": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'A', NULL, '«Kitabın üçüncü fəslini iki-üç dəfə oxudum.»: «oxudum» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9319, 120, 'g11-aze-feil-q2-09', 2, 9, 'hard', 'single', '«Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 5", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 3", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3"}'::jsonb, 'A', NULL, '«Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.»: «dinləyə-dinləyə» — feili bağlama, zərflik; «aparırdılar» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3.');
INSERT INTO public.questions VALUES (9320, 120, 'g11-aze-feil-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər yoxdur, xəbər feillə ifadə olunub və nida yoxdur?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Deməli, bütün çətinliklər arxada qaldı.", "E": "Əhsən, bu çətin yarışda hamını qabaqladın!"}'::jsonb, 'D', NULL, '«Deməli, bütün çətinliklər arxada qaldı.»: «qaldı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9321, 120, 'g11-aze-feil-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "D": "Alim bu problemi təkbaşına araşdırdı.", "E": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı."}'::jsonb, 'D', NULL, '«Alim bu problemi təkbaşına araşdırdı.»: «araşdırdı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9322, 120, 'g11-aze-feil-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Siz çantanı götürəcəksiniz.", "B": "O, çantanı götürəcək.", "C": "Biz çantanı götürməyəcəyik.", "D": "Biz çantanı götürəcəyik.", "E": "Biz çantanı götürürük."}'::jsonb, 'D', NULL, '«götürəcəyik» — qəti gələcək zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9323, 120, 'g11-aze-feil-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər yoxdur, nida yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "B": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "C": "Bəlkə, biz son qatara çatmayacağıq.", "D": "Axı siz bu kitabı oxumamısınız.", "E": "Babam təkbaşına dağa çıxmağı sevirdi."}'::jsonb, 'B', NULL, '«Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.»: «iştirak etdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9324, 120, 'g11-aze-feil-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, II şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən lövhəni sildin.", "B": "Onlar lövhəni sildilər.", "C": "O, lövhəni sildi.", "D": "Siz lövhəni sildiniz.", "E": "Siz lövhəni silirsiniz."}'::jsonb, 'D', NULL, '«sildiniz» — şühudi keçmiş zaman, II şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9325, 120, 'g11-aze-feil-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Biz çantanı götürmədik.", "B": "O, çantanı götürmədi.", "C": "Sən çantanı götürmədin.", "D": "Mən çantanı götürmədim.", "E": "Biz çantanı götürdük."}'::jsonb, 'A', NULL, '«götürmədik» — şühudi keçmiş zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (9326, 120, 'g11-aze-feil-q2-16', 2, 16, 'hard', 'single', '«Doğrudan da, sevdiyi işi görən insan yorulmur.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 2; isim — 2", "B": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 2; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4"}'::jsonb, 'C', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: «sevdiyi» — feili sifət, təyin; «görən» — feili sifət, təyin; «yorulmur» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2.');
INSERT INTO public.questions VALUES (9327, 120, 'g11-aze-feil-q2-17', 2, 17, 'hard', 'single', '«Mən səni öz qardaşım kimi sevirəm.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 1", "B": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 0", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 0"}'::jsonb, 'D', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «sevirəm» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1.');
INSERT INTO public.questions VALUES (9328, 120, 'g11-aze-feil-q2-18', 2, 18, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 1", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'C', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «danışdığınız» — feili sifət, təyin; «unutmayacaq» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (9329, 120, 'g11-aze-feil-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Biz kitabı oxumadıq.", "B": "Onlar kitabı oxudular.", "C": "Biz kitabı oxuyacağıq.", "D": "Mən kitabı oxudum.", "E": "Biz kitabı oxuduq."}'::jsonb, 'E', NULL, '«oxuduq» — şühudi keçmiş zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9330, 120, 'g11-aze-feil-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili sifət yoxdur və sifət var?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Ah, gəncliyimdə bu imkanlar olsaydı!", "D": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'D', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «keçdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9331, 120, 'g11-aze-feil-q2-21', 2, 21, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 6", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "C": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3"}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «nümayiş etdirilir» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4.');
INSERT INTO public.questions VALUES (9332, 120, 'g11-aze-feil-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Biz çayı içirik.", "B": "Biz çayı içmirik.", "C": "Siz çayı içirsiniz.", "D": "O, çayı içir.", "E": "Mən çayı içirəm."}'::jsonb, 'A', NULL, '«içirik» — indiki zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9333, 120, 'g11-aze-feil-q2-23', 2, 23, 'hard', 'single', '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2"}'::jsonb, 'A', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «keçdi» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (9334, 120, 'g11-aze-feil-q2-24', 2, 24, 'hard', 'single', '«Bu işi üç nəfər bir həftəyə gördü.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "E": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 3"}'::jsonb, 'D', NULL, '«Bu işi üç nəfər bir həftəyə gördü.»: «gördü» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3.');
INSERT INTO public.questions VALUES (9335, 120, 'g11-aze-feil-q2-25', 2, 25, 'hard', 'single', '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 4", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 6", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3"}'::jsonb, 'B', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: «oturmuşdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4.');
INSERT INTO public.questions VALUES (9336, 120, 'g11-aze-feil-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Siz məktubu yazırsınız.", "B": "Siz məktubu yazmadınız.", "C": "Mən məktubu yazmıram.", "D": "Siz məktubu yazmırsınız.", "E": "Biz məktubu yazmırıq."}'::jsonb, 'D', NULL, '«yazmırsınız» — indiki zaman, II şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (9337, 120, 'g11-aze-feil-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili sifət yoxdur və zərf var?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Ah, gəncliyimdə bu imkanlar olsaydı!", "C": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "D": "Biz qatarı stansiyada xeyli gözlədik.", "E": "Ay bala, kitablarını rəfə yığ."}'::jsonb, 'D', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «gözlədik» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9338, 120, 'g11-aze-feil-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Onlar maşını satırlar.", "B": "O, maşını satır.", "C": "Siz maşını satırsınız.", "D": "Sən maşını satırsan.", "E": "Biz maşını satırıq."}'::jsonb, 'E', NULL, '«satırıq» — indiki zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9339, 120, 'g11-aze-feil-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, I şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Siz musiqini dinləmirsiniz.", "B": "O, musiqini dinləmir.", "C": "Mən musiqini dinləməyəcəyəm.", "D": "Mən musiqini dinləmədim.", "E": "Mən musiqini dinləmirəm."}'::jsonb, 'E', NULL, '«dinləmirəm» — indiki zaman, I şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (9340, 120, 'g11-aze-feil-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə inkarda olan feil var, məsdər yoxdur, təyin var və modal söz var?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "D": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'D', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: «sevdiyi» — feili sifət, təyin; «görən» — feili sifət, təyin; «yorulmur» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9341, 120, 'g11-aze-feil-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, tapşırığı unutur.", "B": "Siz tapşırığı unutursunuz.", "C": "O, tapşırığı unutacaq.", "D": "O, tapşırığı unutdu.", "E": "Biz tapşırığı unuturuq."}'::jsonb, 'A', NULL, '«unutur» — indiki zaman, III şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9342, 120, 'g11-aze-feil-q3-02', 3, 2, 'hard', 'single', '«Əhsən, bu çətin yarışda hamını qabaqladın!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 1", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 1", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 0", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1"}'::jsonb, 'E', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «qabaqladın» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 1.');
INSERT INTO public.questions VALUES (9343, 120, 'g11-aze-feil-q3-03', 3, 3, 'hard', 'single', '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 6", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3"}'::jsonb, 'D', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: «oturmuşdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4.');
INSERT INTO public.questions VALUES (9344, 120, 'g11-aze-feil-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Sən şəkli çəkmirsən.", "B": "Siz şəkli çəkmirsiniz.", "C": "Onlar şəkli çəkmədilər.", "D": "Onlar şəkli çəkmirlər.", "E": "Biz şəkli çəkmirik."}'::jsonb, 'D', NULL, '«çəkmirlər» — indiki zaman, III şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (9345, 120, 'g11-aze-feil-q3-05', 3, 5, 'hard', 'single', '«Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 5", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "D": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 3", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3"}'::jsonb, 'A', NULL, '«Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.»: «iştirak etdi» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3.');
INSERT INTO public.questions VALUES (9346, 120, 'g11-aze-feil-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər tamamlıq vəzifəsindədir və sifət yoxdur?', NULL, NULL, '{"A": "Axı siz bu kitabı oxumamısınız.", "B": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "C": "Babam təkbaşına dağa çıxmağı sevirdi.", "D": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'C', NULL, '«Babam təkbaşına dağa çıxmağı sevirdi.»: «çıxmağı» — məsdər, təsirlik hal, vasitəsiz tamamlıq; «sevirdi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9347, 120, 'g11-aze-feil-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, II şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "O, bileti almır.", "B": "Sən bileti almırsan.", "C": "Biz bileti almırıq.", "D": "Sən bileti almadın.", "E": "Sən bileti almayacaqsan."}'::jsonb, 'B', NULL, '«almırsan» — indiki zaman, II şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (9348, 120, 'g11-aze-feil-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə feili bağlama var, feili sifət yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Hər kəs öz fikrini yazsın.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Uşaqlar sakitcə nağılı dinləyirdilər.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'B', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «dayanmadan» — feili bağlama, zərflik; «işlədilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9349, 120, 'g11-aze-feil-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər yoxdur, cümlə sual cümləsidir və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Bəs siz hansı universitetə sənəd vermisiniz?", "B": "Axı siz bu kitabı oxumamısınız.", "C": "Hər kəs öz fikrini yazsın.", "D": "Of, bu bitib-tükənməyən yol məni yordu!", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'A', NULL, '«Bəs siz hansı universitetə sənəd vermisiniz?»: «vermisiniz» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9350, 120, 'g11-aze-feil-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, III şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Sən çayı içirsən.", "B": "Mən çayı içirəm.", "C": "Onlar çayı içmirlər.", "D": "Onlar çayı içirlər.", "E": "O, çayı içir."}'::jsonb, 'D', NULL, '«içirlər» — indiki zaman, III şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9351, 120, 'g11-aze-feil-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər yoxdur, bağlayıcı yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Bəs siz hansı universitetə sənəd vermisiniz?", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Uşaqlar sakitcə nağılı dinləyirdilər.", "E": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular."}'::jsonb, 'D', NULL, '«Uşaqlar sakitcə nağılı dinləyirdilər.»: «dinləyirdilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9352, 120, 'g11-aze-feil-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili bağlama yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Biz qatarı stansiyada xeyli gözlədik.", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'E', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «qayıdan» — feili sifət, təyin; «tikdilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9353, 120, 'g11-aze-feil-q3-13', 3, 13, 'hard', 'single', '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 1; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'E', NULL, '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.»: «qalxmaqdan» — məsdər, çıxışlıq hal, vasitəli tamamlıq; «çəkinirdilər» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2.');
INSERT INTO public.questions VALUES (9354, 120, 'g11-aze-feil-q3-14', 3, 14, 'hard', 'single', '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 2; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 4", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 2; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2"}'::jsonb, 'E', NULL, '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.»: «ötən» — feili sifət, təyin; «əkdiyimiz» — feili sifət, təyin; «quruyub» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2.');
INSERT INTO public.questions VALUES (9355, 120, 'g11-aze-feil-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə feili bağlama var, məsdər yoxdur, modal söz yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "B": "Rəqib topu qəsdən kənara vurdu.", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Karvan dənizə sarı irəliləyirdi."}'::jsonb, 'A', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «dayanmadan» — feili bağlama, zərflik; «işlədilər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9356, 120, 'g11-aze-feil-q3-16', 3, 16, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 6", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 3", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 4"}'::jsonb, 'C', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «nümayiş etdirilir» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 4.');
INSERT INTO public.questions VALUES (9357, 120, 'g11-aze-feil-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər yoxdur və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "B": "Hər kəs öz fikrini yazsın.", "C": "Mən səni öz qardaşım kimi sevirəm.", "D": "Kimin əlyazmasını muzeyə verdiniz?", "E": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin."}'::jsonb, 'A', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «gözlədiyimiz» — feili sifət, təyin; «gəldi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9358, 120, 'g11-aze-feil-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, II şəxs təkdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, musiqini dinlədi.", "B": "Siz musiqini dinlədiniz.", "C": "Sən musiqini dinləmədin.", "D": "Sən musiqini dinləyirsən.", "E": "Sən musiqini dinlədin."}'::jsonb, 'E', NULL, '«dinlədin» — şühudi keçmiş zaman, II şəxs tək, təsdiq forması.');
INSERT INTO public.questions VALUES (9359, 120, 'g11-aze-feil-q3-19', 3, 19, 'hard', 'single', '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 3; isim — 2", "B": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 2; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 2", "D": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 3; isim — 2", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 4; isim — 1"}'::jsonb, 'C', NULL, '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.»: «Gülə-gülə» — feili bağlama, təyin; «girən» — feili sifət, təyin; «görcək» — feili bağlama, zərflik; «susdular» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 3; isim — 2.');
INSERT INTO public.questions VALUES (9360, 120, 'g11-aze-feil-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, III şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, maşını satacaq.", "B": "Sən maşını satacaqsan.", "C": "Onlar maşını satdılar.", "D": "Onlar maşını satacaqlar.", "E": "Siz maşını satacaqsınız."}'::jsonb, 'D', NULL, '«satacaqlar» — qəti gələcək zaman, III şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9361, 120, 'g11-aze-feil-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil indiki zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "Mən məktubu yazıram.", "B": "Biz məktubu yazdıq.", "C": "Biz məktubu yazırıq.", "D": "Siz məktubu yazırsınız.", "E": "Onlar məktubu yazırlar."}'::jsonb, 'C', NULL, '«yazırıq» — indiki zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9362, 120, 'g11-aze-feil-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, feili sifət var, xəbər feillə ifadə olunub və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "B": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "E": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'B', NULL, '«Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.»: «yetirdiyi» — feili sifət, təyin; «veriblər» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9363, 120, 'g11-aze-feil-q3-23', 3, 23, 'hard', 'single', '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 3", "B": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 3", "C": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3"}'::jsonb, 'E', NULL, '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.»: «həll etdi» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 3.');
INSERT INTO public.questions VALUES (9364, 120, 'g11-aze-feil-q3-24', 3, 24, 'hard', 'single', 'Hansı cümlədə feilin təsriflənən formalarından 1 işlənib, məsdər yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "B": "Deməli, bütün çətinliklər arxada qaldı.", "C": "Babam təkbaşına dağa çıxmağı sevirdi.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Kimin əlyazmasını muzeyə verdiniz?"}'::jsonb, 'B', NULL, '«Deməli, bütün çətinliklər arxada qaldı.»: «qaldı» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9365, 120, 'g11-aze-feil-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə feili sifət var, feili bağlama yoxdur, ədat yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "D": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "E": "Əhsən, bu çətin yarışda hamını qabaqladın!"}'::jsonb, 'D', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «gözlədiyimiz» — feili sifət, təyin; «gəldi» — feil, xəbər. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9366, 120, 'g11-aze-feil-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil qəti gələcək zamandadır, I şəxs cəmdədir və inkar formasındadır?', NULL, NULL, '{"A": "Onlar tapşırığı unutmayacaqlar.", "B": "Biz tapşırığı unutacağıq.", "C": "Biz tapşırığı unutmuruq.", "D": "Biz tapşırığı unutmayacağıq.", "E": "Mən tapşırığı unutmayacağam."}'::jsonb, 'D', NULL, '«unutmayacağıq» — qəti gələcək zaman, I şəxs cəm, inkar forması.');
INSERT INTO public.questions VALUES (9367, 120, 'g11-aze-feil-q3-27', 3, 27, 'hard', 'single', '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 2; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2", "C": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 3", "D": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 2; isim — 1", "E": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2"}'::jsonb, 'B', NULL, '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.»: «ötən» — feili sifət, təyin; «əkdiyimiz» — feili sifət, təyin; «quruyub» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 2; isim — 2.');
INSERT INTO public.questions VALUES (9368, 120, 'g11-aze-feil-q3-28', 3, 28, 'hard', 'single', '«Afərin, sən yarışda birinci yeri tutdun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "feilin təsriflənən forması — 0; feilin təsriflənməyən forması — 0; isim — 2", "B": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2", "C": "feilin təsriflənən forması — 3; feilin təsriflənməyən forması — 0; isim — 2", "D": "feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 1; isim — 2", "E": "feilin təsriflənən forması — 2; feilin təsriflənməyən forması — 0; isim — 1"}'::jsonb, 'B', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «tutdun» — feil, xəbər. Düzgün: feilin təsriflənən forması — 1; feilin təsriflənməyən forması — 0; isim — 2.');
INSERT INTO public.questions VALUES (9369, 120, 'g11-aze-feil-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs cəmdədir və təsdiq formasındadır?', NULL, NULL, '{"A": "O, tamaşanı gördü.", "B": "Biz tamaşanı görəcəyik.", "C": "Mən tamaşanı gördüm.", "D": "Biz tamaşanı gördük.", "E": "Siz tamaşanı gördünüz."}'::jsonb, 'D', NULL, '«gördük» — şühudi keçmiş zaman, I şəxs cəm, təsdiq forması.');
INSERT INTO public.questions VALUES (9370, 120, 'g11-aze-feil-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə xəbər vəzifəsindəki feil şühudi keçmiş zamandadır, I şəxs təkdədir və inkar formasındadır?', NULL, NULL, '{"A": "Mən tamaşanı görmədim.", "B": "Mən tamaşanı görmürəm.", "C": "Onlar tamaşanı görmədilər.", "D": "Sən tamaşanı görmədin.", "E": "Mən tamaşanı gördüm."}'::jsonb, 'A', NULL, '«görmədim» — şühudi keçmiş zaman, I şəxs tək, inkar forması.');
INSERT INTO public.questions VALUES (9371, 121, 'g11-aze-zerf-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə 1 zərf işlənib, yer zərfi yoxdur, bağlayıcı yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "C": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "D": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'B', NULL, '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.»: «təkbaşına» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9372, 121, 'g11-aze-zerf-q1-02', 1, 2, 'hard', 'single', '«Biz qatarı stansiyada xeyli gözlədik.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 2; isim — 2; əvəzlik — 1", "B": "zərf — 1; isim — 2; əvəzlik — 1", "C": "zərf — 1; isim — 4; əvəzlik — 1", "D": "zərf — 2; isim — 1; əvəzlik — 1", "E": "zərf — 1; isim — 2; əvəzlik — 3"}'::jsonb, 'B', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «xeyli» — kəmiyyət zərfi, zərflik. Düzgün: zərf — 1; isim — 2; əvəzlik — 1.');
INSERT INTO public.questions VALUES (9373, 121, 'g11-aze-zerf-q1-03', 1, 3, 'hard', 'single', '«Nağılı dinləyərkən uşaqlar bir-bir yatdılar.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 2; əvəzlik — 0", "B": "zərf — 2; isim — 1; əvəzlik — 0", "C": "zərf — 2; isim — 2; əvəzlik — 0", "D": "zərf — 1; isim — 1; əvəzlik — 0", "E": "zərf — 1; isim — 2; əvəzlik — 1"}'::jsonb, 'A', NULL, '«Nağılı dinləyərkən uşaqlar bir-bir yatdılar.»: «bir-bir» — tərzi-hərəkət zərfi, zərflik. Düzgün: zərf — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9374, 121, 'g11-aze-zerf-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir, zaman zərfi yoxdur, məsdər yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Bəs siz hansı universitetə sənəd vermisiniz?", "B": "Deməli, bütün çətinliklər arxada qaldı.", "C": "Alim bu problemi təkbaşına araşdırdı.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Görünür, yağış səhərə kimi dayanmayacaq."}'::jsonb, 'C', NULL, '«Alim bu problemi təkbaşına araşdırdı.»: «təkbaşına» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9375, 121, 'g11-aze-zerf-q1-05', 1, 5, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 1; əvəzlik — 2", "B": "zərf — 1; isim — 2; əvəzlik — 3", "C": "zərf — 1; isim — 2; əvəzlik — 2", "D": "zərf — 3; isim — 2; əvəzlik — 2", "E": "zərf — 1; isim — 3; əvəzlik — 1"}'::jsonb, 'C', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «dünən» — zaman zərfi, təyin. Düzgün: zərf — 1; isim — 2; əvəzlik — 2.');
INSERT INTO public.questions VALUES (9376, 121, 'g11-aze-zerf-q1-06', 1, 6, 'hard', 'single', '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 3; əvəzlik — 0", "B": "zərf — 1; isim — 4; əvəzlik — 0", "C": "zərf — 1; isim — 2; əvəzlik — 1", "D": "zərf — 2; isim — 1; əvəzlik — 0", "E": "zərf — 1; isim — 2; əvəzlik — 0"}'::jsonb, 'E', NULL, '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.»: «içəri» — yer zərfi, təyin. Düzgün: zərf — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9377, 121, 'g11-aze-zerf-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə 1 zərf işlənib, tərzi-hərəkət zərfi yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Hər kəs öz fikrini yazsın.", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Rəqib topu qəsdən kənara vurdu."}'::jsonb, 'E', NULL, '«Rəqib topu qəsdən kənara vurdu.»: «qəsdən» — məqsəd zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9378, 121, 'g11-aze-zerf-q1-08', 1, 8, 'hard', 'single', '«Babam təkbaşına dağa çıxmağı sevirdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 2; əvəzlik — 0", "B": "zərf — 1; isim — 2; əvəzlik — 1", "C": "zərf — 1; isim — 1; əvəzlik — 0", "D": "zərf — 1; isim — 3; əvəzlik — 0", "E": "zərf — 0; isim — 2; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Babam təkbaşına dağa çıxmağı sevirdi.»: «təkbaşına» — tərzi-hərəkət zərfi, vasitəsiz tamamlıq. Düzgün: zərf — 1; isim — 2; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9379, 121, 'g11-aze-zerf-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə tərzi-hərəkət zərfi var, məqsəd zərfi yoxdur və zərf var?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'D', NULL, '«Nağılı dinləyərkən uşaqlar bir-bir yatdılar.»: «bir-bir» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
