INSERT INTO public.questions VALUES (9397, 121, 'g11-aze-zerf-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir, kəmiyyət zərfi yoxdur, sifət yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Rəqib topu qəsdən kənara vurdu.", "B": "Ah, gəncliyimdə bu imkanlar olsaydı!", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "E": "Vay, pəncərənin şüşəsi küləkdən sındı!"}'::jsonb, 'A', NULL, '«Rəqib topu qəsdən kənara vurdu.»: «qəsdən» — məqsəd zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
