INSERT INTO public.questions VALUES (9399, 121, 'g11-aze-zerf-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə 1 zərf işlənib, məqsəd zərfi var, qoşma yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Babam təkbaşına dağa çıxmağı sevirdi.", "B": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "C": "Biz qatarı stansiyada xeyli gözlədik.", "D": "Rəqib topu qəsdən kənara vurdu.", "E": "Uşaqlar sakitcə nağılı dinləyirdilər."}'::jsonb, 'D', NULL, '«Rəqib topu qəsdən kənara vurdu.»: «qəsdən» — məqsəd zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9400, 121, 'g11-aze-zerf-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə tərzi-hərəkət zərfi var, kəmiyyət zərfi yoxdur, xəbər feillə ifadə olunub və feili sifət yoxdur?', NULL, NULL, '{"A": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "B": "Deməli, bütün çətinliklər arxada qaldı.", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Mən səni öz qardaşım kimi sevirəm.", "E": "Kitabın üçüncü fəslini iki-üç dəfə oxudum."}'::jsonb, 'C', NULL, '«Nağılı dinləyərkən uşaqlar bir-bir yatdılar.»: «bir-bir» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
