INSERT INTO public.questions VALUES (9442, 121, 'g11-aze-zerf-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə zərf feili sifət tərkibinin daxilindədir, kəmiyyət zərfi yoxdur, xəbər feillə ifadə olunub və feili bağlama var?', NULL, NULL, '{"A": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "E": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar."}'::jsonb, 'C', NULL, '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.»: «içəri» — yer zərfi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9443, 121, 'g11-aze-zerf-q3-13', 3, 13, 'hard', 'single', '«Rəqib topu qəsdən kənara vurdu.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 3; əvəzlik — 0", "B": "zərf — 2; isim — 2; əvəzlik — 0", "C": "zərf — 1; isim — 3; əvəzlik — 2", "D": "zərf — 1; isim — 4; əvəzlik — 0", "E": "zərf — 1; isim — 5; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Rəqib topu qəsdən kənara vurdu.»: «qəsdən» — məqsəd zərfi, zərflik. Düzgün: zərf — 1; isim — 3; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9444, 121, 'g11-aze-zerf-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə tərzi-hərəkət zərfi var, məqsəd zərfi yoxdur, xəbər feillə ifadə olunub və sifət yoxdur?', NULL, NULL, '{"A": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "B": "Ay bala, kitablarını rəfə yığ.", "C": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "D": "Kimin əlyazmasını muzeyə verdiniz?", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'A', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: «yan-yana» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9445, 121, 'g11-aze-zerf-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə 1 zərf işlənib, yer zərfi yoxdur, xəbər feillə ifadə olunub və say yoxdur?', NULL, NULL, '{"A": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "B": "Mən səni öz qardaşım kimi sevirəm.", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Axı siz bu kitabı oxumamısınız."}'::jsonb, 'C', NULL, '«Nağılı dinləyərkən uşaqlar bir-bir yatdılar.»: «bir-bir» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9446, 121, 'g11-aze-zerf-q3-16', 3, 16, 'hard', 'single', '«Rəqib topu qəsdən kənara vurdu.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 3; əvəzlik — 2", "B": "zərf — 1; isim — 3; əvəzlik — 0", "C": "zərf — 1; isim — 4; əvəzlik — 0", "D": "zərf — 2; isim — 3; əvəzlik — 0", "E": "zərf — 3; isim — 3; əvəzlik — 0"}'::jsonb, 'B', NULL, '«Rəqib topu qəsdən kənara vurdu.»: «qəsdən» — məqsəd zərfi, zərflik. Düzgün: zərf — 1; isim — 3; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9447, 121, 'g11-aze-zerf-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə tərzi-hərəkət zərfi var, 1 zərf işlənib, feili sifət yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Rəqib topu qəsdən kənara vurdu.", "C": "Görünür, yağış səhərə kimi dayanmayacaq.", "D": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "E": "Alim bu problemi təkbaşına araşdırdı."}'::jsonb, 'E', NULL, '«Alim bu problemi təkbaşına araşdırdı.»: «təkbaşına» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9448, 121, 'g11-aze-zerf-q3-18', 3, 18, 'hard', 'single', '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 3; isim — 4; əvəzlik — 0", "B": "zərf — 2; isim — 3; əvəzlik — 0", "C": "zərf — 0; isim — 4; əvəzlik — 0", "D": "zərf — 1; isim — 4; əvəzlik — 1", "E": "zərf — 1; isim — 4; əvəzlik — 0"}'::jsonb, 'E', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: «yan-yana» — tərzi-hərəkət zərfi, zərflik. Düzgün: zərf — 1; isim — 4; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9449, 121, 'g11-aze-zerf-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə yer zərfi var, tərzi-hərəkət zərfi yoxdur, qoşma yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Of, bu bitib-tükənməyən yol məni yordu!", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Bəs siz hansı universitetə sənəd vermisiniz?", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'C', NULL, '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.»: «içəri» — yer zərfi, təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9450, 121, 'g11-aze-zerf-q3-20', 3, 20, 'hard', 'single', '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 2; isim — 4; əvəzlik — 0", "B": "zərf — 1; isim — 5; əvəzlik — 0", "C": "zərf — 3; isim — 4; əvəzlik — 0", "D": "zərf — 0; isim — 4; əvəzlik — 0", "E": "zərf — 1; isim — 4; əvəzlik — 0"}'::jsonb, 'E', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: «yan-yana» — tərzi-hərəkət zərfi, zərflik. Düzgün: zərf — 1; isim — 4; əvəzlik — 0.');
INSERT INTO public.questions VALUES (9451, 121, 'g11-aze-zerf-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə kəmiyyət zərfi var, məqsəd zərfi yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Axı siz bu kitabı oxumamısınız.", "C": "Biz qatarı stansiyada xeyli gözlədik.", "D": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'C', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: «xeyli» — kəmiyyət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9452, 121, 'g11-aze-zerf-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə zərf müstəqil zərflik vəzifəsindədir, məqsəd zərfi yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'C', NULL, '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.»: «təkbaşına» — tərzi-hərəkət zərfi, zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9453, 121, 'g11-aze-zerf-q3-23', 3, 23, 'hard', 'single', '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "zərf — 1; isim — 2; əvəzlik — 0", "B": "zərf — 1; isim — 3; əvəzlik — 0", "C": "zərf — 1; isim — 4; əvəzlik — 0", "D": "zərf — 0; isim — 2; əvəzlik — 0", "E": "zərf — 3; isim — 2; əvəzlik — 0"}'::jsonb, 'A', NULL, '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.»: «içəri» — yer zərfi, təyin. Düzgün: zərf — 1; isim — 2; əvəzlik — 0.');
