INSERT INTO public.questions VALUES (9461, 122, 'g11-aze-qosma-q1-01', 1, 1, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9462, 122, 'g11-aze-qosma-q1-02', 1, 2, 'hard', 'single', '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9463, 122, 'g11-aze-qosma-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə qoşma var, yönlük halını idarə edən qoşma yoxdur və müraciət var?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Ay bala, kitablarını rəfə yığ.", "C": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "D": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'E', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9464, 122, 'g11-aze-qosma-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, «kimi» qoşması yönlük halını idarə edir, sifət yoxdur və təyin yoxdur?', NULL, NULL, '{"A": "Görünür, yağış səhərə kimi dayanmayacaq.", "B": "Ay bala, kitablarını rəfə yığ.", "C": "Karvan dənizə sarı irəliləyirdi.", "D": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "E": "Biz qatarı stansiyada xeyli gözlədik."}'::jsonb, 'A', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
