INSERT INTO public.questions VALUES (9477, 122, 'g11-aze-qosma-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə qoşma var, qoşma zərfliyin tərkibindədir, feili bağlama yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "D": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'B', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9478, 122, 'g11-aze-qosma-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, çıxışlıq halını idarə edən qoşma yoxdur, ədat yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "B": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "C": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'A', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9479, 122, 'g11-aze-qosma-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, yönlük halını idarə edən qoşma yoxdur, vasitəli tamamlıq yoxdur və qoşma var?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Mən səni öz qardaşım kimi sevirəm.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'E', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9480, 122, 'g11-aze-qosma-q1-20', 1, 20, 'hard', 'single', '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "E": "qoşma — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «savayı» — qoşma, çıxışlıq hal (idarə edir). Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9481, 122, 'g11-aze-qosma-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, yönlük halını idarə edən qoşma yoxdur və ədat var?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "C": "Axı siz bu kitabı oxumamısınız.", "D": "Mən səni öz qardaşım kimi sevirəm.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'A', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9482, 122, 'g11-aze-qosma-q1-22', 1, 22, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9483, 122, 'g11-aze-qosma-q1-23', 1, 23, 'hard', 'single', '«Mən səni öz qardaşım kimi sevirəm.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9484, 122, 'g11-aze-qosma-q1-24', 1, 24, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "C": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2.');
INSERT INTO public.questions VALUES (9485, 122, 'g11-aze-qosma-q1-25', 1, 25, 'hard', 'single', '«Mən səni öz qardaşım kimi sevirəm.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9486, 122, 'g11-aze-qosma-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə qoşma var, yönlük halını idarə edən qoşma yoxdur, nida yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Mən səni öz qardaşım kimi sevirəm.", "B": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "C": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "D": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'A', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9487, 122, 'g11-aze-qosma-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə qoşma var, yönlük halını idarə edən qoşma yoxdur və say var?', NULL, NULL, '{"A": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "B": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "C": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Bu işi üç nəfər bir həftəyə gördü.", "E": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi."}'::jsonb, 'C', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9488, 122, 'g11-aze-qosma-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, qoşma zərfliyin tərkibindədir, təyin var və say yoxdur?', NULL, NULL, '{"A": "Mən səni öz qardaşım kimi sevirəm.", "B": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "D": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "E": "Bəlkə, biz son qatara çatmayacağıq."}'::jsonb, 'D', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9489, 122, 'g11-aze-qosma-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, yönlük halını idarə edən qoşma yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Bu işi üç nəfər bir həftəyə gördü.", "B": "Afərin, sən yarışda birinci yeri tutdun!", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Rəqib topu qəsdən kənara vurdu."}'::jsonb, 'C', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9490, 122, 'g11-aze-qosma-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, çıxışlıq halını idarə edən qoşma yoxdur, ədat yoxdur və say yoxdur?', NULL, NULL, '{"A": "Əhsən, bu çətin yarışda hamını qabaqladın!", "B": "Alim bu problemi təkbaşına araşdırdı.", "C": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "D": "Bəlkə, biz son qatara çatmayacağıq.", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'C', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
