INSERT INTO public.questions VALUES (9496, 122, 'g11-aze-qosma-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, çıxışlıq halını idarə edən qoşma yoxdur və nida var?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Karvan dənizə sarı irəliləyirdi.", "D": "Mən səni öz qardaşım kimi sevirəm.", "E": "Ah, gəncliyimdə bu imkanlar olsaydı!"}'::jsonb, 'B', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9497, 122, 'g11-aze-qosma-q2-07', 2, 7, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "C": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'A', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2.');
INSERT INTO public.questions VALUES (9498, 122, 'g11-aze-qosma-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, yönlük halını idarə edən qoşma yoxdur və zərflik var?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Deməli, bütün çətinliklər arxada qaldı.", "C": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "E": "Ay bala, kitablarını rəfə yığ."}'::jsonb, 'D', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9499, 122, 'g11-aze-qosma-q2-09', 2, 9, 'hard', 'single', '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), təyin. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9500, 122, 'g11-aze-qosma-q2-10', 2, 10, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9501, 122, 'g11-aze-qosma-q2-11', 2, 11, 'hard', 'single', '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «savayı» — qoşma, çıxışlıq hal (idarə edir). Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9502, 122, 'g11-aze-qosma-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, çıxışlıq halını idarə edən qoşma yoxdur və mübtəda var?', NULL, NULL, '{"A": "Karvan dənizə sarı irəliləyirdi.", "B": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "C": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'A', NULL, '«Karvan dənizə sarı irəliləyirdi.»: «sarı» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9503, 122, 'g11-aze-qosma-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, qoşma var, xəbər feillə ifadə olunub və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Karvan dənizə sarı irəliləyirdi.", "C": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "D": "Mən səni öz qardaşım kimi sevirəm.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'D', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9504, 122, 'g11-aze-qosma-q2-14', 2, 14, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "qoşma — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'B', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2.');
INSERT INTO public.questions VALUES (9505, 122, 'g11-aze-qosma-q2-15', 2, 15, 'hard', 'single', '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9506, 122, 'g11-aze-qosma-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, yönlük halını idarə edən qoşma yoxdur, feili bağlama yoxdur və modal söz yoxdur?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "E": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin."}'::jsonb, 'D', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9507, 122, 'g11-aze-qosma-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, qoşma var və mübtəda var?', NULL, NULL, '{"A": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "E": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi."}'::jsonb, 'D', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
