INSERT INTO public.questions VALUES (9509, 122, 'g11-aze-qosma-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, yönlük halını idarə edən qoşma var, xəbər feillə ifadə olunub və təyin yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "C": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "D": "Ay bala, kitablarını rəfə yığ.", "E": "Rəqib topu qəsdən kənara vurdu."}'::jsonb, 'C', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9510, 122, 'g11-aze-qosma-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə qoşma var, yönlük halını idarə edən qoşma yoxdur, müraciət yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Bəlkə, biz son qatara çatmayacağıq.", "B": "Alim bu problemi təkbaşına araşdırdı.", "C": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "D": "Kimin əlyazmasını muzeyə verdiniz?", "E": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar."}'::jsonb, 'C', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «savayı» — qoşma, çıxışlıq hal (idarə edir). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9511, 122, 'g11-aze-qosma-q2-21', 2, 21, 'hard', 'single', '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 7; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 2; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9512, 122, 'g11-aze-qosma-q2-22', 2, 22, 'hard', 'single', '«Mən səni öz qardaşım kimi sevirəm.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9513, 122, 'g11-aze-qosma-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, yönlük halını idarə edən qoşma yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "C": "Babam təkbaşına dağa çıxmağı sevirdi.", "D": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "E": "Alim bu problemi təkbaşına araşdırdı."}'::jsonb, 'B', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), təyin. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9514, 122, 'g11-aze-qosma-q2-24', 2, 24, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9515, 122, 'g11-aze-qosma-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə qoşma var, çıxışlıq halını idarə edən qoşma yoxdur, ədat yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'B', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9516, 122, 'g11-aze-qosma-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə qoşma var, qoşma zərfliyin tərkibindədir və mübtəda var?', NULL, NULL, '{"A": "Bu işi üç nəfər bir həftəyə gördü.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "D": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Görünür, yağış səhərə kimi dayanmayacaq."}'::jsonb, 'E', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9517, 122, 'g11-aze-qosma-q2-27', 2, 27, 'hard', 'single', '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "E": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9518, 122, 'g11-aze-qosma-q2-28', 2, 28, 'hard', 'single', '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'D', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9519, 122, 'g11-aze-qosma-q2-29', 2, 29, 'hard', 'single', '«Mən səni öz qardaşım kimi sevirəm.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9520, 122, 'g11-aze-qosma-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, yönlük halını idarə edən qoşma yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "C": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "D": "Bəlkə, biz son qatara çatmayacağıq.", "E": "Məhz bu hadisədən sonra onun həyatı dəyişdi."}'::jsonb, 'E', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9521, 122, 'g11-aze-qosma-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə qoşma var, qoşma zərfliyin tərkibindədir, say yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Karvan dənizə sarı irəliləyirdi.", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Qardaşım həm rəssam, həm də musiqiçidir."}'::jsonb, 'B', NULL, '«Karvan dənizə sarı irəliləyirdi.»: «sarı» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9522, 122, 'g11-aze-qosma-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə qoşma var, yönlük halını idarə edən qoşma yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Babam təkbaşına dağa çıxmağı sevirdi.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'C', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9523, 122, 'g11-aze-qosma-q3-03', 3, 3, 'hard', 'single', '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9524, 122, 'g11-aze-qosma-q3-04', 3, 4, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 4", "E": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2.');
INSERT INTO public.questions VALUES (9525, 122, 'g11-aze-qosma-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə çıxışlıq halını idarə edən qoşma var, yönlük halını idarə edən qoşma yoxdur, sifət var və qoşma var?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "C": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'D', NULL, '«Kiçik qardaşımdan savayı hamı imtahandan keçdi.»: «savayı» — qoşma, çıxışlıq hal (idarə edir). Digər cümlələr şərtlərdən ən azı birini ödəmir.');
