INSERT INTO public.questions VALUES (9527, 122, 'g11-aze-qosma-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə qoşma zərfliyin tərkibindədir, yönlük halını idarə edən qoşma yoxdur, xəbər feillə ifadə olunub və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "C": "Uşaqlar sakitcə nağılı dinləyirdilər.", "D": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "E": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular."}'::jsonb, 'A', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9528, 122, 'g11-aze-qosma-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, qoşma zərfliyin tərkibindədir və sifət yoxdur?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "D": "Mən səni öz qardaşım kimi sevirəm.", "E": "Afərin, sən yarışda birinci yeri tutdun!"}'::jsonb, 'B', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9529, 122, 'g11-aze-qosma-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə qoşma var, yönlük halını idarə edən qoşma yoxdur, feili sifət yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "B": "Babam təkbaşına dağa çıxmağı sevirdi.", "C": "Görünür, yağış səhərə kimi dayanmayacaq.", "D": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "E": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar."}'::jsonb, 'D', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9530, 122, 'g11-aze-qosma-q3-10', 3, 10, 'hard', 'single', '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9531, 122, 'g11-aze-qosma-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə «kimi» qoşması yönlük halını idarə edir, yönlük halını idarə edən qoşma var, məsdər yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "B": "Görünür, yağış səhərə kimi dayanmayacaq.", "C": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "D": "Karvan dənizə sarı irəliləyirdi.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'B', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9532, 122, 'g11-aze-qosma-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, «kimi» qoşması yönlük halını idarə edir və təyin yoxdur?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Uşaqlar sakitcə nağılı dinləyirdilər.", "C": "Karvan dənizə sarı irəliləyirdi.", "D": "Görünür, yağış səhərə kimi dayanmayacaq.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'D', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9533, 122, 'g11-aze-qosma-q3-13', 3, 13, 'hard', 'single', '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), təyin. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9534, 122, 'g11-aze-qosma-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, qoşma zərfliyin tərkibindədir və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Mən səni öz qardaşım kimi sevirəm.", "C": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "E": "Məhz bu hadisədən sonra onun həyatı dəyişdi."}'::jsonb, 'C', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
