INSERT INTO public.questions VALUES (9545, 122, 'g11-aze-qosma-q3-25', 3, 25, 'hard', 'single', '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "C": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "D": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9546, 122, 'g11-aze-qosma-q3-26', 3, 26, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 4", "B": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'D', NULL, '«Məhz bu hadisədən sonra onun həyatı dəyişdi.»: «sonra» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2.');
INSERT INTO public.questions VALUES (9547, 122, 'g11-aze-qosma-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə yönlük halını idarə edən qoşma var, çıxışlıq halını idarə edən qoşma yoxdur, təyin yoxdur və qoşma var?', NULL, NULL, '{"A": "Uşaqlar sakitcə nağılı dinləyirdilər.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'E', NULL, '«Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.»: «qədər» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9548, 122, 'g11-aze-qosma-q3-28', 3, 28, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "qoşma — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "qoşma — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "qoşma — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: «bəri» — qoşma, çıxışlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9549, 122, 'g11-aze-qosma-q3-29', 3, 29, 'hard', 'single', '«Mən səni öz qardaşım kimi sevirəm.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "qoşma — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "qoşma — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "qoşma — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "qoşma — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Mən səni öz qardaşım kimi sevirəm.»: «kimi» — qoşma, adlıq hal (idarə edir), zərflik. Düzgün: qoşma — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9550, 122, 'g11-aze-qosma-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə qoşma var, çıxışlıq halını idarə edən qoşma yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "B": "Görünür, yağış səhərə kimi dayanmayacaq.", "C": "Bəlkə, biz son qatara çatmayacağıq.", "D": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "E": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub."}'::jsonb, 'B', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «kimi» — qoşma, yönlük hal (idarə edir), zərflik. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
