INSERT INTO public.questions VALUES (9558, 123, 'g11-aze-bag-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins zərflikləri bağlayır, qoşa (təkrarlanan) bağlayıcı işlənib, xəbər feillə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Axı siz bu kitabı oxumamısınız.", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Nə atam, nə də anam bu xəbəri eşitmişdi."}'::jsonb, 'B', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
