INSERT INTO public.questions VALUES (9569, 123, 'g11-aze-bag-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, qoşa (təkrarlanan) bağlayıcı işlənib və mübtəda var?', NULL, NULL, '{"A": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "D": "Uşaqlar sakitcə nağılı dinləyirdilər.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'B', NULL, '«Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.»: «nə» — bağlayıcı; «nə də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9570, 123, 'g11-aze-bag-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib, bağlayıcı var, mübtəda isimlə ifadə olunub və feili bağlama yoxdur?', NULL, NULL, '{"A": "Babam təkbaşına dağa çıxmağı sevirdi.", "B": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Qardaşım həm rəssam, həm də musiqiçidir.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'D', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9571, 123, 'g11-aze-bag-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, «nə» bağlayıcısı var və mübtəda var?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Qardaşım həm rəssam, həm də musiqiçidir."}'::jsonb, 'A', NULL, '«Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.»: «nə» — bağlayıcı; «nə də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9572, 123, 'g11-aze-bag-q1-22', 1, 22, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9573, 123, 'g11-aze-bag-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins zərflikləri bağlayır, qoşa (təkrarlanan) bağlayıcı işlənib və modal söz yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Qardaşım həm rəssam, həm də musiqiçidir.", "E": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'E', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9574, 123, 'g11-aze-bag-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib, «nə» bağlayıcısı var və qoşma yoxdur?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "C": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Vay, pəncərənin şüşəsi küləkdən sındı!", "E": "Qardaşım həm rəssam, həm də musiqiçidir."}'::jsonb, 'B', NULL, '«Nə atam, nə də anam bu xəbəri eşitmişdi.»: «Nə» — bağlayıcı; «nə də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9575, 123, 'g11-aze-bag-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə «ya» bağlayıcısı var, qoşa (təkrarlanan) bağlayıcı işlənib, sifət var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "C": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin."}'::jsonb, 'E', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9576, 123, 'g11-aze-bag-q1-26', 1, 26, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9577, 123, 'g11-aze-bag-q1-27', 1, 27, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9578, 123, 'g11-aze-bag-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə «və» bağlayıcısı var, bağlayıcı həmcins mübtədaları bağlayır, zərf yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "B": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9579, 123, 'g11-aze-bag-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə «həm» bağlayıcısı var, qoşa (təkrarlanan) bağlayıcı işlənib, xəbər feillə ifadə olunub və nida yoxdur?', NULL, NULL, '{"A": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "B": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "C": "Qardaşım həm rəssam, həm də musiqiçidir.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin."}'::jsonb, 'A', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9580, 123, 'g11-aze-bag-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə «ya» bağlayıcısı var, bağlayıcı həmcins vasitəsiz tamamlıqları bağlayır və nida yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "C": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'D', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9581, 123, 'g11-aze-bag-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, qoşa (təkrarlanan) bağlayıcı işlənib və mübtəda var?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "C": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Məhz bu hadisədən sonra onun həyatı dəyişdi."}'::jsonb, 'A', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9582, 123, 'g11-aze-bag-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə «həm» bağlayıcısı var, bağlayıcı var və təyin yoxdur?', NULL, NULL, '{"A": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Qardaşım həm rəssam, həm də musiqiçidir.", "D": "Karvan dənizə sarı irəliləyirdi.", "E": "Biz qatarı stansiyada xeyli gözlədik."}'::jsonb, 'C', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9583, 123, 'g11-aze-bag-q2-03', 2, 3, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "B": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9584, 123, 'g11-aze-bag-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə «ya» bağlayıcısı var, bağlayıcı həmcins vasitəsiz tamamlıqları bağlayır və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "D": "Hər kəs öz fikrini yazsın.", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'A', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9585, 123, 'g11-aze-bag-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins xəbərləri bağlayır, «həm» bağlayıcısı var, sifət yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Uşaqlar sakitcə nağılı dinləyirdilər.", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'B', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9586, 123, 'g11-aze-bag-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins mübtədaları bağlayır, «nə» bağlayıcısı var, müraciət yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Vay, pəncərənin şüşəsi küləkdən sındı!", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'C', NULL, '«Nə atam, nə də anam bu xəbəri eşitmişdi.»: «Nə» — bağlayıcı; «nə də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
