INSERT INTO public.questions VALUES (9588, 123, 'g11-aze-bag-q2-08', 2, 8, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'A', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9589, 123, 'g11-aze-bag-q2-09', 2, 9, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "bağlayıcı — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9590, 123, 'g11-aze-bag-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins zərflikləri bağlayır, «həm» bağlayıcısı var və mübtəda var?', NULL, NULL, '{"A": "Of, bu bitib-tükənməyən yol məni yordu!", "B": "Görünür, yağış səhərə kimi dayanmayacaq.", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "D": "Qardaşım həm rəssam, həm də musiqiçidir.", "E": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'E', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9591, 123, 'g11-aze-bag-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins mübtədaları bağlayır, bağlayıcı bir dəfə işlənib, məsdər yoxdur və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Bəlkə, biz son qatara çatmayacağıq."}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9592, 123, 'g11-aze-bag-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə «həm» bağlayıcısı var, bağlayıcı var, xəbər feillə ifadə olunmayıb və təyin yoxdur?', NULL, NULL, '{"A": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Qardaşım həm rəssam, həm də musiqiçidir.", "E": "Uşaqlar sakitcə nağılı dinləyirdilər."}'::jsonb, 'D', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9593, 123, 'g11-aze-bag-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə qoşa (təkrarlanan) bağlayıcı işlənib, «həm» bağlayıcısı var, nida yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Rəqib topu qəsdən kənara vurdu.", "E": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin."}'::jsonb, 'B', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9594, 123, 'g11-aze-bag-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə «nə» bağlayıcısı var, bağlayıcı var, feili bağlama yoxdur və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Bəlkə, biz son qatara çatmayacağıq.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'A', NULL, '«Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.»: «nə» — bağlayıcı; «nə də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9595, 123, 'g11-aze-bag-q2-15', 2, 15, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "B": "bağlayıcı — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'C', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
