INSERT INTO public.questions VALUES (9613, 123, 'g11-aze-bag-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, «həm» bağlayıcısı var və modal söz yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Qardaşım həm rəssam, həm də musiqiçidir.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'D', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
