INSERT INTO public.questions VALUES (9616, 123, 'g11-aze-bag-q3-06', 3, 6, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9617, 123, 'g11-aze-bag-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins mübtədaları bağlayır, bağlayıcı bir dəfə işlənib, modal söz yoxdur və sifət var?', NULL, NULL, '{"A": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9618, 123, 'g11-aze-bag-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins zərflikləri bağlayır, qoşa (təkrarlanan) bağlayıcı işlənib və say yoxdur?', NULL, NULL, '{"A": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Qardaşım həm rəssam, həm də musiqiçidir."}'::jsonb, 'B', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9619, 123, 'g11-aze-bag-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins mübtədaları bağlayır, bağlayıcı bir dəfə işlənib, zərflik var və nida yoxdur?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "B": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "C": "Görünür, yağış səhərə kimi dayanmayacaq.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
