INSERT INTO public.questions VALUES (9627, 123, 'g11-aze-bag-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, «həm» bağlayıcısı var, vasitəli tamamlıq yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Rəqib topu qəsdən kənara vurdu.", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Nə atam, nə də anam bu xəbəri eşitmişdi."}'::jsonb, 'B', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
