INSERT INTO public.questions VALUES (9630, 123, 'g11-aze-bag-q3-20', 3, 20, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9631, 123, 'g11-aze-bag-q3-21', 3, 21, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "bağlayıcı — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9632, 123, 'g11-aze-bag-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, qoşa (təkrarlanan) bağlayıcı işlənib və say yoxdur?', NULL, NULL, '{"A": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "B": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "C": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "D": "Babam təkbaşına dağa çıxmağı sevirdi.", "E": "Nə atam, nə də anam bu xəbəri eşitmişdi."}'::jsonb, 'E', NULL, '«Nə atam, nə də anam bu xəbəri eşitmişdi.»: «Nə» — bağlayıcı; «nə də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9633, 123, 'g11-aze-bag-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə bağlayıcı həmcins xəbərləri bağlayır, qoşa (təkrarlanan) bağlayıcı işlənib və zərflik yoxdur?', NULL, NULL, '{"A": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "B": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Qardaşım həm rəssam, həm də musiqiçidir."}'::jsonb, 'E', NULL, '«Qardaşım həm rəssam, həm də musiqiçidir.»: «həm» — bağlayıcı; «həm də» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9634, 123, 'g11-aze-bag-q3-24', 3, 24, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, «ya» bağlayıcısı var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'B', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9635, 123, 'g11-aze-bag-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə bağlayıcı var, «ya» bağlayıcısı var və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "B": "Afərin, sən yarışda birinci yeri tutdun!", "C": "Biz qatarı stansiyada xeyli gözlədik.", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Axı siz bu kitabı oxumamısınız."}'::jsonb, 'D', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9636, 123, 'g11-aze-bag-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə bağlayıcı bir dəfə işlənib, bağlayıcı həmcins mübtədaları bağlayır və say yoxdur?', NULL, NULL, '{"A": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "B": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "C": "Ay bala, kitablarını rəfə yığ.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Bəs siz hansı universitetə sənəd vermisiniz?"}'::jsonb, 'D', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9637, 123, 'g11-aze-bag-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə «ya» bağlayıcısı var, bağlayıcı həmcins vasitəsiz tamamlıqları bağlayır və modal söz yoxdur?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Bu işi üç nəfər bir həftəyə gördü.", "C": "Vay, pəncərənin şüşəsi küləkdən sındı!", "D": "Hər kəs öz fikrini yazsın.", "E": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı."}'::jsonb, 'A', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: «ya» — bağlayıcı; «ya da» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9638, 123, 'g11-aze-bag-q3-28', 3, 28, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "E": "bağlayıcı — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9639, 123, 'g11-aze-bag-q3-29', 3, 29, 'hard', 'single', '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "bağlayıcı — 0; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "bağlayıcı — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Düzgün: bağlayıcı — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9640, 123, 'g11-aze-bag-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə «və» bağlayıcısı var, bağlayıcı həmcins mübtədaları bağlayır və təyin var?', NULL, NULL, '{"A": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "B": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Bəs siz hansı universitetə sənəd vermisiniz?", "E": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin."}'::jsonb, 'B', NULL, '«Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.»: «və» — bağlayıcı. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9641, 124, 'g11-aze-edat-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə ədat var, «axı» ədatı işlənib və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Axı siz bu kitabı oxumamısınız.", "C": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Məhz bu hadisədən sonra onun həyatı dəyişdi."}'::jsonb, 'B', NULL, '«Axı siz bu kitabı oxumamısınız.»: «Axı» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9642, 124, 'g11-aze-edat-q1-02', 1, 2, 'hard', 'single', '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "ədat — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "B": "ədat — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "ədat — 4; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "ədat — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "ədat — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'D', NULL, '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.»: «Hətta» — ədat; «ən» — ədat. Düzgün: ədat — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2.');
INSERT INTO public.questions VALUES (9643, 124, 'g11-aze-edat-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə «ən» ədatı işlənib, ədat var, sifət var və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "D": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "E": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar."}'::jsonb, 'B', NULL, '«Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.»: «ən» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
