INSERT INTO public.questions VALUES (9663, 124, 'g11-aze-edat-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə ədat var, «yalnız» ədatı işlənib, zərflik yoxdur və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "D": "Axı siz bu kitabı oxumamısınız.", "E": "Bəs siz hansı universitetə sənəd vermisiniz?"}'::jsonb, 'A', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «yalnız» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9664, 124, 'g11-aze-edat-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə ədat var, «ən» ədatı işlənib və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "D": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'A', NULL, '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.»: «Hətta» — ədat; «ən» — ədat. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
