INSERT INTO public.questions VALUES (9754, 125, 'g11-aze-modal-q1-24', 1, 24, 'hard', 'single', '«Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 3; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 2; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "modal söz — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.»: «Əlbəttə» — modal söz. Düzgün: modal söz — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9755, 125, 'g11-aze-modal-q1-25', 1, 25, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 0; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «Məncə» — modal söz. Düzgün: modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9756, 125, 'g11-aze-modal-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə modal söz təəssüf bildirir, modal söz var və zərflik yoxdur?', NULL, NULL, '{"A": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "B": "Bəlkə, biz son qatara çatmayacağıq.", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "D": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "E": "Gördüyünüz kimi, bütün sənədlər hazırdır."}'::jsonb, 'D', NULL, '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.»: «Təəssüf ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9757, 125, 'g11-aze-modal-q1-27', 1, 27, 'hard', 'single', '«Görünür, yağış səhərə kimi dayanmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'D', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «Görünür» — modal söz. Düzgün: modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9758, 125, 'g11-aze-modal-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə modal söz var, modal söz ehtimal, şübhə bildirir və say var?', NULL, NULL, '{"A": "Görünür, yağış səhərə kimi dayanmayacaq.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Bəlkə, biz son qatara çatmayacağıq.", "E": "Afərin, sən yarışda birinci yeri tutdun!"}'::jsonb, 'C', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «Ehtimal ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9759, 125, 'g11-aze-modal-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir, modal söz cümlənin əvvəlindədir və müraciət yoxdur?', NULL, NULL, '{"A": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "B": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "C": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "D": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "E": "Görünür, yağış səhərə kimi dayanmayacaq."}'::jsonb, 'D', NULL, '«Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.»: «Əlbəttə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9760, 125, 'g11-aze-modal-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə modal söz var, modal söz cümlənin əvvəlindədir və ədat yoxdur?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Ah, gəncliyimdə bu imkanlar olsaydı!", "C": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'A', NULL, '«Deməli, bütün çətinliklər arxada qaldı.»: «Deməli» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
