INSERT INTO public.questions VALUES (9770, 125, 'g11-aze-modal-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, modal söz var, zərflik yoxdur və ədat var?', NULL, NULL, '{"A": "Bəlkə, biz son qatara çatmayacağıq.", "B": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "C": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Gördüyünüz kimi, bütün sənədlər hazırdır."}'::jsonb, 'D', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «Məncə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
