INSERT INTO public.questions VALUES (9772, 125, 'g11-aze-modal-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, modal söz fikrin kimə məxsus olduğunu bildirir, qoşma yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Bəlkə, biz son qatara çatmayacağıq.", "D": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "E": "Məncə, bu məsələni yalnız siz bizə anladarsınız."}'::jsonb, 'E', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «Məncə» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9773, 125, 'g11-aze-modal-q2-13', 2, 13, 'hard', 'single', '«Doğrudan da, sevdiyi işi görən insan yorulmur.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "modal söz — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: «Doğrudan da» — modal söz. Düzgün: modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9774, 125, 'g11-aze-modal-q2-14', 2, 14, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «Məncə» — modal söz. Düzgün: modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9775, 125, 'g11-aze-modal-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir, modal söz var, nida yoxdur və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Deməli, bütün çətinliklər arxada qaldı.", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "E": "Görünür, yağış səhərə kimi dayanmayacaq."}'::jsonb, 'C', NULL, '«Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.»: «Şübhəsiz» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
