INSERT INTO public.questions VALUES (9790, 125, 'g11-aze-modal-q2-30', 2, 30, 'hard', 'single', '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "C": "modal söz — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "modal söz — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.»: «Təəssüf ki» — modal söz. Düzgün: modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9791, 125, 'g11-aze-modal-q3-01', 3, 1, 'hard', 'single', '«Doğrudan da, sevdiyi işi görən insan yorulmur.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "modal söz — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: «Doğrudan da» — modal söz. Düzgün: modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9792, 125, 'g11-aze-modal-q3-02', 3, 2, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "modal söz — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "modal söz — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'E', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «Məncə» — modal söz. Düzgün: modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9793, 125, 'g11-aze-modal-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə modal söz cümlənin əvvəlindədir, modal söz var və bağlayıcı yoxdur?', NULL, NULL, '{"A": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "B": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "C": "Kiçik qardaşımdan savayı hamı imtahandan keçdi.", "D": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'A', NULL, '«Gördüyünüz kimi, bütün sənədlər hazırdır.»: «Gördüyünüz kimi» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9794, 125, 'g11-aze-modal-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə modal söz nəticə, yekun bildirir, modal söz var və feili sifət yoxdur?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Görünür, yağış səhərə kimi dayanmayacaq.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Bəlkə, biz son qatara çatmayacağıq."}'::jsonb, 'A', NULL, '«Deməli, bütün çətinliklər arxada qaldı.»: «Deməli» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9795, 125, 'g11-aze-modal-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə modal söz ehtimal, şübhə bildirir, modal söz cümlənin əvvəlindədir, zərflik var və mübtəda var?', NULL, NULL, '{"A": "Görünür, yağış səhərə kimi dayanmayacaq.", "B": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Deməli, bütün çətinliklər arxada qaldı.", "D": "Bəlkə, biz son qatara çatmayacağıq.", "E": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı."}'::jsonb, 'A', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «Görünür» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9796, 125, 'g11-aze-modal-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə modal söz təsdiq, qətiyyət bildirir, modal söz cümlənin əvvəlindədir, qoşma yoxdur və zərflik yoxdur?', NULL, NULL, '{"A": "Bəlkə, biz son qatara çatmayacağıq.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "E": "Məncə, bu məsələni yalnız siz bizə anladarsınız."}'::jsonb, 'D', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: «Doğrudan da» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
