INSERT INTO public.questions VALUES (9798, 125, 'g11-aze-modal-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə modal söz ehtimal, şübhə bildirir, modal söz var, feili bağlama yoxdur və say var?', NULL, NULL, '{"A": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "B": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "C": "Bəlkə, biz son qatara çatmayacağıq.", "D": "Görünür, yağış səhərə kimi dayanmayacaq.", "E": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir."}'::jsonb, 'B', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: «Ehtimal ki» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
