INSERT INTO public.questions VALUES (9808, 125, 'g11-aze-modal-q3-18', 3, 18, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "modal söz — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "modal söz — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "modal söz — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "modal söz — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Məncə, bu məsələni yalnız siz bizə anladarsınız.»: «Məncə» — modal söz. Düzgün: modal söz — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9809, 125, 'g11-aze-modal-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə modal söz ehtimal, şübhə bildirir, modal söz cümlənin əvvəlindədir, zərf yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Görünür, yağış səhərə kimi dayanmayacaq.", "D": "Bəlkə, biz son qatara çatmayacağıq.", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'C', NULL, '«Görünür, yağış səhərə kimi dayanmayacaq.»: «Görünür» — modal söz. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
