INSERT INTO public.questions VALUES (9825, 126, 'g11-aze-nida-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə çağırış (xitab) nidası işlənib, xəbər feillə ifadə olunub və nida var?', NULL, NULL, '{"A": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'B', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9826, 126, 'g11-aze-nida-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, modal söz yoxdur və say yoxdur?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "D": "Vay, pəncərənin şüşəsi küləkdən sındı!", "E": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular."}'::jsonb, 'D', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9827, 126, 'g11-aze-nida-q1-07', 1, 7, 'hard', 'single', '«Vay, pəncərənin şüşəsi küləkdən sındı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'A', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Düzgün: nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9828, 126, 'g11-aze-nida-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə nida var, müraciət yoxdur və cümlə nida cümləsidir?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "C": "Kimin əlyazmasını muzeyə verdiniz?", "D": "Ay bala, kitablarını rəfə yığ.", "E": "Afərin, sən yarışda birinci yeri tutdun!"}'::jsonb, 'E', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9829, 126, 'g11-aze-nida-q1-09', 1, 9, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9830, 126, 'g11-aze-nida-q1-10', 1, 10, 'hard', 'single', '«Əhsən, bu çətin yarışda hamını qabaqladın!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 0; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «Əhsən» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
