INSERT INTO public.questions VALUES (9833, 126, 'g11-aze-nida-q1-13', 1, 13, 'hard', 'single', '«Ay bala, kitablarını rəfə yığ.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'A', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Düzgün: nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
