INSERT INTO public.questions VALUES (9838, 126, 'g11-aze-nida-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə nida var, feili bağlama yoxdur və məsdər yoxdur?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "B": "Bu işi üç nəfər bir həftəyə gördü.", "C": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "D": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "E": "Afərin, sən yarışda birinci yeri tutdun!"}'::jsonb, 'E', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9839, 126, 'g11-aze-nida-q1-19', 1, 19, 'hard', 'single', '«Ura, uzun illər gözlədiyimiz qələbə gəldi!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'D', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9840, 126, 'g11-aze-nida-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, sifət yoxdur və feili sifət yoxdur?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Mən səni öz qardaşım kimi sevirəm.", "D": "Ah, gəncliyimdə bu imkanlar olsaydı!", "E": "Məncə, bu məsələni yalnız siz bizə anladarsınız."}'::jsonb, 'D', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9841, 126, 'g11-aze-nida-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, ədat yoxdur və sifət var?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Əhsən, bu çətin yarışda hamını qabaqladın!", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'B', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9842, 126, 'g11-aze-nida-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə nida var, təyin var, zərflik yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "B": "Hər kəs öz fikrini yazsın.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'E', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: «Ey» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9843, 126, 'g11-aze-nida-q1-23', 1, 23, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9844, 126, 'g11-aze-nida-q1-24', 1, 24, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9845, 126, 'g11-aze-nida-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, müraciət yoxdur, ədat yoxdur və sifət var?', NULL, NULL, '{"A": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "E": "Ura, uzun illər gözlədiyimiz qələbə gəldi!"}'::jsonb, 'E', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9846, 126, 'g11-aze-nida-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, qoşma yoxdur və zərflik yoxdur?', NULL, NULL, '{"A": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "B": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "C": "Əhsən, bu çətin yarışda hamını qabaqladın!", "D": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'E', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9847, 126, 'g11-aze-nida-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, müraciət yoxdur, mübtəda isimlə ifadə olunub və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "B": "Vay, pəncərənin şüşəsi küləkdən sındı!", "C": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "D": "Deməli, bütün çətinliklər arxada qaldı.", "E": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar."}'::jsonb, 'B', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9848, 126, 'g11-aze-nida-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə nida müraciətlə birlikdə işlənib, ədat yoxdur, vasitəsiz tamamlıq var və təyin var?', NULL, NULL, '{"A": "Hər kəs öz fikrini yazsın.", "B": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "C": "Ay bala, kitablarını rəfə yığ.", "D": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'D', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
