INSERT INTO public.questions VALUES (9862, 126, 'g11-aze-nida-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə çağırış (xitab) nidası işlənib, ədat yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "B": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "C": "Vay, pəncərənin şüşəsi küləkdən sındı!", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'B', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: «Ey» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9863, 126, 'g11-aze-nida-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə nida var, zərflik yoxdur və cümlə nida cümləsidir?', NULL, NULL, '{"A": "Afərin, sən yarışda birinci yeri tutdun!", "B": "Əhsən, bu çətin yarışda hamını qabaqladın!", "C": "Ah, gəncliyimdə bu imkanlar olsaydı!", "D": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Ura, uzun illər gözlədiyimiz qələbə gəldi!"}'::jsonb, 'E', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9864, 126, 'g11-aze-nida-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, feili sifət yoxdur, qoşma yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "B": "Vay, pəncərənin şüşəsi küləkdən sındı!", "C": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "D": "Alim bu problemi təkbaşına araşdırdı.", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'B', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9865, 126, 'g11-aze-nida-q2-15', 2, 15, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9866, 126, 'g11-aze-nida-q2-16', 2, 16, 'hard', 'single', '«Ay bala, kitablarını rəfə yığ.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 0; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "nida — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Düzgün: nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9867, 126, 'g11-aze-nida-q2-17', 2, 17, 'hard', 'single', '«Ura, uzun illər gözlədiyimiz qələbə gəldi!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 0; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9868, 126, 'g11-aze-nida-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, say var, ədat yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Kitabın üçüncü fəslini iki-üç dəfə oxudum."}'::jsonb, 'D', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9869, 126, 'g11-aze-nida-q2-19', 2, 19, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9870, 126, 'g11-aze-nida-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə nida var, qoşma yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Bəlkə, biz son qatara çatmayacağıq.", "B": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "C": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "D": "Ah, gəncliyimdə bu imkanlar olsaydı!", "E": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur."}'::jsonb, 'D', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9871, 126, 'g11-aze-nida-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə nida var, cümlə nida cümləsidir, feili sifət yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Ay bala, kitablarını rəfə yığ.", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Of, bu bitib-tükənməyən yol məni yordu!", "E": "Ura, uzun illər gözlədiyimiz qələbə gəldi!"}'::jsonb, 'C', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9872, 126, 'g11-aze-nida-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə nida var, vasitəli tamamlıq yoxdur, zərflik var və mübtəda var?', NULL, NULL, '{"A": "Alim bu problemi təkbaşına araşdırdı.", "B": "Afərin, sən yarışda birinci yeri tutdun!", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Deməli, bütün çətinliklər arxada qaldı."}'::jsonb, 'B', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9873, 126, 'g11-aze-nida-q2-23', 2, 23, 'hard', 'single', '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: «Ey» — nida. Düzgün: nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9874, 126, 'g11-aze-nida-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, müraciət yoxdur və qoşma yoxdur?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "E": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir."}'::jsonb, 'A', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9875, 126, 'g11-aze-nida-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə nida müraciətlə birlikdə işlənib, müraciət var və feili sifət yoxdur?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Ay bala, kitablarını rəfə yığ.", "C": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "D": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'B', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9876, 126, 'g11-aze-nida-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə nida var, sifət var və modal söz yoxdur?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Of, bu bitib-tükənməyən yol məni yordu!", "C": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "D": "Əhsən, bu çətin yarışda hamını qabaqladın!", "E": "Kiçik qardaşımdan savayı hamı imtahandan keçdi."}'::jsonb, 'D', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9877, 126, 'g11-aze-nida-q2-27', 2, 27, 'hard', 'single', '«Əhsən, bu çətin yarışda hamını qabaqladın!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 0; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'C', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «Əhsən» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9878, 126, 'g11-aze-nida-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, məsdər yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Bəs siz hansı universitetə sənəd vermisiniz?", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Rəqib topu qəsdən kənara vurdu.", "D": "Görünür, yağış səhərə kimi dayanmayacaq.", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'E', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9879, 126, 'g11-aze-nida-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə nida var, feili bağlama yoxdur və mübtəda var?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "B": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "C": "Rəqib topu qəsdən kənara vurdu.", "D": "Muzeydə qədim qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "E": "Of, bu bitib-tükənməyən yol məni yordu!"}'::jsonb, 'E', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9880, 126, 'g11-aze-nida-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə nida var, müraciət yoxdur, mübtəda yoxdur və təyin var?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Əhsən, bu çətin yarışda hamını qabaqladın!", "C": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq."}'::jsonb, 'B', NULL, '«Əhsən, bu çətin yarışda hamını qabaqladın!»: «Əhsən» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9881, 126, 'g11-aze-nida-q3-01', 3, 1, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9882, 126, 'g11-aze-nida-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, təyin var, cümlə nida cümləsidir və zərflik var?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Of, bu bitib-tükənməyən yol məni yordu!", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "E": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi."}'::jsonb, 'C', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9883, 126, 'g11-aze-nida-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə nida müraciətlə birlikdə işlənib, zərflik yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "B": "Hər kəs öz fikrini yazsın.", "C": "Kimin əlyazmasını muzeyə verdiniz?", "D": "Babam təkbaşına dağa çıxmağı sevirdi.", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'E', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: «Ey» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9884, 126, 'g11-aze-nida-q3-04', 3, 4, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2"}'::jsonb, 'A', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
