INSERT INTO public.questions VALUES (9886, 126, 'g11-aze-nida-q3-06', 3, 6, 'hard', 'single', '«Ura, uzun illər gözlədiyimiz qələbə gəldi!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9887, 126, 'g11-aze-nida-q3-07', 3, 7, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 0; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9888, 126, 'g11-aze-nida-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə nida müraciətlə birlikdə işlənib, müraciət var və ədat yoxdur?', NULL, NULL, '{"A": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "B": "Qardaşım həm rəssam, həm də musiqiçidir.", "C": "Ay bala, kitablarını rəfə yığ.", "D": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'C', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9889, 126, 'g11-aze-nida-q3-09', 3, 9, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "E": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9890, 126, 'g11-aze-nida-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, vasitəsiz tamamlıq yoxdur və sifət yoxdur?', NULL, NULL, '{"A": "Ah, gəncliyimdə bu imkanlar olsaydı!", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "E": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı."}'::jsonb, 'A', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9891, 126, 'g11-aze-nida-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə çağırış (xitab) nidası işlənib, say yoxdur və ədat yoxdur?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Əhsən, bu çətin yarışda hamını qabaqladın!", "C": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Ay bala, kitablarını rəfə yığ.", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'D', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9892, 126, 'g11-aze-nida-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, feili sifət yoxdur, vasitəli tamamlıq yoxdur və zərf yoxdur?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Of, bu bitib-tükənməyən yol məni yordu!", "C": "Axı siz bu kitabı oxumamısınız.", "D": "Ah, gəncliyimdə bu imkanlar olsaydı!", "E": "Hər kəs öz fikrini yazsın."}'::jsonb, 'D', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
