INSERT INTO public.questions VALUES (9894, 126, 'g11-aze-nida-q3-14', 3, 14, 'hard', 'single', '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 2; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "nida — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 3", "C": "nida — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "nida — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "nida — 2; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «Ey» — nida. Düzgün: nida — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9895, 126, 'g11-aze-nida-q3-15', 3, 15, 'hard', 'single', '«Ah, gəncliyimdə bu imkanlar olsaydı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'B', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9896, 126, 'g11-aze-nida-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə çağırış (xitab) nidası işlənib, mübtəda əvəzliklə ifadə olunub, say yoxdur və müraciət var?', NULL, NULL, '{"A": "Ay bala, kitablarını rəfə yığ.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Hər kəs öz fikrini yazsın.", "D": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'E', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9897, 126, 'g11-aze-nida-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə çağırış (xitab) nidası işlənib, bağlayıcı yoxdur, sifət yoxdur və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Ay bala, kitablarını rəfə yığ.", "B": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "C": "Axı siz bu kitabı oxumamısınız.", "D": "Bu işi üç nəfər bir həftəyə gördü.", "E": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar."}'::jsonb, 'A', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9898, 126, 'g11-aze-nida-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə nida müraciətsiz işlənib, ədat yoxdur, zərf yoxdur və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Bu işi üç nəfər bir həftəyə gördü.", "D": "Vay, pəncərənin şüşəsi küləkdən sındı!", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'D', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9899, 126, 'g11-aze-nida-q3-19', 3, 19, 'hard', 'single', '«Ay bala, kitablarını rəfə yığ.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "B": "nida — 0; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'E', NULL, '«Ay bala, kitablarını rəfə yığ.»: «Ay» — nida. Düzgün: nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9900, 126, 'g11-aze-nida-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, müraciət yoxdur, zərf yoxdur və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "D": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "E": "Deməli, bütün çətinliklər arxada qaldı."}'::jsonb, 'B', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9901, 126, 'g11-aze-nida-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, məsdər yoxdur, modal söz yoxdur və müraciət yoxdur?', NULL, NULL, '{"A": "Hər kəs öz fikrini yazsın.", "B": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "C": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "D": "Axı siz bu kitabı oxumamısınız.", "E": "Ura, uzun illər gözlədiyimiz qələbə gəldi!"}'::jsonb, 'E', NULL, '«Ura, uzun illər gözlədiyimiz qələbə gəldi!»: «Ura» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9902, 126, 'g11-aze-nida-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə hiss-həyəcan nidası işlənib, ədat yoxdur və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Of, bu bitib-tükənməyən yol məni yordu!", "B": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "C": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "D": "Karvan dənizə sarı irəliləyirdi.", "E": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq."}'::jsonb, 'A', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9903, 126, 'g11-aze-nida-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə nida var, qoşma yoxdur, vasitəli tamamlıq yoxdur və mübtəda var?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Biz qatarı stansiyada xeyli gözlədik.", "D": "Alim bu problemi təkbaşına araşdırdı.", "E": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı."}'::jsonb, 'B', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9904, 126, 'g11-aze-nida-q3-24', 3, 24, 'hard', 'single', '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 0; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "nida — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 1; isim — 6; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "D": "nida — 1; isim — 7; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "E": "nida — 2; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1"}'::jsonb, 'B', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: «Ey» — nida. Düzgün: nida — 1; isim — 5; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1.');
INSERT INTO public.questions VALUES (9905, 126, 'g11-aze-nida-q3-25', 3, 25, 'hard', 'single', '«Vay, pəncərənin şüşəsi küləkdən sındı!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 2; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 3; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Vay, pəncərənin şüşəsi küləkdən sındı!»: «Vay» — nida. Düzgün: nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9906, 126, 'g11-aze-nida-q3-26', 3, 26, 'hard', 'single', '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 3; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 4; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 3; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'D', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: «Ay» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9907, 126, 'g11-aze-nida-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə nida var, vasitəsiz tamamlıq yoxdur, vasitəli tamamlıq yoxdur və feili bağlama yoxdur?', NULL, NULL, '{"A": "Ay bala, kitablarını rəfə yığ.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "D": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "E": "Ah, gəncliyimdə bu imkanlar olsaydı!"}'::jsonb, 'E', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: «Ah» — nida. Digər cümlələr şərtlərdən ən azı birini ödəmir.');
INSERT INTO public.questions VALUES (9908, 126, 'g11-aze-nida-q3-28', 3, 28, 'hard', 'single', '«Afərin, sən yarışda birinci yeri tutdun!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "B": "nida — 2; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Afərin, sən yarışda birinci yeri tutdun!»: «Afərin» — nida. Düzgün: nida — 1; isim — 2; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9909, 126, 'g11-aze-nida-q3-29', 3, 29, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 1", "C": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 2", "D": "nida — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'A', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9910, 126, 'g11-aze-nida-q3-30', 3, 30, 'hard', 'single', '«Of, bu bitib-tükənməyən yol məni yordu!» cümləsindəki nitq hissələrinin sayı hansı variantda düzgün göstərilib?', NULL, NULL, '{"A": "nida — 2; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "B": "nida — 1; isim — 0; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "C": "nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "D": "nida — 2; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0", "E": "nida — 3; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0"}'::jsonb, 'C', NULL, '«Of, bu bitib-tükənməyən yol məni yordu!»: «Of» — nida. Düzgün: nida — 1; isim — 1; köməkçi nitq hissəsi (qoşma, bağlayıcı, ədat) — 0.');
INSERT INTO public.questions VALUES (9911, 127, 'g11-aze-member-q1-01', 1, 1, 'hard', 'single', '«Bəlkə, biz son qatara çatmayacağıq.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "biz — təyin; son — təyin; qatara — vasitəli tamamlıq; çatmayacağıq — xəbər", "B": "biz — mübtəda; son — təyin; qatara — vasitəli tamamlıq; çatmayacağıq — mübtəda", "C": "biz — vasitəsiz tamamlıq; son — təyin; qatara — vasitəli tamamlıq; çatmayacağıq — xəbər", "D": "biz — mübtəda; son — təyin; qatara — vasitəli tamamlıq; çatmayacağıq — xəbər", "E": "biz — mübtəda; son — təyin; qatara — zərflik; çatmayacağıq — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: biz — mübtəda; son — təyin; qatara — vasitəli tamamlıq; çatmayacağıq — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9912, 127, 'g11-aze-member-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəsiz tamamlıq var, vasitəsiz tamamlıq adlıq halda (qeyri-müəyyən) işlənib, mübtəda var və vasitəli tamamlıq yoxdur?', NULL, NULL, '{"A": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "B": "Alim bu problemi təkbaşına araşdırdı.", "C": "Rəqib topu qəsdən kənara vurdu.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "E": "Mən səni öz qardaşım kimi sevirəm."}'::jsonb, 'D', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: təyin — Doğma yurduna qayıdan; mübtəda — qaçqınlar; zərflik — müharibədən sonra; təyin — yeni; vasitəsiz tamamlıq — evlər; xəbər — tikdilər.');
INSERT INTO public.questions VALUES (9913, 127, 'g11-aze-member-q1-03', 1, 3, 'hard', 'single', '«Vay, pəncərənin şüşəsi küləkdən sındı!» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "pəncərənin — təyin; şüşəsi — mübtəda; küləkdən — zərflik; sındı — mübtəda", "B": "pəncərənin — təyin; şüşəsi — mübtəda; küləkdən — zərflik; sındı — xəbər", "C": "pəncərənin — mübtəda; şüşəsi — təyin; küləkdən — zərflik; sındı — xəbər", "D": "pəncərənin — təyin; şüşəsi — mübtəda; küləkdən — təyin; sındı — xəbər", "E": "pəncərənin — təyin; şüşəsi — mübtəda; küləkdən — vasitəli tamamlıq; sındı — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: pəncərənin — təyin; şüşəsi — mübtəda; küləkdən — zərflik; sındı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9914, 127, 'g11-aze-member-q1-04', 1, 4, 'hard', 'single', '«Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "gələcək — təyin; nəsillər — mübtəda; bu — təyin; qəhrəmanlığı — vasitəsiz tamamlıq; unutmasınlar — mübtəda", "B": "gələcək — təyin; nəsillər — mübtəda; bu — təyin; qəhrəmanlığı — vasitəsiz tamamlıq; unutmasınlar — xəbər", "C": "gələcək — vasitəsiz tamamlıq; nəsillər — mübtəda; bu — təyin; qəhrəmanlığı — təyin; unutmasınlar — xəbər", "D": "gələcək — təyin; nəsillər — mübtəda; bu — vasitəsiz tamamlıq; qəhrəmanlığı — təyin; unutmasınlar — xəbər", "E": "gələcək — mübtəda; nəsillər — təyin; bu — təyin; qəhrəmanlığı — vasitəsiz tamamlıq; unutmasınlar — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: gələcək — təyin; nəsillər — mübtəda; bu — təyin; qəhrəmanlığı — vasitəsiz tamamlıq; unutmasınlar — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9915, 127, 'g11-aze-member-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir, məsdərlə ifadə olunub və söz birləşməsinin (tərkibin) tərkib hissəsidir?', NULL, NULL, '{"A": "Babam təkbaşına dağa «çıxmağı» sevirdi.", "B": "Babam təkbaşına «dağa» çıxmağı sevirdi.", "C": "Babam «təkbaşına» dağa çıxmağı sevirdi.", "D": "Hətta ən təcrübəli alpinistlər bu zirvəyə «qalxmaqdan» çəkinirdilər.", "E": "Əlbəttə, ana dilini «qorumaq» vətəndaşlıq borcudur."}'::jsonb, 'A', NULL, '«çıxmağı» — vasitəsiz tamamlıq, məsdər. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9916, 127, 'g11-aze-member-q1-06', 1, 6, 'hard', 'single', '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "təcrübəli — təyin; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər", "B": "təcrübəli — təyin; alpinistlər — xəbər; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — mübtəda", "C": "təcrübəli — təyin; alpinistlər — təyin; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər", "D": "təcrübəli — xəbər; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — təyin", "E": "təcrübəli — təyin; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — təyin"}'::jsonb, 'A', NULL, 'Düzgün: təcrübəli — təyin; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9917, 127, 'g11-aze-member-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, xəbər feillə ifadə olunub, təyin yiyəlik halında olan isimlə ifadə olunub, vasitəsiz tamamlıq adlıq halda (qeyri-müəyyən) işlənib və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "C": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "D": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi."}'::jsonb, 'B', NULL, '«Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.»: təyin — Xalqımızın yetirdiyi dahi; mübtəda — şəxsiyyətlər; təyin — dünya; vasitəli tamamlıq — mədəniyyətinə; təyin — böyük; vasitəsiz tamamlıq — töhfələr; xəbər — veriblər.');
INSERT INTO public.questions VALUES (9918, 127, 'g11-aze-member-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir, isimlə ifadə olunub və söz birləşməsinin (tərkibin) tərkib hissəsidir?', NULL, NULL, '{"A": "Bəs siz hansı «universitetə» sənəd vermisiniz?", "B": "Beşinci sinifdən bəri Anar şahmat «dərnəyinə» gedir.", "C": "Şairin şeirləri həm ölkəmizdə, həm də «xaricdə» sevilir.", "D": "Karvan «dənizə» sarı irəliləyirdi.", "E": "Hətta ən təcrübəli alpinistlər bu «zirvəyə» qalxmaqdan çəkinirdilər."}'::jsonb, 'D', NULL, '«dənizə» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9919, 127, 'g11-aze-member-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəsiz tamamlıq vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Qoy gələcək nəsillər bu «qəhrəmanlığı» unutmasınlar.", "B": "Uzun illər xaricdə yaşayan «alim» doğma Vətənə qayıtdı.", "C": "Nağılı dinləyərkən «uşaqlar» bir-bir yatdılar.", "D": "Əlbəttə, ana dilini qorumaq «vətəndaşlıq» borcudur.", "E": "«Qardaşım» həm rəssam, həm də musiqiçidir."}'::jsonb, 'A', NULL, '«qəhrəmanlığı» — vasitəsiz tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9920, 127, 'g11-aze-member-q1-10', 1, 10, 'hard', 'single', '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "B": "Siz — mübtəda; tarixi — mübtəda; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "C": "Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — zərflik; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "D": "Siz — təyin; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "E": "Siz — mübtəda; tarixi — təyin; romanı — vasitəli tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər"}'::jsonb, 'A', NULL, 'Düzgün: Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9921, 127, 'g11-aze-member-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir, əvəzliklə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Bəlkə, «biz» son qatara çatmayacağıq.", "B": "Məhz bu hadisədən sonra «onun» həyatı dəyişdi.", "C": "Axı «siz» bu kitabı oxumamısınız.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra «yeni» evlər tikdilər.", "E": "Bəlkə, biz «son» qatara çatmayacağıq."}'::jsonb, 'B', NULL, '«onun» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9922, 127, 'g11-aze-member-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə həmcins vasitəsiz tamamlıqlar var, vasitəsiz tamamlıq var, təyin var və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Mən səni öz qardaşım kimi sevirəm.", "B": "Hər kəs öz fikrini yazsın.", "C": "Bəs siz hansı universitetə sənəd vermisiniz?", "D": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "E": "Məncə, bu məsələni yalnız siz bizə anladarsınız."}'::jsonb, 'D', NULL, '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.»: mübtəda — Siz; təyin — tarixi; vasitəsiz tamamlıq — romanı; təyin — elmi; vasitəsiz tamamlıq — əsəri; xəbər — təhlil edin.');
INSERT INTO public.questions VALUES (9923, 127, 'g11-aze-member-q1-13', 1, 13, 'hard', 'single', '«Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan — zərflik; alim — mübtəda; doğma — təyin; Vətənə — təyin; qayıtdı — xəbər", "B": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — zərflik; Vətənə — zərflik; qayıtdı — xəbər", "C": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər", "D": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — zərflik; Vətənə — təyin; qayıtdı — xəbər", "E": "Uzun illər xaricdə yaşayan — təyin; alim — təyin; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9924, 127, 'g11-aze-member-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, əvəzliklə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun «həyatı» dəyişdi.", "B": "Mən səni «öz» qardaşım kimi sevirəm.", "C": "«Siz» ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Nə «atam», nə də anam bu xəbəri eşitmişdi.", "E": "«Qardaşım» həm rəssam, həm də musiqiçidir."}'::jsonb, 'C', NULL, '«Siz» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9925, 127, 'g11-aze-member-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, vasitəli tamamlıq yoxdur, zərflik zərflə ifadə olunub, xəbər feillə ifadə olunub və vasitəsiz tamamlıq var?', NULL, NULL, '{"A": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "B": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "E": "Uşaqlar sakitcə nağılı dinləyirdilər."}'::jsonb, 'E', NULL, '«Uşaqlar sakitcə nağılı dinləyirdilər.»: mübtəda — Uşaqlar; zərflik — sakitcə; vasitəsiz tamamlıq — nağılı; xəbər — dinləyirdilər.');
INSERT INTO public.questions VALUES (9926, 127, 'g11-aze-member-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, təyin var, vasitəsiz tamamlıq var, təyin feili sifət və ya onun tərkibi ilə ifadə olunub və zərflik yoxdur?', NULL, NULL, '{"A": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "B": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "C": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "D": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "E": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar."}'::jsonb, 'E', NULL, '«Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.»: təyin — gələcək; mübtəda — nəsillər; təyin — bu; vasitəsiz tamamlıq — qəhrəmanlığı; xəbər — unutmasınlar.');
INSERT INTO public.questions VALUES (9927, 127, 'g11-aze-member-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə təyin yiyəlik halında olan isimlə ifadə olunub, mübtəda var, mübtəda isimlə ifadə olunub, xəbər feillə ifadə olunub və təyin feili sifət və ya onun tərkibi ilə ifadə olunub?', NULL, NULL, '{"A": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "B": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "C": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "E": "Vay, pəncərənin şüşəsi küləkdən sındı!"}'::jsonb, 'C', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: təyin — iki həftədən sonra başlayacaq; zərflik — müsabiqədə; təyin — on iki ölkənin; mübtəda — təmsilçiləri; xəbər — yarışacaq.');
INSERT INTO public.questions VALUES (9928, 127, 'g11-aze-member-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, vasitəsiz tamamlıq yoxdur, zərflik qoşmalı birləşmə ilə ifadə olunub və təyin sayla ifadə olunub?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Karvan dənizə sarı irəliləyirdi.", "C": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "D": "Görünür, yağış səhərə kimi dayanmayacaq.", "E": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'C', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: təyin — Beşinci; zərflik — sinifdən bəri; mübtəda — Anar; təyin — şahmat; zərflik — dərnəyinə; xəbər — gedir.');
INSERT INTO public.questions VALUES (9929, 127, 'g11-aze-member-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Şairin şeirləri həm «ölkəmizdə», həm də xaricdə sevilir.", "B": "Şairin şeirləri həm ölkəmizdə, həm də «xaricdə» sevilir.", "C": "«Şairin» şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Gördüyünüz kimi, bütün «sənədlər» hazırdır.", "E": "Bəs siz hansı universitetə «sənəd» vermisiniz?"}'::jsonb, 'D', NULL, '«sənədlər» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9930, 127, 'g11-aze-member-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə təyin sayla ifadə olunub, zərflik qoşmalı birləşmə ilə ifadə olunub, mübtəda isimlə ifadə olunub, xəbər feillə ifadə olunub və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "B": "Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.", "C": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "D": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Məhz bu hadisədən sonra onun həyatı dəyişdi."}'::jsonb, 'B', NULL, '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.»: təyin — Beşinci; zərflik — sinifdən bəri; mübtəda — Anar; təyin — şahmat; zərflik — dərnəyinə; xəbər — gedir.');
INSERT INTO public.questions VALUES (9931, 127, 'g11-aze-member-q1-21', 1, 21, 'hard', 'single', '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Doğma yurduna qayıdan — mübtəda; qaçqınlar — mübtəda; müharibədən sonra — zərflik; yeni — təyin; evlər — vasitəsiz tamamlıq; tikdilər — xəbər", "B": "Doğma yurduna qayıdan — təyin; qaçqınlar — zərflik; müharibədən sonra — mübtəda; yeni — təyin; evlər — vasitəsiz tamamlıq; tikdilər — xəbər", "C": "Doğma yurduna qayıdan — təyin; qaçqınlar — təyin; müharibədən sonra — zərflik; yeni — mübtəda; evlər — vasitəsiz tamamlıq; tikdilər — xəbər", "D": "Doğma yurduna qayıdan — təyin; qaçqınlar — mübtəda; müharibədən sonra — zərflik; yeni — təyin; evlər — vasitəsiz tamamlıq; tikdilər — xəbər", "E": "Doğma yurduna qayıdan — təyin; qaçqınlar — mübtəda; müharibədən sonra — xəbər; yeni — təyin; evlər — vasitəsiz tamamlıq; tikdilər — zərflik"}'::jsonb, 'D', NULL, 'Düzgün: Doğma yurduna qayıdan — təyin; qaçqınlar — mübtəda; müharibədən sonra — zərflik; yeni — təyin; evlər — vasitəsiz tamamlıq; tikdilər — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9932, 127, 'g11-aze-member-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, müraciət var, vasitəli tamamlıq yoxdur və zərflik var?', NULL, NULL, '{"A": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "E": "Görünür, yağış səhərə kimi dayanmayacaq."}'::jsonb, 'B', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: təyin — ata-babalarımızdan qalan bu müqəddəs; vasitəsiz tamamlıq — torpağı; təyin — göz; zərflik — bəbəyi kimi; xəbər — qoruyun.');
INSERT INTO public.questions VALUES (9933, 127, 'g11-aze-member-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir, feillə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Qardaşım həm «rəssam», həm də musiqiçidir.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq «borcudur».", "C": "Qardaşım həm rəssam, həm də «musiqiçidir».", "D": "Gördüyünüz kimi, bütün sənədlər «hazırdır».", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər «tikdilər»."}'::jsonb, 'E', NULL, '«tikdilər» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9934, 127, 'g11-aze-member-q1-24', 1, 24, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "bu — təyin; məsələni — vasitəsiz tamamlıq; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — mübtəda", "B": "bu — təyin; məsələni — xəbər; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — vasitəsiz tamamlıq", "C": "bu — vasitəsiz tamamlıq; məsələni — təyin; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — xəbər", "D": "bu — təyin; məsələni — vasitəsiz tamamlıq; siz — təyin; bizə — vasitəli tamamlıq; anladarsınız — xəbər", "E": "bu — təyin; məsələni — vasitəsiz tamamlıq; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: bu — təyin; məsələni — vasitəsiz tamamlıq; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9935, 127, 'g11-aze-member-q1-25', 1, 25, 'hard', 'single', '«Qardaşım həm rəssam, həm də musiqiçidir.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Qardaşım — xəbər; rəssam — xəbər; musiqiçidir — mübtəda", "B": "Qardaşım — xəbər; rəssam — mübtəda; musiqiçidir — xəbər", "C": "Qardaşım — təyin; rəssam — xəbər; musiqiçidir — xəbər", "D": "Qardaşım — mübtəda; rəssam — xəbər; musiqiçidir — xəbər", "E": "Qardaşım — mübtəda; rəssam — xəbər; musiqiçidir — mübtəda"}'::jsonb, 'D', NULL, 'Düzgün: Qardaşım — mübtəda; rəssam — xəbər; musiqiçidir — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9936, 127, 'g11-aze-member-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə zərflik feili bağlama və ya onun tərkibi ilə ifadə olunub, təyin yoxdur, vasitəsiz tamamlıq var və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Babam təkbaşına dağa çıxmağı sevirdi.", "B": "Uşaqlar sakitcə nağılı dinləyirdilər.", "C": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər.", "D": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "E": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar."}'::jsonb, 'E', NULL, '«Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.»: mübtəda — Tələbələr; zərflik — mühazirəni dinləyə-dinləyə; vasitəsiz tamamlıq — qeydlər; xəbər — aparırdılar.');
INSERT INTO public.questions VALUES (9937, 127, 'g11-aze-member-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir, isimlə ifadə olunub və söz birləşməsinin (tərkibin) tərkib hissəsidir?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi «küləkdən» sındı!", "B": "Əlbəttə, ana «dilini» qorumaq vətəndaşlıq borcudur.", "C": "Ay bala, kitablarını «rəfə» yığ.", "D": "Uzun illər xaricdə yaşayan alim doğma «Vətənə» qayıtdı.", "E": "Beşinci «sinifdən» bəri Anar şahmat dərnəyinə gedir."}'::jsonb, 'E', NULL, '«sinifdən» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9938, 127, 'g11-aze-member-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir, feillə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Gördüyünüz kimi, bütün sənədlər «hazırdır».", "B": "Bəlkə, biz son qatara «çatmayacağıq».", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq «borcudur».", "D": "Qardaşım həm «rəssam», həm də musiqiçidir.", "E": "Qardaşım həm rəssam, həm də «musiqiçidir»."}'::jsonb, 'B', NULL, '«çatmayacağıq» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9939, 127, 'g11-aze-member-q1-29', 1, 29, 'hard', 'single', '«Görünür, yağış səhərə kimi dayanmayacaq.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "yağış — mübtəda; səhərə kimi — vasitəli tamamlıq; dayanmayacaq — xəbər", "B": "yağış — mübtəda; səhərə kimi — zərflik; dayanmayacaq — xəbər", "C": "yağış — təyin; səhərə kimi — zərflik; dayanmayacaq — xəbər", "D": "yağış — mübtəda; səhərə kimi — xəbər; dayanmayacaq — zərflik", "E": "yağış — mübtəda; səhərə kimi — zərflik; dayanmayacaq — mübtəda"}'::jsonb, 'B', NULL, 'Düzgün: yağış — mübtəda; səhərə kimi — zərflik; dayanmayacaq — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9940, 127, 'g11-aze-member-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir, zərflə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan alim doğma «Vətənə» qayıtdı.", "B": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni «təkbaşına» həll etdi.", "C": "Ay bala, kitablarını «rəfə» yığ.", "D": "Şairin şeirləri həm «ölkəmizdə», həm də xaricdə sevilir.", "E": "Şairin şeirləri həm ölkəmizdə, həm də «xaricdə» sevilir."}'::jsonb, 'B', NULL, '«təkbaşına» — zərflik, zərf. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9941, 127, 'g11-aze-member-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəsiz tamamlıq yoxdur, təyin yiyəlik halında olan isimlə ifadə olunub, təyin sayla ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "C": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "D": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "E": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular."}'::jsonb, 'A', NULL, '«Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.»: təyin — iki həftədən sonra başlayacaq; zərflik — müsabiqədə; təyin — on iki ölkənin; mübtəda — təmsilçiləri; xəbər — yarışacaq.');
INSERT INTO public.questions VALUES (9942, 127, 'g11-aze-member-q2-02', 2, 2, 'hard', 'single', '«Ay bala, kitablarını rəfə yığ.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "kitablarını — mübtəda; rəfə — zərflik; yığ — xəbər", "B": "kitablarını — vasitəsiz tamamlıq; rəfə — zərflik; yığ — xəbər", "C": "kitablarını — vasitəsiz tamamlıq; rəfə — xəbər; yığ — zərflik", "D": "kitablarını — zərflik; rəfə — vasitəsiz tamamlıq; yığ — xəbər", "E": "kitablarını — vasitəsiz tamamlıq; rəfə — vasitəli tamamlıq; yığ — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: kitablarını — vasitəsiz tamamlıq; rəfə — zərflik; yığ — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9943, 127, 'g11-aze-member-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə zərflik zərflə ifadə olunub, təyin var, mübtəda isimlə ifadə olunub, xəbər feillə ifadə olunub və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "C": "Alim bu problemi təkbaşına araşdırdı.", "D": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "E": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular."}'::jsonb, 'E', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: təyin — Bayram süfrəsinin; zərflik — başında; mübtəda — uşaqlar; zərflik — yan-yana; xəbər — oturmuşdular.');
INSERT INTO public.questions VALUES (9944, 127, 'g11-aze-member-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə vasitəli tamamlıq əvəzliklə ifadə olunub, təyin var, vasitəsiz tamamlıq yoxdur və mübtəda var?', NULL, NULL, '{"A": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "B": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "C": "Deməli, bütün çətinliklər arxada qaldı.", "D": "Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'D', NULL, '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.»: təyin — təcrübəli; mübtəda — alpinistlər; vasitəli tamamlıq — bu zirvəyə qalxmaqdan; xəbər — çəkinirdilər.');
INSERT INTO public.questions VALUES (9945, 127, 'g11-aze-member-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə təyin əvəzliklə ifadə olunub, müraciət var, vasitəli tamamlıq yoxdur və təyin feili sifət və ya onun tərkibi ilə ifadə olunub?', NULL, NULL, '{"A": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar.", "B": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "D": "Of, bu bitib-tükənməyən yol məni yordu!", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'B', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: təyin — dünən sizin danışdığınız; vasitəsiz tamamlıq — hadisəni; mübtəda — heç kim; xəbər — unutmayacaq.');
INSERT INTO public.questions VALUES (9946, 127, 'g11-aze-member-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, əvəzliklə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Nə «atam», nə də anam bu xəbəri eşitmişdi.", "B": "Məhz bu hadisədən sonra «onun» həyatı dəyişdi.", "C": "Ay müəllim, dünən sizin danışdığınız hadisəni «heç kim» unutmayacaq.", "D": "Məhz «bu» hadisədən sonra onun həyatı dəyişdi.", "E": "Beşinci sinifdən bəri «Anar» şahmat dərnəyinə gedir."}'::jsonb, 'C', NULL, '«heç kim» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9947, 127, 'g11-aze-member-q2-07', 2, 7, 'hard', 'single', '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Şairin — təyin; şeirləri — mübtəda; ölkəmizdə — zərflik; xaricdə — zərflik; sevilir — xəbər", "B": "Şairin — təyin; şeirləri — mübtəda; ölkəmizdə — zərflik; xaricdə — təyin; sevilir — xəbər", "C": "Şairin — təyin; şeirləri — zərflik; ölkəmizdə — zərflik; xaricdə — mübtəda; sevilir — xəbər", "D": "Şairin — təyin; şeirləri — mübtəda; ölkəmizdə — zərflik; xaricdə — zərflik; sevilir — mübtəda", "E": "Şairin — xəbər; şeirləri — mübtəda; ölkəmizdə — zərflik; xaricdə — zərflik; sevilir — təyin"}'::jsonb, 'A', NULL, 'Düzgün: Şairin — təyin; şeirləri — mübtəda; ölkəmizdə — zərflik; xaricdə — zərflik; sevilir — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9948, 127, 'g11-aze-member-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, əvəzliklə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Bəs siz «hansı» universitetə sənəd vermisiniz?", "B": "Deməli, «bütün» çətinliklər arxada qaldı.", "C": "«Tələbələr» mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "D": "Axı «siz» bu kitabı oxumamısınız.", "E": "Alim «bu» problemi təkbaşına araşdırdı."}'::jsonb, 'D', NULL, '«siz» — mübtəda, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9949, 127, 'g11-aze-member-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəsiz tamamlıq var, zərflik qoşmalı birləşmə ilə ifadə olunub və təyin feili sifət və ya onun tərkibi ilə ifadə olunub?', NULL, NULL, '{"A": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "B": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "C": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "D": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "E": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar."}'::jsonb, 'B', NULL, '«Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.»: təyin — Doğma yurduna qayıdan; mübtəda — qaçqınlar; zərflik — müharibədən sonra; təyin — yeni; vasitəsiz tamamlıq — evlər; xəbər — tikdilər.');
INSERT INTO public.questions VALUES (9950, 127, 'g11-aze-member-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Əlbəttə, «ana» dilini qorumaq vətəndaşlıq borcudur.", "B": "«Babam» təkbaşına dağa çıxmağı sevirdi.", "C": "«Şairin» şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Bəs siz hansı «universitetə» sənəd vermisiniz?", "E": "Bu işi üç nəfər bir «həftəyə» gördü."}'::jsonb, 'B', NULL, '«Babam» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9951, 127, 'g11-aze-member-q2-11', 2, 11, 'hard', 'single', '«Kimin əlyazmasını muzeyə verdiniz?» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Kimin — xəbər; əlyazmasını — vasitəsiz tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — təyin", "B": "Kimin — vasitəsiz tamamlıq; əlyazmasını — təyin; muzeyə — vasitəli tamamlıq; verdiniz — xəbər", "C": "Kimin — təyin; əlyazmasını — vasitəli tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — xəbər", "D": "Kimin — təyin; əlyazmasını — vasitəsiz tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — xəbər", "E": "Kimin — təyin; əlyazmasını — vasitəsiz tamamlıq; muzeyə — vasitəsiz tamamlıq; verdiniz — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Kimin — təyin; əlyazmasını — vasitəsiz tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9952, 127, 'g11-aze-member-q2-12', 2, 12, 'hard', 'single', '«Hər kəs öz fikrini yazsın.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Hər kəs — vasitəsiz tamamlıq; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "B": "Hər kəs — vasitəsiz tamamlıq; öz — təyin; fikrini — mübtəda; yazsın — xəbər", "C": "Hər kəs — mübtəda; öz — mübtəda; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "D": "Hər kəs — mübtəda; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "E": "Hər kəs — mübtəda; öz — təyin; fikrini — mübtəda; yazsın — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Hər kəs — mübtəda; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9953, 127, 'g11-aze-member-q2-13', 2, 13, 'hard', 'single', '«Bu işi üç nəfər bir həftəyə gördü.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Bu — təyin; işi — vasitəsiz tamamlıq; üç — zərflik; nəfər — mübtəda; bir — təyin; həftəyə — təyin; gördü — xəbər", "B": "Bu — təyin; işi — vasitəsiz tamamlıq; üç — təyin; nəfər — mübtəda; bir — təyin; həftəyə — zərflik; gördü — xəbər", "C": "Bu — təyin; işi — vasitəsiz tamamlıq; üç — təyin; nəfər — vasitəsiz tamamlıq; bir — təyin; həftəyə — zərflik; gördü — xəbər", "D": "Bu — təyin; işi — təyin; üç — vasitəsiz tamamlıq; nəfər — mübtəda; bir — təyin; həftəyə — zərflik; gördü — xəbər", "E": "Bu — zərflik; işi — vasitəsiz tamamlıq; üç — təyin; nəfər — mübtəda; bir — təyin; həftəyə — zərflik; gördü — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: Bu — təyin; işi — vasitəsiz tamamlıq; üç — təyin; nəfər — mübtəda; bir — təyin; həftəyə — zərflik; gördü — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9954, 127, 'g11-aze-member-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə təyin feili sifət və ya onun tərkibi ilə ifadə olunub, vasitəli tamamlıq yoxdur, vasitəsiz tamamlıq var və zərflik var?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Alim bu problemi təkbaşına araşdırdı.", "C": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Kitabın üçüncü fəslini iki-üç dəfə oxudum.", "E": "Əhsən, bu çətin yarışda hamını qabaqladın!"}'::jsonb, 'A', NULL, '«Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!»: təyin — ata-babalarımızdan qalan bu müqəddəs; vasitəsiz tamamlıq — torpağı; təyin — göz; zərflik — bəbəyi kimi; xəbər — qoruyun.');
INSERT INTO public.questions VALUES (9955, 127, 'g11-aze-member-q2-15', 2, 15, 'hard', 'single', '«Hər kəs öz fikrini yazsın.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Hər kəs — mübtəda; öz — mübtəda; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "B": "Hər kəs — mübtəda; öz — təyin; fikrini — mübtəda; yazsın — xəbər", "C": "Hər kəs — mübtəda; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "D": "Hər kəs — mübtəda; öz — təyin; fikrini — vasitəli tamamlıq; yazsın — xəbər", "E": "Hər kəs — vasitəsiz tamamlıq; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Hər kəs — mübtəda; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9956, 127, 'g11-aze-member-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Nə «atam», nə də anam bu xəbəri eşitmişdi.", "B": "Şairin şeirləri həm ölkəmizdə, həm də «xaricdə» sevilir.", "C": "Ah, «gəncliyimdə» bu imkanlar olsaydı!", "D": "Şairin şeirləri həm «ölkəmizdə», həm də xaricdə sevilir.", "E": "Gənclər nə «çətinlikdən», nə də yorğunluqdan qorxurdular."}'::jsonb, 'A', NULL, '«atam» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9957, 127, 'g11-aze-member-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Şairin şeirləri həm ölkəmizdə, həm də «xaricdə» sevilir.", "B": "Gənclər nə «çətinlikdən», nə də yorğunluqdan qorxurdular.", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq «borcudur».", "D": "Nə atam, nə də «anam» bu xəbəri eşitmişdi.", "E": "Ah, «gəncliyimdə» bu imkanlar olsaydı!"}'::jsonb, 'D', NULL, '«anam» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9958, 127, 'g11-aze-member-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir, feillə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Qardaşım həm rəssam, həm də «musiqiçidir».", "B": "Alim bu problemi təkbaşına «araşdırdı».", "C": "Gördüyünüz kimi, bütün sənədlər «hazırdır».", "D": "Qardaşım həm «rəssam», həm də musiqiçidir.", "E": "Əlbəttə, ana dilini qorumaq vətəndaşlıq «borcudur»."}'::jsonb, 'B', NULL, '«araşdırdı» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9959, 127, 'g11-aze-member-q2-19', 2, 19, 'hard', 'single', '«Hətta ən təcrübəli alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "təcrübəli — təyin; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər", "B": "təcrübəli — təyin; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — mübtəda", "C": "təcrübəli — təyin; alpinistlər — təyin; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər", "D": "təcrübəli — mübtəda; alpinistlər — təyin; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər", "E": "təcrübəli — xəbər; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — təyin"}'::jsonb, 'A', NULL, 'Düzgün: təcrübəli — təyin; alpinistlər — mübtəda; bu zirvəyə qalxmaqdan — vasitəli tamamlıq; çəkinirdilər — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9960, 127, 'g11-aze-member-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir, feili bağlama ilə ifadə olunub və söz birləşməsinin (tərkibin) tərkib hissəsidir?', NULL, NULL, '{"A": "Tələbələr mühazirəni «dinləyə-dinləyə» qeydlər aparırdılar.", "B": "Məhz bu «hadisədən» sonra onun həyatı dəyişdi.", "C": "Tələbələr «mühazirəni» dinləyə-dinləyə qeydlər aparırdılar.", "D": "Mən səni öz «qardaşım» kimi sevirəm.", "E": "«Nağılı» dinləyərkən uşaqlar bir-bir yatdılar."}'::jsonb, 'A', NULL, '«dinləyə-dinləyə» — zərflik, feili bağlama. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9961, 127, 'g11-aze-member-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə təyin əvəzliklə ifadə olunub, vasitəsiz tamamlıq yoxdur, mübtəda var, zərflik var və xəbər feillə ifadə olunub?', NULL, NULL, '{"A": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "B": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "C": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "D": "Bəs siz hansı universitetə sənəd vermisiniz?", "E": "Fəhlələr səhərdən axşama qədər dayanmadan işlədilər."}'::jsonb, 'A', NULL, '«Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.»: təyin — Nənəmin bişirdiyi plovun; mübtəda — ətri; təyin — bütün; zərflik — evə; xəbər — yayılmışdı.');
INSERT INTO public.questions VALUES (9962, 127, 'g11-aze-member-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, zərflik var, təyin yiyəlik halında olan isimlə ifadə olunub və təyin sayla ifadə olunub?', NULL, NULL, '{"A": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "B": "Bu işi üç nəfər bir həftəyə gördü.", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "E": "Kitabın üçüncü fəslini iki-üç dəfə oxudum."}'::jsonb, 'E', NULL, '«Kitabın üçüncü fəslini iki-üç dəfə oxudum.»: təyin — Kitabın üçüncü; vasitəsiz tamamlıq — fəslini; təyin — iki-üç; zərflik — dəfə; xəbər — oxudum.');
INSERT INTO public.questions VALUES (9963, 127, 'g11-aze-member-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə təyin yiyəlik halında olan isimlə ifadə olunub, vasitəsiz tamamlıq yoxdur, mübtəda var, mübtəda isimlə ifadə olunub və həmcins zərfliklər var?', NULL, NULL, '{"A": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "C": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "D": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "E": "Vay, pəncərənin şüşəsi küləkdən sındı!"}'::jsonb, 'C', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: təyin — Şairin; mübtəda — şeirləri; zərflik — ölkəmizdə; zərflik — xaricdə; xəbər — sevilir.');
INSERT INTO public.questions VALUES (9964, 127, 'g11-aze-member-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir, sifətlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra «yeni» evlər tikdilər.", "B": "Hər kəs «öz» fikrini yazsın.", "C": "Axı siz «bu» kitabı oxumamısınız.", "D": "Afərin, sən yarışda «birinci» yeri tutdun!", "E": "«Şairin» şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'A', NULL, '«yeni» — təyin, sifət. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9965, 127, 'g11-aze-member-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "«Alim» bu problemi təkbaşına araşdırdı.", "B": "Şairin şeirləri həm «ölkəmizdə», həm də xaricdə sevilir.", "C": "Siz ya tarixi «romanı», ya da elmi əsəri təhlil edin.", "D": "Alim bu «problemi» təkbaşına araşdırdı.", "E": "Məncə, bu «məsələni» yalnız siz bizə anladarsınız."}'::jsonb, 'A', NULL, '«Alim» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9966, 127, 'g11-aze-member-q2-26', 2, 26, 'hard', 'single', '«Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — təyin", "B": "ana dilini qorumaq — vasitəsiz tamamlıq; vətəndaşlıq — təyin; borcudur — xəbər", "C": "ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — xəbər", "D": "ana dilini qorumaq — mübtəda; vətəndaşlıq — zərflik; borcudur — xəbər", "E": "ana dilini qorumaq — mübtəda; vətəndaşlıq — mübtəda; borcudur — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9967, 127, 'g11-aze-member-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Sinfimizin ən çalışqan şagirdi «beşdə dörd» hissəni təkbaşına həll etdi.", "B": "«Sinfimizin» ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "C": "Beşinci sinifdən bəri Anar şahmat «dərnəyinə» gedir.", "D": "Ura, uzun illər gözlədiyimiz «qələbə» gəldi!", "E": "Afərin, sən «yarışda» birinci yeri tutdun!"}'::jsonb, 'B', NULL, '«Sinfimizin» — təyin, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9968, 127, 'g11-aze-member-q2-28', 2, 28, 'hard', 'single', '«Məncə, bu məsələni yalnız siz bizə anladarsınız.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "bu — təyin; məsələni — vasitəsiz tamamlıq; siz — mübtəda; bizə — xəbər; anladarsınız — vasitəli tamamlıq", "B": "bu — mübtəda; məsələni — vasitəsiz tamamlıq; siz — təyin; bizə — vasitəli tamamlıq; anladarsınız — xəbər", "C": "bu — təyin; məsələni — vasitəsiz tamamlıq; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — xəbər", "D": "bu — təyin; məsələni — vasitəli tamamlıq; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — xəbər", "E": "bu — təyin; məsələni — xəbər; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — vasitəsiz tamamlıq"}'::jsonb, 'C', NULL, 'Düzgün: bu — təyin; məsələni — vasitəsiz tamamlıq; siz — mübtəda; bizə — vasitəli tamamlıq; anladarsınız — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9969, 127, 'g11-aze-member-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə təyin feili sifət və ya onun tərkibi ilə ifadə olunub, mübtəda var, vasitəsiz tamamlıq var, vasitəli tamamlıq yoxdur və mübtəda əvəzliklə ifadə olunub?', NULL, NULL, '{"A": "Afərin, sən yarışda birinci yeri tutdun!", "B": "Axı siz bu kitabı oxumamısınız.", "C": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "D": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Biz qatarı stansiyada xeyli gözlədik."}'::jsonb, 'D', NULL, '«Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.»: təyin — dünən sizin danışdığınız; vasitəsiz tamamlıq — hadisəni; mübtəda — heç kim; xəbər — unutmayacaq.');
INSERT INTO public.questions VALUES (9970, 127, 'g11-aze-member-q2-30', 2, 30, 'hard', 'single', '«Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "ana dilini qorumaq — xəbər; vətəndaşlıq — təyin; borcudur — mübtəda", "B": "ana dilini qorumaq — mübtəda; vətəndaşlıq — xəbər; borcudur — təyin", "C": "ana dilini qorumaq — mübtəda; vətəndaşlıq — mübtəda; borcudur — xəbər", "D": "ana dilini qorumaq — mübtəda; vətəndaşlıq — zərflik; borcudur — xəbər", "E": "ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9971, 127, 'g11-aze-member-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir, feili sifətlə ifadə olunub və söz birləşməsinin (tərkibin) tərkib hissəsidir?', NULL, NULL, '{"A": "Ay müəllim, dünən «sizin» danışdığınız hadisəni heç kim unutmayacaq.", "B": "«Uzun» illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "C": "Qoy «gələcək» nəsillər bu qəhrəmanlığı unutmasınlar.", "D": "Ura, «uzun» illər gözlədiyimiz qələbə gəldi!", "E": "Doğma yurduna «qayıdan» qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'E', NULL, '«qayıdan» — təyin, feili sifət. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9972, 127, 'g11-aze-member-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz təyin vəzifəsindədir, əvəzliklə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Bəlkə, biz «son» qatara çatmayacağıq.", "B": "«Kimin» əlyazmasını muzeyə verdiniz?", "C": "Bəlkə, «biz» son qatara çatmayacağıq.", "D": "«Mən» səni öz qardaşım kimi sevirəm.", "E": "Beşinci sinifdən bəri Anar «şahmat» dərnəyinə gedir."}'::jsonb, 'B', NULL, '«Kimin» — təyin, əvəzlik. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9973, 127, 'g11-aze-member-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə zərflik zərflə ifadə olunub, vasitəsiz tamamlıq yoxdur, xəbər feillə ifadə olunub və mübtəda var?', NULL, NULL, '{"A": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "B": "Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.", "C": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır.", "D": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular."}'::jsonb, 'A', NULL, '«Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.»: təyin — Bayram süfrəsinin; zərflik — başında; mübtəda — uşaqlar; zərflik — yan-yana; xəbər — oturmuşdular.');
INSERT INTO public.questions VALUES (9974, 127, 'g11-aze-member-q3-04', 3, 4, 'hard', 'single', '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Siz — vasitəsiz tamamlıq; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "B": "Siz — mübtəda; tarixi — təyin; romanı — xəbər; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — vasitəsiz tamamlıq", "C": "Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "D": "Siz — mübtəda; tarixi — təyin; romanı — təyin; elmi — vasitəsiz tamamlıq; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "E": "Siz — mübtəda; tarixi — vasitəsiz tamamlıq; romanı — təyin; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9975, 127, 'g11-aze-member-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, mübtəda isimlə ifadə olunub, vasitəsiz tamamlıq yoxdur və təyin var?', NULL, NULL, '{"A": "Ah, gəncliyimdə bu imkanlar olsaydı!", "B": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.", "C": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "D": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "E": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər."}'::jsonb, 'A', NULL, '«Ah, gəncliyimdə bu imkanlar olsaydı!»: zərflik — gəncliyimdə; təyin — bu; mübtəda — imkanlar; xəbər — olsaydı.');
INSERT INTO public.questions VALUES (9976, 127, 'g11-aze-member-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə təyin əvəzliklə ifadə olunub, zərflik yoxdur, müraciət var və mübtəda isimlə ifadə olunub?', NULL, NULL, '{"A": "Of, bu bitib-tükənməyən yol məni yordu!", "B": "Gördüyünüz kimi, bütün sənədlər hazırdır.", "C": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "D": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Qoy gələcək nəsillər bu qəhrəmanlığı unutmasınlar."}'::jsonb, 'C', NULL, '«Ey Vətən, sənin hər qarış torpağın müqəddəsdir!»: təyin — sənin hər qarış; mübtəda — torpağın; xəbər — müqəddəsdir.');
INSERT INTO public.questions VALUES (9977, 127, 'g11-aze-member-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, mübtəda var, zərflik yoxdur və təyin feili sifət və ya onun tərkibi ilə ifadə olunub?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "D": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "E": "Doğrudan da, sevdiyi işi görən insan yorulmur."}'::jsonb, 'E', NULL, '«Doğrudan da, sevdiyi işi görən insan yorulmur.»: təyin — sevdiyi işi görən; mübtəda — insan; xəbər — yorulmur.');
INSERT INTO public.questions VALUES (9978, 127, 'g11-aze-member-q3-08', 3, 8, 'hard', 'single', '«Beşinci sinifdən bəri Anar şahmat dərnəyinə gedir.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Beşinci — təyin; sinifdən bəri — zərflik; Anar — mübtəda; şahmat — təyin; dərnəyinə — zərflik; gedir — mübtəda", "B": "Beşinci — təyin; sinifdən bəri — təyin; Anar — mübtəda; şahmat — təyin; dərnəyinə — zərflik; gedir — xəbər", "C": "Beşinci — təyin; sinifdən bəri — zərflik; Anar — mübtəda; şahmat — mübtəda; dərnəyinə — zərflik; gedir — xəbər", "D": "Beşinci — təyin; sinifdən bəri — zərflik; Anar — mübtəda; şahmat — təyin; dərnəyinə — zərflik; gedir — xəbər", "E": "Beşinci — mübtəda; sinifdən bəri — zərflik; Anar — mübtəda; şahmat — təyin; dərnəyinə — zərflik; gedir — xəbər"}'::jsonb, 'D', NULL, 'Düzgün: Beşinci — təyin; sinifdən bəri — zərflik; Anar — mübtəda; şahmat — təyin; dərnəyinə — zərflik; gedir — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9979, 127, 'g11-aze-member-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, vasitəli tamamlıq yoxdur, təyin yiyəlik halında olan isimlə ifadə olunub və zərflik var?', NULL, NULL, '{"A": "Görünür, yağış səhərə kimi dayanmayacaq.", "B": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Bu işi üç nəfər bir həftəyə gördü.", "D": "Alim bu problemi təkbaşına araşdırdı.", "E": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'E', NULL, '«Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.»: təyin — Şairin; mübtəda — şeirləri; zərflik — ölkəmizdə; zərflik — xaricdə; xəbər — sevilir.');
INSERT INTO public.questions VALUES (9980, 127, 'g11-aze-member-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir, feillə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Qardaşım həm «rəssam», həm də musiqiçidir.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq «borcudur».", "C": "Gördüyünüz kimi, bütün sənədlər «hazırdır».", "D": "Qardaşım həm rəssam, həm də «musiqiçidir».", "E": "Uzun illər xaricdə yaşayan alim doğma Vətənə «qayıtdı»."}'::jsonb, 'E', NULL, '«qayıtdı» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9981, 127, 'g11-aze-member-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəli tamamlıq vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən, nə də «yorğunluqdan» qorxurdular.", "B": "Qoy gələcək nəsillər bu «qəhrəmanlığı» unutmasınlar.", "C": "Afərin, sən «yarışda» birinci yeri tutdun!", "D": "Bəs siz hansı universitetə «sənəd» vermisiniz?", "E": "Məncə, bu məsələni yalnız siz «bizə» anladarsınız."}'::jsonb, 'A', NULL, '«yorğunluqdan» — vasitəli tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9982, 127, 'g11-aze-member-q3-12', 3, 12, 'hard', 'single', '«Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — zərflik; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "B": "Siz — təyin; tarixi — mübtəda; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "C": "Siz — təyin; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — mübtəda; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər", "D": "Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — təyin", "E": "Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Siz — mübtəda; tarixi — təyin; romanı — vasitəsiz tamamlıq; elmi — təyin; əsəri — vasitəsiz tamamlıq; təhlil edin — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9983, 127, 'g11-aze-member-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz xəbər vəzifəsindədir, feillə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Əlbəttə, ana dilini qorumaq vətəndaşlıq «borcudur».", "B": "Qardaşım həm rəssam, həm də «musiqiçidir».", "C": "Qardaşım həm «rəssam», həm də musiqiçidir.", "D": "Gördüyünüz kimi, bütün sənədlər «hazırdır».", "E": "Məhz bu hadisədən sonra onun həyatı «dəyişdi»."}'::jsonb, 'E', NULL, '«dəyişdi» — xəbər, feil. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9984, 127, 'g11-aze-member-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz mübtəda vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Siz ya tarixi «romanı», ya da elmi əsəri təhlil edin.", "B": "Görünür, «yağış» səhərə kimi dayanmayacaq.", "C": "Bəs siz hansı universitetə «sənəd» vermisiniz?", "D": "Qoy gələcək nəsillər bu «qəhrəmanlığı» unutmasınlar.", "E": "Bu «işi» üç nəfər bir həftəyə gördü."}'::jsonb, 'B', NULL, '«yağış» — mübtəda, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9985, 127, 'g11-aze-member-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, zərflik var, vasitəsiz tamamlıq yoxdur, mübtəda isimlə ifadə olunub və təyin sayla ifadə olunub?', NULL, NULL, '{"A": "Məhz bu hadisədən sonra onun həyatı dəyişdi.", "B": "Karvan dənizə sarı irəliləyirdi.", "C": "Sinfimizin ən çalışqan şagirdi beşdə dörd hissəni təkbaşına həll etdi.", "D": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "E": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi."}'::jsonb, 'E', NULL, '«Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.»: zərflik — Yarışda; təyin — iyirmi yeddi ölkənin; mübtəda — idmançıları; xəbər — iştirak etdi.');
INSERT INTO public.questions VALUES (9986, 127, 'g11-aze-member-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, zərflik var, mübtəda əvəzliklə ifadə olunub, təyin yoxdur və zərflik zərflə ifadə olunub?', NULL, NULL, '{"A": "Uşaqlar sakitcə nağılı dinləyirdilər.", "B": "Biz qatarı stansiyada xeyli gözlədik.", "C": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "D": "Rəqib topu qəsdən kənara vurdu.", "E": "Karvan dənizə sarı irəliləyirdi."}'::jsonb, 'B', NULL, '«Biz qatarı stansiyada xeyli gözlədik.»: mübtəda — Biz; vasitəsiz tamamlıq — qatarı; zərflik — stansiyada xeyli; xəbər — gözlədik.');
INSERT INTO public.questions VALUES (9987, 127, 'g11-aze-member-q3-17', 3, 17, 'hard', 'single', '«Kimin əlyazmasını muzeyə verdiniz?» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Kimin — təyin; əlyazmasını — vasitəsiz tamamlıq; muzeyə — zərflik; verdiniz — xəbər", "B": "Kimin — vasitəli tamamlıq; əlyazmasını — vasitəsiz tamamlıq; muzeyə — təyin; verdiniz — xəbər", "C": "Kimin — təyin; əlyazmasını — vasitəsiz tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — xəbər", "D": "Kimin — təyin; əlyazmasını — xəbər; muzeyə — vasitəli tamamlıq; verdiniz — vasitəsiz tamamlıq", "E": "Kimin — təyin; əlyazmasını — vasitəli tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Kimin — təyin; əlyazmasını — vasitəsiz tamamlıq; muzeyə — vasitəli tamamlıq; verdiniz — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9988, 127, 'g11-aze-member-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə zərflik feili bağlama və ya onun tərkibi ilə ifadə olunub, mübtəda isimlə ifadə olunub, vasitəsiz tamamlıq yoxdur və təyin feili sifət və ya onun tərkibi ilə ifadə olunub?', NULL, NULL, '{"A": "Nağılı dinləyərkən uşaqlar bir-bir yatdılar.", "B": "Ehtimal ki, iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "C": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "D": "Gülə-gülə içəri girən qızlar müəllimi görcək susdular.", "E": "Dağların ətəyində yerləşən bu kiçik kənddə qədim adətlər yaşadılır."}'::jsonb, 'D', NULL, '«Gülə-gülə içəri girən qızlar müəllimi görcək susdular.»: təyin — Gülə-gülə içəri girən; mübtəda — qızlar; zərflik — müəllimi görcək; xəbər — susdular.');
INSERT INTO public.questions VALUES (9989, 127, 'g11-aze-member-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Şairin «şeirləri» həm ölkəmizdə, həm də xaricdə sevilir.", "B": "Doğma yurduna qayıdan «qaçqınlar» müharibədən sonra yeni evlər tikdilər.", "C": "Siz ya tarixi romanı, ya da elmi «əsəri» təhlil edin.", "D": "Uşaqlar «sakitcə» nağılı dinləyirdilər.", "E": "Vay, pəncərənin şüşəsi «küləkdən» sındı!"}'::jsonb, 'E', NULL, '«küləkdən» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9990, 127, 'g11-aze-member-q3-20', 3, 20, 'hard', 'single', '«Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — zərflik; Vətənə — təyin; qayıtdı — xəbər", "B": "Uzun illər xaricdə yaşayan — təyin; alim — vasitəsiz tamamlıq; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər", "C": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər", "D": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — vasitəli tamamlıq; qayıtdı — xəbər", "E": "Uzun illər xaricdə yaşayan — təyin; alim — təyin; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər"}'::jsonb, 'C', NULL, 'Düzgün: Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9991, 127, 'g11-aze-member-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə mübtəda isimlə ifadə olunub, vasitəsiz tamamlıq var, xəbər feillə ifadə olunub və vasitəli tamamlıq var?', NULL, NULL, '{"A": "Kimin əlyazmasını muzeyə verdiniz?", "B": "Uşaqlar sakitcə nağılı dinləyirdilər.", "C": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "D": "Doğma yurduna qayıdan qaçqınlar müharibədən sonra yeni evlər tikdilər.", "E": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'E', NULL, '«Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər.»: təyin — Xalqımızın yetirdiyi dahi; mübtəda — şəxsiyyətlər; təyin — dünya; vasitəli tamamlıq — mədəniyyətinə; təyin — böyük; vasitəsiz tamamlıq — töhfələr; xəbər — veriblər.');
INSERT INTO public.questions VALUES (9992, 127, 'g11-aze-member-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz zərflik vəzifəsindədir, isimlə ifadə olunub və söz birləşməsinin (tərkibin) tərkib hissəsidir?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər «arxada» qaldı.", "B": "Əlbəttə, ana «dilini» qorumaq vətəndaşlıq borcudur.", "C": "Görünür, yağış «səhərə» kimi dayanmayacaq.", "D": "Vay, pəncərənin şüşəsi «küləkdən» sındı!", "E": "Ay bala, kitablarını «rəfə» yığ."}'::jsonb, 'C', NULL, '«səhərə» — zərflik, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9993, 127, 'g11-aze-member-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə dırnaq içindəki söz vasitəli tamamlıq vəzifəsindədir, isimlə ifadə olunub və üzvü təkbaşına ifadə edir?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan «alim» doğma Vətənə qayıtdı.", "B": "«Qardaşım» həm rəssam, həm də musiqiçidir.", "C": "Siz ya tarixi romanı, ya da elmi «əsəri» təhlil edin.", "D": "Siz ya tarixi «romanı», ya da elmi əsəri təhlil edin.", "E": "Bəlkə, biz son «qatara» çatmayacağıq."}'::jsonb, 'E', NULL, '«qatara» — vasitəli tamamlıq, isim. (Tərkibin daxilindəki sözlər tərkibin bütövlükdə daşıdığı üzvün tərkibinə daxildir.)');
INSERT INTO public.questions VALUES (9994, 127, 'g11-aze-member-q3-24', 3, 24, 'hard', 'single', '«Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "ana dilini qorumaq — mübtəda; vətəndaşlıq — zərflik; borcudur — xəbər", "B": "ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — xəbər", "C": "ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — təyin", "D": "ana dilini qorumaq — mübtəda; vətəndaşlıq — xəbər; borcudur — təyin", "E": "ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — mübtəda"}'::jsonb, 'B', NULL, 'Düzgün: ana dilini qorumaq — mübtəda; vətəndaşlıq — təyin; borcudur — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9995, 127, 'g11-aze-member-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, mübtəda var, təyin sayla ifadə olunub, təyin yiyəlik halında olan isimlə ifadə olunub və vasitəsiz tamamlıq yoxdur?', NULL, NULL, '{"A": "Bayram süfrəsinin başında uşaqlar yan-yana oturmuşdular.", "B": "Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.", "C": "Vay, pəncərənin şüşəsi küləkdən sındı!", "D": "Nənəmin bişirdiyi plovun ətri bütün evə yayılmışdı.", "E": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir."}'::jsonb, 'B', NULL, '«Yarışda iyirmi yeddi ölkənin idmançıları iştirak etdi.»: zərflik — Yarışda; təyin — iyirmi yeddi ölkənin; mübtəda — idmançıları; xəbər — iştirak etdi.');
INSERT INTO public.questions VALUES (9996, 127, 'g11-aze-member-q3-26', 3, 26, 'hard', 'single', '«Babam təkbaşına dağa çıxmağı sevirdi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Babam — mübtəda; təkbaşına dağa çıxmağı — vasitəli tamamlıq; sevirdi — xəbər", "B": "Babam — mübtəda; təkbaşına dağa çıxmağı — xəbər; sevirdi — vasitəsiz tamamlıq", "C": "Babam — vasitəsiz tamamlıq; təkbaşına dağa çıxmağı — vasitəsiz tamamlıq; sevirdi — xəbər", "D": "Babam — mübtəda; təkbaşına dağa çıxmağı — vasitəsiz tamamlıq; sevirdi — xəbər", "E": "Babam — mübtəda; təkbaşına dağa çıxmağı — vasitəsiz tamamlıq; sevirdi — təyin"}'::jsonb, 'D', NULL, 'Düzgün: Babam — mübtəda; təkbaşına dağa çıxmağı — vasitəsiz tamamlıq; sevirdi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9997, 127, 'g11-aze-member-q3-27', 3, 27, 'hard', 'single', '«Hər kəs öz fikrini yazsın.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Hər kəs — mübtəda; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "B": "Hər kəs — mübtəda; öz — zərflik; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "C": "Hər kəs — mübtəda; öz — mübtəda; fikrini — vasitəsiz tamamlıq; yazsın — xəbər", "D": "Hər kəs — mübtəda; öz — vasitəsiz tamamlıq; fikrini — təyin; yazsın — xəbər", "E": "Hər kəs — mübtəda; öz — xəbər; fikrini — vasitəsiz tamamlıq; yazsın — təyin"}'::jsonb, 'A', NULL, 'Düzgün: Hər kəs — mübtəda; öz — təyin; fikrini — vasitəsiz tamamlıq; yazsın — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9998, 127, 'g11-aze-member-q3-28', 3, 28, 'hard', 'single', '«Uzun illər xaricdə yaşayan alim doğma Vətənə qayıtdı.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — vasitəli tamamlıq; qayıtdı — xəbər", "B": "Uzun illər xaricdə yaşayan — təyin; alim — təyin; doğma — mübtəda; Vətənə — zərflik; qayıtdı — xəbər", "C": "Uzun illər xaricdə yaşayan — zərflik; alim — mübtəda; doğma — təyin; Vətənə — təyin; qayıtdı — xəbər", "D": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — təyin; qayıtdı — xəbər", "E": "Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər"}'::jsonb, 'E', NULL, 'Düzgün: Uzun illər xaricdə yaşayan — təyin; alim — mübtəda; doğma — təyin; Vətənə — zərflik; qayıtdı — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (9999, 127, 'g11-aze-member-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə xəbər feillə ifadə olunub, vasitəsiz tamamlıq var, müraciət var, təyin yoxdur və zərflik var?', NULL, NULL, '{"A": "Biz qatarı stansiyada xeyli gözlədik.", "B": "Uşaqlar sakitcə nağılı dinləyirdilər.", "C": "Tələbələr mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Ay bala, kitablarını rəfə yığ."}'::jsonb, 'E', NULL, '«Ay bala, kitablarını rəfə yığ.»: vasitəsiz tamamlıq — kitablarını; zərflik — rəfə; xəbər — yığ.');
INSERT INTO public.questions VALUES (10000, 127, 'g11-aze-member-q3-30', 3, 30, 'hard', 'single', '«Məhz bu hadisədən sonra onun həyatı dəyişdi.» cümləsinin üzvlərinə görə təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "bu — təyin; hadisədən sonra — zərflik; onun — təyin; həyatı — təyin; dəyişdi — xəbər", "B": "bu — təyin; hadisədən sonra — zərflik; onun — təyin; həyatı — mübtəda; dəyişdi — xəbər", "C": "bu — zərflik; hadisədən sonra — zərflik; onun — təyin; həyatı — mübtəda; dəyişdi — xəbər", "D": "bu — təyin; hadisədən sonra — zərflik; onun — mübtəda; həyatı — mübtəda; dəyişdi — xəbər", "E": "bu — təyin; hadisədən sonra — zərflik; onun — zərflik; həyatı — mübtəda; dəyişdi — xəbər"}'::jsonb, 'B', NULL, 'Düzgün: bu — təyin; hadisədən sonra — zərflik; onun — təyin; həyatı — mübtəda; dəyişdi — xəbər. Tərkiblər və qoşmalı birləşmələr bütövlükdə bir üzv sayılır.');
INSERT INTO public.questions VALUES (10001, 128, 'g11-aze-complex-q1-01', 1, 1, 'hard', 'single', 'Hansı variantda budaq cümlə yer budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "C": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "D": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "E": "Harada ki zəhmət var, orada bərəkət də var."}'::jsonb, 'E', NULL, '«Harada ki zəhmət var, orada bərəkət də var.» — tabeli mürəkkəb cümlədir: budaq cümlə — yer, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10002, 128, 'g11-aze-complex-q1-02', 1, 2, 'hard', 'single', '«Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10003, 128, 'g11-aze-complex-q1-03', 1, 3, 'hard', 'single', '«Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10004, 128, 'g11-aze-complex-q1-04', 1, 4, 'hard', 'single', 'Hansı variantda budaq cümlə təyin budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir, cümlə tabeli mürəkkəbdir və budaq cümlə «ki» bağlayıcısı ilə bağlanıb?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'C', NULL, '«Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.» — tabeli mürəkkəb cümlədir: budaq cümlə — təyin, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10005, 128, 'g11-aze-complex-q1-05', 1, 5, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 2 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "B": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "E": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'B', NULL, '«Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (10006, 128, 'g11-aze-complex-q1-06', 1, 6, 'hard', 'single', '«Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10007, 128, 'g11-aze-complex-q1-07', 1, 7, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 3 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "B": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "C": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "D": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.", "E": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı."}'::jsonb, 'C', NULL, '«Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 3 komponent).');
INSERT INTO public.questions VALUES (10008, 128, 'g11-aze-complex-q1-08', 1, 8, 'hard', 'single', '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "C": "sadə cümlə", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10009, 128, 'g11-aze-complex-q1-09', 1, 9, 'hard', 'single', '«Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10010, 128, 'g11-aze-complex-q1-10', 1, 10, 'hard', 'single', 'Hansı variantda budaq cümlə tamamlıq budaq cümləsidir, budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'B', NULL, '«Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10011, 128, 'g11-aze-complex-q1-11', 1, 11, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə tabeli mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "C": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "D": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "E": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır."}'::jsonb, 'A', NULL, '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10012, 128, 'g11-aze-complex-q1-12', 1, 12, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "C": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "D": "Tələbələr mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.", "E": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi."}'::jsonb, 'D', NULL, '«Tələbələr mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.» — sadə cümlədir (həmcins xəbərlər).');
INSERT INTO public.questions VALUES (10013, 128, 'g11-aze-complex-q1-13', 1, 13, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10014, 128, 'g11-aze-complex-q1-14', 1, 14, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 2 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "B": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "C": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'B', NULL, '«Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (10015, 128, 'g11-aze-complex-q1-15', 1, 15, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10016, 128, 'g11-aze-complex-q1-16', 1, 16, 'hard', 'single', 'Hansı variantda budaq cümlə tamamlıq budaq cümləsidir, cümlə tabeli mürəkkəbdir, budaq cümlə baş cümlədən sonra gəlir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "B": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin."}'::jsonb, 'E', NULL, '«Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10017, 128, 'g11-aze-complex-q1-17', 1, 17, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "B": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "C": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşüb şəhərə tərəf getdilər.", "D": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "E": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'C', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşüb şəhərə tərəf getdilər.» — sadə cümlədir (feili bağlama tərkibi).');
INSERT INTO public.questions VALUES (10018, 128, 'g11-aze-complex-q1-18', 1, 18, 'hard', 'single', '«Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10019, 128, 'g11-aze-complex-q1-19', 1, 19, 'hard', 'single', 'Hansı variantda budaq cümlə «çünki» bağlayıcısı ilə bağlanıb, budaq cümlə baş cümlədən sonra gəlir, budaq cümlə səbəb budaq cümləsidir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "B": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "C": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'B', NULL, '«Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.» — tabeli mürəkkəb cümlədir: budaq cümlə — səbəb, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10020, 128, 'g11-aze-complex-q1-20', 1, 20, 'hard', 'single', '«Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "sadə cümlə", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent.');
INSERT INTO public.questions VALUES (10021, 128, 'g11-aze-complex-q1-21', 1, 21, 'hard', 'single', '«Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10022, 128, 'g11-aze-complex-q1-22', 1, 22, 'hard', 'single', 'Hansı variantda budaq cümlə məqsəd budaq cümləsidir, cümlə tabeli mürəkkəbdir, budaq cümlə baş cümlədən sonra gəlir və budaq cümlə «ki» bağlayıcısı ilə bağlanıb?', NULL, NULL, '{"A": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "B": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "D": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "E": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'D', NULL, '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10023, 128, 'g11-aze-complex-q1-23', 1, 23, 'hard', 'single', '«Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10024, 128, 'g11-aze-complex-q1-24', 1, 24, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə tabesiz mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "B": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "D": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "E": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin."}'::jsonb, 'A', NULL, '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (10025, 128, 'g11-aze-complex-q1-25', 1, 25, 'hard', 'single', '«Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10026, 128, 'g11-aze-complex-q1-26', 1, 26, 'hard', 'single', '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "sadə cümlə"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10027, 128, 'g11-aze-complex-q1-27', 1, 27, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 2 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.", "B": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "C": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "D": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "E": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı."}'::jsonb, 'A', NULL, '«Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (10028, 128, 'g11-aze-complex-q1-28', 1, 28, 'hard', 'single', '«Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10029, 128, 'g11-aze-complex-q1-29', 1, 29, 'hard', 'single', 'Hansı variantda budaq cümlə mübtəda budaq cümləsidir, budaq cümlə baş cümlədən sonra gəlir və budaq cümlə «ki» bağlayıcısı ilə bağlanıb?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.", "C": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "E": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı."}'::jsonb, 'D', NULL, '«Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10030, 128, 'g11-aze-complex-q1-30', 1, 30, 'hard', 'single', '«Harada ki zəhmət var, orada bərəkət də var.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10031, 128, 'g11-aze-complex-q2-01', 2, 1, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə tabesiz mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "B": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "C": "Harada ki zəhmət var, orada bərəkət də var.", "D": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "E": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar."}'::jsonb, 'B', NULL, '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (10032, 128, 'g11-aze-complex-q2-02', 2, 2, 'hard', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "B": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "C": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "D": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "E": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır."}'::jsonb, 'C', NULL, '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10033, 128, 'g11-aze-complex-q2-03', 2, 3, 'hard', 'single', '«Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10034, 128, 'g11-aze-complex-q2-04', 2, 4, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10035, 128, 'g11-aze-complex-q2-05', 2, 5, 'hard', 'single', 'Hansı variantda budaq cümlə səbəb budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir, cümlə tabeli mürəkkəbdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "B": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "C": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "D": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin."}'::jsonb, 'A', NULL, '«Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.» — tabeli mürəkkəb cümlədir: budaq cümlə — səbəb, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10036, 128, 'g11-aze-complex-q2-06', 2, 6, 'hard', 'single', '«Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10037, 128, 'g11-aze-complex-q2-07', 2, 7, 'hard', 'single', 'Hansı variantda budaq cümlə məqsəd budaq cümləsidir, cümlə tabeli mürəkkəbdir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə «ki» bağlayıcısı ilə bağlanıb?', NULL, NULL, '{"A": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "B": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.", "C": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "D": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "E": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq."}'::jsonb, 'B', NULL, '«Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10038, 128, 'g11-aze-complex-q2-08', 2, 8, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə 2 sadə cümlədən ibarətdir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "B": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "C": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "D": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Harada ki zəhmət var, orada bərəkət də var."}'::jsonb, 'B', NULL, '«Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.» — tabeli mürəkkəb cümlədir: budaq cümlə — təyin, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10039, 128, 'g11-aze-complex-q2-09', 2, 9, 'hard', 'single', 'Hansı variantda budaq cümlə yer budaq cümləsidir, budaq cümlə baş cümlədən əvvəl gəlir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "B": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "C": "Harada ki zəhmət var, orada bərəkət də var.", "D": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'C', NULL, '«Harada ki zəhmət var, orada bərəkət də var.» — tabeli mürəkkəb cümlədir: budaq cümlə — yer, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10040, 128, 'g11-aze-complex-q2-10', 2, 10, 'hard', 'single', '«Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10041, 128, 'g11-aze-complex-q2-11', 2, 11, 'hard', 'single', '«Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10042, 128, 'g11-aze-complex-q2-12', 2, 12, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, budaq cümlə baş cümlədən sonra gəlir və budaq cümlə məqsəd budaq cümləsidir?', NULL, NULL, '{"A": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "B": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "D": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "E": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin."}'::jsonb, 'D', NULL, '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10043, 128, 'g11-aze-complex-q2-13', 2, 13, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "B": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.", "C": "Həm müəllimlər, həm də şagirdlər yeni məktəb binasının açılışına toplaşmışdılar.", "D": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'C', NULL, '«Həm müəllimlər, həm də şagirdlər yeni məktəb binasının açılışına toplaşmışdılar.» — sadə cümlədir (həmcins mübtədalar).');
INSERT INTO public.questions VALUES (10044, 128, 'g11-aze-complex-q2-14', 2, 14, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Tələbələr mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.", "B": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "C": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "D": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "E": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq."}'::jsonb, 'A', NULL, '«Tələbələr mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.» — sadə cümlədir (həmcins xəbərlər).');
INSERT INTO public.questions VALUES (10045, 128, 'g11-aze-complex-q2-15', 2, 15, 'hard', 'single', '«Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10046, 128, 'g11-aze-complex-q2-16', 2, 16, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə tabeli mürəkkəbdir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə tamamlıq budaq cümləsidir?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "C": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı."}'::jsonb, 'D', NULL, '«Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.» — tabeli mürəkkəb cümlədir: budaq cümlə — tamamlıq, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10047, 128, 'g11-aze-complex-q2-17', 2, 17, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib, cümlə 3 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "B": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "C": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "D": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "E": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar."}'::jsonb, 'D', NULL, '«Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 3 komponent).');
INSERT INTO public.questions VALUES (10048, 128, 'g11-aze-complex-q2-18', 2, 18, 'hard', 'single', '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10049, 128, 'g11-aze-complex-q2-19', 2, 19, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10050, 128, 'g11-aze-complex-q2-20', 2, 20, 'hard', 'single', '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10051, 128, 'g11-aze-complex-q2-21', 2, 21, 'hard', 'single', '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "sadə cümlə", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10052, 128, 'g11-aze-complex-q2-22', 2, 22, 'hard', 'single', '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10053, 128, 'g11-aze-complex-q2-23', 2, 23, 'hard', 'single', '«Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10054, 128, 'g11-aze-complex-q2-24', 2, 24, 'hard', 'single', '«Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "sadə cümlə", "D": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent.');
INSERT INTO public.questions VALUES (10055, 128, 'g11-aze-complex-q2-25', 2, 25, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə tabesiz mürəkkəbdir və cümlə 3 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "B": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "C": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "D": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "E": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar."}'::jsonb, 'C', NULL, '«Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 3 komponent).');
INSERT INTO public.questions VALUES (10056, 128, 'g11-aze-complex-q2-26', 2, 26, 'hard', 'single', '«Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 3 komponent.');
INSERT INTO public.questions VALUES (10057, 128, 'g11-aze-complex-q2-27', 2, 27, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "B": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "C": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.", "D": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Harada ki zəhmət var, orada bərəkət də var."}'::jsonb, 'A', NULL, '«Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10058, 128, 'g11-aze-complex-q2-28', 2, 28, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "B": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşüb şəhərə tərəf getdilər.", "D": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi."}'::jsonb, 'C', NULL, '«Qatar stansiyaya çatan kimi sərnişinlər vaqonlardan düşüb şəhərə tərəf getdilər.» — sadə cümlədir (feili bağlama tərkibi).');
INSERT INTO public.questions VALUES (10059, 128, 'g11-aze-complex-q2-29', 2, 29, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.", "C": "Gördüklərini danışmaq istəyən uşaq həyəcandan sözlərini çaşdırırdı.", "D": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'C', NULL, '«Gördüklərini danışmaq istəyən uşaq həyəcandan sözlərini çaşdırırdı.» — sadə cümlədir (feili sifət tərkibi).');
INSERT INTO public.questions VALUES (10060, 128, 'g11-aze-complex-q2-30', 2, 30, 'hard', 'single', '«Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "sadə cümlə", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10061, 128, 'g11-aze-complex-q3-01', 3, 1, 'hard', 'single', '«Harada ki zəhmət var, orada bərəkət də var.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; yer budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10062, 128, 'g11-aze-complex-q3-02', 3, 2, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcı ilə əlaqələnib, cümlə 2 sadə cümlədən ibarətdir və cümlə tabesiz mürəkkəbdir?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "D": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi."}'::jsonb, 'C', NULL, '«Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.» — tabesiz mürəkkəb cümlədir (bağlayıcılı, 2 komponent).');
INSERT INTO public.questions VALUES (10063, 128, 'g11-aze-complex-q3-03', 3, 3, 'hard', 'single', '«Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10064, 128, 'g11-aze-complex-q3-04', 3, 4, 'hard', 'single', '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10065, 128, 'g11-aze-complex-q3-05', 3, 5, 'hard', 'single', '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; məqsəd budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10066, 128, 'g11-aze-complex-q3-06', 3, 6, 'hard', 'single', '«Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10067, 128, 'g11-aze-complex-q3-07', 3, 7, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10068, 128, 'g11-aze-complex-q3-08', 3, 8, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə tabeli mürəkkəbdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.", "B": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "C": "Harada ki zəhmət var, orada bərəkət də var.", "D": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'B', NULL, '«Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10069, 128, 'g11-aze-complex-q3-09', 3, 9, 'hard', 'single', '«Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10070, 128, 'g11-aze-complex-q3-10', 3, 10, 'hard', 'single', 'Hansı variantda budaq cümlə zaman budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Harada ki zəhmət var, orada bərəkət də var.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'E', NULL, '«Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.» — tabeli mürəkkəb cümlədir: budaq cümlə — zaman, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10071, 128, 'g11-aze-complex-q3-11', 3, 11, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "B": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "C": "Tələbələr mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.", "D": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "E": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım."}'::jsonb, 'C', NULL, '«Tələbələr mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.» — sadə cümlədir (həmcins xəbərlər).');
INSERT INTO public.questions VALUES (10072, 128, 'g11-aze-complex-q3-12', 3, 12, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, budaq cümlə baş cümlədən sonra gəlir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "B": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "C": "Harada ki zəhmət var, orada bərəkət də var.", "D": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'A', NULL, '«Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10073, 128, 'g11-aze-complex-q3-13', 3, 13, 'hard', 'single', '«Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10074, 128, 'g11-aze-complex-q3-14', 3, 14, 'hard', 'single', 'Hansı variantda budaq cümlə təyin budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə baş cümlədən sonra gəlir?', NULL, NULL, '{"A": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım."}'::jsonb, 'C', NULL, '«Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.» — tabeli mürəkkəb cümlədir: budaq cümlə — təyin, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10075, 128, 'g11-aze-complex-q3-15', 3, 15, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'D', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10076, 128, 'g11-aze-complex-q3-16', 3, 16, 'hard', 'single', 'Hansı variantda budaq cümlə mübtəda budaq cümləsidir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə «ki» bağlayıcısı ilə bağlanıb?', NULL, NULL, '{"A": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "B": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın."}'::jsonb, 'C', NULL, '«Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10077, 128, 'g11-aze-complex-q3-17', 3, 17, 'hard', 'single', 'Hansı variantda budaq cümlə yer budaq cümləsidir, budaq cümlə baş cümlədən əvvəl gəlir və cümlə tabeli mürəkkəbdir?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.", "B": "Harada ki zəhmət var, orada bərəkət də var.", "C": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "D": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "E": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq."}'::jsonb, 'B', NULL, '«Harada ki zəhmət var, orada bərəkət də var.» — tabeli mürəkkəb cümlədir: budaq cümlə — yer, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10078, 128, 'g11-aze-complex-q3-18', 3, 18, 'hard', 'single', '«Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən sonra", "C": "tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "E": "tabeli mürəkkəb cümlə; səbəb budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'C', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; güzəşt budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10079, 128, 'g11-aze-complex-q3-19', 3, 19, 'hard', 'single', '«Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra", "B": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən əvvəl", "D": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "E": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; mübtəda budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10080, 128, 'g11-aze-complex-q3-20', 3, 20, 'hard', 'single', 'Hansı variantda budaq cümlə «çünki» bağlayıcısı ilə bağlanıb, budaq cümlə baş cümlədən sonra gəlir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə səbəb budaq cümləsidir?', NULL, NULL, '{"A": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "B": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "C": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "E": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'A', NULL, '«Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.» — tabeli mürəkkəb cümlədir: budaq cümlə — səbəb, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10081, 128, 'g11-aze-complex-q3-21', 3, 21, 'hard', 'single', '«Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "B": "tabesiz mürəkkəb cümlə; bağlayıcısız; 3 komponent", "C": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən sonra", "D": "sadə cümlə", "E": "tabesiz mürəkkəb cümlə; bağlayıcısız; 2 komponent"}'::jsonb, 'A', NULL, 'Düzgün təhlil: tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent.');
INSERT INTO public.questions VALUES (10082, 128, 'g11-aze-complex-q3-22', 3, 22, 'hard', 'single', 'Hansı variantda budaq cümlə mübtəda budaq cümləsidir, cümlə tabeli mürəkkəbdir və cümlə 2 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "B": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.", "C": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "D": "Harada ki zəhmət var, orada bərəkət də var.", "E": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq."}'::jsonb, 'E', NULL, '«Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.» — tabeli mürəkkəb cümlədir: budaq cümlə — mübtəda, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10083, 128, 'g11-aze-complex-q3-23', 3, 23, 'hard', 'single', 'Hansı variantda budaq cümlə güzəşt budaq cümləsidir, cümlə tabeli mürəkkəbdir və budaq cümlə baş cümlədən əvvəl gəlir?', NULL, NULL, '{"A": "Harada ki zəhmət var, orada bərəkət də var.", "B": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "C": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "D": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "E": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq."}'::jsonb, 'C', NULL, '«Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.» — tabeli mürəkkəb cümlədir: budaq cümlə — güzəşt, baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10084, 128, 'g11-aze-complex-q3-24', 3, 24, 'hard', 'single', '«Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "C": "tabeli mürəkkəb cümlə; zaman budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; şərt budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; kəmiyyət budaq cümləsi; budaq baş cümlədən əvvəl.');
INSERT INTO public.questions VALUES (10085, 128, 'g11-aze-complex-q3-25', 3, 25, 'hard', 'single', 'Hansı variantda budaq cümlə «ki» bağlayıcısı ilə bağlanıb, cümlə tabeli mürəkkəbdir, cümlə 2 sadə cümlədən ibarətdir və budaq cümlə məqsəd budaq cümləsidir?', NULL, NULL, '{"A": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın."}'::jsonb, 'E', NULL, '«Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.» — tabeli mürəkkəb cümlədir: budaq cümlə — məqsəd, baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10086, 128, 'g11-aze-complex-q3-26', 3, 26, 'hard', 'single', 'Hansı variantda tabesiz mürəkkəb cümlənin komponentləri bağlayıcısız (intonasiya ilə) əlaqələnib, cümlə tabesiz mürəkkəbdir və cümlə 3 sadə cümlədən ibarətdir?', NULL, NULL, '{"A": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "B": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "C": "Səhər tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "D": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "E": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar."}'::jsonb, 'D', NULL, '«Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.» — tabesiz mürəkkəb cümlədir (bağlayıcısız, 3 komponent).');
INSERT INTO public.questions VALUES (10087, 128, 'g11-aze-complex-q3-27', 3, 27, 'hard', 'single', '«Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra", "C": "tabesiz mürəkkəb cümlə; bağlayıcılı; 2 komponent", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "E": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl"}'::jsonb, 'B', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10088, 128, 'g11-aze-complex-q3-28', 3, 28, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Gördüklərini danışmaq istəyən uşaq həyəcandan sözlərini çaşdırırdı.", "B": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "E": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar."}'::jsonb, 'A', NULL, '«Gördüklərini danışmaq istəyən uşaq həyəcandan sözlərini çaşdırırdı.» — sadə cümlədir (feili sifət tərkibi).');
INSERT INTO public.questions VALUES (10089, 128, 'g11-aze-complex-q3-29', 3, 29, 'hard', 'single', '«Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.» cümləsinin təhlili hansı variantda düzgün verilib?', NULL, NULL, '{"A": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən əvvəl", "B": "tabeli mürəkkəb cümlə; tamamlıq budaq cümləsi; budaq baş cümlədən əvvəl", "C": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən sonra", "D": "tabeli mürəkkəb cümlə; xəbər budaq cümləsi; budaq baş cümlədən əvvəl", "E": "tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra"}'::jsonb, 'E', NULL, 'Düzgün təhlil: tabeli mürəkkəb cümlə; təyin budaq cümləsi; budaq baş cümlədən sonra.');
INSERT INTO public.questions VALUES (10090, 128, 'g11-aze-complex-q3-30', 3, 30, 'hard', 'single', 'Hansı variantda cümlə sadədir və cümlədə bir xəbər mərkəzi var?', NULL, NULL, '{"A": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "B": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Həm müəllimlər, həm də şagirdlər yeni məktəb binasının açılışına toplaşmışdılar.", "D": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "E": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'C', NULL, '«Həm müəllimlər, həm də şagirdlər yeni məktəb binasının açılışına toplaşmışdılar.» — sadə cümlədir (həmcins mübtədalar).');
INSERT INTO public.questions VALUES (10091, 129, 'g11-aze-punct-q1-01', 1, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı.", "C": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "D": "Məlumdur ki Azərbaycan zəngin təbii sərvətlərə malikdir.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın."}'::jsonb, 'A', NULL, 'Düzgün: «Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10092, 129, 'g11-aze-punct-q1-02', 1, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Ah, gəncliyimdə bu imkanlar olsaydı!", "B": "Ay bala kitablarını rəfə yığ.", "C": "Vay, pəncərənin şüşəsi küləkdən sındı!", "D": "Ey gənclər ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'E', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10093, 129, 'g11-aze-punct-q1-03', 1, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "B": "Kim ki elmə dəyər verir, o heç vaxt geri qalmır.", "C": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "D": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım."}'::jsonb, 'E', NULL, 'Düzgün: «Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10094, 129, 'g11-aze-punct-q1-04', 1, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "B": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Hamıya aydın idi ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır."}'::jsonb, 'D', NULL, 'Düzgün: «Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10095, 129, 'g11-aze-punct-q1-05', 1, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır.", "B": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "D": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "E": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq."}'::jsonb, 'C', NULL, 'Düzgün: «Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10096, 129, 'g11-aze-punct-q1-06', 1, 6, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Elə ki imtahanlar başa çatdı tələbələr doğma kəndlərinə yola düşdülər.", "B": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "C": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Kim ki elmə dəyər verir, o heç vaxt geri qalmır."}'::jsonb, 'D', NULL, 'Düzgün: «Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10097, 129, 'g11-aze-punct-q1-07', 1, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Afərin, sən yarışda birinci yeri tutdun!", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "C": "Əhsən, bu çətin yarışda hamını qabaqladın!", "D": "Of, bu bitib-tükənməyən yol məni yordu!", "E": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'E', NULL, 'Düzgün: «Ey Vətən, sənin hər qarış torpağın müqəddəsdir!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10098, 129, 'g11-aze-punct-q1-08', 1, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "B": "Deməli bütün çətinliklər arxada qaldı.", "C": "Şübhəsiz, kitabxanadan götürdüyümüz nadir, əlyazmaları sabah geri qaytaracağıq.", "D": "Bəlkə biz son qatara çatmayacağıq.", "E": "Gördüyünüz kimi, bütün sənədlər hazırdır."}'::jsonb, 'E', NULL, 'Düzgün: «Gördüyünüz kimi, bütün sənədlər hazırdır.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10099, 129, 'g11-aze-punct-q1-09', 1, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ya qatar vaxtında gələcək ya da biz sabaha qədər gözləməli olacağıq.", "B": "Səhər, tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "C": "Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "D": "Dəniz, sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.", "E": "Gün batdı şəhərin işıqları yandı küçələrdə gəzintiyə çıxanların sayı artdı."}'::jsonb, 'C', NULL, 'Düzgün: «Qonaqlar gəldi, süfrə açıldı və hamı bayramı təbrik etdi.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; iki vergül buraxılıb; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10100, 129, 'g11-aze-punct-q1-10', 1, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "B": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "C": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'B', NULL, 'Düzgün: «Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10101, 129, 'g11-aze-punct-q1-11', 1, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "C": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "E": "Harada ki zəhmət var orada bərəkət də var."}'::jsonb, 'B', NULL, 'Düzgün: «Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10102, 129, 'g11-aze-punct-q1-12', 1, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "B": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "D": "Deməli bütün çətinliklər arxada qaldı.", "E": "Rəqib, topu qəsdən kənara vurdu."}'::jsonb, 'A', NULL, 'Düzgün: «Ey Vətən, sənin hər qarış torpağın müqəddəsdir!». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10103, 129, 'g11-aze-punct-q1-13', 1, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "B": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "C": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Elə ki imtahanlar başa çatdı tələbələr doğma kəndlərinə yola düşdülər.", "E": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı."}'::jsonb, 'B', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10104, 129, 'g11-aze-punct-q1-14', 1, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "B": "Məlumdur ki Azərbaycan zəngin təbii sərvətlərə malikdir.", "C": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "D": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'A', NULL, 'Düzgün: «Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10105, 129, 'g11-aze-punct-q1-15', 1, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hamıya aydın idi ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Harada ki zəhmət var, orada bərəkət də var.", "D": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın."}'::jsonb, 'C', NULL, 'Düzgün: «Harada ki zəhmət var, orada bərəkət də var.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10106, 129, 'g11-aze-punct-q1-16', 1, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ay bala, kitablarını rəfə yığ.", "B": "Təəssüf, ki ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "D": "Alim elə bir kəşf etdi ki onun adı bütün dünyada tanındı.", "E": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'A', NULL, 'Düzgün: «Ay bala, kitablarını rəfə yığ.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10107, 129, 'g11-aze-punct-q1-17', 1, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "B": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "C": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Harada ki zəhmət var orada bərəkət də var.", "E": "Məlumdur, ki Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'B', NULL, 'Düzgün: «Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10108, 129, 'g11-aze-punct-q1-18', 1, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım.", "B": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "E": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'E', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10109, 129, 'g11-aze-punct-q1-19', 1, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Gənclər, nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "B": "Siz ya tarixi romanı ya da elmi əsəri təhlil edin.", "C": "Qardaşım, həm rəssam, həm də musiqiçidir.", "D": "Nə atam, nə də anam bu xəbəri eşitmişdi.", "E": "Muzeydə qədim qılınclar, qalxanlar, və zirehlər nümayiş etdirilir."}'::jsonb, 'D', NULL, 'Düzgün: «Nə atam, nə də anam bu xəbəri eşitmişdi.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10110, 129, 'g11-aze-punct-q1-20', 1, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Elə ki imtahanlar başa çatdı tələbələr doğma kəndlərinə yola düşdülər.", "C": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Baxmayaraq ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım."}'::jsonb, 'C', NULL, 'Düzgün: «Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10111, 129, 'g11-aze-punct-q1-21', 1, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və müraciət var?', NULL, NULL, '{"A": "Afərin, sən yarışda birinci yeri tutdun!", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "D": "Of, bu bitib-tükənməyən yol məni yordu!", "E": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!"}'::jsonb, 'B', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10112, 129, 'g11-aze-punct-q1-22', 1, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Səhər, tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "B": "Ura uzun illər gözlədiyimiz qələbə gəldi!", "C": "Qonaqlar gəldi süfrə açıldı və hamı bayramı təbrik etdi.", "D": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın.", "E": "Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı."}'::jsonb, 'E', NULL, 'Düzgün: «Gün batdı, şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10113, 129, 'g11-aze-punct-q1-23', 1, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Gənclər, nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "C": "Şairin şeirləri həm ölkəmizdə həm də xaricdə sevilir.", "D": "Qardaşım həm rəssam həm də musiqiçidir.", "E": "Muzeydə qədim qılınclar, qalxanlar, və zirehlər nümayiş etdirilir."}'::jsonb, 'A', NULL, 'Düzgün: «Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10114, 129, 'g11-aze-punct-q1-24', 1, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "B": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "C": "Harada ki zəhmət var orada bərəkət də var.", "D": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır.", "E": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'A', NULL, 'Düzgün: «Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10115, 129, 'g11-aze-punct-q1-25', 1, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ay bala, kitablarını rəfə yığ.", "B": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "D": "Qardaşım, həm rəssam, həm də musiqiçidir.", "E": "Sən nə qədər səbirli olsan işlərin bir o qədər yaxşı gedəcək."}'::jsonb, 'A', NULL, 'Düzgün: «Ay bala, kitablarını rəfə yığ.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10116, 129, 'g11-aze-punct-q1-26', 1, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən nə də yorğunluqdan qorxurdular.", "B": "Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.", "C": "Qardaşım, həm rəssam, həm də musiqiçidir.", "D": "Siz ya tarixi romanı, ya da elmi, əsəri təhlil edin.", "E": "Muzeydə qədim qılınclar, qalxanlar, və zirehlər nümayiş etdirilir."}'::jsonb, 'B', NULL, 'Düzgün: «Şairin şeirləri həm ölkəmizdə, həm də xaricdə sevilir.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10117, 129, 'g11-aze-punct-q1-27', 1, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Əhsən, bu çətin, yarışda hamını qabaqladın!", "B": "Ay bala kitablarını rəfə yığ.", "C": "Tələbələr, mühazirəni diqqətlə dinləyir, qeydlər aparır, sonra suallar verirdilər.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Dəniz, sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar."}'::jsonb, 'D', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər cümlələrdə: birinci sözdən sonra artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10118, 129, 'g11-aze-punct-q1-28', 1, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Məncə bu məsələni yalnız siz bizə anladarsınız.", "B": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "C": "Bəlkə, biz son, qatara çatmayacağıq.", "D": "Gördüyünüz kimi bütün sənədlər hazırdır.", "E": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'B', NULL, 'Düzgün: «Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10119, 129, 'g11-aze-punct-q1-29', 1, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "B": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın.", "E": "Elə ki imtahanlar başa çatdı tələbələr doğma kəndlərinə yola düşdülər."}'::jsonb, 'B', NULL, 'Düzgün: «Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10120, 129, 'g11-aze-punct-q1-30', 1, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Alim elə bir kəşf etdi ki onun adı bütün dünyada tanındı.", "B": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Kim ki elmə dəyər verir, o, heç vaxt geri qalmır."}'::jsonb, 'E', NULL, 'Düzgün: «Kim ki elmə dəyər verir, o, heç vaxt geri qalmır.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10121, 129, 'g11-aze-punct-q2-01', 2, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "B": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı.", "C": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın."}'::jsonb, 'A', NULL, 'Düzgün: «Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10122, 129, 'g11-aze-punct-q2-02', 2, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Əhsən, bu çətin yarışda hamını qabaqladın!", "B": "Ay bala, kitablarını rəfə yığ.", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Ay bala kitablarını rəfə yığ.", "E": "Ura, uzun illər gözlədiyimiz qələbə gəldi!"}'::jsonb, 'B', NULL, 'Düzgün: «Ay bala, kitablarını rəfə yığ.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10123, 129, 'g11-aze-punct-q2-03', 2, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "B": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki gələcək nəsillər də onları tanısın.", "D": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq."}'::jsonb, 'A', NULL, 'Düzgün: «Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10124, 129, 'g11-aze-punct-q2-04', 2, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Ah, gəncliyimdə bu imkanlar olsaydı!", "E": "Afərin, sən yarışda birinci yeri tutdun!"}'::jsonb, 'B', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10125, 129, 'g11-aze-punct-q2-05', 2, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ay bala, kitablarını rəfə yığ.", "B": "Tələbələr, mühazirəni dinləyə-dinləyə qeydlər aparırdılar.", "C": "Siz ya tarixi romanı ya da elmi əsəri təhlil edin.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "E": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'A', NULL, 'Düzgün: «Ay bala, kitablarını rəfə yığ.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10126, 129, 'g11-aze-punct-q2-06', 2, 6, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Səhər, tezdən yola düşən səyyahlar dağın ətəyinə çatanda günəş artıq yüksəlmişdi, lakin hava hələ də sərin idi.", "B": "Gün batdı şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "C": "Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.", "D": "Qonaqlar gəldi, süfrə açıldı, və hamı bayramı təbrik etdi.", "E": "Ya qatar vaxtında gələcək ya da biz sabaha qədər gözləməli olacağıq."}'::jsonb, 'C', NULL, 'Düzgün: «Dəniz sakitləşmişdi, balıqçılar isə qayıqlarını suya salmağa hazırlaşırdılar.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10127, 129, 'g11-aze-punct-q2-07', 2, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Əhsən, bu çətin yarışda hamını qabaqladın!", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'E', NULL, 'Düzgün: «Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10128, 129, 'g11-aze-punct-q2-08', 2, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Xalqımızın yetirdiyi dahi şəxsiyyətlər dünya mədəniyyətinə böyük, töhfələr veriblər.", "B": "Bəlkə, biz son, qatara çatmayacağıq.", "C": "Məncə, bu məsələni yalnız siz bizə anladarsınız.", "D": "Təəssüf ki ötən il əkdiyimiz fidanların üçdə biri quruyub.", "E": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'C', NULL, 'Düzgün: «Məncə, bu məsələni yalnız siz bizə anladarsınız.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10129, 129, 'g11-aze-punct-q2-09', 2, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Ura, uzun, illər gözlədiyimiz qələbə gəldi!", "C": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!", "D": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Xalqımızın yetirdiyi dahi, şəxsiyyətlər dünya mədəniyyətinə böyük töhfələr veriblər."}'::jsonb, 'A', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10130, 129, 'g11-aze-punct-q2-10', 2, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "B": "Ay bala kitablarını rəfə yığ.", "C": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "D": "Ah, gəncliyimdə bu imkanlar olsaydı!", "E": "Əhsən, bu çətin yarışda hamını qabaqladın!"}'::jsonb, 'A', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10131, 129, 'g11-aze-punct-q2-11', 2, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!", "B": "Görünür yağış səhərə kimi dayanmayacaq.", "C": "Muzeydə qədim qılınclar, qalxanlar, və zirehlər nümayiş etdirilir.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "E": "Ay bala, kitablarını rəfə yığ."}'::jsonb, 'E', NULL, 'Düzgün: «Ay bala, kitablarını rəfə yığ.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10132, 129, 'g11-aze-punct-q2-12', 2, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və müraciət var?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "B": "Vay, pəncərənin şüşəsi küləkdən sındı!", "C": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "D": "Afərin, sən yarışda birinci yeri tutdun!", "E": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'C', NULL, 'Düzgün: «Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10133, 129, 'g11-aze-punct-q2-13', 2, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Məlumdur ki Azərbaycan zəngin təbii sərvətlərə malikdir.", "B": "Qonaqlar, gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "C": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.", "D": "Gün batdı şəhərin işıqları yandı, küçələrdə gəzintiyə çıxanların sayı artdı.", "E": "Hətta ən təcrübəli, alpinistlər bu zirvəyə qalxmaqdan çəkinirdilər."}'::jsonb, 'C', NULL, 'Düzgün: «Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10134, 129, 'g11-aze-punct-q2-14', 2, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın.", "B": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır.", "C": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "D": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "E": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar."}'::jsonb, 'C', NULL, 'Düzgün: «Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10135, 129, 'g11-aze-punct-q2-15', 2, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "B": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki gələcək nəsillər də onları tanısın.", "C": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı."}'::jsonb, 'C', NULL, 'Düzgün: «Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10136, 129, 'g11-aze-punct-q2-16', 2, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "B": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım.", "C": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Kim ki elmə dəyər verir o heç vaxt geri qalmır."}'::jsonb, 'A', NULL, 'Düzgün: «Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10137, 129, 'g11-aze-punct-q2-17', 2, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Qonaqlar, gəldi, süfrə açıldı və hamı bayramı təbrik etdi.", "B": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Gün batdı, şəhərin işıqları yandı küçələrdə gəzintiyə çıxanların sayı artdı.", "D": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı.", "E": "Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq."}'::jsonb, 'E', NULL, 'Düzgün: «Ya qatar vaxtında gələcək, ya da biz sabaha qədər gözləməli olacağıq.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10138, 129, 'g11-aze-punct-q2-18', 2, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "C": "Ey gənclər ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "D": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!", "E": "Əhsən, bu çətin yarışda hamını qabaqladın!"}'::jsonb, 'B', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10139, 129, 'g11-aze-punct-q2-19', 2, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "B": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "C": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq."}'::jsonb, 'B', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10140, 129, 'g11-aze-punct-q2-20', 2, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "B": "Deməli bütün çətinliklər arxada qaldı.", "C": "Bəlkə, biz son, qatara çatmayacağıq.", "D": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Gördüyünüz kimi bütün sənədlər hazırdır."}'::jsonb, 'A', NULL, 'Düzgün: «Şübhəsiz, kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10141, 129, 'g11-aze-punct-q2-21', 2, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Gənclər nə çətinlikdən nə də yorğunluqdan qorxurdular.", "B": "Nə atam nə də anam bu xəbəri eşitmişdi.", "C": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "D": "Qardaşım, həm rəssam, həm də musiqiçidir.", "E": "Muzeydə qədim qılınclar, qalxanlar, və zirehlər nümayiş etdirilir."}'::jsonb, 'C', NULL, 'Düzgün: «Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10142, 129, 'g11-aze-punct-q2-22', 2, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım.", "B": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın.", "C": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "D": "Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Baxmayaraq ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'D', NULL, 'Düzgün: «Biz istəyirik ki, ana dilimiz bütün sahələrdə daha geniş işlənsin.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10143, 129, 'g11-aze-punct-q2-23', 2, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki gələcək nəsillər də onları tanısın.", "B": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "D": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin."}'::jsonb, 'E', NULL, 'Düzgün: «Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10144, 129, 'g11-aze-punct-q2-24', 2, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.", "B": "Alim elə bir kəşf etdi ki onun adı bütün dünyada tanındı.", "C": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "D": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Məlumdur ki Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'A', NULL, 'Düzgün: «Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10145, 129, 'g11-aze-punct-q2-25', 2, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Həm müəllimlər, həm də şagirdlər yeni məktəb binasının açılışına toplaşmışdılar.", "B": "Qatar, stansiyaya çatan kimi sərnişinlər vaqonlardan düşüb şəhərə tərəf getdilər.", "C": "Tələbələr mühazirəni diqqətlə dinləyir qeydlər aparır, sonra suallar verirdilər.", "D": "Dağların ətəyində yerləşən bu kiçik kənddə qədim, adətlər yaşadılır.", "E": "Alim, bu problemi təkbaşına araşdırdı."}'::jsonb, 'A', NULL, 'Düzgün: «Həm müəllimlər, həm də şagirdlər yeni məktəb binasının açılışına toplaşmışdılar.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10146, 129, 'g11-aze-punct-q2-26', 2, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "C": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "D": "Məlumdur ki Azərbaycan zəngin təbii sərvətlərə malikdir.", "E": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq."}'::jsonb, 'B', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10147, 129, 'g11-aze-punct-q2-27', 2, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Hərçənd səfər çətin, və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "B": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Sən nə qədər səbirli olsan işlərin bir o qədər yaxşı gedəcək."}'::jsonb, 'B', NULL, 'Düzgün: «Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10148, 129, 'g11-aze-punct-q2-28', 2, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "B": "Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'B', NULL, 'Düzgün: «Gənc rəssamın arzusu bu idi ki, əsərləri beynəlxalq sərgidə nümayiş etdirilsin.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10149, 129, 'g11-aze-punct-q2-29', 2, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.", "B": "Gördüyünüz kimi bütün sənədlər hazırdır.", "C": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Bəlkə, biz son, qatara çatmayacağıq.", "E": "Görünür yağış səhərə kimi dayanmayacaq."}'::jsonb, 'A', NULL, 'Düzgün: «Təəssüf ki, ötən il əkdiyimiz fidanların üçdə biri quruyub.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10150, 129, 'g11-aze-punct-q2-30', 2, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və müraciət var?', NULL, NULL, '{"A": "Ah, gəncliyimdə bu imkanlar olsaydı!", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Afərin, sən yarışda birinci yeri tutdun!", "D": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!", "E": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!"}'::jsonb, 'E', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10151, 129, 'g11-aze-punct-q3-01', 3, 1, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Məncə bu məsələni yalnız siz bizə anladarsınız.", "B": "Təəssüf, ki ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.", "E": "Şübhəsiz, kitabxanadan götürdüyümüz nadir, əlyazmaları sabah geri qaytaracağıq."}'::jsonb, 'D', NULL, 'Düzgün: «Əlbəttə, ana dilini qorumaq vətəndaşlıq borcudur.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10152, 129, 'g11-aze-punct-q3-02', 3, 2, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "B": "Şairin şeirləri həm ölkəmizdə həm də xaricdə sevilir.", "C": "Muzeydə qədim, qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "D": "Qardaşım, həm rəssam, həm də musiqiçidir.", "E": "Nə atam nə də anam bu xəbəri eşitmişdi."}'::jsonb, 'A', NULL, 'Düzgün: «Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10153, 129, 'g11-aze-punct-q3-03', 3, 3, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də müraciət var və nida işlənib?', NULL, NULL, '{"A": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "B": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "C": "Əhsən, bu çətin yarışda hamını qabaqladın!", "D": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Ah, gəncliyimdə bu imkanlar olsaydı!"}'::jsonb, 'B', NULL, 'Düzgün: «Ey Vətən, sənin hər qarış torpağın müqəddəsdir!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10154, 129, 'g11-aze-punct-q3-04', 3, 4, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Gördüyünüz kimi bütün sənədlər hazırdır.", "B": "Təəssüf, ki ötən il əkdiyimiz fidanların üçdə biri quruyub.", "C": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "D": "Şübhəsiz, kitabxanadan götürdüyümüz nadir, əlyazmaları sabah geri qaytaracağıq.", "E": "Görünür, yağış səhərə kimi dayanmayacaq."}'::jsonb, 'E', NULL, 'Düzgün: «Görünür, yağış səhərə kimi dayanmayacaq.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10155, 129, 'g11-aze-punct-q3-05', 3, 5, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "B": "Bəs siz hansı universitetə sənəd vermisiniz.", "C": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!", "E": "Əhsən, bu çətin, yarışda hamını qabaqladın!"}'::jsonb, 'D', NULL, 'Düzgün: «Ey gənclər, ata-babalarımızdan qalan bu müqəddəs torpağı göz bəbəyi kimi qoruyun!». Digər cümlələrdə: sual cümləsinin sonunda nöqtə qoyulub; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10156, 129, 'g11-aze-punct-q3-06', 3, 6, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.", "B": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "C": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "E": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'A', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10157, 129, 'g11-aze-punct-q3-07', 3, 7, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır.", "B": "Harada ki zəhmət var orada bərəkət də var.", "C": "Harada ki zəhmət var, orada bərəkət də var.", "D": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "E": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək."}'::jsonb, 'C', NULL, 'Düzgün: «Harada ki zəhmət var, orada bərəkət də var.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10158, 129, 'g11-aze-punct-q3-08', 3, 8, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Alim elə bir kəşf etdi ki onun adı bütün dünyada tanındı.", "C": "Baxmayaraq ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "D": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'E', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10159, 129, 'g11-aze-punct-q3-09', 3, 9, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "B": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "D": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı."}'::jsonb, 'E', NULL, 'Düzgün: «Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10160, 129, 'g11-aze-punct-q3-10', 3, 10, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o, heç vaxt geri qalmır.", "B": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "D": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "E": "Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı."}'::jsonb, 'E', NULL, 'Düzgün: «Alim elə bir kəşf etdi ki, onun adı bütün dünyada tanındı.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10161, 129, 'g11-aze-punct-q3-11', 3, 11, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın.", "C": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "D": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım.", "E": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin."}'::jsonb, 'A', NULL, 'Düzgün: «Baxmayaraq ki, sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10162, 129, 'g11-aze-punct-q3-12', 3, 12, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və müraciət var?', NULL, NULL, '{"A": "Əhsən, bu çətin yarışda hamını qabaqladın!", "B": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!", "C": "Ey Vətən, sənin hər qarış torpağın müqəddəsdir!", "D": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq.", "E": "Vay, pəncərənin şüşəsi küləkdən sındı!"}'::jsonb, 'C', NULL, 'Düzgün: «Ey Vətən, sənin hər qarış torpağın müqəddəsdir!». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10163, 129, 'g11-aze-punct-q3-13', 3, 13, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "B": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.", "C": "Kim ki elmə dəyər verir, o heç vaxt geri qalmır.", "D": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Hamıya aydın idi ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq."}'::jsonb, 'B', NULL, 'Düzgün: «Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10164, 129, 'g11-aze-punct-q3-14', 3, 14, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "C": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Harada ki zəhmət var orada bərəkət də var.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın."}'::jsonb, 'B', NULL, 'Düzgün: «Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10165, 129, 'g11-aze-punct-q3-15', 3, 15, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq, ki gələcək nəsillər də onları tanısın.", "B": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.", "C": "Elə ki imtahanlar başa çatdı tələbələr doğma kəndlərinə yola düşdülər.", "D": "Məlumdur ki Azərbaycan zəngin təbii sərvətlərə malikdir.", "E": "Harada ki zəhmət var orada bərəkət də var."}'::jsonb, 'B', NULL, 'Düzgün: «Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10166, 129, 'g11-aze-punct-q3-16', 3, 16, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım.", "B": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "C": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın."}'::jsonb, 'E', NULL, 'Düzgün: «Ata-babalarımızdan qalan adət-ənənələri qorumalıyıq ki, gələcək nəsillər də onları tanısın.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10167, 129, 'g11-aze-punct-q3-17', 3, 17, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "B": "Ura, uzun, illər gözlədiyimiz qələbə gəldi!", "C": "Of, bu bitib-tükənməyən yol məni yordu!", "D": "Şübhəsiz kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "E": "Ay müəllim dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'C', NULL, 'Düzgün: «Of, bu bitib-tükənməyən yol məni yordu!». Digər cümlələrdə: iki vergül buraxılıb; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10168, 129, 'g11-aze-punct-q3-18', 3, 18, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Elə ki imtahanlar başa çatdı tələbələr doğma kəndlərinə yola düşdülər.", "B": "Alim elə bir kəşf etdi ki onun adı bütün dünyada tanındı.", "C": "Məlumdur, ki Azərbaycan zəngin təbii sərvətlərə malikdir.", "D": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "E": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım."}'::jsonb, 'E', NULL, 'Düzgün: «Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10169, 129, 'g11-aze-punct-q3-19', 3, 19, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "B": "Gənc rəssamın arzusu bu idi ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "C": "Biz istəyirik, ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "D": "Kim ki elmə dəyər verir o heç vaxt geri qalmır.", "E": "Məlumdur, ki Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'A', NULL, 'Düzgün: «Hamıya aydın idi ki, uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10170, 129, 'g11-aze-punct-q3-20', 3, 20, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Sən nə qədər səbirli olsan işlərin bir o qədər yaxşı gedəcək.", "B": "Baxmayaraq ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Gənc rəssamın arzusu bu idi, ki əsərləri beynəlxalq sərgidə nümayiş etdirilsin.", "D": "Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.", "E": "Kim ki elmə dəyər verir o heç vaxt geri qalmır."}'::jsonb, 'D', NULL, 'Düzgün: «Əgər vaxtında tədbir görülməsə, sahildəki qədim tikililər tamamilə dağılacaq.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10171, 129, 'g11-aze-punct-q3-21', 3, 21, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də «ki» bağlayıcısı işlənib və cümlə tabeli mürəkkəb cümlədir?', NULL, NULL, '{"A": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "B": "Baxmayaraq ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "C": "Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.", "D": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "E": "Baxmayaraq, ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'C', NULL, 'Düzgün: «Elə ki imtahanlar başa çatdı, tələbələr doğma kəndlərinə yola düşdülər.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10172, 129, 'g11-aze-punct-q3-22', 3, 22, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Muzeydə qədim qılınclar, qalxanlar, və zirehlər nümayiş etdirilir.", "B": "Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.", "C": "Gənclər, nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Doğrudan da sevdiyi işi görən insan yorulmur.", "E": "Qardaşım həm rəssam həm də musiqiçidir."}'::jsonb, 'B', NULL, 'Düzgün: «Siz ya tarixi romanı, ya da elmi əsəri təhlil edin.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; vergül buraxılıb; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10173, 129, 'g11-aze-punct-q3-23', 3, 23, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Muzeydə qədim, qılınclar, qalxanlar və zirehlər nümayiş etdirilir.", "B": "Qardaşım, həm rəssam, həm də musiqiçidir.", "C": "Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.", "D": "Siz ya tarixi, romanı, ya da elmi əsəri təhlil edin.", "E": "Şairin şeirləri həm ölkəmizdə həm də xaricdə sevilir."}'::jsonb, 'C', NULL, 'Düzgün: «Gənclər nə çətinlikdən, nə də yorğunluqdan qorxurdular.». Digər cümlələrdə: mübtəda ilə cümlənin qalan hissəsi arasında artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10174, 129, 'g11-aze-punct-q3-24', 3, 24, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Alim elə bir kəşf etdi, ki onun adı bütün dünyada tanındı.", "B": "Biz istəyirik ki ana dilimiz bütün sahələrdə daha geniş işlənsin.", "C": "Səhər çox erkən oyandım ki paytaxta gedən ilk qatara çatım.", "D": "Baxmayaraq ki sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir."}'::jsonb, 'E', NULL, 'Düzgün: «Məlumdur ki, Azərbaycan zəngin təbii sərvətlərə malikdir.». Digər cümlələrdə: iki vergül buraxılıb; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10175, 129, 'g11-aze-punct-q3-25', 3, 25, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Deməli, bütün çətinliklər arxada qaldı.", "B": "Şübhəsiz kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "C": "Məncə bu məsələni yalnız siz bizə anladarsınız.", "D": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq.", "E": "Bəlkə, biz son, qatara çatmayacağıq."}'::jsonb, 'A', NULL, 'Düzgün: «Deməli, bütün çətinliklər arxada qaldı.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10176, 129, 'g11-aze-punct-q3-26', 3, 26, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Əgər vaxtında tədbir görülməsə sahildəki qədim tikililər tamamilə dağılacaq.", "B": "Hərçənd səfər çətin, və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "C": "Hamıya aydın idi, ki uzun illər boyu davam edən mübahisə bu dəfə sülhlə başa çatacaq.", "D": "Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.", "E": "Baxmayaraq ki, sınaq çətin keçdi tələbələrin hamısı yüksək nəticə göstərdi."}'::jsonb, 'D', NULL, 'Düzgün: «Sən nə qədər səbirli olsan, işlərin bir o qədər yaxşı gedəcək.». Digər cümlələrdə: vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub; «və» bağlayıcısından əvvəl artıq vergül.');
INSERT INTO public.questions VALUES (10177, 129, 'g11-aze-punct-q3-27', 3, 27, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də cümlə tabeli mürəkkəb cümlədir və «ki» bağlayıcısı işlənib?', NULL, NULL, '{"A": "Hərçənd səfər çətin və uzun idi, yolçular heç bir şikayət etmədən mənzil başına çatdılar.", "B": "Səhər çox erkən oyandım, ki paytaxta gedən ilk qatara çatım.", "C": "Kitabxanaya gələn oxucuların sayı artmışdı, çünki yeni nəşrlər gətirilmişdi.", "D": "Baxmayaraq ki sınaq çətin keçdi, tələbələrin hamısı yüksək nəticə göstərdi.", "E": "Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım."}'::jsonb, 'E', NULL, 'Düzgün: «Səhər çox erkən oyandım ki, paytaxta gedən ilk qatara çatım.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10178, 129, 'g11-aze-punct-q3-28', 3, 28, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Qatar, stansiyaya çatan kimi sərnişinlər vaqonlardan düşüb şəhərə tərəf getdilər.", "B": "Ey gənclər, ata-babalarımızdan qalan bu müqəddəs, torpağı göz bəbəyi kimi qoruyun!", "C": "Şübhəsiz kitabxanadan götürdüyümüz nadir əlyazmaları sabah geri qaytaracağıq.", "D": "Ey Vətən sənin hər qarış torpağın müqəddəsdir!", "E": "Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq."}'::jsonb, 'E', NULL, 'Düzgün: «Ay müəllim, dünən sizin danışdığınız hadisəni heç kim unutmayacaq.». Digər cümlələrdə: birinci sözdən sonra artıq vergül; təyinlə isim arasında artıq vergül; vergül buraxılıb.');
INSERT INTO public.questions VALUES (10179, 129, 'g11-aze-punct-q3-29', 3, 29, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub, həm də nida işlənib və müraciət var?', NULL, NULL, '{"A": "Vay, pəncərənin şüşəsi küləkdən sındı!", "B": "Ura, uzun illər gözlədiyimiz qələbə gəldi!", "C": "Ay bala, kitablarını rəfə yığ.", "D": "Əhsən, bu çətin yarışda hamını qabaqladın!", "E": "Afərin, sən yarışda birinci yeri tutdun!"}'::jsonb, 'C', NULL, 'Düzgün: «Ay bala, kitablarını rəfə yığ.». Digər variantlarda ya durğu səhvi var, ya da şərt ödənmir.');
INSERT INTO public.questions VALUES (10180, 129, 'g11-aze-punct-q3-30', 3, 30, 'hard', 'single', 'Hansı cümlədə durğu işarələri düzgün qoyulub?', NULL, NULL, '{"A": "Şübhəsiz, kitabxanadan götürdüyümüz nadir, əlyazmaları sabah geri qaytaracağıq.", "B": "Bəlkə biz son qatara çatmayacağıq.", "C": "Təəssüf, ki ötən il əkdiyimiz fidanların üçdə biri quruyub.", "D": "Doğrudan da, sevdiyi işi görən insan yorulmur.", "E": "Ehtimal, ki iki həftədən sonra başlayacaq müsabiqədə on iki ölkənin təmsilçiləri yarışacaq."}'::jsonb, 'D', NULL, 'Düzgün: «Doğrudan da, sevdiyi işi görən insan yorulmur.». Digər cümlələrdə: təyinlə isim arasında artıq vergül; vergül buraxılıb; vergül «ki» bağlayıcısından əvvəl qoyulub.');
INSERT INTO public.questions VALUES (10181, 130, 'g11-eng-tense-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By next July, he ___ (read) the report. (2) By next July, they ___ (clean) the kitchen. (3) By next July, they ___ (wash) the dishes.', NULL, NULL, '{"A": "will have read / will have cleaned / had washed", "B": "will have read / will have cleaned / will have washed", "C": "will have read / had cleaned / will have washed", "D": "had read / will have cleaned / will have washed", "E": "has read / will have cleaned / will have washed"}'::jsonb, 'B', NULL, '(1) will have read — Future Perfect: «by next July» (2) will have cleaned — Future Perfect: «by next July» (3) will have washed — Future Perfect: «by next July»');
INSERT INTO public.questions VALUES (10182, 130, 'g11-eng-tense-q1-02', 1, 2, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This time tomorrow, she was finishing the project. This time tomorrow, she will be planting trees in the garden.", "B": "This time tomorrow, she will be finishing the project. This time tomorrow, she planted trees in the garden.", "C": "This time tomorrow, she will be finishing the project. This time tomorrow, she will be planting trees in the garden.", "D": "This time tomorrow, she will be finishing the project. This time tomorrow, she was planting trees in the garden.", "E": "This time tomorrow, she had finished the project. This time tomorrow, she will be planting trees in the garden."}'::jsonb, 'C', NULL, 'will be finishing — Future Continuous: «this time tomorrow»; will be planting — Future Continuous: «this time tomorrow».');
INSERT INTO public.questions VALUES (10183, 130, 'g11-eng-tense-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They are painting the fence when the lights suddenly went out.", "B": "By next July, she has washed the dishes.", "C": "By the time we arrived, they have translated the article.", "D": "I will call you as soon as I plant trees in the garden.", "E": "This time tomorrow, they were cleaning the kitchen."}'::jsonb, 'D', NULL, 'Correct: «I will call you as soon as I plant trees in the garden.» — Zaman budaq cümləsində (as soon as, when) gələcək Present Simple ilə ifadə olunur. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10184, 130, 'g11-eng-tense-q1-04', 1, 4, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He has been teaching the younger kids for two hours, and he still hasn''t finished. I read the report three times since January.", "B": "He was teaching the younger kids for two hours, and he still hasn''t finished. I have read the report three times since January.", "C": "He has been teaching the younger kids for two hours, and he still hasn''t finished. I have read the report three times since January.", "D": "He has been teaching the younger kids for two hours, and he still hasn''t finished. I am reading the report three times since January.", "E": "He is teaching the younger kids for two hours, and he still hasn''t finished. I have read the report three times since January."}'::jsonb, 'C', NULL, 'has been teaching — Present Perfect Continuous: davam edən proses; have read — Present Perfect: «since» + təkrar sayı.');
INSERT INTO public.questions VALUES (10185, 130, 'g11-eng-tense-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) By the time we arrived, they had already ___ (plant) trees in the garden. (2) This time tomorrow, he ___ (translate) the article. (3) By the time we arrived, he ___ (finish) the project.', NULL, NULL, '{"A": "planted / will be translating / finishes", "B": "plant / will be translating / had finished", "C": "planted / will be translating / will have finished", "D": "planted / had translated / had finished", "E": "planted / will be translating / had finished"}'::jsonb, 'E', NULL, '(1) planted — Past Perfect: had + V3 (2) will be translating — Future Continuous: «this time tomorrow» (3) had finished — Past Perfect: «by the time» + keçmiş');
INSERT INTO public.questions VALUES (10186, 130, 'g11-eng-tense-q1-06', 1, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I was reading the report when the lights suddenly went out.", "B": "He is reading the report three times since January.", "C": "My brother repaired the old bike for two hours, and he still hasn''t finished.", "D": "He translated the article three times since January.", "E": "By next July, I had visited the museum."}'::jsonb, 'A', NULL, 'Correct: «I was reading the report when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10187, 130, 'g11-eng-tense-q1-07', 1, 7, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This time tomorrow, he will be painting the fence. I have finished the project three times since January.", "B": "This time tomorrow, he painted the fence. I have finished the project three times since January.", "C": "This time tomorrow, he was painting the fence. I have finished the project three times since January.", "D": "This time tomorrow, he will be painting the fence. I finished the project three times since January.", "E": "This time tomorrow, he will be painting the fence. I finish the project three times since January."}'::jsonb, 'A', NULL, 'will be painting — Future Continuous: «this time tomorrow»; have finished — Present Perfect: «since» + təkrar sayı.');
INSERT INTO public.questions VALUES (10188, 130, 'g11-eng-tense-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By next July, they cooked dinner.", "B": "They will be buying a new laptop when the lights suddenly went out.", "C": "She designed a poster three times since January.", "D": "By the time we arrived, he teaches the younger kids.", "E": "Our neighbours have planted trees in the garden three times since January."}'::jsonb, 'E', NULL, 'Correct: «Our neighbours have planted trees in the garden three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10189, 130, 'g11-eng-tense-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He ___ (repair) the old bike for two hours, and he still hasn''t finished. (2) The students ___ (visit) the museum three times since January. (3) The students ___ (paint) the fence three times since January.', NULL, NULL, '{"A": "has been repairing / are visiting / have painted", "B": "has been repairing / visit / have painted", "C": "has been repairing / have visited / paint", "D": "repaired / have visited / have painted", "E": "has been repairing / have visited / have painted"}'::jsonb, 'E', NULL, '(1) has been repairing — Present Perfect Continuous: davam edən proses (2) have visited — Present Perfect: «since» + təkrar sayı (3) have painted — Present Perfect: «since» + təkrar sayı');
INSERT INTO public.questions VALUES (10190, 130, 'g11-eng-tense-q1-10', 1, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By next July, I had studied for the exam.", "B": "This time tomorrow, they were designing a poster.", "C": "This time tomorrow, he was finishing the project.", "D": "The students have cleaned the kitchen three times since January.", "E": "By the time we arrived, she had already clean the kitchen."}'::jsonb, 'D', NULL, 'Correct: «The students have cleaned the kitchen three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10191, 130, 'g11-eng-tense-q1-11', 1, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Our neighbours were writing a long letter when the lights suddenly went out.", "B": "By the time we arrived, they have washed the dishes.", "C": "Our neighbours wrote a long letter three times since January.", "D": "By next July, I have studied for the exam.", "E": "By the time we arrived, he will have taught the younger kids."}'::jsonb, 'A', NULL, 'Correct: «Our neighbours were writing a long letter when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
