INSERT INTO public.questions VALUES (10207, 130, 'g11-eng-tense-q1-27', 1, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, he ___ (visit) the museum. (2) By the time we arrived, they ___ (teach) the younger kids. (3) I ___ (teach) the younger kids three times since January.', NULL, NULL, '{"A": "visited / had taught / have taught", "B": "will be visiting / had taught / am teaching", "C": "will be visiting / had taught / have taught", "D": "was visiting / had taught / have taught", "E": "will be visiting / teach / have taught"}'::jsonb, 'C', NULL, '(1) will be visiting — Future Continuous: «this time tomorrow» (2) had taught — Past Perfect: «by the time» + keçmiş (3) have taught — Present Perfect: «since» + təkrar sayı');
