INSERT INTO public.questions VALUES (10257, 130, 'g11-eng-tense-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Our neighbours ___ (buy) a new laptop when the lights suddenly went out. (2) This time tomorrow, they ___ (wash) the dishes. (3) She ___ (write) a long letter three times since January.', NULL, NULL, '{"A": "were buying / will be washing / has written", "B": "were buying / will be washing / wrote", "C": "were buying / had washed / has written", "D": "will be buying / will be washing / has written", "E": "are buying / will be washing / has written"}'::jsonb, 'A', NULL, '(1) were buying — Past Continuous: kəsilən proses (2) will be washing — Future Continuous: «this time tomorrow» (3) has written — Present Perfect: «since» + təkrar sayı');
INSERT INTO public.questions VALUES (10258, 130, 'g11-eng-tense-q3-18', 3, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This time tomorrow, she ___ (buy) a new laptop. (2) We ___ (repair) the old bike when the lights suddenly went out. (3) He ___ (design) a poster when the lights suddenly went out.', NULL, NULL, '{"A": "will be buying / are repairing / was designing", "B": "will be buying / were repairing / was designing", "C": "has been buying / were repairing / was designing", "D": "will be buying / were repairing / designs", "E": "will be buying / will be repairing / was designing"}'::jsonb, 'B', NULL, '(1) will be buying — Future Continuous: «this time tomorrow» (2) were repairing — Past Continuous: kəsilən proses (3) was designing — Past Continuous: kəsilən proses');
INSERT INTO public.questions VALUES (10259, 130, 'g11-eng-tense-q3-19', 3, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "By next July, we will have written a long letter. My brother has visited the museum when the lights suddenly went out.", "B": "By next July, we will have written a long letter. My brother was visiting the museum when the lights suddenly went out.", "C": "By next July, we have written a long letter. My brother was visiting the museum when the lights suddenly went out.", "D": "By next July, we wrote a long letter. My brother was visiting the museum when the lights suddenly went out.", "E": "By next July, we will have written a long letter. My brother visits the museum when the lights suddenly went out."}'::jsonb, 'B', NULL, 'will have written — Future Perfect: «by next July»; was visiting — Past Continuous: kəsilən proses.');
INSERT INTO public.questions VALUES (10260, 130, 'g11-eng-tense-q3-20', 3, 20, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, they cook dinner.", "B": "This time tomorrow, they will be cleaning the kitchen.", "C": "This time tomorrow, she had designed a poster.", "D": "This time tomorrow, she was finishing the project.", "E": "My brother is studying for the exam for two hours, and he still hasn''t finished."}'::jsonb, 'B', NULL, 'Correct: «This time tomorrow, they will be cleaning the kitchen.» — Future Continuous: «this time tomorrow». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10261, 130, 'g11-eng-tense-q3-21', 3, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, he had visited the museum. My brother was visiting the museum when the lights suddenly went out.", "B": "By the time we arrived, he had visited the museum. My brother is visiting the museum when the lights suddenly went out.", "C": "By the time we arrived, he had visited the museum. My brother has visited the museum when the lights suddenly went out.", "D": "By the time we arrived, he visits the museum. My brother was visiting the museum when the lights suddenly went out.", "E": "By the time we arrived, he has visited the museum. My brother was visiting the museum when the lights suddenly went out."}'::jsonb, 'A', NULL, 'had visited — Past Perfect: «by the time» + keçmiş; was visiting — Past Continuous: kəsilən proses.');
INSERT INTO public.questions VALUES (10262, 130, 'g11-eng-tense-q3-22', 3, 22, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, they had washed the dishes. He studied for the exam three times since January.", "B": "By the time we arrived, they had washed the dishes. He studies for the exam three times since January.", "C": "By the time we arrived, they have washed the dishes. He has studied for the exam three times since January.", "D": "By the time we arrived, they had washed the dishes. He has studied for the exam three times since January.", "E": "By the time we arrived, they had washed the dishes. He is studying for the exam three times since January."}'::jsonb, 'D', NULL, 'had washed — Past Perfect: «by the time» + keçmiş; has studied — Present Perfect: «since» + təkrar sayı.');
INSERT INTO public.questions VALUES (10263, 130, 'g11-eng-tense-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By next July, she will have finished the project.", "B": "He studied for the exam three times since January.", "C": "By the time we arrived, I had already washing the dishes.", "D": "He paints the fence three times since January.", "E": "This time tomorrow, we had designed a poster."}'::jsonb, 'A', NULL, 'Correct: «By next July, she will have finished the project.» — Future Perfect: «by next July». The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10264, 130, 'g11-eng-tense-q3-24', 3, 24, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "By next July, he will have read the report. She was designing a poster for two hours, and she still hasn''t finished.", "B": "By next July, he had read the report. She has been designing a poster for two hours, and she still hasn''t finished.", "C": "By next July, he will have read the report. She designed a poster for two hours, and she still hasn''t finished.", "D": "By next July, he will have read the report. She is designing a poster for two hours, and she still hasn''t finished.", "E": "By next July, he will have read the report. She has been designing a poster for two hours, and she still hasn''t finished."}'::jsonb, 'E', NULL, 'will have read — Future Perfect: «by next July»; has been designing — Present Perfect Continuous: davam edən proses.');
INSERT INTO public.questions VALUES (10265, 130, 'g11-eng-tense-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, I have painted the fence.", "B": "This time tomorrow, they were buying a new laptop.", "C": "By the time we arrived, they had already repaired the old bike.", "D": "We are buying a new laptop three times since January.", "E": "They finished the project three times since January."}'::jsonb, 'C', NULL, 'Correct: «By the time we arrived, they had already repaired the old bike.» — Past Perfect: had + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10266, 130, 'g11-eng-tense-q3-26', 3, 26, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I have watched a documentary three times since January. I will be teaching the younger kids when the lights suddenly went out.", "B": "I have watched a documentary three times since January. I was teaching the younger kids when the lights suddenly went out.", "C": "I watched a documentary three times since January. I was teaching the younger kids when the lights suddenly went out.", "D": "I have watched a documentary three times since January. I am teaching the younger kids when the lights suddenly went out.", "E": "I am watching a documentary three times since January. I was teaching the younger kids when the lights suddenly went out."}'::jsonb, 'B', NULL, 'have watched — Present Perfect: «since» + təkrar sayı; was teaching — Past Continuous: kəsilən proses.');
INSERT INTO public.questions VALUES (10267, 130, 'g11-eng-tense-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "By next July, they translated the article.", "B": "By the time we arrived, they had already watch a documentary.", "C": "He has been reading the report for two hours, and he still hasn''t finished.", "D": "Our neighbours have watched a documentary when the lights suddenly went out.", "E": "The students are watching a documentary three times since January."}'::jsonb, 'C', NULL, 'Correct: «He has been reading the report for two hours, and he still hasn''t finished.» — Present Perfect Continuous: davam edən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10268, 130, 'g11-eng-tense-q3-28', 3, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "By the time we arrived, they had studied for the exam. I am studying for the exam three times since January.", "B": "By the time we arrived, they will have studied for the exam. I have studied for the exam three times since January.", "C": "By the time we arrived, they had studied for the exam. I have studied for the exam three times since January.", "D": "By the time we arrived, they have studied for the exam. I have studied for the exam three times since January.", "E": "By the time we arrived, they had studied for the exam. I study for the exam three times since January."}'::jsonb, 'C', NULL, 'had studied — Past Perfect: «by the time» + keçmiş; have studied — Present Perfect: «since» + təkrar sayı.');
INSERT INTO public.questions VALUES (10269, 130, 'g11-eng-tense-q3-29', 3, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Our neighbours were planting trees in the garden when the lights suddenly went out.", "B": "By next July, we studied for the exam.", "C": "He is reading the report for two hours, and he still hasn''t finished.", "D": "My brother paints the fence when the lights suddenly went out.", "E": "This time tomorrow, he cleaned the kitchen."}'::jsonb, 'A', NULL, 'Correct: «Our neighbours were planting trees in the garden when the lights suddenly went out.» — Past Continuous: kəsilən proses. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10270, 130, 'g11-eng-tense-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We have visited the museum three times since January.", "B": "My brother is cleaning the kitchen for two hours, and he still hasn''t finished.", "C": "This time tomorrow, he has been finishing the project.", "D": "This time tomorrow, he was painting the fence.", "E": "By the time we arrived, they had already translating the article."}'::jsonb, 'A', NULL, 'Correct: «We have visited the museum three times since January.» — Present Perfect: «since» + təkrar sayı. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10271, 131, 'g11-eng-cond-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he will check the figures, he would find the mistake.", "B": "If they have saved enough money, they would buy a new house.", "C": "If we will leave now, we would catch the train.", "D": "Unless she will practise every day, she won''t win the competition.", "E": "If we had left now, we would have caught the train."}'::jsonb, 'E', NULL, 'Correct: «If we had left now, we would have caught the train.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10272, 131, 'g11-eng-cond-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless she ___ (practise) every day, she won''t win the competition. (2) If I ___ (have) more time, I would visit my grandparents. (3) I wish it ___ raining. It has been raining for days. (stop)', NULL, NULL, '{"A": "practises / have / would stop", "B": "practises / had / would stop", "C": "practises / had / stops", "D": "practises / have had / would stop", "E": "practises / will have / would stop"}'::jsonb, 'B', NULL, '(1) practises — Unless = if not; zaman/şərt hissəsində Present Simple (2) had — II tip şərt: If + Past Simple, would + V1 (3) would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu');
INSERT INTO public.questions VALUES (10273, 131, 'g11-eng-cond-q1-03', 1, 3, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If he had checked the figures, he would have found the mistake. If we would have left now, we would have caught the train.", "B": "If he had checked the figures, he would have found the mistake. If we had left now, we would have caught the train.", "C": "If he will have checked the figures, he would have found the mistake. If we had left now, we would have caught the train.", "D": "If he had checked the figures, he would have found the mistake. If we have left now, we would have caught the train.", "E": "If he would have checked the figures, he would have found the mistake. If we had left now, we would have caught the train."}'::jsonb, 'B', NULL, 'had checked — III tip şərt: şərt hissəsində Past Perfect; had left — III tip şərt: şərt hissəsində Past Perfect.');
INSERT INTO public.questions VALUES (10274, 131, 'g11-eng-cond-q1-04', 1, 4, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If she had studied medicine, she would be a doctor now. If I had more time, I would visit my grandparents.", "B": "If she had studied medicine, she would be a doctor now. If I have more time, I would visit my grandparents.", "C": "If she had studied medicine, she will be a doctor now. If I had more time, I would visit my grandparents.", "D": "If she had studied medicine, she is a doctor now. If I had more time, I would visit my grandparents.", "E": "If she had studied medicine, she would be a doctor now. If I have had more time, I would visit my grandparents."}'::jsonb, 'A', NULL, 'would be — Qarışıq şərt: keçmiş şərt, indiki nəticə; had — II tip şərt: If + Past Simple, would + V1.');
INSERT INTO public.questions VALUES (10275, 131, 'g11-eng-cond-q1-05', 1, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If we had left now, we had caught the train.", "B": "Unless I won''t have more time, I won''t visit my grandparents.", "C": "Unless she practises every day, she won''t win the competition.", "D": "If they would have saved enough money, they would have bought a new house.", "E": "If I have more time, I would visit my grandparents."}'::jsonb, 'C', NULL, 'Correct: «Unless she practises every day, she won''t win the competition.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10276, 131, 'g11-eng-cond-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If we had left now, we ___ (catch) the train. (2) If he had checked the figures, he ___ (find) the mistake. (3) If I ___ (have) more time, I would visit my grandparents.', NULL, NULL, '{"A": "would have caught / would have found / had", "B": "would have caught / would have found / will have", "C": "had caught / would have found / had", "D": "will catch / would have found / had", "E": "would have caught / will have found / had"}'::jsonb, 'A', NULL, '(1) would have caught — III tip şərt: If + Past Perfect, would have + V3 (2) would have found — III tip şərt: If + Past Perfect, would have + V3 (3) had — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (10277, 131, 'g11-eng-cond-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she practises every day, she would win the competition.", "B": "Unless you would study harder, you won''t pass the exam.", "C": "If we had left now, we will have caught the train.", "D": "If he had checked the figures, he would have found the mistake.", "E": "If I wasn''t been afraid of flying, I would have visited you last summer."}'::jsonb, 'D', NULL, 'Correct: «If he had checked the figures, he would have found the mistake.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10278, 131, 'g11-eng-cond-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If we ___ (leave) now, we would have caught the train. (2) If you had studied harder, you ___ (pass) the exam. (3) If he had taken the medicine, he ___ ill now. (not feel)', NULL, NULL, '{"A": "had left / would have passed / won''t feel", "B": "had left / will pass / wouldn''t feel", "C": "have left / would have passed / wouldn''t feel", "D": "had left / would have passed / doesn''t feel", "E": "had left / would have passed / wouldn''t feel"}'::jsonb, 'E', NULL, '(1) had left — III tip şərt: şərt hissəsində Past Perfect (2) would have passed — III tip şərt: If + Past Perfect, would have + V3 (3) wouldn''t feel — Qarışıq şərt: keçmiş şərt → indiki nəticə');
INSERT INTO public.questions VALUES (10279, 131, 'g11-eng-cond-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you ___ (study) harder, you would have passed the exam. (2) If I ___ afraid of flying, I would have visited you last summer. (not be) (3) I wish I ___ taller. (be)', NULL, NULL, '{"A": "would have studied / weren''t / were", "B": "will have studied / weren''t / were", "C": "had studied / weren''t / were", "D": "had studied / am not / were", "E": "had studied / weren''t / being"}'::jsonb, 'C', NULL, '(1) had studied — III tip şərt: şərt hissəsində Past Perfect (2) weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə (3) were — wish + were (bütün şəxslərdə)');
INSERT INTO public.questions VALUES (10280, 131, 'g11-eng-cond-q1-10', 1, 10, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Had I known about the meeting, I had attended it. If he had checked the figures, he would have found the mistake.", "B": "Had I known about the meeting, I will attend it. If he had checked the figures, he would have found the mistake.", "C": "Had I known about the meeting, I would have attended it. If he had checked the figures, he will find the mistake.", "D": "Had I known about the meeting, I would have attended it. If he had checked the figures, he would have found the mistake.", "E": "Had I known about the meeting, I attended it. If he had checked the figures, he would have found the mistake."}'::jsonb, 'D', NULL, 'would have attended — İnversiya: Had I known = If I had known; would have found — III tip şərt: If + Past Perfect, would have + V3.');
INSERT INTO public.questions VALUES (10281, 131, 'g11-eng-cond-q1-11', 1, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I wish I ___ taller. (be) (2) If I ___ afraid of flying, I would have visited you last summer. (not be) (3) If we ___ (leave) now, we would catch the train.', NULL, NULL, '{"A": "were / won''t be / left", "B": "were / weren''t / left", "C": "were / weren''t / will leave", "D": "were / weren''t / have left", "E": "am / weren''t / left"}'::jsonb, 'B', NULL, '(1) were — wish + were (bütün şəxslərdə) (2) weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə (3) left — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (10282, 131, 'g11-eng-cond-q1-12', 1, 12, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If she will have practised every day, she would have won the competition. If she had studied medicine, she would be a doctor now.", "B": "If she had practised every day, she would have won the competition. If she had studied medicine, she will be a doctor now.", "C": "If she had practised every day, she would have won the competition. If she had studied medicine, she is a doctor now.", "D": "If she had practised every day, she would have won the competition. If she had studied medicine, she would be a doctor now.", "E": "If she would have practised every day, she would have won the competition. If she had studied medicine, she would be a doctor now."}'::jsonb, 'D', NULL, 'had practised — III tip şərt: şərt hissəsində Past Perfect; would be — Qarışıq şərt: keçmiş şərt, indiki nəticə.');
INSERT INTO public.questions VALUES (10283, 131, 'g11-eng-cond-q1-13', 1, 13, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If they save enough money, they would buy a new house. If she practised every day, she would win the competition.", "B": "If they saved enough money, they would buy a new house. If she will practise every day, she would win the competition.", "C": "If they will save enough money, they would buy a new house. If she practised every day, she would win the competition.", "D": "If they saved enough money, they would buy a new house. If she practised every day, she would win the competition.", "E": "If they saved enough money, they would buy a new house. If she has practised every day, she would win the competition."}'::jsonb, 'D', NULL, 'saved — II tip şərt: If + Past Simple, would + V1; practised — II tip şərt: If + Past Simple, would + V1.');
INSERT INTO public.questions VALUES (10284, 131, 'g11-eng-cond-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless she will practise every day, she won''t win the competition.", "B": "If only I have driven more carefully yesterday!", "C": "If she had practised every day, she will have won the competition.", "D": "If she had studied medicine, she will be a doctor now.", "E": "If he checked the figures, he would find the mistake."}'::jsonb, 'E', NULL, 'Correct: «If he checked the figures, he would find the mistake.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10285, 131, 'g11-eng-cond-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless you ___ (study) harder, you won''t pass the exam. (2) If they ___ (save) enough money, they would have bought a new house. (3) If I had had more time, I ___ (visit) my grandparents.', NULL, NULL, '{"A": "won''t study / had saved / would have visited", "B": "would study / had saved / would have visited", "C": "study / had saved / will visit", "D": "study / have saved / would have visited", "E": "study / had saved / would have visited"}'::jsonb, 'E', NULL, '(1) study — Unless = if not; zaman/şərt hissəsində Present Simple (2) had saved — III tip şərt: şərt hissəsində Past Perfect (3) would have visited — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (10286, 131, 'g11-eng-cond-q1-16', 1, 16, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If she practises every day, she would win the competition. If only I had driven more carefully yesterday!", "B": "If she practised every day, she would win the competition. If only I have driven more carefully yesterday!", "C": "If she practised every day, she would win the competition. If only I drive more carefully yesterday!", "D": "If she practised every day, she would win the competition. If only I had driven more carefully yesterday!", "E": "If she practised every day, she would win the competition. If only I drove more carefully yesterday!"}'::jsonb, 'D', NULL, 'practised — II tip şərt: If + Past Simple, would + V1; had driven — If only + Past Perfect: keçmişə təəssüf.');
INSERT INTO public.questions VALUES (10287, 131, 'g11-eng-cond-q1-17', 1, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I ___ afraid of flying, I would have visited you last summer. (not be) (2) If you ___ (study) harder, you would have passed the exam. (3) If he ___ (check) the figures, he would have found the mistake.', NULL, NULL, '{"A": "weren''t / have studied / had checked", "B": "won''t be / had studied / had checked", "C": "weren''t / had studied / would have checked", "D": "weren''t / would have studied / had checked", "E": "weren''t / had studied / had checked"}'::jsonb, 'E', NULL, '(1) weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə (2) had studied — III tip şərt: şərt hissəsində Past Perfect (3) had checked — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (10288, 131, 'g11-eng-cond-q1-18', 1, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless they ___ (save) enough money, they won''t buy a new house. (2) If you ___ (study) harder, you would have passed the exam. (3) If you had studied harder, you ___ (pass) the exam.', NULL, NULL, '{"A": "save / would have studied / would have passed", "B": "save / had studied / will have passed", "C": "save / have studied / would have passed", "D": "save / had studied / had passed", "E": "save / had studied / would have passed"}'::jsonb, 'E', NULL, '(1) save — Unless = if not; zaman/şərt hissəsində Present Simple (2) had studied — III tip şərt: şərt hissəsində Past Perfect (3) would have passed — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (10289, 131, 'g11-eng-cond-q1-19', 1, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If they had saved enough money, they will buy a new house.", "B": "Unless you would study harder, you won''t pass the exam.", "C": "Unless we would leave now, we won''t catch the train.", "D": "If she had studied medicine, she is a doctor now.", "E": "Unless she practises every day, she won''t win the competition."}'::jsonb, 'E', NULL, 'Correct: «Unless she practises every day, she won''t win the competition.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10290, 131, 'g11-eng-cond-q1-20', 1, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If only I ___ more carefully yesterday! (drive) (2) Unless I ___ (have) more time, I won''t visit my grandparents. (3) Unless he ___ (check) the figures, he won''t find the mistake.', NULL, NULL, '{"A": "had driven / have / checks", "B": "drive / have / checks", "C": "had driven / won''t have / checks", "D": "have driven / have / checks", "E": "had driven / would have / checks"}'::jsonb, 'A', NULL, '(1) had driven — If only + Past Perfect: keçmişə təəssüf (2) have — Unless = if not; zaman/şərt hissəsində Present Simple (3) checks — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (10291, 131, 'g11-eng-cond-q1-21', 1, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If they had saved enough money, they ___ (buy) a new house. (2) If she had studied medicine, she ___ a doctor now. (be) (3) She wishes she ___ to the party last night. (go)', NULL, NULL, '{"A": "would have bought / had been / had gone", "B": "will buy / would be / had gone", "C": "would have bought / would be / has gone", "D": "would have bought / would be / had gone", "E": "would have bought / will be / had gone"}'::jsonb, 'D', NULL, '(1) would have bought — III tip şərt: If + Past Perfect, would have + V3 (2) would be — Qarışıq şərt: keçmiş şərt, indiki nəticə (3) had gone — wish + Past Perfect: keçmişə təəssüf');
INSERT INTO public.questions VALUES (10292, 131, 'g11-eng-cond-q1-22', 1, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he had checked the figures, he would have found the mistake.", "B": "If only I have driven more carefully yesterday!", "C": "Unless she would practise every day, she won''t win the competition.", "D": "If I had had more time, I will visit my grandparents.", "E": "If you had studied harder, you will have passed the exam."}'::jsonb, 'A', NULL, 'Correct: «If he had checked the figures, he would have found the mistake.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10293, 131, 'g11-eng-cond-q1-23', 1, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he have checked the figures, he would have found the mistake.", "B": "If you will study harder, you would pass the exam.", "C": "If I wasn''t been afraid of flying, I would have visited you last summer.", "D": "If they had saved enough money, they would have bought a new house.", "E": "Unless she won''t practise every day, she won''t win the competition."}'::jsonb, 'D', NULL, 'Correct: «If they had saved enough money, they would have bought a new house.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10294, 131, 'g11-eng-cond-q1-24', 1, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Had I known about the meeting, I would have attended it.", "B": "If you had studied harder, you will have passed the exam.", "C": "If they will save enough money, they would buy a new house.", "D": "If I won''t be afraid of flying, I would have visited you last summer.", "E": "If he have checked the figures, he would have found the mistake."}'::jsonb, 'A', NULL, 'Correct: «Had I known about the meeting, I would have attended it.» — İnversiya: Had I known = If I had known. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10295, 131, 'g11-eng-cond-q1-25', 1, 25, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If we will have left now, we would have caught the train. I wish I were taller.", "B": "If we had left now, we would have caught the train. I wish I am taller.", "C": "If we had left now, we would have caught the train. I wish I were taller.", "D": "If we had left now, we would have caught the train. I wish I being taller.", "E": "If we have left now, we would have caught the train. I wish I were taller."}'::jsonb, 'C', NULL, 'had left — III tip şərt: şərt hissəsində Past Perfect; were — wish + were (bütün şəxslərdə).');
INSERT INTO public.questions VALUES (10296, 131, 'g11-eng-cond-q1-26', 1, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have more time, I would visit my grandparents.", "B": "Should you need any help, called me.", "C": "Had I known about the meeting, I will attend it.", "D": "I wish it stopped to raining. It has been raining for days.", "E": "If he had checked the figures, he would have found the mistake."}'::jsonb, 'E', NULL, 'Correct: «If he had checked the figures, he would have found the mistake.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10297, 131, 'g11-eng-cond-q1-27', 1, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you had studied harder, you had passed the exam.", "B": "I wish I will know the answer to this question.", "C": "I wish it stops raining. It has been raining for days.", "D": "If she practised every day, she would win the competition.", "E": "If I had had more time, I had visited my grandparents."}'::jsonb, 'D', NULL, 'Correct: «If she practised every day, she would win the competition.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10298, 131, 'g11-eng-cond-q1-28', 1, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If they had saved enough money, they would have bought a new house. If they have saved enough money, they would buy a new house.", "B": "If they had saved enough money, they would have bought a new house. If they saved enough money, they would buy a new house.", "C": "If they would have saved enough money, they would have bought a new house. If they saved enough money, they would buy a new house.", "D": "If they have saved enough money, they would have bought a new house. If they saved enough money, they would buy a new house.", "E": "If they had saved enough money, they would have bought a new house. If they will save enough money, they would buy a new house."}'::jsonb, 'B', NULL, 'had saved — III tip şərt: şərt hissəsində Past Perfect; saved — II tip şərt: If + Past Simple, would + V1.');
INSERT INTO public.questions VALUES (10299, 131, 'g11-eng-cond-q1-29', 1, 29, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Unless I have more time, I won''t visit my grandparents. If we had left now, we would have caught the train.", "B": "Unless I won''t have more time, I won''t visit my grandparents. If we had left now, we would have caught the train.", "C": "Unless I will have more time, I won''t visit my grandparents. If we had left now, we would have caught the train.", "D": "Unless I have more time, I won''t visit my grandparents. If we would have left now, we would have caught the train.", "E": "Unless I have more time, I won''t visit my grandparents. If we have left now, we would have caught the train."}'::jsonb, 'A', NULL, 'have — Unless = if not; zaman/şərt hissəsində Present Simple; had left — III tip şərt: şərt hissəsində Past Perfect.');
INSERT INTO public.questions VALUES (10300, 131, 'g11-eng-cond-q1-30', 1, 30, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Unless you study harder, you won''t pass the exam. If she had studied medicine, she will be a doctor now.", "B": "Unless you will study harder, you won''t pass the exam. If she had studied medicine, she would be a doctor now.", "C": "Unless you study harder, you won''t pass the exam. If she had studied medicine, she is a doctor now.", "D": "Unless you study harder, you won''t pass the exam. If she had studied medicine, she would be a doctor now.", "E": "Unless you would study harder, you won''t pass the exam. If she had studied medicine, she would be a doctor now."}'::jsonb, 'D', NULL, 'study — Unless = if not; zaman/şərt hissəsində Present Simple; would be — Qarışıq şərt: keçmiş şərt, indiki nəticə.');
INSERT INTO public.questions VALUES (10301, 131, 'g11-eng-cond-q2-01', 2, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If we left now, we would catch the train.", "B": "Unless they won''t save enough money, they won''t buy a new house.", "C": "If she had studied medicine, she is a doctor now.", "D": "If I won''t be afraid of flying, I would have visited you last summer.", "E": "Unless you will study harder, you won''t pass the exam."}'::jsonb, 'A', NULL, 'Correct: «If we left now, we would catch the train.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10302, 131, 'g11-eng-cond-q2-02', 2, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he had checked the figures, he would have found the mistake.", "B": "If she have practised every day, she would have won the competition.", "C": "If I won''t be afraid of flying, I would have visited you last summer.", "D": "If you will study harder, you would pass the exam.", "E": "If I had had more time, I will visit my grandparents."}'::jsonb, 'A', NULL, 'Correct: «If he had checked the figures, he would have found the mistake.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10303, 131, 'g11-eng-cond-q2-03', 2, 3, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If you had studied harder, you will pass the exam. Unless he checks the figures, he won''t find the mistake.", "B": "If you had studied harder, you would have passed the exam. Unless he won''t check the figures, he won''t find the mistake.", "C": "If you had studied harder, you would have passed the exam. Unless he checks the figures, he won''t find the mistake.", "D": "If you had studied harder, you had passed the exam. Unless he checks the figures, he won''t find the mistake.", "E": "If you had studied harder, you will have passed the exam. Unless he checks the figures, he won''t find the mistake."}'::jsonb, 'C', NULL, 'would have passed — III tip şərt: If + Past Perfect, would have + V3; checks — Unless = if not; zaman/şərt hissəsində Present Simple.');
INSERT INTO public.questions VALUES (10304, 131, 'g11-eng-cond-q2-04', 2, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless we ___ (leave) now, we won''t catch the train. (2) I wish I ___ taller. (be) (3) If I ___ (have) more time, I would have visited my grandparents.', NULL, NULL, '{"A": "leave / were / will have had", "B": "would leave / were / had had", "C": "leave / am / had had", "D": "leave / being / had had", "E": "leave / were / had had"}'::jsonb, 'E', NULL, '(1) leave — Unless = if not; zaman/şərt hissəsində Present Simple (2) were — wish + were (bütün şəxslərdə) (3) had had — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (10305, 131, 'g11-eng-cond-q2-05', 2, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I wish it stops raining. It has been raining for days.", "B": "If he had taken the medicine, he won''t feel ill now.", "C": "If he checks the figures, he would find the mistake.", "D": "She wishes she had gone to the party last night.", "E": "Unless he won''t check the figures, he won''t find the mistake."}'::jsonb, 'D', NULL, 'Correct: «She wishes she had gone to the party last night.» — wish + Past Perfect: keçmişə təəssüf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10306, 131, 'g11-eng-cond-q2-06', 2, 6, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If they had saved enough money, they would have bought a new house. I wish I am taller.", "B": "If they had saved enough money, they would have bought a new house. I wish I were taller.", "C": "If they had saved enough money, they would have bought a new house. I wish I being taller.", "D": "If they had saved enough money, they would have bought a new house. I wish I will be taller.", "E": "If they had saved enough money, they will buy a new house. I wish I were taller."}'::jsonb, 'B', NULL, 'would have bought — III tip şərt: If + Past Perfect, would have + V3; were — wish + were (bütün şəxslərdə).');
INSERT INTO public.questions VALUES (10307, 131, 'g11-eng-cond-q2-07', 2, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless you study harder, you won''t pass the exam.", "B": "If we have left now, we would have caught the train.", "C": "If I would have had more time, I would have visited my grandparents.", "D": "If we had left now, we had caught the train.", "E": "If he would have checked the figures, he would have found the mistake."}'::jsonb, 'A', NULL, 'Correct: «Unless you study harder, you won''t pass the exam.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10308, 131, 'g11-eng-cond-q2-08', 2, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If we ___ (leave) now, we would have caught the train. (2) If they had saved enough money, they ___ (buy) a new house. (3) If only I ___ more carefully yesterday! (drive)', NULL, NULL, '{"A": "had left / would have bought / have driven", "B": "had left / would have bought / had driven", "C": "had left / would have bought / drive", "D": "have left / would have bought / had driven", "E": "had left / will have bought / had driven"}'::jsonb, 'B', NULL, '(1) had left — III tip şərt: şərt hissəsində Past Perfect (2) would have bought — III tip şərt: If + Past Perfect, would have + V3 (3) had driven — If only + Past Perfect: keçmişə təəssüf');
INSERT INTO public.questions VALUES (10309, 131, 'g11-eng-cond-q2-09', 2, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she had studied medicine, she is a doctor now.", "B": "If he had checked the figures, he would have found the mistake.", "C": "If she practises every day, she would win the competition.", "D": "If only I drove more carefully yesterday!", "E": "If he have checked the figures, he would have found the mistake."}'::jsonb, 'B', NULL, 'Correct: «If he had checked the figures, he would have found the mistake.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10310, 131, 'g11-eng-cond-q2-10', 2, 10, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Unless she practises every day, she won''t win the competition. If I had had more time, I would have visited my grandparents.", "B": "Unless she practises every day, she won''t win the competition. If I had had more time, I had visited my grandparents.", "C": "Unless she practises every day, she won''t win the competition. If I had had more time, I will have visited my grandparents.", "D": "Unless she will practise every day, she won''t win the competition. If I had had more time, I would have visited my grandparents.", "E": "Unless she won''t practise every day, she won''t win the competition. If I had had more time, I would have visited my grandparents."}'::jsonb, 'A', NULL, 'practises — Unless = if not; zaman/şərt hissəsində Present Simple; would have visited — III tip şərt: If + Past Perfect, would have + V3.');
INSERT INTO public.questions VALUES (10311, 131, 'g11-eng-cond-q2-11', 2, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If they have saved enough money, they would buy a new house.", "B": "Unless he checks the figures, he won''t find the mistake.", "C": "If he had taken the medicine, he doesn''t feel ill now.", "D": "If I will have more time, I would visit my grandparents.", "E": "If you had studied harder, you will pass the exam."}'::jsonb, 'B', NULL, 'Correct: «Unless he checks the figures, he won''t find the mistake.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10312, 131, 'g11-eng-cond-q2-12', 2, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have more time, I would visit my grandparents.", "B": "If she had studied medicine, she is a doctor now.", "C": "Unless you study harder, you won''t pass the exam.", "D": "If I had had more time, I will visit my grandparents.", "E": "Unless I would have more time, I won''t visit my grandparents."}'::jsonb, 'C', NULL, 'Correct: «Unless you study harder, you won''t pass the exam.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10313, 131, 'g11-eng-cond-q2-13', 2, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If they had saved enough money, they will have bought a new house.", "B": "I wish I knowing the answer to this question.", "C": "If I am not afraid of flying, I would have visited you last summer.", "D": "If we left now, we would catch the train.", "E": "If he had taken the medicine, he doesn''t feel ill now."}'::jsonb, 'D', NULL, 'Correct: «If we left now, we would catch the train.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10314, 131, 'g11-eng-cond-q2-14', 2, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If I will have had more time, I would have visited my grandparents. If I weren''t afraid of flying, I would have visited you last summer.", "B": "If I would have had more time, I would have visited my grandparents. If I weren''t afraid of flying, I would have visited you last summer.", "C": "If I had had more time, I would have visited my grandparents. If I weren''t afraid of flying, I would have visited you last summer.", "D": "If I had had more time, I would have visited my grandparents. If I am not afraid of flying, I would have visited you last summer.", "E": "If I had had more time, I would have visited my grandparents. If I wasn''t been afraid of flying, I would have visited you last summer."}'::jsonb, 'C', NULL, 'had had — III tip şərt: şərt hissəsində Past Perfect; weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə.');
INSERT INTO public.questions VALUES (10315, 131, 'g11-eng-cond-q2-15', 2, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you had studied harder, you ___ (pass) the exam. (2) If I had had more time, I ___ (visit) my grandparents. (3) If she had practised every day, she ___ (win) the competition.', NULL, NULL, '{"A": "would have passed / would have visited / would have won", "B": "would have passed / will have visited / would have won", "C": "will have passed / would have visited / would have won", "D": "would have passed / had visited / would have won", "E": "will pass / would have visited / would have won"}'::jsonb, 'A', NULL, '(1) would have passed — III tip şərt: If + Past Perfect, would have + V3 (2) would have visited — III tip şərt: If + Past Perfect, would have + V3 (3) would have won — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (10316, 131, 'g11-eng-cond-q2-16', 2, 16, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If we would have left now, we would have caught the train. If we left now, we would catch the train.", "B": "If we had left now, we would have caught the train. If we left now, we would catch the train.", "C": "If we will have left now, we would have caught the train. If we left now, we would catch the train.", "D": "If we had left now, we would have caught the train. If we will leave now, we would catch the train.", "E": "If we had left now, we would have caught the train. If we leave now, we would catch the train."}'::jsonb, 'B', NULL, 'had left — III tip şərt: şərt hissəsində Past Perfect; left — II tip şərt: If + Past Simple, would + V1.');
INSERT INTO public.questions VALUES (10317, 131, 'g11-eng-cond-q2-17', 2, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If only I ___ more carefully yesterday! (drive) (2) Had I known about the meeting, I ___ it. (attend) (3) Should you need any help, ___ me. (call)', NULL, NULL, '{"A": "had driven / attended / call", "B": "had driven / would have attended / call", "C": "had driven / had attended / call", "D": "had driven / will attend / call", "E": "had driven / would have attended / called"}'::jsonb, 'B', NULL, '(1) had driven — If only + Past Perfect: keçmişə təəssüf (2) would have attended — İnversiya: Had I known = If I had known (3) call — İnversiya: Should you need = If you need; əmr');
INSERT INTO public.questions VALUES (10318, 131, 'g11-eng-cond-q2-18', 2, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she had practised every day, she ___ (win) the competition. (2) If he had checked the figures, he ___ (find) the mistake. (3) If you ___ (study) harder, you would have passed the exam.', NULL, NULL, '{"A": "would have won / would have found / had studied", "B": "would have won / will find / had studied", "C": "would have won / would have found / will have studied", "D": "would have won / had found / had studied", "E": "had won / would have found / had studied"}'::jsonb, 'A', NULL, '(1) would have won — III tip şərt: If + Past Perfect, would have + V3 (2) would have found — III tip şərt: If + Past Perfect, would have + V3 (3) had studied — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (10319, 131, 'g11-eng-cond-q2-19', 2, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she had practised every day, she had won the competition.", "B": "She wishes she goes to the party last night.", "C": "If we would have left now, we would have caught the train.", "D": "Unless we leave now, we won''t catch the train.", "E": "If you study harder, you would pass the exam."}'::jsonb, 'D', NULL, 'Correct: «Unless we leave now, we won''t catch the train.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10320, 131, 'g11-eng-cond-q2-20', 2, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you ___ (study) harder, you would have passed the exam. (2) If I ___ afraid of flying, I would have visited you last summer. (not be) (3) Should you need any help, ___ me. (call)', NULL, NULL, '{"A": "had studied / wasn''t been / call", "B": "will have studied / weren''t / call", "C": "had studied / weren''t / calling", "D": "had studied / am not / call", "E": "had studied / weren''t / call"}'::jsonb, 'E', NULL, '(1) had studied — III tip şərt: şərt hissəsində Past Perfect (2) weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə (3) call — İnversiya: Should you need = If you need; əmr');
INSERT INTO public.questions VALUES (10321, 131, 'g11-eng-cond-q2-21', 2, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If I had had more time, I would have visited my grandparents. If we had left now, we had caught the train.", "B": "If I had had more time, I would have visited my grandparents. If we had left now, we would have caught the train.", "C": "If I had had more time, I would have visited my grandparents. If we had left now, we will catch the train.", "D": "If I had had more time, I will have visited my grandparents. If we had left now, we would have caught the train.", "E": "If I had had more time, I will visit my grandparents. If we had left now, we would have caught the train."}'::jsonb, 'B', NULL, 'would have visited — III tip şərt: If + Past Perfect, would have + V3; would have caught — III tip şərt: If + Past Perfect, would have + V3.');
INSERT INTO public.questions VALUES (10322, 131, 'g11-eng-cond-q2-22', 2, 22, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Unless we would leave now, we won''t catch the train. If you had studied harder, you would have passed the exam.", "B": "Unless we leave now, we won''t catch the train. If you had studied harder, you will have passed the exam.", "C": "Unless we leave now, we won''t catch the train. If you had studied harder, you had passed the exam.", "D": "Unless we leave now, we won''t catch the train. If you had studied harder, you would have passed the exam.", "E": "Unless we will leave now, we won''t catch the train. If you had studied harder, you would have passed the exam."}'::jsonb, 'D', NULL, 'leave — Unless = if not; zaman/şərt hissəsində Present Simple; would have passed — III tip şərt: If + Past Perfect, would have + V3.');
INSERT INTO public.questions VALUES (10323, 131, 'g11-eng-cond-q2-23', 2, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Should you need any help, ___ me. (call) (2) I wish I ___ the answer to this question. (know) (3) Unless I ___ (have) more time, I won''t visit my grandparents.', NULL, NULL, '{"A": "call / knew / have", "B": "called / knew / have", "C": "call / knew / will have", "D": "call / knowing / have", "E": "to call / knew / have"}'::jsonb, 'A', NULL, '(1) call — İnversiya: Should you need = If you need; əmr (2) knew — wish + Past Simple: indiki vəziyyətə təəssüf (3) have — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (10324, 131, 'g11-eng-cond-q2-24', 2, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If only I drove more carefully yesterday!", "B": "Unless you would study harder, you won''t pass the exam.", "C": "If you had studied harder, you will have passed the exam.", "D": "If we will leave now, we would catch the train.", "E": "If you had studied harder, you would have passed the exam."}'::jsonb, 'E', NULL, 'Correct: «If you had studied harder, you would have passed the exam.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10325, 131, 'g11-eng-cond-q2-25', 2, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If he had checked the figures, he ___ (find) the mistake. (2) Should you need any help, ___ me. (call) (3) If only I ___ more carefully yesterday! (drive)', NULL, NULL, '{"A": "would have found / call / have driven", "B": "would have found / call / drive", "C": "will find / call / had driven", "D": "would have found / calling / had driven", "E": "would have found / call / had driven"}'::jsonb, 'E', NULL, '(1) would have found — III tip şərt: If + Past Perfect, would have + V3 (2) call — İnversiya: Should you need = If you need; əmr (3) had driven — If only + Past Perfect: keçmişə təəssüf');
INSERT INTO public.questions VALUES (10326, 131, 'g11-eng-cond-q2-26', 2, 26, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I wish it would stop raining. It has been raining for days. Unless she will practise every day, she won''t win the competition.", "B": "I wish it would stop raining. It has been raining for days. Unless she won''t practise every day, she won''t win the competition.", "C": "I wish it would stop raining. It has been raining for days. Unless she practises every day, she won''t win the competition.", "D": "I wish it stopped to raining. It has been raining for days. Unless she practises every day, she won''t win the competition.", "E": "I wish it stops raining. It has been raining for days. Unless she practises every day, she won''t win the competition."}'::jsonb, 'C', NULL, 'would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu; practises — Unless = if not; zaman/şərt hissəsində Present Simple.');
INSERT INTO public.questions VALUES (10327, 131, 'g11-eng-cond-q2-27', 2, 27, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Unless he will check the figures, he won''t find the mistake. If I had had more time, I would have visited my grandparents.", "B": "Unless he won''t check the figures, he won''t find the mistake. If I had had more time, I would have visited my grandparents.", "C": "Unless he checks the figures, he won''t find the mistake. If I will have had more time, I would have visited my grandparents.", "D": "Unless he checks the figures, he won''t find the mistake. If I have had more time, I would have visited my grandparents.", "E": "Unless he checks the figures, he won''t find the mistake. If I had had more time, I would have visited my grandparents."}'::jsonb, 'E', NULL, 'checks — Unless = if not; zaman/şərt hissəsində Present Simple; had had — III tip şərt: şərt hissəsində Past Perfect.');
INSERT INTO public.questions VALUES (10328, 131, 'g11-eng-cond-q2-28', 2, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If you had studied harder, you ___ (pass) the exam. (2) Unless he ___ (check) the figures, he won''t find the mistake. (3) Unless she ___ (practise) every day, she won''t win the competition.', NULL, NULL, '{"A": "would have passed / checks / practises", "B": "would have passed / checks / will practise", "C": "would have passed / would check / practises", "D": "would have passed / won''t check / practises", "E": "would have passed / checks / won''t practise"}'::jsonb, 'A', NULL, '(1) would have passed — III tip şərt: If + Past Perfect, would have + V3 (2) checks — Unless = if not; zaman/şərt hissəsində Present Simple (3) practises — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (10329, 131, 'g11-eng-cond-q2-29', 2, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she ___ (practise) every day, she would have won the competition. (2) Unless she ___ (practise) every day, she won''t win the competition. (3) I wish it ___ raining. It has been raining for days. (stop)', NULL, NULL, '{"A": "had practised / practises / would stop", "B": "had practised / won''t practise / would stop", "C": "had practised / practises / stops", "D": "will have practised / practises / would stop", "E": "have practised / practises / would stop"}'::jsonb, 'A', NULL, '(1) had practised — III tip şərt: şərt hissəsində Past Perfect (2) practises — Unless = if not; zaman/şərt hissəsində Present Simple (3) would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu');
INSERT INTO public.questions VALUES (10330, 131, 'g11-eng-cond-q2-30', 2, 30, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If I had had more time, I would have visited my grandparents. If I would have had more time, I would have visited my grandparents.", "B": "If I had had more time, I would have visited my grandparents. If I will have had more time, I would have visited my grandparents.", "C": "If I had had more time, I would have visited my grandparents. If I had had more time, I would have visited my grandparents.", "D": "If I had had more time, I had visited my grandparents. If I had had more time, I would have visited my grandparents.", "E": "If I had had more time, I will visit my grandparents. If I had had more time, I would have visited my grandparents."}'::jsonb, 'C', NULL, 'would have visited — III tip şərt: If + Past Perfect, would have + V3; had had — III tip şərt: şərt hissəsində Past Perfect.');
INSERT INTO public.questions VALUES (10331, 131, 'g11-eng-cond-q3-01', 3, 1, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If you had studied harder, you would have passed the exam. If I weren''t afraid of flying, I would have visited you last summer.", "B": "If you had studied harder, you would have passed the exam. If I am not afraid of flying, I would have visited you last summer.", "C": "If you had studied harder, you will pass the exam. If I weren''t afraid of flying, I would have visited you last summer.", "D": "If you had studied harder, you would have passed the exam. If I wasn''t been afraid of flying, I would have visited you last summer.", "E": "If you had studied harder, you had passed the exam. If I weren''t afraid of flying, I would have visited you last summer."}'::jsonb, 'A', NULL, 'would have passed — III tip şərt: If + Past Perfect, would have + V3; weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə.');
INSERT INTO public.questions VALUES (10332, 131, 'g11-eng-cond-q3-02', 3, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Unless they ___ (save) enough money, they won''t buy a new house. (2) I wish it ___ raining. It has been raining for days. (stop) (3) If he had checked the figures, he ___ (find) the mistake.', NULL, NULL, '{"A": "save / stops / would have found", "B": "save / stopped to / would have found", "C": "save / would stop / will find", "D": "save / would stop / would have found", "E": "won''t save / would stop / would have found"}'::jsonb, 'D', NULL, '(1) save — Unless = if not; zaman/şərt hissəsində Present Simple (2) would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu (3) would have found — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (10333, 131, 'g11-eng-cond-q3-03', 3, 3, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If she will practise every day, she would win the competition. Unless they save enough money, they won''t buy a new house.", "B": "If she practised every day, she would win the competition. Unless they save enough money, they won''t buy a new house.", "C": "If she practised every day, she would win the competition. Unless they would save enough money, they won''t buy a new house.", "D": "If she practises every day, she would win the competition. Unless they save enough money, they won''t buy a new house.", "E": "If she practised every day, she would win the competition. Unless they won''t save enough money, they won''t buy a new house."}'::jsonb, 'B', NULL, 'practised — II tip şərt: If + Past Simple, would + V1; save — Unless = if not; zaman/şərt hissəsində Present Simple.');
INSERT INTO public.questions VALUES (10334, 131, 'g11-eng-cond-q3-04', 3, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she ___ (practise) every day, she would have won the competition. (2) If she ___ (practise) every day, she would win the competition. (3) Had I known about the meeting, I ___ it. (attend)', NULL, NULL, '{"A": "had practised / will practise / would have attended", "B": "had practised / practised / would have attended", "C": "had practised / practised / attended", "D": "had practised / practised / will attend", "E": "had practised / practised / had attended"}'::jsonb, 'B', NULL, '(1) had practised — III tip şərt: şərt hissəsində Past Perfect (2) practised — II tip şərt: If + Past Simple, would + V1 (3) would have attended — İnversiya: Had I known = If I had known');
INSERT INTO public.questions VALUES (10335, 131, 'g11-eng-cond-q3-05', 3, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless we leave now, we won''t catch the train.", "B": "Unless you won''t study harder, you won''t pass the exam.", "C": "If she had practised every day, she will win the competition.", "D": "If I won''t be afraid of flying, I would have visited you last summer.", "E": "Unless he will check the figures, he won''t find the mistake."}'::jsonb, 'A', NULL, 'Correct: «Unless we leave now, we won''t catch the train.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10336, 131, 'g11-eng-cond-q3-06', 3, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If we will leave now, we would catch the train.", "B": "If you had studied harder, you had passed the exam.", "C": "If you had studied harder, you would have passed the exam.", "D": "Unless she won''t practise every day, she won''t win the competition.", "E": "If he has checked the figures, he would find the mistake."}'::jsonb, 'C', NULL, 'Correct: «If you had studied harder, you would have passed the exam.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10337, 131, 'g11-eng-cond-q3-07', 3, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have had more time, I would have visited my grandparents.", "B": "If she will practise every day, she would win the competition.", "C": "If he would have checked the figures, he would have found the mistake.", "D": "If we had left now, we will have caught the train.", "E": "Unless I have more time, I won''t visit my grandparents."}'::jsonb, 'E', NULL, 'Correct: «Unless I have more time, I won''t visit my grandparents.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10338, 131, 'g11-eng-cond-q3-08', 3, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I will have had more time, I would have visited my grandparents.", "B": "If we will leave now, we would catch the train.", "C": "If we had left now, we will catch the train.", "D": "Had I known about the meeting, I will attend it.", "E": "If they had saved enough money, they would have bought a new house."}'::jsonb, 'E', NULL, 'Correct: «If they had saved enough money, they would have bought a new house.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10339, 131, 'g11-eng-cond-q3-09', 3, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Had I known about the meeting, I ___ it. (attend) (2) If we had left now, we ___ (catch) the train. (3) If she had practised every day, she ___ (win) the competition.', NULL, NULL, '{"A": "had attended / would have caught / would have won", "B": "would have attended / will catch / would have won", "C": "would have attended / would have caught / would have won", "D": "will attend / would have caught / would have won", "E": "would have attended / would have caught / had won"}'::jsonb, 'C', NULL, '(1) would have attended — İnversiya: Had I known = If I had known (2) would have caught — III tip şərt: If + Past Perfect, would have + V3 (3) would have won — III tip şərt: If + Past Perfect, would have + V3');
INSERT INTO public.questions VALUES (10340, 131, 'g11-eng-cond-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She wishes she went to the party last night.", "B": "If you have studied harder, you would pass the exam.", "C": "If we had left now, we will catch the train.", "D": "If she has practised every day, she would win the competition.", "E": "If I weren''t afraid of flying, I would have visited you last summer."}'::jsonb, 'E', NULL, 'Correct: «If I weren''t afraid of flying, I would have visited you last summer.» — Qarışıq şərt: indiki şərt (were), keçmiş nəticə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10341, 131, 'g11-eng-cond-q3-11', 3, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If we ___ (leave) now, we would have caught the train. (2) Should you need any help, ___ me. (call) (3) If I ___ (have) more time, I would visit my grandparents.', NULL, NULL, '{"A": "had left / call / have had", "B": "had left / to call / had", "C": "had left / called / had", "D": "had left / call / had", "E": "will have left / call / had"}'::jsonb, 'D', NULL, '(1) had left — III tip şərt: şərt hissəsində Past Perfect (2) call — İnversiya: Should you need = If you need; əmr (3) had — II tip şərt: If + Past Simple, would + V1');
INSERT INTO public.questions VALUES (10342, 131, 'g11-eng-cond-q3-12', 3, 12, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If you had studied harder, you will have passed the exam. If I weren''t afraid of flying, I would have visited you last summer.", "B": "If you had studied harder, you had passed the exam. If I weren''t afraid of flying, I would have visited you last summer.", "C": "If you had studied harder, you would have passed the exam. If I weren''t afraid of flying, I would have visited you last summer.", "D": "If you had studied harder, you would have passed the exam. If I wasn''t been afraid of flying, I would have visited you last summer.", "E": "If you had studied harder, you will pass the exam. If I weren''t afraid of flying, I would have visited you last summer."}'::jsonb, 'C', NULL, 'would have passed — III tip şərt: If + Past Perfect, would have + V3; weren''t — Qarışıq şərt: indiki şərt (were), keçmiş nəticə.');
INSERT INTO public.questions VALUES (10343, 131, 'g11-eng-cond-q3-13', 3, 13, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If I had had more time, I would have visited my grandparents. If he has checked the figures, he would find the mistake.", "B": "If I had had more time, I would have visited my grandparents. If he checked the figures, he would find the mistake.", "C": "If I had had more time, I would have visited my grandparents. If he will check the figures, he would find the mistake.", "D": "If I have had more time, I would have visited my grandparents. If he checked the figures, he would find the mistake.", "E": "If I had had more time, I would have visited my grandparents. If he checks the figures, he would find the mistake."}'::jsonb, 'B', NULL, 'had had — III tip şərt: şərt hissəsində Past Perfect; checked — II tip şərt: If + Past Simple, would + V1.');
INSERT INTO public.questions VALUES (10344, 131, 'g11-eng-cond-q3-14', 3, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If we will have left now, we would have caught the train. If he had checked the figures, he would have found the mistake.", "B": "If we would have left now, we would have caught the train. If he had checked the figures, he would have found the mistake.", "C": "If we had left now, we would have caught the train. If he had checked the figures, he will find the mistake.", "D": "If we had left now, we would have caught the train. If he had checked the figures, he would have found the mistake.", "E": "If we have left now, we would have caught the train. If he had checked the figures, he would have found the mistake."}'::jsonb, 'D', NULL, 'had left — III tip şərt: şərt hissəsində Past Perfect; would have found — III tip şərt: If + Past Perfect, would have + V3.');
INSERT INTO public.questions VALUES (10345, 131, 'g11-eng-cond-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Unless you study harder, you won''t pass the exam.", "B": "Unless they would save enough money, they won''t buy a new house.", "C": "If you have studied harder, you would have passed the exam.", "D": "If I had had more time, I will visit my grandparents.", "E": "I wish it stops raining. It has been raining for days."}'::jsonb, 'A', NULL, 'Correct: «Unless you study harder, you won''t pass the exam.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10346, 131, 'g11-eng-cond-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I ___ (have) more time, I would visit my grandparents. (2) If only I ___ more carefully yesterday! (drive) (3) Unless we ___ (leave) now, we won''t catch the train.', NULL, NULL, '{"A": "have had / had driven / leave", "B": "had / had driven / leave", "C": "have / had driven / leave", "D": "will have / had driven / leave", "E": "had / had driven / won''t leave"}'::jsonb, 'B', NULL, '(1) had — II tip şərt: If + Past Simple, would + V1 (2) had driven — If only + Past Perfect: keçmişə təəssüf (3) leave — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (10347, 131, 'g11-eng-cond-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If she had practised every day, she would have won the competition.", "B": "If I won''t be afraid of flying, I would have visited you last summer.", "C": "I wish it will stop raining. It has been raining for days.", "D": "Unless you will study harder, you won''t pass the exam.", "E": "If I have had more time, I would visit my grandparents."}'::jsonb, 'A', NULL, 'Correct: «If she had practised every day, she would have won the competition.» — III tip şərt: If + Past Perfect, would have + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10348, 131, 'g11-eng-cond-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If I am not afraid of flying, I would have visited you last summer.", "B": "Unless you would study harder, you won''t pass the exam.", "C": "If he checked the figures, he would find the mistake.", "D": "Unless they would save enough money, they won''t buy a new house.", "E": "Unless I will have more time, I won''t visit my grandparents."}'::jsonb, 'C', NULL, 'Correct: «If he checked the figures, he would find the mistake.» — II tip şərt: If + Past Simple, would + V1. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10349, 131, 'g11-eng-cond-q3-19', 3, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I wish it would stop raining. It has been raining for days. I wish I will be taller.", "B": "I wish it stopped to raining. It has been raining for days. I wish I were taller.", "C": "I wish it would stop raining. It has been raining for days. I wish I am taller.", "D": "I wish it would stop raining. It has been raining for days. I wish I being taller.", "E": "I wish it would stop raining. It has been raining for days. I wish I were taller."}'::jsonb, 'E', NULL, 'would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu; were — wish + were (bütün şəxslərdə).');
INSERT INTO public.questions VALUES (10350, 131, 'g11-eng-cond-q3-20', 3, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If only I drove more carefully yesterday! I wish I knew the answer to this question.", "B": "If only I had driven more carefully yesterday! I wish I knew the answer to this question.", "C": "If only I have driven more carefully yesterday! I wish I knew the answer to this question.", "D": "If only I drive more carefully yesterday! I wish I knew the answer to this question.", "E": "If only I had driven more carefully yesterday! I wish I will know the answer to this question."}'::jsonb, 'B', NULL, 'had driven — If only + Past Perfect: keçmişə təəssüf; knew — wish + Past Simple: indiki vəziyyətə təəssüf.');
INSERT INTO public.questions VALUES (10351, 131, 'g11-eng-cond-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If he had checked the figures, he ___ (find) the mistake. (2) If she ___ (practise) every day, she would have won the competition. (3) Unless they ___ (save) enough money, they won''t buy a new house.', NULL, NULL, '{"A": "would have found / had practised / would save", "B": "would have found / had practised / save", "C": "would have found / will have practised / save", "D": "will have found / had practised / save", "E": "will find / had practised / save"}'::jsonb, 'B', NULL, '(1) would have found — III tip şərt: If + Past Perfect, would have + V3 (2) had practised — III tip şərt: şərt hissəsində Past Perfect (3) save — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (10352, 131, 'g11-eng-cond-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If only I ___ more carefully yesterday! (drive) (2) If I had had more time, I ___ (visit) my grandparents. (3) If we ___ (leave) now, we would have caught the train.', NULL, NULL, '{"A": "had driven / would have visited / would have left", "B": "had driven / will have visited / had left", "C": "have driven / would have visited / had left", "D": "had driven / would have visited / had left", "E": "had driven / had visited / had left"}'::jsonb, 'D', NULL, '(1) had driven — If only + Past Perfect: keçmişə təəssüf (2) would have visited — III tip şərt: If + Past Perfect, would have + V3 (3) had left — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (10353, 131, 'g11-eng-cond-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If he had checked the figures, he would have found the mistake.", "B": "If you will have studied harder, you would have passed the exam.", "C": "If they have saved enough money, they would have bought a new house.", "D": "If he had checked the figures, he will find the mistake.", "E": "If she will have practised every day, she would have won the competition."}'::jsonb, 'A', NULL, 'Correct: «If he had checked the figures, he would have found the mistake.» — III tip şərt: şərt hissəsində Past Perfect. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10354, 131, 'g11-eng-cond-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I ___ (have) more time, I would have visited my grandparents. (2) If they had saved enough money, they ___ (buy) a new house. (3) If they ___ (save) enough money, they would have bought a new house.', NULL, NULL, '{"A": "had had / would have bought / would have saved", "B": "had had / would have bought / had saved", "C": "will have had / would have bought / had saved", "D": "had had / will have bought / had saved", "E": "would have had / would have bought / had saved"}'::jsonb, 'B', NULL, '(1) had had — III tip şərt: şərt hissəsində Past Perfect (2) would have bought — III tip şərt: If + Past Perfect, would have + V3 (3) had saved — III tip şərt: şərt hissəsində Past Perfect');
INSERT INTO public.questions VALUES (10355, 131, 'g11-eng-cond-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If she ___ (practise) every day, she would win the competition. (2) She wishes she ___ to the party last night. (go) (3) I wish it ___ raining. It has been raining for days. (stop)', NULL, NULL, '{"A": "practised / had gone / will stop", "B": "practised / went / would stop", "C": "practised / has gone / would stop", "D": "practised / had gone / would stop", "E": "practises / had gone / would stop"}'::jsonb, 'D', NULL, '(1) practised — II tip şərt: If + Past Simple, would + V1 (2) had gone — wish + Past Perfect: keçmişə təəssüf (3) would stop — wish + would: başqasının hərəkətinin dəyişməsini arzu');
INSERT INTO public.questions VALUES (10356, 131, 'g11-eng-cond-q3-26', 3, 26, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Unless we won''t leave now, we won''t catch the train. If he had taken the medicine, he wouldn''t feel ill now.", "B": "Unless we leave now, we won''t catch the train. If he had taken the medicine, he wouldn''t feel ill now.", "C": "Unless we leave now, we won''t catch the train. If he had taken the medicine, he won''t feel ill now.", "D": "Unless we will leave now, we won''t catch the train. If he had taken the medicine, he wouldn''t feel ill now.", "E": "Unless we leave now, we won''t catch the train. If he had taken the medicine, he doesn''t feel ill now."}'::jsonb, 'B', NULL, 'leave — Unless = if not; zaman/şərt hissəsində Present Simple; wouldn''t feel — Qarışıq şərt: keçmiş şərt → indiki nəticə.');
INSERT INTO public.questions VALUES (10357, 131, 'g11-eng-cond-q3-27', 3, 27, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "If she had practised every day, she would have won the competition. If he had taken the medicine, he doesn''t feel ill now.", "B": "If she had practised every day, she would have won the competition. If he had taken the medicine, he won''t feel ill now.", "C": "If she had practised every day, she would have won the competition. If he had taken the medicine, he wouldn''t feel ill now.", "D": "If she would have practised every day, she would have won the competition. If he had taken the medicine, he wouldn''t feel ill now.", "E": "If she will have practised every day, she would have won the competition. If he had taken the medicine, he wouldn''t feel ill now."}'::jsonb, 'C', NULL, 'had practised — III tip şərt: şərt hissəsində Past Perfect; wouldn''t feel — Qarışıq şərt: keçmiş şərt → indiki nəticə.');
INSERT INTO public.questions VALUES (10358, 131, 'g11-eng-cond-q3-28', 3, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I wish I knew the answer to this question. If I had had more time, I would have visited my grandparents.", "B": "I wish I knew the answer to this question. If I would have had more time, I would have visited my grandparents.", "C": "I wish I knew the answer to this question. If I have had more time, I would have visited my grandparents.", "D": "I wish I know the answer to this question. If I had had more time, I would have visited my grandparents.", "E": "I wish I knowing the answer to this question. If I had had more time, I would have visited my grandparents."}'::jsonb, 'A', NULL, 'knew — wish + Past Simple: indiki vəziyyətə təəssüf; had had — III tip şərt: şərt hissəsində Past Perfect.');
INSERT INTO public.questions VALUES (10359, 131, 'g11-eng-cond-q3-29', 3, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "If you study harder, you would pass the exam.", "B": "If she had practised every day, she had won the competition.", "C": "If he has checked the figures, he would find the mistake.", "D": "If they save enough money, they would buy a new house.", "E": "Unless we leave now, we won''t catch the train."}'::jsonb, 'E', NULL, 'Correct: «Unless we leave now, we won''t catch the train.» — Unless = if not; zaman/şərt hissəsində Present Simple. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10360, 131, 'g11-eng-cond-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) If I had had more time, I ___ (visit) my grandparents. (2) If he had checked the figures, he ___ (find) the mistake. (3) Unless they ___ (save) enough money, they won''t buy a new house.', NULL, NULL, '{"A": "will visit / would have found / save", "B": "would have visited / would have found / save", "C": "will have visited / would have found / save", "D": "had visited / would have found / save", "E": "would have visited / would have found / won''t save"}'::jsonb, 'B', NULL, '(1) would have visited — III tip şərt: If + Past Perfect, would have + V3 (2) would have found — III tip şərt: If + Past Perfect, would have + V3 (3) save — Unless = if not; zaman/şərt hissəsində Present Simple');
INSERT INTO public.questions VALUES (10361, 132, 'g11-eng-passive-q1-01', 1, 1, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The parcel was being delivered at the moment. The contract will have been signed by the end of next week.", "B": "The parcel has been delivering at the moment. The contract will have been signed by the end of next week.", "C": "The parcel is being delivered at the moment. The contract will have been signed by the end of next week.", "D": "The parcel is delivering at the moment. The contract will have been signed by the end of next week.", "E": "The parcel is being delivered at the moment. The contract had been signed by the end of next week."}'::jsonb, 'C', NULL, 'is being delivered — Present Continuous Passive: is/are being + V3; will have been signed — Future Perfect Passive: will have been + V3.');
INSERT INTO public.questions VALUES (10362, 132, 'g11-eng-passive-q1-02', 1, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The report ___ (publish) at the moment. (2) The houses ___ (paint) when the storm started. (3) The report ___ (publish) since 2010.', NULL, NULL, '{"A": "is being published / were being painted / has been published", "B": "is being published / were being painted / was published", "C": "is being published / have been painted / has been published", "D": "has been publishing / were being painted / has been published", "E": "is publishing / were being painted / has been published"}'::jsonb, 'A', NULL, '(1) is being published — Present Continuous Passive: is/are being + V3 (2) were being painted — Past Continuous Passive: was/were being + V3 (3) has been published — Present Perfect Passive: has/have been + V3');
INSERT INTO public.questions VALUES (10363, 132, 'g11-eng-passive-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The bridge is being built when the storm started.", "B": "The article has been translated by the end of next week.", "C": "The parcel is delivered since 2010.", "D": "The posters are being designed when the storm started.", "E": "The contract will have been signed by the end of next week."}'::jsonb, 'E', NULL, 'Correct: «The contract will have been signed by the end of next week.» — Future Perfect Passive: will have been + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10364, 132, 'g11-eng-passive-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The houses ___ (paint) by the end of next week. (2) The cars ___ (sell) at the moment. (3) The houses ___ (paint) when the storm started.', NULL, NULL, '{"A": "will have been painted / have been selling / were being painted", "B": "will have been painted / are being sold / were painting", "C": "will have been painted / are being sold / have been painted", "D": "had been painted / are being sold / were being painted", "E": "will have been painted / are being sold / were being painted"}'::jsonb, 'E', NULL, '(1) will have been painted — Future Perfect Passive: will have been + V3 (2) are being sold — Present Continuous Passive: is/are being + V3 (3) were being painted — Past Continuous Passive: was/were being + V3');
INSERT INTO public.questions VALUES (10365, 132, 'g11-eng-passive-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The cars ___ (sell) since 2010. (2) The report ___ (publish) by the end of next week. (3) The letters ___ (send) by the end of next week.', NULL, NULL, '{"A": "have been sold / has been published / will have been sent", "B": "were sold / will have been published / will have been sent", "C": "have been sold / will have been published / will have sent", "D": "have been sold / had been published / will have been sent", "E": "have been sold / will have been published / will have been sent"}'::jsonb, 'E', NULL, '(1) have been sold — Present Perfect Passive: has/have been + V3 (2) will have been published — Future Perfect Passive: will have been + V3 (3) will have been sent — Future Perfect Passive: will have been + V3');
INSERT INTO public.questions VALUES (10366, 132, 'g11-eng-passive-q1-06', 1, 6, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The letters have been sending at the moment. The thief is believed to have left the country last week.", "B": "The letters are sending at the moment. The thief is believed to have left the country last week.", "C": "The letters are being sent at the moment. The thief is believed to have left the country last week.", "D": "The letters were being sent at the moment. The thief is believed to have left the country last week.", "E": "The letters are being sent at the moment. The thief is believed to leave the country last week."}'::jsonb, 'C', NULL, 'are being sent — Present Continuous Passive: is/are being + V3; to have left — Keçmişə aid: be believed + to have + V3.');
INSERT INTO public.questions VALUES (10367, 132, 'g11-eng-passive-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The cars are sold since 2010.", "B": "The cars are selling at the moment.", "C": "The parcel has been delivered by the end of next week.", "D": "The report has been published since 2010.", "E": "The posters are designed since 2010."}'::jsonb, 'D', NULL, 'Correct: «The report has been published since 2010.» — Present Perfect Passive: has/have been + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10368, 132, 'g11-eng-passive-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The posters ___ (design) since 2010. (2) She got her hair ___ last week. (cut) (3) The bridge ___ (build) by the end of next week.', NULL, NULL, '{"A": "have been designed / cutting / will have been built", "B": "have designed / cut / will have been built", "C": "have been designed / cut / had been built", "D": "have been designed / cut / will have been built", "E": "have been designed / cut / has been built"}'::jsonb, 'D', NULL, '(1) have been designed — Present Perfect Passive: has/have been + V3 (2) cut — Causative: get + obyekt + V3 (3) will have been built — Future Perfect Passive: will have been + V3');
