INSERT INTO public.questions VALUES (10373, 132, 'g11-eng-passive-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The bridge is building at the moment.", "B": "The contract has been signed since 2010.", "C": "The contract was being signed at the moment.", "D": "The posters are being designed when the storm started.", "E": "The contract had been signed by the end of next week."}'::jsonb, 'B', NULL, 'Correct: «The contract has been signed since 2010.» — Present Perfect Passive: has/have been + V3. The other sentences each contain an error.');
