INSERT INTO public.questions VALUES (10428, 132, 'g11-eng-passive-q3-08', 3, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The bridge ___ (build) since 2010. (2) The cars ___ (sell) by the end of next week. (3) The bikes ___ (repair) when the storm started.', NULL, NULL, '{"A": "is built / will have been sold / were being repaired", "B": "has been built / will have been sold / have been repaired", "C": "has built / will have been sold / were being repaired", "D": "has been built / will have been sold / were being repaired", "E": "has been built / will have sold / were being repaired"}'::jsonb, 'D', NULL, '(1) has been built — Present Perfect Passive: has/have been + V3 (2) will have been sold — Future Perfect Passive: will have been + V3 (3) were being repaired — Past Continuous Passive: was/were being + V3');
INSERT INTO public.questions VALUES (10429, 132, 'g11-eng-passive-q3-09', 3, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The parcel ___ (deliver) since 2010. (2) The cars ___ (sell) when the storm started. (3) The bridge ___ (build) since 2010.', NULL, NULL, '{"A": "has been delivered / were being sold / was built", "B": "has been delivered / were selling / has been built", "C": "has delivered / were being sold / has been built", "D": "is delivered / were being sold / has been built", "E": "has been delivered / were being sold / has been built"}'::jsonb, 'E', NULL, '(1) has been delivered — Present Perfect Passive: has/have been + V3 (2) were being sold — Past Continuous Passive: was/were being + V3 (3) has been built — Present Perfect Passive: has/have been + V3');
INSERT INTO public.questions VALUES (10430, 132, 'g11-eng-passive-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The bikes will have repaired by the end of next week.", "B": "I had my car repairing yesterday.", "C": "The cars have been sold since 2010.", "D": "The posters have been designing at the moment.", "E": "The parcel has been delivered when the storm started."}'::jsonb, 'C', NULL, 'Correct: «The cars have been sold since 2010.» — Present Perfect Passive: has/have been + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10431, 132, 'g11-eng-passive-q3-11', 3, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The cars ___ (sell) at the moment. (2) The report ___ (publish) by the end of next week. (3) The houses ___ (paint) when the storm started.', NULL, NULL, '{"A": "were being sold / will have been published / were being painted", "B": "are being sold / will have published / were being painted", "C": "are being sold / has been published / were being painted", "D": "are being sold / will have been published / have been painted", "E": "are being sold / will have been published / were being painted"}'::jsonb, 'E', NULL, '(1) are being sold — Present Continuous Passive: is/are being + V3 (2) will have been published — Future Perfect Passive: will have been + V3 (3) were being painted — Past Continuous Passive: was/were being + V3');
INSERT INTO public.questions VALUES (10432, 132, 'g11-eng-passive-q3-12', 3, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The report is being published at the moment.", "B": "The cars have been selling at the moment.", "C": "This problem can''t been solved easily.", "D": "The bridge was building when the storm started.", "E": "The contract is signing at the moment."}'::jsonb, 'A', NULL, 'Correct: «The report is being published at the moment.» — Present Continuous Passive: is/are being + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10433, 132, 'g11-eng-passive-q3-13', 3, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The letters were sending when the storm started.", "B": "The report has published since 2010.", "C": "She got her hair cut last week.", "D": "The article will have translated by the end of next week.", "E": "The contract is signed since 2010."}'::jsonb, 'C', NULL, 'Correct: «She got her hair cut last week.» — Causative: get + obyekt + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10434, 132, 'g11-eng-passive-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The houses ___ (paint) since 2010. (2) The posters ___ (design) by the end of next week. (3) The article ___ (translate) since 2010.', NULL, NULL, '{"A": "have been painted / will have been designed / is translated", "B": "are painted / will have been designed / has been translated", "C": "have been painted / have been designed / has been translated", "D": "have been painted / will have been designed / has been translated", "E": "have been painted / will have been designed / was translated"}'::jsonb, 'D', NULL, '(1) have been painted — Present Perfect Passive: has/have been + V3 (2) will have been designed — Future Perfect Passive: will have been + V3 (3) has been translated — Present Perfect Passive: has/have been + V3');
INSERT INTO public.questions VALUES (10435, 132, 'g11-eng-passive-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The letters ___ (send) by the end of next week. (2) The posters ___ (design) by the end of next week. (3) The report ___ (publish) since 2010.', NULL, NULL, '{"A": "will have been sent / will have designed / has been published", "B": "have been sent / will have been designed / has been published", "C": "will have been sent / had been designed / has been published", "D": "will have been sent / will have been designed / has been published", "E": "will have been sent / will have been designed / has published"}'::jsonb, 'D', NULL, '(1) will have been sent — Future Perfect Passive: will have been + V3 (2) will have been designed — Future Perfect Passive: will have been + V3 (3) has been published — Present Perfect Passive: has/have been + V3');
INSERT INTO public.questions VALUES (10436, 132, 'g11-eng-passive-q3-16', 3, 16, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The letters are sent since 2010. I had my car repaired yesterday.", "B": "The letters have been sent since 2010. I had my car repair yesterday.", "C": "The letters have been sent since 2010. I had my car repairing yesterday.", "D": "The letters have been sent since 2010. I had my car repaired yesterday.", "E": "The letters have been sent since 2010. I had my car to repair yesterday."}'::jsonb, 'D', NULL, 'have been sent — Present Perfect Passive: has/have been + V3; repaired — Causative: have + obyekt + V3.');
INSERT INTO public.questions VALUES (10437, 132, 'g11-eng-passive-q3-17', 3, 17, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The posters have been designed by the end of next week. The bikes will have been repaired by the end of next week.", "B": "The posters will have designed by the end of next week. The bikes will have been repaired by the end of next week.", "C": "The posters had been designed by the end of next week. The bikes will have been repaired by the end of next week.", "D": "The posters will have been designed by the end of next week. The bikes will have repaired by the end of next week.", "E": "The posters will have been designed by the end of next week. The bikes will have been repaired by the end of next week."}'::jsonb, 'E', NULL, 'will have been designed — Future Perfect Passive: will have been + V3; will have been repaired — Future Perfect Passive: will have been + V3.');
INSERT INTO public.questions VALUES (10438, 132, 'g11-eng-passive-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The parcel is delivering at the moment.", "B": "The article has been translated by the end of next week.", "C": "The report will have been published by the end of next week.", "D": "She got her hair to cut last week.", "E": "The report was published since 2010."}'::jsonb, 'C', NULL, 'Correct: «The report will have been published by the end of next week.» — Future Perfect Passive: will have been + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10439, 132, 'g11-eng-passive-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The contract is being signed at the moment.", "B": "The thief is believed to leave the country last week.", "C": "The cars had been sold by the end of next week.", "D": "The bikes are repairing at the moment.", "E": "The parcel was delivering when the storm started."}'::jsonb, 'A', NULL, 'Correct: «The contract is being signed at the moment.» — Present Continuous Passive: is/are being + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10440, 132, 'g11-eng-passive-q3-20', 3, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The bikes are being repaired at the moment. The bikes have been repaired since 2010.", "B": "The bikes are being repaired at the moment. The bikes have repaired since 2010.", "C": "The bikes are repairing at the moment. The bikes have been repaired since 2010.", "D": "The bikes are being repaired at the moment. The bikes were repaired since 2010.", "E": "The bikes were being repaired at the moment. The bikes have been repaired since 2010."}'::jsonb, 'A', NULL, 'are being repaired — Present Continuous Passive: is/are being + V3; have been repaired — Present Perfect Passive: has/have been + V3.');
INSERT INTO public.questions VALUES (10441, 132, 'g11-eng-passive-q3-21', 3, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The bikes are being repaired at the moment. The cars were selling when the storm started.", "B": "The bikes were being repaired at the moment. The cars were being sold when the storm started.", "C": "The bikes are repairing at the moment. The cars were being sold when the storm started.", "D": "The bikes are being repaired at the moment. The cars were being sold when the storm started.", "E": "The bikes are being repaired at the moment. The cars have been sold when the storm started."}'::jsonb, 'D', NULL, 'are being repaired — Present Continuous Passive: is/are being + V3; were being sold — Past Continuous Passive: was/were being + V3.');
