INSERT INTO public.questions VALUES (10443, 132, 'g11-eng-passive-q3-23', 3, 23, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The bikes were being repaired when the storm started. The bridge has been building at the moment.", "B": "The bikes were being repaired when the storm started. The bridge is being built at the moment.", "C": "The bikes are being repaired when the storm started. The bridge is being built at the moment.", "D": "The bikes have been repaired when the storm started. The bridge is being built at the moment.", "E": "The bikes were being repaired when the storm started. The bridge was being built at the moment."}'::jsonb, 'B', NULL, 'were being repaired — Past Continuous Passive: was/were being + V3; is being built — Present Continuous Passive: is/are being + V3.');
INSERT INTO public.questions VALUES (10444, 132, 'g11-eng-passive-q3-24', 3, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The cars have been sold by the end of next week.", "B": "The bikes will have been repaired by the end of next week.", "C": "The contract has been signing at the moment.", "D": "The bikes have been repairing at the moment.", "E": "The letters had been sent by the end of next week."}'::jsonb, 'B', NULL, 'Correct: «The bikes will have been repaired by the end of next week.» — Future Perfect Passive: will have been + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10445, 132, 'g11-eng-passive-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The contract ___ (sign) at the moment. (2) The cars ___ (sell) since 2010. (3) This problem can''t ___ easily. (solve)', NULL, NULL, '{"A": "was being signed / have been sold / be solved", "B": "is being signed / have been sold / be solving", "C": "is being signed / have been sold / be solved", "D": "is being signed / were sold / be solved", "E": "is being signed / have sold / be solved"}'::jsonb, 'C', NULL, '(1) is being signed — Present Continuous Passive: is/are being + V3 (2) have been sold — Present Perfect Passive: has/have been + V3 (3) be solved — Modal + be + V3');
INSERT INTO public.questions VALUES (10446, 132, 'g11-eng-passive-q3-26', 3, 26, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He is said that is the best player in the team.", "B": "The bikes have been repairing at the moment.", "C": "The letters are being sent at the moment.", "D": "The letters were sending when the storm started.", "E": "The houses were painting when the storm started."}'::jsonb, 'C', NULL, 'Correct: «The letters are being sent at the moment.» — Present Continuous Passive: is/are being + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10447, 132, 'g11-eng-passive-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The article was translated since 2010.", "B": "The posters had been designed by the end of next week.", "C": "The thief is believed to leave the country last week.", "D": "The posters were being designed when the storm started.", "E": "The windows need to clean."}'::jsonb, 'D', NULL, 'Correct: «The posters were being designed when the storm started.» — Past Continuous Passive: was/were being + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10448, 132, 'g11-eng-passive-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The contract ___ (sign) since 2010. (2) The bridge ___ (build) since 2010. (3) The houses ___ (paint) since 2010.', NULL, NULL, '{"A": "was signed / has been built / have been painted", "B": "has been signed / is built / have been painted", "C": "is signed / has been built / have been painted", "D": "has been signed / has built / have been painted", "E": "has been signed / has been built / have been painted"}'::jsonb, 'E', NULL, '(1) has been signed — Present Perfect Passive: has/have been + V3 (2) has been built — Present Perfect Passive: has/have been + V3 (3) have been painted — Present Perfect Passive: has/have been + V3');
INSERT INTO public.questions VALUES (10449, 132, 'g11-eng-passive-q3-29', 3, 29, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This problem can''t be solved easily. The houses were being painted when the storm started.", "B": "This problem can''t be solving easily. The houses were being painted when the storm started.", "C": "This problem can''t solved easily. The houses were being painted when the storm started.", "D": "This problem can''t be solved easily. The houses are being painted when the storm started.", "E": "This problem can''t been solved easily. The houses were being painted when the storm started."}'::jsonb, 'A', NULL, 'be solved — Modal + be + V3; were being painted — Past Continuous Passive: was/were being + V3.');
INSERT INTO public.questions VALUES (10450, 132, 'g11-eng-passive-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I had my car repairing yesterday.", "B": "The bridge is building at the moment.", "C": "The letters have been sent by the end of next week.", "D": "The report was published since 2010.", "E": "The contract has been signed since 2010."}'::jsonb, 'E', NULL, 'Correct: «The contract has been signed since 2010.» — Present Perfect Passive: has/have been + V3. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10451, 133, 'g11-eng-article-q1-01', 1, 1, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He was born in the 1990s. She is the only person who knows the truth.", "B": "He was born in the 1990s. She is a only person who knows the truth.", "C": "He was born in the 1990s. She is an only person who knows the truth.", "D": "He was born in 1990s. She is the only person who knows the truth.", "E": "He was born in a 1990s. She is the only person who knows the truth."}'::jsonb, 'A', NULL, 'the — Onilliklər: in the 1990s; the — «only» ilə the.');
INSERT INTO public.questions VALUES (10452, 133, 'g11-eng-article-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Germany is an European country.", "B": "He has an unique talent for music.", "C": "The Netherlands is famous for its tulips.", "D": "I bought an one-way ticket.", "E": "I visit my grandparents twice month."}'::jsonb, 'C', NULL, 'Correct: «The Netherlands is famous for its tulips.» — Cəm formalı ölkə adları ilə the. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10453, 133, 'g11-eng-article-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He was elected ___ president of the club. (2) They climbed ___ Alps last summer. (3) She has ___ MBA from a famous school.', NULL, NULL, '{"A": "— / an / an", "B": "a / the / an", "C": "— / — / an", "D": "an / the / an", "E": "— / the / an"}'::jsonb, 'E', NULL, '(1) — — Yeganə vəzifə «elect» ilə — artiklsiz (2) the — Dağ silsilələri ilə the (3) an — «MBA» [em] səsi ilə başlayır → an');
INSERT INTO public.questions VALUES (10454, 133, 'g11-eng-article-q1-04', 1, 4, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "A Caspian Sea is the largest lake in the world. He was born in the 1990s.", "B": "Caspian Sea is the largest lake in the world. He was born in the 1990s.", "C": "The Caspian Sea is the largest lake in the world. He was born in 1990s.", "D": "The Caspian Sea is the largest lake in the world. He was born in the 1990s.", "E": "The Caspian Sea is the largest lake in the world. He was born in a 1990s."}'::jsonb, 'D', NULL, 'The — Dəniz adları ilə the; the — Onilliklər: in the 1990s.');
INSERT INTO public.questions VALUES (10455, 133, 'g11-eng-article-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) I bought ___ one-way ticket. (2) He was elected ___ president of the club. (3) He has ___ unique talent for music.', NULL, NULL, '{"A": "a / a / a", "B": "a / — / a", "C": "a / an / a", "D": "a / — / an", "E": "an / — / a"}'::jsonb, 'B', NULL, '(1) a — «one» [w] səsi ilə başlayır → a (2) — — Yeganə vəzifə «elect» ilə — artiklsiz (3) a — «unique» [ju] səsi ilə başlayır → a');
INSERT INTO public.questions VALUES (10456, 133, 'g11-eng-article-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ rich should help the poor. (2) ___ Mount Everest is the highest mountain in the world. (3) ___ English language has many irregular verbs.', NULL, NULL, '{"A": "The / — / The", "B": "— / — / The", "C": "The / A / The", "D": "The / The / The", "E": "The / — / —"}'::jsonb, 'A', NULL, '(1) The — the + sifət = sosial qrup (the rich, the poor) (2) — — Tək dağ adları ilə artikl işlənmir (3) The — «the English language» — language sözü ilə the');
INSERT INTO public.questions VALUES (10457, 133, 'g11-eng-article-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) She is ___ only person who knows the truth. (2) ___ rich should help the poor. (3) She lives in ___ United Kingdom.', NULL, NULL, '{"A": "the / The / a", "B": "the / A / the", "C": "the / The / the", "D": "a / The / the", "E": "the / The / —"}'::jsonb, 'C', NULL, '(1) the — «only» ilə the (2) The — the + sifət = sosial qrup (the rich, the poor) (3) the — «Kingdom, States, Republic» olan ölkə adları ilə the');
INSERT INTO public.questions VALUES (10458, 133, 'g11-eng-article-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Lake Baikal is very deep.", "B": "I bought an one-way ticket.", "C": "She is an only person who knows the truth.", "D": "They climbed Alps last summer.", "E": "What a lovely weather we are having!"}'::jsonb, 'A', NULL, 'Correct: «Lake Baikal is very deep.» — «Lake + ad» formasında artikl işlənmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10459, 133, 'g11-eng-article-q1-09', 1, 9, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She lives in a United Kingdom. History is my favourite subject.", "B": "She lives in the United Kingdom. The history is my favourite subject.", "C": "She lives in the United Kingdom. A history is my favourite subject.", "D": "She lives in United Kingdom. History is my favourite subject.", "E": "She lives in the United Kingdom. History is my favourite subject."}'::jsonb, 'E', NULL, 'the — «Kingdom, States, Republic» olan ölkə adları ilə the; — — Fənn adları ümumi mənada artiklsiz.');
INSERT INTO public.questions VALUES (10460, 133, 'g11-eng-article-q1-10', 1, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Lake Baikal is very deep. (2) She has ___ MBA from a famous school. (3) ___ rich should help the poor.', NULL, NULL, '{"A": "— / a / The", "B": "The / an / The", "C": "— / an / The", "D": "A / an / The", "E": "— / an / A"}'::jsonb, 'C', NULL, '(1) — — «Lake + ad» formasında artikl işlənmir (2) an — «MBA» [em] səsi ilə başlayır → an (3) The — the + sifət = sosial qrup (the rich, the poor)');
INSERT INTO public.questions VALUES (10461, 133, 'g11-eng-article-q1-11', 1, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She lives in United Kingdom. What lovely weather we are having!", "B": "She lives in the United Kingdom. What a lovely weather we are having!", "C": "She lives in the United Kingdom. What the lovely weather we are having!", "D": "She lives in the United Kingdom. What lovely weather we are having!", "E": "She lives in a United Kingdom. What lovely weather we are having!"}'::jsonb, 'D', NULL, 'the — «Kingdom, States, Republic» olan ölkə adları ilə the; — — What + saylanmayan isim (weather) — artiklsiz.');
INSERT INTO public.questions VALUES (10462, 133, 'g11-eng-article-q1-12', 1, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He has ___ unique talent for music. (2) ___ rich should help the poor. (3) ___ history is my favourite subject.', NULL, NULL, '{"A": "a / — / —", "B": "a / The / —", "C": "a / A / —", "D": "a / The / The", "E": "an / The / —"}'::jsonb, 'B', NULL, '(1) a — «unique» [ju] səsi ilə başlayır → a (2) The — the + sifət = sosial qrup (the rich, the poor) (3) — — Fənn adları ümumi mənada artiklsiz');
