INSERT INTO public.questions VALUES (10506, 133, 'g11-eng-article-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He was elected ___ president of the club. (2) I visit my grandparents twice ___ month. (3) They climbed ___ Alps last summer.', NULL, NULL, '{"A": "— / the / the", "B": "— / a / the", "C": "an / a / the", "D": "— / a / an", "E": "— / — / the"}'::jsonb, 'B', NULL, '(1) — — Yeganə vəzifə «elect» ilə — artiklsiz (2) a — twice a month — «hər» mənasında a (3) the — Dağ silsilələri ilə the');
INSERT INTO public.questions VALUES (10507, 133, 'g11-eng-article-q2-27', 2, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Caspian Sea is the largest lake in the world. (2) She lives in ___ United Kingdom. (3) He was elected ___ president of the club.', NULL, NULL, '{"A": "The / the / a", "B": "The / — / —", "C": "— / the / —", "D": "The / a / —", "E": "The / the / —"}'::jsonb, 'E', NULL, '(1) The — Dəniz adları ilə the (2) the — «Kingdom, States, Republic» olan ölkə adları ilə the (3) — — Yeganə vəzifə «elect» ilə — artiklsiz');
INSERT INTO public.questions VALUES (10508, 133, 'g11-eng-article-q2-28', 2, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The Netherlands is famous for its tulips. Rich should help the poor.", "B": "Netherlands is famous for its tulips. The rich should help the poor.", "C": "A Netherlands is famous for its tulips. The rich should help the poor.", "D": "The Netherlands is famous for its tulips. A rich should help the poor.", "E": "The Netherlands is famous for its tulips. The rich should help the poor."}'::jsonb, 'E', NULL, 'The — Cəm formalı ölkə adları ilə the; The — the + sifət = sosial qrup (the rich, the poor).');
INSERT INTO public.questions VALUES (10509, 133, 'g11-eng-article-q2-29', 2, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) ___ Mount Everest is the highest mountain in the world. (2) ___ Caspian Sea is the largest lake in the world. (3) ___ English language has many irregular verbs.', NULL, NULL, '{"A": "— / The / The", "B": "A / The / The", "C": "— / The / —", "D": "The / The / The", "E": "— / The / An"}'::jsonb, 'A', NULL, '(1) — — Tək dağ adları ilə artikl işlənmir (2) The — Dəniz adları ilə the (3) The — «the English language» — language sözü ilə the');
INSERT INTO public.questions VALUES (10510, 133, 'g11-eng-article-q2-30', 2, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) What ___ lovely weather we are having! (2) I bought ___ one-way ticket. (3) ___ Caspian Sea is the largest lake in the world.', NULL, NULL, '{"A": "a / a / The", "B": "— / an / The", "C": "the / a / The", "D": "— / a / The", "E": "— / a / A"}'::jsonb, 'D', NULL, '(1) — — What + saylanmayan isim (weather) — artiklsiz (2) a — «one» [w] səsi ilə başlayır → a (3) The — Dəniz adları ilə the');
