INSERT INTO public.questions VALUES (10537, 133, 'g11-eng-article-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "English language has many irregular verbs.", "B": "The Netherlands is famous for its tulips.", "C": "Germany is an European country.", "D": "She lives in a United Kingdom.", "E": "The history is my favourite subject."}'::jsonb, 'B', NULL, 'Correct: «The Netherlands is famous for its tulips.» — Cəm formalı ölkə adları ilə the. The other sentences each contain an error.');
