INSERT INTO public.questions VALUES (10539, 133, 'g11-eng-article-q3-29', 3, 29, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "What the lovely weather we are having! Germany is an European country.", "B": "What the lovely weather we are having! Germany is a European country.", "C": "What lovely weather we are having! Germany is an European country.", "D": "What lovely weather we are having! Germany is a European country.", "E": "What a lovely weather we are having! Germany is a European country."}'::jsonb, 'D', NULL, '— — What + saylanmayan isim (weather) — artiklsiz; a — «European» [ju] səsi ilə başlayır → a.');
INSERT INTO public.questions VALUES (10540, 133, 'g11-eng-article-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = no article): (1) He was elected ___ president of the club. (2) She has ___ MBA from a famous school. (3) ___ Lake Baikal is very deep.', NULL, NULL, '{"A": "— / a / —", "B": "an / an / —", "C": "— / an / A", "D": "— / an / —", "E": "a / an / —"}'::jsonb, 'D', NULL, '(1) — — Yeganə vəzifə «elect» ilə — artiklsiz (2) an — «MBA» [em] səsi ilə başlayır → an (3) — — «Lake + ad» formasında artikl işlənmir');
INSERT INTO public.questions VALUES (10541, 134, 'g11-eng-quant-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I have ___ money, so I can buy you a coffee. (2) We had ___ problems with the new software. (3) ___ number of tourists has increased this year.', NULL, NULL, '{"A": "many / several / The", "B": "a little / several / Many", "C": "a little / several / The", "D": "a little / a little / The", "E": "a little / a great deal / The"}'::jsonb, 'C', NULL, '(1) a little — a little + saylanmayan (müsbət məna: bir az var) (2) several — several + saylan cəm (3) The — the number of + tək feil (has)');
INSERT INTO public.questions VALUES (10542, 134, 'g11-eng-quant-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were such many people at the concert that we couldn''t find a seat.", "B": "We had much problems with the new software.", "C": "No of the students passed the test; it was too difficult.", "D": "I have a few money, so I can buy you a coffee.", "E": "I''ve got a lot of homework to do tonight."}'::jsonb, 'E', NULL, 'Correct: «I''ve got a lot of homework to do tonight.» — homework saylanmayandır → a lot of / much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10543, 134, 'g11-eng-quant-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "One of the cakes is mine; take the other one.", "B": "Every the children enjoyed the trip.", "C": "We had a great deal problems with the new software.", "D": "I''ve got a few homework to do tonight.", "E": "I don''t have many information about this topic."}'::jsonb, 'A', NULL, 'Correct: «One of the cakes is mine; take the other one.» — one of + cəm isim + tək feil. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10544, 134, 'g11-eng-quant-q1-04', 1, 4, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Number of tourists has increased this year. It was such a long journey that we were exhausted.", "B": "The number of tourists has increased this year. It was very a long journey that we were exhausted.", "C": "Many number of tourists has increased this year. It was such a long journey that we were exhausted.", "D": "The number of tourists has increased this year. It was so a long journey that we were exhausted.", "E": "The number of tourists has increased this year. It was such a long journey that we were exhausted."}'::jsonb, 'E', NULL, 'The — the number of + tək feil (has); such — such + (a) + sifət + isim.');
INSERT INTO public.questions VALUES (10545, 134, 'g11-eng-quant-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ number of tourists have complained about the hotel. (2) ___ number of tourists has increased this year. (3) ___ of the students passed the test; it was too difficult.', NULL, NULL, '{"A": "— / The / None", "B": "The / The / None", "C": "A / The / None", "D": "A / The / Any", "E": "A / A / None"}'::jsonb, 'C', NULL, '(1) A — a number of (bir neçə) + cəm feil (have) (2) The — the number of + tək feil (has) (3) None — none of + cəm (üç və daha çox): heç biri');
INSERT INTO public.questions VALUES (10546, 134, 'g11-eng-quant-q1-06', 1, 6, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We had a great deal problems with the new software. We bought some furniture for the new flat.", "B": "We had several problems with the new software. We bought many furniture for the new flat.", "C": "We had much problems with the new software. We bought some furniture for the new flat.", "D": "We had several problems with the new software. We bought some furniture for the new flat.", "E": "We had several problems with the new software. We bought several furniture for the new flat."}'::jsonb, 'D', NULL, 'several — several + saylan cəm; some — furniture saylanmayandır → some.');
INSERT INTO public.questions VALUES (10547, 134, 'g11-eng-quant-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Plenty ___ volunteers came to help. (2) She gave me ___ useful advice. (3) I don''t have ___ information about this topic.', NULL, NULL, '{"A": "of / some / much", "B": "much / some / much", "C": "many / some / much", "D": "of / some / a few", "E": "of / a few / much"}'::jsonb, 'A', NULL, '(1) of — plenty of + isim (2) some — advice saylanmayandır → some advice (3) much — information saylanmayandır → much');
INSERT INTO public.questions VALUES (10548, 134, 'g11-eng-quant-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) ___ number of tourists have complained about the hotel. (3) We had ___ problems with the new software.', NULL, NULL, '{"A": "How much / The / several", "B": "How many / A / several", "C": "How much / A / a great deal", "D": "How much / A / several", "E": "How a lot / A / several"}'::jsonb, 'D', NULL, '(1) How much — luggage saylanmayandır → how much (2) A — a number of (bir neçə) + cəm feil (have) (3) several — several + saylan cəm');
INSERT INTO public.questions VALUES (10549, 134, 'g11-eng-quant-q1-09', 1, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Plenty volunteers came to help.", "B": "She gave me a few useful advice.", "C": "Every of my parents are doctors.", "D": "All of the cakes is mine; take the other one.", "E": "He hardly has any free time these days."}'::jsonb, 'E', NULL, 'Correct: «He hardly has any free time these days.» — hardly (inkar mənalı) + any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10550, 134, 'g11-eng-quant-q1-10', 1, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) She gave me ___ useful advice. (2) It was ___ a long journey that we were exhausted. (3) I''ve got ___ homework to do tonight.', NULL, NULL, '{"A": "some / so / a lot of", "B": "some / too / a lot of", "C": "an / such / a lot of", "D": "some / such / many", "E": "some / such / a lot of"}'::jsonb, 'E', NULL, '(1) some — advice saylanmayandır → some advice (2) such — such + (a) + sifət + isim (3) a lot of — homework saylanmayandır → a lot of / much');
INSERT INTO public.questions VALUES (10551, 134, 'g11-eng-quant-q1-11', 1, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Neither of the two answers is correct, so try again. I have many money, so I can buy you a coffee.", "B": "Neither of the two answers is correct, so try again. I have a little money, so I can buy you a coffee.", "C": "All of the two answers is correct, so try again. I have a little money, so I can buy you a coffee.", "D": "Neither of the two answers is correct, so try again. I have few money, so I can buy you a coffee.", "E": "Both of the two answers is correct, so try again. I have a little money, so I can buy you a coffee."}'::jsonb, 'B', NULL, 'Neither — neither of (ikisindən heç biri) + tək feil (is); a little — a little + saylanmayan (müsbət məna: bir az var).');
INSERT INTO public.questions VALUES (10552, 134, 'g11-eng-quant-q1-12', 1, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I don''t have ___ information about this topic. (2) It was ___ a long journey that we were exhausted. (3) ___ the children enjoyed the trip.', NULL, NULL, '{"A": "much / such / All", "B": "much / very / All", "C": "many / such / All", "D": "much / such / Each", "E": "much / so / All"}'::jsonb, 'A', NULL, '(1) much — information saylanmayandır → much (2) such — such + (a) + sifət + isim (3) All — all (of) the + cəm');
INSERT INTO public.questions VALUES (10553, 134, 'g11-eng-quant-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "One of the cakes is mine; take the other one.", "B": "Only a little students came to the lecture, so it was cancelled.", "C": "He hardly has no free time these days.", "D": "Every the children enjoyed the trip.", "E": "I''ve got many homework to do tonight."}'::jsonb, 'A', NULL, 'Correct: «One of the cakes is mine; take the other one.» — one of + cəm isim + tək feil. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10554, 134, 'g11-eng-quant-q1-14', 1, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Both of the two answers is correct, so try again. I''ve got a lot of homework to do tonight.", "B": "Neither of the two answers is correct, so try again. I''ve got many homework to do tonight.", "C": "All of the two answers is correct, so try again. I''ve got a lot of homework to do tonight.", "D": "Neither of the two answers is correct, so try again. I''ve got several homework to do tonight.", "E": "Neither of the two answers is correct, so try again. I''ve got a lot of homework to do tonight."}'::jsonb, 'E', NULL, 'Neither — neither of (ikisindən heç biri) + tək feil (is); a lot of — homework saylanmayandır → a lot of / much.');
INSERT INTO public.questions VALUES (10555, 134, 'g11-eng-quant-q1-15', 1, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There''s hardly many sugar left.", "B": "He hardly has some free time these days.", "C": "You can take all road; both lead to the city centre.", "D": "I''ve got a few homework to do tonight.", "E": "We bought some furniture for the new flat."}'::jsonb, 'E', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10556, 134, 'g11-eng-quant-q1-16', 1, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the cakes is mine; take the other one. (2) You can take ___ road; both lead to the city centre. (3) He spends ___ deal of time reading.', NULL, NULL, '{"A": "One / all / a great", "B": "One / either / a great", "C": "One / either / a large", "D": "One / either / many", "E": "All / either / a great"}'::jsonb, 'B', NULL, '(1) One — one of + cəm isim + tək feil (2) either — either + tək isim: ikisindən hər hansı biri (3) a great — a great deal of + saylanmayan');
INSERT INTO public.questions VALUES (10557, 134, 'g11-eng-quant-q1-17', 1, 17, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Each the children enjoyed the trip. A number of tourists have complained about the hotel.", "B": "Every the children enjoyed the trip. A number of tourists have complained about the hotel.", "C": "All the children enjoyed the trip. A number of tourists have complained about the hotel.", "D": "All the children enjoyed the trip. Much number of tourists have complained about the hotel.", "E": "All the children enjoyed the trip. The number of tourists have complained about the hotel."}'::jsonb, 'C', NULL, 'All — all (of) the + cəm; A — a number of (bir neçə) + cəm feil (have).');
INSERT INTO public.questions VALUES (10558, 134, 'g11-eng-quant-q1-18', 1, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I''ve got ___ homework to do tonight. (2) We bought ___ furniture for the new flat. (3) We have ___ time; we must hurry.', NULL, NULL, '{"A": "a lot of / some / many", "B": "a lot of / several / little", "C": "a lot of / some / a few", "D": "a lot of / some / few", "E": "a lot of / some / little"}'::jsonb, 'E', NULL, '(1) a lot of — homework saylanmayandır → a lot of / much (2) some — furniture saylanmayandır → some (3) little — little + saylanmayan (mənfi məna)');
INSERT INTO public.questions VALUES (10559, 134, 'g11-eng-quant-q1-19', 1, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I don''t have few information about this topic.", "B": "Nobody of the students passed the test; it was too difficult.", "C": "The number of tourists has increased this year.", "D": "It was so a long journey that we were exhausted.", "E": "He hardly has no free time these days."}'::jsonb, 'C', NULL, 'Correct: «The number of tourists has increased this year.» — the number of + tək feil (has). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10560, 134, 'g11-eng-quant-q1-20', 1, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There''s hardly many sugar left. The number of tourists has increased this year.", "B": "There''s hardly any sugar left. Many number of tourists has increased this year.", "C": "There''s hardly any sugar left. Number of tourists has increased this year.", "D": "There''s hardly any sugar left. A number of tourists has increased this year.", "E": "There''s hardly any sugar left. The number of tourists has increased this year."}'::jsonb, 'E', NULL, 'any — hardly any — demək olar ki, heç; The — the number of + tək feil (has).');
INSERT INTO public.questions VALUES (10561, 134, 'g11-eng-quant-q1-21', 1, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He hardly has any free time these days. I have many money, so I can buy you a coffee.", "B": "He hardly has no free time these days. I have a little money, so I can buy you a coffee.", "C": "He hardly has some free time these days. I have a little money, so I can buy you a coffee.", "D": "He hardly has any free time these days. I have few money, so I can buy you a coffee.", "E": "He hardly has any free time these days. I have a little money, so I can buy you a coffee."}'::jsonb, 'E', NULL, 'any — hardly (inkar mənalı) + any; a little — a little + saylanmayan (müsbət məna: bir az var).');
INSERT INTO public.questions VALUES (10562, 134, 'g11-eng-quant-q1-22', 1, 22, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He spends many deal of time reading. Neither of the two answers is correct, so try again.", "B": "He spends a great deal of time reading. All of the two answers is correct, so try again.", "C": "He spends a great deal of time reading. Neither of the two answers is correct, so try again.", "D": "He spends a lot deal of time reading. Neither of the two answers is correct, so try again.", "E": "He spends a great deal of time reading. Both of the two answers is correct, so try again."}'::jsonb, 'C', NULL, 'a great — a great deal of + saylanmayan; Neither — neither of (ikisindən heç biri) + tək feil (is).');
INSERT INTO public.questions VALUES (10563, 134, 'g11-eng-quant-q1-23', 1, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Much of my parents are doctors.", "B": "There''s hardly some sugar left.", "C": "Many number of tourists has increased this year.", "D": "We had several problems with the new software.", "E": "Some of the cakes is mine; take the other one."}'::jsonb, 'D', NULL, 'Correct: «We had several problems with the new software.» — several + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10564, 134, 'g11-eng-quant-q1-24', 1, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) She gave me ___ useful advice. (2) We bought ___ furniture for the new flat. (3) Only ___ students came to the lecture, so it was cancelled.', NULL, NULL, '{"A": "some / a few / a few", "B": "some / many / a few", "C": "a few / some / a few", "D": "some / some / a few", "E": "some / some / a little"}'::jsonb, 'D', NULL, '(1) some — advice saylanmayandır → some advice (2) some — furniture saylanmayandır → some (3) a few — only a few + saylan cəm');
INSERT INTO public.questions VALUES (10565, 134, 'g11-eng-quant-q1-25', 1, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of the cakes is mine; take the other one.", "B": "She gave me an useful advice.", "C": "There were too much people at the concert that we couldn''t find a seat.", "D": "I don''t have few information about this topic.", "E": "We bought some furniture for the new flat."}'::jsonb, 'E', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10566, 134, 'g11-eng-quant-q1-26', 1, 26, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She gave me a few useful advice. Neither of the two answers is correct, so try again.", "B": "She gave me some useful advice. Both of the two answers is correct, so try again.", "C": "She gave me many useful advice. Neither of the two answers is correct, so try again.", "D": "She gave me some useful advice. Neither of the two answers is correct, so try again.", "E": "She gave me some useful advice. All of the two answers is correct, so try again."}'::jsonb, 'D', NULL, 'some — advice saylanmayandır → some advice; Neither — neither of (ikisindən heç biri) + tək feil (is).');
INSERT INTO public.questions VALUES (10567, 134, 'g11-eng-quant-q1-27', 1, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I''ve got ___ homework to do tonight. (2) We had ___ problems with the new software. (3) It was ___ a long journey that we were exhausted.', NULL, NULL, '{"A": "a lot of / several / too", "B": "several / several / such", "C": "a lot of / several / such", "D": "a few / several / such", "E": "a lot of / a little / such"}'::jsonb, 'C', NULL, '(1) a lot of — homework saylanmayandır → a lot of / much (2) several — several + saylan cəm (3) such — such + (a) + sifət + isim');
INSERT INTO public.questions VALUES (10568, 134, 'g11-eng-quant-q1-28', 1, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Plenty of volunteers came to help. How much luggage do you have?", "B": "Plenty of volunteers came to help. How few luggage do you have?", "C": "Plenty volunteers came to help. How much luggage do you have?", "D": "Plenty of volunteers came to help. How many luggage do you have?", "E": "Plenty many volunteers came to help. How much luggage do you have?"}'::jsonb, 'A', NULL, 'of — plenty of + isim; How much — luggage saylanmayandır → how much.');
INSERT INTO public.questions VALUES (10569, 134, 'g11-eng-quant-q1-29', 1, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of the two answers is correct, so try again.", "B": "He spends many deal of time reading.", "C": "Either the children enjoyed the trip.", "D": "There were so many people at the concert that we couldn''t find a seat.", "E": "We bought a few furniture for the new flat."}'::jsonb, 'D', NULL, 'Correct: «There were so many people at the concert that we couldn''t find a seat.» — so many + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10570, 134, 'g11-eng-quant-q1-30', 1, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Much number of tourists have complained about the hotel.", "B": "We had much problems with the new software.", "C": "You can take either road; both lead to the city centre.", "D": "Plenty much volunteers came to help.", "E": "We bought a few furniture for the new flat."}'::jsonb, 'C', NULL, 'Correct: «You can take either road; both lead to the city centre.» — either + tək isim: ikisindən hər hansı biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10571, 134, 'g11-eng-quant-q2-01', 2, 1, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I have a few money, so I can buy you a coffee. We have little time; we must hurry.", "B": "I have a little money, so I can buy you a coffee. We have little time; we must hurry.", "C": "I have a little money, so I can buy you a coffee. We have a few time; we must hurry.", "D": "I have a little money, so I can buy you a coffee. We have many time; we must hurry.", "E": "I have few money, so I can buy you a coffee. We have little time; we must hurry."}'::jsonb, 'B', NULL, 'a little — a little + saylanmayan (müsbət məna: bir az var); little — little + saylanmayan (mənfi məna).');
INSERT INTO public.questions VALUES (10572, 134, 'g11-eng-quant-q2-02', 2, 2, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We had a little problems with the new software. One of the cakes is mine; take the other one.", "B": "We had several problems with the new software. One of the cakes is mine; take the other one.", "C": "We had several problems with the new software. All of the cakes is mine; take the other one.", "D": "We had several problems with the new software. Some of the cakes is mine; take the other one.", "E": "We had a great deal problems with the new software. One of the cakes is mine; take the other one."}'::jsonb, 'B', NULL, 'several — several + saylan cəm; One — one of + cəm isim + tək feil.');
INSERT INTO public.questions VALUES (10573, 134, 'g11-eng-quant-q2-03', 2, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I have ___ money, so I can buy you a coffee. (2) ___ of the students passed the test; it was too difficult. (3) He spends ___ deal of time reading.', NULL, NULL, '{"A": "a little / None / a great", "B": "a little / None / a lot", "C": "few / None / a great", "D": "a little / None / many", "E": "a little / None / a large"}'::jsonb, 'A', NULL, '(1) a little — a little + saylanmayan (müsbət məna: bir az var) (2) None — none of + cəm (üç və daha çox): heç biri (3) a great — a great deal of + saylanmayan');
INSERT INTO public.questions VALUES (10574, 134, 'g11-eng-quant-q2-04', 2, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "You can take both road; both lead to the city centre.", "B": "We bought many furniture for the new flat.", "C": "She gave me many useful advice.", "D": "Neither of the two answers is correct, so try again.", "E": "Plenty much volunteers came to help."}'::jsonb, 'D', NULL, 'Correct: «Neither of the two answers is correct, so try again.» — neither of (ikisindən heç biri) + tək feil (is). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10575, 134, 'g11-eng-quant-q2-05', 2, 5, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The number of tourists has increased this year. I have a little money, so I can buy you a coffee.", "B": "The number of tourists has increased this year. I have few money, so I can buy you a coffee.", "C": "Number of tourists has increased this year. I have a little money, so I can buy you a coffee.", "D": "A number of tourists has increased this year. I have a little money, so I can buy you a coffee.", "E": "Many number of tourists has increased this year. I have a little money, so I can buy you a coffee."}'::jsonb, 'A', NULL, 'The — the number of + tək feil (has); a little — a little + saylanmayan (müsbət məna: bir az var).');
INSERT INTO public.questions VALUES (10576, 134, 'g11-eng-quant-q2-06', 2, 6, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "How few luggage do you have? I don''t have much information about this topic.", "B": "How much luggage do you have? I don''t have much information about this topic.", "C": "How much luggage do you have? I don''t have a few information about this topic.", "D": "How much luggage do you have? I don''t have few information about this topic.", "E": "How many luggage do you have? I don''t have much information about this topic."}'::jsonb, 'B', NULL, 'How much — luggage saylanmayandır → how much; much — information saylanmayandır → much.');
INSERT INTO public.questions VALUES (10577, 134, 'g11-eng-quant-q2-07', 2, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Plenty ___ volunteers came to help. (2) I don''t have ___ information about this topic. (3) ___ the children enjoyed the trip.', NULL, NULL, '{"A": "of / much / Every", "B": "of / few / All", "C": "of / much / All", "D": "of / much / Each", "E": "much / much / All"}'::jsonb, 'C', NULL, '(1) of — plenty of + isim (2) much — information saylanmayandır → much (3) All — all (of) the + cəm');
INSERT INTO public.questions VALUES (10578, 134, 'g11-eng-quant-q2-08', 2, 8, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I don''t have much information about this topic. It was such a long journey that we were exhausted.", "B": "I don''t have few information about this topic. It was such a long journey that we were exhausted.", "C": "I don''t have many information about this topic. It was such a long journey that we were exhausted.", "D": "I don''t have much information about this topic. It was very a long journey that we were exhausted.", "E": "I don''t have a few information about this topic. It was such a long journey that we were exhausted."}'::jsonb, 'A', NULL, 'much — information saylanmayandır → much; such — such + (a) + sifət + isim.');
INSERT INTO public.questions VALUES (10579, 134, 'g11-eng-quant-q2-09', 2, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) She gave me ___ useful advice. (2) ___ of the cakes is mine; take the other one. (3) You can take ___ road; both lead to the city centre.', NULL, NULL, '{"A": "some / One / both", "B": "some / All / either", "C": "some / One / either", "D": "some / Both / either", "E": "an / One / either"}'::jsonb, 'C', NULL, '(1) some — advice saylanmayandır → some advice (2) One — one of + cəm isim + tək feil (3) either — either + tək isim: ikisindən hər hansı biri');
INSERT INTO public.questions VALUES (10580, 134, 'g11-eng-quant-q2-10', 2, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Only a little students came to the lecture, so it was cancelled.", "B": "We bought many furniture for the new flat.", "C": "I''ve got several homework to do tonight.", "D": "The number of tourists have complained about the hotel.", "E": "She has few friends, so she often feels lonely."}'::jsonb, 'E', NULL, 'Correct: «She has few friends, so she often feels lonely.» — few + saylan (mənfi məna: az, demək olar ki, yox). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10581, 134, 'g11-eng-quant-q2-11', 2, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) We have ___ time; we must hurry. (2) I don''t have ___ information about this topic. (3) ___ the children enjoyed the trip.', NULL, NULL, '{"A": "little / much / All", "B": "little / a few / All", "C": "little / much / Each", "D": "little / much / Either", "E": "little / many / All"}'::jsonb, 'A', NULL, '(1) little — little + saylanmayan (mənfi məna) (2) much — information saylanmayandır → much (3) All — all (of) the + cəm');
INSERT INTO public.questions VALUES (10582, 134, 'g11-eng-quant-q2-12', 2, 12, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He spends a great deal of time reading. There were so much people at the concert that we couldn''t find a seat.", "B": "He spends a lot deal of time reading. There were so many people at the concert that we couldn''t find a seat.", "C": "He spends a great deal of time reading. There were such many people at the concert that we couldn''t find a seat.", "D": "He spends a large deal of time reading. There were so many people at the concert that we couldn''t find a seat.", "E": "He spends a great deal of time reading. There were so many people at the concert that we couldn''t find a seat."}'::jsonb, 'E', NULL, 'a great — a great deal of + saylanmayan; so many — so many + saylan cəm.');
INSERT INTO public.questions VALUES (10583, 134, 'g11-eng-quant-q2-13', 2, 13, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We have many time; we must hurry. There''s hardly any sugar left.", "B": "We have little time; we must hurry. There''s hardly some sugar left.", "C": "We have few time; we must hurry. There''s hardly any sugar left.", "D": "We have little time; we must hurry. There''s hardly any sugar left.", "E": "We have little time; we must hurry. There''s hardly many sugar left."}'::jsonb, 'D', NULL, 'little — little + saylanmayan (mənfi məna); any — hardly any — demək olar ki, heç.');
INSERT INTO public.questions VALUES (10584, 134, 'g11-eng-quant-q2-14', 2, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "You can take both road; both lead to the city centre.", "B": "Every of my parents are doctors.", "C": "She has much friends, so she often feels lonely.", "D": "Plenty of volunteers came to help.", "E": "We bought many furniture for the new flat."}'::jsonb, 'D', NULL, 'Correct: «Plenty of volunteers came to help.» — plenty of + isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10585, 134, 'g11-eng-quant-q2-15', 2, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) Plenty ___ volunteers came to help. (2) I have ___ money, so I can buy you a coffee. (3) ___ number of tourists has increased this year.', NULL, NULL, '{"A": "of / a little / —", "B": "of / few / The", "C": "of / a little / The", "D": "of / a few / The", "E": "of / a little / Many"}'::jsonb, 'C', NULL, '(1) of — plenty of + isim (2) a little — a little + saylanmayan (müsbət məna: bir az var) (3) The — the number of + tək feil (has)');
INSERT INTO public.questions VALUES (10586, 134, 'g11-eng-quant-q2-16', 2, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of the two answers is correct, so try again.", "B": "We had a great deal problems with the new software.", "C": "Plenty much volunteers came to help.", "D": "We bought some furniture for the new flat.", "E": "He hardly has some free time these days."}'::jsonb, 'D', NULL, 'Correct: «We bought some furniture for the new flat.» — furniture saylanmayandır → some. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10587, 134, 'g11-eng-quant-q2-17', 2, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He hardly has no free time these days.", "B": "How few luggage do you have?", "C": "Many number of tourists has increased this year.", "D": "All of the two answers is correct, so try again.", "E": "She has few friends, so she often feels lonely."}'::jsonb, 'E', NULL, 'Correct: «She has few friends, so she often feels lonely.» — few + saylan (mənfi məna: az, demək olar ki, yox). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10588, 134, 'g11-eng-quant-q2-18', 2, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I don''t have few information about this topic.", "B": "We bought a few furniture for the new flat.", "C": "I have a little money, so I can buy you a coffee.", "D": "Plenty many volunteers came to help.", "E": "He hardly has no free time these days."}'::jsonb, 'C', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10589, 134, 'g11-eng-quant-q2-19', 2, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We had several problems with the new software. I''ve got a few homework to do tonight.", "B": "We had several problems with the new software. I''ve got many homework to do tonight.", "C": "We had a little problems with the new software. I''ve got a lot of homework to do tonight.", "D": "We had several problems with the new software. I''ve got a lot of homework to do tonight.", "E": "We had several problems with the new software. I''ve got several homework to do tonight."}'::jsonb, 'D', NULL, 'several — several + saylan cəm; a lot of — homework saylanmayandır → a lot of / much.');
INSERT INTO public.questions VALUES (10590, 134, 'g11-eng-quant-q2-20', 2, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) It was ___ a long journey that we were exhausted. (3) He hardly has ___ free time these days.', NULL, NULL, '{"A": "How few / such / any", "B": "How much / such / any", "C": "How much / very / any", "D": "How much / such / some", "E": "How much / so / any"}'::jsonb, 'B', NULL, '(1) How much — luggage saylanmayandır → how much (2) such — such + (a) + sifət + isim (3) any — hardly (inkar mənalı) + any');
INSERT INTO public.questions VALUES (10591, 134, 'g11-eng-quant-q2-21', 2, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There''s hardly any sugar left. He spends many deal of time reading.", "B": "There''s hardly any sugar left. He spends a large deal of time reading.", "C": "There''s hardly many sugar left. He spends a great deal of time reading.", "D": "There''s hardly few sugar left. He spends a great deal of time reading.", "E": "There''s hardly any sugar left. He spends a great deal of time reading."}'::jsonb, 'E', NULL, 'any — hardly any — demək olar ki, heç; a great — a great deal of + saylanmayan.');
INSERT INTO public.questions VALUES (10592, 134, 'g11-eng-quant-q2-22', 2, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "How few luggage do you have?", "B": "Both of the cakes is mine; take the other one.", "C": "I have a little money, so I can buy you a coffee.", "D": "We bought many furniture for the new flat.", "E": "We had much problems with the new software."}'::jsonb, 'C', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10593, 134, 'g11-eng-quant-q2-23', 2, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A number of tourists has increased this year.", "B": "None of the students passed the test; it was too difficult.", "C": "I don''t have few information about this topic.", "D": "It was so a long journey that we were exhausted.", "E": "She gave me many useful advice."}'::jsonb, 'B', NULL, 'Correct: «None of the students passed the test; it was too difficult.» — none of + cəm (üç və daha çox): heç biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10594, 134, 'g11-eng-quant-q2-24', 2, 24, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It was too a long journey that we were exhausted. All the children enjoyed the trip.", "B": "It was such a long journey that we were exhausted. Every the children enjoyed the trip.", "C": "It was very a long journey that we were exhausted. All the children enjoyed the trip.", "D": "It was such a long journey that we were exhausted. All the children enjoyed the trip.", "E": "It was such a long journey that we were exhausted. Either the children enjoyed the trip."}'::jsonb, 'D', NULL, 'such — such + (a) + sifət + isim; All — all (of) the + cəm.');
INSERT INTO public.questions VALUES (10595, 134, 'g11-eng-quant-q2-25', 2, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I''ve got ___ homework to do tonight. (2) Plenty ___ volunteers came to help. (3) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "a lot of / much / One", "B": "a lot of / of / One", "C": "many / of / One", "D": "a lot of / of / All", "E": "a few / of / One"}'::jsonb, 'B', NULL, '(1) a lot of — homework saylanmayandır → a lot of / much (2) of — plenty of + isim (3) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (10596, 134, 'g11-eng-quant-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the students passed the test; it was too difficult. (2) ___ the children enjoyed the trip. (3) ___ of the cakes is mine; take the other one.', NULL, NULL, '{"A": "None / All / One", "B": "None / Every / One", "C": "Nobody / All / One", "D": "None / Either / One", "E": "None / All / All"}'::jsonb, 'A', NULL, '(1) None — none of + cəm (üç və daha çox): heç biri (2) All — all (of) the + cəm (3) One — one of + cəm isim + tək feil');
INSERT INTO public.questions VALUES (10597, 134, 'g11-eng-quant-q2-27', 2, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were such many people at the concert that we couldn''t find a seat.", "B": "Every the children enjoyed the trip.", "C": "We had several problems with the new software.", "D": "There''s hardly many sugar left.", "E": "You can take both road; both lead to the city centre."}'::jsonb, 'C', NULL, 'Correct: «We had several problems with the new software.» — several + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10598, 134, 'g11-eng-quant-q2-28', 2, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There''s hardly ___ sugar left. (2) ___ number of tourists has increased this year. (3) There were ___ people at the concert that we couldn''t find a seat.', NULL, NULL, '{"A": "any / Many / so many", "B": "any / The / too much", "C": "any / The / so many", "D": "any / The / such many", "E": "few / The / so many"}'::jsonb, 'C', NULL, '(1) any — hardly any — demək olar ki, heç (2) The — the number of + tək feil (has) (3) so many — so many + saylan cəm');
INSERT INTO public.questions VALUES (10599, 134, 'g11-eng-quant-q2-29', 2, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Plenty much volunteers came to help.", "B": "She has few friends, so she often feels lonely.", "C": "Many number of tourists has increased this year.", "D": "Much number of tourists have complained about the hotel.", "E": "Both of the two answers is correct, so try again."}'::jsonb, 'B', NULL, 'Correct: «She has few friends, so she often feels lonely.» — few + saylan (mənfi məna: az, demək olar ki, yox). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10600, 134, 'g11-eng-quant-q2-30', 2, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) ___ of the students passed the test; it was too difficult. (3) I don''t have ___ information about this topic.', NULL, NULL, '{"A": "How much / None / few", "B": "How few / None / much", "C": "How much / No / much", "D": "How much / None / much", "E": "How much / Nobody / much"}'::jsonb, 'D', NULL, '(1) How much — luggage saylanmayandır → how much (2) None — none of + cəm (üç və daha çox): heç biri (3) much — information saylanmayandır → much');
INSERT INTO public.questions VALUES (10601, 134, 'g11-eng-quant-q3-01', 3, 1, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "A number of tourists have complained about the hotel. He hardly has any free time these days.", "B": "A number of tourists have complained about the hotel. He hardly has many free time these days.", "C": "A number of tourists have complained about the hotel. He hardly has no free time these days.", "D": "Number of tourists have complained about the hotel. He hardly has any free time these days.", "E": "The number of tourists have complained about the hotel. He hardly has any free time these days."}'::jsonb, 'A', NULL, 'A — a number of (bir neçə) + cəm feil (have); any — hardly (inkar mənalı) + any.');
INSERT INTO public.questions VALUES (10602, 134, 'g11-eng-quant-q3-02', 3, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There were ___ people at the concert that we couldn''t find a seat. (2) ___ number of tourists has increased this year. (3) You can take ___ road; both lead to the city centre.', NULL, NULL, '{"A": "so many / — / either", "B": "too much / The / either", "C": "so many / The / either", "D": "so many / A / either", "E": "so much / The / either"}'::jsonb, 'C', NULL, '(1) so many — so many + saylan cəm (2) The — the number of + tək feil (has) (3) either — either + tək isim: ikisindən hər hansı biri');
INSERT INTO public.questions VALUES (10603, 134, 'g11-eng-quant-q3-03', 3, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) ___ number of tourists has increased this year. (3) It was ___ a long journey that we were exhausted.', NULL, NULL, '{"A": "How much / The / such", "B": "How a lot / The / such", "C": "How few / The / such", "D": "How much / Many / such", "E": "How much / — / such"}'::jsonb, 'A', NULL, '(1) How much — luggage saylanmayandır → how much (2) The — the number of + tək feil (has) (3) such — such + (a) + sifət + isim');
INSERT INTO public.questions VALUES (10604, 134, 'g11-eng-quant-q3-04', 3, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were so many people at the concert that we couldn''t find a seat.", "B": "We had a little problems with the new software.", "C": "Only much students came to the lecture, so it was cancelled.", "D": "How many luggage do you have?", "E": "We bought many furniture for the new flat."}'::jsonb, 'A', NULL, 'Correct: «There were so many people at the concert that we couldn''t find a seat.» — so many + saylan cəm. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10605, 134, 'g11-eng-quant-q3-05', 3, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Much of my parents are doctors.", "B": "Plenty many volunteers came to help.", "C": "Either the children enjoyed the trip.", "D": "I don''t have many information about this topic.", "E": "I have a little money, so I can buy you a coffee."}'::jsonb, 'E', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10606, 134, 'g11-eng-quant-q3-06', 3, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ the children enjoyed the trip. (2) ___ number of tourists have complained about the hotel. (3) He spends ___ deal of time reading.', NULL, NULL, '{"A": "All / A / a great", "B": "All / The / a great", "C": "All / A / many", "D": "Either / A / a great", "E": "Each / A / a great"}'::jsonb, 'A', NULL, '(1) All — all (of) the + cəm (2) A — a number of (bir neçə) + cəm feil (have) (3) a great — a great deal of + saylanmayan');
INSERT INTO public.questions VALUES (10607, 134, 'g11-eng-quant-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) He spends ___ deal of time reading. (2) He hardly has ___ free time these days. (3) We bought ___ furniture for the new flat.', NULL, NULL, '{"A": "many / any / some", "B": "a great / many / some", "C": "a great / some / some", "D": "a great / no / some", "E": "a great / any / some"}'::jsonb, 'E', NULL, '(1) a great — a great deal of + saylanmayan (2) any — hardly (inkar mənalı) + any (3) some — furniture saylanmayandır → some');
INSERT INTO public.questions VALUES (10608, 134, 'g11-eng-quant-q3-08', 3, 8, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He spends a lot deal of time reading. We bought some furniture for the new flat.", "B": "He spends a great deal of time reading. We bought several furniture for the new flat.", "C": "He spends a great deal of time reading. We bought some furniture for the new flat.", "D": "He spends many deal of time reading. We bought some furniture for the new flat.", "E": "He spends a great deal of time reading. We bought many furniture for the new flat."}'::jsonb, 'C', NULL, 'a great — a great deal of + saylanmayan; some — furniture saylanmayandır → some.');
INSERT INTO public.questions VALUES (10609, 134, 'g11-eng-quant-q3-09', 3, 9, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were so many people at the concert that we couldn''t find a seat. How a lot luggage do you have?", "B": "There were so many people at the concert that we couldn''t find a seat. How much luggage do you have?", "C": "There were so many people at the concert that we couldn''t find a seat. How many luggage do you have?", "D": "There were such many people at the concert that we couldn''t find a seat. How much luggage do you have?", "E": "There were so much people at the concert that we couldn''t find a seat. How much luggage do you have?"}'::jsonb, 'B', NULL, 'so many — so many + saylan cəm; How much — luggage saylanmayandır → how much.');
INSERT INTO public.questions VALUES (10610, 134, 'g11-eng-quant-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We bought many furniture for the new flat.", "B": "Only much students came to the lecture, so it was cancelled.", "C": "How a lot luggage do you have?", "D": "He hardly has some free time these days.", "E": "I have a little money, so I can buy you a coffee."}'::jsonb, 'E', NULL, 'Correct: «I have a little money, so I can buy you a coffee.» — a little + saylanmayan (müsbət məna: bir az var). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10611, 134, 'g11-eng-quant-q3-11', 3, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We had much problems with the new software.", "B": "She gave me an useful advice.", "C": "It was so a long journey that we were exhausted.", "D": "Either the children enjoyed the trip.", "E": "He hardly has any free time these days."}'::jsonb, 'E', NULL, 'Correct: «He hardly has any free time these days.» — hardly (inkar mənalı) + any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10612, 134, 'g11-eng-quant-q3-12', 3, 12, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "One of the cakes is mine; take the other one. None of the students passed the test; it was too difficult.", "B": "One of the cakes is mine; take the other one. No of the students passed the test; it was too difficult.", "C": "All of the cakes is mine; take the other one. None of the students passed the test; it was too difficult.", "D": "Some of the cakes is mine; take the other one. None of the students passed the test; it was too difficult.", "E": "One of the cakes is mine; take the other one. Nobody of the students passed the test; it was too difficult."}'::jsonb, 'A', NULL, 'One — one of + cəm isim + tək feil; None — none of + cəm (üç və daha çox): heç biri.');
INSERT INTO public.questions VALUES (10613, 134, 'g11-eng-quant-q3-13', 3, 13, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "How much luggage do you have? He spends a large deal of time reading.", "B": "How much luggage do you have? He spends a lot deal of time reading.", "C": "How much luggage do you have? He spends a great deal of time reading.", "D": "How many luggage do you have? He spends a great deal of time reading.", "E": "How few luggage do you have? He spends a great deal of time reading."}'::jsonb, 'C', NULL, 'How much — luggage saylanmayandır → how much; a great — a great deal of + saylanmayan.');
INSERT INTO public.questions VALUES (10614, 134, 'g11-eng-quant-q3-14', 3, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Either the children enjoyed the trip. How much luggage do you have?", "B": "All the children enjoyed the trip. How a lot luggage do you have?", "C": "Every the children enjoyed the trip. How much luggage do you have?", "D": "All the children enjoyed the trip. How much luggage do you have?", "E": "All the children enjoyed the trip. How few luggage do you have?"}'::jsonb, 'D', NULL, 'All — all (of) the + cəm; How much — luggage saylanmayandır → how much.');
INSERT INTO public.questions VALUES (10615, 134, 'g11-eng-quant-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I''ve got ___ homework to do tonight. (2) ___ of the two answers is correct, so try again. (3) There were ___ people at the concert that we couldn''t find a seat.', NULL, NULL, '{"A": "a few / Neither / so many", "B": "a lot of / Neither / so much", "C": "a lot of / Neither / too much", "D": "a lot of / All / so many", "E": "a lot of / Neither / so many"}'::jsonb, 'E', NULL, '(1) a lot of — homework saylanmayandır → a lot of / much (2) Neither — neither of (ikisindən heç biri) + tək feil (is) (3) so many — so many + saylan cəm');
INSERT INTO public.questions VALUES (10616, 134, 'g11-eng-quant-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) There were ___ people at the concert that we couldn''t find a seat. (2) ___ of the two answers is correct, so try again. (3) There''s hardly ___ sugar left.', NULL, NULL, '{"A": "so many / Neither / some", "B": "so much / Neither / any", "C": "so many / Neither / many", "D": "such many / Neither / any", "E": "so many / Neither / any"}'::jsonb, 'E', NULL, '(1) so many — so many + saylan cəm (2) Neither — neither of (ikisindən heç biri) + tək feil (is) (3) any — hardly any — demək olar ki, heç');
INSERT INTO public.questions VALUES (10617, 134, 'g11-eng-quant-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) I have ___ money, so I can buy you a coffee. (2) We had ___ problems with the new software. (3) I don''t have ___ information about this topic.', NULL, NULL, '{"A": "a little / a great deal / much", "B": "a little / several / much", "C": "many / several / much", "D": "a little / a little / much", "E": "few / several / much"}'::jsonb, 'B', NULL, '(1) a little — a little + saylanmayan (müsbət məna: bir az var) (2) several — several + saylan cəm (3) much — information saylanmayandır → much');
INSERT INTO public.questions VALUES (10618, 134, 'g11-eng-quant-q3-18', 3, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "None of the students passed the test; it was too difficult.", "B": "Every of my parents are doctors.", "C": "He spends a large deal of time reading.", "D": "Some of the cakes is mine; take the other one.", "E": "He hardly has many free time these days."}'::jsonb, 'A', NULL, 'Correct: «None of the students passed the test; it was too difficult.» — none of + cəm (üç və daha çox): heç biri. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10619, 134, 'g11-eng-quant-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There''s hardly few sugar left.", "B": "You can take all road; both lead to the city centre.", "C": "Only little students came to the lecture, so it was cancelled.", "D": "We had a little problems with the new software.", "E": "It was such a long journey that we were exhausted."}'::jsonb, 'E', NULL, 'Correct: «It was such a long journey that we were exhausted.» — such + (a) + sifət + isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10620, 134, 'g11-eng-quant-q3-20', 3, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) There were ___ people at the concert that we couldn''t find a seat. (3) I''ve got ___ homework to do tonight.', NULL, NULL, '{"A": "How much / so many / a lot of", "B": "How much / so much / a lot of", "C": "How much / so many / many", "D": "How much / such many / a lot of", "E": "How much / so many / a few"}'::jsonb, 'A', NULL, '(1) How much — luggage saylanmayandır → how much (2) so many — so many + saylan cəm (3) a lot of — homework saylanmayandır → a lot of / much');
INSERT INTO public.questions VALUES (10621, 134, 'g11-eng-quant-q3-21', 3, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Any of the students passed the test; it was too difficult. Plenty of volunteers came to help.", "B": "None of the students passed the test; it was too difficult. Plenty of volunteers came to help.", "C": "Nobody of the students passed the test; it was too difficult. Plenty of volunteers came to help.", "D": "None of the students passed the test; it was too difficult. Plenty much volunteers came to help.", "E": "No of the students passed the test; it was too difficult. Plenty of volunteers came to help."}'::jsonb, 'B', NULL, 'None — none of + cəm (üç və daha çox): heç biri; of — plenty of + isim.');
INSERT INTO public.questions VALUES (10622, 134, 'g11-eng-quant-q3-22', 3, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I don''t have few information about this topic.", "B": "She gave me an useful advice.", "C": "There were so much people at the concert that we couldn''t find a seat.", "D": "The number of tourists has increased this year.", "E": "We have a few time; we must hurry."}'::jsonb, 'D', NULL, 'Correct: «The number of tourists has increased this year.» — the number of + tək feil (has). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10623, 134, 'g11-eng-quant-q3-23', 3, 23, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "None of the students passed the test; it was too difficult. I have few money, so I can buy you a coffee.", "B": "None of the students passed the test; it was too difficult. I have a little money, so I can buy you a coffee.", "C": "None of the students passed the test; it was too difficult. I have many money, so I can buy you a coffee.", "D": "No of the students passed the test; it was too difficult. I have a little money, so I can buy you a coffee.", "E": "Nobody of the students passed the test; it was too difficult. I have a little money, so I can buy you a coffee."}'::jsonb, 'B', NULL, 'None — none of + cəm (üç və daha çox): heç biri; a little — a little + saylanmayan (müsbət məna: bir az var).');
INSERT INTO public.questions VALUES (10624, 134, 'g11-eng-quant-q3-24', 3, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Both of the cakes is mine; take the other one.", "B": "It was very a long journey that we were exhausted.", "C": "He hardly has any free time these days.", "D": "I don''t have few information about this topic.", "E": "Number of tourists has increased this year."}'::jsonb, 'C', NULL, 'Correct: «He hardly has any free time these days.» — hardly (inkar mənalı) + any. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10625, 134, 'g11-eng-quant-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Plenty many volunteers came to help.", "B": "It was so a long journey that we were exhausted.", "C": "He spends a lot deal of time reading.", "D": "She gave me some useful advice.", "E": "I''ve got several homework to do tonight."}'::jsonb, 'D', NULL, 'Correct: «She gave me some useful advice.» — advice saylanmayandır → some advice. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10626, 134, 'g11-eng-quant-q3-26', 3, 26, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We bought some furniture for the new flat. It was so a long journey that we were exhausted.", "B": "We bought many furniture for the new flat. It was such a long journey that we were exhausted.", "C": "We bought several furniture for the new flat. It was such a long journey that we were exhausted.", "D": "We bought some furniture for the new flat. It was such a long journey that we were exhausted.", "E": "We bought some furniture for the new flat. It was very a long journey that we were exhausted."}'::jsonb, 'D', NULL, 'some — furniture saylanmayandır → some; such — such + (a) + sifət + isim.');
INSERT INTO public.questions VALUES (10627, 134, 'g11-eng-quant-q3-27', 3, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ of the students passed the test; it was too difficult. (2) There''s hardly ___ sugar left. (3) ___ of the two answers is correct, so try again.', NULL, NULL, '{"A": "Nobody / any / Neither", "B": "None / any / Neither", "C": "None / few / Neither", "D": "None / many / Neither", "E": "No / any / Neither"}'::jsonb, 'B', NULL, '(1) None — none of + cəm (üç və daha çox): heç biri (2) any — hardly any — demək olar ki, heç (3) Neither — neither of (ikisindən heç biri) + tək feil (is)');
INSERT INTO public.questions VALUES (10628, 134, 'g11-eng-quant-q3-28', 3, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "None of the students passed the test; it was too difficult. She gave me an useful advice.", "B": "None of the students passed the test; it was too difficult. She gave me some useful advice.", "C": "None of the students passed the test; it was too difficult. She gave me many useful advice.", "D": "Nobody of the students passed the test; it was too difficult. She gave me some useful advice.", "E": "No of the students passed the test; it was too difficult. She gave me some useful advice."}'::jsonb, 'B', NULL, 'None — none of + cəm (üç və daha çox): heç biri; some — advice saylanmayandır → some advice.');
INSERT INTO public.questions VALUES (10629, 134, 'g11-eng-quant-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps (— = nothing): (1) ___ luggage do you have? (2) We have ___ time; we must hurry. (3) ___ number of tourists has increased this year.', NULL, NULL, '{"A": "How much / few / The", "B": "How much / little / A", "C": "How much / a few / The", "D": "How much / little / Many", "E": "How much / little / The"}'::jsonb, 'E', NULL, '(1) How much — luggage saylanmayandır → how much (2) little — little + saylanmayan (mənfi məna) (3) The — the number of + tək feil (has)');
INSERT INTO public.questions VALUES (10630, 134, 'g11-eng-quant-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Any of the students passed the test; it was too difficult.", "B": "Plenty much volunteers came to help.", "C": "She gave me many useful advice.", "D": "I don''t have much information about this topic.", "E": "You can take both road; both lead to the city centre."}'::jsonb, 'D', NULL, 'Correct: «I don''t have much information about this topic.» — information saylanmayandır → much. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10631, 135, 'g11-eng-noun-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This is the ___ room. (girls — bir neçə qız) (2) The news ___ shocking. (3) It was a three-___ journey.', NULL, NULL, '{"A": "girls'' / were / hour", "B": "girls'' / was / hours", "C": "girls'' / was / hour", "D": "girls''s / was / hour", "E": "girls / was / hour"}'::jsonb, 'C', NULL, '(1) girls'' — Cəm -s ilə bitəndə yiyəlik: girls'' (2) was — news + tək feil (3) hour — a three-hour journey — tək forma');
INSERT INTO public.questions VALUES (10632, 135, 'g11-eng-noun-q1-02', 1, 2, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Scientists have discovered two new species of birds. The report mentions three phenomenons.", "B": "Scientists have discovered two new species of birds. The report mentions three phenomena.", "C": "Scientists have discovered two new specieses of birds. The report mentions three phenomena.", "D": "Scientists have discovered two new specie of birds. The report mentions three phenomena.", "E": "Scientists have discovered two new species of birds. The report mentions three phenomenas."}'::jsonb, 'B', NULL, 'species — species tək və cəmdə eynidir; phenomena — phenomenon → phenomena.');
INSERT INTO public.questions VALUES (10633, 135, 'g11-eng-noun-q1-03', 1, 3, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The new on TV was very bad today. The scissors are on the table.", "B": "The news on TV was very bad today. The scissors is on the table.", "C": "The news'' on TV was very bad today. The scissors are on the table.", "D": "The news on TV was very bad today. The scissors was on the table.", "E": "The news on TV was very bad today. The scissors are on the table."}'::jsonb, 'E', NULL, 'news — news tək sayılır (the news was); are — scissors cəm feillə.');
INSERT INTO public.questions VALUES (10634, 135, 'g11-eng-noun-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three sheepes in the picture.", "B": "We need new furnitures for the office.", "C": "The cattles are grazing in the field.", "D": "Mathematics are my favourite subject.", "E": "She has a ten-year-old son."}'::jsonb, 'E', NULL, 'Correct: «She has a ten-year-old son.» — Mürəkkəb sifətdə isim tək olur: a ten-year-old. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10635, 135, 'g11-eng-noun-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I bought two ___ of bread. (2) Scientists have discovered two new ___ of birds. (species) (3) There were three ___ (hero) in the picture.', NULL, NULL, '{"A": "loaves / species / heroes", "B": "loaves'' / species / heroes", "C": "loaves / specieses / heroes", "D": "loaves / species'' / heroes", "E": "loaf / species / heroes"}'::jsonb, 'A', NULL, '(1) loaves — loaf → loaves (2) species — species tək və cəmdə eynidir (3) heroes — hero → heroes');
INSERT INTO public.questions VALUES (10636, 135, 'g11-eng-noun-q1-06', 1, 6, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three sheep in the picture. The cattle are grazing in the field.", "B": "There were three sheeps in the picture. The cattle are grazing in the field.", "C": "There were three sheepes in the picture. The cattle are grazing in the field.", "D": "There were three sheep in the picture. The cattle''s are grazing in the field.", "E": "There were three sheep in the picture. The cattlees are grazing in the field."}'::jsonb, 'A', NULL, 'sheep — sheep → sheep; cattle — cattle həmişə cəm, -s qəbul etmir.');
INSERT INTO public.questions VALUES (10637, 135, 'g11-eng-noun-q1-07', 1, 7, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He gave me a useful piece of advice. There were three geeses in the picture.", "B": "He gave me a useful piece of an advice. There were three geese in the picture.", "C": "He gave me a useful piece of advice. There were three geese in the picture.", "D": "He gave me a useful piece of advices. There were three geese in the picture.", "E": "He gave me a useful piece of advice. There were three gooses in the picture."}'::jsonb, 'C', NULL, 'advice — a piece of advice — advice saylanmayan; geese — goose → geese.');
INSERT INTO public.questions VALUES (10638, 135, 'g11-eng-noun-q1-08', 1, 8, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three feets in the picture. Scientists have discovered two new species of birds.", "B": "There were three feet in the picture. Scientists have discovered two new species'' of birds.", "C": "There were three foots in the picture. Scientists have discovered two new species of birds.", "D": "There were three feet in the picture. Scientists have discovered two new species of birds.", "E": "There were three feet in the picture. Scientists have discovered two new specieses of birds."}'::jsonb, 'D', NULL, 'feet — foot → feet; species — species tək və cəmdə eynidir.');
INSERT INTO public.questions VALUES (10639, 135, 'g11-eng-noun-q1-09', 1, 9, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The new on TV was very bad today. The report mentions three phenomena.", "B": "The news on TV was very bad today. The report mentions three phenomenons.", "C": "The newses on TV was very bad today. The report mentions three phenomena.", "D": "The news on TV was very bad today. The report mentions three phenomena.", "E": "The news'' on TV was very bad today. The report mentions three phenomena."}'::jsonb, 'D', NULL, 'news — news tək sayılır (the news was); phenomena — phenomenon → phenomena.');
INSERT INTO public.questions VALUES (10640, 135, 'g11-eng-noun-q1-10', 1, 10, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three cities in the picture. There were three leavs in the picture.", "B": "There were three citys in the picture. There were three leaves in the picture.", "C": "There were three cityes in the picture. There were three leaves in the picture.", "D": "There were three cities in the picture. There were three leafs in the picture.", "E": "There were three cities in the picture. There were three leaves in the picture."}'::jsonb, 'E', NULL, 'cities — city → cities; leaves — leaf → leaves.');
INSERT INTO public.questions VALUES (10641, 135, 'g11-eng-noun-q1-11', 1, 11, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three mothers-in-laws in the picture.", "B": "The report mentions three phenomenons.", "C": "There were three feet in the picture.", "D": "There were three heros in the picture.", "E": "It was a three-hourly journey."}'::jsonb, 'C', NULL, 'Correct: «There were three feet in the picture.» — foot → feet. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10642, 135, 'g11-eng-noun-q1-12', 1, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Mathematics have been my favourite subject.", "B": "There are many fishs on the farm.", "C": "I bought two loaf of bread.", "D": "The police are looking for the missing boy.", "E": "My jeans is too tight."}'::jsonb, 'D', NULL, 'Correct: «The police are looking for the missing boy.» — police həmişə cəm feillə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10643, 135, 'g11-eng-noun-q1-13', 1, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The ___ on TV was very bad today. (2) There were three ___ (leaf) in the picture. (3) The report mentions three ___ (criterion).', NULL, NULL, '{"A": "newses / leaves / criteria", "B": "news / leaves / criteria", "C": "news / leafs / criteria", "D": "news / leaves / criterions", "E": "new / leaves / criteria"}'::jsonb, 'B', NULL, '(1) news — news tək sayılır (the news was) (2) leaves — leaf → leaves (3) criteria — criterion → criteria');
INSERT INTO public.questions VALUES (10644, 135, 'g11-eng-noun-q1-14', 1, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three sheep in the picture. She has a ten-years-old son.", "B": "There were three sheeps in the picture. She has a ten-year-old son.", "C": "There were three sheep in the picture. She has a ten-yearly-old son.", "D": "There were three sheep in the picture. She has a ten-year''s-old son.", "E": "There were three sheep in the picture. She has a ten-year-old son."}'::jsonb, 'E', NULL, 'sheep — sheep → sheep; year — Mürəkkəb sifətdə isim tək olur: a ten-year-old.');
INSERT INTO public.questions VALUES (10645, 135, 'g11-eng-noun-q1-15', 1, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three leafs in the picture.", "B": "Our luggage''s was lost at the airport.", "C": "There were three sheeps in the picture.", "D": "The police are looking for the missing boy.", "E": "There are many fishs on the farm."}'::jsonb, 'D', NULL, 'Correct: «The police are looking for the missing boy.» — police həmişə cəm feillə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10646, 135, 'g11-eng-noun-q1-16', 1, 16, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She has a ten-year-old son. Our a luggage was lost at the airport.", "B": "She has a ten-yearly-old son. Our luggage was lost at the airport.", "C": "She has a ten-years-old son. Our luggage was lost at the airport.", "D": "She has a ten-year-old son. Our luggage''s was lost at the airport.", "E": "She has a ten-year-old son. Our luggage was lost at the airport."}'::jsonb, 'E', NULL, 'year — Mürəkkəb sifətdə isim tək olur: a ten-year-old; luggage — luggage saylanmayandır.');
INSERT INTO public.questions VALUES (10647, 135, 'g11-eng-noun-q1-17', 1, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three roofies in the picture.", "B": "There were three passer-bys in the picture.", "C": "I bought two loafs of bread.", "D": "My parents'' car is very old.", "E": "The newses on TV was very bad today."}'::jsonb, 'D', NULL, 'Correct: «My parents'' car is very old.» — Cəm -s ilə: parents''. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10648, 135, 'g11-eng-noun-q1-18', 1, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She has a ten-yearly-old son.", "B": "There were three roofies in the picture.", "C": "There are many fish on the farm.", "D": "The report mentions three analysises.", "E": "These are the children'' toys."}'::jsonb, 'C', NULL, 'Correct: «There are many fish on the farm.» — fish (eyni növ) cəmdə dəyişmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10649, 135, 'g11-eng-noun-q1-19', 1, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We need new furniture for the office.", "B": "There were three gooses in the picture.", "C": "These are the children'' toys.", "D": "There were three leafs in the picture.", "E": "She has a ten-years-old son."}'::jsonb, 'A', NULL, 'Correct: «We need new furniture for the office.» — furniture saylanmayandır. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10650, 135, 'g11-eng-noun-q1-20', 1, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) These are the ___ toys. (children) (2) There were three ___ (city) in the picture. (3) The news ___ shocking.', NULL, NULL, '{"A": "childrens'' / cities / was", "B": "children''s / cities / have been", "C": "children''s / cities / were", "D": "children''s / cities / was", "E": "children''s / cities / are"}'::jsonb, 'D', NULL, '(1) children''s — Qeyri-adi cəmdə yiyəlik: children''s (2) cities — city → cities (3) was — news + tək feil');
INSERT INTO public.questions VALUES (10651, 135, 'g11-eng-noun-q1-21', 1, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "These are the children''s toys.", "B": "The report mentions three analysises.", "C": "There are many fishs on the farm.", "D": "There were three gooses in the picture.", "E": "It was a three-hours journey."}'::jsonb, 'A', NULL, 'Correct: «These are the children''s toys.» — Qeyri-adi cəmdə yiyəlik: children''s. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10652, 135, 'g11-eng-noun-q1-22', 1, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There are many ___ on the farm. (fish) (2) The ___ on TV was very bad today. (3) She has a ten-___-old son.', NULL, NULL, '{"A": "fishs / news / year", "B": "fish / news / year''s", "C": "fish / news / year", "D": "fish / new / year", "E": "fish / newses / year"}'::jsonb, 'C', NULL, '(1) fish — fish (eyni növ) cəmdə dəyişmir (2) news — news tək sayılır (the news was) (3) year — Mürəkkəb sifətdə isim tək olur: a ten-year-old');
INSERT INTO public.questions VALUES (10653, 135, 'g11-eng-noun-q1-23', 1, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The cattlees are grazing in the field.", "B": "She has a ten-year''s-old son.", "C": "These are the children''s toys.", "D": "There were three roofes in the picture.", "E": "It was a three-hours journey."}'::jsonb, 'C', NULL, 'Correct: «These are the children''s toys.» — Qeyri-adi cəmdə yiyəlik: children''s. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10654, 135, 'g11-eng-noun-q1-24', 1, 24, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three sheep in the picture. There are many fish on the farm.", "B": "There were three sheepes in the picture. There are many fish on the farm.", "C": "There were three sheeps in the picture. There are many fish on the farm.", "D": "There were three sheep in the picture. There are many fishies on the farm.", "E": "There were three sheep in the picture. There are many fishes'' on the farm."}'::jsonb, 'A', NULL, 'sheep — sheep → sheep; fish — fish (eyni növ) cəmdə dəyişmir.');
INSERT INTO public.questions VALUES (10655, 135, 'g11-eng-noun-q1-25', 1, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There are many ___ on the farm. (fish) (2) There were three ___ (goose) in the picture. (3) These are the ___ toys. (children)', NULL, NULL, '{"A": "fishes'' / geese / children''s", "B": "fishs / geese / children''s", "C": "fish / geese / childrens''", "D": "fishies / geese / children''s", "E": "fish / geese / children''s"}'::jsonb, 'E', NULL, '(1) fish — fish (eyni növ) cəmdə dəyişmir (2) geese — goose → geese (3) children''s — Qeyri-adi cəmdə yiyəlik: children''s');
INSERT INTO public.questions VALUES (10656, 135, 'g11-eng-noun-q1-26', 1, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (foot) in the picture. (2) There were three ___ (passer-by) in the picture. (3) My jeans ___ too tight.', NULL, NULL, '{"A": "feet / passers-bys / are", "B": "feet / passers-by / has", "C": "feet / passers-by / are", "D": "foots / passers-by / are", "E": "feet / passers-by / was"}'::jsonb, 'C', NULL, '(1) feet — foot → feet (2) passers-by — passer-by → passers-by (3) are — jeans, trousers, scissors — cəm isim');
