INSERT INTO public.questions VALUES (10700, 135, 'g11-eng-noun-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "These are the childrens toys.", "B": "There were three mother-in-laws in the picture.", "C": "The police has looking for the missing boy.", "D": "There were three feets in the picture.", "E": "The scissors are on the table."}'::jsonb, 'E', NULL, 'Correct: «The scissors are on the table.» — scissors cəm feillə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10701, 135, 'g11-eng-noun-q3-11', 3, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three mother-in-laws in the picture. The scissors are on the table.", "B": "There were three mothers-in-laws in the picture. The scissors are on the table.", "C": "There were three mothers-in-law in the picture. The scissors are on the table.", "D": "There were three mothers-in-law in the picture. The scissors is on the table.", "E": "There were three mothers-in-law in the picture. The scissors has been on the table."}'::jsonb, 'C', NULL, 'mothers-in-law — mother-in-law → mothers-in-law; are — scissors cəm feillə.');
