INSERT INTO public.questions VALUES (10703, 135, 'g11-eng-noun-q3-13', 3, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He gave me a useful piece of ___. (2) There were three ___ (passer-by) in the picture. (3) There were three ___ (leaf) in the picture.', NULL, NULL, '{"A": "advice / passers-by / leavs", "B": "advise / passers-by / leaves", "C": "advice / passer-bys / leaves", "D": "advice / passers-by / leaves", "E": "advices / passers-by / leaves"}'::jsonb, 'D', NULL, '(1) advice — a piece of advice — advice saylanmayan (2) passers-by — passer-by → passers-by (3) leaves — leaf → leaves');
INSERT INTO public.questions VALUES (10704, 135, 'g11-eng-noun-q3-14', 3, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "There were three passer-bys in the picture.", "B": "The report mentions three crisises.", "C": "There were three sheepes in the picture.", "D": "There were three leavs in the picture.", "E": "She has a ten-year-old son."}'::jsonb, 'E', NULL, 'Correct: «She has a ten-year-old son.» — Mürəkkəb sifətdə isim tək olur: a ten-year-old. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10705, 135, 'g11-eng-noun-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (roof) in the picture. (2) There were three ___ (city) in the picture. (3) My ___ car is very old. (parents)', NULL, NULL, '{"A": "roofs / citys / parents''", "B": "roofs / cities / parent''s''s", "C": "roofes / cities / parents''", "D": "roofs / cities / parents''", "E": "roofies / cities / parents''"}'::jsonb, 'D', NULL, '(1) roofs — roof → roofs (2) cities — city → cities (3) parents'' — Cəm -s ilə: parents''');
INSERT INTO public.questions VALUES (10706, 135, 'g11-eng-noun-q3-16', 3, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There were three ___ (sheep) in the picture. (2) There were three ___ (leaf) in the picture. (3) There were three ___ (foot) in the picture.', NULL, NULL, '{"A": "sheepes / leaves / feet", "B": "sheep / leaves / foots", "C": "sheep / leaves / feet", "D": "sheep / leaves / feets", "E": "sheep / leafs / feet"}'::jsonb, 'C', NULL, '(1) sheep — sheep → sheep (2) leaves — leaf → leaves (3) feet — foot → feet');
INSERT INTO public.questions VALUES (10707, 135, 'g11-eng-noun-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The report mentions three criterions.", "B": "There were three geeses in the picture.", "C": "My jeans are too tight.", "D": "The news are shocking.", "E": "The report mentions three crisises."}'::jsonb, 'C', NULL, 'Correct: «My jeans are too tight.» — jeans, trousers, scissors — cəm isim. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10708, 135, 'g11-eng-noun-q3-18', 3, 18, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "There were three heroes in the picture. We need new a furniture for the office.", "B": "There were three heroies in the picture. We need new furniture for the office.", "C": "There were three heroes in the picture. We need new furniture''s for the office.", "D": "There were three heroes in the picture. We need new furniture for the office.", "E": "There were three heros in the picture. We need new furniture for the office."}'::jsonb, 'D', NULL, 'heroes — hero → heroes; furniture — furniture saylanmayandır.');
INSERT INTO public.questions VALUES (10709, 135, 'g11-eng-noun-q3-19', 3, 19, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She has a ten-yearly-old son.", "B": "The cattle''s are grazing in the field.", "C": "There were three geese in the picture.", "D": "The new on TV was very bad today.", "E": "There were three feets in the picture."}'::jsonb, 'C', NULL, 'Correct: «There were three geese in the picture.» — goose → geese. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10710, 135, 'g11-eng-noun-q3-20', 3, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He gave me a useful piece of advice. We need new furniture for the office.", "B": "He gave me a useful piece of advice. We need new a furniture for the office.", "C": "He gave me a useful piece of advice. We need new furnitures for the office.", "D": "He gave me a useful piece of an advice. We need new furniture for the office.", "E": "He gave me a useful piece of advices. We need new furniture for the office."}'::jsonb, 'A', NULL, 'advice — a piece of advice — advice saylanmayan; furniture — furniture saylanmayandır.');
INSERT INTO public.questions VALUES (10711, 135, 'g11-eng-noun-q3-21', 3, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We need new furnitures for the office. This is the girls'' room.", "B": "We need new furniture for the office. This is the girl''s room.", "C": "We need new furniture for the office. This is the girls room.", "D": "We need new furniture for the office. This is the girls'' room.", "E": "We need new furniture''s for the office. This is the girls'' room."}'::jsonb, 'D', NULL, 'furniture — furniture saylanmayandır; girls'' — Cəm -s ilə bitəndə yiyəlik: girls''.');
