INSERT INTO public.questions VALUES (10713, 135, 'g11-eng-noun-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The news are shocking.", "B": "The report mentions three criterions.", "C": "These are the children''s toys.", "D": "Scientists have discovered two new specie of birds.", "E": "There were three feets in the picture."}'::jsonb, 'C', NULL, 'Correct: «These are the children''s toys.» — Qeyri-adi cəmdə yiyəlik: children''s. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10714, 135, 'g11-eng-noun-q3-24', 3, 24, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We need new a furniture for the office.", "B": "There were three sheeps in the picture.", "C": "There were three citys in the picture.", "D": "The report mentions three crisises.", "E": "There were three feet in the picture."}'::jsonb, 'E', NULL, 'Correct: «There were three feet in the picture.» — foot → feet. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10715, 135, 'g11-eng-noun-q3-25', 3, 25, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My parent''s''s car is very old.", "B": "The police has looking for the missing boy.", "C": "The news were shocking.", "D": "These are the children'' toys.", "E": "The cattle are grazing in the field."}'::jsonb, 'E', NULL, 'Correct: «The cattle are grazing in the field.» — cattle həmişə cəm, -s qəbul etmir. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10716, 135, 'g11-eng-noun-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The ___ on TV was very bad today. (2) There were three ___ (city) in the picture. (3) My ___ car is very old. (parents)', NULL, NULL, '{"A": "news / cityes / parents''", "B": "news / cities / parents''", "C": "news / cities / parentses''", "D": "news / citys / parents''", "E": "news / cities / parents"}'::jsonb, 'B', NULL, '(1) news — news tək sayılır (the news was) (2) cities — city → cities (3) parents'' — Cəm -s ilə: parents''');
INSERT INTO public.questions VALUES (10717, 135, 'g11-eng-noun-q3-27', 3, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Mathematics have been my favourite subject.", "B": "The scissors has been on the table.", "C": "The news was shocking.", "D": "My jeans has too tight.", "E": "There were three passer-bys in the picture."}'::jsonb, 'C', NULL, 'Correct: «The news was shocking.» — news + tək feil. The other sentences each contain an error.');
