INSERT INTO public.questions VALUES (10720, 135, 'g11-eng-noun-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He gave me a useful piece of ___. (2) There were three ___ (passer-by) in the picture. (3) Our ___ was lost at the airport.', NULL, NULL, '{"A": "advice / passers-by / luggage", "B": "advice / passers-by / a luggage", "C": "advice / passer-bys / luggage", "D": "advice / passers-by / luggages", "E": "advice / passers-bys / luggage"}'::jsonb, 'A', NULL, '(1) advice — a piece of advice — advice saylanmayan (2) passers-by — passer-by → passers-by (3) luggage — luggage saylanmayandır');
INSERT INTO public.questions VALUES (10721, 136, 'g11-eng-adj-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Your English is getting ___. (2) It is getting ___ to find a cheap flat in the city. (3) This summer was much ___ (dry) than last summer.', NULL, NULL, '{"A": "more and more good / harder / drier", "B": "better and better / more hard / drier", "C": "better and better / hardest / drier", "D": "better and better / harder / drier", "E": "better and better / harder / more driest"}'::jsonb, 'D', NULL, '(1) better and better — Artan dəyişiklik: comparative and comparative (2) harder — hard → harder (3) drier — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10722, 136, 'g11-eng-adj-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He has a black small Japanese car.", "B": "My sister looks much happier than before.", "C": "Their new flat is much more biggest than the old one.", "D": "This test is much most difficult than the last one.", "E": "We were shock by the news."}'::jsonb, 'B', NULL, 'Correct: «My sister looks much happier than before.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10723, 136, 'g11-eng-adj-q1-03', 1, 3, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This street is much more busiest than ours. Their new flat is much bigger than the old one.", "B": "This street is much busier than ours. Their new flat is much very bigger than the old one.", "C": "This street is much very busier than ours. Their new flat is much bigger than the old one.", "D": "This street is much busier than ours. Their new flat is much bigger than the old one.", "E": "This street is much busier than ours. Their new flat is much biggest than the old one."}'::jsonb, 'D', NULL, 'busier — much/far + müqayisə dərəcəsi (very işlənmir); bigger — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10724, 136, 'g11-eng-adj-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This book is much ___ (thin) than that one. (2) Leyla is much ___ (careful) than her brother. (3) He has a ___ car.', NULL, NULL, '{"A": "thinner / more careful / small black Japanese", "B": "thinner / more careful / black small Japanese", "C": "very thinner / more careful / small black Japanese", "D": "thinner / most careful / small black Japanese", "E": "thinnest / more careful / small black Japanese"}'::jsonb, 'A', NULL, '(1) thinner — much/far + müqayisə dərəcəsi (very işlənmir) (2) more careful — much/far + müqayisə dərəcəsi (very işlənmir) (3) small black Japanese — Sifət sırası: ölçü – rəng – mənşə');
INSERT INTO public.questions VALUES (10725, 136, 'g11-eng-adj-q1-05', 1, 5, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We were shocking by the news. This plan is much better than the first one.", "B": "We were shocked by the news. This plan is much more best than the first one.", "C": "We were shockingly by the news. This plan is much better than the first one.", "D": "We were shocked by the news. This plan is much better than the first one.", "E": "We were shocked by the news. This plan is much best than the first one."}'::jsonb, 'D', NULL, 'shocked — -ed: hiss (be shocked by); better — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10726, 136, 'g11-eng-adj-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This test is much ___ (difficult) than the last one. (2) It was the ___ (difficult) question in the exam. (3) The weather today is much ___ (bad) than yesterday.', NULL, NULL, '{"A": "more difficult / most difficultest / worse", "B": "more difficult / most difficult / worse", "C": "more difficult / more difficult / worse", "D": "most difficult / most difficult / worse", "E": "very more difficult / most difficult / worse"}'::jsonb, 'B', NULL, '(1) more difficult — much/far + müqayisə dərəcəsi (very işlənmir) (2) most difficult — Üstünlük dərəcəsi: difficult → the most difficult (3) worse — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10727, 136, 'g11-eng-adj-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The more you read, the more you know.", "B": "This street is much more busiest than ours.", "C": "It was the dryest month of the year.", "D": "This test is much most difficult than the last one.", "E": "This summer was much very drier than last summer."}'::jsonb, 'A', NULL, 'Correct: «The more you read, the more you know.» — the + comparative ..., the + comparative. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10728, 136, 'g11-eng-adj-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This street is much more busiest than ours.", "B": "It is the more modern office in the area.", "C": "It is the busyest street in the city.", "D": "I found a round dining wooden table at the market.", "E": "This test is more difficult than the last one."}'::jsonb, 'E', NULL, 'Correct: «This test is more difficult than the last one.» — Müqayisə dərəcəsi: difficult → more difficult. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10729, 136, 'g11-eng-adj-q1-09', 1, 9, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "They live in a lovely old stone house. This street is much busiest than ours.", "B": "They live in a lovely old stone house. This street is much busier than ours.", "C": "They live in a old lovely stone house. This street is much busier than ours.", "D": "They live in a lovely old stone house. This street is much very busier than ours.", "E": "They live in a lovely old stone house. This street is much more busiest than ours."}'::jsonb, 'B', NULL, 'lovely old stone — Sifət sırası: rəy – yaş – material; busier — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10730, 136, 'g11-eng-adj-q1-10', 1, 10, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Your English is getting better and better. It is getting more hard to find a cheap flat in the city.", "B": "Your English is getting gooder and gooder. It is getting harder to find a cheap flat in the city.", "C": "Your English is getting better and better. It is getting hardest to find a cheap flat in the city.", "D": "Your English is getting better and better. It is getting harder to find a cheap flat in the city.", "E": "Your English is getting more and more good. It is getting harder to find a cheap flat in the city."}'::jsonb, 'D', NULL, 'better and better — Artan dəyişiklik: comparative and comparative; harder — hard → harder.');
INSERT INTO public.questions VALUES (10731, 136, 'g11-eng-adj-q1-11', 1, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It is the more modern office in the area. The weather today is much worse than yesterday.", "B": "It is the modernest office in the area. The weather today is much worse than yesterday.", "C": "It is the most modernest office in the area. The weather today is much worse than yesterday.", "D": "It is the most modern office in the area. The weather today is much very worse than yesterday.", "E": "It is the most modern office in the area. The weather today is much worse than yesterday."}'::jsonb, 'E', NULL, 'most modern — Üstünlük dərəcəsi: modern → the most modern; worse — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10732, 136, 'g11-eng-adj-q1-12', 1, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He has a Japanese small black car.", "B": "I found a wooden round dining table at the market.", "C": "This plan is much better than the first one.", "D": "It is the most thin book on the shelf.", "E": "It was the dryest month of the year."}'::jsonb, 'C', NULL, 'Correct: «This plan is much better than the first one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10733, 136, 'g11-eng-adj-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This test is much most difficult than the last one.", "B": "This book is thinner than that one.", "C": "It is the most thin book on the shelf.", "D": "Their office is much most modern than ours.", "E": "It was the difficultest question in the exam."}'::jsonb, 'B', NULL, 'Correct: «This book is thinner than that one.» — Müqayisə dərəcəsi: thin → thinner. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10734, 136, 'g11-eng-adj-q1-14', 1, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It is the thinnest book on the shelf. They live in a stone lovely old house.", "B": "It is the thinnest book on the shelf. They live in a lovely old stone house.", "C": "It is the thinest book on the shelf. They live in a lovely old stone house.", "D": "It is the thinnest book on the shelf. They live in a old lovely stone house.", "E": "It is the most thin book on the shelf. They live in a lovely old stone house."}'::jsonb, 'B', NULL, 'thinnest — Üstünlük dərəcəsi: thin → the thinnest; lovely old stone — Sifət sırası: rəy – yaş – material.');
INSERT INTO public.questions VALUES (10735, 136, 'g11-eng-adj-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Leyla is much ___ (careful) than her brother. (2) Their new flat is much ___ (big) than the old one. (3) They live in a ___ house.', NULL, NULL, '{"A": "very more careful / bigger / lovely old stone", "B": "most careful / bigger / lovely old stone", "C": "more careful / bigger / stone lovely old", "D": "more careful / bigger / lovely old stone", "E": "more careful / very bigger / lovely old stone"}'::jsonb, 'D', NULL, '(1) more careful — much/far + müqayisə dərəcəsi (very işlənmir) (2) bigger — much/far + müqayisə dərəcəsi (very işlənmir) (3) lovely old stone — Sifət sırası: rəy – yaş – material');
INSERT INTO public.questions VALUES (10736, 136, 'g11-eng-adj-q1-16', 1, 16, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their new flat is much ___ (big) than the old one. (2) Their office is much ___ (modern) than ours. (3) My sister looks much ___ (happy) than before.', NULL, NULL, '{"A": "bigger / more modern / more happiest", "B": "bigger / more modern / happier", "C": "more biggest / more modern / happier", "D": "very bigger / more modern / happier", "E": "biggest / more modern / happier"}'::jsonb, 'B', NULL, '(1) bigger — much/far + müqayisə dərəcəsi (very işlənmir) (2) more modern — much/far + müqayisə dərəcəsi (very işlənmir) (3) happier — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10737, 136, 'g11-eng-adj-q1-17', 1, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My sister looks much happiest than before.", "B": "It is the more modern office in the area.", "C": "He has a black small Japanese car.", "D": "This street is busiest than ours.", "E": "This test is much more difficult than the last one."}'::jsonb, 'E', NULL, 'Correct: «This test is much more difficult than the last one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10738, 136, 'g11-eng-adj-q1-18', 1, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They live in a lovely stone old house.", "B": "My sister looks much very happier than before.", "C": "It is the busiest street in the city.", "D": "It is the most modernest office in the area.", "E": "It is the thinner book on the shelf."}'::jsonb, 'C', NULL, 'Correct: «It is the busiest street in the city.» — Üstünlük dərəcəsi: busy → the busiest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10739, 136, 'g11-eng-adj-q1-19', 1, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This street is more busier than ours. This plan is much better than the first one.", "B": "This street is busier than ours. This plan is much very better than the first one.", "C": "This street is busier than ours. This plan is much better than the first one.", "D": "This street is busiest than ours. This plan is much better than the first one.", "E": "This street is busyer than ours. This plan is much better than the first one."}'::jsonb, 'C', NULL, 'busier — Müqayisə dərəcəsi: busy → busier; better — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10740, 136, 'g11-eng-adj-q1-20', 1, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This summer was much ___ (dry) than last summer. (2) This street is ___ (busy) than ours. (3) Their office is much ___ (modern) than ours.', NULL, NULL, '{"A": "drier / busyer / more modern", "B": "more driest / busier / more modern", "C": "very drier / busier / more modern", "D": "drier / busier / more modern", "E": "drier / busier / very more modern"}'::jsonb, 'D', NULL, '(1) drier — much/far + müqayisə dərəcəsi (very işlənmir) (2) busier — Müqayisə dərəcəsi: busy → busier (3) more modern — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10741, 136, 'g11-eng-adj-q1-21', 1, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She bought a beautiful long red silk dress. This book is much more thinnest than that one.", "B": "She bought a beautiful long red silk dress. This book is much very thinner than that one.", "C": "She bought a beautiful long red silk dress. This book is much thinnest than that one.", "D": "She bought a beautiful long red silk dress. This book is much thinner than that one.", "E": "She bought a long beautiful red silk dress. This book is much thinner than that one."}'::jsonb, 'D', NULL, 'beautiful long red silk — Sifət sırası: rəy – ölçü – rəng – material; thinner — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10742, 136, 'g11-eng-adj-q1-22', 1, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) My ___ brother is a pilot. (2) The weather today is much ___ (bad) than yesterday. (3) This book is much ___ (thin) than that one.', NULL, NULL, '{"A": "more old / worse / thinner", "B": "elder / worse / thinner", "C": "older than / worse / thinner", "D": "elder / very worse / thinner", "E": "elder / worse / thinnest"}'::jsonb, 'B', NULL, '(1) elder — elder — ailə üzvləri üçün atributiv (2) worse — much/far + müqayisə dərəcəsi (very işlənmir) (3) thinner — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10743, 136, 'g11-eng-adj-q1-23', 1, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They live in a ___ house. (2) My ___ brother is a pilot. (3) The weather today is much ___ (bad) than yesterday.', NULL, NULL, '{"A": "old lovely stone / elder / worse", "B": "lovely old stone / elder / worse", "C": "lovely old stone / more old / worse", "D": "stone lovely old / elder / worse", "E": "lovely old stone / elder / very worse"}'::jsonb, 'B', NULL, '(1) lovely old stone — Sifət sırası: rəy – yaş – material (2) elder — elder — ailə üzvləri üçün atributiv (3) worse — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10744, 136, 'g11-eng-adj-q1-24', 1, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This street is much ___ (busy) than ours. (2) Their office is ___ (modern) than ours. (3) This book is much ___ (thin) than that one.', NULL, NULL, '{"A": "busier / more modern / thinner", "B": "busier / moderner / thinner", "C": "busier / most modern / thinner", "D": "busier / more moderner / thinner", "E": "busier / more modern / more thinnest"}'::jsonb, 'A', NULL, '(1) busier — much/far + müqayisə dərəcəsi (very işlənmir) (2) more modern — Müqayisə dərəcəsi: modern → more modern (3) thinner — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10745, 136, 'g11-eng-adj-q1-25', 1, 25, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This book is thinner than that one. Their new flat is much bigger than the old one.", "B": "This book is thiner than that one. Their new flat is much bigger than the old one.", "C": "This book is thinnest than that one. Their new flat is much bigger than the old one.", "D": "This book is more thin than that one. Their new flat is much bigger than the old one.", "E": "This book is thinner than that one. Their new flat is much very bigger than the old one."}'::jsonb, 'A', NULL, 'thinner — Müqayisə dərəcəsi: thin → thinner; bigger — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10746, 136, 'g11-eng-adj-q1-26', 1, 26, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This plan is much better than the first one. They live in a lovely old stone house.", "B": "This plan is much better than the first one. They live in a old lovely stone house.", "C": "This plan is much very better than the first one. They live in a lovely old stone house.", "D": "This plan is much better than the first one. They live in a lovely stone old house.", "E": "This plan is much better than the first one. They live in a stone lovely old house."}'::jsonb, 'A', NULL, 'better — much/far + müqayisə dərəcəsi (very işlənmir); lovely old stone — Sifət sırası: rəy – yaş – material.');
INSERT INTO public.questions VALUES (10747, 136, 'g11-eng-adj-q1-27', 1, 27, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This book is thiner than that one.", "B": "This summer was much driest than last summer.", "C": "This test is difficulter than the last one.", "D": "Their office is much more modern than ours.", "E": "It was the drier month of the year."}'::jsonb, 'D', NULL, 'Correct: «Their office is much more modern than ours.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10748, 136, 'g11-eng-adj-q1-28', 1, 28, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The weather today is much worse than yesterday.", "B": "She bought a long beautiful red silk dress.", "C": "This book is much more thinnest than that one.", "D": "Leyla is much most careful than her brother.", "E": "They live in a stone lovely old house."}'::jsonb, 'A', NULL, 'Correct: «The weather today is much worse than yesterday.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10749, 136, 'g11-eng-adj-q1-29', 1, 29, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This street is busyer than ours.", "B": "It is the busiest street in the city.", "C": "This test is much most difficult than the last one.", "D": "It was the drier month of the year.", "E": "This summer was much driest than last summer."}'::jsonb, 'B', NULL, 'Correct: «It is the busiest street in the city.» — Üstünlük dərəcəsi: busy → the busiest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10750, 136, 'g11-eng-adj-q1-30', 1, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (busy) street in the city. (2) This book is ___ (thin) than that one. (3) I found a ___ table at the market.', NULL, NULL, '{"A": "busiest / thinnest / round wooden dining", "B": "busiest / thinner / dining round wooden", "C": "most busier / thinner / round wooden dining", "D": "busiest / thinner / round wooden dining", "E": "busiest / thiner / round wooden dining"}'::jsonb, 'D', NULL, '(1) busiest — Üstünlük dərəcəsi: busy → the busiest (2) thinner — Müqayisə dərəcəsi: thin → thinner (3) round wooden dining — Sifət sırası: forma – material – təyinat');
INSERT INTO public.questions VALUES (10751, 136, 'g11-eng-adj-q2-01', 2, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This summer was drier than last summer.", "B": "This book is thiner than that one.", "C": "I found a wooden round dining table at the market.", "D": "Their new flat is much biggest than the old one.", "E": "Your English is getting more and more good."}'::jsonb, 'A', NULL, 'Correct: «This summer was drier than last summer.» — Müqayisə dərəcəsi: dry → drier. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10752, 136, 'g11-eng-adj-q2-02', 2, 2, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This street is much busiest than ours. We were shocked by the news.", "B": "This street is much busier than ours. We were shockingly by the news.", "C": "This street is much busier than ours. We were shocking by the news.", "D": "This street is much busier than ours. We were shock by the news.", "E": "This street is much busier than ours. We were shocked by the news."}'::jsonb, 'E', NULL, 'busier — much/far + müqayisə dərəcəsi (very işlənmir); shocked — -ed: hiss (be shocked by).');
INSERT INTO public.questions VALUES (10753, 136, 'g11-eng-adj-q2-03', 2, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "We were shocking by the news.", "B": "My sister looks much very happier than before.", "C": "Their office is much most modern than ours.", "D": "It is the busiest street in the city.", "E": "Their new flat is much biggest than the old one."}'::jsonb, 'D', NULL, 'Correct: «It is the busiest street in the city.» — Üstünlük dərəcəsi: busy → the busiest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10754, 136, 'g11-eng-adj-q2-04', 2, 4, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This book is thinner than that one. It is the busier street in the city.", "B": "This book is thiner than that one. It is the busiest street in the city.", "C": "This book is thinner than that one. It is the busyest street in the city.", "D": "This book is thinner than that one. It is the busiest street in the city.", "E": "This book is thinnest than that one. It is the busiest street in the city."}'::jsonb, 'D', NULL, 'thinner — Müqayisə dərəcəsi: thin → thinner; busiest — Üstünlük dərəcəsi: busy → the busiest.');
INSERT INTO public.questions VALUES (10755, 136, 'g11-eng-adj-q2-05', 2, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the driest month of the year.", "B": "My older than brother is a pilot.", "C": "The more you read, the much you know.", "D": "This street is busyer than ours.", "E": "He has a black small Japanese car."}'::jsonb, 'A', NULL, 'Correct: «It was the driest month of the year.» — Üstünlük dərəcəsi: dry → the driest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10756, 136, 'g11-eng-adj-q2-06', 2, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This summer was dryier than last summer.", "B": "Leyla is much very more careful than her brother.", "C": "It is the busiest street in the city.", "D": "This book is thiner than that one.", "E": "This book is much thinnest than that one."}'::jsonb, 'C', NULL, 'Correct: «It is the busiest street in the city.» — Üstünlük dərəcəsi: busy → the busiest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10757, 136, 'g11-eng-adj-q2-07', 2, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It was the difficultest question in the exam.", "B": "This summer was much drier than last summer.", "C": "He has a Japanese small black car.", "D": "They live in a lovely stone old house.", "E": "The more you read, the many you know."}'::jsonb, 'B', NULL, 'Correct: «This summer was much drier than last summer.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10758, 136, 'g11-eng-adj-q2-08', 2, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) We were ___ by the news. (2) It was the ___ (dry) month of the year. (3) It is the ___ (thin) book on the shelf.', NULL, NULL, '{"A": "shocked / driest / thinest", "B": "shockingly / driest / thinnest", "C": "shocked / driest / thinnest", "D": "shocked / drier / thinnest", "E": "shock / driest / thinnest"}'::jsonb, 'C', NULL, '(1) shocked — -ed: hiss (be shocked by) (2) driest — Üstünlük dərəcəsi: dry → the driest (3) thinnest — Üstünlük dərəcəsi: thin → the thinnest');
INSERT INTO public.questions VALUES (10759, 136, 'g11-eng-adj-q2-09', 2, 9, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It is the busyest street in the city. This plan is much better than the first one.", "B": "It is the busiest street in the city. This plan is much better than the first one.", "C": "It is the busiest street in the city. This plan is much very better than the first one.", "D": "It is the busier street in the city. This plan is much better than the first one.", "E": "It is the busiest street in the city. This plan is much more best than the first one."}'::jsonb, 'B', NULL, 'busiest — Üstünlük dərəcəsi: busy → the busiest; better — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10760, 136, 'g11-eng-adj-q2-10', 2, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This test is much very more difficult than the last one.", "B": "He has a small black Japanese car.", "C": "The more you read, the much you know.", "D": "It was the most difficultest question in the exam.", "E": "It is the busyest street in the city."}'::jsonb, 'B', NULL, 'Correct: «He has a small black Japanese car.» — Sifət sırası: ölçü – rəng – mənşə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10761, 136, 'g11-eng-adj-q2-11', 2, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It is the thinner book on the shelf. Their office is much more modern than ours.", "B": "It is the thinnest book on the shelf. Their office is much more modern than ours.", "C": "It is the thinnest book on the shelf. Their office is much most modern than ours.", "D": "It is the most thin book on the shelf. Their office is much more modern than ours.", "E": "It is the thinest book on the shelf. Their office is much more modern than ours."}'::jsonb, 'B', NULL, 'thinnest — Üstünlük dərəcəsi: thin → the thinnest; more modern — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10762, 136, 'g11-eng-adj-q2-12', 2, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This plan is much better than the first one.", "B": "Leyla is much most careful than her brother.", "C": "It is the most busier street in the city.", "D": "She bought a long beautiful red silk dress.", "E": "It is the thinest book on the shelf."}'::jsonb, 'A', NULL, 'Correct: «This plan is much better than the first one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10763, 136, 'g11-eng-adj-q2-13', 2, 13, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Their new flat is much more biggest than the old one. It is the thinnest book on the shelf.", "B": "Their new flat is much bigger than the old one. It is the most thin book on the shelf.", "C": "Their new flat is much bigger than the old one. It is the thinest book on the shelf.", "D": "Their new flat is much bigger than the old one. It is the thinner book on the shelf.", "E": "Their new flat is much bigger than the old one. It is the thinnest book on the shelf."}'::jsonb, 'E', NULL, 'bigger — much/far + müqayisə dərəcəsi (very işlənmir); thinnest — Üstünlük dərəcəsi: thin → the thinnest.');
INSERT INTO public.questions VALUES (10764, 136, 'g11-eng-adj-q2-14', 2, 14, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The more you read, the more you know. It is the thinnest book on the shelf.", "B": "The more you read, the more you know. It is the most thin book on the shelf.", "C": "The more you read, the much you know. It is the thinnest book on the shelf.", "D": "The more you read, the most you know. It is the thinnest book on the shelf.", "E": "The more you read, the more you know. It is the thinest book on the shelf."}'::jsonb, 'A', NULL, 'more — the + comparative ..., the + comparative; thinnest — Üstünlük dərəcəsi: thin → the thinnest.');
INSERT INTO public.questions VALUES (10765, 136, 'g11-eng-adj-q2-15', 2, 15, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This test is difficulter than the last one. My elder brother is a pilot.", "B": "This test is most difficult than the last one. My elder brother is a pilot.", "C": "This test is more difficult than the last one. My elder brother is a pilot.", "D": "This test is more difficult than the last one. My older than brother is a pilot.", "E": "This test is more difficult than the last one. My eldest than brother is a pilot."}'::jsonb, 'C', NULL, 'more difficult — Müqayisə dərəcəsi: difficult → more difficult; elder — elder — ailə üzvləri üçün atributiv.');
INSERT INTO public.questions VALUES (10766, 136, 'g11-eng-adj-q2-16', 2, 16, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The weather today is much worst than yesterday. For further information, please contact our office.", "B": "The weather today is much worse than yesterday. For furthest information, please contact our office.", "C": "The weather today is much worse than yesterday. For further information, please contact our office.", "D": "The weather today is much worse than yesterday. For farer information, please contact our office.", "E": "The weather today is much more worst than yesterday. For further information, please contact our office."}'::jsonb, 'C', NULL, 'worse — much/far + müqayisə dərəcəsi (very işlənmir); further — further = əlavə (məlumat).');
INSERT INTO public.questions VALUES (10767, 136, 'g11-eng-adj-q2-17', 2, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (busy) street in the city. (2) My ___ brother is a pilot. (3) I found a ___ table at the market.', NULL, NULL, '{"A": "busyest / elder / round wooden dining", "B": "most busier / elder / round wooden dining", "C": "busiest / elder / round wooden dining", "D": "busiest / eldest than / round wooden dining", "E": "busiest / elder / dining round wooden"}'::jsonb, 'C', NULL, '(1) busiest — Üstünlük dərəcəsi: busy → the busiest (2) elder — elder — ailə üzvləri üçün atributiv (3) round wooden dining — Sifət sırası: forma – material – təyinat');
INSERT INTO public.questions VALUES (10768, 136, 'g11-eng-adj-q2-18', 2, 18, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My sister looks much more happiest than before.", "B": "This test is difficulter than the last one.", "C": "It is the thinner book on the shelf.", "D": "He has a black small Japanese car.", "E": "It was the driest month of the year."}'::jsonb, 'E', NULL, 'Correct: «It was the driest month of the year.» — Üstünlük dərəcəsi: dry → the driest. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10769, 136, 'g11-eng-adj-q2-19', 2, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is getting ___ to find a cheap flat in the city. (2) For ___ information, please contact our office. (3) This book is much ___ (thin) than that one.', NULL, NULL, '{"A": "harder / further / more thinnest", "B": "harder / further / thinner", "C": "harder / furthest / thinner", "D": "harder / further / thinnest", "E": "most hard / further / thinner"}'::jsonb, 'B', NULL, '(1) harder — hard → harder (2) further — further = əlavə (məlumat) (3) thinner — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10770, 136, 'g11-eng-adj-q2-20', 2, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their office is ___ (modern) than ours. (2) It is the ___ (modern) office in the area. (3) It was the ___ (difficult) question in the exam.', NULL, NULL, '{"A": "more modern / most modern / most difficultest", "B": "more modern / most modern / most difficult", "C": "more moderner / most modern / most difficult", "D": "more modern / most modern / more difficult", "E": "more modern / most modern / difficultest"}'::jsonb, 'B', NULL, '(1) more modern — Müqayisə dərəcəsi: modern → more modern (2) most modern — Üstünlük dərəcəsi: modern → the most modern (3) most difficult — Üstünlük dərəcəsi: difficult → the most difficult');
INSERT INTO public.questions VALUES (10771, 136, 'g11-eng-adj-q2-21', 2, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "They live in a lovely stone old house. Your English is getting better and better.", "B": "They live in a lovely old stone house. Your English is getting more and more good.", "C": "They live in a lovely old stone house. Your English is getting better and better.", "D": "They live in a stone lovely old house. Your English is getting better and better.", "E": "They live in a old lovely stone house. Your English is getting better and better."}'::jsonb, 'C', NULL, 'lovely old stone — Sifət sırası: rəy – yaş – material; better and better — Artan dəyişiklik: comparative and comparative.');
INSERT INTO public.questions VALUES (10772, 136, 'g11-eng-adj-q2-22', 2, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "It is getting harder to find a cheap flat in the city.", "B": "My older than brother is a pilot.", "C": "This summer was more drier than last summer.", "D": "My sister looks much more happiest than before.", "E": "It is the busyest street in the city."}'::jsonb, 'A', NULL, 'Correct: «It is getting harder to find a cheap flat in the city.» — hard → harder. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10773, 136, 'g11-eng-adj-q2-23', 2, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This book is ___ (thin) than that one. (2) Leyla is much ___ (careful) than her brother. (3) This plan is much ___ (good) than the first one.', NULL, NULL, '{"A": "thinner / more carefuler / better", "B": "thiner / more careful / better", "C": "thinner / more careful / better", "D": "thinnest / more careful / better", "E": "thinner / most careful / better"}'::jsonb, 'C', NULL, '(1) thinner — Müqayisə dərəcəsi: thin → thinner (2) more careful — much/far + müqayisə dərəcəsi (very işlənmir) (3) better — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10774, 136, 'g11-eng-adj-q2-24', 2, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (thin) book on the shelf. (2) It is getting ___ to find a cheap flat in the city. (3) Your English is getting ___.', NULL, NULL, '{"A": "thinnest / harder / more and more good", "B": "most thin / harder / better and better", "C": "thinnest / harder / better and better", "D": "thinnest / most hard / better and better", "E": "thinest / harder / better and better"}'::jsonb, 'C', NULL, '(1) thinnest — Üstünlük dərəcəsi: thin → the thinnest (2) harder — hard → harder (3) better and better — Artan dəyişiklik: comparative and comparative');
INSERT INTO public.questions VALUES (10775, 136, 'g11-eng-adj-q2-25', 2, 25, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Leyla is much more careful than her brother. They live in a stone lovely old house.", "B": "Leyla is much more careful than her brother. They live in a old lovely stone house.", "C": "Leyla is much most careful than her brother. They live in a lovely old stone house.", "D": "Leyla is much more careful than her brother. They live in a lovely old stone house.", "E": "Leyla is much more carefuler than her brother. They live in a lovely old stone house."}'::jsonb, 'D', NULL, 'more careful — much/far + müqayisə dərəcəsi (very işlənmir); lovely old stone — Sifət sırası: rəy – yaş – material.');
INSERT INTO public.questions VALUES (10776, 136, 'g11-eng-adj-q2-26', 2, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She bought a ___ dress. (2) He has a ___ car. (3) My sister looks much ___ (happy) than before.', NULL, NULL, '{"A": "beautiful long red silk / small black Japanese / happier", "B": "beautiful long red silk / small black Japanese / more happiest", "C": "beautiful long red silk / small black Japanese / happiest", "D": "beautiful silk long red / small black Japanese / happier", "E": "beautiful long red silk / Japanese small black / happier"}'::jsonb, 'A', NULL, '(1) beautiful long red silk — Sifət sırası: rəy – ölçü – rəng – material (2) small black Japanese — Sifət sırası: ölçü – rəng – mənşə (3) happier — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10777, 136, 'g11-eng-adj-q2-27', 2, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This summer was ___ (dry) than last summer. (2) This book is ___ (thin) than that one. (3) This test is ___ (difficult) than the last one.', NULL, NULL, '{"A": "driest / thinner / more difficult", "B": "drier / more thin / more difficult", "C": "drier / thinner / most difficult", "D": "drier / thinner / more difficult", "E": "drier / thiner / more difficult"}'::jsonb, 'D', NULL, '(1) drier — Müqayisə dərəcəsi: dry → drier (2) thinner — Müqayisə dərəcəsi: thin → thinner (3) more difficult — Müqayisə dərəcəsi: difficult → more difficult');
INSERT INTO public.questions VALUES (10778, 136, 'g11-eng-adj-q2-28', 2, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This book is ___ (thin) than that one. (2) It is the ___ (modern) office in the area. (3) It was the ___ (difficult) question in the exam.', NULL, NULL, '{"A": "more thin / most modern / most difficult", "B": "thinner / most modernest / most difficult", "C": "thinner / most modern / most difficult", "D": "thinner / most modern / more difficult", "E": "thinner / modernest / most difficult"}'::jsonb, 'C', NULL, '(1) thinner — Müqayisə dərəcəsi: thin → thinner (2) most modern — Üstünlük dərəcəsi: modern → the most modern (3) most difficult — Üstünlük dərəcəsi: difficult → the most difficult');
INSERT INTO public.questions VALUES (10779, 136, 'g11-eng-adj-q2-29', 2, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (busy) street in the city. (2) Your English is getting ___. (3) Leyla is much ___ (careful) than her brother.', NULL, NULL, '{"A": "busiest / better and better / most careful", "B": "busiest / more and more good / more careful", "C": "busiest / best and best / more careful", "D": "busiest / better and better / more careful", "E": "busiest / better and better / more carefuler"}'::jsonb, 'D', NULL, '(1) busiest — Üstünlük dərəcəsi: busy → the busiest (2) better and better — Artan dəyişiklik: comparative and comparative (3) more careful — much/far + müqayisə dərəcəsi (very işlənmir)');
INSERT INTO public.questions VALUES (10780, 136, 'g11-eng-adj-q2-30', 2, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This street is much busiest than ours.", "B": "We were shock by the news.", "C": "The more you read, the most you know.", "D": "Leyla is much more carefuler than her brother.", "E": "Their new flat is much bigger than the old one."}'::jsonb, 'E', NULL, 'Correct: «Their new flat is much bigger than the old one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10781, 136, 'g11-eng-adj-q3-01', 3, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "They live in a lovely stone old house.", "B": "It was the difficultest question in the exam.", "C": "This test is much more difficult than the last one.", "D": "I found a round dining wooden table at the market.", "E": "Their office is much most modern than ours."}'::jsonb, 'C', NULL, 'Correct: «This test is much more difficult than the last one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10782, 136, 'g11-eng-adj-q3-02', 3, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Leyla is much most careful than her brother.", "B": "It is the thinner book on the shelf.", "C": "This book is much thinner than that one.", "D": "It is the busier street in the city.", "E": "This summer was much driest than last summer."}'::jsonb, 'C', NULL, 'Correct: «This book is much thinner than that one.» — much/far + müqayisə dərəcəsi (very işlənmir). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10783, 136, 'g11-eng-adj-q3-03', 3, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) My sister looks much ___ (happy) than before. (2) This plan is much ___ (good) than the first one. (3) She bought a ___ dress.', NULL, NULL, '{"A": "happier / better / beautiful long red silk", "B": "very happier / better / beautiful long red silk", "C": "happier / very better / beautiful long red silk", "D": "more happiest / better / beautiful long red silk", "E": "happier / better / red beautiful long silk"}'::jsonb, 'A', NULL, '(1) happier — much/far + müqayisə dərəcəsi (very işlənmir) (2) better — much/far + müqayisə dərəcəsi (very işlənmir) (3) beautiful long red silk — Sifət sırası: rəy – ölçü – rəng – material');
INSERT INTO public.questions VALUES (10784, 136, 'g11-eng-adj-q3-04', 3, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It was the ___ (difficult) question in the exam. (2) Your English is getting ___. (3) For ___ information, please contact our office.', NULL, NULL, '{"A": "most difficult / better and better / furthest", "B": "most difficult / best and best / further", "C": "most difficult / better and better / further", "D": "most difficult / gooder and gooder / further", "E": "most difficultest / better and better / further"}'::jsonb, 'C', NULL, '(1) most difficult — Üstünlük dərəcəsi: difficult → the most difficult (2) better and better — Artan dəyişiklik: comparative and comparative (3) further — further = əlavə (məlumat)');
INSERT INTO public.questions VALUES (10785, 136, 'g11-eng-adj-q3-05', 3, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The weather today is much very worse than yesterday.", "B": "This summer was much very drier than last summer.", "C": "It is the modernest office in the area.", "D": "Your English is getting best and best.", "E": "Their office is more modern than ours."}'::jsonb, 'E', NULL, 'Correct: «Their office is more modern than ours.» — Müqayisə dərəcəsi: modern → more modern. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10786, 136, 'g11-eng-adj-q3-06', 3, 6, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This book is much thinner than that one. This summer was drier than last summer.", "B": "This book is much more thinnest than that one. This summer was drier than last summer.", "C": "This book is much thinner than that one. This summer was dryier than last summer.", "D": "This book is much thinner than that one. This summer was driest than last summer.", "E": "This book is much thinner than that one. This summer was more drier than last summer."}'::jsonb, 'A', NULL, 'thinner — much/far + müqayisə dərəcəsi (very işlənmir); drier — Müqayisə dərəcəsi: dry → drier.');
INSERT INTO public.questions VALUES (10787, 136, 'g11-eng-adj-q3-07', 3, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their new flat is much ___ (big) than the old one. (2) This summer was much ___ (dry) than last summer. (3) My ___ brother is a pilot.', NULL, NULL, '{"A": "bigger / driest / elder", "B": "more biggest / drier / elder", "C": "biggest / drier / elder", "D": "bigger / drier / elder", "E": "bigger / drier / eldest than"}'::jsonb, 'D', NULL, '(1) bigger — much/far + müqayisə dərəcəsi (very işlənmir) (2) drier — much/far + müqayisə dərəcəsi (very işlənmir) (3) elder — elder — ailə üzvləri üçün atributiv');
INSERT INTO public.questions VALUES (10788, 136, 'g11-eng-adj-q3-08', 3, 8, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "My eldest than brother is a pilot. He has a small black Japanese car.", "B": "My older than brother is a pilot. He has a small black Japanese car.", "C": "My more old brother is a pilot. He has a small black Japanese car.", "D": "My elder brother is a pilot. He has a small black Japanese car.", "E": "My elder brother is a pilot. He has a Japanese small black car."}'::jsonb, 'D', NULL, 'elder — elder — ailə üzvləri üçün atributiv; small black Japanese — Sifət sırası: ölçü – rəng – mənşə.');
INSERT INTO public.questions VALUES (10789, 136, 'g11-eng-adj-q3-09', 3, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "My elder brother is a pilot.", "B": "This test is much more difficulter than the last one.", "C": "They live in a lovely stone old house.", "D": "This test is difficulter than the last one.", "E": "It is the most thin book on the shelf."}'::jsonb, 'A', NULL, 'Correct: «My elder brother is a pilot.» — elder — ailə üzvləri üçün atributiv. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10790, 136, 'g11-eng-adj-q3-10', 3, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I found a round wooden dining table at the market.", "B": "It is the more modern office in the area.", "C": "This test is much more difficulter than the last one.", "D": "It is the thinner book on the shelf.", "E": "She bought a long beautiful red silk dress."}'::jsonb, 'A', NULL, 'Correct: «I found a round wooden dining table at the market.» — Sifət sırası: forma – material – təyinat. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10791, 136, 'g11-eng-adj-q3-11', 3, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He has a small black Japanese car. This test is much very more difficult than the last one.", "B": "He has a small black Japanese car. This test is much most difficult than the last one.", "C": "He has a Japanese small black car. This test is much more difficult than the last one.", "D": "He has a small black Japanese car. This test is much more difficult than the last one.", "E": "He has a small Japanese black car. This test is much more difficult than the last one."}'::jsonb, 'D', NULL, 'small black Japanese — Sifət sırası: ölçü – rəng – mənşə; more difficult — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10792, 136, 'g11-eng-adj-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Their office is much ___ (modern) than ours. (2) Leyla is much ___ (careful) than her brother. (3) It is the ___ (thin) book on the shelf.', NULL, NULL, '{"A": "more modern / more carefuler / thinnest", "B": "more modern / more careful / thinner", "C": "more modern / most careful / thinnest", "D": "more modern / more careful / thinnest", "E": "most modern / more careful / thinnest"}'::jsonb, 'D', NULL, '(1) more modern — much/far + müqayisə dərəcəsi (very işlənmir) (2) more careful — much/far + müqayisə dərəcəsi (very işlənmir) (3) thinnest — Üstünlük dərəcəsi: thin → the thinnest');
INSERT INTO public.questions VALUES (10793, 136, 'g11-eng-adj-q3-13', 3, 13, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The more you read, the much you know. My sister looks much happier than before.", "B": "The more you read, the most you know. My sister looks much happier than before.", "C": "The more you read, the more you know. My sister looks much happier than before.", "D": "The more you read, the more you know. My sister looks much more happiest than before.", "E": "The more you read, the more you know. My sister looks much very happier than before."}'::jsonb, 'C', NULL, 'more — the + comparative ..., the + comparative; happier — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10794, 136, 'g11-eng-adj-q3-14', 3, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This street is much ___ (busy) than ours. (2) The more you read, the ___ you know. (3) It is the ___ (modern) office in the area.', NULL, NULL, '{"A": "busier / most / most modern", "B": "busier / more / more modern", "C": "busier / more / most modern", "D": "very busier / more / most modern", "E": "busier / many / most modern"}'::jsonb, 'C', NULL, '(1) busier — much/far + müqayisə dərəcəsi (very işlənmir) (2) more — the + comparative ..., the + comparative (3) most modern — Üstünlük dərəcəsi: modern → the most modern');
INSERT INTO public.questions VALUES (10795, 136, 'g11-eng-adj-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) For ___ information, please contact our office. (2) I found a ___ table at the market. (3) She bought a ___ dress.', NULL, NULL, '{"A": "further / round wooden dining / beautiful long red silk", "B": "further / round wooden dining / red beautiful long silk", "C": "further / dining round wooden / beautiful long red silk", "D": "further / round dining wooden / beautiful long red silk", "E": "further / round wooden dining / long beautiful red silk"}'::jsonb, 'A', NULL, '(1) further — further = əlavə (məlumat) (2) round wooden dining — Sifət sırası: forma – material – təyinat (3) beautiful long red silk — Sifət sırası: rəy – ölçü – rəng – material');
