INSERT INTO public.questions VALUES (10797, 136, 'g11-eng-adj-q3-17', 3, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He has a small Japanese black car.", "B": "Their new flat is much very bigger than the old one.", "C": "This book is more thin than that one.", "D": "It was the most difficult question in the exam.", "E": "My sister looks much happiest than before."}'::jsonb, 'D', NULL, 'Correct: «It was the most difficult question in the exam.» — Üstünlük dərəcəsi: difficult → the most difficult. The other sentences each contain an error.');
