INSERT INTO public.questions VALUES (10800, 136, 'g11-eng-adj-q3-20', 3, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Their new flat is much bigger than the old one. It is the busier street in the city.", "B": "Their new flat is much biggest than the old one. It is the busiest street in the city.", "C": "Their new flat is much bigger than the old one. It is the most busier street in the city.", "D": "Their new flat is much more biggest than the old one. It is the busiest street in the city.", "E": "Their new flat is much bigger than the old one. It is the busiest street in the city."}'::jsonb, 'E', NULL, 'bigger — much/far + müqayisə dərəcəsi (very işlənmir); busiest — Üstünlük dərəcəsi: busy → the busiest.');
INSERT INTO public.questions VALUES (10801, 136, 'g11-eng-adj-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Leyla is much ___ (careful) than her brother. (2) My ___ brother is a pilot. (3) We were ___ by the news.', NULL, NULL, '{"A": "very more careful / elder / shocked", "B": "more careful / eldest than / shocked", "C": "more careful / more old / shocked", "D": "more careful / elder / shocked", "E": "more careful / elder / shocking"}'::jsonb, 'D', NULL, '(1) more careful — much/far + müqayisə dərəcəsi (very işlənmir) (2) elder — elder — ailə üzvləri üçün atributiv (3) shocked — -ed: hiss (be shocked by)');
