INSERT INTO public.questions VALUES (10803, 136, 'g11-eng-adj-q3-23', 3, 23, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "For farer information, please contact our office. This street is much busier than ours.", "B": "For furthest information, please contact our office. This street is much busier than ours.", "C": "For further information, please contact our office. This street is much busier than ours.", "D": "For farther information, please contact our office. This street is much busier than ours.", "E": "For further information, please contact our office. This street is much very busier than ours."}'::jsonb, 'C', NULL, 'further — further = əlavə (məlumat); busier — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10804, 136, 'g11-eng-adj-q3-24', 3, 24, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This test is much most difficult than the last one. Their office is more modern than ours.", "B": "This test is much more difficult than the last one. Their office is more modern than ours.", "C": "This test is much more difficult than the last one. Their office is most modern than ours.", "D": "This test is much more difficult than the last one. Their office is moderner than ours.", "E": "This test is much more difficulter than the last one. Their office is more modern than ours."}'::jsonb, 'B', NULL, 'more difficult — much/far + müqayisə dərəcəsi (very işlənmir); more modern — Müqayisə dərəcəsi: modern → more modern.');
INSERT INTO public.questions VALUES (10805, 136, 'g11-eng-adj-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This summer was ___ (dry) than last summer. (2) It is the ___ (modern) office in the area. (3) He has a ___ car.', NULL, NULL, '{"A": "drier / most modernest / small black Japanese", "B": "drier / most modern / black small Japanese", "C": "drier / most modern / small Japanese black", "D": "drier / most modern / small black Japanese", "E": "drier / modernest / small black Japanese"}'::jsonb, 'D', NULL, '(1) drier — Müqayisə dərəcəsi: dry → drier (2) most modern — Üstünlük dərəcəsi: modern → the most modern (3) small black Japanese — Sifət sırası: ölçü – rəng – mənşə');
