INSERT INTO public.questions VALUES (10807, 136, 'g11-eng-adj-q3-27', 3, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It is the ___ (modern) office in the area. (2) It is getting ___ to find a cheap flat in the city. (3) They live in a ___ house.', NULL, NULL, '{"A": "most modern / harder / lovely stone old", "B": "more modern / harder / lovely old stone", "C": "most modern / harder / lovely old stone", "D": "most modernest / harder / lovely old stone", "E": "most modern / more hard / lovely old stone"}'::jsonb, 'C', NULL, '(1) most modern — Üstünlük dərəcəsi: modern → the most modern (2) harder — hard → harder (3) lovely old stone — Sifət sırası: rəy – yaş – material');
INSERT INTO public.questions VALUES (10808, 136, 'g11-eng-adj-q3-28', 3, 28, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It was the most difficult question in the exam. Their office is much most modern than ours.", "B": "It was the most difficult question in the exam. Their office is much more moderner than ours.", "C": "It was the most difficultest question in the exam. Their office is much more modern than ours.", "D": "It was the most difficult question in the exam. Their office is much very more modern than ours.", "E": "It was the most difficult question in the exam. Their office is much more modern than ours."}'::jsonb, 'E', NULL, 'most difficult — Üstünlük dərəcəsi: difficult → the most difficult; more modern — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10809, 136, 'g11-eng-adj-q3-29', 3, 29, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "My older than brother is a pilot. This plan is much better than the first one.", "B": "My more old brother is a pilot. This plan is much better than the first one.", "C": "My elder brother is a pilot. This plan is much very better than the first one.", "D": "My elder brother is a pilot. This plan is much more best than the first one.", "E": "My elder brother is a pilot. This plan is much better than the first one."}'::jsonb, 'E', NULL, 'elder — elder — ailə üzvləri üçün atributiv; better — much/far + müqayisə dərəcəsi (very işlənmir).');
INSERT INTO public.questions VALUES (10810, 136, 'g11-eng-adj-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She bought a beautiful long red silk dress.", "B": "They live in a old lovely stone house.", "C": "This street is much busiest than ours.", "D": "We were shockingly by the news.", "E": "It was the most driest month of the year."}'::jsonb, 'A', NULL, 'Correct: «She bought a beautiful long red silk dress.» — Sifət sırası: rəy – ölçü – rəng – material. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10811, 137, 'g11-eng-pron-q1-01', 1, 1, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I don''t like these shoes. Can I see the black ___? (2) Between you and ___, I don''t trust him. (3) The two friends looked at ___ and smiled.', NULL, NULL, '{"A": "ones / me / each other", "B": "ones / me / itself", "C": "ones / mine / each other", "D": "ones / I / each other", "E": "ones / me / each others"}'::jsonb, 'A', NULL, '(1) ones — Cəm isim əvəzinə ones (2) me — Önlükdən sonra obyekt forması: me (3) each other — Qarşılıqlı: each other');
INSERT INTO public.questions VALUES (10812, 137, 'g11-eng-pron-q1-02', 1, 2, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We did the project by ourself. A friend of mine is coming to visit.", "B": "We did the project by ourselves. A friend of mine is coming to visit.", "C": "We did the project by ourselves. A friend of I is coming to visit.", "D": "We did the project by ourselves. A friend of my is coming to visit.", "E": "We did the project by ours. A friend of mine is coming to visit."}'::jsonb, 'B', NULL, 'ourselves — by ourselves — öz-özümüzə; mine — a friend of mine — müstəqil forma.');
INSERT INTO public.questions VALUES (10813, 137, 'g11-eng-pron-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) We did the project by ___. (2) The company changed ___ logo last year. (3) I don''t like these shoes. Can I see the black ___?', NULL, NULL, '{"A": "ourselves / its / ones", "B": "ourselves / their''s / ones", "C": "ourselves / its / them", "D": "ourselves / it''s / ones", "E": "we / its / ones"}'::jsonb, 'A', NULL, '(1) ourselves — by ourselves — öz-özümüzə (2) its — its — yiyəlik; it''s = it is (3) ones — Cəm isim əvəzinə ones');
INSERT INTO public.questions VALUES (10814, 137, 'g11-eng-pron-q1-04', 1, 4, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "They blamed themselves for the mistake. Between you and me, I don''t trust him.", "B": "They blamed their for the mistake. Between you and me, I don''t trust him.", "C": "They blamed theirselves for the mistake. Between you and me, I don''t trust him.", "D": "They blamed themselves for the mistake. Between you and I, I don''t trust him.", "E": "They blamed themself for the mistake. Between you and me, I don''t trust him."}'::jsonb, 'A', NULL, 'themselves — Qayıdış: they → themselves; me — Önlükdən sonra obyekt forması: me.');
INSERT INTO public.questions VALUES (10815, 137, 'g11-eng-pron-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Between you and ___, I don''t trust him. (2) She bought a laptop, ___ was very expensive. (3) The company changed ___ logo last year.', NULL, NULL, '{"A": "me / what / its", "B": "I / which / its", "C": "me / which / it''s", "D": "me / which / its", "E": "me / which / their''s"}'::jsonb, 'D', NULL, '(1) me — Önlükdən sonra obyekt forması: me (2) which — Ayırıcı nisbi cümlədə that işlənmir → which (3) its — its — yiyəlik; it''s = it is');
INSERT INTO public.questions VALUES (10816, 137, 'g11-eng-pron-q1-06', 1, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Whose did you give the keys to?", "B": "They blamed themselves for the mistake.", "C": "The company changed it logo last year.", "D": "She bought a laptop, what was very expensive.", "E": "Nothing of them knew the answer, so the teacher explained it again."}'::jsonb, 'B', NULL, 'Correct: «They blamed themselves for the mistake.» — Qayıdış: they → themselves. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10817, 137, 'g11-eng-pron-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Everybody has done ___ homework. (2) She bought a laptop, ___ was very expensive. (3) ___ did you give the keys to?', NULL, NULL, '{"A": "their / which / Who", "B": "there / which / Who", "C": "their / who / Who", "D": "their / which / How", "E": "their / that / Who"}'::jsonb, 'A', NULL, '(1) their — everybody ilə their (cinsdən asılı olmayan forma) (2) which — Ayırıcı nisbi cümlədə that işlənmir → which (3) Who — Sual: Who … to?');
INSERT INTO public.questions VALUES (10818, 137, 'g11-eng-pron-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Neither of the girls brought their own''s book.", "B": "The two friends looked at itself and smiled.", "C": "The company changed it''s logo last year.", "D": "I don''t like these shoes. Can I see the black them?", "E": "The woman whose car was stolen called the police."}'::jsonb, 'E', NULL, 'Correct: «The woman whose car was stolen called the police.» — whose — yiyəlik bildirən nisbi əvəzlik. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10819, 137, 'g11-eng-pron-q1-09', 1, 9, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The man what I spoke to was very helpful.", "B": "The woman who car was stolen called the police.", "C": "A friend of mine is coming to visit.", "D": "She bought a laptop, that was very expensive.", "E": "We did the project by ourself."}'::jsonb, 'C', NULL, 'Correct: «A friend of mine is coming to visit.» — a friend of mine — müstəqil forma. The other sentences each contain an error.');
