INSERT INTO public.questions VALUES (10821, 137, 'g11-eng-pron-q1-11', 1, 11, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I don''t like these shoes. Can I see the black ones? A friend of mine is coming to visit.", "B": "I don''t like these shoes. Can I see the black it? A friend of mine is coming to visit.", "C": "I don''t like these shoes. Can I see the black them? A friend of mine is coming to visit.", "D": "I don''t like these shoes. Can I see the black ones? A friend of my is coming to visit.", "E": "I don''t like these shoes. Can I see the black ones? A friend of I is coming to visit."}'::jsonb, 'A', NULL, 'ones — Cəm isim əvəzinə ones; mine — a friend of mine — müstəqil forma.');
INSERT INTO public.questions VALUES (10822, 137, 'g11-eng-pron-q1-12', 1, 12, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Neither of the girls brought herself book.", "B": "Nothing of them knew the answer, so the teacher explained it again.", "C": "The woman whom car was stolen called the police.", "D": "What you need is a good night''s sleep.", "E": "I have two brothers, both of which are engineers."}'::jsonb, 'D', NULL, 'Correct: «What you need is a good night''s sleep.» — What = the thing that. The other sentences each contain an error.');
