INSERT INTO public.questions VALUES (10824, 137, 'g11-eng-pron-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "That you need is a good night''s sleep.", "B": "Between you and me, I don''t trust him.", "C": "A friend of my is coming to visit.", "D": "What''s did you give the keys to?", "E": "I don''t like these shoes. Can I see the black it?"}'::jsonb, 'B', NULL, 'Correct: «Between you and me, I don''t trust him.» — Önlükdən sonra obyekt forması: me. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10825, 137, 'g11-eng-pron-q1-15', 1, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The woman ___ car was stolen called the police. (2) We did the project by ___. (3) The two friends looked at ___ and smiled.', NULL, NULL, '{"A": "who / ourselves / each other", "B": "whose / ourselves / each other", "C": "whose / ourselves / each others", "D": "whose / ourselves / theirselves", "E": "whose / ours / each other"}'::jsonb, 'B', NULL, '(1) whose — whose — yiyəlik bildirən nisbi əvəzlik (2) ourselves — by ourselves — öz-özümüzə (3) each other — Qarşılıqlı: each other');
INSERT INTO public.questions VALUES (10826, 137, 'g11-eng-pron-q1-16', 1, 16, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This is the place where we first met. Who you need is a good night''s sleep.", "B": "This is the place where we first met. That you need is a good night''s sleep.", "C": "This is the place who we first met. What you need is a good night''s sleep.", "D": "This is the place whose we first met. What you need is a good night''s sleep.", "E": "This is the place where we first met. What you need is a good night''s sleep."}'::jsonb, 'E', NULL, 'where — Yer bildirən nisbi zərf: where; What — What = the thing that.');
