INSERT INTO public.questions VALUES (10828, 137, 'g11-eng-pron-q1-18', 1, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This is the place ___ we first met. (2) A friend of ___ is coming to visit. (3) I don''t like these shoes. Can I see the black ___?', NULL, NULL, '{"A": "where / I / ones", "B": "where / mine / ones", "C": "where / mine / them", "D": "where / my / ones", "E": "where / me / ones"}'::jsonb, 'B', NULL, '(1) where — Yer bildirən nisbi zərf: where (2) mine — a friend of mine — müstəqil forma (3) ones — Cəm isim əvəzinə ones');
INSERT INTO public.questions VALUES (10829, 137, 'g11-eng-pron-q1-19', 1, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ you need is a good night''s sleep. (2) A friend of ___ is coming to visit. (3) They blamed ___ for the mistake.', NULL, NULL, '{"A": "What / mine / themself", "B": "What / mine / theirselves", "C": "What / I / themselves", "D": "What / mine / themselves", "E": "Who / mine / themselves"}'::jsonb, 'D', NULL, '(1) What — What = the thing that (2) mine — a friend of mine — müstəqil forma (3) themselves — Qayıdış: they → themselves');
INSERT INTO public.questions VALUES (10830, 137, 'g11-eng-pron-q1-20', 1, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The man ___ I spoke to was very helpful. (2) This is the place ___ we first met. (3) Everybody has done ___ homework.', NULL, NULL, '{"A": "whom / who / their", "B": "whose / where / their", "C": "whom / which / their", "D": "what / where / their", "E": "whom / where / their"}'::jsonb, 'E', NULL, '(1) whom — whom — obyekt kimi şəxs (formal) (2) where — Yer bildirən nisbi zərf: where (3) their — everybody ilə their (cinsdən asılı olmayan forma)');
INSERT INTO public.questions VALUES (10831, 137, 'g11-eng-pron-q1-21', 1, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A friend of I is coming to visit.", "B": "The woman whose car was stolen called the police.", "C": "This is the place which we first met.", "D": "I don''t like these shoes. Can I see the black them?", "E": "Whose did you give the keys to?"}'::jsonb, 'B', NULL, 'Correct: «The woman whose car was stolen called the police.» — whose — yiyəlik bildirən nisbi əvəzlik. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10832, 137, 'g11-eng-pron-q1-22', 1, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "What you need is a good night''s sleep.", "B": "The company changed it''s logo last year.", "C": "We did the project by ours.", "D": "A friend of my is coming to visit.", "E": "Everybody has done theirs homework."}'::jsonb, 'A', NULL, 'Correct: «What you need is a good night''s sleep.» — What = the thing that. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10833, 137, 'g11-eng-pron-q1-23', 1, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The woman ___ car was stolen called the police. (2) Neither of the girls brought ___ book. (3) The company changed ___ logo last year.', NULL, NULL, '{"A": "whose / herself / its", "B": "whose / her / its", "C": "whose / their own''s / its", "D": "whose / her / their''s", "E": "whose / hers / its"}'::jsonb, 'B', NULL, '(1) whose — whose — yiyəlik bildirən nisbi əvəzlik (2) her — neither (tək) + her (3) its — its — yiyəlik; it''s = it is');
