INSERT INTO public.questions VALUES (10843, 137, 'g11-eng-pron-q2-03', 2, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) A friend of ___ is coming to visit. (2) ___ of them knew the answer, so the teacher explained it again. (3) Neither of the girls brought ___ book.', NULL, NULL, '{"A": "I / None / her", "B": "mine / None / hers", "C": "mine / None / her", "D": "mine / Nothing / her", "E": "mine / No / her"}'::jsonb, 'C', NULL, '(1) mine — a friend of mine — müstəqil forma (2) None — none of them — heç biri (3) her — neither (tək) + her');
