INSERT INTO public.questions VALUES (10885, 137, 'g11-eng-pron-q3-15', 3, 15, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She bought a laptop, what was very expensive.", "B": "I have two brothers, both of who are engineers.", "C": "What''s did you give the keys to?", "D": "I don''t like these shoes. Can I see the black ones?", "E": "This is the place whose we first met."}'::jsonb, 'D', NULL, 'Correct: «I don''t like these shoes. Can I see the black ones?» — Cəm isim əvəzinə ones. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10886, 137, 'g11-eng-pron-q3-16', 3, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I have two brothers, both of them are engineers.", "B": "I don''t like these shoes. Can I see the black ones?", "C": "A friend of I is coming to visit.", "D": "Nothing of them knew the answer, so the teacher explained it again.", "E": "She bought a laptop, that was very expensive."}'::jsonb, 'B', NULL, 'Correct: «I don''t like these shoes. Can I see the black ones?» — Cəm isim əvəzinə ones. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10887, 137, 'g11-eng-pron-q3-17', 3, 17, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They blamed ___ for the mistake. (2) The company changed ___ logo last year. (3) I don''t like these shoes. Can I see the black ___?', NULL, NULL, '{"A": "themself / its / ones", "B": "theirselves / its / ones", "C": "themselves / its / ones", "D": "themselves / it / ones", "E": "themselves / their''s / ones"}'::jsonb, 'C', NULL, '(1) themselves — Qayıdış: they → themselves (2) its — its — yiyəlik; it''s = it is (3) ones — Cəm isim əvəzinə ones');
INSERT INTO public.questions VALUES (10888, 137, 'g11-eng-pron-q3-18', 3, 18, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "What you need is a good night''s sleep. This is the place which we first met.", "B": "What you need is a good night''s sleep. This is the place where we first met.", "C": "What you need is a good night''s sleep. This is the place whose we first met.", "D": "That you need is a good night''s sleep. This is the place where we first met.", "E": "Who you need is a good night''s sleep. This is the place where we first met."}'::jsonb, 'B', NULL, 'What — What = the thing that; where — Yer bildirən nisbi zərf: where.');
INSERT INTO public.questions VALUES (10889, 137, 'g11-eng-pron-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ of them knew the answer, so the teacher explained it again. (2) The company changed ___ logo last year. (3) The woman ___ car was stolen called the police.', NULL, NULL, '{"A": "None / its / whom", "B": "Nobody / its / whose", "C": "None / it / whose", "D": "None / its / whose", "E": "None / its / which"}'::jsonb, 'D', NULL, '(1) None — none of them — heç biri (2) its — its — yiyəlik; it''s = it is (3) whose — whose — yiyəlik bildirən nisbi əvəzlik');
INSERT INTO public.questions VALUES (10890, 137, 'g11-eng-pron-q3-20', 3, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The company changed it''s logo last year. They blamed themselves for the mistake.", "B": "The company changed its logo last year. They blamed their for the mistake.", "C": "The company changed their''s logo last year. They blamed themselves for the mistake.", "D": "The company changed it logo last year. They blamed themselves for the mistake.", "E": "The company changed its logo last year. They blamed themselves for the mistake."}'::jsonb, 'E', NULL, 'its — its — yiyəlik; it''s = it is; themselves — Qayıdış: they → themselves.');
INSERT INTO public.questions VALUES (10891, 137, 'g11-eng-pron-q3-21', 3, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The two friends looked at each others and smiled.", "B": "Neither of the girls brought herself book.", "C": "Whose did you give the keys to?", "D": "This is the place who we first met.", "E": "What you need is a good night''s sleep."}'::jsonb, 'E', NULL, 'Correct: «What you need is a good night''s sleep.» — What = the thing that. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10892, 137, 'g11-eng-pron-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The company changed ___ logo last year. (2) ___ you need is a good night''s sleep. (3) The woman ___ car was stolen called the police.', NULL, NULL, '{"A": "its / What / which", "B": "its / Which / whose", "C": "its / What / whose", "D": "it / What / whose", "E": "their''s / What / whose"}'::jsonb, 'C', NULL, '(1) its — its — yiyəlik; it''s = it is (2) What — What = the thing that (3) whose — whose — yiyəlik bildirən nisbi əvəzlik');
INSERT INTO public.questions VALUES (10893, 137, 'g11-eng-pron-q3-23', 3, 23, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Between you and my, I don''t trust him.", "B": "We did the project by ourself.", "C": "I have two brothers, both of them are engineers.", "D": "Who did you give the keys to?", "E": "I don''t like these shoes. Can I see the black them?"}'::jsonb, 'D', NULL, 'Correct: «Who did you give the keys to?» — Sual: Who … to?. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10894, 137, 'g11-eng-pron-q3-24', 3, 24, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "A friend of my is coming to visit. Between you and me, I don''t trust him.", "B": "A friend of mine is coming to visit. Between you and I, I don''t trust him.", "C": "A friend of mine is coming to visit. Between you and my, I don''t trust him.", "D": "A friend of me is coming to visit. Between you and me, I don''t trust him.", "E": "A friend of mine is coming to visit. Between you and me, I don''t trust him."}'::jsonb, 'E', NULL, 'mine — a friend of mine — müstəqil forma; me — Önlükdən sonra obyekt forması: me.');
INSERT INTO public.questions VALUES (10895, 137, 'g11-eng-pron-q3-25', 3, 25, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Nothing of them knew the answer, so the teacher explained it again. Neither of the girls brought her book.", "B": "None of them knew the answer, so the teacher explained it again. Neither of the girls brought her book.", "C": "None of them knew the answer, so the teacher explained it again. Neither of the girls brought herself book.", "D": "No of them knew the answer, so the teacher explained it again. Neither of the girls brought her book.", "E": "None of them knew the answer, so the teacher explained it again. Neither of the girls brought hers book."}'::jsonb, 'B', NULL, 'None — none of them — heç biri; her — neither (tək) + her.');
INSERT INTO public.questions VALUES (10896, 137, 'g11-eng-pron-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They blamed ___ for the mistake. (2) ___ of them knew the answer, so the teacher explained it again. (3) I don''t like these shoes. Can I see the black ___?', NULL, NULL, '{"A": "theirselves / None / ones", "B": "themselves / None / ones", "C": "themselves / Nothing / ones", "D": "themselves / No / ones", "E": "themselves / Nobody / ones"}'::jsonb, 'B', NULL, '(1) themselves — Qayıdış: they → themselves (2) None — none of them — heç biri (3) ones — Cəm isim əvəzinə ones');
INSERT INTO public.questions VALUES (10897, 137, 'g11-eng-pron-q3-27', 3, 27, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ did you give the keys to? (2) I don''t like these shoes. Can I see the black ___? (3) Between you and ___, I don''t trust him.', NULL, NULL, '{"A": "Who / ones / my", "B": "What''s / ones / me", "C": "Who / ones / mine", "D": "Who / ones / me", "E": "Who / ones / I"}'::jsonb, 'D', NULL, '(1) Who — Sual: Who … to? (2) ones — Cəm isim əvəzinə ones (3) me — Önlükdən sonra obyekt forması: me');
INSERT INTO public.questions VALUES (10898, 137, 'g11-eng-pron-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I have two brothers, both of ___ are engineers. (2) She bought a laptop, ___ was very expensive. (3) The man ___ I spoke to was very helpful.', NULL, NULL, '{"A": "which / which / whom", "B": "whom / what / whom", "C": "whom / who / whom", "D": "whom / which / which", "E": "whom / which / whom"}'::jsonb, 'E', NULL, '(1) whom — Önlükdən sonra şəxs üçün whom (both of whom) (2) which — Ayırıcı nisbi cümlədə that işlənmir → which (3) whom — whom — obyekt kimi şəxs (formal)');
INSERT INTO public.questions VALUES (10899, 137, 'g11-eng-pron-q3-29', 3, 29, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) A friend of ___ is coming to visit. (2) Between you and ___, I don''t trust him. (3) I have two brothers, both of ___ are engineers.', NULL, NULL, '{"A": "mine / me / them", "B": "I / me / whom", "C": "mine / I / whom", "D": "mine / me / whom", "E": "mine / me / which"}'::jsonb, 'D', NULL, '(1) mine — a friend of mine — müstəqil forma (2) me — Önlükdən sonra obyekt forması: me (3) whom — Önlükdən sonra şəxs üçün whom (both of whom)');
INSERT INTO public.questions VALUES (10900, 137, 'g11-eng-pron-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The woman ___ car was stolen called the police. (2) She bought a laptop, ___ was very expensive. (3) They blamed ___ for the mistake.', NULL, NULL, '{"A": "whose / which / themselves", "B": "whose / that / themselves", "C": "who / which / themselves", "D": "whose / which / themself", "E": "which / which / themselves"}'::jsonb, 'A', NULL, '(1) whose — whose — yiyəlik bildirən nisbi əvəzlik (2) which — Ayırıcı nisbi cümlədə that işlənmir → which (3) themselves — Qayıdış: they → themselves');
INSERT INTO public.questions VALUES (10901, 138, 'g11-eng-num-q1-01', 1, 1, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "King Charles the Third became king in 2022. The twentieth-one century began in 2001.", "B": "King Charles Three became king in 2022. The twenty-first century began in 2001.", "C": "King Charles the Third became king in 2022. The twenty-first century began in 2001.", "D": "King Charles third the became king in 2022. The twenty-first century began in 2001.", "E": "King Charles the Third became king in 2022. The twenty-oneth century began in 2001."}'::jsonb, 'C', NULL, 'the Third — Hökmdar adlarında sıra sayı: Charles the Third; twenty-first — XXI əsr: the twenty-first century.');
INSERT INTO public.questions VALUES (10902, 138, 'g11-eng-num-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Water freezes at zero degrees Celsius.", "B": "She won the one prize in the competition.", "C": "Half from the class was absent.", "D": "It was a fifth-mile walk.", "E": "King Charles the Three became king in 2022."}'::jsonb, 'A', NULL, 'Correct: «Water freezes at zero degrees Celsius.» — Temperatur: zero degrees Celsius. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10903, 138, 'g11-eng-num-q1-03', 1, 3, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "This is the hundreds time I have told you!", "B": "Half in the class was absent.", "C": "I need a dozen of eggs for this cake.", "D": "King Charles the Third became king in 2022.", "E": "A hundreds of birds flew over the lake."}'::jsonb, 'D', NULL, 'Correct: «King Charles the Third became king in 2022.» — Hökmdar adlarında sıra sayı: Charles the Third. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10904, 138, 'g11-eng-num-q1-04', 1, 4, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Water freezes at zero degrees ___. (2) ___ birds flew over the lake. (3) The ___ World War ended in 1945.', NULL, NULL, '{"A": "Celsius''s / Hundreds of / Second", "B": "Celsius / A hundreds of / Second", "C": "Celsius / Hundred of / Second", "D": "Celsius / Hundreds of / Second", "E": "Celsius / Hundreds / Second"}'::jsonb, 'D', NULL, '(1) Celsius — Temperatur: zero degrees Celsius (2) Hundreds of — Qeyri-müəyyən: hundreds of (3) Second — the Second World War');
INSERT INTO public.questions VALUES (10905, 138, 'g11-eng-num-q1-05', 1, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I''ve told you ___ times not to do that! (2) The meeting is on ___ floor. (3) This is the ___ time I have told you!', NULL, NULL, '{"A": "dozens of / the ninth / hundred", "B": "a dozens / the ninth / hundredth", "C": "dozens of / the ninth / hundreds", "D": "dozens of / the nineth / hundredth", "E": "dozens of / the ninth / hundredth"}'::jsonb, 'E', NULL, '(1) dozens of — Qeyri-müəyyən: dozens of times (2) the ninth — 9 → ninth (e düşür) (3) hundredth — 100-cü: hundredth');
INSERT INTO public.questions VALUES (10906, 138, 'g11-eng-num-q1-06', 1, 6, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The twenty-first century began in 2001.", "B": "It was a five-miles walk.", "C": "This is the hundreds time I have told you!", "D": "Million people watched the match online.", "E": "The flight takes a one and half hours."}'::jsonb, 'A', NULL, 'Correct: «The twenty-first century began in 2001.» — XXI əsr: the twenty-first century. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10907, 138, 'g11-eng-num-q1-07', 1, 7, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I''ve told you dozen times not to do that!", "B": "Hundreds birds flew over the lake.", "C": "Prices rose by 2.5 per cent — that is, two and five per cent.", "D": "It was a five-mile walk.", "E": "She won firstly prize in the competition."}'::jsonb, 'D', NULL, 'Correct: «It was a five-mile walk.» — Mürəkkəb sifət: a five-mile walk. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10908, 138, 'g11-eng-num-q1-08', 1, 8, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Please open your books at page 25.", "B": "Million of people watched the match online.", "C": "Three fourth of the cake were eaten.", "D": "The flight takes one half and hours.", "E": "She won firstly prize in the competition."}'::jsonb, 'A', NULL, 'Correct: «Please open your books at page 25.» — page + rəqəm, artiklsiz. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10909, 138, 'g11-eng-num-q1-09', 1, 9, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Millions of people watched the match online. She won firstly prize in the competition.", "B": "Million people watched the match online. She won first prize in the competition.", "C": "Million of people watched the match online. She won first prize in the competition.", "D": "Millions of people watched the match online. She won one prize in the competition.", "E": "Millions of people watched the match online. She won first prize in the competition."}'::jsonb, 'E', NULL, 'Millions of — Qeyri-müəyyən çoxluq: millions of; first — won first prize — artiklsiz sabit ifadə.');
INSERT INTO public.questions VALUES (10910, 138, 'g11-eng-num-q1-10', 1, 10, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Water freezes at zero degrees Celsius. I need a dozens eggs for this cake.", "B": "Water freezes at zero degrees Celsius''s. I need a dozen eggs for this cake.", "C": "Water freezes at zero degrees Celsius. I need a dozens of eggs for this cake.", "D": "Water freezes at zero degrees Celsius. I need a dozen eggs for this cake.", "E": "Water freezes at zero degrees Celsius. I need a dozen of eggs for this cake."}'::jsonb, 'D', NULL, 'Celsius — Temperatur: zero degrees Celsius; dozen — a dozen eggs (of olmadan).');
INSERT INTO public.questions VALUES (10911, 138, 'g11-eng-num-q1-11', 1, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Water freezes at zero degrees ___. (2) It was a ___ walk. (3) Prices rose by 2.5 per cent — that is, two ___ five per cent.', NULL, NULL, '{"A": "Celsius / five-mile / dot and", "B": "Celsius''s / five-mile / point", "C": "of Celsius / five-mile / point", "D": "Celsius / five-mile / comma", "E": "Celsius / five-mile / point"}'::jsonb, 'E', NULL, '(1) Celsius — Temperatur: zero degrees Celsius (2) five-mile — Mürəkkəb sifət: a five-mile walk (3) point — Onluq kəsr: two point five');
INSERT INTO public.questions VALUES (10912, 138, 'g11-eng-num-q1-12', 1, 12, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The twenty-first century began in 2001. The Second World War ended in 1945.", "B": "The twentieth-one century began in 2001. The Second World War ended in 1945.", "C": "The twenty-first century began in 2001. The Secondly World War ended in 1945.", "D": "The twenty-first century began in 2001. The Twice World War ended in 1945.", "E": "The twenty-oneth century began in 2001. The Second World War ended in 1945."}'::jsonb, 'A', NULL, 'twenty-first — XXI əsr: the twenty-first century; Second — the Second World War.');
INSERT INTO public.questions VALUES (10913, 138, 'g11-eng-num-q1-13', 1, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Three ___ of the cake were eaten. (3/4) (2) Prices rose by 2.5 per cent — that is, two ___ five per cent. (3) This is the ___ time I have told you!', NULL, NULL, '{"A": "quarters / point / hundred", "B": "four / point / hundredth", "C": "quarters / point / hundredth", "D": "quarters / point / hundredeth", "E": "quarter / point / hundredth"}'::jsonb, 'C', NULL, '(1) quarters — three quarters (2) point — Onluq kəsr: two point five (3) hundredth — 100-cü: hundredth');
INSERT INTO public.questions VALUES (10914, 138, 'g11-eng-num-q1-14', 1, 14, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I need a ___ eggs for this cake. (2) Three ___ of the cake were eaten. (3/4) (3) The ___ century began in 2001.', NULL, NULL, '{"A": "dozen / quarters / twenty-oneth", "B": "dozen / quarters / twenty-first", "C": "dozens / quarters / twenty-first", "D": "dozen / quarters / twenty-one", "E": "dozen / four / twenty-first"}'::jsonb, 'B', NULL, '(1) dozen — a dozen eggs (of olmadan) (2) quarters — three quarters (3) twenty-first — XXI əsr: the twenty-first century');
INSERT INTO public.questions VALUES (10915, 138, 'g11-eng-num-q1-15', 1, 15, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I need a dozens eggs for this cake. Half of the class was absent.", "B": "I need a dozen eggs for this cake. Half of the class was absent.", "C": "I need a dozen of eggs for this cake. Half of the class was absent.", "D": "I need a dozen eggs for this cake. Half in the class was absent.", "E": "I need a dozens of eggs for this cake. Half of the class was absent."}'::jsonb, 'B', NULL, 'dozen — a dozen eggs (of olmadan); of — half of the class.');
INSERT INTO public.questions VALUES (10916, 138, 'g11-eng-num-q1-16', 1, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Water freezes at zero degrees of Celsius.", "B": "This is the hundredth time I have told you!", "C": "The twentieth-one century began in 2001.", "D": "The Two World War ended in 1945.", "E": "King Charles Three became king in 2022."}'::jsonb, 'B', NULL, 'Correct: «This is the hundredth time I have told you!» — 100-cü: hundredth. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10917, 138, 'g11-eng-num-q1-17', 1, 17, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "She won the one prize in the competition.", "B": "Prices rose by 2.5 per cent — that is, two dot and five per cent.", "C": "Three quarter of the cake were eaten.", "D": "Second thirds of the students are girls.", "E": "I''ve told you dozens of times not to do that!"}'::jsonb, 'E', NULL, 'Correct: «I''ve told you dozens of times not to do that!» — Qeyri-müəyyən: dozens of times. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10918, 138, 'g11-eng-num-q1-18', 1, 18, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "The flight takes one and a half hours. The Two World War ended in 1945.", "B": "The flight takes one and a half hours. The Twice World War ended in 1945.", "C": "The flight takes one and a half hours. The Second World War ended in 1945.", "D": "The flight takes one half and hours. The Second World War ended in 1945.", "E": "The flight takes a one and half hours. The Second World War ended in 1945."}'::jsonb, 'C', NULL, 'one and a half — 1,5: one and a half hours; Second — the Second World War.');
INSERT INTO public.questions VALUES (10919, 138, 'g11-eng-num-q1-19', 1, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "This is the hundredth time I have told you! It was a five-miles walk.", "B": "This is the hundred time I have told you! It was a five-mile walk.", "C": "This is the hundreds time I have told you! It was a five-mile walk.", "D": "This is the hundredth time I have told you! It was a five-mile walk.", "E": "This is the hundredeth time I have told you! It was a five-mile walk."}'::jsonb, 'D', NULL, 'hundredth — 100-cü: hundredth; five-mile — Mürəkkəb sifət: a five-mile walk.');
INSERT INTO public.questions VALUES (10920, 138, 'g11-eng-num-q1-20', 1, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The flight takes ___ hours. (2) King Charles ___ became king in 2022. (III) (3) ___ people watched the match online.', NULL, NULL, '{"A": "one half and / the Third / Millions of", "B": "one and a half / Three / Millions of", "C": "one and a half / the Third / Millions of", "D": "one and a half / the Three / Millions of", "E": "one and a half / third the / Millions of"}'::jsonb, 'C', NULL, '(1) one and a half — 1,5: one and a half hours (2) the Third — Hökmdar adlarında sıra sayı: Charles the Third (3) Millions of — Qeyri-müəyyən çoxluq: millions of');
INSERT INTO public.questions VALUES (10921, 138, 'g11-eng-num-q1-21', 1, 21, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "A hundreds of birds flew over the lake.", "B": "The twenty-one century began in 2001.", "C": "The meeting is on nine floor.", "D": "The flight takes one and half hours.", "E": "This is the hundredth time I have told you!"}'::jsonb, 'E', NULL, 'Correct: «This is the hundredth time I have told you!» — 100-cü: hundredth. The other sentences each contain an error.');
