INSERT INTO public.questions VALUES (10962, 138, 'g11-eng-num-q3-02', 3, 2, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Prices rose by 2.5 per cent — that is, two ___ five per cent. (2) The ___ World War ended in 1945. (3) It was a ___ walk.', NULL, NULL, '{"A": "point / Second / five miles''", "B": "point / Second / five-miles", "C": "point / Second / five-mile", "D": "point / Secondly / five-mile", "E": "point / Twice / five-mile"}'::jsonb, 'C', NULL, '(1) point — Onluq kəsr: two point five (2) Second — the Second World War (3) five-mile — Mürəkkəb sifət: a five-mile walk');
INSERT INTO public.questions VALUES (10963, 138, 'g11-eng-num-q3-03', 3, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Prices rose by 2.5 per cent — that is, two ___ five per cent. (2) Water freezes at zero degrees ___. (3) Half ___ the class was absent.', NULL, NULL, '{"A": "point / Celsius / by", "B": "point / Celsius / from", "C": "point / Celsius / in", "D": "point / Celsius / of", "E": "comma / Celsius / of"}'::jsonb, 'D', NULL, '(1) point — Onluq kəsr: two point five (2) Celsius — Temperatur: zero degrees Celsius (3) of — half of the class');
INSERT INTO public.questions VALUES (10964, 138, 'g11-eng-num-q3-04', 3, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "The meeting is on nine floor.", "B": "Million people watched the match online.", "C": "The twenty-one century began in 2001.", "D": "Please open your books at 25 page.", "E": "King Charles the Third became king in 2022."}'::jsonb, 'E', NULL, 'Correct: «King Charles the Third became king in 2022.» — Hökmdar adlarında sıra sayı: Charles the Third. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10965, 138, 'g11-eng-num-q3-05', 3, 5, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "It was a five-mile walk. I''ve told you dozens times not to do that!", "B": "It was a five-mile walk. I''ve told you a dozens times not to do that!", "C": "It was a five-mile walk. I''ve told you dozen times not to do that!", "D": "It was a five-mile walk. I''ve told you dozens of times not to do that!", "E": "It was a five miles'' walk. I''ve told you dozens of times not to do that!"}'::jsonb, 'D', NULL, 'five-mile — Mürəkkəb sifət: a five-mile walk; dozens of — Qeyri-müəyyən: dozens of times.');
