INSERT INTO public.questions VALUES (10971, 138, 'g11-eng-num-q3-11', 3, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Three ___ of the cake were eaten. (3/4) (2) Prices rose by 2.5 per cent — that is, two ___ five per cent. (3) She won ___ prize in the competition.', NULL, NULL, '{"A": "quarters / point / firstly", "B": "quarters / comma / first", "C": "quarter / point / first", "D": "quarters / point / first", "E": "fourth / point / first"}'::jsonb, 'D', NULL, '(1) quarters — three quarters (2) point — Onluq kəsr: two point five (3) first — won first prize — artiklsiz sabit ifadə');
INSERT INTO public.questions VALUES (10972, 138, 'g11-eng-num-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Please open your books at ___. (2) Half ___ the class was absent. (3) It was a ___ walk.', NULL, NULL, '{"A": "page 25 / of / five-miles", "B": "page 25 / of / five-mile", "C": "page 25 / of / fifth-mile", "D": "the 25 page / of / five-mile", "E": "page 25 / from / five-mile"}'::jsonb, 'B', NULL, '(1) page 25 — page + rəqəm, artiklsiz (2) of — half of the class (3) five-mile — Mürəkkəb sifət: a five-mile walk');
