INSERT INTO public.questions VALUES (10985, 138, 'g11-eng-num-q3-25', 3, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) King Charles ___ became king in 2022. (III) (2) I need a ___ eggs for this cake. (3) ___ people watched the match online.', NULL, NULL, '{"A": "the Third / dozen / Millions of", "B": "the Third / dozen / Million of", "C": "the Third / dozen / Million", "D": "the Third / dozen / Millions", "E": "the Third / dozens / Millions of"}'::jsonb, 'A', NULL, '(1) the Third — Hökmdar adlarında sıra sayı: Charles the Third (2) dozen — a dozen eggs (of olmadan) (3) Millions of — Qeyri-müəyyən çoxluq: millions of');
