INSERT INTO public.questions VALUES (10988, 138, 'g11-eng-num-q3-28', 3, 28, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) ___ birds flew over the lake. (2) King Charles ___ became king in 2022. (III) (3) The meeting is on ___ floor.', NULL, NULL, '{"A": "A hundreds of / the Third / the ninth", "B": "Hundreds / the Third / the ninth", "C": "Hundreds of / the Third / the ninth", "D": "Hundreds of / the Third / the nineth", "E": "Hundreds of / the Third / ninth the"}'::jsonb, 'C', NULL, '(1) Hundreds of — Qeyri-müəyyən: hundreds of (2) the Third — Hökmdar adlarında sıra sayı: Charles the Third (3) the ninth — 9 → ninth (e düşür)');
