INSERT INTO public.questions VALUES (10990, 138, 'g11-eng-num-q3-30', 3, 30, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Three four of the cake were eaten.", "B": "King Charles third the became king in 2022.", "C": "Millions of people watched the match online.", "D": "I need a dozens eggs for this cake.", "E": "I''ve told you a dozens times not to do that!"}'::jsonb, 'C', NULL, 'Correct: «Millions of people watched the match online.» — Qeyri-müəyyən çoxluq: millions of. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10991, 139, 'g11-eng-adv-q1-01', 1, 1, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He nearly ever goes to the cinema.", "B": "You are not working enough hard to pass the exam.", "C": "He ran faster than anyone else.", "D": "She answered the question confidentlier than I did.", "E": "We arrived yet on time; the doors were closing."}'::jsonb, 'C', NULL, 'Correct: «He ran faster than anyone else.» — fast → faster. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10992, 139, 'g11-eng-adv-q1-02', 1, 2, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He was too tired that he fell asleep at once.", "B": "He nearly ever goes to the cinema.", "C": "Already had I arrived when the phone rang.", "D": "We arrived lately on time; the doors were closing.", "E": "I can hardly hear you; please speak louder."}'::jsonb, 'E', NULL, 'Correct: «I can hardly hear you; please speak louder.» — hardly = demək olar ki, yox. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10993, 139, 'g11-eng-adv-q1-03', 1, 3, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He ran ___ than anyone else. (2) She answered the question ___ than I did. (3) The soup smells ___.', NULL, NULL, '{"A": "more fast / more confidently / delicious", "B": "faster / more confidently / delicious", "C": "faster / more confidently / more deliciously", "D": "faster / confidentlier / delicious", "E": "faster / more confidently / delicious-ly"}'::jsonb, 'B', NULL, '(1) faster — fast → faster (2) more confidently — -ly zərfləri: more + zərf (3) delicious — Duyğu feilləri (smell, taste) + sifət');
INSERT INTO public.questions VALUES (10994, 139, 'g11-eng-adv-q1-04', 1, 4, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Never I have seen such a beautiful sunset.", "B": "You are not working enough hard to pass the exam.", "C": "He ran more fast than anyone else.", "D": "He hard ever goes to the cinema.", "E": "He arrived late for the meeting."}'::jsonb, 'E', NULL, 'Correct: «He arrived late for the meeting.» — late — zərf (gec). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10995, 139, 'g11-eng-adv-q1-05', 1, 5, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "I can hard hear you; please speak louder.", "B": "Hardly had I arrived when the phone rang.", "C": "She can fluentlly speak three languages.", "D": "She ever lives with her parents.", "E": "Never I saw such a beautiful sunset."}'::jsonb, 'B', NULL, 'Correct: «Hardly had I arrived when the phone rang.» — İnversiya: Hardly had I …. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (10996, 139, 'g11-eng-adv-q1-06', 1, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She can ___ speak three languages. (2) I''ll be there ___. Wait for me! (3) He ___ ever goes to the cinema.', NULL, NULL, '{"A": "fluently / soonest / hardly", "B": "fluently / soon / nearly", "C": "fluently / soon / hardly", "D": "fluency / soon / hardly", "E": "fluent / soon / hardly"}'::jsonb, 'C', NULL, '(1) fluently — fluent → fluently (2) soon — soon — zaman zərfi (3) hardly — hardly ever = demək olar ki, heç vaxt');
INSERT INTO public.questions VALUES (10997, 139, 'g11-eng-adv-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She looked at me ___. (2) He was ___ tired that he fell asleep at once. (3) He ___ ever goes to the cinema.', NULL, NULL, '{"A": "angrily / so / hard", "B": "angryly / so / hardly", "C": "angrily / such / hardly", "D": "angrily / so / hardly", "E": "angerly / so / hardly"}'::jsonb, 'D', NULL, '(1) angrily — look at (hərəkət) + zərf (2) so — so + sifət + that (3) hardly — hardly ever = demək olar ki, heç vaxt');
INSERT INTO public.questions VALUES (10998, 139, 'g11-eng-adv-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Have you seen any good films ___? (2) She ___ lives with her parents. (3) He was ___ tired that he fell asleep at once.', NULL, NULL, '{"A": "lately / still / such", "B": "lateness / still / so", "C": "lately / still / so", "D": "latest / still / so", "E": "late / still / so"}'::jsonb, 'C', NULL, '(1) lately — lately = son vaxtlar (2) still — still — hələ də (davam edən vəziyyət) (3) so — so + sifət + that');
INSERT INTO public.questions VALUES (10999, 139, 'g11-eng-adv-q1-09', 1, 9, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She answered the question ___ than I did. (2) She looked at me ___. (3) He was ___ tired that he fell asleep at once.', NULL, NULL, '{"A": "more confident / angrily / so", "B": "more confidently / angrily / enough", "C": "more confidently / angerly / so", "D": "more confidently / angrily / so", "E": "more confidently / angrily / such"}'::jsonb, 'D', NULL, '(1) more confidently — -ly zərfləri: more + zərf (2) angrily — look at (hərəkət) + zərf (3) so — so + sifət + that');
INSERT INTO public.questions VALUES (11000, 139, 'g11-eng-adv-q1-10', 1, 10, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "Never seen I have such a beautiful sunset.", "B": "She sings more beautifully of all the students.", "C": "He works hard every day.", "D": "She yet lives with her parents.", "E": "Lately had I arrived when the phone rang."}'::jsonb, 'C', NULL, 'Correct: «He works hard every day.» — hard — zərf də olur; hardly = demək olar ki, yox. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11001, 139, 'g11-eng-adv-q1-11', 1, 11, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The soup smells ___. (2) She looked at me ___. (3) She sings ___ of all the students.', NULL, NULL, '{"A": "delicious / angryly / the most beautifully", "B": "delicious / angerly / the most beautifully", "C": "delicious / angrilly / the most beautifully", "D": "delicious / angrily / the most beautifully", "E": "delicious-ly / angrily / the most beautifully"}'::jsonb, 'D', NULL, '(1) delicious — Duyğu feilləri (smell, taste) + sifət (2) angrily — look at (hərəkət) + zərf (3) the most beautifully — Zərfin üstünlük dərəcəsi: the most + -ly');
INSERT INTO public.questions VALUES (11002, 139, 'g11-eng-adv-q1-12', 1, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Have you seen any good films ___? (2) I''ll be there ___. Wait for me! (3) He ___ ever goes to the cinema.', NULL, NULL, '{"A": "lately / soon / hardly", "B": "latest / soon / hardly", "C": "lately / soonest / hardly", "D": "lateness / soon / hardly", "E": "late / soon / hardly"}'::jsonb, 'A', NULL, '(1) lately — lately = son vaxtlar (2) soon — soon — zaman zərfi (3) hardly — hardly ever = demək olar ki, heç vaxt');
INSERT INTO public.questions VALUES (11003, 139, 'g11-eng-adv-q1-13', 1, 13, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He was so tired that he fell asleep at once.", "B": "Have you seen any good films late?", "C": "She sings beautifullest of all the students.", "D": "We arrived yet on time; the doors were closing.", "E": "He arrived lates for the meeting."}'::jsonb, 'A', NULL, 'Correct: «He was so tired that he fell asleep at once.» — so + sifət + that. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11004, 139, 'g11-eng-adv-q1-14', 1, 14, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He works harder than every day.", "B": "He ran more fast than anyone else.", "C": "She ever lives with her parents.", "D": "Hardly had I arrived when the phone rang.", "E": "She answered the question most confidently than I did."}'::jsonb, 'D', NULL, 'Correct: «Hardly had I arrived when the phone rang.» — İnversiya: Hardly had I …. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11005, 139, 'g11-eng-adv-q1-15', 1, 15, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "He arrived lates for the meeting. Hardly had I arrived when the phone rang.", "B": "He arrived late for the meeting. Hardly had I arrived when the phone rang.", "C": "He arrived latish for the meeting. Hardly had I arrived when the phone rang.", "D": "He arrived late for the meeting. Hard had I arrived when the phone rang.", "E": "He arrived lately for the meeting. Hardly had I arrived when the phone rang."}'::jsonb, 'B', NULL, 'late — late — zərf (gec); Hardly — İnversiya: Hardly had I ….');
INSERT INTO public.questions VALUES (11006, 139, 'g11-eng-adv-q1-16', 1, 16, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "You are not working too hard to pass the exam.", "B": "She can fluent speak three languages.", "C": "Never I have seen such a beautiful sunset.", "D": "Have you seen any good films lately?", "E": "The soup smells delicious-ly."}'::jsonb, 'D', NULL, 'Correct: «Have you seen any good films lately?» — lately = son vaxtlar. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11007, 139, 'g11-eng-adv-q1-17', 1, 17, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "I can hardly hear you; please speak louder. She still lives with her parents.", "B": "I can hardly hear you; please speak louder. She yet lives with her parents.", "C": "I can hardy hear you; please speak louder. She still lives with her parents.", "D": "I can hard hear you; please speak louder. She still lives with her parents.", "E": "I can hardily hear you; please speak louder. She still lives with her parents."}'::jsonb, 'A', NULL, 'hardly — hardly = demək olar ki, yox; still — still — hələ də (davam edən vəziyyət).');
INSERT INTO public.questions VALUES (11008, 139, 'g11-eng-adv-q1-18', 1, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Have you seen any good films ___? (2) He ran ___ than anyone else. (3) He works ___ every day.', NULL, NULL, '{"A": "latest / faster / hard", "B": "lately / faster / hardy", "C": "lately / faster / harder than", "D": "late / faster / hard", "E": "lately / faster / hard"}'::jsonb, 'E', NULL, '(1) lately — lately = son vaxtlar (2) faster — fast → faster (3) hard — hard — zərf də olur; hardly = demək olar ki, yox');
INSERT INTO public.questions VALUES (11009, 139, 'g11-eng-adv-q1-19', 1, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "We arrived just on time; the doors were closing. He works hardy every day.", "B": "We arrived yet on time; the doors were closing. He works hard every day.", "C": "We arrived just on time; the doors were closing. He works hardly every day.", "D": "We arrived just on time; the doors were closing. He works harder than every day.", "E": "We arrived just on time; the doors were closing. He works hard every day."}'::jsonb, 'E', NULL, 'just — just — tam, ancaq; hard — hard — zərf də olur; hardly = demək olar ki, yox.');
INSERT INTO public.questions VALUES (11010, 139, 'g11-eng-adv-q1-20', 1, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Never have I seen such a beautiful sunset. He works hardly every day.", "B": "Never have I seen such a beautiful sunset. He works harder than every day.", "C": "Never have I seen such a beautiful sunset. He works hard every day.", "D": "Never seen I have such a beautiful sunset. He works hard every day.", "E": "Never have I seen such a beautiful sunset. He works hardy every day."}'::jsonb, 'C', NULL, 'have I seen — Inkar zərfi əvvəldə → inversiya; hard — hard — zərf də olur; hardly = demək olar ki, yox.');
INSERT INTO public.questions VALUES (11011, 139, 'g11-eng-adv-q1-21', 1, 21, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She sings the most beautiful of all the students. Hardly had I arrived when the phone rang.", "B": "She sings beautifullest of all the students. Hardly had I arrived when the phone rang.", "C": "She sings the most beautifully of all the students. Hardly had I arrived when the phone rang.", "D": "She sings more beautifully of all the students. Hardly had I arrived when the phone rang.", "E": "She sings the most beautifully of all the students. Lately had I arrived when the phone rang."}'::jsonb, 'C', NULL, 'the most beautifully — Zərfin üstünlük dərəcəsi: the most + -ly; Hardly — İnversiya: Hardly had I ….');
