INSERT INTO public.questions VALUES (11039, 139, 'g11-eng-adv-q2-19', 2, 19, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "She still lives with her parents. He almost ever goes to the cinema.", "B": "She still lives with her parents. He hardly ever goes to the cinema.", "C": "She still lives with her parents. He nearly ever goes to the cinema.", "D": "She ever lives with her parents. He hardly ever goes to the cinema.", "E": "She still lives with her parents. He hard ever goes to the cinema."}'::jsonb, 'B', NULL, 'still — still — hələ də (davam edən vəziyyət); hardly — hardly ever = demək olar ki, heç vaxt.');
INSERT INTO public.questions VALUES (11040, 139, 'g11-eng-adv-q2-20', 2, 20, 'hard', 'single', 'In which option are BOTH sentences grammatically correct?', NULL, NULL, '{"A": "Have you seen any good films lately? He works hard every day.", "B": "Have you seen any good films late? He works hard every day.", "C": "Have you seen any good films lately? He works harder than every day.", "D": "Have you seen any good films lately? He works hardy every day.", "E": "Have you seen any good films lately? He works hardly every day."}'::jsonb, 'A', NULL, 'lately — lately = son vaxtlar; hard — hard — zərf də olur; hardly = demək olar ki, yox.');
INSERT INTO public.questions VALUES (11041, 139, 'g11-eng-adv-q2-21', 2, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) You are not working ___ to pass the exam. (2) She ___ lives with her parents. (3) ___ had I arrived when the phone rang.', NULL, NULL, '{"A": "hard enough / still / Lately", "B": "hard enough / still / Hardly", "C": "hard enough / yet / Hardly", "D": "enough hard / still / Hardly", "E": "hard enough / still / Already"}'::jsonb, 'B', NULL, '(1) hard enough — zərf + enough (2) still — still — hələ də (davam edən vəziyyət) (3) Hardly — İnversiya: Hardly had I …');
INSERT INTO public.questions VALUES (11042, 139, 'g11-eng-adv-q2-22', 2, 22, 'hard', 'single', 'Which sentence is grammatically correct?', NULL, NULL, '{"A": "He nearly ever goes to the cinema.", "B": "Lately had I arrived when the phone rang.", "C": "I can hardy hear you; please speak louder.", "D": "She answered the question more confidently than I did.", "E": "He was enough tired that he fell asleep at once."}'::jsonb, 'D', NULL, 'Correct: «She answered the question more confidently than I did.» — -ly zərfləri: more + zərf. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11043, 139, 'g11-eng-adv-q2-23', 2, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She can ___ speak three languages. (2) You are not working ___ to pass the exam. (3) Never ___ such a beautiful sunset.', NULL, NULL, '{"A": "fluently / too hard / have I seen", "B": "fluently / hard enough / have I seen", "C": "fluently / hard enough / seen I have", "D": "fluentlly / hard enough / have I seen", "E": "fluently / enough hard / have I seen"}'::jsonb, 'B', NULL, '(1) fluently — fluent → fluently (2) hard enough — zərf + enough (3) have I seen — Inkar zərfi əvvəldə → inversiya');
