INSERT INTO public.questions VALUES (11245, 141, 'g11-eng-phrasal-q3-15', 3, 15, 'hard', 'single', 'Which sentence is correct?', NULL, NULL, '{"A": "He took off chess last year, and now he plays every day.", "B": "She stood up for her friend when the others laughed at him.", "C": "Here is the form. Please fill it on in and sign it.", "D": "The light is too bright. Could you turn off it, please?", "E": "I don''t feel to going out tonight; I''m too tired."}'::jsonb, 'B', NULL, 'Correct: «She stood up for her friend when the others laughed at him.» — stand up for — müdafiə etmək. The other sentences each contain an error.');
