INSERT INTO public.questions VALUES (11247, 141, 'g11-eng-phrasal-q3-17', 3, 17, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "We need to come up with a solution before Friday. You can always count for me if you need help.", "B": "We need to come up with a solution before Friday. You can always count at me if you need help.", "C": "We need to come off with a solution before Friday. You can always count on me if you need help.", "D": "We need to come up with a solution before Friday. You can always count on me if you need help.", "E": "We need to come up with a solution before Friday. You can always count with me if you need help."}'::jsonb, 'D', NULL, 'up — come up with — tapmaq; on — count on — güvənmək.');
INSERT INTO public.questions VALUES (11248, 141, 'g11-eng-phrasal-q3-18', 3, 18, 'hard', 'single', 'Which sentence is correct?', NULL, NULL, '{"A": "The light is too bright. Could you turn off it, please?", "B": "He walks so fast that I can''t keep up to him.", "C": "You can always count with me if you need help.", "D": "We set off early in the morning to avoid the traffic.", "E": "We need to come off with a solution before Friday."}'::jsonb, 'D', NULL, 'Correct: «We set off early in the morning to avoid the traffic.» — set off — yola düşmək. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11249, 141, 'g11-eng-phrasal-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The rumour turned ___ to be completely false. (2) We need to come ___ with a solution before Friday. (3) He dropped out ___ university in his second year.', NULL, NULL, '{"A": "out / up / off", "B": "out / up / with", "C": "out / over / of", "D": "out / after / of", "E": "out / up / of"}'::jsonb, 'E', NULL, '(1) out — turn out — məlum olmaq (2) up — come up with — tapmaq (3) of — drop out of — oxumağı yarımçıq atmaq');
INSERT INTO public.questions VALUES (11250, 141, 'g11-eng-phrasal-q3-20', 3, 20, 'hard', 'single', 'Which sentence is correct?', NULL, NULL, '{"A": "Someone broke down to our neighbour''s house last night and stole a TV.", "B": "Here is the form. Please fill in it and sign it.", "C": "You should cut down on sugar if you want to be healthy.", "D": "He took over chess last year, and now he plays every day.", "E": "These are your shoes. Put them in on before you go out."}'::jsonb, 'C', NULL, 'Correct: «You should cut down on sugar if you want to be healthy.» — cut down on — azaltmaq. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11251, 141, 'g11-eng-phrasal-q3-21', 3, 21, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) You can always count ___ me if you need help. (2) It took him two weeks to get ___ the flu. (3) He has always looked down ___ people who earn less than him.', NULL, NULL, '{"A": "with / over / on", "B": "for / over / on", "C": "on / over / on", "D": "on / over / after", "E": "on / out / on"}'::jsonb, 'C', NULL, '(1) on — count on — güvənmək (2) over — get over — sağalmaq (3) on — look down on — xor baxmaq');
INSERT INTO public.questions VALUES (11252, 141, 'g11-eng-phrasal-q3-22', 3, 22, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "The government has decided to do away with the old tax. Here is the form. Please fill in to it and sign it.", "B": "The government has decided to do away with the old tax. Here is the form. Please fill in it and sign it.", "C": "The government has decided to do away with the old tax. Here is the form. Please fill it on in and sign it.", "D": "The government has decided to do away from the old tax. Here is the form. Please fill it in and sign it.", "E": "The government has decided to do away with the old tax. Here is the form. Please fill it in and sign it."}'::jsonb, 'E', NULL, 'with — do away with — ləğv etmək; it in — Əvəzlik: fill it in.');
INSERT INTO public.questions VALUES (11253, 141, 'g11-eng-phrasal-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Don''t let the bad result put you ___; keep trying. (2) You can always count ___ me if you need help. (3) The police are looking ___ the case; they want to know what happened.', NULL, NULL, '{"A": "off / for / into", "B": "off / on / into", "C": "off / with / into", "D": "off / on / up to", "E": "off / on / forward"}'::jsonb, 'B', NULL, '(1) off — put somebody off — həvəsdən salmaq (2) on — count on — güvənmək (3) into — look into — araşdırmaq');
INSERT INTO public.questions VALUES (11254, 141, 'g11-eng-phrasal-q3-24', 3, 24, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "I''m not used to getting up so early. After hours of arguing, he finally gave out of and agreed.", "B": "I''m not used to getting up so early. After hours of arguing, he finally gave in and agreed.", "C": "I''m not used to be getting up so early. After hours of arguing, he finally gave in and agreed.", "D": "I''m not used to getting up so early. After hours of arguing, he finally gave off and agreed.", "E": "I''m not used to get up so early. After hours of arguing, he finally gave in and agreed."}'::jsonb, 'B', NULL, 'getting — be used to + V-ing; in — give in — təslim olmaq.');
INSERT INTO public.questions VALUES (11255, 141, 'g11-eng-phrasal-q3-25', 3, 25, 'hard', 'single', 'Which sentence is correct?', NULL, NULL, '{"A": "The children were told to hand off their homework by Friday.", "B": "He dropped out with university in his second year.", "C": "The rumour turned off to be completely false.", "D": "These are your shoes. Put on to them before you go out.", "E": "She stood up for her friend when the others laughed at him."}'::jsonb, 'E', NULL, 'Correct: «She stood up for her friend when the others laughed at him.» — stand up for — müdafiə etmək. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11256, 141, 'g11-eng-phrasal-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) It took him two weeks to get ___ the flu. (2) The meeting has been put ___ until next Monday. (3) He dropped out ___ university in his second year.', NULL, NULL, '{"A": "over / off / off", "B": "over / over to / of", "C": "over / out / of", "D": "over / off / of", "E": "over / off / to"}'::jsonb, 'D', NULL, '(1) over — get over — sağalmaq (2) off — put off — təxirə salmaq (3) of — drop out of — oxumağı yarımçıq atmaq');
INSERT INTO public.questions VALUES (11257, 141, 'g11-eng-phrasal-q3-27', 3, 27, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "Here is the form. Please fill it in and sign it. It took him two weeks to get off the flu.", "B": "Here is the form. Please fill it in and sign it. It took him two weeks to get out the flu.", "C": "Here is the form. Please fill it in and sign it. It took him two weeks to get over the flu.", "D": "Here is the form. Please fill it on in and sign it. It took him two weeks to get over the flu.", "E": "Here is the form. Please fill it in and sign it. It took him two weeks to get up the flu."}'::jsonb, 'C', NULL, 'it in — Əvəzlik: fill it in; over — get over — sağalmaq.');
INSERT INTO public.questions VALUES (11258, 141, 'g11-eng-phrasal-q3-28', 3, 28, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "I came across an interesting article while I was reading the news. I''m not used to got up so early.", "B": "I came up to an interesting article while I was reading the news. I''m not used to getting up so early.", "C": "I came across an interesting article while I was reading the news. I''m not used to getting up so early.", "D": "I came across an interesting article while I was reading the news. I''m not used to get up so early.", "E": "I came over to an interesting article while I was reading the news. I''m not used to getting up so early."}'::jsonb, 'C', NULL, 'across — come across — təsadüfən tapmaq; getting — be used to + V-ing.');
INSERT INTO public.questions VALUES (11259, 141, 'g11-eng-phrasal-q3-29', 3, 29, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "These are your shoes. Put them on before you go out. We set on early in the morning to avoid the traffic.", "B": "These are your shoes. Put them on before you go out. We set over early in the morning to avoid the traffic.", "C": "These are your shoes. Put them in on before you go out. We set off early in the morning to avoid the traffic.", "D": "These are your shoes. Put them on before you go out. We set off early in the morning to avoid the traffic.", "E": "These are your shoes. Put on to them before you go out. We set off early in the morning to avoid the traffic."}'::jsonb, 'D', NULL, 'them on — Əvəzlik: put them on; off — set off — yola düşmək.');
INSERT INTO public.questions VALUES (11260, 141, 'g11-eng-phrasal-q3-30', 3, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The match was called ___ because of the heavy rain. (2) Go ahead — I''ll catch up ___ you later. (3) She turned ___ the job offer because the salary was too low.', NULL, NULL, '{"A": "off / with / up", "B": "off / on / down", "C": "off / with / down", "D": "up / with / down", "E": "off / with / over"}'::jsonb, 'C', NULL, '(1) off — call off — ləğv etmək (2) with — catch up with — çatmaq (3) down — turn down — rədd etmək');
INSERT INTO public.questions VALUES (11261, 142, 'g11-eng-prep-q1-01', 1, 1, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He apologised for being late.", "B": "The demand of electric cars is growing fast.", "C": "This medicine is not suitable with children under 12.", "D": "I''m writing at behalf of my company.", "E": "He arrived by time for the start of the lesson."}'::jsonb, 'A', NULL, 'Correct: «He apologised for being late.» — apologise for. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11262, 142, 'g11-eng-prep-q1-02', 1, 2, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "He arrived in time for the start of the lesson. The decision was taken by the expense of the workers.", "B": "He arrived at time for the start of the lesson. The decision was taken at the expense of the workers.", "C": "He arrived by time for the start of the lesson. The decision was taken at the expense of the workers.", "D": "He arrived with time for the start of the lesson. The decision was taken at the expense of the workers.", "E": "He arrived in time for the start of the lesson. The decision was taken at the expense of the workers."}'::jsonb, 'E', NULL, 'in — in time — vaxtında (gecikmədən); at — at the expense of — hesabına.');
INSERT INTO public.questions VALUES (11263, 142, 'g11-eng-prep-q1-03', 1, 3, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "The demand of electric cars is growing fast. I''m not keen on horror films.", "B": "The demand for electric cars is growing fast. I''m not keen of horror films.", "C": "The demand for electric cars is growing fast. I''m not keen on horror films.", "D": "The demand for electric cars is growing fast. I''m not keen with horror films.", "E": "The demand for electric cars is growing fast. I''m not keen at horror films."}'::jsonb, 'C', NULL, 'for — demand for; on — keen on.');
INSERT INTO public.questions VALUES (11264, 142, 'g11-eng-prep-q1-04', 1, 4, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "Sorry, I took your umbrella with mistake.", "B": "He arrived at time for the start of the lesson.", "C": "On the whole, the trip was a success.", "D": "The lift is off of order, so we have to use the stairs.", "E": "She is jealous about her sister''s success."}'::jsonb, 'C', NULL, 'Correct: «On the whole, the trip was a success.» — on the whole — ümumilikdə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11265, 142, 'g11-eng-prep-q1-05', 1, 5, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "In spite of the rain, they went for a walk. The building is in construction and will open next year.", "B": "In spite of the rain, they went for a walk. The building is on construction and will open next year.", "C": "In spite of the rain, they went for a walk. The building is under construction and will open next year.", "D": "Despite of spite of the rain, they went for a walk. The building is under construction and will open next year.", "E": "On spite of the rain, they went for a walk. The building is under construction and will open next year."}'::jsonb, 'C', NULL, 'In — in spite of (despite of yanlışdır); under — under construction.');
INSERT INTO public.questions VALUES (11266, 142, 'g11-eng-prep-q1-06', 1, 6, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "Mr Aliyev is on charge of the sales department.", "B": "The decision was taken on the expense of the workers.", "C": "This medicine is not suitable at children under 12.", "D": "You have to book the tickets in advance.", "E": "Are you aware about the risks?"}'::jsonb, 'D', NULL, 'Correct: «You have to book the tickets in advance.» — in advance — əvvəlcədən. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11267, 142, 'g11-eng-prep-q1-07', 1, 7, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He arrived ___ time for the start of the lesson. (2) I''ll meet you ___ the weekend. (3) Mr Aliyev is ___ charge of the sales department.', NULL, NULL, '{"A": "in / in / in", "B": "in / of / in", "C": "in / at / at", "D": "in / at / in", "E": "in / to / in"}'::jsonb, 'D', NULL, '(1) in — in time — vaxtında (gecikmədən) (2) at — at the weekend (BrE) (3) in — in charge of — məsul');
INSERT INTO public.questions VALUES (11268, 142, 'g11-eng-prep-q1-08', 1, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) You have to book the tickets ___ advance. (2) This medicine is not suitable ___ children under 12. (3) He succeeded ___ finding a new job.', NULL, NULL, '{"A": "in / of / in", "B": "in / with / in", "C": "in / for / in", "D": "at / for / in", "E": "in / at / in"}'::jsonb, 'C', NULL, '(1) in — in advance — əvvəlcədən (2) for — suitable for (3) in — succeed in + V-ing');
INSERT INTO public.questions VALUES (11269, 142, 'g11-eng-prep-q1-09', 1, 9, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She objected against being treated like a child. The two brothers look alike, but they differ in character.", "B": "She objected to being treated like a child. The two brothers look alike, but they differ on character.", "C": "She objected to being treated like a child. The two brothers look alike, but they differ at character.", "D": "She objected to being treated like a child. The two brothers look alike, but they differ in character.", "E": "She objected to being treated like a child. The two brothers look alike, but they differ with character."}'::jsonb, 'D', NULL, 'to — object to + V-ing; in — differ in.');
INSERT INTO public.questions VALUES (11270, 142, 'g11-eng-prep-q1-10', 1, 10, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "They accused him of stealing the money. She insisted for paying for dinner.", "B": "They accused him of stealing the money. She insisted on paying for dinner.", "C": "They accused him of stealing the money. She insisted to paying for dinner.", "D": "They accused him with stealing the money. She insisted on paying for dinner.", "E": "They accused him about stealing the money. She insisted on paying for dinner."}'::jsonb, 'B', NULL, 'of — accuse somebody of; on — insist on + V-ing.');
INSERT INTO public.questions VALUES (11271, 142, 'g11-eng-prep-q1-11', 1, 11, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "Sorry, I took your umbrella in mistake. The plan is still under discussion.", "B": "Sorry, I took your umbrella on mistake. The plan is still under discussion.", "C": "Sorry, I took your umbrella with mistake. The plan is still under discussion.", "D": "Sorry, I took your umbrella by mistake. The plan is still under discussion.", "E": "Sorry, I took your umbrella by mistake. The plan is still at discussion."}'::jsonb, 'D', NULL, 'by — by mistake — səhvən; under — under discussion — müzakirədə.');
INSERT INTO public.questions VALUES (11272, 142, 'g11-eng-prep-q1-12', 1, 12, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He was with the impression that the meeting had been cancelled.", "B": "She insisted at paying for dinner.", "C": "This medicine is not suitable with children under 12.", "D": "I''m writing by behalf of my company.", "E": "The lift is out of order, so we have to use the stairs."}'::jsonb, 'E', NULL, 'Correct: «The lift is out of order, so we have to use the stairs.» — out of order — xarab. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11273, 142, 'g11-eng-prep-q1-13', 1, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) There has been a sharp rise ___ the price of fuel. (2) She has no intention ___ resigning. (3) He succeeded ___ finding a new job.', NULL, NULL, '{"A": "on / of / in", "B": "in / of / on", "C": "in / on / in", "D": "in / of / in", "E": "with / of / in"}'::jsonb, 'D', NULL, '(1) in — a rise in (price) (2) of — intention of + V-ing (3) in — succeed in + V-ing');
INSERT INTO public.questions VALUES (11274, 142, 'g11-eng-prep-q1-14', 1, 14, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "The plan is still under discussion.", "B": "The new rules will come in effect next month.", "C": "Are you aware about the risks?", "D": "This book is different with the one I read last year.", "E": "He did it by his own, without any help."}'::jsonb, 'A', NULL, 'Correct: «The plan is still under discussion.» — under discussion — müzakirədə. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11275, 142, 'g11-eng-prep-q1-15', 1, 15, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "He arrived by time for the start of the lesson. The decision was taken at the expense of the workers.", "B": "He arrived in time for the start of the lesson. The decision was taken by the expense of the workers.", "C": "He arrived in time for the start of the lesson. The decision was taken at the expense of the workers.", "D": "He arrived with time for the start of the lesson. The decision was taken at the expense of the workers.", "E": "He arrived in time for the start of the lesson. The decision was taken for the expense of the workers."}'::jsonb, 'C', NULL, 'in — in time — vaxtında (gecikmədən); at — at the expense of — hesabına.');
INSERT INTO public.questions VALUES (11276, 142, 'g11-eng-prep-q1-16', 1, 16, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "She objected for being treated like a child.", "B": "He is capable to doing much better work.", "C": "She is married with a doctor.", "D": "The decision was taken at the expense of the workers.", "E": "He arrived at time for the start of the lesson."}'::jsonb, 'D', NULL, 'Correct: «The decision was taken at the expense of the workers.» — at the expense of — hesabına. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11277, 142, 'g11-eng-prep-q1-17', 1, 17, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He is capable to doing much better work.", "B": "He was in the impression that the meeting had been cancelled.", "C": "Are you aware on the risks?", "D": "The lift is under of order, so we have to use the stairs.", "E": "Sorry, I took your umbrella by mistake."}'::jsonb, 'E', NULL, 'Correct: «Sorry, I took your umbrella by mistake.» — by mistake — səhvən. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11278, 142, 'g11-eng-prep-q1-18', 1, 18, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She is married ___ a doctor. (2) He apologised ___ being late. (3) The lift is ___ of order, so we have to use the stairs.', NULL, NULL, '{"A": "to / of / out", "B": "to / for / off", "C": "to / for / out", "D": "to / on / out", "E": "for / for / out"}'::jsonb, 'C', NULL, '(1) to — married to (2) for — apologise for (3) out — out of order — xarab');
INSERT INTO public.questions VALUES (11279, 142, 'g11-eng-prep-q1-19', 1, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The new rules will come ___ effect next month. (2) They accused him ___ stealing the money. (3) Mr Aliyev is ___ charge of the sales department.', NULL, NULL, '{"A": "in / of / in", "B": "into / of / in", "C": "into / with / in", "D": "to / of / in", "E": "into / about / in"}'::jsonb, 'B', NULL, '(1) into — come into effect — qüvvəyə minmək (2) of — accuse somebody of (3) in — in charge of — məsul');
INSERT INTO public.questions VALUES (11280, 142, 'g11-eng-prep-q1-20', 1, 20, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He was ___ the impression that the meeting had been cancelled. (2) The new rules will come ___ effect next month. (3) There has been a sharp rise ___ the price of fuel.', NULL, NULL, '{"A": "on / into / in", "B": "under / to / in", "C": "under / into / in", "D": "under / on / in", "E": "under / in / in"}'::jsonb, 'C', NULL, '(1) under — under the impression — belə təsəvvür etmək (2) into — come into effect — qüvvəyə minmək (3) in — a rise in (price)');
INSERT INTO public.questions VALUES (11281, 142, 'g11-eng-prep-q1-21', 1, 21, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She has no intention of resigning. Sorry, I took your umbrella by mistake.", "B": "She has no intention to resigning. Sorry, I took your umbrella by mistake.", "C": "She has no intention of resigning. Sorry, I took your umbrella on mistake.", "D": "She has no intention of resigning. Sorry, I took your umbrella in mistake.", "E": "She has no intention of resigning. Sorry, I took your umbrella with mistake."}'::jsonb, 'A', NULL, 'of — intention of + V-ing; by — by mistake — səhvən.');
INSERT INTO public.questions VALUES (11282, 142, 'g11-eng-prep-q1-22', 1, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) They accused him ___ stealing the money. (2) The demand ___ electric cars is growing fast. (3) I know the poem ___ heart.', NULL, NULL, '{"A": "of / for / in", "B": "of / for / by", "C": "of / on / by", "D": "of / to / by", "E": "about / for / by"}'::jsonb, 'B', NULL, '(1) of — accuse somebody of (2) for — demand for (3) by — by heart — əzbər');
INSERT INTO public.questions VALUES (11283, 142, 'g11-eng-prep-q1-23', 1, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The decision was taken ___ the expense of the workers. (2) I''ll meet you ___ the weekend. (3) She is jealous ___ her sister''s success.', NULL, NULL, '{"A": "at / to / of", "B": "at / at / of", "C": "at / at / for", "D": "by / at / of", "E": "at / in / of"}'::jsonb, 'B', NULL, '(1) at — at the expense of — hesabına (2) at — at the weekend (BrE) (3) of — jealous of');
INSERT INTO public.questions VALUES (11284, 142, 'g11-eng-prep-q1-24', 1, 24, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "Sorry, I took your umbrella in mistake.", "B": "He was with the impression that the meeting had been cancelled.", "C": "They accused him of stealing the money.", "D": "He arrived with time for the start of the lesson.", "E": "The rain prevented us to going out."}'::jsonb, 'C', NULL, 'Correct: «They accused him of stealing the money.» — accuse somebody of. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11285, 142, 'g11-eng-prep-q1-25', 1, 25, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) This book is different ___ the one I read last year. (2) I''m writing ___ behalf of my company. (3) He succeeded ___ finding a new job.', NULL, NULL, '{"A": "from / by / in", "B": "of / on / in", "C": "from / on / in", "D": "from / on / to", "E": "from / on / at"}'::jsonb, 'C', NULL, '(1) from — different from (2) on — on behalf of — adından (3) in — succeed in + V-ing');
INSERT INTO public.questions VALUES (11286, 142, 'g11-eng-prep-q1-26', 1, 26, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He arrived by time for the start of the lesson.", "B": "The two brothers look alike, but they differ in character.", "C": "He apologised of being late.", "D": "She is jealous for her sister''s success.", "E": "The plan is still at discussion."}'::jsonb, 'B', NULL, 'Correct: «The two brothers look alike, but they differ in character.» — differ in. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11287, 142, 'g11-eng-prep-q1-27', 1, 27, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "In the whole, the trip was a success.", "B": "The plan is still in discussion.", "C": "I broke the vase by accident, not for purpose.", "D": "She congratulated me on passing the exam.", "E": "She has no intention to resigning."}'::jsonb, 'D', NULL, 'Correct: «She congratulated me on passing the exam.» — congratulate somebody on. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11288, 142, 'g11-eng-prep-q1-28', 1, 28, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She insisted on paying for dinner. She objected to being treated like a child.", "B": "She insisted on paying for dinner. She objected for being treated like a child.", "C": "She insisted for paying for dinner. She objected to being treated like a child.", "D": "She insisted on paying for dinner. She objected against being treated like a child.", "E": "She insisted on paying for dinner. She objected on being treated like a child."}'::jsonb, 'A', NULL, 'on — insist on + V-ing; to — object to + V-ing.');
INSERT INTO public.questions VALUES (11289, 142, 'g11-eng-prep-q1-29', 1, 29, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She is jealous of her sister''s success. She has no intention of resigning.", "B": "She is jealous for her sister''s success. She has no intention of resigning.", "C": "She is jealous on her sister''s success. She has no intention of resigning.", "D": "She is jealous of her sister''s success. She has no intention on resigning.", "E": "She is jealous about her sister''s success. She has no intention of resigning."}'::jsonb, 'A', NULL, 'of — jealous of; of — intention of + V-ing.');
INSERT INTO public.questions VALUES (11290, 142, 'g11-eng-prep-q1-30', 1, 30, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He did it ___ his own, without any help. (2) The building is ___ construction and will open next year. (3) ___ spite of the rain, they went for a walk.', NULL, NULL, '{"A": "by / under / In", "B": "for / under / In", "C": "on / at / In", "D": "on / under / On", "E": "on / under / In"}'::jsonb, 'E', NULL, '(1) on — on his own — təkbaşına (2) under — under construction (3) In — in spite of (despite of yanlışdır)');
INSERT INTO public.questions VALUES (11291, 142, 'g11-eng-prep-q2-01', 2, 1, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "There has been a sharp rise on the price of fuel.", "B": "The rain prevented us of going out.", "C": "She has no intention on resigning.", "D": "This medicine is not suitable of children under 12.", "E": "I''m writing on behalf of my company."}'::jsonb, 'E', NULL, 'Correct: «I''m writing on behalf of my company.» — on behalf of — adından. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11292, 142, 'g11-eng-prep-q2-02', 2, 2, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "He arrived by time for the start of the lesson. This book is different from the one I read last year.", "B": "He arrived at time for the start of the lesson. This book is different from the one I read last year.", "C": "He arrived in time for the start of the lesson. This book is different of the one I read last year.", "D": "He arrived in time for the start of the lesson. This book is different from the one I read last year.", "E": "He arrived in time for the start of the lesson. This book is different on the one I read last year."}'::jsonb, 'D', NULL, 'in — in time — vaxtında (gecikmədən); from — different from.');
INSERT INTO public.questions VALUES (11293, 142, 'g11-eng-prep-q2-03', 2, 3, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He arrived with time for the start of the lesson.", "B": "You have to book the tickets in advance.", "C": "She congratulated me about passing the exam.", "D": "There has been a sharp rise on the price of fuel.", "E": "This medicine is not suitable at children under 12."}'::jsonb, 'B', NULL, 'Correct: «You have to book the tickets in advance.» — in advance — əvvəlcədən. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11294, 142, 'g11-eng-prep-q2-04', 2, 4, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "This book is different from the one I read last year.", "B": "The lift is under of order, so we have to use the stairs.", "C": "He was with the impression that the meeting had been cancelled.", "D": "She is jealous on her sister''s success.", "E": "The rain prevented us of going out."}'::jsonb, 'A', NULL, 'Correct: «This book is different from the one I read last year.» — different from. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11295, 142, 'g11-eng-prep-q2-05', 2, 5, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "I broke the vase by accident, not by purpose.", "B": "She insisted at paying for dinner.", "C": "She objected for being treated like a child.", "D": "You have to book the tickets in advance.", "E": "The demand of electric cars is growing fast."}'::jsonb, 'D', NULL, 'Correct: «You have to book the tickets in advance.» — in advance — əvvəlcədən. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11296, 142, 'g11-eng-prep-q2-06', 2, 6, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The rain prevented us ___ going out. (2) I know the poem ___ heart. (3) I''ll meet you ___ the weekend.', NULL, NULL, '{"A": "from / by / of", "B": "from / by / in", "C": "from / with / at", "D": "from / by / to", "E": "from / by / at"}'::jsonb, 'E', NULL, '(1) from — prevent somebody from + V-ing (2) by — by heart — əzbər (3) at — at the weekend (BrE)');
INSERT INTO public.questions VALUES (11297, 142, 'g11-eng-prep-q2-07', 2, 7, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "He is capable of doing much better work. She objected to being treated like a child.", "B": "He is capable for doing much better work. She objected to being treated like a child.", "C": "He is capable of doing much better work. She objected for being treated like a child.", "D": "He is capable of doing much better work. She objected on being treated like a child.", "E": "He is capable to doing much better work. She objected to being treated like a child."}'::jsonb, 'A', NULL, 'of — capable of + V-ing; to — object to + V-ing.');
INSERT INTO public.questions VALUES (11298, 142, 'g11-eng-prep-q2-08', 2, 8, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I''m writing ___ behalf of my company. (2) There has been a sharp rise ___ the price of fuel. (3) ___ spite of the rain, they went for a walk.', NULL, NULL, '{"A": "on / in / In", "B": "by / in / In", "C": "on / with / In", "D": "for / in / In", "E": "on / in / By"}'::jsonb, 'A', NULL, '(1) on — on behalf of — adından (2) in — a rise in (price) (3) In — in spite of (despite of yanlışdır)');
INSERT INTO public.questions VALUES (11299, 142, 'g11-eng-prep-q2-09', 2, 9, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "Are you aware of the risks? She is married with a doctor.", "B": "Are you aware of the risks? She is married on a doctor.", "C": "Are you aware about the risks? She is married to a doctor.", "D": "Are you aware of the risks? She is married for a doctor.", "E": "Are you aware of the risks? She is married to a doctor."}'::jsonb, 'E', NULL, 'of — aware of; to — married to.');
INSERT INTO public.questions VALUES (11300, 142, 'g11-eng-prep-q2-10', 2, 10, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "The plan is still on discussion.", "B": "She insisted on paying for dinner.", "C": "Mr Aliyev is at charge of the sales department.", "D": "She is married on a doctor.", "E": "I''m not keen of horror films."}'::jsonb, 'B', NULL, 'Correct: «She insisted on paying for dinner.» — insist on + V-ing. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11301, 142, 'g11-eng-prep-q2-11', 2, 11, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She is jealous of her sister''s success. This book is different from the one I read last year.", "B": "She is jealous of her sister''s success. This book is different of the one I read last year.", "C": "She is jealous for her sister''s success. This book is different from the one I read last year.", "D": "She is jealous on her sister''s success. This book is different from the one I read last year.", "E": "She is jealous of her sister''s success. This book is different with the one I read last year."}'::jsonb, 'A', NULL, 'of — jealous of; from — different from.');
