INSERT INTO public.questions VALUES (11303, 142, 'g11-eng-prep-q2-13', 2, 13, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He succeeded ___ finding a new job. (2) They accused him ___ stealing the money. (3) This medicine is not suitable ___ children under 12.', NULL, NULL, '{"A": "in / of / at", "B": "in / for / for", "C": "to / of / for", "D": "in / of / for", "E": "in / of / with"}'::jsonb, 'D', NULL, '(1) in — succeed in + V-ing (2) of — accuse somebody of (3) for — suitable for');
INSERT INTO public.questions VALUES (11304, 142, 'g11-eng-prep-q2-14', 2, 14, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She objected to being treated like a child. I''m not keen with horror films.", "B": "She objected against being treated like a child. I''m not keen on horror films.", "C": "She objected for being treated like a child. I''m not keen on horror films.", "D": "She objected to being treated like a child. I''m not keen on horror films.", "E": "She objected to being treated like a child. I''m not keen at horror films."}'::jsonb, 'D', NULL, 'to — object to + V-ing; on — keen on.');
