INSERT INTO public.questions VALUES (11325, 142, 'g11-eng-prep-q3-05', 3, 5, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Sorry, I took your umbrella ___ mistake. (2) She has no intention ___ resigning. (3) She is jealous ___ her sister''s success.', NULL, NULL, '{"A": "by / of / for", "B": "by / of / on", "C": "by / to / of", "D": "by / of / of", "E": "by / of / about"}'::jsonb, 'D', NULL, '(1) by — by mistake — səhvən (2) of — intention of + V-ing (3) of — jealous of');
INSERT INTO public.questions VALUES (11326, 142, 'g11-eng-prep-q3-06', 3, 6, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She objected to being treated like a child. He did it on his own, without any help.", "B": "She objected for being treated like a child. He did it on his own, without any help.", "C": "She objected against being treated like a child. He did it on his own, without any help.", "D": "She objected to being treated like a child. He did it by his own, without any help.", "E": "She objected on being treated like a child. He did it on his own, without any help."}'::jsonb, 'A', NULL, 'to — object to + V-ing; on — on his own — təkbaşına.');
INSERT INTO public.questions VALUES (11327, 142, 'g11-eng-prep-q3-07', 3, 7, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "On the whole, the trip was a success. The demand of electric cars is growing fast.", "B": "At the whole, the trip was a success. The demand for electric cars is growing fast.", "C": "In the whole, the trip was a success. The demand for electric cars is growing fast.", "D": "On the whole, the trip was a success. The demand for electric cars is growing fast.", "E": "By the whole, the trip was a success. The demand for electric cars is growing fast."}'::jsonb, 'D', NULL, 'On — on the whole — ümumilikdə; for — demand for.');
INSERT INTO public.questions VALUES (11328, 142, 'g11-eng-prep-q3-08', 3, 8, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He arrived in time for the start of the lesson.", "B": "Despite of spite of the rain, they went for a walk.", "C": "The two brothers look alike, but they differ on character.", "D": "They accused him for stealing the money.", "E": "There has been a sharp rise at the price of fuel."}'::jsonb, 'A', NULL, 'Correct: «He arrived in time for the start of the lesson.» — in time — vaxtında (gecikmədən). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11329, 142, 'g11-eng-prep-q3-09', 3, 9, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "The demand for electric cars is growing fast. The rain prevented us of going out.", "B": "The demand for electric cars is growing fast. The rain prevented us for going out.", "C": "The demand to electric cars is growing fast. The rain prevented us from going out.", "D": "The demand for electric cars is growing fast. The rain prevented us from going out.", "E": "The demand on electric cars is growing fast. The rain prevented us from going out."}'::jsonb, 'D', NULL, 'for — demand for; from — prevent somebody from + V-ing.');
INSERT INTO public.questions VALUES (11330, 142, 'g11-eng-prep-q3-10', 3, 10, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I''ll meet you ___ the weekend. (2) ___ the whole, the trip was a success. (3) She is jealous ___ her sister''s success.', NULL, NULL, '{"A": "at / On / on", "B": "of / On / of", "C": "at / In / of", "D": "at / On / for", "E": "at / On / of"}'::jsonb, 'E', NULL, '(1) at — at the weekend (BrE) (2) On — on the whole — ümumilikdə (3) of — jealous of');
INSERT INTO public.questions VALUES (11331, 142, 'g11-eng-prep-q3-11', 3, 11, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "They accused him for stealing the money. The building is under construction and will open next year.", "B": "They accused him of stealing the money. The building is under construction and will open next year.", "C": "They accused him of stealing the money. The building is on construction and will open next year.", "D": "They accused him of stealing the money. The building is in construction and will open next year.", "E": "They accused him of stealing the money. The building is at construction and will open next year."}'::jsonb, 'B', NULL, 'of — accuse somebody of; under — under construction.');
INSERT INTO public.questions VALUES (11332, 142, 'g11-eng-prep-q3-12', 3, 12, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) The rain prevented us ___ going out. (2) She objected ___ being treated like a child. (3) He did it ___ his own, without any help.', NULL, NULL, '{"A": "from / to / in", "B": "of / to / on", "C": "from / for / on", "D": "from / against / on", "E": "from / to / on"}'::jsonb, 'E', NULL, '(1) from — prevent somebody from + V-ing (2) to — object to + V-ing (3) on — on his own — təkbaşına');
INSERT INTO public.questions VALUES (11333, 142, 'g11-eng-prep-q3-13', 3, 13, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "The new rules will come in effect next month.", "B": "He is capable to doing much better work.", "C": "He was under the impression that the meeting had been cancelled.", "D": "The lift is without of order, so we have to use the stairs.", "E": "They accused him for stealing the money."}'::jsonb, 'C', NULL, 'Correct: «He was under the impression that the meeting had been cancelled.» — under the impression — belə təsəvvür etmək. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11334, 142, 'g11-eng-prep-q3-14', 3, 14, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "She has no intention on resigning.", "B": "The demand of electric cars is growing fast.", "C": "The new rules will come to effect next month.", "D": "He arrived with time for the start of the lesson.", "E": "Are you aware of the risks?"}'::jsonb, 'E', NULL, 'Correct: «Are you aware of the risks?» — aware of. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11335, 142, 'g11-eng-prep-q3-15', 3, 15, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) He did it ___ his own, without any help. (2) He was ___ the impression that the meeting had been cancelled. (3) She insisted ___ paying for dinner.', NULL, NULL, '{"A": "on / under / on", "B": "on / under / at", "C": "on / in / on", "D": "on / under / for", "E": "for / under / on"}'::jsonb, 'A', NULL, '(1) on — on his own — təkbaşına (2) under — under the impression — belə təsəvvür etmək (3) on — insist on + V-ing');
INSERT INTO public.questions VALUES (11336, 142, 'g11-eng-prep-q3-16', 3, 16, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "They accused him about stealing the money.", "B": "The demand for electric cars is growing fast.", "C": "There has been a sharp rise on the price of fuel.", "D": "She is married for a doctor.", "E": "The lift is off of order, so we have to use the stairs."}'::jsonb, 'B', NULL, 'Correct: «The demand for electric cars is growing fast.» — demand for. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11337, 142, 'g11-eng-prep-q3-17', 3, 17, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He succeeded on finding a new job.", "B": "There has been a sharp rise with the price of fuel.", "C": "The building is on construction and will open next year.", "D": "They accused him of stealing the money.", "E": "Mr Aliyev is under charge of the sales department."}'::jsonb, 'D', NULL, 'Correct: «They accused him of stealing the money.» — accuse somebody of. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11338, 142, 'g11-eng-prep-q3-18', 3, 18, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She insisted to paying for dinner. The demand for electric cars is growing fast.", "B": "She insisted on paying for dinner. The demand of electric cars is growing fast.", "C": "She insisted on paying for dinner. The demand on electric cars is growing fast.", "D": "She insisted on paying for dinner. The demand for electric cars is growing fast.", "E": "She insisted on paying for dinner. The demand to electric cars is growing fast."}'::jsonb, 'D', NULL, 'on — insist on + V-ing; for — demand for.');
INSERT INTO public.questions VALUES (11339, 142, 'g11-eng-prep-q3-19', 3, 19, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) Sorry, I took your umbrella ___ mistake. (2) He did it ___ his own, without any help. (3) She congratulated me ___ passing the exam.', NULL, NULL, '{"A": "by / on / of", "B": "by / in / on", "C": "by / on / about", "D": "with / on / on", "E": "by / on / on"}'::jsonb, 'E', NULL, '(1) by — by mistake — səhvən (2) on — on his own — təkbaşına (3) on — congratulate somebody on');
INSERT INTO public.questions VALUES (11340, 142, 'g11-eng-prep-q3-20', 3, 20, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "She insisted on paying for dinner. This book is different with the one I read last year.", "B": "She insisted on paying for dinner. This book is different of the one I read last year.", "C": "She insisted on paying for dinner. This book is different on the one I read last year.", "D": "She insisted at paying for dinner. This book is different from the one I read last year.", "E": "She insisted on paying for dinner. This book is different from the one I read last year."}'::jsonb, 'E', NULL, 'on — insist on + V-ing; from — different from.');
INSERT INTO public.questions VALUES (11341, 142, 'g11-eng-prep-q3-21', 3, 21, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "The two brothers look alike, but they differ with character.", "B": "The demand on electric cars is growing fast.", "C": "She is jealous of her sister''s success.", "D": "Are you aware about the risks?", "E": "He did it in his own, without any help."}'::jsonb, 'C', NULL, 'Correct: «She is jealous of her sister''s success.» — jealous of. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11342, 142, 'g11-eng-prep-q3-22', 3, 22, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She objected ___ being treated like a child. (2) The decision was taken ___ the expense of the workers. (3) The rain prevented us ___ going out.', NULL, NULL, '{"A": "to / on / from", "B": "to / by / from", "C": "to / at / to", "D": "to / at / from", "E": "to / at / for"}'::jsonb, 'D', NULL, '(1) to — object to + V-ing (2) at — at the expense of — hesabına (3) from — prevent somebody from + V-ing');
INSERT INTO public.questions VALUES (11343, 142, 'g11-eng-prep-q3-23', 3, 23, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I know the poem ___ heart. (2) There has been a sharp rise ___ the price of fuel. (3) This book is different ___ the one I read last year.', NULL, NULL, '{"A": "by / in / with", "B": "from / in / from", "C": "by / on / from", "D": "by / in / from", "E": "by / with / from"}'::jsonb, 'D', NULL, '(1) by — by heart — əzbər (2) in — a rise in (price) (3) from — different from');
INSERT INTO public.questions VALUES (11344, 142, 'g11-eng-prep-q3-24', 3, 24, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) I''m not keen ___ horror films. (2) He succeeded ___ finding a new job. (3) Mr Aliyev is ___ charge of the sales department.', NULL, NULL, '{"A": "on / in / under", "B": "with / in / in", "C": "on / in / at", "D": "on / in / in", "E": "on / at / in"}'::jsonb, 'D', NULL, '(1) on — keen on (2) in — succeed in + V-ing (3) in — in charge of — məsul');
INSERT INTO public.questions VALUES (11345, 142, 'g11-eng-prep-q3-25', 3, 25, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "Sorry, I took your umbrella by mistake. The new rules will come to effect next month.", "B": "Sorry, I took your umbrella on mistake. The new rules will come into effect next month.", "C": "Sorry, I took your umbrella in mistake. The new rules will come into effect next month.", "D": "Sorry, I took your umbrella with mistake. The new rules will come into effect next month.", "E": "Sorry, I took your umbrella by mistake. The new rules will come into effect next month."}'::jsonb, 'E', NULL, 'by — by mistake — səhvən; into — come into effect — qüvvəyə minmək.');
INSERT INTO public.questions VALUES (11346, 142, 'g11-eng-prep-q3-26', 3, 26, 'hard', 'single', 'Choose the option that correctly completes all the gaps: (1) She is jealous ___ her sister''s success. (2) They accused him ___ stealing the money. (3) The decision was taken ___ the expense of the workers.', NULL, NULL, '{"A": "for / of / at", "B": "about / of / at", "C": "of / with / at", "D": "of / for / at", "E": "of / of / at"}'::jsonb, 'E', NULL, '(1) of — jealous of (2) of — accuse somebody of (3) at — at the expense of — hesabına');
INSERT INTO public.questions VALUES (11347, 142, 'g11-eng-prep-q3-27', 3, 27, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He is capable for doing much better work.", "B": "She has no intention on resigning.", "C": "She insisted for paying for dinner.", "D": "He arrived in time for the start of the lesson.", "E": "You have to book the tickets at advance."}'::jsonb, 'D', NULL, 'Correct: «He arrived in time for the start of the lesson.» — in time — vaxtında (gecikmədən). The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11348, 142, 'g11-eng-prep-q3-28', 3, 28, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "The decision was taken at the expense of the workers.", "B": "She objected on being treated like a child.", "C": "He was in the impression that the meeting had been cancelled.", "D": "The rain prevented us to going out.", "E": "He did it by his own, without any help."}'::jsonb, 'A', NULL, 'Correct: «The decision was taken at the expense of the workers.» — at the expense of — hesabına. The other sentences each contain an error.');
INSERT INTO public.questions VALUES (11349, 142, 'g11-eng-prep-q3-29', 3, 29, 'hard', 'single', 'In which option are BOTH sentences correct?', NULL, NULL, '{"A": "He apologised for being late. They accused him with stealing the money.", "B": "He apologised on being late. They accused him of stealing the money.", "C": "He apologised of being late. They accused him of stealing the money.", "D": "He apologised about being late. They accused him of stealing the money.", "E": "He apologised for being late. They accused him of stealing the money."}'::jsonb, 'E', NULL, 'for — apologise for; of — accuse somebody of.');
INSERT INTO public.questions VALUES (11350, 142, 'g11-eng-prep-q3-30', 3, 30, 'hard', 'single', 'In which sentence is the preposition used correctly?', NULL, NULL, '{"A": "He is capable of doing much better work.", "B": "The demand on electric cars is growing fast.", "C": "Sorry, I took your umbrella with mistake.", "D": "On spite of the rain, they went for a walk.", "E": "He apologised of being late."}'::jsonb, 'A', NULL, 'Correct: «He is capable of doing much better work.» — capable of + V-ing. The other sentences each contain an error.');
